# =============================================================================
# RECOVERY DEBUG (universal completeness diagnostics)
# =============================================================================
# Enable with --debug / --debug-verbose, NDL_RECOVER_DEBUG=1, or NDL_DEBUG_DIR.
# Per-function dumps never land in the process CWD: a 50 MB application binary
# would otherwise flood the workspace with DEBUG_COMPLETE.txt / DEBUG_RECOVER.txt.

_NDL_DEBUG_DIR = (os.environ.get('NDL_DEBUG_DIR') or '').strip() or None
_NDL_DEBUG_VERBOSE = os.environ.get('NDL_RECOVER_DEBUG', '').strip().lower() in (
    '2', 'verbose', 'all')
_RECOVER_DEBUG = os.environ.get('NDL_RECOVER_DEBUG', '').strip().lower() in (
    '1', 'true', 'yes', 'on', '2', 'verbose', 'all')
_NDL_DEBUG_LOCK = threading.Lock()


def _ndl_set_debug(enabled, debug_dir=None, verbose=None):
    """Enable structured recovery diagnostics for the rest of this process."""
    global _RECOVER_DEBUG, _NDL_DEBUG_DIR, _NDL_DEBUG_VERBOSE
    _RECOVER_DEBUG = bool(enabled)
    if verbose is not None:
        _NDL_DEBUG_VERBOSE = bool(verbose)
        if _NDL_DEBUG_VERBOSE:
            _RECOVER_DEBUG = True
    if debug_dir:
        _NDL_DEBUG_DIR = os.path.abspath(debug_dir)
        try:
            os.makedirs(_NDL_DEBUG_DIR, exist_ok=True)
        except Exception:
            pass


def _ndl_debug_path(name):
    root = _NDL_DEBUG_DIR or os.getcwd()
    try:
        os.makedirs(root, exist_ok=True)
    except Exception:
        pass
    return os.path.join(root, name)


def _ndl_debug_append(name, text):
    """Append a debug text artifact. No-op unless debug is enabled."""
    if not _RECOVER_DEBUG:
        return
    if not text:
        return
    try:
        payload = text if text.endswith('\n') else text + '\n'
        with _NDL_DEBUG_LOCK:
            with open(_ndl_debug_path(name), 'a', encoding='utf-8') as handle:
                handle.write(payload)
    except Exception:
        pass


def _ndl_debug_json(name, obj, append=False):
    """Write a JSON/JSONL debug artifact. No-op unless debug is enabled."""
    if not _RECOVER_DEBUG and not _NDL_DEBUG_DIR:
        return
    try:
        payload = json.dumps(obj, indent=None if append else 2,
                             sort_keys=not append, default=str)
        if append:
            payload += '\n'
        else:
            payload += '\n'
        mode = 'a' if append else 'w'
        with _NDL_DEBUG_LOCK:
            with open(_ndl_debug_path(name), mode, encoding='utf-8') as handle:
                handle.write(payload)
    except Exception:
        pass


def _ndl_debug_body(filename, qualname, tag, body, extra=''):
    """Dump a recovered body. Compact mode keeps only incomplete/bad bodies."""
    if not _RECOVER_DEBUG:
        return
    text = body if isinstance(body, str) else '\n'.join(body or [])
    bad = bool(extra) and ('bad=True' in extra or 'deg=True' in extra)
    empty = (not text.strip()) or all(
        line.strip() in ('', 'pass', '...', 'pass  # UNCERTAIN: body not recovered')
        for line in text.splitlines())
    if not _NDL_DEBUG_VERBOSE and not bad and not empty and tag not in (
            'PS-NOT-PROTECTED',):
        return
    _ndl_debug_append(
        filename,
        f"{tag} {qualname}{(' ' + extra) if extra else ''}\n"
        f"{text}\n"
        f"{'=' * 21}\n")


def _ndl_debug_ctx(ctx, selected=None, extra=None):
    """Snapshot blob/module-table facts that gate complete recovery."""
    if not ctx:
        return
    chunks = ctx.get('chunks') or []
    ents = ctx.get('ents') or []
    names = [n for n, _ in chunks if n]
    probe = {
        'effective_target': ctx.get('effective_target'),
        'edition': ctx.get('edition'),
        'blob_state': ctx.get('blob_state'),
        'python_version': ctx.get('python_version'),
        'constants_profile': ctx.get('constants_profile'),
        'blob_name_encoding': ctx.get('blob_name_encoding'),
        'chunk_count': len(names),
        'module_table_entries': len(ents),
        'module_table_with_func_ptr': sum(
            1 for e in ents if isinstance(e, dict) and e.get('func_ptr')),
        'selected': list(selected or []),
        'selected_count': len(selected or []),
        'live_opts': dict(_LIVE_DECOMPILE_OPTS) if '_LIVE_DECOMPILE_OPTS' in globals() else None,
        'adaptive_fast': bool(globals().get('_NDL_ADAPTIVE_FAST')),
        'chunks_preview': names[:40],
    }
    if extra:
        probe.update(extra)
    _ndl_debug_json('probe.json', probe)

