class ProgressBar:
    def __init__(self, total, desc="Processing", width=40, spinner='fire'):
        self.total = max(total, 1)
        self.current = 0
        self.desc = desc
        self.width = width
        self.start_time = time.time()
        self.spinner_frames = ['*', '+', 'x', '+']
        self.frame = 0

    def update(self, n=1):
        self.current = min(self.current + n, self.total)
        self.frame = (self.frame + 1) % len(self.spinner_frames)
        self._render()

    def _render(self):
        progress = self.current / self.total
        filled = int(self.width * progress)
        bar = ""
        for i in range(self.width):
            if i < filled:
                if i < self.width * 0.3: bar += f"{C.BRIGHT_RED}#"
                elif i < self.width * 0.6: bar += f"{C.BRIGHT_YELLOW}#"
                else: bar += f"{C.BRIGHT_GREEN}#"
            else: bar += f"{C.DIM}."
        bar += C.RESET
        elapsed = time.time() - self.start_time
        eta = (elapsed / self.current * (self.total - self.current)) if self.current > 0 else 0
        s = self.spinner_frames[self.frame]
        status = (f"\r{C.BOLD}{C.BRIGHT_CYAN}[{s}]{C.RESET} "
                  f"{C.BRIGHT_WHITE}{self.desc}{C.RESET} [{bar}] "
                  f"{C.BRIGHT_YELLOW}{progress*100:5.1f}%{C.RESET} "
                  f"{C.DIM}({self.current}/{self.total}){C.RESET} "
                  f"{C.BRIGHT_MAGENTA}ETA: {int(eta)}s{C.RESET}")
        print(status, end='', flush=True)

    def finish(self, message="Done!"):
        print(f"\r{' ' * 120}\r", end='')
        print(f"{C.BRIGHT_GREEN}[OK]{C.RESET} {C.BRIGHT_WHITE}{self.desc}{C.RESET}: {C.BRIGHT_GREEN}{message}{C.RESET}")


def print_section(title):
    width = 65
    print()
    print(f"{C.BRIGHT_CYAN}{'=' * width}{C.RESET}")
    centered = title.center(width - 4)
    print(f"{C.BRIGHT_CYAN}||{C.RESET} {C.BOLD}{C.BRIGHT_WHITE}{centered}{C.RESET} {C.BRIGHT_CYAN}||{C.RESET}")
    print(f"{C.BRIGHT_CYAN}{'=' * width}{C.RESET}")

def log(msg): print(f"{C.BRIGHT_CYAN}[**]{C.RESET} {msg}")
def log_ok(msg): print(f"{C.BRIGHT_GREEN}[OK]{C.RESET} {msg}")
def log_err(msg): print(f"{C.BRIGHT_RED}[!!]{C.RESET} {msg}")
def log_warn(msg): print(f"{C.BRIGHT_YELLOW}[!!]{C.RESET} {msg}")
def log_fire(msg): print(f"{C.BRIGHT_RED}[>>]{C.RESET} {C.BOLD}{msg}{C.RESET}")


# =============================================================================
# SUPPORTED PROTECTED METADATA HANDLING
# =============================================================================

class CommercialBypass:
    """Research implementation for Nuitka Commercial data-hiding metadata.

    Use this only for binaries that you own or are authorized to inspect.

    Algorithm summary (from DataHidingPlugin.py):
    - Protected constants metadata uses substitution cipher + XOR with running counter + MD5 digest feedback
    - Key material: _mapping[] (256 byte inverse subst table) + d0-d7 (8 MD5 digest bytes)
    - Module names: mapping2 seeded with Random(27), always reconstructible

    Detection: if CRC32 of the payload doesn't match after header, the blob is protected.
    Key extraction: scan .text/.rdata for _mapping[] (256 byte lookup table) and d0-d7.
    Strategy v2: try ALL mapping candidates x ALL d0-d7 candidates,
                 validate each combination with CRC32 before accepting.
    """

    def __init__(self):
        # mapping2 for module names - ALWAYS seed=27, reconstructible without the binary
        r = random.Random(27)
        fwd = list(range(1, 256))
        r.shuffle(fwd)
        fwd.insert(0, 0)
        self.mapping2_forward = list(fwd)
        # Inverse mapping2 for name decoding
        self.name_decode_table = [0] * 256
        for i, v in enumerate(fwd):
            self.name_decode_table[v] = i
        # Expected _mapping2 table as stored in the binary (= inverse of forward mapping2)
        # Used to distinguish _mapping2 (for names) from _mapping (for data) among PE candidates
        self.expected_binary_mapping2 = list(self.name_decode_table)

    def decode_module_name(self, encoded_name: bytes) -> str:
        """Decode a module name obfuscated with mapping2 (seed=27)."""
        decoded = bytearray()
        for b in encoded_name:
            decoded.append(self.name_decode_table[b])
        return decoded.decode('utf-8', errors='strict')

    def is_blob_encrypted(self, blob_data: bytes) -> bool:
        """Recognize DataHidingPlugin's exact extra-16-byte layout.

        A CRC mismatch without this marker is corruption/unknown framing, not
        evidence of encryption and must not trigger speculative key recovery.
        """
        return self.has_commercial_digest(blob_data)

    def has_commercial_digest(self, blob_data: bytes) -> bool:
        """Detect a supported protected layout marker."""
        if len(blob_data) < 24:
            return False
        size_stored = struct.unpack('<I', blob_data[4:8])[0]
        extra = len(blob_data) - 8 - size_stored
        return extra == 16

    def get_blob_layout(self, blob_data: bytes) -> dict:
        """Return structural metadata for open-source and commercial blobs."""
        if len(blob_data) < 8:
            return {
                'declared_size': 0,
                'available_payload': 0,
                'extra_bytes': 0,
                'has_commercial_digest': False,
            }

        declared_size = struct.unpack('<I', blob_data[4:8])[0]
        available_payload = max(0, len(blob_data) - 8)
        extra_bytes = len(blob_data) - 8 - declared_size
        return {
            'declared_size': declared_size,
            'available_payload': available_payload,
            'extra_bytes': extra_bytes,
            'has_commercial_digest': extra_bytes == 16,
        }

    def _decrypt_raw(self, encrypted_blob: bytes, mapping: list, d_values: list,
                      max_bytes: int = 0) -> bytes:
        """Decrypt the blob (or only the first max_bytes for quick validation).

        If max_bytes > 0, decrypt just enough bytes to produce max_bytes
        of output after the header, for quick CRC validation without
        processing the entire 6+ MB blob.
        """
        if not isinstance(encrypted_blob, (bytes, bytearray, memoryview)):
            raise TypeError("encrypted blob must be bytes-like")
        if len(encrypted_blob) < 24:
            raise ValueError("commercial blob is shorter than its header/digest")
        if (not isinstance(mapping, (list, tuple)) or len(mapping) != 256
                or any(not isinstance(x, int) or not 0 <= x <= 255
                       for x in mapping)):
            raise ValueError("commercial mapping must contain 256 bytes")
        if (not isinstance(d_values, (list, tuple)) or len(d_values) != 8
                or any(not isinstance(x, int) or not 0 <= x <= 255
                       for x in d_values)):
            raise ValueError("commercial digest key must contain 8 bytes")

        original_size = struct.unpack('<I', encrypted_blob[4:8])[0]
        if len(encrypted_blob) != original_size + 24:
            raise ValueError(
                "commercial blob length does not match header+digest+payload")

        if max_bytes > 0:
            # Limit: decrypt only enough for header + max_bytes of data
            out_needed = min(max_bytes + 8, original_size + 8)
        else:
            out_needed = original_size + 8

        output = bytearray(out_needed)
        output[:8] = encrypted_blob[:8]

        # How many encrypted bytes to process: output[i-16] starts at i=24
        # So for out_needed bytes of output, we need i up to out_needed+16-1
        total_enc = original_size + 16
        if max_bytes > 0:
            # Process just enough: to fill output up to out_needed
            # output[idx] is written at i = idx + 16, so i_max = out_needed + 15
            loop_end = min(out_needed + 16, 8 + total_enc)
        else:
            loop_end = 8 + total_enc

        # Pre-convert mapping to bytes for faster indexing
        mapping_tbl = mapping  # already a list[int]
        d0, d1, d2, d3, d4, d5, d6, d7 = d_values[0], d_values[1], d_values[2], d_values[3], d_values[4], d_values[5], d_values[6], d_values[7]
        d_lut = (d0, d1, d2, d3, d4, d5, d6, d7)

        last = 0
        enc = encrypted_blob  # local ref for speed
        decoded_digest = bytearray()

        for i in range(8, loop_end):
            c = enc[i]
            temp = (last + (i - 8)) & 0xFF
            c = c ^ temp
            c = mapping_tbl[c]
            if i < 24:
                decoded_digest.append(c)
            if i >= 24:
                idx = i - 16
                if idx < out_needed:
                    output[idx] = c
            last = (c + d_lut[i & 7]) & 0xFF

        result = bytes(output)
        if max_bytes <= 0:
            if len(result) != original_size + 8:
                raise ValueError("normalized commercial blob has wrong length")
            if bytes(decoded_digest) != hashlib.md5(result).digest():
                raise ValueError("commercial blob MD5 witness mismatch")
        return result

    def _check_crc(self, decrypted: bytes) -> bool:
        """Verify CRC32 of the decrypted blob. True = OK."""
        if len(decrypted) < 8:
            return False
        crc_stored = struct.unpack('<I', decrypted[0:4])[0]
        size_stored = struct.unpack('<I', decrypted[4:8])[0]
        if 8 + size_stored != len(decrypted):
            return False
        actual_crc = zlib.crc32(decrypted[8:8 + size_stored]) & 0xFFFFFFFF
        return actual_crc == crc_stored

    def _quick_validate(self, encrypted_blob: bytes, mapping: list, d_values: list) -> bool:
        """Quick validation: decrypt first ~64 bytes and verify module structure.

        In commercial builds module names are encoded with mapping2, so they
        are NOT printable ASCII. They must be decoded before verification.
        """
        try:
            partial = self._decrypt_raw(encrypted_blob, mapping, d_values, max_bytes=64)
            data_start = partial[8:] if len(partial) > 8 else b''
            if not data_start:
                return False

            null_pos = data_start.find(b'\x00')
            if null_pos < 1:
                return False

            raw_name = data_start[:null_pos]

            # Strategy 1: decode with mapping2 (commercial builds encode names)
            decoded = self.decode_module_name(raw_name)
            printable_ok = sum(1 for c in decoded if c.isprintable() or c == '.') / max(len(decoded), 1) >= 0.8

            if not printable_ok:
                # Strategy 2: check raw bytes (open-source builds keep names as-is)
                printable_ok = sum(1 for b in raw_name if 0x20 <= b < 0x7F) / max(len(raw_name), 1) >= 0.8

            if not printable_ok:
                return False

            size_pos = null_pos + 1
            if size_pos + 4 <= len(data_start):
                chunk_size = struct.unpack('<I', data_start[size_pos:size_pos + 4])[0]
                orig_size = struct.unpack('<I', encrypted_blob[4:8])[0]
                if chunk_size > orig_size or chunk_size == 0:
                    return False
            return True
        except Exception:
            return False

    def extract_key_material_from_pe(self, pe_data: bytes):
        """Extract _mapping[] and d0-d7 from the PE binary.

        Strategy v2 (robust):
        1. Collect ALL _mapping[] candidates (256-byte permutations)
        2. For each mapping candidate, search for d0-d7 via:
           a. Cross-reference LEA/MOV to the mapping in .text -> decode_hidden function
           b. Scan imm8 clusters in the found function
           c. Fallback global ADD/MOV imm8 scan in .text
        3. Validate each (mapping, d0-d7) pair with CRC32 on the actual blob
        4. Return the first valid pair
        """
        import pefile
        pe = pefile.PE(data=pe_data)

        mapping_candidates = self._find_all_mapping_candidates(pe)
        if not mapping_candidates:
            log_err("No _mapping[] candidates found in PE")
            return None, None

        log(f"  {len(mapping_candidates)} _mapping[] candidate(s) to test")

        all_d_candidates = self._find_all_digest_candidates(pe, pe_data, mapping_candidates)
        log(f"  {len(all_d_candidates)} d0-d7 candidate sets found")

        return mapping_candidates, all_d_candidates

    def decrypt_blob_auto(self, encrypted_blob: bytes, mapping_candidates: list,
                          d_candidates: list) -> tuple:
        """Try all mapping x d0-d7 combinations with quick validation.

        Phase 0: filter mapping2 (name-encoding) from data-decryption candidates
        Phase 1: quick_validate on first 64 bytes (instant)
        Phase 2: full decrypt + CRC check only on candidates that pass phase 1
        """
        mapping_candidates = list(mapping_candidates or ())
        d_candidates = list(d_candidates or ())
        if not mapping_candidates:
            return None, None, None

        # Phase 0: remove mapping2 (for name encoding) from data decryption candidates
        filtered = [m for m in mapping_candidates
                    if m != self.expected_binary_mapping2]
        if len(filtered) < len(mapping_candidates):
            log(f"  Filtered mapping2 (name encoding): {len(mapping_candidates)} -> {len(filtered)} _mapping[] candidates")
        mapping_candidates = filtered
        if not mapping_candidates:
            return None, None, None

        # === FAST PATH: derive d0-d7 directly from the encrypted blob ===
        # d0-d7 are the first 8 bytes of the MD5 digest, which is encrypted
        # inside the blob itself. We can recover them using just the mapping.
        for mi, mapping in enumerate(mapping_candidates):
            derived_d = self._derive_d_from_blob(encrypted_blob, mapping)
            if derived_d:
                try:
                    result = self._decrypt_raw(encrypted_blob, mapping, derived_d)
                    if self._check_crc(result):
                        log_ok(f"Direct d0-d7 derivation from blob succeeded! mapping#{mi}")
                        return result, mapping, derived_d
                except (ValueError, TypeError, IndexError, struct.error):
                    pass

        log_warn("  Direct derivation failed, trying scanned combinations...")

        total_combos = len(mapping_candidates) * len(d_candidates)
        log(f"  Trying {total_combos} combinations (mapping x d0-d7)...")

        # Phase 1: quick validation
        valid_pairs = []
        for mi, mapping in enumerate(mapping_candidates):
            for di, d_vals in enumerate(d_candidates):
                if self._quick_validate(encrypted_blob, mapping, d_vals):
                    valid_pairs.append((mi, mapping, di, d_vals))

        if valid_pairs:
            log(f"  {len(valid_pairs)} combinations pass quick validation")
        else:
            log_warn("  No combination passes quick validation")
        # Quick validation is an ordering hint only. Long/empty first names can
        # exceed its 64-byte probe, so every remaining pair must still receive
        # the authoritative full MD5+CRC check.
        _prioritized = {(mi, di) for mi, _m, di, _d in valid_pairs}
        valid_pairs.extend(
            (mi, m, di, d)
            for mi, m in enumerate(mapping_candidates)
            for di, d in enumerate(d_candidates)
            if (mi, di) not in _prioritized)

        # Phase 2: full decrypt + CRC only on filtered candidates
        for mi, mapping, di, d_vals in valid_pairs:
            try:
                result = self._decrypt_raw(encrypted_blob, mapping, d_vals)
                if self._check_crc(result):
                    log_ok(f"Valid combination found! mapping#{mi} + d0-d7#{di}")
                    return result, mapping, d_vals
            except (ValueError, TypeError, IndexError, struct.error):
                continue

        log_warn("No combination passed the commercial MD5/CRC checks.")
        return None, None, None

    def _find_all_mapping_candidates(self, pe, rdata_only: bool = False):
        """Collect ALL _mapping[] candidates (complete 0-255 permutations).

        Uses a O(n) sliding-window frequency counter instead of creating a new
        set() for every 1-byte-stepped window — ~50x faster on large sections.
        """
        candidates = []
        _identity = list(range(256))

        # Priority order: .rdata (most likely) first, then .data, then .text
        section_order = {'.rdata': 0, '.data': 1, '.text': 2}
        sections_sorted = sorted(
            pe.sections,
            key=lambda s: section_order.get(
                s.Name.rstrip(b'\x00').decode('ascii', errors='replace'), 3)
        )

        for section in sections_sorted:
            name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            sec_key = next((k for k in ('.rdata', '.data', '.text') if k in name), None)
            if sec_key is None:
                continue
            if rdata_only and sec_key != '.rdata':
                continue

            sec_data = section.get_data()
            sec_size = len(sec_data)
            if sec_size < 256:
                continue

            # Sliding-window permutation check: maintain a frequency array of
            # size 256 and a count of distinct values in the current window.
            freq = [0] * 256
            distinct = 0

            # Initialise with first window
            for b in sec_data[:256]:
                if freq[b] == 0:
                    distinct += 1
                freq[b] += 1

            def _check(offset):
                if distinct != 256:
                    return
                table = list(sec_data[offset:offset + 256])
                if table == _identity:
                    return  # identity = open-source no-op
                if any(c[1] == table for c in candidates):
                    return  # deduplicate
                rva = section.VirtualAddress + offset
                candidates.append((rva, table, sec_key))
                log(f"  _mapping[] candidate at RVA 0x{rva:X} ({name}+0x{offset:X})")

            _check(0)

            for offset in range(1, sec_size - 256 + 1):
                # Slide: remove outgoing byte
                out_b = sec_data[offset - 1]
                freq[out_b] -= 1
                if freq[out_b] == 0:
                    distinct -= 1
                # Add incoming byte
                in_b = sec_data[offset + 255]
                if freq[in_b] == 0:
                    distinct += 1
                freq[in_b] += 1

                _check(offset)

            # Found something in .rdata — skip slower sections in fast mode
            if rdata_only and candidates:
                break

        # Sort: .rdata first, then .data, then .text
        order = {'.rdata': 0, '.data': 1, '.text': 2}
        candidates.sort(key=lambda x: order.get(x[2], 3))
        return [c[1] for c in candidates]

    def _find_all_digest_candidates(self, pe, pe_data: bytes, mapping_candidates: list) -> list:
        """Find all d0-d7 candidate sets using multiple strategies.

        Prioritizes xref-based results (most accurate), then falls back to
        heuristic scans. Filters mapping2 from candidates before xref search
        so we only search near the actual data decryption mapping.
        """
        all_candidates = []
        seen = set()

        # Filter mapping2 from candidates for more targeted xref search
        data_mappings = [m for m in mapping_candidates if m != self.expected_binary_mapping2]
        if not data_mappings:
            data_mappings = mapping_candidates

        # Strategy 1: xref to mapping in .text -> decode_hidden function -> extract imm8
        xref_results = self._find_d_via_mapping_xref(pe, pe_data, data_mappings)
        for d in xref_results:
            key = tuple(d)
            if key not in seen:
                seen.add(key)
                all_candidates.append(d)
                log("    digest-key candidate found via xref")

        # Strategy 2: scan imm8 clusters in .text (ADD/MOV patterns)
        scan_results = self._scan_imm8_clusters(pe)
        for d in scan_results:
            key = tuple(d)
            if key not in seen:
                seen.add(key)
                all_candidates.append(d)
                log("    digest-key candidate found via instruction scan")

        # Strategy 3: targeted scan near switch(i%8) patterns
        raw_results = self._scan_raw_imm8_sequences(pe)
        for d in raw_results:
            key = tuple(d)
            if key not in seen and any(v > 0 for v in d):
                seen.add(key)
                all_candidates.append(d)
                log("    digest-key candidate found via switch scan")

        return all_candidates

    def _find_d_via_mapping_xref(self, pe, pe_data: bytes, mapping_candidates: list) -> list:
        """Search .text for LEA/MOV instructions that reference _mapping[].

        In x86-64, static data access uses RIP-relative addressing:
          LEA reg, [RIP + disp32]    -> 48 8D ?? ?? ?? ?? ??
          MOVZX reg, byte [reg + RIP+disp32]  -> various forms

        Once decode_hidden is located, extract the adjacent imm8 constants
        (the d0-d7 from the switch-case).
        """
        results = []
        image_base = pe.OPTIONAL_HEADER.ImageBase

        # Find .text
        text_section = None
        for section in pe.sections:
            name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            if '.text' in name:
                text_section = section
                break

        if not text_section:
            return results

        text_data = text_section.get_data()
        text_va = image_base + text_section.VirtualAddress
        text_rva = text_section.VirtualAddress

        # Search .rdata/.data for the VA of mapping candidates
        for section in pe.sections:
            sec_name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            if sec_name not in ('.rdata', '.data'):
                continue

            sec_data = section.get_data()
            sec_va = image_base + section.VirtualAddress

            # Find all offsets of mapping candidates in this section
            for mapping_table in mapping_candidates:
                mapping_bytes = bytes(mapping_table)
                offset_in_sec = sec_data.find(mapping_bytes)
                if offset_in_sec == -1:
                    continue

                mapping_va = sec_va + offset_in_sec
                log(f"    _mapping[] found at VA 0x{mapping_va:X}")

                # Search for RIP-relative references to mapping_va in .text
                for text_off in range(0, len(text_data) - 8):
                    for insn_len in [3, 4, 5, 6, 7]:
                        if text_off + insn_len + 4 > len(text_data):
                            break
                        disp = struct.unpack('<i', text_data[text_off + insn_len:text_off + insn_len + 4])[0]
                        next_insn_va = text_va + text_off + insn_len + 4
                        target_va = next_insn_va + disp

                        if target_va == mapping_va:
                            func_start = max(0, text_off - 512)
                            func_end = min(len(text_data), text_off + 1024)
                            func_bytes = text_data[func_start:func_end]

                            d_vals = self._extract_imm8_from_switch(func_bytes)
                            if d_vals:
                                results.append(d_vals)
                            break

        return results

    def _extract_imm8_from_switch(self, code_window: bytes) -> list:
        """Extract 8 imm8 values from a code block (switch-case d0-d7).

        Looks for patterns:
        - Sequences of 8 imm8 bytes in instructions like:
            80 C? imm8  (ADD reg8, imm8)
            80 E? imm8  (AND reg8, imm8)
            B? imm8     (MOV reg8, imm8)
            6A imm8     (PUSH imm8)
        Picks the cluster of 8 closest to the center of the window.
        """
        imm8_by_pos = []

        i = 0
        while i < len(code_window) - 2:
            b = code_window[i]
            # ADD reg8, imm8
            if b in (0x80, 0x82) and (code_window[i+1] & 0xF8) in (0xC0, 0xC8, 0xD0, 0xD8, 0xE0, 0xE8, 0xF0, 0xF8):
                imm8_by_pos.append((i, code_window[i+2]))
                i += 3; continue
            # MOV reg8, imm8 (B0-B7)
            if 0xB0 <= b <= 0xB7:
                imm8_by_pos.append((i, code_window[i+1]))
                i += 2; continue
            # PUSH imm8
            if b == 0x6A:
                imm8_by_pos.append((i, code_window[i+1]))
                i += 2; continue
            # ADD al, imm8
            if b == 0x04:
                imm8_by_pos.append((i, code_window[i+1]))
                i += 2; continue
            i += 1

        # Find window of 8 with spread < 200 bytes
        for j in range(len(imm8_by_pos) - 7):
            cluster = imm8_by_pos[j:j+8]
            spread = cluster[7][0] - cluster[0][0]
            if spread < 200:
                vals = [c[1] for c in cluster]
                if len(set(vals)) > 2:
                    return vals

        return []

    def _scan_imm8_clusters(self, pe) -> list:
        """Generic scan for clusters of 8 ADD/MOV imm8 in .text."""
        results = []

        for section in pe.sections:
            name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            if '.text' not in name:
                continue

            sec_data = section.get_data()

            # Find 8 consecutive ADD cl/al/dl, imm8 instructions
            for prefix in [b'\x80\xc1', b'\x80\xc0', b'\x80\xc2']:
                positions = []
                pos = 0
                while pos < len(sec_data) - 3:
                    idx = sec_data.find(prefix, pos)
                    if idx == -1:
                        break
                    imm = sec_data[idx + 2]
                    positions.append((idx, imm))
                    pos = idx + 1

                for j in range(len(positions) - 7):
                    cluster = positions[j:j+8]
                    spread = cluster[7][0] - cluster[0][0]
                    if spread < 600:
                        vals = [c[1] for c in cluster]
                        if len(set(vals)) > 3:
                            results.append(vals)

        return results

    def _scan_raw_imm8_sequences(self, pe) -> list:
        """Search for d0-d7 byte sequences in .text near switch-case instructions.

        Focuses on ADD reg, imm8 patterns that match the compiler output for:
          switch(i%8) { case 0: last = (last + d0) % 256; ... }
        """
        results = []

        for section in pe.sections:
            name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            if '.text' not in name:
                continue

            sec_data = section.get_data()

            # Only look near AND reg, 7 (the i%8 operation) as anchor
            # x86: AND ecx, 7 = 83 E1 07  or  AND eax, 7 = 83 E0 07
            for anchor_prefix in [b'\x83\xe1\x07', b'\x83\xe0\x07', b'\x83\xe2\x07']:
                pos = 0
                while pos < len(sec_data) - 200:
                    idx = sec_data.find(anchor_prefix, pos)
                    if idx == -1:
                        break
                    # Scan 256 bytes after the AND for ADD imm8 patterns
                    window = sec_data[idx:idx + 256]
                    d_vals = self._extract_imm8_from_switch(window)
                    if d_vals and len(set(d_vals)) >= 3:
                        results.append(d_vals)
                    pos = idx + 1
                    if len(results) > 20:
                        return results

        return results

    def _derive_d_from_blob(self, encrypted_blob: bytes, mapping: list) -> list:
        """Derive d0-d7 directly from the encrypted blob using the mapping.

        The encrypted blob layout: [header(8)][encrypted_digest(16)][encrypted_data]
        d0-d7 ARE the first 8 bytes of the MD5 digest. The digest is encrypted
        with the same stream cipher (starting at i=8 with last=0), so we can
        recover them by running the cipher forward:

          For each k in 0..7:
            temp = (last + k) & 0xFF
            digest[k] = mapping[encrypted_blob[8+k] ^ temp]
            last = (digest[k] + digest[k]) & 0xFF   # d[k] = digest[k]

        This eliminates the need to scan the PE for d0-d7 entirely.
        """
        if len(encrypted_blob) < 24:
            return None
        declared_size = struct.unpack_from('<I', encrypted_blob, 4)[0]
        if len(encrypted_blob) != declared_size + 24:
            return None
        if (not isinstance(mapping, (list, tuple)) or len(mapping) != 256
                or any(not isinstance(x, int) or not 0 <= x <= 255
                       for x in mapping)):
            return None

        d = [0] * 8
        last = 0
        for k in range(8):
            c = encrypted_blob[8 + k]
            temp = (last + k) & 0xFF
            c = c ^ temp
            c = mapping[c]
            d[k] = c
            last = (c + c) & 0xFF
        return d

    def decrypt_blob(self, encrypted_blob: bytes, mapping: list, d_values: list) -> bytes:
        """Return a fully MD5/CRC-verified normalization, or ``None``."""
        if len(encrypted_blob) < 24:
            log_err("Blob too small for decryption")
            return None
        try:
            result = self._decrypt_raw(encrypted_blob, mapping, d_values)
        except Exception as exc:
            log_warn(f"Commercial blob normalization failed: {exc}")
            return None
        if not self._check_crc(result):
            log_warn("Post-decrypt CRC32/length verification failed")
            return None
        log_ok("Decryption verified (MD5 witness + CRC32 + exact length)")
        return result


# =============================================================================
# PE ANALYSIS
# =============================================================================

_NDL_TARGET_PYTHON_OVERRIDE = None

# Explicit target layouts used by the constants/code-object and PYC paths.
# Do not silently reinterpret an unknown ABI as the interpreter running this
# tool: that produces valid-looking but structurally wrong metadata.
_NDL_SUPPORTED_TARGET_PYTHONS = frozenset(
    [(2, 7)] + [(3, minor) for minor in range(0, 15)])


def _ndl_parse_target_python_version(version):
    if isinstance(version, str):
        match = re.fullmatch(r'\s*(\d+)\.(\d+)\s*', version)
        if not match:
            raise ValueError("target Python must be exactly MAJOR.MINOR")
        parsed = (int(match.group(1)), int(match.group(2)))
    else:
        try:
            parsed = (int(version[0]), int(version[1]))
        except Exception as exc:
            raise ValueError(
                "target Python must be a (major, minor) pair") from exc
    if parsed not in _NDL_SUPPORTED_TARGET_PYTHONS:
        raise ValueError(
            f"unsupported target Python {parsed[0]}.{parsed[1]}; "
            "supported layouts are 2.7 and 3.0 through 3.14")
    return parsed


def _ndl_set_target_python_override(version):
    """Set the authoritative target ABI selected by the caller.

    This is deliberately separate from ``set_nuitka_target_python``: the latter
    is temporary decoder state and is saved/restored while probing a constants
    stream.  Treating it as a CLI override made ``--target-python`` disappear as
    soon as the live context auto-detected the input again.
    """
    global _NDL_TARGET_PYTHON_OVERRIDE
    if version is None:
        _NDL_TARGET_PYTHON_OVERRIDE = None
        return
    _NDL_TARGET_PYTHON_OVERRIDE = _ndl_parse_target_python_version(version)


def detect_python_version_from_pe(pe_data: bytes):
    """Detect the embedded CPython ABI, returning ``None`` when unknown.

    Falling back to the interpreter running this script is unsafe: a Python
    3.10 Nuitka onefile bootstrap analysed under Python 3.14 used to be parsed
    with the 3.14 code-object layout.  Unknown is now an explicit state and the
    caller may resolve it with ``--target-python``.
    """
    try:
        import pefile
        pe = pefile.PE(data=pe_data)
        if hasattr(pe, 'DIRECTORY_ENTRY_IMPORT'):
            for entry in pe.DIRECTORY_ENTRY_IMPORT:
                dll_name = entry.dll.decode('ascii', errors='replace').lower()
                m = re.fullmatch(
                    r'python(\d)(\d{1,2})(?:t)?(?:_d)?\.dll', dll_name)
                if m:
                    try:
                        return _ndl_parse_target_python_version(m.groups())
                    except ValueError:
                        continue
        # Also search .rdata section for python3XX.dll strings
        for section in pe.sections:
            sec_data = section.get_data()
            for match in re.finditer(
                    rb'python(\d)(\d{1,2})(?:t)?(?:_d)?\.dll',
                    sec_data, re.IGNORECASE):
                try:
                    return _ndl_parse_target_python_version(match.groups())
                except ValueError:
                    continue
    except Exception:
        pass
    try:
        # Raw scan also covers malformed PE import tables and ELF/Mach-O names.
        for pattern in (
                rb'python(\d)(\d{1,2})(?:t)?(?:_d)?\.dll',
                rb'libpython(\d)\.(\d{1,2})(?:t)?(?:m|d)?'
                rb'(?:\.so(?:\.\d+)*|\.dylib|\x00)',
                rb'Python\.framework/Versions/(\d)\.(\d{1,2})'):
            match = re.search(pattern, pe_data or b'', re.IGNORECASE)
            if match:
                try:
                    return _ndl_parse_target_python_version(match.groups())
                except ValueError:
                    continue
    except Exception:
        pass
    return None


def _ndl_detect_python_from_blob(pe_data):
    """Fallback: cerca pattern python3XX nel PE anche senza import table."""
    for m in re.finditer(rb'python3(\d{1,2})', pe_data or b'', re.IGNORECASE):
        minor = int(m.group(1))
        if 0 <= minor <= 14:
            return (3, minor)
    for m in re.finditer(rb'libpython3\.(\d{1,2})', pe_data or b''):
        minor = int(m.group(1))
        if 0 <= minor <= 14:
            return (3, minor)
    return None


def detect_nuitka_edition(pe_data: bytes, blob_data: bytes = None) -> str:
    """Detect whether the binary is Nuitka open-source or Commercial.

    Uses both string indicators in the PE and structural analysis of the blob.
    The most reliable indicator is the 16-byte MD5 digest that commercial
    data-hiding inserts between the header and the module data.
    """
    # Structural blob check (most reliable for stripped binaries)
    if blob_data and len(blob_data) >= 24:
        size_stored = struct.unpack('<I', blob_data[4:8])[0]
        extra_bytes = len(blob_data) - 8 - size_stored
        if extra_bytes == 16:
            return "commercial"
    if blob_data and len(blob_data) >= 8:
        crc_stored, size_stored = struct.unpack_from('<II', blob_data, 0)
        if len(blob_data) == size_stored + 8:
            crc_actual = zlib.crc32(blob_data[8:]) & 0xFFFFFFFF
            if crc_actual == crc_stored:
                return "opensource"

    indicators_commercial = [
        b'decode_hidden', b'decode_public', b'_mapping2',
        b'data-hiding', b'DataHiding',
        b'nuitka_data_decoder',
    ]
    indicators_opensource = [
        b'Nuitka', b'nuitka_empty_function',
        b'loadConstantsBlob', b'MetaPathBasedLoader',
    ]

    score_commercial = 0
    score_opensource = 0

    for indicator in indicators_commercial:
        if indicator in pe_data:
            score_commercial += 1

    for indicator in indicators_opensource:
        if indicator in pe_data:
            score_opensource += 1

    if score_commercial >= 2:
        return "commercial"
    elif score_opensource >= 1:
        return "opensource"
    return "unknown"


def _find_blob_in_raw_bytes(data: bytes) -> bytes:
    """Scan raw bytes for a Nuitka constants blob (open-source or commercial)."""
    n = len(data)
    # Search for open-source (CRC32 verified) blobs
    for offset in range(0, n - 8, 4):
        potential_size = struct.unpack('<I', data[offset + 4:offset + 8])[0]
        if not (1000 < potential_size < 50_000_000):
            continue
        if offset + 8 + potential_size <= n:
            potential_crc = struct.unpack('<I', data[offset:offset + 4])[0]
            actual_crc = zlib.crc32(data[offset + 8:offset + 8 + potential_size]) & 0xFFFFFFFF
            if actual_crc == potential_crc:
                log_ok(f"Blob found via raw scan at offset 0x{offset:X} ({8 + potential_size:,} bytes)")
                return bytes(data[offset:offset + 8 + potential_size])

    # Search for commercial/encrypted blobs (using heuristics similar to _find_embedded_blob)
    best = None
    for offset in range(0, n - 8, 4):
        potential_size = struct.unpack('<I', data[offset + 4:offset + 8])[0]
        if not (1000 < potential_size < 50_000_000):
            continue
        encrypted_total = 8 + 16 + potential_size
        if offset + encrypted_total <= n:
            tail = data[offset + encrypted_total:offset + encrypted_total + 32]
            score = 0
            if offset % 16 == 0:
                score += 2
            if not tail or all(b == 0 for b in tail[:min(len(tail), 16)]):
                score += 3
            if offset + encrypted_total >= n - 64:
                score += 2
            if potential_size > 64 * 1024:
                score += 1
            if best is None or score > best[0]:
                best = (score, offset, potential_size)
    if best is not None:
        score, offset, potential_size = best
        blob = bytes(data[offset:offset + 8 + 16 + potential_size])
        log_ok(f"Encrypted commercial blob candidate via raw scan at offset 0x{offset:X} ({len(blob):,} bytes, score={score})")
        return blob
    return None


def _ndl_pe_resource_bytes(pe, type_id, resource_id):
    """Return one numeric PE resource without writing it to disk."""
    try:
        image = pe.get_memory_mapped_image()
        for res_type in pe.DIRECTORY_ENTRY_RESOURCE.entries:
            if res_type.id != int(type_id):
                continue
            for res_name in res_type.directory.entries:
                if res_name.id != int(resource_id):
                    continue
                for res_lang in res_name.directory.entries:
                    data_rva = int(res_lang.data.struct.OffsetToData)
                    size = int(res_lang.data.struct.Size)
                    if size <= 0 or data_rva < 0 or data_rva + size > len(image):
                        return None
                    return bytes(image[data_rva:data_rva + size])
    except Exception:
        return None
    return None


def _ndl_zstd_decompress_bounded(payload, max_output):
    """Decompress one Zstandard frame with a hard output bound.

    Python 3.14 ships ``compression.zstd``; older interpreters can use the
    normal ``zstandard`` package.  Nuitka onefile resources sometimes leave
    zero alignment bytes after the frame, which are accepted only when they are
    actually zero.
    """
    errors = []
    try:
        from compression import zstd as _zstd
        decoder = _zstd.ZstdDecompressor()
        out = decoder.decompress(payload, max_length=int(max_output) + 1)
        if len(out) > int(max_output) or not decoder.eof:
            raise ValueError("onefile zstd output exceeds the configured bound")
        unused = bytes(getattr(decoder, 'unused_data', b'') or b'')
        if unused and any(unused):
            raise ValueError("non-zero data follows the onefile zstd frame")
        return bytes(out)
    except (ImportError, AttributeError) as exc:
        errors.append(str(exc))
    except Exception as exc:
        errors.append(str(exc))

    try:
        import io as _io
        import zstandard as _zstd
        if not hasattr(_zstd, 'ZstdDecompressor'):
            raise ImportError("zstandard package has no decoder extension")
        # Windows aligns the attached payload before writing its trailing
        # uint64 size.  Consequently the RCDATA resource can contain up to
        # seven NUL bytes after the Zstandard frame.  ``stream_reader`` tries
        # to interpret those bytes as another frame (even with
        # read_across_frames=False) and reports ``Unknown frame descriptor``.
        # The one-shot API deliberately stops at the first complete frame and
        # still enforces max_output_size, so prefer it here.  This also avoids
        # deleting bytes that merely *look* like padding from a valid frame.
        try:
            out = _zstd.ZstdDecompressor().decompress(
                payload, max_output_size=int(max_output) + 1)
            if len(out) > int(max_output):
                raise ValueError(
                    "onefile zstd output exceeds the configured bound")
            return bytes(out)
        except Exception as direct_exc:
            errors.append(str(direct_exc))

        # Compatibility fallback for frames produced without a content-size
        # field, for which some python-zstandard releases require streaming.
        # Only proven Windows alignment bytes are removed.
        stream_payload = payload
        padding = len(stream_payload) - len(stream_payload.rstrip(b'\x00'))
        if 0 < padding <= 7:
            stream_payload = stream_payload[:-padding]
        result = bytearray()
        with _zstd.ZstdDecompressor().stream_reader(
                _io.BytesIO(stream_payload), read_across_frames=False) as reader:
            while True:
                chunk = reader.read(min(1024 * 1024,
                                        int(max_output) + 1 - len(result)))
                if not chunk:
                    break
                result.extend(chunk)
                if len(result) > int(max_output):
                    raise ValueError(
                        "onefile zstd output exceeds the configured bound")
        return bytes(result)
    except Exception as exc:
        errors.append(str(exc))

    raise RuntimeError(
        "cannot decompress Nuitka onefile payload; use Python 3.14+ or install "
        "the 'zstandard' package (" + "; ".join(x for x in errors if x) + ")")


def _ndl_is_python_source_archive_name(name):
    """True only for safe relative .py/.pyw members of a onefile archive."""
    normalized = str(name or '').replace('\\', '/')
    if (not normalized or normalized.startswith('/') or
            '..' in normalized.split('/')):
        return False
    return normalized.lower().endswith(('.py', '.pyw'))


def _ndl_parse_windows_onefile_archive(
        archive, *, max_file_size, collect_sources=False,
        max_source_bytes=64 * 1024 * 1024):
    """Parse the Windows onefile stream emitted by ``OnefileCompressor``.

    The first record is the executable/DLL run by the bootstrap.  We retain
    the child PE and the entry-name inventory.  When explicitly requested,
    `.py`/`.pyw` members are retained byte-for-byte under a separate bounded
    budget; other archive members are never copied.
    """
    data = memoryview(archive)
    pos = 0
    names = []
    first = None
    first_name = None
    embedded_sources = {}
    skipped_sources = []
    source_total = 0
    while True:
        name_start = pos
        while pos + 2 <= len(data) and bytes(data[pos:pos + 2]) != b'\x00\x00':
            pos += 2
            if pos - name_start > 8192:
                raise ValueError("onefile entry name exceeds 4096 UTF-16 characters")
        if pos + 2 > len(data):
            raise ValueError("truncated onefile entry name")
        raw_name = bytes(data[name_start:pos])
        pos += 2
        if not raw_name:
            if pos != len(data) and any(data[pos:]):
                raise ValueError("non-zero bytes after onefile archive terminator")
            break
        try:
            name = raw_name.decode('utf-16le', errors='strict')
        except UnicodeDecodeError as exc:
            raise ValueError("invalid UTF-16 onefile entry name") from exc
        if '\x00' in name or os.path.isabs(name) or '..' in name.replace('\\', '/').split('/'):
            raise ValueError("unsafe onefile entry name")
        if pos + 8 > len(data):
            raise ValueError("truncated onefile entry size")
        file_size = int(struct.unpack_from('<Q', data, pos)[0])
        pos += 8
        if file_size > int(max_file_size) or pos + file_size > len(data):
            raise ValueError("invalid or oversized onefile entry")
        names.append(name)
        if first is None:
            first_name = name
            first = bytes(data[pos:pos + file_size])
        if collect_sources and _ndl_is_python_source_archive_name(name):
            if source_total + file_size <= int(max_source_bytes):
                embedded_sources[name] = bytes(data[pos:pos + file_size])
                source_total += file_size
            else:
                skipped_sources.append(name)
        pos += file_size
    if not names or first is None:
        raise ValueError("empty Nuitka onefile archive")
    return {
        'name': first_name,
        'data': first,
        'entries': tuple(names),
        'archive_bytes': len(archive),
        'archive_format': 'stream',
        'embedded_sources': embedded_sources,
        'skipped_source_entries': tuple(skipped_sources),
    }


def _ndl_parse_windows_onefile_per_file_archive(
        archive, *, max_file_size, collect_sources=False,
        max_source_bytes=64 * 1024 * 1024):
    """Parse ``--onefile-as-archive`` Windows payloads.

    Despite retaining the ``KAY`` header, this mode does not compress the
    complete filename/file stream as one Zstandard frame.  Each record stores
    its uncompressed uint64 size, optionally a uint32 CRC (persistent/cached
    onefile mode), a uint32 compressed size, and one independent Zstd frame.
    The frame magic gives an exact discriminator for the optional checksum.
    """
    data = memoryview(archive)
    pos = 0
    names = []
    first = None
    first_name = None
    embedded_sources = {}
    skipped_sources = []
    source_total = 0
    checksum_layout = None
    zstd_magic = b'\x28\xb5\x2f\xfd'

    while True:
        name_start = pos
        while pos + 2 <= len(data) and bytes(data[pos:pos + 2]) != b'\x00\x00':
            pos += 2
            if pos - name_start > 8192:
                raise ValueError(
                    "onefile entry name exceeds 4096 UTF-16 characters")
        if pos + 2 > len(data):
            raise ValueError("truncated onefile archive entry name")
        raw_name = bytes(data[name_start:pos])
        pos += 2
        if not raw_name:
            if pos != len(data) and any(data[pos:]):
                raise ValueError(
                    "non-zero bytes after onefile archive terminator")
            break
        try:
            name = raw_name.decode('utf-16le', errors='strict')
        except UnicodeDecodeError as exc:
            raise ValueError("invalid UTF-16 onefile archive name") from exc
        if ('\x00' in name or os.path.isabs(name)
                or '..' in name.replace('\\', '/').split('/')):
            raise ValueError("unsafe onefile archive entry name")
        if pos + 12 > len(data):
            raise ValueError("truncated onefile archive entry header")

        file_size = int(struct.unpack_from('<Q', data, pos)[0])
        pos += 8
        if file_size > int(max_file_size):
            raise ValueError("oversized onefile archive entry")

        # No-checksum: [compressed-size][zstd magic].
        # Cached layout: [crc32][compressed-size][zstd magic].
        no_checksum = bytes(data[pos + 4:pos + 8]) == zstd_magic
        with_checksum = (pos + 12 <= len(data)
                         and bytes(data[pos + 8:pos + 12]) == zstd_magic)
        if no_checksum == with_checksum:
            raise ValueError("invalid onefile per-file Zstandard header")
        this_checksum_layout = bool(with_checksum)
        if checksum_layout is None:
            checksum_layout = this_checksum_layout
        elif checksum_layout != this_checksum_layout:
            raise ValueError("mixed onefile archive checksum layouts")
        if with_checksum:
            # Retained for structural validation; the CRC applies to the
            # original file and is checked after decompressing the first child.
            expected_crc = int(struct.unpack_from('<I', data, pos)[0])
            pos += 4
        else:
            expected_crc = None
        compressed_size = int(struct.unpack_from('<I', data, pos)[0])
        pos += 4
        if (compressed_size <= 0 or pos + compressed_size > len(data)
                or bytes(data[pos:pos + 4]) != zstd_magic):
            raise ValueError("invalid onefile per-file compressed size")

        names.append(name)
        is_source = (collect_sources and
                     _ndl_is_python_source_archive_name(name))
        keep_source = (is_source and
                       source_total + file_size <= int(max_source_bytes))
        if is_source and not keep_source:
            skipped_sources.append(name)
        unpacked = None
        if first is None or keep_source:
            unpacked = _ndl_zstd_decompress_bounded(
                bytes(data[pos:pos + compressed_size]), max_file_size)
            if len(unpacked) != file_size:
                raise ValueError(
                    "onefile entry decompressed size does not match header")
            if (expected_crc is not None
                    and (zlib.crc32(unpacked) & 0xffffffff) != expected_crc):
                raise ValueError("onefile entry CRC32 mismatch")
        if first is None:
            first_name = name
            first = unpacked
        if keep_source:
            embedded_sources[name] = unpacked
            source_total += file_size
        pos += compressed_size

    if not names or first is None:
        raise ValueError("empty Nuitka per-file onefile archive")
    return {
        'name': first_name,
        'data': first,
        'entries': tuple(names),
        'archive_bytes': len(archive),
        'archive_format': 'per-file-zstd',
        'file_checksums': bool(checksum_layout),
        'embedded_sources': embedded_sources,
        'skipped_source_entries': tuple(skipped_sources),
    }


def _ndl_extract_nuitka_onefile_child(
        pe, *, max_output=None, collect_sources=False,
        max_source_bytes=None):
    """Return the first PE contained in a Windows Nuitka onefile resource.

    ``None`` means the input is not a onefile bootstrap.  A recognised ``KAX``
    or ``KAY`` resource that cannot be validated raises instead of falling
    through to the raw encrypted-blob heuristic in the bootstrap's ``.text``.
    """
    resource = _ndl_pe_resource_bytes(pe, 10, 27)
    if not resource or resource[:2] != b'KA':
        return None
    if len(resource) < 4 or resource[2:3] not in (b'X', b'Y'):
        raise ValueError("unsupported Nuitka onefile payload header")
    if max_output is None:
        try:
            max_output = int(os.environ.get(
                'NDL_ONEFILE_MAX_BYTES', str(2 * 1024 * 1024 * 1024)))
        except Exception:
            max_output = 2 * 1024 * 1024 * 1024
    max_output = max(1024 * 1024, int(max_output))
    if max_source_bytes is None:
        try:
            max_source_bytes = int(os.environ.get(
                'NDX_MAX_EMBEDDED_SOURCE_BYTES', str(64 * 1024 * 1024)))
        except Exception:
            max_source_bytes = 64 * 1024 * 1024
    max_source_bytes = max(
        0, min(int(max_source_bytes), min(max_output, 512 * 1024 * 1024)))

    payload_end = len(resource)
    # Current compressors append the payload byte count; older Windows builds
    # may omit it.  Strip it only when the value proves its own location.
    if len(resource) >= 11:
        trailer_size = int(struct.unpack_from('<Q', resource, len(resource) - 8)[0])
        if trailer_size == len(resource) - 8:
            payload_end -= 8
    payload = resource[3:payload_end]
    if resource[2:3] == b'Y':
        if payload.startswith(b'\x28\xb5\x2f\xfd'):
            archive = _ndl_zstd_decompress_bounded(payload, max_output)
            result = _ndl_parse_windows_onefile_archive(
                archive, max_file_size=max_output,
                collect_sources=collect_sources,
                max_source_bytes=max_source_bytes)
        else:
            # ``--onefile-as-archive`` compresses each member separately and
            # therefore begins with the first UTF-16 filename, not frame magic.
            result = _ndl_parse_windows_onefile_per_file_archive(
                payload, max_file_size=max_output,
                collect_sources=collect_sources,
                max_source_bytes=max_source_bytes)
    else:
        if len(payload) > max_output:
            raise ValueError("onefile archive exceeds the configured bound")
        archive = payload
        result = _ndl_parse_windows_onefile_archive(
            archive, max_file_size=max_output,
            collect_sources=collect_sources,
            max_source_bytes=max_source_bytes)
    if result['data'][:2] != b'MZ':
        raise ValueError("first Nuitka onefile entry is not a PE image")
    result['compression'] = resource[2:3].decode('ascii')
    result['resource_bytes'] = len(resource)
    return result


def extract_pe_constants_blob(pe_path: str, pe_data: bytes = None,
                              _resolve_onefile: bool = True) -> bytes:
    """Extract a Nuitka constants blob from a PE or its onefile child."""
    try:
        import pefile
    except ImportError:
        log_err("pefile not installed. Run: pip install pefile")
        try:
            data = pe_data
            if data is None:
                with open(pe_path, 'rb') as f:
                    data = f.read()
            return _find_blob_in_raw_bytes(data)
        except Exception:
            return None

    try:
        pe = pefile.PE(data=pe_data) if pe_data is not None else pefile.PE(pe_path)
    except Exception as e:
        log_err(f"PE parsing error: {e}")
        try:
            data = pe_data
            if data is None:
                with open(pe_path, 'rb') as f:
                    data = f.read()
            return _find_blob_in_raw_bytes(data)
        except Exception:
            pass
        return None

    # Reject physically truncated PE files before section/resource fallbacks.
    # pefile can parse headers whose sections point far beyond EOF and returns
    # the remaining bytes from ``section.get_data()``; scanning that partial
    # data produced convincing-looking but false encrypted-blob candidates.
    try:
        file_size = len(pe_data) if pe_data is not None else os.path.getsize(pe_path)
        missing = []
        for section in pe.sections:
            raw_size = int(section.SizeOfRawData or 0)
            raw_off = int(section.PointerToRawData or 0)
            if raw_size and raw_off + raw_size > file_size:
                name = section.Name.rstrip(b'\x00').decode(
                    'ascii', errors='replace')
                missing.append((name, raw_off + raw_size))
        if missing:
            name, required = max(missing, key=lambda x: x[1])
            log_err(
                f"PE file is truncated: {file_size:,} bytes on disk, but "
                f"section {name!r} requires at least {required:,} bytes. "
                "Re-copy/re-download the complete binary before decompiling.")
            return None
    except Exception:
        pass

    blob = _ndl_pe_resource_bytes(pe, 10, 3)
    if blob is not None:
        log_ok(f"Blob found in RT_RCDATA #3 ({len(blob):,} bytes)")
        return blob

    # A onefile bootstrap is not the compiled application. Resolve resource 27
    # before any section/raw scan, otherwise random bootstrap bytes can look like
    # a Commercial blob header.
    if _resolve_onefile:
        try:
            child = _ndl_extract_nuitka_onefile_child(pe)
        except Exception as exc:
            log_err(f"Nuitka onefile payload could not be decoded: {exc}")
            extract_pe_constants_blob.last_error = 'onefile_decode_failed'
            return None
        if child is not None:
            log_ok(
                f"Nuitka onefile child selected: {child['name']} "
                f"({len(child['data']):,} bytes; {len(child['entries'])} entries)")
            return extract_pe_constants_blob(
                pe_path, pe_data=child['data'], _resolve_onefile=False)

    # Fallback: search for blob embedded as C array (incbin / const array)
    log_warn("Blob not found in RT_RCDATA, searching for static embedding...")
    blob = _find_embedded_blob(pe)
    if blob:
        return blob

    try:
        data = pe_data
        if data is None:
            with open(pe_path, 'rb') as f:
                data = f.read()
        return _find_blob_in_raw_bytes(data)
    except Exception:
        pass
    return None


# Regex for a real Nuitka module/entry chunk name: dotted identifiers (with an
# optional leading '.' for meta chunks like .bytecode/.files). Used only as the
# sanity gate for the headerless-incbin locator below.
_BLOB_MODNAME_RE = re.compile(r'^\.?[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_0-9][A-Za-z0-9_]*)*$')



def _find_blob_by_bytecode_anchor(pe) -> bytes:
    """Locate and exactly carve a headerless Nuitka constants blob.

    Standalone DLLs and extension modules can embed the DataComposer stream
    without the outer ``[crc32][size]`` resource header.  The first chunk is
    normally ``.bytecode``.  Older code carved from that marker to the end of
    the PE section, which mixed alignment/adjacent data into the blob and could
    produce misleading CRCs and cache keys.

    This implementation scans every occurrence of the marker, validates the
    complete chunk stream, and re-frames only the exact validated byte range.
    It never executes the target.
    """
    anchor_marker = b'.bytecode\x00'
    max_chunk = 100 * 1024 * 1024
    max_name = 4096

    def _walk_stream(data, start):
        n = len(data)
        pos = start
        end = start
        names = []
        empty_seen = False
        confirmed_module = False

        for index in range(1_000_000):
            if pos + 5 > n:
                break
            nul = data.find(b'\x00', pos, min(pos + max_name + 1, n))
            if nul < 0:
                break
            raw_name = data[pos:nul]
            try:
                name = raw_name.decode('utf-8', errors='strict')
            except UnicodeDecodeError:
                break
            if not _is_plausible_blob_module_name(name):
                break
            if index == 0 and name != '.bytecode':
                break
            if name == '':
                if empty_seen:
                    break
                empty_seen = True

            size_pos = nul + 1
            if size_pos + 4 > n:
                break
            chunk_size = struct.unpack_from('<I', data, size_pos)[0]
            data_pos = size_pos + 4
            chunk_end = data_pos + chunk_size
            # Zero-sized chunks are indistinguishable from section padding and
            # are not emitted by the DataComposer layouts supported here.
            if chunk_size == 0 or chunk_size > max_chunk or chunk_end > n:
                break

            names.append(name)
            if name and not name.startswith('.') and index > 0:
                confirmed_module = True
            end = chunk_end
            pos = chunk_end

        if len(names) < 2 or names[0] != '.bytecode' or not confirmed_module:
            return None
        return end, names

    section_order = {'.rdata': 0, '.data': 1, '.text': 2}
    sections = sorted(
        pe.sections,
        key=lambda s: section_order.get(
            s.Name.rstrip(b'\x00').decode('ascii', errors='replace'), 3),
    )

    for section in sections:
        sec_name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
        sec_data = section.get_data()
        search_at = 0
        while True:
            anchor = sec_data.find(anchor_marker, search_at)
            if anchor < 0:
                break
            walked = _walk_stream(sec_data, anchor)
            if walked is not None:
                end, names = walked
                payload = bytes(sec_data[anchor:end])
                crc = zlib.crc32(payload) & 0xFFFFFFFF
                trailing = len(sec_data) - end
                log_ok(
                    f"Blob located via .bytecode anchor in {sec_name}+0x{anchor:X} "
                    f"(headerless incbin; exact payload {len(payload):,} bytes; "
                    f"{len(names):,} chunks; excluded {trailing:,} trailing "
                    f"section bytes)"
                )
                return struct.pack('<II', crc, len(payload)) + payload
            search_at = anchor + 1

    return None


def _find_embedded_blob(pe) -> bytes:
    """Search for the blob embedded directly in sections (incbin mode).

    Memory-/CPU-bounded: on a non-Nuitka or onefile-bootstrapper binary (no
    plaintext blob) ~1% of 4-byte offsets pass the size gate, so the old code
    (a) accumulated a copy of up to ~50 MB per candidate into a list and
    (b) ran crc32 over huge slices at every fitting offset — together that
    exhausted RAM and pegged the CPU for minutes. We now keep only the best
    candidate's METADATA (re-slicing the winner once at the end) and cap the
    cumulative crc32 work, degrading to "not found" instead of OOM."""

    # Headerless incbin is common for DLLs and can be validated exactly from the
    # canonical first chunk. Try it before the expensive CRC sweep.
    anchored = _find_blob_by_bytecode_anchor(pe)
    if anchored is not None:
        return anchored

    # (best_score, section_index, offset, potential_size) — no bytes retained.
    best = None
    # Cap cumulative bytes fed to crc32 across the whole scan. A genuine incbin
    # blob's header crc matches as soon as we reach its offset; this bound just
    # stops the fruitless scan of a non-Nuitka target from running for minutes.
    crc_budget = 2 * 1024 * 1024 * 1024
    crc_spent = 0
    crc_exhausted = False

    for sec_index, section in enumerate(pe.sections):
        name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
        sec_data = section.get_data()
        n = len(sec_data)

        for offset in range(0, n - 8, 4):
            potential_size = struct.unpack('<I', sec_data[offset + 4:offset + 8])[0]
            if not (1000 < potential_size < 50_000_000):
                continue
            if offset + 8 + potential_size <= n and not crc_exhausted:
                potential_crc = struct.unpack('<I', sec_data[offset:offset + 4])[0]
                actual_crc = zlib.crc32(
                    sec_data[offset + 8:offset + 8 + potential_size]) & 0xFFFFFFFF
                crc_spent += potential_size
                if crc_spent > crc_budget:
                    crc_exhausted = True
                    log_warn("Embedded-blob crc scan budget reached; "
                             "skipping further plaintext checks")
                if actual_crc == potential_crc:
                    blob = sec_data[offset:offset + 8 + potential_size]
                    log_ok(f"Blob found in {name}+0x{offset:X} ({len(blob):,} bytes)")
                    return bytes(blob)

            # Nuitka Commercial data-hiding keeps the 8-byte header clear and
            # inserts a 16-byte encrypted MD5 digest before the real payload.
            # The CRC will not match until Phase 3 decrypts it, so score these
            # as second-pass candidates — but retain only the BEST one's
            # metadata, never a copy of the bytes (that was the OOM).
            encrypted_total = 8 + 16 + potential_size
            if offset + encrypted_total <= n:
                tail = sec_data[offset + encrypted_total:offset + encrypted_total + 32]
                score = 0
                if offset % 16 == 0:
                    score += 2
                if not tail or all(b == 0 for b in tail[: min(len(tail), 16)]):
                    score += 3
                if offset + encrypted_total >= n - 64:
                    score += 2
                # Prefer realistic Nuitka blobs over accidental integers.
                if potential_size > 64 * 1024:
                    score += 1
                if best is None or score > best[0]:
                    best = (score, sec_index, offset, potential_size)

    if best is not None:
        score, sec_index, offset, potential_size = best
        sec_data = pe.sections[sec_index].get_data()
        name = pe.sections[sec_index].Name.rstrip(b'\x00').decode('ascii', errors='replace')
        blob = bytes(sec_data[offset:offset + 8 + 16 + potential_size])
        log_ok(
            f"Encrypted commercial blob candidate in {name}+0x{offset:X} "
            f"({len(blob):,} bytes, score={score})"
        )
        return blob

    return None


# =============================================================================
# EMBEDDED SOURCE DETECTION
# =============================================================================

PYTHON_SOURCE_STARTERS = (
    'def ', 'class ', 'import ', 'from ', 'return ',
    'if ', 'elif ', 'else:', 'for ', 'while ', 'try:',
    'except ', 'with ', 'yield ', '#', '    ', '@', 'async ',
)


def _python_source_confidence(data: bytes) -> float:
    """Return 0.0-1.0: how likely *data* is Python source code."""
    if len(data) < 30:
        return 0.0
    text = None
    for enc in ('utf-8-sig', 'utf-8', 'utf-16', 'latin-1'):
        try:
            text = data.decode(enc)
            break
        except UnicodeDecodeError:
            pass
    if text is None:
        return 0.0
    lines = text.splitlines()
    if not lines:
        return 0.0
    window = lines[:min(len(lines), 320)]
    signal = 0.0
    body = 0
    for ln in window:
        stripped = ln.strip()
        if not stripped:
            continue
        body += 1
        if stripped.startswith('#!') or 'coding' in stripped.lower():
            signal += 0.75
            continue
        if stripped.startswith(PYTHON_SOURCE_STARTERS):
            signal += 1.0
        if stripped.endswith(':') and re.match(
                r'^(async\s+def|def|class|if|elif|else|for|while|try|except|with|match|case)\b',
                stripped):
            signal += 0.75
        if (' import ' in f' {stripped} ' or stripped.startswith('from ')
                or ' return ' in f' {stripped} ' or ' raise ' in f' {stripped} '):
            signal += 0.25
    score = signal / max(body, 1)
    snippet = text[:20000]
    if '#!/usr/bin/env python' in snippet or '# -*- coding' in snippet:
        score = min(1.0, score + 0.4)
    if 'def ' in snippet and ('import ' in snippet or 'class ' in snippet):
        score = min(1.0, score + 0.25)
    try:
        import ast as _ast
        _ast.parse(snippet)
        score = min(1.0, score + 0.2)
    except Exception:
        pass
    return score


def _try_decompress(data: bytes):
    """Try zlib decompression (various wbits). Returns bytes or None."""
    for wbits in (15, -15, 47):
        try:
            return zlib.decompress(data, wbits)
        except Exception:
            pass
    return None


def scan_pe_resources_for_source(pe_path: str, output_dir: str) -> list:
    """Scan ALL PE resources for embedded Python source or compressed blobs.

    The Nuitka constants blob lives at RT_RCDATA/3 and is handled elsewhere.
    Every other resource entry is checked for:
      - Raw Python source text
      - zlib-compressed Python source
      - Any data > 32 B (saved for manual inspection)

    Returns list of dicts: {path, size, confidence, saved_at}
    """
    try:
        import pefile
    except ImportError:
        log_warn("pefile not installed - skipping resource scan")
        return []

    results = []
    res_dir = os.path.join(output_dir, "pe_resources")
    os.makedirs(res_dir, exist_ok=True)

    RT_NAMES = {
        1: 'RT_CURSOR', 2: 'RT_BITMAP', 3: 'RT_ICON', 4: 'RT_MENU',
        5: 'RT_DIALOG', 6: 'RT_STRING', 7: 'RT_FONTDIR', 8: 'RT_FONT',
        9: 'RT_ACCELERATOR', 10: 'RT_RCDATA', 11: 'RT_MESSAGETABLE',
        14: 'RT_GROUP_ICON', 16: 'RT_VERSION', 24: 'RT_MANIFEST',
    }

    try:
        pe = pefile.PE(pe_path)
    except Exception as e:
        log_warn(f"PE resource scan error: {e}")
        return results

    if not hasattr(pe, 'DIRECTORY_ENTRY_RESOURCE'):
        log("  No PE resources directory found")
        return results

    mm = pe.get_memory_mapped_image()
    saved_hashes = set()

    def _save_resource(path, data, conf):
        h = zlib.crc32(data) & 0xFFFFFFFF
        if h in saved_hashes:
            return None
        saved_hashes.add(h)
        safe = re.sub(r'[<>:"|?*/\\]', '_', path)
        ext  = '.py' if conf > 0.25 else '.bin'
        out  = os.path.join(res_dir, safe + ext)
        with open(out, 'wb') as fh:
            fh.write(data)
        return out

    def _visit(node, path):
        if hasattr(node, 'data'):
            try:
                rva  = node.data.struct.OffsetToData
                size = node.data.struct.Size
                if size < 32:
                    return
                raw = bytes(mm[rva:rva + size])
                # Skip Nuitka constants blob (RT_RCDATA/3/*)
                if re.match(r'^RT_RCDATA/3', path):
                    return
                conf  = _python_source_confidence(raw)
                used  = raw
                label = path
                if conf < 0.15:
                    dec = _try_decompress(raw)
                    if dec:
                        dc = _python_source_confidence(dec)
                        if dc > conf:
                            conf, used, label = dc, dec, path + '[zlib]'
                out = _save_resource(label, used, conf)
                if out:
                    rec = {'path': path, 'size': size,
                           'confidence': round(conf, 3), 'saved_at': out}
                    results.append(rec)
                    if conf > 0.30:
                        log_fire(f"  SOURCE CANDIDATE resource {path}: "
                                 f"conf={conf:.2f} ({size:,} B) -> {out}")
                    else:
                        log(f"  Resource {path}: {size:,} B conf={conf:.2f} -> saved")
            except Exception:
                pass
            return

        if hasattr(node, 'directory'):
            for child in node.directory.entries:
                if hasattr(child, 'name') and child.name:
                    child_id = child.name.string.decode('utf-8', errors='replace')
                elif hasattr(child, 'id') and child.id is not None:
                    child_id = str(child.id)
                else:
                    child_id = '?'
                _visit(child, f"{path}/{child_id}" if path else child_id)

    for top in pe.DIRECTORY_ENTRY_RESOURCE.entries:
        if hasattr(top, 'id') and top.id is not None:
            top_name = RT_NAMES.get(top.id, f'TYPE_{top.id}')
        elif hasattr(top, 'name') and top.name:
            top_name = top.name.string.decode('utf-8', errors='replace')
        else:
            top_name = 'UNKNOWN'
        _visit(top, top_name)

    return results


def scan_sections_for_source(pe_data: bytes, output_dir: str) -> list:
    """Scan every PE section for embedded Python source or compressed blobs.

    Strategy A: Python source markers (b'def ', b'class ', b'import ', …)
    Strategy B: zlib magic bytes -> decompress -> check confidence

    Returns list of dicts: {section, offset, method, confidence, saved_at}
    """
    try:
        import pefile
    except ImportError:
        return []

    results = []
    sec_dir = os.path.join(output_dir, "section_scan")
    os.makedirs(sec_dir, exist_ok=True)

    try:
        pe = pefile.PE(data=pe_data)
    except Exception as e:
        log_warn(f"Section scan PE error: {e}")
        return results

    MARKERS = [
        b'def ', b'class ', b'import ', b'from ',
        b'#!/usr/bin/env python', b'# -*-',
        b'\ndef ', b'\nclass ', b'\nimport ',
    ]
    ZLIB_MAGICS = [b'\x78\x9c', b'\x78\x01', b'\x78\xda', b'\x78\x5e']

    saved_hashes = set()

    def _save(sec_name, offset, method, data, conf):
        h = zlib.crc32(data) & 0xFFFFFFFF
        if h in saved_hashes:
            return None
        saved_hashes.add(h)
        ext   = '.py' if conf > 0.25 else '.bin'
        fname = f"{re.sub(r'[^a-zA-Z0-9_]', '_', sec_name)}_0x{offset:08X}_{method}{ext}"
        out   = os.path.join(sec_dir, fname)
        with open(out, 'wb') as fh:
            fh.write(data)
        return out

    for section in pe.sections:
        sec_name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace').strip()
        raw  = section.get_data()
        size = len(raw)
        if size < 64:
            continue

        log(f"  Scanning section [{sec_name}] ({size:,} B) for source...")

        # Strategy A: source text markers
        for marker in MARKERS:
            pos = 0
            while True:
                idx = raw.find(marker, pos)
                if idx == -1:
                    break
                start = max(0, idx - 1024)
                end   = min(size, idx + 65536)
                block = raw[start:end]
                conf  = _python_source_confidence(block)
                if conf > 0.20:
                    out = _save(sec_name, start, 'marker', block, conf)
                    if out:
                        rec = {'section': sec_name, 'offset': start,
                               'method': 'marker', 'confidence': round(conf, 3),
                               'saved_at': out}
                        results.append(rec)
                        log_fire(f"  SOURCE in [{sec_name}]+0x{start:X} "
                                 f"('{marker.decode('ascii', errors='replace')}'): conf={conf:.2f}")
                pos = idx + max(len(marker), 1)

        # Strategy B: zlib compressed blobs
        for magic in ZLIB_MAGICS:
            pos      = 0
            attempts = 0
            while attempts < 200:
                idx = raw.find(magic, pos)
                if idx == -1:
                    break
                attempts += 1
                chunk = raw[idx:min(idx + 1024 * 1024, size)]
                dec   = _try_decompress(chunk)
                if dec:
                    conf = _python_source_confidence(dec)
                    if conf > 0.15:
                        out = _save(sec_name, idx, 'zlib', dec, conf)
                        if out:
                            rec = {'section': sec_name, 'offset': idx,
                                   'method': 'zlib', 'confidence': round(conf, 3),
                                   'saved_at': out}
                            results.append(rec)
                            log_fire(f"  COMPRESSED SOURCE [{sec_name}]+0x{idx:X}: "
                                     f"conf={conf:.2f} ({len(dec):,} B decompressed) -> {out}")
                pos = idx + 2

    return results


def search_constants_for_source(constants: list, module_name: str, output_dir: str) -> list:
    """Find strings/bytes in module constants that look like Python source."""
    results = []
    src_dir = os.path.join(output_dir, "source_in_constants")

    def _visit(val, depth=0):
        if depth > 8:
            return
        data = None
        if isinstance(val, str) and len(val) > 80:
            data = val.encode('utf-8', errors='replace')
        elif isinstance(val, (bytes, bytearray)) and len(val) > 80:
            data = bytes(val)

        if data is not None:
            conf = _python_source_confidence(data)
            used = data
            if conf < 0.15:
                dec = _try_decompress(data)
                if dec:
                    dc = _python_source_confidence(dec)
                    if dc > conf:
                        conf, used = dc, dec
            if conf > 0.25:
                os.makedirs(src_dir, exist_ok=True)
                safe = re.sub(r'[<>:"|?*/\\.]', '_', module_name)
                out  = os.path.join(src_dir, f"{safe}_{len(results)}.py")
                with open(out, 'wb') as fh:
                    fh.write(used)
                results.append({'module': module_name,
                                'confidence': round(conf, 3), 'saved_at': out})
                log_fire(f"  SOURCE in constants of [{module_name}]: "
                         f"conf={conf:.2f} ({len(data):,} B) -> {out}")
            return

        if isinstance(val, (list, tuple)):
            for item in val:
                _visit(item, depth + 1)
        elif isinstance(val, dict):
            for v in val.values():
                _visit(v, depth + 1)

    for c in constants:
        _visit(c)
    return results


# =============================================================================
# VLQ READER
# =============================================================================

_CURRENT_NUITKA_TARGET_PYTHON = None  # deve essere risolto dal PE, MAI dal launcher

def _ndl_resolve_target_python(pe_data=None, explicit=None):
    """Risolve la versione Python del TARGET, mai dal launcher.
    Ordine di priorità:
    1. Override esplicito (--target-python)
    2. Rilevamento dal PE (import table, .rdata)
    3. Rilevamento dal blob constants (layout probing)
    4. Fallback sicuro: None -> il chiamante DEVE gestire l'errore
    """
    global _CURRENT_NUITKA_TARGET_PYTHON
    if explicit is not None:
        _CURRENT_NUITKA_TARGET_PYTHON = explicit
        return explicit
    if _CURRENT_NUITKA_TARGET_PYTHON is not None:
        return _CURRENT_NUITKA_TARGET_PYTHON
    if pe_data:
        detected = detect_python_version_from_pe(pe_data)
        if detected:
            _CURRENT_NUITKA_TARGET_PYTHON = detected
            return detected
    # Probing del blob: prova layout da 3.14 a 2.7
    # (gestito dal chiamante che ha il blob)
    return None
# Nuitka has used two integer encodings in constants blobs:
#   * historical: tags l/q/i/I followed by a fixed little-endian uint32
#   * current:    the same tags followed by a 7-bit VLQ
# The mode is selected per module stream by parse_module_constants.
_CURRENT_NUITKA_BLOB_INT_MODE = "vlq"
_CURRENT_NUITKA_BLOB_PROFILE = "modern_vlq31"
# V100: variante layout del tag code-object — alcune versioni Nuitka
# emettono il bit opzionale QUALNAME anche per Python < 3.11 (bit0),
# spostando freevars/kwonly/posonly di un bit.  Auto-selezionato provando
# entrambi i layout sul chunk intero.
_CURRENT_CO_QUALNAME_ALL_PY = False
_NDL_SELECTED_CONSTANTS_PROFILE = None
_NDL_CONSTANTS_PROFILES = (
    "modern_vlq31", "hybrid_1_9_to_2_3", "legacy_through_1_8_6")
_Nuitka_END_OF_STREAM = object()
_Nuitka_PARSE_ERROR = object()
_Nuitka_UNSTREAMED_SLOT = object()


class _NuitkaConstantsList(list):
    """List-compatible constants pool with serialized-layout metadata.

    Historical Nuitka releases could reserve entries in ``mod_consts`` that
    were initialized outside the blob. The uint16 header is therefore the true
    slot count, while fewer values appear before the terminating ``.`` marker.
    Keeping both counts lets native slot VAs be aligned without inventing data.
    """

    def __init__(self, values=(), *, declared_count=None, int_mode=None,
                 profile=None, end_pos=None, diagnostics=None,
                 candidate_diagnostics=None):
        super().__init__(values)
        self.diagnostics = diagnostics or {}
        self.declared_count = int(declared_count if declared_count is not None else len(self))
        self.streamed_count = int(
            self.diagnostics.get('decoded_count', len(self)))
        self.int_mode = int_mode
        self.profile = profile
        self.end_pos = end_pos
        self.candidate_diagnostics = list(candidate_diagnostics or ())


def _normalize_python_version(version):
    if version is None:
        return tuple(_CURRENT_NUITKA_TARGET_PYTHON[:2])
    return _ndl_parse_target_python_version(version)


def set_nuitka_target_python(version):
    """Set the Python version used for version-dependent Nuitka blob tags."""
    global _CURRENT_NUITKA_TARGET_PYTHON
    _CURRENT_NUITKA_TARGET_PYTHON = _normalize_python_version(version)


def _target_python_hex(version=None):
    major, minor = _normalize_python_version(version)
    # Nuitka's compile-time PYTHON_VERSION is hexadecimal decimal notation:
    # 3.9 -> 0x390, 3.10 -> 0x3a0, ... 3.14 -> 0x3e0.
    if major == 2 and minor == 7:
        return 0x270
    if major == 3 and 0 <= minor <= 14:
        return 0x300 + (minor * 0x10)
    raise ValueError(f"no Nuitka PYTHON_VERSION mapping for {major}.{minor}")


def read_vlq(data, pos, *, max_bits=64):
    """Read Nuitka's variable-length unsigned integer.

    Nuitka's DataComposer encodes uint64_t values using little-endian 7-bit
    groups. Older versions of this unpacker only consumed up to four bytes,
    which misaligned chunks containing large blobs or future wider counters.
    """
    result = 0
    shift = 0
    end = len(data)
    max_bytes = max(1, (int(max_bits) + 6) // 7)

    for index in range(max_bytes):
        if pos >= end:
            raise _NuitkaDecoderAbort("truncated VLQ integer", pos)
        byte = data[pos]
        pos += 1
        payload = byte & 0x7F
        remaining_bits = int(max_bits) - shift
        if remaining_bits < 7 and payload >= (1 << remaining_bits):
            raise _NuitkaDecoderAbort("VLQ integer exceeds bit width", pos - 1)
        result |= payload << shift
        if byte < 0x80:
            if index and payload == 0:
                raise _NuitkaDecoderAbort(
                    "non-canonical overlong VLQ integer", pos - 1)
            return result, pos
        shift += 7

    raise _NuitkaDecoderAbort("unterminated/overlong VLQ integer", pos)


def _read_blob_integer(data, pos):
    """Read an integer payload using the active Nuitka blob generation.

    Older DataComposer releases wrote four-byte little-endian magnitudes after
    integer tags. Newer releases use the same VLQ codec as container lengths.
    The surrounding stream parser chooses the mode by full-stream validation.
    """
    if _CURRENT_NUITKA_BLOB_INT_MODE == "fixed32":
        if pos + 4 > len(data):
            raise _NuitkaDecoderAbort("truncated fixed32 integer", pos)
        return struct.unpack_from('<I', data, pos)[0], pos + 4
    return read_vlq(data, pos)


def _read_constant_container_count(data, pos):
    """Read a T/L/D/S/P count for the active source-backed profile."""
    if _CURRENT_NUITKA_BLOB_PROFILE == "legacy_through_1_8_6":
        if pos + 4 > len(data):
            raise _NuitkaDecoderAbort("truncated legacy container count", pos)
        value = struct.unpack_from('<i', data, pos)[0]
        if value < 0:
            raise _NuitkaDecoderAbort("negative legacy container count", pos)
        return value, pos + 4
    return read_vlq(data, pos)


def _read_profile_payload_length(data, pos, *, raw_blob=False):
    """Read a byte payload length without mixing historical grammars."""
    fixed = (_CURRENT_NUITKA_BLOB_PROFILE == "legacy_through_1_8_6"
             or (raw_blob and _CURRENT_NUITKA_BLOB_PROFILE ==
                 "hybrid_1_9_to_2_3"))
    if fixed:
        if pos + 4 > len(data):
            raise _NuitkaDecoderAbort("truncated fixed payload length", pos)
        value = struct.unpack_from('<i', data, pos)[0]
        if value < 0:
            raise _NuitkaDecoderAbort("negative fixed payload length", pos)
        return value, pos + 4
    return read_vlq(data, pos)


