# Pre-compute as a frozenset of lowercased names for O(1) lookup.
_KNOWN_LIBRARY_SET = frozenset(lib.lower() for lib in KNOWN_LIBRARY_PREFIXES)


def is_main_module(name):
    if not name: return False
    base = name.split('.')[0].lower()
    # Exact match against the known library set (no startswith — avoids
    # matching 'keyboard' against 'key' or 'mss' against 'ms').
    if base in _KNOWN_LIBRARY_SET:
        return False
    # Catch private stdlib modules: _thread, _io, _collections_abc, etc.
    # But NOT dunder names like __main__, __init__ — those could be dev code.
    if base.startswith('_') and not base.startswith('__'):
        return False
    return True


def module_matches_patterns(name, patterns):
    """Match exact module names or shell-style globs used by ``--only``.

    Older releases special-cased only ``pkg.*``.  That made documented-looking
    selectors such as ``**main**`` silently behave as exact names.  Accept the
    normal ``*``, ``?`` and character-class syntax everywhere.  A backslash
    immediately before ``_`` is also discarded because PowerShell users often
    paste Markdown-escaped names such as ``parents\\_main``.
    """
    if not patterns:
        return True
    for pat in patterns:
        pat = str(pat).replace(r'\_', '_')
        if pat == name or fnmatch.fnmatchcase(name, pat):
            return True
    return False


# Module-level tracker for the 'p' (previous) constant tag. ``None`` is itself
# a valid constant, therefore absence needs a distinct sentinel.
_NO_NUITKA_PREVIOUS = object()
_last_unpacked = _NO_NUITKA_PREVIOUS


class _NuitkaDecoderAbort(Exception):
    """A bounded-decoder candidate was rejected before unsafe expansion."""

    def __init__(self, reason, pos):
        super().__init__(reason)
        self.reason = str(reason)
        self.pos = int(pos)


class _NuitkaDecodeBudget:
    """Per-stream recursion and decoded-node budget."""

    __slots__ = ('initial_nodes', 'nodes_remaining', 'max_depth', 'max_seen_depth')

    def __init__(self, node_budget, max_depth):
        self.initial_nodes = max(0, int(node_budget))
        self.nodes_remaining = self.initial_nodes
        self.max_depth = max(0, int(max_depth))
        self.max_seen_depth = 0

    def consume_node(self, pos, depth):
        if depth > self.max_depth:
            raise _NuitkaDecoderAbort(
                f"constant nesting depth {depth} exceeds limit {self.max_depth}", pos)
        self.max_seen_depth = max(self.max_seen_depth, depth)
        if self.nodes_remaining <= 0:
            raise _NuitkaDecoderAbort(
                f"constant node budget {self.initial_nodes} exhausted", pos)
        self.nodes_remaining -= 1


def _new_nuitka_decode_budget(data, start_pos=0, *, node_budget=None, max_depth=128):
    remaining = max(0, len(data) - max(0, int(start_pos)))
    if node_budget is None:
        # Every constant consumes at least its tag byte. The absolute cap protects
        # aggressive scans of adversarial multi-megabyte ranges.
        node_budget = min(remaining, 1_000_000)
    return _NuitkaDecodeBudget(node_budget, max_depth)


def _validate_constant_sequence(data, pos, count, state, *, multiplier=1):
    """Reject impossible child counts before constructing their output list."""
    try:
        count = int(count)
        required = count * int(multiplier)
    except (TypeError, ValueError, OverflowError):
        raise _NuitkaDecoderAbort("invalid constant sequence count", pos)
    if count < 0 or required < 0:
        raise _NuitkaDecoderAbort("negative constant sequence count", pos)
    remaining_bytes = max(0, len(data) - pos)
    if required > remaining_bytes:
        raise _NuitkaDecoderAbort(
            f"constant sequence needs {required} tag bytes, only {remaining_bytes} remain", pos)
    if required > state.nodes_remaining:
        raise _NuitkaDecoderAbort(
            f"constant sequence needs {required} nodes, budget has {state.nodes_remaining}", pos)
    return count


def _unpack_constant_sequence(data, pos, count, *, _decoder_state=None, _depth=0,
                              _validated_multiplier=1):
    """Decode one C ``_unpackBlobConstants`` output array.

    Nuitka's ``p`` tag means the previous element of the *current output
    array*, not the last recursively decoded object. Resetting/restoring the
    tracker at every tuple/list/dict-side/special-value sequence matches the C
    helper and prevents nested containers from leaking previous-value state.
    """
    global _last_unpacked
    state = _decoder_state or _new_nuitka_decode_budget(data, pos)
    count = _validate_constant_sequence(
        data, pos, count, state, multiplier=_validated_multiplier)
    parent_previous = _last_unpacked
    _last_unpacked = _NO_NUITKA_PREVIOUS
    out = []
    try:
        for _ in range(count):
            item, pos = unpack_single_constant(
                data, pos, _decoder_state=state, _depth=_depth)
            if item is _Nuitka_END_OF_STREAM:
                raise _NuitkaDecoderAbort(
                    "premature constant-stream terminator", max(0, pos - 1))
            out.append(item)
    finally:
        _last_unpacked = parent_previous
    return out, pos


def unpack_single_constant(data, pos, *, _decoder_state=None, _depth=0):
    """Unpack a single value from the Nuitka constants blob.

    Handles all known tags from HelpersConstantsBlob.c and DataComposer.py.
    Synchronized with Nuitka Commercial 2025 source.
    """
    global _last_unpacked
    state = _decoder_state or _new_nuitka_decode_budget(data, pos)
    state.consume_node(pos, _depth)

    if pos >= len(data):
        raise _NuitkaDecoderAbort("truncated constant tag", pos)

    marker = data[pos]
    ch = chr(marker) if 32 <= marker < 127 else None
    pos += 1

    # === 'p' - previous ref: repeat last unpacked value (NO VLQ read) ===
    if ch == 'p':
        if _last_unpacked is _NO_NUITKA_PREVIOUS:
            raise _NuitkaDecoderAbort(
                "previous-value tag has no previous constant", pos - 1)
        return _last_unpacked, pos

    if ch == '.':
        return _Nuitka_END_OF_STREAM, pos

    result = _unpack_constant_inner(
        data, pos, ch, marker, _decoder_state=state, _depth=_depth)
    if result is not None:
        val, pos = result
        if val is _Nuitka_PARSE_ERROR:
            raise _NuitkaDecoderAbort(
                "unrecognized or truncated constant", max(0, pos - 1))
        _last_unpacked = val
        return val, pos

    _last_unpacked = _NO_NUITKA_PREVIOUS
    raise _NuitkaDecoderAbort(
        "unrecognized constant tag", max(0, pos - 1))


class _NuitkaBuiltinName(str):
    """Builtin loaded by Nuitka's constants table (distinct from a string)."""


class _NuitkaExceptionName(str):
    """Exception type loaded by Nuitka's constants table."""


def _unpack_constant_inner(data, pos, ch, marker, *, _decoder_state=None, _depth=0):
    """Internal dispatcher for all constant types except 'p'."""
    state = _decoder_state or _new_nuitka_decode_budget(data, pos)

    # --- Strings ---
    if ch in ('a', 'u'):  # null-terminated string (attribute or unicode)
        end = data.find(b'\x00', pos)
        if end == -1:
            raise _NuitkaDecoderAbort("unterminated unicode constant", pos)
        if ch == 'a' and _target_python_hex() < 0x300:
            return data[pos:end], end + 1
        try:
            value = data[pos:end].decode('utf-8', errors='surrogatepass')
        except UnicodeDecodeError:
            raise _NuitkaDecoderAbort("invalid UTF-8 unicode constant", pos)
        return value, end + 1

    elif ch == 'w':  # single-char unicode
        if pos < len(data):
            try:
                return data[pos:pos + 1].decode(
                    'utf-8', errors='surrogatepass'), pos + 1
            except UnicodeDecodeError:
                raise _NuitkaDecoderAbort(
                    "invalid single-byte unicode constant", pos)
        raise _NuitkaDecoderAbort("truncated unicode constant", pos)

    elif ch == 'v':  # length-prefixed unicode (contains null bytes)
        size, pos = _read_profile_payload_length(data, pos)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated unicode payload", pos)
        try:
            value = data[pos:pos + size].decode(
                'utf-8', errors='surrogatepass')
        except UnicodeDecodeError:
            raise _NuitkaDecoderAbort("invalid UTF-8 unicode payload", pos)
        return value, pos + size

    elif ch == 's':  # empty string
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "empty-string tag is absent from the selected old profile",
                pos - 1)
        return "", pos

    # --- Bytes ---
    elif ch == 'c':  # Python3: zero-terminated bytes / Python2: str
        end = data.find(b'\x00', pos)
        if end == -1:
            raise _NuitkaDecoderAbort("unterminated bytes constant", pos)
        return data[pos:end], end + 1

    elif ch == 'b':  # bytes with VLQ length (contains null bytes)
        size, pos = _read_profile_payload_length(data, pos)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated bytes payload", pos)
        return data[pos:pos + size], pos + size

    elif ch == 'B':  # bytearray
        size, pos = _read_profile_payload_length(data, pos)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated bytearray payload", pos)
        return bytearray(data[pos:pos + size]), pos + size

    elif ch == 'd':  # single byte (Python3: bytes len 1)
        if pos < len(data): return bytes([data[pos]]), pos + 1
        raise _NuitkaDecoderAbort("truncated single-byte constant", pos)

    # --- Singletons ---
    elif ch == 'n': return None, pos
    elif ch == 't': return True, pos
    elif ch == 'F': return False, pos

    # --- Integers ---
    elif ch == 'l':
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            # Historical DataComposer: C ``long`` payload, signed 32-bit on
            # Windows (negative values keep the same tag, two's complement).
            if pos + 4 > len(data):
                raise _NuitkaDecoderAbort("truncated fixed32 long", pos)
            return struct.unpack_from('<i', data, pos)[0], pos + 4
        value, pos = read_vlq(data, pos)       # current: positive magnitude
        if value >= 0x7FFFFFFF:
            raise _NuitkaDecoderAbort(
                "non-canonical modern long must use big-integer tag", pos)
        return value, pos
    elif ch == 'q':
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            # Historical ``long long`` payload (despite the mode name): fixed
            # signed 64-bit. Values such as 0x7fffffff/0xffffffff commonly use
            # this tag and are positive, so negating them was doubly wrong.
            if pos + 8 > len(data):
                raise _NuitkaDecoderAbort("truncated fixed64 long", pos)
            value = struct.unpack_from('<q', data, pos)[0]
            return value, pos + 8
        value, pos = read_vlq(data, pos)       # current: negative magnitude
        if value == 0:
            raise _NuitkaDecoderAbort(
                "non-canonical negative zero", pos)
        if value >= 0x7FFFFFFF:
            raise _NuitkaDecoderAbort(
                "non-canonical modern long must use big-integer tag", pos)
        return -value, pos

    elif ch == 'I':
        if _target_python_hex() >= 0x300:
            raise _NuitkaDecoderAbort(
                "integer-I tag is Python-2-only", pos - 1)
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "integer-I tag is absent from the selected hybrid profile",
                pos - 1)
        value, pos = read_vlq(data, pos)
        if value == 0:
            raise _NuitkaDecoderAbort(
                "non-canonical negative zero", pos)
        return -value, pos
    elif ch == 'i':
        if _target_python_hex() >= 0x300:
            raise _NuitkaDecoderAbort(
                "integer-i tag is Python-2-only", pos - 1)
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            if pos + 4 > len(data):
                raise _NuitkaDecoderAbort("truncated fixed32 integer", pos)
            return struct.unpack_from('<i', data, pos)[0], pos + 4
        value, pos = read_vlq(data, pos)
        return value, pos

    elif (ch == 'g'
          and _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31"):
        if pos >= len(data) or data[pos:pos + 1] not in (b'+', b'-'):
            raise _NuitkaDecoderAbort(
                "invalid hybrid big-integer sign", pos)
        negative = data[pos:pos + 1] == b'-'
        pos += 1
        if pos + 4 > len(data):
            raise _NuitkaDecoderAbort(
                "truncated hybrid big-integer limb count", pos)
        num_parts = struct.unpack_from('<i', data, pos)[0]
        pos += 4
        try:
            max_int_bits = max(64, int(os.environ.get(
                'NDL_MAX_INT_BITS', str(8 * 1024 * 1024))))
        except Exception:
            max_int_bits = 8 * 1024 * 1024
        max_limbs = max_int_bits // 64
        if (num_parts < 1 or num_parts > max_limbs
                or num_parts > state.nodes_remaining
                or num_parts > (len(data) - pos) // 8):
            raise _NuitkaDecoderAbort(
                f"hybrid big-integer limb count {num_parts} is invalid", pos)
        state.nodes_remaining -= num_parts
        value = 0
        first_part = None
        for _ in range(num_parts):
            part = struct.unpack_from('<Q', data, pos)[0]
            pos += 8
            if first_part is None:
                first_part = part
            value = (value << 64) | part
        if not first_part:
            raise _NuitkaDecoderAbort(
                "non-canonical hybrid big-integer leading limb", pos)
        if ((not negative and value <= 0x7FFFFFFFFFFFFFFF)
                or (negative and value <= 0x8000000000000000)):
            raise _NuitkaDecoderAbort(
                "non-canonical hybrid big integer fits signed 64-bit", pos)
        return (-value if negative else value), pos

    elif (ch in ('g', 'G')
          and _CURRENT_NUITKA_BLOB_PROFILE == "modern_vlq31"):
        # Modern Nuitka uses g/G for positive/negative base-2^31 limbs.
        is_negative = (ch == 'G')
        num_parts, pos = _read_blob_integer(data, pos)
        try:
            max_int_bits = max(62, int(os.environ.get(
                'NDL_MAX_INT_BITS', str(8 * 1024 * 1024))))
        except Exception:
            max_int_bits = 8 * 1024 * 1024
        max_limbs = max_int_bits // 31
        # Modern DataComposer uses g/G at the exact 2**31-1 boundary too.
        # Charge every limb to the stream budget before doing bigint work.
        if (num_parts < 1 or num_parts > len(data) - pos
                or num_parts > max_limbs
                or num_parts > state.nodes_remaining):
            raise _NuitkaDecoderAbort(
                f"big-integer limb count {num_parts} exceeds remaining payload", pos)
        state.nodes_remaining -= num_parts
        parts = []
        for _ in range(num_parts):
            part, pos = _read_blob_integer(data, pos)
            if part > 0x7FFFFFFF:
                raise _NuitkaDecoderAbort(
                    "big-integer limb exceeds 31 bits", pos)
            parts.append(part)
        if not parts or parts[0] == 0:
            raise _NuitkaDecoderAbort(
                "non-canonical big-integer leading limb", pos)

        def _combine_limbs(lo, hi):
            if hi - lo == 1:
                return parts[lo]
            mid = (lo + hi) // 2
            return (_combine_limbs(lo, mid) << (31 * (hi - mid))) | \
                _combine_limbs(mid, hi)

        result = _combine_limbs(0, len(parts))
        if result < 0x7FFFFFFF:
            raise _NuitkaDecoderAbort(
                "non-canonical modern big integer fits l/q tag", pos)
        return (-result if is_negative else result), pos

    # --- Floats ---
    elif ch == 'f':  # double float (8 bytes IEEE 754)
        if pos + 8 <= len(data):
            return struct.unpack('<d', data[pos:pos + 8])[0], pos + 8
        raise _NuitkaDecoderAbort("truncated float constant", pos)

    elif ch == 'Z':  # special float: +0.0, -0.0, +NaN, -NaN, +Inf, -Inf
        if pos < len(data):
            v = data[pos]
            pos += 1
            if v == 0: return 0.0, pos
            elif v == 1: return -0.0, pos
            elif v == 2: return float('nan'), pos
            elif v == 3: return copysign(float('nan'), -1.0), pos
            elif v == 4: return float('inf'), pos
            elif v == 5: return float('-inf'), pos
            else:
                raise _NuitkaDecoderAbort(
                    "unknown special-float selector", pos - 1)
        raise _NuitkaDecoderAbort("truncated special-float constant", pos)

    # --- Complex ---
    elif ch == 'j':  # complex (two 8-byte doubles)
        if pos + 16 <= len(data):
            real = struct.unpack('<d', data[pos:pos + 8])[0]
            imag = struct.unpack('<d', data[pos + 8:pos + 16])[0]
            return complex(real, imag), pos + 16
        raise _NuitkaDecoderAbort("truncated complex constant", pos)

    elif ch == 'J':  # complex via float sub-constants (for special values)
        parts, pos = _unpack_constant_sequence(
            data, pos, 2, _decoder_state=state, _depth=_depth + 1)
        try:
            return complex(parts[0], parts[1]), pos
        except (TypeError, ValueError):
            raise _NuitkaDecoderAbort("invalid complex components", pos)

    # --- Containers ---
    elif ch == 'T':  # tuple
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        return tuple(items), pos

    elif ch == 'L':  # list
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        return items, pos

    elif ch == 'D':  # dict — Nuitka writes ALL keys first, then ALL values
        count, pos = _read_constant_container_count(data, pos)
        # Validate both key and value arrays before allocating either one.
        _validate_constant_sequence(data, pos, count, state, multiplier=2)
        keys, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        values, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        d = {}
        for k, v in zip(keys, values):
            try:
                if k in d:
                    raise _NuitkaDecoderAbort(
                        "duplicate dictionary key in constants stream", pos)
                d[k] = v
            except TypeError as exc:
                raise _NuitkaDecoderAbort(
                    f"unhashable dictionary key: {exc}", pos)
        return d, pos

    elif ch == 'S':  # set
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        try:
            result = set(items)
        except TypeError as exc:
            raise _NuitkaDecoderAbort(
                f"unhashable set member: {exc}", pos)
        if len(result) != count:
            raise _NuitkaDecoderAbort(
                "duplicate set member in constants stream", pos)
        return result, pos

    elif ch == 'P':  # frozenset
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        try:
            result = frozenset(items)
        except TypeError as exc:
            raise _NuitkaDecoderAbort(
                f"unhashable frozenset member: {exc}", pos)
        if len(result) != count:
            raise _NuitkaDecoderAbort(
                "duplicate frozenset member in constants stream", pos)
        return result, pos

    # --- Raw blob (bytecode pointer) ---
    elif ch == 'X':
        size, pos = _read_profile_payload_length(data, pos, raw_blob=True)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated raw-blob payload", pos)
        blob = data[pos:pos + size]
        return blob, pos + size

    # --- Special types ---
    elif ch == 'M':  # anon builtin / type-table value
        if pos >= len(data):
            raise _NuitkaDecoderAbort("truncated anonymous-builtin index", pos)
        py_hex = _target_python_hex()
        names = [
            'NoneType', 'ellipsis', 'NotImplementedType', 'function',
            'generator', 'builtin_function_or_method', 'code', 'module',
        ]
        if py_hex < 0x300:
            names.extend(('file', 'classobj', 'instance', 'instancemethod'))
        if py_hex >= 0x270:
            names.append('version_info')
        if py_hex >= 0x390:
            names.append('GenericAlias')
        if py_hex >= 0x3A0:
            names.append('Union' if py_hex >= 0x3E0 else 'UnionType')
        index = data[pos]
        if index >= len(names):
            raise _NuitkaDecoderAbort(
                f"invalid anonymous-builtin index {index} for target Python",
                pos)
        return ('_nuitka_builtin_anon_type', names[index]), pos + 1

    elif ch == 'Q':  # special singleton/table value
        if pos >= len(data):
            raise _NuitkaDecoderAbort("truncated special-value index", pos)
        special_values = {
            0: Ellipsis,
            1: NotImplemented,
            2: ('_nuitka_special', 'Py_SysVersionInfo'),
        }
        index = data[pos]
        if index not in special_values:
            raise _NuitkaDecoderAbort(
                f"invalid special-value index {index}", pos)
        return special_values[index], pos + 1

    elif ch in ('O', 'E'):  # builtin/exception name (null-terminated)
        end = data.find(b'\x00', pos)
        if end == -1:
            raise _NuitkaDecoderAbort(
                "unterminated builtin/exception name", pos)
        try:
            value = data[pos:end].decode('utf-8', errors='strict')
        except UnicodeDecodeError as exc:
            raise _NuitkaDecoderAbort(
                f"invalid UTF-8 builtin/exception name: {exc}", pos)
        marker_type = _NuitkaBuiltinName if ch == 'O' else _NuitkaExceptionName
        return marker_type(value), end + 1

    elif ch == ':':  # slice(start, stop, step)
        items, pos = _unpack_constant_sequence(
            data, pos, 3, _decoder_state=state, _depth=_depth + 1)
        return ('slice', items[0], items[1], items[2]), pos

    elif ch == ';':  # range/xrange(start, stop, step)
        if (_CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31"
                and _target_python_hex() < 0x300):
            if pos + 12 > len(data):
                raise _NuitkaDecoderAbort(
                    "truncated old-profile xrange payload", pos)
            items = struct.unpack_from('<iii', data, pos)
            pos += 12
        else:
            items, pos = _unpack_constant_sequence(
                data, pos, 3, _decoder_state=state, _depth=_depth + 1)
        return ('range', items[0], items[1], items[2]), pos

    elif (ch == 'G'
          and _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31"):
        if _target_python_hex() < 0x390:
            raise _NuitkaDecoderAbort(
                "old-profile GenericAlias tag requires Python 3.9+", pos - 1)
        parts, pos = _unpack_constant_sequence(
            data, pos, 2, _decoder_state=state, _depth=_depth + 1)
        return ('GenericAlias', parts[0], parts[1]), pos

    elif ch == 'A':  # GenericAlias (Python 3.9+) — 2 sub-constants
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "GenericAlias-A tag is absent from old profiles", pos - 1)
        if _target_python_hex() < 0x390:
            raise _NuitkaDecoderAbort(
                "GenericAlias tag requires Python 3.9+", pos - 1)
        parts, pos = _unpack_constant_sequence(
            data, pos, 2, _decoder_state=state, _depth=_depth + 1)
        return ('GenericAlias', parts[0], parts[1]), pos

    elif ch == 'H':  # UnionType (Python 3.10+) — 1 sub-constant
        if _target_python_hex() < 0x3A0:
            raise _NuitkaDecoderAbort(
                "UnionType tag requires Python 3.10+", pos - 1)
        parts, pos = _unpack_constant_sequence(
            data, pos, 1, _decoder_state=state, _depth=_depth + 1)
        return ('UnionType', parts[0]), pos

    elif ch == 'C':  # CodeObject metadata
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "code-object tag is absent from old profiles", pos - 1)
        co_info, pos = _parse_code_object_tag(
            data, pos, _decoder_state=state, _depth=_depth)
        return co_info, pos

    elif ch == '.':  # end-of-stream marker
        return _Nuitka_END_OF_STREAM, pos

    else:
        raise _NuitkaDecoderAbort(
            f"unknown constant tag 0x{marker:02x}", pos - 1)


def _parse_code_object_tag(data, pos, python_version=None, *, _decoder_state=None,
                           _depth=0):
    """Parse the 'C' tag (CodeObject skeleton) and return a dict with the info.

    Synchronized with DataComposer.py _writeConstantValueCodeObject() and
    HelpersConstantsBlob.c _unpackBlobConstant() case 'C'.

    Flag bit layout (dynamic, version-dependent):
      [qualname] [free_vars] [kw_only] [pos_only] [gen_kind:2bits]
      [CO_OPTIMIZED] [CO_NEWLOCALS] [CO_VARARGS] [CO_VARKEYWORDS]
      [future_spec bits...]
    """
    global _last_unpacked
    parent_previous = _last_unpacked
    _last_unpacked = _NO_NUITKA_PREVIOUS
    try:
        py_hex = _target_python_hex(python_version)
        flags, pos = _read_blob_integer(data, pos)
        flag_base = 1

        # Name is mandatory
        func_name, pos = unpack_single_constant(
            data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
        if not isinstance(func_name, str):
            raise _NuitkaDecoderAbort(
                "code-object name is not a string", pos)

        # Line number is mandatory (encoded as line-1)
        line_number, pos = _read_blob_integer(data, pos)
        line_number += 1

        # Arg names (tuple) is mandatory
        arg_names, pos = unpack_single_constant(
            data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
        if not isinstance(arg_names, tuple):
            raise _NuitkaDecoderAbort(
                "code-object varnames are not a tuple", pos)

        # Arg count is mandatory
        arg_count, pos = _read_blob_integer(data, pos)
        if arg_count > len(arg_names):
            raise _NuitkaDecoderAbort(
                "code-object argument count exceeds varnames", pos)

        # qualname (Python 3.11+, optional flag — o qualunque Python con
        # la variante _CURRENT_CO_QUALNAME_ALL_PY attiva)
        qualname = func_name
        if py_hex >= 0x3B0 or _CURRENT_CO_QUALNAME_ALL_PY:
            if flags & flag_base:
                qualname_parent, pos = unpack_single_constant(
                    data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
                if not isinstance(qualname_parent, str):
                    raise _NuitkaDecoderAbort(
                        "invalid code-object qualname prefix", pos)
                qualname = qualname_parent + "." + func_name
            flag_base <<= 1

        # free_vars (optional)
        free_vars = ()
        if flags & flag_base:
            free_vars, pos = unpack_single_constant(
                data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
            if not isinstance(free_vars, tuple):
                raise _NuitkaDecoderAbort(
                    "code-object freevars are not a tuple", pos)
        flag_base <<= 1

        # kw_only_count (Python 3.0+, optional)
        kw_only = 0
        if py_hex >= 0x300:
            if flags & flag_base:
                kw_only, pos = _read_blob_integer(data, pos)
                kw_only += 1
            flag_base <<= 1

        # pos_only_count (Python 3.8+, optional)
        pos_only = 0
        if py_hex >= 0x380:
            if flags & flag_base:
                pos_only, pos = _read_blob_integer(data, pos)
                pos_only += 1
            flag_base <<= 1
        if pos_only > arg_count or arg_count + kw_only > len(arg_names):
            raise _NuitkaDecoderAbort(
                "code-object parameter counts exceed varnames", pos)

        # Generator kind: 2 bits
        co_flags = 0
        gen_bits = (flags >> (flag_base.bit_length() - 1)) & 3
        if py_hex >= 0x360 and gen_bits == 3:
            co_flags |= 0x200    # CO_ASYNC_GENERATOR
        elif py_hex >= 0x350 and gen_bits == 2:
            co_flags |= 0x80     # CO_COROUTINE
        elif gen_bits == 1:
            co_flags |= 0x20     # CO_GENERATOR
        elif gen_bits:
            raise _NuitkaDecoderAbort(
                "generator-kind bits are invalid for target Python", pos)
        flag_base <<= 2

        # CO_OPTIMIZED
        if flags & flag_base:
            co_flags |= 0x01
        flag_base <<= 1

        # CO_NEWLOCALS
        if flags & flag_base:
            co_flags |= 0x02
        flag_base <<= 1

        # CO_VARARGS
        if flags & flag_base:
            co_flags |= 0x04
        flag_base <<= 1

        # CO_VARKEYWORDS
        if flags & flag_base:
            co_flags |= 0x08
        flag_base <<= 1

        # Remaining bits are future_spec flags — we consume them
        # to keep position correct but don't need them for extraction.
        # CO_FUTURE_DIVISION (Py2), CO_FUTURE_UNICODE_LITERALS,
        # CO_FUTURE_PRINT_FUNCTION (Py2), CO_FUTURE_ABSOLUTE_IMPORT (Py2),
        # CO_FUTURE_GENERATOR_STOP (3.5-3.6), CO_FUTURE_ANNOTATIONS (3.7+),
        # CO_FUTURE_BARRY_AS_BDFL (3.0+)
        # These are bit flags but no additional data is read.

        # FutureSpec.encode() stores a compact, version-dependent bitset above
        # the basic flags. Translate it back to CPython CO_FUTURE_* values.
        future_encoded = flags // flag_base
        future_bit = 1
        if py_hex < 0x300:
            if future_encoded & future_bit:
                co_flags |= 0x20000   # CO_FUTURE_DIVISION
            future_bit <<= 1
        if future_encoded & future_bit:
            co_flags |= 0x200000      # CO_FUTURE_UNICODE_LITERALS
        future_bit <<= 1
        if py_hex < 0x300:
            if future_encoded & future_bit:
                co_flags |= 0x100000  # CO_FUTURE_PRINT_FUNCTION
            future_bit <<= 1
            if future_encoded & future_bit:
                co_flags |= 0x40000   # CO_FUTURE_ABSOLUTE_IMPORT
            future_bit <<= 1
        if 0x350 <= py_hex < 0x370:
            if future_encoded & future_bit:
                co_flags |= 0x800000  # CO_FUTURE_GENERATOR_STOP
            future_bit <<= 1
        if py_hex >= 0x370:
            if future_encoded & future_bit:
                co_flags |= 0x1000000  # CO_FUTURE_ANNOTATIONS
            future_bit <<= 1
        if py_hex >= 0x300 and future_encoded & future_bit:
            co_flags |= 0x400000       # CO_FUTURE_BARRY_AS_BDFL
        if py_hex >= 0x300:
            future_bit <<= 1
        # V100: le Nuitka recenti aggiungono nuovi bit FutureSpec (nessun
        # dato extra viene letto per i future flag).  I bit sconosciuti si
        # consumano senza abortire: prima l'abort uccideva l'intero chunk
        # del modulo alla prima costante code-object (1 sola costante
        # decodificata per modulo su interi build).
        # future_encoded >= future_bit → bit future extra, ignorati.

        return {
            '_type': 'CodeObject',
            'name': func_name,
            'qualname': qualname,
            'line': line_number,
            'args': list(arg_names),
            'argcount': arg_count,
            'kwonly': kw_only,
            'posonly': pos_only,
            'freevars': list(free_vars),
            'flags': co_flags,
        }, pos
    except _NuitkaDecoderAbort:
        raise
    except Exception as exc:
        raise _NuitkaDecoderAbort(
            f"invalid code-object metadata: {type(exc).__name__}: {exc}", pos)
    finally:
        _last_unpacked = parent_previous


# =============================================================================
# BLOB PARSER - Named Chunks
# =============================================================================


def _is_plausible_blob_module_name(name: str) -> bool:
    """Validate Nuitka DataComposer chunk names without product assumptions."""
    if name == "":
        return True
    if name in (".bytecode", ".files", ".bytecode_data"):
        return True
    if len(name) > 4096:
        return False
    if any(ord(c) < 32 or ord(c) == 127 for c in name):
        return False
    # Generated preload/postload names and plugin chunks can contain dashes,
    # plus signs, paths, or a leading dot. Reject binary noise, not valid names.
    return all(c.isalnum() or c in "._-+/\\:" for c in name)


def _blob_module_name_score(name: str) -> int:
    """Rank candidate plain/mapping2 chunk-name decodings."""
    if not _is_plausible_blob_module_name(name):
        return -10_000
    if name in (".bytecode", ".files", ".bytecode_data"):
        return 10_000
    if name == "":
        return 9_000

    score = 100
    if len(name) <= 512:
        score += 20
    parts = name.lstrip('.').split('.')
    if parts and all(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*'
                                  r'(?:-(?:preLoad|postLoad))?', p or '')
                     for p in parts):
        score += 300
    if '.' in name:
        score += 80
    if name.startswith('__') and name.endswith('__'):
        score += 40
    if any(ord(c) > 127 for c in name):
        score -= 80
    return score


def _decode_blob_module_name(raw_name: bytes,
                             commercial_bypass: CommercialBypass = None) -> str:
    """Decode a DataComposer name under an explicit layout contract."""
    if commercial_bypass is not None:
        # The protected marker is authoritative. Encoded one-byte names can
        # themselves be identifiers (encoded ``e`` is raw ``i``), therefore
        # ranking the raw and mapping2 spellings cannot disambiguate them.
        decoded = commercial_bypass.decode_module_name(raw_name)
        if not _is_plausible_blob_module_name(decoded):
            raise ValueError("invalid mapping2 module name")
        return decoded

    try:
        plain = raw_name.decode('utf-8', errors='strict')
    except UnicodeDecodeError as exc:
        raise ValueError(f"invalid UTF-8 plaintext module name: {exc}")
    if not _is_plausible_blob_module_name(plain):
        raise ValueError("invalid plaintext module name")
    return plain


def parse_blob_modules(blob_data: bytes,
                       commercial_bypass: CommercialBypass = None,
                       *,
                       strict: bool = False,
                       diagnostics: dict = None):
    """Parse a framed Nuitka DataComposer blob into ``(name, data)`` chunks.

    ``strict`` rejects CRC/size/name inconsistencies.  In normal best-effort
    mode parsing stops at the first invalid trailing record but records the
    reason in ``diagnostics`` when a dictionary is supplied.
    """
    diag = diagnostics if diagnostics is not None else {}
    diag.clear()
    diag.update({
        'ok': False, 'crc_ok': False, 'declared_size': 0,
        'available_size': max(0, len(blob_data or b'') - 8),
        'parsed_chunks': 0, 'consumed_payload': 0,
        'trailing_bytes': 0, 'stop_reason': None,
    })

    if not blob_data or len(blob_data) < 8:
        diag['stop_reason'] = 'blob_too_small'
        return []

    crc_stored, size_stored = struct.unpack_from('<II', blob_data, 0)
    diag['declared_size'] = size_stored
    log(f"CRC32: 0x{crc_stored:08X}, Declared size: {size_stored:,} bytes")

    available = len(blob_data) - 8
    if size_stored > available:
        diag['stop_reason'] = 'declared_size_exceeds_available'
        log_warn(
            f"Blob is truncated: declared {size_stored:,} payload bytes, "
            f"only {available:,} available")
        if strict:
            return []
        data_end = len(blob_data)
    else:
        data_end = 8 + size_stored
        if strict and size_stored != available:
            diag['stop_reason'] = 'declared_size_does_not_match_blob'
            diag['trailing_bytes'] = available - size_stored
            return []

    actual_crc = zlib.crc32(blob_data[8:data_end]) & 0xFFFFFFFF
    diag['crc_ok'] = (size_stored <= available and actual_crc == crc_stored)
    if diag['crc_ok']:
        log_ok("CRC32 verified OK!")
    else:
        log_warn(
            f"CRC32 mismatch: expected 0x{crc_stored:08X}, "
            f"computed 0x{actual_crc:08X}")
        if strict:
            diag['stop_reason'] = 'crc_mismatch'
            return []

    data = memoryview(blob_data)[8:data_end]
    selected_name_decoder = commercial_bypass
    diag['name_encoding'] = 'plain'

    # DataHidingPlugin may encode loader lookup strings without encoding the
    # names stored inside the DataComposer blob (Commercial 4.0.6 Panel does
    # exactly that). Select one name mode for the entire table; never mix
    # per-name guesses, which is ambiguous for one-byte identifiers.
    if commercial_bypass is not None:
        raw_names = []
        probe = 0
        probe_ok = True
        while probe < len(data):
            name_rel = bytes(data[probe:min(probe + 4097, len(data))]).find(
                b'\x00')
            if name_rel < 0:
                probe_ok = False
                break
            name_end = probe + name_rel
            size_pos = name_end + 1
            if size_pos + 4 > len(data):
                probe_ok = False
                break
            chunk_size = struct.unpack_from('<I', data, size_pos)[0]
            chunk_end = size_pos + 4 + chunk_size
            if chunk_end > len(data):
                probe_ok = False
                break
            raw_names.append(bytes(data[probe:name_end]))
            probe = chunk_end
        probe_ok = probe_ok and probe == len(data) and bool(raw_names)

        def _decode_name_table(decoder):
            if not probe_ok:
                return None
            decoded_names = []
            try:
                for raw_name in raw_names:
                    value = (decoder.decode_module_name(raw_name)
                             if decoder is not None else
                             raw_name.decode('utf-8', errors='strict'))
                    if not _is_plausible_blob_module_name(value):
                        return None
                    decoded_names.append(value)
            except Exception:
                return None
            if len(set(decoded_names)) != len(decoded_names):
                return None
            score = sum(_blob_module_name_score(x) for x in decoded_names)
            score += 100000 * sum(
                x in ('', '.bytecode', '.files', '.bytecode_data')
                for x in decoded_names)
            return decoded_names, score

        plain_table = _decode_name_table(None)
        mapped_table = _decode_name_table(commercial_bypass)
        if plain_table is not None and mapped_table is None:
            selected_name_decoder = None
        elif mapped_table is not None and plain_table is None:
            selected_name_decoder = commercial_bypass
            diag['name_encoding'] = 'mapping2'
        elif plain_table is not None and mapped_table is not None:
            if plain_table[0] == mapped_table[0]:
                selected_name_decoder = None
            else:
                diag['stop_reason'] = 'ambiguous_chunk_name_encoding'
                if strict:
                    return []
                selected_name_decoder = None
                diag['name_encoding'] = 'ambiguous_plain_fallback'
        else:
            diag['stop_reason'] = 'invalid_chunk_name_encoding'
            if strict:
                return []

    offset = 0
    modules = []
    seen_names = set()

    while offset < len(data):
        # Exact carvers should leave no padding, but tolerate all-zero alignment
        # in externally supplied blobs without inventing empty chunks.
        remaining = data[offset:]
        if remaining and not any(remaining):
            diag['stop_reason'] = 'zero_padding'
            break
        if len(data) - offset < 5:
            diag['stop_reason'] = 'truncated_chunk_header'
            break

        raw_view = data[offset:min(offset + 4097, len(data))]
        name_rel = bytes(raw_view).find(b'\x00')
        if name_rel < 0:
            diag['stop_reason'] = 'unterminated_chunk_name'
            break
        name_end = offset + name_rel
        raw_name = bytes(data[offset:name_end])
        try:
            module_name = _decode_blob_module_name(
                raw_name, selected_name_decoder)
        except Exception:
            diag['stop_reason'] = 'invalid_chunk_name_encoding'
            break
        if not _is_plausible_blob_module_name(module_name):
            diag['stop_reason'] = 'invalid_chunk_name'
            break
        if module_name in seen_names:
            diag['stop_reason'] = 'duplicate_chunk_name'
            break
        seen_names.add(module_name)

        size_pos = name_end + 1
        if size_pos + 4 > len(data):
            diag['stop_reason'] = 'truncated_chunk_size'
            break
        chunk_size = struct.unpack_from('<I', data, size_pos)[0]
        chunk_pos = size_pos + 4
        chunk_end = chunk_pos + chunk_size
        if chunk_size > 100 * 1024 * 1024:
            diag['stop_reason'] = 'chunk_too_large'
            break
        if chunk_end > len(data):
            diag['stop_reason'] = 'truncated_chunk_data'
            break

        modules.append((module_name, bytes(data[chunk_pos:chunk_end])))
        offset = chunk_end

    diag['parsed_chunks'] = len(modules)
    diag['consumed_payload'] = offset
    diag['trailing_bytes'] = max(0, len(data) - offset)
    fully_consumed = (offset == len(data))
    diag['ok'] = bool(modules) and (
        (diag['crc_ok'] and fully_consumed) if strict else True)
    if diag['stop_reason'] is None:
        diag['stop_reason'] = 'eof'
    if strict and not diag['ok']:
        return []
    return modules


# =============================================================================
# SHARED BLOB DECRYPTION (extracted from --list-modules logic)
# =============================================================================

def _decrypt_blob_if_encrypted(target_path: str, blob_data: bytes,
                               pe_data: bytes = None) -> bytes:
    """
    Decrypt the Nuitka constants blob if it's encrypted (Commercial/Protected).
    Returns a CRC-verified normalized blob.  A protected blob that cannot be
    verified returns ``None``; encrypted bytes are never sent to plaintext
    parsers.  ``last_state`` records ``plaintext``, ``decrypted`` or
    ``decrypt_failed`` for reporting.
    """
    import pefile
    bypass = CommercialBypass()

    _decrypt_blob_if_encrypted.last_state = 'missing'
    _decrypt_blob_if_encrypted.last_error = None
    if not blob_data:
        return blob_data

    if not bypass.is_blob_encrypted(blob_data):
        _diag = {}
        _valid_plaintext = False
        # Data-hiding can leave framing/CRC plaintext while module names still
        # use mapping2.  Try the ordinary grammar first, then name decoding;
        # both paths retain the same strict size/CRC/full-consumption checks.
        for _name_decoder in (None, bypass):
            _try_diag = {}
            if parse_blob_modules(
                    blob_data, _name_decoder, strict=True,
                    diagnostics=_try_diag):
                _diag = _try_diag
                _valid_plaintext = True
                break
            _diag = _try_diag
        if not _valid_plaintext:
            _decrypt_blob_if_encrypted.last_state = 'invalid_plaintext'
            _decrypt_blob_if_encrypted.last_error = _diag.get('stop_reason')
            return None
        _decrypt_blob_if_encrypted.last_state = 'plaintext'
        return blob_data

    log_fire("Blob is encrypted — attempting commercial metadata normalization...")

    # read PE data
    try:
        if pe_data is None:
            with open(target_path, 'rb') as f:
                pe_data = f.read()
    except Exception as e:
        log_err(f"Cannot read PE data: {e}")
        _decrypt_blob_if_encrypted.last_state = 'decrypt_failed'
        _decrypt_blob_if_encrypted.last_error = 'target_read_failed'
        return None

    try:
        pe = pefile.PE(data=pe_data)
    except Exception as e:
        log_err(f"PE parse error: {e}")
        _decrypt_blob_if_encrypted.last_state = 'decrypt_failed'
        _decrypt_blob_if_encrypted.last_error = 'target_pe_parse_failed'
        return None

    # 1) Fast path: search .rdata only for _mapping[], then derive d0-d7 from blob
    log("  Scanning .rdata for mapping table...")
    mapping_candidates = bypass._find_all_mapping_candidates(pe, rdata_only=True)
    if not mapping_candidates:
        log("  No candidates in .rdata, scanning all sections...")
        mapping_candidates = bypass._find_all_mapping_candidates(pe)

    decrypted_blob = None
    if mapping_candidates:
        log(f"  {len(mapping_candidates)} mapping candidate(s) — deriving d0-d7 from blob...")
        for idx, mapping in enumerate(mapping_candidates):
            d_vals = bypass._derive_d_from_blob(blob_data, mapping)
            if d_vals:
                try:
                    result = bypass._decrypt_raw(
                        blob_data, mapping, d_vals)
                except (ValueError, TypeError, IndexError, struct.error):
                    continue
                if bypass._check_crc(result):
                    log_ok(f"  Decrypted and verified with mapping#{idx}")
                    decrypted_blob = result
                    break

    if decrypted_blob is None:
        # 2) Slow fallback: full PE scan + brute-force
        log_warn("  Fast derivation failed — running full key scan (may be slow)...")
        mapping_candidates2, d_candidates = bypass.extract_key_material_from_pe(pe_data)
        if mapping_candidates2 is not None:
            if d_candidates is None:
                d_candidates = []
            decrypted_blob, _, _ = bypass.decrypt_blob_auto(
                blob_data, mapping_candidates2, d_candidates
            )

    _diag = {}
    _verified_chunks = []
    if decrypted_blob is not None:
        for _name_decoder in (None, CommercialBypass()):
            _try_diag = {}
            _verified_chunks = parse_blob_modules(
                decrypted_blob, _name_decoder, strict=True,
                diagnostics=_try_diag)
            _diag = _try_diag
            if _verified_chunks and _try_diag.get('ok'):
                break
    if _verified_chunks:
        log_ok("Blob decrypted successfully")
        _decrypt_blob_if_encrypted.last_state = 'decrypted'
        return decrypted_blob
    else:
        log_warn("Decryption failed CRC/structure validation; protected bytes rejected")
        _decrypt_blob_if_encrypted.last_state = 'decrypt_failed'
        _decrypt_blob_if_encrypted.last_error = (
            _diag.get('stop_reason') or 'no_crc_verified_candidate')
        return None


# =============================================================================
# NUITKA C-SOURCE REBUILDER  v7 — reconstruct Nuitka-style .c from metadata
# =============================================================================

class NuitkaCSourceRebuilder:
    """Reconstruct the per-module C source that Nuitka would have generated,
    using the metadata we recovered from the constants blob.

    The original C is not stored in the compiled binary (it is an intermediate
    file that Nuitka produces in the build directory and then compiles to
    machine code). What we CAN do is apply the exact same code templates
    (Nuitka-develop/nuitka/code_generation/templates/CodeTemplates*.py) to the
    metadata we recovered:

      - module name / identifier          (from blob chunk name / module table)
      - module_init_func address          (from module table)
      - constants                         (from parsed chunk - every 'str', 'int', etc.)
      - CodeObjectSpecs                   (from parsed chunk - every 'C' tag)
      - qualname hierarchy                (Class.method patterns)
      - function signatures               (args, kwonly, posonly, varargs, **kwargs)
      - doc strings                       (usually the first str constant per func)

    What we CANNOT recover (because Nuitka *does not* marshal it):
      - function bodies (they are translated directly to C operations and then
        to native x86-64 instructions)
      - local variable names beyond what appears in the argument list
      - source line numbers for individual statements

    So the generated C file is "Nuitka-style skeleton": it compiles conceptually
    (after plugging in the missing glue headers) and matches the original byte
    for byte in its structural sections (constants table, code objects,
    function declarations, module init) — only the function BODIES are stubbed.
    """

    # Mirror of the forward Nuitka mapping of Python identifiers to C names.
    # See Nuitka/code_generation/Identifiers.py and the `_encodePythonStringToC`
    # helpers — identifiers are transliterated conservatively.
    _IDENT_CHAR_MAP = {
        '.': '$', '-': '_', ' ': '_', '+': '_plus_', '/': '_slash_',
        '<': '$lt$', '>': '$gt$', '=': '$eq$', '[': '$lb$', ']': '$rb$',
        '(': '$lp$', ')': '$rp$', "'": '$sq$', '"': '$dq$', ',': '$c$',
        '!': '$ex$', '?': '$qm$',
    }

    @classmethod
    def encode_identifier(cls, s: str) -> str:
        out = []
        for c in s:
            if c.isalnum() or c == '_':
                out.append(c)
            elif c in cls._IDENT_CHAR_MAP:
                out.append(cls._IDENT_CHAR_MAP[c])
            else:
                out.append(f"$u{ord(c):04x}$")
        return ''.join(out) or '_empty'

    @classmethod
    def is_package(cls, module_name, module_table):
        if module_table:
            for e in module_table:
                if e['name'] == module_name:
                    return 'PACKAGE' in e['flag_names']
        return module_name.endswith('.__init__') or module_name in ('', '__main__')

    @classmethod
    def constant_c_name(cls, val, seen_names):
        """Produce a stable Nuitka-style name for a constant value."""
        tname = type(val).__name__
        if isinstance(val, str):
            # Nuitka uses: const_str_plain_<ident> for valid identifiers,
            # const_str_digest_<md5[:8]> for others.
            if val.isidentifier() and len(val) < 40:
                base = f"const_str_plain_{val}"
            else:
                import hashlib
                h = hashlib.md5(val.encode('utf-8', 'replace')).hexdigest()[:8]
                base = f"const_str_digest_{h}"
        elif isinstance(val, (bytes, bytearray)):
            import hashlib
            h = hashlib.md5(bytes(val)).hexdigest()[:8]
            base = f"const_bytes_digest_{h}"
        elif isinstance(val, bool):
            base = f"const_{str(val).lower()}"
        elif val is None:
            base = "const_none"
        elif isinstance(val, int):
            sign = 'neg' if val < 0 else 'pos'
            absv = abs(val)
            if absv < 1000000:
                base = f"const_int_{sign}_{absv}"
            else:
                import hashlib
                h = hashlib.md5(str(val).encode()).hexdigest()[:8]
                base = f"const_int_digest_{h}"
        elif isinstance(val, float):
            base = f"const_float_{str(val).replace('.', '_').replace('-', 'neg_')}"
        elif isinstance(val, tuple):
            base = f"const_tuple_{len(val)}"
        elif isinstance(val, list):
            base = f"const_list_{len(val)}"
        elif isinstance(val, dict):
            base = f"const_dict_{len(val)}"
        elif isinstance(val, set):
            base = f"const_set_{len(val)}"
        elif isinstance(val, frozenset):
            base = f"const_frozenset_{len(val)}"
        elif isinstance(val, dict) and val.get('_type') == 'CodeObject':
            base = f"const_code_object_{val.get('name', 'unknown')}"
        else:
            base = f"const_{tname}"

        base = cls.encode_identifier(base)

        # Disambiguate colliding names
        candidate = base
        k = 0
        while candidate in seen_names:
            k += 1
            candidate = f"{base}_{k}"
        seen_names.add(candidate)
        return candidate

    @classmethod
    def format_constant_comment(cls, val, max_len=60):
        try:
            r = repr(val)
        except Exception:
            return "<unrepresentable>"
        if len(r) > max_len:
            r = r[:max_len] + '...'
        return r.replace('*/', '*\\/').replace('\n', '\\n')

    @classmethod
    def infer_functions_from_constants(cls, constants):
        """For C-compiled modules that don't serialize CodeObjectSpec ('C')
        tags, Nuitka still embeds the filename, function name, qualname and
        co_varnames tuple as plain constants because they're passed to
        `MAKE_FUNCTION_*`. We detect those tuples by matching on any of the
        layouts the code-generator emits.

        Typical layouts observed in real binaries:

          Layout A (free function / module body):
            [name_str]  [filename.py str]  [qualname]  [tuple(varnames)]

          Layout B (method — qualname contains a dot):
            [tuple(varnames)]  [name_str]  [qualname('Class.method')]  [filename.py]

          Layout C (listcomp / genexpr helper - qualname starts with <):
            [tuple(varnames)]  [name_str=<listcomp>]  [qualname]  [filename.py]

        We anchor on `.py` filenames, look both before and after by up to 4
        positions, and accept any arrangement where exactly one ident-tuple,
        one plain ident, and one qualname (optionally dotted) are adjacent.
        """
        inferred = []
        def is_ident(s):
            return (isinstance(s, str) and s
                    and (s.isidentifier() or s.startswith('<')))

        def is_qualname(s):
            if not isinstance(s, str) or not s:
                return False
            # qualnames can be 'x.y', 'x.<locals>.y', '<module>', '<module x.y>', 'x'
            if s.startswith('<'):
                return True
            parts = s.replace('<locals>', 'LOCALS').split('.')
            return all(p.isidentifier() for p in parts if p)

        def is_ident_tuple(t):
            if not isinstance(t, tuple) or not t:
                return False
            # Allow leading '.0' synthetic argument used by comprehensions
            for x in t:
                if not isinstance(x, str):
                    return False
                if x == '.0' or x.isidentifier():
                    continue
                return False
            return True

        # Find a single module filename (for context).
        module_filename = None
        for c in constants:
            if isinstance(c, str) and c.endswith('.py'):
                module_filename = c
                break

        # Anchor on each tuple-of-idents (candidate co_varnames). Those are
        # what Nuitka MUST emit for every function / class body.
        seen_anchors = set()
        for i, c in enumerate(constants):
            if not is_ident_tuple(c):
                continue

            # Tuples of 1-2 elements that look like __slots__ or simple
            # decorator arg tuples usually aren't co_varnames. Require
            # length > 0 always (even `()` is a valid co_varnames for no-arg funcs).
            varnames = c

            # Scan neighbours for: a qualified name (like "Foo.bar" or "<module>"
            # or "<listcomp>") OR a plain ident (function name).
            window = []
            for off in (-4, -3, -2, -1, 1, 2, 3, 4):
                j = i + off
                if 0 <= j < len(constants):
                    window.append((j, constants[j]))

            # Collect the closest name candidate (plain ident) and
            # qualname candidate (dotted/angle).
            name_val = None
            name_dist = 99
            qualname_val = None
            qual_dist = 99
            for j, v in window:
                if not isinstance(v, str):
                    continue
                if v.endswith('.py'):
                    continue
                d = abs(j - i)
                # qualname-like: contains '.' OR '<...>' wrapper
                if is_qualname(v) and (
                        '.' in v or (v.startswith('<') and v.endswith('>'))):
                    if d < qual_dist:
                        qual_dist, qualname_val = d, v
                # plain ident-like name
                elif is_ident(v) and '.' not in v:
                    if d < name_dist:
                        name_dist, name_val = d, v

            # Must find at least a name OR a qualname.
            if name_val is None and qualname_val is None:
                continue

            if name_val is None:
                # Derive plain name from qualname
                nm = qualname_val
                if '.' in nm:
                    nm = nm.rsplit('.', 1)[-1]
                name_val = nm

            if qualname_val is None:
                qualname_val = name_val

            anchor = (i, name_val, tuple(varnames))
            if anchor in seen_anchors:
                continue
            seen_anchors.add(anchor)

            inferred.append({
                '_type': 'CodeObject',
                'name': name_val,
                'qualname': qualname_val,
                'filename': module_filename or '',
                'args': list(varnames),
                'argcount': len(varnames),
                'kwonly': 0,
                'posonly': 0,
                'freevars': [],
                'flags': 0,
                'line': 0,
                '_source': 'inferred-from-constants',
            })

        # Deduplicate (same name, args)
        seen = set()
        out = []
        for co in inferred:
            k = (co['name'], tuple(co['args']), co.get('qualname'))
            if k in seen:
                continue
            seen.add(k)
            out.append(co)
        return out

    @classmethod
    def classify_code_objects(cls, code_objects):
        """Group code objects by their qualified-name hierarchy.

        Returns a dict: { 'Class.method': [...], 'free_function': [...], '<module>': [...] }

        This lets us emit class { ... } structures correctly. Nuitka uses qualname
        of the form "Class.method" (or "Class.inner_func") to denote nested
        definitions.
        """
        tree = {
            '__module_body__': [],   # qualname == '<module>' or name == '<module>'
            'classes': {},            # 'ClassName' -> {'methods': [...], 'bases': []}
            'free_functions': [],
        }

        for co in code_objects:
            if not co:
                continue
            name = co.get('name') or ''
            qualname = co.get('qualname') or name

            if name == '<module>' or qualname == '<module>':
                tree['__module_body__'].append(co)
                continue

            # qualname of "Foo.bar" → method 'bar' of class 'Foo'
            if '.' in qualname and not qualname.startswith('<'):
                parent, leaf = qualname.rsplit('.', 1)
                # Strip any trailing <locals> markers
                parent = parent.split('.<locals>.')[0]
                if '.' not in parent and parent and parent[0].isupper():
                    # Looks like a class
                    tree['classes'].setdefault(parent, {'methods': [], 'bases': []})
                    tree['classes'][parent]['methods'].append(co)
                    continue

            # Default: free function
            tree['free_functions'].append(co)

        return tree

    @classmethod
    def format_arg_list(cls, co):
        """Turn a CodeObjectSpec into a 'def foo(a, b, *args, c=..., **kw)' style arg string."""
        args = list(co.get('args') or [])
        argcount = co.get('argcount') or 0
        kwonly = co.get('kwonly') or 0
        posonly = co.get('posonly') or 0
        flags = co.get('flags') or 0

        has_varargs = bool(flags & 0x04)
        has_varkw = bool(flags & 0x08)

        parts = []
        idx = 0
        # Positional-only args (before a '/')
        if posonly:
            for _ in range(min(posonly, len(args))):
                parts.append(str(args[idx]))
                idx += 1
            parts.append('/')

        # Regular positional args
        regular_count = argcount - (posonly or 0)
        for _ in range(regular_count):
            if idx < len(args):
                parts.append(str(args[idx]))
            idx += 1

        if has_varargs:
            if idx < len(args):
                parts.append('*' + str(args[idx]))
                idx += 1
            else:
                parts.append('*args')
        elif kwonly:
            parts.append('*')

        for _ in range(kwonly):
            if idx < len(args):
                parts.append(f"{args[idx]}=None")
                idx += 1

        if has_varkw:
            if idx < len(args):
                parts.append('**' + str(args[idx]))
            else:
                parts.append('**kwargs')

        return ', '.join(parts)

    @classmethod
    def generate_c_source(cls, module_name, constants, code_objects,
                           module_table_entry=None, native_func_addr=None,
                           nuitka_version="RECONSTRUCTED"):
        """Produce the full .c file content for this module."""
        if not module_name:
            module_name = '__main__'
        module_ident = cls.encode_identifier(module_name)

        is_pkg = (module_table_entry and 'PACKAGE' in module_table_entry.get('flag_names', []))
        is_dunder_main = module_name == '__main__'
        flags = module_table_entry['flag_names'] if module_table_entry else ['COMPILED']

        # -- Header / copyright -------------------------------------------
        year = datetime.now().year
        out = []
        out.append(f"/* Reconstructed C source for Python module '{module_name}'")
        out.append(f" * Recovered by HEXPYRION (by dimareverse) from compiled binary metadata.")
        out.append(f" *")
        out.append(f" * Original C was generated by Nuitka but is not stored in the binary.")
        out.append(f" * This reconstruction applies the same Nuitka code-generation templates")
        out.append(f" * to the metadata we recovered from the constants blob.")
        out.append(f" *")
        out.append(f" * STRUCTURAL PARTS (match what Nuitka produced):")
        out.append(f" *   - Module constants table (every constant byte-identical)")
        out.append(f" *   - Code object declarations (names, line numbers, arg names)")
        out.append(f" *   - Function signature declarations")
        out.append(f" *   - Module-initialization entry point")
        out.append(f" *")
        out.append(f" * LOST (compiled directly to native instructions by Nuitka):")
        out.append(f" *   - Function bodies — translated through Nuitka IR to C operations")
        out.append(f" *     to x86-64/ARM assembly. Original Python statements cannot be")
        out.append(f" *     reconstructed without disassembling the native code around the")
        out.append(f" *     module_init_func pointer.")
        out.append(f" *")
        if native_func_addr:
            out.append(f" * NATIVE ENTRY POINT: module_code_{module_ident} @ 0x{native_func_addr:X}")
        out.append(f" * Flags: {', '.join(flags)}")
        out.append(f" * Is package: {is_pkg}")
        out.append(f" */")
        out.append("")
        out.append(f'#include "nuitka/prelude.h"')
        out.append(f'#include "nuitka/unfreezing.h"')
        out.append(f'#include "__helpers.h"')
        out.append("")

        out.append(f"/* The module object (Python-visible) */")
        out.append(f"PyObject *module_{module_ident};")
        out.append(f"PyDictObject *moduledict_{module_ident};")
        out.append("")

        # -- Module constants struct -------------------------------------
        out.append(f"/* Module constants: {len(constants)} entries recovered from blob chunk '{module_name}'. */")
        out.append("static struct ModuleConstants {")
        seen_names = set()
        constant_c_names = []
        for idx, c in enumerate(constants):
            cname = cls.constant_c_name(c, seen_names)
            constant_c_names.append(cname)
            comment = cls.format_constant_comment(c)
            out.append(f"    PyObject *{cname};  /* [{idx}] {type(c).__name__} = {comment} */")
        out.append("} mod_consts;")
        out.append("")

        out.append(f"static PyObject *module_filename_obj = NULL;")
        out.append("static bool constants_created = false;")
        out.append("")
        out.append(f"static void createModuleConstants(PyThreadState *tstate) {{")
        out.append(f"    if (constants_created == false) {{")
        out.append(f'        loadConstantsBlob(tstate, (PyObject **)&mod_consts, UN_TRANSLATE("{module_name}"));')
        out.append(f"        constants_created = true;")
        out.append(f"    }}")
        out.append(f"}}")
        out.append("")

        if is_dunder_main:
            out.append(f"/* Entry used to initialize __main__ constants from main program glue. */")
            out.append(f"void createMainModuleConstants(PyThreadState *tstate) {{")
            out.append(f"    createModuleConstants(tstate);")
            out.append(f"}}")
            out.append("")

        # -- Function inference from constants (for C-compiled modules) --
        # The chunk usually has no 'C' (CodeObjectSpec) tag for compiled modules,
        # but the tuples of varnames + the source filename + the function name
        # ARE still present as constants (Nuitka needs them for MAKE_FUNCTION).
        # We harvest those patterns to recover function signatures.
        inferred = cls.infer_functions_from_constants(constants)
        if inferred and not code_objects:
            code_objects = inferred
        elif inferred:
            # Merge: keep explicit CodeObjects but add any inferred ones not already present
            seen = {(co.get('name'), tuple(co.get('args') or ())) for co in code_objects}
            for co in inferred:
                if (co['name'], tuple(co['args'])) not in seen:
                    code_objects.append(co)

        # -- Code object declarations -----------------------------------
        out.append("/* Code objects declared for this module's functions. Nuitka")
        out.append(" * creates one PyCodeObject per function/class body, then wraps")
        out.append(" * them in Nuitka_Function objects via MAKE_FUNCTION_*. */")
        for idx, co in enumerate(code_objects):
            if not co:
                continue
            name = co.get('name', '?')
            line = co.get('line', 0)
            src = co.get('_source', 'explicit')
            out.append(f"static PyCodeObject *codeobj_{idx}__{cls.encode_identifier(name)};   /* {name!r} @ line {line}  ({src}) */")
        out.append("")

        # -- Function declarations + stubs ------------------------------
        tree = cls.classify_code_objects(code_objects)

        # Module body (if we inferred one)
        if tree['__module_body__']:
            out.append("/* === Module body code object ================================ */")
            for co in tree['__module_body__']:
                name = co.get('name', '<module>')
                arg_list = cls.format_arg_list(co)
                fn = co.get('filename', '?')
                out.append("")
                out.append(f"/* Module body for {module_name!r}")
                out.append(f" *   source filename: {fn}")
                out.append(f" *   locals / varnames: ({arg_list})")
                out.append(f" *   — this is what runs on `import {module_name}` */")
                out.append(f"/* Nuitka-style entry: module_code_{module_ident}() — see below. */")

        # Free functions
        out.append("")
        out.append("/* === Free function signatures =============================== */")
        for co in tree['free_functions']:
            name = co.get('name', 'unknown')
            qualname = co.get('qualname', name)
            line = co.get('line', 0)
            arg_list = cls.format_arg_list(co)
            out.append(f"")
            out.append(f"/* Recovered Python signature:  def {name}({arg_list})")
            out.append(f" *  qualname: {qualname}   line: {line}")
            out.append(f" *  flags: 0x{co.get('flags', 0):X}")
            out.append(f" *  body: compiled to native code — not recoverable here */")
            out.append(f"static PyObject *impl_{module_ident}${cls.encode_identifier(name)}(PyThreadState *tstate, PyObject **python_pars);")

        # Classes
        out.append("")
        out.append("/* === Class bodies ============================================ */")
        for class_name, cdata in tree['classes'].items():
            out.append("")
            out.append(f"/* Class: {class_name}")
            out.append(f" *   methods recovered: {len(cdata['methods'])}")
            out.append(f" *   class body was also compiled to native code */")
            for co in cdata['methods']:
                name = co.get('name', '?')
                line = co.get('line', 0)
                arg_list = cls.format_arg_list(co)
                out.append(f"static PyObject *impl_{module_ident}${cls.encode_identifier(class_name)}${cls.encode_identifier(name)}(PyThreadState *tstate, PyObject **python_pars);  /* def {class_name}.{name}({arg_list}) line {line} */")

        # -- Function stubs (bodies) --------------------------------------
        out.append("")
        out.append("/* === Function body stubs =====================================")
        out.append(" *   All bodies are placeholders. The real implementations are")
        out.append(" *   at the machine-code level. See module_code_<name> below")
        out.append(" *   for the native entry point recovered from the PE. */")
        out.append("")

        for co in tree['free_functions']:
            name = co.get('name', 'unknown')
            arg_list = cls.format_arg_list(co)
            ident = f"{module_ident}${cls.encode_identifier(name)}"
            out.append(f"static PyObject *impl_{ident}(PyThreadState *tstate, PyObject **python_pars) {{")
            out.append(f"    /* Original Python source equivalent:  def {name}({arg_list}): ... */")
            out.append(f"    /* Body unrecoverable. Disassemble around the native")
            out.append(f"     * module_init entry point to inspect the compiled code. */")
            out.append(f"    Py_RETURN_NONE;")
            out.append(f"}}")
            out.append("")

        for class_name, cdata in tree['classes'].items():
            for co in cdata['methods']:
                name = co.get('name', '?')
                arg_list = cls.format_arg_list(co)
                ident = f"{module_ident}${cls.encode_identifier(class_name)}${cls.encode_identifier(name)}"
                out.append(f"static PyObject *impl_{ident}(PyThreadState *tstate, PyObject **python_pars) {{")
                out.append(f"    /* def {class_name}.{name}({arg_list}): ... */")
                out.append(f"    Py_RETURN_NONE;")
                out.append(f"}}")
                out.append("")

        # -- Module init entry point (Nuitka's standard template) --------
        out.append("/* ============================================================")
        out.append(" *  Module initialization entry point")
        out.append(" *  Nuitka template: template_module_body in CodeTemplatesModules.py")
        out.append(" * ============================================================ */")
        out.append(f"PyObject *module_code_{module_ident}(PyThreadState *tstate, PyObject *module,")
        out.append(f"                                     struct Nuitka_MetaPathBasedLoaderEntry const *loader_entry) {{")
        out.append(f"    module_{module_ident} = module;")
        out.append(f"    moduledict_{module_ident} = MODULE_DICT(module_{module_ident});")
        out.append(f"")
        out.append(f"    static bool init_done = false;")
        out.append(f"    if (init_done == false) {{")
        out.append(f"        createModuleConstants(tstate);")
        out.append(f"        init_done = true;")
        out.append(f"    }}")
        out.append(f"")
        out.append(f"    /* The sequence of CREATE_MODULE_VARIABLE + MAKE_FUNCTION calls")
        out.append(f"     * that Nuitka generates here for import statements and class")
        out.append(f"     * definitions is not recoverable from metadata alone.")
        out.append(f"     * It lives natively at:")
        if native_func_addr:
            out.append(f"     *    PE virtual address  0x{native_func_addr:X}")
        out.append(f"     *")
        out.append(f"     * Recovered imports (detected from module constants): */")
        # Heuristic: scan constants for 'module.name' patterns used as import args
        for c in constants:
            if isinstance(c, str) and '.' in c and c.replace('.', '').replace('_', '').isalnum():
                if not c.startswith('.') and len(c) < 60:
                    out.append(f"    /*   import {c} */")
        out.append(f"")
        out.append(f"    return module;")
        out.append(f"}}")
        out.append("")

        return '\n'.join(out) + '\n'


# =============================================================================
# NUITKA MODULE TABLE PARSER  v7 — locate Nuitka_MetaPathBasedLoaderEntry[]
# =============================================================================

class NuitkaModuleTableParser:
    """Parse the array of `Nuitka_MetaPathBasedLoaderEntry` from the PE.

    Each record (x64, 32 bytes without file_path):
        char const *name;                  // +0   8 bytes
        module_init_func python_init_func; // +8   8 bytes
        int bytecode_index;                // +16  4 bytes
        int bytecode_size;                  // +20  4 bytes
        int flags;                          // +24  4 bytes
        // 4 bytes padding (aligns next pointer)
    Terminator: {NULL, NULL, 0, 0, 0}

    The `flags` field uses bits from unfreezing.h:
        NUITKA_EXTENSION_MODULE_FLAG = 1
        NUITKA_PACKAGE_FLAG          = 2
        NUITKA_BYTECODE_FLAG         = 4
        NUITKA_ABORT_MODULE_FLAG     = 8
        NUITKA_TRANSLATED_FLAG       = 16
        NUITKA_PERFECT_SUPPORTED_FLAG= 32
        NUITKA_EXCLUDED_MODULE_FLAG  = 64

    For x86 (32-bit) the pointers are 4 bytes each, record is 20 bytes.
    """

    FLAG_NAMES = {
        1: 'EXTENSION', 2: 'PACKAGE', 4: 'BYTECODE',
        8: 'ABORT',     16: 'TRANSLATED', 32: 'PERFECT',
        64: 'EXCLUDED',
    }

    def __init__(self, pe, name_decode_table=None):
        self.pe = pe
        self.image_base = pe.OPTIONAL_HEADER.ImageBase
        self.is_x64 = pe.FILE_HEADER.Machine == 0x8664
        self.ptr_size = 8 if self.is_x64 else 4
        self.record_size = 32 if self.is_x64 else 20
        # Optional: mapping2 decode table for commercial builds where module
        # name strings in the PE are encoded (name_decode_table[enc] = orig).
        self.name_decode_table = name_decode_table

    def _collect_strings(self):
        """Index every null-terminated printable ASCII string in .rdata/.data.

        For commercial builds pass name_decode_table to also find encoded
        module name strings (encoded with Nuitka Commercial mapping2).
        """
        strings_by_va = {}
        dec = self.name_decode_table  # None for open-source builds

        for section in self.pe.sections:
            sec_name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            if sec_name not in ('.rdata', '.data'):
                continue
            sec_data = section.get_data()
            base_va = self.image_base + section.VirtualAddress
            sz = len(sec_data)
            i = 0
            while i < sz:
                # ── Pass A: plain printable ASCII ──
                j = i
                while j < sz and 0x20 <= sec_data[j] < 0x7F:
                    j += 1
                if j > i and j < sz and sec_data[j] == 0 and j - i >= 2:
                    try:
                        s = sec_data[i:j].decode('ascii')
                        strings_by_va[base_va + i] = s
                    except Exception:
                        pass

                # ── Pass B: mapping2-decoded (commercial builds only) ──
                if dec is not None and sec_data[i] != 0:
                    k = i
                    decoded_bytes = []
                    while k < sz and sec_data[k] != 0 and len(decoded_bytes) < 256:
                        orig = dec[sec_data[k]]
                        if not (0x20 <= orig < 0x7F):
                            break
                        decoded_bytes.append(orig)
                        k += 1
                    if (len(decoded_bytes) >= 2 and k < sz and sec_data[k] == 0
                            and (base_va + i) not in strings_by_va):
                        try:
                            s = bytes(decoded_bytes).decode('ascii')
                            if self._is_module_name(s) or s in ('.bytecode', ''):
                                strings_by_va[base_va + i] = s
                        except Exception:
                            pass

                i = j + 1 if j > i else i + 1
        return strings_by_va

    @staticmethod
    def _is_module_name(s):
        if not s or len(s) > 200:
            return False
        # Valid dotted module identifier, or __special__
        if not all(c.isalnum() or c in '._-' for c in s):
            return False
        # Must start with letter/underscore
        first = s[0]
        if not (first.isalpha() or first == '_'):
            return False
        return True

    def find_table(self, extra_names=None, bc_index_to_name=None):
        """Locate the module table and return the full entry list.

        Strategy (4 passes, combined):

          1. **Primary cluster scan** — identical to the original: walk every
             8-byte offset in .data/.rdata, follow contiguous records and
             pick the longest run with >= 100 entries whose names look
             module-like. That's the main loader table Nuitka emits in
             `meta_path_loader_entries[]`.

          2. **Fragment stitching** — ANY other cluster of >= 10
             consecutive valid records in the same sections is appended
             (deduplicated by `func_ptr`). Some builds split the table
             across a couple of fragments, typically when data-hiding
             plugins reorder it.

          3. **Name-anchored fallback** — given `extra_names` (a list of
             module names we already know exist, e.g. from the blob chunks
             the analyser decoded), search for each name's string in
             .data/.rdata, then scan for a qword pointer to that string.
             Around each such pointer, try to parse a full record (32-B
             layout). If the record validates, add it. This rescues
             isolated entries like `__main__` that live outside the main
             cluster because Nuitka's loader-codes generator sometimes
             emits them in a sidecar array.

          4. **Function-pointer cluster scan** (commercial / data-hiding builds) —
             when passes 1-3 recover nothing (because module name strings are
             fully hidden or stored outside .data/.rdata), scan .data/.rdata
             for 32-byte-aligned clusters where the func_ptr field (offset 8 in
             x64) is a valid .text address. This recovers func_ptrs without
             needing name strings at all. Names are then recovered from the
             `bc_index_to_name` mapping (derived from the already-decrypted blob
             chunk list via the bytecode_index field), or left as '<unknown_N>'.

        Args:
            extra_names:      list of module names known to exist (from blob chunks).
            bc_index_to_name: dict {bytecode_index: module_name} built from the
                              decrypted blob so Pass 4 can recover names even when
                              the PE stores them encrypted.

        Returns `(start_va, entries)` or `None`.
        """
        strings_by_va = self._collect_strings()
        module_strings = {va: s for va, s in strings_by_va.items()
                          if self._is_module_name(s)}

        best = None                 # (start_va, entries) — the primary cluster
        other_clusters = []         # [(va, entries), ...] — passed 2

        # Snapshot of each section (avoid re-calling get_data() in the hot loop)
        sections_info = []
        for section in self.pe.sections:
            sec_name = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            if sec_name not in ('.rdata', '.data'):
                continue
            sections_info.append({
                'name': sec_name,
                'data': section.get_data(),
                'base_va': self.image_base + section.VirtualAddress,
            })

        # ---------- Pass 1 + 2 ----------
        for info in sections_info:
            sec_data = info['data']
            sec_size = len(sec_data)
            base_va = info['base_va']

            off = 0
            while off < sec_size - self.record_size:
                if self.is_x64:
                    p1 = struct.unpack('<Q', sec_data[off:off + 8])[0]
                else:
                    p1 = struct.unpack('<I', sec_data[off:off + 4])[0]

                if p1 not in module_strings:
                    off += 8
                    continue

                entries = []
                run_off = off
                while run_off + self.record_size <= sec_size:
                    entry = self._read_record(sec_data, run_off, module_strings)
                    if entry is None:
                        break
                    if entry == 'TERMINATOR':
                        break
                    entries.append(entry)
                    run_off += self.record_size
                    if len(entries) > 10000:
                        break

                if entries:
                    # Promote any cluster of >= 100 entries to the primary;
                    # fragments of >= 10 are kept for stitching.
                    if len(entries) >= 100:
                        dotted = sum(1 for e in entries if '.' in e['name'])
                        has_trans = sum(1 for e in entries if (e['flags'] & 16) != 0)
                        if not (dotted < 5 and has_trans < 50):
                            if best is None or len(entries) > len(best[1]):
                                # A newer LONGER real table replaces the primary,
                                # but the old primary is KEPT as a stitch fragment.
                                # A binary can embed SEVERAL >=100-entry loader
                                # tables — Nuitka emits the app modules and each
                                # large dependency package as separate
                                # meta_path_loader arrays. The old code kept only
                                # the single LONGEST >=100 cluster and DISCARDED
                                # the others (they were never added to
                                # other_clusters), so e.g. the ~300-entry app+deps
                                # table (auth_system/gui/buyu.*), being shorter
                                # than the ~700-entry numpy table, was lost — its
                                # func_ptrs never found and every body emitted as
                                # `pass`. Demote-and-merge recovers ALL real tables
                                # (the func_ptr / (name,bc_index) dedup below drops
                                # any overlap). single-table layouts are unaffected.
                                if best is not None:
                                    other_clusters.append(best)
                                best = (base_va + off, entries)
                            else:
                                other_clusters.append((base_va + off, entries))
                    elif len(entries) >= 10:
                        has_trans = sum(1 for e in entries if (e['flags'] & 16) != 0)
                        if has_trans >= 5:
                            other_clusters.append((base_va + off, entries))

                # Jump past the cluster we just consumed; if only 1 entry
                # matched we advance by record_size to try the next slot.
                off = run_off + (self.record_size if not entries else 0)
                if off <= run_off:
                    off = run_off + 8

        # Merge fragments into the primary cluster (deduplicate on func_ptr
        # OR on (name, bytecode_index) when func_ptr is 0).
        def _entry_key(e):
            if e.get('func_ptr'):
                return ('fp', e['func_ptr'])
            return ('ni', e.get('name'), e.get('bytecode_index'))

        if best is None and other_clusters:
            # No primary cluster — promote the biggest fragment
            other_clusters.sort(key=lambda c: -len(c[1]))
            best = other_clusters[0]
            other_clusters = other_clusters[1:]

        if best and other_clusters:
            seen_keys = {_entry_key(e) for e in best[1]}
            merged = list(best[1])
            for _, frag in other_clusters:
                for e in frag:
                    k = _entry_key(e)
                    if k in seen_keys:
                        continue
                    seen_keys.add(k)
                    merged.append(e)
            best = (best[0], merged)

        # ---------- Pass 3 — name-anchored fallback ----------
        #
        # For every module name we know the binary MUST contain (either
        # passed in via `extra_names` or the blob chunk names we already
        # decoded), find its string address and scan for a qword pointer
        # that references it. If the 32-B window around the pointer looks
        # like a valid `Nuitka_MetaPathBasedLoaderEntry`, add it.
        #
        # This is what rescues `__main__`, `.bytecode`, and other entries
        # Nuitka emits outside the main `meta_path_loader_entries[]`
        # array (e.g. as members of `_frozen_modules[]` or in a data-hiding
        # plugin's sidecar table).
        if extra_names:
            # Build reverse lookup: module_name -> string_va
            name_to_va = {s: va for va, s in module_strings.items()}
            # Also add names we didn't flag as "module-like" (e.g. '.bytecode')
            for va, s in strings_by_va.items():
                if s and s not in name_to_va:
                    name_to_va[s] = va

            known = set()
            if best:
                for e in best[1]:
                    known.add(e['name'])

            added_va = set()
            # V95 Fix 1 (universal): run the name-anchored rescue even when
            # NO >=10-entry cluster was found.  Small builds (accelerated
            # exes, --module extension builds, tiny apps) carry a loader
            # table with only a handful of entries — gating this pass on
            # `best` left them with NO func_ptr at all (static-only recovery
            # of __main__ with zero lines).  Unchanged when a cluster exists.
            added = []
            first_added_va = None
            # Old implementation scanned every qword of every section once
            # PER missing name: O(section_bytes * module_count), which takes
            # hours on 60+ MB standalone DLLs.  Invert the lookup and walk
            # each section exactly once instead.
            # V95 Fix 2 (universal): anchor EVERY string instance of a wanted
            # name, not just one.  Compilers emit duplicated string constants
            # (MinGW keeps several copies in .rdata) and the loader entry may
            # reference any instance — a single-VA map misses the record.
            wanted_by_va = {}
            for n in extra_names:
                if n in known:
                    continue
                target_va = name_to_va.get(n)
                if target_va is not None:
                    wanted_by_va[target_va] = n
            _wanted_name_set = {n for n in extra_names if n not in known}
            for va, s in strings_by_va.items():
                if s and va not in wanted_by_va and s not in known \
                        and s in _wanted_name_set:
                    wanted_by_va[va] = s

            found_names = set()
            ptr_fmt = '<Q' if self.is_x64 else '<I'
            step = self.ptr_size
            for info in sections_info:
                if len(found_names) >= len(wanted_by_va):
                    break
                sec_data = info['data']
                sec_size = len(sec_data)
                base_va = info['base_va']
                for off in range(0, sec_size - self.record_size, step):
                    ptr = struct.unpack_from(ptr_fmt, sec_data, off)[0]
                    wanted_name = wanted_by_va.get(ptr)
                    if wanted_name is None or wanted_name in found_names:
                        continue
                    abs_va = base_va + off
                    if abs_va in added_va:
                        continue
                    entry = self._read_record(sec_data, off, module_strings)
                    if (entry is None or entry == 'TERMINATOR'
                            or not isinstance(entry, dict)):
                        entry = self._read_record_permissive(
                            sec_data, off, strings_by_va)
                    if entry and entry != 'TERMINATOR':
                        added.append(entry)
                        added_va.add(abs_va)
                        if first_added_va is None:
                            first_added_va = abs_va
                        known.add(entry['name'])
                        found_names.add(wanted_name)
            if added:
                if best:
                    merged = list(best[1]) + [
                        e for e in added
                        if _entry_key(e) not in {_entry_key(x) for x in best[1]}
                    ]
                    best = (best[0], merged)
                else:
                    best = (first_added_va or 0, added)

        # ---------- Pass 4 — func_ptr cluster scan (commercial / data-hiding) ----------
        #
        # When passes 1-3 find nothing (e.g. all name strings are encrypted or
        # stored outside .data/.rdata by the data-hiding plugin), we scan for
        # clusters of 32-byte records where the func_ptr field points into .text.
        # No name strings needed — we recover names from bc_index_to_name instead.
        if best is None:
            fp_result = self._find_table_by_funcptr(sections_info, bc_index_to_name)
            if fp_result:
                best = fp_result

        return best

    def _find_table_by_funcptr(self, sections_info, bc_index_to_name=None):
        """Pass 4: find module table by scanning for func_ptr clusters.

        Does not depend on name strings being present in .data/.rdata.
        For each 32-byte-aligned window in .data/.rdata where the func_ptr
        field (offset 8 on x64, offset 4 on x86) is a valid .text VA, walk
        forward to find the longest consecutive cluster.  Names are recovered
        from bc_index_to_name when available; otherwise set to '<unknown_N>'.
        Returns (start_va, entries) or None.
        """
        MIN_CLUSTER = 5  # minimum entries to accept as a real table

        # Build set of valid .text VA ranges
        text_lo, text_hi = 0, 0
        for section in self.pe.sections:
            sn = section.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            if sn == '.text':
                base = self.image_base + section.VirtualAddress
                sz   = section.SizeOfRawData
                if sz > text_hi - text_lo:
                    text_lo, text_hi = base, base + sz

        if text_hi == 0:
            return None

        def is_text(va):
            return text_lo <= va < text_hi

        ptr_fmt  = '<Q' if self.is_x64 else '<I'
        ptr_size = self.ptr_size
        rec      = self.record_size
        fp_off   = ptr_size   # func_ptr is immediately after name_ptr

        # Commercial / data-hiding builds encode module-name strings in the PE
        # with mapping2 (seed=27). When name_decode_table is available we decode
        # name_ptr directly — the ground-truth name source, independent of
        # _collect_strings (which Pass A/B may have missed) and of bc_idx
        # (which is 0 for every record in commercial builds).
        dec = self.name_decode_table
        _sec_lookup = None
        if dec is not None:
            _sec_lookup = [(info['base_va'], info['base_va'] + len(info['data']),
                            info['data'], info['base_va']) for info in sections_info]

        def _decode_name_at(nptr):
            """Decode a mapping2-encoded module name at VA nptr. Returns str or None."""
            if not nptr or not _sec_lookup:
                return None
            for lo, hi, sd, bv in _sec_lookup:
                if lo <= nptr < hi:
                    raw = bytearray()
                    p = nptr - bv
                    while p < len(sd) and sd[p] != 0 and len(raw) < 256:
                        raw.append(sd[p])
                        p += 1
                    if len(raw) >= 2:
                        try:
                            s = bytes(dec[b] for b in raw).decode('ascii')
                            if self._is_module_name(s):
                                return s
                        except Exception:
                            pass
                    return None
            return None

        best_cluster = None
        best_len     = 0

        for info in sections_info:
            sec_data = info['data']
            sec_size = len(sec_data)
            base_va  = info['base_va']

            off = 0
            while off <= sec_size - rec:
                # Quick pre-check: func_ptr field must be a .text VA
                if off + fp_off + ptr_size > sec_size:
                    off += 8
                    continue
                fp_val = struct.unpack_from(ptr_fmt, sec_data, off + fp_off)[0]
                if not is_text(fp_val):
                    off += 8
                    continue

                # Walk forward collecting entries
                cluster   = []
                run_off   = off
                idx_seq   = 0   # sequential index for unknown-name fallback

                while run_off + rec <= sec_size:
                    if self.is_x64:
                        name_ptr = struct.unpack_from('<Q', sec_data, run_off)[0]
                        fp  = struct.unpack_from('<Q', sec_data, run_off + 8)[0]
                        bci = struct.unpack_from('<i', sec_data, run_off + 16)[0]
                        bcs = struct.unpack_from('<i', sec_data, run_off + 20)[0]
                        flg = struct.unpack_from('<I', sec_data, run_off + 24)[0]
                    else:
                        name_ptr = struct.unpack_from('<I', sec_data, run_off)[0]
                        fp  = struct.unpack_from('<I', sec_data, run_off + 4)[0]
                        bci = struct.unpack_from('<i', sec_data, run_off + 8)[0]
                        bcs = struct.unpack_from('<i', sec_data, run_off + 12)[0]
                        flg = struct.unpack_from('<I', sec_data, run_off + 16)[0]

                    # Terminator row: everything zero
                    if fp == 0 and bci == 0 and bcs == 0 and flg == 0:
                        break

                    # Validate fields
                    if fp != 0 and not is_text(fp):
                        break
                    if bci < -1 or bci > 200_000:
                        break
                    if bcs < 0 or bcs > 100_000_000:
                        break
                    if flg > 0xFF:
                        break

                    # Recover name: decode name_ptr (commercial) > bc_index_to_name > unknown
                    name = _decode_name_at(name_ptr)
                    if name is None and bc_index_to_name and bci >= 0 and bci in bc_index_to_name:
                        name = bc_index_to_name[bci]
                    if name is None:
                        name = f'<unknown_{idx_seq}>'

                    cluster.append({
                        'name':           name,
                        'name_ptr':       name_ptr,
                        'func_ptr':       fp,
                        'bytecode_index': bci,
                        'bytecode_size':  bcs,
                        'flags':          flg,
                        'flag_names':     self._decode_flags(flg),
                    })
                    run_off += rec
                    idx_seq += 1

                if len(cluster) >= MIN_CLUSTER and len(cluster) > best_len:
                    best_len     = len(cluster)
                    best_cluster = (base_va + off, cluster)

                off = run_off if cluster else off + 8

        return best_cluster

    def _read_record_permissive(self, sec_data, off, all_strings):
        """Relaxed version of _read_record that accepts ANY string (not
        just module-name-looking) as the `name` pointer. Used for the
        pass-3 rescue when we already know the target name is legit."""
        if self.is_x64:
            name_ptr = struct.unpack('<Q', sec_data[off:off + 8])[0]
            func_ptr = struct.unpack('<Q', sec_data[off + 8:off + 16])[0]
            bc_idx   = struct.unpack('<i', sec_data[off + 16:off + 20])[0]
            bc_size  = struct.unpack('<i', sec_data[off + 20:off + 24])[0]
            flags    = struct.unpack('<I', sec_data[off + 24:off + 28])[0]
        else:
            name_ptr = struct.unpack('<I', sec_data[off:off + 4])[0]
            func_ptr = struct.unpack('<I', sec_data[off + 4:off + 8])[0]
            bc_idx   = struct.unpack('<i', sec_data[off + 8:off + 12])[0]
            bc_size  = struct.unpack('<i', sec_data[off + 12:off + 16])[0]
            flags    = struct.unpack('<I', sec_data[off + 16:off + 20])[0]

        if name_ptr == 0 and func_ptr == 0 and bc_idx == 0 and bc_size == 0 and flags == 0:
            return 'TERMINATOR'
        if name_ptr not in all_strings:
            return None
        if flags > 0xFF:
            return None
        if bc_idx < 0 or bc_idx > 100000 or bc_size < 0 or bc_size > 100_000_000:
            return None

        return {
            'name': all_strings[name_ptr],
            'func_ptr': func_ptr,
            'bytecode_index': bc_idx,
            'bytecode_size': bc_size,
            'flags': flags,
            'flag_names': self._decode_flags(flags),
        }

    def _read_record(self, sec_data, off, module_strings):
        """Decode one Nuitka_MetaPathBasedLoaderEntry. Returns dict or None or 'TERMINATOR'."""
        if self.is_x64:
            name_ptr = struct.unpack('<Q', sec_data[off:off + 8])[0]
            func_ptr = struct.unpack('<Q', sec_data[off + 8:off + 16])[0]
            bc_idx   = struct.unpack('<i', sec_data[off + 16:off + 20])[0]
            bc_size  = struct.unpack('<i', sec_data[off + 20:off + 24])[0]
            flags    = struct.unpack('<I', sec_data[off + 24:off + 28])[0]
        else:
            name_ptr = struct.unpack('<I', sec_data[off:off + 4])[0]
            func_ptr = struct.unpack('<I', sec_data[off + 4:off + 8])[0]
            bc_idx   = struct.unpack('<i', sec_data[off + 8:off + 12])[0]
            bc_size  = struct.unpack('<i', sec_data[off + 12:off + 16])[0]
            flags    = struct.unpack('<I', sec_data[off + 16:off + 20])[0]

        if name_ptr == 0 and func_ptr == 0 and bc_idx == 0 and bc_size == 0 and flags == 0:
            return 'TERMINATOR'

        if name_ptr not in module_strings:
            return None
        if flags > 0xFF:
            return None
        if bc_idx < 0 or bc_idx > 100000 or bc_size < 0 or bc_size > 100_000_000:
            return None

        return {
            'name': module_strings[name_ptr],
            'func_ptr': func_ptr,
            'bytecode_index': bc_idx,
            'bytecode_size': bc_size,
            'flags': flags,
            'flag_names': self._decode_flags(flags),
        }

    @classmethod
    def _decode_flags(cls, flags):
        names = [n for bit, n in cls.FLAG_NAMES.items() if flags & bit]
        return names if names else ['COMPILED']


# =============================================================================
# STATICALY INTEGRATION  v7_2 — pure-Python port of nuitka_deobfuscate.c +
#                               xdis-based code object scanner +
#                               OMNI unified Nuitka decompiler framework
# =============================================================================
#
# Originally three separate modules contributed by a collaborator:
#   1. `nuitka_deobfuscate.c` (CPython extension)  — fast blob section decoder
#   2. `run_extract*.py`                           — xdis marshal scanner
#   3. `omni_nuitka_framework.py`                  — AST-based decompiler
#
# All three are now embedded directly in this file as pure Python so the tool
# remains standalone. xdis is used when available (optional dependency) for
# cross-Python-version marshal parsing; otherwise we fall back to the builtin
# marshal module and our own write_pyc_from_marshal header helper.
# =============================================================================

# ---------------------------------------------------------------------------
#  1. NUITKA BLOB DECODER  (Python port of nuitka_deobfuscate.c)
# ---------------------------------------------------------------------------

class NuitkaBlobDecoder:
    """Full Python port of `nuitka_deobfuscate.c` (collaborator's extension).

    Two-pass decoder for Nuitka constants blobs:

    * SCAN 1 — Linear Chain:  follow the documented
          [name\\0] [u32 size] [u16 count] [typed constants...]
      layout starting at offset 8 (past the CRC32/size header). This recovers
      the "normal" named sections Nuitka's data composer emits.

    * SCAN 2 — Aggressive Signature Scan:  slide byte-by-byte through the blob
      looking for `[u32 size][u16 count][valid tag byte]` triples and try to
      decode constants from that offset. Rescues sections that the linear
      walker misses (truncated blobs, custom plugins, hidden injected
      segments, corrupted CRCs).

    Returns a `dict[str, tuple[Any, ...]]` mapping section name to its
    decoded constants tuple — identical signature to the C `.decode_blob`.
    """

    # Valid first-byte tags for a constant in Nuitka's format (see
    # Nuitka-develop/nuitka/build/static_src/HelpersConstantsBlob.c)
    _VALID_TAGS = frozenset(b"TLDCXbvactF:;MQOEZSPilqgGfjJBwu.AHcdrnsKpI")

    # Kept below CPython's recursion ceiling because each nested constant uses
    # several Python frames before the next budget check.
    _DEPTH_LIMIT = 128

    def __init__(self):
        self._collision_idx = 0
        self._last_decode_diagnostics = {}

    # ---- primitive readers ----

    @staticmethod
    def _unpack_vlq(data: memoryview, pos: int):
        """Nuitka's variable-length quantity (7-bit LE, high bit = continue)."""
        result = 0
        factor = 1
        end = len(data)
        while pos < end:
            b = data[pos]
            pos += 1
            result += (b & 0x7F) * factor
            if b < 0x80:
                break
            factor <<= 7
            if factor >= (1 << 63):
                break
        return result, pos

    @staticmethod
    def _anon_value(idx: int):
        """Recover singleton values by index (Ellipsis, NotImplemented, etc.)."""
        try:
            return [type(None), type(Ellipsis), type(NotImplemented),
                    __import__('types').FunctionType, None,
                    __import__('builtins').classmethod,
                    __import__('types').CodeType,
                    __import__('types').ModuleType][idx]
        except Exception:
            return None

    @staticmethod
    def _special_value(idx: int):
        m = {0: Ellipsis, 1: NotImplemented, 2: sys.version_info}
        return m.get(idx, None)

    # ---- recursive constant decoder ----

    def _decode_one_legacy_unused(self, data: memoryview, pos: int, depth: int = 0):
        """Decode exactly one constant and return (value, new_pos).

        Mirrors `_unpackBlobConstant` in nuitka_deobfuscate.c. On malformed
        input we consume one byte and emit None — this matches the C version's
        behaviour and keeps the stream aligned for subsequent constants.
        """
        end = len(data)
        if depth > self._DEPTH_LIMIT or pos >= end:
            return None, min(pos + 1, end)

        tag = data[pos]
        pos += 1
        ch = chr(tag) if tag < 128 else None

        if ch == 'p':  # repeat-marker, consumes a VLQ
            _, pos = self._unpack_vlq(data, pos)
            return None, pos

        if ch in ('T', 'L'):
            size, pos = self._unpack_vlq(data, pos)
            if size > 5_000_000:
                return None, pos
            items = []
            for _ in range(size):
                if pos >= end:
                    break
                v, pos = self._decode_one(data, pos, depth + 1)
                items.append(v)
            return (tuple(items) if ch == 'T' else items), pos

        if ch == 'D':
            size, pos = self._unpack_vlq(data, pos)
            if size > 500_000:
                return {}, pos
            keys = []
            for _ in range(size):
                if pos >= end:
                    break
                v, pos = self._decode_one(data, pos, depth + 1)
                keys.append(v)
            values = []
            for _ in range(size):
                if pos >= end:
                    break
                v, pos = self._decode_one(data, pos, depth + 1)
                values.append(v)
            d = {}
            for k, v in zip(keys, values):
                try:
                    d[k] = v
                except TypeError:
                    pass
            return d, pos

        if ch in ('S', 'P'):
            size, pos = self._unpack_vlq(data, pos)
            if size > 500_000:
                return (set() if ch == 'S' else frozenset()), pos
            items = []
            for _ in range(size):
                if pos >= end:
                    break
                v, pos = self._decode_one(data, pos, depth + 1)
                items.append(v)
            try:
                return (set(items) if ch == 'S' else frozenset(items)), pos
            except TypeError:
                return (set() if ch == 'S' else frozenset()), pos

        if ch in ('i', 'l'):
            val, pos = self._unpack_vlq(data, pos)
            return val, pos
        if ch == 'q':
            val, pos = self._unpack_vlq(data, pos)
            return -val, pos

        if ch in ('g', 'G'):
            nparts, pos = self._unpack_vlq(data, pos)
            result = 0
            for _ in range(nparts):
                result <<= 31
                part, pos = self._unpack_vlq(data, pos)
                result += part
            return (-result if ch == 'G' else result), pos

        if ch == 'f':
            if pos + 8 > end:
                return 0.0, end
            val = struct.unpack_from('<d', data, pos)[0]
            return val, pos + 8

        if ch == 'j':
            if pos + 16 > end:
                return 0j, end
            real = struct.unpack_from('<d', data, pos)[0]
            imag = struct.unpack_from('<d', data, pos + 8)[0]
            return complex(real, imag), pos + 16

        if ch == 'J':
            parts = []
            for _ in range(2):
                v, pos = self._decode_one(data, pos, depth + 1)
                parts.append(v if isinstance(v, (int, float)) else 0.0)
            return complex(parts[0], parts[1]), pos

        if ch == 'Z':
            if pos >= end:
                return 0.0, pos
            v = data[pos]
            pos += 1
            return {0: 0.0, 1: -0.0, 2: float('nan'),
                    3: copysign(float('nan'), -1.0),
                    4: float('inf'), 5: float('-inf')}.get(v, 0.0), pos

        if ch in ('c', 'a', 'u'):
            # null-terminated: strings and bytes
            zero = bytes(data[pos:]).find(b'\x00')
            if zero == -1:
                s_end = end
            else:
                s_end = pos + zero
            raw = bytes(data[pos:s_end])
            pos = min(s_end + 1, end)
            if ch in ('c', 'a'):
                # Python3 bytes or attribute name str (Py2 str)
                # Nuitka uses 'a' for attribute name (interned str Py3)
                try:
                    return raw.decode('utf-8'), pos
                except UnicodeDecodeError:
                    return raw, pos
            try:
                return raw.decode('utf-8', errors='replace'), pos
            except Exception:
                return raw, pos

        if ch == 'w':
            if pos >= end:
                return '', pos
            try:
                return bytes(data[pos:pos + 1]).decode('utf-8', errors='replace'), pos + 1
            except Exception:
                return '', pos + 1

        if ch == 'v':
            size, pos = self._unpack_vlq(data, pos)
            if pos + size > end:
                return '', end
            raw = bytes(data[pos:pos + size])
            return raw.decode('utf-8', errors='replace'), pos + size

        if ch == 'b':
            size, pos = self._unpack_vlq(data, pos)
            if pos + size > end:
                return b'', end
            return bytes(data[pos:pos + size]), pos + size

        if ch == 'd':
            if pos >= end:
                return b'', end
            return bytes(data[pos:pos + 1]), pos + 1

        if ch == 'B':
            size, pos = self._unpack_vlq(data, pos)
            if pos + size > end:
                return bytearray(), end
            return bytearray(data[pos:pos + size]), pos + size

        if ch == 'n':
            return None, pos
        if ch == 't':
            return True, pos
        if ch == 'F':
            return False, pos
        if ch == 's':
            return '', pos

        if ch in ('X', 'Q'):
            size, pos = self._unpack_vlq(data, pos)
            if pos + size > end:
                return b'', end
            return bytes(data[pos:pos + size]), pos + size

        if ch == ':':  # slice
            items = []
            for _ in range(3):
                v, pos = self._decode_one(data, pos, depth + 1)
                items.append(v)
            return ('slice', items[0], items[1], items[2]), pos

        if ch == ';':  # range/xrange
            items = []
            for _ in range(3):
                v, pos = self._decode_one(data, pos, depth + 1)
                items.append(v)
            return ('range', items[0], items[1], items[2]), pos

        if ch in ('M', 'A'):
            if pos >= end:
                return None, pos
            return self._anon_value(data[pos]), pos + 1

        if ch == 'r':  # builtin-special alias
            if pos >= end:
                return None, pos
            return self._special_value(data[pos]), pos + 1

        if ch in ('O', 'E'):
            zero = bytes(data[pos:]).find(b'\x00')
            s_end = end if zero == -1 else pos + zero
            try:
                return bytes(data[pos:s_end]).decode('utf-8', errors='replace'), min(s_end + 1, end)
            except Exception:
                return None, min(s_end + 1, end)

        if ch == 'K':
            v, pos = self._decode_one(data, pos, depth + 1)
            return v, pos

        if ch == 'C':
            # Code-object skeleton: (flags VLQ) (name constant) (line VLQ)
            # (arg_names constant) (arg_count VLQ) — store as tuple.
            _, pos = self._unpack_vlq(data, pos)            # flags
            fn, pos = self._decode_one(data, pos, depth + 1)
            _, pos = self._unpack_vlq(data, pos)            # line
            args, pos = self._decode_one(data, pos, depth + 1)
            _, pos = self._unpack_vlq(data, pos)            # argcount
            return (fn, args), pos

        if ch == 'H':  # UnionType 3.10+
            v, pos = self._decode_one(data, pos, depth + 1)
            return ('UnionType', v), pos

        if ch == '.':
            return None, pos

        # Unknown byte: treat as opaque separator
        return None, pos

    def _decode_one(self, data: memoryview, pos: int, depth: int = 0):
        """Decode one value with the canonical bounded constants grammar."""
        items, new_pos, diagnostics = _decode_constants_stream(
            bytes(data), 1, start_pos=pos, return_diagnostics=True,
            max_depth=max(0, self._DEPTH_LIMIT - max(0, int(depth))))
        self._last_decode_diagnostics = diagnostics
        return (items[0] if items else None), new_pos

    def _decode_count(self, data: memoryview, pos: int, count: int):
        """Decode *count* constants starting at *pos*. Returns (tuple, new_pos)."""
        items, new_pos, diagnostics = _decode_constants_stream(
            bytes(data),
            count,
            start_pos=pos,
            return_diagnostics=True,
        )
        self._last_decode_diagnostics = diagnostics
        return tuple(items), new_pos

    def _add_section(self, result: dict, name: str, items: tuple):
        """Add section to result, auto-disambiguating duplicate names."""
        if name in result:
            self._collision_idx += 1
            name = f"{name}_dup_{self._collision_idx}"
        result[name] = items

    # ---- top-level entry points ----

    def decode_blob(self, data, *, python_version=None,
                    commercial_bypass=None):
        """Decode Nuitka constants blob. Returns `dict[section_name, tuple]`.

        Mirrors `nuitka_deobfuscate.decode_blob(bytes)` in output but is
        stricter about the aggressive scan: it only considers byte ranges
        **not already covered** by the linear chain, so it can't produce
        truncated duplicates of already-decoded sections.

        Two scans:
          - Linear Chain: the well-formed, documented blob layout.
          - Aggressive Signature Scan: byte-by-byte probing for hidden /
            injected / corrupted sections. Restricted to the gaps the
            linear chain didn't cover.
        """
        if not isinstance(data, (bytes, bytearray, memoryview)):
            raise TypeError("data must be bytes-like")
        # One strict framing/grammar implementation is the canonical path.
        # The historical two-pass scanner remains below only as unreachable
        # documentation; accepting byte-by-byte salvage as real sections made
        # corrupt input look like recovered source.
        blob_diagnostics = {}
        chunks = parse_blob_modules(
            bytes(data), commercial_bypass, strict=True,
            diagnostics=blob_diagnostics)
        profile, profile_diagnostics = _ndl_select_constants_profile(
            chunks, python_version=python_version)
        sections = {}
        section_diagnostics = {}
        if not chunks or not blob_diagnostics.get('ok'):
            self._last_decode_diagnostics = {
                'blob': blob_diagnostics,
                'profile': profile_diagnostics,
                'sections': section_diagnostics,
            }
            return sections
        for section_name, section_data in chunks:
            values = parse_module_constants(
                section_data, python_version=python_version, profile=profile)
            section_diagnostics[section_name] = dict(values.diagnostics)
            sections[section_name] = tuple(values)
        self._last_decode_diagnostics = {
            'blob': blob_diagnostics,
            'profile': profile_diagnostics,
            'sections': section_diagnostics,
        }
        return sections

        mv = memoryview(data) if not isinstance(data, memoryview) else data
        end = len(mv)
        result = {}
        covered = []  # list of (start, end) ranges eaten by linear chain

        # ---- SCAN 1: Linear Chain ----
        w = 8  # skip 8-byte header (CRC32 + size)
        while w + 6 < end:
            # consume NUL padding
            while w < end and mv[w] == 0:
                w += 1
            if w + 6 >= end:
                break

            name_start = w
            p = w
            while p < end and mv[p] != 0:
                p += 1

            if p + 6 >= end:
                break

            s_size = struct.unpack_from('<I', mv, p + 1)[0]
            s_count = struct.unpack_from('<H', mv, p + 5)[0]

            if (0 < s_size < (end - p - 5) and
                    0 < s_count < 65000):
                # BUG in the collaborator's C code: it used
                #     sec_end = data_ptr + s_size      # 2 bytes PAST the real end
                # but `s_size` is the length of the `part` emitted by
                # Nuitka's DataComposer, which is
                #     part = struct.pack("H", count) + constants + b"."
                # so it already includes the u16 count + the trailing "." byte.
                # Therefore the chunk ends at p + 5 + s_size, not p + 7 + s_size.
                # That off-by-2 was consuming the first two characters of every
                # *next* chunk name (e.g. "xrpl.asyncio.*" -> "pl.asyncio.*",
                # "urllib.parse.*" -> "llib.parse.*"). Fixed here.
                data_ptr = p + 7               # start of the actual constants
                sec_end = p + 5 + s_size        # end of the full part (= next name start)
                constants_end = sec_end - 1    # skip the trailing "." marker

                name_bytes = bytes(mv[name_start:p])
                # Strict sanity: a real Nuitka chunk name is either empty
                # (main module), `.bytecode`, or a dotted Python identifier.
                # Reject anything with non-printable characters or obviously
                # truncated fragments — those are alignment errors where we
                # landed mid-chunk-data and should keep scanning.
                name_ok = True
                try:
                    name = name_bytes.decode('ascii')
                except UnicodeDecodeError:
                    try:
                        name = name_bytes.decode('utf-8', errors='strict')
                    except UnicodeDecodeError:
                        name_ok = False
                        name = bytes(name_bytes).decode('utf-8', errors='replace')
                if name_ok and name:
                    # Names must be ident-chars + dots + underscores; or start
                    # with a single '.' (internal chunks like `.bytecode`).
                    core = name[1:] if name.startswith('.') else name
                    if not all(c.isalnum() or c in '._-' for c in core):
                        name_ok = False

                if name_ok:
                    # Decode constants up to constants_end (excl trailing ".")
                    section_view = memoryview(bytes(mv[data_ptr:constants_end]))
                    items, _consumed = self._decode_count(section_view, 0, s_count)
                    # Accept liberally: if the name passed the ASCII check and
                    # the body decoded at least partially, keep the section.
                    # Tighter checks make decoding O(N^2) on large blobs
                    # because every reject forces a 1-byte-at-a-time retry.
                    self._add_section(result, name, items)
                    covered.append((name_start, sec_end))
                    w = sec_end
                    continue

                # Name looked wrong — slide past the name we just tried.
                w = name_start + 1
                continue

            w = p + 1

        def _in_covered(off):
            # Binary-search-free but we have at most a few thousand ranges
            for s, e in covered:
                if s <= off < e:
                    return True
            return False

        # ---- SCAN 2: Aggressive Signature Scan (gaps only) ----
        scan_p = 8
        while scan_p + 7 < end:
            # Skip ranges we already covered with the linear-chain scan
            if _in_covered(scan_p):
                # Jump to the end of the covering range
                for s, e in covered:
                    if s <= scan_p < e:
                        scan_p = e
                        break
                continue

            s_size = struct.unpack_from('<I', mv, scan_p)[0]
            s_count = struct.unpack_from('<H', mv, scan_p + 4)[0]
            next_tag = mv[scan_p + 6]

            if (0 < s_size < (end - scan_p - 6) and
                    0 < s_count < 65000 and
                    next_tag in self._VALID_TAGS):

                sec_view = memoryview(bytes(mv[scan_p + 6:scan_p + 6 + s_size]))
                items, _ = self._decode_count(sec_view, 0, s_count)
                if items:
                    discovered_name = "hidden_segment"
                    if scan_p - 1 >= 0 and mv[scan_p - 1] == 0:
                        name_scan = scan_p - 2
                        while name_scan >= 0 and 32 <= mv[name_scan] < 127:
                            name_scan -= 1
                        candidate = bytes(mv[name_scan + 1:scan_p - 1])
                        if candidate and all(32 <= c < 127 for c in candidate):
                            discovered_name = candidate.decode('ascii', errors='replace')

                    name_buf = f"discovered_{discovered_name}_at_{scan_p}"
                    self._add_section(result, name_buf, items)
                    scan_p += 6 + s_size
                    continue

            scan_p += 1

        return result

    def decode_at_offset(self, data, offset: int):
        """Decode a single constant starting at a specific byte offset."""
        items, _ = _decode_constants_stream(bytes(data), 1, start_pos=offset)
        return items[0] if items else None


# ---------------------------------------------------------------------------
#  2. XDIS-BASED RAW CODE OBJECT SCANNER
#      (port of run_extract.py's raw_scan_for_code_objects + version probing)
# ---------------------------------------------------------------------------

# xdis is an optional dependency (pip install xdis). When available we use it
# for cross-Python-version marshal parsing which is much more reliable than
# the running interpreter's native marshal module. xdis 6.x does not export
# TYPE_CODE / TYPE_STRING as public symbols so we define them inline — the
# values are stable in CPython marshal.c across every 3.x version.
_XDIS_TYPE_CODE = b'c'       # 0x63 — TYPE_CODE in Python/marshal.c
_XDIS_TYPE_STRING = b's'     # 0x73 — TYPE_STRING (Python 2) / TYPE_ASCII (3.4+)
_XDIS_FLAG_REF = 0x80        # set on marshaled object if it may be referenced

try:
    import xdis.marsh as _xdis_marshal
    from xdis.magics import (
        by_version as _xdis_by_version,
        magic2int as _xdis_magic2int,
        magic_int2tuple as _xdis_magic_int2tuple,
    )
    from xdis.unmarshal import load_code as _xdis_load_code
    # Try to use xdis's own constants if present (newer versions)
    try:
        from xdis.unmarshal import (
            FLAG_REF as _XDIS_FLAG_REF_X,
            TYPE_CODE as _XDIS_TYPE_CODE_X,
            TYPE_STRING as _XDIS_TYPE_STRING_X,
        )
        _XDIS_FLAG_REF = _XDIS_FLAG_REF_X
        _XDIS_TYPE_CODE = _XDIS_TYPE_CODE_X
        _XDIS_TYPE_STRING = _XDIS_TYPE_STRING_X
    except ImportError:
        pass  # fall back to the hardcoded values above
    XDIS_AVAILABLE = True
except ImportError:
    _xdis_marshal = None
    _xdis_by_version = {}
    XDIS_AVAILABLE = False


def _marshal_code_tags():
    """Return (all_tags, code_tag_pattern, version_hint_pattern). Empty if no xdis."""
    if not XDIS_AVAILABLE:
        return (), None, None
    values = (ord(_XDIS_TYPE_CODE), _XDIS_FLAG_REF | ord(_XDIS_TYPE_CODE))
    tags = tuple(bytes((v,)) for v in values)
    code_pat = re.compile(b"[" + re.escape(bytes(values)) + b"]")
    hint_pat = re.compile(b"[" + re.escape(b"\xf3" + bytes(values)) + b"]")
    return tags, code_pat, hint_pat


MARSHAL_CODE_TAGS, MARSHAL_CODE_TAG_PATTERN, MARSHAL_VERSION_HINT_TAG_PATTERN = _marshal_code_tags()
MARSHAL_VERSION_HINT_TAGS = (b"\xf3",) + MARSHAL_CODE_TAGS
MARSHAL_PYC_PATH_PATTERN = re.compile(rb"([A-Za-z0-9_./\\-]{1,260}\.py)")


class _MemoryReader:
    """Minimal file-like reader over a bytes buffer."""
    def __init__(self, data, start=0):
        self._data = data if isinstance(data, memoryview) else memoryview(data)
        self._pos = start

    def read(self, n=-1):
        if n < 0:
            n = len(self._data) - self._pos
        end = min(len(self._data), self._pos + n)
        chunk = bytes(self._data[self._pos:end])
        self._pos = end
        return chunk


def _xdis_get_magic_int(version):
    if not XDIS_AVAILABLE:
        return None
    if isinstance(version, tuple):
        version = f"{version[0]}.{version[1]}"
    magic = _xdis_by_version.get(version)
    if not magic:
        return None
    return _xdis_magic2int(bytes(magic))


def _xdis_version_sort_key(version):
    major, minor = version.split(".", 1)
    return int(major), int(minor)


def guess_version_from_marshal_bytes(data: bytes):
    """Fast structural guess at Python version from a marshal code-object header."""
    if not data or data[0:1] not in (b"\xe3", b"\x63"):
        return None
    if len(data) < 25:
        return None
    try:
        argcount = struct.unpack_from("<I", data, 1)[0]
        kwonlycount = struct.unpack_from("<I", data, 9)[0]
        stacksize = struct.unpack_from("<I", data, 17)[0]
        flags = struct.unpack_from("<I", data, 21)[0]
        posonlycount = struct.unpack_from("<I", data, 5)[0]
        nlocals = struct.unpack_from("<I", data, 13)[0]
        if argcount > 255 or kwonlycount > 255 or stacksize > 65535:
            kw2 = struct.unpack_from("<I", data, 5)[0]
            nl2 = struct.unpack_from("<I", data, 9)[0]
            fl2 = struct.unpack_from("<I", data, 17)[0]
            if kw2 <= 255 and nl2 <= 65535 and fl2 >= 0:
                return "3.7"
        lower_bound = "3.6" if flags & 0x0200 else "3.5"
        if posonlycount <= argcount and stacksize <= 65535 and nlocals <= 65535:
            if flags & 0x0100 and not (flags & 0x0200):
                return "3.8"
            return "3.8+"
        return lower_bound
    except Exception:
        return None


def _marshal_candidate_versions(version_hint):
    if not XDIS_AVAILABLE:
        return []
    versions = sorted(
        {v for v in _xdis_by_version
         if re.fullmatch(r"\d+\.\d+", v) and _xdis_version_sort_key(v) >= (3, 5)},
        key=_xdis_version_sort_key, reverse=True)
    if version_hint is None:
        return versions
    if version_hint.endswith("+"):
        lb = _xdis_version_sort_key(version_hint[:-1])
        prio = [v for v in versions if _xdis_version_sort_key(v) >= lb]
        fb = [v for v in versions if _xdis_version_sort_key(v) < lb]
        return prio + fb
    if version_hint in versions:
        return [version_hint] + [v for v in versions if v != version_hint]
    return versions


def _xdis_looks_like_code_header(data, offset, magic_int):
    if not XDIS_AVAILABLE or magic_int is None:
        return False
    version = _xdis_magic_int2tuple(magic_int)
    field_count = 1  # argcount
    if version >= (3, 8):
        field_count += 1  # posonlyargcount
    if version >= (3, 0):
        field_count += 1  # kwonlyargcount
    if version < (3, 11):
        field_count += 1  # nlocals
    field_count += 2  # stacksize, flags
    header_end = offset + 1 + (field_count * 4)
    if len(data) < header_end + 1:
        return False
    fields = struct.unpack_from("<" + ("I" * field_count), data, offset + 1)
    cur = 0
    if fields[cur] > 4096:
        return False
    cur += 1
    if version >= (3, 8):
        if fields[cur] > 4096:
            return False
        cur += 1
    if version >= (3, 0):
        if fields[cur] > 4096:
            return False
        cur += 1
    if version < (3, 11):
        if fields[cur] > 65536:
            return False
        cur += 1
    stacksize = fields[cur]
    flags = fields[cur + 1]
    if stacksize > 65536:
        return False
    if flags > 0x3FFFFFFF:
        return False
    next_tag = data[header_end]
    return next_tag in (ord(_XDIS_TYPE_STRING), _XDIS_FLAG_REF | ord(_XDIS_TYPE_STRING))


def _xdis_try_detect_code_object(data, offset, magic_int):
    if not XDIS_AVAILABLE or magic_int is None or len(data) - offset < 32:
        return None
    # xdis' load_code prints "Unknown type N (hex ...)" on stderr for every
    # failing probe. During a raw scan we expect MANY failures, so we must
    # redirect stdout+stderr to a sink for the duration of the call.
    import io, contextlib
    sink = io.StringIO()
    try:
        with contextlib.redirect_stdout(sink), contextlib.redirect_stderr(sink):
            reader = _MemoryReader(data, offset)
            obj = _xdis_load_code(reader, magic_int)
    except Exception:
        return None
    name = type(obj).__name__
    if name == 'code' or name.startswith('Code'):
        return obj
    return None


def _xdis_try_load_code_object(data, offset, magic_int):
    if not _xdis_looks_like_code_header(data, offset, magic_int):
        return None
    return _xdis_try_detect_code_object(data, offset, magic_int)


def _xdis_score_code_object(co):
    score = 3
    score += len(getattr(co, 'co_consts', ()) or ())
    score += len(getattr(co, 'co_varnames', ()) or ())
    score += int(bool(getattr(co, 'co_filename', None)))
    return score


def xdis_detect_version_from_marshal(data: bytes):
    """Scored probe of candidate versions against marshal code-object offsets."""
    if not XDIS_AVAILABLE:
        return None
    version_hint = guess_version_from_marshal_bytes(data)
    candidates = _marshal_candidate_versions(version_hint)
    probe_offsets = [m.start() for m in MARSHAL_VERSION_HINT_TAG_PATTERN.finditer(data)]
    if not probe_offsets and data[:1] in MARSHAL_VERSION_HINT_TAGS:
        probe_offsets = [0]
    if not probe_offsets:
        return None
    scores = {}
    for ver in candidates:
        magic_int = _xdis_get_magic_int(ver)
        best = 0
        for off in probe_offsets[:128]:
            obj = _xdis_try_detect_code_object(data, off, magic_int)
            if obj is None:
                continue
            best = max(best, _xdis_score_code_object(obj))
            if best >= 4:
                break
        if best > 0:
            scores[ver] = best
    if not scores:
        return None
    best_score = max(scores.values())
    winners = [version for version, score in scores.items()
               if score == best_score]
    # Marshal layouts are shared by several minor releases. A tie is unknown,
    # never an invitation to choose the host or newest candidate.
    return winners[0] if len(winners) == 1 else None


def xdis_raw_scan_for_code_objects(raw: bytes, python_version):
    """Scan raw blob for marshal code-object tags; return [(offset, code_obj), ...].

    Replaces the standard section-based scan for Nuitka blobs where bytecode
    is embedded in the raw byte stream, not wrapped in structured sections.
    Only available when xdis is installed.
    """
    if not XDIS_AVAILABLE:
        return []
    magic_int = _xdis_get_magic_int(python_version)
    if magic_int is None:
        return []
    results = []
    raw_view = memoryview(raw)
    last = -8
    for m in MARSHAL_CODE_TAG_PATTERN.finditer(raw):
        off = m.start()
        if off - last < 8:
            continue
        obj = _xdis_try_load_code_object(raw_view, off, magic_int)
        if obj is None:
            continue
        results.append((off, obj))
        last = off
    return results


def _xdis_code_to_native_recursive(code_obj):
    """Convert an xdis portable code object to a native CodeType recursively."""
    if hasattr(code_obj, 'to_native'):
        native = code_obj.to_native()
    else:
        native = code_obj

    if not hasattr(native, 'replace'):
        return native

    def _convert_value(value):
        if hasattr(value, 'to_native'):
            return _xdis_code_to_native_recursive(value)
        if isinstance(value, tuple):
            return tuple(_convert_value(item) for item in value)
        if isinstance(value, list):
            return [_convert_value(item) for item in value]
        if isinstance(value, dict):
            return {k: _convert_value(v) for k, v in value.items()}
        return value

    native_consts = tuple(_convert_value(value) for value in getattr(native, 'co_consts', ()))
    try:
        return native.replace(co_consts=native_consts)
    except Exception:
        return native


def _xdis_code_matches_module_name(code_obj, module_name: str) -> bool:
    """Best-effort check that a raw-scanned code object belongs to a module."""
    if not module_name:
        return False

    filename = str(getattr(code_obj, 'co_filename', '') or '').replace('\\', '/').lower()
    module_name = module_name.replace('\\', '/').lower()
    leaf = module_name.rsplit('/', 1)[-1].rsplit('.', 1)[-1]
    module_path = module_name.replace('.', '/')

    if filename.endswith(module_path + '.py') or filename.endswith(module_path + '/__init__.py'):
        return True
    if filename.endswith(leaf + '.py') or filename.endswith(leaf + '/__init__.py'):
        return True
    if leaf and (f'/{leaf}.py' in filename or filename.endswith(f'/{leaf}/__init__.py')):
        return True
    return False


def xdis_extract_path_from_code(co):
    try:
        if hasattr(co, 'co_filename'):
            return str(co.co_filename)
        if hasattr(co, 'co_qualname'):
            return str(co.co_qualname)
    except Exception:
        pass
    return None


def xdis_extract_code_label(co):
    try:
        for attr in ('co_qualname', 'co_name', 'co_filename'):
            value = getattr(co, attr, None)
            if not value:
                continue
            label = str(value).strip().replace("\\", "/")
            if not label:
                continue
            if attr == 'co_filename' and ":" in label:
                label = label.split(":", 1)[1]
            label = label.lstrip("/")
            if label == "<module>":
                label = "module"
            if attr == 'co_filename':
                label = Path(label).stem or label
            label = re.sub(r'[<>:"/\\|?*\x00]+', "_", label).strip("._ ")
            if label:
                return label[:96]
    except Exception:
        pass
    return None


def xdis_extract_path_from_marshaled_bytes(data):
    try:
        candidates = []
        for match in MARSHAL_PYC_PATH_PATTERN.finditer(bytes(data)[:65536]):
            c = match.group(1).decode('utf-8', errors='ignore').replace("\\", "/").lstrip("./")
            if c:
                candidates.append(c)
        if not candidates:
            return None
        return max(candidates, key=lambda v: (v.count("/"), len(v)))
    except Exception:
        return None


def xdis_sanitize_filename(filepath):
    filepath = filepath.replace("\\", "/")
    if ":" in filepath:
        filepath = filepath.split(":", 1)[1]
    filepath = filepath.lstrip("/")
    for p in ["module.", "nuitka_build/"]:
        if filepath.startswith(p):
            filepath = filepath[len(p):]
    return filepath


# ---------------------------------------------------------------------------
#  3. OMNI UNIFIED NUITKA DECOMPILER FRAMEWORK
#      (full port of omni_nuitka_framework.py — ~760 lines)
# ---------------------------------------------------------------------------

class OmniNuitkaTags:
    ARG = 'a'; CLOSURE = 'c'; DICT = 'd'; FUNCTION = 'f'; GLOBALS = 'g'
    TUPLE = 't'; LIST = 'l'; FLOAT = 'F'; INT = 'I'; STRING = 's'
    BYTES = 'y'; BOOL_TRUE = 'T'; BOOL_FALSE = 'F'; NONE = 'N'
    CODE_OBJ = 'C'; MODULE = 'm'; METHOD = 'M'; USER_DEF = 'u'
    PRIVATE_DEF = 'p'; OBJECT_TYPE = 'O'


def _omni_b2s_safe(val):
    if val is None:
        return "None"
    if isinstance(val, str):
        return val
    if isinstance(val, (int, float, bool)):
        return str(val)
    if isinstance(val, (tuple, list, dict, set, frozenset)):
        return str(val)
    if hasattr(val, 'decode'):
        try:
            return val.decode('utf-8')
        except Exception:
            return val.decode('latin-1', errors='replace')
    return repr(val)


def _omni_is_b64_image(val):
    s = _omni_b2s_safe(val) if isinstance(val, (bytes, bytearray)) else str(val)
    return 'iVBORw0KGgo' in s or 'JFIF' in s


def _omni_is_annotation_dict(d):
    if not d or len(d) > 25:
        return False
    for k in d.keys():
        key = _omni_b2s_safe(k)
        if not key.isidentifier() and key != 'return':
            return False
    return True


def _omni_decode_annotation_blob(d):
    ann = {}
    if not isinstance(d, dict):
        return ann
    for k, v in d.items():
        key = _omni_b2s_safe(k)
        if v is None:
            ann[key] = 'Any'
        elif v is True or v is False:
            ann[key] = 'bool'
        elif isinstance(v, int):
            ann[key] = 'int'
        elif isinstance(v, float):
            ann[key] = 'float'
        elif isinstance(v, str):
            ann[key] = v if v[0:1].isupper() else 'str'
        elif isinstance(v, (bytes, bytearray)):
            s = _omni_b2s_safe(v)
            ann[key] = s if s[0:1].isupper() else 'str'
        else:
            ann[key] = type(v).__name__
    return ann


def _omni_parse_packed_signature(raw_bytes):
    """Decode a null-separated packed signature blob (Nuitka encodes these for
    runtime introspection of a compiled function/class)."""
    if isinstance(raw_bytes, str):
        raw_bytes = raw_bytes.encode('utf-8', errors='replace')
    segments = raw_bytes.split(b'\x00')
    method_refs, args, types = [], [], {}
    for seg in segments:
        if not seg:
            continue
        text = seg.decode('utf-8', errors='replace')
        if not text:
            continue
        tag, name = text[0], text[1:]
        if tag == OmniNuitkaTags.ARG:
            args.append(name)
        elif tag == OmniNuitkaTags.USER_DEF:
            if '.' in name and name[0:1].isupper() and name.split('.')[0].isidentifier():
                method_refs.append(name)
        elif tag == OmniNuitkaTags.OBJECT_TYPE:
            if args:
                types[args[-1]] = name
        elif tag == OmniNuitkaTags.PRIVATE_DEF:
            if name and '.' in name and name.split('.')[0][0:1].isupper():
                method_refs.append(name)
    return method_refs, args, types


# -- AST node framework (minimal reimplementation) --

class _OmniASTNode:
    def render(self, indent=0):
        raise NotImplementedError


class _OmniCodeBlock(_OmniASTNode):
    def __init__(self):
        self.children = []

    def add(self, node):
        self.children.append(node)

    def render(self, indent=0):
        if not self.children:
            return " " * (indent * 4) + "pass\n"
        return "".join(c.render(indent) for c in self.children)


class _OmniFunctionCall(_OmniASTNode):
    def __init__(self, func_name, args, kwargs, inline=False):
        self.func_name = func_name
        self.args = args
        self.kwargs = kwargs
        self.inline = inline

    def render(self, indent=0):
        pad = " " * (indent * 4) if not self.inline else ""
        arg_str = ", ".join(str(a) for a in self.args)
        kw_str = ", ".join(f"{k}={v}" for k, v in self.kwargs.items())
        combined = ", ".join(filter(bool, [arg_str, kw_str]))
        res = f"{pad}{self.func_name}({combined})"
        return res if self.inline else res + "\n"


class _OmniAssignment(_OmniASTNode):
    def __init__(self, target, value, annotation=None):
        self.target = target
        self.value = value
        self.annotation = annotation

    def render(self, indent=0):
        pad = " " * (indent * 4)
        if self.annotation:
            return f"{pad}{self.target}: {self.annotation} = {self.value}\n"
        return f"{pad}{self.target} = {self.value}\n"


class _OmniRawString(_OmniASTNode):
    def __init__(self, text):
        self.text = text

    def render(self, indent=0):
        return " " * (indent * 4) + self.text + "\n"


class _OmniRawComment(_OmniASTNode):
    def __init__(self, text):
        self.text = text

    def render(self, indent=0):
        return " " * (indent * 4) + "# " + self.text + "\n"


class _OmniReturn(_OmniASTNode):
    def __init__(self, val="None"):
        self.val = val

    def render(self, indent=0):
        return " " * (indent * 4) + f"return {self.val}\n"


class _OmniClassDef(_OmniASTNode):
    def __init__(self, name):
        self.name = name
        self.bases = []
        self.attributes = set()
        self.methods = []
        self.slots = None

    def render(self, indent=0):
        pad = " " * (indent * 4)
        base_str = f"({', '.join(self.bases)})" if self.bases else ""
        res = f"\n{pad}class {self.name}{base_str}:\n"
        ip = " " * ((indent + 1) * 4)
        has_content = False
        if self.slots:
            res += f"{ip}__slots__ = {self.slots}\n\n"
            has_content = True
        if self.attributes:
            res += f"{ip}# Recovered Instance Attributes:\n"
            for a in sorted(self.attributes):
                res += f"{ip}# self.{a}\n"
            res += "\n"
            has_content = True
        for m in self.methods:
            res += m.render(indent + 1)
            has_content = True
        if not has_content:
            res += f"{ip}pass\n"
        return res


class _OmniMethodDef(_OmniASTNode):
    def __init__(self, name, args, annotations, return_type):
        self.name = name
        self.args = args
        self.annotations = annotations
        self.return_type = return_type
        self.body = _OmniCodeBlock()
        self.is_async = False
        self.is_staticmethod = False
        self.is_classmethod = False
        self.internals = []
        self.locals_hints = []

    def render(self, indent=0):
        pad = " " * (indent * 4)
        res = ""
        if self.is_staticmethod:
            res += f"{pad}@staticmethod\n"
        if self.is_classmethod:
            res += f"{pad}@classmethod\n"
        prefix = "async def " if self.is_async else "def "
        sig = []
        for arg in self.args:
            if arg in self.annotations and self.annotations[arg]:
                sig.append(f"{arg}: {self.annotations[arg]}")
            else:
                sig.append(arg)
        ret = f" -> {self.return_type}" if self.return_type else ""
        res += f"{pad}{prefix}{self.name}({', '.join(sig)}){ret}:\n"
        res += self.body.render(indent + 1)
        res += "\n"
        return res


class OmniDecompiler:
    """AST-based heuristic decompiler from collaborator's omni_nuitka_framework.

    Reconstructs classes, methods and signatures by pattern-matching on the
    items decoded from a constants blob section. Emits Python pseudo-source
    with inline C-API trace comments (what Nuitka would have generated).
    """

    def __init__(self):
        from collections import OrderedDict
        self.classes = OrderedDict()
        self.api_endpoints = set()
        self.images = OrderedDict()
        self.vk_table = OrderedDict()
        self.current_class = None
        self.last_method_cls = None
        self.last_method_name = None
        self.last_item_name = None

    def ensure_class(self, cls_name):
        if cls_name not in self.classes:
            self.classes[cls_name] = _OmniClassDef(cls_name)

    def ensure_method(self, cls_name, method_name, args=None, annotations=None, return_type=None):
        self.ensure_class(cls_name)
        cls_node = self.classes[cls_name]
        existing = next((m for m in cls_node.methods if m.name == method_name), None)
        if not existing:
            m = _OmniMethodDef(method_name, args or ['self'], annotations or {}, return_type)
            cls_node.methods.append(m)
            return m
        if args and existing.args == ['self']:
            existing.args = args
        if annotations:
            existing.annotations.update(annotations)
        if return_type and not existing.return_type:
            existing.return_type = return_type
        return existing

    def run_pass_1_structural_mapping(self, blob_items):
        n = len(blob_items)

        def _t(v):
            if v is None:
                return 'none'
            if isinstance(v, bool):
                return 'bool'
            if isinstance(v, int):
                return 'int'
            if isinstance(v, float):
                return 'float'
            if isinstance(v, str):
                return 'str'
            if isinstance(v, (bytes, bytearray)):
                if b'\x00' in v and len(v) > 4:
                    return 'packed'
                return 'bytes'
            if isinstance(v, tuple):
                return 'tuple'
            if isinstance(v, list):
                return 'list'
            if isinstance(v, dict):
                return 'dict'
            if isinstance(v, (set, frozenset)):
                return 'set'
            return 'other'

        i = 0
        while i < n:
            item = blob_items[i]
            t = _t(item)
            if t == 'none':
                i += 1
                continue

            if t == 'bytes':
                name = _omni_b2s_safe(item)
                if name.endswith('_B64') and i + 1 < n and _t(blob_items[i + 1]) in ('str', 'bytes'):
                    if _omni_is_b64_image(blob_items[i + 1]):
                        self.images[name] = len(_omni_b2s_safe(blob_items[i + 1]))
                        i += 2
                        continue
                if name.startswith('VK_'):
                    vk_val = None
                    if i + 1 < n and _t(blob_items[i + 1]) == 'int':
                        vk_val = blob_items[i + 1]
                    elif i > 0 and _t(blob_items[i - 1]) == 'int':
                        vk_val = blob_items[i - 1]
                    self.vk_table[name] = vk_val
                    i += 1
                    continue

            is_method = False
            if t in ('str', 'bytes'):
                name = _omni_b2s_safe(item)
                if '.' in name and not name.startswith('.') and not name.startswith('\\'):
                    parts = name.split('.', 1)
                    if (len(parts) == 2 and parts[0]
                            and (parts[0][0:1].isupper() or parts[0][0:1] == '_')
                            and parts[1].isidentifier()):
                        cls, method = parts[0], parts[1]
                        self.ensure_method(cls, method)
                        self.current_class = cls
                        self.last_method_cls = cls
                        self.last_method_name = method
                        is_method = True
                        if i + 1 < n and _t(blob_items[i + 1]) == 'dict':
                            if _omni_is_annotation_dict(blob_items[i + 1]):
                                ann = _omni_decode_annotation_blob(blob_items[i + 1])
                                arg_names = [k for k in ann.keys() if k != 'return']
                                ret = ann.get('return')
                                self.ensure_method(cls, method,
                                                   args=['self'] + arg_names if arg_names else None,
                                                   annotations=ann, return_type=ret)

            if t == 'packed':
                method_refs, args, ptypes = _omni_parse_packed_signature(item)
                for ref in method_refs:
                    parts = ref.split('.', 1)
                    if len(parts) == 2 and (parts[0][0:1].isupper() or parts[0][0:1] == '_'):
                        self.ensure_method(parts[0], parts[1])
                        self.current_class = parts[0]
                        self.last_method_cls, self.last_method_name = parts[0], parts[1]
                if args and method_refs:
                    last_ref = method_refs[-1]
                    parts = last_ref.split('.', 1)
                    if len(parts) == 2:
                        self.ensure_method(parts[0], parts[1],
                                           args=['self'] + args, annotations=ptypes)
                elif args and self.last_method_cls and self.last_method_name:
                    self.ensure_method(self.last_method_cls, self.last_method_name,
                                       args=['self'] + args, annotations=ptypes)
                i += 1
                continue

            if self.last_method_cls and self.last_method_name:
                meth_node = next(
                    (m for m in self.classes[self.last_method_cls].methods
                     if m.name == self.last_method_name), None)
                if meth_node:
                    if t == 'dict' and not _omni_is_annotation_dict(item):
                        dec = {}
                        for kx, vx in list(item.items())[:50]:
                            dx = repr(vx)[:250] if not isinstance(vx, (bytes, bytearray)) else _omni_b2s_safe(vx)[:250]
                            dec[_omni_b2s_safe(kx)] = dx
                        meth_node.internals.append(('dict', dec))
                    elif t == 'list':
                        meth_node.internals.append(('list', [_omni_b2s_safe(x) for x in item[:100]]))
                    elif t == 'tuple':
                        decoded = tuple(_omni_b2s_safe(x) for x in item)
                        if self.last_item_name == '__slots__' and self.current_class:
                            self.classes[self.current_class].slots = decoded
                        elif all(isinstance(x, str) for x in decoded) and len(decoded) >= 2:
                            meth_node.locals_hints.append(decoded)
                        else:
                            meth_node.internals.append(('tuple', decoded))
                    elif t in ('int', 'float', 'bool'):
                        meth_node.internals.append(('literal', item))
                    elif t in ('str', 'bytes'):
                        name = _omni_b2s_safe(item)
                        if t == 'bytes' and name.startswith('_') and self.current_class and len(name) > 2 and not name.startswith('__'):
                            self.classes[self.current_class].attributes.add(name)
                        if 'http' in name.lower() or '/functions/' in name:
                            self.api_endpoints.add(name)
                        if len(name) > 2 and not name.startswith('VK_') and not is_method:
                            meth_node.internals.append(('str', name))

            if t in ('str', 'bytes'):
                self.last_item_name = _omni_b2s_safe(item)
            else:
                self.last_item_name = None
            i += 1

    def run_pass_2_ast_synthesis(self):
        for cls_name, cls_node in self.classes.items():
            for meth_node in cls_node.methods:
                internals = meth_node.internals
                locals_hints = meth_node.locals_hints
                if locals_hints:
                    meth_node.body.add(_OmniRawComment("--- Locals Discovery ---"))
                    for hint in locals_hints:
                        valid = [v for v in hint if str(v).isidentifier()]
                        if valid:
                            meth_node.body.add(_OmniAssignment(", ".join(valid), "None"))
                if not internals:
                    meth_node.body.add(_OmniRawString("pass"))
                    continue
                meth_node.body.add(_OmniRawComment("--- Heuristic Execution Trace ---"))
                i = 0
                n = len(internals)
                while i < n:
                    typ, val = internals[i]
                    if typ == 'dict':
                        ds = "{\n"
                        for k, v in val.items():
                            ds += f"            {repr(k)}: {v},\n"
                        ds += "        }"
                        meth_node.body.add(_OmniAssignment(f"config_mapping_{i}", ds))
                        meth_node.body.add(_OmniRawComment(f"C-API: PyObject *dict_{i} = _PyDict_NewPresized({len(val)});"))
                    elif typ == 'list':
                        ls = "[\n"
                        for x in val:
                            ls += f"            {repr(x)},\n"
                        ls += "        ]"
                        meth_node.body.add(_OmniAssignment(f"sequence_array_{i}", ls))
                        meth_node.body.add(_OmniRawComment(f"C-API: PyObject *list_{i} = PyList_New({len(val)});"))
                    elif typ == 'tuple' and len(val) == 1 and isinstance(val[0], str):
                        target = val[0]
                        if any(m.name == target for m in cls_node.methods):
                            meth_node.body.add(_OmniFunctionCall(f"self.{target}", [], {}))
                            meth_node.body.add(_OmniRawComment(
                                f"C-API: PyObject *func_{i} = LOOKUP_ATTRIBUTE(tstate, par_self, MAKE_STRING(\"{target}\"));"))
                        else:
                            meth_node.body.add(_OmniAssignment(f"state_flags_{i}", repr(val)))
                    elif typ == 'str' and val in [m.name for m in cls_node.methods]:
                        meth_node.body.add(_OmniAssignment(f"target_callback_{i}", f"self.{val}"))
                    elif typ == 'str' and val in cls_node.attributes:
                        meth_node.body.add(_OmniAssignment(f"PY_OBJ_ATTR_{i}", f"getattr(self, {repr(val)}, None)"))
                    elif typ == 'str' and ('http' in val.lower() or '/functions/' in val):
                        meth_node.body.add(_OmniAssignment(f"api_res_{i}", f"requests.request('GET', {repr(val)})"))
                    elif typ == 'literal':
                        if isinstance(val, int) and 10 < val < 10000:
                            meth_node.body.add(_OmniFunctionCall("time.sleep", [f"{val} / 1000.0"], {}))
                        elif isinstance(val, float):
                            meth_node.body.add(_OmniAssignment(f"calc_threshold_{i}", val))
                        else:
                            meth_node.body.add(_OmniAssignment(f"flag_{i}", val))
                    elif typ == 'str':
                        if len(val) > 4 and ('error' in val.lower() or 'warn' in val.lower() or 'success' in val.lower()):
                            meth_node.body.add(_OmniFunctionCall("logger.log", [repr(val)], {}))
                        else:
                            meth_node.body.add(_OmniAssignment(f"string_const_{i}", repr(val)))
                    elif typ == 'tuple':
                        if len(val) > 1 and any(isinstance(x, str) and (x.endswith('_color')) for x in val):
                            meth_node.body.add(_OmniAssignment(f"ui_widget_bind_{i}", f"apply_kwargs(**{repr(val)})"))
                        else:
                            meth_node.body.add(_OmniAssignment(f"tuple_block_{i}", repr(val)))
                    i += 1
                meth_node.body.add(_OmniReturn())


# ---------------------------------------------------------------------------
#  NUITKA STATIC DISASSEMBLER — reconstruct function logic from native code
# ---------------------------------------------------------------------------

try:
    import capstone as _capstone
    from capstone import x86 as _capstone_x86
    CAPSTONE_AVAILABLE = True
except ImportError:
    _capstone = None
    _capstone_x86 = None
    CAPSTONE_AVAILABLE = False


_NDL_IDENT_RE = re.compile(r'^[A-Za-z_]\w*$')


def _ndl_sanitize_def_args(sig):
    """Make recovered code-object argument names valid Python identifiers.

    CPython uses ``.0``/``.1`` ... as the implicit positional parameters of
    comprehensions and generator expressions, and Nuitka streams those names
    verbatim into co_varnames.  Rendering them literally yields
    ``def f(.0):`` - a hard syntax error that made whole modules unparseable.
    Rewrite every non-identifier entry to a deterministic positional alias
    (``__pos<N>`` by argument position), preserving ``*``/``**`` prefixes and
    the bare ``*`` keyword-only separator, never colliding with a real
    sibling argument name.  Version-independent: the rule is purely "is this
    a valid identifier", so it cannot regress any Python or Nuitka release.
    """
    if not sig:
        return sig
    taken = set()
    for a in sig:
        if isinstance(a, str) and a != '*':
            taken.add(a.lstrip('*'))
    out = []
    for pos, a in enumerate(sig):
        if not isinstance(a, str):
            a = str(a)
        if a == '*':
            out.append(a)
            continue
        prefix = ''
        name = a
        while name.startswith('*'):
            prefix += '*'
            name = name[1:]
        if _NDL_IDENT_RE.match(name):
            out.append(prefix + name)
            continue
        cand = '__pos%d' % pos
        while cand in taken:
            cand += '_'
        taken.add(cand)
        out.append(prefix + cand)
    return out


def _ndl_code_name_from_qualname(qualname):
    """Return the code-name component proven by a CPython ``co_qualname``.

    Nuitka is free to reuse an immortal/shared constant for ``co_name`` while
    keeping ``co_qualname`` in the module's own ``mod_consts`` array.  In that
    layout the Win64 ``makeCodeObject`` call still gives us an exact qualname,
    but the name slot cannot be resolved against the module-local constant
    base.  CPython's code-object invariant makes the final qualname component
    the code name (including ``<lambda>``/comprehension pseudo names), so it is
    safe to use only when that component has code-name syntax.

    ``None`` deliberately means "not proven"; callers must not guess.
    """
    if not isinstance(qualname, str) or not qualname:
        return None
    leaf = qualname.rsplit('.', 1)[-1]
    if leaf.isidentifier() or re.fullmatch(r'<[^<>]+>', leaf):
        return leaf
    return None


class NuitkaStaticDisassembler:
    """Disassemble each compiled module's native entry point and emit a
    Nuitka-aware pseudo-source listing.

    Nuitka compiles every Python module function into a C function, then
    the C compiler turns that into native x86-64 code. The C function
    performs three kinds of operations we can identify statically:

      1. **Python C API calls** — `PyObject_GetAttr`, `PyObject_CallObject`,
         `PyDict_SetItem`, etc. These come via the import table (IAT); we
         resolve each `call qword ptr [rip+X]` by looking up the IAT slot.

      2. **Nuitka runtime helpers** — `LOOKUP_ATTRIBUTE`, `CALL_FUNCTION_*`,
         `MAKE_FUNCTION_*`, `loadConstantsBlob`, etc. These are compiled as
         direct calls `call 0x...` to addresses inside `.text`. Without
         symbols we can't name them, but we can identify the most-called
         ones (they ARE the Nuitka runtime) and flag them.

      3. **Constant loads** — every Python constant access becomes
         `mov reg, qword ptr [rip + offset]` where the offset points into
         the `mod_consts` struct in `.data`. We resolve the target
         address and — knowing the constants we decoded from the blob in
         the same order — can map it back to the original Python literal.

    The output is a `.disasm.txt` per compiled module with:
      * per-instruction disassembly with resolved RIP-relative refs
      * a "Calls to" list (sorted by target)
      * a "Constants referenced" list (the Python literals this function
        actually touches)
      * a pseudo-Python call trace ("step 1: LOOKUP_ATTR 'session'; step
        2: LOOKUP_ATTR 'get'; step 3: CALL_FUNCTION args=...")
    """

    # Common Python C API names to look for in the IAT — anything matching
    # is flagged as "real Python operation".
    _PYTHON_CAPI_NAMES = (
        'Py_', 'PyDict_', 'PyList_', 'PyTuple_', 'PyLong_', 'PyFloat_',
        'PyUnicode_', 'PyBytes_', 'PyBool_', 'PyNumber_', 'PyObject_',
        'PyType_', 'PyIter_', 'PyErr_', 'PyThreadState_', 'PyEval_',
        'PyImport_', 'PyFunction_', 'PyMethod_', 'PyCFunction_',
        'PyRun_', 'PyMarshal_', 'PyWeakref_', 'PyCompile_', 'PyCode_',
        'PyFrame_', 'PyArg_', 'PyStructSequence_', 'PySys_', 'PyModule_',
        'PyBaseObject_', 'PyMem_', 'PyGILState_',
    )

    def __init__(self, pe_file, blob_sections=None, module_table=None):
        if not CAPSTONE_AVAILABLE:
            raise RuntimeError("capstone not installed (pip install capstone)")
        self.pe = pe_file
        self.image_base = pe_file.OPTIONAL_HEADER.ImageBase
        self.is_x64 = pe_file.FILE_HEADER.Machine == 0x8664
        self.sections = blob_sections or {}
        self.module_table = module_table or []

        # Capstone decoder
        self.md = _capstone.Cs(_capstone.CS_ARCH_X86,
                               _capstone.CS_MODE_64 if self.is_x64
                               else _capstone.CS_MODE_32)
        self.md.detail = True

        # Pre-compute useful lookups
        self._iat = self._build_iat_map()
        self._section_map = self._build_section_map()
        self._section_data_cache = {}
        self._analysis_cache = OrderedDict()
        self._analysis_cache_max = 256
        self._memory_efficient = False
        self._analysis_cache_lock = threading.Lock()
        # V100 SPEED: cache dei risultati di disassemblamento. Il profilo reale
        # mostra che _disasm_body/_bounded_disasm/disassemble_function vengono
        # richiamate centinaia di migliaia di volte con gli STESSI parametri
        # (stesso va, stesso budget): ~30-40% del runtime era puro churn
        # capstone (1.9M generatori creati).  Gli insn capstone sono snapshot
        # immutabili, condividerli e' sicuro.  LRU con cap per la RAM.
        self._disasm_lru = OrderedDict()
        self._disasm_lru_max_entries = 4096
        self._disasm_lru_max_insns = 600000
        # Map func_ptr -> module_name from the loader table
        self._func_to_module = {e['func_ptr']: e['name']
                                for e in self.module_table
                                if e.get('func_ptr')}
        # IAT slot of the CPython code-object constructor — call sites of this
        # API carry every function's EXACT co_argcount/flags/varnames as
        # immediate operands, letting us recover real signatures from native
        # code. PyCode_NewWithPosOnlyArgs is used on 3.8-3.10; on CPython 3.11+
        # it was RENAMED to PyUnstable_Code_NewWithPosOnlyArgs (same call, plus a
        # `qualname` arg after `name` and an `exceptiontable` arg at the very end
        # — both APPENDED, so args 1-14 keep their Win64 positions and the offsets
        # this recovery reads (0x28 flags / 0x38 consts / 0x48 varnames / 0x68
        # name) are unchanged). Without this the 3.12 slot was never found and
        # every compiled module recovered ZERO code objects (bodies all `pass`).
        self._pycode_slot = None
        # Detect the target Python ABI from the imported runtime DLL as the
        # authoritative signal. Python 3.11 builds generated by older/current
        # Nuitka releases may still import the legacy PyCode_NewWithPosOnlyArgs
        # spelling, so the PyUnstable_* symbol name alone is NOT a valid version
        # discriminator.
        self._py_ver = None
        self.target_python = None
        try:
            for _dll, _sym in self._iat.values():
                _m = re.match(r"python(\d)(\d+)\.dll$", str(_dll).lower())
                if _m:
                    self._py_ver = (int(_m.group(1)), int(_m.group(2)))
                    self.target_python = self._py_ver
                    break
        except Exception:
            self._py_ver = None
            self.target_python = None
        # True only on CPython 3.11+ (PyUnstable_* rename) — the marker that this
        # binary uses the shared makeCodeObject helper, so the wrapper-based
        # code-object recovery + its static-only fallback apply. On 3.8-3.10
        # (PyCode_NewWithPosOnlyArgs / PyCode_New) they must NOT run, so the
        # 3.8-3.10 emit path stays byte-identical.
        self._pycode_is_unstable = False
        for _name in (b'PyUnstable_Code_NewWithPosOnlyArgs',
                      b'PyCode_NewWithPosOnlyArgs', b'PyCode_New'):
            for addr, (_dll, _sym) in self._iat.items():
                if _sym.encode() == _name:
                    self._pycode_slot = addr
                    self._pycode_is_unstable = _name.startswith(b'PyUnstable_')
                    break
            if self._pycode_slot:
                break
        # ABI/layout gate, not spelling gate. CPython 3.11 retained the legacy
        # export on several runtimes and Nuitka revisions, while still using the
        # shared 10-argument makeCodeObject wrapper and 3.11 frame layout.
        if self._py_ver is not None and self._py_ver >= (3, 11):
            self._pycode_is_unstable = True

        # Exact x64 function bounds from the PE exception directory (.pdata).
        #
        # IMPORTANT: one logical MSVC function may be split into several
        # RUNTIME_FUNCTION records.  A secondary record carries
        # UNW_FLAG_CHAININFO and points at the primary record.  Treating those
        # physical fragments as independent functions truncated large Nuitka
        # createModuleCodeObjects/module-init routines and made later scans
        # wander into helpers.  Build a union of explicitly chained fragments
        # and expose their logical min(start)..max(end) extent.
        self._pdata_ranges = []          # physical records, sorted
        self._pdata_starts = []
        self._pdata_logical = {}         # physical start -> logical (start,end)
        try:
            import struct as _pdata_struct
            _records = []
            _entries = getattr(self.pe, 'DIRECTORY_ENTRY_EXCEPTION', ()) or ()
            for _e in _entries:
                _brva = int(_e.struct.BeginAddress)
                _erva = int(_e.struct.EndAddress)
                _urva = int(getattr(_e.struct, 'UnwindData', 0)) & ~1
                if not (0 <= _brva < _erva):
                    continue
                _rec = {
                    'b': self.image_base + _brva,
                    'e': self.image_base + _erva,
                    'brva': _brva, 'erva': _erva, 'urva': _urva,
                    'chain': None,
                }
                # UNWIND_INFO: Version:3 | Flags:5, SizeOfProlog,
                # CountOfCodes, FrameRegister/Offset, UNWIND_CODE array.  When
                # CHAININFO (0x4) is set, an aligned RUNTIME_FUNCTION triple
                # follows the unwind codes.  Parse defensively; malformed or
                # stripped records simply remain standalone.
                try:
                    _off = self.pe.get_offset_from_rva(_urva)
                    _raw = self.pe.__data__
                    if _off is not None and _off + 4 <= len(_raw):
                        _flags = int(_raw[_off]) >> 3
                        _count = int(_raw[_off + 2])
                        _coff = (_off + 4 + _count * 2 + 3) & ~3
                        if (_flags & 0x4) and _coff + 12 <= len(_raw):
                            _cb, _ce, _cu = _pdata_struct.unpack_from(
                                '<III', _raw, _coff)
                            if 0 <= _cb < _ce:
                                _rec['chain'] = (_cb, _ce, _cu & ~1)
                except Exception:
                    pass
                _records.append(_rec)

            _records.sort(key=lambda r: (r['b'], r['e']))
            self._pdata_ranges = [(r['b'], r['e']) for r in _records]
            self._pdata_starts = [r['b'] for r in _records]

            # Union each CHAININFO fragment with the exact record it names.
            _n = len(_records)
            _parent = list(range(_n))
            def _find(_i):
                while _parent[_i] != _i:
                    _parent[_i] = _parent[_parent[_i]]
                    _i = _parent[_i]
                return _i
            def _union(_a, _b):
                _ra, _rb = _find(_a), _find(_b)
                if _ra != _rb:
                    _parent[_rb] = _ra
            _by_triple = {
                (r['brva'], r['erva'], r['urva']): i
                for i, r in enumerate(_records)
            }
            _by_range = {
                (r['brva'], r['erva']): i for i, r in enumerate(_records)
            }
            for _i, _r in enumerate(_records):
                _ch = _r.get('chain')
                if not _ch:
                    continue
                _j = _by_triple.get(_ch)
                if _j is None:
                    _j = _by_range.get((_ch[0], _ch[1]))
                if _j is not None:
                    _union(_i, _j)

            _groups = {}
            for _i, _r in enumerate(_records):
                _groups.setdefault(_find(_i), []).append(_r)
            for _grp in _groups.values():
                _lb = min(r['b'] for r in _grp)
                _le = max(r['e'] for r in _grp)
                for _r in _grp:
                    self._pdata_logical[_r['b']] = (_lb, _le)
        except Exception:
            self._pdata_ranges = []
            self._pdata_starts = []
            self._pdata_logical = {}
        # Cache for _returns_nuitka_bool (helper VA -> bool), shared across the
        # whole binary (helpers are module-wide).
        self._nuitka_bool_cache = {}
        self._attr_store_cache = {}   # helper VA -> is an attribute-STORE helper
        self._compare_op_cache = {}   # helper VA -> '=='/'!='/None
        # CALL_FUNCTION_NO_ARGS / CALL_METHOD_NO_ARGS helper VAs, discovered
        # once per binary by static body shape (see _discover_call_helpers).
        self._call0_helpers = None
        self._mcall0_helpers = None
        # IAT slots of the CPython singletons, by symbol name — used to detect
        # `is None` / truth branches statically (universal, not VA-hardcoded).
        self._none_iat = self._true_iat = self._false_iat = None
        for _addr, (_dll, _sym) in self._iat.items():
            if _sym == '_Py_NoneStruct':
                self._none_iat = _addr
            elif _sym == '_Py_TrueStruct':
                self._true_iat = _addr
            elif _sym == '_Py_FalseStruct':
                self._false_iat = _addr

    def set_memory_efficient(self, enabled=True, cache_max=None):
        """Lower RAM use for live decompile: LRU-capped analysis cache, omit
        per-function raw_disasm blobs from stored results."""
        self._memory_efficient = bool(enabled)
        if cache_max is not None:
            self._analysis_cache_max = max(16, int(cache_max))

    def clear_analysis_cache(self):
        with self._analysis_cache_lock:
            self._analysis_cache.clear()
        # The structural CFG cache is separate from the recursive function
        # analysis LRU.  It is budget/extent-sensitive (complete source emits
        # use a wider, multi-return-aware instruction extent), so clearing the
        # public analysis cache must clear it too; otherwise a prior balanced
        # probe can leave a permanently truncated/None CFG for the same VA.
        try:
            self._cfg_cache.clear()
        except Exception:
            self._cfg_cache = {}

    @staticmethod
    def _slim_analysis_info(info):
        if not info:
            return info
        if 'raw_disasm' not in info:
            return info
        slim = dict(info)
        raw = slim.pop('raw_disasm', None) or []
        if raw:
            slim['prologue_head'] = raw[:5]
        return slim

    def _get_analysis_cache(self, cache_key):
        with self._analysis_cache_lock:
            hit = self._analysis_cache.get(cache_key)
            if hit is not None:
                self._analysis_cache.move_to_end(cache_key)
            return hit

    def _put_analysis_cache(self, cache_key, result):
        with self._analysis_cache_lock:
            self._analysis_cache[cache_key] = result
            self._analysis_cache.move_to_end(cache_key)
            while len(self._analysis_cache) > self._analysis_cache_max:
                self._analysis_cache.popitem(last=False)

    def _build_section_map(self):
        """Map each RVA range to its section for fast lookup."""
        ranges = []
        for s in self.pe.sections:
            name = s.Name.rstrip(b'\x00').decode('ascii', errors='replace')
            start = s.VirtualAddress
            end = start + max(s.Misc_VirtualSize, s.SizeOfRawData)
            ranges.append((start, end, name, s))
        return ranges

    def _find_section_for_rva(self, rva):
        for start, end, name, s in self._section_map:
            if start <= rva < end:
                return (name, s, rva - start)
        return (None, None, 0)

    def _build_iat_map(self):
        """Resolve every IAT slot to its symbol name."""
        iat = {}
        if not hasattr(self.pe, 'DIRECTORY_ENTRY_IMPORT'):
            return iat
        for entry in self.pe.DIRECTORY_ENTRY_IMPORT:
            dll = entry.dll.decode('ascii', errors='replace') if entry.dll else '?'
            for imp in entry.imports:
                if imp.address and imp.name:
                    name = imp.name.decode('ascii', errors='replace')
                    iat[imp.address] = (dll, name)
                elif imp.address and imp.ordinal:
                    iat[imp.address] = (dll, f'ord_{imp.ordinal}')
        return iat

    def _resolve_rip_relative(self, ins):
        """For RIP-relative instructions (call qword ptr [rip+X], mov reg,
        [rip+X], lea reg, [rip+X]), return the VA of the target."""
        for op in ins.operands:
            if op.type == _capstone_x86.X86_OP_MEM:
                if op.mem.base == _capstone_x86.X86_REG_RIP:
                    return ins.address + ins.size + op.mem.disp
        return None

    def _v39_scan_text_prologues(self, max_prologues=2000, desired_lines=None):
        """V39: Scan the ENTIRE .text section for function prologues and
        return a {first_lineno: va} map. This finds functions NOT reachable
        from the module entry point (Qt signal slots, callbacks, lambdas).

        A function prologue on MSVC x64 typically starts with one of:
          - `sub rsp, N`           (frame-pointer omission, most common)
          - `mov [rsp+8], rbx; sub rsp, N`
          - `push rbp; mov rbp, rsp; sub rsp, N`

        For each prologue candidate, disasm the first ~80 instructions and
        look for a f_lineno marker. Returns {first_lineno: va} where va is
        the START of the function (the prologue), not the marker address.
        """
        # Find the .text section
        text_sec = None
        text_va = 0
        text_size = 0
        for start, end, name, s in self._section_map:
            if '.text' in name:
                text_va = self.image_base + start
                text_size = end - start
                text_sec = s
                break
        if not text_sec:
            return {}
        try:
            data = text_sec.get_data()
        except Exception:
            return {}

        # V73: PE x64 unwind metadata already enumerates exact native function
        # starts. Prefer it over the historical 1-byte scan of up to 8 MB of
        # .text, which was O(section_size) and could materialise thousands of
        # false prologues. The line map stores only one VA per source line, so
        # an optional desired-line set lets callers stop as soon as every
        # relevant code-object line has been found.
        _wanted = None
        if desired_lines:
            try:
                _wanted = {int(x) for x in desired_lines if int(x) > 0}
            except Exception:
                _wanted = None

        # Determine the f_lineno offset for this Python version
        loff = 0x64  # default 3.8-3.10
        try:
            loff = _ndl_flineno_offset(self)
        except Exception:
            pass

        # f_lineno marker pattern: `mov dword ptr [<reg>+0x<loff>], <imm>`
        # where <reg> is typically rbp/rsp/rbx and <imm> is 1-1000000
        lre = re.compile(
            r"^dword ptr \[\w+ \+ 0x%x\],\s*(\d+|0x[0-9a-f]+)$" % loff)

        # Common prologue byte patterns (MSVC x64):
        # 48 89 5C 24 XX     mov [rsp+XX], rbx
        # 48 83 EC XX        sub rsp, XX
        # 55                 push rbp
        # 48 8B EC           mov rbp, rsp
        # 4C 89 4C 24 XX     mov [rsp+XX], r9
        # 4C 89 44 24 XX     mov [rsp+XX], r8
        # We scan for `48 83 EC` (sub rsp) and `55 48 8B EC` (push rbp; mov rbp,rsp)
        # and `48 89 5C 24` (mov [rsp+X], rbx — very common MSVC first insn)

        line_to_va = {}
        va_to_line = {}
        prologue_count = 0

        # Exact and fast path for PE x64. `_pdata_logical` folds CHAININFO
        # fragments, so each logical C function is inspected once.
        if self._pdata_ranges:
            try:
                starts = sorted({self._pdata_logical.get(b, (b, e))[0]
                                 for b, e in self._pdata_ranges})
                text_end = text_va + text_size
                for va in starts:
                    if prologue_count >= max_prologues:
                        break
                    if not (text_va <= va < text_end):
                        continue
                    off = va - text_va
                    try:
                        insns = self.md.disasm(data[off:off + 512], va)
                    except Exception:
                        continue
                    first_lineno = None
                    for _idx, ins in enumerate(insns):
                        if _idx >= 80:
                            break
                        if ins.mnemonic == 'mov':
                            m = lre.match(ins.op_str)
                            if m:
                                v = int(m.group(1), 0)
                                if 0 < v <= 1000000:
                                    first_lineno = v
                                    break
                        if ins.mnemonic == 'ret':
                            break
                    if first_lineno is None:
                        continue
                    if _wanted is not None and first_lineno not in _wanted:
                        continue
                    if first_lineno not in line_to_va:
                        line_to_va[first_lineno] = va
                    va_to_line[va] = first_lineno
                    prologue_count += 1
                    if _wanted is not None and _wanted.issubset(line_to_va):
                        break
                self._v39_va_to_line = va_to_line
                self._v39_line_to_va = line_to_va
                return line_to_va
            except Exception:
                # Stripped/corrupt unwind data: retain the legacy byte-pattern
                # fallback below.
                line_to_va.clear(); va_to_line.clear(); prologue_count = 0

        # V39.1: Scan at 1-byte resolution but only at positions that match
        # a prologue byte pattern. This is slower but finds ALL functions,
        # not just 16-byte-aligned ones.
        # Strategy: for each position, check if the bytes match a known
        # prologue pattern. If yes, disasm and look for f_lineno marker.
        scan_limit = min(text_size, 0x800000)  # 8MB max scan
        pos = 0
        # Pre-build the data as a bytes object for fast slicing
        data_len = len(data)
        while pos < scan_limit and prologue_count < max_prologues:
            if pos + 5 > data_len:
                break
            va = text_va + pos
            b0 = data[pos]
            b1 = data[pos+1]
            b2 = data[pos+2]
            b3 = data[pos+3]

            is_prologue = False
            # `sub rsp, imm8`: 48 83 EC XX
            if b0 == 0x48 and b1 == 0x83 and b2 == 0xEC:
                is_prologue = True
            # `sub rsp, imm32`: 48 81 EC XX XX XX XX
            elif b0 == 0x48 and b1 == 0x81 and b2 == 0xEC:
                is_prologue = True
            # `push rbp`: 55 (but only if followed by mov rbp,rsp or sub rsp)
            elif b0 == 0x55 and pos + 4 <= data_len:
                b3b = data[pos+3] if pos+3 < data_len else 0
                b4b = data[pos+4] if pos+4 < data_len else 0
                # push rbp; mov rbp, rsp; sub rsp = 55 48 8B EC 48 83 EC
                if b1 == 0x48 and b2 == 0x8B and b3b == 0xEC:
                    is_prologue = True
            # `mov [rsp+X], rbx`: 48 89 5C 24 XX (common MSVC first insn)
            elif b0 == 0x48 and b1 == 0x89 and b2 == 0x5C and b3 == 0x24:
                is_prologue = True
            # `mov [rsp+X], rdi`: 48 89 7C 24 XX
            elif b0 == 0x48 and b1 == 0x89 and b2 == 0x7C and b3 == 0x24:
                is_prologue = True
            # `mov [rsp+X], rsi`: 48 89 74 24 XX
            elif b0 == 0x48 and b1 == 0x89 and b2 == 0x74 and b3 == 0x24:
                is_prologue = True
            # `mov [rsp+X], rbx` (REX.WB): 4C 89 5C 24 XX
            elif b0 == 0x4C and b1 == 0x89 and b2 == 0x5C and b3 == 0x24:
                is_prologue = True
            # `mov rax, rsp` (used in some prologues): 48 8B C4
            elif b0 == 0x48 and b1 == 0x8B and b2 == 0xC4:
                is_prologue = True

            if not is_prologue:
                pos += 1
                continue

            # V39.2: Relaxed boundary check — accept most positions.
            # The strict boundary check (ret/int3/nop) missed too many real
            # prologues. We now accept any position that matches a prologue
            # pattern and has a valid f_lineno marker. False positives are
            # filtered by the f_lineno marker requirement (most non-function
            # positions won't have a valid f_lineno marker).
            # Only skip if the previous byte is clearly mid-instruction
            # (a continuation byte like 0x00 after a 0x48 prefix).

            # Try to disasm the first ~80 instructions and find a f_lineno marker
            try:
                insns = list(self.md.disasm(data[pos:pos+512], va))[:80]
            except Exception:
                pos += 1
                continue

            first_lineno = None
            for ins in insns:
                if ins.mnemonic == 'mov':
                    m = lre.match(ins.op_str)
                    if m:
                        v = int(m.group(1), 0)
                        if 0 < v <= 1000000:
                            first_lineno = v
                            break
                # Stop at `ret` (end of tiny function)
                if ins.mnemonic == 'ret':
                    break

            if first_lineno is not None:
                if first_lineno not in line_to_va:
                    line_to_va[first_lineno] = va
                va_to_line[va] = first_lineno
                prologue_count += 1

            pos += 1

        # Build a reverse index: for each VA, its first_lineno
        self._v39_va_to_line = va_to_line
        self._v39_line_to_va = line_to_va
        return line_to_va



    def _classify_call(self, ins):
        """Classify a call/jmp instruction. Returns one of:
          - ('capi', dll, name)   # Python/system C API via IAT
          - ('internal', va)      # direct call to .text
          - ('indirect', va)      # call through memory (not IAT)
          - ('unknown', None)
        """
        # Direct: `call 0x....` — operand is immediate VA
        if ins.operands and ins.operands[0].type == _capstone_x86.X86_OP_IMM:
            target_va = ins.operands[0].imm
            # If in .text, it's an internal Nuitka runtime call
            rva = target_va - self.image_base
            name, _, _ = self._find_section_for_rva(rva)
            if name == '.text':
                return ('internal', target_va)
            return ('unknown', target_va)
        # Indirect: `call qword ptr [rip+X]` — X points at an IAT slot
        if ins.operands and ins.operands[0].type == _capstone_x86.X86_OP_MEM:
            target = self._resolve_rip_relative(ins)
            if target is not None:
                if target in self._iat:
                    dll, name = self._iat[target]
                    return ('capi', dll, name)
                return ('indirect', target)
        # V95 Fix 3 (universal, pseudo-PLT): `call reg` where reg was loaded
        # from `mov reg, qword ptr [rip+IAT_SLOT]` (MinGW/gcc codegen).  The
        # caller-side tracker (analyse_function) annotates the instruction
        # with the slot VA before classification.
        _reg_hint = getattr(ins, '_ndl_iat_target', None)
        if _reg_hint is not None and _reg_hint in self._iat:
            dll, name = self._iat[_reg_hint]
            return ('capi', dll, name)
        return ('unknown', None)

    def _resolve_const_load(self, ins):
        """Resolve `mov/lea reg, [rip+X]` where X points into `.data`/.rdata.
        Returns the absolute VA and the section name, or None."""
        if ins.mnemonic not in ('mov', 'lea'):
            return None
        if len(ins.operands) < 2:
            return None
        src = ins.operands[1]
        if (src.type == _capstone_x86.X86_OP_MEM
                and src.mem.base == _capstone_x86.X86_REG_RIP):
            va = ins.address + ins.size + src.mem.disp
            rva = va - self.image_base
            name, _, _ = self._find_section_for_rva(rva)
            if name in ('.data', '.rdata'):
                return (va, name)
        return None

    def _resolve_text_ptr_load(self, ins):
        """Resolve `lea reg, [rip+X]` where X points into `.text`.

        Nuitka registers every compiled Python function body by passing
        its entry-point as an ARGUMENT to `MAKE_FUNCTION_*`, not by
        `call`-ing it. The function pointer is materialised via
        `lea rcx, [rip+offset_to_impl_funcname]`. Tracking these loads
        lets the recursive BFS reach the real Python `def` bodies —
        without this every function body stays invisible and only the
        Nuitka-runtime plumbing appears as @OPS blocks.

        Returns the absolute VA of the `.text` target, or None.
        """
        # `mov` loads are sometimes used for call-via-memory-table
        # patterns but those already become `call [rip+X]` → resolved
        # separately. Keep this to `lea` which is the idiomatic
        # function-pointer materialisation.
        if len(ins.operands) < 2:
            return None
        src = ins.operands[1]

        def _as_text_va(value):
            if value is None:
                return None
            value = int(value)
            for candidate in (value, self.image_base + value):
                name, _, _ = self._find_section_for_rva(
                    candidate - self.image_base)
                if name == '.text':
                    b, _e = self._function_bounds(candidate)
                    return int(b or candidate)
            return None

        if (ins.mnemonic == 'lea'
                and src.type == _capstone_x86.X86_OP_MEM
                and src.mem.base == _capstone_x86.X86_REG_RIP):
            va = ins.address + ins.size + src.mem.disp
            return _as_text_va(va)
        if ins.mnemonic != 'mov':
            return None
        dst = ins.operands[0]
        if (dst.type != _capstone_x86.X86_OP_REG
                or dst.reg not in (_capstone_x86.X86_REG_RCX,
                                   _capstone_x86.X86_REG_ECX)):
            return None
        if src.type == _capstone_x86.X86_OP_IMM:
            return _as_text_va(src.imm)
        if (src.type == _capstone_x86.X86_OP_MEM
                and src.mem.base == _capstone_x86.X86_REG_RIP):
            slot_va = ins.address + ins.size + src.mem.disp
            name, section, offset = self._find_section_for_rva(
                slot_va - self.image_base)
            if name not in ('.data', '.rdata') or section is None:
                return None
            try:
                data = section.get_data()
                if offset < 0 or offset + 8 > len(data):
                    return None
                return _as_text_va(struct.unpack_from('<Q', data, offset)[0])
            except Exception:
                return None
        return None

    def _resolve_direct_text_lea(self, ins):
        """Strict factory-scan resolver: only direct LEA into ``.text``.

        Compact makers load several runtime pointers into RCX. Those are useful
        to the broad graph traversal but must not enter the factory's one-c_code
        cardinality test, which specifically models the direct implementation
        LEA emitted before Nuitka_Function_New.
        """
        if ins.mnemonic != 'lea' or len(ins.operands) < 2:
            return None
        src = ins.operands[1]
        if (src.type != _capstone_x86.X86_OP_MEM
                or src.mem.base != _capstone_x86.X86_REG_RIP):
            return None
        va = ins.address + ins.size + src.mem.disp
        name, _, _ = self._find_section_for_rva(va - self.image_base)
        if name != '.text':
            return None
        b, _e = self._function_bounds(va)
        return int(b or va)

    def _resolve_function_new_c_code(self, insns, call_site, max_back=32,
                                          arg_reg='rcx'):
        """Back-slice a Win64 register argument at a Nuitka constructor call.

        ``Nuitka_Function_New`` receives ``function_impl_identifier`` in RCX
        (argument 0).  Coroutine/async-generator constructors receive their
        native context function in RDX (argument 1, after ``tstate``).  Keeping
        the register explicit avoids the former hard-coded RCX assumption.

        Returns ``('impl', va)``, ``('null', None)`` or ``(None, None)``.
        """
        self._last_c_code_slice = {'status': 'no-writer'}

        def _norm_reg(ins, reg):
            n = (ins.reg_name(reg) or '').lower()
            _m32 = {'eax': 'rax', 'ebx': 'rbx', 'ecx': 'rcx', 'edx': 'rdx',
                    'esi': 'rsi', 'edi': 'rdi', 'ebp': 'rbp', 'esp': 'rsp'}
            if n in _m32:
                return _m32[n]
            if re.fullmatch(r'r(?:8|9|1[0-5])d', n):
                return n[:-1]
            return n

        def _operand_text_target(ins):
            if len(ins.operands) < 2:
                return None
            src = ins.operands[1]
            value = None
            if ins.mnemonic == 'lea' and src.type == _capstone_x86.X86_OP_MEM \
                    and src.mem.base == _capstone_x86.X86_REG_RIP:
                value = ins.address + ins.size + src.mem.disp
            elif ins.mnemonic == 'mov' and src.type == _capstone_x86.X86_OP_IMM:
                value = src.imm
            elif ins.mnemonic == 'mov' and src.type == _capstone_x86.X86_OP_MEM \
                    and src.mem.base == _capstone_x86.X86_REG_RIP:
                slot = ins.address + ins.size + src.mem.disp
                name, sec, off = self._find_section_for_rva(slot - self.image_base)
                if name in ('.data', '.rdata') and sec is not None:
                    try:
                        data = sec.get_data()
                        if 0 <= off <= len(data) - 8:
                            value = struct.unpack_from('<Q', data, off)[0]
                    except Exception:
                        value = None
            if value is None:
                return None
            for candidate in (int(value), self.image_base + int(value)):
                name, _, _ = self._find_section_for_rva(candidate - self.image_base)
                if name == '.text':
                    b, _e = self._function_bounds(candidate)
                    return int(b or candidate)
            return None

        before = [i for i in insns if i.address < call_site][-max_back:]
        tracked = str(arg_reg or 'rcx').lower()
        for ins in reversed(before):
            if ins.mnemonic in ('call', 'callq', 'jmp', 'jmpq'):
                if tracked in ('rbx', 'rbp', 'rsi', 'rdi', 'r12', 'r13',
                               'r14', 'r15'):
                    continue
                self._last_c_code_slice = {
                    'status': 'clobber', 'tracked': tracked,
                    'writer': '%s %s' % (ins.mnemonic, ins.op_str)}
                break
            if not ins.operands:
                continue
            dst = ins.operands[0]
            if dst.type != _capstone_x86.X86_OP_REG:
                continue
            dst_name = _norm_reg(ins, dst.reg)
            if dst_name != tracked:
                continue
            op = re.sub(r'\s+', ' ', ins.op_str.strip().lower())
            if (ins.mnemonic == 'xor' and len(ins.operands) >= 2
                    and ins.operands[1].type == _capstone_x86.X86_OP_REG
                    and _norm_reg(ins, ins.operands[1].reg) == tracked):
                self._last_c_code_slice = {'status': 'null', 'tracked': tracked,
                                           'writer': ins.mnemonic + ' ' + ins.op_str}
                return 'null', None
            if (ins.mnemonic == 'mov' and len(ins.operands) >= 2
                    and ins.operands[1].type == _capstone_x86.X86_OP_IMM
                    and int(ins.operands[1].imm) == 0):
                self._last_c_code_slice = {'status': 'null', 'tracked': tracked,
                                           'writer': ins.mnemonic + ' ' + ins.op_str}
                return 'null', None
            target = _operand_text_target(ins)
            if target is not None:
                self._last_c_code_slice = {'status': 'impl', 'tracked': tracked,
                                           'writer': ins.mnemonic + ' ' + ins.op_str,
                                           'target': int(target)}
                return 'impl', int(target)
            if (ins.mnemonic == 'mov' and len(ins.operands) >= 2
                    and ins.operands[1].type == _capstone_x86.X86_OP_REG):
                tracked = _norm_reg(ins, ins.operands[1].reg)
                if tracked:
                    continue
            # This is the last writer of arg0, but its value is not provable.
            self._last_c_code_slice = {'status': 'unknown', 'tracked': tracked,
                                       'writer': ins.mnemonic + ' ' + ins.op_str}
            return None, None
        return None, None

    def disassemble_function(self, func_ptr, max_bytes=65536, max_insns=30000):
        """Disassemble from `func_ptr` until RET (or budget exhausted).

        Defaults are sized for the largest realistic module-entry
        function in a complex Nuitka binary: the `__main__` module
        entry of a multi-hundred-`def` application materialises one
        `lea + lea + call MAKE_FUNCTION` triple per `def`, so registering
        419 defs takes ~15-25 KB of machine code. The 65 KB / 30 K insn
        caps give generous headroom; most Python function bodies are
        tiny (under 1 KB) and hit RET long before the cap.
        """
        rva = func_ptr - self.image_base
        name, section, offset = self._find_section_for_rva(rva)
        if section is None:
            return []
        cache_key = (section.VirtualAddress, section.SizeOfRawData)
        sec_data = self._section_data_cache.get(cache_key)
        if sec_data is None:
            sec_data = section.get_data()
            self._section_data_cache[cache_key] = sec_data
        # Never cross a compiler-emitted logical function boundary.  The
        # logical bound already merges MSVC CHAININFO fragments, so large
        # module/createCodeObjects routines are kept whole while adjacent
        # functions cannot be accidentally consumed when a `ret` is unusual.
        try:
            _fb, _fe = self._function_bounds(func_ptr)
            if _fb is not None and _fe is not None and _fb <= func_ptr < _fe:
                max_bytes = min(max_bytes, max(1, _fe - func_ptr))
        except Exception:
            pass
        _cap_insns = 12000 if self._memory_efficient else max_insns
        _lru_key = ('f', func_ptr, int(max_bytes), int(_cap_insns))
        _cached = self._disasm_lru_get(_lru_key)
        if _cached is not None:
            return list(_cached)
        code = sec_data[offset:offset + max_bytes]
        instructions = []
        for ins in self.md.disasm(code, func_ptr):
            instructions.append(ins)
            if ins.mnemonic == 'ret' or len(instructions) >= _cap_insns:
                break
        self._disasm_lru_put(_lru_key, instructions)
        return list(instructions)

    def analyse_function(self, func_ptr, max_bytes=65536):
        """Disassemble + classify every call and every RIP-relative const load.

        Returns a dict:
            {
              'func_va': 0x...,
              'instruction_count': N,
              'calls': [ {va_from, kind, target, name}, ... ],
              'const_loads': [ {va_from, target_va, section}, ... ],
              'func_ptr_loads': [ {va_from, target_va}, ... ],  # lea -> .text
              'raw_disasm': [ (va, mnemonic, op_str), ... ],
              'reached_ret': True/False
            }
        """
        cache_key = (func_ptr, max_bytes)
        cached = self._get_analysis_cache(cache_key)
        if cached is not None:
            return cached

        instructions = self.disassemble_function(func_ptr, max_bytes=max_bytes)
        calls = []
        const_loads = []
        func_ptr_loads = []
        raw = []
        # `make_function_hints` cross-references each function pointer
        # load with the const loads that appear in the SAME basic block
        # before the next `call`. Nuitka's MAKE_FUNCTION call site is:
        #    lea rcx, [rip + func_ptr]
        #    lea rdx, [rip + qualname_str]    <-- we want this
        #    lea r8,  [rip + defaults_tuple]  <-- or this (tuple, not str)
        #    call MAKE_FUNCTION_<N>
        # so we collect EVERY subsequent const load (up to the call),
        # then resolve them at render time and pick the first that is
        # a plain string. Storing a list instead of a single value
        # avoids locking onto the defaults-tuple when it appears first.
        make_function_hints = []    # list of {func_va, candidate_vas[]}
        pending_fp = None           # last unmatched func_ptr_load
        pending_fp_hint_index = -1  # index into make_function_hints
        # V95 Fix 3 (universal, pseudo-PLT): MinGW/gcc binds imported C-API
        # functions to registers once (`mov reg, qword ptr [rip+IAT_SLOT]`)
        # and calls them as `call reg`.  Track the latest RIP-relative
        # load per register so `call reg` can be resolved to the IAT symbol.
        _reg_rip_target = {}
        for idx, ins in enumerate(instructions):
            raw.append((ins.address, ins.mnemonic, ins.op_str))
            if ins.mnemonic == 'call' and ins.operands \
                    and ins.operands[0].type == _capstone_x86.X86_OP_REG:
                _hint = _reg_rip_target.get(ins.operands[0].reg)
                if _hint is not None and _hint in self._iat:
                    ins._ndl_iat_target = _hint
            elif ins.mnemonic in ('mov', 'lea') and len(ins.operands) == 2:
                _dd, _ss = ins.operands
                if _dd.type == _capstone_x86.X86_OP_REG:
                    if (_ss.type == _capstone_x86.X86_OP_MEM
                            and _ss.mem.base == _capstone_x86.X86_REG_RIP):
                        _reg_rip_target[_dd.reg] = (
                            ins.address + ins.size + _ss.mem.disp)
                    else:
                        _reg_rip_target.pop(_dd.reg, None)
            if ins.mnemonic in ('call', 'callq') or ins.mnemonic.startswith('jmp'):
                kind_tuple = self._classify_call(ins)
                kind = kind_tuple[0]
                if kind == 'capi':
                    calls.append({
                        'va_from': ins.address,
                        'kind': 'capi',
                        'dll': kind_tuple[1],
                        'name': kind_tuple[2],
                    })
                elif kind == 'internal':
                    calls.append({
                        'va_from': ins.address,
                        'kind': 'internal',
                        'target': kind_tuple[1],
                        'module': self._func_to_module.get(kind_tuple[1]),
                    })
                elif kind == 'indirect':
                    calls.append({
                        'va_from': ins.address,
                        'kind': 'indirect',
                        'target': kind_tuple[1],
                    })
                elif kind == 'unknown' and kind_tuple[1] is not None:
                    calls.append({
                        'va_from': ins.address,
                        'kind': 'unknown',
                        'target': kind_tuple[1],
                    })
                # A call terminates the MAKE_FUNCTION window — stop
                # collecting candidates for the pending func_ptr.
                pending_fp = None
                pending_fp_hint_index = -1
            const = self._resolve_const_load(ins)
            if const is not None:
                const_loads.append({
                    'va_from': ins.address,
                    'mnemonic': ins.mnemonic,
                    'target_va': const[0],
                    'section': const[1],
                })
                # If a function pointer was just loaded (within a
                # 6-instruction window) append this const as a
                # candidate qualname for it. Render-time picks the
                # first candidate whose mod_consts entry is a string.
                if (pending_fp is not None
                        and pending_fp_hint_index >= 0
                        and len(make_function_hints[pending_fp_hint_index]['candidate_vas']) < 6):
                    make_function_hints[pending_fp_hint_index][
                        'candidate_vas'].append(const[0])
            # Function-pointer materialisation: `lea reg, [rip+X]` where
            # X -> .text. These are Nuitka's per-function compiled
            # entry-points passed as arguments to MAKE_FUNCTION_* /
            # MAKE_CLASS_* — i.e. the REAL Python def bodies we want
            # the recursive BFS to reach.
            fp_va = self._resolve_text_ptr_load(ins)
            if fp_va is not None:
                func_ptr_loads.append({
                    'va_from': ins.address,
                    'target_va': fp_va,
                })
                # Open a fresh candidate window for this function ptr.
                make_function_hints.append({
                    'func_va': fp_va,
                    'candidate_vas': [],
                })
                pending_fp = fp_va
                pending_fp_hint_index = len(make_function_hints) - 1

        result = {
            'func_va': func_ptr,
            'instruction_count': len(instructions),
            'reached_ret': bool(instructions and instructions[-1].mnemonic == 'ret'),
            'calls': calls,
            'const_loads': const_loads,
            'func_ptr_loads': func_ptr_loads,
            'make_function_hints': make_function_hints,
            'raw_disasm': raw,
        }
        cached = (self._slim_analysis_info(result)
                  if self._memory_efficient else result)
        self._put_analysis_cache(cache_key, cached)
        return result

    @staticmethod
    def _looks_like_function_entry(info):
        """Cheap check: does the disassembly start like a real function?

        Nuitka-compiled function prologues on x64 almost always begin
        with one of:
            push rbx / push rdi / push rsi / push rbp / push r12-r15
            sub  rsp, 0x??
            mov  [rsp + ??], reg            (MSVC-style shadow store)
            mov  rax, qword ptr fs:[0x??]   (stack cookie for /GS)
            sub  rsp, 0x28   +  call  <stack-check>

        If the first ~4 instructions contain NONE of these markers, the
        VA is most likely a jump-table entry or a mid-function label
        reached via `lea` — we skip it rather than emit a noise @OPS
        block full of garbage instructions.
        """
        raw = info.get('raw_disasm') or info.get('prologue_head') or []
        if not raw:
            return False
        # Only look at the first 5 instructions
        head = raw[:5]
        prologue_hits = 0
        for (_va, mnem, ops) in head:
            if mnem == 'push' and ops in (
                'rbx', 'rdi', 'rsi', 'rbp',
                'r12', 'r13', 'r14', 'r15',
            ):
                prologue_hits += 1
            elif mnem == 'sub' and ops.startswith('rsp,'):
                prologue_hits += 1
            elif mnem == 'mov' and ops.startswith(('qword ptr [rsp',
                                                     '[rsp')):
                prologue_hits += 1
            elif mnem == 'mov' and 'fs:' in ops:
                prologue_hits += 1
        return prologue_hits >= 1

    def analyse_function_recursive(self, entry_va, runtime_aliases=None,
                                    max_funcs=1000, max_bytes_per_fn=16384,
                                    max_bytes_entry=65536):
        """BFS through every module-local `call` AND every `lea`
        function-pointer materialisation starting at `entry_va`.

        Nuitka compiles every Python function as its own C function with
        its own `.text` entry point. The module-entry function (the one
        in the loader table) only runs the module's top-level code; all
        the actual `def` bodies are reached in TWO ways:

          (a) directly, via `call <impl_fn>` — rare, only for inner
              helpers that don't get promoted to Python function objects,
          (b) indirectly, via `lea reg, [rip + impl_fn]` passed as an
              argument to `MAKE_FUNCTION_*` — the common case for every
              `def` the module exposes.

        This BFS follows BOTH kinds, so a module with N Python `def`s
        yields N+ `@OPS` blocks in the final .nbc (one per compiled
        function body, plus the module entry).

        To rebuild each function body 1:1 we need its own disassembly
        window. This method walks the call graph:

          * starts at `entry_va`
          * for every `internal` call found, enqueues the target (unless
            it's a Nuitka runtime helper, the entry of a DIFFERENT
            module, or already visited)
          * stops at `max_funcs` to bound work per module

        Returns an `OrderedDict` {func_va: analyse_function_info}.

        `runtime_aliases` (the result of `build_module_call_stats`) is
        used to skip runtime helpers — otherwise we'd disassemble
        `LOOKUP_ATTRIBUTE` etc. once per module, which is pointless.
        """
        from collections import OrderedDict, deque
        runtime_aliases = runtime_aliases or {}

        # Skip ranked helpers found by the call-frequency prepass. These
        # are shared runtime helpers that every
        # module ends up calling — disassembling them per-module would
        # duplicate the same ops in every .nbc and waste LLM context.
        helper_vas = {va for va, alias in runtime_aliases.items()
                      if isinstance(alias, str)
                      and (alias.startswith('RUNTIME_HELPER_')
                           or alias.startswith('helper_'))}

        # Cross-module entries: every VA in the loader table except our
        # starting VA is the entry point of ANOTHER module, so skip it.
        skip_module_va = set(self._func_to_module.keys()) - {entry_va}

        # Two-queue traversal with provenance tracking:
        #   * `fp_queue` (high priority) = function-pointer `lea` targets —
        #     these may or may not be real function entries, so they get
        #     validated by the prologue heuristic at process-time.
        #   * `call_queue` (low priority) = direct-call targets — the
        #     caller BELIEVED these are functions (it emitted `call` to
        #     them), so we trust them and skip the prologue check.
        # Each queue entry is (va, source) where source is 'lea' or 'call'.
        results = OrderedDict()
        fp_queue = deque()
        call_queue = deque()
        call_queue.append((entry_va, 'entry'))
        seen = set()

        def _pop_next():
            if fp_queue:
                return fp_queue.popleft()
            if call_queue:
                return call_queue.popleft()
            return None

        while len(results) < max_funcs:
            item = _pop_next()
            if item is None:
                break
            va, source = item
            if va in seen:
                continue
            seen.add(va)

            # Never disassemble runtime helpers or sibling module entries
            if va != entry_va:
                if va in helper_vas:
                    continue
                if va in skip_module_va:
                    continue

            # Target must be a valid .text address
            rva = va - self.image_base
            sec_name, _, _ = self._find_section_for_rva(rva)
            if sec_name != '.text':
                continue

            try:
                # The module entry tends to be huge (thousands of
                # MAKE_FUNCTION registrations) — give it a larger
                # disasm budget. All other blocks are individual
                # Python function bodies, almost always under 4 KB
                # of native code.
                _budget = max_bytes_entry if va == entry_va else max_bytes_per_fn
                info = self.analyse_function(va, max_bytes=_budget)
            except Exception:
                continue
            if not info.get('raw_disasm') and not info.get('instruction_count'):
                continue

            # Prologue heuristic applies ONLY to `lea`-discovered VAs
            if source == 'lea' and va != entry_va:
                if not self._looks_like_function_entry(info):
                    continue
            results[va] = (self._slim_analysis_info(info)
                           if self._memory_efficient else info)

            # Enqueue direct-call targets with source='call'
            for c in info['calls']:
                if c['kind'] != 'internal':
                    continue
                tgt = c['target']
                if tgt in seen or tgt in helper_vas or tgt in skip_module_va:
                    continue
                call_queue.append((tgt, 'call'))

            # **Key insight**: Nuitka's `MAKE_FUNCTION_*` runtime helper
            # takes the compiled function pointer as an ARGUMENT, not as
            # a callee. The pattern in native code is:
            #
            #     lea  rcx, [rip + impl_fn_body]     ; func ptr arg
            #     lea  rdx, [rip + defaults_tuple]   ; defaults arg
            #     call MAKE_FUNCTION_NOFRAME_<N>
            #
            # So the real Python `def` bodies are reached via `lea`
            # targets that fall in `.text`, not via `call`. Enqueue
            # them on the HIGH-priority `fp_queue`: they're the
            # precious blocks we most want in the output.
            for fp in info.get('func_ptr_loads', []):
                tgt = fp['target_va']
                if tgt in seen or tgt in helper_vas or tgt in skip_module_va:
                    continue
                # Defensive: the lea could target a jump table or an
                # exception handler. analyse_function will still try to
                # disassemble it; if the result looks like noise the
                # prologue heuristic (source='lea') rejects it.
                fp_queue.append((tgt, 'lea'))
        return results


    def _first_source_lineno(self, va, max_bytes=8192):
        """Return the first compiler-emitted f_lineno value for a native body.

        V74 uses this as a strict proof that a .text pointer is a compiled Python
        implementation rather than a runtime helper, jump-table label, or cleanup
        fragment. Both immediate stores and the common ``mov reg, imm`` followed
        by ``mov [frame+f_lineno], reg`` form are accepted.
        """
        try:
            _cache = getattr(self, "_v74_first_lineno_cache", None)
            if _cache is None:
                _cache = {}
                self._v74_first_lineno_cache = _cache
            _b, _e = self._function_bounds(va)
            _start = _b or va
            if _start in _cache:
                return _cache[_start]
            if _e is not None and _e > _start:
                max_bytes = min(max_bytes, _e - _start)
            insns = self.disassemble_function(_start, max_bytes=max_bytes,
                                               max_insns=2500)
            try:
                _off = _ndl_flineno_offset(self)
            except Exception:
                _off = 0x28 if getattr(self, "_py_ver", (3, 10)) >= (3, 11) else 0x64
            _dst = re.compile(
                r"^dword ptr \[\w+ \+ 0x%x\],\s*"
                r"(e[a-z]{2}|r(?:8|9|1[0-5])d|\d+|0x[0-9a-f]+)$" % _off)
            _imm = {}
            _found = None
            for _i in insns:
                if _i.mnemonic != "mov":
                    continue
                _m = re.match(
                    r"^(e[a-z]{2}|r(?:8|9|1[0-5])d),\s*"
                    r"(0x[0-9a-f]+|\d+)$", _i.op_str)
                if _m:
                    _imm[_m.group(1)] = int(_m.group(2), 0)
                    continue
                _m = _dst.match(_i.op_str)
                if not _m:
                    continue
                _v = _m.group(1)
                _ln = _imm.get(_v) if not (_v[0].isdigit() or _v.startswith("0x")) else int(_v, 0)
                if _ln is not None and 0 < _ln <= 1000000:
                    _found = _ln
                    break
            _cache[_start] = _found
            return _found
        except Exception:
            return None

    def _maker_impl_targets(self, caller_info, max_helpers=512,
                            helper_max_bytes=4096, impl_probe_bytes=8192,
                            max_depth=32, deadline=None):
        """Discover modern Nuitka ``module -> maker -> impl_*`` edges.

        Nuitka 4.x commonly embeds the Python implementation pointer inside the
        small MAKE_FUNCTION maker. The module therefore CALLs the maker, while the
        maker itself materialises ``impl_*`` with a RIP-relative LEA before
        constructing the function object. Older traversal only followed LEAs in
        the module body and consequently missed every such implementation.

        This pass inspects only bounded direct callees, accepts only small
        return-reaching helpers, and promotes a pointer only when the pointed
        native function contains a real f_lineno store. That proof keeps runtime
        helpers and arbitrary .text constants out of the Python-function graph.
        """
        out = []
        direct_python_targets = set()
        seen = set()
        queued = set()
        calls = [c for c in (caller_info or {}).get("calls", ())
                 if c.get("kind") == "internal" and c.get("target")]
        work = deque()
        for c in calls:
            hva = c.get("target")
            if hva and hva not in queued:
                work.append((hva, 0))
                queued.add(hva)
        processed = 0
        # Nuitka Commercial can interpose multiple compact forwarding helpers
        # between the module entry, MAKE_FUNCTION maker and implementation.
        # Walk that helper subgraph to a fixed point instead of inspecting only
        # the module's direct callees.  `seen`, pdata bounds and the global node
        # budget make this cycle-safe and deterministic.
        while work and processed < max_helpers:
            if deadline is not None and time.perf_counter() > deadline:
                break
            hva, depth = work.popleft()
            if depth > max_depth:
                continue
            try:
                hb, he = self._function_bounds(hva)
                hs = hb or hva
                if hs in seen:
                    continue
                seen.add(hs)
                processed += 1
                if he is not None and he > hs and he - hs > helper_max_bytes:
                    continue
                hinfo = self.analyse_function(
                    hs, max_bytes=min(helper_max_bytes,
                                      (he - hs) if he is not None and he > hs
                                      else helper_max_bytes))
                if not hinfo.get("reached_ret"):
                    continue
                # A Python implementation has line stores; a generated maker does
                # not.  Reaching one through a direct call is still a valid edge in
                # protected/commercial builds: wrappers may CALL the implementation
                # instead of (or before) exposing it through Nuitka_Function_New.
                #
                # Older code merely stopped walking here.  Worse, ``hs`` was now in
                # ``seen``, so a later maker LEA to the very same implementation was
                # discarded below.  The result depended on traversal order and lost
                # real bodies.  Treat a line-bearing callee as a Python frontier:
                # publish it, but do not recurse into its runtime-helper calls in
                # this helper-only closure.  The outer fixed point will analyse it
                # with the normal per-function budget and discover nested defs.
                if self._first_source_lineno(
                        hs, max_bytes=min(impl_probe_bytes,
                                          max(helper_max_bytes, 2048))):
                    out.append(hs)
                    direct_python_targets.add(hs)
                    continue
                # Continue through compact helper/forwarder calls even if this
                # node has no direct implementation LEA. This is the missing
                # module -> wrapper -> maker -> impl recursion in protected
                # builds. Python bodies are excluded above by f_lineno.
                if depth < max_depth:
                    for nc in hinfo.get("calls", ()):
                        if nc.get("kind") != "internal" or not nc.get("target"):
                            continue
                        nt = int(nc["target"])
                        nb, ne = self._function_bounds(nt)
                        ns = nb or nt
                        if ns in seen or ns in queued:
                            continue
                        if ne is not None and ne > ns and ne - ns > helper_max_bytes:
                            continue
                        work.append((ns, depth + 1))
                        queued.add(ns)
                fps = []
                for fp in hinfo.get("func_ptr_loads", ()):
                    if fp.get("target_va"):
                        fps.append(fp["target_va"])
                for hint in hinfo.get("make_function_hints", ()):
                    if hint.get("func_va"):
                        fps.append(hint["func_va"])
                # Real makers normally carry very few .text pointers. A huge set is
                # a dispatch/helper table and is intentionally rejected.
                if not fps or len(set(fps)) > 8:
                    continue

                # V75: retain the analysed maker itself.  The exact code-object
                # slot and the implementation pointer coexist in this helper,
                # but analyse_python_function_targets historically returned only
                # the module entry and impl bodies.  Consequently the later
                # code-slot join never saw the strongest maker evidence.
                _mi = getattr(self, "_maker_infos", None)
                if _mi is None:
                    _mi = self._maker_infos = {}
                _mi[hs] = hinfo

                for tgt in fps:
                    tb, te = self._function_bounds(tgt)
                    ts = tb or tgt
                    # STRENGTHEN: maker-context fps are impl pointers by construction
                    # (the maker LEA'd them for MAKE_FUNCTION). The lineno scan is
                    # corroborative but can miss on some register layouts / 3.11+
                    # / DLLs (non-imm stores, different frame ptr). Include
                    # unconditionally from the maker path.  Do NOT suppress a
                    # target merely because the helper walk encountered it first:
                    # ``seen`` is a cycle guard, not negative implementation
                    # evidence.  De-duplication happens deterministically on return.
                    out.append(ts)
            except Exception:
                continue
        self._last_maker_closure_stats = {
            'helpers_seen': len(seen),
            'helpers_processed': processed,
            'max_depth': max_depth,
            'budget_exhausted': bool(work),
            'impl_targets': len(set(out)),
            'direct_python_targets': len(direct_python_targets),
        }
        return list(dict.fromkeys(out))

    def analyse_python_function_targets(self, entry_va, max_funcs=1000,
                                        max_bytes_entry=65536,
                                        max_bytes_per_fn=32768,
                                        deadline=None):
        """Walk only Nuitka-registered Python implementation pointers.

        This is the precise, low-noise alternative to
        :meth:`analyse_function_recursive` for modern Nuitka.  Native direct
        calls overwhelmingly lead to shared runtime helpers; real Python
        ``def``/lambda/comprehension implementations are materialised as
        pointers in ``func_ptr_loads`` / ``make_function_hints``.  Recursing
        through those pointers discovers nested definitions too, without
        disassembling hundreds of refcount/exception helpers per module.

        All targets are canonicalised through CHAININFO-aware `.pdata` bounds,
        so cold/chained fragments cannot become duplicate pseudo-functions.
        """
        from collections import OrderedDict, deque
        results = OrderedDict()
        queue = deque()
        if deadline is None:
            deadline = time.perf_counter() + (
                90.0 if _ndl_live_opt('complete_mode') else 30.0)

        _eb, _ee = self._function_bounds(entry_va)
        entry_start = _eb or entry_va
        queue.append(entry_start)
        seen = set()

        # Canonical starts of other module entry functions.
        skip_module_starts = set()
        for _mva in self._func_to_module:
            _mb, _me = self._function_bounds(_mva)
            skip_module_starts.add(_mb or _mva)
        skip_module_starts.discard(entry_start)

        while queue and len(results) < max_funcs:
            if deadline is not None and time.perf_counter() > deadline:
                break
            va = queue.popleft()
            _b, _e = self._function_bounds(va)
            start = _b or va
            if start in seen:
                continue
            seen.add(start)
            if start != entry_start and start in skip_module_starts:
                continue
            rva = start - self.image_base
            sec_name, _, _ = self._find_section_for_rva(rva)
            if sec_name != '.text':
                continue
            budget = max_bytes_entry if start == entry_start else max_bytes_per_fn
            if _e is not None and _e > start:
                budget = min(budget, _e - start)
            try:
                info = self.analyse_function(start, max_bytes=max(1, budget))
            except Exception:
                continue
            if not info.get('instruction_count'):
                continue
            # Without unwind metadata retain the old conservative prologue gate
            # for pointer-discovered bodies.  Exact pdata starts need no heuristic.
            if start != entry_start and _b is None:
                if not self._looks_like_function_entry(info):
                    continue
            results[start] = (self._slim_analysis_info(info)
                              if self._memory_efficient else info)

            targets = []
            for fp in info.get('func_ptr_loads', ()):
                if fp.get('target_va'):
                    targets.append(fp['target_va'])
            for hint in info.get('make_function_hints', ()):
                if hint.get('func_va'):
                    targets.append(hint['func_va'])
            # V74 source-driven edge: modern Nuitka makers contain the impl pointer
            # themselves, so follow bounded caller->maker->impl links as well.
            try:
                targets.extend(self._maker_impl_targets(
                    info, max_helpers=max(64, min(2048, max_funcs * 4)),
                    helper_max_bytes=min(8192, max_bytes_per_fn),
                    max_depth=int(_ndl_live_opt('maker_max_depth') or 32),
                    deadline=deadline))
            except Exception:
                pass
            for tgt in dict.fromkeys(targets):
                _tb, _te = self._function_bounds(tgt)
                tstart = _tb or tgt
                if (tstart not in seen and tstart not in skip_module_starts
                        and tstart != entry_start):
                    queue.append(tstart)
        return results

    def analyse_module_targets(self, entry_va, max_bytes_entry=65536,
                               max_bytes_per_fn=32768):
        """Backward-compatible alias for the Python-pointer-only traversal."""
        return self.analyse_python_function_targets(
            entry_va, max_funcs=1000, max_bytes_entry=max_bytes_entry,
            max_bytes_per_fn=max_bytes_per_fn)

    def build_module_call_stats(self, targets):
        """Scan ALL targeted functions, count how many times each internal
        address is called. The most-called internal addresses are the
        Nuitka runtime helpers (LOOKUP_ATTRIBUTE, CALL_FUNCTION_*, etc.) —
        we can't name them without symbols, but we can rank them and give
        them stable aliases so the same helper always shows the same label
        in every disassembly file.
        """
        from collections import Counter
        counter = Counter()
        # Pre-pass budget: keep each module entry at 8 KB / 2000 insns.
        # This is enough to see the call targets (every module entry
        # makes its first few thousand calls in the prologue) and
        # dramatically faster than the 65 KB full-body budget.
        # Ranking accuracy is unaffected — we only need relative
        # frequency, not exhaustive disassembly.
        for e in targets:
            try:
                info = self.analyse_function(e['func_ptr'], max_bytes=8192)
            except Exception:
                continue
            for c in info['calls']:
                if c['kind'] == 'internal':
                    counter[c['target']] += 1
        # Rank-based aliasing. Hot targets shared by many module entries are
        # runtime helpers; one-off targets are kept as fn_0x... so the BFS
        # can still chase real local code instead of over-skipping it.
        alias_map = {}
        sample_count = max(len(targets), 1)
        helper_min_count = max(2, sample_count // 25)
        for rank, (va, count) in enumerate(counter.most_common()):
            # First few are the hottest runtime helpers
            if rank < 20:
                alias_map[va] = f'RUNTIME_HELPER_{rank:02d}_x{va & 0xFFFF:04x}'
            elif count >= helper_min_count:
                alias_map[va] = f'helper_{rank:03d}_0x{va:X}'
            else:
                alias_map[va] = f'fn_0x{va:X}'
        return alias_map, counter

    @staticmethod
    def _estimate_mod_consts_base(const_loads, expected_count):
        """Guess the base address of the module's `mod_consts` struct.

        Every function in a Nuitka C-compiled module loads its constants
        via `mov reg, [mod_consts + 8*K]`. All those loads therefore cluster
        in a contiguous 8-byte-stride region of `.data`. We spot the tightest
        cluster (density close to 1 load per 8 bytes) and treat its minimum
        as the base, its (max - min) / 8 as the approximate count.

        Returns `(base_va, count)` or `(None, 0)` on failure.
        """
        if not const_loads:
            return None, 0
        targets = sorted({cl['target_va'] for cl in const_loads
                          if cl.get('section') == '.data'})
        if not targets:
            return None, 0

        # Build clusters: consecutive addresses with stride <= 16
        clusters = []
        current = [targets[0]]
        for va in targets[1:]:
            if va - current[-1] <= 16:
                current.append(va)
            else:
                clusters.append(current)
                current = [va]
        clusters.append(current)

        # The largest cluster is almost certainly mod_consts
        best = max(clusters, key=len)
        base = best[0]
        span = best[-1] - base
        count = (span // 8) + 1
        # Sanity: clamp count to a reasonable range
        if expected_count and count > expected_count * 2 + 20:
            count = expected_count + 20
        return base, count

    def _disasm_lru_get(self, key):
        try:
            out = self._disasm_lru.get(key)
        except Exception:
            return None
        if out is not None:
            try:
                self._disasm_lru.move_to_end(key)
            except Exception:
                pass
        return out

    def _disasm_lru_put(self, key, insns):
        try:
            self._disasm_lru[key] = insns
            self._disasm_lru.move_to_end(key)
            if len(self._disasm_lru) > self._disasm_lru_max_entries:
                self._disasm_lru.popitem(last=False)
        except Exception:
            pass

    def _bounded_disasm(self, va, max_bytes=80000):
        """Disassemble from `va` up to the first `ret` (or budget)."""
        rva = va - self.image_base
        _nm, sec, off = self._find_section_for_rva(rva)
        if not sec:
            return []
        cache_key = (sec.VirtualAddress, sec.SizeOfRawData)
        data = self._section_data_cache.get(cache_key)
        if data is None:
            data = sec.get_data()
            self._section_data_cache[cache_key] = data
        _lru_key = ('b', va, int(max_bytes))
        _cached = self._disasm_lru_get(_lru_key)
        if _cached is not None:
            return list(_cached)
        out = []
        for ins in self.md.disasm(data[off:off + max_bytes], va):
            out.append(ins)
            if ins.mnemonic == 'ret':
                break
        self._disasm_lru_put(_lru_key, out)
        return list(out)

    def _disasm_body(self, va, max_bytes=80000, func_extent=False):
        """Like _bounded_disasm but DOES NOT stop at the first `ret` when a REAL
        Python branch jumps past it: MSVC/Nuitka lay an alternate return path
        (e.g. the fall-through `return response.json()` after an early-return
        `if status == 429: return 429`) AFTER the early `ret` in address order.
        We extend the range past a `ret` only for a forward conditional jump that
        follows a `cmp` (a real `if`), NOT a `test reg,reg` null-check (scaffold /
        raise block) — so we recover the later return without pulling in error
        blocks. Used ONLY for the structurer's main walk (run_structured), so the
        narrow _bounded_disasm that feeds code-object / branch / loop recovery is
        unchanged (no cascade regressions). Single-return functions are identical
        to _bounded_disasm (no cmp-jcc extends past their sole ret).

        3.11+/Nuitka-V4.x EXCEPTION (func_extent=True AND _pycode_is_unstable):
        the extension is SUPPRESSED and the walk stops at the FIRST `ret`. On V4.x
        the comparison/contains helpers signal exceptions via an INT `res == -1`
        test (NUITKA_BOOL_EXCEPTION=-1, ComparisonCodes.getErrorExitBoolCode)
        emitted as `cmp eax,-1; je <error_exit>`, and MSVC lays every error-exit /
        refcount cold block OUT OF LINE past the shared epilogue; those cmp-driven
        edges would otherwise cascade the walk thousands of insns into LATER
        functions (measured: clean_ansi_codes 132 -> 2108 insns). Every V4.x
        function reaches its one real return through the shared epilogue, so the
        first ret is the true extent (verified: 100% of 1349 sampled 3.12 starts
        end on a ret under this bound). On 3.8-3.10 (_pycode_is_unstable False)
        func_extent is a NO-OP — the extension runs unchanged, so 3.10 is
        byte-identical. Mid-function callers (makeobj arg scan) leave it False."""
        rva = va - self.image_base
        _nm, sec, off = self._find_section_for_rva(rva)
        if not sec:
            return []
        cache_key = (sec.VirtualAddress, sec.SizeOfRawData)
        data = self._section_data_cache.get(cache_key)
        if data is None:
            data = sec.get_data()
            self._section_data_cache[cache_key] = data
        if func_extent:
            try:
                _fb, _fe = self._function_bounds(va)
                if _fb is not None and _fe is not None and _fb <= va < _fe:
                    max_bytes = min(max_bytes, max(1, _fe - va))
            except Exception:
                pass
        _tight = func_extent and getattr(self, '_pycode_is_unstable', False)
        _lru_key = ('d', va, int(max_bytes), bool(_tight))
        _cached = self._disasm_lru_get(_lru_key)
        if _cached is not None:
            return list(_cached)
        out = []
        max_target = va
        prev_m = None
        for ins in self.md.disasm(data[off:off + max_bytes], va):
            out.append(ins)
            m = ins.mnemonic
            if (not _tight and m[:1] == 'j' and m != 'jmp' and prev_m == 'cmp'
                    and ins.op_str.startswith('0x')):
                try:
                    t = int(ins.op_str, 16)
                    if t > max_target:
                        max_target = t
                except Exception:
                    pass
            if m == 'ret' and ins.address >= max_target:
                break
            if m != 'nop':
                prev_m = m
        self._disasm_lru_put(_lru_key, out)
        return list(out)

    # C-API symbols whose RDX=key / R8=value set a namespace __doc__/__qualname__.
    _DOC_SETITEM_SYMS = frozenset((
        'PyObject_SetItem', 'PyObject_SetAttr', 'PyObject_SetAttrString',
        'PyDict_SetItem'))

    def _recover_module_docstrings(self, func_ptr, consts, best_base, co_names,
                                   targets, disasm_cache=None):
        """Recover class / module / function docstrings from the module's native
        init code, WITHOUT relying on co_consts[0].

        Nuitka passes a single SHARED dummy co_consts tuple to PyCode_New for
        every code object (the real consts live in mod_consts), so co_consts[0]
        is NEVER the docstring. Instead Nuitka materialises __doc__ via two
        ABI-stable mechanisms (CPython 3.x Win64), both binary-evidenced here:
          * class / module __doc__ -> PyObject_SetItem(ns, '__doc__', value);
            the sibling SetItem(ns, '__qualname__', clsname) names the class.
          * function __doc__        -> the single free-text string stack-arg of
            the Nuitka_Function_New / MAKE_FUNCTION call whose RDX is the
            function's bare name and R8 its dotted qualname.
        Returns (doc_by_qualname, doc_by_name, module_doc). Pure evidence: an
        entity with no docstring resolves to None; nothing is fabricated.
        Universal — keys only off IAT C-API symbol names, the interned attribute
        keys '__doc__'/'__qualname__', and the Win64 RDX/R8 arg registers.
        """
        cxm = _capstone_x86
        if not best_base or not co_names:
            return {}, {}, None

        def _res(va):
            if va is None or (va - best_base) % 8 \
                    or not (0 <= (va - best_base) // 8 < len(consts)):
                return None
            return consts[(va - best_base) // 8]

        def _ident(s):
            return isinstance(s, str) and bool(re.fullmatch(r'[A-Za-z_]\w*', s))

        def _dotted(s):
            return isinstance(s, str) and '.' in s

        leaves = {n for n in co_names if _ident(n)}
        doc_by_qual, doc_by_name, module_doc = {}, {}, None
        for t in list(targets):
            sub = disasm_cache.pop(t, None) if disasm_cache is not None else None
            if sub is None:
                try:
                    sub = self._bounded_disasm(t)
                except Exception:
                    continue
            rc = {}; stk = {}; region_doc = None; region_qual = None
            for I in sub:
                op = I.operands
                if I.mnemonic in ('mov', 'lea') and len(op) == 2:
                    dd, s = op
                    if (dd.type == cxm.X86_OP_REG and s.type == cxm.X86_OP_MEM
                            and s.mem.base == cxm.X86_REG_RIP):
                        rc[dd.reg] = I.address + I.size + s.mem.disp
                    elif dd.type == cxm.X86_OP_REG:
                        rc.pop(dd.reg, None)
                    elif (dd.type == cxm.X86_OP_MEM
                          and dd.mem.base == cxm.X86_REG_RSP
                          and s.type == cxm.X86_OP_REG and s.reg in rc):
                        stk[dd.mem.disp] = rc[s.reg]
                elif I.mnemonic in ('call', 'callq'):
                    tgt = None
                    if (op and op[0].type == cxm.X86_OP_MEM
                            and op[0].mem.base == cxm.X86_REG_RIP):
                        tgt = I.address + I.size + op[0].mem.disp
                    elif op and op[0].type == cxm.X86_OP_REG:
                        # V95 Fix 3 (pseudo-PLT): `call reg` with reg loaded
                        # from ``mov reg, [rip+X]`` -> rc[reg] is the X VA.
                        _rg = rc.get(op[0].reg)
                        if _rg is not None:
                            tgt = _rg
                    ent = self._iat.get(tgt) if tgt is not None else None
                    sym = ent[1] if isinstance(ent, tuple) else ent
                    if sym in self._DOC_SETITEM_SYMS:
                        key = _res(rc.get(cxm.X86_REG_RDX))
                        val = _res(rc.get(cxm.X86_REG_R8))
                        if key == '__doc__' and isinstance(val, str):
                            region_doc = val
                        elif key == '__qualname__' and isinstance(val, str):
                            region_qual = val
                    else:
                        rdx = _res(rc.get(cxm.X86_REG_RDX))
                        r8 = _res(rc.get(cxm.X86_REG_R8))
                        if _ident(rdx) and rdx in leaves:
                            def _is_doc(c, _rdx=rdx, _r8=r8):
                                # A docstring is free text. Exclude the function's
                                # own name/qualname, any code-object name, and a
                                # pure dotted-identifier qualname (a real doc may
                                # legitimately END with '.', so never reject on
                                # "contains a dot" alone).
                                if not isinstance(c, str) or not c or c.startswith('<'):
                                    return False
                                if c == _rdx or c == _r8 or c in co_names:
                                    return False
                                if re.fullmatch(r'[A-Za-z_][\w.]*', c) and '.' in c:
                                    return False
                                return True
                            cand = [c for c in (_res(v) for v in stk.values())
                                    if _is_doc(c)]
                            if len(cand) == 1:
                                qkey = r8 if _dotted(r8) else rdx
                                doc_by_qual.setdefault(qkey, cand[0])
                                doc_by_name.setdefault(rdx, cand[0])
                    rc = {}; stk = {}
            if region_qual is not None and region_doc is not None:
                doc_by_qual.setdefault(region_qual, region_doc)
                doc_by_name.setdefault(region_qual, region_doc)
            elif region_doc is not None and t == func_ptr:
                module_doc = module_doc or region_doc
        return doc_by_qual, doc_by_name, module_doc

    def recover_code_objects(self, func_ptr, module_constants):
        """Recover EXACT code objects for a C-compiled Nuitka module.

        Every Python def/class/module body becomes a real PyCodeObject built
        at init time via PyCode_NewWithPosOnlyArgs(); its co_argcount,
        co_kwonlyargcount, co_flags are immediate operands and its co_name /
        co_varnames are pointers into the module's mod_consts array. We:
          1. follow the module init's internal calls to the function(s) that
             call PyCode_New* (the code-object creator),
          2. read (argcount, kwonly, flags, name_va, varnames_va) at each site,
          3. solve the module's mod_consts base by anchoring on the
             distinctive co_varnames TUPLE constants,
          4. resolve names/varnames and split args from locals.

        Returns a list of code-object dicts with `_native=True`. Universal for
        Nuitka on CPython 3.8-3.10 (Win64 ABI). Returns [] if unavailable.
        """
        cxm = _capstone_x86
        if not self._pycode_slot or not func_ptr or not module_constants:
            return []
        consts = list(module_constants)
        SLOT = self._pycode_slot
        CO_NEWLOCALS, CO_VARARGS, CO_VARKEYWORDS = 0x02, 0x04, 0x08
        CO_GENERATOR, CO_COROUTINE, CO_ASYNCGEN = 0x20, 0x80, 0x200
        # Win64 callee-saved GP registers (both 64- and 32-bit ids). MSVC hoists
        # a frequently-used small immediate (e.g. arg_count==1) into one of these
        # ONCE at module-init top and re-reads it before every
        # PyCode_NewWithPosOnlyArgs site (`mov ecx, esi`), so the immediate is no
        # longer at the call site itself. They survive the call, so the tracked
        # constant must persist across per-site resets to recover arg_count.
        _CALLEE_SAVED = set()
        for _rn in ('RBX', 'RBP', 'RSI', 'RDI', 'R12', 'R13', 'R14', 'R15',
                    'EBX', 'EBP', 'ESI', 'EDI', 'R12D', 'R13D', 'R14D', 'R15D'):
            _rid = getattr(cxm, 'X86_REG_' + _rn, None)
            if _rid is not None:
                _CALLEE_SAVED.add(_rid)

        def is_ident(s):
            return isinstance(s, str) and bool(re.fullmatch(r'[A-Za-z_]\w*', s))

        def is_codename(s):
            return isinstance(s, str) and (s.startswith('<') or is_ident(s))

        def is_vtuple(t):
            return isinstance(t, tuple) and all(is_ident(x) or x == '.0' for x in t)

        def pycode_call(ins, _rc=None):
            # V95 Fix 3 (universal, pseudo-PLT): MinGW/gcc materialises every
            # C-API call as `mov reg, qword ptr [rip+IAT_SLOT]` ... `call reg`
            # instead of MSVC's direct `call qword ptr [rip+IAT_SLOT]`.  When a
            # register-call context is available (``_rc`` maps reg -> RIP target
            # of the latest ``mov/lea reg, [rip+X]``), resolve the slot through
            # it so code-object sites are found on both compilers.
            if ins.mnemonic == 'call' and ins.operands:
                o0 = ins.operands[0]
                if o0.type == cxm.X86_OP_MEM \
                        and o0.mem.base == cxm.X86_REG_RIP:
                    return ins.address + ins.size + o0.mem.disp == SLOT
                if _rc is not None and o0.type == cxm.X86_OP_REG \
                        and _rc.get(o0.reg) == SLOT:
                    return True
            return False

        def collect_sites(ins):
            rc = {}; ri = {}; sc = {}; si = {}; res = []
            # PyCode_New* returns the freshly-created code object in RAX.  The
            # 3.8-3.10 Nuitka module init stores that pointer in a dedicated
            # RIP-relative slot shortly after the call; Nuitka_Function_New
            # later passes the SAME slot as its R9 code-object argument.  Keep
            # this exact ABI edge so duplicate leaves (e.g. a method and a
            # top-level function both named ``check``) do not get paired by a
            # size/name heuristic.
            pending_result = None
            _rax = getattr(cxm, 'X86_REG_RAX', -1)
            _rax_clobbers = {
                getattr(cxm, 'X86_REG_' + _n, -1)
                for _n in ('RAX', 'EAX', 'AX', 'AL', 'AH')
            }

            def _writable_pointer_slot(slot_va):
                try:
                    rva = int(slot_va) - int(self.image_base)
                    for _section in self.pe.sections:
                        _lo = int(_section.VirtualAddress)
                        _span = max(int(_section.Misc_VirtualSize or 0),
                                    int(_section.SizeOfRawData or 0))
                        if not (_lo <= rva < _lo + _span):
                            continue
                        _chars = int(_section.Characteristics or 0)
                        return bool((_chars & 0x80000000)
                                    and not (_chars & 0x20000000))
                except Exception:
                    pass
                return False
            for I in ins:
                if pycode_call(I, rc):
                    _site = dict(
                        argcount=ri.get(cxm.X86_REG_RCX, ri.get(cxm.X86_REG_ECX)) or 0,
                        kwonly=ri.get(cxm.X86_REG_R8, ri.get(cxm.X86_REG_R8D)) or 0,
                        flags=si.get(0x28) or 0,
                        name_va=sc.get(0x68), varnames_va=sc.get(0x48),
                        consts_va=sc.get(0x38),    # co_consts tuple; [0] is the docstring
                        # co_firstlineno: verified on the machine code of this
                        # helper's call sites - the 32-bit immediate store at
                        # [rsp+0x70], one slot past name_va ([rsp+0x68]), e.g.
                        # the <lambda> whose def sits at source line 394.
                        line=si.get(0x70) or 0,
                        call_site=I.address,
                        code_slot_va=None)
                    res.append(_site)
                    pending_result = _site
                    # Reset volatile per-call state, but KEEP constants the
                    # compiler hoisted into callee-saved registers: they persist
                    # across this call (Win64 ABI) and get re-used as the
                    # arg_count / kw-only immediates at the next site.
                    # V95 Fix 3 (pseudo-PLT): also keep rc entries that resolve
                    # to IAT slots — those are MinGW/gcc register bindings of
                    # imported C-API functions (loaded ONCE at function top,
                    # e.g. `mov rbp, [rip+PyCode_slot]`), not per-site
                    # constants, so they must survive the reset to match the
                    # next `call rbp` site.  Per-site .data/.rdata pointers are
                    # still dropped exactly as before.
                    rc = {r: v for r, v in rc.items()
                          if isinstance(v, int) and v in self._iat}
                    sc, si = {}, {}
                    ri = {r: v for r, v in ri.items() if r in _CALLEE_SAVED}
                    continue
                op = I.operands
                if pending_result is not None:
                    # The store is normally 1-8 instructions after the call.
                    # Bound the search and abandon it at any intervening call
                    # or RAX write: after either event RAX is no longer proven
                    # to be this PyCode_New result.
                    if (I.address - pending_result['call_site'] > 0x80
                            or I.mnemonic in ('call', 'callq')):
                        pending_result = None
                    elif (I.mnemonic == 'mov' and len(op) == 2
                            and op[0].type == cxm.X86_OP_MEM
                            and op[0].mem.base == cxm.X86_REG_RIP
                            and op[1].type == cxm.X86_OP_REG
                            and op[1].reg == _rax
                            and (getattr(op[0], 'size', 0) == 8
                                 or I.op_str.startswith('qword ptr '))):
                        _slot_va = I.address + I.size + op[0].mem.disp
                        if _writable_pointer_slot(_slot_va):
                            pending_result['code_slot_va'] = _slot_va
                        pending_result = None
                    elif (op and op[0].type == cxm.X86_OP_REG
                            and op[0].reg in _rax_clobbers
                            and I.mnemonic not in ('cmp', 'test')):
                        pending_result = None
                if (I.mnemonic == 'xor' and len(op) == 2
                        and op[0].type == op[1].type == cxm.X86_OP_REG
                        and op[0].reg == op[1].reg):
                    ri[op[0].reg] = 0; rc.pop(op[0].reg, None)
                    continue
                if I.mnemonic in ('mov', 'lea') and len(op) == 2:
                    dd, s = op
                    if dd.type == cxm.X86_OP_REG:
                        if s.type == cxm.X86_OP_IMM:
                            ri[dd.reg] = s.imm; rc.pop(dd.reg, None)
                        elif s.type == cxm.X86_OP_MEM and s.mem.base == cxm.X86_REG_RIP:
                            rc[dd.reg] = I.address + I.size + s.mem.disp
                            ri.pop(dd.reg, None)
                        elif (I.mnemonic == 'mov' and s.type == cxm.X86_OP_REG
                                and s.reg in ri):
                            # register copy of a tracked immediate (the hoisted
                            # arg_count): propagate it so RCX resolves at the site.
                            # NB: touch ONLY ri here. The rc (const-pointer) map
                            # must keep its original "leave stale" behaviour:
                            # Nuitka's empty-tuple null-check emits `mov rdx, rcx`
                            # AFTER loading the varnames-tuple pointer, and the
                            # later `mov [rsp+0x48], rdx` relies on rc[rdx] still
                            # holding that pointer to resolve co_varnames.
                            ri[dd.reg] = ri[s.reg]
                        else:
                            # any other write clobbers this reg's tracked
                            # immediate; drop it so a stale constant can't leak
                            # into a later arg_count/kw-only read. rc is left
                            # exactly as before (see note above).
                            ri.pop(dd.reg, None)
                    elif dd.type == cxm.X86_OP_MEM and dd.mem.base == cxm.X86_REG_RSP:
                        if s.type == cxm.X86_OP_IMM:
                            si[dd.mem.disp] = s.imm
                        elif s.type == cxm.X86_OP_REG and s.reg in rc:
                            sc[dd.mem.disp] = rc[s.reg]
            return res

        # 1) gather PyCode sites from init + the functions it calls
        max_init = getattr(self, '_entry_max_bytes', 65536)
        try:
            co_limit = max(1, int(getattr(self, '_co_target_limit', 400)))
        except (TypeError, ValueError):
            co_limit = 400
        try:
            info = self.analyse_function(func_ptr, max_bytes=max_init)
        except Exception:
            return []
        # The module entry point is the only target guaranteed to own this
        # module's ``mod_consts`` base.  V93 put it in a set with every helper
        # and then sliced that unordered set: under the balanced budget the
        # entry could land after the cutoff, producing zero code objects even
        # though its body contained dozens of PyCode_New calls.  Scan it first,
        # then deterministic, deduplicated helper VAs in call-site order up to
        # the same budget.  Call order also prioritises Nuitka's separately
        # compiled createModuleCodeObjects helper when the C compiler does not
        # inline it; numeric VA order has no such semantic relationship.
        targets = [func_ptr]
        seen_targets = {func_ptr}
        for call in info.get('calls', ()):
            target = call.get('target')
            if (call.get('kind') != 'internal'
                    or not isinstance(target, int) or target <= 0
                    or target in seen_targets):
                continue
            seen_targets.add(target)
            targets.append(target)
        sites = []
        # Cache pass-1 disasm so the docstring scan reuses it instead of
        # re-disassembling every target (which doubled emit time). Bounded by an
        # instruction budget so huge modules (e.g. ui) can't blow memory — any
        # target past the budget is simply re-disassembled on demand.
        _doc_subs = {}
        _doc_budget = 60000
        # V95 Fix 3 (pseudo-PLT): pre-scan with a lightweight register tracker
        # so `mov reg, [rip+SLOT]` ... `call reg` sites are detected too.
        def _sub_has_pycode_call(sub_insns):
            _rc = {}
            for I in sub_insns:
                if I.mnemonic == 'call':
                    if pycode_call(I, _rc):
                        return True
                    continue
                if I.mnemonic in ('mov', 'lea') and len(I.operands) == 2:
                    dd, s = I.operands
                    if dd.type == cxm.X86_OP_REG:
                        if (s.type == cxm.X86_OP_MEM
                                and s.mem.base == cxm.X86_REG_RIP):
                            _rc[dd.reg] = I.address + I.size + s.mem.disp
                        else:
                            _rc.pop(dd.reg, None)
            return False

        for t in targets[:co_limit]:
            try:
                sub = self._bounded_disasm(t)
            except Exception:
                continue
            if _doc_budget > 0:
                _doc_subs[t] = sub
                _doc_budget -= len(sub)
            if _sub_has_pycode_call(sub):
                sites.extend(collect_sites(sub))
        if not sites:
            return []

        # 2) solve mod_consts base by anchoring on co_varnames tuples
        from collections import Counter
        tuple_pos = {i: v for i, v in enumerate(consts) if is_vtuple(v) and v}
        votes = Counter()
        for s in sites:
            if s['varnames_va'] is None:
                continue
            for ti in tuple_pos:
                votes[s['varnames_va'] - 8 * ti] += 1
        if not votes:
            return []

        def resolve(va, base):
            if va is None or (va - base) % 8 or not (0 <= (va - base) // 8 < len(consts)):
                return None
            return consts[(va - base) // 8]

        # Strong anchors for the correct base: the module body's co_name is
        # always '<module ...>', and every method leaf appears as the tail of a
        # dotted `Class.method` qualname. A base that resolves those is almost
        # certainly right; one that merely resolves arbitrary identifiers (the
        # failure mode on modules with few/ambiguous varname tuples) is not.
        known_leaves = set()
        for c in consts:
            if (isinstance(c, str) and '.' in c and '<' not in c and ' ' not in c
                    and not c.endswith(('.py', '.pyc'))):
                parts = c.replace('.<locals>', '').split('.')
                if len(parts) >= 2 and parts[0][:1].isupper() \
                        and all(re.fullmatch(r'[A-Za-z_]\w*', p) for p in parts):
                    known_leaves.add(parts[-1])

        def base_score(base):
            ok = bonus = 0
            for s in sites:
                nm = resolve(s['name_va'], base)
                vn = resolve(s['varnames_va'], base)
                if is_codename(nm) and (vn is None or is_vtuple(vn)):
                    ok += 1
                    if isinstance(nm, str) and nm.startswith('<module'):
                        bonus += 50          # the module body — decisive anchor
                    elif nm in known_leaves:
                        bonus += 5           # a real method name
            return ok + bonus

        best_base, best = None, -1
        for base, _ in votes.most_common(60):
            sc = base_score(base)
            if sc > best:
                best, best_base = sc, base
        if best_base is None:
            return []
        # Stash the robustly-solved base so recover_body_traces (called right
        # after, for the same module) can reuse it instead of the weaker
        # const-load estimator.
        self._last_mod_consts_base = best_base

        # 3) build code objects
        out, seen = [], set()
        for s in sites:
            nm = resolve(s['name_va'], best_base)
            vn = resolve(s['varnames_va'], best_base)
            if not is_codename(nm):
                continue
            if vn is not None and not is_vtuple(vn):
                continue
            argc = s['argcount']; kw = s['kwonly']; flags = s['flags']
            vt = list(vn) if isinstance(vn, tuple) else []
            # Guard: arg_count + kw-only can never exceed the number of
            # co_varnames (params are the leading slots). An implausible value
            # means the immediate was mis-tracked -> fall back to 0 rather than
            # fabricate parameters out of locals.
            if not (0 <= argc and argc + (kw or 0) <= len(vt)):
                argc = 0
            sig = vt[:argc]
            kk = argc
            kwonly_names = vt[kk:kk + kw]; kk += kw
            if flags & CO_VARARGS and kk < len(vt):
                sig.append('*' + vt[kk]); kk += 1
            elif kwonly_names:
                sig.append('*')
            sig += kwonly_names
            if flags & CO_VARKEYWORDS and kk < len(vt):
                sig.append('**' + vt[kk]); kk += 1
            sig = _ndl_sanitize_def_args(sig)
            # Distinct PyCode_New sites/slots are distinct code objects even
            # when name, signature and locals are byte-identical (common for
            # sibling class methods such as ``__init__(self)``).
            key = (s.get('code_slot_va') or s.get('call_site'),
                   nm, argc, tuple(vt))
            if key in seen:
                continue
            seen.add(key)
            # Docstrings are recovered AFTER this loop from the native init code
            # (PyObject_SetItem(__doc__) for classes/modules; the MAKE_FUNCTION
            # free-text stack arg for functions). co_consts[0] is NOT the
            # docstring under Nuitka (shared dummy co_consts tuple).
            doc = None
            _line = s.get('line') or 0
            try:
                _line = int(_line)
                if not (0 < _line <= 1000000):
                    _line = 0
            except Exception:
                _line = 0
            out.append({
                '_type': 'CodeObject', '_native': True, 'name': nm,
                'argcount': argc, 'kwonly': kw, 'flags': flags,
                'args': sig, 'varnames': vt, 'docstring': doc,
                'is_async': bool(flags & (CO_COROUTINE | CO_ASYNCGEN)),
                'is_gen': bool(flags & CO_GENERATOR),
                'line': _line,
                '_code_slot_va': s.get('code_slot_va'),
                '_code_create_call_va': s.get('call_site'),
            })

        # Recover docstrings from the native init code and attach them to the
        # code objects. Keyed by bare name; recovery runs PER MODULE so most leaf
        # names are unique. A leaf-uniqueness guard means an ambiguous leaf (two
        # same-named methods in different classes) is left undocumented rather
        # than risk attaching one class's doc to the other (never fabricate). The
        # qualname map is stashed for a future collision-aware consumer.
        try:
            from collections import Counter as _Counter
            out_names = {str(c['name']) for c in out if c.get('name')}
            doc_q, doc_n, mod_doc = self._recover_module_docstrings(
                func_ptr, consts, best_base, out_names,
                list(targets)[:co_limit], disasm_cache=_doc_subs)
            self._doc_by_qualname = doc_q
            self._doc_by_name = doc_n
            self._module_docstring = mod_doc
            _name_counts = _Counter(str(c.get('name') or '') for c in out)
            for c in out:
                nm = str(c.get('name') or '')
                d = doc_q.get(nm)                       # class name (unique) hit
                if not d and _name_counts[nm] == 1:     # leaf unique -> safe
                    d = doc_n.get(nm)
                if isinstance(d, str) and d:
                    c['docstring'] = d
        except Exception:
            pass
        return out

    # Names emitted by the compiler at the top of every function body
    # (module/class machinery), never part of the function's real logic.
    _BODY_TRACE_MACHINERY = frozenset({
        '__qualname__', '__name__', '__module__', '__doc__', '__file__',
        '__spec__', '__cached__', '__dict__', '__class__', '__package__',
        '__loader__', '__builtins__', '__orig_bases__', '__prepare__',
        '__mro_entries__', '__set_name__', '__init_subclass__',
        'origin', 'has_location', 'metaclass',
    })

    # CPython 3.10 x64 type-slot offsets used to recover operators statically.
    # An operator is identified ONLY by the CHAINED dataflow pattern
    #   mov R, [type + tp_as_number(0x60)]   ; R = tp_as_number
    #   mov R2, [R + nb_slot]                 ; R2 = the operator's C function
    #   call R2
    # Flat offset matching is NOT safe (0x18/0x58/0x60... collide with frame
    # and thread-state fields), so we require the two-step register chain.
    # CPython x64 ABI offsets — stable across CPython 3.5-3.12, so universal
    # across Nuitka Win64 binaries (NOT specific to any one .exe).
    _TP_AS_NUMBER = 0x60
    _TP_AS_MAPPING = 0x70
    _MP_SUBSCRIPT = 0x08          # PyMappingMethods.mp_subscript  -> obj[key]
    _MP_ASS_SUBSCRIPT = 0x10      # PyMappingMethods.mp_ass_subscript -> obj[key]=v / del obj[key]
    # nb_add is at offset 0x00.  It is safe here only after the preceding
    # ``mov R,[type + tp_as_number]`` has established that the base register
    # is the numeric-method table; an unrelated zero-displacement dereference
    # is never promoted without that dataflow proof.
    _NB_SLOTS = {0x00: '+', 0x08: '-', 0x10: '*', 0x18: '%', 0x28: '**',
                 0x58: '<<', 0x60: '>>', 0x68: '&', 0x70: '^', 0x78: '|',
                 0xe8: '//', 0xf0: '/', 0x110: '@'}
    # x86 ops that overwrite the CPU flags (so an earlier cmp no longer governs
    # a later branch). Used by recover_real_branches to avoid attributing a
    # refcount `sub [m],1; jne` to a preceding `cmp reg,None`.
    _FLAG_CLOBBER = frozenset({
        'add', 'sub', 'adc', 'sbb', 'and', 'or', 'xor', 'inc', 'dec', 'neg',
        'mul', 'imul', 'div', 'idiv', 'shl', 'shr', 'sar', 'sal', 'rol',
        'ror', 'bt', 'bts', 'btr', 'cmpxchg', 'lock',
    })

    def _function_bounds(self, va):
        """Return the logical (start, end) of an x64 native function.

        `.pdata` contains physical unwind fragments, not necessarily one record
        per C function.  `_pdata_logical` merges fragments linked through
        UNW_FLAG_CHAININFO, so callers inside a chained/cold fragment resolve to
        the same canonical start as the primary function.  Return (None, None)
        when unwind metadata is unavailable.
        """
        try:
            import bisect
            if not self._pdata_ranges:
                return None, None
            _i = bisect.bisect_right(self._pdata_starts, int(va)) - 1
            if _i >= 0:
                _b, _e = self._pdata_ranges[_i]
                if _b <= va < _e:
                    return self._pdata_logical.get(_b, (_b, _e))
        except Exception:
            pass
        return None, None

    def _find_makeobj_wrapper(self):
        """Small isolation wrapper for the shared-helper locator.

        Keeping the large .text scan in its own completed Python frame before
        the caller starts the 10k+ metadata pass avoids retaining the temporary
        section buffer/iterator state across the next Capstone phase.  This is
        functionally identical to the implementation below, but proved
        deterministic on very large PE images where direct inlined sequencing
        occasionally stalled in the following disassembly pass.
        """
        return self._find_makeobj_wrapper_impl()

    def _find_makeobj_wrapper_impl(self):
        """CPython 3.11+ code-object recovery. Modern Nuitka creates EVERY code
        object through ONE shared helper `makeCodeObject` (compiled_frame.h) that
        wraps PyUnstable_Code_NewWithPosOnlyArgs — so there is exactly ONE call to
        `_pycode_slot` in the whole binary, inside that helper, and the per-function
        metadata is passed as ARGS to the helper (not as call-site immediates like
        3.8-3.10). This finds the helper = the function that contains the single
        PyCode call. Cached per binary; returns None on 3.8-3.10 (many call sites)
        or if not found."""
        # Disassemblers are recreated for each emitted module, but the PE
        # image is shared by the whole run.  Cache this binary-wide .text scan
        # on the PE object; otherwise a 60-module application rescans the same
        # tens-of-megabytes section once per module.
        _pe_cached = getattr(self.pe, '_ndl_makeobj_wrapper_cached', None)
        if _pe_cached is not None or getattr(
                self.pe, '_ndl_makeobj_wrapper_scanned', False):
            self._makeobj_wrapper_cached = _pe_cached
            return _pe_cached
        self._makeobj_wrapper_cached = None
        slot = self._pycode_slot
        if not slot:
            return None
        sites = []
        for section in self.pe.sections:
            if section.Name.rstrip(b'\x00') != b'.text':
                continue
            d = section.get_data(); base = self.image_base + section.VirtualAddress
            # Sparse opcode search instead of a Python byte-by-byte walk over
            # 40-100 MB .text sections. Validation by the computed RIP target
            # makes false opcode bytes harmless.
            i = d.find(b'\xff\x15')
            while i >= 0 and i + 6 <= len(d):
                disp = struct.unpack_from('<i', d, i + 2)[0]
                if base + i + 6 + disp == slot:
                    sites.append(base + i)
                    if len(sites) > 3:
                        self.pe._ndl_makeobj_wrapper_scanned = True
                        self.pe._ndl_makeobj_wrapper_cached = None
                        return None    # old direct-call layout, not one wrapper
                i = d.find(b'\xff\x15', i + 1)
            break
        if len(sites) != 1:
            self.pe._ndl_makeobj_wrapper_scanned = True
            self.pe._ndl_makeobj_wrapper_cached = None
            return None
        self._makeobj_wrapper_cached = self._makeobj_func_start(sites[0])
        self.pe._ndl_makeobj_wrapper_scanned = True
        self.pe._ndl_makeobj_wrapper_cached = self._makeobj_wrapper_cached
        return self._makeobj_wrapper_cached

    def _makeobj_func_start(self, addr):
        """Start VA of the function containing `addr`.

        Prefer the exact PE x64 unwind range. The legacy backward prologue scan
        is retained only as a fallback for binaries without .pdata; unlike the
        old implementation it disassembles a raw range and therefore cannot be
        truncated by a `ret` belonging to the previous function.
        """
        _b, _e = self._function_bounds(addr)
        if _b is not None:
            return _b
        try:
            _start = max(self.image_base, addr - 0x600)
            _rva = _start - self.image_base
            _nm, _sec, _off = self._find_section_for_rva(_rva)
            if _sec is None:
                return None
            _blob = _sec.get_data()[_off:_off + (addr - _start) + 8]
            ins = list(self.md.disasm(_blob, _start))
        except Exception:
            return None
        best = None
        for k, i in enumerate(ins):
            if i.address >= addr:
                break
            if i.mnemonic == 'sub' and i.op_str.startswith('rsp,'):
                j = k - 1
                s = i.address
                # MSVC often spills non-volatiles to caller shadow-space before
                # its push cluster, so include adjacent mov [rsp+off],reg stores.
                while j >= 0 and (ins[j].mnemonic == 'push' or
                                  (ins[j].mnemonic == 'mov' and
                                   ins[j].op_str.startswith('qword ptr [rsp + '))):
                    s = ins[j].address
                    j -= 1
                best = s
        return best

    def _read_makeobj_args(self, call_site):
        """Read one makeCodeObject caller's args (Win64 ABI). Signature (3.11+):
        (filename, line, flags, name, qualname, arg_names, free_vars, arg_count,
         kw_only, pos_only) → name=r9, qualname=[rsp+0x20], arg_names=[rsp+0x28],
        flags=r8d, arg_count=[rsp+0x38], kw_only=[rsp+0x40], line=edx. The name/
        qualname/arg_names pointers are loaded from mod_consts SLOTS
        (`mov r9,[rip+X]`); X is the slot VA — resolved by index vs mcb, NOT
        dereferenced (the slots are runtime-filled, 0 in the file)."""
        try:
            ins = list(self._disasm_body(call_site - 0x70, max_bytes=0x78))
        except Exception:
            return None
        reg = {}
        stk = {}

        def _rip(i):
            m = re.search(r'\[rip \+ (0x[0-9a-f]+)\]', i.op_str)
            return (i.address + i.size + int(m.group(1), 16)) if m else None

        for i in ins:
            if i.address >= call_site:
                break
            if i.mnemonic not in ('mov', 'lea') or ',' not in i.op_str:
                continue
            dd, s = [x.strip() for x in i.op_str.split(',', 1)]
            val = None
            if s.startswith('0x') or re.fullmatch(r'-?\d+', s):
                val = ('imm', int(s, 0))
            elif '[rip' in s:
                val = ('slot', _rip(i))
            elif re.fullmatch(r'[a-z0-9]+', s) and s in reg:
                val = reg[s]
            if re.fullmatch(r'[a-z0-9]+', dd):
                if val:
                    reg[dd] = val
                else:
                    reg.pop(dd, None)
            elif '[rsp' in dd:
                m2 = re.search(r'\[rsp \+ (0x[0-9a-f]+)\]', dd)
                if m2 and val:
                    stk[int(m2.group(1), 16)] = val

        def _imm(v):
            return v[1] if (v and v[0] == 'imm') else None

        def _slot(v):
            return v[1] if (v and v[0] == 'slot') else None
        return {
            'filename_va': _slot(reg.get('rcx')),
            'name_va': _slot(reg.get('r9')),
            'qualname_va': _slot(stk.get(0x20)),
            'varnames_va': _slot(stk.get(0x28)),
            'flags': _imm(reg.get('r8d')) or _imm(reg.get('r8')) or 0,
            'argcount': _imm(stk.get(0x38)) or 0,
            'kwonly': _imm(stk.get(0x40)) or 0,
            'line': _imm(reg.get('edx')) or _imm(reg.get('rdx')) or 0,
        }

    def _makeobj_callers(self, owner_filter=None):
        """Recover every 3.11+ ``makeCodeObject`` call and its exact metadata.

        The old implementation disassembled a separate 0x78-byte window for
        every call site. Large applications contain 10k+ code objects, making
        that both slow and fragile at basic-block boundaries. This version:

        * finds direct callers with sparse ``bytes.find`` opcode scans;
        * groups them by exact PE ``.pdata`` function range;
        * disassembles each owner function once;
        * symbolically tracks the Win64 register/stack call arguments; and
        * records the destination ``code_objects_*`` slot written after the call.

        The ABI comes directly from Nuitka's ``compiled_frame.h`` for CPython
        3.11+: filename, line, flags, name, qualname, arg_names, free_vars,
        arg_count, kw_only_count, pos_only_count. No target-specific addresses
        are embedded. Falls back to the legacy local-window reader when unwind
        metadata is unavailable.
        """
        # Whole-binary callers are retained for compatibility, but source emit
        # normally requests one exact createModuleCodeObjects owner.  Keeping a
        # per-owner cache avoids symbolically disassembling every dependency in
        # a 1,000+ module standalone binary before the first requested file.
        if owner_filter is None:
            _c = getattr(self.pe, '_ndl_makeobj_callers', None)
            if _c is not None:
                self._makeobj_callers_cached = _c
                return _c
            if hasattr(self, '_makeobj_callers_cached'):
                return self._makeobj_callers_cached
        else:
            _owner_cache = getattr(self.pe, '_ndl_makeobj_callers_by_owner', None)
            if _owner_cache is not None and owner_filter in _owner_cache:
                return _owner_cache[owner_filter]

        out = []
        wrapper = self._find_makeobj_wrapper()
        if not wrapper:
            self._makeobj_callers_cached = out
            return out

        _site_index = getattr(self.pe, '_ndl_makeobj_owner_sites', None)
        if owner_filter:
            # Targeted source emit: the exact owner is already known from a
            # shallow walk of the module entry. Search only that function for
            # calls to makeCodeObject; never enumerate every E8 in the PE.
            text_section = None
            for section in self.pe.sections:
                if section.Name.rstrip(b'\x00') == b'.text':
                    text_section = section
                    break
            b, e = self._function_bounds(owner_filter)
            if text_section is None or b is None or e is None:
                return out
            d = text_section.get_data()
            text_base = self.image_base + text_section.VirtualAddress
            lo = max(0, b - text_base)
            hi = min(len(d), e - text_base)
            if _ndl_live_opt('targeted_only'):
                hi = min(hi, lo + 0x4000)
            # Complete mode keeps the exact .pdata range: large GUI modules
            # can emit createModuleCodeObjects bodies well above 16 KiB.
            call_sites = []
            i = d.find(b'\xe8', lo, hi)
            while i >= 0 and i + 5 <= hi:
                rel = struct.unpack_from('<i', d, i + 1)[0]
                if text_base + i + 5 + rel == wrapper:
                    call_sites.append(text_base + i)
                i = d.find(b'\xe8', i + 1, hi)
            by_owner = OrderedDict([((b, e), call_sites)]) if call_sites else OrderedDict()
            no_bounds = []
        elif _site_index is None:
            text_section = None
            for section in self.pe.sections:
                if section.Name.rstrip(b'\x00') == b'.text':
                    text_section = section
                    break
            if text_section is None:
                self._makeobj_callers_cached = out
                return out

            d = text_section.get_data()
            text_base = self.image_base + text_section.VirtualAddress
            call_sites = []
            i = d.find(b'\xe8')
            while i >= 0 and i + 5 <= len(d):
                rel = struct.unpack_from('<i', d, i + 1)[0]
                if text_base + i + 5 + rel == wrapper:
                    call_sites.append(text_base + i)
                i = d.find(b'\xe8', i + 1)
            if not call_sites:
                self._makeobj_callers_cached = out
                return out

            # Group call sites by exact native function range without decoding
            # the owners yet. This cheap address index is shared by every module.
            by_owner = OrderedDict()
            no_bounds = []
            for site in call_sites:
                b, e = self._function_bounds(site)
                if b is None:
                    no_bounds.append(site)
                else:
                    by_owner.setdefault((b, e), []).append(site)
            _site_index = (d, text_base, call_sites, by_owner, no_bounds)
            try:
                self.pe._ndl_makeobj_owner_sites = _site_index
            except Exception:
                pass
        else:
            d, text_base, call_sites, by_owner, no_bounds = _site_index

        if owner_filter is not None and not owner_filter:
            by_owner = OrderedDict(
                (k, v) for k, v in by_owner.items() if k[0] == owner_filter)
            # Sites without unwind bounds cannot be assigned safely to a module.
            no_bounds = []

        _RA = {
            'eax': 'rax', 'ax': 'rax', 'al': 'rax',
            'ebx': 'rbx', 'bx': 'rbx', 'bl': 'rbx',
            'ecx': 'rcx', 'cx': 'rcx', 'cl': 'rcx',
            'edx': 'rdx', 'dx': 'rdx', 'dl': 'rdx',
            'esi': 'rsi', 'si': 'rsi', 'sil': 'rsi',
            'edi': 'rdi', 'di': 'rdi', 'dil': 'rdi',
            'ebp': 'rbp', 'bp': 'rbp', 'bpl': 'rbp',
            'r8d': 'r8', 'r8w': 'r8', 'r8b': 'r8',
            'r9d': 'r9', 'r9w': 'r9', 'r9b': 'r9',
            'r10d': 'r10', 'r10w': 'r10', 'r10b': 'r10',
            'r11d': 'r11', 'r11w': 'r11', 'r11b': 'r11',
            'r12d': 'r12', 'r12w': 'r12', 'r12b': 'r12',
            'r13d': 'r13', 'r13w': 'r13', 'r13b': 'r13',
            'r14d': 'r14', 'r14w': 'r14', 'r14b': 'r14',
            'r15d': 'r15', 'r15w': 'r15', 'r15b': 'r15',
        }

        def _rn(insn, reg_id):
            n = insn.reg_name(reg_id)
            return _RA.get(n, n)

        def _imm(v):
            return v[1] if v and v[0] == 'imm' else None

        def _slot(v):
            return v[1] if v and v[0] == 'slot' else None

        volatile = ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11')
        callset_all = set(call_sites)

        for (owner_start, owner_end), owner_sites in by_owner.items():
            # All direct callers were found in the already-cached .text bytes;
            # slice that one buffer directly. Calling pefile.get_data() for each
            # of hundreds of groups may copy the entire 40-100 MB section and
            # turns a 2-second pass into minutes.
            off = owner_start - text_base
            max_len = max(0, min(owner_end - owner_start, len(d) - off))
            if off < 0 or max_len <= 0:
                no_bounds.extend(owner_sites)
                continue
            blob = d[off:off + max_len]
            owner_set = set(owner_sites)
            regs, stk = {}, {}
            pending = None
            pending_age = 0

            for insn in self.md.disasm(blob, owner_start):
                mn = insn.mnemonic
                ops = insn.operands

                # Capture the static code_objects_* destination. Usually this is
                # ``mov [rip+slot], rax`` immediately after the wrapper call, but
                # result tags also survive a short register move chain.
                if pending is not None:
                    pending_age += 1
                    if mn == 'mov' and len(ops) == 2:
                        dst, src = ops
                        if (dst.type == _capstone_x86.X86_OP_MEM
                                and dst.mem.base == _capstone_x86.X86_REG_RIP
                                and dst.mem.index == 0
                                and src.type == _capstone_x86.X86_OP_REG):
                            sv = regs.get(_rn(insn, src.reg))
                            if sv and sv[0] == 'result' and sv[1] is pending:
                                pending['code_slot_va'] = (
                                    insn.address + insn.size + dst.mem.disp)
                                pending = None
                    if pending is not None and (pending_age > 16 or mn in ('ret', 'jmp')):
                        pending = None

                if mn in ('mov', 'lea') and len(ops) == 2:
                    dst, src = ops
                    val = None
                    if src.type == _capstone_x86.X86_OP_IMM:
                        val = ('imm', int(src.imm))
                    elif src.type == _capstone_x86.X86_OP_REG:
                        val = regs.get(_rn(insn, src.reg))
                    elif (src.type == _capstone_x86.X86_OP_MEM
                          and src.mem.base == _capstone_x86.X86_REG_RIP
                          and src.mem.index == 0):
                        val = ('slot', insn.address + insn.size + src.mem.disp)
                    elif (src.type == _capstone_x86.X86_OP_MEM
                          and src.mem.base == _capstone_x86.X86_REG_RSP
                          and src.mem.index == 0):
                        val = stk.get(int(src.mem.disp))

                    if dst.type == _capstone_x86.X86_OP_REG:
                        dr = _rn(insn, dst.reg)
                        if val is None:
                            regs.pop(dr, None)
                        else:
                            regs[dr] = val
                    elif (dst.type == _capstone_x86.X86_OP_MEM
                          and dst.mem.base == _capstone_x86.X86_REG_RSP
                          and dst.mem.index == 0):
                        so = int(dst.mem.disp)
                        if val is None:
                            stk.pop(so, None)
                        else:
                            stk[so] = val

                elif (mn in ('xor', 'sub') and len(ops) == 2
                      and ops[0].type == _capstone_x86.X86_OP_REG
                      and ops[1].type == _capstone_x86.X86_OP_REG
                      and ops[0].reg == ops[1].reg):
                    regs[_rn(insn, ops[0].reg)] = ('imm', 0)

                if insn.address in owner_set:
                    rec = {
                        'call_site': insn.address,
                        'owner_start': owner_start,
                        'filename_va': _slot(regs.get('rcx')),
                        'name_va': _slot(regs.get('r9')),
                        'qualname_va': _slot(stk.get(0x20)),
                        'varnames_va': _slot(stk.get(0x28)),
                        'freevars_va': _slot(stk.get(0x30)),
                        'flags': _imm(regs.get('r8')) or 0,
                        'argcount': _imm(stk.get(0x38)) or 0,
                        'kwonly': _imm(stk.get(0x40)) or 0,
                        'posonly': _imm(stk.get(0x48)) or 0,
                        'line': _imm(regs.get('rdx')) or 0,
                    }
                    if os.environ.get('NDL_DEBUG_MAKEOBJ') == '1':
                        print('[MAKEOBJDBG] site=%#x owner=%#x line=%r '
                              'argc=%r kw=%r pos=%r stack=%r' % (
                                  insn.address, owner_start, rec['line'],
                                  rec['argcount'], rec['kwonly'],
                                  rec['posonly'],
                                  {hex(_k): _v for _k, _v in sorted(stk.items())
                                   if 0x20 <= _k <= 0x50}), flush=True)
                    if rec['name_va']:
                        out.append(rec)
                        pending = rec
                        pending_age = 0
                        regs['rax'] = ('result', rec)
                    for r in volatile:
                        if r != 'rax':
                            regs.pop(r, None)
                    for so in (0x20, 0x28, 0x30, 0x38, 0x40, 0x48):
                        stk.pop(so, None)

                elif mn == 'call':
                    for r in volatile:
                        regs.pop(r, None)

        # Unwind metadata may be absent on x86 or deliberately stripped. Keep
        # correctness via the legacy per-site slice reader in that case.
        for site in no_bounds:
            a = self._read_makeobj_args(site)
            if a and a.get('name_va'):
                a['call_site'] = site
                out.append(a)

        out.sort(key=lambda x: x.get('call_site', 0))
        if owner_filter is None:
            self._makeobj_callers_cached = out
            try:
                self.pe._ndl_makeobj_callers = out
            except Exception:
                pass
        else:
            try:
                cache = getattr(self.pe, '_ndl_makeobj_callers_by_owner', None)
                if cache is None:
                    cache = {}
                    self.pe._ndl_makeobj_callers_by_owner = cache
                cache[owner_filter] = out
            except Exception:
                pass
        return out

    def _makeobj_owner_for_module(self, func_ptr):
        """Return the exact ``createModuleCodeObjects`` owner for a module.

        On CPython 3.11+ Nuitka emits one native owner function per compiled
        module. The module entry point calls that owner before executing module
        code. PE x64 ``.pdata`` gives exact function boundaries, so this is a
        deterministic ownership join rather than a proximity heuristic. A
        shallow call-graph fallback supports builds that add one small wrapper.
        ``None`` means the module genuinely has no streamed code objects or the
        required unwind metadata is unavailable.
        """
        try:
            fp = int(func_ptr or 0)
        except Exception:
            return None
        if not fp:
            return None
        cache = getattr(self.pe, '_ndl_makeobj_owner_by_module', None)
        if cache is None:
            cache = {}
            self.pe._ndl_makeobj_owner_by_module = cache
        if fp in cache:
            return cache[fp]

        wrapper = self._find_makeobj_wrapper()
        if not wrapper:
            cache[fp] = None
            return None

        b0, e0 = self._function_bounds(fp)
        # Breadth-first search is deliberately shallow. Normal Nuitka builds
        # hit at depth 1: module init -> createModuleCodeObjects -> shared
        # makeCodeObject. Crucially, this touches only the requested module.
        frontier = [(b0 or fp, e0, 0)]
        seen = set()
        hits_by_depth = {}
        while frontier:
            start, end, depth = frontier.pop(0)
            if start in seen or depth > 1:
                continue
            seen.add(start)
            if end is None:
                _b, _e = self._function_bounds(start)
                start, end = (_b or start), _e
            max_bytes = min(0x40000, max(0x100, (end - start) if end else 0x20000))
            if _ndl_live_opt('targeted_only'):
                # Fast/adaptive static-only recovery only needs the shallow
                # module-to-owner edge; generated initialisers can span huge
                # ranges and scanning all of them defeats the bounded profile.
                max_bytes = min(max_bytes, 0x4000)
            # Complete mode keeps the pdata-derived extent (already capped at
            # 256 KiB above). The previous 16 KiB cap hid createModuleCodeObjects
            # for large application modules.
            try:
                ins = list(self._disasm_body(start, max_bytes=max_bytes, func_extent=True))
            except Exception:
                continue
            next_funcs = []
            for I in ins:
                if I.mnemonic not in ('call', 'jmp') or not I.operands:
                    continue
                op = I.operands[0]
                if op.type != _capstone_x86.X86_OP_IMM:
                    continue
                tgt = int(op.imm)
                if tgt == wrapper:
                    hits_by_depth.setdefault(depth, []).append(start)
                elif depth < 1:
                    tb, te = self._function_bounds(tgt)
                    if tb is not None:
                        next_funcs.append((tb, te, depth + 1))
            if depth in hits_by_depth:
                uniq = list(OrderedDict.fromkeys(hits_by_depth[depth]))
                if len(uniq) == 1:
                    cache[fp] = uniq[0]
                    return uniq[0]
                # More than one owner at the same minimum depth is ambiguous;
                # refusing is safer than borrowing another module's metadata.
                cache[fp] = None
                return None
            frontier.extend(next_funcs)

        cache[fp] = None
        return None

    def _align_unstreamed_constant_slots(self, module_constants, callers, mcb):
        """Expand a historical compressed blob stream to true ``mod_consts`` slots.

        Some older Nuitka generations reserve constants that are initialized by
        C code instead of writing them to the blob. The chunk header still gives
        the full slot count, while the stream ends early with ``.``. Native
        ``name_va``/``qualname_va``/``varnames_va`` addresses index the full
        array, so treating the streamed list as dense shifts every later code
        object.

        We recover the missing-slot positions with a small sequence-alignment
        dynamic program. Constraints come only from the exact makeCodeObject ABI:
        names/qualnames must be strings and var/free names must be string tuples.
        Missing slots remain an opaque sentinel; no value is fabricated. The
        aligned mapping is accepted only when it improves the number of fully
        consistent code-object descriptors.
        """
        values = list(module_constants)
        declared = int(getattr(module_constants, 'declared_count', len(values)) or len(values))
        gap = declared - len(values)
        if gap <= 0 or not callers or not mcb:
            return values
        # Corrupt counts or a wrong chunk should not trigger a huge DP.
        if declared > 60000 or gap > 4096 or gap * 2 > declared:
            return values

        roles = [set() for _ in range(declared)]
        for c in callers:
            for field, role in (('name_va', 'n'), ('qualname_va', 'q'),
                                ('varnames_va', 'v'), ('freevars_va', 'f')):
                va = c.get(field)
                if not va or (va - mcb) % 8:
                    continue
                idx = (va - mcb) // 8
                if 0 <= idx < declared:
                    roles[idx].add(role)
        if not any(roles):
            return values + [_Nuitka_UNSTREAMED_SLOT] * gap

        _idre = re.compile(r'(?:[A-Za-z_]\w*|<[^>]+>)\Z')

        def _slot_score(idx, value):
            rs = roles[idx]
            if not rs:
                return 0
            score = 0
            if 'n' in rs:
                score += 12 if (isinstance(value, str) and _idre.fullmatch(value)) else -25
            if 'q' in rs:
                score += 10 if isinstance(value, str) else -20
            if 'v' in rs:
                good = isinstance(value, tuple) and all(isinstance(x, str) for x in value)
                score += 16 if good else -30
            if 'f' in rs:
                good = isinstance(value, tuple) and all(isinstance(x, str) for x in value)
                score += 8 if good else -12
            return score

        neg = -10 ** 12
        previous = [neg] * (gap + 1)
        previous[0] = 0
        back_rows = []
        streamed = len(values)

        for actual_idx in range(declared):
            current = [neg] * (gap + 1)
            back = bytearray(gap + 1)  # 0=consume stream value, 1=missing slot
            constrained = bool(roles[actual_idx])
            for holes_used in range(gap + 1):
                stream_idx = actual_idx - holes_used
                if 0 <= stream_idx < streamed and previous[holes_used] > neg:
                    score = previous[holes_used] + _slot_score(
                        actual_idx, values[stream_idx])
                    if score > current[holes_used]:
                        current[holes_used] = score
                        back[holes_used] = 0
                if holes_used and previous[holes_used - 1] > neg:
                    score = previous[holes_used - 1] - (40 if constrained else 0)
                    if score > current[holes_used]:
                        current[holes_used] = score
                        back[holes_used] = 1
            previous = current
            back_rows.append(back)

        holes = set()
        h = gap
        for actual_idx in range(declared - 1, -1, -1):
            if back_rows[actual_idx][h]:
                holes.add(actual_idx)
                h -= 1
        if h != 0:
            return values

        aligned = []
        stream_idx = 0
        for actual_idx in range(declared):
            if actual_idx in holes:
                aligned.append(_Nuitka_UNSTREAMED_SLOT)
            else:
                if stream_idx >= streamed:
                    return values
                aligned.append(values[stream_idx])
                stream_idx += 1
        if stream_idx != streamed:
            return values

        def _quality(pool):
            total = 0
            size = len(pool)
            for c in callers:
                def _get(field):
                    va = c.get(field)
                    if not va or (va - mcb) % 8:
                        return None
                    idx = (va - mcb) // 8
                    if not 0 <= idx < size:
                        return None
                    value = pool[idx]
                    return None if value is _Nuitka_UNSTREAMED_SLOT else value
                name = _get('name_va')
                qualname = _get('qualname_va')
                varnames = _get('varnames_va')
                need = (c.get('argcount') or 0) + (c.get('kwonly') or 0)
                name_ok = isinstance(name, str)
                qual_ok = (isinstance(qualname, str) and name_ok and
                           (qualname == name or qualname.endswith('.' + name)
                            or qualname.endswith(name)))
                vars_ok = (need == 0 or
                           (isinstance(varnames, tuple) and len(varnames) >= need
                            and all(isinstance(x, str) for x in varnames)))
                if qual_ok and vars_ok:
                    total += 1
            return total

        baseline = values + [_Nuitka_UNSTREAMED_SLOT] * gap
        return aligned if _quality(aligned) >= _quality(baseline) else baseline

    def _makeobj_solve_dotted(self, module_constants, callers=None):
        """CPython 3.11+ code-object recovery via the shared makeCodeObject helper.
        Solves this module's mod_consts base (mcb) by voting: the module's own
        code objects' `name_va` slots all lie in [mcb, mcb+8*len), aligned to 8,
        and resolve to identifier consts (the co_names). Returns the SAME
        code-object dicts as recover_code_objects. Universal for Nuitka on 3.11+.

        NOTE: this vote needs a DOTTED qualname anchor (`Class.method`) to pin the
        base; a module of only plain top-level `def f(...)` (no class / nested
        func — e.g. auth_system) has none, so this returns []. The public wrapper
        `recover_code_objects_makeobj` then re-solves such modules from the
        module-init function's own .bss mod_consts references
        (`_makeobj_toplevel_via_fp`)."""
        if not self._pycode_slot or not module_constants:
            return []
        callers = list(callers) if callers is not None else self._makeobj_callers()
        if not callers:
            return []
        _constants_meta = module_constants
        consts = list(module_constants)
        navs = [c['name_va'] for c in callers if c.get('name_va')]
        navset = set(navs)
        # identifier / <dunder-ish> consts are candidate co_names; the LONGEST
        # ones are the most distinctive anchors for the mcb vote.
        _idre = re.compile(r'[A-Za-z_]\w*|<[\w ]+>')
        ident = [(i, c) for i, c in enumerate(consts)
                 if isinstance(c, str) and _idre.fullmatch(c)]
        if len(ident) < 3:
            return []
        # Solve mcb by a NAME↔QUALNAME CONSISTENCY vote. A real code object's
        # qualname ENDS WITH its name ('gui.ModernGUI.__init__' ends with
        # '__init__'; a top-level 'func' has qualname 'func'; '<module gui>' /
        # '<lambda>' end with themselves). Each caller has a FIXED
        # delta = (qualname_va - name_va)/8, so for a hypothesised name index jn
        # the qualname sits at jn+delta. We find the jn where consts[jn] is an
        # identifier AND consts[jn+delta] ends with it, then vote for
        # mcb = name_va - 8*jn. Only THIS module's callers satisfy the consistency
        # against THIS module's consts, so cross-module / import-name noise (which
        # dominated a plain resolution vote) is filtered out.
        from collections import Counter
        cap = None
        if len(ident) > 800:
            cap = {i for i, c in sorted(ident, key=lambda t: -len(t[1]))[:800]}
        idset = set(i for i, _ in ident)

        def _is_vtuple(t):
            return isinstance(t, tuple) and all(
                isinstance(x, str) and (x == '.0' or re.fullmatch(r'[A-Za-z_]\w*', x))
                for x in t)

        # ---- Phase 1: GENERATE candidate mcbs from strong per-caller anchors ---
        # (a) DOTTED qualname ending in the name (`Class.method`), OR
        # (b) name is an identifier AND varnames resolves to a non-empty tuple of
        #     identifiers (arg-bearing top-level function). Either yields a
        #     candidate mcb = name_va - 8*name_index. Over-generation is fine —
        #     Phase 2 validates.
        cand = Counter()
        # anchor: a DOTTED qualname ending in the name yields one candidate per
        # such caller. Enough for any module with a class / nested func / lambda.
        # Iterate over the (few) DOTTED consts, not all identifiers: for a caller
        # with delta dq the qualname sits at name_idx+dq, so a dotted const at
        # index jq implies name_idx = jq - dq — turning the O(callers*idents) scan
        # into O(callers*dotted) (dotted consts are a small fraction).
        _dotted = [(jq, cq) for jq, cq in enumerate(consts)
                   if isinstance(cq, str) and '.' in cq and _idre.fullmatch(cq.rsplit('.', 1)[-1] or ' ')]
        for c in callers:
            nva = c.get('name_va'); qva = c.get('qualname_va')
            # ``co_qualname`` is always a direct makeCodeObject argument and is
            # module-local even when Nuitka interns/reuses ``co_name`` in a
            # shared constants block.  Vote directly from its slot too.  The
            # correct base is the only candidate repeated consistently across
            # the exact owner call set; Phase 2 still validates descriptor
            # arity and name/qualname semantics before accepting it.
            if qva:
                for jq, _cq in _dotted:
                    cand[qva - 8 * jq] += 1
            if not nva or not qva or (qva - nva) % 8:
                continue
            dq = (qva - nva) // 8
            if dq == 0:
                continue
            for jq, cq in _dotted:
                jn = jq - dq
                if not (0 <= jn < len(consts)) or jn not in idset:
                    continue
                cn = consts[jn]
                if cq.endswith('.' + cn) or cq.endswith(cn):
                    cand[nva - 8 * jn] += 1
                    break
        # (b) VARNAMES fallback anchor — ONLY when the dotted anchor found NOTHING,
        # i.e. a TOP-LEVEL-only module of plain `def f(a, b): …` functions (no
        # class/method/nested dotted qualnames, e.g. auth_system). Each arg-bearing
        # caller's varnames_va resolves to a tuple of identifiers of length
        # >= argcount+kwonly at a FIXED delta dv from name_va: a vtuple at index jv
        # implies name index jn = jv - dv; if consts[jn] is an identifier, vote
        # mcb = name_va - 8*jn. Longest vtuples first, capped. Kept OUT of the
        # dotted path so it can never mis-rank a class-bearing module (gui).
        _varnames_fallback = not cand
        if _varnames_fallback:
            _vtuples = sorted(
                ((jv, cv) for jv, cv in enumerate(consts)
                 if _is_vtuple(cv) and len(cv) >= 1),
                key=lambda t: -len(t[1]))[:600]
            for c in callers:
                nva = c.get('name_va'); vva = c.get('varnames_va')
                if not nva or not vva or (vva - nva) % 8:
                    continue
                need = (c.get('argcount') or 0) + (c.get('kwonly') or 0)
                dv = (vva - nva) // 8
                for jv, cv in _vtuples:
                    if len(cv) < need:
                        continue
                    jn = jv - dv
                    if 0 <= jn < len(consts) and jn in idset:
                        cand[nva - 8 * jn] += 1
                        break
        if not cand:
            # A top-level-only module yields no dotted candidates at all; the
            # structural filename anchor can still pin the exact base so the
            # Phase-2 vote has a provably-correct candidate to score.
            _anchor0 = self._makeobj_filename_anchor(
                consts, len(consts), callers, idset)
            if _anchor0 is not None:
                cand[_anchor0] += 1_000_000_000
            else:
                return []
        else:
            # ---- FILENAME ANCHOR (structural - Nuitka's module template) ----
            _anchor0 = self._makeobj_filename_anchor(
                consts, len(consts), callers, idset)
            if _anchor0 is not None:
                cand[_anchor0] += 1_000_000_000
        # ---- Phase 2: SCORE each candidate by the UNIVERSAL qualname check ------
        # EVERY real code object's qualname ENDS WITH its name; random consts under
        # a wrong base almost never do. Score(mcb) = callers whose name resolves to
        # an identifier AND whose qualname resolves to a string ending with it.
        def _resolved_descriptor_name(c, lo2, hi2):
            """Resolve ``co_name`` without requiring it to be module-local.

            Nuitka 4.x commonly points repeated names such as ``__init__`` at a
            shared/immortal constant slot outside this module's ``mod_consts``.
            The exact ``co_qualname`` argument remains local.  When the name is
            local we retain the stronger old name↔qualname consistency check;
            when it is external, the final qualname component is the only
            deterministic CPython code-name value and is accepted as such.
            """
            nva = c.get('name_va')
            qva = c.get('qualname_va')
            if (not nva or not qva or not (lo2 <= qva < hi2)
                    or (qva - lo2) % 8):
                return None, None
            cq = consts[(qva - lo2) // 8]
            if not isinstance(cq, str):
                return None, None
            if lo2 <= nva < hi2:
                if (nva - lo2) % 8:
                    return None, None
                ni = (nva - lo2) // 8
                if ni not in idset:
                    return None, None
                cn = consts[ni]
                if not (cq == cn or cq.endswith('.' + cn)
                        or cq.endswith(cn)):
                    return None, None
                return cn, cq
            return _ndl_code_name_from_qualname(cq), cq

        def _resolves(c, mcb, lo2, hi2):
            """True if caller c FULLY resolves to a real code object under mcb:
            an exact local/external name, local qualname, and (no args, or
            varnames→a tuple long enough for argcount+kwonly)."""
            cn, cq = _resolved_descriptor_name(c, lo2, hi2)
            if cn is None or cq is None:
                return False
            need = (c.get('argcount') or 0) + (c.get('kwonly') or 0)
            vva = c.get('varnames_va')
            if vva:
                if not vva or not (lo2 <= vva < hi2) or (vva - lo2) % 8:
                    return False
                tv = consts[(vva - lo2) // 8]
                if not (_is_vtuple(tv) and len(tv) >= need):
                    return False
            elif need >= 1:
                return False
            return True

        def _score(mcb):
            # DISCRIMINATING score: callers whose name→identifier AND qualname→a
            # DOTTED string ending in that name (delta!=0). The delta==0
            # (qualname==name) top-level case is EXCLUDED from scoring (it matches
            # any identifier at a dense-identifier base and inflates wrong mcbs);
            # such callers are still emitted by the _resolves output filter once
            # the base is pinned by the dotted code objects.
            lo2, hi2 = mcb, mcb + 8 * len(consts)
            sc = 0
            for c in callers:
                cn, cq = _resolved_descriptor_name(c, lo2, hi2)
                if (cn is not None and isinstance(cq, str)
                        and '.' in cq and cq != cn
                        and (cq.endswith('.' + cn) or cq.endswith(cn))):
                    sc += 1
            # VARNAMES fallback score — ONLY for TOP-LEVEL-only modules (no dotted
            # code objects at all under mcb). Counts callers whose name→identifier
            # AND varnames→a right-arity identifier tuple. Gated on sc==0 so it
            # NEVER perturbs the winner for a module that has any dotted anchor
            # (which the noisier varnames signal would otherwise mis-rank).
            if sc == 0 and _varnames_fallback:
                for c in callers:
                    nva = c.get('name_va')
                    need = (c.get('argcount') or 0) + (c.get('kwonly') or 0)
                    if not nva or need < 1 or not (lo2 <= nva < hi2) or (nva - lo2) % 8:
                        continue
                    if (nva - lo2) // 8 not in idset:
                        continue
                    vva = c.get('varnames_va')
                    if vva and (lo2 <= vva < hi2) and not ((vva - lo2) % 8):
                        tv = consts[(vva - lo2) // 8]
                        if _is_vtuple(tv) and len(tv) >= need:
                            sc += 1
            return sc
        top = [m for m, _ in cand.most_common(60)]
        mcb = max(top, key=_score)
        _dotted_score = _score(mcb)
        # Tiny top-level modules (__main__ with 1-2 functions) have no dotted
        # Class.method anchors. Accept a unique fully-resolved caller set
        # instead of requiring two dotted hits.
        _min_dotted = 2
        if len(callers) <= 2:
            _min_dotted = 1 if _varnames_fallback or len(callers) == 1 else 2
        if _dotted_score < _min_dotted:
            return []
        self._last_mod_consts_base = mcb
        consts = self._align_unstreamed_constant_slots(
            _constants_meta, callers, mcb)
        idset = set(i for i, c in enumerate(consts)
                    if isinstance(c, str) and _idre.fullmatch(c))
        lo, hi = mcb, mcb + 8 * len(consts)
        CO_VARARGS, CO_VARKEYWORDS = 0x04, 0x08
        CO_GENERATOR, CO_COROUTINE, CO_ASYNCGEN = 0x20, 0x80, 0x200

        def _resolve(va):
            if not va or not (lo <= va < hi) or (va - lo) % 8:
                return None
            idx = (va - lo) // 8
            return consts[idx] if 0 <= idx < len(consts) else None

        out = []
        seen = set()
        for c in callers:
            # Only emit callers that FULLY resolve as a real code object under the
            # solved mcb (name identifier + qualname-ends-with-name + argcount↔
            # varnames). This drops the import-name / non-code-object callers whose
            # name_va merely happens to land on an identifier const in range.
            if not _resolves(c, mcb, lo, hi):
                continue
            nva = c.get('name_va')
            qn = _resolve(c.get('qualname_va'))
            nm = _resolve(nva)
            _external_name = not isinstance(nm, str)
            if _external_name:
                nm = _ndl_code_name_from_qualname(qn)
            key = (c.get('code_slot_va') or c.get('call_site'), nm,
                   c.get('line') or 0, c.get('varnames_va'))
            if key in seen:
                continue
            seen.add(key)
            vt_raw = _resolve(c.get('varnames_va'))
            vt = [str(x) for x in vt_raw] if isinstance(vt_raw, tuple) else []
            argc = c.get('argcount') or 0
            kw = c.get('kwonly') or 0
            flags = c.get('flags') or 0
            sig = list(vt[:argc])
            kk = argc
            kwonly_names = vt[kk:kk + kw]
            kk += kw
            if (flags & CO_VARARGS) and kk < len(vt):
                sig.append('*' + vt[kk]); kk += 1
            elif kwonly_names:
                sig.append('*')
            sig += kwonly_names
            if (flags & CO_VARKEYWORDS) and kk < len(vt):
                sig.append('**' + vt[kk])
            sig = _ndl_sanitize_def_args(sig)
            out.append({
                '_type': 'CodeObject', '_native': True, 'name': nm,
                'qualname': qn if isinstance(qn, str) else None,
                'argcount': argc, 'kwonly': kw,
                'posonly': c.get('posonly') or 0, 'flags': flags,
                'args': sig, 'varnames': vt, 'docstring': None,
                'is_async': bool(flags & (CO_COROUTINE | CO_ASYNCGEN)),
                'is_gen': bool(flags & CO_GENERATOR),
                # co_firstlineno (makeCodeObject `line` arg) — used to JOIN this
                # code object to its native impl VA by matching against the body's
                # first f_lineno statement marker (3.11+ line-proximity join, since
                # the lea-adjacency name pairing is unavailable when names live in
                # runtime-filled slots).
                'line': c.get('line') or 0,
                # 3.11+ makeCodeObject recovery: argcount/kwonly are EXACT, but
                # which trailing args are optional (the __defaults__ tuple) lives
                # in Nuitka_Function_New's args, not in the code object. So the
                # pool-tuple default GUESS (_ndl_infer_defaults_heuristic) is
                # unsound here — it assigned e.g. (1000,600) from a setGeometry
                # literal to every 2-arg method. Mark so the renderer skips it.
                '_makeobj': True,
                # Exact native evidence retained for the 3.11+ implementation
                # join.  These private fields are never rendered as source.
                '_code_slot_va': c.get('code_slot_va'),
                '_makeobj_call_site': c.get('call_site'),
                '_makeobj_owner_start': c.get('owner_start'),
                '_makeobj_external_name': _external_name,
            })
        return out

    def recover_code_objects_makeobj(self, module_constants, func_ptr=None):
        """CPython 3.11+ code-object recovery via the shared makeCodeObject helper.

        Two solvers, dotted first:
          1. `_makeobj_solve_dotted` — needs a `Class.method` qualname anchor to
             pin the mod_consts base. Handles class/nested-func modules (gui,
             login_gui) exactly as before.
          2. `_makeobj_toplevel_via_fp` — for TOP-LEVEL-only modules (all plain
             `def f(...)`, no dotted qualname; e.g. auth_system) the dotted vote
             returns []. This re-solves the base by WINDOWING candidate bases to
             the module-init function's OWN .bss mod_consts references, then
             scoring by DISTINCT fully-resolved code objects.

        The top-level solver is adopted ONLY when it finds STRICTLY MORE code
        objects than the dotted vote, so a module the dotted vote already solved
        (gui: 65, on which the two agree exactly) is never perturbed. 3.11+-only:
        on <=3.10 the makeCodeObject wrapper does not exist, so `_makeobj_callers`
        is empty and both solvers return []."""
        scoped_callers = None
        if func_ptr and getattr(self, '_pycode_is_unstable', False):
            owner = self._makeobj_owner_for_module(func_ptr)
            if owner is not None:
                scoped_callers = self._makeobj_callers(owner_filter=owner)
            elif self._find_makeobj_wrapper():
                # Exact owner metadata exists, but this module has no owner. Do
                # not run the old global vote: it can borrow a neighbouring
                # module's perfectly plausible name/qualname/varnames tuple.
                return []

        out = self._makeobj_solve_dotted(module_constants, scoped_callers)
        if func_ptr and getattr(self, '_pycode_is_unstable', False):
            try:
                alt, alt_base = self._makeobj_toplevel_via_fp(
                    module_constants, func_ptr, scoped_callers)
            except Exception:
                alt, alt_base = [], None
            if alt and alt_base is not None and (not out or len(alt) > len(out)):
                self._last_mod_consts_base = alt_base
                return alt
        return out

    def _makeobj_filename_anchor(self, consts, N, callers, idset):
        """Solve ``mcb`` deterministically from Nuitka's module .data layout.

        Nuitka's module template (CodeTemplatesModules.py - identical in
        open-source and commercial builds; data-hiding encrypts the blob
        CONTENTS, never this layout) emits one translation unit per module
        with, in declaration order:
          1. ``static struct ModuleConstants { ... } mod_consts;`` - N
             PyObject* fields in blob stream order;
          2. (assert builds only) ``static Py_hash_t mod_consts_hash[N];``
          3. ``static PyObject *module_filename_obj = NULL;``
          4. the ``static PyCodeObject *code_object_*;`` pointers.

        Same-TU statics land in .data in declaration order, and every
        makeCodeObject caller of one module passes rcx = that single
        module_filename_obj slot, so the filename slot F satisfies
            F == mcb + 8*N          release layout
            F == mcb + 16*N         assert layout (hash array present)
        and mcb = F - 8*N (or F - 16*N) - no voting, no heuristics.

        A candidate is accepted only when it fully resolves at least 60% of
        the callers (the true base resolves essentially all of them), so the
        legacy vote stays in charge whenever the layout assumption does not
        hold (packed/merged-section binaries, unusual linkers).
        """
        from collections import Counter as _Counter
        files = _Counter(c.get('filename_va') for c in callers
                         if c.get('filename_va'))
        if not files or N < 3:
            return None
        F, freq = files.most_common(1)[0]
        # co_filename is one and the same object for the whole module; without
        # a clear majority slot the anchor has nothing to hang on.
        if freq < max(2, (len(callers) * 2) // 3):
            return None

        def _vt(t):
            return isinstance(t, tuple) and all(
                isinstance(x, str)
                and (x == '.0' or re.fullmatch(r'[A-Za-z_]\w*', x))
                for x in t)

        def _resolves(c, B):
            lo, hi = B, B + 8 * N
            nva = c.get('name_va')
            qva = c.get('qualname_va')
            if not nva or not (lo <= nva < hi) or (nva - B) % 8:
                return False
            ni = (nva - B) // 8
            if ni not in idset:
                return False
            cn = consts[ni]
            if not (qva and lo <= qva < hi and not (qva - B) % 8):
                return False
            cq = consts[(qva - B) // 8]
            if not (isinstance(cq, str)
                    and (cq == cn or cq.endswith('.' + cn) or cq.endswith(cn))):
                return False
            need = (c.get('argcount') or 0) + (c.get('kwonly') or 0)
            if need >= 1:
                vva = c.get('varnames_va')
                if not (vva and lo <= vva < hi and not (vva - B) % 8):
                    return False
                tv = consts[(vva - B) // 8]
                if not (_vt(tv) and len(tv) >= need):
                    return False
            return True

        best = None
        for layout in (N, 2 * N):
            B = F - 8 * layout
            if B <= 0:
                continue
            sc = sum(1 for c in callers if _resolves(c, B))
            if sc and (best is None or sc > best[1]):
                best = (B, sc)
        if best is None:
            return None
        # The structural base resolves essentially every caller; reject weak
        # coincidences so a bad anchor can never displace the vote.
        if best[1] < max(3, (len(callers) * 3) // 5):
            return None
        return best[0]

    def _makeobj_toplevel_via_fp(self, module_constants, func_ptr, callers=None):
        """Solve a TOP-LEVEL-only module's mod_consts base by windowing candidate
        bases to the module-init function's own .bss references.

        Modules of only plain top-level `def`s have NO dotted qualname anchor, so
        the dotted vote (`_makeobj_solve_dotted`) can't pin the base. But the
        module-init function `func_ptr` loads/stores its own code objects and
        constants through `mov reg,[rip+X]` into the module's `mod_consts[]`
        array in `.bss` (runtime-filled, 0 in the file). Those rip-relative .bss
        targets cluster tightly on the module's own array; the tightest cluster
        WINDOWS the true base. Candidate bases are `name_va - 8*ni` for every
        makeCodeObject caller whose name slot lands in that window and every
        identifier const index `ni`; each candidate is scored by the number of
        DISTINCT callers that FULLY resolve under it (name->identifier, qualname
        ends with the name, and argcount<=varnames arity). The wrong-base /
        neighbouring-module noise never resolves consistently, so the true base
        wins cleanly (validated: auth_system 0->12, discord_logger 1->5,
        pyautogui 4->56, and gui/login_gui agree with the dotted vote).

        Returns (code_object_dicts, base_va) or ([], None). Pure static;
        3.11+-only (the caller gates on `_pycode_is_unstable`)."""
        if not self._pycode_slot or not module_constants or not func_ptr:
            return [], None
        callers = list(callers) if callers is not None else self._makeobj_callers()
        if not callers:
            return [], None
        _constants_meta = module_constants
        consts = list(module_constants)
        N = len(consts)
        if N < 3:
            return [], None
        _idre = re.compile(r'[A-Za-z_]\w*|<[\w ]+>')
        idset = set(i for i, c in enumerate(consts)
                    if isinstance(c, str) and _idre.fullmatch(c))
        if len(idset) < 2:
            return [], None

        def _is_vtuple(t):
            return isinstance(t, tuple) and all(
                isinstance(x, str) and (x == '.0' or re.fullmatch(r'[A-Za-z_]\w*', x))
                for x in t)

        # ---- 1) window: the module-init fn's own .bss mod_consts references ----
        try:
            # The module entry's first writable-constant loads are enough to
            # identify the mod_consts window.  Bound this probe; protected
            # builds can expose an enormous generated entry where scanning the
            # full 128 KiB adds no useful candidates.
            _window_bytes = 0x4000
            if not _ndl_live_opt('targeted_only'):
                _b0, _e0 = self._function_bounds(func_ptr)
                if _b0 is not None and _e0 is not None and _e0 > _b0:
                    _window_bytes = min(0x40000, max(_window_bytes, _e0 - _b0))
            ins = self._disasm_body(func_ptr, max_bytes=_window_bytes)
        except Exception:
            return [], None
        bss = []
        for I in ins:
            m = re.search(r'\[rip \+ (0x[0-9a-f]+)\]', I.op_str)
            if not m:
                continue
            tgt = I.address + I.size + int(m.group(1), 16)
            _nm, _sec, _off = self._find_section_for_rva(tgt - self.image_base)
            # mod_consts[] is a runtime-filled PyObject* array, so it always
            # lives in a WRITABLE section: ``.bss`` on open-source Nuitka, but
            # ``.data`` on commercial/protected builds (the decrypted
            # constants blob pre-initialises it there) and on several linker
            # layouts.  Gate on the section's IMAGE_SCN_MEM_WRITE
            # characteristic (universal, layout-proof); fall back to the
            # classic writable names only when characteristics are missing.
            try:
                _wr = bool(_sec is not None
                           and (_sec.Characteristics & 0x80000000))
            except Exception:
                _wr = _nm in ('.bss', '.data')
            if _wr:
                bss.append(tgt)
        bss = sorted(set(bss))
        if not bss:
            return [], None
        # tightest contiguous cluster (module arrays are packed adjacently in
        # .bss; stride<=0x400 keeps this module's block, drops far neighbours)
        clusters = []
        cur = [bss[0]]
        for v in bss[1:]:
            if v - cur[-1] <= 0x400:
                cur.append(v)
            else:
                clusters.append(cur)
                cur = [v]
        clusters.append(cur)
        cl = max(clusters, key=len)
        wlo, whi = cl[0], cl[-1]
        # With the V73 exact owner join, every caller already belongs to this
        # module's createModuleCodeObjects function. The old .bss window was a
        # noise filter for the global caller pool and can discard legitimate
        # code objects whose name slot lies outside the entry function's sampled
        # references. Retain it only for legacy/no-owner fallback data.
        _owners = {c.get('owner_start') for c in callers if c.get('owner_start')}
        if len(_owners) == 1 and all(c.get('owner_start') for c in callers):
            win = list(callers)
        else:
            win = [c for c in callers
                   if c.get('name_va') and wlo <= c['name_va'] <= whi]
        if not win:
            return [], None

        # ---- 2) generate candidate bases and score by DISTINCT resolutions ----
        # cap the identifier set for candidate generation on very large modules
        # (longest names are the most distinctive anchors); scoring still uses
        # the full idset.
        gen_idset = idset
        if len(idset) > 400:
            gen_idset = set(i for i, _ in sorted(
                ((i, consts[i]) for i in idset),
                key=lambda t: -len(t[1]))[:400])
        from collections import Counter
        cand = Counter()
        for c in win:
            nva = c['name_va']
            for ni in gen_idset:
                B = nva - 8 * ni
                cand[B] += 1
        if not cand:
            return [], None

        # ---- 2a) FILENAME ANCHOR (structural - Nuitka's module template) ----
        # When the release/assert .data layout holds, F - 8*N (or F - 16*N) is
        # the exact mod_consts base: it resolves ~all callers and therefore
        # outranks every voted candidate in the _score() race below.  Validated
        # inside the helper; legacy voting is untouched when it does not apply.
        _anchor_mcb = self._makeobj_filename_anchor(consts, N, callers, idset)
        if _anchor_mcb is not None:
            cand[_anchor_mcb] += 1_000_000_000

        def _resolve_ni(c, B):
            """The name-const index c resolves to under base B, or None if c does
            NOT fully resolve as a real code object (name->identifier, qualname
            ends with name, argcount<=varnames arity)."""
            lo, hi = B, B + 8 * N
            nva = c.get('name_va')
            qva = c.get('qualname_va')
            if not nva or not (lo <= nva < hi) or (nva - B) % 8:
                return None
            ni = (nva - B) // 8
            if ni not in idset:
                return None
            cn = consts[ni]
            if not (qva and lo <= qva < hi and not (qva - B) % 8):
                return None
            cq = consts[(qva - B) // 8]
            if not (isinstance(cq, str)
                    and (cq == cn or cq.endswith('.' + cn) or cq.endswith(cn))):
                return None
            need = (c.get('argcount') or 0) + (c.get('kwonly') or 0)
            vva = c.get('varnames_va')
            # Zero-arg functions still carry a locals tuple. When the native
            # call wrote varnames_va, that slot MUST be a string tuple under
            # the candidate base; otherwise every identifier index trivially
            # "resolves" (name==qualname) on tiny top-level modules.
            if vva:
                if not (lo <= vva < hi and not (vva - B) % 8):
                    return None
                tv = consts[(vva - B) // 8]
                if not (_is_vtuple(tv) and len(tv) >= need):
                    return None
            elif need >= 1:
                return None
            return ni

        def _score(B):
            nis = set()
            vlen = 0
            module_name_hits = 0
            for c in win:
                r = _resolve_ni(c, B)
                if r is not None:
                    nis.add(r)
                    vva = c.get('varnames_va')
                    if vva:
                        tv = consts[(vva - B) // 8]
                        if _is_vtuple(tv):
                            vlen += len(tv)
                    # The module entry creates a genuine CPython module code
                    # object whose co_name/co_qualname is ``<module>``.  A
                    # wrong base can nevertheless resolve that same zero-arg
                    # caller to an arbitrary identifier (for example a dict
                    # key), so use this ABI-independent code-object invariant
                    # as a deterministic tie-breaker between equally sized
                    # candidate constant windows.
                    if (not int(c.get('flags') or 0)
                            and not int(c.get('argcount') or 0)
                            and int(c.get('line') or 0) == 1
                            and 0 <= r < len(consts)
                            and consts[r] == '<module>'):
                        module_name_hits += 1
            return (len(nis), module_name_hits, vlen)

        top = [b for b, _ in cand.most_common(80)]
        if not top:
            return [], None
        mcb = max(top, key=_score)
        best = _score(mcb)[0]
        # Tiny modules (__main__, empty-ish packages) often have 1-2 code
        # objects. The old global floor of 3 rejected them even when every
        # caller resolved uniquely. Keep the floor of 3 only for larger
        # owner functions, where a wrong base can accidentally resolve a
        # couple of identifier slots.
        _min_best = 3
        if len(win) <= 2:
            _min_best = len(win)
        elif len(win) <= 4:
            _min_best = 2
        if best < _min_best:
            return [], None

        # Historical streams may omit C-initialized constants. Align the
        # streamed values to the true slot count before resolving metadata VAs.
        consts = self._align_unstreamed_constant_slots(
            _constants_meta, win, mcb)
        N = len(consts)
        idset = set(i for i, c in enumerate(consts)
                    if isinstance(c, str) and _idre.fullmatch(c))

        # ---- 3) emit code-object dicts (same shape as the dotted solver) -------
        lo, hi = mcb, mcb + 8 * N
        CO_VARARGS, CO_VARKEYWORDS = 0x04, 0x08
        CO_GENERATOR, CO_COROUTINE, CO_ASYNCGEN = 0x20, 0x80, 0x200

        def _resolve(va):
            if not va or not (lo <= va < hi) or (va - lo) % 8:
                return None
            idx = (va - lo) // 8
            return consts[idx] if 0 <= idx < N else None

        out = []
        seen = set()
        for c in win:
            if _resolve_ni(c, mcb) is None:
                continue
            nva = c.get('name_va')
            nm = _resolve(nva)
            key = (c.get('code_slot_va') or c.get('call_site'), nm,
                   c.get('line') or 0, c.get('varnames_va'))
            if key in seen:
                continue
            seen.add(key)
            vt_raw = _resolve(c.get('varnames_va'))
            vt = [str(x) for x in vt_raw] if isinstance(vt_raw, tuple) else []
            qn = _resolve(c.get('qualname_va'))
            argc = c.get('argcount') or 0
            kw = c.get('kwonly') or 0
            flags = c.get('flags') or 0
            sig = list(vt[:argc])
            kk = argc
            kwonly_names = vt[kk:kk + kw]
            kk += kw
            if (flags & CO_VARARGS) and kk < len(vt):
                sig.append('*' + vt[kk]); kk += 1
            elif kwonly_names:
                sig.append('*')
            sig += kwonly_names
            if (flags & CO_VARKEYWORDS) and kk < len(vt):
                sig.append('**' + vt[kk])
            sig = _ndl_sanitize_def_args(sig)
            out.append({
                '_type': 'CodeObject', '_native': True, 'name': nm,
                'qualname': qn if isinstance(qn, str) else None,
                'argcount': argc, 'kwonly': kw,
                'posonly': c.get('posonly') or 0, 'flags': flags,
                'args': sig, 'varnames': vt, 'docstring': None,
                'is_async': bool(flags & (CO_COROUTINE | CO_ASYNCGEN)),
                'is_gen': bool(flags & CO_GENERATOR),
                'line': c.get('line') or 0,
                '_makeobj': True,
                # Exact native evidence retained for the 3.11+ implementation
                # join.  These private fields are never rendered as source.
                '_code_slot_va': c.get('code_slot_va'),
                '_makeobj_call_site': c.get('call_site'),
                '_makeobj_owner_start': c.get('owner_start'),
            })
        if len(out) < _min_best:
            return [], None
        return out, mcb

    def _recover_operators(self, va, max_bytes=8192, insns=None):
        """Return the operators a compiled body applies (arithmetic via
        tp_as_number->nb_slot, subscript via tp_as_mapping->mp_subscript), in
        native execution order. Each is found ONLY through the two-step
        register chain `mov R,[type+as_slot]` then `mov R2,[R+method_slot]`,
        which is unambiguous (flat offset matching is not). Pure static,
        universal (CPython x64 ABI offsets). Validated: convert_to_btc -> ['/'].
        Best-effort; returns [] on any disasm failure."""
        cxm = _capstone_x86
        if cxm is None:
            return []
        if insns is None:
            try:
                insns = self._bounded_disasm(va, max_bytes=max_bytes)
            except Exception:
                return []
        ops = []
        holds = {}     # reg -> 'asnum' | 'asmap'  (holds a tp_as_* table ptr)
        pending = {}   # reg -> (addr, op)  (holds a slot fn ptr, awaiting a call)
        for I in insns:
            mn = I.mnemonic
            if mn == 'ret':
                break
            ops_ = I.operands
            # An operator only counts if its slot function pointer is actually
            # CALLED — merely loading tp_as_number for type introspection (and
            # reading a slot offset) is NOT an operation. This is what keeps
            # the result never-wrong (validated: drops spurious nb_subtract from
            # type introspection, keeps real arithmetic ops in the callee).
            if mn == 'call' and ops_ and ops_[0].type == cxm.X86_OP_REG:
                hit = pending.pop(ops_[0].reg, None)
                if hit:
                    ops.append(hit)
                continue
            if mn != 'mov' or len(ops_) != 2:
                continue
            dst, src = ops_
            if dst.type != cxm.X86_OP_REG:
                continue
            if src.type == cxm.X86_OP_REG:        # mov R_dst, R_src — propagate
                for tbl in (holds, pending):
                    if src.reg in tbl:
                        tbl[dst.reg] = tbl[src.reg]
                    else:
                        tbl.pop(dst.reg, None)
                continue
            holds.pop(dst.reg, None)
            pending.pop(dst.reg, None)
            if src.type != cxm.X86_OP_MEM or src.mem.index != 0:
                continue
            base_reg, disp = src.mem.base, src.mem.disp
            if disp == self._TP_AS_NUMBER:
                holds[dst.reg] = 'asnum'
            elif disp == self._TP_AS_MAPPING:
                holds[dst.reg] = 'asmap'
            elif holds.get(base_reg) == 'asnum' and disp in self._NB_SLOTS:
                pending[dst.reg] = (I.address, self._NB_SLOTS[disp])
            elif holds.get(base_reg) == 'asmap' and disp == self._MP_SUBSCRIPT:
                pending[dst.reg] = (I.address, '[]')
        return ops

    def _synth_arith_return(self, va, params, module_constants,
                            mod_consts_base=None, max_bytes=2048):
        """Reconstruct the EXACT body of a one-line arithmetic-return function —
        `return <param> <op> <const>` — as REAL Python (not a comment), for the
        provably-unambiguous shape: a single parameter, a single numeric
        constant, a single nb-slot operator, nothing else (the `convert_to_*`
        unit converters). Operand ORDER is read from the native call: the
        nb-slot fn is invoked as `op(arg0=rcx, arg1=rdx)` = `op(left, right)`;
        whichever of rcx/rdx holds the rip-const fixes `value OP const` vs
        `const OP value`, so even non-commutative `/ // - %` come out correct.
        Returns the `return ...` source line, or None for any other shape — we
        never fabricate a body we cannot prove. Pure static, CPython x64 ABI."""
        cxm = _capstone_x86
        if cxm is None or len(params) != 1 or not params[0].isidentifier():
            return None
        base = mod_consts_base
        if base is None:
            base = getattr(self, '_last_mod_consts_base', None)
        if base is None or not module_constants:
            return None
        consts = module_constants
        try:
            insns = list(self._bounded_disasm(va, max_bytes=max_bytes))
        except Exception:
            return None

        def lit_at(addr):
            if addr is None or addr < base or (addr - base) % 8:
                return None
            i = (addr - base) // 8
            if not (0 <= i < len(consts)):
                return None
            v = consts[i]
            if isinstance(v, bool):
                return None
            return v if isinstance(v, (int, float)) else None

        holds = {}          # reg -> 'asnum' (holds a tp_as_number table ptr)
        pending = {}        # reg -> op symbol (nb-slot fn awaiting its call)
        const_regs = {}     # reg -> numeric literal currently held
        n_ops = 0
        result = None
        RCX, RDX = cxm.X86_REG_RCX, cxm.X86_REG_RDX
        for I in insns:
            mn = I.mnemonic
            if mn == 'ret':
                break
            ops_ = I.operands
            if mn == 'call' and ops_ and ops_[0].type == cxm.X86_OP_REG:
                op = pending.pop(ops_[0].reg, None)
                if op is not None:
                    n_ops += 1
                    lc, rc = const_regs.get(RCX), const_regs.get(RDX)
                    if rc is not None and lc is None:
                        result = (params[0], op, repr(rc))       # value OP const
                    elif lc is not None and rc is None:
                        result = (repr(lc), op, params[0])       # const OP value
                    else:
                        result = None
                continue
            if mn != 'mov' or len(ops_) != 2 or ops_[0].type != cxm.X86_OP_REG:
                continue
            dst, src = ops_
            if src.type == cxm.X86_OP_REG:
                for tbl in (holds, pending, const_regs):
                    if src.reg in tbl:
                        tbl[dst.reg] = tbl[src.reg]
                    else:
                        tbl.pop(dst.reg, None)
                continue
            holds.pop(dst.reg, None)
            pending.pop(dst.reg, None)
            const_regs.pop(dst.reg, None)
            if src.type != cxm.X86_OP_MEM or src.mem.index != 0:
                continue
            if src.mem.base == cxm.X86_REG_RIP:
                v = lit_at(I.address + I.size + src.mem.disp)
                if v is not None:
                    const_regs[dst.reg] = v
                continue
            disp, base_reg = src.mem.disp, src.mem.base
            if disp == self._TP_AS_NUMBER:
                holds[dst.reg] = 'asnum'
            elif holds.get(base_reg) == 'asnum' and disp in self._NB_SLOTS:
                pending[dst.reg] = self._NB_SLOTS[disp]
        if n_ops != 1 or result is None:
            return None
        left, op, right = result
        return 'return %s %s %s' % (left, op, right)

    @staticmethod
    def _trace_tokens(line):
        """Split one faithful-trace line into string literals and identifiers."""
        return re.findall(
            r"(?:\"(?:[^\"\\]|\\.)*\"|'(?:[^'\\]|\\.)*')|[A-Za-z_]\w*",
            line)

    def _synth_concat_return(self, seq):
        """Rebuild `return 'a' + VAR + 'b' + ...` from a straight-line trace
        that is only string literals and identifiers (compiled f-string /
        str.cat). GATED: no control-flow markers; >=3 parts. Returns one line
        or None."""
        if not seq:
            return None
        if any(re.search(r'<(?:if|for|el)', l) for l in seq):
            return None
        parts = []
        for line in seq:
            for tok in self._trace_tokens(line):
                if not tok:
                    continue
                if tok[0] in "'\"":
                    parts.append(tok)
                elif re.fullmatch(r'[A-Za-z_]\w*', tok):
                    parts.append(tok)
                else:
                    return None
        if len(parts) < 3:
            return None
        if not any(p[0] in "'\"" for p in parts):
            return None
        if not any(p[0] not in "'\"" for p in parts):
            return None
        expr = parts[0]
        for p in parts[1:]:
            expr += ' + ' + p
        return ['return %s' % expr]

    def _synth_call_chain(self, va, params, module_constants,
                          mod_consts_base=None, mcall0=None,
                          local_names=None, max_bytes=12000, classifier=None):
        """Reconstruct the EXACT body of a straight-line function as real Python
        — fused method/attribute/call chains AND straight-line DAGs (a value
        reused by several sub-expressions becomes a named local, e.g.
        `ctx = Context.from_input(self.seed); return Result(ctx.get_value_...
        ().hex(), ctx.get_secret_...().hex()).format()`). Register
        abstract-interpreter over the HAPPY PATH (each helper call is `call H;
        test rax,rax; jne SUCCESS` — follow the success edge; fall-through is the
        error handler). Per-site, UNIVERSAL (zero hardcoded helper VAs), informed
        by Nuitka's own code-generation conventions:

          * name-op  = helper call with an identifier name-const in r8; object in
                       rdx -> bare ('ATTR','obj.name',helper); no object ->
                       'name' (module global). A bare ATTR -> `expr()` when used
                       as the OBJECT of a later name-op (0-arg method call) or
                       when its helper is a known CALL_METHOD_NO_ARGS (`mcall0`).
          * cached var = module-local accessor `call <fn>` embedding a single
                       identifier const; OR a module-var CACHE slot resolved by
                       a pre-pass (the cache STORE follows the name-const load);
                       OR a name-const in rdx (MODULE_VAR fast helper).
          * callN    = call whose rdx is a live callable; args from a stack
                       array (`lea r8,[rbp-X]`) or registers; CONSTANT args are a
                       constant tuple (Nuitka codegen) extracted via
                       `[tuple+0x18+8i]` (PyTuple_GET_ITEM).

        DAG reuse via VALUE-INSTANCE tracking: each produced value gets an id
        tagged through registers/slots; a SEMANTIC consumption counts a use;
        used>1 -> materialise `<local> = expr` (local_names best-effort, else
        `_loc{n}`) and reference the name. GATED by caller (straight-line only;
        coverage). Returns a LIST of body lines, or None when it does not fully
        resolve (no holes) — never a wrong/partial body. CPython x64 ABI."""
        cxm = _capstone_x86
        if cxm is None or not params:
            return None
        base = mod_consts_base
        if base is None:
            base = getattr(self, '_last_mod_consts_base', None)
        if base is None or not module_constants:
            return None
        consts = module_constants
        mcall0 = set(mcall0 or ())
        call0 = set()
        local_names = list(local_names or [])
        try:
            insns = list(self._bounded_disasm(va, max_bytes=max_bytes))
        except Exception:
            return None
        # SAFETY GATE: only straight-line bodies (no real branch/loop); a
        # branchy/looping body is multi-path and is left as a faithful trace.
        try:
            if self.recover_real_branches(va, consts, base, insns=insns):
                return None
            if self.recover_loops(va, insns=insns):
                return None
        except Exception:
            return None
        idx = {I.address: k for k, I in enumerate(insns)}
        RCX, RDX, R8, R9, RAX, RBP, RSP, RIP = (
            cxm.X86_REG_RCX, cxm.X86_REG_RDX, cxm.X86_REG_R8, cxm.X86_REG_R9,
            cxm.X86_REG_RAX, cxm.X86_REG_RBP, cxm.X86_REG_RSP, cxm.X86_REG_RIP)

        def rcst(a):
            if a is None or a < base or (a - base) % 8:
                return None
            i = (a - base) // 8
            return consts[i] if 0 <= i < len(consts) else None

        # module-var CACHE pre-pass: Nuitka caches a module global in a writable
        # rip slot; the happy path reads the cached pointer (not a mod_consts
        # value). The cache STORE `mov [rip+X], reg` follows the name-const load,
        # so map X -> name; a later `mov reg,[rip+X]` then resolves to the name.
        cache_map = {}; recent = None
        for I in insns:
            O = I.operands
            if I.mnemonic == 'mov' and O and O[0].type == cxm.X86_OP_REG:
                for op in O:
                    if op.type == cxm.X86_OP_MEM and op.mem.base == RIP:
                        s = rcst(I.address + I.size + op.mem.disp)
                        if isinstance(s, str) and s.isidentifier():
                            recent = s
            elif (I.mnemonic == 'mov' and O and O[0].type == cxm.X86_OP_MEM
                  and O[0].mem.base == RIP and len(O) == 2
                  and O[1].type == cxm.X86_OP_REG):
                t = I.address + I.size + O[0].mem.disp
                if recent and rcst(t) is None:
                    cache_map[t] = recent

        varcache = {}

        def var_name(v):
            if v in varcache:
                return varcache[v]
            nm = None
            try:
                seen = set()
                for J in self._bounded_disasm(v, max_bytes=900):
                    if J.mnemonic in ('mov', 'lea'):
                        for op in J.operands:
                            if (op.type == cxm.X86_OP_MEM
                                    and op.mem.base == RIP):
                                s = rcst(J.address + J.size + op.mem.disp)
                                if isinstance(s, str) and s.isidentifier():
                                    seen.add(s)
                    if J.mnemonic == 'ret':
                        break
                if len(seen) == 1:
                    nm = next(iter(seen))
            except Exception:
                pass
            varcache[v] = nm
            return nm

        def isname(x): return isinstance(x, tuple) and x and x[0] == 'NAME'
        def isattr(x): return isinstance(x, tuple) and x and x[0] == 'ATTR'
        def isptr(x):  return isinstance(x, tuple) and x and x[0] == 'ARGPTR'
        def istup(x):  return isinstance(x, tuple) and x and x[0] == 'TUPLE'
        def isexpr(x): return isinstance(x, str)

        def interp(pass2, reused_ids):
            E = {}; TAG = {}; STK = {}; STKTAG = {}; STKGEN = {}
            gen = [0]; last_call = [0]; selfreg = [None]
            nextid = [0]; uses = {}; stmts = []; lc = [0]

            def use(reg):
                t = TAG.get(reg)
                if t is not None:
                    uses[t] = uses.get(t, 0) + 1

            def as_obj(x):
                if isexpr(x):
                    return x
                if isattr(x):
                    mcall0.add(x[2]); return x[1] + '()'
                return None

            def as_callable(x):
                return x[1] if isattr(x) else (x if isexpr(x) else None)

            def as_arg(x):
                if isattr(x):
                    return x[1] + '()' if x[2] in mcall0 else x[1]
                if isexpr(x):
                    return x
                if istup(x):
                    return ', '.join(repr(e) for e in x[1])
                return None

            def args_of(r8v):
                if istup(r8v):
                    return [repr(e) for e in r8v[1]]
                if not isptr(r8v):
                    return None
                o = r8v[1]; out = []
                while True:
                    k = ('stk', o)
                    if k in STK and STKGEN.get(k, -1) >= last_call[0]:
                        out.append(as_arg(STK[k])); o += 8
                    else:
                        break
                return out

            def produce(res):
                vid = nextid[0]; nextid[0] += 1
                if (pass2 and vid in reused_ids
                        and (isattr(res) or isexpr(res))):
                    nm = (local_names[lc[0]] if lc[0] < len(local_names)
                          and local_names[lc[0]].isidentifier()
                          else '_loc%d' % lc[0])
                    lc[0] += 1
                    stmts.append('%s = %s' % (nm, as_arg(res)))
                    E[RAX] = nm
                else:
                    E[RAX] = res
                TAG[RAX] = vid

            ip = 0; lt = None; ret = [None]; steps = 0
            while 0 <= ip < len(insns) and steps < 9000:
                steps += 1
                I = insns[ip]; mn = I.mnemonic; O = I.operands
                if mn == 'ret':
                    ret[0] = E.get(RAX); break
                if (mn == 'test' and len(O) == 2 and O[0].type == O[1].type
                        == cxm.X86_OP_REG and O[0].reg == O[1].reg):
                    lt = O[0].reg; ip += 1; continue
                if mn in ('je', 'jne'):
                    tgt = O[0].imm if O and O[0].type == cxm.X86_OP_IMM else None
                    if lt is not None and tgt in idx:
                        ip = idx[tgt] if mn == 'jne' else ip + 1
                        lt = None; continue
                    lt = None; ip += 1; continue
                if mn == 'jmp':
                    tgt = O[0].imm if O and O[0].type == cxm.X86_OP_IMM else None
                    if tgt in idx:
                        ip = idx[tgt]; continue
                    break
                lt = None
                if mn == 'call':
                    if O and O[0].type == cxm.X86_OP_REG:    # tp_dealloc scaffold
                        ip += 1; continue
                    tgt = O[0].imm if O and O[0].type == cxm.X86_OP_IMM else None
                    rcx = E.get(RCX); r8 = E.get(R8)
                    rdx = E.get(RDX); r9 = E.get(R9)
                    res = None
                    # BUILTIN call (str/int/float/repr/len/…): produce its result
                    # so it threads into the NEXT call's args — e.g. recovers
                    # `setText(str(value))` instead of dropping the `str(value)`.
                    # Nuitka passes the builtin's positionals in rdx,r8,r9 (tstate
                    # in rcx). Gated on >=1 clean arg (never a bare `str()`).
                    if tgt is not None and classifier is not None:
                        try:
                            _bcat, _bname = classifier.classify(tgt)
                        except Exception:
                            _bcat, _bname = (None, None)
                        if _bcat == "BUILTIN_CALL" and _bname:
                            # The strict API-free PyObject_Size helper receives
                            # its only object in rcx and returns native ssize_t;
                            # regular BUILTIN_<X> wrappers keep tstate in rcx and
                            # their Python arguments in rdx/r8/r9.
                            _len_rcx = bool(
                                _bname == "len"
                                and classifier._object_size_slot_strict(tgt))
                            _arg_values = ((rcx,) if _len_rcx
                                           else (rdx, r8, r9))
                            _ba = [as_arg(x) for x in _arg_values
                                   if (isexpr(x) or isattr(x) or isname(x))]
                            _ba = [a for a in _ba if a is not None]
                            if _ba:
                                if _len_rcx:
                                    use(RCX)
                                else:
                                    use(RDX); use(R8); use(R9)
                                E.pop(R8, None); E.pop(R9, None)
                                TAG.pop(R8, None); TAG.pop(R9, None)
                                last_call[0] = gen[0] + 1
                                produce('%s(%s)' % (_bname, ', '.join(_ba)))
                                ip += 1
                                continue
                    if isname(r8):
                        nm = r8[1]
                        obj = (as_obj(rdx) if (isexpr(rdx) or isattr(rdx))
                               else None)
                        arg = (as_arg(r9) if (isexpr(r9) or isattr(r9)
                               or istup(r9)) else None)
                        if obj is not None:
                            use(RDX)
                        if arg is not None:
                            use(R9)
                        if obj is not None and arg is not None:
                            res = '%s.%s(%s)' % (obj, nm, arg)
                        elif obj is not None:
                            res = ('ATTR', '%s.%s' % (obj, nm), tgt)
                            if (nm == 'hex'
                                    and self._helper_is_mcall0_shape(tgt)):
                                mcall0.add(tgt)
                        else:
                            res = nm
                    elif (tgt is not None and tgt < 0x1_4400_0000
                          and var_name(tgt)):
                        res = var_name(tgt)
                    elif isname(rdx) and not isexpr(E.get(RCX)):
                        res = rdx[1]
                    else:
                        f = as_callable(rdx)
                        a = args_of(r8 if (isptr(r8) or istup(r8)) else None)
                        if a is None:
                            a = [as_arg(x) for x in (r8, r9)
                                 if (isexpr(x) or isattr(x) or istup(x))]
                        if f and a is not None and all(x is not None for x in a):
                            use(RDX); use(R8); use(R9)
                            res = '%s(%s)' % (f, ', '.join(a))
                    E.pop(R8, None); E.pop(R9, None)
                    TAG.pop(R8, None); TAG.pop(R9, None)
                    last_call[0] = gen[0] + 1
                    if res is not None:
                        produce(res)
                    ip += 1; continue
                if mn in ('mov', 'lea') and O and O[0].type == cxm.X86_OP_REG:
                    d = O[0].reg; s = O[1]
                    if (mn == 'lea' and s.type == cxm.X86_OP_MEM
                            and s.mem.base == RSP and d == RBP):
                        E.pop(d, None); TAG.pop(d, None); ip += 1; continue
                    if (mn == 'lea' and s.type == cxm.X86_OP_MEM
                            and s.mem.base == RBP and s.mem.index == 0):
                        E[d] = ('ARGPTR', s.mem.disp); TAG.pop(d, None)
                        ip += 1; continue
                    if s.type == cxm.X86_OP_REG:
                        if s.reg in E:
                            E[d] = E[s.reg]
                        else:
                            E.pop(d, None)
                        if s.reg in TAG:
                            TAG[d] = TAG[s.reg]
                        else:
                            TAG.pop(d, None)
                    elif (s.type == cxm.X86_OP_MEM and s.mem.base == R8
                          and s.mem.disp == 0 and selfreg[0] is None):
                        E[d] = params[0]; selfreg[0] = d; TAG.pop(d, None)
                    elif (s.type == cxm.X86_OP_MEM and s.mem.disp == 0
                          and s.mem.index == 0 and isexpr(E.get(s.mem.base))):
                        E[d] = E[s.mem.base]; TAG.pop(d, None)   # cache-cell deref
                    elif (s.type == cxm.X86_OP_MEM and s.mem.base == d
                          and istup(E.get(d)) and s.mem.disp >= 0x18
                          and (s.mem.disp - 0x18) % 8 == 0):
                        tup = E[d][1]; i = (s.mem.disp - 0x18) // 8  # GET_ITEM
                        if 0 <= i < len(tup):
                            E[d] = repr(tup[i])
                        else:
                            E.pop(d, None)
                        TAG.pop(d, None)
                    elif (s.type == cxm.X86_OP_MEM and s.mem.base == RBP
                          and s.mem.index == 0):
                        k = ('stk', s.mem.disp)
                        if k in STK:
                            E[d] = STK[k]
                            if k in STKTAG:
                                TAG[d] = STKTAG[k]
                            else:
                                TAG.pop(d, None)
                        else:
                            E.pop(d, None); TAG.pop(d, None)
                    elif s.type == cxm.X86_OP_MEM and s.mem.base == RIP:
                        TAG.pop(d, None)
                        t = I.address + I.size + s.mem.disp
                        v = rcst(t)
                        if t in cache_map:
                            E[d] = cache_map[t]              # module-var cache
                        elif isinstance(v, str) and v.isidentifier():
                            E[d] = ('NAME', v)
                        elif isinstance(v, tuple):
                            E[d] = ('TUPLE', v)
                        elif v is not None and not isinstance(v, bool):
                            E[d] = repr(v)
                        else:
                            E.pop(d, None)
                    else:
                        E.pop(d, None); TAG.pop(d, None)
                    ip += 1; continue
                if (mn == 'mov' and O and O[0].type == cxm.X86_OP_MEM
                        and O[0].mem.base == RBP and O[0].mem.index == 0
                        and len(O) == 2 and O[1].type == cxm.X86_OP_REG):
                    k = ('stk', O[0].mem.disp); gen[0] += 1
                    if O[1].reg in E:
                        STK[k] = E[O[1].reg]; STKGEN[k] = gen[0]
                        if O[1].reg in TAG:
                            STKTAG[k] = TAG[O[1].reg]
                        else:
                            STKTAG.pop(k, None)
                    else:
                        STK.pop(k, None); STKTAG.pop(k, None)
                    ip += 1; continue
                ip += 1
            r = ret[0]
            if isattr(r):
                r = (r[1] + '()') if r[2] in mcall0 else r[1]
            elif not isexpr(r):
                return None, None
            return uses, stmts + ['return %s' % r]

        u, _ = interp(False, set())
        if u is None:
            return None
        reused = {i for i, c in u.items() if c > 1}
        _, lines = interp(True, reused)
        if not lines:
            return None
        # require at least one call, attribute access, or concat operator
        if not any(('(' in ln) or ('.' in ln) or (' + ' in ln) for ln in lines):
            return None
        return lines

    # 32-bit register -> its 64-bit name (for immediate tracking in helpers).
    _REG32_TO_64 = {
        'eax': 'rax', 'ebx': 'rbx', 'ecx': 'rcx', 'edx': 'rdx', 'esi': 'rsi',
        'edi': 'rdi', 'ebp': 'rbp', 'r8d': 'r8', 'r9d': 'r9', 'r10d': 'r10',
        'r11d': 'r11', 'r12d': 'r12', 'r13d': 'r13', 'r14d': 'r14',
        'r15d': 'r15', 'al': 'rax', 'bl': 'rbx',
    }

    def _is_text_va(self, va):
        """True when `va` points into the PE `.text` section."""
        rva = va - self.image_base
        nm, _, _ = self._find_section_for_rva(rva)
        return nm == '.text'

    def _helper_is_mcall0_shape(self, hva):
        """True when helper `hva` matches Nuitka CALL_METHOD_NO_ARGS body shape:
        compact (25-160 insns), <=6 distinct internal callees, tail-calls a small
        stub (the shared CALL_FUNCTION_NO_ARGS). Cached per VA.

        Upper bound 160 (was 135): fused LOOKUP+CALL_FUNCTION_NO_ARGS helpers
        for zero-arg methods often land at ~137 insns under MSVC."""
        cache = getattr(self, '_mcall0_shape_cache', None)
        if cache is None:
            cache = {}
            self._mcall0_shape_cache = cache
        if hva in cache:
            return cache[hva]
        cache[hva] = False
        cxm = _capstone_x86
        if cxm is None or not self._is_text_va(hva):
            return False
        try:
            insns = list(self._bounded_disasm(hva, max_bytes=12000))
        except Exception:
            return False
        n = len(insns)
        if n < 25 or n > 160:
            return False
        internal = []
        tail_stub = False
        for i, I in enumerate(insns):
            if I.mnemonic != 'call' or not I.operands:
                continue
            if I.operands[0].type != cxm.X86_OP_IMM:
                continue
            t2 = I.operands[0].imm
            if not self._is_text_va(t2):
                continue
            internal.append(t2)
            if (n - 1 - i) > 45:
                continue
            try:
                stub_n = len(list(self._bounded_disasm(t2, max_bytes=3000)))
            except Exception:
                stub_n = 0
            if 20 <= stub_n <= 90:
                tail_stub = True
        uniq = set(internal)
        for t2 in uniq:
            try:
                if len(list(self._bounded_disasm(t2, max_bytes=12000))) > 400:
                    cache[hva] = False
                    return False
            except Exception:
                pass
        if not tail_stub or len(uniq) > 6:
            return False
        cache[hva] = True
        return True

    def _discover_call_helpers(self):
        """Legacy hook — CALL_METHOD_NO_ARGS is now decided per call-site via
        ``_helper_is_mcall0_shape`` (no global VA table needed). Returns empty
        sets so callers can keep merging without a slow module-wide prepass."""
        if self._mcall0_helpers is not None:
            return self._call0_helpers or set(), self._mcall0_helpers or set()
        self._call0_helpers = set()
        self._mcall0_helpers = set()
        return set(), set()

    def _returns_nuitka_bool(self, hva):
        """True if the helper at `hva` returns a nuitka_bool (the int enum
        -1/0/1 that Nuitka's comparison / truth / contains helpers return)
        rather than a PyObject* pointer. Decided STATICALLY from the helper's
        own ret paths: it must show POSITIVE bool evidence (a ret of 1 or -1,
        or a setcc-derived ret) and NEVER return a pointer. Returning only 0 is
        ambiguous with a NULL PyObject*, so it does not qualify. This is what
        separates a real Python `if`/`while` condition from a scaffold
        NULL-check, with zero false positives (validated against ground truth).
        Cached per VA. CPython x64 ABI, universal."""
        cache = self._nuitka_bool_cache
        if hva in cache:
            return cache[hva]
        cache[hva] = False                       # guard against recursion
        cxm = _capstone_x86
        if cxm is None:
            return False
        try:
            insns = self._bounded_disasm(hva, max_bytes=4096)
        except Exception:
            return False
        norm = self._REG32_TO_64
        imm = {}        # reg -> small immediate currently held
        isbool = set()  # regs produced by a setcc (value 0/1)
        rets = []       # ('bool'|'imm'|'ptr', value) per ret of rax
        POS = {1, -1, 0xffffffff, 0xffffffffffffffff}
        for I in insns:
            mn = I.mnemonic
            ops_ = I.operands
            if mn == 'ret':
                if 'rax' in isbool:
                    rets.append(('bool', None))
                elif 'rax' in imm:
                    rets.append(('imm', imm['rax']))
                else:
                    rets.append(('ptr', None))
                continue
            if mn.startswith('set') and ops_ and ops_[0].type == cxm.X86_OP_REG:
                r = norm.get(I.reg_name(ops_[0].reg), I.reg_name(ops_[0].reg))
                isbool.add(r); imm.pop(r, None)
                continue
            if mn == 'xor' and len(ops_) == 2 and ops_[0].type == ops_[1].type \
                    == cxm.X86_OP_REG and ops_[0].reg == ops_[1].reg:
                r = norm.get(I.reg_name(ops_[0].reg), I.reg_name(ops_[0].reg))
                imm[r] = 0; isbool.discard(r)
                continue
            if mn == 'mov' and len(ops_) == 2 and ops_[0].type == cxm.X86_OP_REG:
                r = norm.get(I.reg_name(ops_[0].reg), I.reg_name(ops_[0].reg))
                s = ops_[1]
                if s.type == cxm.X86_OP_IMM:
                    imm[r] = s.imm & 0xffffffffffffffff; isbool.discard(r)
                elif s.type == cxm.X86_OP_REG:
                    sr = norm.get(I.reg_name(s.reg), I.reg_name(s.reg))
                    if sr in imm:
                        imm[r] = imm[sr]; isbool.discard(r)
                    elif sr in isbool:
                        isbool.add(r); imm.pop(r, None)
                    else:
                        imm.pop(r, None); isbool.discard(r)
                else:
                    imm.pop(r, None); isbool.discard(r)
                continue
            if ops_ and ops_[0].type == cxm.X86_OP_REG:   # any other writer
                r = norm.get(I.reg_name(ops_[0].reg), I.reg_name(ops_[0].reg))
                imm.pop(r, None); isbool.discard(r)
        if not rets:
            return False
        if any(k == 'ptr' for k, _ in rets):
            return False
        res = any(k == 'bool' or (k == 'imm' and v in POS) for k, v in rets)
        cache[hva] = res
        return res

    def _is_attr_store_helper(self, hva):
        """`self.x = v` -> SET_ATTRIBUTE(tstate, target, attr, value), a helper
        that DISPATCHES the store through type->tp_setattro (struct offset 0x98)
        and returns a bool SUCCESS flag. Its `== false` error-exit `test/jcc`
        therefore mimics a real comparison branch and would otherwise be mistaken
        for a Python `if`. Recognise it structurally: a 0x98 type-slot access with
        NO tp_getattro (0x90) read — tp_getattro would mark an attribute GET, not a
        store. No read/get operation touches tp_setattro, so this is unambiguous.
        Cached per VA (helpers are binary-wide). CPython 3.10 / Win64 layout."""
        cache = self._attr_store_cache
        if hva in cache:
            return cache[hva]
        cache[hva] = False
        try:
            insns = self._bounded_disasm(hva, max_bytes=0x140)
        except Exception:
            return False
        touch_set = False
        for k, I in enumerate(insns):
            if k >= 90:
                break
            o = I.op_str
            for off_str, is_set in (("+ 0x98]", True), ("+ 0x90]", False)):
                if off_str in o:
                    base = o.split(off_str)[0][-7:]
                    if not any(b in base for b in ("rsp", "rbp", "rip")):
                        if is_set:
                            touch_set = True
                        else:
                            return False        # tp_getattro -> a GET, not a store
        cache[hva] = touch_set
        return touch_set

    # x86 conditional ops that test ORDERING (a<b etc.), not just equality.
    _ORDERING_CC = frozenset({
        'jl', 'jg', 'jle', 'jge', 'jb', 'ja', 'jbe', 'jae',
        'setl', 'setg', 'setle', 'setge', 'setb', 'seta', 'setbe', 'setae',
        'cmovl', 'cmovg', 'cmovle', 'cmovge', 'cmovb', 'cmova', 'cmovbe',
        'cmovae',
    })

    def _full_disasm(self, va, nbytes=768):
        """Disassemble `nbytes` from `va` WITHOUT stopping at the first ret
        (so a helper's slow path, past its fast-path return, is visible)."""
        rva = va - self.image_base
        _nm, sec, off = self._find_section_for_rva(rva)
        if not sec:
            return []
        data = sec.get_data()
        return list(self.md.disasm(data[off:off + nbytes], va))

    def _compare_operator(self, hva):
        """Classify a nuitka_bool COMPARISON helper's operator, CONSERVATIVELY.
        A Nuitka rich-compare helper begins with an identity fast-path
        (`cmp pA,pB; jne slow; mov reg,<1|0>; ret`): returning 1 on identity =>
        a reflexive operator, 0 => irreflexive. If the helper contains NO
        ordering conditionals (jl/jg/setl/...), it is a pure EQUALITY test, so
        identity->1 is `==` and identity->0 is `!=`. Any ordering conditional
        (could be <,<=,>,>=) yields None so the caller keeps the honest `cmp`.
        Returns '=='/'!='/None. Cached. Universal (CPython x64)."""
        cxm = _capstone_x86
        if cxm is None:
            return None
        if hva in self._compare_op_cache:
            return self._compare_op_cache[hva]
        self._compare_op_cache[hva] = None
        try:
            insns = self._full_disasm(hva, 768)
        except Exception:
            return None
        # Primary signal: the helper materialises its result with a `setcc`
        # whose condition IS the operator (validated: `sete`->'==' string
        # helper, `setne`->'!=', `setg/seta/...`->ordering). This is far more
        # reliable than the identity fast-path (which has type-specific shapes
        # and once flipped a string `==` to `!=`).
        ORD = ('jl', 'jg', 'jle', 'jge', 'jb', 'ja', 'jbe', 'jae',
               'setl', 'setg', 'setle', 'setge', 'setb', 'seta', 'setbe',
               'setae', 'cmovl', 'cmovg', 'cmovle', 'cmovge', 'cmovb',
               'cmova', 'cmovbe', 'cmovae')
        setccs = set()
        has_ordering = False
        for I in insns:
            if I.mnemonic in ('jmp',) and I.operands \
                    and I.operands[0].type == cxm.X86_OP_IMM \
                    and I.operands[0].imm > I.address + 0x300:
                break    # likely tail-jumped out of the helper
            if I.mnemonic in ORD:
                has_ordering = True
            if I.mnemonic.startswith('set'):
                setccs.add(I.mnemonic)
        if has_ordering:
            return None          # <, <=, >, >= — don't guess, keep honest cmp
        has_eq = bool(setccs & {'sete', 'setz'})
        has_ne = bool(setccs & {'setne', 'setnz'})
        op = None
        if has_eq and not has_ne:
            op = '=='
        elif has_ne and not has_eq:
            op = '!='
        else:
            # mixed (e.g. the multi-digit int loop) or none: disambiguate via
            # the identity fast-path return value.
            identity = None
            for idx, I in enumerate(insns):
                if (identity is None and I.mnemonic == 'cmp'
                        and len(I.operands) == 2
                        and I.operands[0].type == cxm.X86_OP_REG
                        and I.operands[1].type == cxm.X86_OP_REG):
                    for J in insns[idx + 1: idx + 8]:
                        if (J.mnemonic == 'xor' and len(J.operands) == 2
                                and J.operands[0].type == J.operands[1].type
                                == cxm.X86_OP_REG
                                and J.operands[0].reg == J.operands[1].reg):
                            identity = False
                            break
                        if (J.mnemonic == 'mov' and len(J.operands) == 2
                                and J.operands[0].type == cxm.X86_OP_REG
                                and J.operands[1].type == cxm.X86_OP_IMM
                                and J.operands[1].imm in (0, 1)):
                            identity = (J.operands[1].imm == 1)
                            break
                    if identity is not None:
                        break
            op = '==' if identity is True else '!=' if identity is False else None
        self._compare_op_cache[hva] = op
        return op

    def recover_real_branches(self, va, module_constants=None,
                              mod_consts_base=None, max_bytes=16384,
                              insns=None):
        """Return [(addr, marker, target)] for the REAL Python conditional
        branches in a compiled body — those whose tested value comes from a
        helper that returns a nuitka_bool (a comparison / truth / contains
        test) or an inlined identity-vs-None compare, NOT a scaffold NULL-check.
        `marker` is `<if cmp 200>` / `<if is None>` / `<if>`; `target` is the
        true/false branch's join (else/skip) address for nesting. Validated
        never-wrong (0 false positives vs ground truth); misses bare-truth
        branches (incomplete, not wrong). Pure static, universal."""
        cxm = _capstone_x86
        if cxm is None:
            return []
        base = mod_consts_base
        if base is None:
            base = getattr(self, '_last_mod_consts_base', None)
        consts = list(module_constants) if module_constants else None
        if insns is None:
            try:
                insns = self._bounded_disasm(va, max_bytes=max_bytes)
            except Exception:
                return []
        ins = []
        for I in insns:
            ins.append(I)
            if I.mnemonic == 'ret':
                break
        JCC = ('je', 'jne', 'jg', 'jl', 'jge', 'jle', 'ja', 'jb', 'jae',
               'jbe', 's', 'jns')

        def const_at(addr_va):
            if (consts is None or base is None or addr_va is None
                    or addr_va < base or (addr_va - base) % 8):
                return None
            i = (addr_va - base) // 8
            return consts[i] if 0 <= i < len(consts) else None

        def rip_const(I):
            if I.mnemonic not in ('mov', 'lea'):
                return None
            for op in I.operands:
                if (op.type == cxm.X86_OP_MEM
                        and op.mem.base == cxm.X86_REG_RIP):
                    return const_at(I.address + I.size + op.mem.disp)
            return None

        def is_none_mem(I):
            """True if instruction reads `[rip -> _Py_NoneStruct]`."""
            if self._none_iat is None:
                return False
            for op in I.operands:
                if (op.type == cxm.X86_OP_MEM
                        and op.mem.base == cxm.X86_REG_RIP
                        and I.address + I.size + op.mem.disp == self._none_iat):
                    return True
            return False

        def jcc_target(J):
            if J.operands and J.operands[0].type == cxm.X86_OP_IMM:
                return J.operands[0].imm
            return None

        addr_list = [I.address for I in ins]

        def else_end_of(T):
            """If the then-body that ends at the false-target `T` finishes with
            an unconditional `jmp JOIN`, there is an `else:` block [T, JOIN).
            Return JOIN, else None. (Standard Nuitka if/else layout:
            `THEN; jmp JOIN; ELSE: ...; JOIN:`.)"""
            if T is None:
                return None
            import bisect
            j = bisect.bisect_left(addr_list, T) - 1
            if j < 0:
                return None
            P = ins[j]
            if P.mnemonic == 'jmp':
                J = jcc_target(P)
                if J is not None and J > T:
                    return J
            return None

        def true_false_branch(from_i):
            """From the nuitka_bool helper call, the true/false branch is the
            jcc controlled by `cmp <reg>, 1` (compare the bool to TRUE); its
            target is the else/skip boundary — the reliable join anchor. The
            preceding `cmp reg,-1` is the exception check (skip it).
            Returns (jcc_addr, jcc_target, jcc_mnemonic). The mnemonic encodes
            the body layout: `jne TARGET` skips the body when FALSE, so the
            then-body is inline at [branch, TARGET) (TARGET = else/next); `je
            TARGET` jumps INTO the body when TRUE, so the body is placed
            out-of-line at TARGET and the linear fall-through is the sibling /
            next-elif compare (a flat continuation, not a nested then).

            Two scaffold layouts for the `-1` exception check coexist: `cmp
            reg,-1; je EXC` keeps the decisive `cmp reg,1` inline on the
            fall-through, but `cmp reg,-1; jne CONTINUE` puts the error-raise
            inline and the decisive `cmp reg,1` at CONTINUE (the jump target).
            So we scan linearly AND across that redirect, else every arm of a
            `match`/`if-elif` whose body raises (the worker coin dispatch) is
            missed and the chain never folds."""
            import bisect
            starts = [from_i]
            for j in range(from_i, min(from_i + 8, len(ins))):
                J = ins[j]
                if J.mnemonic == 'jne' and j > 0:
                    P = ins[j - 1]
                    if P.mnemonic == 'cmp' and len(P.operands) == 2 \
                            and P.operands[1].type == cxm.X86_OP_IMM \
                            and P.operands[1].imm == -1:
                        tgt = jcc_target(J)
                        if tgt is not None:
                            ti = bisect.bisect_left(addr_list, tgt)
                            if ti < len(addr_list) and addr_list[ti] == tgt:
                                starts.append(ti)
                        break
            # V4.x/3.12 (CTypeBool truth check): the decisive branch is
            # `test reg,reg ; je/jne TARGET` (getTruthCheckCode "X != false"), NOT
            # the nuitka_bool `cmp reg,1` form. Map polarity onto the legacy
            # convention so downstream chaining/layout is unchanged: `test;jne`
            # jumps when TRUE == legacy `je` (out-of-line then-body); `test;je`
            # jumps when FALSE == legacy `jne` (inline then, TARGET=join). Gated to
            # 3.11+ so 3.10 is byte-identical.
            if getattr(self, '_pycode_is_unstable', False):
                for s in starts:
                    for j in range(s, min(s + 16, len(ins))):
                        J = ins[j]
                        if J.mnemonic == 'call':
                            break                 # don't cross into a later compare
                        if J.mnemonic in ('je', 'jne') and j > 0:
                            P = ins[j - 1]
                            if (P.mnemonic == 'test' and len(P.operands) == 2
                                    and P.operands[0].type == cxm.X86_OP_REG
                                    and P.operands[1].type == cxm.X86_OP_REG
                                    and P.operands[0].reg == P.operands[1].reg):
                                inv = 'je' if J.mnemonic == 'jne' else 'jne'
                                return J.address, jcc_target(J), inv
            for s in starts:
                for j in range(s, min(s + 16, len(ins))):
                    J = ins[j]
                    if J.mnemonic in JCC and j > 0:
                        P = ins[j - 1]
                        if P.mnemonic == 'cmp' and len(P.operands) == 2 \
                                and P.operands[1].type == cxm.X86_OP_IMM \
                                and P.operands[1].imm == 1:
                            return J.address, jcc_target(J), J.mnemonic
            return None, None, None

        def _v4x_nb_error_sentinel(call_site_addr):
            """3.11+ ONLY: a DIRECT call immediately followed by `cmp e?x,-1 ; je`
            is Nuitka-V4.x's nuitka_bool/CBOOL error-exit (ComparisonCodes
            getErrorExitBoolCode condition 'res == -1') — positive proof the callee
            returns a comparison result, even when _returns_nuitka_bool's first-ret
            heuristic (setne;movzx;neg -> looks like a pointer) says no. A scaffold
            NULL-check compares a pointer to 0/None, never to -1."""
            import bisect
            ci = bisect.bisect_left(addr_list, call_site_addr)
            if ci >= len(addr_list) or addr_list[ci] != call_site_addr:
                return False
            for k in range(ci + 1, min(ci + 4, len(ins))):
                C = ins[k]
                if (C.mnemonic == 'cmp' and len(C.operands) == 2
                        and C.operands[0].type == cxm.X86_OP_REG
                        and C.operands[1].type == cxm.X86_OP_IMM
                        and C.operands[1].imm == -1):
                    return (k + 1 < len(ins) and ins[k + 1].mnemonic == 'je')
                if C.mnemonic in ('call', 'ret'):
                    break
            return False

        out = []
        cmp_arms = []            # comparison branches, normalized after the scan
        seen_helper_site = set()
        none_regs = set()        # registers currently holding the None pointer
        flags_from_none = False  # the most recent cmp/test compared with None
        for i, I in enumerate(ins):
            mn = I.mnemonic
            # --- track which registers hold None, and None comparisons -------
            # CPU flags are clobbered by any arithmetic/logic op and by calls,
            # so a `cmp reg,None` only governs the NEXT branch if nothing in
            # between rewrites the flags. Crucially, Nuitka's Py_DECREF
            # (`sub [mem],1; jne`) sits between many None-compares and unrelated
            # branches — without resetting here we'd flag every refcount check
            # as an `is None` branch (the 84->real-count fix).
            if mn in ('cmp', 'test'):
                regs_used = [op.reg for op in I.operands
                             if op.type == cxm.X86_OP_REG]
                flags_from_none = is_none_mem(I) or any(r in none_regs
                                                        for r in regs_used)
            elif mn in self._FLAG_CLOBBER or mn == 'call':
                flags_from_none = False
            if mn == 'mov' and I.operands and I.operands[0].type == cxm.X86_OP_REG:
                d = I.operands[0].reg
                if is_none_mem(I):
                    none_regs.add(d)
                else:
                    none_regs.discard(d)
            elif mn != 'cmp' and I.operands \
                    and I.operands[0].type == cxm.X86_OP_REG:
                none_regs.discard(I.operands[0].reg)

            if mn not in JCC:
                continue
            # (a) comparison / truth branch: tested value came from a helper
            #     that returns a nuitka_bool (not a scaffold NULL-check).
            hva = None
            call_site = None
            for J in reversed(ins[max(0, i - 8):i]):
                if J.mnemonic == 'call' and J.operands \
                        and J.operands[0].type == cxm.X86_OP_IMM:
                    hva = J.operands[0].imm
                    call_site = J.address
                    break
            if hva is not None and not self._is_attr_store_helper(hva) \
                    and (self._returns_nuitka_bool(hva)
                         or (getattr(self, '_pycode_is_unstable', False)
                             and _v4x_nb_error_sentinel(call_site))):
                # Dedup by CALL SITE, not by helper VA: a single helper (e.g.
                # the string-equality helper) is reused for every comparison in
                # an `if/elif` chain (`command == "a"` / `== "b"` / ...). Keying
                # on the helper would collapse the whole chain to one branch;
                # keying on the call instruction keeps one branch per source
                # comparison (while still merging the -1/1 double-jcc of one
                # call, which share a call site).
                if call_site in seen_helper_site:   # one if per call site
                    continue
                seen_helper_site.add(call_site)
                ctx = None
                for J in reversed(ins[max(0, i - 10):i]):
                    c = rip_const(J)
                    if c is not None:
                        ctx = c
                        break
                # the structuring boundary = the true/false branch's target
                br_addr, target, jcc_mn = true_false_branch(i)
                # Exact == / != ONLY for NUMERIC comparisons (validated correct:
                # `== 200`). For string/object compare helpers neither the
                # identity fast-path NOR the internal setcc maps reliably to the
                # source operator (both flipped `== "socks4"` to `!=` in
                # testing), so those keep the honest, never-wrong `cmp` marker.
                op = (self._compare_operator(hva)
                      if isinstance(ctx, (int, float))
                      and not isinstance(ctx, bool) else None)
                if ctx is not None and op is not None:
                    marker = '<if %s %r>' % (op, ctx)
                elif ctx is not None:
                    marker = '<if cmp %r>' % ctx
                else:
                    marker = '<if>'
                # The body layout depends on the decisive jcc polarity (see
                # true_false_branch): `jne TARGET` => then-body inline at
                # [branch, TARGET); `je TARGET` => then-body out-of-line at
                # TARGET, with the fall-through being the next sibling/elif
                # compare. Record both so the cascade post-pass can stitch an
                # if/elif/else chain; fall-through is the address right after
                # the decisive jcc.
                import bisect as _bisect
                ai = _bisect.bisect_left(addr_list, br_addr) if br_addr else -1
                fallthrough = (addr_list[ai + 1] if 0 <= ai < len(addr_list) - 1
                               and addr_list[ai] == br_addr else None)
                cmp_arms.append({
                    'addr': br_addr or I.address, 'marker': marker,
                    'hva': hva, 'jcc_mn': jcc_mn, 'target': target,
                    'fallthrough': fallthrough,
                    'else_end': else_end_of(target),
                    # The mnemonic of the jcc this arm is anchored on. When
                    # true_false_branch found no `cmp reg,1` decode (jcc_mn None)
                    # the anchor is `I` itself; a `jns`/`js` anchor there is the
                    # helper's signed -1 EXCEPTION-sentinel guard, never a real
                    # source branch (see the unbounded-undecidable drop below).
                    'anchor_mn': I.mnemonic,
                })
            # (b) identity-vs-None branch (`x is None` / `x is not None`),
            #     inlined as a pointer compare with no helper call. Polarity
            #     from the jump that SKIPS the then-body: `cmp x,None; je SKIP`
            #     skips when x==None, so the body runs when x is not None;
            #     `jne SKIP` -> body runs when x is None.
            elif flags_from_none:
                tgt = jcc_target(I)
                marker = ('<if is not None>' if I.mnemonic == 'je'
                          else '<if is None>')
                out.append((I.address, marker, tgt, else_end_of(tgt)))
                flags_from_none = False

        # --- stitch if/elif/else cascades -----------------------------------
        # A run of comparison arms that test the SAME value against different
        # constants (`if command=="a": ... elif command=="b": ...`) compiles to
        # a chain linked through control flow: a `jne` arm continues at its jump
        # target, a `je` arm continues at its fall-through, and the next arm's
        # compare begins right there. We follow that link (requiring the SAME
        # helper, so unrelated compares never merge) and renormalize every arm
        # to a uniform then=[arm, next_arm) / else=[next_arm, JOIN) shape, so
        # the renderer folds the whole thing into one flat `if/elif/.../else`
        # instead of a rightward staircase. Out-of-line `je` bodies still land
        # best-effort (their tokens sort after the join). Arms that are not part
        # of a >=2 chain keep their standalone shape.
        cmp_arms.sort(key=lambda a: a['addr'])

        def chain_next_addr(a):
            if a['jcc_mn'] == 'jne':
                return a['target']        # false -> next compare / else
            if a['jcc_mn'] == 'je':
                return a['fallthrough']   # true jumps to out-of-line body
            return None                   # ordering ccs: don't chain

        arm_addrs = [a['addr'] for a in cmp_arms]
        succ = [None] * len(cmp_arms)
        has_pred = [False] * len(cmp_arms)
        import bisect as _bis
        for idx, a in enumerate(cmp_arms):
            cont = chain_next_addr(a)
            if cont is None:
                continue
            k = _bis.bisect_left(arm_addrs, cont)
            if k < len(cmp_arms) and 0 <= arm_addrs[k] - cont <= 128 \
                    and cmp_arms[k]['hva'] == a['hva'] and k != idx:
                succ[idx] = k
                has_pred[k] = True

        normalized = [None] * len(cmp_arms)   # (target, else_end) per arm
        for idx in range(len(cmp_arms)):
            if has_pred[idx] or succ[idx] is None:
                continue                       # only start at a chain head
            chain = [idx]
            j = succ[idx]
            seen = {idx}
            while j is not None and j not in seen:
                chain.append(j)
                seen.add(j)
                j = succ[j]
            if len(chain) < 2:
                continue
            join = max((cmp_arms[c]['else_end'] for c in chain
                        if cmp_arms[c]['else_end'] is not None), default=None)
            if join is None:
                continue                       # no reliable reconvergence point
            for pos, c in enumerate(chain):
                if pos + 1 < len(chain):
                    nt = cmp_arms[chain[pos + 1]]['addr']
                    normalized[c] = (nt, join)
                else:                          # last arm of the chain
                    es = chain_next_addr(cmp_arms[c])
                    if es is not None and cmp_arms[c]['addr'] < es < join:
                        # a distinct trailing `else:` body lives at [es, join)
                        normalized[c] = (es, join)
                    else:
                        # no else clause (the no-match path goes straight to the
                        # join, e.g. a final `case`/`elif` with nothing after):
                        # still give it a real then-range so it folds as the
                        # closing `<elif>` instead of leaking out as a bare `if`
                        # inside the previous arm's else.
                        normalized[c] = (join, None)

        for idx, a in enumerate(cmp_arms):
            if normalized[idx] is not None:
                tgt, ee = normalized[idx]
            elif a['jcc_mn'] == 'je':
                # standalone out-of-line then: stay flat (no nesting range), as
                # [arm, target) would swallow unrelated following code.
                tgt, ee = None, None
            else:
                tgt, ee = a['target'], a['else_end']
            # UNBOUNDED-UNDECIDABLE GUARD: when true_false_branch found no
            # decisive `cmp reg,1` decode (jcc_mn is None), this arm was not
            # folded into a chain (tgt/ee None), AND the anchoring jcc is a
            # SIGNED branch (`jns`/`js`), the arm is anchored on the helper's
            # signed -1 EXCEPTION-sentinel guard (`test rax,rax; jns no_error`),
            # NOT a real source decision. Emitting it makes run_structured
            # recurse the then-region with stop=None, swallowing the ENTIRE rest
            # of the function into an empty `if X: pass`. Drop it: the linear
            # walk then continues past the scaffold and recovers the loop /
            # branches / return that follow. Narrow to jns/js ONLY so a genuine
            # bare-truth `if obj:` (test;je/jne-anchored, then-region terminates
            # at a return) is KEPT.
            if (tgt is None and ee is None and a['jcc_mn'] is None
                    and a.get('anchor_mn') in ('jns', 'js')):
                continue
            out.append((a['addr'], a['marker'], tgt, ee))
        return out

    def recover_module_global_names(self, func_ptr, module_constants,
                                    mod_consts_base=None, max_bytes=131072):
        """Return the set of names the module-init function STORES at module
        scope (the genuine module globals + module-level defs), read from the
        repeated store-helper pattern `mov rdx,[rip->KEY]; call STORE` in the
        module body. A helper used with >=2 DISTINCT identifier keys is a
        module-dict store (Nuitka emits `UPDATE_STRING_DICT(moduledict, name,
        value)` with the name in rdx); a one-off string passed to a regular
        call never reaches the threshold. Lets the reconstructor keep only the
        real ALL_CAPS globals and drop pool strings that are actually attribute
        names (colorama `Fore.MAGENTA`) or imported constants — neither is ever
        stored as a global. Pure static, universal. Returns set() on failure."""
        cxm = _capstone_x86
        if cxm is None or not func_ptr or not module_constants:
            return set()
        consts = list(module_constants)
        base = mod_consts_base
        if base is None:
            base = getattr(self, '_last_mod_consts_base', None)
        if base is None:
            return set()
        try:
            insns = list(self._bounded_disasm(func_ptr, max_bytes=max_bytes))
        except Exception:
            return set()

        # Gate on confirmed UPDATE_STRING_DICT helpers — LOOKUP_ATTR/METHOD
        # use the same `mov rdx, name; call` shape and would otherwise pollute
        # module_globals with every attribute/method name (setWindowTitle=None…).
        cl = getattr(self, '_ndl_helper_classifier', None)
        if cl is None:
            try:
                cl = _NativeHelperClassifier(self)
                self._ndl_helper_classifier = cl
            except Exception:
                cl = None

        def rip_str(I):
            if I.mnemonic != 'mov':
                return None
            for op in I.operands:
                if (op.type == cxm.X86_OP_MEM
                        and op.mem.base == cxm.X86_REG_RIP):
                    addr = I.address + I.size + op.mem.disp
                    if addr < base or (addr - base) % 8:
                        return None
                    idx = (addr - base) // 8
                    if 0 <= idx < len(consts):
                        v = consts[idx]
                        return v if isinstance(v, str) else None
            return None

        by_helper = {}            # helper_va -> {identifier key, ...}
        rdx_key = None            # identifier currently in rdx
        rdx_age = 99              # instructions since rdx was set to it
        for I in insns:
            mn = I.mnemonic
            if (mn == 'mov' and I.operands
                    and I.operands[0].type == cxm.X86_OP_REG
                    and I.operands[0].reg == cxm.X86_REG_RDX):
                s = rip_str(I)
                rdx_key = s if (s and re.fullmatch(r'[A-Za-z_]\w*', s)) else None
                rdx_age = 0
            elif mn == 'call':
                if (rdx_key is not None and rdx_age <= 3 and I.operands
                        and I.operands[0].type == cxm.X86_OP_IMM):
                    hva = I.operands[0].imm
                    _ok_store = True
                    if cl is not None:
                        try:
                            _ok_store = bool(cl._modstore_helper(hva))
                        except Exception:
                            _ok_store = False
                    if _ok_store:
                        by_helper.setdefault(hva, set()).add(rdx_key)
                rdx_key = None
            else:
                rdx_age += 1
                if rdx_age > 3:
                    rdx_key = None
        names = set()
        for keys in by_helper.values():
            if len(keys) >= 2:
                names |= keys
        # Defense: never treat methodish / Qt API leaf names as module globals
        # even if a helper was misclassified as a store.
        _drop = set()
        for n in names:
            if (n[:1].islower()
                    and (n.startswith(('set', 'get', 'add', 'is', 'has',
                                       'on_', 'setup_', 'show_', 'load_',
                                       'save_', 'update_', 'append', 'remove',
                                       'insert', 'clear', 'emit', 'connect'))
                         or n in ('resize', 'exec', 'quit', 'hide', 'show',
                                  'accept', 'reject', 'clicked', 'timeout',
                                  'processEvents', 'singleShot', 'strip',
                                  'split', 'replace', 'find', 'count'))):
                _drop.add(n)
            elif (len(n) > 1 and n[0] == 'Q' and n[1].isupper()):
                # Qt class/enum names are imports/attrs, never data globals
                _drop.add(n)
        names -= _drop
        return names

    # jcc -> the THEN condition (the fall-through executes when the jcc is NOT
    # taken, since Nuitka lays out `cmp; jcc SKIP; <then>; SKIP:`). So the source
    # `if X != -1:` compiles to `je SKIP`, and the then-condition is the NEGATION
    # of the jcc test.
    _JCC_THEN = {'je': '!=', 'jz': '!=', 'jne': '==', 'jnz': '==',
                 'jg': '<=', 'jge': '<', 'jl': '>=', 'jle': '>',
                 'ja': '<=', 'jae': '<', 'jb': '>=', 'jbe': '>'}

    def _cfg_analyze(self, va, max_bytes=49152, max_blocks=2200, insns=None):
        """Build a basic-block CFG once per function and derive BOTH the natural
        loops (dominators) AND the conditional branches with exact merge points
        (post-dominators). Cached by VA, budgets, and exact instruction extent.
        Returns {'loops': [(header, latch)],
        'branches': [(jcc_addr, op, rhs, join, else_end)]} or None on failure.

        This is the structuring core: dominator-based loop detection pins the real
        `for`/`while` header on tangled match+exception CFGs, and post-dominator
        merge points let nested `if balance != -1:`/`if balance > 0:` integer
        conditionals (which the helper-based recover_real_branches misses) be
        emitted with correct then/else boundaries — NEVER fabricated (only
        cmp-vs-immediate branches; bare null/truth tests are left to the existing
        recogniser)."""
        # The caller may supply the exact instruction extent used by
        # run_structured (notably _disasm_body(..., func_extent=True)).  The old
        # implementation always re-disassembled with _bounded_disasm, whose
        # first-ret boundary can disagree with the renderer, then cached that
        # result by VA alone.  A small/failed balanced analysis therefore
        # poisoned every later complete emit.  Cache by budget + exact extent,
        # and analyse the supplied extent verbatim when available.
        _provided_insns = insns is not None
        if _provided_insns:
            try:
                insns = list(insns)
            except Exception:
                return None
            # Bounds alone are not an exact extent identity: two decoded
            # instruction streams can have the same count/first/last address
            # while differing at a branch in between.  Fingerprint the compact
            # instruction shape so a caller-supplied CFG can never reuse a
            # structurally different cached graph.
            _extent_fp = hashlib.blake2b(digest_size=16)
            for _ci in insns:
                _extent_fp.update(('%x:%s:%s:%s\0' % (
                    int(_ci.address), getattr(_ci, 'size', 0),
                    _ci.mnemonic, _ci.op_str)).encode(
                        'utf-8', errors='surrogatepass'))
            _extent_key = (
                len(insns),
                insns[0].address if insns else None,
                insns[-1].address if insns else None,
                _extent_fp.digest(),
            )
        else:
            _extent_key = None
        _cache_key = (int(va), int(max_bytes), int(max_blocks), _extent_key)
        cache = getattr(self, '_cfg_cache', None)
        if cache is None:
            cache = self._cfg_cache = {}
        if _cache_key in cache:
            return cache[_cache_key]
        cache[_cache_key] = None                      # default (failure)
        cxm = _capstone_x86
        if cxm is None:
            return None
        CFLOW = {'jmp', 'je', 'jne', 'jz', 'jnz', 'jg', 'jge', 'jl', 'jle',
                 'ja', 'jae', 'jb', 'jbe', 'js', 'jns', 'jo', 'jno', 'jp', 'jnp'}
        COND = CFLOW - {'jmp'}
        if not _provided_insns:
            try:
                insns = list(self._bounded_disasm(va, max_bytes=max_bytes))
            except Exception:
                return None
        by = {i.address: i for i in insns}
        order = sorted(by)
        if not order or len(order) > max_blocks * 6:
            return None
        nxt = {order[k]: order[k + 1] for k in range(len(order) - 1)}
        inr = set(by)

        def _t(i):
            if i.op_str.startswith('0x'):
                try:
                    return int(i.op_str, 16)
                except Exception:
                    return None
            return None

        leaders = {va}
        for a in order:
            i = by[a]
            if i.mnemonic in CFLOW:
                t = _t(i)
                if t is not None and t in inr:
                    leaders.add(t)
                nx = nxt.get(a)
                if nx is not None:
                    leaders.add(nx)
            elif i.mnemonic == 'ret':
                nx = nxt.get(a)
                if nx is not None:
                    leaders.add(nx)
        leaders = sorted(L for L in leaders if L in inr)
        if len(leaders) > max_blocks:
            return None
        succ = {}; term = {}
        for idx, L in enumerate(leaders):
            nextL = leaders[idx + 1] if idx + 1 < len(leaders) else None
            a = L; last = L
            while a is not None and (nextL is None or a < nextL):
                last = a
                i = by[a]
                if i.mnemonic in CFLOW or i.mnemonic == 'ret':
                    break
                a = nxt.get(a)
            ti = by[last]; term[L] = last; outs = []
            if ti.mnemonic == 'ret':
                outs = []
            elif ti.mnemonic == 'jmp':
                t = _t(ti)
                if t in inr:
                    outs = [t]
            elif ti.mnemonic in COND:
                t = _t(ti); fall = nxt.get(last)
                if t in inr:
                    outs.append(t)
                if fall in inr:
                    outs.append(fall)
            else:
                fall = nxt.get(last)
                if fall in inr:
                    outs = [fall]
            succ[L] = outs
        seen = set(); stack = [va]
        while stack:
            b = stack.pop()
            if b in seen:
                continue
            seen.add(b)
            for s in succ.get(b, []):
                stack.append(s)
        blocks = sorted(seen)
        succ = {b: [s for s in succ.get(b, []) if s in seen] for b in blocks}
        preds = {b: [] for b in blocks}
        for b in blocks:
            for s in succ[b]:
                preds[s].append(b)
        allset = set(blocks)

        # ---- dominators -> natural loops ----
        from collections import deque as _CfgDeque
        dom = {b: set(allset) for b in blocks}
        dom[va] = {va}
        _dom_work = _CfgDeque(b for b in blocks if b != va)
        _dom_queued = set(_dom_work)
        while _dom_work:
            b = _dom_work.popleft()
            _dom_queued.discard(b)
            ps = preds[b]
            if ps:
                inter = set(allset)
                for p in ps:
                    inter &= dom[p]
                new = {b} | inter
            else:
                new = {b}
            if new != dom[b]:
                dom[b] = new
                for child in succ.get(b, ()):
                    if child != va and child not in _dom_queued:
                        _dom_work.append(child)
                        _dom_queued.add(child)
        loopmap = {}
        for n in blocks:
            for h in succ[n]:
                if h in dom[n]:
                    # A self-loop's latch is its header.  Walking predecessors
                    # from that same node would absorb the preheader into the
                    # natural-loop body, even though no path from the header
                    # back to the preheader exists.
                    body = {h, n}; st = ([] if n == h else [n])
                    while st:
                        x = st.pop()
                        for p in preds[x]:
                            if p not in body:
                                body.add(p); st.append(p)
                    # A natural loop can have more than one latch.  Keep the
                    # complete region instead of overwriting all but the last
                    # back-edge; the legacy ``loops`` projection below remains
                    # available to existing callers.
                    region = loopmap.setdefault(
                        h, {'body': set(), 'latches': set()})
                    region['body'].update(body)
                    region['latches'].add(n)

        loop_regions = {}
        loops = []
        for h, region in sorted(loopmap.items()):
            body = frozenset(region['body'])
            latches = tuple(sorted(region['latches']))
            exits = tuple(sorted({
                target
                for member in body
                for target in succ.get(member, ())
                if target not in body
            }))
            loop_regions[h] = {
                'header': h,
                'body': tuple(sorted(body)),
                'latches': latches,
                'exits': exits,
            }
            # Compatibility: the former implementation retained the last
            # latch encountered in ascending block order, i.e. the greatest
            # latch address.
            if latches:
                loops.append((h, latches[-1]))

        # ---- post-dominators (dominators on the reversed CFG) -> if-merge ----
        # Model all native returns through one synthetic EXIT.  Initialising
        # every real return as an unrelated singleton makes post-dominators
        # disappear in multi-return functions, even when both arms of a Python
        # ``if`` have a perfectly ordinary first join before those returns.
        # The synthetic node is analysis-only and is never exposed as an address.
        _pdom_exit = object()
        _pdom_nodes = set(allset)
        _pdom_nodes.add(_pdom_exit)
        pdom = {b: set(_pdom_nodes) for b in blocks}
        pdom[_pdom_exit] = {_pdom_exit}
        _pdom_work = _CfgDeque(blocks)
        _pdom_queued = set(blocks)
        while _pdom_work:
            b = _pdom_work.popleft()
            _pdom_queued.discard(b)
            outs = succ[b] or [_pdom_exit]
            inter = set(_pdom_nodes)
            for s in outs:
                inter &= pdom[s]
            new = {b} | inter
            if new != pdom[b]:
                pdom[b] = new
                for parent in preds.get(b, ()):
                    if parent not in _pdom_queued:
                        _pdom_work.append(parent)
                        _pdom_queued.add(parent)

        def _ipdom(b):
            cand = pdom[b] - {b}
            for d in cand:
                # ``d`` is the nearest strict post-dominator iff every other
                # strict post-dominator is itself post-dominated by ``d``.
                # The former test used the inverse relation (d in pdom[o]) and
                # therefore selected the *farthest* node, normally the function
                # exit.  That inflated an inner branch to the rest of the native
                # function and was the root cause of recursive region blow-ups.
                if all((o == d or o in pdom[d]) for o in cand):
                    return None if d is _pdom_exit else d
            return None

        # ---- exception-sink identification (shared Nuitka frame_exception_exit)
        # Error edges (`<call>; test rax,rax; je H` NULL, or `cmp r,-1; je H`)
        # all converge on one cold block per frame. Found by frequency: a je/jz
        # target reached by >=2 NULL/-1 checks; plus high-in-degree `ret` blocks.
        # A post-dom JOIN that lands on such a sink is a DEGENERATE function-end
        # reconvergence (not a real if/else boundary) — used to clamp join-fill.
        from collections import Counter as _Counter
        _err_tgt = _Counter()
        for b in blocks:
            ta = term[b]; ti = by[ta]
            if ti.mnemonic not in ('je', 'jz'):
                continue
            a = b; lastcmp = None
            while a is not None and a <= ta:
                if by[a].mnemonic in ('test', 'cmp'):
                    lastcmp = by[a]
                a = nxt.get(a)
            if lastcmp is None:
                continue
            _os = lastcmp.op_str
            if ((lastcmp.mnemonic == 'test' and re.match(r'^(\w+),\s*\1$', _os))
                    or (lastcmp.mnemonic == 'cmp'
                        and re.search(r',\s*(?:-1|0x0*f{8,16})$', _os))):
                T = _t(ti)
                if T in inr:
                    _err_tgt[T] += 1
        exc_sinks = {t for t, c in _err_tgt.items() if c >= 2}
        for b in blocks:
            if by[term[b]].mnemonic == 'ret' and len(preds[b]) >= 3:
                exc_sinks.add(b)

        # ---- post-dominator JOINS for every 2-way forward conditional ---------
        # Keyed by jcc address; consumed ONLY to fill the missing join of branches
        # recover_real_branches already proved real (its bare-truth `<if>` arrive
        # with join=None). The caller A/B-tests with vs without these joins and
        # keeps the richer body, so a wrong (degenerate) join self-corrects.
        cond_joins = {}
        branch_regions = {}
        for b in blocks:
            if len(succ.get(b, [])) != 2:
                continue
            ta = term[b]; ti = by[ta]
            if ti.mnemonic not in COND:
                continue
            T = _t(ti)
            fall = nxt.get(ta)
            merge = _ipdom(b)
            branch_regions[ta] = {
                'block': b,
                'jcc': ti.mnemonic,
                'taken': T if T in inr else None,
                'fallthrough': fall if fall in inr else None,
                'merge': merge,
            }
            if T is None or T <= ta:
                continue
            else_end = merge if (merge is not None and merge != T and merge > T) else T
            cond_joins[ta] = (T, else_end)

        # ---- conditional branches: only cmp-vs-immediate (real int compares) --
        branches = []
        for b in blocks:
            ta = term[b]
            ti = by[ta]
            if ti.mnemonic not in self._JCC_THEN or len(succ.get(b, [])) != 2:
                continue
            T = _t(ti)
            if T is None or T <= ta:           # forward branch only
                continue
            # recover `cmp <reg>, <imm>` in this block (last one before the jcc)
            op = rhs = None
            a = b
            while a is not None and a <= ta:
                ii = by[a]
                if ii.mnemonic == 'cmp':
                    mm = re.match(r'^[a-z0-9]+,\s*(-?(?:0x[0-9a-fA-F]+|\d+))$',
                                  ii.op_str)
                    if mm:
                        try:
                            rhs = int(mm.group(1), 0)
                            op = self._JCC_THEN[ti.mnemonic]
                        except Exception:
                            op = rhs = None
                    else:
                        op = rhs = None          # cmp reg,reg -> not a const cond
                a = nxt.get(a)
            if op is None:
                continue                          # bare test / reg-reg: leave it
            if rhs in (-1, 0, 1):
                # -1/0/1 are the nuitka_bool ENUM sentinels ({-1 err,0 false,
                # 1 true}); a `cmp eax,-1`/`cmp eax,1` here is the bool DECODE of
                # a comparison helper (`balance != -1` etc.), already handled by
                # the helper-based recogniser + the interpreter's nbool path —
                # NOT a separate source `if`. Emitting it fabricates nested junk.
                continue
            merge = _ipdom(b)
            join = T
            if merge is not None and merge != T and merge > T:
                else_end = merge
            else:
                else_end = T                      # no else (jcc skips to merge)
            branches.append((ta, op, rhs, join, else_end))

        result = {
            'loops': loops,
            'loop_regions': loop_regions,
            'branches': branches,
            'cond_joins': cond_joins,
            # Exact, polarity-neutral native branch topology.  Unlike the
            # legacy ``cond_joins`` tuple this does not assume a forward
            # skip-then layout; a typed flags/SSA pass can decide which successor
            # represents the Python truth arm without consulting addresses.
            'branch_regions': branch_regions,
            'exc_sinks': exc_sinks,
            # Expose the proven reachable CFG to the recursive emitter/origin
            # analysis.  These are immutable address containers, not Capstone
            # objects, so caching remains bounded.
            'entry': va,
            'blocks': tuple(blocks),
            'succ': {b: tuple(succ.get(b, ())) for b in blocks},
            'preds': {b: tuple(preds.get(b, ())) for b in blocks},
            'term': dict(term),
            'postdom': {
                b: frozenset(x for x in pdom.get(b, ())
                             if x is not _pdom_exit)
                for b in blocks
            },
            'dominators': {
                b: frozenset(dom.get(b, ())) for b in blocks
            },
            'extent': _extent_key or (
                len(insns), order[0] if order else None,
                order[-1] if order else None),
        }
        cache[_cache_key] = result
        return result

    def recover_loops_cfg(self, va, max_bytes=49152, max_blocks=2200,
                          insns=None):
        """Natural loops from the CFG/dominator analysis (see _cfg_analyze)."""
        r = self._cfg_analyze(
            va, max_bytes=max_bytes, max_blocks=max_blocks, insns=insns)
        return r['loops'] if r else []

    def recover_loops_threading(self, va, max_bytes=49152):
        """Recover loop [header, loop_end) pairs from the UNIVERSAL back-edge latch
        Nuitka emits at the tail of EVERY loop (LoopCodes.py:generateLoopCode):
            call CONSIDER_THREADING ; test al,al ; jcc <exc> ; jmp <loop_start>
        i.e. a backward `jmp` immediately preceded (within ~7 insns) by a
        `test/cmp ; jcc` GIL guard. This catches `while`/`while True` loops with NO
        iterator (e.g. ui.py menus / async input loops) that the iternext and
        dominator detectors miss. loop_end == the instruction right after the
        back-edge jmp (Nuitka places `loop_end:` there). Returns [(header, loop_end)].
        Universal: the CONSIDER_THREADING latch is on every Nuitka loop, all
        versions, free & commercial."""
        try:
            insns = list(self._bounded_disasm(va, max_bytes=max_bytes))
        except Exception:
            return []
        by = {i.address: i for i in insns}
        order = sorted(by)
        idx = {a: k for k, a in enumerate(order)}
        out = []
        for k, a in enumerate(order):
            I = by[a]
            if I.mnemonic != "jmp" or not I.op_str.startswith("0x"):
                continue
            try:
                tgt = int(I.op_str, 16)
            except Exception:
                continue
            if tgt >= a or tgt not in by:        # must be a backward jmp into the fn
                continue
            # preceding ~7 insns must carry a `test/cmp ; jcc` (the GIL guard)
            guard = False
            for j in range(max(0, k - 7), k):
                jm = by[order[j]].mnemonic
                if (jm in ("je", "jne", "jz", "jnz") and j > 0
                        and by[order[j - 1]].mnemonic in ("test", "cmp")):
                    guard = True
                    break
            if not guard:
                continue
            # reject if a `ret` lies between header and latch (tail-call, not a loop)
            if any(by[order[m]].mnemonic == "ret" for m in range(idx[tgt], k)):
                continue
            loop_end = order[k + 1] if k + 1 < len(order) else (a + I.size)
            out.append((tgt, loop_end))
        return out

    def recover_while_loops(self, va, insns=None, max_bytes=16384):
        """Rileva while loops: backward jmp senza iternext e senza
        CONSIDER_THREADING (già coperto da recover_loops_threading)."""
        if insns is None:
            try:
                insns = list(self._bounded_disasm(va, max_bytes=max_bytes))
            except Exception:
                return []
        loops = []
        seen = set()
        for i, insn in enumerate(insns):
            if insn.mnemonic != 'jmp' or not insn.op_str.startswith('0x'):
                continue
            tgt = int(insn.op_str, 16)
            if tgt >= insn.address or tgt in seen:
                continue
            # Escludi loop con iternext (già coperti da recover_loops)
            has_iter = False
            for j in range(i - 30, i):
                if j < 0:
                    continue
                if insns[j].mnemonic == 'call' and insns[j].op_str.startswith('0x'):
                    has_iter = True
                    break
            if has_iter:
                continue
            seen.add(tgt)
            loops.append((tgt, insn.address))
        return loops

    def recover_branches_cfg(self, va, max_bytes=49152, max_blocks=2200,
                             insns=None):
        """Conditional branches (cmp-vs-immediate) with post-dominator merge
        points — recovers nested integer `if`s the helper recogniser misses."""
        r = self._cfg_analyze(
            va, max_bytes=max_bytes, max_blocks=max_blocks, insns=insns)
        return r['branches'] if r else []

    def _is_iter_maker_thunk(self, va):
        """True if `va` is Nuitka's GET_ITER thunk (`mov rdx,[type+0xd8]`(tp_iter)
        then `call rdx`). Nuitka routes `for x in seq:` over a list through this
        thunk instead of an inline tp_iternext, so the loop carries no
        `mov reg,[base+0xe0]` signal in its own body — without recognising the
        thunk, recover_loops misses every for-over-container loop."""
        cache = getattr(self, "_iter_thunk_cache", None)
        if cache is None:
            cache = self._iter_thunk_cache = {}
        if va in cache:
            return cache[va]
        res = False
        try:
            for ins in self._bounded_disasm(va, max_bytes=72):
                if (ins.mnemonic == "mov"
                        and re.match(r"^rdx, qword ptr \[\w+ \+ 0xd8\]$", ins.op_str)):
                    res = True
                    break
                if ins.mnemonic in ("ret", "jmp"):
                    break
        except Exception:
            res = False
        cache[va] = res
        return res

    def recover_loops(self, va, insns=None, max_bytes=16384, classifier=None):
        """Detect `for` loops: a back-edge (a jump to an EARLIER address) whose
        spanned body contains a `tp_iternext` (PyTypeObject + 0xe0) call is the
        compiled form of `for x in it:`. Returns [(header_addr, end_addr)] (the
        loop spans [header, end]). Gated on the iternext signal so the many
        scaffold/exception back-edges Nuitka emits are not mistaken for loops.
        Pure static, universal; misses `while` loops with no iterator."""
        cxm = _capstone_x86
        if cxm is None:
            return []
        if insns is None:
            try:
                insns = self._bounded_disasm(va, max_bytes=max_bytes)
            except Exception:
                return []
        ins = []
        for I in insns:
            ins.append(I)
            if I.mnemonic == 'ret':
                break
        if not ins:
            return []
        lo = ins[0].address
        JCC = ('je', 'jne', 'jg', 'jl', 'jge', 'jle', 'ja', 'jb', 'jae',
               'jbe', 'js', 'jns', 'jmp')
        # ---- CPython 3.11+/Nuitka-V4.x header-anchored loop recovery ----------
        # V4.x emits ITERATOR_NEXT as an INDIRECT CALL through the tp_iternext
        # slot (`call qword ptr [reg+0xe0]`); 3.8-3.10 loaded the slot into a
        # register first (`mov reg,[reg+0xe0]`). The legacy detector only saw the
        # `mov` form, so every V4.x `for` was missed. A real for loop_start BEGINS
        # with the iternext access, so we anchor the header to an iternext in its
        # first bytes; only when nothing is anchored do we fall back to the legacy
        # span model. Gated on 3.11+ -> 3.8-3.10 byte-identical.
        if getattr(self, '_pycode_is_unstable', False):
            def _iter_slot(I):
                if (I.mnemonic == 'mov' and len(I.operands) == 2
                        and I.operands[0].type == cxm.X86_OP_REG
                        and I.operands[1].type == cxm.X86_OP_MEM):
                    op = I.operands[1]
                elif (I.mnemonic == 'call' and I.operands
                      and I.operands[0].type == cxm.X86_OP_MEM):
                    op = I.operands[0]
                else:
                    return False
                return (op.mem.disp == 0xe0 and op.mem.index == 0
                        and op.mem.base not in (cxm.X86_REG_RSP,
                                                cxm.X86_REG_RBP))
            _iternext = [I.address for I in ins if _iter_slot(I)]
            _getiter = []
            for I in ins:
                if (I.mnemonic == 'call' and I.operands
                        and I.operands[0].type == cxm.X86_OP_IMM):
                    _t = I.operands[0].imm
                    if classifier is not None:
                        try:
                            _apis = classifier.collect_apis(_t)
                        except Exception:
                            _apis = {}
                        if _apis.get('PyObject_GetIter', 9) <= 2:
                            _getiter.append(I.address)
                    if self._is_iter_maker_thunk(_t):
                        _getiter.append(I.address)
            if not _iternext and not _getiter:
                return []
            _HDR = 80          # loop_start .. tp_iternext call is ~9-12 bytes
            _anchored, _sa = [], set()
            for I in ins:
                if (I.mnemonic in JCC and I.operands
                        and I.operands[0].type == cxm.X86_OP_IMM):
                    T = I.operands[0].imm
                    if (lo <= T < I.address and T not in _sa
                            and any(T <= x <= T + _HDR for x in _iternext)):
                        _sa.add(T)
                        _anchored.append((T, I.address))
            if _anchored:
                _cand = _anchored
            else:
                _cand, _sb = [], set()
                for I in ins:
                    if (I.mnemonic in JCC and I.operands
                            and I.operands[0].type == cxm.X86_OP_IMM):
                        T = I.operands[0].imm
                        if (lo <= T < I.address and T not in _sb
                                and (any(T <= x <= I.address for x in _iternext)
                                     or any(T <= x <= I.address
                                            for x in _getiter))):
                            _sb.add(T)
                            _cand.append((T, I.address))
            _kept = []
            for h, e in sorted(_cand, key=lambda L: -(L[1] - L[0])):
                if not any(kh <= h and e <= ke for kh, ke in _kept):
                    _kept.append((h, e))
            return sorted(_kept)
        iternext = []
        getiter_sites = []
        for I in ins:
            if (I.mnemonic == 'mov' and len(I.operands) == 2
                    and I.operands[0].type == cxm.X86_OP_REG
                    and I.operands[1].type == cxm.X86_OP_MEM
                    and I.operands[1].mem.disp == 0xe0
                    and I.operands[1].mem.index == 0
                    and I.operands[1].mem.base not in (cxm.X86_REG_RSP,
                                                       cxm.X86_REG_RBP)):
                iternext.append(I.address)
            if (I.mnemonic == 'call' and I.operands
                    and I.operands[0].type == cxm.X86_OP_IMM):
                _t = I.operands[0].imm
                if classifier is not None:
                    apis = classifier.collect_apis(_t)
                    if apis.get('PyObject_GetIter', 9) <= 2:
                        getiter_sites.append(I.address)
                # Nuitka's iterator thunk (`for x in <container>:`) carries no
                # inline tp_iternext — recognise the thunk so the loop is found.
                if self._is_iter_maker_thunk(_t):
                    getiter_sites.append(I.address)
        if not iternext and not getiter_sites:
            return []
        loops = []
        seen = set()

        def _has_iter(lo_b, hi_b):
            if any(lo_b <= x <= hi_b for x in iternext):
                return True
            return any(lo_b <= x <= hi_b for x in getiter_sites)

        for I in ins:
            if I.mnemonic in JCC and I.operands \
                    and I.operands[0].type == cxm.X86_OP_IMM:
                T = I.operands[0].imm
                if lo <= T < I.address and T not in seen \
                        and _has_iter(T, I.address):
                    seen.add(T)
                    loops.append((T, I.address))
        # One source `for` emits several back-edges (the normal iteration plus
        # `continue`/exception retries), which would nest as phantom loops.
        # Keep only MAXIMAL ranges: drop any loop fully contained in another.
        kept = []
        for h, e in sorted(loops, key=lambda L: -(L[1] - L[0])):
            if not any(kh <= h and e <= ke for kh, ke in kept):
                kept.append((h, e))
        return sorted(kept)

    def recover_body_traces(self, func_ptr, module_constants,
                            mod_consts_base=None, runtime_aliases=None,
                            max_funcs=600, code_objects=None, infos=None,
                            va_to_qn=None):
        """Recover a FAITHFUL per-function body trace for a C-compiled module.

        Every compiled `def`/method body references its attribute, method and
        global names through RIP-relative loads into the module's mod_consts
        array, in native execution order. We BFS every function reachable from
        the module init, resolve those loads, drop the compiler machinery
        names, and return `{qualname: [name, ...]}` — the real sequence of
        names each function touches. This is faithful (it is exactly what the
        binary does), NOT reconstructed control flow, so it is rendered as a
        commented guide rather than fabricated Python. Universal for Nuitka on
        CPython 3.8-3.10 (Win64). Returns ({} traces, {} exact-bodies) when
        unavailable. When `code_objects` (the recovered native code objects,
        for parameter names) is supplied, the second dict carries EXACT,
        real-Python bodies for the provably-unambiguous functions (see
        _synth_arith_return) — actual decompiled source, not a comment.
        """
        if not func_ptr or not module_constants:
            return {}, {}
        consts = list(module_constants)
        if infos is None:
            try:
                infos = self.analyse_function_recursive(
                    func_ptr, runtime_aliases=runtime_aliases or {},
                    max_funcs=max_funcs)
            except Exception:
                return {}, {}
        elif not infos:
            return {}, {}
        if mod_consts_base is None:
            # Prefer the robust base solved by recover_code_objects for this
            # same module (call it first); fall back to the const-load estimate.
            mod_consts_base = getattr(self, '_last_mod_consts_base', None)
        if mod_consts_base is None:
            all_loads = []
            for _v, _i in infos.items():
                all_loads.extend(_i.get('const_loads', []))
            mod_consts_base, _ = self._estimate_mod_consts_base(
                all_loads, len(consts))
        if mod_consts_base is None:
            return {}, {}

        # Map a function's leaf name -> its native parameter list (for exact
        # body synthesis) and its local-variable names (co_varnames after the
        # args, for naming materialised DAG locals best-effort).
        qn_params = {}
        qn_locals = {}
        for _co in (code_objects or []):
            try:
                _nm = _co.get('name')
                _args = [str(a) for a in (_co.get('args') or [])]
                _vars = [str(a) for a in (_co.get('varnames') or [])]
            except Exception:
                continue
            if _nm:
                _leaf = str(_nm).split('.')[-1]
                qn_params.setdefault(_leaf, _args)
                qn_locals.setdefault(_leaf, _vars[len(_args):])

        def token_of(v):
            """Render one referenced constant as a faithful trace token, or
            None to drop it. Identifiers (attr/method/global names) stay bare;
            real data literals (numbers, URLs, messages, tuples) are repr'd so
            the trace carries the function's actual VALUES, not just its names.
            Compiler machinery, qualnames and filenames are dropped."""
            if isinstance(v, str):
                if not v or v in self._BODY_TRACE_MACHINERY:
                    return None
                if v.endswith(('.py', '.pyc')):
                    return None
                if re.fullmatch(r'[A-Za-z_]\w*', v):
                    return v                                  # bare identifier
                if '<' in v or '>' in v:
                    return None                               # <module>, <metaclass>
                if '.' in v and ' ' not in v and "'" not in v \
                        and re.fullmatch(r'[\w.]+', v):
                    return None                               # dotted qualname
                r = repr(v)
                return r if len(r) <= 80 else r[:77] + "...'"  # data string
            if isinstance(v, bool) or v is None:
                return None
            if isinstance(v, (int, float)):
                return repr(v)
            if isinstance(v, tuple):
                r = repr(v)
                return r if 2 < len(r) <= 80 else None
            return None

        def names_of(va, info):
            # The decoded constants blob is one module-wide sequence.  The
            # per-function RIP-relative clusters are local aliases into that
            # sequence, not independent Python constant arrays.  Keep the
            # code-object/maker-anchored module base here; estimating a new
            # base from one body's loads shifts indices into a sibling window.
            _body_mcb = mod_consts_base
            # Collect every referenced constant, recovered arithmetic operator
            # and REAL branch (with its join target), ordered by address, then
            # fold them into a nested if/else skeleton: events in
            # [branch, target) are the then-body (a child's range is capped by
            # its parent's, so an inner if can't swallow an outer else).
            events = []   # (addr, kind, payload)
            for cl in info.get('const_loads', []):
                if cl.get('section') != '.data':
                    # 3.8-3.10: mod_consts lives in .data — keep the strict filter
                    # so those emits stay byte-identical. CPython 3.11+ Nuitka
                    # places the module const array in a DIFFERENT section (e.g.
                    # .rdata), so requiring '.data' dropped EVERY const-load and
                    # produced empty traces (no bodies, no line maps). On 3.11+
                    # accept any section — the mcb-range + alignment checks below
                    # are the real, precise filter for "points into mod_consts".
                    if not getattr(self, '_pycode_is_unstable', False):
                        continue
                tva = cl.get('target_va')
                if (tva is None or _body_mcb is None or tva < _body_mcb
                        or (tva - _body_mcb) % 8):
                    continue
                idx = (tva - _body_mcb) // 8
                if not (0 <= idx < len(consts)):
                    continue
                tok = token_of(consts[idx])
                if tok is not None:
                    events.append((cl.get('va_from', 0), 'tok', tok))
            # Disassemble the body ONCE and share it with both analyses
            # (operators + branches) instead of re-disassembling per call.
            try:
                body_insns = list(self._bounded_disasm(va, max_bytes=16384))
            except Exception:
                body_insns = None
            for addr, opsym in self._recover_operators(va, insns=body_insns):
                events.append((addr, 'tok', '(%s)' % opsym))
            for addr, marker, target, else_end in self.recover_real_branches(
                    va, consts, _body_mcb, insns=body_insns):
                events.append((addr, 'if', (marker, target, else_end)))
            for header, end in self.recover_loops(va, insns=body_insns):
                events.append((header, 'loop', ('<for>', end, None)))
            # order at one address: a loop opens before its body tokens, which
            # render before the branch they feed.
            _prio = {'loop': 0, 'tok': 1, 'if': 2}
            events.sort(key=lambda e: (e[0], _prio[e[1]]))

            # Drop each comparison's OPERAND token — the constant that is loaded
            # right before the compare and already shown inside the branch marker
            # (e.g. the `'run-task'` token sitting just ahead of `<if cmp
            # 'run-task'>`). It is redundant, and when it lands at an
            # else-start it blocks elif folding (the if would no longer be the
            # first event of the else). Remove the nearest preceding contiguous
            # token whose value matches the marker's operand repr.
            def _marker_operands(marker):
                # The token may render the operand either repr'd (`'run-searcher'`,
                # for non-identifier strings / numbers) or BARE (`value`, when
                # token_of keeps identifier-shaped strings unquoted), so match
                # both forms.
                m = re.match(r"<if (?:cmp |[=!<>]+ )(.+)>$", marker)
                if not m:
                    return ()
                v = m.group(1)
                cands = {v}
                if len(v) >= 2 and v[0] in "'\"" and v[-1] == v[0]:
                    cands.add(v[1:-1])
                return cands
            drop = set()
            for k in range(len(events)):
                if events[k][1] != 'if':
                    continue
                cands = _marker_operands(events[k][2][0])
                if not cands:
                    continue
                j = k - 1
                while j >= 0 and events[j][1] == 'tok':
                    if j not in drop and events[j][2] in cands:
                        drop.add(j)
                        break
                    j -= 1
            if drop:
                events = [e for i, e in enumerate(events) if i not in drop]

            lines = []
            stack = []          # open-if join addresses (parent-capped)
            buf = []            # tokens accumulating at the current indent
            last = [None]       # last token emitted (drop consecutive dups)

            def flush():
                if not buf:
                    return
                indent = '    ' * len(stack)
                line, width = '', 84
                for t in buf:
                    piece = (', ' if line else '') + t
                    if len(indent) + len(line) + len(piece) > width and line:
                        lines.append(indent + line)
                        line = t
                    else:
                        line += piece
                if line:
                    lines.append(indent + line)
                buf.clear()

            # stack entries: [end_addr, else_end, in_else]
            for addr, kind, payload in events:
                # When the FIRST event of an else-block is itself an `if`, the
                # source was `elif`, not `else: if`. Detect & collapse: render a
                # flat `<elif ...>` at the parent indent and REUSE the same stack
                # frame (retarget it to the inner if) so the whole chain stays at
                # one level instead of marching rightward. Guard with containment
                # (`cur_if_target <= top[1]`) so a sibling if that merely follows
                # an inner block is not mis-attached as an elif.
                cur_if_target = payload[1] if kind == 'if' else None
                consumed = False
                elif_done = False
                while stack:
                    top = stack[-1]
                    if (not top[2] and top[1] is not None
                            and addr >= top[0]):
                        # then-body finished and this if has an else: switch
                        flush()
                        last[0] = None
                        if (kind == 'if' and not elif_done
                                and cur_if_target is not None
                                and cur_if_target <= top[1]):
                            marker, ntarget, nelse_end = payload
                            lines.append('    ' * (len(stack) - 1)
                                         + '<el' + marker[1:] + ':')
                            region_end = top[1]   # elif chain upper bound
                            nt = (ntarget if ntarget is not None
                                  and ntarget <= region_end else region_end)
                            nee = nelse_end
                            if nee is not None:
                                nee = min(nee, region_end)
                                if nee <= nt:
                                    nee = None
                            top[0], top[1], top[2] = nt, nee, False
                            elif_done = True
                            consumed = True
                            break
                        lines.append('    ' * (len(stack) - 1) + 'else:')
                        top[0] = top[1]      # block now runs to else_end
                        top[2] = True
                        continue
                    if addr >= top[0]:
                        flush()
                        last[0] = None
                        stack.pop()
                        continue
                    break
                if consumed:
                    continue
                if kind == 'tok':
                    if last[0] != payload:
                        buf.append(payload)
                        last[0] = payload
                else:
                    flush()
                    last[0] = None
                    marker, target, else_end = payload
                    lines.append('    ' * len(stack) + marker + ':')
                    if target and target > addr:
                        cap = stack[-1][0] if stack else None
                        t = min(target, cap) if cap is not None else target
                        ee = else_end
                        if ee is not None:
                            if cap is not None:
                                ee = min(ee, cap)
                            if ee <= t:        # else outside this range -> none
                                ee = None
                        stack.append([t, ee, False])
            flush()
            return lines

        # Build the authoritative body-VA -> qualname map via MAKE_FUNCTION
        # adjacency. A compiled method body never loads its own __qualname__
        # (that string is loaded by the CLASS body, next to the `lea` of the
        # method's function pointer), so per-body qualname inference mislabels
        # every method. Instead, for each parent function pair its `lea
        # child_body` with the nearest qualname-shaped const it loads.
        def resolve_str(va):
            if va is None or va < mod_consts_base or (va - mod_consts_base) % 8:
                return None
            i = (va - mod_consts_base) // 8
            if not (0 <= i < len(consts)):
                return None
            v = consts[i]
            return v if isinstance(v, str) else None

        va_to_qualname = {}
        for _va, info in infos.items():
            const_events = []
            for cl in info.get('const_loads', []):
                s = resolve_str(cl.get('target_va'))
                if isinstance(s, str) and s and (
                        ('.' in s and '<' not in s and not s.endswith(('.py', '.pyc')))
                        or re.fullmatch(r'[A-Za-z_]\w*', s)):
                    const_events.append((cl.get('va_from', 0), s))
            for fp in info.get('func_ptr_loads', []):
                site = fp.get('va_from', 0)
                tgt = fp.get('target_va')
                if tgt is None or tgt in va_to_qualname:
                    continue
                nearby = [(('.' not in s), abs(c - site), s)
                          for c, s in const_events if abs(c - site) <= 192]
                if nearby:
                    nearby.sort()        # dotted qualname first, then nearest
                    va_to_qualname[tgt] = nearby[0][2]
            for hint in info.get('make_function_hints', []):
                tgt = hint.get('func_va')
                for cand in hint.get('candidate_vas', []):
                    s = resolve_str(cand)
                    if isinstance(s, str) and s and (
                            '.' in s or tgt not in va_to_qualname):
                        if '.' in s or '<' in s or tgt not in va_to_qualname:
                            va_to_qualname[tgt] = s
                        break

        # CPython 3.11+: the def-site NAME is a runtime-filled mod_consts slot,
        # so the adjacency map above recovers (almost) nothing -> traces {} ->
        # no line maps, no bodies. The caller solves impl_VA -> qualname another
        # way (source-line join, _ndl_join_impl_by_line) and passes it in; fold
        # it in for the VAs adjacency missed. Gated on the PyUnstable slot so
        # 3.8-3.10 is byte-identical (there va_to_qualname is already complete and
        # setdefault adds nothing).
        if va_to_qn and getattr(self, '_pycode_is_unstable', False):
            for _v, _q in va_to_qn.items():
                if _q:
                    va_to_qualname.setdefault(_v, _q)

        traces = {}
        sources = {}    # qualname/leaf -> EXACT real-Python body (list of lines)
        synth_cands = []   # (qn, leaf, va, params, local_names, seq) for synth
        synth_seen = set()

        def offer(key, seq):
            # Several compiled functions can share a qualname (a thin wrapper
            # plus the real body); keep the RICHEST sequence, which is the
            # actual body — never the 2-3 name registration stub.
            if seq and len(seq) > len(traces.get(key, ())):
                traces[key] = seq

        for va, info in infos.items():
            # The module-entry function runs the top-level code and creates
            # every def via MAKE_FUNCTION, so it references all of them. Its
            # weak-fallback qualname is the first def it touches, which would
            # clobber that def's real body trace — skip it.
            if va == func_ptr:
                continue
            # Only trust the authoritative MAKE_FUNCTION-adjacency qualname, or
            # a STRONG (dotted) per-body inference. The weak single-ident
            # fallback mislabels helper/registration stubs onto real functions.
            qn = va_to_qualname.get(va)
            if not qn:
                cand = NuitkaCompactEmitter._infer_func_qualname(
                    info, consts, mod_consts_base)
                qn = cand if (cand and '.' in cand) else None
            if not qn or '<' in qn:
                continue
            seq = names_of(va, info)
            if not seq:
                continue
            offer(qn, seq)
            leaf = qn.split('.')[-1]
            if leaf != qn:
                offer(leaf, seq)
            # EXACT body for the provably-unambiguous arithmetic-return shape:
            # real decompiled `return <param> <op> <const>` source, not a trace.
            # GATE on the body trace being MINIMAL — a single line of just one
            # numeric const + one operator, nothing else. That proves the whole
            # body is the arithmetic return (no other call/name/branch produced
            # a token), so the value operand can only be the parameter; without
            # this gate a big function that merely contains one `local / const`
            # (e.g. a helper's `local_value / scale_factor` deep inside its body)
            # would be mis-synthesised as `return address / 1000000`.
            params = qn_params.get(leaf, [])
            if leaf not in synth_seen:
                synth_seen.add(leaf)
                synth_cands.append(
                    (qn, leaf, va, params, qn_locals.get(leaf, []), list(seq)))

        # --- EXACT real-Python body synthesis (two-pass) --------------------
        # body_sources carries actual decompiled source (not a comment trace)
        # for the functions that provably reconstruct. The call/DAG synthesiser
        # needs a MODULE-GLOBAL set of CALL_METHOD_NO_ARGS helper VAs (`mcall0`,
        # so `obj.m()` gets its `()` even when used only as a call argument), so
        # pass 1 runs every candidate just to populate that set, pass 2 then
        # reconstructs with it complete. Each emitted body is GATED: the
        # arithmetic shape needs a minimal trace; the call/DAG body must contain
        # every NAME the faithful trace recorded (coverage) — else it dropped
        # logic and we keep the trace. Never a wrong/partial body.
        # mcall0 = CALL_METHOD_NO_ARGS helper VAs (so `obj.m()` keeps its `()`).
        # Static discovery (_discover_call_helpers) identifies them by body shape;
        # pass 1 still accumulates used-as-callable ATTR sites as a supplement.
        for _qn, _leaf, _va, _params, _locals, _seq in synth_cands:
            src = None
            if (len(_seq) == 1 and re.fullmatch(
                    r'-?\d+(?:\.\d+)?, \([^)]+\)', _seq[0].strip())):
                arith = self._synth_arith_return(
                    _va, _params, consts, mod_consts_base)
                if arith:
                    src = [arith]
            if src is None:
                def _coverage_ok(_lines):
                    if not _lines:
                        return False
                    _tnames = set(re.findall(
                        r'[A-Za-z_]\w*', ' '.join(_seq)))
                    _cnames = set(re.findall(
                        r'[A-Za-z_]\w*', ' '.join(_lines)))
                    return not (_tnames - _cnames - {'self'})

                _cands = []
                try:
                    _mcall = set()
                    _cc = self._synth_call_chain(
                        _va, _params, consts, mod_consts_base,
                        mcall0=_mcall, local_names=_locals)
                    if _cc:
                        _cands.append(_cc)
                except Exception:
                    pass
                try:
                    _cr = self._synth_concat_return(_seq)
                    if _cr:
                        _cands.append(_cr)
                except Exception:
                    pass
                for _lines in _cands:
                    if _coverage_ok(_lines):
                        src = _lines
                        break
            if src:
                sources[_qn] = src
                if _leaf != _qn:
                    sources[_leaf] = src
        return traces, sources

    def render_function(self, func_ptr, module_name=None, max_bytes=8192,
                         runtime_alias_map=None,
                         module_constants=None,
                         mod_consts_base=None):
        """Produce the human-readable `.disasm.txt` content for one function.

        The real added value: when `module_constants` (the list of Python
        literals decoded from the blob for THIS module) is supplied we
        resolve every `mov/lea reg, [rip+X]` inside the `mod_consts`
        cluster into the actual Python literal. That gives a listing like

            0x1424C83AE   mov   rdi, qword ptr [rip + 0x3711cb3]
            //            = mod_consts.const_str_plain_session   // 'session'

        which is exactly what you'd see if Nuitka's original generated C
        source was compiled with debug symbols. Feeding the resulting
        .disasm.txt to a human or an LLM turns it into plain Python 1:1.
        """
        runtime_alias_map = runtime_alias_map or {}
        module_constants = module_constants or []

        info = self.analyse_function(func_ptr, max_bytes=max_bytes)

        # If the caller didn't provide the mod_consts base, estimate it
        # from this function's const loads alone. When we're processing
        # the ENTRY POINT (`module_code_X`) the loads touch every constant
        # in the struct, so this is quite reliable.
        if mod_consts_base is None:
            mod_consts_base, _count = self._estimate_mod_consts_base(
                info['const_loads'], len(module_constants))

        def resolve_const(va):
            if mod_consts_base is None or not module_constants:
                return None
            if va < mod_consts_base:
                return None
            offset = va - mod_consts_base
            if offset % 8 != 0:
                return None
            idx = offset // 8
            if 0 <= idx < len(module_constants):
                return idx, module_constants[idx]
            return None

        out = []
        out.append('=' * 72)
        out.append(f' NATIVE-CODE DISASSEMBLY  module_code_{module_name or "?"}')
        out.append('=' * 72)
        out.append(f'# Entry point VA      : 0x{func_ptr:X}')
        out.append(f'# Instructions        : {info["instruction_count"]}'
                   + (' (hit RET)' if info['reached_ret'] else ' (budget exhausted)'))
        out.append(f'# Direct calls        : {sum(1 for c in info["calls"] if c["kind"] == "internal")}')
        out.append(f'# Python C API calls  : {sum(1 for c in info["calls"] if c["kind"] == "capi")}')
        out.append(f'# Const loads         : {len(info["const_loads"])}')
        if mod_consts_base is not None:
            out.append(f'# mod_consts base VA  : 0x{mod_consts_base:X} '
                       f'(struct holds {len(module_constants)} slots)')
        out.append('')

        # --- Call summary ---
        out.append('-' * 72)
        out.append(' CALLS (in order of occurrence)')
        out.append('-' * 72)
        for c in info['calls']:
            va = c['va_from']
            if c['kind'] == 'capi':
                out.append(f'  0x{va:X}  -> {c["dll"]}!{c["name"]}')
            elif c['kind'] == 'internal':
                mod = c.get('module')
                if mod:
                    out.append(f'  0x{va:X}  -> module_code_{mod}  (0x{c["target"]:X})')
                else:
                    alias = runtime_alias_map.get(c['target'])
                    if alias:
                        out.append(f'  0x{va:X}  -> {alias}')
                    else:
                        out.append(f'  0x{va:X}  -> nuitka_internal_0x{c["target"]:X}')
            else:
                tgt = c.get('target')
                out.append(f'  0x{va:X}  -> {c["kind"]} 0x{tgt:X}'
                           if tgt else f'  0x{va:X}  -> {c["kind"]}')
        out.append('')

        # --- Constant loads with full value resolution ---
        out.append('-' * 72)
        out.append(' CONSTANT LOADS (RIP-relative, resolved to blob values)')
        out.append('-' * 72)
        if mod_consts_base is None or not module_constants:
            out.append(' (cannot resolve — mod_consts base not found or '
                       'module constants unavailable)')
            for cl in info['const_loads']:
                out.append(f'  0x{cl["va_from"]:X}  {cl["mnemonic"]} -> '
                           f'0x{cl["target_va"]:X}  [{cl["section"]}]')
        else:
            for cl in info['const_loads']:
                res = resolve_const(cl['target_va'])
                if res is None:
                    out.append(f'  0x{cl["va_from"]:X}  {cl["mnemonic"]} -> '
                               f'0x{cl["target_va"]:X}  [{cl["section"]}]  '
                               f'(outside mod_consts)')
                else:
                    idx, val = res
                    rep = repr(val)
                    if len(rep) > 100:
                        rep = rep[:97] + '...'
                    out.append(
                        f'  0x{cl["va_from"]:X}  {cl["mnemonic"]} -> '
                        f'mod_consts[{idx}]  =  {type(val).__name__}  {rep}')
        out.append('')

        # --- Annotated raw disassembly: inline every const load + call ---
        out.append('-' * 72)
        out.append(' ANNOTATED DISASSEMBLY')
        out.append(" (each `mov ..., [rip+X]` into mod_consts is inlined with")
        out.append("  the actual Python literal; every `call` shows the")
        out.append("  runtime helper alias or the IAT symbol)")
        out.append('-' * 72)

        call_by_va = {c['va_from']: c for c in info['calls']}
        const_by_va = {cl['va_from']: cl for cl in info['const_loads']}

        for va, mnem, ops in info['raw_disasm']:
            line = f'  0x{va:X}:  {mnem:<8} {ops}'

            # Inline comments
            comment_parts = []
            if va in const_by_va:
                cl = const_by_va[va]
                res = resolve_const(cl['target_va'])
                if res is not None:
                    idx, val = res
                    rep = repr(val)
                    if len(rep) > 90:
                        rep = rep[:87] + '...'
                    comment_parts.append(f'mod_consts[{idx}] = {rep}')
            if va in call_by_va:
                c = call_by_va[va]
                if c['kind'] == 'capi':
                    comment_parts.append(f'{c["dll"]}!{c["name"]}')
                elif c['kind'] == 'internal':
                    mod = c.get('module')
                    if mod:
                        comment_parts.append(f'module_code_{mod}')
                    else:
                        alias = runtime_alias_map.get(c['target'])
                        if alias:
                            comment_parts.append(alias)

            if comment_parts:
                # Pad to a stable column so comments line up
                line = f'{line:<60}  // {";  ".join(comment_parts)}'
            out.append(line)

        out.append('')
        return '\n'.join(out), info


# ---------------------------------------------------------------------------
#  NUITKA COMPACT "NBC" EMITTER — one tiny file per module for AI 1:1 rebuild
# ---------------------------------------------------------------------------

class NuitkaCompactEmitter:
    """Emit a compact `.nbc` (Nuitka ByteCode) file per module.

    The `.nbc` format is a hand-designed pseudo-bytecode tuned to feed an
    LLM so it can rebuild the original Python source 1:1. It is
    **self-sufficient**: together, the enriched `@OPS` virtual ops, the
    decoded `@CONSTS`, and the base64 `@RAW_CHUNK` carry everything an
    LLM (or a re-parser) needs to reconstruct the module literally —
    without going back to the executable.

    Per module it contains:
       * the module name + target Python version + module-table entry
       * the original constants chunk, base64 (`@RAW_CHUNK`) — re-parseable
       * the complete decoded-constants table (one per line, typed)
       * the import statements Nuitka's blob layout reveals
       * the detected internal functions (`@FUNCS_DETECTED`) and the
         full code-object inventory (`@CODE_OBJECTS`)
       * `@FUNC_PTR_MAP`: every function VA referenced by the op traces,
         bound to its qualname + frame shape (args/freevars/line) — the
         single table to resolve any `fn@0xVA` reference at a glance
       * one `@OPS <va>` block per disassembled function: an ordered
         sequence of *enriched* virtual ops where each call carries its
         live arguments (`rcx=c[..] rdx=c[..]`), each conditional jump
         carries its condition (`c[N]`, `#imm`, or `J_NULL reg`), and
         each runtime-helper call carries its alias name

    `@ASM` (raw x86-64 disassembly) is available but **off by default**:
    the enriched `@OPS` already carries its information in a denser form.
    Opt in with `--nbc-full-asm` when you want the raw disassembly too.

    Deliberately absent:
       * no JSON variant (redundant with the text form)
       * no categorised-constants tables (redundant with @CONSTS)

    Format summary (stable — treat as API):

        @MOD   <module_dotted_name>
        @VER   <python_major.minor>
        @ENTRY 0x<virtual_address_of_module_code>
        @CONSTS <count>
          0 i 100000000                       # <index> <typecode> <repr>
          1 s 'https://example.com/'
          ...
        @IMPORTS
          from X import Y
          import Z
        @FUNCS_DETECTED                       # inferred def skeletons
          convert_to_btc(chain_stats)
          ...
        @FUNC_PTR_MAP <n>                     # VA -> qualname + frame shape
          0x401000  qualname='convert_to_btc'  args=(chain_stats,)  line=12
          0x4012A0  qualname=?                 # internal target, name unknown
        @OPS <entry_va>  # qualname           # virtual bytecode from disasm
          ; frame  args=(self, address)  line=10
          L c[1]                               # 'https://example.com/'
          C r#0  ; RUNTIME_HELPER_00_x1234     # LOOKUP_ATTRIBUTE
          C capi:PyDict_SetItem  rcx=c[3] rdx=c[4] r8=c[5]   # dict[k]=v
          J_EQ c[7] L1                         # cmp == const
          J_NULL rax L2                        # error/NULL check
          RET
          :L1
          C r#4 rcx=c[9] rdx=c[10]  ; RUNTIME_HELPER_04_x5678   # print(...)
          RET

    Type codes (single character, stable):
        n None  t True  F False
        i int   f float  c complex
        s str   b bytes  B bytearray
        T tuple L list   D dict  S set P frozenset
        ? unknown

    Instructions:
        L  c[N]             LOAD_CONST from mod_consts[N]
        C  r#N              CALL to runtime-helper rank N (alias in trailing comment)
        C  helper_XXX       CALL to a less-frequent helper
        C  fn@0xAA          CALL to a module-local function at virtual address
        C  capi:NAME        CALL to a Python C-API via the IAT
        C  ... rcx=c[..]    Call args follow as reg=source (c[N]=const, #imm, g<va>=global)
        J_EQ c[N] LABEL     cmp + je with a constant (best-effort)
        J_EQ #imm LABEL     cmp + je with an immediate
        J_NULL reg LABEL    test reg,reg + je  (NULL/error check)
        J_NOTNULL reg LABEL test reg,reg + jne (non-NULL check)
        J    LABEL          unconditional jump
        RET                 return
        :LABEL              jump target
    """

    # A few type-code mappings
    _TYPE_CODE = {
        type(None):  'n', bool:       't',  # bool collapses to t/F below
        int:         'i', float:      'f', complex: 'c',
        str:         's', bytes:      'b', bytearray: 'B',
        tuple:       'T', list:       'L',
        dict:        'D', set:        'S', frozenset: 'P',
    }
    _QUALNAME_RE = re.compile(
        r'(?:[A-Za-z_][A-Za-z0-9_]*|<[^>\s]+>)'
        r'(?:\.(?:[A-Za-z_][A-Za-z0-9_]*|<[^>\s]+>))*'
    )
    _COMMON_NON_QUALNAMES = {
        'none', 'true', 'false', 'self', 'args', 'kwargs', 'main',
        'init', 'call', 'test', 'name', 'file', 'path', 'data',
        'json', 'text', 'open', 'read', 'write',
    }

    @classmethod
    def _qualname_score(cls, value, *, allow_short=False):
        """Score strings that look like Python function/class qualnames."""
        if not isinstance(value, str):
            return 0
        if not (2 <= len(value) <= 200):
            return 0
        if any(ch in value for ch in (' ', '\n', '\r', '/', '\\')):
            return 0
        if value.startswith('__') and value.endswith('__'):
            return 0
        if not cls._QUALNAME_RE.fullmatch(value):
            return 0
        low = value.lower()
        if low in cls._COMMON_NON_QUALNAMES:
            return 0
        if value.isupper():
            return 0

        tail = value.rsplit('.', 1)[-1]
        tail_plain = tail[1:-1] if tail.startswith('<') and tail.endswith('>') else tail
        if not allow_short and '.' not in value and '<' not in value:
            if not (value.startswith('_') and len(value) >= 4) and len(value) < 8:
                return 0

        score = 1
        if '<' in value:
            score += 6
        if '.' in value:
            score += 5
        if value.startswith('_') and len(value) >= 4:
            score += 2
        if len(tail_plain) >= 5 and not tail_plain.isupper():
            score += 2
        if allow_short and len(tail_plain) >= 3 and not tail_plain.isupper():
            score += 1
        if value[:1].isupper() and '.' not in value:
            score -= 2
        return max(score, 0)

    @classmethod
    def _type_code(cls, v):
        if v is None:
            return 'n'
        if v is True:
            return 't'
        if v is False:
            return 'F'
        return cls._TYPE_CODE.get(type(v), '?')

    @staticmethod
    def _short_repr(v, cap=120):
        r = repr(v)
        return r if len(r) <= cap else r[:cap - 3] + '...'

    @classmethod
    def _full_repr(cls, v):
        try:
            return repr(v)
        except Exception as e:
            return f'<repr failed: {type(v).__name__}: {e}>'

    @classmethod
    def _emit_constants(cls, constants, out, *, full=True):
        mode = 'full_repr' if full else 'compact_repr'
        out.append(f"@CONSTS {len(constants)} mode={mode}")
        for i, v in enumerate(constants):
            rep = cls._full_repr(v) if full else cls._short_repr(v)
            out.append(f"  {i} {cls._type_code(v)} {rep}")

    @classmethod
    def _emit_raw_chunk(cls, chunk_bytes, out):
        """Embed the original per-module Nuitka constants chunk.

        The decoded constants are what an LLM normally needs, but keeping
        the raw chunk in the same `.nbc` makes the file self-contained:
        another tool can re-parse it, verify our decoder, or recover a tag
        we do not yet understand without going back to the executable.
        """
        if not chunk_bytes:
            return
        chunk = bytes(chunk_bytes)
        out.append('@RAW_CHUNK')
        out.append(f'  size: {len(chunk)}')
        out.append(f'  sha256: {hashlib.sha256(chunk).hexdigest()}')
        out.append('  encoding: base64')
        b64 = base64.b64encode(chunk).decode('ascii')
        out.append('  data:')
        for i in range(0, len(b64), 120):
            out.append('    ' + b64[i:i + 120])
        out.append('')

    @staticmethod
    def _module_table_value(entry, key, default=''):
        if not entry:
            return default
        value = entry.get(key, default)
        if isinstance(value, int):
            return f'0x{value:X}' if key.endswith('ptr') or key.endswith('va') else str(value)
        if isinstance(value, (list, tuple)):
            return ','.join(str(x) for x in value)
        return str(value)

    @classmethod
    def _emit_module_table_entry(cls, module_table_entry, out):
        if not module_table_entry:
            return
        out.append('@MODULE_TABLE')
        out.append(f"  name: {module_table_entry.get('name', '')}")
        out.append(f"  func_ptr: 0x{module_table_entry.get('func_ptr', 0):X}")
        out.append(f"  flags: {','.join(module_table_entry.get('flag_names') or [])}")
        out.append(f"  bytecode_index: {module_table_entry.get('bytecode_index', -1)}")
        out.append(f"  bytecode_size: {module_table_entry.get('bytecode_size', -1)}")
        out.append('')

    @classmethod
    def _collect_code_objects(cls, constants):
        """Walk the decoded constants and return the de-duplicated list
        of CodeObject dicts (name/qualname/line/args/argcount/freevars/...).

        Shared by `_emit_code_objects`, `_build_va_to_codeobject` and the
        per-`@OPS` frame header so they all see the same set."""
        code_objects = []

        def walk(v):
            if isinstance(v, dict):
                if v.get('_type') == 'CodeObject':
                    code_objects.append(v)
                for item in v.values():
                    walk(item)
            elif isinstance(v, (tuple, list, set, frozenset)):
                for item in v:
                    walk(item)

        for c in constants:
            walk(c)

        seen = set()
        unique = []
        for co in code_objects:
            key = (
                co.get('name'),
                co.get('qualname'),
                co.get('line'),
                co.get('argcount'),
                tuple(co.get('args') or ()),
            )
            if key in seen:
                continue
            seen.add(key)
            unique.append(co)
        return unique

    @classmethod
    def _build_va_to_codeobject(cls, va_to_qualname, code_objects):
        """Map each disassembled function VA to its CodeObject.

        `va_to_qualname` (built in render() from MAKE_FUNCTION adjacency)
        tells us the qualname of each VA; the module's CodeObjects carry
        that same qualname. Joining the two binds every `@OPS 0xVA` block
        — and every `fn@0xVA` reference — to its frame shape
        (args/freevars/line), which is what an LLM needs to bind local
        names while reading the op trace."""
        if not va_to_qualname or not code_objects:
            return {}
        by_qualname = {}
        by_name = {}
        for co in code_objects:
            qn = co.get('qualname')
            nm = co.get('name')
            if qn and qn not in by_qualname:
                by_qualname[qn] = co
            if nm and nm not in by_name:
                by_name[nm] = co
        va_to_co = {}
        for va, qn in va_to_qualname.items():
            co = by_qualname.get(qn) or by_name.get(qn)
            if co is not None:
                va_to_co[va] = co
        return va_to_co

    @classmethod
    def _emit_func_ptr_map(cls, out, infos_dict, va_to_qualname,
                            va_to_codeobject):
        """Emit `@FUNC_PTR_MAP`: one line per function VA referenced by
        this module's `@OPS` blocks, bound to its qualname + frame shape.

        A consolidated table an LLM can scan once to resolve every
        `fn@0xVA` / `C r#N` reference inside the op traces, instead of
        cross-referencing scattered `@OPS` headers and `@FUNCS_DETECTED`.
        """
        if not infos_dict and not va_to_qualname:
            return
        vas = set(infos_dict or {}) | set(va_to_qualname or {})
        if not vas:
            return
        out.append(f'@FUNC_PTR_MAP {len(vas)}')
        for va in sorted(vas):
            qn = (va_to_qualname or {}).get(va)
            co = (va_to_codeobject or {}).get(va)
            parts = [f'0x{va:X}']
            parts.append(f'qualname={qn!r}' if qn else 'qualname=?')
            if co:
                args = ', '.join(str(a) for a in (co.get('args') or ()))
                parts.append(f'args=({args})')
                fv = tuple(co.get('freevars') or ())
                if fv:
                    parts.append(f'freevars={fv!r}')
                if co.get('line'):
                    parts.append(f'line={co.get("line")}')
            out.append('  ' + '  '.join(parts))
        out.append('')

    @classmethod
    def _emit_code_objects(cls, module_name, constants, out):
        unique = cls._collect_code_objects(constants)
        if not unique:
            return
        out.append(f'@CODE_OBJECTS {len(unique)}')
        for co in unique:
            args = ', '.join(str(a) for a in (co.get('args') or ()))
            flags = co.get('flags', 0)
            extras = []
            if co.get('posonly'):
                extras.append(f"posonly={co.get('posonly')}")
            if co.get('kwonly'):
                extras.append(f"kwonly={co.get('kwonly')}")
            if co.get('freevars'):
                extras.append(f"freevars={tuple(co.get('freevars'))!r}")
            if flags:
                extras.append(f"flags=0x{flags:X}")
            suffix = '  # ' + ' '.join(extras) if extras else ''
            qn = co.get('qualname') or co.get('name') or '<unknown>'
            line = co.get('line', '?')
            out.append(f"  line={line} qualname={qn!r} def {co.get('name', '<unknown>')}({args}){suffix}")
        out.append('')

    @classmethod
    def _emit_block_summary(cls, disasm_infos, runtime_aliases, out):
        if not disasm_infos:
            return
        out.append(f'@BLOCKS {len(disasm_infos)}')
        for va, info in disasm_infos.items():
            calls = info.get('calls') or []
            capi = sum(1 for c in calls if c.get('kind') == 'capi')
            internal = sum(1 for c in calls if c.get('kind') == 'internal')
            const_loads = len(info.get('const_loads') or [])
            fps = len(info.get('func_ptr_loads') or [])
            ret = 'yes' if info.get('reached_ret') else 'no'
            out.append(
                f"  0x{va:X} insns={info.get('instruction_count', 0)} "
                f"ret={ret} calls_internal={internal} calls_capi={capi} "
                f"const_loads={const_loads} func_ptr_loads={fps}"
            )
        out.append('')

    @classmethod
    def _emit_native_asm(cls, disasm_info, constants, mod_consts_base,
                         runtime_aliases, out):
        if not disasm_info:
            return

        fn_va = disasm_info.get('func_va')
        out.append(f'@ASM 0x{fn_va:X}')

        call_by_va = {c['va_from']: c for c in disasm_info.get('calls', [])}
        const_by_va = {cl['va_from']: cl for cl in disasm_info.get('const_loads', [])}
        fp_by_va = {fp['va_from']: fp for fp in disasm_info.get('func_ptr_loads', [])}

        def resolve_const(va):
            if mod_consts_base is None or not constants or va is None:
                return None
            if va < mod_consts_base:
                return None
            offset = va - mod_consts_base
            if offset % 8:
                return None
            idx = offset // 8
            if 0 <= idx < len(constants):
                return idx, constants[idx]
            return None

        important_mnems = {
            'cmp', 'test', 'ret', 'call', 'callq',
            'jmp', 'je', 'jne', 'ja', 'jae', 'jb', 'jbe', 'jg', 'jge',
            'jl', 'jle', 'jo', 'jno', 'js', 'jns',
            'add', 'sub', 'imul', 'mul', 'idiv', 'div', 'neg', 'not',
            'and', 'or', 'xor', 'shl', 'shr', 'sar', 'seta', 'setae',
            'setb', 'setbe', 'sete', 'setne', 'setg', 'setge', 'setl',
            'setle',
        }
        omitted = 0
        for va, mnem, ops in disasm_info.get('raw_disasm', []):
            comments = []
            if va in const_by_va:
                cl = const_by_va[va]
                resolved = resolve_const(cl.get('target_va'))
                if resolved is not None:
                    idx, value = resolved
                    comments.append(f'const c[{idx}]={cls._short_repr(value, cap=180)}')
                else:
                    comments.append(f"data 0x{cl.get('target_va', 0):X} [{cl.get('section', '?')}]")
            if va in fp_by_va:
                comments.append(f"func_ptr 0x{fp_by_va[va].get('target_va', 0):X}")
            if va in call_by_va:
                c = call_by_va[va]
                if c.get('kind') == 'capi':
                    comments.append(f"{c.get('dll')}!{c.get('name')}")
                elif c.get('kind') == 'internal':
                    if c.get('module'):
                        comments.append(f"module_code_{c.get('module')}")
                    else:
                        alias = runtime_aliases.get(c.get('target'))
                        comments.append(alias or f"internal_0x{c.get('target', 0):X}")
                elif c.get('target') is not None:
                    comments.append(f"{c.get('kind')} 0x{c.get('target'):X}")
                else:
                    comments.append(str(c.get('kind')))

            if not comments and mnem not in important_mnems:
                omitted += 1
                continue

            line = f'  0x{va:X}: {mnem:<8} {ops}'
            if comments:
                line += '  ; ' + ' ; '.join(comments)
            out.append(line)
        if omitted:
            out.append(f'  # omitted {omitted} low-signal native instruction(s)')
        out.append('')

    # Names that look like module candidates but are actually built-in
    # method names, built-in functions, or common variable names that
    # Nuitka stores as constants adjacent to varname tuples.  A string
    # matching any of these must never be treated as an import source.
    _NOT_A_MODULE = frozenset({
        # str methods
        'strip', 'lstrip', 'rstrip', 'split', 'rsplit', 'splitlines',
        'join', 'find', 'rfind', 'index', 'rindex', 'count', 'replace',
        'startswith', 'endswith', 'encode', 'decode', 'format',
        'format_map', 'upper', 'lower', 'title', 'capitalize', 'swapcase',
        'center', 'ljust', 'rjust', 'zfill', 'expandtabs',
        'isalpha', 'isdigit', 'isalnum', 'isspace', 'islower', 'isupper',
        'istitle', 'isprintable', 'isidentifier', 'isnumeric',
        'removeprefix', 'removesuffix', 'partition', 'rpartition',
        # list / dict / set methods
        'append', 'extend', 'insert', 'remove', 'pop', 'clear', 'copy',
        'sort', 'reverse', 'index', 'count',
        'keys', 'values', 'items', 'get', 'update', 'setdefault',
        'add', 'discard', 'difference', 'intersection', 'union',
        # built-in functions
        'len', 'str', 'int', 'float', 'bool', 'list', 'dict', 'set',
        'tuple', 'type', 'print', 'repr', 'sorted', 'reversed',
        'enumerate', 'zip', 'map', 'filter', 'any', 'all',
        'min', 'max', 'sum', 'abs', 'round', 'divmod', 'pow',
        'isinstance', 'issubclass', 'getattr', 'setattr', 'hasattr',
        'delattr', 'callable', 'hash', 'id', 'iter', 'next',
        'open', 'input', 'vars', 'dir', 'help', 'exec', 'eval',
        'compile', 'globals', 'locals', 'chr', 'ord', 'hex', 'oct', 'bin',
        'range', 'slice', 'object', 'super', 'property', 'staticmethod',
        'classmethod', 'bytes', 'bytearray', 'memoryview', 'complex',
        'frozenset', 'format', 'vars', 'breakpoint', 'reload',
        # common variable / attribute names that appear as constants
        'convert', 'squeeze', 'reshape', 'flatten', 'transpose',
        'split', 'merge', 'concat', 'apply', 'transform', 'fit',
        'predict', 'run', 'start', 'stop', 'close', 'open', 'read',
        'write', 'send', 'recv', 'connect', 'bind', 'listen', 'accept',
        'getenv', 'environ', 'getcwd', 'chdir', 'listdir', 'makedirs',
        'remove', 'rename', 'walk', 'glob', 'expanduser', 'expandvars',
        'basename', 'dirname', 'exists', 'isfile', 'isdir', 'join',
        'splitext', 'abspath', 'realpath', 'normpath',
        'search', 'match', 'fullmatch', 'findall', 'finditer', 'sub',
        'subn', 'compile', 'escape', 'purge',
        'dumps', 'loads', 'dump', 'load',
        'sleep', 'time', 'clock', 'monotonic', 'perf_counter',
        'strftime', 'strptime', 'now', 'today', 'utcnow', 'fromtimestamp',
        'flush', 'seek', 'tell', 'truncate', 'fileno', 'readable',
        'writable', 'seekable', 'readline', 'readlines', 'writelines',
        'kill', 'signal', 'wait', 'poll', 'communicate', 'terminate',
        'lower', 'upper', 'get', 'set', 'delete', 'head', 'post', 'put',
        'patch', 'request', 'response', 'content', 'text', 'json',
        'headers', 'cookies', 'params', 'data', 'files', 'auth',
        'timeout', 'verify', 'allow_redirects', 'stream', 'proxies',
        'raise_for_status', 'status_code', 'url', 'encoding',
        'info', 'warn', 'error', 'debug', 'critical', 'exception',
        'emit', 'handle', 'filter', 'addHandler', 'setLevel',
        # numpy/array shortcuts
        'float32', 'float64', 'int32', 'int64', 'uint8', 'uint16',
        'zeros', 'ones', 'array', 'arange', 'linspace', 'reshape',
        'dtype', 'shape', 'ndim', 'size', 'T', 'argmax', 'argmin',
        # misc single-word false positives
        'true', 'false', 'null', 'none', 'undefined',
        'ok', 'err', 'error', 'result', 'value', 'values',
        'key', 'keys', 'name', 'names', 'label', 'labels',
        'node', 'nodes', 'edge', 'edges', 'path', 'paths',
        'w', 'h', 'x', 'y', 'z', 'r', 'g', 'b', 'a',
        'i', 'j', 'k', 'n', 'm', 's', 't', 'f', 'c', 'p', 'q',
        'src', 'dst', 'buf', 'msg', 'log', 'out', 'inp', 'tmp',
        'idx', 'pos', 'off', 'end', 'cur', 'prev', 'next', 'last',
        # Qt-specific
        'setObjectName', 'setGeometry', 'setWindowTitle', 'setStyleSheet',
        'setEnabled', 'setVisible', 'setChecked', 'setCurrentIndex',
        'setCurrentText', 'setText', 'setPlaceholderText', 'setMaxLength',
        'setMinimumWidth', 'setMinimumSize', 'setDefault', 'setFocus',
        'setProperty', 'setAlignment', 'setTextAlignment', 'setColumnStretch',
        'setCursor', 'setDisplayFormat', 'addWidget', 'addItem',
        'addSeparator', 'addStretch', 'setLayout',
        'clicked', 'connect', 'emit', 'disconnect',
        'show', 'hide', 'close', 'exec', 'move', 'resize',
        # Common method / builtin names mistaken for modules
        'toString', 'toJson', 'fromJson', 'toDict', 'fromDict',
        'getenv', 'environ', 'getattr', 'setattr',
    })

    @classmethod
    def _emit_imports(cls, module_name, constants, out):
        """Liberal import detection specifically for the .nbc output.

        Matches `str 'x'` immediately followed by `tuple('A','B',...)` as
        `from x import A, B`.  A comprehensive blacklist (_NOT_A_MODULE)
        filters out built-in method names, built-in functions, Qt widget
        methods, and common variable names that Nuitka stores as constants
        adjacent to varname tuples.  Without this filter, large modules like
        __main__ generate hundreds of false `from strip import X` lines.
        """
        lines = []
        used = set()
        n = len(constants)
        for i, c in enumerate(constants):
            if not isinstance(c, str):
                continue
            if len(c) < 2 or len(c) > 80:
                continue
            if c.endswith(('.py', '.pyc')):
                continue
            if c.startswith('__') and c.endswith('__'):
                continue
            # Must be a plain dotted module identifier (all lowercase ok, or
            # package.Module style — but REJECT Class.method qualnames).
            if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*', c):
                continue
            parts = c.split('.')
            if parts[0][:1].isupper():
                continue  # Class.method
            # Reject known non-module names (methods, builtins, variables).
            if parts[0] in cls._NOT_A_MODULE:
                continue
            # Single-word all-lowercase names that are not known stdlib/popular
            # packages are highly likely to be variable names, not modules.
            # Require at least one dot OR membership in a known-packages set
            # OR starting underscore (internal module like _thread) to pass
            # without a dot.
            if len(parts) == 1 and not c.startswith('_'):
                _KNOWN_ROOTS = {
                    'subprocess', 're', 'os', 'sys', 'io', 'abc', 'ast',
                    'asyncio', 'base64', 'binascii', 'builtins', 'calendar',
                    'cmath', 'codecs', 'collections', 'concurrent', 'configparser',
                    'contextlib', 'copy', 'copyreg', 'csv', 'ctypes',
                    'dataclasses', 'datetime', 'decimal', 'difflib', 'dis',
                    'email', 'enum', 'errno', 'fileinput', 'fnmatch',
                    'fractions', 'ftplib', 'functools', 'gc', 'getopt',
                    'getpass', 'glob', 'gzip', 'hashlib', 'heapq', 'hmac',
                    'html', 'http', 'imaplib', 'importlib', 'inspect',
                    'ipaddress', 'itertools', 'json', 'keyword', 'linecache',
                    'locale', 'logging', 'lzma', 'marshal', 'math',
                    'mimetypes', 'multiprocessing', 'numbers', 'operator',
                    'optparse', 'os', 'pathlib', 'pickle', 'platform',
                    'pprint', 'profile', 'pstats', 'pty', 'queue', 'random',
                    'shlex', 'shutil', 'signal', 'site', 'socket', 'socketserver',
                    'sqlite3', 'ssl', 'stat', 'statistics', 'string',
                    'struct', 'subprocess', 'sys', 'sysconfig', 'tarfile',
                    'tempfile', 'threading', 'time', 'timeit', 'tkinter',
                    'tomllib', 'traceback', 'tracemalloc', 'types', 'typing',
                    'unicodedata', 'unittest', 'urllib', 'uuid', 'warnings',
                    'weakref', 'xml', 'xmlrpc', 'zipfile', 'zipimport', 'zlib',
                    # popular third-party
                    'requests', 'httpx', 'aiohttp', 'flask', 'django',
                    'fastapi', 'starlette', 'pydantic', 'attrs', 'click',
                    'celery', 'redis', 'pymongo', 'sqlalchemy', 'alembic',
                    'numpy', 'pandas', 'scipy', 'matplotlib', 'sklearn',
                    'tensorflow', 'torch', 'keras', 'cv2', 'PIL', 'onnxruntime',
                    'psutil', 'paramiko', 'fabric', 'ansible', 'boto3',
                    'selenium', 'seleniumbase', 'playwright', 'pyppeteer',
                    'bs4', 'lxml', 'scrapy', 'mechanize',
                    'cryptography', 'nacl', 'bcrypt', 'jwt', 'passlib',
                    'PyQt5', 'PyQt6', 'PySide2', 'PySide6', 'PyGTK', 'wx',
                    'pynput', 'keyboard', 'mouse', 'pyautogui', 'pygetwindow',
                    'psycopg2', 'pymysql', 'aiomysql', 'aiosqlite',
                    'colorama', 'rich', 'tabulate', 'tqdm', 'loguru',
                    'yaml', 'toml', 'dotenv', 'environs',
                    'websocket', 'websockets', 'socketio',
                    'win32api', 'win32con', 'win32gui', 'winreg', 'ctypes',
                    'pefile', 'capstone', 'keystone', 'unicorn',
                    'tblib', 'dill', 'cloudpickle',
                }
                if c not in _KNOWN_ROOTS:
                    continue
            # Expect next const to be a tuple of idents (= the imported names)
            nxt = constants[i + 1] if i + 1 < n else None
            if (isinstance(nxt, tuple) and nxt
                    and all(isinstance(x, str) and
                            re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', x)
                            for x in nxt)):
                # Strip dunder names from the import list
                names = [x for x in nxt if not x.startswith('__')]
                if not names:
                    continue
                key = f"from {c} import {','.join(sorted(names))}"
                if key in used:
                    continue
                used.add(key)
                lines.append(f"from {c} import {', '.join(names)}")
        if not lines:
            return
        out.append('@IMPORTS')
        for line in lines:
            out.append('  ' + line)

    @classmethod
    def _emit_funcs_detected(cls, module_name, constants, out):
        """Use the same heuristic function-signature inference as the
        C-source rebuilder, filtered for clean idents."""
        inferred = NuitkaCSourceRebuilder.infer_functions_from_constants(
            list(constants))
        if not inferred:
            return
        out.append('@FUNCS_DETECTED')
        emitted = 0
        max_funcs = 300
        for fn in inferred:
            if emitted >= max_funcs:
                break
            name = fn.get('name', '')
            if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name or ''):
                continue
            args = fn.get('args') or []
            args_str = ', '.join(str(a) for a in args)
            out.append(f"  {name}({args_str})")
            emitted += 1
        if len(inferred) > emitted:
            out.append(f"  # ... {len(inferred) - emitted} more inferred "
                       f"signature candidate(s) omitted")

    @classmethod
    def _emit_forensics(cls, constants, va_to_qualname, out):
        """Emit @FORENSICS sections for qualnames with no @OPS block.

        After the BFS disassembler has done its best, some `def`
        qualnames still appear in `mod_consts` without a matching
        `@OPS 0xVA  # qualname` block. Typical reasons:

          * **Tk/Qt callbacks** bound via `trace_add`, `bind`, or
            `signal.connect(...)` — no direct callsite exists in the
            binary, so the BFS never reaches them.
          * **Inlined helpers** that Nuitka merged into the caller.
          * **Dead code** (unused methods the compiler could have
            dropped but kept the qualname string for reflection).
          * **BFS cap** — the `max_funcs` limit cut the traversal
            short before reaching them.

        For each such orphan qualname we give an LLM enough CONTEXT
        to infer plausible behaviour without fabricating:

          * the mod_consts indices of its qualname + short name;
          * the ~12 constants ADJACENT to it in the constants table
            (Nuitka clusters a function's literals near its qualname);
          * any string anywhere in `mod_consts` that mentions the
            function's short name (error messages, dict keys, log
            formats, debug prints) — these pin down likely behaviour.

        Format:

            @FORENSICS
            # qualnames present in @CONSTS but not in @OPS — constants
            # adjacent to each give forensic evidence for the body.

            @NO_OPS <qualname>
              qualname_idx: <i>   name_idx: <j>
              adjacent:
                c[i-6] <type> <repr>
                ...
              mentions:
                c[42] s 'error in <qualname>: ...'
                c[99] s 'log: <qualname> called with ...'
        """
        if not constants:
            return

        # Collect all qualname-shaped strings in @CONSTS, with their
        # indices. A qualname looks like `foo`, `Foo.bar`,
        # `mod.Foo.bar.<locals>.baz`, `<lambda>`, `<genexpr>`.
        all_qualnames = {}   # qualname -> first index in mod_consts
        for i, v in enumerate(constants):
            if cls._qualname_score(v, allow_short=False) <= 0:
                continue
            # Python-function naming heuristics — reject anything too
            # generic to plausibly be a function qualname:
            #   * dotted names (ClassName.method)   -> strong candidate
            #   * angle brackets (<lambda> etc.)    -> strong candidate
            #   * starts with '_' and len >= 4      -> likely private fn
            #   * len >= 8 + lowercase              -> long identifier,
            #                                          likely a function
            #   * otherwise (short word like 'foo') -> reject
            if v not in all_qualnames:
                all_qualnames[v] = i

        # Remove qualnames that already have an @OPS block (labeled
        # via va_to_qualname or matched by a block's header suffix).
        already_labeled = set((va_to_qualname or {}).values())
        orphans = [(q, i) for q, i in all_qualnames.items()
                   if q not in already_labeled]
        if not orphans:
            return

        # Sort by mod_consts index (stable, reproducible)
        orphans.sort(key=lambda t: t[1])

        # Precompute: for each qualname, find the SHORT name (the part
        # after the last `.`) — we use it to search for mention
        # strings elsewhere in constants.
        def short_name(q):
            tail = q.rsplit('.', 1)[-1]
            # Drop angle-bracket wrappers: '<lambda>' -> 'lambda'
            if tail.startswith('<') and tail.endswith('>'):
                tail = tail[1:-1]
            return tail

        # Precompute: index of mentions for efficiency (scan once)
        # mentions[short_name] = [(idx, const_value), ...]
        mentions_by_short = {}
        shorts = {short_name(q) for q, _ in orphans}
        # Filter out very short or common shorts that would match too much
        shorts = {s for s in shorts
                  if len(s) >= 4 and s.lower() not in
                  ('init', 'call', 'main', 'test', 'self', 'args')}
        if shorts:
            for i, v in enumerate(constants):
                if not isinstance(v, str) or len(v) < 4:
                    continue
                # Only long-ish strings have room to mention a function
                if len(v) > 500:
                    continue
                for s in shorts:
                    if s in v and v != s:
                        mentions_by_short.setdefault(s, []).append((i, v))
                        break   # don't double-record

        # Emit header
        out.append(f'@FORENSICS {len(orphans)}')
        out.append('# Qualnames in @CONSTS without a matching @OPS block.')
        out.append('# Each block lists adjacent mod_consts + mentions.')
        out.append('# Use this as evidence for the function\'s probable')
        out.append('# behaviour — do NOT fabricate anything beyond what')
        out.append('# these constants plainly support.')
        out.append('')

        MAX_BLOCKS = 400      # cap so we don't explode huge modules
        ADJ_WINDOW = 6        # ±6 slots around the qualname
        MAX_MENTIONS = 12     # per function

        for qname, qidx in orphans[:MAX_BLOCKS]:
            short = short_name(qname)
            # The short-name index is usually qidx-1 (Nuitka emits
            # (short_name, qualname) pairs); search the ±4 window.
            short_idx = None
            for off in (-1, 1, -2, 2, -3, 3, -4, 4):
                j = qidx + off
                if 0 <= j < len(constants):
                    if constants[j] == short:
                        short_idx = j
                        break

            out.append(f'@NO_OPS {qname}')
            hdr = f'  qualname_idx: {qidx}'
            if short_idx is not None:
                hdr += f'   name_idx: {short_idx}'
            out.append(hdr)

            # Adjacent constants
            out.append('  adjacent:')
            lo = max(0, qidx - ADJ_WINDOW)
            hi = min(len(constants), qidx + ADJ_WINDOW + 1)
            for j in range(lo, hi):
                if j == qidx:
                    marker = ' <-- qualname'
                elif j == short_idx:
                    marker = ' <-- name'
                else:
                    marker = ''
                v = constants[j]
                tcode = cls._type_code(v)
                r = cls._short_repr(v, cap=100)
                out.append(f'    c[{j}] {tcode} {r}{marker}')

            # Mentions elsewhere in constants
            mlist = mentions_by_short.get(short, [])
            # De-dup identical strings, keep up to MAX_MENTIONS
            seen_strs = set()
            distinct_mentions = []
            for i, v in mlist:
                if v in seen_strs:
                    continue
                seen_strs.add(v)
                # Skip mentions that ARE the qualname itself or
                # adjacent hits already covered above.
                if i == qidx or i == short_idx:
                    continue
                if lo <= i < hi:
                    continue
                distinct_mentions.append((i, v))
                if len(distinct_mentions) >= MAX_MENTIONS:
                    break
            if distinct_mentions:
                out.append('  mentions:')
                for i, v in distinct_mentions:
                    tcode = cls._type_code(v)
                    r = cls._short_repr(v, cap=100)
                    out.append(f'    c[{i}] {tcode} {r}')
            out.append('')

        if len(orphans) > MAX_BLOCKS:
            out.append(f'# ... {len(orphans) - MAX_BLOCKS} more orphan '
                       f'qualnames omitted (MAX_BLOCKS cap).')
            out.append('')

    @classmethod
    def _emit_virtual_ops(cls, disasm_info, constants, mod_consts_base,
                           runtime_aliases, out, va_to_qualname=None,
                           suppress_fallback_label=False,
                           va_to_codeobject=None):
        """Translate the native disassembly into one-line virtual ops.

        Every `mov reg, [rip+X]` into mod_consts becomes `L c[N]`.
        Every `call` becomes `C <target>`. Every `ret` becomes `RET`.
        Every `cmp reg, imm`/`je` pair becomes `J_EQ c[...] L<N>`.
        Other instructions (arith, mov between regs, stack ops) are
        summarised as they contribute little to source recovery.

        This is a linear view, NOT a true decompilation — but together
        with the constants table and the runtime-helper inventory it's
        enough for an LLM to produce a 1:1 Python translation.

        `va_to_qualname` (optional) is an authoritative map built by
        `render()` from the `make_function_hints` of ALL disassembled
        functions. It's the accurate source for the `# qualname` label
        because the qualname-string const is loaded by the PARENT
        function (as a MAKE_FUNCTION argument), not by the child body.
        """
        if not disasm_info:
            return
        fn_va = disasm_info['func_va']
        # Preferred: authoritative MAKE_FUNCTION-adjacency qualname.
        qualname = None
        if va_to_qualname:
            qualname = va_to_qualname.get(fn_va)
        # Fallback: per-block heuristic (less accurate, noisy for the
        # module entry — but still useful if the parent block was never
        # reached, e.g. for standalone test runs on a subset).
        # Skipped for blocks whose nature precludes a qualname (the
        # module entry in particular: it is the top-level code, not a
        # `def`).
        if not qualname and not suppress_fallback_label:
            qualname = cls._infer_func_qualname(disasm_info, constants,
                                                 mod_consts_base)
        if qualname:
            out.append(f'@OPS 0x{fn_va:X}  # {qualname}')
        else:
            out.append(f'@OPS 0x{fn_va:X}')

        # Per-function code-object header (args/freevars/line) when this
        # VA resolves to a CodeObject via the qualname join built in
        # render().  Gives the LLM the function's frame shape inline with
        # its op trace so it can bind local names while reading @OPS.
        co = (va_to_codeobject or {}).get(fn_va)
        if co:
            co_args = ', '.join(str(a) for a in (co.get('args') or ()))
            co_fv = tuple(co.get('freevars') or ())
            parts = [f'args=({co_args})']
            if co_fv:
                parts.append(f'freevars={co_fv!r}')
            if co.get('line'):
                parts.append(f'line={co.get("line")}')
            extras = []
            if co.get('posonly'):
                extras.append(f'posonly={co.get("posonly")}')
            if co.get('kwonly'):
                extras.append(f'kwonly={co.get("kwonly")}')
            if extras:
                parts.append(' '.join(extras))
            out.append(f'  ; frame  ' + '  '.join(parts))

        call_by_va = {c['va_from']: c for c in disasm_info['calls']}
        const_by_va = {cl['va_from']: cl for cl in disasm_info['const_loads']}

        def resolve_const(va):
            if mod_consts_base is None or not constants:
                return None
            if va < mod_consts_base:
                return None
            offset = va - mod_consts_base
            if offset % 8:
                return None
            idx = offset // 8
            if 0 <= idx < len(constants):
                return idx
            return None

        # Build a label map for jump targets first
        label_map = {}   # VA -> label id
        ops_raw = []     # ( kind, data, va, extra )

        # ---- register-state arg tracking ------------------------------
        # Nuitka's x64 codegen loads each call's arguments (and the arg
        # count for CALL_FUNCTION_WITH_ARGSn) into the ABI arg registers
        # immediately before the `call`.  We track the most-recent write
        # to each register so a call line can carry its live arguments
        # (`C capi:PyDict_SetItem rcx=c[..] rdx=c[..] r8=c[..]`) instead
        # of an opaque `C capi:PyDict_SetItem` that hides the operands.
        _REG_ALIASES = {
            'al': 'rax', 'ax': 'rax', 'eax': 'rax', 'rax': 'rax',
            'cl': 'rcx', 'cx': 'rcx', 'ecx': 'rcx', 'rcx': 'rcx',
            'dl': 'rdx', 'dx': 'rdx', 'edx': 'rdx', 'rdx': 'rdx',
            'sil': 'rsi', 'si': 'rsi', 'esi': 'rsi', 'rsi': 'rsi',
            'dil': 'rdi', 'di': 'rdi', 'edi': 'rdi', 'rdi': 'rdi',
            'r8b': 'r8', 'r8w': 'r8', 'r8d': 'r8', 'r8': 'r8',
            'r9b': 'r9', 'r9w': 'r9', 'r9d': 'r9', 'r9': 'r9',
            'bl': 'rbx', 'bx': 'rbx', 'ebx': 'rbx', 'rbx': 'rbx',
            'spl': 'rsp', 'sp': 'rsp', 'esp': 'rsp', 'rsp': 'rsp',
            'bpl': 'rbp', 'bp': 'rbp', 'ebp': 'rbp', 'rbp': 'rbp',
        }
        _ARG_REGS = ('rcx', 'rdx', 'r8', 'r9', 'rax', 'rbx')
        _IMM_RE = re.compile(r'^-?(0x[0-9a-fA-F]+|0o[0-7]+|\d+)$')

        def _norm_reg(tok):
            return _REG_ALIASES.get(tok.strip()) if tok else None

        def _mov_dest(ops):
            # 'rcx, qword ptr [rip + 0x..]' -> 'rcx'
            head = ops.split(',', 1)[0].strip()
            return head.split()[-1] if head else ''

        reg_state = {}                  # canonical reg -> ('const',idx)|('imm',v)|('global',va)|('other',)
        pending_cmp = None              # ('const',idx)|('imm',v)|('null',reg)
        pending_cmp_va = None

        def _snapshot_args():
            snap = []
            for r in _ARG_REGS:
                src = reg_state.get(r)
                if not src:
                    continue
                if src[0] == 'const':
                    snap.append((r, ('c', src[1])))
                elif src[0] == 'imm':
                    snap.append((r, ('#', src[1])))
                elif src[0] == 'global':
                    snap.append((r, ('g', src[1])))
            return snap

        for va, mnem, ops in disasm_info['raw_disasm']:
            if va in const_by_va:
                cl = const_by_va[va]
                idx = resolve_const(cl['target_va'])
                dest = _norm_reg(_mov_dest(ops))
                if dest:
                    if idx is not None:
                        reg_state[dest] = ('const', idx)
                    else:
                        reg_state[dest] = ('global', cl.get('target_va'))
                if idx is not None:
                    ops_raw.append(('L', idx, va, None))
                # else: a .data/global load — tracked above, not emitted as L
            elif va in call_by_va:
                pending_cmp = None
                c = call_by_va[va]
                snap = _snapshot_args()
                # The call consumes + clobbers the arg registers.
                for r in _ARG_REGS:
                    reg_state.pop(r, None)
                if c['kind'] == 'capi':
                    ops_raw.append(('C', f'capi:{c["name"]}', va, snap))
                elif c['kind'] == 'internal':
                    mod = c.get('module')
                    alias = runtime_aliases.get(c['target'])
                    if mod:
                        ops_raw.append(('C', f'module_code_{mod}', va,
                                        (snap, alias)))
                    elif alias and alias.startswith('RUNTIME_HELPER_'):
                        try:
                            rank = str(int(alias.split('_')[2]))
                        except Exception:
                            rank = alias.split('_')[2]
                        ops_raw.append(('C', f'r#{rank}', va, (snap, alias)))
                    elif alias and alias.startswith('helper_'):
                        ops_raw.append(('C', alias, va, (snap, alias)))
                    else:
                        tgt_va = c['target']
                        ops_raw.append(('C', f'fn@0x{tgt_va:X}', va,
                                        (snap, alias)))
            elif mnem == 'mov':
                pending_cmp = None
                dest = _norm_reg(_mov_dest(ops))
                if dest:
                    src_part = ops.split(',', 1)[1].strip() if ',' in ops else ''
                    last = src_part.split()[-1] if src_part else ''
                    m = _IMM_RE.match(last)
                    src_reg = _norm_reg(last)
                    if m:
                        try:
                            reg_state[dest] = ('imm', int(last, 0))
                        except ValueError:
                            reg_state[dest] = ('other',)
                    elif src_reg:
                        reg_state[dest] = reg_state.get(src_reg, ('other',))
                    else:
                        reg_state[dest] = ('other',)
            elif mnem == 'xor':
                pending_cmp = None
                parts = [p.strip() for p in ops.split(',')]
                p0 = _norm_reg(parts[0]) if parts else None
                p1 = _norm_reg(parts[1]) if len(parts) > 1 else None
                if p0 and p0 == p1:
                    reg_state[p0] = ('imm', 0)
                elif p0:
                    reg_state[p0] = ('other',)
            elif mnem in ('cmp', 'test'):
                parts = [p.strip() for p in ops.split(',')]
                last = parts[-1].split()[-1] if parts else ''
                r1 = _norm_reg(parts[0]) if parts else None
                r2 = _norm_reg(parts[1]) if len(parts) > 1 else None
                m = _IMM_RE.match(last)
                if mnem == 'cmp':
                    if m:
                        try:
                            pending_cmp = ('imm', int(last, 0))
                            pending_cmp_va = va
                        except ValueError:
                            pending_cmp = None
                    elif r1 and r2:
                        s1 = reg_state.get(r1)
                        s2 = reg_state.get(r2)
                        if s1 and s1[0] == 'const':
                            pending_cmp = ('const', s1[1]); pending_cmp_va = va
                        elif s2 and s2[0] == 'const':
                            pending_cmp = ('const', s2[1]); pending_cmp_va = va
                        else:
                            pending_cmp = None
                    else:
                        pending_cmp = None
                else:  # test
                    if r1 and r1 == r2:
                        pending_cmp = ('null', r1); pending_cmp_va = va
                    else:
                        pending_cmp = None
            elif mnem == 'je' or mnem == 'jne':
                try:
                    target = int(ops.split()[-1], 0)
                    label_map.setdefault(target, len(label_map) + 1)
                    cond = None
                    if (pending_cmp is not None
                            and pending_cmp_va is not None
                            and va - pending_cmp_va <= 64):
                        cond = pending_cmp
                    ops_raw.append(('Jc', (mnem, cond, target), va, None))
                    pending_cmp = None
                except Exception:
                    pass
            elif mnem == 'jmp':
                pending_cmp = None
                try:
                    target = int(ops.split()[-1], 0)
                    label_map.setdefault(target, len(label_map) + 1)
                    ops_raw.append(('J', target, va, None))
                except Exception:
                    pass
            elif mnem == 'ret':
                ops_raw.append(('RET', None, va, None))
            else:
                # Any other instruction that writes a tracked register
                # invalidates that register's tracked source (conservative:
                # we lose precision rather than misreport a stale value).
                head = ops.split(',', 1)[0].strip()
                if head:
                    dest = _norm_reg(head.split()[-1])
                    if dest in _ARG_REGS:
                        reg_state[dest] = ('other',)

        # Inline-resolve a constant index to a short readable form, e.g.
        # `c[1]='FromSeed'`, so the op trace reads as the function's actual
        # logic (LOAD name / GETATTR / CALL) without cross-referencing @CONSTS.
        def fmt_const(idx):
            if idx is None or not (0 <= idx < len(constants)):
                return f'c[{idx}]'
            v = constants[idx]
            if isinstance(v, str):
                s = v if len(v) <= 40 else v[:40] + '…'
                return f"c[{idx}]={s!r}"
            if isinstance(v, (int, float, bool)) or v is None:
                return f'c[{idx}]={v!r}'
            if isinstance(v, tuple):
                return f'c[{idx}]=<tuple{len(v)}>'
            return f'c[{idx}]'

        def fmt_arg(src):
            tag, val = src
            if tag == 'c':
                return fmt_const(val)
            if tag == '#':
                return f'#{val}'
            if tag == 'g':
                return f'g<0x{val:X}>' if isinstance(val, int) else 'g<?>'
            return '?'

        # Second pass: emit, injecting ":L<n>" when a label target is reached.
        seen_labels = set()
        for entry in ops_raw:
            kind, data, va = entry[0], entry[1], entry[2]
            extra = entry[3] if len(entry) > 3 else None
            if va in label_map and va not in seen_labels:
                out.append(f'  :L{label_map[va]}')
                seen_labels.add(va)
            if kind == 'L':
                out.append(f'  L  {fmt_const(data)}')
            elif kind == 'C':
                snap = None
                alias = None
                if isinstance(extra, tuple) and len(extra) == 2 \
                        and isinstance(extra[0], list):
                    snap, alias = extra
                elif isinstance(extra, list):
                    snap = extra
                line = f'  C  {data}'
                if snap:
                    line += '  ' + ' '.join(
                        f'{r}={fmt_arg(s)}' for r, s in snap)
                if alias:
                    line += f'  ; {alias}'
                out.append(line)
            elif kind == 'Jc':
                jmnem, cond, tgt = data
                lbl = f'L{label_map.get(tgt, "?")}'
                op = 'J_EQ' if jmnem == 'je' else 'J_NE'
                if cond is None:
                    out.append(f'  {op} ? {lbl}')
                elif cond[0] == 'const':
                    out.append(f'  {op} {fmt_const(cond[1])} {lbl}')
                elif cond[0] == 'imm':
                    out.append(f'  {op} #{cond[1]} {lbl}')
                elif cond[0] == 'null':
                    if jmnem == 'je':
                        out.append(f'  J_NULL {cond[1]} {lbl}')
                    else:
                        out.append(f'  J_NOTNULL {cond[1]} {lbl}')
            elif kind == 'J':
                lbl = f'L{label_map.get(data, "?")}'
                out.append(f'  J    {lbl}')
            elif kind == 'RET':
                out.append(f'  RET')

    @classmethod
    def _infer_func_qualname(cls, info, constants, mod_consts_base):
        """Identify a compiled function by its Python qualname.

        Nuitka emits the `__qualname__` assignment near the top of every
        compiled function body — it's materialised from `mod_consts` like
        any other string literal. We walk the first few RIP-relative
        loads into `mod_consts` and return the first string that looks
        like a qualname (`ClassName.method`, `func_name`, `<listcomp>`,
        etc.). The LLM can then associate each `@OPS` block with its
        `@FUNCS_DETECTED` signature.
        """
        if not info or not constants or mod_consts_base is None:
            return None
        # Collect every qualname-shaped string this function references
        # via mod_consts, then rank them. Nuitka emits the `__qualname__`
        # assignment via one of those loads, but the function body may
        # also reference other function names (as dict keys, as bound
        # method lookups, etc.). A string is a "strong" qualname
        # candidate if it contains `.` or `<` (class method, nested
        # scope, lambda/listcomp/genexpr) — those patterns are unique
        # to qualnames and never appear in the random string literals
        # the function happens to pass around. Only fall back to
        # single-word identifiers if no strong candidate exists.
        strong = []      # dotted / angle-bracketed qualnames
        weak = []        # bare identifiers (less confident)
        seen_strs = set()
        for cl in info.get('const_loads', []):
            if cl.get('section') != '.data':
                continue
            target = cl.get('target_va')
            if target is None or target < mod_consts_base:
                continue
            offset = target - mod_consts_base
            if offset % 8:
                continue
            idx = offset // 8
            if not (0 <= idx < len(constants)):
                continue
            v = constants[idx]
            if not isinstance(v, str) or v in seen_strs:
                continue
            seen_strs.add(v)
            if cls._qualname_score(v, allow_short=True) <= 0:
                continue
            # Strong candidates have a dot or an angle bracket —
            # unambiguously a qualname.
            if '.' in v or '<' in v:
                strong.append(v)
            else:
                # Skip all-uppercase short bare names (more likely
                # dict keys / enum constants than function qualnames).
                if len(v) >= 3 and not v.isupper():
                    weak.append(v)
        # Prefer the FIRST strong candidate — that's the load Nuitka
        # emits for `__qualname__`. Fall back to the first weak one
        # only if no strong candidate appeared.
        if strong:
            return strong[0]
        if weak:
            return weak[0]
        return None

    @classmethod
    def render(cls, module_name, constants, python_version,
               disasm_info=None, disasm_infos=None, mod_consts_base=None,
               runtime_aliases=None, entry_va=None,
               ops_absence_reason=None, module_table_entry=None,
               chunk_bytes=None, full=True, include_native_asm=False):
        """Produce the text content for `<module>.nbc`.

        Either `disasm_info` (single-block) OR `disasm_infos` (dict of
        {va: info}, multi-block) may be given. When `disasm_infos` is
        provided, one `@OPS <va>` block is emitted per function — this
        is the form the LLM needs to rebuild individual function bodies
        literally instead of just signatures.

        `mod_consts_base` and `runtime_aliases` are optional — when
        omitted the emitter still emits the constants + imports +
        funcs_detected header but ALSO writes a `@NO_OPS` diagnostic
        block explaining WHY `@OPS` is missing so the LLM knows it got
        a partial file (and the user knows what to fix).

        `ops_absence_reason` can be one of:
            'capstone_missing' | 'no_pe' | 'no_module_table' |
            'not_in_module_table' | 'disasm_failed' | None
        """
        runtime_aliases = runtime_aliases or {}
        out = []
        out.append('# Nuitka static reconstruction. Feed this .nbc file to an LLM.')
        out.append('# Format version: NBC/2 full self-contained module record.')
        out.append('# c[N]=mod_consts[N]   r#N=runtime_helper_rank   capi:=Python C API')
        out.append('# Multiple @OPS blocks = one per disassembled function '
                   '(module entry + every internal call target reached via BFS).')
        out.append('')
        out.append('@NBC 2')
        out.append(f'@MOD {module_name or "__module__"}')
        out.append(f'@VER {python_version[0]}.{python_version[1]}')
        if entry_va is not None:
            out.append(f'@ENTRY 0x{entry_va:X}')
        out.append('')
        cls._emit_module_table_entry(module_table_entry, out)
        cls._emit_raw_chunk(chunk_bytes, out)
        cls._emit_constants(list(constants), out, full=full)
        out.append('')
        cls._emit_imports(module_name, constants, out)
        out.append('')
        cls._emit_funcs_detected(module_name, constants, out)
        out.append('')
        cls._emit_code_objects(module_name, list(constants), out)
        out.append('')
        # Normalise: prefer disasm_infos (multi), fall back to disasm_info (single)
        infos_dict = None
        if disasm_infos:
            infos_dict = disasm_infos
        elif disasm_info:
            infos_dict = {disasm_info['func_va']: disasm_info}
        if infos_dict:
            cls._emit_block_summary(infos_dict, runtime_aliases, out)
            # Build an authoritative func_va -> qualname map by
            # aggregating every `make_function_hints` pair across all
            # disassembled blocks. This is much more accurate than
            # inferring qualnames per-block because Nuitka emits the
            # (func_ptr, qualname) pair inline at the MAKE_FUNCTION
            # call site — right where the parent function creates the
            # child. The child itself has no __qualname__ const load.
            va_to_qualname = {}
            if mod_consts_base is not None:
                def _resolve_const_str(va):
                    if va is None:
                        return None
                    if va < mod_consts_base:
                        return None
                    off = va - mod_consts_base
                    if off % 8:
                        return None
                    i = off // 8
                    if not (0 <= i < len(constants)):
                        return None
                    v = constants[i]
                    if cls._qualname_score(v, allow_short=True) <= 0:
                        return None
                    return v

                # For every (parent_func, lea->impl) hint, gather ALL
                # the parent function's mod_consts string loads as
                # qualname candidates. Nuitka sometimes emits the
                # (impl_ptr, qualname) pair in "lea qualname, lea impl"
                # order (qualname FIRST) rather than the reverse — a
                # forward-only window misses that case.  Collect every
                # candidate and pick the one that best matches
                # `ClassName.method` / `func` / `<lambda>` etc.
                for _va, _info in infos_dict.items():
                    # Precompute this parent's string candidates once
                    const_events = []
                    for cl in _info.get('const_loads', []):
                        s = _resolve_const_str(cl['target_va'])
                        if s is None:
                            continue
                        const_events.append((
                            cl.get('va_from', 0),
                            cls._qualname_score(s, allow_short=True),
                            s,
                        ))
                    if not const_events:
                        continue
                    # Pair each function pointer with the nearest
                    # qualname-like constant load in the same call site.
                    for fp in _info.get('func_ptr_loads', []):
                        fp_site = fp.get('va_from', 0)
                        tgt = fp.get('target_va')
                        if tgt is None:
                            continue
                        nearby = []
                        for c_site, score, s in const_events:
                            dist = abs(c_site - fp_site)
                            if dist <= 192:
                                nearby.append((-score, dist, c_site > fp_site, s))
                        if nearby and tgt not in va_to_qualname:
                            nearby.sort()
                            va_to_qualname[tgt] = nearby[0][3]
                    # Also keep the previous adjacency logic for
                    # parents that have MULTIPLE (lea, qualname) pairs
                    # — try to pair each specifically
                    for hint in _info.get('make_function_hints', []):
                        target_fn_va = hint['func_va']
                        for cand in hint.get('candidate_vas', []):
                            s = _resolve_const_str(cand)
                            if s is not None:
                                # Override weak picks with specific
                                # adjacency-derived qualname
                                if ('.' in s or '<' in s
                                        or target_fn_va not in va_to_qualname):
                                    va_to_qualname[target_fn_va] = s
                                break

            # Resolve a qualname for every disassembled VA the same way
            # `_emit_virtual_ops` labels its `@OPS` header: prefer the
            # authoritative MAKE_FUNCTION map, then the per-block
            # `_infer_func_qualname` fallback.  Feeding the UNIFIED map to
            # `@FUNC_PTR_MAP` keeps the table consistent with the `@OPS`
            # labels — otherwise the map shows `qualname=?` for hundreds of
            # functions whose `@OPS` block carries a recovered name.
            resolved_qn = dict(va_to_qualname)
            for _va, _info in infos_dict.items():
                if _va in resolved_qn:
                    continue
                if entry_va is not None and _va == entry_va:
                    continue  # module entry has no __qualname__
                _qn = cls._infer_func_qualname(_info, constants,
                                                mod_consts_base)
                if _qn:
                    resolved_qn[_va] = _qn

            # Bind each disassembled VA to its CodeObject (args/freevars/
            # line) via the qualname join, then emit a consolidated
            # @FUNC_PTR_MAP table so `fn@0xVA` references inside the op
            # traces can be resolved at a glance.
            va_to_codeobject = cls._build_va_to_codeobject(
                resolved_qn, cls._collect_code_objects(constants))
            cls._emit_func_ptr_map(out, infos_dict, resolved_qn,
                                    va_to_codeobject)

            # Emit one @OPS block per function; the module entry VA goes first.
            entry_first = []
            others = []
            for va, info in infos_dict.items():
                if entry_va is not None and va == entry_va:
                    entry_first.append((va, info))
                else:
                    others.append((va, info))
            ordered = entry_first + others
            out.append(f'# @OPS blocks: {len(ordered)} function(s) '
                       f'(entry + {len(ordered) - 1} locals)')
            out.append('')
            for va, info in ordered:
                # The module entry (module_code_<mod>) is not a Python
                # `def` — it has no __qualname__. Suppress any fallback
                # labeling attempt so it isn't accidentally stamped with
                # the qualname of the first child function it creates.
                is_module_entry = (entry_va is not None and va == entry_va)
                cls._emit_virtual_ops(info, constants, mod_consts_base,
                                      runtime_aliases, out,
                                      va_to_qualname=va_to_qualname,
                                      suppress_fallback_label=is_module_entry,
                                      va_to_codeobject=va_to_codeobject)
                out.append('')
                if include_native_asm:
                    cls._emit_native_asm(info, constants, mod_consts_base,
                                         runtime_aliases, out)

            # --- FORENSICS section ------------------------------------
            # For qualnames that appear in @CONSTS but never got an
            # @OPS block (BFS didn't reach them — usually Tk/Qt
            # callbacks bound via trace_add/bind, inlined helpers,
            # dead-code paths), emit the **constants that are
            # plausibly tied to them**:
            #   1. the qualname + short name indices
            #   2. the 12 constants adjacent in mod_consts order
            #      (Nuitka clusters a function's consts around its
            #      qualname in the defining module's constants table)
            #   3. any string in @CONSTS whose text literally contains
            #      the short function name (error messages, logs).
            # This gives an LLM concrete forensic evidence to
            # reconstruct likely behaviour WITHOUT fabricating random
            # code — at minimum it sees the error strings, dict keys
            # and integers the function must have referenced.
            cls._emit_forensics(
                constants=constants,
                va_to_qualname=va_to_qualname,
                out=out,
            )
        else:
            # The @OPS section is the heart of a .nbc — its absence turns
            # the file into a signature skeleton only. Explain explicitly
            # so an LLM doesn't silently fabricate a body AND the user
            # knows what to change.
            reason_map = {
                'capstone_missing':
                    'capstone was not installed at analyser runtime '
                    '(pip install capstone); no disassembler could run.',
                'no_pe':
                    'the analyser did not receive a parsed PE object '
                    '(StaticalyExtractor(pe_file=None) — construct with '
                    'the binary).',
                'no_module_table':
                    'the Nuitka module table could not be located in '
                    '.data / .rdata; cannot find the entry VA to '
                    'disassemble from.',
                'not_in_module_table':
                    'this specific module was not present in the module '
                    'table fragment the analyser recovered — other '
                    'modules in this run may still have @OPS.',
                'disasm_failed':
                    'capstone threw while disassembling; the .text bytes '
                    'may be obfuscated or the func_ptr is wrong.',
                None:
                    'disassemble_modules() was never invoked for this '
                    'run (HEXPYRION ran in constants-only mode).',
            }
            reason_text = reason_map.get(ops_absence_reason, reason_map[None])
            out.append('@NO_OPS')
            out.append(f'  reason: {reason_text}')
            out.append(f'  consequence: function bodies cannot be rebuilt '
                       f'literally — any LLM fed this file can only emit '
                       f'signatures + # UNCERTAIN bodies.')
            out.append(f'  fix: re-run with')
            out.append(f'       pip install capstone')
            out.append(f'       python nuitka_decompiler.py '
                       f'--source <target.exe> --output <dir> --all')
            out.append(f'       (make sure the run logs show '
                       f'"Staticaly modules disassembled: N > 0")')
        return '\n'.join(out) + '\n'


# ---------------------------------------------------------------------------
#  NUITKA MODULE DUMP — exhaustive per-module diagnostic file
# ---------------------------------------------------------------------------

class NuitkaModuleDump:
    """Produce a `pseudo-bytecode` dump of a single blob module chunk.

    The goal is to capture **every recoverable byte of information** about
    the module so a reverse engineer (or another tool / AI) can
    reconstruct the original Python source literally.

    The dump is a multi-section text file that includes:

      # METADATA
        module name, chunk size, offset in blob, constants count.

      # CONSTANTS  (the authoritative list, in blob order)
        position, type, interpretation, hex size, value repr.

      # CATEGORISED CONSTANTS
          strings   (split into: idents, dunder, URLs, messages,
                    attribute-names-like, filenames)
          numerics  (ints / floats / booleans)
          tuples    (co_varnames candidates, import-names, kw_defaults, …)
          dicts, sets, bytes

      # INFERRED STRUCTURES
          functions   : name, argcount, args (from position-paired tuple),
                        nearby URL / dict / header constants
          classes     : class name, methods (via qualname `Class.method`)
          imports     : from X import ..., import X (detected patterns)

      # CROSS-REFERENCES  (which string appears as what, how many times)

      # POSITIONAL ANALYSIS
          for every ident-tuple: its position and the nearest surrounding
          ident strings that might be its co_varnames' function name.

      # RAW HEX DUMP of the chunk (optional, last).

    Output file: `<module>.dump.txt`  (same tree as `omni_reconstructed/`).
    Optionally `<module>.dump.json`   for machine-readable analysis.
    """

    def __init__(self, module_name, chunk_bytes, constants, blob_offset=None):
        self.module_name = module_name or '__module__'
        self.chunk = bytes(chunk_bytes) if chunk_bytes is not None else b''
        self.constants = list(constants)
        self.blob_offset = blob_offset

    # --- classification helpers ---

    @staticmethod
    def _classify_string(s):
        if not isinstance(s, str) or not s:
            return 'empty'
        if s.startswith(('http://', 'https://')):
            return 'url'
        if s.startswith('__') and s.endswith('__'):
            return 'dunder'
        if re.fullmatch(r'[A-Z][A-Z0-9_]{2,}', s):
            return 'constant_like'       # ALL_CAPS → probable module-level const
        if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', s):
            if s[0].isupper():
                return 'class_like'      # CamelCase
            return 'ident'               # snake_case
        if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)+', s):
            return 'dotted_path'
        if s.endswith(('.py', '.pyc')):
            return 'filename'
        if '\\' in s or '/' in s:
            return 'path'
        if len(s) > 40 and ' ' in s:
            return 'message'
        if re.fullmatch(r'%[sdifoxXcrb]', s) or '%s' in s or '%d' in s:
            return 'format_string'
        return 'string'

    @staticmethod
    def _is_ident_tuple(t):
        return (isinstance(t, tuple) and t
                and all(isinstance(x, str) and
                        (x == '.0' or re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', x))
                        for x in t))

    # --- rendering ---

    def render(self, include_hex=True):
        out = []
        out.append('=' * 72)
        out.append(f' NUITKA MODULE DUMP   {self.module_name}')
        out.append('=' * 72)
        out.append('')
        out.append(f'# Chunk size        : {len(self.chunk):,} bytes')
        if self.blob_offset is not None:
            out.append(f'# Blob offset       : 0x{self.blob_offset:X}')
        out.append(f'# Constants count   : {len(self.constants)}')
        out.append(f'# Dump produced by  : HEXPYRION (by dimareverse)')
        out.append('')

        # ---------- CONSTANTS ----------
        out.append('-' * 72)
        out.append(' CONSTANTS (in blob order)')
        out.append('-' * 72)
        for i, c in enumerate(self.constants):
            tname = type(c).__name__
            if isinstance(c, str):
                kind = self._classify_string(c)
                rep = repr(c)
                if len(rep) > 120:
                    rep = rep[:117] + '...'
                out.append(f'[{i:4d}] str/{kind:<13} {rep}')
            elif isinstance(c, (bytes, bytearray)):
                kind = 'bytes'
                try:
                    maybe = c.decode('utf-8')
                    if all(32 <= ord(x) < 127 or x in '\r\n\t' for x in maybe[:200]):
                        kind = 'bytes/ascii'
                except Exception:
                    pass
                rep = repr(bytes(c)[:80]) + ('...' if len(c) > 80 else '')
                out.append(f'[{i:4d}] {kind:<17} size={len(c)}  {rep}')
            elif isinstance(c, tuple):
                if self._is_ident_tuple(c):
                    kind = 'tuple/idents'
                elif all(isinstance(x, str) for x in c):
                    kind = 'tuple/strs'
                elif all(isinstance(x, (int, float)) for x in c):
                    kind = 'tuple/nums'
                else:
                    kind = 'tuple'
                rep = repr(c)
                if len(rep) > 120:
                    rep = rep[:117] + '...'
                out.append(f'[{i:4d}] {kind:<17} size={len(c)}  {rep}')
            elif isinstance(c, dict):
                out.append(f'[{i:4d}] dict              size={len(c)}  {repr(c)[:100]}')
            elif isinstance(c, (list, set, frozenset)):
                out.append(f'[{i:4d}] {tname:<17} size={len(c)}  {repr(c)[:100]}')
            elif isinstance(c, bool):
                out.append(f'[{i:4d}] bool              {c}')
            elif isinstance(c, int):
                out.append(f'[{i:4d}] int               {c}   (hex 0x{c:X})'
                           if abs(c) < (1 << 32) else f'[{i:4d}] int               {c}')
            elif isinstance(c, float):
                out.append(f'[{i:4d}] float             {c}')
            elif c is None:
                out.append(f'[{i:4d}] None')
            else:
                out.append(f'[{i:4d}] {tname:<17} {repr(c)[:100]}')
        out.append('')

        # ---------- CATEGORISED ----------
        cat = {
            'urls': [], 'messages': [], 'format_strings': [], 'filenames': [],
            'paths': [], 'dunders': [], 'idents': [], 'class_likes': [],
            'constant_likes': [], 'strings': [], 'dotted_paths': [],
            'integers': [], 'floats': [], 'bytes': [],
            'ident_tuples': [], 'string_tuples': [], 'numeric_tuples': [],
            'dicts': [], 'sets': [],
        }
        for i, c in enumerate(self.constants):
            if isinstance(c, str):
                k = self._classify_string(c)
                bucket = {
                    'url': 'urls',
                    'message': 'messages',
                    'format_string': 'format_strings',
                    'filename': 'filenames',
                    'path': 'paths',
                    'dunder': 'dunders',
                    'ident': 'idents',
                    'class_like': 'class_likes',
                    'constant_like': 'constant_likes',
                    'dotted_path': 'dotted_paths',
                }.get(k, 'strings')
                cat[bucket].append((i, c))
            elif isinstance(c, (bytes, bytearray)):
                cat['bytes'].append((i, bytes(c)))
            elif isinstance(c, tuple):
                if self._is_ident_tuple(c):
                    cat['ident_tuples'].append((i, c))
                elif all(isinstance(x, str) for x in c):
                    cat['string_tuples'].append((i, c))
                elif all(isinstance(x, (int, float)) for x in c):
                    cat['numeric_tuples'].append((i, c))
            elif isinstance(c, dict):
                cat['dicts'].append((i, c))
            elif isinstance(c, (set, frozenset)):
                cat['sets'].append((i, c))
            elif isinstance(c, bool):
                pass  # skip
            elif isinstance(c, int):
                cat['integers'].append((i, c))
            elif isinstance(c, float):
                cat['floats'].append((i, c))

        out.append('-' * 72)
        out.append(' CATEGORISED CONSTANTS')
        out.append('-' * 72)
        sect_names = [
            ('urls', 'URLs / HTTP endpoints'),
            ('messages', 'Human-readable messages (len>40 with spaces)'),
            ('format_strings', 'Format strings (printf / %s / %d …)'),
            ('filenames', 'Filenames (end in .py / .pyc)'),
            ('paths', 'Paths (with / or \\)'),
            ('dunders', 'Dunder attributes (__foo__)'),
            ('constant_likes', 'ALL_CAPS constants'),
            ('class_likes', 'CamelCase identifiers (probable classes)'),
            ('dotted_paths', 'Dotted paths (module.attr / Class.method)'),
            ('idents', 'snake_case identifiers'),
            ('strings', 'Other strings'),
            ('integers', 'Integers'),
            ('floats', 'Floats'),
            ('bytes', 'Bytes'),
            ('ident_tuples', 'Tuples of identifiers (co_varnames candidates)'),
            ('string_tuples', 'Tuples of strings (non-ident)'),
            ('numeric_tuples', 'Tuples of numbers'),
            ('dicts', 'Dicts (literal kwargs / configs)'),
            ('sets', 'Sets / frozensets'),
        ]
        for key, title in sect_names:
            items = cat[key]
            if not items:
                continue
            out.append(f'\n### {title}  ({len(items)})')
            for i, v in items:
                rep = repr(v)
                if len(rep) > 140:
                    rep = rep[:137] + '...'
                out.append(f'  [{i:4d}] {rep}')
        out.append('')

        # ---------- INFERRED STRUCTURES ----------
        out.append('-' * 72)
        out.append(' INFERRED STRUCTURES')
        out.append('-' * 72)

        # 1) Imports: dotted path OR stdlib-ident followed by ident-tuple
        imports_detected = []
        stdlib = StaticalySmartReconstructor._COMMON_STDLIB
        for i, c in enumerate(self.constants):
            if not isinstance(c, str):
                continue
            next_tup = (self.constants[i + 1] if i + 1 < len(self.constants) else None)
            dotted = bool(re.fullmatch(
                r'[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)+', c
            ) and not c.endswith('.py') and c.split('.')[0][:1].islower())
            is_std = c in stdlib
            if (dotted or is_std) and self._is_ident_tuple(next_tup):
                imports_detected.append(('from_import', i, c, list(next_tup)))
            elif dotted or is_std:
                imports_detected.append(('import', i, c, None))

        if imports_detected:
            out.append('\n### Imports')
            for kind, idx, mod, names in imports_detected:
                if kind == 'from_import':
                    out.append(f'  [{idx:4d}] from {mod} import {", ".join(names)}')
                else:
                    out.append(f'  [{idx:4d}] import {mod}')

        # 2) Function candidates: for each ident-tuple, find the nearest
        #    ident-string that could be the function name.
        out.append('\n### Function candidates (tuple → likely function signature)')
        for i, tup in cat['ident_tuples']:
            # Look backwards and forwards up to 8 positions for an ident
            name = None
            for off in range(-8, 9):
                j = i + off
                if j == i or j < 0 or j >= len(self.constants):
                    continue
                v = self.constants[j]
                if (isinstance(v, str)
                        and re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', v or '')
                        and not v.startswith('__')):
                    name = v
                    break
            args = ', '.join(tup)
            if name:
                out.append(f'  [{i:4d}] tuple ({args}) ~= co_varnames of def {name}(...)')
            else:
                out.append(f'  [{i:4d}] tuple ({args}) ~= anonymous co_varnames')

        # 3) Classes from qualname patterns
        classes = {}
        for c in self.constants:
            if not isinstance(c, str):
                continue
            m = re.fullmatch(
                r'([A-Z][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)(?:\.<locals>.*)?', c
            )
            if m:
                classes.setdefault(m.group(1), set()).add(m.group(2))
        if classes:
            out.append('\n### Class hierarchy (from `Class.method` qualnames)')
            for cls_name in sorted(classes):
                methods = sorted(classes[cls_name])
                out.append(f'  class {cls_name}:')
                for m in methods:
                    out.append(f'      def {m}(self, ...)')

        # 4) HTTP API endpoints explicit list
        if cat['urls']:
            out.append('\n### HTTP API endpoints')
            for i, u in cat['urls']:
                out.append(f'  [{i:4d}] {u}')

        # 5) Error / status messages
        if cat['messages']:
            out.append('\n### Human-readable messages (errors / prompts)')
            for i, m in cat['messages']:
                out.append(f'  [{i:4d}] {m!r}')

        out.append('')

        # ---------- POSITIONAL ANALYSIS ----------
        out.append('-' * 72)
        out.append(' POSITIONAL MAP  (name → nearest tuple)')
        out.append('-' * 72)
        name_positions = [(i, c) for i, c in enumerate(self.constants)
                          if isinstance(c, str)
                          and re.fullmatch(r'[a-z_][a-z0-9_]*', c or '')
                          and len(c) > 2]
        tuple_positions = [(i, c) for i, c in cat['ident_tuples']]
        # Pair positionally (1-to-1 by sorted index) — this matches source order.
        pair_lines = []
        for k in range(min(len(name_positions), len(tuple_positions))):
            pi, pn = name_positions[k]
            ti, pt = tuple_positions[k]
            pair_lines.append(f'  {pn!r} (const[{pi}])  <->  {pt}  (const[{ti}])')
        out.extend(pair_lines[:80])
        if len(pair_lines) > 80:
            out.append(f'  ... ({len(pair_lines) - 80} more pairings)')
        out.append('')

        # ---------- HEX DUMP ----------
        if include_hex and self.chunk:
            out.append('-' * 72)
            out.append(f' RAW HEX DUMP of chunk  ({len(self.chunk):,} bytes)')
            out.append('-' * 72)
            # canonical xxd-style: offset  16 bytes hex  ascii
            for off in range(0, len(self.chunk), 16):
                row = self.chunk[off:off + 16]
                hex_part = ' '.join(f'{b:02x}' for b in row)
                ascii_part = ''.join(chr(b) if 0x20 <= b < 0x7F else '.' for b in row)
                out.append(f'{off:08x}  {hex_part:<47}  |{ascii_part}|')
            out.append('')

        return '\n'.join(out) + '\n'

    def render_json(self):
        """Machine-readable version of the dump."""
        def _serialisable(v):
            if isinstance(v, (str, int, float, bool)) or v is None:
                return v
            if isinstance(v, (bytes, bytearray)):
                try:
                    return {'_type': 'bytes', 'hex': bytes(v).hex(),
                            'size': len(v)}
                except Exception:
                    return {'_type': 'bytes', 'repr': repr(bytes(v)[:200])}
            if isinstance(v, tuple):
                return {'_type': 'tuple', 'items': [_serialisable(x) for x in v]}
            if isinstance(v, list):
                return [_serialisable(x) for x in v]
            if isinstance(v, dict):
                return {'_type': 'dict',
                        'items': [[_serialisable(k), _serialisable(x)]
                                  for k, x in list(v.items())[:200]]}
            if isinstance(v, (set, frozenset)):
                return {'_type': type(v).__name__,
                        'items': [_serialisable(x) for x in list(v)[:200]]}
            return repr(v)

        payload = {
            'module': self.module_name,
            'chunk_size': len(self.chunk),
            'blob_offset': self.blob_offset,
            'constants_count': len(self.constants),
            'constants': [
                {'index': i,
                 'type': type(c).__name__,
                 'classification': (self._classify_string(c)
                                    if isinstance(c, str) else None),
                 'value': _serialisable(c)}
                for i, c in enumerate(self.constants)
            ],
        }
        return json.dumps(payload, indent=2, ensure_ascii=False, default=str)


# ---------------------------------------------------------------------------
#  STATICALY SMART PYTHON RECONSTRUCTOR — deepest per-module recovery
# ---------------------------------------------------------------------------

# V95 Fix 11 (universal): `_heal_class_bases` lived only in the NDX half of
# this file (bound AFTER the legacy `sys.exit(main())` driver at module
# level), so every legacy-CLI run reconstructing a CLASS WITH BASES died with
# `NameError: name '_heal_class_bases' is not defined`.  Bind it in the legacy
# half too; the identical later def keeps NDX behavior unchanged.
_CLASS_BASE_MACHINERY_MARKERS = ('via_PyUnicode_FromString', '<metaclass>',
                                 '_tstate(', '_stackaddr(', '_type_of(',
                                 'CALL_FUNCTION(', '__prepare__',
                                 '_PyObject_GC_Malloc(', '_gslot(')


def _heal_class_bases(bases, class_name=None):
    """Riduce le basi machinery di Nuitka alle classi reali del sorgente.

    La create-class porta il metaclass plumbing (lookup del nome,
    ``__prepare__``, ``_type_of``) come basi spurie; la tupla delle basi
    VERE vive dentro una di esse come ``(Base,)``. Una base con marker
    machinery viene scartata, a meno che contenga una tupla di soli
    identifier classe-like: quei nomi SONO le basi del sorgente."""
    out = []
    for b in bases:
        if not any(m in b for m in _CLASS_BASE_MACHINERY_MARKERS):
            out.append(b)
            continue
        for m in re.finditer(
                r'\(\s*([A-Z]\w*(?:\s*,\s*[A-Z]\w*)*)\s*,?\s*\)', b):
            for nm in m.group(1).split(','):
                nm = nm.strip()
                if nm and nm != class_name and nm not in out:
                    out.append(nm)
    return out


class StaticalySmartReconstructor:
    """Deep static reconstruction of a Nuitka module chunk into Python source.

    Nuitka translates each Python function body directly into C operations
    and then into native x86-64 instructions: the original `co_code` is
    NEVER stored in the binary for C-compiled modules, only its metadata.
    So a 100% byte-exact source recovery is impossible for those modules.

    What IS recoverable from the `constants` chunk of each module:
      * All string/int/float/tuple/dict/set/frozenset literals the module
        body or any of its functions reference. These are the constants
        passed to `LOAD_CONST` in the never-stored bytecode, emitted by
        Nuitka into the blob so the generated C code can look them up.
      * All `co_varnames` tuples — one per function/method body. That's
        the argument list + local-variable names of every def in the
        original source.
      * The `co_filename` / `co_name` / `co_qualname` of every code
        object (they're stored with 'C' tag or sit near the arg tuple).
      * Import side-effects: Nuitka emits the module-name STR followed by
        a tuple of imported-names STRs for every `from X import Y, Z`.

    This reconstructor pattern-matches on those constants to emit a
    near-original Python source:

      1. `import X`, `from X import (Y, Z as A)` lines
      2. Module-level globals (first non-dunder str sequence)
      3. `class Name(Base1, Base2):` with `def method(self, args):` inside
      4. Free `def func(args):` with an heuristic body when we recognise
         a well-known pattern (HTTP fetch, HMAC sign, JSON parse, etc.)
      5. Body STUBS with a list of "strings referenced by this function"
         so a reverse-engineer can re-derive the logic from the clues.

    When the pattern isn't recognised we emit `...` (not fabricated code)
    so the output never misleads with invented behaviour.
    """

    # Recognisable Python keywords that often appear verbatim in the
    # constants (`co_consts` items).
    _BUILTIN_EXCEPTIONS = {
        'Exception', 'ValueError', 'TypeError', 'KeyError', 'IndexError',
        'RuntimeError', 'AttributeError', 'ImportError', 'IOError',
        'OSError', 'FileNotFoundError', 'ConnectionError', 'TimeoutError',
        'InvalidSignature',
    }
    _HTTP_STATUS_NAMES = ('status_code', 'text', 'json', 'content')
    _HTTP_GET_KEYWORDS = ('status_code', 'json', 'get', 'response', 'text', 'content')

    def __init__(self, module_name, constants, code_objects, body_traces=None,
                 module_globals=None, body_sources=None, defaults=None,
                 known_modules=None, is_package=False, emit_banner=True,
                 module_global_values=None,
                 native_attempted=False, source_order=None):
        self.module_name = module_name or '__module__'
        # True when the live native code-object recovery actually ran for this
        # module. If it ran and produced no function code objects we TRUST that
        # (emit no functions) instead of broad-scanning the constant pool for
        # plausible function names — that guessing invents phantom defs like
        # `def lookup_table(): ...` for what is really a data global.
        self.native_attempted = bool(native_attempted)
        # Full set of dotted module names present in the binary (so import
        # relativity can be decided exactly: a bare `from X import …` is a
        # relative sibling iff `<pkg>.X` is one of these). Optional.
        self.known_modules = set(known_modules or ())
        # True when THIS module is a package __init__ (its children are
        # `<module_name>.*`). Controls the relative-import base.
        self.is_package = bool(is_package)
        # Emit the synthetic "Static reconstruction …" module docstring banner.
        # The whole-binary source emit turns this OFF so the output tracks the
        # original (which never had that banner) as closely as possible.
        self.emit_banner = bool(emit_banner)
        self.constants = list(constants)
        self.code_objects = list(code_objects)
        self._defaults = dict(defaults or {})
        # {qualname: [name, ...]} faithful per-function name-access sequence
        # recovered from the native const-loads (see
        # NuitkaStaticDisassembler.recover_body_traces). Optional.
        self.body_traces = dict(body_traces or {})
        # {qualname: [line, ...]} EXACT real-Python bodies for the provably-
        # unambiguous functions (currently single-expression arithmetic
        # returns, e.g. `return satoshis_amount / 100000000`). When present for
        # a function its body is emitted as REAL decompiled code instead of the
        # faithful comment trace. Optional. See _synth_arith_return.
        self.body_sources = dict(body_sources or {})
        # Set of names the module-init actually STORES at module scope (the
        # real module globals), recovered from the store-helper calls in the
        # module body (NuitkaStaticDisassembler.recover_module_global_names).
        # When available it lets _emit_module_constants drop ALL_CAPS pool
        # strings that are really attribute names (colorama `Fore.MAGENTA`) or
        # imported constants, keeping only the genuine globals. Optional;
        # empty => fall back to emitting every ALL_CAPS candidate.
        self.module_globals = set(module_globals or ())
        # Dict of module-global names -> recovered constant literal values,
        # obtained from the module-init MODSTORE helpers. Optional.
        self.module_global_values = dict(module_global_values or {})

        # C-compiled Nuitka modules don't emit 'C' tags into their
        # constants chunk, so we have to infer the function/class layout
        # from the raw constant pool. The pool DOES contain, for every def
        # in the original source: its bare co_name, its dotted co_qualname
        # (`Class.method`), and its co_varnames tuple (args + locals). We
        # drive the reconstruction off those QUALNAMES — that is far more
        # accurate than the old "every lowercase ident is a function" scan,
        # which turned attribute names like `seed`/`account` into bogus defs.
        self._inferred_bases = {}
        if self.code_objects and any(co.get('_native') for co in self.code_objects):
            # EXACT code objects recovered from the native PyCode_New* call
            # sites (argcount/flags/varnames are ground truth). Merge them with
            # the dotted-qualname constants so methods land in their class.
            (self.code_objects,
             self._inferred_classes,
             self._inferred_bases) = self._merge_native_code_objects(self.code_objects)
        elif not self.code_objects:
            # No recovered code objects: either native recovery ran and found
            # none, OR we're on the static-only path (no func_ptr — typical
            # commercial / data-hiding binary). In BOTH cases
            # a bare lowercase ident in the constant pool is indistinguishable
            # from a module name (`sqlite3` from `import sqlite3`) or an
            # attribute load (`connect`, `now`, `strftime`, `write`, `loads`,
            # `read`, `pack` from `sqlite3.connect` / `datetime.now` /
            # `json.loads` / `struct.pack`), so broad-scanning free functions
            # fabricates phantom defs like `def sqlite3(): pass`. Recover class
            # structure from the dotted qualnames only (reliable — keys off
            # unambiguous `Class.method` strings) and leave free-function
            # discovery to the native code-object path. Imports are still
            # emitted honestly by detect_imports(). UNIVERSAL + zero-regression:
            # this whole elif is only entered when self.code_objects is empty;
            # for the scored suite native recovery
            # populates code_objects so this branch — and the free scan — stay
            # dormant. (Previously the native_attempted=False arm called
            # _infer_code_objects_from_constants -> _scan_free_functions, which
            # was the sole source of the fabricated defs.)
            methods, class_order, method_leaves = self._scan_qualnames()
            self._assign_args_by_order(methods)
            self.code_objects = methods
            self._inferred_classes = class_order
            self._inferred_bases = self._scan_class_bases(
                class_order, method_leaves)
        else:
            self._inferred_classes = []

        # Build string index by value → list of positions (for pattern scans)
        self.str_positions = {}
        for i, c in enumerate(self.constants):
            if isinstance(c, str):
                self.str_positions.setdefault(c, []).append(i)

        # Classify each code object into module-body / class methods / free funcs
        self._classify()

        # SOURCE-ORDER map: self.code_objects is in PyCode_New call-site order
        # (== MAKE_FUNCTION / definition order), the faithful top-to-bottom
        # layout. Keyed by id() so it works even for duplicate leaf names. The
        # constant-pool string index (str_positions) is NOT source order —
        # Nuitka interns each name on first reference, not by line — which used
        # to float `main` above `__init__`. Backfilled (qualname-only) methods
        # are absent here and fall back to the const index in the sort keys.
        self._def_order = {id(co): i for i, co in enumerate(self.code_objects)}
        # PROVEN source order, keyed by dotted qualname: ascending function
        # implementation-VA. Nuitka's C codegen emits each function/method body
        # as a C function in source-declaration order, so ascending impl-VA is
        # the original top-to-bottom order. Built in decompile_module_to_source
        # from va_to_qn and threaded in. This is more reliable than _def_order,
        # which reflects Nuitka's ALPHABETICAL PyCode_New call-site order (NOT
        # source order) and breaks when co dicts are copied during merge/backfill.
        self._src_order = dict(source_order or {})

    # ---- structural classification ----

    # --- Names we should NEVER emit as `def <name>(...)`. These are
    # module-level attributes, well-known dunder names, or constant-like
    # ALL_CAPS identifiers that represent values rather than callables.
    _NON_FUNCTION_NAMES = frozenset({
        # Python module machinery
        '__doc__', '__file__', '__cached__', '__name__', '__spec__',
        '__package__', '__builtins__', '__class__', '__loader__',
        '__path__', '__module__', '__all__', '__version__',
        '__author__', '__annotations__', '__dict__', '__slots__',
        '__qualname__', '__weakref__', '__mro_entries__',
        # HTTP / response-object attribute accesses (they're strings used
        # for LOAD_ATTR, not functions in the module)
        'status_code', 'text', 'content', 'json', 'get', 'post', 'put',
        'delete', 'headers', 'cookies', 'url', 'ok', 'reason', 'encoding',
        'origin', 'has_location',
        # Control flow / magic method names emitted as LOAD_ATTR consts
        '__iter__', '__getitem__', '__setitem__', '__enter__', '__exit__',
        '__init__', '__call__', '__str__', '__repr__', '__eq__', '__hash__',
        '__bool__', '__len__', '__contains__', '__add__', '__sub__',
        '__mul__', '__truediv__', '__getattr__', '__setattr__',
    })

    # Names that Nuitka's package/module init machinery references as code
    # objects (os.path.dirname/join, os.environ, the package __path__ setter
    # `submodule_search_locations`, getcwd, …) but which are NEVER user-defined
    # module-level functions. They get spuriously recovered as free functions in
    # re-exporting package __init__ modules; we drop them at module scope only
    # (a class method genuinely named e.g. `join` is still kept).
    _PACKAGE_MACHINERY_NAMES = frozenset({
        'path', 'dirname', 'join', 'environ', 'submodule_search_locations',
        'getcwd', 'abspath', 'basename', 'realpath', 'normpath', 'splitext',
        'expanduser', 'isdir', 'isfile', 'pardir', 'curdir',
    })

    # ---- qualname-driven structure inference (primary path) ----------------

    @staticmethod
    def _is_ident(s):
        return isinstance(s, str) and bool(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', s))

    @staticmethod
    def _is_valid_def_name(name):
        """A name we can legally emit as `def <name>(...)` / `class <name>`."""
        import keyword
        return (isinstance(name, str)
                and bool(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name))
                and not keyword.iskeyword(name)
                and not keyword.issoftkeyword(name))

    def _definition_region(self):
        """(start, end) constant indices bounding the def/class region.

        Nuitka emits a module's LOAD_ATTR / usage strings first, then a block
        of dunder markers (``__doc__``/``__file__``/``__module__``), then the
        function & class machinery, and finally ``__spec__``. Restricting the
        free-function scan to [first-dunder, __spec__) discards the early
        attribute-name noise (``now``/``readlines``/``getcwd`` …) that is not
        a module-level def.
        """
        start, end = 0, len(self.constants)
        markers_lo = ('__doc__', '__file__', '__module__', '__qualname__')
        for i, c in enumerate(self.constants):
            if isinstance(c, str) and c in markers_lo:
                start = i
                break
        for i, c in enumerate(self.constants):
            if c == '__spec__':
                end = i
                break
        return start, end

    def _is_varnames_tuple(self, t):
        """True for a tuple that looks like a co_varnames list (args+locals)."""
        return (isinstance(t, tuple) and 0 < len(t) <= 40
                and all(x == '.0' or self._is_ident(x) for x in t))

    def _scan_qualnames(self):
        """Recover methods + their owning classes from dotted co_qualnames.

        Nuitka stores, for every method, the FULL qualname string
        ``Class.method`` (and for nested defs ``Class.method.<locals>.inner``).
        The owning class is the first dotted segment when it is Capitalised
        (a lowercase first segment denotes a module path like
        ``tls_client.Session`` — an attribute access, not a method qualname).

        Returns (methods, class_order, method_leaves):
          methods       list[code-object dict] one per detected method
          class_order   list[str] class names in first-seen order
          method_leaves set[str]  bare method names (so the free-func scan
                                   doesn't re-emit them at module level)
        """
        methods = []
        class_order = []
        method_leaves = set()
        seen = set()
        # Obfuscators routinely lowercase/randomise class names. Capitalisation
        # is only a fallback heuristic; a native code object without
        # CO_NEWLOCALS is direct evidence of a class namespace body and makes
        # its name a valid qualname owner regardless of spelling.
        _proven_class_names = {
            str(co.get('name')) for co in (self.code_objects or ())
            if co and co.get('name') and not str(co.get('name')).startswith('<')
            and not (int(co.get('flags') or 0) & 0x02)
            and self._is_valid_def_name(str(co.get('name')))
        }
        for c in self.constants:
            if not isinstance(c, str) or '.' not in c:
                continue
            if c.endswith(('.py', '.pyc')) or ' ' in c:
                continue
            # A qualname containing '<locals>' is a CLOSURE (def-in-def), NEVER a
            # direct class method. Nuitka names each enclosing method's nested
            # closures identically -- e.g. ModernGUI.start_craft.<locals>.read_output
            # AND ModernGUI.start_farmer.<locals>.read_output. The old code did
            # `raw = c.replace('.<locals>', '')`, which collapsed BOTH to
            # 'ModernGUI.start_craft.read_output' / '...start_farmer.read_output'
            # and then to leaf 'read_output' on ModernGUI, so every bot-launcher's
            # thread closures (run/read_output/read_error/wait_process) were emitted
            # 5x as DUPLICATE class methods. Closures belong inside their enclosing
            # method's body, not as top-level class methods -- so skip them here.
            # (Safe & universal: in Python a real Class.method qualname NEVER
            # contains '<locals>'/'<lambda>'/'<listcomp>'/'<genexpr>'.)
            if any(_m in c for _m in
                   ('<locals>', '<lambda>', '<listcomp>', '<dictcomp>',
                    '<setcomp>', '<genexpr>')):
                continue
            raw = c
            if '<' in raw or '>' in raw:
                continue
            parts = raw.split('.')
            if len(parts) < 2 or not all(self._is_ident(p) for p in parts):
                continue
            owner = parts[0]
            leaf = parts[-1]
            if owner in self._PACKAGE_MACHINERY_NAMES:
                # Package/bootstrap attributes can carry dotted names that
                # look like class methods (``environ.foo``/``path.join``),
                # but their owner is runtime machinery, never a user class.
                continue
            # A capitalised owner looks like a class. A lowercase/obfuscated
            # owner is accepted only when its native class-body code object
            # proves class ownership; otherwise it remains a module/attribute
            # path and is rejected.
            if not owner[:1].isupper() and owner not in _proven_class_names:
                continue
            # A Capitalised owner that is a known MODULE name (e.g. `PySide6` in
            # `PySide6.QtCore` from `from PySide6 import QtCore`) is an import
            # path, NOT a class — without this it becomes a phantom
            # `class PySide6(...):`. Universal: keys off the recovered module
            # table only. (`object`/builtins owners stay; they aren't modules.)
            if any(p == owner or p.startswith(owner + '.')
                   for p in self.known_modules):
                continue
            # Skip the metaclass plumbing Nuitka emits for every class body.
            if leaf in ('__class__', '__prepare__', '__mro_entries__'):
                continue
            # Owner and leaf must be legal identifiers we can emit.
            if not (self._is_valid_def_name(owner) and self._is_valid_def_name(leaf)):
                continue
            if raw in seen:
                continue
            seen.add(raw)
            if owner not in class_order:
                class_order.append(owner)
            method_leaves.add(leaf)
            methods.append({
                '_type': 'CodeObject', 'name': leaf, 'qualname': raw,
                'args': [], 'argcount': 0, 'kwonly': 0, 'posonly': 0,
                'flags': 0, 'line': 0, '_source': 'qualname',
            })
        return methods, class_order, method_leaves

    def _import_tuple_positions(self):
        """Indices of ident-tuples that are `from X import (...)` name lists.

        Such a tuple is immediately preceded (within 1-2 slots) by a module
        name string. We use this to AVOID mistaking import-name tuples for
        class-base tuples.
        """
        positions = set()
        for i, c in enumerate(self.constants):
            if not self._is_varnames_tuple(c):
                continue
            for back in (1, 2):
                j = i - back
                if j < 0:
                    break
                p = self.constants[j]
                if isinstance(p, str) and self._is_ident(p) and p[:1].islower():
                    positions.add(i)
                    break
        return positions

    def _scan_class_bases(self, class_order, method_leaves):
        """Best-effort base-class tuple for each detected class.

        Nuitka only emits the `__orig_bases__` marker for classes that have
        EXPLICIT bases, so we use its presence as the gate: no marker => no
        class in this module inherits => assign nothing (avoids inventing
        bases for plain `class X:` definitions).

        When bases DO exist, the bases tuple is a small CamelCase-only ident
        tuple (e.g. ``('CryptoBase',)``). It often coincides with a
        `from .base import CryptoBase` import-names tuple (deduped), so unlike
        free-function detection we must NOT exclude import tuples here. Among
        candidates we prefer the SMALLEST (base lists are short) and assign to
        a class by source proximity.
        """
        if '__orig_bases__' not in self.constants or not class_order:
            return {}
        # IMPORT-NAME EXCLUSION: a `from bs4 import BeautifulSoup` value-import
        # emits a (module-name, names...) tuple in the const pool whose names are
        # CamelCase (BeautifulSoup, AsyncClient, ...). Without excluding them the
        # proximity assigner below mistakes such a single-element tuple for a
        # class base and invents `class Scraper(BeautifulSoup):` for a class that
        # really inherits nothing. Real bases are classes DEFINED in this module
        # (or builtin/known base types), never import-target bindings. Reuse the
        # exact import-name gather from _scan_free_functions so the two agree.
        import_names = set()
        try:
            import_tuple_pos = self._import_tuple_positions()
        except Exception:
            import_tuple_pos = set()
        for i, c in enumerate(self.constants):
            if not isinstance(c, str):
                continue
            nxt = self.constants[i + 1] if i + 1 < len(self.constants) else None
            if (self._is_ident(c) and isinstance(nxt, tuple) and nxt
                    and all(isinstance(x, str) for x in nxt)
                    and (i + 1) in import_tuple_pos):
                import_names.add(c)
                for x in nxt:
                    import_names.add(x)
        # Credibility set: a CamelCase token is a believable base class only if
        # it is a class DEFINED in this module (intra-module inheritance, e.g.
        # `class Admin(User):` where both are local), or a known builtin/stdlib
        # base type. Everything else (import targets, stdlib exceptions like
        # ValueError/TypeError in a multi-member tuple, Qt module names like
        # QtCore/QtGui, single-word docstring/label fragments) must never be
        # assigned as a base — the proximity matcher has no way to distinguish
        # them from real bases, so "omit when unsure" is always safer than
        # inventing `class X(ValueError):` for a class that really inherits
        # object. `class_order` is the authoritative list of classes detected in
        # THIS module (passed in by the caller), available even though
        # self.classes is populated later.
        _defined_class_names = set(class_order)
        _BUILTIN_BASE_TYPES = frozenset({
            'object', 'type',
            'bool', 'int', 'float', 'complex', 'str', 'bytes', 'bytearray',
            'list', 'tuple', 'set', 'frozenset', 'dict', 'range',
            'Enum', 'IntEnum', 'Flag', 'IntFlag',
            'ABC', 'ABCMeta', 'Generic', 'TypedDict', 'NamedTuple',
            'Thread', 'RLock', 'Lock', 'Event', 'Condition',
            'Future', 'Task', 'Coroutine',
            'TestCase', 'IsolatedAsyncioTestCase', 'TestCase',
            'Mock', 'MagicMock', 'AsyncMock',
            'field',
        })
        # Concrete exception classes are credible as a SINGLE base (`class
        # MyError(ValueError):`) but a TUPLE of only exceptions is almost always
        # an `except (A, B):` handler, never inheritance. Used to reject
        # multi-member all-exception base tuples.
        _EXCEPTION_TYPES = frozenset({
            'Exception', 'BaseException', 'ValueError', 'TypeError',
            'KeyError', 'AttributeError', 'RuntimeError', 'StopIteration',
            'StopAsyncIteration', 'NotImplementedError', 'OSError', 'IOError',
            'FileNotFoundError', 'PermissionError', 'ArithmeticError',
            'ZeroDivisionError', 'OverflowError', 'LookupError', 'IndexError',
            'NameError', 'AssertionError', 'Warning', 'UserWarning',
            'DeprecationWarning', 'RuntimeWarning', 'ResourceWarning',
            'UnicodeError', 'UnicodeDecodeError', 'UnicodeEncodeError',
            'MemoryError', 'RecursionError', 'SystemExit', 'KeyboardInterrupt',
            'GeneratorExit', 'TimeoutError', 'ConnectionError',
            'BrokenPipeError', 'ConnectionResetError', 'ConnectionRefusedError',
            'ConnectionAbortedError', 'FileExistsError', 'IsADirectoryError',
            'NotADirectoryError', 'InterruptedError', 'BlockingIOError',
            'ChildProcessError', 'ProcessLookupError', 'EOFError', 'ImportError',
            'ModuleNotFoundError', 'NotImplemented', 'RecursionError',
        })
        # Stdlib module names that appear as CamelCase-ish or capitalized tokens
        # in tuples but are MODULES, never base classes (Qt submodules are the
        # classic case: (QtCore, QtGui, QtWidgets) is the `from PySide6 import
        # ...` names tuple, not a bases tuple).
        _MODULE_NAME_TOKENS = frozenset({
            'QtCore', 'QtGui', 'QtWidgets', 'QtTest', 'QtNetwork', 'QtSql',
            'QtSvg', 'QtXml', 'QtMultimedia', 'QtPrintSupport', 'QtConcurrent',
            'QtQml', 'QtQuick', 'QtQuickWidgets', 'QtCharts', 'QtDataVisualization',
            'QtWebEngineWidgets', 'QtWebEngineCore', 'QtWebChannel',
            'QtOpenGL', 'QtBluetooth', 'QtPositioning', 'QtLocation',
            'QtSensors', 'QtSerialPort', 'QtWebSockets',
        })

        def _credible_base(name):
            # The proximity matcher cannot prove INHERITANCE — it only sees that
            # a CamelCase tuple sits near a class name in the constant pool. For
            # one-file / multi-DLL binaries that is exactly where import-names
            # tuples land too, so an import target is NOT credible evidence of a
            # base (it would invent `class X(ExampleDialog):` from a
            # `from web_login_dialog import ExampleDialog`). The ONLY base this
            # scan can prove is a class DEFINED in this same module (intra-module
            # inheritance, e.g. `class Admin(User):` where both are local) —
            # external qualified bases (QtWidgets.QDialog) are recovered by the
            # disasm path, not here. Builtins (object/Enum/...) and a single
            # concrete exception (`class MyErr(ValueError):`) are the sole safe
            # exceptions; multi-exception tuples are killed separately above.
            if name in _defined_class_names:
                return True
            if name in _BUILTIN_BASE_TYPES:
                return True
            if name in _EXCEPTION_TYPES:
                return True
            return False

        base_tuples = []   # (pos, [names], size)

        def _is_compound_camel_base(name):
            # A real base class is either a qualified path (handled elsewhere)
            # or a COMPOUND CamelCase name (ResourceManager, ExampleDialog).
            # A single-word capitalized token (Logs, Manual, Auto, Algorithm)
            # is almost always a docstring fragment / button label that the
            # proximity assigner mistakes for a base. Require ≥2 capitalized
            # words (an internal case transition) for a lone base candidate.
            return bool(re.search(r'[a-z0-9][A-Z]', name[1:])
                        or re.search(r'[A-Z]{2,}[a-z]', name[1:]))

        for i, c in enumerate(self.constants):
            if not (isinstance(c, tuple) and c):
                continue
            names = list(c)
            if not all(isinstance(n, str) and re.fullmatch(r'[A-Z]\w*', n)
                       for n in names):
                continue
            if names == ['__class__'] or any(n in method_leaves for n in names):
                continue
            # A tuple of stdlib/Qt MODULE-name tokens ((QtCore, QtGui, QtWidgets)
            # from `from PySide6 import ...`) is an import-names list, never a
            # bases tuple. Skip the whole tuple.
            if any(n in _MODULE_NAME_TOKENS for n in names):
                continue
            # A MULTI-member tuple of ONLY exception classes ((ValueError,
            # TypeError) from an `except (A, B):` handler) is never a bases
            # tuple — multiple-inheritance from two concrete exceptions does not
            # occur in real code. Single exception bases (`class E(ValueError):`)
            # remain credible and pass the gate below.
            if len(names) >= 2 and all(n in _EXCEPTION_TYPES for n in names):
                continue
            # CREDIBILITY GATE: every member of a real bases tuple must be a
            # believable base — a class defined here, or a known builtin/base
            # type (incl. a single concrete exception). A single unbelievable
            # member means the tuple is an `except (A, B):` handler's exception
            # list or a co_varnames tuple, NOT inheritance. Rejecting here is
            # what kills `class X(ValueError, TypeError):` / `class
            # X(ExampleDialog):` hallucinations from import-names tuples.
            if not all(_credible_base(n) for n in names):
                continue
            # A single-member tuple of a one-word CamelCase token that is NOT a
            # locally-defined class (Logs, Manual, Auto, Algorithm) is a
            # string-literal fragment, not a base. A locally-defined one-word
            # class (User, Admin) is a legitimate base (`class Admin(User):`)
            # and passes; so do compound/builtin/exception names.
            if (len(names) == 1 and not _is_compound_camel_base(names[0])
                    and names[0] not in _defined_class_names
                    and names[0] not in _BUILTIN_BASE_TYPES
                    and names[0] not in _EXCEPTION_TYPES):
                continue
            base_tuples.append((i, names, len(names)))
        if not base_tuples:
            return {}
        class_pos = {}
        for cls in class_order:
            for i, c in enumerate(self.constants):
                if isinstance(c, str) and (c == cls or c.startswith(cls + '.')):
                    class_pos[cls] = i
                    break
        bases = {}
        used = set()
        # Smallest base tuples first — inheritance lists are short, whereas a
        # broad `from pkg import A, B, C` value-import tuple is longer.
        order = sorted(range(len(base_tuples)), key=lambda k: base_tuples[k][2])
        for cls in class_order:
            anchor = class_pos.get(cls, 0)
            best = None
            for k in order:
                if k in used:
                    continue
                pos, names, size = base_tuples[k]
                d = (size, abs(pos - anchor))
                if best is None or d < best[0]:
                    best = (d, k, names)
            if best is not None:
                used.add(best[1])
                bases[cls] = best[2]
        return bases

    def _scan_free_functions(self, class_names, method_leaves):
        """Module-level (free) function names.

        A free function name is a snake/camelCase ident that is NOT:
          * a method leaf (already emitted inside its class),
          * a class name,
          * a member of ANY ident-tuple — those are co_varnames/locals or
            `from X import (...)` targets, never a def at this level,
          * a known attribute / dunder / stdlib module / common keyword.
        This single "appears inside a tuple ⇒ not a top-level def" rule is
        what kills the bulk of the old broad-scan noise (locals and import
        targets inside ident-tuples in a re-exporting __init__).
        """
        import builtins as _bi
        leaf = self.module_name.split('.')[-1] if self.module_name else ''
        tuple_members = set()
        for c in self.constants:
            if isinstance(c, tuple):
                for x in c:
                    if isinstance(x, str):
                        tuple_members.add(x)
        # Names that are imported (module names + `from X import (names)`
        # targets) are bindings, not defs in THIS module. Strip them so an
        # `import colorama` / `from threading import Lock` doesn't surface as
        # `def colorama(...)` / `def Lock(...)`.
        import_tuple_pos = self._import_tuple_positions()
        import_names = set()
        for i, c in enumerate(self.constants):
            if not isinstance(c, str):
                continue
            nxt = self.constants[i + 1] if i + 1 < len(self.constants) else None
            if (self._is_ident(c) and isinstance(nxt, tuple) and nxt
                    and all(isinstance(x, str) for x in nxt)
                    and (i + 1) in import_tuple_pos):
                import_names.add(c)
                for x in nxt:
                    import_names.add(x)
        blacklist = (set(self._NON_FUNCTION_NAMES) | set(self._COMMON_STDLIB)
                     | set(dir(_bi)) | import_names | {
            leaf, 'self', 'cls', 'args', 'kwargs', 'data', 'value', 'key',
            'name', 'item', 'items', 'obj', 'result', 'error', 'exc',
            'config', 'session', 'token', 'url', 'response', 'request',
            'param', 'params', 'print',
        })
        lo, hi = self._definition_region()
        free = []
        seen = set()
        for i, c in enumerate(self.constants):
            if not isinstance(c, str) or c in seen:
                continue
            # Only the def/class region — discards the early attribute-name
            # block (datetime.now, file.readlines, os.getcwd …).
            if not (lo <= i < hi):
                continue
            # snake_case or camelCase, must START lowercase/underscore so we
            # never grab ClassNames or ALL_CAPS constants, and must be a legal
            # def name (rejects keywords like `return`, `class`, `https`).
            if not re.fullmatch(r'[a-z_][A-Za-z0-9_]*', c):
                continue
            if len(c) < 2 or not self._is_valid_def_name(c):
                continue
            # Dunder names (`__prepare__`, `__orig_bases__`, `__mro_entries__`)
            # are class-creation machinery Nuitka emits, never module defs.
            if c.startswith('__') and c.endswith('__'):
                continue
            if (c in blacklist or c in tuple_members
                    or c in method_leaves or c in class_names):
                continue
            seen.add(c)
            free.append({
                '_type': 'CodeObject', 'name': c, 'qualname': c,
                'args': [], 'argcount': 0, 'kwonly': 0, 'posonly': 0,
                'flags': 0, 'line': 0, '_source': 'free',
            })
        return free

    def _assign_args_by_order(self, funcs):
        """Attach a co_varnames tuple (args+locals) to each function.

        Both a function's identifying string and its co_varnames tuple live in
        the definition region in source order, so we pair them positionally.
        For a method we anchor on its UNIQUE dotted qualname position
        (``Class.method``) rather than the bare name, which also appears early
        as an attribute-access constant and would mis-order the pairing.
        """
        lo, hi = self._definition_region()
        import_tuples = self._import_tuple_positions()

        anchors = []   # (position, func)
        for f in funcs:
            key = f.get('qualname') if f.get('_source') == 'qualname' else f.get('name')
            pos = None
            for i, c in enumerate(self.constants):
                if c == key and lo - 4 <= i:
                    pos = i
                    break
            if pos is None:
                # fall back to first occurrence of the bare name anywhere
                for i, c in enumerate(self.constants):
                    if c == f.get('name'):
                        pos = i
                        break
            if pos is not None:
                anchors.append((pos, f))

        tuple_positions = sorted(
            i for i, c in enumerate(self.constants)
            if self._is_varnames_tuple(c) and i not in import_tuples)

        anchors.sort(key=lambda t: t[0])
        for k in range(min(len(anchors), len(tuple_positions))):
            f = anchors[k][1]
            tup = self.constants[tuple_positions[k]]
            if not f['args']:
                f['args'] = list(tup)
                f['argcount'] = len(tup)

    def _infer_code_objects_from_constants(self):
        """Primary inference for C-compiled modules (no 'C' tags in blob).

        Returns (code_objects, class_order, bases_map).
        """
        methods, class_order, method_leaves = self._scan_qualnames()
        class_names = set(class_order)
        free = self._scan_free_functions(class_names, method_leaves)
        code_objects = methods + free
        # Attach recovered co_varnames (args + locals) to each function.
        # CAVEAT: Nuitka does not store these tuples in source/definition
        # order, so positional pairing can attach a function the locals of a
        # sibling, and we cannot split args from locals without the native
        # MAKE_CODE_OBJECT argcount. We still surface them because they are
        # the real identifier names from the source — far more useful to a
        # reverse engineer than an empty signature. `render()` labels them as
        # approximate.
        self._assign_args_by_order(code_objects)
        bases = self._scan_class_bases(class_order, method_leaves)
        return code_objects, class_order, bases

    def _merge_native_code_objects(self, native):
        """Combine EXACT native-recovered code objects (co_name, co_argcount,
        co_varnames, co_flags from the PyCode_New* call sites) with the dotted
        co_qualname constants that give class membership.

        Native objects carry the truth for signatures; the constant pool's
        `Class.method` qualnames tell us which class each method belongs to.
        co_flags' CO_NEWLOCALS bit (0x02) distinguishes real functions from
        module/class *bodies* (which Nuitka also builds code objects for).
        """
        CO_NEWLOCALS = 0x02
        methods, class_order, method_leaves = self._scan_qualnames()
        bases = self._scan_class_bases(class_order, method_leaves)
        class_names = set(class_order)
        leaf_owner = {}
        for m in methods:
            leaf_owner.setdefault(m['name'], m['qualname'].split('.')[0])

        # Recover obfuscated/lowercase classes whose dotted co_qualnames were
        # stripped.  Each class contributes an __init__ code object, while its
        # methods retain source lines and a leading self/cls parameter.  When
        # native metadata contains more distinct __init__ definitions than the
        # qualname scan found classes, pair the surplus source interval with an
        # otherwise-unexplained mixed-case module global. This is structural
        # evidence (class deficit + constructor boundary + method receiver), not
        # a capitalization guess.
        _init_cos = sorted(
            (co for co in native if co.get('name') == '__init__'
             and int(co.get('line') or co.get('firstlineno') or 0) > 0),
            key=lambda co: int(co.get('line') or co.get('firstlineno') or 0))
        _qualified_init_owners = {
            str(m.get('qualname')).split('.')[0] for m in methods
            if m.get('name') == '__init__' and '.' in str(m.get('qualname') or '')
        }
        _class_deficit = max(
            0, len(_init_cos) - len(_qualified_init_owners))
        _native_names = {str(co.get('name')) for co in native if co.get('name')}
        _hidden_candidates = []
        for _g in sorted(self.module_globals):
            if not isinstance(_g, str) or not self._is_valid_def_name(_g):
                continue
            if (_g in class_names or _g in _native_names or _g.startswith('_')
                    or _g in self.known_modules):
                continue
            # Obfuscated class identifiers characteristically mix cases; plain
            # lowercase globals remain data/functions and are not promoted.
            if not (_g[:1].islower()
                    and any(ch.islower() for ch in _g)
                    and any(ch.isupper() for ch in _g)):
                continue
            _hidden_candidates.append(_g)
        _hidden_owner_by_id = {}
        if _class_deficit and len(_hidden_candidates) == _class_deficit:
            _surplus_inits = _init_cos[-_class_deficit:]
            for _idx, (_cls, _ico) in enumerate(zip(
                    _hidden_candidates, _surplus_inits)):
                _start = int(_ico.get('line') or _ico.get('firstlineno') or 0)
                _end = (int(_surplus_inits[_idx + 1].get('line')
                            or _surplus_inits[_idx + 1].get('firstlineno') or 0)
                        if _idx + 1 < len(_surplus_inits) else 1 << 30)
                class_order.append(_cls)
                class_names.add(_cls)
                for _co in native:
                    _line = int(_co.get('line') or _co.get('firstlineno') or 0)
                    _vn = list(_co.get('varnames') or _co.get('args') or ())
                    if (_start <= _line < _end
                            and (_co is _ico or (_vn and _vn[0] in ('self', 'cls')))
                            and not str(_co.get('name') or '').startswith('<')):
                        _hidden_owner_by_id[id(_co)] = _cls
                        # Propagate the proven owner to the shared native
                        # metadata. Later body matching and placeholder pruning
                        # consume the original `cos`, not the copied skeleton
                        # node; keeping this only in `nc` silently deleted valid
                        # hidden-class methods at the final pass.
                        _hq = '%s.%s' % (_cls, str(_co.get('name') or ''))
                        _co['_match_qualname'] = _hq

        out = []
        covered = set()        # qualnames already emitted from native data
        self._class_docstrings = {}
        for co in native:
            name = co.get('name') or ''
            flags = co.get('flags') or 0
            if name.startswith('<'):
                continue                      # module body
            if not (flags & CO_NEWLOCALS):
                # class body (or other namespace block): register the class,
                # don't emit it as a function. co_consts[0] is its docstring.
                if (name in self.known_modules
                        or name in self._PACKAGE_MACHINERY_NAMES):
                    # A package initializer can expose its module name or a
                    # runtime namespace block through the same flag shape as a
                    # class body.  The module table is authoritative here.
                    continue
                if self._is_valid_def_name(name):
                    if name not in class_names:
                        class_order.append(name)
                        class_names.add(name)
                    if co.get('docstring'):
                        self._class_docstrings[name] = co['docstring']
                continue
            if not self._is_valid_def_name(name):
                continue
            nc = dict(co)
            if id(co) in _hidden_owner_by_id:
                nc['qualname'] = '%s.%s' % (
                    _hidden_owner_by_id[id(co)], name)
            elif (co.get('_makeobj') and
                  isinstance(co.get('qualname'), str) and
                  (co.get('qualname') == name or
                   co.get('qualname').endswith('.' + name))):
                # CPython 3.11+ passes co_qualname explicitly to the shared
                # makeCodeObject helper.  It is an exact identity, and must win
                # over the legacy leaf_owner map: common duplicate leaves such
                # as __init__/run/check_filter otherwise all collapse onto the
                # first class and the remaining classes are backfilled with
                # inferred ``self``-only signatures.
                nc['qualname'] = co.get('qualname')
            elif co.get('_match_qualname'):
                # Override disambiguation (local-count match) already resolved the
                # exact owning class for this co — trust it over leaf_owner.
                nc['qualname'] = co['_match_qualname']
            else:
                owner = leaf_owner.get(name)
                nc['qualname'] = f"{owner}.{name}" if owner else name
            # An overridden leaf (same method name in several subclasses) yields
            # several native cos that all resolve to the base via leaf_owner.
            # Emit only the FIRST under the base class; the remaining override
            # copies are added by the backfill below under their OWN classes
            # (from the dotted qualname constants) and filled from
            # bodies[Class.method] at injection time. Without this skip the base
            # class got 3 identical `handle` methods (complex method).
            if nc['qualname'] in covered:
                continue
            covered.add(nc['qualname'])
            out.append(nc)

        # Native recovery can miss a code object (creator not reached, base
        # not solved). Backfill any method seen in the dotted-qualname
        # constants that native didn't cover, so class method LISTS stay
        # complete (these get a conservative signature, not an exact one).
        for m in methods:
            if m['qualname'] not in covered:
                out.append(m)
                covered.add(m['qualname'])
        # A method-less class can be absent from the dotted-qualname scan, but
        # its namespace header is still a native class-body proof.  Recompute
        # bases after registering those native class bodies so an exception or
        # marker class does not silently lose its declared base.
        if class_order:
            bases = self._scan_class_bases(class_order, method_leaves)
        return out, class_order, bases

    def _broad_scan_function_names(self):
        """Return every plausible function-name ident in the constants.

        A plausible function name is an ident that:
          * is lowercase or snake_case (not ALL_CAPS, not CamelCase —
            those are classes/constants, handled separately),
          * is at least 3 chars long,
          * isn't in _NON_FUNCTION_NAMES,
          * isn't an arg-name-like common word (self, args, kwargs, etc.),
          * isn't the leaf of this module's own name.

        Pairing with co_varnames happens in `_repair_name_args_by_order`.
        """
        leaf = self.module_name.split('.')[-1] if self.module_name else ''
        blacklist = set(self._NON_FUNCTION_NAMES) | {leaf} | {
            'self', 'cls', 'args', 'kwargs', 'data', 'value', 'key',
            'name', 'item', 'items', 'obj', 'result', 'error', 'e', 'exc',
            'config', 'session', 'token', 'url', 'response', 'request',
            'param', 'params',
            'print', 'bool', 'str', 'int', 'float', 'list', 'tuple', 'dict',
            'set', 'type', 'range', 'len', 'sum', 'min', 'max', 'map',
            'filter', 'sorted', 'reversed', 'all', 'any',
        }

        candidates = []
        seen = set()
        for c in self.constants:
            if not isinstance(c, str):
                continue
            if c in seen or c in blacklist:
                continue
            if not re.fullmatch(r'[a-z_][a-z0-9_]*', c):
                continue
            if len(c) < 3:
                continue
            # Reject strings that end in '.py' or contain . or \ (filenames)
            if '.' in c or '\\' in c or '/' in c:
                continue
            seen.add(c)
            candidates.append({
                '_type': 'CodeObject',
                'name': c,
                'qualname': c,
                'args': [],
                'argcount': 0,
                'kwonly': 0,
                'posonly': 0,
                'flags': 0,
                'line': 0,
                '_source': 'broad-scan',
            })
        return candidates

    def _repair_name_args_by_order(self, code_objects):
        """Re-pair function NAMES with co_varnames TUPLES by source-code order.

        Nuitka's constants blob lays out per-function data like this (this
        is not a hard contract but holds for every real binary we've seen):

            str 'func1'                 <- at list index i1
            str 'func2'                 <- at list index i2
            ...
            str 'funcN'
            str '<module>.py' / '<module ...>'   <- filename/qualname marker
            tuple(varnames of func1)    <- at list index j1, usually i1 < jk
            tuple(varnames of func2)
            ...
            tuple(varnames of funcN)

        Names appear in source declaration order in a contiguous run, and
        the co_varnames tuples appear in the SAME relative order after a
        filename anchor. So we can re-pair them positionally by:
          1. collecting every candidate function-name string and its position,
          2. collecting every ident-tuple and its position,
          3. sorting both lists by position,
          4. matching name[k] <-> tuple[k] (clipped to min length).
        """
        # Candidate function names from the inferrer's preliminary pass
        candidate_names = []
        name_seen = set()
        for co in code_objects:
            n = co.get('name') or ''
            if n and re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', n) and n not in name_seen:
                name_seen.add(n)
                candidate_names.append(n)

        # Collect positions
        name_positions = []
        for i, c in enumerate(self.constants):
            if isinstance(c, str) and c in name_seen:
                name_positions.append((i, c))

        tuple_positions = []
        for i, c in enumerate(self.constants):
            if (isinstance(c, tuple) and c
                    and all(isinstance(x, str) and
                            (x == '.0' or re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', x))
                            for x in c)):
                tuple_positions.append((i, c))

        # Sort by position and pair 1:1 in order. Because names appear in
        # the same source order as their varnames tuples, index k of the
        # name list maps to index k of the tuple list.
        name_positions.sort()
        tuple_positions.sort()
        paired = {}
        limit = min(len(name_positions), len(tuple_positions))
        for k in range(limit):
            _, name = name_positions[k]
            _, tup = tuple_positions[k]
            # Don't overwrite a name that already has a good pairing —
            # keep the FIRST (leftmost) occurrence so we preserve source order.
            paired.setdefault(name, tup)

        # Rebuild code_objects with the repaired pairings
        result = []
        for co in code_objects:
            name = co.get('name') or ''
            new_co = dict(co)
            if name in paired:
                tup = paired[name]
                new_co['args'] = list(tup)
                new_co['argcount'] = len(tup)
            result.append(new_co)
        return result

    def _classify(self):
        self.classes = {}   # class_name -> {'methods': [co], 'bases': [...]}
        self.free_funcs = []
        self.module_body = None

        # Pre-register every class discovered via qualname scanning so a class
        # with no detected methods (or whose methods were filtered) still gets
        # emitted, and so base lists are available.
        bases_map = getattr(self, '_inferred_bases', {}) or {}
        for cls in (getattr(self, '_inferred_classes', None) or []):
            self.classes.setdefault(cls, {'methods': [], 'bases': []})
            if cls in bases_map:
                self.classes[cls]['bases'] = list(bases_map[cls])

        for co in self.code_objects:
            if not co:
                continue
            name = co.get('name') or ''
            qualname = co.get('qualname') or name

            if name == '<module>' or qualname == '<module>':
                self.module_body = co
                continue

            if name in ('<listcomp>', '<dictcomp>', '<setcomp>',
                        '<genexpr>', '<lambda>'):
                continue

            # qualname like "ClassName.method" => method. Handle nested
            # `<locals>` paths ("Outer.inner.<locals>.method" => stops at Outer)
            qn = str(qualname)
            parent = None
            leaf = name
            if '.' in qn and not qn.startswith('<'):
                parts = qn.split('.<locals>.')[0].split('.')
                if (len(parts) >= 2 and parts[0]
                        and (parts[0][0].isupper()
                             or parts[0] in self.classes
                             or parts[0] in (getattr(
                                 self, '_inferred_classes', None) or ()))):
                    parent = parts[0]
                    leaf = parts[-1]

            # A capitalised qualname prefix that is a known MODULE name (e.g.
            # `PySide6.QtCore` from `from PySide6 import QtCore`) is an IMPORT
            # construct, not a class — emitting it as `class PySide6(...):` is a
            # phantom. Module-init imports/globals are already emitted at module
            # scope, so drop this redundant code object. Universal: keys off the
            # recovered module table, never a sample-specific name.
            if parent and parent in self.known_modules:
                continue

            if parent:
                if parent not in self.classes:
                    self.classes[parent] = {
                        'methods': [], 'bases': list(bases_map.get(parent, []))}
                self.classes[parent]['methods'].append(co)
            else:
                # Drop package/module-init machinery misrecovered as a top-level
                # function (path/dirname/join/environ/submodule_search_locations).
                if leaf in self._PACKAGE_MACHINERY_NAMES:
                    continue
                self.free_funcs.append(co)

    # ---- import recovery ----

    # Stdlib modules that routinely show up as bare imports in the blob.
    # We only accept a BARE ident as a module name if it's in this set —
    # otherwise we'd mistake every function/attribute name for an import.
    _COMMON_STDLIB = {
        'sys', 'os', 're', 'json', 'time', 'struct', 'ctypes',
        'hashlib', 'hmac', 'base64', 'random', 'binascii',
        'threading', 'asyncio', 'typing', 'datetime', 'math',
        'itertools', 'functools', 'copy', 'io', 'traceback',
        'collections', 'pathlib', 'socket', 'ssl', 'subprocess',
        'warnings', 'logging', 'signal', 'platform', 'pickle',
        'codecs', 'enum', 'abc', 'inspect', 'importlib', 'weakref',
        'urllib', 'http', 'email', 'concurrent', 'decimal',
        'queue', 'uuid', 'bisect', 'heapq', 'operator', 'atexit',
        'contextlib', 'dataclasses', 'gc', 'glob', 'shutil',
        'stat', 'string', 'textwrap', 'tempfile', 'zipfile',
        'zlib', 'gzip', 'bz2', 'lzma', 'csv', 'xml', 'html',
        'token', 'tokenize', 'types', 'typing_extensions',
        # extremely common third-party HTTP / utility packages
        'requests', 'aiohttp', 'httpx', 'yarl', 'six',
    }

    def detect_imports(self):
        """Return a list of `import ...` / `from ... import ...` statements.

        Pattern used by Nuitka's C-compiled code generator:
           str  <module_name>
           tuple (<imported_name>, ...)        # co_names of the import
           str  <imported_name>                # the IMPORT_FROM names
           (str <alias>                        # STORE_NAME if `as` was used)
        We recognise a module STRING only when it either
          * contains a '.' (dotted path, unambiguously a module), OR
          * is followed immediately by a tuple-of-idents (= the `from X
            import (A, B)` names tuple), OR
          * is one of a small whitelist of stdlib modules.
        This avoids turning every bare identifier like `session`, `print`
        or `payload` into a bogus `import session` line.
        """
        lines = []
        used = set()
        n = len(self.constants)

        # Build the set of names that appear in ANY ident-tuple. Those are
        # co_varnames / argument names from other functions in the same
        # module — they're NOT importable module names, even though they
        # show up next to a tuple-of-idents.
        arg_names_in_tuples = set()
        for c in self.constants:
            if isinstance(c, tuple) and c:
                for x in c:
                    if isinstance(x, str) and re.fullmatch(r'[a-z_][a-z0-9_]*', x):
                        arg_names_in_tuples.add(x)

        # Common method/function names that often appear as string+tuple
        # pairs because they're `obj.method(**kwargs)` calls, NOT imports.
        # Filtering these avoids spurious `from dumps import sort_keys, default`
        # when the real code is `json.dumps(..., sort_keys=True, default=json_serial)`.
        METHOD_CALL_ARTIFACTS = {
            'dumps', 'loads', 'dump', 'load',
            'get', 'post', 'put', 'delete', 'patch', 'head', 'options',
            'request', 'send', 'open', 'write', 'read',
            'sha256', 'sha1', 'sha512', 'md5', 'hmac', 'new', 'digest',
            'hexdigest', 'encode', 'decode', 'verify', 'sign',
            'format', 'split', 'join', 'strip', 'replace', 'startswith',
            'endswith', 'find', 'index', 'count', 'upper', 'lower',
            'items', 'keys', 'values', 'update', 'append', 'pop',
            'extend', 'insert', 'remove', 'clear', 'copy', 'sort',
            'reverse', 'add', 'discard', 'isdigit', 'isalpha',
        }

        # Data-file extensions: a string like `mnemonic_phrases.txt` matches the
        # dotted-name regex but is a FILENAME, not a module.
        _DATA_EXTS = ('.py', '.pyc', '.pyd', '.txt', '.json', '.cfg', '.ini',
                      '.dat', '.log', '.csv', '.md', '.html', '.htm', '.xml',
                      '.yaml', '.yml', '.toml', '.png', '.jpg', '.jpeg', '.gif',
                      '.ico', '.exe', '.dll', '.so', '.zip', '.gz', '.db',
                      '.sqlite', '.bin', '.tmp', '.bak', '.lock', '.env')

        def is_dotted_module(s):
            if not isinstance(s, str) or not (2 < len(s) < 80):
                return False
            if s.lower().endswith(_DATA_EXTS):
                return False
            if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)+', s):
                return False
            parts = s.split('.')
            # reject dunder-containing paths like `foo.__class__`
            if any(p.startswith('__') for p in parts):
                return False
            # Domain names and service hosts are common string constants and
            # satisfy Python's dotted-identifier grammar (`steamcommunity.com`).
            # They are not import paths.
            if parts[-1].lower() in {
                    'com', 'org', 'net', 'io', 'dev', 'app', 'xyz', 'ru',
                    'de', 'it', 'fr', 'uk', 'co', 'me', 'gg', 'tv'}:
                return False
            # reject CamelCase/mixed-case segments — these are overwhelmingly
            # class.method qualnames, not package paths. Exact bundled module
            # names remain allowed below for the rare case-sensitive package.
            first = parts[0]
            _known_exact = s in self.known_modules
            if not _known_exact and any(p != p.lower() for p in parts):
                return False
            if first and first[0].isupper() and not _known_exact:
                return False
            # With a complete Nuitka module table, require positive ownership:
            # exact bundled module, bundled root, or stdlib root. This rejects
            # obfuscated qualnames such as `abcX.method` that happened to start
            # lowercase while preserving requests.*, steampy.*, etc. when they
            # are actually present in the binary.
            if self.known_modules:
                roots = {m.split('.')[0] for m in self.known_modules if m}
                if not (_known_exact or first in roots or first in self._COMMON_STDLIB):
                    return False
            return True

        def is_stdlib_module(s):
            return (isinstance(s, str) and s in self._COMMON_STDLIB)

        def is_ident_tuple(t):
            if not isinstance(t, tuple) or not t or len(t) > 30:
                return False
            return all(isinstance(x, str)
                       and re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', x)
                       for x in t)

        # When we know every module compiled into the binary, a bare lowercase
        # `from X import …` candidate is only credible if X is actually one of
        # those modules (or a package prefix of one). This rejects method/alias
        # names that merely sit next to a tuple — `from urlopen import timeout`,
        # `from colorama_init import config` — while keeping real third-party
        # packages (`third_party_pkg`, `colorama`). With no known-module set we keep
        # the looser legacy behaviour.
        _known_roots = set()
        for _km in self.known_modules:
            _known_roots.add(_km)
            _known_roots.add(_km.split('.')[0])
        _pkg_roots = _known_roots
        # Package whose submodules are addressed by their bare leaf name in a
        # relative import (`from .subpackage import …` stores just `subpackage`).
        if self.is_package:
            _pkg_base = self.module_name
        elif '.' in self.module_name:
            _pkg_base = self.module_name.rsplit('.', 1)[0]
        else:
            _pkg_base = None

        def is_known_module(x):
            if not self.known_modules:
                return True
            if x in _known_roots:
                return True
            # a sibling/submodule of the current package (relative import leaf)
            return bool(_pkg_base and f'{_pkg_base}.{x}' in self.known_modules)

        # ---- sibling/local-import recovery for one-file / multi-DLL binaries ----
        # A Nuitka "onefile" build compiles each application module into its OWN
        # shared object, so THIS module's blob table never lists the siblings it
        # imports (e.g. a __main__ that does `from resource_manager import
        # ResourceManager`). `is_known_module` rejects those because the module
        # name is absent from the (partial) table, which then cascades into
        # hallucinated class bases, `_v()` constructor placeholders and lost
        # `__init__` params.
        #
        # Constant-pool adjacency is unreliable for onefile (Nuitka splits the
        # module string from its import-names tuple across the pool), so the
        # robust, universal signal is NAME SHAPE + USE: when this module USES a
        # CamelCase name as a class base or `Name(...)` constructor that it does
        # NOT define locally, and the snake_case form of that name exists as a
        # lowercase string in the pool, recover `from <snake> import <Camel>`.
        # E.g. `ResourceManager` (used as a ctor, not defined) + `'resource_manager'`
        # present in the pool ⇒ `from resource_manager import ResourceManager`.
        # This never fires for locally-defined classes (they are excluded) and
        # never for lowercase varnames (no CamelCase to map), so the noise gate
        # stays as tight as the legacy rule.

        def _camel_to_snake(name):
            s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', name)
            s = re.sub(r'([a-z\d])([A-Z])', r'\1_\2', s)
            return s.lower()

        # All lowercase ident strings present in the pool (candidate module
        # names). Real sibling modules are bare lowercase idents.
        _lower_idents_in_pool = set()
        for _cv in self.constants:
            if (isinstance(_cv, str)
                    and re.fullmatch(r'[a-z_][a-z0-9_]*', _cv)
                    and len(_cv) >= 3):
                _lower_idents_in_pool.add(_cv)

        # Recover `from <snake> import <Camel>` for every CamelCase name that is
        # USED here as a class base or ctor, NOT defined here, and whose
        # snake_case module name is present in the pool. Because Nuitka's C
        # compilation strips most varnames/ctor evidence at skeleton stage, the
        # strongest universal signal is the constant pool itself: a CamelCase
        # class-like name whose snake_case module string co-occurs in the pool.
        # We require the CamelCase name to look like a CLASS (member of an
        # ident-tuple of CamelCase names — Nuitka's import-names / bases layout —
        # OR used as a recovered base) so that stray capitalized fragments never
        # qualify. This is exactly the evidence that recovered
        # `ResourceManager` above; the same rule recovers every sibling class.
        _sibling_imports = []      # list of (module_name, CamelCase_name)
        _sibling_seen = set()
        _defined_classes = set(
            (getattr(self, 'classes', None) or {}).keys())
        # CamelCase names that appear inside an all-CamelCase ident tuple —
        # Nuitka stores both import-names tuples and class-bases tuples this way.
        # A SINGLE-member CamelCase tuple like ('Auto',) is usually a
        # string-literal label (a button text / title), whereas a single-member
        # tuple of a COMPOUND class name like () is a real
        # import-names list. We accept single-member tuples only for compound
        # CamelCase names (≥2 capitalized words: contains an internal case
        # transition), and accept multi-member tuples unconditionally.
        _camelcase_in_tuple = set()

        def _is_compound_camel(name):
            # ≥2 capitalized words => a class-like name with enough information
            # content to be an import target, not a one-word label. Looks for a
            # lowercase->uppercase or uppercase-run->Upper-lower transition after
            # the first char (e.g. ExampleDialog, ResourceManager => True;
            # Auto, Manual, Logs => False).
            return bool(re.search(r'[a-z0-9][A-Z]', name[1:])
                        or re.search(r'[A-Z]{2,}[a-z]', name[1:]))

        for _cv in self.constants:
            if (isinstance(_cv, tuple) and _cv
                    and all(isinstance(_x, str)
                            and re.fullmatch(r'[A-Z]\w*', _x) for _x in _cv)):
                if len(_cv) == 1 and not _is_compound_camel(_cv[0]):
                    continue  # lone one-word label, not an import-names list
                _camelcase_in_tuple.update(_cv)
        # CamelCase names used as recovered class bases.
        _used_as_base = set()
        for _cd in ((getattr(self, 'classes', None) or {}).values()):
            if isinstance(_cd, dict):
                for _b in (_cd.get('bases') or []):
                    if isinstance(_b, str):
                        _used_as_base.add(_b.split('.')[0])
        # ctor callees from any recovered bodies (empty at pure-skeleton stage).
        _used_as_ctor = set()
        for _co in (getattr(self, '_cos', None) or []):
            if not isinstance(_co, dict):
                continue
            _body = _co.get('body') or _co.get('body_lines') or []
            if isinstance(_body, str):
                _body = _body.splitlines()
            for _bl in (_body or []):
                if not isinstance(_bl, str):
                    continue
                _bm = re.search(r'=\s*([A-Z][A-Za-z0-9_]*)\s*\(', _bl)
                if _bm:
                    _used_as_ctor.add(_bm.group(1))
        _class_like = _camelcase_in_tuple | _used_as_base | _used_as_ctor
        # Generic lowercase words that are far too common to be credible sibling
        # module names (they collide with variables/labels in almost any binary).
        _GENERIC_MODULE_WORDS = frozenset({
            'auto', 'manual', 'data', 'base', 'node', 'item', 'user', 'home',
            'main', 'core', 'utils', 'config', 'types', 'types', 'model',
            'form', 'list', 'table', 'grid', 'page', 'view', 'app', 'run',
            'test', 'info', 'error', 'status', 'value', 'name', 'type',
            'image', 'exception', 'exceptions',
        })
        _BUILTIN_CLASS_NAMES = {
            'Exception', 'BaseException', 'ValueError', 'TypeError',
            'RuntimeError', 'KeyError', 'IndexError', 'AttributeError',
            'ImportError', 'OSError', 'IOError', 'StopIteration',
            'NotImplementedError', 'Image', 'ImageTk',
        }
        for _camel in _class_like:
            if _camel in _defined_classes or _camel in _BUILTIN_CLASS_NAMES:
                continue
            if not re.fullmatch(r'[A-Z]\w*', _camel):
                continue
            _snake = _camel_to_snake(_camel)
            if (_snake in _lower_idents_in_pool
                    and _snake not in self._COMMON_STDLIB
                    and _snake not in METHOD_CALL_ARTIFACTS
                    and _snake not in _GENERIC_MODULE_WORDS):
                _key = (_snake, _camel)
                if _key not in _sibling_seen:
                    _sibling_seen.add(_key)
                    _sibling_imports.append(_key)

        def is_sibling_import_candidate(mod_name, next_tuple):
            """Credible local import for onefile/multi-DLL, keyed off the
            snake_case↔CamelCase USE rule above. Only returns True for module
            names we have positive USE-evidence for."""
            for _mod, _cls in _sibling_imports:
                if _mod == mod_name:
                    if (isinstance(next_tuple, tuple)
                            and _cls in next_tuple):
                        return True
                    return False
            return False

        i = 0
        while i < n:
            c = self.constants[i]
            # Peek forward for an adjacent ident-tuple that looks like
            # an import-names list.
            next_is_tuple = (i + 1 < n and is_ident_tuple(self.constants[i + 1]))

            # Heuristic: a bare lowercase ident followed by a tuple IS an
            # import only when the ident looks like a module (lowercase
            # with underscores, no CamelCase — classes are not modules).
            is_probable_module = (
                isinstance(c, str)
                and re.fullmatch(r'[a-z_][a-z0-9_]*', c)  # all lowercase
                and (len(c) >= 3 or is_known_module(c))   # ≥3 chars, or known sibling
                and c not in ('self', 'args', 'kwargs', 'cls', 'data',
                              'text', 'name', 'value', 'item', 'items',
                              'key', 'keys', 'obj', 'result', 'response',
                              'request', 'url', 'path', 'config', 'token',
                              'print', 'headers', 'status_code',
                              'content', 'origin', 'has_location'))

            # Bare stdlib names like `json` appear as LOAD_ATTR constants for
            # `response.json()` — only emit `import json` in the module-init
            # cluster (near `sys` / sibling-package imports), not mid-pool.
            _import_cluster = 0
            for _ic, _cv in enumerate(self.constants):
                if _cv in ('__cached__', '__spec__', 'sys', 'apis',
                           'proxyconnector', 'random'):
                    _import_cluster = _ic
                    break

            # Reject bare idents that are actually co_varnames somewhere
            # else in the module — they look like module names but aren't.
            if (isinstance(c, str)
                    and c in arg_names_in_tuples
                    and not is_dotted_module(c)
                    and not is_stdlib_module(c)):
                i += 1
                continue

            # Reject well-known method/function names (dumps, sha256, ...)
            # when they're bare — they're method-call LOAD_ATTR constants,
            # not imports.
            if (isinstance(c, str)
                    and c in METHOD_CALL_ARTIFACTS
                    and not is_dotted_module(c)):
                i += 1
                continue

            # Never emit a module importing ITSELF (Nuitka stores the module's
            # own dotted name as a constant; it is not an import statement).
            if isinstance(c, str) and c == self.module_name:
                i += 1
                continue
            # Dunder names (`__cached__`, `__main__`, ...) are module machinery,
            # never an importable module — skip so we don't emit
            # `from __cached__ import config`.
            if isinstance(c, str) and c.startswith('__') and c.endswith('__'):
                i += 1
                continue

            # Stdlib modules that are virtually always used as plain `import X`
            # (never `from X import ...`). A following ident-tuple next to one
            # of these is co_varnames, NOT an import-names list — so we emit
            # the plain import and do NOT consume the tuple (this kills bogus
            # lines like `from json import data`).
            PLAIN_IMPORT = {'sys', 'os', 'json', 're', 'time', 'math', 'random',
                            'struct', 'base64', 'hashlib', 'platform', 'socket',
                            'ctypes', 'io', 'copy', 'gc', 'signal'}

            # String values that appear as dict keys (protocol names, scheme
            # prefixes, etc.) must not be treated as importable module names.
            _DICT_KEY_BLOCKLIST = frozenset({
                'http', 'https', 'ftp', 'data', 'ws', 'wss', 'smtp', 'imap',
                'pop3', 'sftp', 'ssh', 'tcp', 'udp', 'html', 'xml', 'text',
                'utf-8', 'utf8', 'ascii', 'latin-1',
            })
            if isinstance(c, str) and (is_stdlib_module(c) or is_dotted_module(c)
                                       or (next_is_tuple and is_probable_module
                                           and is_known_module(c))
                                       or (next_is_tuple
                                           and is_sibling_import_candidate(
                                               c, self.constants[i + 1]))):
                if c in _DICT_KEY_BLOCKLIST:
                    i += 1
                    continue
                if next_is_tuple and c not in PLAIN_IMPORT:
                    imp = self.constants[i + 1]
                    names = [x for x in imp if not x.startswith('__')]
                    if names:
                        # Single-name `from M import X as Y`: Nuitka lays out
                        # M, (X,), X, Y where Y is the STORE alias (kept in the
                        # module dict). Recover the `as Y` when the const right
                        # after the repeated name is a different stored ident.
                        rendered = ', '.join(names)
                        _alias = self.constants[i + 3] if i + 3 < n else None
                        _after = self.constants[i + 4] if i + 4 < n else None

                        def _struct_marker(v):
                            return (isinstance(v, str)
                                    and (v.endswith(('.py', '.pyc'))
                                         or v.startswith('<module')
                                         or v == '__spec__'))
                        # Names defined as functions/classes in THIS module are
                        # not valid import aliases — the alias would shadow them.
                        _verb_prefixes = ('fetch_', 'get_', 'check_', 'handle_',
                                          'process_', 'start_', 'run_', 'load_',
                                          'save_', 'create_', 'build_', 'emit_')
                        _func_names = {
                            co.get('name', '').split('.')[-1]
                            for co in (getattr(self, '_cos', None) or [])
                            if isinstance(co, dict)
                        }
                        _alias_is_func = (
                            _alias in _func_names
                            if isinstance(_alias, str) else False
                        ) or (
                            isinstance(_alias, str)
                            and any(_alias.startswith(p) for p in _verb_prefixes)
                        )
                        # Never alias an import to another package's top-level
                        # name (``from colorama import init as bs4``) — that is
                        # constant-pool adjacency noise, not a real alias.
                        _KNOWN_PKG_ALIASES = frozenset({
                            'bs4', 'requests', 'colorama', 'colorful', 'json',
                            'sys', 'os', 're', 'time', 'random', 'linecache',
                            'PySide6', 'PyQt5', 'PyQt6', 'QtCore', 'QtGui',
                            'QtWidgets', 'BeautifulSoup', 'cf', 'np', 'pd',
                        })
                        _alias_is_pkg = (
                            isinstance(_alias, str)
                            and (_alias in _KNOWN_PKG_ALIASES
                                 or _alias in _known_roots
                                 or is_stdlib_module(_alias)
                                 or is_dotted_module(_alias))
                        )
                        if (len(names) == 1 and i + 3 < n
                                and self.constants[i + 2] == names[0]
                                and isinstance(_alias, str)
                                and re.fullmatch(r'[A-Za-z_]\w*', _alias)
                                and _alias != names[0]
                                and not _alias.startswith('__')
                                and _alias not in _known_roots
                                and not _alias_is_func
                                and not _alias_is_pkg
                                and (_alias in (self.module_globals or set())
                                     or (not self.module_globals
                                         and _struct_marker(_after)))):
                            rendered = f"{names[0]} as {_alias}"
                        key = f"from {c} import {rendered}"
                        if key not in used:
                            used.add(key)
                            lines.append(f"from {c} import {rendered}")
                    i += 2
                    continue
                # plain `import X` for stdlib / dotted modules (also catches
                # bare `import sys` that has no following import tuple).
                if is_stdlib_module(c) or is_dotted_module(c):
                    if is_stdlib_module(c) and i < _import_cluster:
                        i += 1
                        continue
                    # V100 FIX: i moduli THIRD-PARTY della whitelist ('six',
                    # 'requests', ...) possono arrivare nel pool anche come
                    # SEMPLICI STRINGHE del sorgente (es. return "six"). Un
                    # import reale li vincola nel namespace del modulo, quindi
                    # richiedi l'evidenza del binding quando module_globals e'
                    # noto; se e' ignoto mantieni il comportamento legacy.
                    _THIRDPARTY_WHITELIST = {
                        'requests', 'aiohttp', 'httpx', 'yarl', 'six'}
                    if c in _THIRDPARTY_WHITELIST:
                        # un third-party nel pool e' credibile SOLO con il
                        # binding nel namespace del modulo (module_globals).
                        # La sola posizione nel cluster di init non basta: il
                        # cluster contiene sempre 'sys' della machinery e ogni
                        # stringa successiva passerebbe (es. return "six").
                        if not (self.module_globals
                                and c in self.module_globals):
                            i += 1
                            continue
                    key = f"import {c}"
                    if key not in used:
                        used.add(key)
                        lines.append(f"import {c}")
            i += 1

        # Relative `from .. import config` — Nuitka stores an int level (1/2/3)
        # adjacent to the imported name tuple in the module-init cluster.
        for i in range(n - 2):
            c = self.constants[i]
            if not isinstance(c, int) or c not in (1, 2, 3):
                continue
            nxt = self.constants[i + 1]
            if not (isinstance(nxt, str) and re.fullmatch(r'[A-Za-z_]\w*', nxt)):
                continue
            # V100 FIX: i nomi dunder (`__high__`, `__mid__`, ...) sono chiavi
            # di dict / marker di macchina, MAI simboli importati da un parent.
            # Erano la causa di `from .. import __high__` fabbricato.
            if nxt.startswith('__') and nxt.endswith('__'):
                continue
            prev = self.constants[i - 1] if i else None
            names = None
            if isinstance(prev, tuple) and nxt in prev:
                names = [x for x in prev if isinstance(x, str)
                         and re.fullmatch(r'[A-Za-z_]\w*', x)]
            elif isinstance(prev, str) and prev == nxt:
                names = [nxt]
            if not names:
                continue
            dots = '.' * c
            key = f"from {dots} import {','.join(sorted(names))}"
            if key in used:
                continue
            used.add(key)
            lines.append(f"from {dots} import {', '.join(names)}")

        # Backfill plain `import X` for stdlib / bundled modules the module-init
        # provably imports (X ∈ module_globals) but the positional scan missed
        # because the name sits far from the import cluster (`import json`,
        # `import requests`, `import socks`, `import socket`, …). We skip names
        # that already have an import line and names that look from-imported (a
        # tuple member) so `from datetime import datetime` is never turned into a
        # wrong `import datetime`.
        if self.module_globals:
            covered_mods = set()
            for ln in lines:
                _m1 = re.match(r'^import\s+([A-Za-z_][\w.]*)', ln)
                _m2 = re.match(r'^from\s+\.*([A-Za-z_][\w.]*)\s+import', ln)
                if _m1:
                    covered_mods.add(_m1.group(1).split('.')[0])
                if _m2:
                    covered_mods.add(_m2.group(1).split('.')[0])
            covered_syms = _ndl_parse_imported_symbols(lines)
            tuple_members = set()
            for cc in self.constants:
                if isinstance(cc, tuple):
                    for x in cc:
                        if isinstance(x, str):
                            tuple_members.add(x)
            for name in self.module_globals:
                if (not isinstance(name, str) or name in covered_mods
                        or name in covered_syms or name in tuple_members
                        or name == self.module_name):
                    continue
                if name in self._COMMON_STDLIB or name in _known_roots:
                    key = f"import {name}"
                    if key not in used:
                        used.add(key)
                        lines.append(key)

        # Emit recovered sibling/local imports (onefile / multi-DLL binaries
        # whose module table omits application siblings). Grouped by module so
        # `from resource_manager import ResourceManager, Account` is one line.
        # Only fired when positive USE-evidence was gathered above; never
        # fabricates a binding that is already covered or locally defined.
        if _sibling_imports:
            _covered_syms = _ndl_parse_imported_symbols(lines)
            _sib_by_mod = {}
            for _mod, _cls in _sibling_imports:
                if _cls in _covered_syms or _cls in _defined_classes:
                    continue
                _sib_by_mod.setdefault(_mod, []).append(_cls)
            for _mod in sorted(_sib_by_mod):
                _names = sorted(set(_sib_by_mod[_mod]))
                _line = f"from {_mod} import {', '.join(_names)}"
                _key = f"from {_mod} import {','.join(sorted(_names))}"
                if _key not in used:
                    used.add(_key)
                    lines.append(_line)

        lines = _ndl_qualify_imports(lines, self.module_name,
                                     known_modules=self.known_modules,
                                     is_package=self.is_package)

        if 'typing' in self.constants:
            _imported_symbols = set()
            for _line in lines:
                _match = re.match(r'^\s*from\s+[^ ]+\s+import\s+(.+)$', _line)
                if _match:
                    _imported_symbols.update(
                        part.strip().split(' as ')[-1]
                        for part in _match.group(1).split(','))
            _typing_syms = []
            for _ts in ('List', 'Dict', 'Set', 'Tuple', 'Optional', 'Union',
                        'Any', 'Callable', 'Iterable', 'Mapping', 'Sequence'):
                if _ts in self.constants and _ts not in _imported_symbols:
                    _typing_syms.append(_ts)
            if _typing_syms:
                _tkey = 'from typing import ' + ', '.join(_typing_syms)
                if _tkey not in lines:
                    lines.append(_tkey)

        # Ordering: stdlib < third-party < project-local
        mod_root = self.module_name.split('.')[0] if self.module_name else ''

        def sort_key(line):
            parts = line.split()
            mod = parts[1] if parts else ''
            root = mod.split('.')[0]
            if root in self._COMMON_STDLIB:
                return (0, root, line)
            if mod_root and mod.startswith(mod_root + '.'):
                return (2, mod, line)
            return (1, mod, line)

        lines.sort(key=sort_key)
        return lines

    # ---- function-body heuristics ----

    def _function_string_context(self, args):
        """Pick string constants that look 'related' to this function.

        A crude metric: strings whose value contains one of the arg names,
        or that match URL/http patterns, or that look like error messages.
        """
        urls = []
        messages = []
        keys = []
        for c in self.constants:
            if not isinstance(c, str):
                continue
            low = c.lower()
            if low.startswith(('http://', 'https://')) and len(c) > 12:
                urls.append(c)
            elif len(c) > 30 and (' ' in c and c.count(' ') > 2):
                messages.append(c)
            elif re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]{2,40}', c):
                keys.append(c)
        return urls, messages, keys

    def _guess_body(self, name, args, indent='    '):
        """Return a FAITHFUL placeholder body for a def.

        The original Python body of a C-compiled Nuitka function is not stored
        in the binary (Nuitka translates it to native machine code), so we do
        NOT invent body logic — handing fabricated control flow to someone who
        has no source is worse than nothing. The only body that is exactly
        recoverable here, an `__init__` storing its positional args onto self,
        is emitted by the caller from the native arg list; everything else gets
        an honest placeholder that points at the faithful per-function
        operation trace carried in the matching .nbc file.
        """
        return [f'{indent}pass  # native-compiled body — faithful op trace in the .nbc']

    # ---- emission ----

    @staticmethod
    def _format_docstring(doc, indent):
        """Render a recovered docstring as a triple-quoted block, FAITHFULLY.

        The docstring const captured from the binary already contains the
        source's own embedded newlines and per-line indentation, e.g. the source
            \"\"\"
            Fetches the balance ...
            \"\"\"
        is stored as '\\n    Fetches the balance ...\\n    '. So the byte-exact
        reproduction is simply `{indent}\"\"\"` + doc + `\"\"\"` — we must NOT
        re-indent each interior line (that corrupted the original formatting and
        cost text-sim). Emit one element per physical line so downstream
        line-oriented passes stay well-formed."""
        q = '"""' if '"""' not in doc else "'''"
        if '\n' not in doc:
            return [f'{indent}{q}{doc}{q}']
        parts = doc.split('\n')
        out = [f'{indent}{q}{parts[0]}']     # open quote + text before first \n
        out.extend(parts[1:-1])              # interior lines verbatim (own indent)
        out.append(f'{parts[-1]}{q}')        # last line (own indent) + close quote
        return out

    def _body_trace_lines(self, name, parent, body_indent):
        """Render the recovered body as a clearly-marked comment guide: a
        nested if/else skeleton whose branch CONDITIONS and names/values are
        faithful (recovered from the native code), with best-effort nesting.
        Emitted as comments, never as executable code, so it can never be
        mistaken for a verified reconstruction."""
        if not self.body_traces:
            return []
        seq = None
        for key in ((f'{parent}.{name}',) if parent else ()) + (name,):
            if key in self.body_traces:
                seq = self.body_traces[key]
                break
        if not seq:
            return []
        out = [f'{body_indent}# reconstructed control flow (branch conditions,'
               f' names & values faithful; nesting best-effort):']
        for ln in seq:
            out.append(f'{body_indent}#   {ln}')
        return out

    def _emit_function(self, co, indent='', is_method=False, parent=None):
        name = co.get('name', '?') or '?'

        # Basic ident check on the name — must be a legal, non-keyword def name
        if not self._is_valid_def_name(name):
            return []

        native = bool(co.get('_native'))
        full_varnames = [str(a) for a in (co.get('varnames') or co.get('args') or [])]

        # --- signature ---------------------------------------------------
        if native:
            # EXACT signature recovered from the native co_argcount/flags.
            sig_args = [str(a) for a in (co.get('args') or [])]
            # Nuitka makeCodeObject arg_names for instance methods always
            # include self/cls as slot 0. If the class nest is proven and
            # that slot was dropped, restore it.
            if (is_method and sig_args
                    and sig_args[0] not in ('self', 'cls')
                    and 'self' not in sig_args and 'cls' not in sig_args):
                sig_args = ['self'] + sig_args
            elif is_method and not sig_args:
                sig_args = ['self']
        else:
            # Inferred path: we cannot split co_varnames into (args | locals)
            # without the native argcount, and Nuitka stores varnames out of
            # definition order, so we do NOT fabricate the parameter list.
            # Emit a conservative signature and surface the names in the body.
            if is_method:
                sig_args = ['self'] if (not full_varnames
                                        or full_varnames[0] in ('self', 'cls')) else []
                if full_varnames and full_varnames[0] in ('self', 'cls'):
                    sig_args = [full_varnames[0]]
            else:
                sig_args = []

        flags = co.get('flags') or 0
        is_async = bool(co.get('is_async')) or bool(flags & 0x0080) or bool(flags & 0x0200)
        kw = 'async def' if is_async else 'def'

        # Bare parameter names (before annotation decoration) — used to keep
        # them out of the recovered-locals line and to feed the body heuristics
        # (which test `.isidentifier()` and would choke on `name: Type`).
        bare_sig_args = list(sig_args)
        bare_params = {a.lstrip('*') for a in sig_args} | {'self', 'cls'}

        # Attach recovered type annotations (real, from __annotations__).
        ann = self._match_annotations(co) if native else None
        ret_hint = ''
        if ann:
            decorated = []
            for a in sig_args:
                key = a.lstrip('*')
                t = self._render_annotation_type(ann[key]) if key in ann else None
                decorated.append(f'{a}: {t}' if t and a not in ('self', 'cls') else a)
            sig_args = decorated
            if 'return' in ann:
                rt = self._render_annotation_type(ann['return'])
                if rt:
                    ret_hint = f' -> {rt}'

        # __defaults__ tuple from MAKE_FUNCTION (last N positional args).
        defs = None
        if parent:
            defs = self._defaults.get(f'{parent}.{name}')
        else:
            for dk in (name,):
                if dk in self._defaults:
                    defs = self._defaults[dk]
                    break
        if defs is None and native and not co.get('_makeobj'):
            defs = _ndl_infer_defaults_heuristic(co, self.constants)
        if defs and native:
            pos_idx = [i for i, a in enumerate(sig_args) if not a.startswith('*')]
            for di, dv in enumerate(reversed(defs)):
                pi = len(pos_idx) - 1 - di
                if pi < 0:
                    break
                ai = pos_idx[pi]
                base = sig_args[ai].split(' = ')[0].strip()
                if isinstance(dv, int) and ': str' in sig_args[ai]:
                    continue
                sig_args[ai] = f'{base} = {dv!r}'

        # ``__kwdefaults__`` is separate from ``__defaults__`` and applies by
        # parameter name, not by trailing positional index.  Modern source
        # recovery attaches it only after a unique exact-key dictionary match.
        kw_defaults = co.get('_kw_defaults') if native else None
        if isinstance(kw_defaults, dict):
            for ai, raw in enumerate(bare_sig_args):
                pname = str(raw).lstrip('*')
                if not pname or pname not in kw_defaults:
                    continue
                base = sig_args[ai].split(' = ')[0].strip()
                sig_args[ai] = f'{base} = {kw_defaults[pname]!r}'

        lines = []
        lines.append(f'{indent}{kw} {name}({", ".join(sig_args)}){ret_hint}:')
        body_indent = indent + '    '
        # Real docstring recovered from co_consts[0].
        doc = co.get('docstring')
        if isinstance(doc, str) and doc:
            lines.extend(self._format_docstring(doc, body_indent))
        # Recovered local-variable names (everything in co_varnames that isn't
        # already a parameter). Real identifiers from the source.
        locals_only = [v for v in full_varnames
                       if v not in bare_params and self._is_ident(v)]
        # The one body that is EXACT: __init__ storing its positional params
        # onto self. Use only real parameters (never locals) and only when the
        # signature was recovered natively, so we don't fabricate.
        init_params = ([a for a in bare_sig_args[1:] if a.isidentifier()]
                       if native and name == '__init__'
                       and bare_sig_args[:1] == ['self'] else [])
        # EXACT decompiled body (real Python), when one was proven for this
        # function (e.g. `return x / 100000000` or a fused method chain).
        # Emitted INSTEAD of the comment trace/placeholder — it is the actual
        # source. The recovered-locals placeholder is then suppressed: those
        # locals were fused into the expression by the optimizer, so listing
        # them as `x = y = ...` would be misleading next to the real body.
        exact_body = None
        for key in ((f'{parent}.{name}',) if parent else ()) + (name,):
            if key in self.body_sources:
                exact_body = self.body_sources[key]
                break
        body = []
        if exact_body:
            # Apply URL-merge and token-swap healers so that split-URL patterns
            # emitted by _synth_call_chain (e.g. `url = f'...address='` +
            # `headers = {'&tag=latest&apikey=': token}`) are reconstructed.
            _eb = list(exact_body)
            _vn = full_varnames[:len(bare_sig_args)]
            _eb = _ndl_heal_incomplete_url_slash(_eb, _vn)
            _eb = _ndl_heal_split_fstring_url(_eb, _vn)
            _eb = _ndl_heal_url_token_swap(_eb)
            body.extend(f"{body_indent}{ln}" for ln in _eb)
        else:
            if locals_only:
                label = ('# locals' if native else
                         '# co_varnames (args+locals, order/split approximate)')
                body.append(f"{body_indent}{label}: " + ", ".join(locals_only))
            # Faithful recovered name-access sequence (comment guide).
            trace_lines = self._body_trace_lines(name, parent, body_indent)
            body.extend(trace_lines)
            if init_params:
                body.extend(f"{body_indent}self.{a} = {a}" for a in init_params)
            else:
                body.extend(self._guess_body(name, bare_sig_args + locals_only, body_indent))
        # Never emit a def with an empty body (would be a SyntaxError).
        if not body:
            body = [f'{body_indent}pass']

        # ── __init__ parameter recovery ──────────────────────────────────
        # A recovered __init__ body (native OR inferred) may reference positional
        # parameters as `argN` (the `_param_of` fallback when varnames were
        # unavailable) while the signature declares only `self`. Reconcile: every
        # `argN` the body uses becomes a declared parameter, and one stored onto
        # `self.<attr>` (e.g. `self.resource_manager = arg1`) is NAMED after the
        # attribute — recovering `def __init__(self, resource_manager,
        # parent=None)`. Universal: driven purely by the body's own `argN`
        # references and `self.<attr>` stores, never by sample names.
        if is_method and name == '__init__':
            _authoritative_init_args = None
            if native:
                try:
                    _native_argc = int(co.get('argcount'))
                    _native_args = [str(x) for x in (co.get('args') or ())]
                    if 0 <= _native_argc <= len(_native_args):
                        _authoritative_init_args = _native_args[:_native_argc]
                except Exception:
                    pass
            sig_args, body = _ndl_reconcile_init_params(sig_args, body,
                                                        body_indent,
                                                        self.constants,
                                                        authoritative_args=(
                                                            _authoritative_init_args))
        lines.extend(body)
        return lines

    def _const_index(self, *names):
        """First-appearance index of any of `names` in the constant pool (a
        proxy for source declaration order). Missing names sort last."""
        best = None
        for nm in names:
            if nm and nm in self.str_positions:
                p = self.str_positions[nm][0]
                if best is None or p < best:
                    best = p
        return best if best is not None else 10 ** 9

    def _emit_class(self, class_name, cls_data, indent=''):
        methods = list(cls_data.get('methods', []))
        # Methods in SOURCE order. self.code_objects is in definition order
        # (PyCode_New call-site order), so the id()-keyed _def_order map is
        # faithful. The old constant-pool string index is NOT source order
        # (Nuitka interns names by first reference, not by line), which floated
        # `main` above `__init__`. Fall back to the const index only for
        # methods with no recovered code object (qualname-only backfills).
        _ord = getattr(self, '_def_order', {})
        _src = getattr(self, '_src_order', {})

        def _mkey(m):
            # Tiered sort key, most-trusted first:
            #  (0, rank) proven source order from ascending impl-VA (va_to_qn);
            #  (-1, 0)   a bodyless __init__ has no impl-VA, but Python/Nuitka
            #            convention always declares __init__ first -> class-top;
            #  (1, ...)  fallback to the old _def_order / const-index ordering.
            qn = m.get('qualname') or m.get('name') or ''
            if qn in _src:
                return (0, _src[qn])
            if str(qn).split('.')[-1] == '__init__':
                return (-1, 0)
            return (1, _ord.get(
                id(m), 10 ** 6 + self._const_index(m.get('qualname'),
                                                   m.get('name'))))
        methods.sort(key=_mkey)
        bases = _heal_class_bases(cls_data.get('bases', []), class_name)
        header = f'{indent}class {class_name}' + (f'({", ".join(bases)})' if bases else '') + ':'
        lines = [header]
        cdoc = getattr(self, '_class_docstrings', {}).get(class_name)
        if isinstance(cdoc, str) and cdoc:
            lines.extend(self._format_docstring(cdoc, indent + '    '))
        if not methods:
            # A class code object proves the definition, not an arbitrary class
            # attribute.  Keep the structural gap explicit and executable-safe.
            lines.append(f'{indent}    # UNCERTAIN: class body was not recovered from native code')
            lines.append(f'{indent}    pass')
            return lines
        for co in methods:
            lines.append('')
            lines.extend(self._emit_function(co, indent + '    ',
                                             is_method=True, parent=class_name))
        return lines

    # ---- annotation recovery -----------------------------------------------

    @classmethod
    def _render_annotation_type(cls, v):
        """Render a recovered __annotations__ value into a type expression.

        The constant parser represents typing objects structurally, e.g.
          'str'                                            -> str
          ('GenericAlias', 'list', ('str',))               -> list[str]
          ('UnionType', (X, Y))                            -> X | Y
          None                                             -> None
        Returns a string, or None if it can't be rendered cleanly.
        """
        if v is None:
            return 'None'
        if isinstance(v, str):
            return v if re.fullmatch(r'[A-Za-z_][\w.]*', v) else None
        if isinstance(v, tuple) and v:
            tag = v[0]
            if tag == 'GenericAlias' and len(v) >= 3:
                base = cls._render_annotation_type(v[1])
                params = v[2]
                if isinstance(params, (tuple, list)):
                    inner = ', '.join(filter(None,
                                             (cls._render_annotation_type(p) for p in params)))
                else:
                    inner = cls._render_annotation_type(params) or ''
                if base and inner:
                    return f'{base}[{inner}]'
                return base
            if tag == 'UnionType' and len(v) >= 2 and isinstance(v[1], (tuple, list)):
                parts = list(filter(None,
                                    (cls._render_annotation_type(p) for p in v[1])))
                return ' | '.join(parts) if parts else None
            if isinstance(tag, str) and tag.startswith('<type '):
                inner = tag[len('<type '):].rstrip('>')
                return inner or None
        return None

    def _collect_annotation_dicts(self):
        """All constants that look like a function's __annotations__ map:
        a dict whose keys are identifiers (arg names + optional 'return')."""
        out = []
        for c in self.constants:
            if (isinstance(c, dict) and c
                    and all(isinstance(k, str) and self._is_ident(k) for k in c)):
                out.append(c)
        return out

    def _match_annotations(self, co):
        """Find the annotation dict belonging to ``co``.

        Argument overlap alone is ambiguous when two functions share the same
        parameter names.  Nuitka keeps the annotation dictionary near the
        function/qualname strings in the module constant stream, so use that
        native ordering as a deterministic tie-breaker.
        """
        args = [a.lstrip('*') for a in (co.get('args') or [])
                if a not in ('self', 'cls')]
        if not args:
            return None
        argset = set(args)
        names = [str(co.get('qualname') or co.get('name') or '').split('.')[-1]]
        name_positions = [pos for pos, value in enumerate(self.constants)
                          if isinstance(value, str) and value in names]
        best, best_key = None, None
        for pos, d in enumerate(self.constants):
            if not (isinstance(d, dict) and d
                    and all(isinstance(k, str) and self._is_ident(k)
                            for k in d)):
                continue
            keys = set(d) - {'return'}
            if not keys:
                continue
            overlap = len(keys & argset)
            # require the dict's arg-keys to be a subset of this function's args
            if not overlap or not keys <= argset:
                continue
            distance = (min((abs(pos - name_pos) for name_pos in name_positions),
                            default=10 ** 9))
            key = (-overlap, distance, pos)
            if best_key is None or key < best_key:
                best, best_key = d, key
        return best

    # Distinctive substrings of Nuitka / CPython class-creation + type
    # machinery error templates. These strings are emitted by the compiler,
    # never written by a human, so they must not surface as "recovered data".
    _MACHINERY_MARKERS = (
        '__prepare__', 'must return a mapping', '__mro_entries__',
        'metaclass conflict', '__set_name__',
    )

    @classmethod
    def _is_machinery_string(cls, v):
        """True for a string that is compiler/runtime machinery rather than
        something a human wrote (e.g. '<metaclass>', '<module x>', the
        '%s.__prepare__() must return a mapping, not %s' error template)."""
        if not isinstance(v, str) or not v:
            return False
        # <metaclass>, <module ...>, <lambda>, <listcomp>, <genexpr>, <string>
        if v.startswith('<') and v.endswith('>'):
            return True
        return any(m in v for m in cls._MACHINERY_MARKERS)

    @staticmethod
    def _is_type_spec(v):
        """True for a value that is an __annotations__ TYPE spec, not real data:
        None, a bare/typing type name ('str', 'list[str]', 'A | B'), or a
        Nuitka-encoded type tuple (('UnionType', …)/('GenericAlias', …))."""
        if v is None:
            return True
        if isinstance(v, str):
            return bool(re.fullmatch(
                r'[A-Za-z_][\w.]*(?:\s*\|\s*[A-Za-z_][\w.]*)*', v)) or \
                bool(re.fullmatch(r'[A-Za-z_][\w.]*\[.*\]', v))
        if isinstance(v, tuple) and v and isinstance(v[0], str):
            return v[0] in ('UnionType', 'GenericAlias', 'Optional', 'Union',
                            'Annotated', 'type', 'Final', 'ClassVar')
        return False

    def _is_annotation_dict(self, d):
        """A function/class `__annotations__` dict (`{'x': 'int', 'return': …}`)
        — compiler machinery, NOT a data literal the dev wrote. Recognised when
        every key is an identifier (or 'return') and every value is a type spec.
        Keeps real data dicts (e.g. {'name': 'iPhone | iOS 18', …}) as data."""
        if not isinstance(d, dict) or not d:
            return False
        if not all(isinstance(k, str) and (self._is_ident(k) or k == 'return')
                   for k in d):
            return False
        return all(self._is_type_spec(v) for v in d.values())

    def _is_data_literal(self, v):
        """True for a constant that is real DATA (a literal a human wrote),
        as opposed to compiler machinery (identifiers, qualnames, dunders)."""
        if isinstance(v, bool):
            return False
        if isinstance(v, str):
            if not v:
                return False
            # bare identifiers / dotted names / filenames are machinery
            if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_.]*', v):
                return False
            if v.endswith(('.py', '.pyc')):
                return False
            if self._is_machinery_string(v):
                return False
            return True
        if isinstance(v, (int, float)):
            return not (isinstance(v, int) and -2 <= v <= 2)
        if isinstance(v, bytes):
            return len(v) > 0
        if isinstance(v, dict):
            # exclude __annotations__ dicts (type machinery, not data)
            return len(v) > 0 and not self._is_annotation_dict(v)
        if isinstance(v, (list, set, frozenset)):
            return len(v) > 0
        if isinstance(v, tuple):
            # a tuple of pure idents is a co_varnames/imports artefact, skip;
            # a tuple containing data literals is real data.
            return any(self._is_data_literal(x) for x in v)
        return False

    def _emit_module_constants(self):
        """Emit module-level literals recovered from the constant pool.

        For C-compiled modules the *values* of every module-level literal
        (URLs, messages, format strings, JSON config blobs, lists/dicts of
        data, numbers) are stored verbatim in the blob even though the
        assignment statements are gone. We surface them so the reconstruction
        carries the module's real data, not just its skeleton. ALL_CAPS names
        are emitted as their own bindings (they are almost always module
        constants like CONFIG_PATH / SECRET_KEY / RELEASES_SERVER).
        """
        consts = self.constants
        out = []

        # ---- names already accounted for elsewhere -------------------------
        defined = set()
        for cls, d in self.classes.items():
            defined.add(cls)
            for m in d.get('methods', []):
                defined.add(m.get('name'))
            for b in d.get('bases', []):
                defined.add(b)
        for f in self.free_funcs:
            defined.add(f.get('name'))
        import_names = set(_ndl_imported_names_from_constants(consts))
        import_names |= _ndl_parse_imported_symbols(
            getattr(self, '_detected_import_lines', []))
        explained = set(self._NON_FUNCTION_NAMES) | defined | import_names

        # ---- __all__ reconstruction ---------------------------------------
        # The export list `__all__ = [...]` is stored as a constant tuple of
        # identifier strings; in a re-exporting package __init__ it is often the
        # ONLY real content. Recognise it as the largest ident-only collection
        # whose members are (mostly) names defined/imported in this module, so
        # it is emitted as `__all__` instead of an anonymous `_recovered_data_N`.
        # Membership for the __all__ ratio uses only names we can actually see
        # defined or imported here. The store-scan (module_globals) is NOT used
        # for this test — it contains every module-scope store and would let a
        # body literal list like `["http","https","socks4","socks5"]` masquerade
        # as an export list.
        # Use ONLY the symbols of the import lines we actually emitted — not the
        # constant-pool heuristic `import_names`, which misreads a body literal
        # tuple that merely follows a lowercase ident (checker's
        # `('http','https','socks4','socks5')`) as a from-import names tuple and
        # would then let it qualify as __all__.
        name_pool = defined | _ndl_parse_imported_symbols(
            getattr(self, '_detected_import_lines', []))
        # The name-sets of each emitted `from X import a, b, c` line — an
        # __all__ candidate that exactly matches one of these is really that
        # import's names tuple (e.g. the lone `from third_party import …` tuple in
        # a module with no __all__), so it must NOT be promoted to __all__.
        import_sets = []
        for _ln in getattr(self, '_detected_import_lines', []):
            _m = re.match(r'^from\s+\S+\s+import\s+(.+)$', _ln)
            if _m:
                _nm = {p.split(' as ')[0].strip() for p in _m.group(1).split(',')}
                import_sets.append(frozenset(_nm))
        # co_varnames sets (function params+locals) — an __all__ candidate that
        # is a subset of one is really a parameter list, not an export list
        # (e.g. checker's `('file','timeout','method','site','random_user_agent')`).
        varname_sets = []
        for co in self.code_objects:
            vs = co.get('varnames') or co.get('args') or []
            if vs:
                varname_sets.append(frozenset(str(x) for x in vs))
        all_list = None
        all_src = None              # original constant object (identity, for
                                    # excluding it from data collections)
        for c in consts:
            if not (isinstance(c, (list, tuple)) and len(c) >= 2
                    and all(isinstance(x, str) and self._is_ident(x) for x in c)):
                continue
            names = list(c)
            if any(x.startswith('__') for x in names):
                continue
            cand = frozenset(names)
            if cand in import_sets:
                continue
            if any(cand <= vs for vs in varname_sets):
                continue
            known = sum(1 for x in names if x in name_pool)
            if known >= max(2, int(0.6 * len(names))):
                if all_list is None or len(names) > len(all_list):
                    all_list = names
                    all_src = c

        # ---- real module globals from the store-scan ----------------------
        # `module_globals` is the AUTHORITATIVE set of names the module-init
        # stores at module scope (UPDATE_STRING_DICT). It contains imports +
        # defs + the genuine globals, so we subtract the imports/defs/dunders
        # to isolate the real top-level assignments (ALL_CAPS module globals).
        # When the scan returns nothing we
        # emit no globals rather than guessing — that is what kills the old
        # `FAILED = ...` / `OPTION_A = ...` noise (those are body string
        # literals / enum attribute names, never stored at module scope).
        # Names that are importable modules compiled into the binary (their bare
        # `import X` line may have been missed by the import scan); they are
        # imports, never genuine data globals, so keep them out of real_globals.
        known_import_roots = set()
        for _km in self.known_modules:
            known_import_roots.add(_km)
            known_import_roots.add(_km.split('.')[0])
        emitted_syms = _ndl_parse_imported_symbols(
            getattr(self, '_detected_import_lines', []))

        def _is_real_global(c):
            return (isinstance(c, str) and c not in explained
                    and self._is_valid_def_name(c)
                    and c not in self._COMMON_STDLIB
                    and c not in known_import_roots
                    and c not in emitted_syms
                    and not (c.startswith('__') and c.endswith('__')))

        real_globals = []
        seen_g = set()
        if self.module_globals:
            for c in consts:               # constant-pool order ≈ source order
                # _is_real_global() checks isinstance(str) first, so it guards
                # the `c in module_globals` hash against list/dict constants.
                if (_is_real_global(c) and c not in seen_g
                        and c in self.module_globals):
                    seen_g.add(c)
                    real_globals.append(c)

        # __all__ members that are neither imported nor defined here are genuine
        # module-level assignments (e.g. `lookup_table`); recover them as data
        # globals even when the store-scan came up empty (package __init__).
        inferred = []
        for nm in (all_list or []):
            if nm not in seen_g and _is_real_global(nm):
                seen_g.add(nm)
                inferred.append(nm)

        # ---- recovered data collections (lists/dicts of literals) ---------
        collections = []
        for c in consts:
            if c is all_src:           # the __all__ export list itself
                continue
            if isinstance(c, (list, dict)) and self._is_data_literal(c):
                collections.append(c)

        # Bind a data collection to its sole owning global name when that is
        # unambiguous (exactly one data global + one collection), e.g.
        # `user_agents = [...]` / `lookup_table = {...}`. A proven (store-scan)
        # global is always emitted (value `...` if unbound); an __all__-inferred
        # global is emitted ONLY if it binds to a collection — otherwise it is
        # most likely an import whose line we failed to recover, not data.
        bound = {}
        bind_candidates = real_globals + inferred
        if len(collections) == 1 and len(bind_candidates) == 1:
            bound[bind_candidates[0]] = collections[0]

        _TYPING_OR_IMPORT_NAMES = frozenset({
            'List', 'Dict', 'Set', 'Tuple', 'Optional', 'Union', 'Any',
            'Callable', 'Iterable', 'Iterator', 'Mapping', 'Sequence',
            'Type', 'TypeVar', 'Generic', 'Final', 'Literal', 'Annotated',
            'Protocol', 'NamedTuple', 'TypedDict', 'Enum', 'auto',
        })
        _imported_syms = _ndl_parse_imported_symbols(
            getattr(self, '_detected_import_lines', []))
        _all_import_names = _ndl_all_import_names(
            getattr(self, '_detected_import_lines', []))
        emit_globals = list(real_globals) + [n for n in inferred if n in bound]
        # Drop methodish / Qt-class pollution that slipped past the store-scan
        # gate (LOOKUP_ATTR helpers misclassified as MODSTORE).
        def _looks_attr_pollution(nm):
            if not isinstance(nm, str):
                return True
            # ALL_CAPS / SCREAMING_SNAKE — keep (URL_*, USERNAME_*)
            if re.fullmatch(r'[A-Z][A-Z0-9_]*', nm):
                return False
            if len(nm) > 1 and nm[0] == 'Q' and nm[1].isupper():
                return True
            if nm[:1].islower() and (
                    nm.startswith(('set', 'get', 'add', 'is', 'has', 'on_',
                                   'setup_', 'show_', 'load_', 'save_',
                                   'update_', 'append', 'remove', 'insert',
                                   'clear', 'emit', 'connect', 'clicked'))
                    or nm in ('resize', 'exec', 'quit', 'hide', 'show',
                              'accept', 'reject', 'timeout', 'strip',
                              'split', 'replace', 'find', 'count',
                              'processEvents', 'singleShot', 'hardware_id',
                              'license_manager', 'account_manager',
                              'key_edit', 'status_label', 'session',
                              'running', 'signals', 'ui', 'argv',
                              'bases', 'clicked', 'connect', 'emit')):
                return True
            # CamelCase Qt enum/attr leaves (AlignmentFlag, DragDropMode, …)
            if (nm[:1].isupper() and '_' not in nm
                    and not nm.startswith(('Ui_', 'Worker', 'License',
                                           'Account', 'Main'))):
                # Keep user class names; drop Qt enum-style identifiers
                if nm.endswith(('Flag', 'Mode', 'Role', 'Shape', 'Button',
                                'Edit', 'Layout', 'Widget', 'Box', 'Label',
                                'Dialog', 'Window', 'Pool', 'Timer')):
                    return True
            return False
        emit_globals = [n for n in emit_globals if not _looks_attr_pollution(n)]
        # Final gate: unresolved (=None) globals must be SCREAMING_SNAKE data
        # constants — never camelCase / snake UI ids.
        emit_globals = [
            n for n in emit_globals
            if (n in bound or n in getattr(self, 'module_global_values', {})
                or re.fullmatch(r'[A-Z][A-Z0-9_]*', n))
        ]
        emit_globals.sort(key=lambda n: self._const_index(n))
        for name in emit_globals:
            if name in _imported_syms or name in _all_import_names or name in import_names:
                continue
            if name in _TYPING_OR_IMPORT_NAMES:
                continue
            if name in bound:
                out.append(f'{name} = {self._safe_literal(bound[name])}')
            elif name in self.module_global_values:
                gv = self.module_global_values[name]
                if isinstance(gv, tuple) and len(gv) == 2 and gv[0] == '__expr__':
                    expr = gv[1]
                    if expr in ('_v()', '_v') or re.search(r'\b_v\b', expr):
                        guess = _ndl_guess_global_init(name, _imported_syms,
                                                       self.constants)
                        # `...` (not None) so the evidenced subscript-chain
                        # healer (_ndl_heal_config_subscript_globals) can arm.
                        out.append(f'{name} = {guess}' if guess else
                                   f'{name} = ...')
                    else:
                        out.append(f'{name} = {expr}')
                else:
                    out.append(f'{name} = {self._safe_literal(gv)}')
            else:
                guess = _ndl_guess_global_init(name, _imported_syms,
                                               self.constants)
                if guess:
                    out.append(f'{name} = {guess}')
                else:
                    # Universal complete source: never emit bare ... or synthetic top-level artifacts.
                    # Use None + comment so it parses, is executable, and no _X0/_R0 style noise.
                    out.append(f'{name} = None  # module global (value not statically recoverable; evidence in const pool)')

        if all_list is not None:
            out.append('')
            out.append('__all__ = [')
            for nm in all_list:
                out.append(f'    {nm!r},')
            out.append(']')

        # ---- verbose forensic extras (only in banner/forensic mode) -------
        # The raw literal pool and any unbound data collections are intelligence
        # for a reverse-engineer but never appear in the original source, so the
        # clean whole-binary source emit (emit_banner=False) omits them.
        if self.emit_banner:
            literals = []
            seen_lit = set()
            for c in consts:
                if not self._is_data_literal(c) or isinstance(
                        c, (list, dict, set, frozenset, tuple)):
                    continue
                key = repr(c)
                if key in seen_lit:
                    continue
                seen_lit.add(key)
                literals.append(c)
            if literals:
                out.append('')
                out.append('# --- string / numeric literals recovered from the constant pool ---')
                out.append('# (the original variable bindings are gone; the values are exact)')
                out.append('_recovered_literals = (')
                for lit in literals[:400]:
                    out.append(f'    {self._safe_literal(lit)},')
                out.append(')')
            bound_ids = {id(v) for v in bound.values()}
            k = 0
            for coll in collections[:20]:
                if id(coll) in bound_ids:
                    continue
                out.append('')
                out.append(f'_recovered_data_{k} = {self._safe_literal(coll)}')
                k += 1

        return out

    @staticmethod
    def _safe_literal(v, _depth=0):
        """repr() a recovered constant, guarding against unrepr-able / huge
        values and recursion."""
        try:
            if _depth > 6:
                return '...'
            if isinstance(v, (str, bytes, int, float, bool)) or v is None:
                r = repr(v)
                if len(r) <= 2000:
                    return r
                # Never cut a literal mid-way: an unterminated string/bytes
                # literal is a SyntaxError for the WHOLE emitted module.
                # Truncate the VALUE and re-repr so the literal always closes;
                # the true length survives in an honest trailing comment.
                if isinstance(v, str):
                    return repr(v[:1900]) + '  # ... (%d chars total)' % len(v)
                if isinstance(v, (bytes, bytearray)):
                    return repr(bytes(v[:1900])) + '  # ... (%d bytes total)' % len(v)
                return r
            if isinstance(v, (list, tuple, set, frozenset)):
                inner = ', '.join(
                    StaticalySmartReconstructor._safe_literal(x, _depth + 1)
                    for x in list(v)[:60])
                if isinstance(v, list):
                    return f'[{inner}]'
                if isinstance(v, set):
                    return f'{{{inner}}}' if v else 'set()'
                if isinstance(v, frozenset):
                    return f'frozenset({{{inner}}})'
                return f'({inner})'
            if isinstance(v, dict):
                items = ', '.join(
                    f'{StaticalySmartReconstructor._safe_literal(k, _depth + 1)}: '
                    f'{StaticalySmartReconstructor._safe_literal(val, _depth + 1)}'
                    for k, val in list(v.items())[:60])
                return f'{{{items}}}'
            return repr(v)
        except Exception:
            return '...'

    def render(self):
        out = []
        if self.emit_banner:
            out.append(f'"""Module: {self.module_name}')
            out.append('')
            out.append('Static reconstruction from the Nuitka constants blob + native')
            out.append('code objects. EXACT from the binary: imports, class/function')
            out.append('structure, signatures, type annotations, bases, docstrings, and')
            out.append('every constant / string / numeric literal. Function BODIES are')
            out.append('compiled to native machine code (no Python bytecode is stored),')
            out.append('so they appear as placeholders; the faithful per-function')
            out.append('operation trace is in the matching .nbc file.')
            out.append('"""')
            out.append('')

        imports = self.detect_imports()
        self._detected_import_lines = list(imports)
        if imports:
            for imp in imports:
                out.append(imp)
            _imported = _ndl_parse_imported_symbols(imports)
            for _sym in sorted(_imported, key=len, reverse=True):
                if (_sym[0].isupper() and 'c' in self.constants
                        and _sym not in ('Table', 'Console', 'Style', 'Fore')
                        and not _sym.isupper() and not _sym.endswith('TOKENS')):
                    out.append('c = %s()' % _sym)
                    break
            out.append('')

        # Module-level literals/constants recovered from the blob.
        const_lines = self._emit_module_constants()
        if const_lines:
            out.extend(const_lines)
            out.append('')

        # Emit classes and free functions in SOURCE order. Nuitka lays the
        # co_name / co_qualname strings into the constant pool in declaration
        # order, so the first-appearance index is a faithful proxy for the
        # original top-to-bottom layout (far better than VA or alphabetic order).
        # Top-level interleave (free funcs + classes) stays on the constant-pool
        # string index: empirically a better source-order proxy here than the
        # code-object BFS-discovery order (which is reliable for WITHIN-class
        # method order — see _emit_class — but not for module-level defs).
        _ord = getattr(self, '_def_order', {})

        def _class_pos(cname):
            idxs = [_ord.get(id(m), 10 ** 6)
                    for m in self.classes[cname].get('methods', [])]
            if idxs:
                return min(idxs)
            return self._const_index(cname)

        # V82: order top-level entities (classes AND free functions) by PROVEN
        # source order. The constant-pool first-appearance index (the legacy key
        # below) is NOT source order -- Nuitka interns names by first reference,
        # not by line, so it emitted paid-API funcs before free-API funcs
        # (bitcoin), a free func AFTER a class that precedes it in source
        # (proxyconnector: loadProxies vs StealthConnection), and scattered base
        # classes among subclasses (scraper). The ascending implementation-VA
        # rank in `_src_order` (built in decompile_module_*) EXACTLY reproduces
        # GT top-to-bottom order. Verified free-func: bitcoin 11/11, ethereum
        # 3/3, litecoin 7/7, tron 4/4. Verified class-bearing: proxyconnector
        # (func-before-class interleave), scraper (all 7 classes in source
        # order), checker. A class is ranked by its own qualname if keyed, else
        # the min rank over its methods' qualnames (a class's methods are
        # contiguous in source, so the first method's rank is a faithful
        # class-position proxy). Apply ONLY when EVERY entity has a `_src_order`
        # rank; otherwise fall back to the legacy const-index ordering unchanged
        # (zero regression on modules with an incomplete VA->qualname map).
        _src = getattr(self, '_src_order', {})

        def _func_src_rank(co):
            qn = co.get('qualname') or co.get('name') or ''
            if qn in _src:
                return _src[qn]
            nm = co.get('name') or ''
            return _src.get(nm)

        def _class_src_rank(cname):
            if cname in _src:
                return _src[cname]
            cand = [_src[m.get('qualname')] for m in
                    self.classes[cname].get('methods', [])
                    if m.get('qualname') and m.get('qualname') in _src]
            return min(cand) if cand else None

        _unified = []
        _complete = bool(self.classes or self.free_funcs)
        for c in self.classes:
            r = _class_src_rank(c)
            if r is None:
                _complete = False
            _unified.append(('class', c, r))
        for co in self.free_funcs:
            r = _func_src_rank(co)
            if r is None:
                _complete = False
            _unified.append(('func', co, r))

        if _src and _complete:
            ordered = _unified
        else:
            ordered = ([('class', c, _class_pos(c)) for c in self.classes]
                       + [('func', co, self._const_index(co.get('qualname'),
                                                         co.get('name')))
                          for co in self.free_funcs])
        ordered.sort(key=lambda t: (t[2] if t[2] is not None else 10 ** 9))
        for kind, obj, _pos in ordered:
            out.append('')
            if kind == 'class':
                out.extend(self._emit_class(obj, self.classes[obj]))
            else:
                out.extend(self._emit_function(obj))
            out.append('')

        # If no classes AND no free functions were recovered, dump the
        # string/numeric constants as module-level references so the output
        # still carries the blob's intelligence. This is forensic noise that is
        # never in the original source, so the clean source emit omits it.
        if self.emit_banner and not self.classes and not self.free_funcs:
            for c in self.constants[:60]:
                if isinstance(c, str) and len(c) > 4:
                    out.append(f'# const: {c!r}')

        return '\n'.join(out) + '\n'


def omni_generate_source(decompiler, section_name, raw_constants=None):
    """Emit a Python file from an OmniDecompiler's collected state.

    For modules that contain only free functions (no classes), falls back to
    a) signature inference from constants (same logic as NuitkaCSourceRebuilder)
    b) notable-strings dump (URLs, file paths, keys, function names)
    c) imports detected via dotted-module-name heuristic
    so every recovered module produces USEFUL output, not just boilerplate.
    """
    out = []
    out.append('"""')
    out.append('==== OMNI UNIFIED MAXIMUM DECOMPILATION ====')
    out.append(f'Reconstructed source: {section_name}')
    out.append('Uniting everything known: AST generation, Meaningful Types, C-API Fallbacks')
    out.append('"""\n')
    out.append('# =========================================================')
    out.append('# IMPORTS & REQUIRED LIBRARIES')
    out.append('# =========================================================')
    out.append('import json, os, sys, time, struct')
    out.append('import ctypes\n')

    # --- detected imports (from constants like 'json', 'tls_client.Session', etc.) --
    detected_imports = set()
    if raw_constants:
        for c in raw_constants:
            if isinstance(c, str) and 2 < len(c) < 80:
                # Looks like a module/attr name: 'foo', 'foo.bar', 'foo.bar.baz'
                if (re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*', c)
                        and '.' in c
                        and not c.startswith('_')
                        and not c.endswith('.py')):
                    detected_imports.add(c)
    if detected_imports:
        out.append('# =========================================================')
        out.append('# DETECTED IMPORTS (from constants)')
        out.append('# =========================================================')
        for imp in sorted(detected_imports)[:40]:
            out.append(f'# import {imp}')
        out.append('')

    if decompiler.api_endpoints:
        out.append('# =========================================================')
        out.append('# DISCOVERED HTTP API ENDPOINTS')
        out.append('# =========================================================')
        for url in sorted(list(decompiler.api_endpoints)):
            out.append(f'API_TARGET_{abs(hash(url)) % 10000} = {repr(url)}')
        out.append('')

    if decompiler.vk_table:
        out.append('# =========================================================')
        out.append('# RECOVERED DYNAMIC VIRTUAL KEYCODES')
        out.append('# =========================================================')
        for k, v in decompiler.vk_table.items():
            out.append(f'{k} = 0x{v:02X}' if v is not None else f'{k} = None')
        out.append('')

    classes_emitted = 0
    if decompiler.classes:
        out.append('# =========================================================')
        out.append('# ORGANIC CLASS ABSTRACTIONS AND HEURISTIC METHOD TRACES')
        out.append('# =========================================================')
        for cls_name, cls_node in decompiler.classes.items():
            if len(cls_name) > 60 or ' ' in cls_name or '\x00' in cls_name:
                continue
            if not cls_name[0:1].isalpha() and cls_name[0:1] != '_':
                continue
            if not cls_node.methods and not cls_node.attributes:
                continue
            out.append(cls_node.render(0))
            classes_emitted += 1

    # --- free-function inference (for pure-function modules) ---
    if raw_constants is not None:
        inferred = NuitkaCSourceRebuilder.infer_functions_from_constants(raw_constants)
        # Skip ones that look like they're already emitted as class methods
        emitted_method_names = set()
        for cls_node in decompiler.classes.values():
            for m in cls_node.methods:
                emitted_method_names.add(m.name)

        free_funcs = []
        for co in inferred:
            name = co.get('name', '')
            qualname = co.get('qualname', name)
            # qualname containing '.' => probably a method; skip
            if '.' in qualname and not qualname.startswith('<'):
                continue
            if name in emitted_method_names:
                continue
            if name in ('<module>', '<listcomp>', '<dictcomp>', '<genexpr>',
                        '<lambda>', '<setcomp>'):
                continue
            free_funcs.append(co)

        if free_funcs:
            out.append('# =========================================================')
            out.append('# FREE FUNCTION SIGNATURES (inferred from constants)')
            out.append('# =========================================================')
            for co in free_funcs[:80]:   # cap output
                name = co.get('name', '')
                args = co.get('args', []) or []
                # safe ident for Python: skip names containing weird chars
                if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name):
                    continue
                sig_args = [a for a in args if re.fullmatch(r'[A-Za-z_.][A-Za-z0-9_]*', str(a))]
                out.append(f'')
                out.append(f'def {name}({", ".join(str(a) for a in sig_args)}):')
                out.append(f'    """Body not recoverable (compiled to native code by Nuitka)."""')
                out.append(f'    ...')
            out.append('')

    # --- notable strings dump (URLs, paths, keys, long strings) ---
    if raw_constants:
        notable = []
        seen = set()
        for c in raw_constants:
            if not isinstance(c, str):
                continue
            if len(c) < 8 or c in seen:
                continue
            if any(m in c.lower() for m in ('http', 'https', '/api/', '.com', '.io',
                                              '.net', '.org', '.php', 'bearer',
                                              'secret', 'private_key',
                                              'password', 'auth', 'key',
                                              'rpc', 'discord', 'telegram')):
                if len(c) < 200:
                    notable.append(c)
                    seen.add(c)
            elif len(c) > 60 and ' ' in c:
                # Probably a human-readable message (error/status)
                notable.append(c)
                seen.add(c)
            if len(notable) >= 60:
                break
        if notable:
            out.append('# =========================================================')
            out.append('# NOTABLE STRING CONSTANTS (URLs, endpoints, messages)')
            out.append('# =========================================================')
            for s in notable:
                # Try to give each a stable variable name
                out.append(f'_CONST_{abs(hash(s)) % 100000} = {repr(s)}')
            out.append('')

    return "\n".join(out)


# ---------------------------------------------------------------------------
#  EMBEDDED nuitka_static_decompiler  (previously an external sidecar file)
# ---------------------------------------------------------------------------
#
# Older versions of this tool loaded these two symbols from
# `nuitka_static_decompiler.py` sitting next to the main script. They are
# now provided inline so the whole pipeline is a single standalone file.
#
# Public API (unchanged from the sidecar):
#   BlobParser(blob_bytes)                  — decoder instance
#       .parse_module(chunk_data)           -> (consts_list, code_objects)
#   reconstruct_python_source(name, consts) -> str (Python source)
#
# `consts_list` is a list of dicts `{type, value, index}` so callers can
# introspect the decoded constants easily. Internally we reuse the
# already-embedded `parse_module_constants`, `extract_code_object_map`
# and `StaticalySmartReconstructor` to avoid duplicate logic.
# ---------------------------------------------------------------------------

class BlobParser:
    """Compatibility wrapper around the embedded parsers.

    Historical API expected by `NuitkalizatorPro.run()` Phase 11. Instances
    carry the full blob bytes only as metadata; the real decoding works
    on one module chunk at a time via `parse_module`.
    """

    def __init__(self, blob_bytes):
        self.blob = bytes(blob_bytes) if blob_bytes else b''

    @staticmethod
    def _classify(value):
        if value is None:
            return 'none'
        if isinstance(value, bool):
            return 'bool'
        if isinstance(value, int):
            return 'int'
        if isinstance(value, float):
            return 'float'
        if isinstance(value, complex):
            return 'complex'
        if isinstance(value, str):
            return 'str'
        if isinstance(value, bytes):
            return 'bytes'
        if isinstance(value, bytearray):
            return 'bytearray'
        if isinstance(value, tuple):
            return 'tuple'
        if isinstance(value, list):
            return 'list'
        if isinstance(value, dict):
            if value.get('_type') == 'CodeObject':
                return 'code'
            return 'dict'
        if isinstance(value, frozenset):
            return 'frozenset'
        if isinstance(value, set):
            return 'set'
        return type(value).__name__

    def parse_module(self, chunk_data, module_name='', *, python_version=None,
                     constants_profile=None):
        """Return `(consts, code_objects)` for one module chunk.

        Every entry in `consts` is `{'index': i, 'type': t, 'value': v}`
        where `type` is a short string ('str', 'int', 'tuple', 'code', ...).
        `code` entries have `value` = the CodeObjectSpec dict emitted by
        `_parse_code_object_tag` when Nuitka included a `'C'` tag in the
        chunk (rare for C-compiled modules; common inside inner code
        objects).
        """
        raw = parse_module_constants(
            chunk_data, python_version=python_version,
            profile=constants_profile)
        co_list = extract_code_object_map(
            module_name or '', chunk_data, python_version=python_version,
            profile=constants_profile)
        consts = []
        for i, v in enumerate(raw):
            consts.append({
                'index': i,
                'type': self._classify(v),
                'value': v,
            })
        return consts, co_list


def reconstruct_python_source(module_name, consts, native_code_objects=None,
                              body_traces=None, module_globals=None,
                              body_sources=None):
    """Produce Python source for a module from its decoded constants list.

    This is the high-level "synthesise the module" entry point used by
    Phase 11. Under the hood it delegates to `StaticalySmartReconstructor`
    which does pattern-matched import detection + class/method hierarchy
    + heuristic HTTP-fetch body templates + notable-string harvesting.

    `consts` may be either the dict-wrapped list produced by
    `BlobParser.parse_module` or the raw list emitted by
    `parse_module_constants` — both are accepted.

    `native_code_objects`, when supplied, are the EXACT code objects recovered
    from the native PyCode_New* call sites (real argcount/flags/varnames);
    they take priority over anything found in the constants.
    """
    # Unwrap dict form into raw Python values
    raw_values = []
    code_objs = []
    for entry in consts:
        if isinstance(entry, dict) and 'value' in entry and 'type' in entry:
            raw_values.append(entry['value'])
            if entry['type'] == 'code':
                code_objs.append(entry['value'])
        else:
            raw_values.append(entry)
            if isinstance(entry, dict) and entry.get('_type') == 'CodeObject':
                code_objs.append(entry)

    if native_code_objects:
        code_objs = native_code_objects

    recon = StaticalySmartReconstructor(
        module_name=module_name or '__module__',
        constants=raw_values,
        code_objects=code_objs,
        body_traces=body_traces,
        module_globals=module_globals,
        body_sources=body_sources,
    )
    return recon.render()


# ---------------------------------------------------------------------------
#  4. UNIFIED STATICALY PIPELINE — orchestrates 1 + 2 + 3
# ---------------------------------------------------------------------------

class StaticalyExtractor:
    """Unified orchestrator: drives NuitkaBlobDecoder + xdis raw scan + OMNI.

    Usage:
        ext = StaticalyExtractor(blob_bytes, target_python=(3, 10))
        result = ext.run(output_dir="OUT")
    """

    def __init__(self, blob_data, target_python=None, pe_file=None,
                 module_table=None, nbc_only=False):
        self.blob = blob_data
        self.pe = pe_file                 # optional pefile.PE for disassembly
        self.module_table = module_table or []
        self.nbc_only = nbc_only
        # When True, .nbc files include the per-function @ASM native
        # disassembly block alongside the (enriched) @OPS virtual ops.
        # Default False: enriched @OPS subsumes @ASM and the files stay
        # small enough to feed an LLM. Set by NuitkalizatorPro from the
        # --nbc-full-asm CLI flag.
        self.include_native_asm = False
        # Optional `--only` filter (list of names or `pkg.*` globs).
        # Set by NuitkalizatorPro after construction. When None, the
        # pipeline disassembles every compiled entry in the table.
        self.only_modules = None
        # When True, NBC generation is restricted to user (non-stdlib/non-library)
        # modules only. Set by NuitkalizatorPro when --user-nbc is passed.
        self.user_nbc = False
        if target_python is None:
            raise ValueError(
                "target_python is required; raw marshal bytes do not prove an "
                "exact CPython minor ABI")
        self.target_python = tuple(target_python[:2])
        self.target_ver_str = f"{self.target_python[0]}.{self.target_python[1]}"
        set_nuitka_target_python(self.target_python)
        # Cache for _find_user_sections result — computed once, reused by
        # omni_reconstruct, emit_nbc_placeholders, AND disassemble_modules.
        self._user_sections_cache = None

    # ------------------------------------------------------------------
    # USER-MODULE AUTO-DETECTION  (used by --user-nbc)
    # ------------------------------------------------------------------

    @staticmethod
    def _py_path_from_constants(items) -> str:
        """Return the first *.py string constant found in a module's items, or ''."""
        for item in items:
            if isinstance(item, str) and item.endswith('.py') and len(item) > 3:
                return item.replace('\\', '/')
        return ''

    @staticmethod
    def _path_root(p: str) -> str:
        """Return the top-level directory (or bare name) from a normalised path.

        'Crypto/Cipher/AES.py'  -> 'Crypto'
        'os.py'                 -> 'os'
        '/usr/lib/python3/os.py'-> '' (absolute → caller uses other checks)
        """
        parts = p.split('/')
        root = parts[0] if parts else ''
        if root.endswith('.py'):
            root = root[:-3]
        # Absolute path: first part is empty (Linux) or drive letter (Windows)
        if not root or (len(root) == 2 and root[1] == ':') or root == '':
            return ''
        return root

    # Path fragments that unambiguously identify third-party origin.
    _SITEPACKAGES_MARKERS = (
        '/site-packages/', '/dist-packages/',
        'site-packages\\', 'dist-packages\\',
    )
    # Path fragments that unambiguously identify stdlib origin (absolute paths).
    _STDLIB_PATH_MARKERS = (
        '/lib/python', '\\lib\\python',
        '/python3.', '\\python3.',
        '/python2.', '\\python2.',
    )
    # Well-known stdlib anchors: if their path is absolute, tells us stdlib root.
    _STDLIB_ANCHORS = ('os', 'sys', 'json', 'io', 're', 'abc', 'typing',
                       'pathlib', 'collections', 'functools', 'importlib')

    def _extract_pypi_modules(self, sections: dict) -> set:
        """Scan constants looking for the runtime_metadata_values tuple
        injected by Nuitka. Returns a set of top-level module names
        belonging to external PyPI distributions."""
        mod_names = set()
        for items in sections.values():
            for item in items:
                if isinstance(item, tuple) and len(item) > 0:
                    for sub_item in item:
                        if isinstance(sub_item, tuple) and len(sub_item) == 2:
                            dist_name, dist_data = sub_item
                            if isinstance(dist_name, str) and isinstance(dist_data, tuple) and len(dist_data) == 3:
                                mod, metadata, _ = dist_data
                                if isinstance(metadata, str) and 'Metadata-Version:' in metadata:
                                    if isinstance(mod, str):
                                        mod_names.add(mod)
        return mod_names

    def _find_user_sections(self, sections: dict) -> set:
        """Return the set of section names that belong to the developer's own code.

        Nuitka has NO binary flag to distinguish developer modules from
        stdlib/third-party.  We use a 4-strategy cascade:

          1. __main__ co_filename anchor
             1a  Packaged: 'myapp/__main__.py' or 'C:/project/myapp/__main__.py'
                 → dev_root = 'myapp' (relative first dir OR absolute parent dir
                   of __main__.py, cross-checked against module table)
             1b  Flat: '__main__.py' with no directory component
                 → dev code = flat .py files that pass is_dev()
          2. __main__ import-graph
             Walk __main__'s string constants; roots that exist in the blob AND
             pass is_dev() are the developer's packages.  is_dev() uses
             KNOWN_LIBRARY_PREFIXES + sys.stdlib_module_names + embedded PyPI
             metadata, so PIL / customtkinter / cv2 etc. are excluded even when
             __main__ directly imports them.
             Also collects flat .py files (no directory in path) as developer code.
          3. Path-marker analysis  (absolute paths with stdlib/site-packages markers)
          4. KNOWN_LIBRARY_PREFIXES name fallback
        """
        if self._user_sections_cache is not None:
            return self._user_sections_cache

        # ── unified is_dev predicate ───────────────────────────────────────
        pypi_mods    = self._extract_pypi_modules(sections)
        stdlib_names = getattr(sys, 'stdlib_module_names',
                               frozenset(self._STDLIB_ANCHORS))

        # Nuitka-generated internal module names: underscore + 8+ hex digits.
        # Examples: _5930d51333, _96066c68ed — never developer code.
        import re as _re
        _nuitka_hash = _re.compile(r'^_[0-9a-f]{8,}$').match

        _NUITKA_INTERNALS = frozenset({
            '__module_root__', '__module_root',
            '__init__helper__', 'tkinter-preLoad', 'tkinter_preLoad',
        })

        def is_dev(name: str) -> bool:
            root = name.split('.')[0]
            if root in _NUITKA_INTERNALS: return False
            if _nuitka_hash(root):        return False   # _5930d51333 etc.
            if root in pypi_mods:         return False
            if root in stdlib_names:      return False
            return is_main_module(name)                  # KNOWN_LIBRARY_PREFIXES

        # ── co_filename map ────────────────────────────────────────────────
        paths: dict = {}
        for name, items in sections.items():
            paths[name] = self._py_path_from_constants(items)

        has_paths      = sum(1 for p in paths.values() if p)
        path_coverage  = has_paths / max(len(sections), 1)
        all_sect_roots = {name.split('.')[0] for name in sections}

        # ── helper: package name from any path (relative OR absolute) ──────
        def _pkg_from_path(p: str) -> str:
            """Return the top-level package directory, or '' for flat files.

            Relative 'myapp/core.py'           → 'myapp'
            Relative 'utils.py'                → '' (flat)
            Absolute 'C:/proj/myapp/f.py'      → 'myapp' (parent dir, if in blob)
            Absolute '/home/dev/proj/myapp/f.py'→ 'myapp' (same rule)
            """
            if not p:
                return ''
            parts = p.split('/')
            first = parts[0]
            # Relative path with a real directory component
            if first and not (len(first) == 2 and first[1] == ':'):
                if len(parts) == 1:
                    return ''          # flat file  e.g. 'utils.py'
                root = first
                if root.endswith('.py'):
                    return ''          # shouldn't happen but guard anyway
                return root
            # Absolute path (Linux '' first part, or Windows 'C:' drive)
            # Best signal: parent directory of the .py file, if it exists
            # as a top-level module root in the blob.
            if len(parts) >= 2 and parts[-1].endswith('.py'):
                parent = parts[-2]
                if parent and parent in all_sect_roots and is_dev(parent):
                    return parent
            return ''

        def _is_flat_path(p: str) -> bool:
            """True when p is a bare filename with no directory component."""
            return bool(p) and len(p.split('/')) == 1

        # ══ Strategy 1: __main__ co_filename anchor ════════════════════════
        main_path = (paths.get('__main__', '') or
                     paths.get('__parents_main__', ''))
        dev_root  = _pkg_from_path(main_path)

        if dev_root:
            # 1a — packaged project ----------------------------------------
            # Discover additional developer roots imported by __main__
            main_items   = list(sections.get('__main__', ()))
            extra_roots  = set()
            for item in main_items:
                if not isinstance(item, str):
                    continue
                r = item.split('.')[0]
                if (r and r != dev_root
                        and r in all_sect_roots
                        and is_dev(r)
                        and r not in ('__main__', '__init__',
                                      '__builtins__', '__parents_main__')):
                    extra_roots.add(r)
            accepted = {dev_root} | extra_roots

            user = set()
            for name, p in paths.items():
                pkg = _pkg_from_path(p) if p else name.split('.')[0]
                if pkg in accepted:
                    user.add(name)
                elif p and _is_flat_path(p) and is_dev(name):
                    user.add(name)          # flat dev file alongside package
                elif not p and name.split('.')[0] in accepted:
                    user.add(name)          # no-path module in accepted root
            user.update(n for n in ('__main__', '__parents_main__')
                        if n in sections)

            log(f"  [user-nbc] Strategy 1a — packaged: dev_root={dev_root!r}"
                + (f" + extra={sorted(extra_roots)}" if extra_roots else ""))
            log(f"    {len(user)} developer module(s) (from {len(sections)} total)")
            if user: log(f"    Preview: {sorted(user)[:8]}")
            self._user_sections_cache = user
            return user

        if main_path and _is_flat_path(main_path):
            # 1b — flat project: __main__.py at root, no package dir ---------
            # Use __main__'s import graph instead of "all flat is_dev files".
            # Extension modules and single-file third-party packages also have
            # flat paths or no paths, so just passing is_dev() is not enough.
            # The import graph uses KNOWN_LIBRARY_PREFIXES to exclude PIL,
            # brotli, socks, pywintypes etc. even when __main__ imports them.
            _1b_items = list(sections.get('__main__',
                             sections.get('__parents_main__', ())))
            _1b_roots = set()
            for _item in _1b_items:
                if not isinstance(_item, str):
                    continue
                _r = _item.split('.')[0]
                if (_r and _r in all_sect_roots and is_dev(_r)
                        and _r not in ('__main__', '__init__',
                                       '__builtins__', '__parents_main__',
                                       '__module_root__')):
                    _1b_roots.add(_r)
            user = {n for n in ('__main__', '__parents_main__') if n in sections}
            for _name in sections:
                _root = _name.split('.')[0]
                if _root in _1b_roots:
                    # _1b_roots were verified against is_dev() and the module
                    # table, so ALL sub-modules under a discovered dev root are
                    # developer code regardless of path depth.
                    user.add(_name)
            log(f"  [user-nbc] Strategy 1b — flat project import graph: "
                f"roots={sorted(_1b_roots)}, {len(user)} dev module(s)")
            self._user_sections_cache = user
            return user

        # ══ Strategy 2: __main__ import-graph ═════════════════════════════
        # When __main__ has no path (or absolute path we couldn't resolve),
        # scan its string constants for package roots that:
        #   • exist in the module table (all_sect_roots)
        #   • pass is_dev()  ← excludes PIL, customtkinter, cv2, etc.
        # This works even when __main__ directly imports third-party libraries,
        # because those are in KNOWN_LIBRARY_PREFIXES and fail is_dev().
        main_items      = list(sections.get('__main__',
                               sections.get('__parents_main__', ())))
        candidate_roots = set()
        for item in main_items:
            if not isinstance(item, str):
                continue
            r = item.split('.')[0]
            if (r and r in all_sect_roots and is_dev(r)
                    and r not in ('__main__', '__init__',
                                  '__builtins__', '__parents_main__')):
                candidate_roots.add(r)

        # Flat dev files: only include flat .py files whose name root is in
        # candidate_roots (i.e. __main__ imports them AND they pass is_dev).
        # We do NOT include ALL flat is_dev files here because extension modules
        # and single-file third-party packages are also flat with no path.
        flat_devs = {name for name, p in paths.items()
                     if p and _is_flat_path(p) and is_dev(name)
                     and name.split('.')[0] in candidate_roots}

        if candidate_roots or flat_devs:
            user = set()
            for name in sections:
                if name.split('.')[0] in candidate_roots:
                    user.add(name)
            user.update(flat_devs)
            # no-path modules whose name root is in candidate_roots
            for name, p in paths.items():
                if not p and is_dev(name) and name.split('.')[0] in candidate_roots:
                    user.add(name)
            user.update(n for n in ('__main__', '__parents_main__')
                        if n in sections)
            log(f"  [user-nbc] Strategy 2 — import graph: "
                f"roots={sorted(candidate_roots)}, flat={len(flat_devs)}")
            log(f"    {len(user)} developer module(s) (from {len(sections)} total)")
            if user: log(f"    Preview: {sorted(user)[:8]}")
            self._user_sections_cache = user
            return user

        # ══ Strategy 3: path-marker analysis (absolute paths) ══════════════
        if path_coverage >= 0.3:
            stdlib_base = None
            for anchor in self._STDLIB_ANCHORS:
                p = paths.get(anchor, '')
                if not p or '/' not in p:
                    continue
                base = p.rsplit('/', 1)[0].rstrip('/')
                if len(base) > 4:
                    stdlib_base = base
                    break

            user    = set()
            stdlib  = set()
            sitepkg = set()
            for name, p in paths.items():
                if not is_dev(name):
                    stdlib.add(name); continue
                if not p:
                    user.add(name); continue
                p_low = p.lower()
                if any(m.lower() in p_low for m in self._SITEPACKAGES_MARKERS):
                    sitepkg.add(name); continue
                if stdlib_base and p.startswith(stdlib_base):
                    stdlib.add(name); continue
                if any(m.lower() in p_low for m in self._STDLIB_PATH_MARKERS):
                    stdlib.add(name); continue
                pkg = _pkg_from_path(p)
                if pkg:
                    (user if is_dev(pkg) else stdlib).add(name)
                else:
                    user.add(name)       # flat file → developer

            user.update(n for n in ('__main__', '__parents_main__')
                        if n in sections)
            stdlib.discard('__main__'); stdlib.discard('__parents_main__')
            user.discard('__module_root__')

            log(f"  [user-nbc] Strategy 3 — path markers "
                f"({path_coverage*100:.0f}%, stdlib_base={stdlib_base!r}):")
            log(f"    user={len(user)}  stdlib={len(stdlib)}  "
                f"site-pkgs={len(sitepkg)}  pypi_meta={len(pypi_mods)}")
            if user: log(f"    Preview: {sorted(user)[:12]}")
            self._user_sections_cache = user
            return user

        # ══ Strategy 4: KNOWN_LIBRARY_PREFIXES name fallback ══════════════
        log(f"  [user-nbc] Strategy 4 — name fallback (pypi_meta={len(pypi_mods)})")
        result = {name for name in sections if is_dev(name)}
        self._user_sections_cache = result
        return result

    @staticmethod
    def _normalize_decoded_sections(raw_sections):
        """Filter out aggressive-scan artefacts that are truncated duplicates
        of names the linear-chain scan already decoded.

        The aggressive byte-by-byte scanner walks *backwards* looking for
        printable ASCII and stops at the first NUL byte — which in a real
        Nuitka blob often lands **inside** a module name, giving us truncated
        prefixes like `pl.asyncio.foo` (from `xrpl.asyncio.foo`) or
        `rl.parse` (from `urllib.parse`). The linear-chain scan meanwhile
        yields the clean full name. When both scans find the same section
        we want to keep the clean one and drop the truncated one.
        """
        discovered = {}   # clean_name -> original key
        plain = {}        # clean_name (lstripped '.') -> original key
        for key in raw_sections:
            m = re.match(r'^discovered_(.+?)_at_(\d+)$', key)
            if m:
                clean = m.group(1).lstrip('.')
                if clean and not clean.startswith('hidden_segment'):
                    discovered[clean] = key
            else:
                plain[key.lstrip('.')] = key

        def _is_truncated_suffix_of(short, full):
            """True if *short* is a proper suffix of *full* (treated as
            dotted-segment paths). Used so `pl.foo.bar` is recognised as a
            truncation of `xrpl.foo.bar` but `pl.foo.bar` vs
            `other.foo.bar` is not."""
            if short == full:
                return False  # same name, handle separately
            if not full.endswith(short):
                return False
            # what comes before in full must end in the same first component
            # (short shares tail segments and the extra bit is inside the
            # first one)
            prefix = full[: -len(short)]
            return prefix != '' and not prefix.endswith('.')

        # Build the normalised result
        out = {}
        # 1. Keep every plain section as-is (cleaner names win)
        for clean, orig in plain.items():
            out[clean] = raw_sections[orig]

        # 2. For each discovered section, only keep it if it's NOT a truncation
        #    of anything we already have from the linear chain. Keep genuine
        #    injected segments under a `hidden_…` name so they're obvious.
        for clean, orig in discovered.items():
            # Skip if exactly the same as a plain section
            if clean in out:
                continue
            # Skip if it's a proper truncated suffix of any plain name
            if any(_is_truncated_suffix_of(clean, plain_name) for plain_name in plain):
                continue
            out[clean] = raw_sections[orig]

        # 3. Preserve explicitly hidden segments under a clear `hidden_` prefix.
        #    We skip monster segments (>~10k items) because the aggressive
        #    scan will occasionally land on noise that `_decode_count` happily
        #    chews through — those generate multi-megabyte reconstructions
        #    full of garbage. A real Nuitka module rarely has >5k constants.
        HIDDEN_MAX_ITEMS = 10000
        for key, items in raw_sections.items():
            m = re.match(r'^discovered_(.+?)_at_(\d+)$', key)
            if not m:
                continue
            if m.group(1).lstrip('.') and not m.group(1).lstrip('.').startswith('hidden_segment'):
                continue
            if len(items) > HIDDEN_MAX_ITEMS:
                continue
            out[f"hidden_segment_{m.group(2)}"] = items

        return out

    def decode_sections(self):
        """Enumerate every named chunk and decode its constants.

        Returns the `{name: tuple_of_items}` dict. The raw chunk bytes are
        stored separately on self.chunk_raw_bytes so the dumper can embed
        a hex dump in the per-module diagnostic file.

        We use the project's own `parse_blob_modules` (v7 parser) to split
        the blob — it finds 1719 chunks vs the 620 of the Python port of
        `nuitka_deobfuscate.c` (the C code has an alignment bug in its
        aggressive scan). Falls back to `NuitkaBlobDecoder` only if
        `parse_blob_modules` returns nothing.
        """
        sections = {}
        self.chunk_raw_bytes = {}
        try:
            _section_blob_diag = {}
            chunks = parse_blob_modules(
                self.blob, strict=True, diagnostics=_section_blob_diag)
        except Exception:
            chunks = []

        if chunks:
            constants_profile, _profile_diagnostics = \
                _ndl_select_constants_profile(
                    chunks, python_version=self.target_python)
            self.constants_profile = constants_profile
            self.constants_profile_diagnostics = _profile_diagnostics
            for name, chunk_data in chunks:
                if name == '.bytecode':
                    continue
                if self.only_modules and not module_matches_patterns(name, self.only_modules):
                    continue
                try:
                    items = parse_module_constants(
                        chunk_data, python_version=self.target_python,
                        profile=constants_profile)
                except Exception:
                    items = []
                section_name = name or '__module_root__'
                sections[section_name] = tuple(items)
                self.chunk_raw_bytes[section_name] = bytes(chunk_data)
            return sections

        raw = NuitkaBlobDecoder().decode_blob(
            self.blob, python_version=self.target_python)
        sections = self._normalize_decoded_sections(raw)
        if self.only_modules:
            sections = {
                name: items for name, items in sections.items()
                if module_matches_patterns(name, self.only_modules)
            }
        return sections

    def raw_scan_bytecode(self):
        """Run xdis raw scan for embedded marshal code objects. Returns
        [(offset, code_obj), ...] or [] if xdis unavailable."""
        if not XDIS_AVAILABLE:
            return []
        return xdis_raw_scan_for_code_objects(self.blob, self.target_ver_str)

    def write_pycs(self, raw_code_objects, out_dir):
        """Dump raw scan results as .pyc files with correct magic."""
        if not XDIS_AVAILABLE or not raw_code_objects:
            return 0
        out_dir = Path(out_dir)
        header = self._pyc_header()
        written = 0
        for offset, co in raw_code_objects:
            try:
                raw = _xdis_marshal.dumps(co, python_version=self.target_python)
                path = xdis_extract_path_from_code(co)
                label = xdis_extract_code_label(co)
                if path and '<' not in path:
                    dest = out_dir / 'pyc' / xdis_sanitize_filename(path).replace('.py', '.pyc')
                elif label:
                    dest = out_dir / 'pyc' / 'raw_scan' / f"{label}_at_{offset:08x}.pyc"
                else:
                    dest = out_dir / 'pyc' / 'raw_scan' / f"at_{offset:08x}.pyc"
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_bytes(header + raw)
                written += 1
            except Exception:
                continue
        return written

    def _pyc_header(self):
        """Build a valid 16-byte .pyc header for the target Python version."""
        if XDIS_AVAILABLE:
            magic = _xdis_by_version.get(self.target_ver_str)
            if magic:
                mb = bytes(magic)
                return (mb
                        + struct.pack("<I", 0)
                        + struct.pack("<I", int(time.time()))
                        + struct.pack("<I", 0))
        # fallback: use our own table
        return pyc_magic_bytes(self.target_python) + struct.pack("<I", 0) + struct.pack("<I", int(time.time())) + struct.pack("<I", 0)

    @staticmethod
    def _section_name_to_module_path(section_name):
        """Turn a blob-section key into an importable module path (a/b/c.py).

        Handles every shape the NuitkaBlobDecoder emits:

          'Crypto.Cipher.AES'                        -> 'Crypto/Cipher/AES.py'
          '__main__'                                  -> '__main__.py'
          'vendor.vxauth'                             -> 'vendor/vxauth.py'
          '.wmi'                                      -> 'wmi.py'        (leading '.' stripped)
          'discovered_.xrpl.core.types.amount_at_131' -> 'xrpl/core/types/amount.py'
          'discovered_hidden_segment_at_12345'        -> 'hidden/hidden_segment_12345.py'
          '<module foo.bar>'                          -> 'foo/bar.py'
          '<something weird>'                         -> 'unnamed/<hash>.py'
          '' or '.'                                   -> '__module_root__.py'
          'name_dup_3'                                -> 'name__dup3.py'
        """
        if not section_name:
            return '__module_root__.py'

        name = str(section_name).strip()

        # Strip discovered_ prefix + _at_NNN suffix (aggressive-scan artefacts)
        m = re.match(r'^discovered_(.+?)_at_(\d+)$', name)
        if m:
            base = m.group(1).lstrip('.')
            offset = m.group(2)
            if base.startswith('hidden_segment') or not base:
                return f"hidden/hidden_segment_{offset}.py"
            name = base

        # Collision suffix from NuitkaBlobDecoder (`_dup_N`)
        m = re.match(r'^(.+?)_dup_(\d+)$', name)
        if m:
            name = f"{m.group(1)}__dup{m.group(2)}"

        # '<module foo.bar>' -> 'foo.bar'
        m = re.match(r'^<\s*module\s+(.+?)\s*>$', name)
        if m:
            name = m.group(1)

        # Strip leading dots
        name = name.lstrip('.')

        # If what's left contains characters that aren't valid in a module name,
        # fall back to a hash so we don't silently truncate something weird.
        if not name:
            return '__module_root__.py'

        # Dotted names become a directory hierarchy
        parts = [p for p in name.split('.') if p]
        safe_parts = []
        for p in parts:
            # Allow ASCII idents only; fall back to a hash for anything else
            if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', p):
                safe_parts.append(p)
            else:
                import hashlib as _h
                safe_parts.append('_' + _h.md5(p.encode('utf-8')).hexdigest()[:10])

        if not safe_parts:
            return '__module_root__.py'

        return '/'.join(safe_parts) + '.py'

    def omni_reconstruct(self, sections, out_dir, chunk_raw_bytes=None):
        """Reconstruct every blob section as a directory tree.

        For each module we emit THREE artefacts in the same tree layout:

          1. `<module>.py`         — heuristic reconstructed Python source
                                     (real imports + class hierarchy +
                                     pattern-matched function bodies)
          2. `<module>.dump.txt`   — exhaustive human-readable module dump:
                                     every constant in blob order with
                                     type + classification + value, every
                                     ident-tuple paired with its probable
                                     function name, categorised sections
                                     (URLs, error strings, dotted paths,
                                     etc.) and a full hex dump of the
                                     chunk bytes.
          3. `<module>.dump.json`  — same information machine-readable,
                                     for programmatic post-processing.

        The dump is the "pseudo-bytecode" record you asked for: everything
        Nuitka left in the blob about this module, in one place, so that
        a reverse engineer (or another tool) can rebuild the original
        Python source literally from the clues.

        `chunk_raw_bytes` is an optional mapping `{section_name: bytes}`
        used to include the raw chunk in the hex-dump section.
        """
        out_dir = Path(out_dir)
        omni_dir = out_dir / 'omni_reconstructed'
        omni_dir.mkdir(parents=True, exist_ok=True)
        chunk_raw_bytes = chunk_raw_bytes or {}
        written = 0
        dump_written = 0
        used_paths = {}   # rel_path -> collision counter, to dedupe
        manifest = []     # list of {section, rel_path, has_class_def}
        mt_by_name = {e.get('name'): e for e in self.module_table} if self.module_table else {}

        # Native code-object recovery: when a PE + loader table are available
        # we read every function's EXACT co_argcount/flags/varnames out of the
        # PyCode_New* call sites. This is what lifts C-compiled modules from
        # "names only" to real signatures. Built once, reused per module.
        _native_disasm = None
        if CAPSTONE_AVAILABLE and self.pe is not None and self.module_table:
            try:
                _native_disasm = NuitkaStaticDisassembler(
                    self.pe, module_table=self.module_table)
            except Exception:
                _native_disasm = None

        user_nbc_filter = getattr(self, 'user_nbc', False)
        if user_nbc_filter:
            user_set = self._find_user_sections(sections)
            filtered_sections = {k: v for k, v in sections.items() if k in user_set}
            skipped = len(sections) - len(filtered_sections)
            log(f"  --user-nbc: keeping {len(filtered_sections)} developer module(s), "
                f"skipping {skipped} stdlib/third-party")
            sections = filtered_sections

        for name, items in sections.items():
            if not items:
                continue

            items_list = list(items)
            src = None

            # 1) Try the deep smart reconstructor first. It uses the
            #    module's own CodeObjectSpec list (tag 'C') + the full
            #    constants to produce a near-original source file with
            #    real imports, class hierarchies and pattern-matched
            #    function bodies.
            try:
                # Extract code_objects from the constants by recursion
                code_objs = []
                _collect_code_objects_recursive(items_list, name, code_objs)

                # For C-compiled modules the constants carry no 'C' tags, so
                # recover the EXACT code objects from native PyCode_New* sites,
                # plus the faithful per-function body name-traces.
                _body_traces = {}
                _body_sources = {}
                _module_globals = set()
                if not code_objs and _native_disasm is not None:
                    _entry = mt_by_name.get(name)
                    _fp = _entry.get('func_ptr') if _entry else None
                    if _fp:
                        try:
                            code_objs = _native_disasm.recover_code_objects(
                                _fp, items_list)
                        except Exception:
                            code_objs = []
                        try:
                            _body_traces, _body_sources = \
                                _native_disasm.recover_body_traces(
                                    _fp, items_list, code_objects=code_objs)
                        except Exception:
                            _body_traces, _body_sources = {}, {}
                        try:
                            _module_globals = \
                                _native_disasm.recover_module_global_names(
                                    _fp, items_list)
                        except Exception:
                            _module_globals = set()

                smart = StaticalySmartReconstructor(
                    name, items_list, code_objs,
                    body_traces=_body_traces,
                    module_globals=_module_globals,
                    body_sources=_body_sources,
                    native_attempted=bool(_fp),
                )
                smart_src = smart.render()
                if smart_src and ('def ' in smart_src
                                  or 'class ' in smart_src
                                  or 'import ' in smart_src
                                  or not code_objs):
                    src = smart_src
            except Exception:
                src = None

            # 2) Fall back to the OMNI AST synthesiser for modules where
            #    the smart reconstructor didn't find enough structure.
            if src is None:
                try:
                    omp = OmniDecompiler()
                    omp.run_pass_1_structural_mapping(items_list)
                    omp.run_pass_2_ast_synthesis()
                    src = omni_generate_source(omp, name, raw_constants=items_list)
                except Exception:
                    continue

            # Emit anything that has *any* recovered structure (class, def,
            # or a populated constants table). That covers modules that are
            # just a bag of free functions (e.g. `pkg.utils`, `pkg.helpers.strings`)
            # — without this we'd skip most of the application core.
            has_recon = (
                'class ' in src
                or 'def ' in src
                or len(items) >= 4  # any non-trivial constants-only module
            )
            if not has_recon:
                continue

            rel_path = self._section_name_to_module_path(name)
            # Deduplicate if two sections map to the same path
            if rel_path in used_paths:
                used_paths[rel_path] += 1
                base, _, ext = rel_path.rpartition('.')
                rel_path = f"{base}__dup{used_paths[rel_path]}.{ext}"
            else:
                used_paths[rel_path] = 0

            dest = omni_dir / rel_path
            try:
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_text(src, encoding='utf-8')
                written += 1

                # Emit the compact .nbc (Nuitka ByteCode) file. At this
                # point we haven't run the disassembler yet (that happens
                # in disassemble_modules() AFTER omni_reconstruct), so
                # compute the absence reason now: if any requirement for
                # disassembly is missing we embed a clear @NO_OPS block
                # so the downstream LLM knows the file is incomplete.
                if not CAPSTONE_AVAILABLE:
                    _reason = 'capstone_missing'
                elif self.pe is None:
                    _reason = 'no_pe'
                elif not self.module_table:
                    _reason = 'no_module_table'
                else:
                    # disassemble_modules() will overwrite this file with
                    # a version that HAS @OPS if the module is in the
                    # loader table. If not, the @NO_OPS block stays.
                    _in_table = any(e.get('name') == name
                                     and e.get('func_ptr')
                                     and 'BYTECODE' not in e.get('flag_names', [])
                                     and 'EXTENSION' not in e.get('flag_names', [])
                                     for e in self.module_table)
                    _reason = None if _in_table else 'not_in_module_table'
                if _reason is not None:
                    try:
                        nbc_text = NuitkaCompactEmitter.render(
                            module_name=name,
                            constants=items_list,
                            python_version=self.target_python,
                            ops_absence_reason=_reason,
                            module_table_entry=mt_by_name.get(name),
                            chunk_bytes=chunk_raw_bytes.get(name),
                        )
                        nbc_path = dest.with_suffix('.nbc')
                        nbc_path.write_text(nbc_text, encoding='utf-8')
                        dump_written += 1
                    except Exception:
                        pass

                # Stats for the manifest
                try:
                    cls_count = len(omp.classes) if 'omp' in locals() else 0
                    method_count = (sum(len(c.methods) for c in omp.classes.values())
                                    if 'omp' in locals() else 0)
                except Exception:
                    cls_count = method_count = 0
                manifest.append({
                    'section': name,
                    'rel_path': rel_path,
                    'classes': cls_count,
                    'methods': method_count,
                })
            except Exception:
                continue

        # Persist a manifest so you can cross-reference the original
        # section names (some of which are ugly: `discovered_*_at_NNN`) with
        # the clean output tree.
        try:
            import json as _json
            (omni_dir / '_MANIFEST.json').write_text(
                _json.dumps(manifest, indent=2, ensure_ascii=False),
                encoding='utf-8',
            )
        except Exception:
            pass

        return written

    def emit_nbc_placeholders(self, sections, out_dir, chunk_raw_bytes=None):
        """Write constants-only `.nbc` files for modules disasm cannot cover.

        The normal OMNI path creates `.py` reconstructions and placeholder
        `.nbc` files before the disassembler upgrades them. In `--nbc-only`
        mode we skip those `.py` artefacts entirely; this method only emits
        fallback NBC files for modules that will not be overwritten by
        `disassemble_modules()`.
        """
        out_dir = Path(out_dir)
        omni_dir = out_dir / 'omni_reconstructed'
        omni_dir.mkdir(parents=True, exist_ok=True)
        chunk_raw_bytes = chunk_raw_bytes or {}
        mt_by_name = {e.get('name'): e for e in self.module_table} if self.module_table else {}
        manifest = []
        written = 0

        def _path_for(name):
            rel = self._section_name_to_module_path(name)
            return omni_dir / (rel[:-3] + '.nbc' if rel.endswith('.py') else rel + '.nbc')

        user_nbc_filter = getattr(self, 'user_nbc', False)
        if user_nbc_filter:
            user_set = self._find_user_sections(sections)
            filtered_sections = {k: v for k, v in sections.items() if k in user_set}
            skipped = len(sections) - len(filtered_sections)
            log(f"  --user-nbc: keeping {len(filtered_sections)} developer module(s) "
                f"(placeholders), skipping {skipped} stdlib/third-party")
            sections = filtered_sections

        for name, items in sections.items():
            items_list = list(items)
            if not CAPSTONE_AVAILABLE:
                reason = 'capstone_missing'
            elif self.pe is None:
                reason = 'no_pe'
            elif not self.module_table:
                reason = 'no_module_table'
            else:
                entry = mt_by_name.get(name)
                in_table = bool(
                    entry and entry.get('func_ptr')
                    and 'BYTECODE' not in entry.get('flag_names', [])
                    and 'EXTENSION' not in entry.get('flag_names', [])
                )
                reason = None if in_table else 'not_in_module_table'

            if reason is None:
                manifest.append({'section': name, 'rel_path': str(_path_for(name).relative_to(omni_dir)).replace(os.sep, '/')})
                continue

            try:
                nbc_path = _path_for(name)
                nbc_path.parent.mkdir(parents=True, exist_ok=True)
                nbc_text = NuitkaCompactEmitter.render(
                    module_name=name,
                    constants=items_list,
                    python_version=self.target_python,
                    ops_absence_reason=reason,
                    module_table_entry=mt_by_name.get(name),
                    chunk_bytes=chunk_raw_bytes.get(name),
                )
                nbc_path.write_text(nbc_text, encoding='utf-8')
                written += 1
                manifest.append({
                    'section': name,
                    'rel_path': str(nbc_path.relative_to(omni_dir)).replace(os.sep, '/'),
                    'nbc_only': True,
                    'reason': reason,
                })
            except Exception:
                continue

        try:
            (omni_dir / '_MANIFEST.json').write_text(
                json.dumps(manifest, indent=2, ensure_ascii=False),
                encoding='utf-8',
            )
        except Exception:
            pass
        return written

    def disassemble_modules(self, output_dir, max_modules=None, max_bytes=16384,
                             sections=None, max_funcs_per_module=1000):
        """Disassemble each compiled module's native entry point.

        Requires `self.pe` (pefile.PE) and `self.module_table` to be set at
        construction time. Emits `<module>.disasm.txt` in the same tree as
        `omni_reconstructed/` so the .py / .dump.txt / .disasm.txt sit next
        to each other.

        This is the "reconstruct the logic statically" step: for each
        compiled-module function we extract the x86-64 instructions from
        .text at that function's VA, identify every call + RIP-relative
        constant load, resolve IAT slots to Python-C-API names and direct
        calls to the module that owns them (via the loader table).

        Returns how many modules were successfully disassembled.
        """
        if not CAPSTONE_AVAILABLE:
            return 0
        if self.pe is None or not self.module_table:
            return 0

        output_dir = Path(output_dir)
        omni_dir = output_dir / 'omni_reconstructed'
        omni_dir.mkdir(parents=True, exist_ok=True)

        disasm = NuitkaStaticDisassembler(self.pe,
                                           module_table=self.module_table)
        written = 0
        targets = [e for e in self.module_table
                   if e.get('func_ptr')
                   and 'BYTECODE' not in e.get('flag_names', [])
                   and 'EXTENSION' not in e.get('flag_names', [])]

        # --user-nbc: filter to developer modules identified by _find_user_sections.
        # Re-use the cached result computed by omni_reconstruct/emit_nbc_placeholders
        # (same run); if not yet computed, compute now using the provided sections.
        if getattr(self, 'user_nbc', False):
            user_names = self._user_sections_cache
            if user_names is None and sections:
                user_names = self._find_user_sections(sections)
            if user_names is not None:
                before = len(targets)
                targets = [e for e in targets if e.get('name') in user_names]
                log(f"  --user-nbc: {len(targets)} developer module(s) selected "
                    f"for disassembly (skipped {before - len(targets)} library entries)")

        if max_modules:
            targets = targets[:max_modules]

        # Apply the --only filter before expensive work in --nbc-only mode.
        # We still sample a small context window from the rest of the binary for
        # helper ranking, but full recursive disassembly is limited to the
        # requested modules immediately.
        only = getattr(self, 'only_modules', None)
        if only and self.nbc_only:
            filtered = [e for e in targets
                        if module_matches_patterns(e['name'], only)]
            log(f"  --only filter: {len(filtered)} of {len(targets)} "
                f"module(s) match {only}")
            selected_vas = {e.get('func_ptr') for e in filtered}
            context = [e for e in targets if e.get('func_ptr') not in selected_vas]
            stats_targets = filtered + context[:48]
            if len(stats_targets) < len(targets):
                log(f"  Runtime-helper prepass: sampling "
                    f"{len(stats_targets)}/{len(targets)} module entries "
                    f"({len(filtered)} selected + context)")
            targets = filtered
        else:
            stats_targets = targets

        # Pre-pass: count how many times each internal address is called.
        # The most-called ones are Nuitka runtime helpers; the aliases stay
        # consistent across every module's disassembly so helper usage remains
        # traceable without recursively disassembling the runtime in each file.
        try:
            CALL_STATS_CONTEXT_LIMIT = 120
            if len(stats_targets) > CALL_STATS_CONTEXT_LIMIT:
                stats_targets = stats_targets[:CALL_STATS_CONTEXT_LIMIT]
                log(f"  Runtime-helper prepass: sampling "
                    f"{len(stats_targets)}/{len(targets)} module entries")
            runtime_aliases, call_counter = disasm.build_module_call_stats(stats_targets)
        except Exception:
            runtime_aliases, call_counter = {}, {}

        # In the full pipeline, apply --only after call-stats so ranking is
        # computed on the full sample while recursive rendering stays focused.
        if only and not self.nbc_only:
            filtered = [e for e in targets
                        if module_matches_patterns(e['name'], only)]
            log(f"  --only filter: {len(filtered)} of {len(targets)} "
                f"module(s) match {only}")
            targets = filtered

        # Write the runtime-helper inventory once, at the top of the tree
        try:
            inv_path = omni_dir / 'NUITKA_RUNTIME_HELPERS.txt'
            inv_lines = ['# Nuitka runtime helpers ranked by call frequency',
                         '# (aliases are used in per-module .disasm.txt files)',
                         '# Rank  CallCount  Alias                     Address', '']
            for rank, (va, count) in enumerate(call_counter.most_common()):
                alias = runtime_aliases.get(va, f'fn_0x{va:X}')
                inv_lines.append(f'  {rank:4d}  {count:9d}  {alias:<24s}  0x{va:X}')
            inv_path.write_text('\n'.join(inv_lines), encoding='utf-8')
        except Exception:
            pass

        def _nbc_path_for(mod_name):
            rel = StaticalyExtractor._section_name_to_module_path(mod_name)
            return omni_dir / (rel[:-3] + '.nbc'
                               if rel.endswith('.py') else rel + '.nbc')

        def _write_fallback_nbc(entry, mod_consts, reason='disasm_failed'):
            mod_name = entry.get('name', '')
            nbc_path = _nbc_path_for(mod_name)
            nbc_path.parent.mkdir(parents=True, exist_ok=True)
            text = NuitkaCompactEmitter.render(
                module_name=mod_name,
                constants=mod_consts,
                python_version=self.target_python,
                ops_absence_reason=reason,
                module_table_entry=entry,
                chunk_bytes=getattr(self, 'chunk_raw_bytes', {}).get(mod_name),
            )
            nbc_path.write_text(text, encoding='utf-8')

        for entry in targets:
            mod_name = entry['name']
            func_ptr = entry['func_ptr']
            mod_consts = list(sections[mod_name]) if (sections and mod_name in sections) else []
            try:
                # Recursively disassemble the module entry AND every
                # module-local function it reaches via `call`. Nuitka
                # compiles every Python def as its own C entry point, so
                # without this step each function body in the .nbc
                # reduces to a signature skeleton (no @OPS). The BFS
                # stops at runtime helpers and sibling-module entries.
                infos = disasm.analyse_function_recursive(
                    func_ptr,
                    runtime_aliases=runtime_aliases,
                    max_funcs=max_funcs_per_module,
                    max_bytes_per_fn=max_bytes,
                )
                if not infos:
                    _write_fallback_nbc(entry, mod_consts, 'disasm_failed')
                    continue

                # Aggregate ALL const_loads from every function to
                # estimate mod_consts_base across the whole module.
                # (A single function's loads may miss the base; the
                # union across all of them is dense enough.)
                all_const_loads = []
                for _va, _info in infos.items():
                    all_const_loads.extend(_info['const_loads'])
                base, _cnt = NuitkaStaticDisassembler._estimate_mod_consts_base(
                    all_const_loads, len(mod_consts))

                # Replace / upgrade the .nbc that omni_reconstruct already
                # wrote (or write a fresh one for modules that weren't
                # decoded via omni).
                nbc_path = _nbc_path_for(mod_name)
                nbc_path.parent.mkdir(parents=True, exist_ok=True)

                nbc_text = NuitkaCompactEmitter.render(
                    module_name=mod_name,
                    constants=mod_consts,
                    python_version=self.target_python,
                    disasm_infos=infos,
                    mod_consts_base=base,
                    runtime_aliases=runtime_aliases,
                    entry_va=func_ptr,
                    module_table_entry=entry,
                    chunk_bytes=getattr(self, 'chunk_raw_bytes', {}).get(mod_name),
                    include_native_asm=getattr(self, 'include_native_asm', False),
                )

                # Guard against runaway file size. Kept high so
                # we rarely hit it — and when we do, KEEP the impl
                # bodies (the important part) and DROP the short
                # wrapper stubs (3-4 op blocks that contain no source
                # information). Wrappers are identified by tiny
                # instruction count AND membership in the helper
                # range; bodies are everything else.
                HARD_CAP_BYTES = 128_000_000
                if len(nbc_text.encode('utf-8', errors='replace')) > HARD_CAP_BYTES:
                    # Strategy: keep entry + every block with
                    # `instruction_count >= 30` (real code). Drop
                    # anything tiny (wrappers / registration stubs).
                    keep = {}
                    for _va, _info in infos.items():
                        if _va == func_ptr:
                            keep[_va] = _info
                            continue
                        if _info.get('instruction_count', 0) >= 30:
                            keep[_va] = _info
                    nbc_text = NuitkaCompactEmitter.render(
                        module_name=mod_name,
                        constants=mod_consts,
                        python_version=self.target_python,
                        disasm_infos=keep,
                        mod_consts_base=base,
                        runtime_aliases=runtime_aliases,
                        entry_va=func_ptr,
                        module_table_entry=entry,
                        chunk_bytes=getattr(self, 'chunk_raw_bytes', {}).get(mod_name),
                        include_native_asm=getattr(self, 'include_native_asm', False),
                    )
                    # If STILL too large after dropping wrappers, chop
                    # the lowest-instruction-count bodies until under
                    # the cap.
                    if len(nbc_text.encode('utf-8', errors='replace')) > HARD_CAP_BYTES:
                        sorted_by_size = sorted(
                            keep.items(),
                            key=lambda kv: (
                                0 if kv[0] == func_ptr else 1,  # entry always first
                                -kv[1].get('instruction_count', 0),
                            ),
                        )
                        # Binary-search how many top-N bodies fit
                        lo, hi = 1, len(sorted_by_size)
                        best_text = nbc_text
                        while lo <= hi:
                            mid = (lo + hi) // 2
                            subset = dict(sorted_by_size[:mid])
                            candidate = NuitkaCompactEmitter.render(
                                module_name=mod_name,
                                constants=mod_consts,
                                python_version=self.target_python,
                                disasm_infos=subset,
                                mod_consts_base=base,
                                runtime_aliases=runtime_aliases,
                                entry_va=func_ptr,
                                module_table_entry=entry,
                                chunk_bytes=getattr(self, 'chunk_raw_bytes', {}).get(mod_name),
                                include_native_asm=getattr(self, 'include_native_asm', False),
                            )
                            if len(candidate.encode('utf-8', errors='replace')) <= HARD_CAP_BYTES:
                                best_text = candidate
                                lo = mid + 1
                            else:
                                hi = mid - 1
                        nbc_text = best_text

                nbc_path.write_text(nbc_text, encoding='utf-8')
                written += 1
            except Exception:
                try:
                    _write_fallback_nbc(entry, mod_consts, 'disasm_failed')
                except Exception:
                    pass
                continue
        return written

    def run(self, output_dir):
        """Execute the full Staticaly pipeline and return a result dict."""
        output_dir = Path(output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)

        result = {
            'target_python': self.target_ver_str,
            'xdis_available': XDIS_AVAILABLE,
            'capstone_available': CAPSTONE_AVAILABLE,
            'sections': 0,
            'raw_scan_pyc': 0,
            'omni_reconstructed': 0,
            'nbc_files': 0,
            'modules_disassembled': 0,
            'output_dir': str(output_dir),
        }

        sections = self.decode_sections()
        result['sections'] = len(sections)

        if self.nbc_only:
            result['nbc_only'] = True
            result['raw_scan_pyc'] = 0
            result['omni_reconstructed'] = 0
            result['nbc_placeholders'] = self.emit_nbc_placeholders(
                sections, output_dir,
                chunk_raw_bytes=getattr(self, 'chunk_raw_bytes', {}),
            )
        else:
            raw_hits = self.raw_scan_bytecode()
            result['raw_scan_pyc'] = self.write_pycs(raw_hits, output_dir)

            result['omni_reconstructed'] = self.omni_reconstruct(
                sections, output_dir,
                chunk_raw_bytes=getattr(self, 'chunk_raw_bytes', {}),
            )
        # count nbc files on disk
        try:
            dump_dir = Path(output_dir) / 'omni_reconstructed'
            result['nbc_files'] = len(list(dump_dir.rglob('*.nbc')))
        except Exception:
            result['nbc_files'] = 0

        # Static disassembly of compiled modules (only if pe + module_table
        # were provided at construction — typically from NuitkalizatorPro).
        # Pass `sections` so the renderer can resolve every mod_consts load
        # to its real Python literal.
        if CAPSTONE_AVAILABLE and self.pe is not None and self.module_table:
            try:
                result['modules_disassembled'] = self.disassemble_modules(
                    output_dir, sections=sections)
            except Exception as _e:
                result['modules_disassembled'] = 0
            try:
                dump_dir = Path(output_dir) / 'omni_reconstructed'
                result['nbc_files'] = len(list(dump_dir.rglob('*.nbc')))
            except Exception:
                pass

        return result


# =============================================================================
# BYTECODE EXTRACTION (from .bytecode chunk)  v7 — cross-Python-version safe
# =============================================================================

# Full CPython magic table (covers every release from 2.7 to 3.14)
# Each magic is the u16 value defined in CPython's Python/importlib.h.
# The on-disk header is always: <u16 magic><\r\n><u32 flags><u32 mtime><u32 size>
# = 16 bytes total (PEP 552, 3.7+). Pre-3.7 uses 12 bytes (no flags).
PYC_MAGIC_NUMBERS = {
    (2, 7): 62211,
    (3, 0): 3130, (3, 1): 3150, (3, 2): 3180, (3, 3): 3230,
    (3, 4): 3310, (3, 5): 3351, (3, 6): 3379,
    (3, 7): 3394, (3, 8): 3413, (3, 9): 3425, (3, 10): 3439,
    (3, 11): 3495, (3, 12): 3531, (3, 13): 3571, (3, 14): 3627,
}


def pyc_magic_bytes(python_version):
    """Return the 4-byte magic header for the given (major, minor) target."""
    num = PYC_MAGIC_NUMBERS.get(tuple(python_version[:2]))
    if num is None:
        raise ValueError(
            f"unknown PYC magic for target Python {python_version!r}")
    return num.to_bytes(2, 'little') + b'\r\n'


def write_pyc_from_marshal(marshal_data: bytes, output_path: str, python_version):
    """Write a valid .pyc file from raw marshal data (no deserialization required).

    This means we DON'T need the running Python to match the target version —
    we simply wrap the raw marshal blob with the correct header. A decompiler
    like pycdc reads the header to determine which opcode table to use.
    """
    os.makedirs(os.path.dirname(output_path) or '.', exist_ok=True)
    magic = pyc_magic_bytes(python_version)
    flags = (0).to_bytes(4, 'little')        # PEP 552 flags (0 = timestamp-based)
    mtime = int(time.time()).to_bytes(4, 'little')
    src_size = (0).to_bytes(4, 'little')
    with open(output_path, 'wb') as f:
        # 3.7+ header is 16 bytes; older is 12 (no flags). Use 16 for safety
        # (pycdc and 3.7+ interpreters ignore flags when 0 anyway).
        if tuple(python_version[:2]) >= (3, 7):
            f.write(magic + flags + mtime + src_size + marshal_data)
        else:
            f.write(magic + mtime + src_size + marshal_data)
    return True


def create_pyc_file(code_obj, output_path, python_version=None):
    """Create a valid .pyc file from a code object. Kept for backward compat."""
    os.makedirs(os.path.dirname(output_path) or '.', exist_ok=True)
    if python_version is None:
        python_version = sys.version_info[:2]
    if not isinstance(code_obj, types.CodeType):
        return False
    marshalled = marshal.dumps(code_obj)
    return write_pyc_from_marshal(marshalled, output_path, python_version)


def _iter_bytecode_marshaled(bytecode_chunk: bytes, constants_profile=None):
    """Yield validated ``(loader_index, marshal_bytes)`` entries.

    BlobData ``X`` changed from a fixed signed i32 size to VLQ in Nuitka 2.4.
    Parse the complete part before yielding so malformed tails cannot produce a
    trusted partial loader-index mapping.
    """
    if (not isinstance(bytecode_chunk, (bytes, bytearray))
            or len(bytecode_chunk) < 2):
        return
    profile = (constants_profile or _NDL_SELECTED_CONSTANTS_PROFILE
               or "modern_vlq31")
    if profile not in _NDL_CONSTANTS_PROFILES:
        return
    count = struct.unpack_from('<H', bytecode_chunk, 0)[0]
    pos = 2
    size_total = len(bytecode_chunk)
    entries = []
    for index in range(count):
        if pos >= size_total or bytecode_chunk[pos] != 0x58:
            return
        pos += 1
        if profile == "modern_vlq31":
            value = 0
            shift = 0
            for group in range(10):
                if pos >= size_total:
                    return
                byte = bytecode_chunk[pos]
                pos += 1
                payload = byte & 0x7f
                if group == 9 and payload > 1:
                    return
                value |= payload << shift
                if byte < 0x80:
                    if group and payload == 0:
                        return
                    break
                shift += 7
            else:
                return
        else:
            if pos + 4 > size_total:
                return
            value = struct.unpack_from('<i', bytecode_chunk, pos)[0]
            pos += 4
        end = pos + value
        if value <= 0 or end > size_total:
            return
        entries.append((index, bytes(bytecode_chunk[pos:end])))
        pos = end
    if pos != size_total - 1 or bytecode_chunk[pos:pos + 1] != b'.':
        return
    yield from entries


def _bytecode_marshal_at_index(bytecode_chunk: bytes, wanted_index: int,
                               constants_profile=None):
    """Return the exact marshalled code object at a Nuitka loader-table index.

    ``meta_path_loader_entries[].bytecode_index`` addresses the BlobData array
    stored in the ``.bytecode`` constants chunk.  It is *not* an index into a
    filename-filtered code-object scan.  Keeping this parser byte-oriented also
    makes exact extraction work when host and target Python versions differ.
    """
    try:
        wanted_index = int(wanted_index)
    except Exception:
        return None
    if wanted_index < 0:
        return None
    for index, data in _iter_bytecode_marshaled(
            bytecode_chunk, constants_profile=constants_profile):
        if index == wanted_index:
            return data
    return None


def _bytecode_index_name_map(bytecode_chunk: bytes, python_version,
                             constants_profile=None):
    """Recover the real loader index -> module-name relation from co_filename."""
    result = {}
    same_version = tuple((python_version or ())[:2]) == sys.version_info[:2]
    for index, marshal_data in _iter_bytecode_marshaled(
            bytecode_chunk, constants_profile=constants_profile):
        filename = ''
        if same_version:
            try:
                code = marshal.loads(marshal_data)
                if isinstance(code, types.CodeType):
                    filename = code.co_filename or ''
            except Exception:
                pass
        if not filename:
            filename = _guess_filename_from_marshal(marshal_data)
        rel = _sanitize_module_path(filename, index).replace('\\', '/')
        if not rel or rel.startswith('module_'):
            continue
        if rel.endswith('/__init__.py'):
            rel = rel[:-len('/__init__.py')]
        elif rel.endswith('.py'):
            rel = rel[:-3]
        name = rel.strip('/').replace('/', '.')
        if re.fullmatch(r'[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*', name):
            result[index] = name
    return result


_MARSHAL_FILENAME_RE = re.compile(
    rb'((?:[A-Za-z_][A-Za-z0-9_]*[\\/])*[A-Za-z_][A-Za-z0-9_]*\.py)')


def _guess_filename_from_marshal(marshal_data: bytes, max_scan: int = 4096) -> str:
    """Best-effort: scan marshal bytes for a *.py filename string.

    Marshal stores strings as TYPE_SHORT_ASCII (0x7A/0xFA), TYPE_ASCII (0x61/0xE1),
    TYPE_STRING (0x73/0xF3), etc. — each followed by length + raw bytes. We
    don't need to parse; just look for a short printable ASCII blob ending
    with .py, which in practice is the co_filename.
    """
    m = _MARSHAL_FILENAME_RE.search(marshal_data[:max_scan])
    if m:
        try:
            return m.group(1).decode('ascii', errors='replace')
        except Exception:
            pass
    return ""


def _sanitize_module_path(filename: str, bytecode_index: int) -> str:
    """Convert a co_filename like 'asyncio\\base_events.py' or 'lib/asyncio/base.py'
    into a safe relative path 'asyncio/base_events.py'.
    """
    fn = filename.replace('\\', '/').strip()
    if not fn:
        return f"module_{bytecode_index:04d}.py"

    # Drop absolute prefixes / drive letters / common Python lib roots
    low = fn.lower()
    for marker in ('/site-packages/', '/lib/', 'python310/lib/',
                   'python310\\lib\\', 'lib\\python', '/python/', '\\python\\'):
        idx = low.find(marker)
        if idx != -1:
            fn = fn[idx + len(marker):]
            low = fn.lower()

    # Drop drive letter
    if len(fn) > 2 and fn[1] == ':':
        fn = fn[2:].lstrip('/')

    # Clean up
    fn = fn.replace('..', '__').strip('/')
    fn = re.sub(r'[<>:"|?*]', '_', fn)

    if not fn or fn == '.py':
        return f"module_{bytecode_index:04d}.py"

    if not fn.endswith('.py'):
        # could be package init or something else, force .py
        if fn.endswith('.pyc'):
            fn = fn[:-1]
        else:
            fn = fn + '.py'

    return fn


def extract_bytecode_modules(bytecode_chunk: bytes, output_dir: str,
                             python_version, constants_profile=None):
    """Extract .pyc modules from the .bytecode chunk (Nuitka constants blob).

    Format (from Nuitka DataComposer.py):
      [count:u16_LE]
      [ 'X' (0x58) + profile_size + marshal_blob ] * count
      [ '.'  end-of-stream marker ]

    v7 improvements over v6:
      - Magic header is that of the TARGET Python, not the running interpreter
        (so decompilers parse opcodes correctly even when run from a different py)
      - Filenames are taken either from marshal.loads (if same-version Python)
        OR scanned directly from marshal bytes (cross-version safe)
      - Raw marshal blobs are dumped alongside .pyc for forensic use
      - Output mirrors the original package tree (asyncio/base_events.pyc)
      - VLQ reader handles the full uint64 range
      - A MANIFEST.json records the full index -> path mapping
    """
    if len(bytecode_chunk) < 4:
        return 0, {}

    count = struct.unpack('<H', bytecode_chunk[0:2])[0]
    log(f".bytecode chunk: {count} compiled modules (target Python {python_version[0]}.{python_version[1]})")

    py_match = tuple(python_version[:2]) == sys.version_info[:2]
    if py_match:
        log_ok(f"  Running Python matches target ({python_version[0]}.{python_version[1]}) — full marshal parsing available")
    else:
        log_warn(f"  Running Python {sys.version_info[0]}.{sys.version_info[1]} != target {python_version[0]}.{python_version[1]}")
        log_warn(f"  Will fall back to filename-string scanning when marshal.loads fails")

    profile = (constants_profile or _NDL_SELECTED_CONSTANTS_PROFILE
               or "modern_vlq31")
    validated_entries = list(_iter_bytecode_marshaled(
        bytecode_chunk, constants_profile=profile))
    if len(validated_entries) != count:
        log_warn("  .bytecode framing/profile validation failed; no partial "
                 "PYC files were emitted")
        return 0, {}
    entry_map = dict(validated_entries)
    extracted = 0
    parse_errors = 0
    pyc_dir = os.path.join(output_dir, "bytecode_pyc")
    marshal_dir = os.path.join(output_dir, "bytecode_marshal_raw")
    os.makedirs(pyc_dir, exist_ok=True)
    os.makedirs(marshal_dir, exist_ok=True)

    manifest = {}   # bytecode_index -> {path, size, name, co_filename, parsed}
    pb = ProgressBar(count, desc="Extracting .pyc")

    used_paths = {}   # to deduplicate colliding filenames

    for i in range(count):
        pb.update()
        marshal_data = entry_map[i]
        marshal_size = len(marshal_data)

        # Try to parse with marshal (works if same Python version)
        co = None
        co_filename = ""
        co_name = ""
        try:
            obj = marshal.loads(marshal_data)
            if isinstance(obj, types.CodeType):
                co = obj
                co_filename = obj.co_filename or ""
                co_name = obj.co_name or ""
        except Exception:
            parse_errors += 1

        # If marshal parsing failed (different Python version), scan bytes for
        # the filename string directly.
        if not co_filename:
            co_filename = _guess_filename_from_marshal(marshal_data)

        # Build a safe relative path from the filename
        rel_path = _sanitize_module_path(co_filename, i)

        # Deduplicate in case two modules share the same co_filename
        if rel_path in used_paths:
            used_paths[rel_path] += 1
            base, ext = os.path.splitext(rel_path)
            rel_path = f"{base}__dup{used_paths[rel_path]}{ext}"
        else:
            used_paths[rel_path] = 0

        # .pyc output
        pyc_rel = rel_path[:-3] + '.pyc' if rel_path.endswith('.py') else rel_path + '.pyc'
        pyc_path = os.path.join(pyc_dir, pyc_rel)
        write_pyc_from_marshal(marshal_data, pyc_path, python_version)

        # Raw marshal dump (forensic)
        marshal_flat_name = f"{i:04d}_{rel_path.replace('/', '__').replace(os.sep, '__')}.marshal"
        marshal_path = os.path.join(marshal_dir, marshal_flat_name)
        with open(marshal_path, 'wb') as f:
            f.write(marshal_data)

        manifest[i] = {
            'index': i,
            'co_filename': co_filename,
            'co_name': co_name,
            'marshal_size': marshal_size,
            'pyc_path': os.path.relpath(pyc_path, output_dir).replace(os.sep, '/'),
            'marshal_path': os.path.relpath(marshal_path, output_dir).replace(os.sep, '/'),
            'parsed_with_marshal': co is not None,
        }
        extracted += 1

    pb.finish(f"Extracted {extracted}/{count} (.pyc + .marshal)"
              + (f" — {parse_errors} marshal parse errors" if parse_errors else ""))

    # Write manifest
    manifest_path = os.path.join(output_dir, "BYTECODE_MANIFEST.json")
    with open(manifest_path, 'w', encoding='utf-8') as f:
        json.dump({
            'target_python': f"{python_version[0]}.{python_version[1]}",
            'magic_hex': pyc_magic_bytes(python_version).hex(),
            'total_modules': extracted,
            'parse_errors': parse_errors,
            'entries': list(manifest.values()),
        }, f, indent=2, ensure_ascii=False)
    log_ok(f"  Manifest: {manifest_path}")

    return extracted, manifest


# =============================================================================
# SECRETS SCANNER
# =============================================================================

SECRET_PATTERNS = [
    (r'(?:password|passwd|pwd)\s*[:=]\s*["\'](.+?)["\']', 'password'),
    (r'(?:api[_-]?key|apikey)\s*[:=]\s*["\'](.+?)["\']', 'api_key'),
    (r'(?:secret|token)\s*[:=]\s*["\'](.+?)["\']', 'secret_token'),
    (r'(?:flag|ctf)\s*[:={}]\s*["\']?([A-Za-z0-9_{}!@#$%^&*]+)', 'flag'),
    (r'FLAG\{[^}]+\}', 'flag'),
    (r'(?:mysql|postgres|mongodb|redis)://[^\s"\']+', 'database_url'),
    (r'(?:https?://[^\s"\']+)', 'url'),
    (r'(?:sk-[A-Za-z0-9]{20,})', 'openai_key'),
    (r'(?:ghp_[A-Za-z0-9]{36,})', 'github_token'),
    (r'(?:AKIA[A-Z0-9]{16})', 'aws_key'),
    (r'(?:eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,})', 'jwt_token'),
    (r'-----BEGIN (?:RSA |EC )?PRIVATE KEY-----', 'private_key'),
    (r'(?:Bearer\s+[A-Za-z0-9_\-.]+)', 'bearer_token'),
]

KEYWORD_PATTERNS = [
    'password', 'secret', 'flag', 'token', 'api_key', 'private',
    'encrypt', 'decrypt', 'hash', 'salt', 'admin', 'root',
    'check_password', 'verify', 'authenticate', 'login',
    'Enter the secret', 'Enter password',
]


def scan_for_secrets(constants: list, module_name: str = "") -> list:
    """Scan a list of constants for secrets and interesting patterns."""
    findings = []

    def _scan_value(val, depth=0):
        if depth > 5:
            return
        if isinstance(val, str) and len(val) > 2:
            for pattern, secret_type in SECRET_PATTERNS:
                matches = re.findall(pattern, val, re.IGNORECASE)
                for match in matches:
                    findings.append({
                        'type': secret_type,
                        'value': match if isinstance(match, str) else val,
                        'module': module_name,
                        'context': val[:200]
                    })
            for keyword in KEYWORD_PATTERNS:
                if keyword.lower() in val.lower():
                    findings.append({
                        'type': 'keyword_match',
                        'value': keyword,
                        'module': module_name,
                        'context': val[:200]
                    })
            if 8 <= len(val) <= 128 and re.match(r'^[A-Za-z0-9_!@#$%^&*{}]+$', val):
                if not val.startswith(('http', 'file', 'ftp', 'ssh')):
                    entropy = _calc_entropy(val)
                    if entropy > 3.0:
                        findings.append({
                            'type': 'possible_password',
                            'value': val,
                            'module': module_name,
                            'entropy': round(entropy, 2)
                        })

        elif (isinstance(val, tuple) and val and isinstance(val[0], str)
              and val[0].startswith('_nuitka_')):
            return
        elif isinstance(val, (tuple, list)):
            for item in val:
                _scan_value(item, depth + 1)
        elif isinstance(val, dict):
            if val.get('_type') == 'unknown':
                return
            for k, v in val.items():
                _scan_value(k, depth + 1)
                _scan_value(v, depth + 1)
        elif isinstance(val, (set, frozenset)):
            for item in val:
                _scan_value(item, depth + 1)

    for const in constants:
        _scan_value(const)

    return findings


def _calc_entropy(s: str) -> float:
    if not s: return 0
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1
    length = len(s)
    entropy = -sum((count / length) * math.log2(count / length)
                    for count in freq.values())
    return entropy


# =============================================================================
# CODE OBJECT MAP (from C-compiled modules)
# =============================================================================

def _collect_code_objects_recursive(val, module_name, acc):
    """Walk a parsed-constants value and collect every nested CodeObject dict."""
    if isinstance(val, dict) and val.get('_type') == 'CodeObject':
        # Filter out artefacts: names must be printable identifiers or <module>
        name = val.get('name') or ''
        qualname = val.get('qualname') or name
        if isinstance(name, str) and name and not name.startswith('<parse_error>'):
            # Reject garbage from GenericAlias mis-parses (huge-int qualnames)
            if len(str(qualname)) > 300:
                return
            if isinstance(name, bytes):
                name = name.decode('ascii', errors='replace')
            val = dict(val)
            val['name'] = name
            val['module'] = module_name
            acc.append(val)
        return
    if isinstance(val, (list, tuple)):
        for it in val:
            _collect_code_objects_recursive(it, module_name, acc)
    elif isinstance(val, dict):
        for v in val.values():
            _collect_code_objects_recursive(v, module_name, acc)


def extract_code_object_map(module_name: str, chunk_data: bytes,
                            python_version=None, profile: str = None) -> list:
    """Extract code object signatures from a module constants chunk.

    Correct approach: parse the chunk normally via `parse_module_constants`,
    then walk the resulting tree and pluck every dict tagged as CodeObject.
    This avoids false positives from scanning byte-wise for 'C' (0x43), which
    appears inside large integers, byte strings, GenericAlias numeric args, etc.
    """
    try:
        constants = parse_module_constants(
            chunk_data, python_version=python_version, profile=profile)
    except Exception:
        return []

    code_objects = []
    for c in constants:
        _collect_code_objects_recursive(c, module_name, code_objects)

    # Also deduplicate on (name, line, argcount) — the same code object may
    # appear both as a standalone constant AND inside a containing tuple.
    seen = set()
    unique = []
    for co in code_objects:
        key = (co.get('name'), co.get('qualname'), co.get('line'),
               co.get('argcount'), tuple(co.get('args') or ()))
        if key in seen:
            continue
        seen.add(key)
        unique.append(co)
    return unique


# =============================================================================
# PER-MODULE CONSTANTS PARSER
# =============================================================================

def _decode_constants_stream_orig(stream_data: bytes, count: int, *, python_version=None,
                             start_pos: int = 0, int_mode: str = "vlq",
                             profile: str = None,
                             return_diagnostics: bool = False,
                             node_budget=None, max_depth: int = 128) -> tuple:
    """Decode *count* constants from a raw constants stream.

    This is the stateful core used by both normal chunks and aggressive scans.
    The `'p'` previous-value marker is stream-local in Nuitka, so resetting it
    here avoids cross-module contamination and keeps `None` constants intact.
    """
    global _last_unpacked, _CURRENT_NUITKA_BLOB_INT_MODE
    global _CURRENT_NUITKA_BLOB_PROFILE
    _last_unpacked = _NO_NUITKA_PREVIOUS
    old_target = _CURRENT_NUITKA_TARGET_PYTHON
    old_int_mode = _CURRENT_NUITKA_BLOB_INT_MODE
    old_profile = _CURRENT_NUITKA_BLOB_PROFILE
    if profile is None:
        profile = ("hybrid_1_9_to_2_3"
                   if int_mode == "fixed32" else "modern_vlq31")
    if profile not in _NDL_CONSTANTS_PROFILES:
        raise ValueError(f"unknown Nuitka constants profile: {profile}")
    _CURRENT_NUITKA_BLOB_PROFILE = profile
    _CURRENT_NUITKA_BLOB_INT_MODE = (
        "vlq" if profile == "modern_vlq31" else "fixed32")
    set_nuitka_target_python(python_version or old_target)

    pos = start_pos
    constants = []
    state = _new_nuitka_decode_budget(
        stream_data, start_pos, node_budget=node_budget, max_depth=max_depth)
    diagnostics = {
        'aborted': False,
        'reason': None,
        'abort_pos': None,
        'requested_count': count,
        'decoded_count': 0,
        'node_budget': state.initial_nodes,
        'nodes_used': 0,
        'max_depth': state.max_depth,
        'max_seen_depth': 0,
        'int_mode': _CURRENT_NUITKA_BLOB_INT_MODE,
        'profile': profile,
    }

    try:
        count = _validate_constant_sequence(stream_data, pos, count, state)
        for _ in range(count):
            if pos >= len(stream_data):
                break
            val, new_pos = unpack_single_constant(
                stream_data, pos, _decoder_state=state, _depth=0)
            if new_pos <= pos:
                diagnostics['reason'] = 'decoder made no forward progress'
                break
            pos = new_pos
            if val is _Nuitka_END_OF_STREAM:
                diagnostics['reason'] = 'end of stream'
                break
            if val is _Nuitka_PARSE_ERROR:
                diagnostics['reason'] = 'unrecognized or truncated constant tag'
                break
            constants.append(val)
    except _NuitkaDecoderAbort as exc:
        diagnostics['aborted'] = True
        diagnostics['reason'] = exc.reason
        diagnostics['abort_pos'] = exc.pos
        pos = max(pos, min(exc.pos, len(stream_data)))
        constants.append({
            '_type': 'unknown',
            'offset': exc.pos,
            'byte': (stream_data[exc.pos] if 0 <= exc.pos < len(stream_data)
                     else None),
            'context_hex': stream_data[
                max(0, exc.pos - 8):min(len(stream_data), exc.pos + 9)].hex(),
            'reason': exc.reason,
        })
    except Exception as exc:
        # Aggressive candidate scans operate on arbitrary bytes. A malformed
        # candidate must be rejected, not escape and terminate the whole scan.
        diagnostics['aborted'] = True
        diagnostics['reason'] = f"{type(exc).__name__}: {exc}"
        diagnostics['abort_pos'] = pos
        constants.append({
            '_type': 'unknown', 'offset': pos,
            'byte': (stream_data[pos] if 0 <= pos < len(stream_data) else None),
            'context_hex': stream_data[
                max(0, pos - 8):min(len(stream_data), pos + 9)].hex(),
            'reason': diagnostics['reason'],
        })
    finally:
        diagnostics['decoded_count'] = sum(
            not (isinstance(item, dict) and item.get('_type') == 'unknown')
            for item in constants)
        diagnostics['diagnostic_nodes'] = (
            len(constants) - diagnostics['decoded_count'])
        diagnostics['nodes_used'] = state.initial_nodes - state.nodes_remaining
        diagnostics['max_seen_depth'] = state.max_seen_depth
        _last_unpacked = _NO_NUITKA_PREVIOUS
        _CURRENT_NUITKA_BLOB_INT_MODE = old_int_mode
        _CURRENT_NUITKA_BLOB_PROFILE = old_profile
        set_nuitka_target_python(old_target)

    if return_diagnostics:
        return constants, pos, diagnostics
    return constants, pos


def _ndl_constant_values_equivalent(left, right, _depth=0):
    """Compare profile outputs, treating equal NaNs as structurally equal."""
    if _depth > 140 or type(left) is not type(right):
        return False
    if isinstance(left, float):
        return left == right or (left != left and right != right)
    if isinstance(left, complex):
        return (_ndl_constant_values_equivalent(left.real, right.real,
                                                _depth + 1)
                and _ndl_constant_values_equivalent(left.imag, right.imag,
                                                    _depth + 1))
    if isinstance(left, (list, tuple)):
        return (len(left) == len(right)
                and all(_ndl_constant_values_equivalent(a, b, _depth + 1)
                        for a, b in zip(left, right)))
    if isinstance(left, dict):
        if len(left) != len(right):
            return False
        return all(
            _ndl_constant_values_equivalent(ka, kb, _depth + 1)
            and _ndl_constant_values_equivalent(va, vb, _depth + 1)
            for (ka, va), (kb, vb) in zip(left.items(), right.items()))
    if isinstance(left, (set, frozenset)):
        return repr(left) == repr(right)
    try:
        return left == right
    except Exception:
        return repr(left) == repr(right)


def _ndl_unknown_constants_result(reason, *, count=0, offset=0,
                                  candidate_diagnostics=(), data=None):
    raw = bytes(data) if isinstance(
        data, (bytes, bytearray, memoryview)) else b''
    offset = max(0, int(offset))
    unknown = {
        '_type': 'unknown', 'offset': offset,
        'byte': (raw[offset] if offset < len(raw) else None),
        'context_hex': raw[
            max(0, offset - 8):min(len(raw), offset + 9)].hex(),
        'reason': str(reason),
    }
    diagnostics = {
        'aborted': True, 'exact': False, 'reason': str(reason),
        'abort_pos': offset, 'requested_count': int(count),
        'decoded_count': 0, 'profile': None,
    }
    return _NuitkaConstantsList(
        [unknown], declared_count=count, end_pos=offset,
        diagnostics=diagnostics,
        candidate_diagnostics=list(candidate_diagnostics))


# V100: wrapper auto-selezione layout qualname per il tag code-object.
# Alcune versioni Nuitka emettono il bit qualname anche su Python < 3.11
# (bit0), spostando freevars/kwonly/posonly di un bit.  Il decode canonico
# viene provato per primo; se il chunk non decodifica EXACT, si riprova
# con la variante qualname-all e vince chi chiude lo stream.
def _decode_constants_stream(stream_data, count, *args, **kwargs):
    global _CURRENT_CO_QUALNAME_ALL_PY
    _saved = _CURRENT_CO_QUALNAME_ALL_PY

    def _ok(d):
        # successo: exact esplicito OPPURE nessun abort (il decoder dello
        # stream non imposta 'exact' — lo fa il chiamante col terminatore)
        return bool(d.get('exact')) or not d.get('reason')
    try:
        r = _decode_constants_stream_orig(stream_data, count, *args,
                                          **kwargs)
        if _ok(r[2]):
            return r
        _CURRENT_CO_QUALNAME_ALL_PY = True
        try:
            r2 = _decode_constants_stream_orig(stream_data, count, *args,
                                               **kwargs)
        except Exception:
            return r
        return r2 if _ok(r2[2]) else r
    finally:
        _CURRENT_CO_QUALNAME_ALL_PY = _saved


def parse_module_constants(chunk_data: bytes, python_version=None,
                           profile: str = None) -> list:
    """Decode one DataComposer part under an exact source-backed profile.

    A successful part is precisely ``<H count> + count values + b'.'``.  No
    trailing bytes, early terminator, partial candidate, or heuristic score is
    accepted.  Unknown/malformed input is preserved as a diagnostic node.
    """
    if not isinstance(chunk_data, (bytes, bytearray, memoryview)):
        return _ndl_unknown_constants_result(
            "module constants chunk is not bytes-like")
    chunk_data = bytes(chunk_data)
    if len(chunk_data) < 3:
        return _ndl_unknown_constants_result(
            "module constants chunk is shorter than <H> plus terminator",
            offset=len(chunk_data), data=chunk_data)
    count = struct.unpack_from('<H', chunk_data, 0)[0]

    selected = profile or _NDL_SELECTED_CONSTANTS_PROFILE
    if selected is not None and selected not in _NDL_CONSTANTS_PROFILES:
        return _ndl_unknown_constants_result(
            f"unknown constants profile {selected!r}", count=count,
            offset=2, data=chunk_data)
    profiles = (selected,) if selected else _NDL_CONSTANTS_PROFILES
    exact = []
    candidate_diagnostics = []

    for candidate_profile in profiles:
        vals, pos, diagnostics = _decode_constants_stream(
            chunk_data, count, python_version=python_version,
            start_pos=2, profile=candidate_profile,
            return_diagnostics=True)
        dot_at_eof = (pos == len(chunk_data) - 1
                      and chunk_data[pos:pos + 1] == b'.')
        is_exact = (not diagnostics.get('aborted')
                    and len(vals) == count and dot_at_eof)
        diagnostics.update({
            'exact': is_exact,
            'end_pos': pos,
            'terminator_at_eof': dot_at_eof,
            'trailing_bytes': max(0, len(chunk_data) - (pos + 1)),
        })
        candidate_diagnostics.append(diagnostics)
        if is_exact:
            exact.append((candidate_profile, vals, pos, diagnostics))

    if not exact:
        furthest = max(
            candidate_diagnostics,
            key=lambda d: int(d.get('end_pos') or d.get('abort_pos') or 0),
            default={})
        reason = furthest.get('reason') or (
            "no constants profile consumed the declared values and final dot "
            "exactly")
        return _ndl_unknown_constants_result(
            reason, count=count,
            offset=int(furthest.get('end_pos') or
                       furthest.get('abort_pos') or 2),
            candidate_diagnostics=candidate_diagnostics,
            data=chunk_data)

    first_profile, first_vals, first_pos, first_diag = exact[0]
    if any(not _ndl_constant_values_equivalent(first_vals, other_vals)
           for _profile, other_vals, _pos, _diag in exact[1:]):
        return _ndl_unknown_constants_result(
            "ambiguous constants profiles produced different exact values",
            count=count, offset=first_pos,
            candidate_diagnostics=candidate_diagnostics,
            data=chunk_data)

    chosen = next(
        (item for item in exact
         if item[0] == (_NDL_SELECTED_CONSTANTS_PROFILE or
                        "modern_vlq31")),
        exact[0])
    chosen_profile, vals, pos, diagnostics = chosen
    diagnostics = dict(diagnostics)
    diagnostics['exact'] = True
    if len(exact) > 1:
        diagnostics['profile_ambiguous_equivalent'] = [
            item[0] for item in exact]
    return _NuitkaConstantsList(
        vals, declared_count=count,
        int_mode=diagnostics.get('int_mode'), profile=chosen_profile,
        end_pos=pos, diagnostics=diagnostics,
        candidate_diagnostics=candidate_diagnostics)


def _ndl_select_constants_profile(module_chunks, python_version=None):
    """Select one profile using exact evidence from every module chunk."""
    global _NDL_SELECTED_CONSTANTS_PROFILE
    _NDL_SELECTED_CONSTANTS_PROFILE = None
    survivors = list(_NDL_CONSTANTS_PROFILES)
    divergent_pairs = set()
    checked = 0
    evidence_chunks = 0
    decoded = 0
    malformed_chunks = []

    for name, chunk in module_chunks or ():
        checked += 1
        outputs = {}
        next_survivors = []
        for candidate in survivors:
            result = parse_module_constants(
                chunk, python_version=python_version, profile=candidate)
            if result.diagnostics.get('exact'):
                next_survivors.append(candidate)
                outputs[candidate] = result
        if not next_survivors:
            # Distinguish a damaged chunk from a mixed-profile blob. A chunk
            # valid only under an already-eliminated profile is positive
            # evidence that no one global DataComposer grammar can explain it.
            for candidate in _NDL_CONSTANTS_PROFILES:
                if candidate in survivors:
                    continue
                result = parse_module_constants(
                    chunk, python_version=python_version, profile=candidate)
                if result.diagnostics.get('exact'):
                    outputs[candidate] = result
            if outputs:
                _NDL_SELECTED_CONSTANTS_PROFILE = 'unresolved'
                return None, {
                    'ok': False,
                    'reason': 'no_single_profile_for_all_chunks',
                    'valid_profiles_for_conflicting_chunk': sorted(outputs),
                    'conflicting_chunk': name,
                    'checked_chunks': checked,
                    'evidence_chunks': evidence_chunks,
                    'decoded_constants': decoded,
                    'malformed_chunks': malformed_chunks,
                }
            # Invalid under all profiles: retain the framed module as an
            # unknown diagnostic and use other intact chunks as evidence.
            malformed_chunks.append(name)
            continue
        survivors = next_survivors
        evidence_chunks += 1
        decoded += len(next(iter(outputs.values()))) if outputs else 0
        for index, left_profile in enumerate(survivors):
            for right_profile in survivors[index + 1:]:
                if not _ndl_constant_values_equivalent(
                        outputs[left_profile], outputs[right_profile]):
                    divergent_pairs.add(tuple(sorted(
                        (left_profile, right_profile))))

    if not checked or not evidence_chunks:
        _NDL_SELECTED_CONSTANTS_PROFILE = 'unresolved'
        return None, {
            'ok': False, 'reason': ('no_module_constant_chunks' if not checked
                                    else 'no_valid_profile_witness'),
            'checked_chunks': checked, 'evidence_chunks': evidence_chunks,
            'decoded_constants': decoded,
            'malformed_chunks': malformed_chunks,
        }
    live_pairs = [pair for pair in divergent_pairs
                  if pair[0] in survivors and pair[1] in survivors]
    if len(survivors) > 1 and live_pairs:
        _NDL_SELECTED_CONSTANTS_PROFILE = 'unresolved'
        return None, {
            'ok': False, 'reason': 'ambiguous_constant_profile',
            'survivors': survivors, 'divergent_pairs': live_pairs,
            'checked_chunks': checked, 'evidence_chunks': evidence_chunks,
            'decoded_constants': decoded,
            'malformed_chunks': malformed_chunks,
        }
    if not survivors:
        # Fallback: prova tutti i profili in ordine di probabilità
        for fallback in ("modern_vlq31", "hybrid_1_9_to_2_3",
                         "legacy_through_1_8_6"):
            if module_chunks:
                test_result = parse_module_constants(
                    module_chunks[0][1],
                    python_version=python_version,
                    profile=fallback)
                if test_result.diagnostics.get('exact'):
                    chosen = fallback
                    break
        else:
            chosen = "modern_vlq31"
    else:
        chosen = ("modern_vlq31" if "modern_vlq31" in survivors else survivors[0])
    _NDL_SELECTED_CONSTANTS_PROFILE = chosen
    return chosen, {
        'ok': True, 'profile': chosen, 'survivors': survivors,
        'profile_ambiguous_equivalent': (
            survivors if len(survivors) > 1 else []),
        'checked_chunks': checked, 'evidence_chunks': evidence_chunks,
        'decoded_constants': decoded,
        'malformed_chunks': malformed_chunks,
    }


# =============================================================================
# STRING EXTRACTION (recursive)
# =============================================================================

def extract_all_strings(constants: list, *, max_depth: int = 25) -> list:
    """Extract ALL strings from a list of constants (recursive).

    Visits: str, tuple/list, dict (keys+values), set/frozenset, CodeObject dicts.
    Deduplicates while preserving order.
    """
    seen = set()
    out = []

    def add(s: str):
        if not s:
            return
        if s in seen:
            return
        seen.add(s)
        out.append(s)

    def walk(v, depth: int):
        if depth > max_depth:
            return

        if isinstance(v, str):
            add(v)
            return

        # Nuitka constants can contain bytes/bytearray; optionally harvest readable text.
        if isinstance(v, (bytes, bytearray)):
            b = bytes(v)
            if not b:
                return
            # Heuristic: try UTF-8, and only keep if looks mostly printable.
            try:
                s = b.decode("utf-8")
            except Exception:
                return
            printable = sum(1 for ch in s if ch.isprintable() or ch in "\r\n\t")
            if printable / max(len(s), 1) >= 0.85:
                add(s)
            return

        # Structural decoder markers are metadata, not strings from the target.
        if isinstance(v, tuple) and v and isinstance(v[0], str):
            if v[0].startswith('_nuitka_'):
                return
            if v[0] in ("slice", "range", "GenericAlias", "UnionType"):
                for item in v[1:]:
                    walk(item, depth + 1)
                return

        if isinstance(v, (tuple, list)):
            for item in v:
                walk(item, depth + 1)
            return

        if isinstance(v, dict):
            if v.get('_type') == 'unknown':
                return
            for k, val in v.items():
                walk(k, depth + 1)
                walk(val, depth + 1)
            return

        if isinstance(v, (set, frozenset)):
            for item in v:
                walk(item, depth + 1)
            return

    for c in constants:
        walk(c, 0)

    return out


# =============================================================================
# BYTECODE DECOMPILATION HELPERS (Phase 12)
# =============================================================================

def _detect_decompiler(py_ver=None):
    """Return a list of decompilers to try in order, from best to worst.

    Each entry is a dict:
        {'kind': 'pycdc'|'pycdas'|'decompyle3'|'uncompyle6'|'pylingual'|'pydis',
         'binary': str|None,  # path for external tools
         'priority': int}      # lower = tried first
    """
    import subprocess, shutil
    target_ver = py_ver or (0, 0)
    available = []

    def _check_bin(bin_name, kind):
        # Search common install locations AND PATH
        search_paths = []
        for d in (r'C:\pycdc', r'C:\tools\pycdc', r'C:\Program Files\pycdc',
                  r'C:\Program Files (x86)\pycdc',
                  os.path.expanduser('~'), os.path.expanduser('~/pycdc')):
            for ext in ('', '.exe'):
                search_paths.append(os.path.join(d, bin_name + ext))
        for path in ([shutil.which(bin_name), shutil.which(bin_name + '.exe')]
                     + [p for p in search_paths if os.path.isfile(p)]):
            if not path:
                continue
            # run_external_tool swallows crashes + hides console windows
            r = run_external_tool([path, '--help'], timeout=5)
            if r.returncode >= 0 and not (0xC0000000 <= (r.returncode & 0xFFFFFFFF) <= 0xCFFFFFFF):
                return path
        return None

    # 1. pycdc (ancient bytecode support 1.0 through 3.13) — best for 3.10+
    pycdc = _check_bin('pycdc', 'pycdc')
    if pycdc:
        priority = 1 if target_ver >= (3, 10) else 3
        available.append({'kind': 'pycdc', 'binary': pycdc, 'priority': priority})

    # 2. pycdas (disassembler from pycdc project) — always useful as last resort
    pycdas = _check_bin('pycdas', 'pycdas')
    if pycdas:
        available.append({'kind': 'pycdas', 'binary': pycdas, 'priority': 9})

    # 3. decompile3 / decompyle3 — best for Python 3.7-3.9, partial 3.10
    if target_ver <= (3, 9):
        for mod, label, prio in [('decompile3', 'decompile3', 1),
                                  ('decompyle3', 'decompyle3', 2),
                                  ('uncompyle6', 'uncompyle6', 4)]:
            try:
                __import__(mod)
                available.append({'kind': label, 'binary': None, 'priority': prio})
            except ImportError:
                continue
    else:
        # For 3.10+ try them anyway as fallback
        for mod, label in [('decompile3', 'decompile3'),
                            ('decompyle3', 'decompyle3'),
                            ('uncompyle6', 'uncompyle6')]:
            try:
                __import__(mod)
                available.append({'kind': label, 'binary': None, 'priority': 6})
            except ImportError:
                continue

    # 4. pylingual (newer 3.12/3.13 decompiler) — if installed
    try:
        __import__('pylingual')
        available.append({'kind': 'pylingual', 'binary': None, 'priority': 2})
    except ImportError:
        pass

    available.sort(key=lambda d: d['priority'])
    return available


def _try_autoinstall_pycdc():
    """Best-effort: try to clone + build pycdc. Returns path or None."""
    log_warn("  pycdc not found. Trying pip install decompyle3/uncompyle6 as fallback...")
    for pkg in ('decompyle3', 'uncompyle6'):
        r = run_external_tool(
            [sys.executable, '-m', 'pip', 'install', pkg],
            timeout=120,
        )
        if r.returncode == 0:
            log_ok(f"  Installed {pkg}")
    return None


def _decompile_pyc(pyc_path, out_py_path, decompiler_info):
    """Decompile a .pyc file using one of the configured backends.

    decompiler_info is a dict from _detect_decompiler() or list of such dicts.
    Each candidate is tried in order until one produces non-empty output.

    Robustness:
      * Every external-tool invocation goes through `run_external_tool`
        (which suppresses Windows crash dialogs, catches timeouts and
        OSErrors instead of letting them propagate).
      * A process-wide counter tracks how many times each decompiler kind
        returns a hard crash (returncode < 0 or returncode >= 1000 on
        Windows = 0xc0000xxx access violation range). After 10 consecutive
        crashes for the same kind we DISABLE that backend for the rest of
        the run — otherwise a bad .pyc can kill throughput because every
        subsequent file re-triggers the crash.
      * Python-module decompilers (decompyle3 / uncompyle6 / decompile3)
        are called inside try/except; any exception just falls through
        to the next candidate, never propagates.
    """
    # Support either a single dict (legacy) or a list of candidates
    if isinstance(decompiler_info, dict):
        candidates = [decompiler_info]
    elif isinstance(decompiler_info, (list, tuple)):
        if len(decompiler_info) == 2 and isinstance(decompiler_info[0], str):
            candidates = [{'kind': decompiler_info[0], 'binary': decompiler_info[1]}]
        else:
            candidates = list(decompiler_info)
    else:
        return False

    # Persistent per-kind crash counter (lives on the function object)
    crash_counts = getattr(_decompile_pyc, '_crash_counts', None)
    if crash_counts is None:
        crash_counts = {}
        _decompile_pyc._crash_counts = crash_counts
    disabled = getattr(_decompile_pyc, '_disabled_kinds', None)
    if disabled is None:
        disabled = set()
        _decompile_pyc._disabled_kinds = disabled
    MAX_CRASHES = 10     # after this many consecutive crashes, disable the backend

    def _mark_crash(k):
        crash_counts[k] = crash_counts.get(k, 0) + 1
        if crash_counts[k] >= MAX_CRASHES and k not in disabled:
            disabled.add(k)
            try:
                log_warn(f"  [fallback] disabling {k!r} after {MAX_CRASHES} "
                         f"consecutive crashes — using remaining backends only")
            except Exception:
                pass

    def _mark_success(k):
        crash_counts[k] = 0   # reset streak on success

    def _is_crash(returncode):
        # Returncode < 0 = killed by signal (Unix) or timeout;
        # on Windows returncode >= 0xC0000000 (unsigned) means access
        # violation / unhandled SEH / etc.
        if returncode < 0:
            return True
        return 0xC0000000 <= (returncode & 0xFFFFFFFF) <= 0xCFFFFFFF

    for info in candidates:
        kind = info.get('kind')
        binary = info.get('binary')
        if kind in disabled:
            continue

        try:
            if kind == 'pycdc':
                r = run_external_tool([binary, pyc_path], timeout=45)
                if _is_crash(r.returncode):
                    _mark_crash('pycdc')
                    continue
                src = r.stdout.decode('utf-8', errors='replace')
                if src.strip():
                    is_incomplete = ('Decompyle incomplete' in src
                                     or 'Unsupported opcode' in src)
                    if is_incomplete:
                        bin_dir = os.path.dirname(binary)
                        bin_name = os.path.basename(binary).replace('pycdc', 'pycdas')
                        pycdas_bin = os.path.join(bin_dir, bin_name)
                        if os.path.isfile(pycdas_bin) and 'pycdas' not in disabled:
                            r2 = run_external_tool([pycdas_bin, pyc_path], timeout=45)
                            if _is_crash(r2.returncode):
                                _mark_crash('pycdas')
                            else:
                                dis_text = r2.stdout.decode('utf-8', errors='replace')
                                if dis_text.strip():
                                    src += ("\n\n"
                                            "# =========================================================\n"
                                            "# pycdc decompilation was incomplete — appending full\n"
                                            "# bytecode DISASSEMBLY from pycdas for manual reading.\n"
                                            "# =========================================================\n\n")
                                    src += dis_text
                    try:
                        with open(out_py_path, 'w', encoding='utf-8') as f:
                            f.write(src)
                        if os.path.getsize(out_py_path) > 20:
                            _mark_success('pycdc')
                            return True
                    except Exception:
                        pass
                # Empty output = treat as soft failure, not a crash
                continue

            elif kind == 'pycdas':
                r = run_external_tool([binary, pyc_path], timeout=45)
                if _is_crash(r.returncode):
                    _mark_crash('pycdas')
                    continue
                out = r.stdout.decode('utf-8', errors='replace')
                if out.strip():
                    try:
                        with open(out_py_path, 'w', encoding='utf-8') as f:
                            f.write("# === pycdas DISASSEMBLY (no source recovery) ===\n")
                            f.write(out)
                        if os.path.getsize(out_py_path) > 20:
                            _mark_success('pycdas')
                            return True
                    except Exception:
                        pass
                continue

            elif kind == 'decompile3':
                try:
                    from decompile3 import decompile_file as _dc
                except ImportError:
                    from decompile import decompile as _dc
                with open(out_py_path, 'w', encoding='utf-8') as f:
                    _dc(pyc_path, f)
                if os.path.getsize(out_py_path) > 20:
                    _mark_success('decompile3')
                    return True

            elif kind == 'decompyle3':
                import decompyle3
                with open(out_py_path, 'w', encoding='utf-8') as f:
                    decompyle3.decompile_file(pyc_path, f)
                if os.path.getsize(out_py_path) > 20:
                    _mark_success('decompyle3')
                    return True

            elif kind == 'uncompyle6':
                import uncompyle6
                with open(out_py_path, 'w', encoding='utf-8') as f:
                    uncompyle6.decompile_file(pyc_path, f)
                if os.path.getsize(out_py_path) > 20:
                    _mark_success('uncompyle6')
                    return True

            elif kind == 'pylingual':
                import pylingual
                try:
                    src = pylingual.decompile_file(pyc_path)
                except AttributeError:
                    src = pylingual.decompile(pyc_path)
                if src:
                    with open(out_py_path, 'w', encoding='utf-8') as f:
                        f.write(src)
                    _mark_success('pylingual')
                    return True

        except Exception:
            # Python-module decompiler raised — count as a soft crash so
            # we eventually disable it if it keeps failing, but never
            # let it bubble up and abort the outer loop.
            _mark_crash(kind or 'unknown')
            continue

    return False

    return False


def _is_code(obj):
    """True if obj is a code object (works across Python versions)."""
    return hasattr(obj, 'co_code') or hasattr(obj, 'co_code_adaptive')


def _make_func_src(co, indent=''):
    """Return lines of pseudo-source for a function/method code object."""
    import dis
    ii = indent + '    '
    lines = []

    # Build argument list from co_varnames
    nargs = co.co_argcount
    nkw   = getattr(co, 'co_kwonlyargcount', 0)
    flags = co.co_flags
    vnames = co.co_varnames

    args = list(vnames[:nargs])
    kw_args = list(vnames[nargs:nargs + nkw])
    idx = nargs + nkw
    if flags & 0x04:   # CO_VARARGS
        args.append('*' + (vnames[idx] if idx < len(vnames) else 'args'))
        idx += 1
    elif kw_args:
        args.append('*')
    args.extend(f'{a}=None' for a in kw_args)
    if flags & 0x08:   # CO_VARKEYWORDS
        args.append('**' + (vnames[idx] if idx < len(vnames) else 'kwargs'))

    is_async = bool(flags & (0x80 | 0x200))  # coroutine or async generator
    kw = 'async def' if is_async else 'def'
    lines.append(f"{indent}{kw} {co.co_name}({', '.join(args)}):")

    # Docstring (first const if it's a non-empty string)
    doc = co.co_consts[0] if co.co_consts and isinstance(co.co_consts[0], str) and co.co_consts[0] else None
    if doc:
        if '\n' in doc:
            lines.append(f'{ii}"""')
            for dl in doc.splitlines():
                lines.append(f'{ii}{dl}')
            lines.append(f'{ii}"""')
        else:
            lines.append(f'{ii}"""{doc}"""')

    # Body: analyse bytecode for patterns
    body = _extract_body(co, ii)
    if body:
        lines.extend(body)
    else:
        lines.append(f'{ii}...')
    return lines


def _extract_body(co, indent):
    """
    Walk instructions to extract recognisable Python patterns.
    Returns a list of source lines (may be empty if nothing found).
    """
    import dis
    ii = indent + '    '
    lines = []
    try:
        instrs = list(dis.get_instructions(co))
    except Exception:
        return []

    i = 0
    seen_names = set()   # avoid duplicate STORE_NAME output
    seen_funcs = set()   # avoid emitting same function name twice (try/except branches)

    while i < len(instrs):
        instr = instrs[i]
        op    = instr.opname

        # Skip noise opcodes
        if op in ('RESUME', 'COPY_FREE_VARS', 'CACHE', 'PRECALL',
                  'NOP', 'RETURN_CONST'):
            i += 1
            continue

        # ── import X  /  from X import Y ────────────────────────────────────
        if op == 'IMPORT_NAME':
            mod = instr.argval
            j = i + 1
            # skip LOAD_ATTR chains (relative imports)
            froms = []
            aliases = []
            while j < len(instrs) and instrs[j].opname == 'IMPORT_FROM':
                froms.append(instrs[j].argval)
                if j + 1 < len(instrs) and instrs[j+1].opname in ('STORE_NAME','STORE_FAST','STORE_GLOBAL'):
                    aliases.append(instrs[j+1].argval)
                    j += 2
                else:
                    j += 1
            if froms:
                pairs = []
                for f, a in zip(froms, aliases if len(aliases) == len(froms) else froms):
                    pairs.append(f"{f} as {a}" if a != f else f)
                lines.append(f"{indent}from {mod} import {', '.join(pairs)}")
                i = j
                # POP_TOP after the last import_from group
                if i < len(instrs) and instrs[i].opname == 'POP_TOP':
                    i += 1
                continue
            # plain import [as alias]
            if j < len(instrs) and instrs[j].opname in ('STORE_NAME','STORE_FAST','STORE_GLOBAL'):
                alias = instrs[j].argval
                if alias != mod:
                    lines.append(f"{indent}import {mod} as {alias}")
                else:
                    lines.append(f"{indent}import {mod}")
                i = j + 1
            else:
                lines.append(f"{indent}import {mod}")
                i = j
            continue

        # ── constant assignment  LOAD_CONST → STORE_* ───────────────────────
        if op == 'LOAD_CONST' and not _is_code(instr.argval):
            j = i + 1
            while j < len(instrs) and instrs[j].opname in ('COPY', 'DUP_TOP'):
                j += 1
            if j < len(instrs) and instrs[j].opname in ('STORE_NAME','STORE_FAST','STORE_GLOBAL','STORE_DEREF'):
                name = instrs[j].argval
                val  = instr.argval
                # Skip docstring (already emitted) and None returns
                if not (isinstance(val, str) and val and i == 1):
                    if name not in seen_names and not name.startswith('.'):
                        lines.append(f"{indent}{name} = {repr(val)}")
                        seen_names.add(name)
                i = j + 1
                continue

        # ── function definition  MAKE_FUNCTION ──────────────────────────────
        if op == 'MAKE_FUNCTION':
            # search backward for the code-object LOAD_CONST
            func_co = None
            for j in range(max(0, i - 6), i):
                if instrs[j].opname == 'LOAD_CONST' and _is_code(instrs[j].argval):
                    func_co = instrs[j].argval
                    break
            _skip = ('<listcomp>','<dictcomp>','<setcomp>','<genexpr>','<lambda>')
            if func_co is not None and func_co.co_name not in _skip:
                if func_co.co_name not in seen_funcs:
                    lines.append('')
                    lines.extend(_make_func_src(func_co, indent))
                    seen_funcs.add(func_co.co_name)
            i += 1
            continue

        # ── class definition  LOAD_BUILD_CLASS ──────────────────────────────
        if op == 'LOAD_BUILD_CLASS':
            # Next MAKE_FUNCTION carries the class body code object
            j = i + 1
            cls_co = None
            while j < len(instrs) and instrs[j].opname != 'MAKE_FUNCTION':
                if instrs[j].opname == 'LOAD_CONST' and _is_code(instrs[j].argval):
                    cls_co = instrs[j].argval
                j += 1
            if cls_co is not None and cls_co.co_name not in seen_funcs:
                lines.append('')
                lines.extend(_make_class_src(cls_co, indent))
                seen_funcs.add(cls_co.co_name)
            i = j + 1
            continue

        # ── RETURN_VALUE / RETURN CONST ─────────────────────────────────────
        if op == 'RETURN_VALUE':
            # peek at what's on the "stack" — look back for a LOAD
            if i > 0:
                prev = instrs[i - 1]
                if prev.opname == 'LOAD_CONST' and prev.argval is not None:
                    lines.append(f"{indent}return {repr(prev.argval)}")
                elif prev.opname in ('LOAD_NAME','LOAD_FAST','LOAD_GLOBAL','LOAD_DEREF'):
                    name = prev.argval
                    if isinstance(name, str):
                        lines.append(f"{indent}return {name}")
            i += 1
            continue

        i += 1

    return lines


def _make_class_src(co, indent=''):
    """Return lines of pseudo-source for a class body code object."""
    ii = indent + '    '
    lines = []

    # Determine base classes: look for LOAD_NAME instructions before MAKE_FUNCTION
    # (class name comes from co_name of the class body's code object)
    lines.append(f"{indent}class {co.co_name}:")

    # Docstring
    doc = co.co_consts[0] if co.co_consts and isinstance(co.co_consts[0], str) and co.co_consts[0] else None
    if doc:
        lines.append(f'{ii}"""{doc}"""')

    # Find method code objects in co_consts (they are nested code objects)
    methods = [c for c in co.co_consts if _is_code(c)
               and c.co_name not in ('<listcomp>','<dictcomp>','<setcomp>','<genexpr>','<lambda>')]
    # Also look in _extract_body for MAKE_FUNCTION patterns
    body = _extract_body(co, ii)
    # Avoid emitting duplicate method defs from both methods and body
    emitted = {ln.strip().split('(')[0].replace('def ', '').replace('async def ', '').strip()
               for ln in body if 'def ' in ln}
    extra_methods = [m for m in methods if m.co_name not in emitted]

    if body:
        lines.extend(body)
    for m in extra_methods:
        lines.append('')
        lines.extend(_make_func_src(m, ii))
    if not body and not extra_methods:
        lines.append(f'{ii}pass')
    return lines


def _pyc_dis(pyc_path, out_path):
    """Convert a .pyc to readable pseudo-source (no external decompiler needed)."""
    import dis, marshal, io
    try:
        with open(pyc_path, 'rb') as f:
            f.read(16)   # magic + flags + mtime + size (PEP 552)
            raw = f.read()
        co = marshal.loads(raw)

        buf = io.StringIO()
        mod_name = os.path.splitext(os.path.basename(pyc_path))[0]
        buf.write(f"# Module: {mod_name}\n")
        buf.write(f"# Pseudo-source reconstructed from bytecode (no decompiler)\n\n")

        # Module-level body
        body_lines = _extract_body(co, '')
        for ln in body_lines:
            buf.write(ln + '\n')

        # Any top-level code objects that MAKE_FUNCTION missed
        seen = set()
        for ln in body_lines:
            s = ln.strip()
            for prefix in ('async def ', 'def ', 'class '):
                if s.startswith(prefix):
                    name = s[len(prefix):].split('(')[0].split(':')[0].strip()
                    seen.add(name)
                    break
        for const in co.co_consts:
            if not _is_code(const):
                continue
            name = const.co_name
            if name in seen or name in ('<listcomp>','<dictcomp>','<setcomp>','<genexpr>','<lambda>','<module>'):
                continue
            buf.write('\n')
            func_lines = _make_func_src(const, '')
            buf.write('\n'.join(func_lines) + '\n')
            seen.add(name)

        content = buf.getvalue().strip()
        if not content:
            content = f"# Module: {mod_name}\n# (empty or unrecognised bytecode)\n"

        with open(out_path, 'w', encoding='utf-8') as f:
            f.write(content + '\n')
        return True
    except Exception as e:
        try:
            with open(out_path, 'w', encoding='utf-8') as f:
                f.write(f"# {os.path.basename(pyc_path)}: parse error — {e}\n")
        except Exception:
            pass
        return False


# =============================================================================
# MAIN EXTRACTION ENGINE
# =============================================================================

class NuitkalizatorPro:
    """Main engine for static extraction.

    Pipeline:
    1. PE analysis (Python version, Nuitka edition)
    2. Constants blob extraction (PE resources or embedded)
    3. Protected metadata detection and normalization
    4. Blob parsing into named modules
    5. .pyc extraction from .bytecode chunk
    6. Per-module constants parsing
    7. Code object map (function signatures)
    8. Secrets scanner
    9. JSON report
    """

    def __init__(self, target_path: str, output_dir: str, main_only: bool = False,
                 only_modules=None, decompile_pyc: bool = True,
                 nbc_only: bool = False, user_nbc: bool = False,
                 include_native_asm: bool = False):
        self.target = target_path
        self.output_dir = output_dir
        self.main_only = main_only
        # List of module names (or `pkg.*` glob patterns) to restrict
        # PHASE 11.7 recursive disassembly to. `None` = disassemble all
        # compiled modules (the default behaviour).
        self.only_modules = only_modules
        self.decompile_pyc = decompile_pyc
        self.nbc_only = nbc_only
        # When True, NBC generation is restricted to user (non-stdlib) modules.
        self.user_nbc = user_nbc
        # When True, .nbc files include per-function @ASM blocks (opt-in
        # via --nbc-full-asm). Default False — enriched @OPS is the dense
        # 1:1 representation and keeps files LLM-sized.
        self.include_native_asm = include_native_asm
        self.bypass = CommercialBypass()
        self.report = {
            'target': os.path.basename(target_path),
            'timestamp': datetime.now().isoformat(),
            'python_version': None,
            'nuitka_edition': None,
            'encrypted': False,
            'modules': [],
            'bytecode_count': 0,
            'secrets': [],
            'code_objects': [],
            'stats': {},
        }

    def run(self):
        """Execute the full static extraction pipeline."""
        print(BANNER, flush=True)
        os.makedirs(self.output_dir, exist_ok=True)

        # === PHASE 1: PE Analysis ===
        print_section("PHASE 1: PE ANALYSIS")

        if not os.path.isfile(self.target):
            log_err(f"File not found: {self.target}")
            return False

        with open(self.target, 'rb') as f:
            outer_pe_data = f.read()

        try:
            import pefile as _pefile_outer
            _outer_pe = _pefile_outer.PE(data=outer_pe_data)
        except Exception as _pe_error:
            log_err(f"Target is not a valid PE image: {_pe_error}")
            return False
        try:
            _onefile_child = _ndl_extract_nuitka_onefile_child(_outer_pe)
        except Exception as _onefile_error:
            log_err(f"Nuitka onefile payload is unsupported or corrupt: "
                    f"{_onefile_error}")
            return False

        if _onefile_child is not None:
            pe_data = _onefile_child['data']
            self.report['onefile'] = {
                key: value for key, value in _onefile_child.items()
                if key != 'data'}
            self.report['effective_target'] = _onefile_child['name']
            log_ok(f"Onefile child selected: {_onefile_child['name']} "
                   f"({len(pe_data):,} bytes)")
        else:
            pe_data = outer_pe_data
            self.report['onefile'] = None
            self.report['effective_target'] = os.path.basename(self.target)

        file_size = len(pe_data)
        log(f"Target: {self.target}")
        log(f"Size: {file_size:,} bytes ({file_size / 1024 / 1024:.2f} MB)")

        py_ver = (_NDL_TARGET_PYTHON_OVERRIDE
                  or detect_python_version_from_pe(pe_data)
                  or _ndl_detect_python_from_blob(pe_data))
        if py_ver is None:
            log_err("Cannot determine the embedded CPython ABI; use "
                    "--target-python X.Y")
            return False
        set_nuitka_target_python(py_ver)
        self.report['python_version'] = f"{py_ver[0]}.{py_ver[1]}"
        log_ok(f"Python version: {py_ver[0]}.{py_ver[1]}")

        # Preliminary edition detection (will be refined after blob extraction)
        edition = detect_nuitka_edition(pe_data)

        # === PHASE 1.5: Resource & Section Scan for Embedded Source ===
        print_section("PHASE 1.5: EMBEDDED SOURCE SCAN (resources + sections)")
        if self.nbc_only:
            log("Skipping embedded source scan (--nbc-only).")
            resource_findings = []
            section_findings = []
            all_source_candidates = []
            high_conf_source = []
        else:
            log("Scanning ALL PE resources and sections for hidden Python source...")

            # The resource scanner accepts a path, not an in-memory PE. Scanning
            # the outer onefile archive would misclassify compressed payload
            # bytes as child resources, so use section evidence from the child.
            resource_findings = ([] if _onefile_child is not None else
                                 scan_pe_resources_for_source(
                                     self.target, self.output_dir))
            section_findings  = scan_sections_for_source(pe_data, self.output_dir)

            all_source_candidates = (
                [dict(r, origin='resource') for r in resource_findings] +
                [dict(r, origin='section')  for r in section_findings]
            )
            high_conf_source = [r for r in all_source_candidates if r['confidence'] > 0.30]

            if high_conf_source:
                log_fire(f"FOUND {len(high_conf_source)} HIGH-CONFIDENCE SOURCE CANDIDATE(S)!")
                for r in high_conf_source:
                    loc = r.get('path') or f"{r.get('section','?')}+0x{r.get('offset',0):X}"
                    log_fire(f"  [{r['origin']}] {loc}: conf={r['confidence']} -> {r['saved_at']}")
            else:
                log(f"  Resources scanned: {len(resource_findings)}, "
                    f"Section blocks found: {len(section_findings)}")
                log("  No high-confidence source in resources/sections "
                    "(may be in constants blob - checked in Phase 6)")

        self.report['embedded_source_scan'] = {
            'resource_entries':   len(resource_findings),
            'section_blocks':     len(section_findings),
            'high_conf_total':    len(high_conf_source),
            'candidates':         all_source_candidates,
        }

        # === PHASE 2: Constants blob extraction ===
        print_section("PHASE 2: CONSTANTS BLOB EXTRACTION")

        blob_data = extract_pe_constants_blob(
            self.target, pe_data=pe_data, _resolve_onefile=False)
        if not blob_data:
            log_err("Constants blob not found!")
            return False

        log_ok(f"Blob extracted: {len(blob_data):,} bytes")

        blob_path = os.path.join(self.output_dir, "constants_blob_raw.bin")
        with open(blob_path, 'wb') as f:
            f.write(blob_data)

        # Refine edition detection using blob structure (most reliable for stripped binaries)
        edition = detect_nuitka_edition(pe_data, blob_data)
        self.report['nuitka_edition'] = edition
        if edition == "commercial":
            log_fire("Protected/commercial Nuitka metadata detected")
        else:
            log_ok(f"Edition: {edition}")

        # === PHASE 3: Protected metadata handling ===
        print_section("PHASE 3: PROTECTED METADATA CHECK")

        is_encrypted = self.bypass.is_blob_encrypted(blob_data)
        has_digest = self.bypass.has_commercial_digest(blob_data)
        self.report['encrypted'] = is_encrypted

        if has_digest:
            log_fire("Protected constants metadata marker detected")
        elif is_encrypted:
            log_fire("Encoded constants metadata detected (CRC32 mismatch)")

        normalized_blob = _decrypt_blob_if_encrypted(
            self.target, blob_data, pe_data=pe_data)
        if normalized_blob is None:
            log_err("Constants metadata normalization failed: " + str(
                getattr(_decrypt_blob_if_encrypted, 'last_error', None)
                or 'no identity-verified candidate'))
            return False
        blob_data = normalized_blob
        if is_encrypted:
            dec_path = os.path.join(
                self.output_dir, "constants_blob_decrypted.bin")
            with open(dec_path, 'wb') as f:
                f.write(blob_data)
            log_ok(f"Identity-verified decrypted blob saved: {dec_path}")

        if not is_encrypted:
            log_ok("Blob uses a plain metadata layout")

        # === PHASE 4: Parse blob into modules ===
        print_section("PHASE 4: MODULE PARSING")

        # PE product strings do not imply mapping2 inside the DataComposer
        # blob. Only the exact protected layout authorizes a mapping2 probe.
        bypass_for_names = self.bypass if is_encrypted else None
        _blob_parse_diag = {}
        modules = parse_blob_modules(
            blob_data, bypass_for_names, strict=True,
            diagnostics=_blob_parse_diag)
        if not modules or not _blob_parse_diag.get('ok'):
            log_err("Constants blob failed strict CRC/framing validation: "
                    + str(_blob_parse_diag.get('stop_reason') or 'unknown'))
            return False
        log_ok(f"Found {len(modules)} modules in blob")

        bytecode_chunk = None
        module_chunks = []

        for name, data in modules:
            if name == ".bytecode":
                bytecode_chunk = data
                log(f"  [BC] .bytecode ({len(data):,} bytes)")
            else:
                module_chunks.append((name, data))
                if not self.nbc_only:
                    is_main = is_main_module(name)
                    icon = f"{C.BRIGHT_GREEN}[>>]{C.RESET}" if is_main else "    "
                    log(f"  {icon} {name} ({len(data):,} bytes)")
        if self.nbc_only and module_chunks:
            log(f"  Module list suppressed in --nbc-only mode "
                f"({len(module_chunks)} constants chunks parsed).")

        constants_profile, _constants_profile_diag = \
            _ndl_select_constants_profile(modules, python_version=py_ver)
        if constants_profile is None:
            log_warn("Constants grammar is unresolved; malformed/ambiguous "
                     "modules will be emitted as diagnostic unknown nodes: "
                     + str(_constants_profile_diag.get('reason') or 'unknown'))
        _blob_parse_diag['constants_profile'] = constants_profile
        _blob_parse_diag['constants_profile_diagnostics'] = \
            _constants_profile_diag
        self.report['constants_profile'] = constants_profile or 'unresolved'
        self.report['blob_name_encoding'] = _blob_parse_diag.get(
            'name_encoding', 'plain')
        if constants_profile:
            log_ok(f"Constants grammar: {constants_profile}")

        self.report['stats']['total_modules'] = len(modules)
        analysis_module_chunks = module_chunks
        if self.only_modules:
            analysis_module_chunks = [
                (name, data) for name, data in module_chunks
                if module_matches_patterns(name, self.only_modules)
            ]
            log(f"  --only analysis filter: {len(analysis_module_chunks)} "
                f"of {len(module_chunks)} constants chunks match {self.only_modules}")
            self.report['stats']['only_modules_filter'] = list(self.only_modules)
            self.report['stats']['only_modules_matched'] = len(analysis_module_chunks)

        # Save raw module chunks as .nuitka_const in a single folder (library_modules-style)
        nuitka_const_dir = os.path.join(self.output_dir, "library_modules")
        dumped_count = 0
        if self.nbc_only:
            log("Skipping library_modules .nuitka_const dump (--nbc-only).")
        else:
            os.makedirs(nuitka_const_dir, exist_ok=True)
            _all_module_names = [name for name, _ in module_chunks]
            _const_root = os.path.abspath(nuitka_const_dir)
            for module_name, chunk_data in module_chunks:
                _safe_source_rel = _module_to_relpath(
                    module_name, _all_module_names)
                _safe_rel = os.path.splitext(_safe_source_rel)[0] + ".nuitka_const"
                out_path = os.path.abspath(os.path.join(
                    _const_root, _safe_rel))
                try:
                    _inside_const_root = (
                        os.path.normcase(os.path.commonpath(
                            [_const_root, out_path]))
                        == os.path.normcase(_const_root))
                except Exception:
                    _inside_const_root = False
                if not _inside_const_root:
                    log_warn(f"Skipping unsafe module path {module_name!r}")
                    continue

                os.makedirs(os.path.dirname(out_path) or '.', exist_ok=True)
                with open(out_path, "wb") as f:
                    f.write(chunk_data)

                dumped_count += 1

        self.report['stats']['nuitka_const_modules'] = dumped_count
        if not self.nbc_only:
            log_ok(f"Saved {dumped_count} .nuitka_const module files into 'library_modules'")

        # === PHASE 4.5: Nuitka module table (PE meta_path_loader_entries[]) ===
        print_section("PHASE 4.5: NUITKA MODULE TABLE")
        module_table_entries = []
        try:
            import pefile as _pefile_mt
            _pe_mt = _pefile_mt.PE(data=pe_data)
            _name_dec = self.bypass.name_decode_table if is_encrypted else None
            mtp = NuitkaModuleTableParser(_pe_mt, name_decode_table=_name_dec)
            # Feed in every module name the blob decoder already resolved
            # (plus __main__ / __init__ / .bytecode sentinels). The pass-3
            # name-anchored fallback inside find_table() uses these to rescue
            # entries that live outside the main meta_path_loader_entries[]
            # cluster (typical for __main__ and other sidecar records).
            _known_chunk_names = [name for name, _ in module_chunks]
            _extra_names = list(_known_chunk_names) + [
                '__main__', '__init__', '.bytecode',
            ]
            # Dedupe while preserving order
            _seen = set()
            _extra_names_dedup = []
            for _n in _extra_names:
                if _n in _seen:
                    continue
                _seen.add(_n)
                _extra_names_dedup.append(_n)

            # Build the mapping from the actual `.bytecode` BlobData array.
            # Loader bytecode_index never addresses the per-module constants
            # chunk list; treating those unrelated positions as equivalent
            # silently attached compiled-module names to exact .pyc payloads.
            _bc_index_to_name = _bytecode_index_name_map(
                bytecode_chunk or b'', py_ver,
                constants_profile=constants_profile)

            found = mtp.find_table(
                extra_names=_extra_names_dedup,
                bc_index_to_name=_bc_index_to_name,
            )
            if found:
                start_va, module_table_entries = found
                log_ok(f"Module table: {len(module_table_entries)} entries at VA 0x{start_va:X}")

                # Write table dump
                mt_path = os.path.join(self.output_dir, "NUITKA_MODULE_TABLE.txt")
                with open(mt_path, 'w', encoding='utf-8') as f:
                    f.write("=" * 80 + "\n")
                    f.write(f" NUITKA MODULE TABLE  —  {len(module_table_entries)} entries\n")
                    f.write(f" Start VA: 0x{start_va:X}\n")
                    f.write("=" * 80 + "\n\n")
                    f.write(f"{'NAME':<50s} {'FLAGS':<30s} {'BC_IDX':>7s} {'BC_SIZE':>9s}\n")
                    f.write("-" * 100 + "\n")
                    for e in module_table_entries:
                        flags_str = ','.join(e['flag_names'])
                        f.write(f"{e['name']:<50s} {flags_str:<30s} "
                                f"{e['bytecode_index']:>7d} {e['bytecode_size']:>9d}\n")
                log_ok(f"  Saved: {mt_path}")

                bc_entries = [e for e in module_table_entries if 'BYTECODE' in e['flag_names']]
                compiled_entries = [e for e in module_table_entries if 'BYTECODE' not in e['flag_names']
                                    and 'EXTENSION' not in e['flag_names']]
                ext_entries = [e for e in module_table_entries if 'EXTENSION' in e['flag_names']]
                log(f"  Breakdown: BYTECODE={len(bc_entries)}  COMPILED={len(compiled_entries)}  EXTENSION={len(ext_entries)}")

                self.report['module_table'] = {
                    'start_va': f"0x{start_va:X}",
                    'total_entries': len(module_table_entries),
                    'bytecode_entries': len(bc_entries),
                    'compiled_entries': len(compiled_entries),
                    'extension_entries': len(ext_entries),
                }
            else:
                # Emit a detailed diagnostic so the user knows WHICH pass failed.
                _str_count = 0
                try:
                    _diag_strings = mtp._collect_strings()
                    _str_count = len(_diag_strings)
                except Exception:
                    pass
                log_warn("Module table NOT located — diagnostic:")
                log_warn(f"  Strings found in .data/.rdata : {_str_count}")
                log_warn(f"  bc_index_to_name entries      : {len(_bc_index_to_name)}")
                log_warn(f"  Pass 4 (func_ptr scan)        : also found nothing")
                log_warn("  Possible causes:")
                log_warn("    - data-hiding stores name strings outside .data/.rdata")
                log_warn("    - func_ptrs use indirection thunks (not direct .text VAs)")
                log_warn("    - non-standard Nuitka record size (try a different build)")
                log_warn("  @OPS blocks will be absent; .nbc files will be constants-only.")
        except Exception as _mt_err:
            log_warn(f"Module table scan error: {_mt_err}")

        if self.nbc_only:
            print_section("PHASE 5: NBC-ONLY FAST PATH")
            log("Skipping .pyc extraction, constants reports, secrets scan, "
                "heuristic .py output, C-source output, and .pyc decompilation.")

            self.report['bytecode_count'] = 0
            self.report['modules'] = []
            self.report['code_objects'] = []
            self.report['secrets'] = []
            self.report['stats'].update({
                'nbc_only': True,
                'bytecode_pyc': 0,
                'modules_with_constants': 0,
                'total_code_objects': 0,
                'main_code_objects': 0,
                'total_secrets': 0,
                'total_strings': 0,
            })
            self.report['embedded_source_summary'] = {
                'skipped': True,
                'reason': '--nbc-only',
            }
            self.report.setdefault('decompilation', {}).update({
                'skipped': True,
                'reason': '--nbc-only',
            })
            self.report['c_source_reconstruction'] = {
                'skipped': True,
                'reason': '--nbc-only',
            }

            print_section("PHASE 11.7: STATICALY NBC GENERATION")
            try:
                log("Running Staticaly in NBC-only mode "
                    + ("[xdis available]" if XDIS_AVAILABLE else "[xdis MISSING]")
                    + (" [capstone available]" if CAPSTONE_AVAILABLE else " [capstone MISSING]"))
                if not CAPSTONE_AVAILABLE:
                    log_err("=" * 66)
                    log_err(" capstone is NOT installed in the running Python.")
                    log_err(" NBC files will be constants-only (@NO_OPS).")
                    log_err(" Fix:  py -3.10 -m pip install capstone")
                    log_err("=" * 66)
                if not module_table_entries:
                    log_err("=" * 66)
                    log_err(" Nuitka module table was NOT located in the PE.")
                    log_err(" NBC files will not have function-body @OPS blocks.")
                    log_err("=" * 66)

                st_dir = os.path.join(self.output_dir, "staticaly")
                _pe_for_staticaly = None
                try:
                    import pefile as _pf
                    _pe_for_staticaly = _pf.PE(data=pe_data)
                except Exception:
                    _pe_for_staticaly = None
                extractor = StaticalyExtractor(
                    blob_data,
                    target_python=py_ver,
                    pe_file=_pe_for_staticaly,
                    module_table=module_table_entries,
                    nbc_only=True,
                )
                if getattr(self, 'only_modules', None):
                    extractor.only_modules = self.only_modules
                extractor.user_nbc = getattr(self, 'user_nbc', False)
                extractor.include_native_asm = getattr(self, 'include_native_asm', False)
                st_result = extractor.run(st_dir)
                log_ok(f"Staticaly sections decoded         : {st_result['sections']}")
                log_ok(f"Staticaly .nbc files produced     : {st_result.get('nbc_files', 0)}")
                log_ok(f"Staticaly modules disassembled    : {st_result.get('modules_disassembled', 0)}")
                log(f"  Output                           : {st_result['output_dir']}")
                self.report['staticaly'] = st_result
            except Exception as _st_err:
                log_warn(f"Staticaly NBC-only pipeline error: {_st_err}")
                import traceback
                traceback.print_exc()
                self.report['staticaly'] = {'error': str(_st_err)}

            print_section("PHASE 9: FINAL REPORT")
            report_path = os.path.join(self.output_dir, "REPORT.json")
            with open(report_path, 'w', encoding='utf-8') as f:
                json.dump(self.report, f, indent=2, ensure_ascii=False, default=str)

            ai_ready = organize_ai_ready_nbc(self.output_dir)
            self.report['ai_ready_nbc'] = ai_ready
            with open(report_path, 'w', encoding='utf-8') as f:
                json.dump(self.report, f, indent=2, ensure_ascii=False, default=str)
            try:
                import shutil as _shutil
                _ctx = Path(ai_ready.get('context_dir', ''))
                if _ctx.exists():
                    _shutil.copy2(report_path, _ctx / 'REPORT.json')
            except Exception:
                pass

            log_ok(f"Report saved: {report_path}")
            if ai_ready.get('files'):
                log_ok(f"AI-ready .nbc bundle: {ai_ready['files']} file(s) -> {ai_ready['output_dir']}")

            print_section("FINAL RESULTS")
            print(f"""
  {C.BRIGHT_WHITE}Target:{C.RESET}                {self.report['target']}
  {C.BRIGHT_WHITE}Python:{C.RESET}                {self.report['python_version']}
  {C.BRIGHT_WHITE}Nuitka Edition:{C.RESET}        {self.report['nuitka_edition']}
  {C.BRIGHT_WHITE}Encrypted blob:{C.RESET}        {'YES - BYPASS SUCCEEDED' if self.report['encrypted'] else 'NO'}

  {C.BRIGHT_GREEN}Modules in blob:{C.RESET}       {self.report['stats'].get('total_modules', 0)}
  {C.BRIGHT_GREEN}.nbc files:{C.RESET}            {ai_ready.get('files', 0)}
  {C.BRIGHT_GREEN}.nbc with @OPS:{C.RESET}        {ai_ready.get('with_ops', 0)}
  {C.BRIGHT_GREEN}.nbc without @OPS:{C.RESET}     {ai_ready.get('without_ops', 0)}

  {C.BRIGHT_WHITE}Output:{C.RESET}                {self.output_dir}
  {C.BRIGHT_WHITE}AI-ready .nbc:{C.RESET}         {ai_ready.get('output_dir', 'n/a')}
""")
            return True

        # === PHASE 5: .pyc extraction ===
        print_section("PHASE 5: BYTECODE EXTRACTION (.pyc)")

        pyc_count = 0
        bytecode_manifest = {}
        if bytecode_chunk:
            pyc_count, bytecode_manifest = extract_bytecode_modules(
                bytecode_chunk, self.output_dir, py_ver,
                constants_profile=constants_profile)

            # Cross-reference: if we have both the module table and manifest, enrich
            if module_table_entries:
                bc_table = [e for e in module_table_entries if 'BYTECODE' in e['flag_names']]
                # Match by bytecode_index
                for e in bc_table:
                    idx = e['bytecode_index']
                    if idx in bytecode_manifest:
                        bytecode_manifest[idx]['canonical_module_name'] = e['name']
                        bytecode_manifest[idx]['flags'] = e['flag_names']
                log_ok(f"  Enriched {len(bc_table)} bytecode entries with canonical names")

                # Rewrite manifest with the updates
                mfp = os.path.join(self.output_dir, "BYTECODE_MANIFEST.json")
                try:
                    with open(mfp, 'r', encoding='utf-8') as f:
                        mf = json.load(f)
                    mf['entries'] = list(bytecode_manifest.values())
                    with open(mfp, 'w', encoding='utf-8') as f:
                        json.dump(mf, f, indent=2, ensure_ascii=False)
                except Exception:
                    pass
        else:
            log_warn("No .bytecode chunk found in blob")
            log_warn("All modules are C-compiled (constants still extractable)")

        self.report['bytecode_count'] = pyc_count

        # === PHASE 6: Per-module constants parsing ===
        print_section("PHASE 6: PER-MODULE CONSTANTS EXTRACTION")

        constants_dir = os.path.join(self.output_dir, "module_constants")
        os.makedirs(constants_dir, exist_ok=True)

        all_secrets = []
        all_code_objects = []
        module_info_list = []
        all_const_source_findings = []

        pb = ProgressBar(len(analysis_module_chunks), desc="Parsing module constants")

        for module_name, chunk_data in analysis_module_chunks:
            pb.update()

            is_main = is_main_module(module_name)
            if self.main_only and not is_main:
                continue

            constants = parse_module_constants(
                chunk_data, python_version=py_ver,
                profile=constants_profile)
            # Search constants for embedded Python source (embedded Python source)
            const_src = search_constants_for_source(constants, module_name, self.output_dir)
            if const_src:
                all_const_source_findings.extend(const_src)
            code_objs = extract_code_object_map(
                module_name, chunk_data, python_version=py_ver,
                profile=constants_profile)
            all_code_objects.extend(code_objs)
            secrets = scan_for_secrets(constants, module_name)
            all_secrets.extend(secrets)

            safe_name = module_name.replace('.', '_').replace('<', '_').replace('>', '_')
            safe_name = re.sub(r'[<>:"|?*]', '_', safe_name)
            const_file = os.path.join(constants_dir, f"{safe_name}_constants.txt")

            # Extract all strings recursively from parsed constants and code-object info
            strings = extract_all_strings(constants)
            # Also include code object names/qualnames/args/freevars, which are not always present in constants list.
            strings += extract_all_strings(code_objs)
            # Deduplicate again while preserving order
            strings = list(dict.fromkeys(strings))

            with open(const_file, 'w', encoding='utf-8') as f:
                f.write(f"# Module: {module_name}\n")
                f.write(f"# Constants count: {len(constants)}\n\n")
                for idx, val in enumerate(constants):
                    f.write(f"[{idx}] {type(val).__name__}: {_safe_repr(val)}\n")

                f.write("\n" + "=" * 70 + "\n")
                f.write(f"# Strings extracted (recursive): {len(strings)}\n")
                f.write("=" * 70 + "\n\n")
                for s in strings:
                    f.write(s.replace("\r\n", "\n"))
                    f.write("\n")

            module_info = {
                'name': module_name,
                'is_main': is_main,
                'chunk_size': len(chunk_data),
                'constants_count': len(constants),
                'strings_count': len(strings),
                'code_objects': len(code_objs),
                'secrets_found': len(secrets),
            }
            module_info_list.append(module_info)

        pb.finish(f"Parsed {len(module_chunks)} modules")

        self.report['modules'] = module_info_list
        self.report['code_objects'] = all_code_objects

        # Deduplicate secrets
        seen = set()
        unique_secrets = []
        for s in all_secrets:
            key = (s['type'], str(s.get('value', '')))
            if key not in seen:
                seen.add(key)
                unique_secrets.append(s)
        all_secrets = unique_secrets
        self.report['secrets'] = all_secrets

        # === PHASE 7: Code Object Map ===
        print_section("PHASE 7: CODE OBJECT MAP")

        if all_code_objects:
            co_map_path = os.path.join(self.output_dir, "CODE_OBJECT_MAP.txt")
            with open(co_map_path, 'w', encoding='utf-8') as f:
                f.write("=" * 70 + "\n")
                f.write("  HEXPYRION by dimareverse - CODE OBJECT MAP\n")
                f.write("  Function signatures extracted from C-compiled code\n")
                f.write("=" * 70 + "\n\n")

                current_module = None
                for co in sorted(all_code_objects, key=lambda x: x.get('module', '')):
                    mod = co.get('module', '')
                    if mod != current_module:
                        f.write(f"\n{'_' * 60}\n")
                        f.write(f"MODULE: {mod}\n")
                        f.write(f"{'_' * 60}\n\n")
                        current_module = mod

                    raw_args = co.get('args', [])
                    args = ", ".join(str(a) if a is not None else '?' for a in raw_args)
                    flags_str = []
                    cf = co.get('flags', 0)
                    if cf & 0x04: flags_str.append("*args")
                    if cf & 0x08: flags_str.append("**kwargs")
                    if cf & 0x20: flags_str.append("generator")
                    if cf & 0x80: flags_str.append("coroutine")
                    if cf & 0x200: flags_str.append("async_gen")
                    flags_display = f" [{', '.join(flags_str)}]" if flags_str else ""
                    f.write(f"  def {co['name']}({args}){flags_display}\n")
                    f.write(f"      line: {co.get('line', '?')}\n\n")

            log_ok(f"Code object map: {len(all_code_objects)} functions found")
            log(f"  Saved to: {co_map_path}")

            main_cos = [co for co in all_code_objects if is_main_module(co.get('module', ''))]
            if main_cos:
                log_fire(f"  {len(main_cos)} functions from the app code:")
                for co in main_cos[:20]:
                    raw_args = co.get('args', [])
                    args = ", ".join(str(a) if a is not None else '?' for a in raw_args)
                    print(f"    {C.BRIGHT_YELLOW}def {co['name']}({args}){C.RESET} @ line {co.get('line', '?')}")
                if len(main_cos) > 20:
                    print(f"    ... and {len(main_cos) - 20} more")
        else:
            log_warn("No code objects found in modules")

        # === PHASE 8: Secrets Report ===
        print_section("PHASE 8: SECRETS SCANNER")

        if all_secrets:
            secrets_dir = os.path.join(self.output_dir, "secrets")
            os.makedirs(secrets_dir, exist_ok=True)

            secrets_path = os.path.join(secrets_dir, "SECRETS.json")
            with open(secrets_path, 'w', encoding='utf-8') as f:
                json.dump(all_secrets, f, indent=2, ensure_ascii=False, default=str)

            secrets_txt = os.path.join(secrets_dir, "SECRETS.txt")
            with open(secrets_txt, 'w', encoding='utf-8') as f:
                f.write("=" * 60 + "\n")
                f.write("  SECRETS FOUND BY HEXPYRION - by dimareverse\n")
                f.write("  SECRETS FOUND BY HEXPYRION - by dimareverse\n")
                f.write("=" * 60 + "\n\n")
                for s in all_secrets:
                    f.write(f"[{s['type']}] {s.get('value', 'N/A')}\n")
                    f.write(f"  Module: {s.get('module', 'N/A')}\n")
                    if 'context' in s:
                        f.write(f"  Context: {s['context'][:100]}\n")
                    if 'entropy' in s:
                        f.write(f"  Entropy: {s['entropy']}\n")
                    f.write("\n")

            log_fire(f"FOUND {len(all_secrets)} SECRETS!")
            for s in all_secrets[:15]:
                stype = s['type']
                sval = str(s.get('value', ''))[:60]
                color = C.BRIGHT_RED if stype in ('password', 'flag', 'private_key') else C.BRIGHT_YELLOW
                print(f"  {color}[{stype}]{C.RESET} {sval}")
            if len(all_secrets) > 15:
                print(f"  ... and {len(all_secrets) - 15} more")
        else:
            log("No secrets found in analyzed modules")

        # === PHASE 10: Embedded Source Summary ===
        print_section("PHASE 10: EMBEDDED SOURCE SUMMARY")

        total_source = (
            len(high_conf_source) +
            len(all_const_source_findings)
        )

        if total_source > 0:
            log_fire(f"TOTAL EMBEDDED SOURCE CANDIDATES: {total_source}")

            if high_conf_source:
                log_fire(f"  From PE resources/sections ({len(high_conf_source)}):")
                for r in high_conf_source:
                    loc = r.get('path') or f"[{r.get('section','?')}]+0x{r.get('offset',0):X}"
                    print(f"    {C.BRIGHT_GREEN}[{r['origin']}]{C.RESET} "
                          f"{C.BRIGHT_WHITE}{loc}{C.RESET} "
                          f"conf={C.BRIGHT_YELLOW}{r['confidence']:.2f}{C.RESET} "
                          f"-> {r['saved_at']}")

            if all_const_source_findings:
                log_fire(f"  From module constants ({len(all_const_source_findings)}):")
                for r in all_const_source_findings:
                    print(f"    {C.BRIGHT_MAGENTA}[const]{C.RESET} "
                          f"{C.BRIGHT_WHITE}{r['module']}{C.RESET} "
                          f"conf={C.BRIGHT_YELLOW}{r['confidence']:.2f}{C.RESET} "
                          f"-> {r['saved_at']}")

            log_fire("Check the saved .py files above - these are the real embedded source!")
        else:
            log_warn("No embedded Python source found automatically.")
            log_warn("Possible locations to check manually:")
            log_warn("  1. Custom PE sections not named .text/.data/.rdata")
            log_warn("  2. Non-standard PE resource IDs")
            log_warn("  3. Source embedded with a custom encoding/cipher")
            log_warn(f"  4. Check pe_resources/ and section_scan/ in {self.output_dir}")

        self.report['embedded_source_summary'] = {
            'total_candidates': total_source,
            'from_resources_sections': len(high_conf_source),
            'from_constants': len(all_const_source_findings),
            'const_findings': all_const_source_findings,
        }

        # === PHASE 11: Static Decompilation ===
        # Now uses the EMBEDDED BlobParser + reconstruct_python_source
        # (previously loaded from an external nuitka_static_decompiler.py
        # sidecar). Everything lives in this single script.
        print_section("PHASE 11: STATIC DECOMPILATION (constants → Python source)")
        try:
            _bp = BlobParser(b'')
            _decompiled_count = 0
            _decompile_report = []

            # Native code-object recovery: build the disassembler once so every
            # module gets EXACT signatures (co_argcount/flags/varnames) from the
            # PyCode_New* call sites. Universal across Nuitka binaries.
            _native_disasm = None
            _mt_by_name = {}
            if CAPSTONE_AVAILABLE and module_table_entries:
                try:
                    import pefile as _pefile_native
                    _pe_native = _pefile_native.PE(data=pe_data, fast_load=True)
                    _pe_native.parse_data_directories(directories=[
                        _pefile_native.DIRECTORY_ENTRY['IMAGE_DIRECTORY_ENTRY_IMPORT']])
                    _native_disasm = NuitkaStaticDisassembler(
                        _pe_native, module_table=module_table_entries)
                    _mt_by_name = {e.get('name'): e for e in module_table_entries}
                    log_ok("  Native code-object recovery enabled (exact signatures)")
                except Exception as _e:
                    _native_disasm = None
                    log_warn(f"  Native code-object recovery unavailable: {_e}")

            for _mod_name, _mod_data in analysis_module_chunks:
                try:
                    _consts, _ = _bp.parse_module(
                        bytes(_mod_data), _mod_name,
                        python_version=py_ver,
                        constants_profile=constants_profile)
                    _native_cos = None
                    _body_traces = None
                    _body_sources = {}
                    _module_globals = set()
                    if _native_disasm is not None:
                        _ent = _mt_by_name.get(_mod_name)
                        _fp = _ent.get('func_ptr') if _ent else None
                        if _fp:
                            try:
                                # Use parse_module_constants for the native
                                # resolver — its ordering matches the binary's
                                # mod_consts array (required for index math).
                                _rawvals = parse_module_constants(
                                    bytes(_mod_data), python_version=py_ver,
                                    profile=constants_profile)
                                _cand = _native_disasm.recover_code_objects(_fp, _rawvals)
                                if _cand:
                                    _native_cos = _cand
                                # Faithful per-function body name-traces (real
                                # call/attribute order) + EXACT decompiled bodies
                                # for the provable arithmetic-return shape.
                                _body_traces, _body_sources = \
                                    _native_disasm.recover_body_traces(
                                        _fp, _rawvals, code_objects=_native_cos)
                                # Real module-global names (drop colorama-style
                                # attribute pool strings from the skeleton).
                                _module_globals = \
                                    _native_disasm.recover_module_global_names(
                                        _fp, _rawvals)
                            except Exception:
                                _native_cos = None
                    _src = reconstruct_python_source(_mod_name, _consts,
                                                     native_code_objects=_native_cos,
                                                     body_traces=_body_traces,
                                                     module_globals=_module_globals,
                                                     body_sources=_body_sources)

                    # Build output path: __main__ / empty name → reconstructed_source.py
                    # package.sub.module → package/sub/module.py
                    _safe = _mod_name.replace('.', os.sep).strip(os.sep)
                    if not _safe or _safe == '__main__':
                        _src_path = os.path.join(self.output_dir, 'reconstructed_source.py')
                    else:
                        _src_path = os.path.join(self.output_dir, _safe + '.py')
                        os.makedirs(os.path.dirname(_src_path), exist_ok=True)

                    with open(_src_path, 'w', encoding='utf-8') as _f:
                        _f.write(_src)

                    _n_str  = sum(1 for _c in _consts if _c.get('type') == 'str')
                    _n_code = sum(1 for _c in _consts if _c.get('type') == 'code')
                    log_ok(f"Module {_mod_name!r}: {len(_consts)} constants "
                           f"({_n_str} strings, {_n_code} code objects) -> {_src_path}")

                    _decompiled_count += 1
                    _decompile_report.append({
                        'module': _mod_name,
                        'path': _src_path,
                        'constants': len(_consts),
                        'strings': _n_str,
                        'code_objects': _n_code,
                    })
                except Exception as _mod_err:
                    log_warn(f"Decompilation failed for {_mod_name!r}: {_mod_err}")

            if _decompiled_count == 0:
                log_warn("No modules could be decompiled")
            else:
                log_ok(f"Decompiled {_decompiled_count} module(s) with embedded BlobParser")

            self.report['reconstructed_source'] = _decompile_report

        except Exception as _e:
            log_warn(f"Static decompilation error: {_e}")
            import traceback
            traceback.print_exc()

        # === PHASE 11.5: C SOURCE RECONSTRUCTION (Nuitka-style .c per module) ===
        print_section("PHASE 11.5: C SOURCE RECONSTRUCTION (Nuitka-style .c per module)")

        c_src_dir = os.path.join(self.output_dir, "reconstructed_c_sources")
        os.makedirs(c_src_dir, exist_ok=True)

        # Build a quick lookup: module_name -> module_table_entry
        mt_by_name = {e['name']: e for e in module_table_entries} if module_table_entries else {}

        c_generated = 0
        c_total_lines = 0
        c_pb = ProgressBar(len(analysis_module_chunks), desc="Generating .c files")
        for module_name, chunk_data in analysis_module_chunks:
            c_pb.update()
            try:
                constants = parse_module_constants(
                    chunk_data, python_version=py_ver,
                    profile=constants_profile)
                code_objs = extract_code_object_map(
                    module_name, chunk_data, python_version=py_ver,
                    profile=constants_profile)

                mt_entry = mt_by_name.get(module_name)
                native_addr = mt_entry['func_ptr'] if mt_entry else None

                c_src = NuitkaCSourceRebuilder.generate_c_source(
                    module_name=module_name,
                    constants=constants,
                    code_objects=code_objs,
                    module_table_entry=mt_entry,
                    native_func_addr=native_addr,
                )

                safe_name = module_name.replace('.', os.sep) or '__main__'
                safe_name = re.sub(r'[<>:"|?*]', '_', safe_name)
                c_path = os.path.join(c_src_dir, safe_name + '.c')
                os.makedirs(os.path.dirname(c_path) or '.', exist_ok=True)
                with open(c_path, 'w', encoding='utf-8') as f:
                    f.write(c_src)
                c_generated += 1
                c_total_lines += c_src.count('\n')
            except Exception as _c_err:
                pass

        c_pb.finish(f"Generated {c_generated} .c files ({c_total_lines:,} total lines)")
        log_ok(f"  Output: {c_src_dir}")

        self.report['c_source_reconstruction'] = {
            'generated_files': c_generated,
            'total_lines': c_total_lines,
            'output_dir': c_src_dir,
        }

        # === PHASE 11.7: STATICALY PIPELINE ===
        #  - NuitkaBlobDecoder (Python port of nuitka_deobfuscate.c)
        #  - xdis raw marshal scanner (finds embedded code objects the
        #    section decoder misses)
        #  - OmniDecompiler AST synthesis with C-API trace comments
        print_section("PHASE 11.7: STATICALY DEOBFUSCATION + OMNI DECOMPILATION")
        if blob_data is None:
            log_warn("No blob data available — skipping Staticaly pipeline")
        else:
            try:
                log("Running embedded Staticaly pipeline "
                    + ("[xdis available]" if XDIS_AVAILABLE else "[xdis MISSING - raw scan disabled]")
                    + (" [capstone available]" if CAPSTONE_AVAILABLE else " [capstone MISSING - disasm disabled]"))

                # Give the user a VERY loud warning when capstone is not
                # installed — without it every .nbc file comes out with a
                # @NO_OPS block and no function bodies can be recovered.
                if not CAPSTONE_AVAILABLE:
                    log_err("=" * 66)
                    log_err(" capstone is NOT installed in the running Python.")
                    log_err(" Every .nbc file will be produced WITHOUT the")
                    log_err(" @OPS section — an LLM fed those files can only")
                    log_err(" emit signature skeletons, not real function bodies.")
                    log_err(" Fix:  py -3.10 -m pip install capstone")
                    log_err(" Then re-run this extraction.")
                    log_err("=" * 66)
                if not module_table_entries:
                    log_err("=" * 66)
                    log_err(" Nuitka module table was NOT located in the PE.")
                    log_err(" Without it the disassembler cannot find function")
                    log_err(" entry points — every .nbc will have @NO_OPS.")
                    log_err(" Check the PHASE 4.5 log above; if the target was")
                    log_err(" built with --obfuscate or with an unusual Nuitka")
                    log_err(" fork the loader table may live at a non-standard")
                    log_err(" offset and require a custom scan.")
                    log_err("=" * 66)

                st_dir = os.path.join(self.output_dir, "staticaly")
                # Reuse the already-parsed pefile + module table so the
                # disassembler can annotate calls with module names and
                # resolve the IAT for Python-C-API references.
                _pe_for_staticaly = None
                try:
                    import pefile as _pf
                    _pe_for_staticaly = _pf.PE(data=pe_data)
                except Exception:
                    _pe_for_staticaly = None
                extractor = StaticalyExtractor(
                    blob_data,
                    target_python=py_ver,
                    pe_file=_pe_for_staticaly,
                    module_table=module_table_entries,
                )
                # Optional --only filter: restrict PHASE 11.7 recursive
                # disassembly to a user-specified subset of modules.
                if getattr(self, 'only_modules', None):
                    extractor.only_modules = self.only_modules
                extractor.user_nbc = getattr(self, 'user_nbc', False)
                extractor.include_native_asm = getattr(self, 'include_native_asm', False)
                st_result = extractor.run(st_dir)
                log_ok(f"Staticaly sections decoded         : {st_result['sections']}")
                log_ok(f"Staticaly raw-scan .pyc extracted : {st_result['raw_scan_pyc']}")
                log_ok(f"Staticaly OMNI reconstructions    : {st_result['omni_reconstructed']}")
                log_ok(f"Staticaly .nbc files produced     : {st_result.get('nbc_files', 0)}")
                log_ok(f"Staticaly modules disassembled    : {st_result.get('modules_disassembled', 0)}")
                log(f"  Output                           : {st_result['output_dir']}")
                self.report['staticaly'] = st_result
            except Exception as _st_err:
                log_warn(f"Staticaly pipeline error: {_st_err}")
                import traceback
                traceback.print_exc()
                self.report['staticaly'] = {'error': str(_st_err)}

        # === PHASE 12: .pyc → Python source decompilation ===
        print_section("PHASE 12: BYTECODE DECOMPILATION (.pyc → Python source)")

        pyc_dir   = os.path.join(self.output_dir, "bytecode_pyc")
        src_dir   = os.path.join(self.output_dir, "modules")
        os.makedirs(src_dir, exist_ok=True)

        # Collect all .pyc files extracted in Phase 5
        pyc_files = []
        if not self.decompile_pyc:
            log_warn("Skipping .pyc decompilation (--no-pyc-decompile).")
            self.report.setdefault('decompilation', {}).update({
                'skipped': True,
                'reason': '--no-pyc-decompile',
                'output_dir': src_dir,
            })
        elif os.path.exists(pyc_dir):
            for _root, _dirs, _fnames in os.walk(pyc_dir):
                for _fn in sorted(_fnames):
                    if _fn.endswith('.pyc'):
                        pyc_files.append(os.path.join(_root, _fn))

        if not pyc_files:
            if self.decompile_pyc:
                log_warn("No .pyc files found (Phase 5 may have found no bytecode chunk).")
                log_warn("This binary may be fully C-compiled (no Python bytecode to decompile).")
        else:
            log(f"Found {len(pyc_files)} .pyc file(s) to decompile")

            _dec_list = _detect_decompiler(py_ver)
            if _dec_list:
                log_ok(f"Decompiler chain ({len(_dec_list)}):")
                for _i, _d in enumerate(_dec_list):
                    _bin = f"  ({_d['binary']})" if _d.get('binary') else ""
                    log(f"    {_i+1}. {_d['kind']}{_bin}  [priority {_d['priority']}]")
            else:
                log_warn("No Python decompiler found.")
                log_warn("  For Python 3.8-3.9:  pip install decompile3 decompyle3")
                log_warn("  For Python 3.10+:    install pycdc from https://github.com/zrax/pycdc")
                log_warn(f"    - build with cmake . && make; place pycdc.exe on PATH")
                log_warn("  Falling back to bytecode disassembly / pseudo-source.")

            _dec_ok = _dec_fail = 0
            _pb12 = ProgressBar(len(pyc_files), desc="Decompiling .pyc")

            for _pyc in pyc_files:
                _pb12.update()
                # Build output path: bytecode_pyc/a/b/c.pyc → modules/a/b/c.py
                _rel   = os.path.relpath(_pyc, pyc_dir)
                _py    = os.path.join(src_dir, _rel[:-1])   # .pyc → .py  (drop the trailing 'c')
                os.makedirs(os.path.dirname(_py) or '.', exist_ok=True)

                _ok = False
                if _dec_list:
                    _ok = _decompile_pyc(_pyc, _py, _dec_list)

                if not _ok:
                    # Fall back: write bytecode disassembly directly into the .py file.
                    # Marked with a prominent header so the user knows it's dis output.
                    _pyc_dis(_pyc, _py)
                    _dec_fail += 1
                else:
                    _dec_ok += 1

            _pb12.finish(f"Decompiled {_dec_ok}/{len(pyc_files)}"
                         + (f" ({_dec_fail} -> dis fallback)" if _dec_fail else ""))

            if _dec_ok > 0:
                log_ok(f"Source files written to: {src_dir}")
            if _dec_fail > 0 and not _dec_list:
                log_warn(f"Install pycdc or decompile3 to get real source for {_dec_fail} file(s)")

            self.report.setdefault('decompilation', {}).update({
                'decompiler_chain': [d['kind'] for d in _dec_list] if _dec_list else ['dis_fallback'],
                'total': len(pyc_files),
                'success': _dec_ok,
                'fallback_dis': _dec_fail,
                'output_dir': src_dir,
            })

        # === PHASE 9: JSON Report ===
        print_section("PHASE 9: FINAL REPORT")

        self.report['stats'].update({
            'bytecode_pyc': pyc_count,
            'modules_with_constants': len([m for m in module_info_list if m['constants_count'] > 0]),
            'total_code_objects': len(all_code_objects),
            'main_code_objects': len([co for co in all_code_objects if is_main_module(co.get('module', ''))]),
            'total_secrets': len(all_secrets),
            'total_strings': sum(m['strings_count'] for m in module_info_list),
        })

        report_path = os.path.join(self.output_dir, "REPORT.json")
        with open(report_path, 'w', encoding='utf-8') as f:
            json.dump(self.report, f, indent=2, ensure_ascii=False, default=str)

        ai_ready = organize_ai_ready_nbc(self.output_dir)
        self.report['ai_ready_nbc'] = ai_ready
        with open(report_path, 'w', encoding='utf-8') as f:
            json.dump(self.report, f, indent=2, ensure_ascii=False, default=str)
        try:
            import shutil as _shutil
            _ctx = Path(ai_ready.get('context_dir', ''))
            if _ctx.exists():
                _shutil.copy2(report_path, _ctx / 'REPORT.json')
        except Exception:
            pass

        log_ok(f"Report saved: {report_path}")
        if ai_ready.get('files'):
            log_ok(f"AI-ready .nbc bundle: {ai_ready['files']} file(s) -> {ai_ready['output_dir']}")

        # === SUMMARY ===
        print_section("FINAL RESULTS")
        stats = self.report['stats']

        _dec_report = self.report.get('decompilation', {})
        _dec_ok_n   = _dec_report.get('success', 0)
        _dec_total  = _dec_report.get('total', 0)
        _dec_chain  = _dec_report.get('decompiler_chain') or [_dec_report.get('decompiler', 'none')]
        _dec_tool   = ', '.join(_dec_chain)
        if _dec_report.get('skipped'):
            _dec_line = f"skipped [{_dec_report.get('reason', 'requested')}]"
        else:
            _dec_line = (f"{_dec_ok_n}/{_dec_total} files  [{_dec_tool}]"
                         if _dec_total else "n/a (no bytecode chunk)")

        print(f"""
  {C.BRIGHT_WHITE}Target:{C.RESET}                {self.report['target']}
  {C.BRIGHT_WHITE}Python:{C.RESET}                {self.report['python_version']}
  {C.BRIGHT_WHITE}Nuitka Edition:{C.RESET}        {self.report['nuitka_edition']}
  {C.BRIGHT_WHITE}Encrypted blob:{C.RESET}        {'YES - BYPASS SUCCEEDED' if self.report['encrypted'] else 'NO'}

  {C.BRIGHT_GREEN}Modules in blob:{C.RESET}       {stats.get('total_modules', 0)}
  {C.BRIGHT_GREEN}.pyc extracted:{C.RESET}        {pyc_count}
  {C.BRIGHT_GREEN}Decompiled .py:{C.RESET}        {_dec_line}
  {C.BRIGHT_GREEN}Total strings:{C.RESET}         {stats.get('total_strings', 0)} (recursive, deduplicated per module)
  {C.BRIGHT_GREEN}Code objects:{C.RESET}          {stats.get('total_code_objects', 0)} ({stats.get('main_code_objects', 0)} from app)

  {C.BRIGHT_RED}Secrets found:{C.RESET}         {stats.get('total_secrets', 0)}

  {C.BRIGHT_WHITE}Output:{C.RESET}                {self.output_dir}
  {C.BRIGHT_WHITE}AI-ready .nbc:{C.RESET}         {ai_ready.get('output_dir', 'n/a')}
  {C.BRIGHT_WHITE}Source files:{C.RESET}          {os.path.join(self.output_dir, 'modules')}
""")

        print(f"{C.BRIGHT_GREEN}{C.BOLD}")
        print("   +=====================================================+")
        print("   ||   EXTRACTION COMPLETE! NUITKA STATIC BYPASS     ||")
        print("   +=====================================================+")
        print(C.RESET)

        return True


def organize_ai_ready_nbc(output_dir: str) -> dict:
    """Create a clean, LLM-facing output tree for the generated `.nbc` files.

    The main extractor intentionally keeps legacy folders for compatibility.
    This post-pass gives the reverse-engineering workflow one obvious place
    to look: `AI_READY_NBC/nbc/` plus a small context bundle and manifest.
    """
    root = Path(output_dir).resolve()
    src_tree = root / "staticaly" / "omni_reconstructed"
    ready_dir = root / "AI_READY_NBC"
    nbc_dir = ready_dir / "nbc"
    ctx_dir = ready_dir / "context"

    result = {
        'output_dir': str(ready_dir),
        'nbc_dir': str(nbc_dir),
        'context_dir': str(ctx_dir),
        'files': 0,
        'with_ops': 0,
        'without_ops': 0,
        'manifest': str(ready_dir / 'NBC_MANIFEST.json'),
    }

    if not src_tree.exists():
        return result

    try:
        resolved_ready = ready_dir.resolve()
        if resolved_ready.exists() and resolved_ready.is_relative_to(root):
            import shutil as _shutil
            _shutil.rmtree(resolved_ready)
    except Exception:
        pass

    nbc_dir.mkdir(parents=True, exist_ok=True)
    ctx_dir.mkdir(parents=True, exist_ok=True)

    manifest = []
    import shutil as _shutil

    for src in sorted(src_tree.rglob('*.nbc')):
        rel = src.relative_to(src_tree)
        dst = nbc_dir / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        _shutil.copy2(src, dst)

        try:
            text = dst.read_text(encoding='utf-8', errors='replace')
        except Exception:
            text = ''

        module_name = ''
        const_count = None
        for line in text.splitlines()[:80]:
            if line.startswith('@MOD '):
                module_name = line[5:].strip()
            elif line.startswith('@CONSTS '):
                try:
                    const_count = int(line.split()[1])
                except Exception:
                    const_count = None

        lines = text.splitlines()
        has_ops = any(line.startswith('@OPS ') for line in lines)
        # A bare @NO_OPS means the module has no disassembly. In the
        # @FORENSICS section, "@NO_OPS <qualname>" only marks a single
        # orphan function and should not classify the whole module as failed.
        has_no_ops = any(line.strip() == '@NO_OPS' for line in lines)
        data = dst.read_bytes()
        item = {
            'module': module_name,
            'path': str(rel).replace(os.sep, '/'),
            'bytes': len(data),
            'sha256': hashlib.sha256(data).hexdigest(),
            'constants': const_count,
            'has_ops': has_ops,
            'has_no_ops': has_no_ops,
        }
        manifest.append(item)
        result['files'] += 1
        if has_ops:
            result['with_ops'] += 1
        if has_no_ops and not has_ops:
            result['without_ops'] += 1

    context_files = [
        root / 'REPORT.json',
        root / 'NUITKA_MODULE_TABLE.txt',
        root / 'CODE_OBJECT_MAP.txt',
        root / 'BYTECODE_MANIFEST.json',
        src_tree / '_MANIFEST.json',
        src_tree / 'NUITKA_RUNTIME_HELPERS.txt',
    ]
    for src in context_files:
        if src.exists() and src.is_file():
            try:
                _shutil.copy2(src, ctx_dir / src.name)
            except Exception:
                pass

    manifest_path = ready_dir / 'NBC_MANIFEST.json'
    manifest_path.write_text(
        json.dumps({
            'created_at': datetime.now().isoformat(),
            'source_tree': str(src_tree),
            'nbc_files': result['files'],
            'with_ops': result['with_ops'],
            'without_ops': result['without_ops'],
            'entries': manifest,
        }, indent=2, ensure_ascii=False),
        encoding='utf-8',
    )

    readme = ready_dir / 'README_AI.md'
    readme.write_text(
        "# AI-ready Nuitka NBC bundle\n\n"
        "Use files under `nbc/` as the primary input for source reconstruction.\n"
        "Each `.nbc` is self-contained: full decoded constants, raw chunk "
        "base64, loader-table metadata when available, virtual `@OPS`, and "
        "annotated native `@ASM` blocks when static disassembly succeeded.\n\n"
        "Prefer files with `has_ops: true` in `NBC_MANIFEST.json`; files "
        "with `@NO_OPS` contain constants and metadata only.\n",
        encoding='utf-8',
    )

    return result


def _safe_repr(val, max_len=500):
    try:
        r = repr(val)
        if len(r) > max_len:
            # Never cut a string/bytes literal mid-way (unterminated literal).
            if isinstance(val, str):
                return repr(val[:max(0, max_len - 12)]) + '...'
            if isinstance(val, (bytes, bytearray)):
                return repr(bytes(val[:max(0, max_len - 12)])) + '...'
            return r[:max_len] + '...'
        return r
    except Exception:
        return f"<unrepresentable: {type(val).__name__}>"


