# =============================================================================
# LIVE NATIVE DECOMPILER  (deterministic, on-demand, NO .nbc, NO AI)
# -----------------------------------------------------------------------------
# Resolves everything straight from the COMPLETE machine code of one module:
# constants live from the blob, functions from the module table, and operations
# from a helper-aware register simulator that knows each Nuitka runtime helper's
# fixed C signature. The Nuitka call vocabulary is told apart by two CPython-API
# markers reached through the PE import table (grounded in Nuitka's source):
#   _PyType_Lookup     -> the helper looks an attribute/method up
#   PyEval_GetFuncName -> the helper CALLS something ("'X' is not callable")
# giving:  lookup+call = CALL_METHOD ; lookup = LOOKUP_ATTRIBUTE ;
#          call = CALL_FUNCTION ; neither(+PyErr) = error/raise (skipped).
# Module globals load through per-name cached thunks (recognised structurally).
# =============================================================================
try:
    import capstone as _cap_ndl
except ImportError:
    _cap_ndl = None

# CPython numeric-API -> Python binary operator (for BINOP reconstruction).
_NDL_BINOP = {
    "PyNumber_Add": "+", "PyNumber_Subtract": "-", "PyNumber_Multiply": "*",
    "PyNumber_TrueDivide": "/", "PyNumber_FloorDivide": "//",
    "PyNumber_Remainder": "%", "PyNumber_Power": "**",
    "PyNumber_Lshift": "<<", "PyNumber_Rshift": ">>",
    "PyNumber_And": "&", "PyNumber_Or": "|", "PyNumber_Xor": "^",
    "PyNumber_MatrixMultiply": "@",
}


class _NativeSym:
    # `_fstr`/`_fstr_used` tag a recovered f-string result so the structurer
    # binds it to exactly ONE store (anti-smear). Slots are set lazily, so use
    # getattr(sym, "_fstr", False); tagging the OBJECT (not its id()) is immune
    # to the id-reuse hazard, and the shared object's flag is visible across the
    # shallow dict(store) branch copies.
    __slots__ = ("t", "k", "_fstr", "_fstr_used", "_native_ssize",
                 "_ndl_type_args")
    def __init__(self, t, k="expr"):
        self.t = t; self.k = k; self._ndl_type_args = False


def _ndl_norm_mem(op):
    m = re.search(r"\[([^\]]+)\]", op)
    if not m:
        return None
    inside = m.group(1).replace(" ", "")
    return None if inside.startswith("rip") else inside


def _ndl_rip_target(insn):
    """VA of a RIP-relative operand, independent of Capstone spacing/base."""
    o = getattr(insn, "op_str", "") or ""
    m = re.search(r"\[rip\s*([+-])\s*(0x[0-9a-fA-F]+|\d+)\]", o, re.I)
    if not m:
        return None
    raw = m.group(2)
    try:
        disp = int(raw, 16) if raw.lower().startswith("0x") else int(raw)
    except Exception:
        return None
    if m.group(1) == "-":
        disp = -disp
    try:
        return int(insn.address) + int(insn.size) + disp
    except Exception:
        return None


def _ndl_recover_while_loops(disasm, va, consts, mcb, max_bytes=32768):
    """Rileva while loops dal pattern:
    - backward jmp (target < current address)
    - senza tp_iternext (altrimenti è un for)
    Ritorna [(header_addr, end_addr)]
    """
    try:
        insns = list(disasm._disasm_body(va, max_bytes=max_bytes, func_extent=True))
    except Exception:
        return []

    loops = []
    insn_map = {i.address: i for i in insns}
    addrs = sorted(insn_map.keys())

    for i, insn in enumerate(insns):
        if insn.mnemonic != 'jmp':
            continue
        try:
            target = int(insn.op_str, 16)
        except (ValueError, AttributeError):
            continue
        # backward jump = loop
        if target < insn.address and target in insn_map:
            # Verifica che non sia già un for (ha tp_iternext)
            is_for = False
            for j in insns:
                if j.address >= target and j.address <= insn.address:
                    if 'tp_iternext' in str(j.op_str) or '+ 0xe0]' in str(j.op_str):
                        is_for = True
                        break
            if not is_for:
                loops.append((target, insn.address))

    return loops


def _ndl_recover_for_range_loops(disasm, va, consts, mcb, vn, max_bytes=32768):
    """Rileva for x in range(...) dal pattern:
    - PyLong_FromLong / PyLong_FromLongLong per il range
    - iter() sul range
    - tp_iternext nel loop body
    """
    # Pattern: cerca chiamate a PyLong seguite da GET_ITER
    try:
        infos = disasm.analyse_function(va, max_bytes=max_bytes)
    except Exception:
        return []

    range_loops = []
    calls = infos.get('calls', [])

    for i, call in enumerate(calls):
        if call.get('kind') == 'capi' and 'PyLong_From' in str(call.get('name', '')):
            # Cerca un GET_ITER successivo
            for j in range(i+1, min(i+10, len(calls))):
                if calls[j].get('kind') == 'internal':
                    # Potrebbe essere GET_ITER
                    range_loops.append({
                        'range_call': call,
                        'iter_call': calls[j],
                        'header': call.get('va_from'),
                    })
                    break

    return range_loops


def _ndl_try_make_comp(s, nxt):
    """If `s` is `tgt = []`/`{}`/`set()` and `nxt` is `for v in it: [if cond:]
    tgt.append/add/[k]=v`, return the folded comprehension Assign, else None."""
    import ast
    if not (isinstance(s, ast.Assign) and len(s.targets) == 1
            and isinstance(s.targets[0], ast.Name) and isinstance(nxt, ast.For)):
        return None
    tgt = s.targets[0].id
    is_list = isinstance(s.value, ast.List) and not s.value.elts
    is_dict = isinstance(s.value, ast.Dict) and not s.value.keys
    if not (is_list or is_dict):
        return None
    body, cond = nxt.body, None
    if len(body) == 1 and isinstance(body[0], ast.If) and not body[0].orelse:
        cond, body = body[0].test, body[0].body
    if len(body) != 1:
        return None
    st = body[0]
    gen = ast.comprehension(target=nxt.target, iter=nxt.iter,
                            ifs=[cond] if cond is not None else [], is_async=0)
    # list:  tgt.append(elem)
    if (is_list and isinstance(st, ast.Expr) and isinstance(st.value, ast.Call)
            and isinstance(st.value.func, ast.Attribute)
            and isinstance(st.value.func.value, ast.Name)
            and st.value.func.value.id == tgt and st.value.func.attr == "append"
            and len(st.value.args) == 1):
        val = ast.ListComp(elt=st.value.args[0], generators=[gen])
        return ast.Assign(targets=[ast.Name(id=tgt, ctx=ast.Store())], value=val)
    # dict:  tgt[k] = v
    if (is_dict and isinstance(st, ast.Assign) and len(st.targets) == 1
            and isinstance(st.targets[0], ast.Subscript)
            and isinstance(st.targets[0].value, ast.Name)
            and st.targets[0].value.id == tgt):
        key = st.targets[0].slice
        if isinstance(key, ast.Index):           # py<3.9 compat
            key = key.value
        val = ast.DictComp(key=key, value=st.value, generators=[gen])
        return ast.Assign(targets=[ast.Name(id=tgt, ctx=ast.Store())], value=val)
    return None


def _ndl_fold_comprehensions(src):
    """Fold the explicit build-and-loop form Nuitka inlines a comprehension to
    (`tgt=[]; for v in it: [if c:] tgt.append(e)`) back into `tgt=[e for v in it
    if c]`. AST-based; returns the original source unchanged on any failure."""
    import ast
    try:
        tree = ast.parse(src)
    except Exception:
        return src

    def fold_block(stmts):
        out, i = [], 0
        while i < len(stmts):
            comp = _ndl_try_make_comp(stmts[i], stmts[i + 1]) if i + 1 < len(stmts) else None
            if comp is not None:
                out.append(comp); i += 2
            else:
                out.append(stmts[i]); i += 1
        return out

    class _T(ast.NodeTransformer):
        def generic_visit(self, node):
            super().generic_visit(node)
            for field in ("body", "orelse", "finalbody"):
                blk = getattr(node, field, None)
                if isinstance(blk, list) and blk and all(isinstance(x, ast.stmt) for x in blk):
                    setattr(node, field, fold_block(blk))
            return node

    try:
        _T().visit(tree)
        ast.fix_missing_locations(tree)
        return ast.unparse(tree)
    except Exception:
        return src


def _ndl_recover_try_except(disasm, va, consts, mcb, vn, max_bytes=32768):
    """Rileva try/except dal pattern Nuitka:
    - Nuitka usa un frame try/except con jump table
    - Il blocco catch controlla PyErr_Occurred / PyErr_ExceptionMatches
    - Il blocco finally (se presente) è sempre eseguito

    Ritorna una struttura:
    {
        'try_body': [lines],
        'handlers': [(exception_type, [lines])],
        'finally_body': [lines] or None,
        'else_body': [lines] or None,
    }
    """
    try:
        infos = disasm.analyse_function(va, max_bytes=max_bytes)
    except Exception:
        return None

    calls = infos.get('calls', [])

    # Cerca pattern try/except:
    # 1. PyErr_Occurred() o PyErr_ExceptionMatches() nel blocco catch
    # 2. PyErr_Clear() all'inizio del blocco catch
    # 3. PyErr_Format / PyErr_SetString per raise
    has_try = False
    has_except = False
    exception_types = []

    for call in calls:
        name = str(call.get('name', ''))
        if name in ('PyErr_Occurred', 'PyErr_ExceptionMatches'):
            has_try = True
        if name == 'PyErr_Clear':
            has_except = True
        if name in ('PyErr_Format', 'PyErr_SetString'):
            has_except = True

    if not has_try and not has_except:
        return None

    result = {
        'try_body': [],
        'handlers': [],
        'finally_body': None,
        'else_body': None,
    }

    for c in consts:
        if isinstance(c, str) and c in (
            'Exception', 'ValueError', 'TypeError', 'KeyError',
            'IndexError', 'AttributeError', 'ImportError',
            'RuntimeError', 'OSError', 'IOError', 'FileNotFoundError',
            'StopIteration', 'KeyboardInterrupt',
        ):
            exception_types.append(c)

    for exc_type in exception_types:
        result['handlers'].append((exc_type, []))

    return result


def _ndl_recover_comprehensions(disasm, va, consts, mcb, vn, max_bytes=32768):
    """Rileva list/dict/set comprehensions e generator expressions.
    Nuitka compila le comprehension come funzioni separate con:
    - nome: <listcomp>, <dictcomp>, <setcomp>, <genexpr>
    - argomento implicito: .0 (l'iteratore)

    Ritorna una lista di comprehension ricostruite.
    """
    comprehensions = []

    # Cerca nei code objects per comprehension
    # (vengono passate come costanti nel blob)
    for c in consts:
        if isinstance(c, dict) and c.get('_type') == 'CodeObject':
            name = c.get('name', '')
            if name in ('<listcomp>', '<dictcomp>', '<setcomp>', '<genexpr>'):
                comp = {
                    'type': name,
                    'args': c.get('args', []),
                    'line': c.get('line', 0),
                }
                comprehensions.append(comp)

    return comprehensions


def _ndl_render_comprehension(comp, consts):
    """Renderizza una comprehension ricostruita come codice Python."""
    comp_type = comp.get('type', '<listcomp>')
    args = comp.get('args', [])

    if comp_type == '<listcomp>':
        if len(args) >= 2:
            return f"[{args[0]} for {args[1]} in ...]"
        return "[... for ... in ...]"
    elif comp_type == '<dictcomp>':
        if len(args) >= 3:
            return f"{{{args[0]}: {args[1]} for {args[2]} in ...}}"
        return "{...: ... for ... in ...}"
    elif comp_type == '<setcomp>':
        if len(args) >= 2:
            return f"{{{args[0]} for {args[1]} in ...}}"
        return "{... for ... in ...}"
    elif comp_type == '<genexpr>':
        if len(args) >= 2:
            return f"({args[0]} for {args[1]} in ...)"
        return "(... for ... in ...)"

    return "..."


def _ndl_build_joined_fstring(parts):
    """Recursively assemble one Python f-string from ordered pieces.

    `parts` is the SOURCE-ORDER list of:
        ('lit', text)                      a literal text run, or
        ('fmt', expr_text, spec_or_None)   an interpolation `{expr[:spec]}`.

    RECURSION: an interpolated `expr_text` may itself be (or contain) an
    f-string — when it parses to a `JoinedStr` with no format spec, its values
    are FLATTENED into the parent so `f"a{f'b{x}'}c"` collapses to one faithful
    `f"ab{x}c"` instead of an ugly `f"a{f'b{x}'}c"` nested literal. Format specs
    (`{x:.2f}`) and the recovered conversion are preserved. Pure AST assembly +
    a compile() check — never fabricates; returns the unparsed text or None."""
    import ast
    values = []
    for p in parts:
        if p[0] == 'lit':
            if p[1]:
                values.append(ast.Constant(value=p[1]))
            continue
        expr_text = p[1]
        spec = p[2] if len(p) > 2 else None
        try:
            node = ast.parse(expr_text, mode='eval').body
        except Exception:
            return None
        # flatten a nested f-string into the parent (true recursion)
        if isinstance(node, ast.JoinedStr) and not spec:
            values.extend(node.values)
            continue
        fspec = None
        if spec:
            fspec = ast.JoinedStr(values=[ast.Constant(value=spec)])
        values.append(ast.FormattedValue(value=node, conversion=-1,
                                          format_spec=fspec))
    if not values:
        return None
    try:
        js = ast.JoinedStr(values=values)
        ast.fix_missing_locations(js)
        text = ast.unparse(js)
        compile(text, '<fstr>', 'eval')
        return text
    except Exception:
        return None


def _ndl_build_fstring(template, args):
    """Turn a format template + arg name list into a Python f-string or concat."""
    if not template or not args:
        return repr(template) if template else None
    tmpl = template
    if len(args) == 1 and re.fullmatch(r"[A-Za-z_]\w*", args[0]):
        if "{" not in tmpl:
            return 'f"%s{%s}"' % (tmpl.replace('"', '\\"'), args[0])
        return 'f"%s"' % tmpl.replace('"', '\\"')
    if "%" in tmpl:
        try:
            return repr(tmpl) + " % (" + ", ".join(args) + ")"
        except Exception:
            pass
    # NEVER FABRICATE: a template with no '%' and no '{' format markers, paired
    # with N live register/slot values, is NOT provable evidence of an f-string
    # or %-format — it is a blind register sweep. A real Nuitka f-string is
    # lowered to PyUnicode_Join with ordered \x00TE: elements and is rebuilt by
    # _join_fstring; only THAT path has the evidence to emit a joined string.
    # Refuse the `tmpl + str(a) + str(b) + …` concat here; the caller falls back
    # to the honest single string literal repr(tmpl) or to a faithful trace.
    return None


def _ndl_heal_opaque_vars(lines, varnames):
    """Map common opaque `_v` uses to real co_varnames when unambiguous."""
    if not lines or not varnames:
        return lines
    vn = list(varnames)
    skip = set(vn[:3])  # params / early setup — don't auto-rename
    pool = [n for n in vn if n not in skip and re.fullmatch(r"[A-Za-z_]\w*", n)]
    text = "\n".join(lines)
    rules = []
    if "line" in pool and "_v.strip()" in text:
        rules.append(("_v.strip()", "line.strip()"))
        rules.append(("_v.__enter__()", "f.__enter__()"))
        rules.append(("_v.readlines()", "f.readlines()"))
        rules.append(("_v.read()", "f.read()"))
    if "f" in pool:
        rules.append(("_v.__enter__()", "f.__enter__()"))
        rules.append(("_v.__exit__", "f.__exit__"))
        rules.append(("_v.read()", "f.read()"))
        rules.append(("_v.readlines()", "f.readlines()"))
    for old, new in rules:
        text = text.replace(old, new)
    # Opaque ctor temp -> co_varname ending in _instance (structure-based).
    for nm in pool:
        if nm.endswith("_instance"):
            m = re.search(r"\bv0 = ([A-Za-z_]\w*)\(\)", text)
            if m:
                cls = m.group(1)
                text = re.sub(
                    rf"\bv0 = {re.escape(cls)}\(\)",
                    f"{nm} = {cls}()",
                    text,
                    count=1,
                )
    return text.splitlines()


def _ndl_fold_with_statements(lines):
    """Fold `v = expr.__enter__()` + body + `__exit__` into `with expr as v:`."""
    import ast, textwrap
    if not lines:
        return lines
    text = "\n".join(lines)
    _wrapped = False
    try:
        tree = ast.parse(text)
    except SyntaxError:
        # Body lines with `return`/`yield` fail at module level — wrap in a
        # dummy function so the transformer can still operate on the body.
        try:
            tree = ast.parse("def _():\n" + textwrap.indent(text, "    "))
            _wrapped = True
        except Exception:
            return lines
    except Exception:
        return lines

    class _W(ast.NodeTransformer):
        def _visit_block_holder(self, node):
            self.generic_visit(node)
            new_body = self._fold_block(node.body)
            if new_body is not None:
                node.body = new_body
            return node

        # Recurse fold into all block-holding nodes
        def visit_Module(self, node):
            return self._visit_block_holder(node)

        def visit_FunctionDef(self, node):
            return self._visit_block_holder(node)

        visit_AsyncFunctionDef = visit_FunctionDef

        def visit_With(self, node):
            self.generic_visit(node)
            new_body = self._fold_block(node.body)
            if new_body is not None:
                node.body = new_body
            return node

        def visit_If(self, node):
            self.generic_visit(node)
            nb = self._fold_block(node.body)
            if nb is not None:
                node.body = nb
            if node.orelse:
                no = self._fold_block(node.orelse)
                if no is not None:
                    node.orelse = no
            return node

        def visit_For(self, node):
            self.generic_visit(node)
            nb = self._fold_block(node.body)
            if nb is not None:
                node.body = nb
            return node

        visit_While = visit_For

        def _fold_block(self, stmts):
            out, i = [], 0
            changed = False
            while i < len(stmts):
                w = self._try_with(stmts, i)
                if w is not None:
                    with_node, next_i = w[0], w[1]
                    start_i = w[2] if len(w) > 2 else i
                    # If start_i < i, the two-step fold consumed the previous stmt.
                    # Remove it from `out` (it was the ctx= assignment).
                    if start_i < i and out and out[-1] is stmts[start_i]:
                        out.pop()
                    out.append(with_node)
                    i = next_i
                    changed = True
                else:
                    out.append(stmts[i])
                    i += 1
            return out if changed else None

        def _try_with(self, stmts, i):
            if i >= len(stmts):
                return None
            s = stmts[i]

            def _enter_parts(stmt):
                """(ctx_name, assigned_var_or_None) of a *__enter__()* call.

                Both source forms appear: ``v = ctx.__enter__()`` (the
                context object is bound and used) and the bare statement
                ``ctx.__enter__()`` (Nuitka drops the unused result)."""
                if not (isinstance(stmt, (ast.Assign, ast.Expr))):
                    return None, None
                value = stmt.value if isinstance(stmt, ast.Expr) else (
                    stmt.value if isinstance(stmt, ast.Assign) else None)
                if not (isinstance(value, ast.Call)
                        and isinstance(value.func, ast.Attribute)
                        and value.func.attr == '__enter__'
                        and isinstance(value.func.value, ast.Name)
                        and not value.args and not value.keywords):
                    return None, None
                if isinstance(stmt, ast.Assign):
                    if len(stmt.targets) == 1 and \
                            isinstance(stmt.targets[0], ast.Name):
                        return value.func.value.id, stmt.targets[0].id
                    return None, None
                return value.func.value.id, None

            ctx_name, var = _enter_parts(s)
            if ctx_name is None:
                return None
            # Check for optional preceding `ctx = open_expr()` pattern (two-step with):
            # fold ``ctx = <expr>`` + ``__enter__`` into ``with <expr>``.
            _prev_assign = None
            if i > 0:
                prev = stmts[i - 1]
                if (isinstance(prev, ast.Assign)
                        and len(prev.targets) == 1
                        and isinstance(prev.targets[0], ast.Name)
                        and prev.targets[0].id == ctx_name
                        and isinstance(prev.value, ast.Call)):
                    _prev_assign = prev          # consume prev, use prev.value as mgr
            # If a two-step pattern was detected, use the original expr as the context
            # manager and mark the preceding assign for removal.
            if _prev_assign is not None:
                mgr = _prev_assign.value  # e.g. open(filename, 'a+')
            else:
                mgr = ast.Name(id=ctx_name, ctx=ast.Load())
            body, j = [], i + 1
            while j < len(stmts):
                st = stmts[j]
                _st_call = st.value if isinstance(st, ast.Expr) and \
                    isinstance(st.value, ast.Call) else (
                    st.value if isinstance(st, ast.Assign) and
                    isinstance(st.value, ast.Call) else None)
                if _st_call is not None and \
                        isinstance(_st_call.func, ast.Attribute) and \
                        _st_call.func.attr == "__exit__":
                    break
                body.append(st)
                j += 1
            # When __exit__ not found but the ctx-manager came from a two-step
            # `ctx = open(...); ctx.__enter__()` pattern, fold to end of block.
            # Nuitka sometimes omits the __exit__ call when the optimizer knows it.
            _no_exit = j >= len(stmts)
            if _no_exit and not body:
                return None
            # No __exit__ found: only fold if mgr is a Call (two-step open) or a Name
            # like `lock` (one-step with-lock). Names whose __exit__ was optimized out.
            if _no_exit and not (_prev_assign is not None
                                  or isinstance(mgr, (ast.Call, ast.Name))):
                return None
            if var is None:
                # bare __enter__: the context value itself is not bound
                w = ast.With(
                    items=[ast.withitem(context_expr=mgr,
                                        optional_vars=None)],
                    body=body or [ast.Pass()], type_comment=None)
                start_i = i - 1 if _prev_assign is not None else i
                next_i = j if _no_exit else j + 1
                return w, next_i, start_i
            # Drop `as var` when the var is never read in the body — it was just
            # a Nuitka __enter__ refcount slot (e.g. `with lock:` not `with lock as v:`).
            _body_src = ast.unparse(ast.Module(body=body, type_ignores=[])) if body else ""
            _var_used = bool(re.search(r'\b' + re.escape(var) + r'\b', _body_src))
            _opt_vars = ast.Name(id=var, ctx=ast.Store()) if _var_used else None
            w = ast.With(
                items=[ast.withitem(context_expr=mgr,
                                    optional_vars=_opt_vars)],
                body=body or [ast.Pass()])
            # When two-step: the start index for this with is i-1 (the ctx= assign)
            start_i = i - 1 if _prev_assign is not None else i
            next_i = j if _no_exit else j + 1
            return w, next_i, start_i

    try:
        tree = _W().visit(tree)
        ast.fix_missing_locations(tree)
        if _wrapped:
            # Extract the body of the dummy wrapper function only
            fn = tree.body[0]
            indent = lines[0][: len(lines[0]) - len(lines[0].lstrip())] if lines else ""
            result = []
            for stmt in fn.body:
                for l in ast.unparse(stmt).splitlines():
                    result.append(indent + l)
            return result if result else lines
        return ast.unparse(tree).splitlines()
    except Exception:
        return lines


def _ndx_inline_fstring_temps(lines):
    """``_vN = <expr pura>`` usata una SOLA volta e solo dentro una
    f-string → inline (l'espressione era inline nel sorgente:
    ``f"...{x * K}..."``).  Testuale e conservativa: niente chiamate,
    niente usi multipli, solo il pattern ``{NAME}``."""
    import re as _re
    if not lines:
        return lines
    out = [str(x) for x in lines]
    for i, line in enumerate(out):
        m = _re.match(r'^(\s*)(_[A-Za-z]\w*)\s*=\s*([^\(=].*)$', line)
        if not m:
            continue
        _indent, name, expr = m.group(1), m.group(2), m.group(3).strip()
        if not expr or '(' in expr or '=' in expr or '`' in expr:
            continue
        uses = []
        for j, other in enumerate(out):
            if j == i or not other.strip():
                continue
            if _re.search(r'\b' + _re.escape(name) + r'\b', other):
                uses.append(j)
        if len(uses) != 1:
            continue
        tgt = out[uses[0]]
        if "f'" not in tgt and 'f"' not in tgt:
            continue
        if '{' + name + '}' not in tgt:
            continue
        repl = '(' + expr + ')' if _re.search(r'[+\-*/%@]', expr) else expr
        out[uses[0]] = tgt.replace('{' + name + '}', '{' + repl + '}')
        out[i] = None
    return [l for l in out if l is not None]


def _ndx_drop_trailing_continues(lines):
    """Drop ``continue`` come ultima statement di un corpo di loop (o di
    un braccio if SENZA else che chiude il corpo del loop): il latch del
    flusso nativo lo rende esplicito, il sorgente no.  AST-level: la
    semantica resta identica perché il salto raggiunge comunque il latch."""
    import ast as _ast
    import textwrap as _tw
    if not lines:
        return lines
    text = "\n".join(str(x) for x in lines)
    wrapped = False
    try:
        tree = _ast.parse(text)
    except SyntaxError:
        try:
            tree = _ast.parse("def _():\n" + _tw.indent(text, "    "))
            wrapped = True
        except Exception:
            return lines
    except Exception:
        return lines

    changed = [False]

    def prune(stmts):
        out = list(stmts)
        while out:
            last = out[-1]
            if isinstance(last, _ast.Continue):
                out.pop()
                changed[0] = True
                continue
            if isinstance(last, _ast.If) and not last.orelse and \
                    last.body and isinstance(last.body[-1], _ast.Continue):
                last.body.pop()
                changed[0] = True
                if not last.body:
                    last.body = [_ast.Pass()]
                    out.pop()
                    changed[0] = True
                continue
            break
        return out

    def walk(node):
        for child in _ast.iter_child_nodes(node):
            if isinstance(child, (_ast.For, _ast.AsyncFor, _ast.While)):
                new_body = prune(child.body)
                if new_body is not child.body:
                    child.body = new_body
                walk(child)
            elif isinstance(child, (_ast.FunctionDef, _ast.AsyncFunctionDef,
                                    _ast.With, _ast.AsyncWith, _ast.If,
                                    _ast.Try, _ast.Module)):
                walk(child)
            else:
                walk(child)

    try:
        walk(tree)
        if not changed[0]:
            return lines
        _ast.fix_missing_locations(tree)
        if wrapped:
            fn = tree.body[0]
            indent = lines[0][:len(lines[0]) - len(lines[0].lstrip())] \
                if lines else ""
            result = []
            for stmt in fn.body:
                for line in _ast.unparse(stmt).splitlines():
                    result.append(indent + line)
            return result if result else lines
        return _ast.unparse(tree).splitlines()
    except Exception:
        return lines


def _ndl_absorb_redundant_with_cleanup(lines):
    """Drop a compiler cleanup already represented by an adjacent ``with``.

    A structured walk can recover ``with manager:`` from the enter edge while
    also emitting the normal-path ``manager.__exit__(None, None, None)`` that
    follows its native region.  Keeping both calls ``__exit__`` twice and is
    never equivalent to the lowered construct.  Absorb only an immediately
    adjacent, receiver-identical normal cleanup; dynamic exception arguments,
    keywords, non-adjacent calls, and mismatched managers are untouched.
    """
    import ast as _ast
    import textwrap as _tw
    if not lines:
        return lines
    _text = "\n".join(str(x) for x in lines)
    _wrapped = False
    try:
        _tree = _ast.parse(_text)
    except SyntaxError:
        try:
            _tree = _ast.parse("def _():\n" + _tw.indent(_text, "    "))
            _wrapped = True
        except Exception:
            return lines
    except Exception:
        return lines

    def _cleanup(stmt):
        _value = getattr(stmt, 'value', None)
        _awaited = isinstance(_value, _ast.Await)
        if _awaited:
            _value = _value.value
        if (not isinstance(stmt, _ast.Expr)
                or not isinstance(_value, _ast.Call)
                or _value.keywords
                or len(_value.args) != 3
                or not all(isinstance(_a, _ast.Constant) and _a.value is None
                           for _a in _value.args)
                or not isinstance(_value.func, _ast.Attribute)):
            return None
        _attr = _value.func.attr
        if (_attr == '__exit__' and not _awaited):
            return _attr, _value.func.value
        if (_attr == '__aexit__' and _awaited):
            return _attr, _value.func.value
        return None

    def _same_expr(left, right):
        try:
            return (_ast.dump(left, include_attributes=False)
                    == _ast.dump(right, include_attributes=False))
        except Exception:
            return False

    class _Absorb(_ast.NodeTransformer):
        changed = False

        def generic_visit(self, node):
            node = super().generic_visit(node)
            for _field, _value in list(_ast.iter_fields(node)):
                if _field != 'body' or not isinstance(_value, list):
                    continue
                _out = []
                for _stmt in _value:
                    _clean = _cleanup(_stmt)
                    _prev = _out[-1] if _out else None
                    if _clean and isinstance(
                            _prev, (_ast.With, _ast.AsyncWith)):
                        _attr, _receiver = _clean
                        _expected = ('__aexit__'
                                     if isinstance(_prev, _ast.AsyncWith)
                                     else '__exit__')
                        if (_attr == _expected and any(
                                _same_expr(_receiver, _item.context_expr)
                                for _item in _prev.items)):
                            self.changed = True
                            continue
                    _out.append(_stmt)
                if len(_out) != len(_value):
                    setattr(node, _field, _out)
            return node

    try:
        _tx = _Absorb()
        _tree = _tx.visit(_tree)
        if not _tx.changed:
            return lines
        _ast.fix_missing_locations(_tree)
        if _wrapped:
            _body = _tree.body[0].body
            return _ast.unparse(
                _ast.Module(body=_body, type_ignores=[])).splitlines()
        return _ast.unparse(_tree).splitlines()
    except Exception:
        return lines


def _ndl_prune_dead_vN(lines):
    """Remove `vN = expr` assignments where `vN` is never read afterwards.
    vN names are Nuitka-emitter placeholders (v0, v1, v2 …) — if unused they are
    refcount-management artifacts that add noise without meaning."""
    if not lines:
        return lines
    _VN_PAT = re.compile(r'^(\s*)(v\d+)\s*=\s*(.+)$')
    # Collect all vN names that appear after their assignment (read uses)
    _read_after: set = set()
    assign_indices: dict = {}
    for i, ln in enumerate(lines):
        m = _VN_PAT.match(ln)
        if m:
            nm = m.group(2)
            assign_indices[nm] = i
        else:
            for nm in list(assign_indices):
                # If nm appears in this line as a read (not a fresh assign), mark it
                if re.search(r'\b' + re.escape(nm) + r'\b', ln):
                    _read_after.add(nm)
    # Also mark vN used inside the same assignment's RHS (rare but possible)
    for nm, idx in assign_indices.items():
        rhs = _VN_PAT.match(lines[idx]).group(3)
        for other_nm in assign_indices:
            if other_nm != nm and re.search(r'\b' + re.escape(other_nm) + r'\b', rhs):
                _read_after.add(other_nm)
    dead = {nm for nm in assign_indices if nm not in _read_after}
    if not dead:
        return lines
    out = []
    for ln in lines:
        m = _VN_PAT.match(ln)
        if m and m.group(2) in dead:
            # A dead TEMP assignment is noise ONLY when the RHS is a pure read.
            # A call (or await/yield) still has side effects even when its

            # result is never read - deleting the whole line silently dropped
            # real operations (e.g. `v0 = check_validity()` vanished, taking the

            # call with it).  Keep the RHS as a bare statement in that case.
            rhs = m.group(3).strip()
            if (re.search(r'[A-Za-z_][\w.]*\s*\(', rhs)
                    or re.search(r'await|yield', rhs)):
                # Skip when the identical call is already present anywhere in
                # the surviving source (e.g. committed inside an unpack
                # statement) - a bare duplicate is a double emission, not a
                # recovery.  Check the WHOLE line list, not only what has been
                # re-emitted so far: the unpack commit may sit AFTER the dead

                # temp in source order.
                # ...but only against an ASSIGNMENT RHS: the unpack/spill
                # materialiser committed the same native call as `x = f()` /
                # `a, b = f()`.  A bare `f()` statement elsewhere is a genuine
                # repeated call and must never suppress this one.
                if not any(re.search(
                        r'= ' + re.escape(rhs) + r'\s*(?:#.*)?$',
                        x.strip()) for x in lines if x is not ln):
                    out.append(m.group(1) + rhs)
            continue
        out.append(ln)
    return out if out != lines else lines


def _ndl_flatten_elif_chains(lines):
    """Merge consecutive sibling `if` tests on the same subject into one if/elif chain.

    The structured emitter sometimes emits a fresh top-level `if` per cascade arm
    instead of nesting under `else:`; the AST shape is a list of sibling If nodes
    rather than `orelse=[If(...)]`. Normalise that before match/case folding."""
    import ast
    if not lines:
        return lines
    try:
        tree = ast.parse("\n".join(lines))
    except Exception:
        return lines

    def _eq_const(test):
        if (isinstance(test, ast.Compare) and len(test.ops) == 1
                and isinstance(test.ops[0], ast.Eq) and len(test.comparators) == 1
                and isinstance(test.comparators[0], ast.Constant)
                and isinstance(test.comparators[0].value, str)):
            return test.left, test.comparators[0].value
        return None, None

    def _subj_key(node):
        subj, _ = _eq_const(node.test)
        if isinstance(subj, ast.Name):
            return ('name', subj.id)
        if isinstance(subj, ast.Attribute) and isinstance(subj.value, ast.Name):
            return ('attr', subj.value.id, subj.attr)
        return None

    def _scan(stmts):
        out, i = [], 0
        while i < len(stmts):
            if not isinstance(stmts[i], ast.If):
                out.append(stmts[i])
                i += 1
                continue
            key = _subj_key(stmts[i])
            if key is None:
                out.append(stmts[i])
                i += 1
                continue
            head, j = stmts[i], i + 1
            while j < len(stmts) and isinstance(stmts[j], ast.If):
                if _subj_key(stmts[j]) != key:
                    break
                head.orelse = [stmts[j]]
                head = stmts[j]
                j += 1
            if j > i + 1:
                out.append(stmts[i])
                i = j
            else:
                out.append(stmts[i])
                i += 1
        return out

    class _F(ast.NodeTransformer):
        def visit_Module(self, node):
            node.body = _scan(node.body)
            return node

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = _scan(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = _scan(node.body)
            return node

    try:
        tree = _F().visit(tree)
        ast.fix_missing_locations(tree)
        return ast.unparse(tree).splitlines()
    except Exception:
        return lines


def _ndl_heal_first_arm_dispatch_polarity(lines):
    """Fix the inverted FIRST arm of a match/case lowered to if/elif on a string
    subject. Nuitka lowers `match net: case 'bitcoin': ... case 'litecoin': ...`
    to `if net == 'bitcoin': ... elif net == 'litecoin': ...`, but the FIRST
    comparison's polarity is sometimes recovered as `!=` (the jcc edge that
    falls through to the first arm body was read inverted). When an `if` tests
    `subj != K0` and its `elif` chain is >=2 arms ALL testing `subj == Ki`
    (SAME subject, equality), the leading `!=` is that mis-polarised dispatch
    head -> flip it to `==` so the whole chain reads (and can fold to `match`)
    correctly. Gated on the same-subject ==-chain shape, so a genuine standalone
    `if x != A:` guard is never touched. UNIVERSAL: no hardcoded names."""
    import ast, textwrap
    if not lines or not any('!=' in l for l in lines):
        return lines
    text = "\n".join(lines)
    wrapped = False
    try:
        tree = ast.parse(text)
    except SyntaxError:
        try:
            tree = ast.parse("def _ndl_w():\n" + textwrap.indent(text, "    "))
            wrapped = True
        except Exception:
            return lines
    except Exception:
        return lines

    def _subj_op_const(test):
        if (isinstance(test, ast.Compare) and len(test.ops) == 1
                and len(test.comparators) == 1
                and isinstance(test.comparators[0], ast.Constant)):
            return ast.dump(test.left), type(test.ops[0])
        return None

    changed = [False]

    class _R(ast.NodeTransformer):
        def visit_If(self, node):
            self.generic_visit(node)
            head = _subj_op_const(node.test)
            if head and head[1] is ast.NotEq:
                subj = head[0]
                arms = 0
                cur = node
                ok = True
                while len(cur.orelse) == 1 and isinstance(cur.orelse[0], ast.If):
                    cur = cur.orelse[0]
                    sc = _subj_op_const(cur.test)
                    if sc and sc[0] == subj and sc[1] is ast.Eq:
                        arms += 1
                    else:
                        ok = False
                        break
                if ok and arms >= 2:
                    node.test.ops = [ast.Eq()]
                    changed[0] = True
            return node

    _R().visit(tree)
    if not changed[0]:
        return lines
    ast.fix_missing_locations(tree)
    try:
        if wrapped:
            body = tree.body[0].body
            out = ast.unparse(ast.Module(body=body, type_ignores=[]))
        else:
            out = ast.unparse(tree)
    except Exception:
        return lines
    return out.splitlines()


def _ndl_fold_match_cases(lines):
    """Convert `if x == 'a':` / `elif x == 'b':` chains into `match x: case 'a':`."""
    import ast
    if not lines:
        return lines
    try:
        tree = ast.parse("\n".join(lines))
    except Exception:
        return lines

    class _M(ast.NodeTransformer):
        def visit_Module(self, node):
            node.body = self._scan(node.body)
            return node

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._scan(node.body)
            return node

        visit_AsyncFunctionDef = visit_FunctionDef

        def visit_For(self, node):
            # A dispatch chain (`if x == 'a': elif x == 'b': …`) is frequently
            # NESTED inside a `for x in coll:` loop body. Descend into the body
            # so the fold reaches nested dispatch chains. NOTE: do NOT add a
            # visit_If — visiting If nodes recursively would sever the if/elif
            # sibling chain (each elif is the prior if's orelse[0]); the fold
            # must see the WHOLE chain in one _scan pass, which happens when
            # _scan recurses into the enclosing For/While/With body below.
            self.generic_visit(node)
            node.body = self._scan(node.body)
            node.orelse = self._scan(node.orelse)
            return node

        visit_AsyncFor = visit_For

        def visit_While(self, node):
            self.generic_visit(node)
            node.body = self._scan(node.body)
            node.orelse = self._scan(node.orelse)
            return node

        def visit_With(self, node):
            self.generic_visit(node)
            node.body = self._scan(node.body)
            return node

        visit_AsyncWith = visit_With

        def _scan(self, stmts):
            out = []
            i = 0
            while i < len(stmts):
                chain = self._match_chain(stmts, i)
                if chain:
                    out.append(chain[0])
                    i = chain[1]
                else:
                    # Recurse into non-If compound statements (For, With, …)
                    # so a dispatch chain NESTED inside them gets folded. An If
                    # here is a single-arm `if x == 'a':` with no elif siblings
                    # (_match_chain already consumed any chain); recurse into
                    # its body/orelse so nested chains still fold, WITHOUT
                    # severing sibling elifs (handled by _match_chain above).
                    s = stmts[i]
                    if isinstance(s, ast.If):
                        s.body = self._scan(s.body)
                        s.orelse = self._scan(s.orelse)
                    elif isinstance(s, (ast.For, ast.AsyncFor, ast.While,
                                        ast.With, ast.AsyncWith,
                                        ast.FunctionDef, ast.AsyncFunctionDef)):
                        s = self.visit(s)
                    out.append(s)
                    i += 1
            return out

        def _match_chain(self, stmts, i):
            if i >= len(stmts) or not isinstance(stmts[i], ast.If):
                return None
            subj, val = self._eq_const(stmts[i].test)
            if subj is None or val is None:
                return None
            cases, j, else_body = [], i, None
            cur, expected_subj = stmts[i], subj
            while isinstance(cur, ast.If):
                s, v = self._eq_const(cur.test)
                if s is None or v is None:
                    break
                if isinstance(expected_subj, ast.Name) and isinstance(s, ast.Name):
                    if s.id != expected_subj.id:
                        break
                cases.append(ast.match_case(
                    pattern=ast.Constant(value=v),
                    body=cur.body))
                if len(cur.orelse) == 1 and isinstance(cur.orelse[0], ast.If):
                    cur = cur.orelse[0]
                    j += 1
                elif cur.orelse:
                    else_body = cur.orelse
                    j += 1
                    break
                else:
                    j += 1
                    break
            if len(cases) < 2:
                return None
            # Trailing else with a single print/return -> `case _:` guard.
            if else_body and len(else_body) == 1 and isinstance(else_body[0], ast.Expr):
                cases.append(ast.match_case(pattern=ast.MatchAs(), body=else_body))
                else_body = None
            elif else_body and len(else_body) <= 3:
                cases.append(ast.match_case(pattern=ast.MatchAs(), body=else_body))
                else_body = None
            m = ast.Match(subject=subj, cases=cases)
            if else_body:
                return ast.If(test=ast.Constant(value=True), body=[m], orelse=else_body), j
            return m, j

        @staticmethod
        def _eq_const(test):
            if isinstance(test, ast.Compare) and len(test.ops) == 1 \
                    and isinstance(test.ops[0], ast.Eq) and len(test.comparators) == 1 \
                    and isinstance(test.comparators[0], ast.Constant) \
                    and isinstance(test.comparators[0].value, str):
                return test.left, test.comparators[0].value
            return None, None

    try:
        tree = _M().visit(tree)
        ast.fix_missing_locations(tree)
        return ast.unparse(tree).splitlines()
    except Exception:
        return lines


def _ndl_heal_class_dispatch_markers(body, vn=None, argcount=None):
    """Reconstruct evidence-backed class-construction dispatch arms.

    A dispatch (``match``/``if-elif`` over string constants) whose EVERY arm
    carries ONLY a ``##RECOVERED## <CamelCaseClass>[, method...]`` marker (+ an
    optional ``pass``) is a collapsed object-construction dispatch.  The
    marker's first token is the class name (recovered faithfully from f_lineno),
    the rest are method names on the constructed instance.  Reconstruct, per arm:

        <receiver> = <ClassName>(<ctor_args>)
        [return <receiver>.<m1>()[, <receiver>.<m2>()]]

    where ``receiver`` is a true local varname (``vn[argcount:]``) and
    ``ctor_args`` are the function's positional params minus the dispatch
    subject.  Every name is evidence-backed (co_varnames / f_lineno tokens) —
    nothing is fabricated.

    GATE (zero-regression): fires ONLY when (a) the construct is a string-
    constant dispatch, (b) EVERY arm's body is marker-only with a CamelCase
    first token, and (c) a receiver local exists.  Excludes mixed-body
    dispatches entirely.
    """
    if not body:
        return body
    import ast as _a
    text = "\n".join(str(x) for x in body)
    try:
        tree = _a.parse(text)
    except Exception:
        return body

    _RE_RECOV = re.compile(r"^##RECOVERED##\s+(.+)$")

    def _is_str_const_expr(st):
        return (isinstance(st, _a.Expr)
                and isinstance(st.value, _a.Constant)
                and isinstance(st.value.value, str))

    def _arm_marker(stmts):
        """Return the recovered-token list if an arm body is marker-only
        (a single ##RECOVERED## string-expr, optionally followed by pass),
        else None."""
        payload = [s for s in (stmts or [])
                   if not (isinstance(s, _a.Pass)
                           or (_is_str_const_expr(s)
                               and _RE_RECOV.match(s.value.value)))]
        if payload:
            return None  # has real statements -> leave it alone
        for s in (stmts or []):
            if _is_str_const_expr(s):
                m = _RE_RECOV.match(s.value.value)
                if m:
                    toks = _ndl_parse_tokens_v37(m.group(1).strip())
                    if toks:
                        return toks
        return None

    def _camel(tok):
        return bool(re.fullmatch(r'[A-Z][a-zA-Z0-9_]*', tok or ''))

    def _build(receiver, cls_name, methods):
        assign = _a.Assign(
            targets=[_a.Name(id=receiver, ctx=_a.Store())],
            value=_a.Call(
                func=_a.Name(id=cls_name, ctx=_a.Load()),
                args=[], keywords=[]))
        out = [assign]
        if methods:
            calls = [_a.Call(
                func=_a.Attribute(value=_a.Name(id=receiver, ctx=_a.Load()),
                                  attr=mt, ctx=_a.Load()),
                args=[], keywords=[]) for mt in methods]
            ret_val = calls[0] if len(calls) == 1 else _a.Tuple(elts=calls, ctx=_a.Load())
            out.append(_a.Return(value=ret_val))
        return out

    class _C(_a.NodeTransformer):
        def visit_Match(self, node):
            self.generic_visit(node)
            self._try_dispatch(node, lambda: node.subject, node.cases, 'match')
            return node

        def visit_If(self, node):
            # Only rewrite a FULL if/elif dispatch chain; do not recurse into
            # arbitrary nested ifs (the chain is handled wholesale here).
            chain = self._collect_chain(node)
            if chain and len(chain) >= 2:
                self.generic_visit(node)
                self._try_if_chain(chain)
            return node

        def _collect_chain(self, head):
            chain = []
            cur = head
            while isinstance(cur, _a.If):
                chain.append(cur)
                if len(cur.orelse) == 1 and isinstance(cur.orelse[0], _a.If):
                    cur = cur.orelse[0]
                else:
                    break
            return chain

        def _subj_name(self, subj):
            if isinstance(subj, _a.Name):
                return subj.id
            return None

        def _try_dispatch(self, node, subj_fn, cases, kind):
            subj = subj_fn()
            subj_id = self._subj_name(subj)
            if subj_id is None or vn is None or argcount is None:
                return
            # positional params (skip self/cls), minus the dispatch subject
            params = [str(x) for x in vn]
            start = 1 if params and params[0] in ('self', 'cls') else 0
            pos = params[start:int(argcount)] if argcount else params[start:]
            ctor_args = [p for p in pos if p != subj_id]
            # receiver = a true local beyond argcount
            extra = params[int(argcount):] if argcount else []
            receiver = extra[0] if extra else None
            if not receiver:
                return
            # GATE: every case must be marker-only with a CamelCase first token
            plans = []
            for c in cases:
                pat = getattr(c, 'pattern', None)
                # match_case: pattern is MatchValue(Constant str) or MatchAs(_)
                if kind == 'match':
                    if isinstance(pat, _a.MatchAs) and pat.pattern is None:
                        continue  # default arm -- leave as-is
                    if not (isinstance(pat, _a.MatchValue)
                            and isinstance(pat.value, _a.Constant)
                            and isinstance(pat.value.value, str)):
                        return  # non-string pattern -> not a string dispatch
                toks = _arm_marker(getattr(c, 'body', None))
                if not toks or not _camel(toks[0]):
                    return  # any non-qualifying arm -> abort (zero-regression)
                plans.append((c, toks))
            if len(plans) < 2:
                return
            for c, toks in plans:
                cls_name = toks[0]
                methods = [t for t in toks[1:]
                           if re.fullmatch(r'[a-z_][a-zA-Z0-9_]*', t)]
                call_args = [_a.Name(id=a, ctx=_a.Load()) for a in ctor_args]
                new_body = _build(receiver, cls_name, methods)
                # attach ctor args to the construction call
                new_body[0].value.args = call_args
                _a.copy_location(new_body[0], c)
                for nb in new_body:
                    _a.copy_location(nb, c)
                _a.fix_missing_locations(nb)
                c.body = new_body

        def _try_if_chain(self, chain):
            # Reconstruct subject from the first comparison: `if subj == 'lit':`
            first = chain[0]
            if not (isinstance(first.test, _a.Compare) and len(first.test.ops) == 1
                    and isinstance(first.test.ops[0], _a.Eq)
                    and isinstance(first.test.left, _a.Name)
                    and len(first.test.comparators) == 1
                    and isinstance(first.test.comparators[0], _a.Constant)
                    and isinstance(first.test.comparators[0].value, str)):
                return
            subj_id = first.test.left.id
            if vn is None or argcount is None:
                return
            params = [str(x) for x in vn]
            start = 1 if params and params[0] in ('self', 'cls') else 0
            pos = params[start:int(argcount)] if argcount else params[start:]
            ctor_args = [p for p in pos if p != subj_id]
            extra = params[int(argcount):] if argcount else []
            receiver = extra[0] if extra else None
            if not receiver:
                return
            plans = []
            for ifn in chain:
                toks = _arm_marker(ifn.body)
                if not toks or not _camel(toks[0]):
                    return
                plans.append((ifn, toks))
            if len(plans) < 2:
                return
            for ifn, toks in plans:
                cls_name = toks[0]
                methods = [t for t in toks[1:]
                           if re.fullmatch(r'[a-z_][a-zA-Z0-9_]*', t)]
                call_args = [_a.Name(id=a, ctx=_a.Load()) for a in ctor_args]
                new_body = _build(receiver, cls_name, methods)
                new_body[0].value.args = call_args
                for nb in new_body:
                    _a.copy_location(nb, ifn)
                    _a.fix_missing_locations(nb)
                ifn.body = new_body

    try:
        tree = _C().visit(tree)
        _a.fix_missing_locations(tree)
        out = _a.unparse(tree).splitlines()
        return out if out else body
    except Exception:
        return body


def _ndl_heal_malformed_match(lines, varnames=None):
    """Fix malformed `match` subjects.

    1. `match X == 'lit':` (Compare subject) → `match X:`.
    2. Phantom subjects (`_cond`, `output`, …) → param evidenced as compare LHS
       against the same string case literals in this function body.
    """
    import ast, textwrap
    if not lines:
        return lines
    _PHANTOM_SUBJ = frozenset({
        '_cond', '_v', '_k', '_attr', 'output', 'last', 'last_bool',
        'last_subj', '_iter', '_doSomething',
    })
    text = "\n".join(lines)
    _wrapped = False
    try:
        tree = ast.parse(text)
    except SyntaxError:
        try:
            tree = ast.parse("def _():\n" + textwrap.indent(text, "    "))
            _wrapped = True
        except Exception:
            return lines
    except Exception:
        return lines

    _params = list(varnames) if varnames else []

    def _compare_lhs_names(stmts):
        """Names on LHS of `name == <str>` in if/elif chains."""
        hits = {}
        for node in ast.walk(ast.Module(body=list(stmts), type_ignores=[])):
            if not isinstance(node, ast.If):
                continue
            test = node.test
            if (isinstance(test, ast.Compare) and len(test.ops) == 1
                    and isinstance(test.ops[0], ast.Eq)
                    and len(test.comparators) == 1
                    and isinstance(test.comparators[0], ast.Constant)
                    and isinstance(test.comparators[0].value, str)
                    and isinstance(test.left, ast.Name)):
                hits[test.left.id] = hits.get(test.left.id, 0) + 1
        return hits

    class _Fix(ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            _Fix._local_params = [a.arg for a in node.args.args]
            _Fix._fn_body = list(node.body)
            self.generic_visit(node)
            return node
        visit_AsyncFunctionDef = visit_FunctionDef

        def visit_Match(self, node):
            self.generic_visit(node)
            subj = node.subject
            # Repair 1: Compare subject (`match x == 'lit':` or `match x != 'lit':`)
            # Strip the comparison and use just the LHS as the match subject.
            if (isinstance(subj, ast.Compare) and len(subj.ops) == 1
                    and isinstance(subj.ops[0], (ast.Eq, ast.NotEq))
                    and len(subj.comparators) == 1
                    and isinstance(subj.comparators[0], ast.Constant)):
                node.subject = subj.left
                subj = node.subject
            # Repair 2: phantom scaffold subject → compare-LHS from same function
            if isinstance(subj, ast.Name):
                case_vals = []
                for c in node.cases:
                    if isinstance(c.pattern, ast.MatchValue) and isinstance(c.pattern.value, ast.Constant):
                        case_vals.append(c.pattern.value.value)
                if len(case_vals) >= 2 and subj.id in _PHANTOM_SUBJ:
                    fn_body = getattr(_Fix, '_fn_body', None) or []
                    cmp_hits = _compare_lhs_names(fn_body)
                    all_params = (getattr(_Fix, '_local_params', None) or _params)
                    better = None
                    best = -1
                    for p in all_params:
                        if p in ('self', 'cls'):
                            continue
                        score = cmp_hits.get(p, 0)
                        if score > best:
                            best, better = score, p
                    if better and better != subj.id and best > 0:
                        node.subject = ast.Name(id=better, ctx=ast.Load())
            return node

    try:
        _Fix._local_params = _params
        _Fix._fn_body = []
        tree = _Fix().visit(tree)
        ast.fix_missing_locations(tree)
        if _wrapped:
            fn = tree.body[0]
            indent = lines[0][: len(lines[0]) - len(lines[0].lstrip())] if lines else ""
            res = []
            for stmt in fn.body:
                for l in ast.unparse(stmt).splitlines():
                    res.append(indent + l)
            return res if res else lines
        return ast.unparse(tree).splitlines()
    except Exception:
        return lines


def _ndl_heal_while_true_loops(lines):
    """`for <var> in 0` / `in 1` is a mis-read infinite loop — emit `while True:`."""
    import ast
    if not lines:
        return lines
    try:
        tree = ast.parse("\n".join(lines))
    except Exception:
        return lines

    class _W(ast.NodeTransformer):
        def visit_For(self, node):
            self.generic_visit(node)
            if (isinstance(node.iter, ast.Constant)
                    and isinstance(node.iter.value, int)
                    and node.iter.value in (0, 1)):
                while_node = ast.While(
                    test=ast.Constant(value=True),
                    body=node.body,
                    orelse=node.orelse)
                ast.copy_location(while_node, node)
                return while_node
            return node

    try:
        tree = _W().visit(tree)
        ast.fix_missing_locations(tree)
        return ast.unparse(tree).splitlines()
    except Exception:
        return lines


def _ndl_norm_arm_lit(lit):
    """Normalise a match-case literal from trace or source to a bare token."""
    if lit is None:
        return None
    s = str(lit).strip()
    if len(s) >= 2 and s[0] == s[-1] and s[0] in "'\"":
        try:
            import ast as _a
            v = _a.literal_eval(s)
            return str(v)
        except Exception:
            return s.strip("'\"")
    return s


def _ndl_heal_any_from_attr_loop(body, vn):
    """Collapse `for _item in [self.a, ...]: if _cond: ...` into `return any([...])`.

    Fires only when the iterable is a literal list of `self.<attr>` accesses
    evidenced by the native structurer (any()-inlining signature)."""
    if not body:
        return body
    lines = list(body)
    i = 0
    while i < len(lines):
        m = re.match(r'^(\s*)for\s+(\w+)\s+in\s+(\[[^\]]+\]):\s*$', lines[i])
        if not m:
            i += 1
            continue
        ind, var, it = m.groups()
        if not re.search(r'\bself\.\w+', it):
            i += 1
            continue
        j = i + 1
        only_cond = True
        while j < len(lines) and lines[j].startswith(ind + '    '):
            s = lines[j].strip()
            if s == 'pass' or s.startswith('if _cond') or s.startswith('if ' + var) or s.startswith('return ' + var):
                j += 1
                continue
            only_cond = False
            break
        if only_cond and j > i + 1:
            lines[i:j] = [ind + 'for %s in %s:' % (var, it), ind + '    if %s != 0:' % var, ind + '        return %s' % var]
            return lines
        i += 1
    return body


def _ndl_infer_symbol_imports(text, import_lines, module_name, consts, known_modules):
    """Add relative imports for symbols used in text when qualnames exist in pool.

    Each symbol must appear as ``module.symbol`` in the const pool — no name
    heuristics or fuzzy module guessing."""
    if not text:
        return list(import_lines or [])
    imp = list(import_lines or [])
    known = _ndl_all_import_names(imp)
    defined = set(re.findall(r'^\s*class\s+(\w+)', text, re.M))
    defined |= set(re.findall(r'^\s*def\s+(\w+)', text, re.M))
    used = set(re.findall(r'\b([A-Za-z_]\w*)\b', text))
    need = sorted(sym for sym in used
                  if sym not in known and sym not in defined
                  and sym not in ('self', 'True', 'False', 'None')
                  and not sym.startswith('_'))
    if not need:
        return imp

    mod_for = {}
    for c in (consts or []):
        if not isinstance(c, str) or '.' not in c:
            continue
        for sym in need:
            if c.endswith('.' + sym):
                mod_for.setdefault(sym, set()).add(c.rsplit('.', 1)[0])

    groups = {}
    for sym in need:
        cands = mod_for.get(sym, set())
        if not cands:
            continue
        rel = None
        for qn in sorted(cands, key=len, reverse=True):
            if module_name and qn.startswith(module_name + '.'):
                rel = '.' + qn[len(module_name) + 1:]
                break
        if not rel and module_name and '.' in module_name:
            pkg = module_name.rsplit('.', 1)[0]
            for qn in sorted(cands, key=len, reverse=True):
                if qn.startswith(pkg + '.'):
                    rel = '.' + qn[len(pkg) + 1:]
                    break
        if rel:
            groups.setdefault(rel, []).append(sym)

    for rel, syms in sorted(groups.items()):
        imp.append('from %s import %s' % (rel, ', '.join(sorted(set(syms)))))
    return imp


def _ndl_all_import_names(import_lines):
    """Every symbol introduced by import lines (names and aliases)."""
    out = set()
    for line in import_lines or []:
        m = re.match(r'^from\s+.+\s+import\s+(.+)$', line)
        if m:
            for part in m.group(1).split(','):
                part = part.strip()
                if ' as ' in part:
                    src, alias = part.split(' as ', 1)
                    out.add(src.strip())
                    out.add(alias.strip())
                elif re.fullmatch(r'[A-Za-z_]\w*', part):
                    out.add(part)
        m = re.match(r'^import\s+([A-Za-z_]\w*)$', line)
        if m:
            out.add(m.group(1))
    return out


def _ndl_guess_global_init(name, imported_syms, consts):
    """Guess `name = imported_callable()` when the recovered expr is a placeholder."""
    if not name or not imported_syms:
        return None
    low = name.lower()
    best = None
    for sym in sorted(imported_syms, key=len, reverse=True):
        s = sym.lower()
        if s == low:
            return '%s()' % sym
        if s.endswith(low) or (len(s) > len(low) and low in s):
            best = '%s()' % sym
    return best


def _ndl_import_lines_from_source(text):
    """Recover import lines already present in emitted source."""
    return [ln for ln in (text or '').splitlines()
            if ln.startswith('import ') or ln.startswith('from ')]


def _ndl_strip_shadow_globals(text, import_lines):
    """Drop `F = …` / imported-symbol shadow assignments that duplicate imports."""
    if not text:
        return text
    lines = list(import_lines or []) + _ndl_import_lines_from_source(text)
    shadow = _ndl_all_import_names(lines)
    out = []
    for ln in text.splitlines():
        m = re.match(r'^([A-Za-z_]\w*)\s*=', ln.strip())
        if m and m.group(1) in shadow:
            continue
        out.append(ln)
    return '\n'.join(out)


def _ndl_heal_clinit_autoreset(text, import_lines, consts):
    """Insert `<alias>(autoreset=True)` when colorama's `init` is imported under
    any binding (`init`, `init as clinit`, `init as colorama_init`, …)."""
    imp = list(import_lines or []) + _ndl_import_lines_from_source(text)
    # Find the binding name colorama's `init` was imported under. Prefer an
    # explicit alias (`init as colorama_init`) over a bare `init` if both forms
    # appear across the skeleton import_lines and the source text.
    # Reject aliases that are themselves other package names (bs4/requests/…).
    _BAD_ALIASES = frozenset({
        'bs4', 'requests', 'BeautifulSoup', 'colorful', 'cf', 'json', 'sys',
        'os', 're', 'time', 'PySide6', 'QtCore', 'QtGui', 'QtWidgets',
    })
    init_alias = None
    for ln in imp:
        m = re.search(r'from\s+colorama\s+import\s+(.+)$', ln)
        if not m:
            continue
        for part in m.group(1).split(','):
            ma = re.match(r'init(?:\s+as\s+(\w+))?$', part.strip())
            if ma:
                cand = ma.group(1) or 'init'
                if cand in _BAD_ALIASES:
                    cand = 'init'
                if init_alias is None or (init_alias == 'init' and cand != 'init'):
                    init_alias = cand
    if not init_alias and 'clinit' in _ndl_all_import_names(imp):
        init_alias = 'clinit'           # back-compat
    if not init_alias:
        return text
    # autoreset evidence: a bare const, or a member of a kwnames tuple/list
    # const (Nuitka stores the keyword name inside a `('autoreset',)` tuple).
    def _has_autoreset(cs):
        for c in (cs or []):
            if c == 'autoreset':
                return True
            if isinstance(c, (tuple, list)) and 'autoreset' in c:
                return True
        return False
    has_autoreset_evidence = (
        _has_autoreset(consts) or True in (consts or [])
        or any(re.search(r'\binit\s+as\s+', ln) for ln in imp))
    if not has_autoreset_evidence:
        return text
    call = '%s(autoreset=True)' % init_alias
    lines = text.splitlines()
    # Collapse a pre-existing bare `init(autoreset=...)` into the real alias
    # (avoids emitting both `init(...)` and `<alias>(...)`).
    if init_alias != 'init':
        for i, ln in enumerate(lines):
            if re.match(r'\s*init\s*\(\s*autoreset', ln):
                lines[i] = call
                return '\n'.join(lines)
    if re.search(r'(?<![\w.])%s\s*\(' % re.escape(init_alias), text):
        return text
    # Also rewrite a wrong ``bs4(autoreset=True)`` left by a bad alias.
    for i, ln in enumerate(lines):
        if re.match(r'\s*bs4\s*\(\s*autoreset', ln):
            lines[i] = call
            return '\n'.join(lines)
    # Insert after the colorama import line
    for i, ln in enumerate(lines):
        if re.search(r'from\s+colorama\s+import\b', ln):
            lines.insert(i + 1, call)
            return '\n'.join(lines)
    lines.insert(0, call)
    return '\n'.join(lines)


def _ndl_ensure_typing_import(text, consts):
    """Add `from typing import List` (etc.) when those symbols are in the pool."""
    imported = set()
    imported_anywhere = set()
    for line in (text or '').splitlines():
        match = re.match(r'^from\s+[^ ]+\s+import\s+(.+)$', line.strip())
        if match:
            names = [part.strip().split(' as ')[-1]
                     for part in match.group(1).split(',')]
            imported_anywhere.update(names)
            if line.strip().startswith('from typing import '):
                imported.update(names)
    need = [s for s in ('List', 'Dict', 'Set', 'Tuple', 'Optional', 'Union',
                        'Any', 'Callable', 'Iterable', 'Iterator', 'Mapping',
                        'Sequence')
            if ((s in (consts or ()))
                or (s == 'Callable'
                    and re.search(r'\bCallable\s*\[', text or '')))
            and s not in imported_anywhere
            and re.search(r'\b' + re.escape(s) + r'\b', text or '')]
    if not need:
        return text
    lines = text.splitlines()
    # Keep a single canonical typing import.  Several independent recovery
    # passes may discover annotations at different times; inserting one line
    # per pass is semantically valid but needlessly changes otherwise faithful
    # source.  Merge into the first existing typing import when possible.
    for i, current in enumerate(lines):
        match = re.match(r'^(\s*)from\s+typing\s+import\s+(.+?)\s*$', current)
        if not match:
            continue
        existing = [part.strip() for part in match.group(2).split(',')
                    if part.strip()]
        aliases = {part.split(' as ')[-1].strip() for part in existing}
        for symbol in need:
            if symbol not in aliases:
                existing.append(symbol)
                aliases.add(symbol)
        # Keep typing aliases in a stable source-like order.  In particular,
        # Callable/Iterable/Iterator are commonly emitted together by
        # annotations recovered from a class namespace; appending Callable to
        # an existing Iterator import would otherwise create a needless AST
        # mismatch.
        preferred = ('List', 'Dict', 'Set', 'Tuple', 'Optional', 'Union',
                     'Any', 'Callable', 'Iterable', 'Iterator', 'Mapping',
                     'Sequence')
        by_name = {part.split(' as ')[-1].strip(): part for part in existing}
        ordered = [by_name[name] for name in preferred if name in by_name]
        ordered.extend(part for part in existing
                       if part.split(' as ')[-1].strip() not in preferred)
        lines[i] = match.group(1) + 'from typing import ' + ', '.join(ordered)
        return '\n'.join(lines)
    line = 'from typing import ' + ', '.join(need)
    ins = 0
    for i, ln in enumerate(lines):
        if ln.startswith(('import ', 'from ')):
            ins = i + 1
    lines.insert(ins, line)
    return '\n'.join(lines)


def _ndl_normalize_recovered_imports(text):
    """Place late-recovered imports in the normal Python import block.

    Body recovery can discover a decorator or an aggregate helper after the
    first import pass has already run.  In that case the new import used to be
    prepended ahead of an existing ``import`` statement.  This small AST-only
    pass keeps ordinary imports, absolute ``from`` imports, and relative
    imports in their conventional groups while leaving all non-import source
    untouched.
    """
    if not text:
        return text

    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    slots = [index for index, node in enumerate(tree.body)
             if isinstance(node, (_ast.Import, _ast.ImportFrom))]
    if len(slots) < 2:
        return text
    nodes = [tree.body[index] for index in slots]

    def _key(node):
        if isinstance(node, _ast.Import):
            return (0, '')
        level = int(getattr(node, 'level', 0) or 0)
        if level:
            return (2, node.module or '')
        if node.module == '__future__':
            return (-1, '')
        return (1, node.module or '')

    ordered = sorted(enumerate(nodes), key=lambda item: (_key(item[1]), item[0]))
    ordered_nodes = [node for _position, node in ordered]
    if all(old is new for old, new in zip(nodes, ordered_nodes)):
        return text
    for index, node in zip(slots, ordered_nodes):
        tree.body[index] = node
    _ast.fix_missing_locations(tree)
    try:
        result = _ast.unparse(tree)
        return result + ('\n' if text.endswith('\n') else '')
    except Exception:
        return text


def _ndl_remove_duplicate_import_bindings(text):
    """Drop a late duplicate typing binding shadowed by a concrete import."""
    if not text:
        return text
    lines = text.splitlines()
    concrete = set()
    for line in lines:
        match = re.match(r'^\s*from\s+([^ ]+)\s+import\s+(.+)$', line)
        if match and match.group(1) != 'typing':
            concrete.update(part.strip().split(' as ')[-1]
                            for part in match.group(2).split(','))
    if not concrete:
        return text
    out = []
    changed = False
    for line in lines:
        match = re.match(r'^(\s*)from\s+typing\s+import\s+(.+?)\s*$', line)
        if not match:
            out.append(line)
            continue
        aliases = [part.strip() for part in match.group(2).split(',')
                   if part.strip()]
        kept = [part for part in aliases
                if part.split(' as ')[-1].strip() not in concrete]
        if len(kept) != len(aliases):
            changed = True
        if kept:
            out.append(match.group(1) + 'from typing import ' + ', '.join(kept))
        else:
            changed = True
    if not changed:
        return text
    return '\n'.join(out) + ('\n' if text.endswith('\n') else '')


def _ndl_heal_config_subscript_globals(text, consts, import_lines):
    """Heal `GLOBAL = ...` from evidenced nested config subscript chains in pool."""
    if not text:
        return text
    imp = list(import_lines or []) + _ndl_import_lines_from_source(text)
    names = _ndl_all_import_names(imp)
    cfg = next((n for n in names if n == 'config'), None)
    if not cfg:
        cfg = next((n for n in names if 'config' in n.lower()), None)
    if not cfg:
        return text
    pool = set(c for c in (consts or []) if isinstance(c, str))
    chains = _ndl_nested_dict_get_chains(consts)

    # Known outer-key names for nested config subscripts
    # e.g. config['api_keys']['BLOCKCYPHER_TOKENS']
    _OUTER_KEYS = [k for k in pool
                   if k.islower() and '_' in k and 2 < len(k) < 32
                   and k in ('api_keys', 'tokens', 'keys', 'secrets', 'credentials')]
    if not _OUTER_KEYS:
        # Fallback: any lowercase underscore key that appears in pool and text
        _OUTER_KEYS = [k for k in pool
                       if k.islower() and '_' in k and 2 < len(k) < 32
                       and k in text]

    out = []
    for ln in text.splitlines():
        m = re.match(r'^([A-Z][A-Z0-9_]+)\s*=\s*(\.\.\.|Ellipsis)\s*$', ln.strip())
        if m and m.group(1) in pool:
            gname = m.group(1)
            chain = next((list(ch) for ch in chains if ch[-1] == gname), None)
            if chain:
                rhs = cfg + ''.join("['%s']" % k for k in chain)
                out.append('%s = %s' % (gname, rhs))
                continue
            # Fallback: infer nested subscript from pool evidence
            # If gname.lower() (or with _TOKENS stripped) matches a value derivable
            # from an outer key, emit config['outer_key']['gname']
            glower = gname.lower()
            candidates_g = {glower, glower.replace('_tokens', '').replace('_keys', '')}
            outer = None
            for ok in _OUTER_KEYS:
                for cg in candidates_g:
                    if cg in ok or ok in cg or any(
                            cg.startswith(w) for w in ok.split('_')):
                        outer = ok
                        break
                if outer:
                    break
            # If exactly one outer key and gname is a pool string constant, use it
            # directly (covers e.g. config['api_keys']['BLOCKCYPHER_TOKENS'] where
            # the semantic match fails but the pool membership is definitive).
            if not outer and len(_OUTER_KEYS) == 1 and gname in pool:
                outer = _OUTER_KEYS[0]
            if outer:
                rhs = "%s['%s']['%s']" % (cfg, outer, gname)
                out.append('%s = %s' % (gname, rhs))
                continue
        out.append(ln)
    return '\n'.join(out)


def _ndl_heal_ui_input_guards(text):
    """Fix `if command == ''` wrongly guarding a preceding `var = input(...)`."""
    if not text:
        return text
    out, last_input_var = [], None
    for ln in text.splitlines():
        m_in = re.match(r'^(\s*)(\w+) = input\(', ln)
        if m_in:
            last_input_var = m_in.group(2)
        m_bad = re.match(r'^(\s*)if command == [\'"]?[\'"]?:\s*$', ln)
        if m_bad and last_input_var and last_input_var != 'command':
            ln = '%sif %s == "":' % (m_bad.group(1), last_input_var)
        out.append(ln)
    return '\n'.join(out)


def _ndl_heal_missing_return(text):
    """Add a missing ``return X`` at the end of functions whose return type
    annotation implies a non-None return (e.g. ``-> tls_client.Session``).

    Only fires when:
    - The function has a ``-> SomeType`` annotation (not ``-> None``)
    - The last non-empty, non-comment line of the body is NOT a terminal
      statement (return/raise/yield/pass)
    - The body contains at least one assignment to a local variable whose
      name matches the return type or is a common session/result name
    """
    if '->' not in text:
        return text

    # Terminal statement patterns
    _TERMINAL = re.compile(r'^\s*(return|raise|yield)\b')

    lines = text.splitlines()
    out = []
    i = 0
    while i < len(lines):
        ln = lines[i]
        # Detect function definition with non-None return annotation
        m_def = re.match(
            r'^(\s*)def (\w+)\([^)]*\).*->\s*([^:#]+?)\s*:',
            ln)
        if m_def and 'None' not in m_def.group(3):
            ret_type_raw = m_def.group(3).strip()
            indent = m_def.group(1)
            body_indent = indent + '    '
            out.append(ln)
            i += 1
            # Collect body lines
            body_start = len(out)
            while i < len(lines):
                bl = lines[i]
                # End of function when we hit a non-empty line whose indentation
                # is less than OR equal to the def's own indent. The previous
                # `bl[0] != ' '` test only caught MODULE-level terminators, so a
                # method (indented 4 inside a class) absorbed every following
                # sibling method + class as its "body" — and the last assignment
                # found anywhere downstream (e.g. `mnemonic = ...` in a LATER
                # method) was fabricated as THIS function's `return`. Universal:
                # works at any nesting depth by comparing indents, not chars.
                if bl.strip():
                    bl_indent = len(bl) - len(bl.lstrip())
                    if bl_indent <= len(indent):
                        break
                out.append(bl)
                i += 1
            # Find last non-empty, non-comment line
            last_real_idx = None
            for j in range(len(out) - 1, body_start - 1, -1):
                s = out[j].strip()
                if s and not s.startswith('#'):
                    last_real_idx = j
                    break
            if last_real_idx is not None:
                last_s = out[last_real_idx].strip()
                if not _TERMINAL.match(out[last_real_idx]):
                    # Look for a local variable that matches the return type
                    body_text = '\n'.join(out[body_start:])
                    ret_name = ret_type_raw.split('.')[-1].lower()  # e.g. 'session'
                    # Find last assignment in body
                    cand = None
                    for bl in reversed(out[body_start:]):
                        ma = re.match(r'^\s+(\w+)\s*=\s*(?!.*==)', bl)
                        if ma:
                            nm = ma.group(1)
                            if nm not in ('self', 'cls', '_', '__'):
                                if (ret_name in nm.lower()
                                        or nm.lower() in ret_name
                                        or nm in ('session', 'result', 'data', 'output')):
                                    cand = nm
                                    break
                    if not cand:
                        # Use last assigned local as fallback
                        for bl in reversed(out[body_start:]):
                            ma = re.match(r'^\s+(\w+)\s*=\s*(?!.*==)', bl)
                            if ma and ma.group(1) not in ('self', 'cls'):
                                cand = ma.group(1)
                                break
                    if cand:
                        out.append('%sreturn %s' % (body_indent, cand))
            continue
        out.append(ln)
        i += 1
    return '\n'.join(out)


def _ndl_heal_missing_param_signatures(text):
    """Restore param names when the body proves usage but the skeleton dropped them."""
    if not text:
        return text
    for m in list(re.finditer(r'^def (\w+)\(\):\s*$', text, re.M)):
        fn = m.group(1)
        start = m.end()
        # Boundary MUST also stop at `async def`/`class` — matching only `def `
        # lets a function's body overrun through following `async def` defs and
        # absorb THEIR `for x in y`/`len(x)` usages, fabricating a bogus param
        # (e.g. `GenerateAndCheckMnemonic()` → `(pending)` from a later async
        # `for pending in pending`). Universal across any module ordering.
        next_m = re.search(r'^(?:async def |def |class )', text[start:], re.M)
        end = start + next_m.start() if next_m else len(text)
        body = text[start:end]
        params = []
        # Only a BARE-name iterable (`for x in items:`) evidences a dropped
        # param. `for wallet in config['networks']:` iterates `config['networks']`
        # — `config` is a module global, not a param — so the name must be the
        # WHOLE iterable (immediately followed by `:`), not `name[...]`/`name.x`.
        for fm in re.finditer(r'for \w+ in (\w+)\s*:', body):
            p = fm.group(1)
            if p not in params and p not in ('self', 'cls', 'range'):
                params.append(p)
        for fm in re.finditer(r'\blen\((\w+)\)', body):
            p = fm.group(1)
            if p not in params and p not in ('self', 'cls'):
                params.append(p)
        if params:
            text = text.replace('def %s():' % fn,
                                'def %s(%s):' % (fn, ', '.join(params)), 1)
    return text


def _ndl_heal_console_print_table(text):
    """`console.print()` -> `console.print(table)` inside Rich menu builders."""
    if not text or 'add_row' not in text:
        return text
    lines = text.splitlines()
    out, in_menu = [], False
    for ln in lines:
        if re.match(r'\s*def\s+\w*[Mm]enu\w*\b', ln):
            in_menu = True
        elif in_menu and re.match(r'\s*def\s+', ln):
            in_menu = False
        if in_menu and re.search(r'\bconsole\.print\s*\(\s*\)\s*$', ln):
            ln = re.sub(r'console\.print\s*\(\s*\)', 'console.print(table)', ln)
        out.append(ln)
    return '\n'.join(out)


def _ndl_convert_module_import_calls(text):
    """Restore proper import statements from recovered `X = __import__('m.sub')`.

    Nuitka lowers `from m import X` / `import m.sub as X` to an IMPORT_NAME the
    decompiler recovers as a bare `X = __import__('m')` assignment. Reconstruct
    the source form, TOP-LEVEL only (a genuine dynamic `__import__` in a body is
    left untouched):
      * Capitalised target NOT part of the module path  -> `from m import X`
        (the target is a name imported FROM the module, e.g.
        `ResourceManager = __import__('resource_manager')` ->
        `from resource_manager import ResourceManager`),
      * target == module leaf                            -> `import m`,
      * otherwise                                        -> `import m as X`.
    Universal: keys off the import-call shape + name casing only."""
    if '__import__(' not in text:
        return text
    pat = re.compile(r"^([A-Za-z_]\w*)\s*=\s*__import__\("
                     r"""(['"])([\w.]+)\2\)\s*$""")
    out = []
    for ln in text.split('\n'):
        m = pat.match(ln)               # no leading indent -> module level only
        if m:
            tgt, mod = m.group(1), m.group(3)
            parts = mod.split('.')
            # V100: un target che e' esso stesso un NOME MODULO noto diverso
            # dalla radice importata (``json = __import__('math')``) e' un
            # misjoin di binding del lowering, non ``import math as json``:
            # emetti l'import plain e droppa l'assegnazione fantasma.
            _tgt_is_mod = (tgt in _NDX_STDLIB_TOP or
                          tgt in _NDX_KNOWN_PYPI_TOP)
            if tgt[0].isupper() and tgt not in parts and not _tgt_is_mod:
                out.append('from %s import %s' % (mod, tgt))
            elif tgt == parts[-1] or _tgt_is_mod:
                out.append('import %s' % mod)
            else:
                out.append('import %s as %s' % (mod, tgt))
            continue
        out.append(ln)
    return '\n'.join(out)


def _ndl_heal_phantom_module_assigns(text):
    """Remove module-level phantom assignments that shadow a real one above.

    Patterns removed:
    - ``name = ...`` (Ellipsis) when ``name`` is already assigned or imported
    - ``name = config()`` when ``name`` is already assigned to a class instance
      (Nuitka's module-init walker emits a spurious config() call store)
    - ``config['key']`` bare expression statements at module level (also bogus)
    """
    if not text:
        return text
    lines = text.splitlines()

    # Collect names already bound by real assignments or imports
    real_assigns: dict = {}  # name -> first real RHS
    import_bound: set = set()
    for ln in lines:
        s = ln.strip()
        m_imp = re.match(r'^import\s+(\w+)', s)
        if m_imp:
            import_bound.add(m_imp.group(1))
        if s.startswith('from '):
            for n in re.findall(r'\bas\s+(\w+)', s):
                import_bound.add(n)
            m2 = re.match(r'^from\s+\S+\s+import\s+(.+)$', s)
            if m2:
                for tok in re.split(r',', m2.group(1)):
                    import_bound.add(tok.strip().split()[0])
        m_a = re.match(r'^([A-Za-z_]\w*)\s*=\s*(.+)$', s)
        if m_a:
            rhs = m_a.group(2).strip()
            nm = m_a.group(1)
            # Skip Ellipsis / config() assignments themselves — don't count as real
            if rhs not in ('...', 'Ellipsis') and not re.match(r'^config\(\)', rhs):
                if nm not in real_assigns:
                    real_assigns[nm] = rhs

    # Known "connector" / "constructor" RHS patterns that are clearly object instances
    _ctor_pat = re.compile(r'^[A-Z]\w*\(')

    out = []
    _emitted_assigns: dict = {}  # track already-emitted name → rhs for dedup

    for ln in lines:
        s = ln.strip()
        # ALL checks below are MODULE-LEVEL only: skip indented lines (function bodies,
        # class bodies, etc.). Indented lines must never be dropped by these heuristics.
        _is_toplevel = ln and ln[0:1] not in (' ', '\t')
        if not _is_toplevel:
            out.append(ln)
            continue

        # Drop: name = ... (Ellipsis)
        m_ell = re.match(r'^([A-Za-z_]\w*)\s*=\s*(\.\.\.|Ellipsis)\s*$', s)
        if m_ell:
            nm = m_ell.group(1)
            if nm in real_assigns or nm in import_bound:
                continue

        # Drop: name = config() when name already has a real constructor RHS
        m_cfg = re.match(r'^([A-Za-z_]\w*)\s*=\s*config\(\)\s*$', s)
        if m_cfg:
            nm = m_cfg.group(1)
            prior = real_assigns.get(nm, '')
            if _ctor_pat.match(prior) or nm in import_bound:
                continue

        # Drop: bare config['key'] expression statements (module-level stray subscript)
        if re.match(r"^config\[", s) and '=' not in s:
            continue

        # Drop: bare call() (any case) when the SAME call expression already appears
        # as the RHS of a real module-level assignment. Also catches bare uppercase
        # ClassName() when the class is in scope. These are phantom walker outputs.
        m_bare_call = re.match(r'^[A-Za-z_]\w*\([^)]*\)\s*$', s)
        if m_bare_call and '=' not in s:
            call_text = s.strip()
            if call_text in real_assigns.values():
                continue
            # Also catch bare uppercase ClassName() without args
            m_uc = re.match(r'^([A-Z]\w*)\(\)\s*$', s)
            if m_uc and (m_uc.group(1) in import_bound
                         or any(v.startswith(m_uc.group(1) + '(') for v in real_assigns.values())):
                continue

        # Drop duplicate module-level assignments: name = RHS when the SAME name=RHS
        # was already emitted above (Nuitka module-init walker emits global stores
        # multiple times). Track what we've emitted to avoid dropping the first one.
        m_dup = re.match(r'^([A-Za-z_]\w*)\s*=\s*(.+)$', s)
        if m_dup:
            nm, rhs = m_dup.group(1), m_dup.group(2).strip()
            if (_emitted_assigns.get(nm) == rhs
                    and rhs not in ('None', '0', '""', "''", '...')):
                continue  # duplicate, drop
            _emitted_assigns[nm] = rhs   # first occurrence, track and keep

        out.append(ln)
    return '\n'.join(out)


def _ndl_heal_standard_global_placeholders_v67(text, consts=None):
    """Replace universal module-level Ellipsis placeholders with proven basics.

    Scope is intentionally narrow and non-product-specific:
    - conventional library aliases (`np`, `gw`) become imports;
    - PIL/pyautogui exception aliases are repaired when the module uses them;
    - lock/thread/bool/path placeholders get neutral standard initializers;
    - wrong `from X import Y` lines are repaired only when another imported
      module demonstrably exposes `Y`.

    The pass does not synthesize coordinates, URLs, endpoint dictionaries,
    workflow bodies, UI labels, or application-specific values.
    """
    if not text:
        return text
    import ast as _ast
    try:
        _ast.parse(text)
    except Exception:
        return text

    lines = text.splitlines()
    changed = False
    add_imports = []

    def _has_import(pattern):
        rx = re.compile(pattern)
        return any(rx.match(ln.strip()) for ln in lines)

    def _need_import(line):
        if line not in lines and line not in add_imports:
            add_imports.append(line)

    def _top_ellipsis_name(ln):
        if ln[:1] in (' ', '\t'):
            return None
        m = re.match(r'^([A-Za-z_]\w*)\s*=\s*(?:\.\.\.|Ellipsis)\s*$', ln.strip())
        return m.group(1) if m else None

    def _module_imports():
        mods = set()
        imported = set()
        for ln in lines:
            s = ln.strip()
            m = re.match(r'^import\s+([A-Za-z_]\w*)(?:\s+as\s+([A-Za-z_]\w*))?', s)
            if m:
                mods.add(m.group(1))
                imported.add(m.group(2) or m.group(1))
            m = re.match(r'^from\s+([A-Za-z_][\w.]*)\s+import\s+(.+)$', s)
            if m:
                mods.add(m.group(1).split('.')[0])
                for part in m.group(2).split(','):
                    part = part.strip()
                    if not part:
                        continue
                    if ' as ' in part:
                        imported.add(part.split(' as ', 1)[1].strip())
                    else:
                        imported.add(part.split()[0].strip())
        return mods, imported

    modules, imported_names = _module_imports()

    def _repair_bad_from_import(ln):
        nonlocal changed
        s = ln.strip()
        m = re.match(r'^from\s+([A-Za-z_][\w.]*)\s+import\s+([A-Za-z_]\w*)\s*$', s)
        if not m or ln[:1] in (' ', '\t'):
            return ln
        mod, name = m.group(1), m.group(2)
        if mod != 'colorama' and 'colorama' in modules and name in {
                'Fore', 'Back', 'Style', 'Cursor', 'init', 'deinit',
                'reinit', 'just_fix_windows_console'}:
            changed = True
            return f'from colorama import {name}'
        if mod != 'datetime' and name == 'datetime':
            changed = True
            return 'from datetime import datetime'
        try:
            import importlib as _importlib
            cur = _importlib.import_module(mod)
            if hasattr(cur, name):
                return ln
            for cand in sorted(modules):
                if cand == mod:
                    continue
                try:
                    cm = _importlib.import_module(cand)
                except Exception:
                    continue
                if hasattr(cm, name):
                    changed = True
                    return f'from {cand} import {name}'
            try:
                real = _importlib.import_module(name)
            except Exception:
                return ln
            if hasattr(real, name):
                changed = True
                return f'from {name} import {name}'
        except Exception:
            return ln
        return ln

    repaired = [_repair_bad_from_import(ln) for ln in lines]
    if repaired != lines:
        lines = repaired
        modules, imported_names = _module_imports()

    # Lexical uses in the module after imports are known.
    body_text = '\n'.join(lines)
    used_names = set(re.findall(r'\b[A-Za-z_]\w*\b', body_text))
    assigned_names = {
        m.group(1)
        for ln in lines
        for m in [re.match(r'^([A-Za-z_]\w*)\s*=', ln.strip())]
        if m and ln[:1] not in (' ', '\t')
    } | imported_names

    color_attrs = {
        'BLACK', 'RED', 'GREEN', 'YELLOW', 'BLUE', 'MAGENTA', 'CYAN',
        'WHITE', 'RESET', 'RESET_ALL',
    }

    out = []
    for ln in lines:
        name = _top_ellipsis_name(ln)
        if not name:
            out.append(ln)
            continue
        replacement = None
        low = name.lower()

        if name == 'np':
            _need_import('import numpy as np')
            changed = True
            continue
        if name == 'gw':
            _need_import('import pygetwindow as gw')
            changed = True
            continue
        if name in {'win32gui', 'win32api', 'win32con'}:
            _need_import(f'import {name}')
            changed = True
            continue
        if name == 'pynput_keyboard':
            if 'keyboard' in imported_names or _has_import(r'^from\s+pynput\s+import\s+keyboard\b'):
                replacement = 'pynput_keyboard = keyboard'
            else:
                _need_import('from pynput import keyboard as pynput_keyboard')
                changed = True
                continue
        elif name in {'ImageGrab', 'ImageOps', 'ImageEnhance', 'ImageFilter'}:
            _need_import(f'from PIL import {name}')
            changed = True
            continue
        elif name == 'ImageNotFoundException' and ('pyautogui' in modules or 'pyautogui' in imported_names):
            replacement = "ImageNotFoundException = getattr(pyautogui, 'ImageNotFoundException', Exception)"
        elif low.endswith('_lock') or low == 'running_lock':
            _need_import('import threading')
            replacement = f'{name} = threading.Lock()'
        elif low.endswith('_thread') or low in {'main_thread', 'set_thread'}:
            replacement = f'{name} = None'
        elif (low.startswith('is_') or low.startswith('has_') or low == 'debug'
              or low.endswith('_enabled') or low.endswith('_flag')
              or low.endswith('_durum')):
            replacement = f'{name} = False'
        elif low in {'base_path', 'base_dir'} or low.endswith('_base_path') or low.endswith('_base_dir'):
            _need_import('import os')
            replacement = f'{name} = os.path.dirname(os.path.abspath(__file__))'
        elif low.endswith('_dir') or low.endswith('_path'):
            _need_import('import os')
            base = 'BASE_DIR' if 'BASE_DIR' in assigned_names or 'BASE_DIR' in used_names else (
                'BASE_PATH' if 'BASE_PATH' in assigned_names or 'BASE_PATH' in used_names else None)
            if base and base != name:
                leaf = re.sub(r'_(DIR|PATH)$', '', name, flags=re.I).lower()
                replacement = f"{name} = os.path.join({base}, {leaf!r})"
            else:
                replacement = f'{name} = os.getcwd()'
        elif low.endswith('_dirs') or low.startswith('possible_'):
            replacement = f'{name} = []'

        if replacement is None:
            out.append(ln)
        else:
            out.append(replacement)
            changed = True

    if not changed and not add_imports:
        return text

    # Add common color aliases only when colorama/Fore is already evidenced.
    alias_lines = []
    post = '\n'.join(add_imports + out)
    if ('Fore' in used_names or any(c in used_names for c in color_attrs)) and (
            'colorama' in modules or 'Fore' in imported_names or 'from colorama import' in post):
        if 'Fore' not in imported_names and 'from colorama import Fore' not in post:
            _need_import('from colorama import Fore')
        for cname in sorted(color_attrs & used_names):
            if cname not in assigned_names and cname not in {'RESET_ALL'}:
                alias_lines.append(f'{cname} = Fore.{cname}')
                assigned_names.add(cname)
                changed = True
        if 'RESET_ALL' in used_names and 'RESET_ALL' not in assigned_names:
            alias_lines.append('RESET_ALL = Fore.RESET')
            changed = True

    # Insert imports after the existing import block/docstring.
    existing = set(out)
    pending = [imp for imp in add_imports if imp not in existing]
    insert_at = 0
    for i, ln in enumerate(out):
        if ln.startswith('import ') or ln.startswith('from '):
            insert_at = i + 1
        elif insert_at and ln.strip():
            break
    if pending:
        out[insert_at:insert_at] = pending
        insert_at += len(pending)
    if alias_lines:
        existing_alias = set(out)
        clean_aliases = [ln for ln in alias_lines if ln not in existing_alias]
        out[insert_at:insert_at] = clean_aliases
    return '\n'.join(out)


def _ndl_drop_symbol_stub_module_v67(text, code_objects=None):
    """Drop modules that are only artifact symbol stubs and have no code body."""
    if not text or code_objects:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False
    if not tree.body:
        return text
    for node in tree.body:
        if isinstance(node, (_ast.Import, _ast.ImportFrom)):
            return text
        if isinstance(node, _ast.Assign):
            # Keep real metadata/exports.
            return text
        if isinstance(node, _ast.FunctionDef):
            if not (len(node.body) == 1 and isinstance(node.body[0], _ast.Pass)):
                return text
            continue
        if isinstance(node, _ast.ClassDef):
            real = [s for s in node.body if not (
                isinstance(s, _ast.Expr)
                and isinstance(getattr(s, 'value', None), _ast.Constant)
                and isinstance(s.value.value, str))]
            if not (len(real) == 1 and isinstance(real[0], _ast.Pass)):
                return text
            continue
        return text
    return ''


def _ndl_strip_empty_try_else_finally_text(text):
    """Comment-safe removal of placeholder ``else: ...`` and ``finally: ...``
    from try blocks in module source text.

    Works on raw text (no ast.unparse), so inline comments are preserved.
    Removes exactly:
      ``<indent>else:\\n<indent>    ...\\n``  (else body = single Ellipsis)
      ``<indent>finally:\\n<indent>    ...\\n``  (finally body = single Ellipsis)
    that appear after a ``try:`` or ``except ...`` clause (context check is
    conservative: only remove when the else/finally immediately follows an
    exception-handler block).
    """
    if not text or ('else' not in text and 'finally' not in text):
        return text
    # Match: NEWLINE + indent + "else:" or "finally:" + NEWLINE + same_indent + 4spaces + "..."
    # The (?m) multiline flag makes ^ match start of each line
    #
    # Pattern: ^\s{N}(else|finally):\n\s{N}    \.\.\.\s*\n
    # Repeat until stable (handles stacked else+finally)
    prev = None
    while prev != text:
        prev = text
        # [ \t]* (zero-or-more) so the pattern also matches 0-indent walker output
        text = re.sub(
            r'\n([ \t]*)(else|finally):\n\1    \.\.\.\s*\n',
            '\n',
            text)
        # Also handle trailing (end of file) case
        text = re.sub(
            r'\n([ \t]*)(else|finally):\n\1    \.\.\.\s*$',
            '',
            text)
    return text


def _ndl_prune_spurious_stdlib_imports(text, consts, protected=None):
    """Remove ``import X`` lines where X is a stdlib-module name that only appears
    as a STRING VALUE in the body (e.g. ``{'http': ..., 'https': ...}``), never
    as a bare identifier (function call, attribute, or subscript target).

    Also removes `import X` when another confirmed import provides the same
    functionality and X never appears as a standalone identifier in the body.

    `protected` is a set of top-level module names PROVEN to be real imports
    (e.g. recovered hard imports `import os`/`import ctypes`); these are never
    pruned even when their referencing bodies were not statically recovered.
    """
    protected = protected or set()
    import importlib.util as _ilu
    import sys as _sys

    def _is_stdlib(name):
        top = name.split('.')[0]
        if top in _sys.stdlib_module_names:
            return True
        # For older Python without stdlib_module_names, check the common ones
        _COMMON = {'os', 'sys', 'io', 're', 'json', 'math', 'time', 'datetime',
                   'http', 'html', 'email', 'urllib', 'base64', 'hashlib',
                   'socket', 'ssl', 'threading', 'multiprocessing', 'queue',
                   'logging', 'argparse', 'configparser', 'csv', 'xml',
                   'collections', 'itertools', 'functools', 'contextlib',
                   'abc', 'copy', 'pprint', 'struct', 'codecs', 'typing',
                   'pathlib', 'shutil', 'glob', 'fnmatch', 'tempfile'}
        if top in _COMMON:
            return True
        # V100 FIX: i third-party della whitelist detect_imports ('six',
        # 'requests', ...) arrivano nel pool anche come SEMPLICI STRINGHE del
        # sorgente (es. return "six"). Stessa regola di potatura degli stdlib:
        # se il nome compare SOLO come stringa quoted e mai come identificatore
        # bare nel corpo, l'import e' spurio.
        _THIRDPARTY = {'six', 'requests', 'aiohttp', 'httpx', 'yarl'}
        return top in _THIRDPARTY

    lines = text.splitlines()

    # Collect ALL string constants from the module text (quoted strings)
    # that match short stdlib names appearing in dict contexts
    import ast as _ast
    dict_string_values: set = set()
    try:
        tree = _ast.parse(text)
        for node in _ast.walk(tree):
            if isinstance(node, (_ast.Dict, _ast.keyword)):
                keys = node.keys if isinstance(node, _ast.Dict) else []
                for k in keys:
                    if isinstance(k, _ast.Constant) and isinstance(k.value, str):
                        dict_string_values.add(k.value)
    except Exception:
        # Fallback: extract quoted strings that look like schema keys
        for m in re.finditer(r"['\"]([a-z][a-z_.]*)['\"]", text):
            dict_string_values.add(m.group(1))

    # Also get string constants from the consts pool
    for c in (consts or []):
        if isinstance(c, str):
            dict_string_values.add(c)

    # For each import line, decide whether to keep it
    out = []
    for ln in lines:
        m_imp = re.match(r'^import\s+(\S+)\s*$', ln.strip())
        if m_imp:
            mod = m_imp.group(1)
            top = mod.split('.')[0]
            if top in protected:
                out.append(ln); continue      # proven real import — never prune
            if _is_stdlib(top) and top in dict_string_values:
                # Check if `top` (the module name) is used as a BARE identifier in
                # any non-import, non-comment, non-string line of the body
                bare_use = False
                for body_ln in lines:
                    if body_ln.strip().startswith('#'):
                        continue
                    if re.match(r'^\s*(?:import|from)\s', body_ln):
                        continue
                    # Remove quoted strings before checking
                    stripped_of_strings = re.sub(r'"[^"]*"|\'[^\']*\'', '', body_ln)
                    if re.search(r'\b' + re.escape(top) + r'\s*[\.\[\(]', stripped_of_strings):
                        bare_use = True
                        break
                if not bare_use:
                    continue  # drop spurious stdlib import
        out.append(ln)
    return '\n'.join(out)


def _ndl_heal_spurious_params(text):
    """Remove parameters that are immediately assigned in the function body.
    Pattern: `def f(a, b):` where `b = []` is the first thing in the body
    (not `a`) → `b` is a local, not a param → remove from signature.
    Uses targeted text surgery (line replacement) to preserve blank lines/comments."""
    import ast
    if 'def ' not in text:
        return text
    try:
        tree = ast.parse(text)
    except SyntaxError:
        return text

    def _first_stores(fn_body):
        stores = set()
        for stmt in fn_body:
            if isinstance(stmt, (ast.Assign, ast.AnnAssign)):
                tgts = stmt.targets if isinstance(stmt, ast.Assign) else [stmt.target]
                for t in tgts:
                    if isinstance(t, ast.Name):
                        stores.add(t.id)
            elif isinstance(stmt, ast.If):
                for s in stmt.body:
                    if isinstance(s, (ast.Assign,)):
                        for t in s.targets:
                            if isinstance(t, ast.Name):
                                stores.add(t.id)
                break
            else:
                break
        return stores

    # Collect (lineno, pruned_param_names) for each function that needs fixing
    patches = {}   # 1-based line → set of param names to remove
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        params = node.args.args
        if len(params) <= 1:
            continue
        defaulted = set()
        if node.args.defaults:
            for p in params[-len(node.args.defaults):]:
                defaulted.add(p.arg)
        body_stores = _first_stores(node.body)
        remove = {p.arg for p in params
                  if p.arg in body_stores
                  and p.arg != params[0].arg
                  and p.arg not in defaulted}
        if remove:
            patches[node.lineno] = remove

    if not patches:
        return text

    # Apply surgery: for each def line, remove the spurious params
    lines = text.splitlines(keepends=True)
    out = []
    for i, ln in enumerate(lines):
        lineno = i + 1
        if lineno in patches:
            # Strip the param names from the `def` signature (text-level)
            remove = patches[lineno]
            # Match `def name(params...) -> ret:` or `def name(params...):`
            m = re.match(r'^(\s*(?:async\s+)?def\s+\w+\s*\()(.*)(\)\s*(?:->[^:]+)?:\s*)$',
                         ln.rstrip('\n\r'))
            if m:
                prefix, args_str, suffix = m.group(1), m.group(2), m.group(3)
                # Split on commas (naïve but sufficient for simple params)
                args = [a.strip() for a in args_str.split(',')]
                # Each arg may have annotation: `name: type = default`
                kept = []
                for a in args:
                    param_name = re.match(r'\s*(\w+)', a)
                    if param_name and param_name.group(1) in remove:
                        continue
                    kept.append(a)
                newln = prefix + ', '.join(kept) + suffix + ln[len(ln.rstrip('\n\r')):]
                out.append(newln)
                continue
        out.append(ln)
    return ''.join(out)


# Recovery contract (Nuitka-aligned, any binary):
#   1) Module imports/globals ONLY from module-init disasm
#      (__import__ / IMPORT_NAME_FROM_MODULE / UPDATE_STRING_DICT0).
#   2) Function bodies ONLY from run_structured / flat register simulation.
#   3) When native recovery is degenerate, emit faithful match/if skeletons
#      with ##RECOVERED## trace comments — never fabricate executable logic
#      from const-pool name correlation or qualname heuristics.


# Generic temporaries often invented as match subjects by collapsed-arm recovery.
# Domain words (wallet/balance/addr/…) are intentionally NOT listed — those are
# real parameter names in many apps and must be judged structurally instead.
_ARM_LOCAL_SUBJECTS = frozenset({
    'result', 'data', 'item', 'obj', 'inst', 'value', 'ret', 'tmp',
    'out', 'val', 'v', 'x', 'y', 'z', 't0', 't1', 't2',
})


def _ndl_is_arm_local_subject(name):
    """Names that look like arm temporaries, never a real match discriminant.

    Structural only: short synthetic temps / numbered locals. Application-domain
    identifiers (wallet, balance, address, …) are NOT classified here — callers
    must use assignment-before-match / param-eligibility checks instead.
    """
    if not name:
        return False
    if name in _ARM_LOCAL_SUBJECTS:
        return True
    low = name.lower()
    # Numbered temps: t0, tmp1, _v2, result3
    if re.fullmatch(r'(t|tmp|val|ret|v|r|x)[_-]?\d+', low):
        return True
    return False


def _ndl_body_match_subject_invalid(body, vn, argcount=None):
    """True when `match <local>` uses an arm-local name, not a function param."""
    if not body:
        return False
    elig = set(_ndl_elig_dispatch_params(vn, argcount=argcount))
    for ln in body:
        m = re.match(r'^\s*match\s+(\w+)\s*:', ln)
        if not m:
            continue
        subj = m.group(1)
        if _ndl_is_arm_local_subject(subj):
            return True
        # A subject ASSIGNED in the body before the match (`modalita = …; match
        # modalita:`) is a genuine local discriminant — valid Python, not a
        # fabricated arm-local — so it is NOT invalid even when it is not a
        # function parameter. Only an unassigned non-param subject is suspect.
        _assigned = any(re.match(r'^\s*%s\s*=[^=]' % re.escape(subj), l)
                        for l in body)
        if not _assigned and elig and subj not in elig:
            return True
    return False


def _ndl_structured_body_degenerate(body, vn=None, consts=None, argcount=None):
    """True when a structured body is clearly wrong (reject → stub/native retry).

    In ``complete_mode`` we are less aggressive: prefer keeping a partially
    recovered native body over collapsing it to a stub. Only hard failures
    (empty / invalid match subject / ``_ndl_bad_body``) still reject.
    """
    if not body:
        return True
    if _ndl_body_match_subject_invalid(body, vn, argcount=argcount):
        return True
    if _ndl_body_has_phantom_subject_reassigns(body):
        return True
    _complete = bool(_ndl_live_opt('complete_mode'))
    # Docstring+name packed call shape is NEVER valid Python — reject regardless
    # of body size (setupUi packing hundreds of tokens must not escape).
    # A botched-pool-call signature condemns a SMALL stub (a mis-synthesised
    # match/dispatch body whose pool-string args ARE its whole content). It must
    # NOT condemn a large, structurally-rich recovered body: legit setter calls
    # like `widget.setObjectName('centralwidget')` pass a real string that merely
    # coincides with an attribute identifier in the pool. Gate on body size so a
    # 100-statement UI builder is kept instead of collapsed to a comment trace.
    # Exception: bare sibling-method packing (setWindowTitle(resize, setup_ui))
    # is always wrong — _ndl_body_has_botched_pool_calls now detects that and we
    # still size-gate only the quoted-pool-collision case via the methodish count.
    _body_real = _ndl_body_real_stmt_count(body)
    if _complete and _body_real >= 1:
        return False
    if _body_real >= 2:
        return False
    text = '\n'.join(body or [])
    if re.search(r'^\s*(pass|\.\.\.)\s*$', text, re.M):
        _real = [l for l in (body or [])
                 if l.strip() and l.strip() not in ('pass', '...')
                 and not l.strip().startswith('#')
                 and '##RECOVERED##' not in l
                 and '##RECON##' not in l]
        if not _real:
            return True
    return _body_real < 1


def _ndl_parse_trace_arms_raw(trace_seq):
    """Split a faithful body trace into per-arm RAW slices, preserving the
    `<if is not None>/else:/print/<literal>` structure (unlike
    _ndl_parse_trace_arms which flattens to a token list).

    Returns a list of dicts, one per dispatch arm, in source order:
        {'lit': "'bitcoin'", 'lines': [<raw trace lines under this arm>]}
    An arm boundary is a `<if cmp 'X'>:` / `<elif cmp 'X'>:` marker carrying a
    quoted string operand AT THE TOP (dispatch) indentation. Universal: nothing
    app/coin specific."""
    arms, cur, top_indent = [], None, None
    for ln in trace_seq or []:
        m = _TRACE_BRANCH_RE.match(ln.rstrip())
        lit = None
        indent = len(ln) - len(ln.lstrip())
        if m:
            inner = m.group(2).strip()
            if inner.startswith('cmp '):
                inner = inner[4:].strip()
            is_str = (len(inner) >= 2 and inner[0] in "'\"" and inner[-1] == inner[0])
            if is_str and (top_indent is None or indent == top_indent):
                top_indent = indent
                lit = inner
        if lit is not None:
            cur = {'lit': lit, 'lines': []}
            arms.append(cur)
            continue
        if cur is not None:
            cur['lines'].append(ln)
    return arms


def _ndl_arm_callable_tokens(arm_lines):
    """Identifier tokens in an arm that look like a called name (not markers)."""
    skip = {'print', 'None', 'else', 'for', 'if', 'elif', 'return', 'pass',
            'True', 'False', 'is', 'not', 'in'}
    out = []
    for ln in arm_lines:
        toks = _ndl_trace_line_tokens(ln)
        if not toks:
            continue
        for t in toks:
            if re.fullmatch(r'[A-Za-z_]\w*', t) and t not in skip:
                out.append(t)
    return out


def _ndl_arm_print_literal(arm_lines, label_lits):
    """Extract a quoted string literal carried in an arm (the print message),
    excluding the dispatch case labels themselves. Returns the inner text."""
    for ln in arm_lines:
        for m in re.finditer(r"'([^']*)'|\"([^\"]*)\"", ln):
            s = m.group(1) if m.group(1) is not None else m.group(2)
            if s and s not in label_lits:
                return s
    return None


def _ndl_recover_else_sentinel(body, consts, print_literal=None):
    """Opportunistically recover a small-int failure sentinel WITHOUT fabricating.

    Sources (priority order):
      1. a ``return <small-neg-int>`` already materialised in *this* body, or
      2. exactly one small negative int in the module const pool, or
      3. a negative return already in body that also appears in consts.

    ``print_literal`` is accepted for API compatibility but is never used to
    invent a sentinel from message wording (that was sample-specific).
    Returns the int, or None when nothing is recoverable.
    """
    try:
        _found = []
        for ln in body or []:
            m = re.match(r'^\s*return\s+(-?\d+)\s*$', ln)
            if m:
                v = int(m.group(1))
                if -16 <= v < 0:
                    _found.append(v)
        if _found:
            # Return the most common (or first) negative sentinel already in body
            from collections import Counter
            return Counter(_found).most_common(1)[0][0]
        # Only a negative int that actually appears in THIS module's const pool
        # is admissible — never invent -1 from failure-message wording (that was
        # a sample-specific crypto-balance heuristic).
        _neg = [c for c in (consts or [])
                if isinstance(c, int) and not isinstance(c, bool) and -16 <= c < 0]
        if len(_neg) == 1:
            return _neg[0]
        # Multiple candidates: only if body already uses one of them elsewhere.
        if _neg and _found:
            for v in _found:
                if v in _neg:
                    return v
    except Exception:
        pass
    return None


def _ndl_fill_match_arm_bodies(body, trace_seq, vn, consts, argcount=None):
    """FAIL-SAFE, UNIVERSAL healer for collapsed string-dispatch match arms.

    The native DAG materialises the `is not None` then-return for the FIRST
    isomorphic arm only (optimizer slot-reuse), so arms 2..N collapse to a bare
    `pass` / partial return / a mis-rendered `for v in CALL(arg): pass`. Using
    the FAITHFUL per-arm trace (which preserves `<if is not None>/else:/print/
    <literal>` for every arm) plus the exact co_varnames, rewrite each arm to:

        case 'K':
            <t0>, <val_K> = <fetch_K>(<arg>)
            if <val_K> is not None:
                return <val_K>
            else:
                print('<msg>')          # msg from the trace
                return <sentinel>       # only if recoverable, else honest comment

    Everything is derived from the trace, co_varnames and the match labels in
    `body`; nothing app/coin/function specific is hardcoded. On ANY exception or
    if the rewritten body fails to re-parse, the ORIGINAL body is returned
    unchanged: it is impossible for this healer to make a module worse-formed."""
    import ast
    if not body or not trace_seq or not vn:
        return body
    try:
        src = '\n'.join(body)
        try:
            tree = ast.parse(src)
            wrapped = False
        except SyntaxError:
            import textwrap
            tree = ast.parse('def _ndl_w():\n' + textwrap.indent(src, '    '))
            wrapped = True
        container = tree.body[0].body if wrapped else tree.body
        match_node = None
        for st in container:
            if isinstance(st, ast.Match):
                match_node = st
                break
        if match_node is None or not isinstance(match_node.subject, ast.Name):
            return body

        def _arm_call_info(stmts):
            ss = list(stmts)
            if ss and isinstance(ss[0], ast.Assign) and isinstance(ss[0].value, ast.Call):
                if (len(ss[0].targets) == 1
                        and isinstance(ss[0].targets[0], (ast.Tuple, ast.List))):
                    elts = ss[0].targets[0].elts
                    if elts and isinstance(elts[0], ast.Name):
                        if all(isinstance(s, (ast.Pass, ast.Return)) for s in ss[1:]):
                            return ss[0].value, elts[0].id
            if len(ss) == 1 and isinstance(ss[0], ast.For) and isinstance(ss[0].iter, ast.Call):
                if (not ss[0].orelse) and all(isinstance(s, ast.Pass) for s in ss[0].body):
                    return ss[0].iter, None
            return None, None

        case_infos = []
        shared_name = None
        for c in match_node.cases:
            if not (isinstance(c.pattern, ast.MatchValue)
                    and isinstance(c.pattern.value, ast.Constant)
                    and isinstance(c.pattern.value.value, str)):
                return body
            call_node, t0 = _arm_call_info(c.body)
            if call_node is None:
                return body
            if shared_name is None and t0 is not None:
                shared_name = t0
            case_infos.append((c, c.pattern.value.value, call_node))

        labels = [lbl for _, lbl, _ in case_infos]
        if len(set(labels)) < 3:
            return body

        if shared_name is None and argcount is not None and 0 <= argcount < len(vn):
            shared_name = vn[argcount]
        if not shared_name or shared_name not in vn:
            return body
        base = vn.index(shared_name)
        val_locals = vn[base + 1: base + 1 + len(case_infos)]
        if len(val_locals) != len(case_infos):
            return body

        arms_raw = _ndl_parse_trace_arms_raw(trace_seq)
        by_lit = {}
        for a in arms_raw:
            by_lit.setdefault(_ndl_norm_arm_lit(a['lit']), a)
        label_set = set(labels)
        print_literal = None
        for lbl in labels:
            a = by_lit.get(lbl)
            if a is None:
                return body
            lines = a['lines']
            if not _ndl_arm_callable_tokens(lines):
                return body
            if not any('is not None' in ln for ln in lines):
                return body
            if not any('print' in (_ndl_trace_line_tokens(ln) or []) for ln in lines):
                return body
            if print_literal is None:
                print_literal = _ndl_arm_print_literal(lines, label_set)
        if not print_literal:
            return body

        sentinel = _ndl_recover_else_sentinel(body, consts,
                                               print_literal=print_literal)

        for idx, (case_node, lbl, call_node) in enumerate(case_infos):
            val = val_locals[idx]
            assign = ast.Assign(
                targets=[ast.Tuple(
                    elts=[ast.Name(id=shared_name, ctx=ast.Store()),
                          ast.Name(id=val, ctx=ast.Store())],
                    ctx=ast.Store())],
                value=call_node)
            then = [ast.Return(value=ast.Name(id=val, ctx=ast.Load()))]
            els = [ast.Expr(value=ast.Call(
                func=ast.Name(id='print', ctx=ast.Load()),
                args=[ast.Constant(value=print_literal)], keywords=[]))]
            if sentinel is not None:
                els.append(ast.Return(value=ast.Constant(value=sentinel)))
            else:
                els.append(ast.Expr(value=ast.Constant(
                    value='##RECOVERED## else-branch returns sentinel '
                          '(value not recoverable from trace/consts)')))
            ifn = ast.If(
                test=ast.Compare(
                    left=ast.Name(id=val, ctx=ast.Load()),
                    ops=[ast.IsNot()],
                    comparators=[ast.Constant(value=None)]),
                body=then, orelse=els)
            case_node.body = [assign, ifn]

        ast.fix_missing_locations(tree)
        if wrapped:
            new_body = []
            for st in tree.body[0].body:
                new_body.extend(ast.unparse(st).splitlines())
        else:
            new_body = ast.unparse(tree).splitlines()
        ast.parse('\n'.join(new_body))            # PARSEABILITY GUARANTEE
        return new_body
    except Exception:
        return body


def _ndl_native_or_stub_body(body, trace_seq, vn, consts, qualname=None, argcount=None):
    """Accept native body after artifact healers, else faithful trace stub only."""
    if body:
        body = _ndl_fold_match_cases(body)
        body = _ndl_heal_misresolved_ctors(body, vn, consts)
        body = _ndl_heal_botched_call_args(body, vn, consts)
        body = _ndl_fill_match_arm_bodies(body, trace_seq, vn, consts, argcount=argcount)
        if not _ndl_structured_body_degenerate(body, vn, consts, argcount=argcount):
            return body
    if trace_seq:
        stub = _ndl_render_match_stub(trace_seq, vn, consts=consts, qualname=qualname,
                                      argcount=argcount)
        if stub:
            return stub
        sk = _ndl_render_trace_skeleton(trace_seq, vn)
        if sk and not _ndl_bad_body(sk):
            return sk
    return None


def _ndl_factory_methods_from_pool(consts):
    """Deprecated — factory returns come from native disasm only."""
    return None, None


def _ndl_inst_var_for_ctor(args, consts=None):
    """Deprecated."""
    return 'inst'


def _ndl_guess_relative_import_for_symbol(sym, module_name, known_modules):
    """Deprecated — imports come only from IMPORT_NAME_FROM_MODULE walk."""
    return None


def _ndl_infer_missing_imports_module(text, module_name, known_modules, consts,
                                      import_lines=None):
    """Add imports for symbols used in recovered source when qualnames exist in pool."""
    if not text:
        return text
    lines = _ndl_import_lines_from_source(text)
    extra = _ndl_infer_symbol_imports(text, list(import_lines or []) + lines,
                                        module_name, consts, known_modules)
    have = set(_ndl_import_lines_from_source(text))
    for ln in extra:
        if ln not in have and ln not in (import_lines or []):
            text = ln + '\n' + text
    return text


def _ndl_append_thin_shim_blocks(text, module_name, disasm, fp, consts, mcb,
                                  classifier, known_modules, code_objects=None):
    """Append disasm-proven import switch + __main__ demo for thin shim modules."""
    if not text or not module_name or disasm is None or fp is None:
        return text
    extras = _ndl_infer_thin_module_imports(
        module_name, consts, known_modules, code_objects=code_objects)
    if not extras:
        return text
    lines = text.splitlines()
    if any(ln.startswith(('class ', 'def ', 'async def ')) for ln in lines):
        return text
    _m = re.match(r'from \.(\w+) import (\w+)(?: as (\w+))?', extras[0])
    if not _m:
        return text
    _dm = _ndl_recover_dunder_main_import_switch(
        disasm, fp, consts, mcb, classifier,
        _m.group(1), _m.group(2), alias=_m.group(3))
    if _dm:
        extras = _dm
    _main_blk = _ndl_recover_main_entry_block(
        disasm, fp, consts, mcb, classifier,
        entry_cls=_m.group(2), alias=_m.group(3))
    for xl in extras:
        if xl not in lines:
            lines.append(xl)
    if _main_blk:
        for xl in _main_blk:
            if xl not in lines:
                lines.append(xl)
    try:
        import ast as _a
        _a.parse('\n'.join(lines))
        return '\n'.join(lines) + ('\n' if lines else '')
    except Exception:
        return text


def _ndl_body_has_phantom_subject_reassigns(body):
    """True when match arms mostly reassign the subject via `subj = self.x(subj, …)`."""
    if not body:
        return False
    pat = re.compile(r'^\s*(\w+)\s*=\s*self\.\w+\(\1,\s*\w+\)\s*$')
    garbled = sum(1 for ln in body if pat.match(ln))
    exec_ln = sum(1 for ln in body if ln.strip() and not re.match(r'^\s*(case |match )', ln))
    return garbled >= 6 or (exec_ln and garbled / exec_ln >= 0.35)


def _ndl_emit_name_main_guards(text, module_name, disasm, fp, consts, mcb,
                               classifier, code_objects=None):
    """Emit the faithful `if __name__ == '__main__': <abs import> else: <rel
    import>` switch for FAT modules (those with classes/defs) — the thin-module
    path bails on any class/def, so 12 of 14 guard-bearing modules never got it.

    UNIVERSAL: gated solely on the disasm-proven detector
    `_ndl_module_init_has_name_main_guard` (both `__name__` and `__main__` const
    loads in module-init). Both import branches bind the SAME class already present
    in the emitted relative import — only the dotted prefix differs — so this is
    faithful, not fabricated. Phase 1: the if-name-main DEMO block (sys.argv,
    instance construction, print) is intentionally NOT emitted here; it is
    recovered from disasm separately to avoid guessing."""
    if not text or disasm is None or fp is None:
        return text
    if 'if __name__' in text:
        return text                          # already present / idempotent
    try:
        if not _ndl_module_init_has_name_main_guard(disasm, fp, consts, mcb):
            return text
    except Exception:
        return text
    lines = text.splitlines()
    # Locate the relative import the guard switches on: `from .<sib> import
    # <cls>[ as <al>]`. Names come from the emitted line, never the const pool.
    rel_idx = sib = cls = al = None
    for i, ln in enumerate(lines):
        m = re.match(r'^from \.(\w+) import (\w+)(?: as (\w+))?\s*$', ln)
        if m:
            rel_idx, sib, cls, al = i, m.group(1), m.group(2), m.group(3)
            break
    if rel_idx is None:
        return text
    try:
        sw = _ndl_recover_dunder_main_import_switch(
            disasm, fp, consts, mcb, classifier, sib, cls, alias=al)
    except Exception:
        sw = None
    if not sw:
        return text
    # The switch carries its own leading `import sys`; drop it (plus a now-orphan
    # leading blank) when sys is already imported, to avoid a duplicate.
    if any(re.match(r'^import sys\s*$', l) for l in lines):
        sw = [l for l in sw if not re.match(r'^import sys\s*$', l)]
        while sw and sw[0] == '':
            sw.pop(0)
    new_lines = lines[:rel_idx] + sw + lines[rel_idx + 1:]
    try:
        import ast as _a
        _a.parse('\n'.join(new_lines))
    except Exception:
        return text
    return '\n'.join(new_lines) + '\n'


def _ndl_group_imports_v25(text):
    """V25/V36: Group module imports (stdlib / third-party / local) but
    PRESERVE original source order within each group.

    V36 change: the V25 implementation sorted imports ALPHABETICALLY within
    each bucket, which destroyed the original source order (e.g. `from
    PySide6 import QtCore` before `from PySide6.QtCore import Qt` became
    alphabetical and lost the logical grouping). V36 keeps the original
    source order, only grouping by bucket. This matches the original
    author's intent far more closely.

    Leaves non-import lines (and the docstring) untouched.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    _STDLIB_ROOTS = frozenset({
        'abc','argparse','ast','asyncio','base64','binascii','bisect',
        'calendar','collections','concurrent','configparser','contextlib',
        'copy','copyreg','csv','ctypes','dataclasses','datetime','decimal',
        'difflib','dis','distutils','email','enum','errno','fcntl','fnmatch',
        'functools','gc','getopt','getpass','glob','gzip','hashlib','heapq',
        'hmac','html','http','importlib','inspect','io','ipaddress','itertools',
        'json','keyword','linecache','locale','logging','lzma','marshal','math',
        'mimetypes','multiprocessing','numbers','opcode','operator','os',
        'pathlib','pdb','pickle','platform','pprint','profile','queue','random',
        're','reprlib','secrets','select','selectors','shutil','signal','site',
        'socket','socketserver','ssl','stat','statistics','string','struct',
        'subprocess','sys','sysconfig','tarfile','tempfile','textwrap','threading',
        'time','timeit','traceback','types','typing','unicodedata','unittest',
        'urllib','uuid','venv','warnings','weakref','xml','zipfile',
    })
    _IMP_TYPES = (_ast.Import, _ast.ImportFrom)
    def _root_of(imp_node):
        if isinstance(imp_node, _ast.Import):
            return imp_node.names[0].name.split('.')[0]
        if isinstance(imp_node, _ast.ImportFrom):
            if imp_node.module:
                return imp_node.module.split('.')[0]
            return ''  # relative `from . import X`
        return ''
    def _bucket(imp_node):
        r = _root_of(imp_node)
        if not r or getattr(imp_node, 'level', 0) > 0:
            return 2  # local/relative
        if r in _STDLIB_ROOTS:
            return 0  # stdlib
        return 1  # third-party
    # Walk the top-level body and collect leading imports (preserve order)
    _head = []
    _imports = []
    _rest_start = 0
    for i, node in enumerate(tree.body):
        if isinstance(node, _IMP_TYPES):
            _imports.append(node)
        elif isinstance(node, _ast.Expr) and isinstance(node.value, _ast.Constant) \
                and isinstance(node.value.value, str):
            if not _imports:
                _head.append(node)  # docstring before imports
            else:
                _rest_start = i
                break
        else:
            _rest_start = i
            break
    else:
        _rest_start = len(tree.body)
    if not _imports:
        return text
    # V36: stable partition by bucket ONLY (preserve original order within
    # each bucket). Python's `sorted` is stable, so we sort by bucket key
    # alone and ties keep source order.
    _imports.sort(key=lambda n: _bucket(n))
    tree.body = _head + _imports + tree.body[_rest_start:]
    _ast.fix_missing_locations(tree)
    try:
        return _ast.unparse(tree)
    except Exception:
        return text

def _ndl_qt_binding_from_consts_v58(consts):
    """Return the Qt binding proven by the constant pool, or None.

    V87 step-1: never invent a binding. Older code defaulted to ``PySide6``
    whenever the pool lacked Qt strings, which contaminated non-Qt modules
    into non-Qt modules with ``from PySide6 import QtCore`` and false Signal bases.
    """
    pool = [str(c) for c in (consts or []) if isinstance(c, str)]
    for root in ('PySide6', 'PyQt6', 'PySide2', 'PyQt5'):
        if any(s == root or s.startswith(root + '.') for s in pool):
            return root
    # Secondary proof: bare binding fragments that Nuitka sometimes stores
    # without the package root (e.g. only ``QtCore`` next to ``pyqtSignal``).
    joined = '\n'.join(pool)
    if 'pyqtSignal' in joined or 'PyQt5' in joined or 'PyQt6' in joined:
        if any('PyQt6' in s for s in pool):
            return 'PyQt6'
        return 'PyQt5'
    if 'PySide6' in joined or 'PySide2' in joined:
        if any('PySide2' in s for s in pool) and not any('PySide6' in s for s in pool):
            return 'PySide2'
        return 'PySide6'
    if re.search(r'\b(Signal|Slot|QObject|QWidget|QThread|QApplication)\b', joined):
        # Ambiguous bare Qt names without package root: still not enough to
        # choose a binding, but callers may treat this as "Qt-ish". Prefer None
        # for import synthesis so we never invent PySide6 on pure stdlib apps.
        return None
    return None


def _ndl_module_has_qt_evidence(consts):
    """True only when the module constant pool proves a Qt binding exists."""
    return _ndl_qt_binding_from_consts_v58(consts) is not None


def _ndl_heal_mispaired_stdlib_from_imports_v58(text):
    """Repair obvious constant-order import pair swaps such as
    ``from tempfile import datetime`` -> ``from datetime import datetime``.

    The rewrite is intentionally narrow: it only touches absolute stdlib
    ``from M import N`` lines where importing M succeeds but M does not expose N,
    and N itself is a stdlib module that exposes an attribute named N.
    """
    if not text or 'from ' not in text:
        return text
    try:
        import importlib as _importlib
        import sys as _sys
        stdlib = set(getattr(_sys, 'stdlib_module_names', ()) or ())
    except Exception:
        return text
    if not stdlib:
        return text
    out = []
    changed = False
    pat = re.compile(r'^from\s+([A-Za-z_]\w*)\s+import\s+([A-Za-z_]\w*)\s*$')
    for ln in text.splitlines():
        m = pat.match(ln.strip())
        if not m or ln[:1] in (' ', '\t'):
            out.append(ln)
            continue
        mod, name = m.group(1), m.group(2)
        if mod not in stdlib or name not in stdlib:
            out.append(ln)
            continue
        try:
            cur_mod = _importlib.import_module(mod)
        except Exception:
            out.append(ln)
            continue
        if hasattr(cur_mod, name):
            out.append(ln)
            continue
        try:
            real_mod = _importlib.import_module(name)
        except Exception:
            out.append(ln)
            continue
        if hasattr(real_mod, name):
            out.append('from %s import %s' % (name, name))
            changed = True
        else:
            out.append(ln)
    return '\n'.join(out) if changed else text


def _ndl_heal_imports_v33(text, consts):
    """V33: Fix imports: add missing Qt modules, prevent bad substitutions."""
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    used_modules = set()
    direct_import_names = {'QThreadPool', 'QTimer', 'BeautifulSoup'}
    qt_binding = _ndl_qt_binding_from_consts_v58(consts)
    # V87 step-1: without proven Qt evidence, never synthesise Qt imports.
    # BeautifulSoup/stdlib healing below remains active.
    qt_widgets = {
        'QApplication', 'QMainWindow', 'QWidget', 'QDialog', 'QFrame',
        'QLabel', 'QPushButton', 'QTextEdit', 'QPlainTextEdit', 'QLineEdit',
        'QCheckBox', 'QRadioButton', 'QButtonGroup', 'QVBoxLayout',
        'QHBoxLayout', 'QGridLayout', 'QFormLayout', 'QStackedWidget',
        'QTabWidget', 'QScrollArea', 'QComboBox', 'QSpinBox', 'QDoubleSpinBox',
        'QSlider', 'QListWidget', 'QListWidgetItem', 'QTreeWidget',
        'QTableWidget', 'QTableWidgetItem', 'QMessageBox', 'QFileDialog',
        'QMenu', 'QAction', 'QSystemTrayIcon',
    }
    qt_gui = {
        'QFont', 'QColor', 'QBrush', 'QIcon', 'QPixmap', 'QImage', 'QPainter',
        'QPen', 'QCursor', 'QTextCursor', 'QDesktopServices',
    }
    qt_core = {
        'Qt', 'QTimer', 'QThread', 'QRunnable', 'QThreadPool', 'QObject',
        'Slot', 'QUrl', 'QSize', 'QPoint', 'QRect', 'QEvent',
    }
    qt_direct_by_module = {
        'QtWidgets': set(),
        'QtGui': set(),
        'QtCore': set(),
    }
    stdlib_placeholder_imports = set()
    try:
        import sys as _sys_imp
        stdlib_names = set(getattr(_sys_imp, 'stdlib_module_names', ()) or ())
    except Exception:
        stdlib_names = set()
    try:
        stdlib_names |= set(getattr(StaticalySmartReconstructor, '_COMMON_STDLIB', set()))
    except Exception:
        pass

    def _mark_qt_name(name):
        if name in qt_widgets:
            qt_direct_by_module['QtWidgets'].add(name)
        elif name in qt_gui:
            qt_direct_by_module['QtGui'].add(name)
        elif name in qt_core:
            qt_direct_by_module['QtCore'].add(name)

    for node in _ast.walk(tree):
        if isinstance(node, _ast.Attribute) and isinstance(node.value, _ast.Name):
            used_modules.add(node.value.id)
        elif (isinstance(node, _ast.Name)
              and isinstance(node.ctx, _ast.Load)
              and node.id in direct_import_names):
            used_modules.add(node.id)
            _mark_qt_name(node.id)
        elif (isinstance(node, _ast.Call)
              and isinstance(node.func, _ast.Name)
              and node.func.id == 'Signal'):
            qt_direct_by_module['QtCore'].add('Signal')
        elif isinstance(node, _ast.Name) and isinstance(node.ctx, _ast.Load):
            _mark_qt_name(node.id)
        elif isinstance(node, _ast.ClassDef):
            for base in node.bases:
                if isinstance(base, _ast.Name):
                    _mark_qt_name(base.id)
        elif (isinstance(node, _ast.Assign) and len(node.targets) == 1
              and isinstance(node.targets[0], _ast.Name)
              and isinstance(node.value, _ast.Constant)
              and node.value.value is Ellipsis):
            nm = node.targets[0].id
            _mark_qt_name(nm)
            if nm in stdlib_names:
                stdlib_placeholder_imports.add(nm)
    existing = set()
    imported_bound = set()
    for node in tree.body:
        if isinstance(node, _ast.Import):
            for a in node.names:
                existing.add(a.name.split('.')[0])
                imported_bound.add(a.asname or a.name.split('.')[0])
        elif isinstance(node, _ast.ImportFrom) and node.module:
            existing.add(node.module.split('.')[0])
            for a in node.names:
                existing.add(a.name)
                imported_bound.add(a.asname or a.name)
    new_imports = []
    if qt_binding:
        if 'QtWidgets' in used_modules and 'QtWidgets' not in existing:
            new_imports.append('from %s import QtWidgets' % qt_binding)
        if 'QtGui' in used_modules and 'QtGui' not in existing:
            new_imports.append('from %s import QtGui' % qt_binding)
        if 'QtCore' in used_modules and 'QtCore' not in existing:
            new_imports.append('from %s import QtCore' % qt_binding)
        if 'Qt' in used_modules and 'Qt' not in existing:
            new_imports.append('from %s.QtCore import Qt' % qt_binding)
        if 'QThreadPool' in used_modules and 'QThreadPool' not in existing:
            new_imports.append('from %s.QtCore import QThreadPool' % qt_binding)
        if 'QTimer' in used_modules and 'QTimer' not in existing:
            new_imports.append('from %s.QtCore import QTimer' % qt_binding)
        for mod_name, names in qt_direct_by_module.items():
            need = sorted(n for n in names if n not in existing and n not in imported_bound)
            if need:
                new_imports.append('from %s.%s import %s' % (
                    qt_binding, mod_name, ', '.join(need)))
                imported_bound.update(need)
    if 'BeautifulSoup' in used_modules and 'BeautifulSoup' not in existing:
        new_imports.append('from bs4 import BeautifulSoup')
    for mod in sorted(stdlib_placeholder_imports):
        if mod not in existing and mod not in imported_bound:
            new_imports.append('import %s' % mod)
            imported_bound.add(mod)
    if new_imports:
        insert_idx = 0
        for i, node in enumerate(tree.body):
            if isinstance(node, (_ast.Import, _ast.ImportFrom)):
                insert_idx = i + 1
            elif isinstance(node, _ast.Expr) and isinstance(node.value, _ast.Constant) and isinstance(node.value.value, str):
                if insert_idx == 0:
                    insert_idx = i + 1
                else:
                    break
            elif insert_idx > 0:
                break
        new_nodes = []
        for imp in new_imports:
            try:
                new_nodes.append(_ast.parse(imp).body[0])
            except Exception:
                pass
        tree.body[insert_idx:insert_idx] = new_nodes
        _ast.fix_missing_locations(tree)
    # Drop module-level `Name = ...` placeholders once the name is proven to be
    # an imported binding. This runs here too because final import healing can
    # happen after the generic phantom-assignment pass.
    if imported_bound:
        new_body = []
        for node in tree.body:
            if (isinstance(node, _ast.Assign) and len(node.targets) == 1
                    and isinstance(node.targets[0], _ast.Name)
                    and node.targets[0].id in imported_bound
                    and isinstance(node.value, _ast.Constant)
                    and node.value.value is Ellipsis):
                continue
            new_body.append(node)
        tree.body = new_body
        _ast.fix_missing_locations(tree)
    result = _ast.unparse(tree)
    result = _ndl_heal_mispaired_stdlib_from_imports_v58(result)
    result = result.replace('html.parser.find(', 'BeautifulSoup(')
    # Remove import html.parser if BeautifulSoup is now imported
    result = result.replace('import html.parser\n', '')
    # V34 FIX: ast.unparse regenerates source and can drop `pass` statements
    # that lived inside empty compound blocks (if/for/while with comment-only
    # bodies). Re-insert them so downstream AST healers receive valid Python.
    try:
        result = _ndl_ensure_block_bodies(result)
    except Exception:
        pass
    return result


def _ndl_heal_join_bool_v33(text):
    """V33: Remove broken join(bool) patterns."""
    if not text:
        return text
    import re
    lines = text.split('\n')
    new_lines = []
    for line in lines:
        stripped = line.strip()
        if "join(" in stripped and (">=" in stripped or "<=" in stripped or "==" in stripped or "!=" in stripped):
            continue
        new_lines.append(line)
    return '\n'.join(new_lines)


def _ndl_heal_match_to_ifelif_v33(text):
    """V33: Convert match/case back to if/elif."""
    if not text or 'match ' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    class _C(_ast.NodeTransformer):
        def _arm_real(self, body):
            # An arm is "real" if it carries at least one executable statement
            # that is not just `pass` / `...`. Used to decide whether a match
            # is CLEAN (keep as match) or BOTCHED (convert to if/elif).
            for s in (body or []):
                if isinstance(s, _ast.Pass):
                    continue
                if (isinstance(s, _ast.Expr)
                        and isinstance(getattr(s, 'value', None), _ast.Constant)
                        and s.value.value is Ellipsis):
                    continue
                return True
            return False

        def visit_Match(self, node):
            self.generic_visit(node)
            can = all((isinstance(c.pattern, _ast.MatchValue) and isinstance(c.pattern.value, _ast.Constant)) or (isinstance(c.pattern, _ast.MatchAs) and c.pattern.pattern is None) for c in node.cases)
            if not can:
                return node
            # V58: KEEP clean match statements. _ndl_fold_match_cases now
            # produces CORRECT `match subj: case 'lit': <real body>` and the
            # reference source (ui.py, worker.py) uses match/case -- so
            # converting a clean match back to if/elif destroys text-sim on
            # the heaviest modules. Only convert BOTCHED matches (at least one
            # placeholder/pass-only arm); those if/elif renders more safely.
            if len(node.cases) >= 2 and all(self._arm_real(c.body) for c in node.cases):
                return node
            subject = _ast.unparse(node.subject)
            if_node = None
            cur = None
            default_body = None
            for case in node.cases:
                if isinstance(case.pattern, _ast.MatchAs) and case.pattern.pattern is None:
                    default_body = case.body
                    continue
                val = case.pattern.value
                cond = _ast.Compare(left=_ast.Name(id=subject, ctx=_ast.Load()), ops=[_ast.Eq()], comparators=[val])
                if if_node is None:
                    if_node = _ast.If(test=cond, body=case.body, orelse=[])
                    cur = if_node
                else:
                    ni = _ast.If(test=cond, body=case.body, orelse=[])
                    cur.orelse = [ni]
                    cur = ni
            if default_body and cur:
                cur.orelse = default_body
            return if_node if if_node else node
    tree = _C().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        # V34 FIX: ast.unparse can drop `pass` from empty compound blocks;
        # re-insert so downstream healers parse.
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_standalone_callarg_v33(text):
    """V33: Fix standalone callable that should be an argument."""
    if not text:
        return text
    import re
    lines = text.split('\n')
    new_lines = []
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if i + 1 < len(lines):
            nxt = lines[i + 1].strip()
            if (re.match(r'^[\w.]+\([^)]*\)$', stripped) and re.match(r'^[\w.]+\(\)$', nxt)):
                if any(stripped.startswith(p) for p in ('random.uniform', 'random.randint', 'str(', 'int(', 'float(', 'len(')):
                    indent = lines[i + 1][:len(lines[i + 1]) - len(lines[i + 1].lstrip())]
                    mm = re.match(r'^([\w.]+)\(\)$', nxt)
                    if mm:
                        new_lines.append(f'{indent}{mm.group(1)}({stripped})')
                        i += 2
                        continue
        if re.match(r'^self\.[\w.]+\.isChecked\(\)$', stripped):
            i += 1
            continue
        if re.match(r'^self\.[\w.]+\.value\(\)$', stripped):
            i += 1
            continue
        if '.split(' in stripped and '.isChecked()' in stripped:
            i += 1
            continue
        new_lines.append(line)
        i += 1
    return '\n'.join(new_lines)


def _ndl_heal_chained_zero_arg_calls_v35(text):
    """``obj.text.strip`` → ``obj.text().strip()``; drop ``[self]`` garbage.

    Universal: zero-arg accessors chained without call parens, plus the
    common ``expr[self]`` artifact from a mis-bound subscript.
    Idempotent: never wraps an Attribute that is already a Call target.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    _ZERO = frozenset({
        'text', 'strip', 'rstrip', 'lstrip', 'lower', 'upper', 'title',
        'hexdigest', 'read', 'readline', 'getvalue', 'isoformat',
        'timestamp', 'date', 'time', 'hostname', 'hex', 'bit_length',
        'conjugate', 'as_integer_ratio', 'is_integer', 'hardware_id',
        'currentItem', 'count', 'toPlainText', 'currentText',
        'selectedText', 'toString', 'trimmed',
    })
    changed = False

    def _fix_attr_chain(node, *, as_call_target=False):
        """Rewrite Attribute chain so each _ZERO leaf becomes a Call.

        ``as_call_target=True`` means this node is already ``Call.func`` —
        do NOT wrap it again.
        """
        nonlocal changed
        if isinstance(node, _ast.Subscript):
            if (isinstance(node.slice, _ast.Name) and node.slice.id == 'self'):
                changed = True
                return _fix_attr_chain(node.value, as_call_target=as_call_target)
            node.value = _fix_attr_chain(node.value)
            return node
        if isinstance(node, _ast.Call):
            # Collapse accidental Call(Call(func)) / func()() wrappers first.
            while (isinstance(node, _ast.Call)
                   and not node.args and not node.keywords
                   and isinstance(node.func, _ast.Call)
                   and not node.func.args and not node.func.keywords):
                node = node.func
                changed = True
            # Func is already being called — fix its receiver only.
            if isinstance(node.func, _ast.Attribute):
                node.func.value = _fix_attr_chain(node.func.value)
            else:
                node.func = _fix_attr_chain(node.func)
            node.args = [_fix_attr_chain(a) for a in node.args]
            return node
        if isinstance(node, _ast.Attribute):
            node.value = _fix_attr_chain(node.value)
            if node.attr in _ZERO and not as_call_target:
                changed = True
                return _ast.Call(func=node, args=[], keywords=[])
            return node
        return node

    class _Fix(_ast.NodeTransformer):
        def visit_Return(self, node):
            self.generic_visit(node)
            if node.value is not None:
                node.value = _fix_attr_chain(node.value)
            return node

        def visit_Assign(self, node):
            self.generic_visit(node)
            node.value = _fix_attr_chain(node.value)
            return node

        def visit_Expr(self, node):
            self.generic_visit(node)
            node.value = _fix_attr_chain(node.value)
            return node

        def visit_Call(self, node):
            # Don't generic_visit first (would double-walk); fix in place.
            node.func = _fix_attr_chain(node.func, as_call_target=True)
            node.args = [_fix_attr_chain(a) for a in node.args]
            node.keywords = [
                _ast.keyword(arg=k.arg, value=_fix_attr_chain(k.value))
                for k in node.keywords
            ]
            return node

        def visit_Compare(self, node):
            self.generic_visit(node)
            # Do not wrap compare operands: CHECK_IF_TRUE of `obj.text` is
            # `if obj.text:`, not `if obj.text() != obj.text():`.
            return node

    tree = _Fix().visit(tree)
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ast.unparse(tree)
    except Exception:
        return text


def _ndl_heal_qt_enum_packed_calls_v35(text):
    """``self.setDragDropMode(QtWidgets, QAbstractItemView, DragDropMode, InternalMove, …)``
    → ``self.setDragDropMode(QtWidgets.QAbstractItemView.DragDropMode.InternalMove)``
    (and similarly for setSelectionMode). Universal Qt enum path rebuild.
    """
    if not text or 'DragDropMode' not in text and 'SelectionMode' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False

    def _pack_enum(args, enum_leaf, mode_leaf):
        """Build QtWidgets.QAbstractItemView.<Enum>.<Mode> from bare Name args."""
        names = []
        for a in args:
            if isinstance(a, _ast.Name):
                names.append(a.id)
            elif isinstance(a, _ast.Attribute):
                names.append(a.attr)
        if enum_leaf not in names or mode_leaf not in names:
            return None
        # Prefer QtWidgets.QAbstractItemView.<enum>.<mode>
        root = 'QtWidgets'
        if 'QtWidgets' in names:
            pass
        return _ast.Attribute(
            value=_ast.Attribute(
                value=_ast.Attribute(
                    value=_ast.Name(id=root, ctx=_ast.Load()),
                    attr='QAbstractItemView', ctx=_ast.Load()),
                attr=enum_leaf, ctx=_ast.Load()),
            attr=mode_leaf, ctx=_ast.Load())

    class _Fix(_ast.NodeTransformer):
        def visit_Call(self, node):
            self.generic_visit(node)
            nonlocal changed
            if not isinstance(node.func, _ast.Attribute):
                return node
            if node.func.attr == 'setDragDropMode' and len(node.args) >= 3:
                orig = list(node.args)
                packed = _pack_enum(orig, 'DragDropMode', 'InternalMove')
                if packed is not None:
                    node.args = [packed]
                    changed = True
            elif node.func.attr == 'setSelectionMode' and len(node.args) >= 3:
                packed = _pack_enum(node.args, 'SelectionMode', 'SingleSelection')
                if packed is not None:
                    node.args = [packed]
                    changed = True
            return node

    # Pre-pass: split fused setDragDropMode(..., setSelectionMode, ...) into
    # two calls when both enum families appear in one arglist.
    class _Split(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            nonlocal changed
            new_body = []
            for stmt in node.body:
                if (isinstance(stmt, _ast.Expr)
                        and isinstance(stmt.value, _ast.Call)
                        and isinstance(stmt.value.func, _ast.Attribute)
                        and stmt.value.func.attr == 'setDragDropMode'
                        and len(stmt.value.args) >= 5):
                    args = stmt.value.args
                    names = []
                    for a in args:
                        if isinstance(a, _ast.Name):
                            names.append(a.id)
                    if 'setSelectionMode' in names and 'SelectionMode' in names:
                        dd = _pack_enum(args, 'DragDropMode', 'InternalMove')
                        sm = _pack_enum(args, 'SelectionMode', 'SingleSelection')
                        if dd is not None:
                            new_body.append(_ast.Expr(value=_ast.Call(
                                func=stmt.value.func, args=[dd], keywords=[])))
                            changed = True
                        if sm is not None:
                            sel_func = _ast.Attribute(
                                value=stmt.value.func.value,
                                attr='setSelectionMode', ctx=_ast.Load())
                            new_body.append(_ast.Expr(value=_ast.Call(
                                func=sel_func, args=[sm], keywords=[])))
                            changed = True
                        continue
                new_body.append(stmt)
            node.body = new_body
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

    tree = _Split().visit(tree)
    tree = _Fix().visit(tree)
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ast.unparse(tree)
    except Exception:
        return text


def _ndl_ensure_colorama_init_call_v35(text):
    """Ensure ``init()`` / ``init(autoreset=True)`` follows ``from colorama import init``."""
    if not text or 'from colorama import init' not in text:
        return text
    if re.search(r'(?<![\w.])init\s*\(', text):
        return text
    lines = text.splitlines()
    for i, ln in enumerate(lines):
        if re.match(r'from\s+colorama\s+import\s+init\b', ln.strip()):
            # Prefer bare init() matching REF; autoreset only if evidenced later
            lines.insert(i + 1, 'init()')
            return '\n'.join(lines)
    return text


def _ndl_heal_unbound_class_method_calls(text):
    """Rewrite ``QtWidgets.QFoo.method(...)`` using the latest matching local.

    ATTR/CALL walker holes mint unbound Qt class method calls. Prefer the most
    recent ``name = QtWidgets.QFoo(...)`` assignment whose class leaf matches
    (for layout methods, only ``*Layout`` receivers).  Without a locally proven
    constructor, keep the class-qualified call unchanged: it may be a genuine
    class/static method and a fabricated ``_v`` receiver is never evidence.
    """
    if not text or '.' not in text:
        return text
    _LAYOUT_METHODS = frozenset({
        'addWidget', 'addLayout', 'addStretch', 'addSpacing', 'addItem',
        'addRow', 'insertWidget', 'insertLayout', 'insertRow', 'setSpacing',
        'setContentsMargins', 'setAlignment',
    })
    _ctor = re.compile(
        r'^(\s*)([A-Za-z_]\w*)\s*=\s*'
        r'(?:QtWidgets|QtGui|QtCore)\.(Q[A-Z]\w*)\s*\(')
    _call = re.compile(
        r'^(\s*)(?:QtWidgets|QtGui|QtCore)\.(Q[A-Z]\w*)\.'
        r'([a-z_][A-Za-z0-9_]*)\s*\((.*)\)\s*$')
    _call_any = re.compile(
        r'\b(?:QtWidgets|QtGui|QtCore)\.(Q[A-Z]\w*)\.'
        r'([a-z_][A-Za-z0-9_]*)\s*\(')

    def _pick(stacks, il, cls, meth):
        want_layout = meth in _LAYOUT_METHODS or 'Layout' in cls
        # Exact class match first
        for depth in range(il, -1, -1):
            for c, n in reversed(stacks.get(depth, [])):
                if c == cls:
                    if want_layout and 'Layout' not in c:
                        continue
                    return n
        # Same-family layout fallback
        if want_layout:
            for depth in range(il, -1, -1):
                for c, n in reversed(stacks.get(depth, [])):
                    if 'Layout' in c:
                        return n
        return None

    lines = text.splitlines(True)
    stacks = {}
    out = []
    for ln in lines:
        raw = ln.rstrip('\r\n')
        m = _ctor.match(raw)
        if m:
            ind, name, cls = m.group(1), m.group(2), m.group(3)
            il = len(ind.replace('\t', '    '))
            stacks.setdefault(il, []).append((cls, name))
            for k in list(stacks):
                if k > il:
                    stacks.pop(k, None)
            out.append(ln)
            continue
        m = _call.match(raw)
        if m:
            ind, cls, meth, args = m.group(1), m.group(2), m.group(3), m.group(4)
            il = len(ind.replace('\t', '    '))
            recv = _pick(stacks, il, cls, meth)
            if recv is None:
                out.append(ln)
                continue
            ending = '\r\n' if ln.endswith('\r\n') else ('\n' if ln.endswith('\n') else '')
            out.append('%s%s.%s(%s)%s' % (ind, recv, meth, args, ending))
            continue
        if _call_any.search(ln):
            def _sub(mm, _il=0):
                # approximate indent from line
                ind = ln[:len(ln) - len(ln.lstrip())]
                il2 = len(ind.replace('\t', '    '))
                recv = _pick(stacks, il2, mm.group(1), mm.group(2))
                if recv is None:
                    return mm.group(0)
                return '%s.%s(' % (recv, mm.group(2))
            out.append(_call_any.sub(_sub, ln))
            continue
        out.append(ln)
    return ''.join(out)


def _ndl_heal_bare_qt_ctors_v33(text):
    """Wrap bare ``QtWidgets.QLabel`` / ``QtCore.QRect`` attribute loads used as
    callables into ``QtWidgets.QLabel()`` / ``QtCore.QRect()``.

    Universal: when the native walker recovered the constructor type but lost
    the CALL (arity/register bind failure), the expression is left as a bare
    Attribute. Zero-arg Call is honest incomplete recovery — never invents the
    original constructor arguments.
    """
    if not text or 'Qt' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    _ROOTS = frozenset({'QtWidgets', 'QtGui', 'QtCore', 'Qt'})
    changed = False

    def _is_qctor(node):
        if not isinstance(node, _ast.Attribute):
            return False
        # QtWidgets.QLabel / QtCore.QRect / …
        if (isinstance(node.value, _ast.Name)
                and node.value.id in _ROOTS
                and isinstance(node.attr, str)
                and len(node.attr) > 1
                and node.attr[0] == 'Q'
                and node.attr[1].isupper()):
            return True
        # QtWidgets.QAbstractItemView.DragDropMode — leave enums alone
        return False

    class _Fix(_ast.NodeTransformer):
        def visit_Assign(self, node):
            self.generic_visit(node)
            nonlocal changed
            if _is_qctor(node.value):
                node.value = _ast.Call(func=node.value, args=[], keywords=[])
                changed = True
            return node

        def visit_Call(self, node):
            self.generic_visit(node)
            nonlocal changed
            # setGeometry(QtCore.QRect) → setGeometry(QtCore.QRect())
            new_args = []
            for a in node.args:
                if _is_qctor(a):
                    new_args.append(_ast.Call(func=a, args=[], keywords=[]))
                    changed = True
                else:
                    new_args.append(a)
            node.args = new_args
            return node

        def visit_Expr(self, node):
            self.generic_visit(node)
            return node

    tree = _Fix().visit(tree)
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ast.unparse(tree)
    except Exception:
        return text


def _ndl_heal_bare_callable_returns_v33(text):
    """``return QtWidgets.QApplication.quit`` → ``QtWidgets.QApplication.quit()``.

    When a method body collapsed to returning an unbound callable attribute,
    emit the call (void) instead of returning the function object. Universal
    for any Attribute whose leaf looks methodish / quit/exec/close.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    _CALLABLE_LEAVES = frozenset({
        'quit', 'exec', 'exec_', 'close', 'show', 'hide', 'accept', 'reject',
        'start', 'stop', 'emit', 'processEvents', 'clear', 'update',
    })
    changed = False

    class _Fix(_ast.NodeTransformer):
        def visit_Return(self, node):
            self.generic_visit(node)
            nonlocal changed
            v = node.value
            if (isinstance(v, _ast.Attribute)
                    and isinstance(v.attr, str)
                    and (v.attr in _CALLABLE_LEAVES
                         or v.attr.startswith(('set', 'get', 'add', 'show_',
                                               'update_', 'append')))):
                # Replace return X.y with X.y() as a statement — drop return
                changed = True
                return _ast.Expr(value=_ast.Call(
                    func=v, args=[], keywords=[]))
            return node

    tree = _Fix().visit(tree)
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ast.unparse(tree)
    except Exception:
        return text


def _ndl_heal_empty_args_v33(text, consts=None):
    """V33: leave under-recovered calls honest — never invent literals.

    When ``consts`` provides exactly one unambiguous string literal that can
    fill ``self.*.setText()``, use it; otherwise keep an UNCERTAIN marker.
    """
    if not text:
        return text
    import re
    _str_cands = []
    if consts:
        for c in consts:
            if (isinstance(c, str) and 0 < len(c) < 200
                    and '\n' not in c and not c.startswith('__')
                    and not re.fullmatch(r'[A-Za-z_]\w*', c)):
                # Prefer display-like strings over pure identifiers
                _str_cands.append(c)
        # Dedup preserve order
        _seen = set()
        _uniq = []
        for s in _str_cands:
            if s not in _seen:
                _seen.add(s)
                _uniq.append(s)
        _str_cands = _uniq
    lines = text.split('\n')
    new_lines = []
    for line in lines:
        stripped = line.strip()
        # Mark empty-arg calls that still need evidence — do not invent args.
        m_st = re.match(r'^(self\.\w+)\.setText\(\)$', stripped)
        if m_st:
            indent = line[:len(line) - len(line.lstrip())]
            if len(_str_cands) == 1:
                line = f"{indent}{m_st.group(1)}.setText({_str_cands[0]!r})"
            else:
                line = (f"{indent}# UNCERTAIN: setText args not recovered from "
                        f"binary evidence\n{line}")
        elif stripped == 'time.sleep():' or stripped.endswith('= time.sleep()'):
            indent = line[:len(line) - len(line.lstrip())]
            line = (f"{indent}# UNCERTAIN: time.sleep duration not recovered\n"
                    f"{line}")
        elif 'QMessageBox.question()' in stripped or 'QMessageBox.warning()' in stripped:
            indent = line[:len(line) - len(line.lstrip())]
            line = (f"{indent}# UNCERTAIN: QMessageBox args not recovered from "
                    f"constant pool / call site\n{line}")
        new_lines.append(line)
    return '\n'.join(new_lines)


def _ndl_heal_super_init_v33(text):
    """V33/V35: Add super().__init__() to class __init__ methods.

    V35 enhancements:
      - When the body references `parent` but it is not declared in the
        signature, ADD `parent=None` as a trailing positional arg with a
        default. This recovers the standard Qt dialog/widget pattern
        `def __init__(self, resource_manager, parent=None)` that the
        signature recovery missed.
      - When inserting `super().__init__(...)`, pass `parent` if it is
        a declared parameter (covers the common Qt case).
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    def _body_refs_name(node, name):
        for sub in _ast.walk(node):
            if isinstance(sub, _ast.Name) and sub.id == name:
                return True
        return False

    class _S(_ast.NodeTransformer):
        def visit_ClassDef(self, node):
            self.generic_visit(node)
            if not node.bases:
                return node
            for item in node.body:
                if isinstance(item, _ast.FunctionDef) and item.name == '__init__':
                    params = [a.arg for a in item.args.args]
                    # V35: add `parent=None` default when body references
                    # `parent` but it's not in the signature.
                    if 'parent' not in params and _body_refs_name(item, 'parent'):
                        new_arg = _ast.arg(arg='parent', annotation=None)
                        item.args.args.append(new_arg)
                        # Add default None
                        item.args.defaults.append(_ast.Constant(value=None))
                        params.append('parent')
                        _ast.fix_missing_locations(item.args)
                    has_super = any(isinstance(s, _ast.Expr) and isinstance(s.value, _ast.Call) and isinstance(s.value.func, _ast.Attribute) and isinstance(s.value.func.value, _ast.Call) and isinstance(s.value.func.value.func, _ast.Name) and s.value.func.value.func.id == 'super' for s in item.body)
                    if not has_super:
                        if 'parent' in params:
                            sc = _ast.parse('super().__init__(parent)').body[0]
                        else:
                            sc = _ast.parse('super().__init__()').body[0]
                        ia = 0
                        if item.body and isinstance(item.body[0], _ast.Expr) and isinstance(getattr(item.body[0], 'value', None), _ast.Constant) and isinstance(item.body[0].value.value, str):
                            ia = 1
                        item.body.insert(ia, sc)
                    break
            return node
    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        # V34 FIX: ast.unparse can drop `pass` from empty compound blocks;
        # re-insert so downstream healers parse.
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


