def _ndl_heal_qt_parent_ctors_v58(text):
    """Restore `parent=None` in simple Qt subclass constructors when omitted."""
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False
    for cls in [n for n in tree.body if isinstance(n, _ast.ClassDef)]:
        base_txt = ' '.join((_ast.unparse(b) if hasattr(_ast, 'unparse') else '') for b in cls.bases)
        is_qt_widget = any(k in base_txt for k in ('QDialog', 'QListWidget', 'QWidget'))
        if not is_qt_widget:
            continue
        for fn in [n for n in cls.body if isinstance(n, _ast.FunctionDef) and n.name == '__init__']:
            arg_names = [a.arg for a in fn.args.args]
            if 'parent' in arg_names or len(arg_names) < 1:
                continue
            fn.args.args.append(_ast.arg(arg='parent'))
            fn.args.defaults.append(_ast.Constant(value=None))
            for st in fn.body:
                if isinstance(st, _ast.Expr) and isinstance(st.value, _ast.Call):
                    c = st.value
                    try:
                        ctxt = _ast.unparse(c.func)
                    except Exception:
                        ctxt = ''
                    if ctxt == 'super().__init__' and not c.args and not c.keywords:
                        c.args.append(_ast.Name(id='parent', ctx=_ast.Load()))
                        break
            changed = True
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ndl_ensure_block_bodies(_ast.unparse(tree))
    except Exception:
        return text


def _ndl_heal_drop_event_order_v58(text):
    """Reorder a Qt dropEvent body so that `super().dropEvent(event)` runs
    BEFORE any `self.<signal>.emit()` call (Qt requires the base class to
    process the drop before the signal fires).

    V62 universalized: previously this was hardcoded to look for
    `order_changed.emit()` -- a sample-specific signal name. Now it
    auto-discovers any custom Signal attribute defined on the same class
    (e.g. `order_changed = QtCore.Signal()`, `items_reordered = Signal()`,
    `layout_changed = Signal()`, ...) and reorders its emit() call to
    follow the super().dropEvent() call.
    """
    if not text or 'dropEvent' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False
    for cls in [n for n in tree.body if isinstance(n, _ast.ClassDef)]:
        # Auto-discover any Signal attribute defined on this class
        signal_names = set()
        for s in cls.body:
            if isinstance(s, _ast.AnnAssign) and isinstance(s.target, _ast.Name):
                # e.g. order_changed: Signal = ...
                signal_names.add(s.target.id)
            elif isinstance(s, _ast.Assign):
                # e.g. order_changed = QtCore.Signal()
                for t in s.targets:
                    if isinstance(t, _ast.Name):
                        # Heuristic: only collect if RHS looks like a Signal()
                        try:
                            rhs = _ast.unparse(s.value)
                        except Exception:
                            rhs = ''
                        if 'Signal(' in rhs or 'pyqtSignal(' in rhs:
                            signal_names.add(t.id)
        if not signal_names:
            continue
        for fn in [n for n in cls.body if isinstance(n, _ast.FunctionDef) and n.name == 'dropEvent']:
            txt = [_ast.unparse(s) for s in fn.body]
            # Find the first emit of any discovered signal
            emit_i = next(
                (i for i, s in enumerate(txt)
                 if any(f'{sig}.emit' in s for sig in signal_names)),
                None,
            )
            super_i = next((i for i, s in enumerate(txt) if 'super().dropEvent' in s), None)
            if emit_i is not None and super_i is not None and emit_i < super_i:
                emit_stmt = fn.body.pop(emit_i)
                super_i = next((i for i, s in enumerate([_ast.unparse(x) for x in fn.body]) if 'super().dropEvent' in s), None)
                fn.body.insert((super_i if super_i is not None else len(fn.body)) + 1, emit_stmt)
                changed = True
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ndl_ensure_block_bodies(_ast.unparse(tree))
    except Exception:
        return text


def _ndl_url_global_names_v58(text):
    names = set()
    for m in re.finditer(r'^\s*(URL_[A-Z0-9_]+)\s*=', text or '', re.M):
        names.add(m.group(1))
    return names


def _ndl_heal_controller_bodies_v58(text, consts=None, code_objects=None):
    """V58: universal late AST hygiene for mechanically proven repairs.

    This hook must not synthesize product workflows. It only fixes AST-local
    artifacts that already expose their intent: safe integer conversion,
    guarded dynamic UI updates, dict extraction target collisions, orphan
    exception variables, and missing dialog constructors when a matching dialog
    class is present in the same module.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False

    def _txt(node):
        try:
            return _ast.unparse(node)
        except Exception:
            return ''

    def _parse_suite(src):
        try:
            return _ndl_parse_body_v58(src)
        except Exception:
            return []

    def _is_doc(stmt):
        return (isinstance(stmt, _ast.Expr)
                and isinstance(getattr(stmt, 'value', None), _ast.Constant)
                and isinstance(stmt.value.value, str))

    def _name_loads(node):
        return {n.id for n in _ast.walk(node) if isinstance(n, _ast.Name) and isinstance(n.ctx, _ast.Load)}

    def _assigned_names(stmts):
        out = set()
        for st in stmts:
            for n in _ast.walk(st):
                if isinstance(n, _ast.Name) and isinstance(n.ctx, (_ast.Store, _ast.Param)):
                    out.add(n.id)
                elif isinstance(n, _ast.ExceptHandler) and n.name:
                    out.add(n.name)
        return out

    def _return_int_value(stmt):
        return (isinstance(stmt, _ast.Return)
                and isinstance(stmt.value, _ast.Call)
                and isinstance(stmt.value.func, _ast.Name)
                and stmt.value.func.id == 'int'
                and len(stmt.value.args) == 1
                and isinstance(stmt.value.args[0], _ast.Name)
                and stmt.value.args[0].id == 'value')

    class_names = {n.name for n in tree.body if isinstance(n, _ast.ClassDef)}
    imported_dialog_classes = set()
    for n in tree.body:
        if isinstance(n, _ast.ImportFrom):
            for a in n.names:
                nm = a.asname or a.name
                if isinstance(nm, str) and nm.lower().endswith('dialog'):
                    imported_dialog_classes.add(nm)
        elif isinstance(n, _ast.Import):
            for a in n.names:
                nm = (a.asname or a.name).split('.')[-1]
                if nm.lower().endswith('dialog'):
                    imported_dialog_classes.add(nm)
    dialog_classes = {c for c in class_names if c.lower().endswith('dialog')} | imported_dialog_classes
    class_init_args = {}
    for cls in [n for n in tree.body if isinstance(n, _ast.ClassDef)]:
        for item in cls.body:
            if isinstance(item, _ast.FunctionDef) and item.name == '__init__':
                class_init_args[cls.name] = [a.arg for a in item.args.args[1:]]
                break

    def _module_self_attrs():
        attrs = set()
        for node in _ast.walk(tree):
            if (isinstance(node, _ast.Attribute)
                    and isinstance(node.value, _ast.Name)
                    and node.value.id == 'self'):
                attrs.add(node.attr)
        return attrs

    self_attrs = _module_self_attrs()

    def _best_dialog_for(fn_name):
        if not dialog_classes:
            return None
        words = [w for w in re.split(r'[^A-Za-z0-9]+', fn_name.lower()) if w]
        scored = []
        for cls in dialog_classes:
            low = cls.lower()
            score = sum(1 for w in words if w and w != 'dialog' and w in low)
            if score:
                scored.append((score, cls))
        if scored:
            scored.sort(reverse=True)
            return scored[0][1]
        return next(iter(imported_dialog_classes)) if len(imported_dialog_classes) == 1 else None

    def _guard_getattr_settext(body):
        local_changed = False
        out = []
        for stmt in body:
            if isinstance(stmt, (_ast.If, _ast.For, _ast.While, _ast.Try, _ast.With)):
                out.append(stmt)
                continue
            call = getattr(stmt, 'value', None)
            if not (isinstance(stmt, _ast.Expr)
                    and isinstance(call, _ast.Call)
                    and isinstance(call.func, _ast.Attribute)
                    and call.func.attr == 'setText'
                    and isinstance(call.func.value, _ast.Call)
                    and isinstance(call.func.value.func, _ast.Name)
                    and call.func.value.func.id == 'getattr'
                    and len(call.func.value.args) >= 2
                    and isinstance(call.func.value.args[0], _ast.Name)
                    and call.func.value.args[0].id == 'self'
                    and isinstance(call.func.value.args[1], _ast.Name)):
                out.append(stmt)
                continue
            attr_name = call.func.value.args[1].id
            wrapped = _parse_suite(f"""
if hasattr(self, {attr_name}):
    {_txt(stmt)}
""")
            if wrapped:
                out.extend(wrapped)
                local_changed = True
            else:
                out.append(stmt)
        return out, local_changed

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            nonlocal changed
            self.generic_visit(node)
            body_text = _txt(node)

            arg_names = [a.arg for a in getattr(node.args, 'args', [])]
            real = [s for s in node.body if not _is_doc(s)]
            if ('value' in arg_names and 'default' in arg_names
                    and len(real) == 1 and _return_int_value(real[0])
                    and 'except' not in body_text):
                suite = _parse_suite('''
try:
    return int(value)
except (ValueError, TypeError):
    return default
''')
                if suite:
                    doc = node.body[0] if node.body and _is_doc(node.body[0]) else None
                    node.body = ([doc] if doc else []) + suite
                    changed = True
                    return node

            # Retarget `holder = holder.get_*data*()` to `data = ...` when the
            # following statements already use a data mapping.
            for st in node.body:
                if (isinstance(st, _ast.Assign) and len(st.targets) == 1
                        and isinstance(st.targets[0], _ast.Name)
                        and isinstance(st.value, _ast.Call)
                        and isinstance(st.value.func, _ast.Attribute)
                        and isinstance(st.value.func.value, _ast.Name)
                        and st.targets[0].id == st.value.func.value.id
                        and 'data' in st.value.func.attr.lower()):
                    st.targets[0].id = 'data'
                    changed = True

            # Fix `tmp = data['tmp']`/keyword collisions by using the key as the
            # variable or keyword value. This is data-shape driven, not app-name driven.
            extracted_keys = set()
            for st in node.body:
                if (isinstance(st, _ast.Assign) and len(st.targets) == 1
                        and isinstance(st.targets[0], _ast.Name)
                        and isinstance(st.value, _ast.Subscript)
                        and isinstance(st.value.value, _ast.Name)
                        and st.value.value.id == 'data'):
                    key = None
                    sl = st.value.slice
                    if isinstance(sl, _ast.Constant) and isinstance(sl.value, str):
                        key = sl.value
                    if key and re.fullmatch(r'[A-Za-z_]\w*', key):
                        extracted_keys.add(key)
                        if st.targets[0].id != key:
                            st.targets[0].id = key
                            changed = True
            for st in _ast.walk(node):
                if isinstance(st, _ast.Call):
                    for kw in st.keywords:
                        if not kw.arg:
                            continue
                        if isinstance(kw.value, _ast.Name) and kw.value.id not in {kw.arg, 'self'}:
                            if kw.arg in extracted_keys or kw.arg in _assigned_names(node.body):
                                kw.value = _ast.Name(id=kw.arg, ctx=_ast.Load())
                                changed = True
                            elif extracted_keys and 'data' in _name_loads(node):
                                kw.value = _ast.Subscript(
                                    value=_ast.Name(id='data', ctx=_ast.Load()),
                                    slice=_ast.Constant(value=kw.arg),
                                    ctx=_ast.Load())
                                changed = True

            guarded, did_guard = _guard_getattr_settext(node.body)
            if did_guard:
                node.body = guarded
                changed = True

            # Move statements that read an otherwise-undefined exception name
            # into an `except Exception as <name>` block.
            doc = node.body[0] if node.body and _is_doc(node.body[0]) else None
            work = node.body[1:] if doc else node.body
            defined = set(arg_names) | _assigned_names(work) | {'self', 'True', 'False', 'None'}
            loads = set().union(*(_name_loads(s) for s in work)) if work else set()
            exc_name = next((n for n in ('e', 'ex', 'exc', 'err') if n in loads and n not in defined), None)
            if exc_name and not any(isinstance(s, _ast.Try) for s in work):
                try_body = []
                except_body = []
                for st in work:
                    if exc_name in _name_loads(st):
                        except_body.append(st)
                    else:
                        try_body.append(st)
                if except_body:
                    node.body = ([doc] if doc else []) + [_ast.Try(
                        body=try_body or [_ast.Pass()],
                        handlers=[_ast.ExceptHandler(type=_ast.Name(id='Exception', ctx=_ast.Load()),
                                                     name=exc_name,
                                                     body=except_body)],
                        orelse=[], finalbody=[])]
                    changed = True

            # Recover `dialog = ClassDialog(...)` immediately before `dialog.exec()`
            # when a matching dialog class and constructor signature are present.
            work = node.body[1:] if node.body and _is_doc(node.body[0]) else node.body
            def _is_real_dialog_assign(s):
                if not (isinstance(s, _ast.Assign)
                        and any(isinstance(t, _ast.Name) and t.id == 'dialog' for t in s.targets)):
                    return False
                if (isinstance(s.value, _ast.Call)
                        and isinstance(s.value.func, _ast.Attribute)
                        and isinstance(s.value.func.value, _ast.Name)
                        and s.value.func.value.id == 'dialog'
                        and 'data' in s.value.func.attr.lower()):
                    return False
                return True
            has_dialog_assign = any(_is_real_dialog_assign(s) for s in work)
            needs_dialog = any('dialog.exec' in _txt(s) for s in work)
            if needs_dialog and not has_dialog_assign:
                cls_name = _best_dialog_for(node.name)
                if cls_name:
                    args = []
                    init_args = class_init_args.get(cls_name)
                    if init_args is None and cls_name in imported_dialog_classes:
                        init_args = ['parent']
                    for a in (init_args or []):
                        if a == 'parent':
                            if 'centralwidget' in self_attrs:
                                args.append('self.centralwidget.window()')
                            else:
                                args.append('None')
                        elif a in self_attrs:
                            args.append('self.' + a)
                        else:
                            args.append(a)
                    stmt = _ast.parse(f"dialog = {cls_name}({', '.join(args)})").body[0]
                    insert_at = 1 if node.body and _is_doc(node.body[0]) else 0
                    node.body.insert(insert_at, stmt)
                    changed = True
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

    try:
        tree = _S().visit(tree)
        if not changed:
            return text
        _ast.fix_missing_locations(tree)
        out = _ast.unparse(tree)
        return _ndl_ensure_block_bodies(out)
    except Exception:
        return text


def _ndl_heal_controller_workflows_v59(text, consts=None, code_objects=None):
    """Compatibility stub for removed product-shaped workflow synthesis."""
    return text



def _ndl_heal_data_extraction_text_v58(text):
    """Fix target collisions around `mapping['name']` extractions generically."""
    if not text or "['" not in text and '["' not in text:
        return text
    def _assign_repl(m):
        ind, target, quote, key = m.group(1), m.group(2), m.group(3), m.group(4)
        if not re.fullmatch(r'[A-Za-z_]\w*', key):
            return m.group(0)
        return f"{ind}{key} = data[{quote}{key}{quote}]"
    text = re.sub(r"(?m)^(\s*)([A-Za-z_]\w*)\s*=\s*data\[(['\"])([A-Za-z_]\w*)\3\]", _assign_repl, text)
    text = re.sub(r"(?m)^(\s*)([A-Za-z_]\w*)\s*=\s*([A-Za-z_]\w*)\.([A-Za-z_]\w*data\w*)\(\)",
                  lambda m: f"{m.group(1)}data = {m.group(3)}.{m.group(4)}()" if m.group(2) == m.group(3) else m.group(0),
                  text)
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False
    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            nonlocal changed
            self.generic_visit(node)
            data_keys = set()
            assigned = set()
            for st in _ast.walk(node):
                if isinstance(st, _ast.Assign):
                    for t in st.targets:
                        if isinstance(t, _ast.Name):
                            assigned.add(t.id)
                    if (len(st.targets) == 1 and isinstance(st.targets[0], _ast.Name)
                            and isinstance(st.value, _ast.Subscript)
                            and isinstance(st.value.value, _ast.Name)
                            and st.value.value.id == 'data'):
                        sl = st.value.slice
                        if isinstance(sl, _ast.Constant) and isinstance(sl.value, str) and re.fullmatch(r'[A-Za-z_]\w*', sl.value):
                            data_keys.add(sl.value)
            if not data_keys:
                return node
            for call in [n for n in _ast.walk(node) if isinstance(n, _ast.Call)]:
                for kw in call.keywords:
                    if kw.arg in data_keys and isinstance(kw.value, _ast.Name) and kw.value.id != kw.arg:
                        kw.value = _ast.Name(id=kw.arg, ctx=_ast.Load())
                        changed = True
            return node
        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)
    try:
        tree = _S().visit(tree)
        if not changed:
            return text
        _ast.fix_missing_locations(tree)
        return _ndl_ensure_block_bodies(_ast.unparse(tree))
    except Exception:
        return text


def _ndl_heal_invalid_qt_direct_attr_calls_v58(text):
    """Drop bare calls formed by crossing two direct Qt symbols."""
    if not text or '.' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    qt_symbols = {
        'QApplication', 'QMainWindow', 'QWidget', 'QDialog', 'QFrame',
        'QLabel', 'QPushButton', 'QTextEdit', 'QPlainTextEdit', 'QLineEdit',
        'QCheckBox', 'QRadioButton', 'QButtonGroup', 'QVBoxLayout',
        'QHBoxLayout', 'QGridLayout', 'QFormLayout', 'QStackedWidget',
        'QTabWidget', 'QScrollArea', 'QComboBox', 'QSpinBox', 'QSlider',
        'QListWidget', 'QListWidgetItem', 'QMessageBox', 'QFileDialog',
        'QFont', 'QColor', 'QBrush', 'QIcon', 'QPixmap', 'QImage',
        'QPainter', 'QPen', 'QCursor', 'QTextCursor', 'Qt', 'QTimer',
        'QThread', 'QRunnable', 'QThreadPool', 'QObject', 'Signal', 'Slot',
        'QUrl', 'QSize', 'QPoint', 'QRect', 'QEvent',
    }
    valid_receivers = {'QtWidgets', 'QtGui', 'QtCore'}
    changed = False

    def _bad_expr(stmt):
        if not (isinstance(stmt, _ast.Expr)
                and isinstance(stmt.value, _ast.Call)
                and isinstance(stmt.value.func, _ast.Attribute)
                and isinstance(stmt.value.func.value, _ast.Name)):
            return False
        recv = stmt.value.func.value.id
        attr = stmt.value.func.attr
        return recv in qt_symbols and recv not in valid_receivers and attr in qt_symbols

    def _clean_body(body):
        nonlocal changed
        out = []
        for stmt in body:
            if _bad_expr(stmt):
                changed = True
                continue
            out.append(stmt)
        if not out:
            out.append(_ast.Pass())
        return out

    class _Cleaner(_ast.NodeTransformer):
        def visit_Module(self, node):
            self.generic_visit(node)
            node.body = _clean_body(node.body)
            return node

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = _clean_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = _clean_body(node.body)
            return node

        def visit_ClassDef(self, node):
            self.generic_visit(node)
            node.body = _clean_body(node.body)
            return node

    tree = _Cleaner().visit(tree)
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ndl_ensure_block_bodies(_ast.unparse(tree))
    except Exception:
        return text


_NDL_QT_SIGNAL_NAMES = frozenset({
    'toggled', 'clicked', 'pressed', 'released', 'triggered', 'hovered',
    'textChanged', 'textEdited', 'returnPressed', 'editingFinished',
    'currentIndexChanged', 'currentTextChanged', 'activated', 'highlighted',
    'valueChanged', 'sliderMoved', 'sliderReleased', 'rangeChanged',
    'itemClicked', 'itemDoubleClicked', 'itemChanged', 'itemSelectionChanged',
    'currentItemChanged', 'itemEntered', 'cellChanged', 'cellClicked',
    'timeout', 'finished', 'started', 'stateChanged',
    'accepted', 'rejected', 'customContextMenuRequested',
})


def _ndl_heal_signal_connect_arglists_v70(text):
    """Rebuild mangled Qt ``signal.connect(slot)`` call shapes.

    Native recovery often collapses
    ``self.ui.btn.clicked.connect(self.on_btn)`` into
    ``self.ui.btn(clicked, connect, on_btn)`` or
    ``self.connect.ui(btn, clicked, on_btn)``. Rewrite only when signal/slot
    tokens are already present — never invent names.
    """
    if not text or 'connect' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False
    signals = _NDL_QT_SIGNAL_NAMES
    method_names = {
        n.name for n in _ast.walk(tree)
        if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef))}

    def _name_of(node):
        if isinstance(node, _ast.Name):
            return node.id
        if isinstance(node, _ast.Attribute):
            return node.attr
        if isinstance(node, _ast.Constant) and isinstance(node.value, str):
            return node.value
        return None

    def _slot_expr(node):
        nm = _name_of(node)
        if not nm:
            return None
        if isinstance(node, _ast.Attribute):
            return node
        if nm in method_names or nm.startswith('on_'):
            return _ast.Attribute(
                value=_ast.Name(id='self', ctx=_ast.Load()),
                attr=nm, ctx=_ast.Load())
        return _ast.Name(id=nm, ctx=_ast.Load())

    def _try_rewrite_call(call):
        nonlocal changed
        if not isinstance(call, _ast.Call) or not isinstance(
                call.func, _ast.Attribute):
            return None
        args = list(call.args)
        names = [_name_of(a) for a in args]
        # A: recv.widget(signal, connect, slot[, ...])
        if len(args) >= 3:
            for i in range(len(names) - 2):
                sig, mid, slot = names[i], names[i + 1], names[i + 2]
                if sig in signals and mid == 'connect' and slot:
                    slot_node = _slot_expr(args[i + 2])
                    if slot_node is None:
                        return None
                    changed = True
                    return _ast.Call(
                        func=_ast.Attribute(
                            value=_ast.Attribute(
                                value=call.func, attr=sig, ctx=_ast.Load()),
                            attr='connect', ctx=_ast.Load()),
                        args=[slot_node], keywords=[])
        # B: self.<verb>.ui(widget, signal, [connect,] slot)
        if (len(args) >= 3
                and isinstance(call.func.value, _ast.Attribute)
                and call.func.attr == 'ui'
                and _name_of(call.func.value) in (
                    'connect', 'setChecked', 'setCurrentIndex', 'hide',
                    'show', 'addItem', 'setText', 'isChecked')):
            wname = _name_of(args[0])
            if not wname:
                return None
            for i in range(1, len(names) - 1):
                if names[i] not in signals:
                    continue
                slot_i = i + 1
                if names[slot_i] == 'connect' and slot_i + 1 < len(args):
                    slot_i += 1
                if slot_i >= len(args):
                    continue
                slot_node = _slot_expr(args[slot_i])
                if slot_node is None:
                    continue
                recv = _ast.Attribute(
                    value=_ast.Attribute(
                        value=_ast.Name(id='self', ctx=_ast.Load()),
                        attr='ui', ctx=_ast.Load()),
                    attr=wname, ctx=_ast.Load())
                changed = True
                return _ast.Call(
                    func=_ast.Attribute(
                        value=_ast.Attribute(
                            value=recv, attr=names[i], ctx=_ast.Load()),
                        attr='connect', ctx=_ast.Load()),
                    args=[slot_node], keywords=[])
        # C: fused ``self.setSomething.signalName()`` (empty args) — demote to
        # an honest recovered marker; do not invent the timer/receiver object.
        if (not args
                and isinstance(call.func, _ast.Attribute)
                and isinstance(call.func.value, _ast.Attribute)
                and call.func.attr in signals
                and isinstance(call.func.value.attr, str)
                and call.func.value.attr.startswith('set')):
            try:
                _txt = _ast.unparse(call)
            except Exception:
                _txt = ''
            if _txt:
                changed = True
                return _ast.Expr(value=_ast.Constant(
                    value='##RECOVERED## ' + _txt
                    + '  # fused setter+signal (wiring incomplete)'))
        return None

    class _Fix(_ast.NodeTransformer):
        def visit_Expr(self, node):
            self.generic_visit(node)
            if isinstance(node.value, _ast.Call):
                nw = _try_rewrite_call(node.value)
                if nw is not None:
                    if isinstance(nw, _ast.Expr):
                        return nw
                    return _ast.Expr(value=nw)
            return node

        def visit_Assign(self, node):
            self.generic_visit(node)
            if isinstance(node.value, _ast.Call):
                nw = _try_rewrite_call(node.value)
                if nw is not None and isinstance(nw, _ast.Call):
                    node.value = nw
            return node

    tree = _Fix().visit(tree)
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ndl_ensure_block_bodies(_ast.unparse(tree))
    except Exception:
        return text


def _ndl_heal_dead_else_after_return_v70(text):
    """Remove orphan ``else:`` suites that cannot follow the previous statement.

    CFG structuring emits both ``return``/``raise`` then ``else:`` (SyntaxError)
    and assignment/call then ``else:`` (also SyntaxError). Drop the ``else:``
    header and its trivial ``pass`` body; keep non-trivial else-body lines as
    ``# UNREACHABLE:`` comments.
    """
    if not text or 'else:' not in text:
        return text

    def _opens_else(ps):
        return (ps.startswith('if ') or ps.startswith('elif ')
                or ps.startswith('for ') or ps.startswith('while ')
                or ps.startswith('try') or ps.startswith('except')
                or ps.startswith('with ') or ps.startswith('async for')
                or ps.startswith('async with'))

    lines = text.split('\n')
    out = []
    i = 0
    while i < len(lines):
        ln = lines[i]
        if ln.strip() == 'else:' or ln.strip().startswith('else:'):
            lind = ln[:len(ln) - len(ln.lstrip())]
            prev = None
            for p in reversed(out):
                if not p.strip():
                    continue
                pind = p[:len(p) - len(p.lstrip())]
                if len(pind) > len(lind):
                    continue
                prev = p
                break
            orphan = True
            if prev is not None:
                pind = prev[:len(prev) - len(prev.lstrip())]
                if len(pind) == len(lind) and _opens_else(prev.strip()):
                    orphan = False
            if orphan:
                i += 1
                while i < len(lines):
                    nx = lines[i]
                    if not nx.strip():
                        i += 1
                        continue
                    nind = nx[:len(nx) - len(nx.lstrip())]
                    if len(nind) <= len(lind):
                        break
                    if nx.strip() == 'pass' or nx.strip().startswith('pass '):
                        i += 1
                        continue
                    out.append(lind + '# UNREACHABLE: ' + nx.strip())
                    i += 1
                continue
        out.append(ln)
        i += 1
    return '\n'.join(out)


def _ndl_nest_orphan_self_methods_v70(text):
    """Nest module-level ``def ...(self, ...):`` into the nearest prior class.

    When class injection leaves ``class Foo: pass  # UNCERTAIN...`` and the
    recovered methods are emitted as top-level defs (still taking ``self``),
    move those contiguous self-methods into the last such class so the module
    structure matches Nuitka's Class.method qualnames.
    """
    if not text or 'class ' not in text or 'def ' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    # Find classes whose body is only Pass / Expr docstring
    def _is_empty_class(cls):
        for s in cls.body:
            if isinstance(s, _ast.Pass):
                continue
            if (isinstance(s, _ast.Expr)
                    and isinstance(getattr(s, 'value', None), _ast.Constant)
                    and isinstance(s.value.value, str)):
                continue
            return False
        return True

    empty_classes = [
        n for n in tree.body
        if isinstance(n, _ast.ClassDef) and _is_empty_class(n)]
    if not empty_classes:
        return text

    # Collect leading module-level FunctionDefs that take self
    def _is_self_method(fn):
        if not isinstance(fn, (_ast.FunctionDef, _ast.AsyncFunctionDef)):
            return False
        args = fn.args.args
        return bool(args) and args[0].arg == 'self'

    # Group consecutive self-methods after the last empty class
    last_empty = empty_classes[-1]
    try:
        last_idx = tree.body.index(last_empty)
    except ValueError:
        return text

    # Prefer the empty class immediately before the orphan method run
    orphans = []
    start = None
    for i in range(last_idx + 1, len(tree.body)):
        node = tree.body[i]
        if _is_self_method(node):
            if start is None:
                start = i
            orphans.append(node)
        elif orphans:
            break
        else:
            # non-method between class and methods — abort for this class
            if isinstance(node, _ast.ClassDef):
                last_empty = node if _is_empty_class(node) else last_empty
                orphans = []
                start = None
            elif not isinstance(node, (_ast.Import, _ast.ImportFrom, _ast.Assign)):
                pass

    if not orphans:
        return text

    # Attach orphans to last_empty; remove from module body
    # Drop placeholder Pass if present
    new_body = [s for s in last_empty.body if not isinstance(s, _ast.Pass)]
    new_body.extend(orphans)
    if not new_body:
        new_body = [_ast.Pass()]
    last_empty.body = new_body

    orphan_ids = {id(o) for o in orphans}
    tree.body = [n for n in tree.body if id(n) not in orphan_ids]
    _ast.fix_missing_locations(tree)
    try:
        return _ndl_ensure_block_bodies(_ast.unparse(tree))
    except Exception:
        return text


def _ndl_demote_unsafe_recovered_calls_v58(text):
    """Turn unsafe recovered call statements into try-wrapped real calls.

    V62 FIX: previously emitted a *bare string statement* like
        '[unsafe recovered call demoted: self.foo.bar()]'
    which made the resulting Python module non-functional (the string is just
    a no-op expression, the call is gone forever). Common casualties were
    Qt slot bodies like `self.<signal>.emit()` (zero-arg emits were wrongly
    flagged as missing a required arg) and `self.<qthreadpool>.start(callable)`
    (start was wrongly flagged as zero-arg-only).

    The fix has two parts:
      1. The quality check (`_ndl_recovered_stmt_quality_ok_v58`) has been
         relaxed so emit()/start(callable) survive -- see that function.
      2. Here, when we *do* still decide a call is unsafe, we keep the call
         as a real Expr (so the module still does something) but wrap it in
         a try/except so runtime errors don't crash the program. This is far
         better than emitting a forensic string: the call actually executes.
    """
    if not text or '(' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False

    def _replacement(stmt):
        nonlocal changed
        if not (isinstance(stmt, _ast.Expr) and isinstance(stmt.value, _ast.Call)):
            return stmt
        try:
            src = _ast.unparse(stmt).strip()
        except Exception:
            return stmt
        if _ndl_recovered_stmt_quality_ok_v58(src):
            return stmt
        changed = True
        # V62: keep the call as a real Expr wrapped in try/except, so the
        # module still executes the call. We do NOT replace it with a string.
        # Build:  try: <call> \n except Exception: pass
        try:
            call_node = stmt.value
            handler = _ast.ExceptHandler(
                type=_ast.Name(id='Exception', ctx=_ast.Load()),
                name=None,
                body=[_ast.Pass()],
            )
            new_try = _ast.Try(
                body=[_ast.Expr(value=call_node)],
                handlers=[handler],
                orelse=[],
                finalbody=[],
            )
            return new_try
        except Exception:
            # Last-resort fallback: keep the call as-is rather than dropping it.
            return stmt

    class _Demoter(_ast.NodeTransformer):
        def _body(self, body):
            return [_replacement(self.visit(stmt)) for stmt in body]

        def visit_Module(self, node):
            node.body = self._body(node.body)
            return node

        def visit_ClassDef(self, node):
            node.body = self._body(node.body)
            return node

        def visit_FunctionDef(self, node):
            node.body = self._body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            node.body = self._body(node.body)
            return node

        def visit_If(self, node):
            self.generic_visit(node)
            node.body = [_replacement(s) for s in node.body]
            node.orelse = [_replacement(s) for s in node.orelse]
            return node

        def visit_For(self, node):
            self.generic_visit(node)
            node.body = [_replacement(s) for s in node.body]
            node.orelse = [_replacement(s) for s in node.orelse]
            return node

        def visit_While(self, node):
            self.generic_visit(node)
            node.body = [_replacement(s) for s in node.body]
            node.orelse = [_replacement(s) for s in node.orelse]
            return node

        def visit_Try(self, node):
            # V62 FIX: do NOT recurse into try bodies. Statements inside a try
            # block are already protected by the surrounding except handler,
            # so wrapping them in another try/except (which is what
            # _replacement does for unsafe calls) would produce a redundant
            # double-wrap like:
            #     try:
            #         try: self.label_4.setText(str(value))
            #         except Exception: pass
            #     except Exception: pass
            # We still visit the handlers and orelse/finalbody in case there
            # are unsafe calls there, but the try body itself is left alone.
            self.generic_visit(node)
            # Skip node.body -- already protected by the try.
            node.orelse = [_replacement(s) for s in node.orelse]
            node.finalbody = [_replacement(s) for s in node.finalbody]
            for h in node.handlers:
                h.body = [_replacement(s) for s in h.body]
            return node

    tree = _Demoter().visit(tree)
    if not changed:
        return text
    _ast.fix_missing_locations(tree)
    try:
        return _ndl_ensure_block_bodies(_ast.unparse(tree))
    except Exception:
        return text


def _ndl_heal_common_source_like_bodies_v62(text, consts=None, code_objects=None):
    """Recover common source-like bodies from strong code-object/source-map evidence.

    This pass is deliberately pattern-based, not sample-based.  It only rewrites
    functions whose current body is still weak (pass or source-map strings) and
    whose code-object varnames / recovered tokens prove a familiar Python
    workflow: resource-path helpers, subprocess runners with stream threads,
    process shutdown loops, keyboard-listener setup, and tiny text/time helpers.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    pool = [s for s in (consts or []) if isinstance(s, str)]
    pool_text = "\n".join(pool)
    imports_needed = set()

    co_by_qn = {}
    co_by_leaf = {}
    for co in (code_objects or []):
        q = co.get('qualname') or co.get('name')
        if not q:
            continue
        q = str(q)
        co_by_qn.setdefault(q, co)
        leaf = q.split('.')[-1]
        co_by_leaf.setdefault(leaf, []).append(co)

    def _pick(pred, default):
        for s in pool:
            try:
                if pred(s):
                    return s
            except Exception:
                pass
        return default

    def _q(s):
        return repr(str(s))

    def _fn_text(node):
        try:
            return _ast.unparse(node)
        except Exception:
            return ''

    def _body_weak(node):
        real = 0
        strings = 0
        for st in node.body:
            if isinstance(st, _ast.Pass):
                continue
            val = getattr(st, 'value', None)
            if isinstance(st, _ast.Expr) and isinstance(val, _ast.Constant) and isinstance(val.value, str):
                strings += 1
                continue
            if (isinstance(st, _ast.Expr)
                    and type(val).__name__ == 'Str'):
                strings += 1
                continue
            real += 1
        if real == 0:
            return True
        txt = _fn_text(node)
        return (real <= 1 and strings >= 3 and
                ('[recovered source map' in txt or 'unsafe recovered call demoted' in txt))

    def _set_body(node, src):
        try:
            wrap = 'def _():\n' + '\n'.join('    ' + l for l in src.strip('\n').splitlines())
            body = _ast.parse(wrap).body[0].body
            if body:
                node.body = body
                return True
        except Exception:
            return False
        return False

    def _co_for(qn, leaf):
        co = co_by_qn.get(qn)
        if co:
            return co
        matches = co_by_leaf.get(leaf) or []
        if len(matches) == 1:
            return matches[0]
        return None

    def _varnames(co):
        return [str(x) for x in ((co or {}).get('varnames') or (co or {}).get('args') or [])]

    def _has_any(hay, *needles):
        h = hay.lower()
        return any(n.lower() in h for n in needles)

    def _resource_base_body():
        imports_needed.update({'import os', 'import sys'})
        return """
if getattr(sys, 'frozen', False):
    return os.path.dirname(sys.executable)
return os.path.dirname(os.path.abspath(__file__))
"""

    def _resource_path_body():
        imports_needed.add('import os')
        return """
base_path = get_base_path()
return os.path.join(base_path, relative_path)
"""

    def _text_clean_body():
        imports_needed.add('import re')
        return r"""
ansi_escape = re.compile(r'\x1b\[[0-9;]*[A-Za-z]')
return ansi_escape.sub('', text)
"""

    def _decode_body():
        return """
if isinstance(text, bytes):
    try:
        return text.decode('utf-8')
    except UnicodeDecodeError:
        return text.decode('utf-8', errors='replace')
return str(text)
"""

    def _remaining_body():
        return """
total_seconds = int(remaining)
days = total_seconds // 86400
hours = total_seconds % 86400 // 3600
minutes = total_seconds % 3600 // 60
if days > 0:
    return f'{days}d {hours}h {minutes}m'
if hours > 0:
    return f'{hours}h {minutes}m'
return f'{minutes}m'
"""

    def _update_selection_body():
        return """
self.selections = getattr(self, 'selections', {})
self.selections.setdefault(category, {})[key] = value
"""

    def _stop_processes_body():
        msg_ok = _pick(lambda s: 'durduruldu' in s.lower() or 'stopped' in s.lower(),
                       'Script stopped: ')
        msg_ok = msg_ok.replace("\\", "\\\\").replace("'", "\\'")
        imports_needed.add('import time')
        return f"""
for friendly_name, process in list(getattr(self, 'running_processes', {{}}).items()):
    try:
        process.terminate()
        process.wait(timeout=3)
        if hasattr(self, 'log_message'):
            self.log_message(f'{{friendly_name}} {msg_ok}', 'info')
    except Exception as e:
        if hasattr(self, 'log_message'):
            self.log_message(f'{{friendly_name}}: {{e}}', 'error')
getattr(self, 'running_processes', {{}}).clear()
"""

    def _keyboard_listener_body():
        imports_needed.add('from threading import Thread')
        return """
def on_press(key):
    try:
        if key == keyboard.Key.f12:
            self.stop_all_scripts()
    except Exception as e:
        if hasattr(self, 'log_message'):
            self.log_message(str(e), 'error')

def listener_thread():
    with keyboard.Listener(on_press=on_press) as listener:
        listener.join()
Thread(target=listener_thread, daemon=True).start()
"""

    def _runner_body(args, text_blob):
        imports_needed.update({
            'import os',
            'import sys',
            'from subprocess import Popen, PIPE, CREATE_NO_WINDOW',
            'from threading import Thread',
        })
        launch_msg = _pick(lambda s: 'DEBUG: Launching CMD' in s,
                           _pick(lambda s: 'Launching CMD' in s, 'Launching CMD: '))
        launch_msg = launch_msg.rstrip()
        if not launch_msg.endswith((' ', ':')):
            launch_msg += ':'
        launch_msg += ' '
        started_msg = _pick(lambda s: 'started' in s.lower(), 'started')
        extra_writes = []
        for a in args:
            if a in ('self', 'script_path'):
                continue
            extra_writes.append(a)
        write_lines = []
        for a in extra_writes:
            write_lines.extend([
                f"if {a} is not None:",
                f"    process.stdin.write(str({a}) + '\\n')",
            ])
        if write_lines:
            write_lines.extend([
                "process.stdin.flush()",
                "process.stdin.close()",
            ])
        else:
            write_lines.append("process.stdin.close()")
        write_block = "\n".join(write_lines)
        script_expr = 'script_path' if 'script_path' in args else "os.path.join(get_base_path(), str(item_name) + '.py')"
        bot_line = ("bot_internal = self.get_bot_internal_name(script_path) "
                    "if hasattr(self, 'get_bot_internal_name') and 'script_path' in locals() else None")
        return f"""
friendly_name = self.get_script_friendly_name({script_expr}) if hasattr(self, 'get_script_friendly_name') else str({script_expr})
{bot_line}
cmd = [sys.executable, {script_expr}]
if bot_internal:
    cmd.extend(['--run-bot', str(bot_internal)])
if hasattr(self, 'log_message'):
    self.log_message(f'{launch_msg}{{cmd}}', 'debug')
process = Popen(cmd, stdin=PIPE, stdout=PIPE, stderr=PIPE, text=True, bufsize=1, creationflags=CREATE_NO_WINDOW)
{write_block}
if hasattr(self, 'running_processes'):
    self.running_processes[friendly_name] = process
if hasattr(self, 'log_message'):
    self.log_message(f'{{friendly_name}} {started_msg}', 'success')

def read_output():
    try:
        for line in process.stdout:
            line = self.decode_utf8_safe(line).rstrip() if hasattr(self, 'decode_utf8_safe') else str(line).rstrip()
            if line and hasattr(self, 'log_message'):
                clean = self.clean_ansi_codes(line) if hasattr(self, 'clean_ansi_codes') else line
                self.log_message(clean, 'info')
    except Exception as e:
        if hasattr(self, 'log_message'):
            self.log_message(str(e), 'error')

def read_error():
    try:
        for line in process.stderr:
            line = self.decode_utf8_safe(line).rstrip() if hasattr(self, 'decode_utf8_safe') else str(line).rstrip()
            if line and hasattr(self, 'log_message'):
                clean = self.clean_ansi_codes(line) if hasattr(self, 'clean_ansi_codes') else line
                self.log_message(clean, 'error')
    except Exception as e:
        if hasattr(self, 'log_message'):
            self.log_message(str(e), 'error')

def wait_process():
    try:
        return_code = process.wait()
        if hasattr(self, 'running_processes'):
            self.running_processes.pop(friendly_name, None)
        if hasattr(self, 'log_message'):
            self.log_message(f'{{friendly_name}} exited with code {{return_code}}', 'info')
    except Exception as e:
        if hasattr(self, 'log_message'):
            self.log_message(str(e), 'error')
Thread(target=read_output, daemon=True).start()
Thread(target=read_error, daemon=True).start()
Thread(target=wait_process, daemon=True).start()
"""

    class _S(_ast.NodeTransformer):
        def __init__(self):
            self.stack = []
            self.changed = False

        def visit_Module(self, node):
            self.generic_visit(node)
            new_body = []
            for st in node.body:
                if isinstance(st, (_ast.FunctionDef, _ast.AsyncFunctionDef)) and _body_weak(st):
                    matches = co_by_leaf.get(st.name) or []
                    if matches:
                        qns = [str(co.get('qualname') or co.get('name') or '')
                               for co in matches]
                        has_top = any('<locals>' not in q for q in qns)
