    import copy as _copy
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False

    def _txt(node):
        try:
            return _ast.unparse(node)
        except Exception:
            return ''

    def _loads_name(node, name):
        return any(isinstance(n, _ast.Name) and isinstance(n.ctx, _ast.Load) and n.id == name
                   for n in _ast.walk(node))

    def _expr_stmt_matches_test(stmt, test):
        return (isinstance(stmt, _ast.Expr) and isinstance(stmt.value, _ast.Call)
                and _txt(stmt.value) == _txt(test))

