# =============================================================================
# DEVIRT MODE v8 — direct rematerialization of the ORIGINAL Python artifacts
# =============================================================================
#
# New in this upgrade (implemented on top of the Nuitka 4.0.6/4.1.x formats):
#
#   --devirt            Static, zero-execution devirtualization:
#                       rematerialize the original compiled Python directly
#                       from the DataComposer constants blob WITHOUT any C
#                       reconstruction or translation:
#                         * every marshal'd code object in the ".bytecode"
#                           chunk is emitted 1:1 as a real .pyc file
#                           (the original bytecode, byte for byte)
#                         * the ".files" chunk is unpacked
#                         * per-module constants pools + code-object maps are
#                           dumped for native-compiled modules
#                         * a full DEVIRT_MANIFEST.json is produced
#
#   --onefile-unpack    Statically unpack any Nuitka onefile binary (ELF, PE,
#                       Mach-O) — including the zstd-compressed payload —
#                       WITHOUT executing the bootstrap. Works for Linux/macOS
#                       payloads too (the legacy code was Windows-only).
#
#   --trigger           Runtime "triggeratore" (payload-neutralized trigger):
#                       runs the target under gdb, sets a breakpoint BEFORE
#                       any module code executes (EXECUTE_MAIN_MODULE), dumps
#                       the *decoded* constants blob straight from process
#                       memory, then KILLS the process. The payload never
#                       runs. The dumped blob feeds the same static devirt
#                       pipeline, which defeats in-memory/commercial blob
#                       protection that is opaque on disk.
#
# Why this is the correct "runtime way" to devirtualize Nuitka:
#   Nuitka-compiled modules are translated to C: their code objects exist in
#   the blob ONLY as compact metadata ('C' tags — name/lines/args, NO
#   bytecode). The original Python bytecode survives verbatim ONLY for the
#   modules Nuitka embeds uncompiled (the ".bytecode" chunk), stored as raw
#   marshal streams loaded at runtime via PyMarshal_ReadObjectFromString.
#   Devirt therefore rematerializes every byte of original Python that exists
#   in the binary, reports honestly what is native-only, and the trigger mode
#   additionally captures the decoded constants blob from a live (but never
#   payload-executing) process for protected builds.
# =============================================================================

_DV_MAX_BLOB_SCAN = 512 * 1024 * 1024


# ---------------------------------------------------------------------------
# Zstandard decompression with a portable backend chain
# ---------------------------------------------------------------------------

_DV_ZSTD_LIB_CANDIDATES = (
    "libzstd.so.1", "libzstd.so", "libzstd.dylib", "libzstd.dll",
    "/usr/lib/x86_64-linux-gnu/libzstd.so.1",
    "/usr/lib/aarch64-linux-gnu/libzstd.so.1",
    "/usr/lib/libzstd.so.1",
)


def _dv_ctypes_zstd_decompress(data, max_output=None, allow_trailing=False):
    """Stream-decompress zstd data through libzstd via ctypes (no deps)."""
    import ctypes

    if not data:
        return b""

    lib = None
    for name in _DV_ZSTD_LIB_CANDIDATES:
        try:
            lib = ctypes.CDLL(name)
            break
        except OSError:
            continue
    if lib is None:
        raise RuntimeError("libzstd not loadable via ctypes")

    class _InBuf(ctypes.Structure):
        _fields_ = [("src", ctypes.c_void_p),
                    ("size", ctypes.c_size_t),
                    ("pos", ctypes.c_size_t)]

    class _OutBuf(ctypes.Structure):
        _fields_ = [("dst", ctypes.c_void_p),
                    ("size", ctypes.c_size_t),
                    ("pos", ctypes.c_size_t)]

    lib.ZSTD_createDCtx.restype = ctypes.c_void_p
    lib.ZSTD_createDCtx.argtypes = []
    lib.ZSTD_freeDCtx.restype = ctypes.c_size_t
    lib.ZSTD_freeDCtx.argtypes = [ctypes.c_void_p]
    lib.ZSTD_decompressStream.restype = ctypes.c_size_t
    lib.ZSTD_decompressStream.argtypes = [
        ctypes.c_void_p, ctypes.POINTER(_OutBuf), ctypes.POINTER(_InBuf)]
    lib.ZSTD_isError.restype = ctypes.c_uint
    lib.ZSTD_isError.argtypes = [ctypes.c_size_t]
    lib.ZSTD_getErrorName.restype = ctypes.c_char_p
    lib.ZSTD_getErrorName.argtypes = [ctypes.c_size_t]

    ctx = lib.ZSTD_createDCtx()
    if not ctx:
        raise RuntimeError("ZSTD_createDCtx failed")

    try:
        src_buf = ctypes.create_string_buffer(bytes(data), len(data))
        inb = _InBuf(ctypes.cast(src_buf, ctypes.c_void_p), len(data), 0)
        out = bytearray()
        limit = int(max_output) if max_output else (2 * 1024 * 1024 * 1024 - 1)
        chunk = 1 << 20

        while True:
            dst = ctypes.create_string_buffer(chunk)
            outb = _OutBuf(ctypes.cast(dst, ctypes.c_void_p), chunk, 0)
            ret = lib.ZSTD_decompressStream(
                ctx, ctypes.byref(outb), ctypes.byref(inb))
            if lib.ZSTD_isError(ret):
                err = lib.ZSTD_getErrorName(ret)
                raise RuntimeError("zstd error: %s" %
                                   (err.decode() if err else str(ret)))
            if outb.pos:
                out += dst.raw[:outb.pos]
            if len(out) > limit:
                raise ValueError("zstd output exceeds the configured bound")
            if ret == 0:
                # Frame complete.  Continue only when another frame follows
                # (onefile multi-frame streams); stop otherwise, tolerating
                # trailing bytes when the caller allows it.
                if inb.pos >= inb.size:
                    break
                rest = bytes(data)[inb.pos:]
                if not any(rest):
                    break
                if allow_trailing:
                    break
                continue
            if inb.pos >= inb.size:
                raise ValueError("truncated zstd stream")
        return bytes(out)
    finally:
        if ctx:
            lib.ZSTD_freeDCtx(ctx)


def _dv_zstd_decompress(data, max_output=None, allow_trailing=False):
    """Decompress one zstd stream using the best available backend.

    Order: Python 3.14 compression.zstd -> zstandard package -> ctypes
    libzstd -> zstd CLI.  ``allow_trailing`` permits non-zstd bytes after
    the end of the frame (embedded Nuitka >= 4.1 onefile payloads).
    Raises RuntimeError when nothing works.
    """
    errors = []

    try:
        from compression import zstd as _zstd
        decoder = _zstd.ZstdDecompressor()
        out = decoder.decompress(data, max_length=int(max_output) + 1
                                 if max_output else -1)
        if max_output is not None and len(out) > int(max_output):
            raise ValueError("zstd output exceeds the configured bound")
        return bytes(out)
    except ImportError as exc:
        errors.append("compression.zstd: %s" % exc)
    except Exception as exc:
        if not allow_trailing:
            errors.append("compression.zstd: %s" % exc)
        else:
            # Trailing data after the frame: fall through to the streaming
            # backends which stop at the first frame boundary.
            errors.append("compression.zstd: %s (trailing tolerated)" % exc)

    try:
        import io as _io
        import zstandard as _zstd
        dec = _zstd.ZstdDecompressor()
        if not allow_trailing:
            try:
                out = dec.decompress(data, max_output_size=int(max_output) + 1
                                     if max_output else 0)
                if max_output is not None and len(out) > int(max_output):
                    raise ValueError("zstd output exceeds the configured bound")
                return bytes(out)
            except Exception:
                pass
        # Streaming API: stops at the first complete frame, so trailing
        # bytes after the frame are naturally tolerated.
        result = bytearray()
        with dec.stream_reader(_io.BytesIO(bytes(data)),
                               read_across_frames=False) as reader:
            while True:
                want = 1024 * 1024
                if max_output is not None:
                    want = min(want, int(max_output) + 1 - len(result))
                    if want <= 0:
                        raise ValueError(
                            "zstd output exceeds the configured bound")
                piece = reader.read(want)
                if not piece:
                    break
                result.extend(piece)
        return bytes(result)
    except ImportError as exc:
        errors.append("zstandard: %s" % exc)
    except Exception as exc:
        errors.append("zstandard: %s" % exc)

    try:
        return _dv_ctypes_zstd_decompress(data, max_output=max_output,
                                          allow_trailing=allow_trailing)
    except Exception as exc:
        errors.append("ctypes-libzstd: %s" % exc)

    # Last resort: the zstd CLI
    try:
        import shutil
        import subprocess
        zstd_bin = shutil.which("zstd")
        if zstd_bin:
            proc = run_external_tool(
                [zstd_bin, "-dc"], input_bytes=bytes(data), timeout=120)
            out = proc.stdout or b""
            if proc.returncode == 0:
                if max_output is not None and len(out) > int(max_output):
                    raise ValueError("zstd output exceeds the configured bound")
                return bytes(out)
            raise RuntimeError("zstd CLI failed with code %d" % proc.returncode)
        raise RuntimeError("zstd CLI not found")
    except Exception as exc:
        errors.append("zstd-cli: %s" % exc)

    raise RuntimeError(
        "no zstd backend available (need Python 3.14 compression.zstd, the "
        "'zstandard' package, libzstd.so, or the zstd CLI); tried: "
        + "; ".join(errors))


# ---------------------------------------------------------------------------
# Container format detection
# ---------------------------------------------------------------------------

def _dv_detect_binfmt(data):
    """Return 'PE', 'ELF', 'MACHO' or None for raw binary bytes."""
    if not data or len(data) < 16:
        return None
    if data[:2] == b"MZ":
        return "PE"
    if data[:4] == b"\x7fELF":
        return "ELF"
    for magic in (b"\xfe\xed\xfa\xce", b"\xfe\xed\xfa\xcf",
                  b"\xcf\xfa\xed\xfe", b"\xce\xfa\xed\xfe",
                  b"\xca\xfe\xba\xbe"):
        if data[:4] == magic:
            return "MACHO"
    return None


def _dv_is_onefile_candidate(data):
    """Cheap check whether *data* carries an attached Nuitka onefile payload."""
    # Trailer form (ELF/Mach-O and PE appends): last 8 bytes = payload size,
    # payload begins with b"KA" + b"X"/b"Y".
    if not data or len(data) < 16:
        return False
    size = struct.unpack_from("<Q", data, len(data) - 8)[0]
    if size <= 0 or size > len(data) - 8:
        return False
    start = len(data) - 8 - size
    if data[start:start + 2] == b"KA" and data[start + 2:start + 3] in (b"X", b"Y"):
        return True
    return False


# ---------------------------------------------------------------------------
# Onefile payload parsing (static — the bootstrap NEVER runs)
# ---------------------------------------------------------------------------

def _dv_onefile_payload_bytes(data, binfmt=None):
    """Locate raw onefile payload stream candidates.

    Returns a list of ``(payload_bytes, source)`` tuples, most trustworthy
    first.  Sources:
      * 'pe-resource-27'      — Windows keeps the payload in RCDATA 27
      * 'appended-trailer'    — classic ELF/Mach-O layout: payload + u64
                                size trailer at EOF (Nuitka <= 4.0)
      * 'embedded-ka-marker'  — Nuitka >= 4.1 embeds the payload through the
                                constants-blob mechanism (no trailer); the
                                stream starts at a 'KA'+'X'/'Y' marker inside
                                the image and is validated during parsing.
    """
    candidates = []

    # 1) Windows keeps the payload in RCDATA resource 27.
    if (binfmt or _dv_detect_binfmt(data)) == "PE":
        try:
            import pefile
            pe = pefile.PE(data=data)
            resource = _ndl_pe_resource_bytes(pe, 10, 27)
            if resource and resource[:2] == b"KA" \
                    and resource[2:3] in (b"X", b"Y"):
                candidates.append((bytes(resource), "pe-resource-27"))
        except Exception:
            pass

    # 2) Trailer form used on ELF/Mach-O (and older PE builds).
    if len(data) >= 16:
        size = struct.unpack_from("<Q", data, len(data) - 8)[0]
        if 0 < size <= len(data) - 8:
            start = len(data) - 8 - size
            if data[start:start + 2] == b"KA" \
                    and data[start + 2:start + 3] in (b"X", b"Y"):
                candidates.append(
                    (bytes(data[start:len(data) - 8]), "appended-trailer"))

    # 3) Embedded form (Nuitka >= 4.1): 'KA' marker inside the image.  All
    #    occurrences are candidates; the entry-table parser validates them.
    if not candidates:
        pos = 0
        seen = set()
        while len(candidates) < 16:
            offset = data.find(b"KA", pos)
            if offset < 0 or offset > len(data) - 8:
                break
            pos = offset + 1
            if data[offset + 2:offset + 3] not in (b"X", b"Y"):
                continue
            if offset in seen:
                continue
            seen.add(offset)
            candidates.append((
                bytes(data[offset:]), "embedded-ka-marker+0x%X" % offset))
    return candidates


def _dv_read_onefile_name(stream, pos, wide):
    """Read a Nuitka onefile entry name; returns (name, new_pos) or None at EOF."""
    n = len(stream)
    if wide:
        start = pos
        while pos + 2 <= n:
            if stream[pos:pos + 2] == b"\x00\x00":
                raw = bytes(stream[start:pos])
                try:
                    name = raw.decode("utf-16le")
                except UnicodeDecodeError:
                    raise ValueError("invalid UTF-16 onefile entry name")
                return name, pos + 2
            pos += 2
            if pos - start > 8192:
                raise ValueError("onefile entry name too long")
        raise ValueError("truncated onefile entry name")
    else:
        start = pos
        while pos < n:
            if stream[pos] == 0:
                try:
                    name = bytes(stream[start:pos]).decode("utf-8")
                except UnicodeDecodeError:
                    raise ValueError("invalid UTF-8 onefile entry name")
                return name, pos + 1
            pos += 1
            if pos - start > 4096:
                raise ValueError("onefile entry name too long")
        raise ValueError("truncated onefile entry name")


def _dv_safe_onefile_path(name):
    """Sanitize one relative onefile entry name, or reject it."""
    cleaned = (name or "").replace("\\", "/").strip()
    if not cleaned or "\x00" in cleaned:
        return None
    parts = [p for p in cleaned.split("/") if p not in ("", ".")]
    if any(p == ".." for p in parts):
        return None
    if os.path.isabs(cleaned) or (len(cleaned) > 1 and cleaned[1] == ":"):
        return None
    cleaned = "/".join(parts)
    cleaned = re.sub(r'[<>:"|?*\x00-\x1f]', "_", cleaned)
    return cleaned or None


def _dv_parse_onefile_stream(stream, *, wide, flags_byte, per_file_zstd,
                             file_checksums, decompress, max_files=100000,
                             max_file_size=None):
    """Parse a Nuitka onefile payload stream (already decompressed unless
    ``per_file_zstd``) and yield entry dicts.

    Layout per entry (OnefileCompressor.py / OnefileBootstrap.c):
        name + "\\0" (utf-16le when wide)      -- empty name = terminator
        [flags u8]                  only when flags_byte (non-Windows)
        [link_target + "\\0"]       when flags & 2 (symlink, no data follows)
        size u64
        [crc32 u32]                 only when file_checksums
        [compressed_size u32]       only when per_file_zstd
        data
    """
    if max_file_size is None:
        try:
            max_file_size = int(os.environ.get(
                "NDL_ONEFILE_MAX_BYTES", str(2 * 1024 * 1024 * 1024)))
        except Exception:
            max_file_size = 2 * 1024 * 1024 * 1024

    data = memoryview(bytes(stream))
    n = len(data)
    pos = 0
    entries = []

    while True:
        if len(entries) >= max_files:
            raise ValueError("onefile entry count exceeds the safety bound")

        name, pos = _dv_read_onefile_name(data, pos, wide)
        if name == "":
            break

        entry = {"name": name, "safe_path": _dv_safe_onefile_path(name),
                 "is_symlink": False, "exec_bit": False,
                 "size": 0, "crc": None}

        if flags_byte:
            if pos + 1 > n:
                raise ValueError("truncated onefile flags")
            flags = data[pos]
            pos += 1
            entry["exec_bit"] = bool(flags & 1)
            if flags & 2:
                target, pos = _dv_read_onefile_name(data, pos, wide)
                entry["is_symlink"] = True
                entry["link_target"] = target
                entries.append(entry)
                continue

        if pos + 8 > n:
            raise ValueError("truncated onefile entry size")
        file_size = struct.unpack_from("<Q", data, pos)[0]
        pos += 8
        if file_size > max_file_size:
            raise ValueError("onefile entry exceeds the size safety bound")
        entry["size"] = int(file_size)

        if file_checksums:
            if pos + 4 > n:
                raise ValueError("truncated onefile entry checksum")
            entry["crc"] = struct.unpack_from("<I", data, pos)[0]
            pos += 4

        if per_file_zstd:
            if pos + 4 > n:
                raise ValueError("truncated onefile compressed size")
            comp_size = struct.unpack_from("<I", data, pos)[0]
            pos += 4
            if comp_size > max_file_size or pos + comp_size > n:
                raise ValueError("invalid onefile compressed size")
            frame = bytes(data[pos:pos + comp_size])
            pos += comp_size
            if decompress:
                content = _dv_zstd_decompress(
                    frame, max_output=max_file_size)
            else:
                content = frame  # caller decompresses later
            if len(content) != file_size:
                raise ValueError("onefile entry size mismatch after zstd")
            entry["data"] = content
        else:
            if pos + file_size > n:
                raise ValueError("truncated onefile entry data")
            entry["data"] = bytes(data[pos:pos + file_size])
            pos += file_size

        if entry.get("crc") is not None and entry.get("data") is not None:
            actual = zlib.crc32(entry["data"]) & 0xFFFFFFFF
            if actual == 0:
                actual = 1
            if actual != entry["crc"]:
                raise ValueError("onefile entry CRC32 mismatch")

        entries.append(entry)

    return entries


def _dv_unpack_onefile_payload(payload, *, wide, decompress=True,
                               max_file_size=None):
    """Parse a raw ``KAX``/``KAY`` payload and return the entry list.

    Handles all three stream layouts Nuitka emits:
      * ``KAX``                 — uncompressed stream
      * ``KAY`` (default)       — one zstd stream wrapping everything
      * ``KAY`` + per-file zstd — ``--onefile-as-archive``: raw metadata,
                                   one zstd frame per file
    ``file_checksums`` (cached onefile mode) is auto-detected by attempting
    the no-checksum layout first, then the checksum layout.
    """
    if not payload or payload[:2] != b"KA":
        return None
    indicator = payload[2:3]
    if indicator not in (b"X", b"Y"):
        raise ValueError("unsupported Nuitka onefile payload header")

    compressed = indicator == b"Y"
    max_files = 100000

    def _attempt(file_checksums, per_file_zstd):
        stream = payload[3:]
        if compressed and not per_file_zstd:
            stream = _dv_zstd_decompress(
                stream, max_output=max_file_size
                or int(os.environ.get("NDL_ONEFILE_MAX_BYTES",
                                      str(2 * 1024 * 1024 * 1024))),
                allow_trailing=True)
        return _dv_parse_onefile_stream(
            stream, wide=wide, flags_byte=not wide,
            per_file_zstd=per_file_zstd, file_checksums=file_checksums,
            decompress=decompress, max_files=max_files,
            max_file_size=max_file_size)

    # Prefer the default layouts, then the less common ones.
    attempts = [
        (False, False),   # default temp-mode, whole-stream zstd / raw
        (True, False),    # cached onefile with per-entry CRC32
        (False, True),    # --onefile-as-archive
        (True, True),     # --onefile-as-archive + cached
    ]
    if not compressed:
        attempts = [(False, False), (True, False)]

    last_error = None
    for file_checksums, per_file_zstd in attempts:
        try:
            entries = _attempt(file_checksums, per_file_zstd)
            if entries:
                return {
                    "entries": entries,
                    "compressed": compressed,
                    "file_checksums": file_checksums,
                    "per_file_zstd": per_file_zstd,
                }
        except Exception as exc:
            last_error = exc
            continue
    raise ValueError("could not parse the Nuitka onefile payload: %s"
                     % (last_error or "unknown layout"))


def run_onefile_unpack(target, out_dir, max_file_size=None):
    """Statically unpack a Nuitka onefile binary. NEVER executes the target."""
    print_section("ONEFILE STATIC UNPACK (zero execution)")

    with open(target, "rb") as handle:
        data = handle.read()

    binfmt = _dv_detect_binfmt(data)
    candidates = _dv_onefile_payload_bytes(data, binfmt=binfmt)
    if not candidates:
        log_err("No Nuitka onefile payload (no 'KA' stream, no resource 27).")
        return None

    wide = binfmt == "PE"
    result = None
    source = None
    payload = None
    last_error = None
    for payload, source in candidates:
        try:
            result = _dv_unpack_onefile_payload(
                payload, wide=wide, max_file_size=max_file_size)
            if result and result.get("entries"):
                break
        except Exception as exc:
            last_error = exc
            result = None
            continue
    if result is None:
        log_err("Onefile payload candidates found but none parsed: "
                f"{last_error or 'unknown layout'}")
        return None
    log_ok(f"Onefile payload located via {source} "
           f"({len(payload):,} bytes, indicator {payload[2:3].decode()})")
    entries = result["entries"]

    payload_dir = os.path.join(out_dir, "onefile_payload")
    os.makedirs(payload_dir, exist_ok=True)

    manifest = {
        "target": os.path.basename(target),
        "binfmt": binfmt,
        "payload_source": source,
        "compressed": result["compressed"],
        "file_checksums": result["file_checksums"],
        "per_file_zstd": result["per_file_zstd"],
        "entry_count": len(entries),
        "files": [],
    }

    log(f"Unpacking {len(entries)} entries to {payload_dir}")
    main_candidate = None
    for index, entry in enumerate(entries):
        safe = entry.get("safe_path")
        record = {
            "index": index,
            "name": entry["name"],
            "is_symlink": entry["is_symlink"],
            "exec_bit": entry["exec_bit"],
            "size": entry["size"],
        }
        if entry["is_symlink"]:
            record["link_target"] = entry.get("link_target")
        if safe is None:
            record["skipped_unsafe_name"] = True
            manifest["files"].append(record)
            continue

        dest = os.path.join(payload_dir, safe)
        os.makedirs(os.path.dirname(dest) or payload_dir, exist_ok=True)
        if entry["is_symlink"]:
            record["written"] = False
            try:
                link = entry.get("link_target") or ""
                if link and not os.path.isabs(link) \
                        and ".." not in link.replace("\\", "/").split("/"):
                    if os.path.lexists(dest):
                        os.unlink(dest)
                    os.symlink(link, dest)
                    record["written"] = True
            except Exception:
                pass
        else:
            with open(dest, "wb") as handle:
                handle.write(entry.get("data") or b"")
            record["written"] = True
            if entry.get("exec_bit"):
                try:
                    os.chmod(dest, os.stat(dest).st_mode | 0o111)
                except Exception:
                    pass
            if main_candidate is None:
                head = (entry.get("data") or b"")[:16]
                if head[:2] == b"MZ" or head[:4] == b"\x7fELF":
                    main_candidate = {
                        "name": entry["name"],
                        "path": os.path.relpath(dest, out_dir),
                        "size": entry["size"],
                        "binfmt": _dv_detect_binfmt(head),
                    }
        manifest["files"].append(record)

    if main_candidate is None and entries:
        first = entries[0]
        main_candidate = {
            "name": first["name"],
            "path": os.path.join("onefile_payload",
                                 first.get("safe_path") or first["name"]),
            "size": first["size"],
            "binfmt": None,
        }
    manifest["main_binary"] = main_candidate

    manifest_path = os.path.join(out_dir, "ONEFILE_MANIFEST.json")
    with open(manifest_path, "w", encoding="utf-8") as handle:
        json.dump(manifest, handle, indent=2, ensure_ascii=False)
        handle.write("\n")

    log_ok(f"Unpacked {len(entries)} entries (manifest: {manifest_path})")
    if main_candidate:
        log_ok(f"Main binary: {main_candidate['name']} "
               f"({main_candidate['size']:,} bytes)")
    return manifest


# ---------------------------------------------------------------------------
# Universal constants-blob location (PE resource / ELF / Mach-O / memory)
# ---------------------------------------------------------------------------

def _dv_blob_frame_ok(blob):
    """Validate the classic [crc32][size] frame of a DataComposer blob."""
    if not blob or len(blob) < 12:
        return False
    crc_stored, size_stored = struct.unpack_from("<II", blob, 0)
    if size_stored != len(blob) - 8:
        return False
    return (zlib.crc32(blob[8:]) & 0xFFFFFFFF) == crc_stored


def _dv_find_blob(target_path, data, binfmt=None):
    """Locate the DataComposer constants blob in any container format.

    Returns ``(blob_bytes, meta_dict)`` or ``(None, meta)``.

    Strategy order (most authoritative first):
      1. PE resource / onefile child resolution (existing proven code)
      2. ELF symbol table: every resource mode (incbin / linker / c23_embed /
         code) exports ``constant_bin_data`` (+ end/size companions) — an
         exact, CRC-free carve that also covers the HEADERLESS blob format
         introduced by Nuitka 4.1 (no more [crc][size] frame).
      3. CRC32-verified raw scan (classic <= 4.0 format)
      4. Headerless chunk-table anchor walk
      5. Unvalidated commercial/protected candidate (last resort)
    """
    meta = {"method": None}

    # 1) Windows PE: dedicated resource + onefile resolution (existing code).
    if binfmt == "PE":
        blob = extract_pe_constants_blob(target_path, pe_data=data)
        if blob:
            meta["method"] = "pe-resource-or-embedded"
            return blob, meta
        return None, meta

    # 2) ELF: exact carve through the symbol table.
    blob = _dv_find_blob_by_symbols(data)
    if blob:
        meta["method"] = "elf-symbols"
        return blob, meta

    # 3) Classic (<= 4.0) framed blob: CRC32-verified raw scan.  The scan's
    #    commercial heuristic can return an UNVALIDATED candidate for
    #    protected builds — verify the frame and keep it only as a last
    #    resort after the headerless anchor walk.
    raw_candidate = _find_blob_in_raw_bytes(data)
    if raw_candidate and _dv_blob_frame_ok(raw_candidate):
        meta["method"] = "raw-crc-scan"
        return raw_candidate, meta

    # 4) Headerless variant (Nuitka >= 4.1): the blob starts directly at the
    #    chunk table (".bytecode" or the empty global-chunk name first).
    anchored = _dv_find_blob_by_anchor(data)
    if anchored:
        meta["method"] = "chunk-table-anchor"
        return anchored, meta

    # 5) Last resort: the unvalidated commercial/protected candidate.
    if raw_candidate:
        meta["method"] = "raw-scan-unvalidated"
        meta["unvalidated"] = True
        return raw_candidate, meta

    return None, meta


# ---------------------------------------------------------------------------
# Minimal ELF parser (no external deps): symbols + vaddr mapping
# ---------------------------------------------------------------------------

def _dv_elf_parse_header(data):
    """Parse a little-endian ELF header; returns a dict or None."""
    if len(data) < 52 or data[:4] != b"\x7fELF":
        return None
    is_64 = data[4] == 2
    little = data[5] == 1
    if not little:
        return None  # big-endian ELF is not supported by this carver
    try:
        if is_64:
            (e_type, e_machine, _e_version, _e_entry, e_phoff, e_shoff,
             _e_flags, _e_ehsize, e_phentsize, e_phnum, e_shentsize,
             e_shnum, e_shstrndx) = struct.unpack_from("<HHIQQQIHHHHHH",
                                                       data, 16)
        else:
            (e_type, e_machine, _e_version, _e_entry, e_phoff, e_shoff,
             _e_flags, _e_ehsize, e_phentsize, e_phnum, e_shentsize,
             e_shnum, e_shstrndx) = struct.unpack_from("<HHIIIIIHHHHHH",
                                                       data, 16)
        return {
            "is64": is_64, "phoff": e_phoff, "shoff": e_shoff,
            "phentsize": e_phentsize, "phnum": e_phnum,
            "shentsize": e_shentsize, "shnum": e_shnum,
            "shstrndx": e_shstrndx,
        }
    except Exception:
        return None


def _dv_elf_sections(data, elf):
    """Yield ``(sh_name, sh_type, sh_addr, sh_offset, sh_size, sh_link)``."""
    is64 = elf["is64"]
    fmt = "<IIQQQQIIQQ" if is64 else "<IIIIIIIIII"
    fmt_size = struct.calcsize(fmt)
    for index in range(elf["shnum"]):
        off = elf["shoff"] + index * elf["shentsize"]
        if off + fmt_size > len(data):
            return
        fields = struct.unpack_from(fmt, data, off)
        if is64:
            (sh_name, sh_type, _sh_flags, sh_addr, sh_offset, sh_size,
             sh_link, _sh_info, _sh_addralign, _sh_entsize) = fields
        else:
            (sh_name, sh_type, _sh_flags, sh_addr, sh_offset, sh_size,
             sh_link, _sh_info, _sh_addralign, _sh_entsize) = fields
        yield {
            "index": index, "name_off": sh_name, "type": sh_type,
            "addr": sh_addr, "offset": sh_offset, "size": sh_size,
            "link": sh_link,
        }


def _dv_elf_symbols(data, elf, section_types=(2,)):
    """Return ``[(name, value, size), ...]`` from symtab/dynsym sections."""
    sections = list(_dv_elf_sections(data, elf))

    # Section-header string table for section names.
    shstr = None
    if 0 <= elf["shstrndx"] < len(sections):
        sec = sections[elf["shstrndx"]]
        if sec["offset"] + sec["size"] <= len(data):
            shstr = data[sec["offset"]:sec["offset"] + sec["size"]]

    def _sec_name(sec):
        if shstr is None:
            return ""
        end = shstr.find(b"\x00", sec["name_off"])
        if end < 0:
            return ""
        return shstr[sec["name_off"]:end].decode("utf-8", errors="replace")

    symbols = []
    for sec in sections:
        if sec["type"] not in section_types:  # SHT_SYMTAB / SHT_DYNSYM
            continue
        strtab_sec = None
        if 0 <= sec["link"] < len(sections):
            strtab_sec = sections[sec["link"]]
        if strtab_sec is None:
            continue
        strtab_off = strtab_sec["offset"]
        strtab_size = strtab_sec["size"]
        if strtab_off + strtab_size > len(data):
            continue
        strtab = data[strtab_off:strtab_off + strtab_size]

        is64 = elf["is64"]
        fmt = "<IBBHQQ" if is64 else "<IIII"
        fmt_size = struct.calcsize(fmt)
        count = sec["size"] // fmt_size
        for index in range(min(count, 4_000_000)):
            off = sec["offset"] + index * fmt_size
            if off + fmt_size > len(data):
                break
            fields = struct.unpack_from(fmt, data, off)
            if is64:
                st_name, _st_info, _st_other, _st_shndx, st_value, st_size \
                    = fields
            else:
                st_name, _st_value, _st_size, _st_info, _st_other = fields
                st_value, st_size = _st_value, _st_size
            if st_name == 0:
                continue
            end = strtab.find(b"\x00", st_name)
            if end < 0:
                continue
            name = strtab[st_name:end].decode("utf-8", errors="replace")
            if name:
                symbols.append((name, st_value, st_size))
    return symbols


def _dv_elf_vaddr_to_offset(data, elf, vaddr):
    """Map a virtual address to a file offset through PT_LOAD segments."""
    is64 = elf["is64"]
    fmt = "<IIQQQQQQ" if is64 else "<IIIIIIII"
    fmt_size = struct.calcsize(fmt)
    for index in range(elf["phnum"]):
        off = elf["phoff"] + index * elf["phentsize"]
        if off + fmt_size > len(data):
            break
        fields = struct.unpack_from(fmt, data, off)
        if is64:
            p_type, _p_flags, p_offset, p_vaddr, _p_paddr, p_filesz, \
                _p_memsz, _p_align = fields
        else:
            p_type, p_offset, p_vaddr, _p_paddr, p_filesz, _p_memsz, \
                _p_flags, _p_align = fields
        if p_type != 1:  # PT_LOAD
            continue
        if p_vaddr <= vaddr < p_vaddr + p_filesz:
            return p_offset + (vaddr - p_vaddr)
    return None


def _dv_blob_walk_headerless(data, start, end_bound):
    """Walk the headerless DataComposer chunk table from *start*.

    Returns ``(end_pos, chunk_count)`` when the walk validates, else None.
    Chunk layout per record: ``name\\0`` + ``u32 size`` + data.  The empty
    global-constants chunk name is legal, but runs of empty zero-size
    records are treated as padding terminators.
    """
    n = min(len(data), end_bound)
    pos = start
    chunks = 0
    real_chunks = 0
    last_real_end = None

    while pos + 4 <= n:
        name_end = data.find(b"\x00", pos, min(pos + 513, n))
        if name_end < 0:
            break
        raw_name = bytes(data[pos:name_end])
        size_pos = name_end + 1
        if size_pos + 4 > n:
            break
        chunk_size = struct.unpack_from("<I", data, size_pos)[0]
        chunk_end = size_pos + 4 + chunk_size
        if chunk_end > n:
            break

        if raw_name == b"" and chunk_size == 0:
            # Padding: stop here, keep the end before the padding run.
            break

        try:
            name = raw_name.decode("utf-8")
        except UnicodeDecodeError:
            break
        # The empty name is the global-constants chunk and perfectly legal.
        if name and not _BLOB_MODNAME_RE.match(name):
            break

        pos = chunk_end
        chunks += 1
        if name:
            real_chunks += 1
            last_real_end = pos
        if chunks > 8192:
            return None

    if real_chunks < 1 or last_real_end is None:
        return None
    return last_real_end, chunks


def _dv_wrap_headerless(carved):
    """Attach a synthesized [crc][size] frame for the classic parsers."""
    crc = zlib.crc32(carved) & 0xFFFFFFFF
    return struct.pack("<II", crc, len(carved)) + carved


def _dv_find_blob_by_symbols(data):
    """Exact constants-blob carve via the ELF symbol table.

    Every Linux resource mode emits delimiting symbols:
      * incbin:      constant_bin_data / constant_bin_end / constant_bin_size
      * linker:      constant_bin_data (alias of _binary_*_constants_bin_start)
                     plus the auto-generated _binary_*_start/_end pair
      * c23_embed / code: constant_bin_data array with a real st_size
    """
    elf = _dv_elf_parse_header(data)
    if elf is None:
        return None

    try:
        symbols = _dv_elf_symbols(data, elf)
    except Exception:
        return None
    if not symbols:
        return None

    by_name = {}
    for name, value, size in symbols:
        by_name.setdefault(name, (value, size))

    candidates = []  # (start_vaddr, size_bytes)

    start_val = by_name.get("constant_bin_data")
    if start_val is not None:
        start_vaddr, start_size = start_val
        if start_size and start_size > 32:
            candidates.append((start_vaddr, start_size))
        # incbin end symbol
        end_entry = by_name.get("constant_bin_end")
        if end_entry is not None:
            end_vaddr = end_entry[0]
            if end_vaddr > start_vaddr:
                candidates.append((start_vaddr, end_vaddr - start_vaddr))
        # incbin size symbol (absolute, value == byte count)
        size_entry = by_name.get("constant_bin_size")
        if size_entry is not None and size_entry[0] > 32 \
                and size_entry[0] < _DV_MAX_BLOB_SCAN:
            candidates.append((start_vaddr, size_entry[0]))

    # Linker mode: _binary_<mangled>_constants_bin_start / _end
    link_start = link_end = None
    for name, value, _size in symbols:
        if "constants_bin" not in name:
            continue
        if name.endswith("_start") and link_start is None:
            link_start = value
        elif name.endswith("_end") and link_end is None:
            link_end = value
    if link_start is not None and link_end is not None \
            and link_end > link_start:
        candidates.append((link_start, link_end - link_start))
        if start_val is None:
            pass

    seen = set()
    for start_vaddr, size in candidates:
        if size <= 32 or size > _DV_MAX_BLOB_SCAN:
            continue
        if (start_vaddr, size) in seen:
            continue
        seen.add((start_vaddr, size))
        offset = _dv_elf_vaddr_to_offset(data, elf, start_vaddr)
        if offset is None or offset + size > len(data):
            continue
        carved = bytes(data[offset:offset + size])
        walk = _dv_blob_walk_headerless(carved, 0, len(carved))
        if walk is None:
            # Classic (<= 4.0) framed blob: verify via its own header.
            if len(carved) >= 8:
                crc_stored, size_stored = struct.unpack_from("<II", carved, 0)
                if size_stored == len(carved) - 8 and (
                        zlib.crc32(carved[8:]) & 0xFFFFFFFF) == crc_stored:
                    return carved
            continue
        end_pos, chunk_count = walk
        blob_data = carved[:end_pos]
        log_ok(f"Constants blob carved via ELF symbols at file offset "
               f"0x{offset:X} ({end_pos:,} bytes, {chunk_count} chunks)")
        return _dv_wrap_headerless(blob_data)

    return None


def _dv_find_blob_by_anchor(data):
    """Carve a headerless constants blob by anchoring on chunk names.

    Used when the ELF symbol table is stripped.  The DataComposer chunk
    table is ``name\\0 + u32 size + data`` repeated; anchors are the
    '.bytecode' marker (standalone builds) and the empty global-chunk
    name.  A candidate is accepted when the walk validates and spans a
    meaningful portion of the file.
    """
    n = len(data)
    if n < 64:
        return None

    best = None
    for marker in (b".bytecode\x00", b"\x00"):
        start = 0
        while True:
            offset = data.find(marker, start)
            if offset < 0 or offset > n - 16:
                break
            start = offset + 1
            walk = _dv_blob_walk_headerless(data, offset, n)
            if walk is None:
                continue
            end_pos, chunk_count = walk
            span = end_pos - offset
            if span < 128:
                continue
            if best is None or span > best[1]:
                best = (offset, span, chunk_count)
        if best:
            break

    if best is None:
        return None
    offset, span, chunk_count = best
    carved = bytes(data[offset:offset + span])
    log_ok(f"Headerless blob carved at 0x{offset:X} ({span:,} bytes, "
           f"{chunk_count} chunks)")
    return _dv_wrap_headerless(carved)


# ---------------------------------------------------------------------------
# Target Python version detection (ELF / Mach-O aware)
# ---------------------------------------------------------------------------

def _dv_detect_python_version(data, blob=None, binfmt=None):
    """Best-effort CPython ABI detection for any binary container."""
    # Reuse the existing PE/raw heuristics — the raw-scan patterns inside
    # detect_python_version_from_pe also match libpython strings in ELF.
    version = detect_python_version_from_pe(data)
    if version:
        return version
    version = _ndl_detect_python_from_blob(data)
    if version:
        return version
    if blob:
        version = _ndl_detect_python_from_blob(blob)
        if version:
            return version
        # Marshal'd code objects in the .bytecode chunk are version locked;
        # the existing xdis probe scores candidate magics against the data.
        try:
            for name, chunk in (parse_blob_modules(blob) or []):
                if name == ".bytecode":
                    version = xdis_detect_version_from_marshal(chunk)
                    if version:
                        return version
        except Exception:
            pass
    return None


# ---------------------------------------------------------------------------
# ".files" chunk extraction (embedded data files)
# ---------------------------------------------------------------------------

def _dv_extract_files_chunk(chunk, out_dir):
    """Dump BlobData ('X') entries of the '.files' chunk.

    The mapping to real filenames lives in generated C code, so entries are
    emitted with their loader index plus any recognizable magic prefix.
    """
    files_dir = os.path.join(out_dir, "devirt_files")
    os.makedirs(files_dir, exist_ok=True)
    records = []

    entries = list(_iter_bytecode_marshaled(chunk))
    for index, blob_data in entries:
        name_hint = ""
        head = blob_data[:512]
        if head.startswith(b"PK\x03\x04"):
            name_hint = "_zip"
        elif head.startswith(b"\x1f\x8b"):
            name_hint = "_gz"
        elif head.startswith(b"\x89PNG"):
            name_hint = "_png"
        elif head.startswith(b"\xff\xd8\xff"):
            name_hint = "_jpg"
        elif head[:2] == b"BM":
            name_hint = "_bmp"
        elif head.startswith(b"{") or head.startswith(b"["):
            name_hint = "_json"
        out_path = os.path.join(files_dir, f"file_{index:04d}{name_hint}.bin")
        with open(out_path, "wb") as handle:
            handle.write(blob_data)
        records.append({
            "index": index,
            "size": len(blob_data),
            "path": os.path.relpath(out_path, out_dir).replace(os.sep, "/"),
            "magic_hint": name_hint or None,
        })
    return records


# ---------------------------------------------------------------------------
# JSON-safe constant serialization
# ---------------------------------------------------------------------------

def _dv_json_safe(value, depth=0, max_depth=12):
    """Convert a decoded constants value into JSON-safe data."""
    if depth > max_depth:
        return repr(value)[:256]
    if value is None or isinstance(value, (bool, int, float, str)):
        if isinstance(value, float) and (isnan(value) or isinf(value)):
            return repr(value)
        if isinstance(value, str) and len(value) > 4096:
            return value[:4096] + f"...(+{len(value) - 4096} chars)"
        return value
    if isinstance(value, bytes):
        if len(value) > 2048:
            return {"_bytes_truncated": len(value),
                    "head_hex": value[:64].hex()}
        return {"_bytes": value.hex()}
    if isinstance(value, (list, tuple)):
        return [_dv_json_safe(item, depth + 1, max_depth)
                for item in value[:4096]]
    if isinstance(value, (set, frozenset)):
        return {"_set": [_dv_json_safe(item, depth + 1, max_depth)
                         for item in list(value)[:2048]]}
    if isinstance(value, dict):
        result = {}
        for key, item in list(value.items())[:2048]:
            safe_key = key if isinstance(key, (bool, int, float, str)) \
                else repr(key)[:128]
            result[str(safe_key)] = _dv_json_safe(item, depth + 1, max_depth)
        return result
    if isinstance(value, range):
        return {"_range": [value.start, value.stop, value.step]}
    if isinstance(value, slice):
        return {"_slice": [value.start, value.stop, value.step]}
    if isinstance(value, complex):
        return {"_complex": [value.real, value.imag]}
    return repr(value)[:256]


def _dv_summarize_constants(constants, limit=64):
    """Human-oriented digest of a module constants pool."""
    strings, numbers, others = [], [], 0
    def _walk(val, depth=0):
        nonlocal others
        if depth > 6:
            return
        if isinstance(val, str):
            if val and len(val) <= 256 and len(strings) < limit:
                strings.append(val)
        elif isinstance(val, (int, float, bool)) and not isinstance(val, bool):
            if len(numbers) < limit:
                numbers.append(val)
        elif isinstance(val, (bytes, bytearray)):
            others += 1
        elif isinstance(val, (list, tuple, set, frozenset)):
            for item in val[:256]:
                _walk(item, depth + 1)
        elif isinstance(val, dict):
            for key, item in list(val.items())[:256]:
                _walk(key, depth + 1)
                _walk(item, depth + 1)
        else:
            others += 1
    for value in (constants or [])[:8192]:
        _walk(value)
    return {
        "strings": strings[:limit],
        "numbers": numbers[:limit],
        "other_count": others,
    }


# ---------------------------------------------------------------------------
# The DEVIRT pipeline
# ---------------------------------------------------------------------------

def run_devirt_mode(target, out_dir, *, extract_pyc=True, extract_constants=True,
                    extract_files=True, decompile=False, only=None,
                    blob_override=None, blob_source_label=None,
                    python_version=None, max_file_size=None):
    """Devirtualize a Nuitka binary statically. Returns a report dict.

    ``blob_override`` lets the trigger mode feed a memory-dumped (already
    decoded) constants blob straight into this pipeline.
    """
    print_section("DEVIRT: STATIC REMATERIALIZATION (zero execution)")

    report = {
        "target": os.path.basename(target),
        "mode": "devirt",
        "python_version": None,
        "nuitka_edition": None,
        "blob": {},
        "onefile": None,
        "bytecode_modules": 0,
        "native_modules": [],
        "files_chunk": None,
        "pyc": {},
        "decompiled": 0,
        "notes": [],
    }

    os.makedirs(out_dir, exist_ok=True)

    with open(target, "rb") as handle:
        data = handle.read()

    binfmt = _dv_detect_binfmt(data)
    report["binfmt"] = binfmt
    log(f"Container format: {binfmt or 'unknown'} ({len(data):,} bytes)")

    # --- onefile resolution (fully static) ---------------------------------
    effective_data = data
    effective_name = os.path.basename(target)
    if blob_override is None:
        onefile_manifest = None
        try:
            candidates = _dv_onefile_payload_bytes(data, binfmt=binfmt)
        except Exception:
            candidates = []
        if candidates:
            try:
                onefile_manifest = run_onefile_unpack(
                    target, out_dir, max_file_size=max_file_size)
            except Exception as exc:
                log_warn(f"Onefile static unpack failed: {exc}")
                report["notes"].append(f"onefile unpack failed: {exc}")
        if onefile_manifest is not None:
            report["onefile"] = {
                key: value for key, value in onefile_manifest.items()
                if key != "files"}
            main_binary = onefile_manifest.get("main_binary")
            if main_binary and main_binary.get("path"):
                child_path = os.path.join(out_dir, main_binary["path"])
                if os.path.isfile(child_path):
                    with open(child_path, "rb") as handle:
                        effective_data = handle.read()
                    effective_name = main_binary.get("name") or effective_name
                    report["effective_target"] = effective_name
                    log_ok(f"Continuing devirt on onefile child "
                           f"{effective_name} ({len(effective_data):,} bytes)")
    else:
        report["effective_target"] = effective_name

    # --- constants blob -----------------------------------------------------
    if blob_override is not None:
        blob = bytes(blob_override)
        report["blob"] = {
            "method": blob_source_label or "trigger-memory-dump",
            "size": len(blob),
        }
        log_ok(f"Constants blob supplied by trigger memory dump "
               f"({len(blob):,} bytes)")
    else:
        blob, blob_meta = _dv_find_blob(target, effective_data, binfmt)
        if not blob:
            log_err("No Nuitka constants blob found in this binary.")
            report["notes"].append("constants blob not found")
            _dv_write_devirt_manifest(out_dir, report)
            return report
        report["blob"] = dict(blob_meta)
        report["blob"]["size"] = len(blob)
        log_ok(f"Constants blob: {len(blob):,} bytes via {blob_meta['method']}")

    # --- commercial / protected blob normalization --------------------------
    try:
        bypass = CommercialBypass()
        raw_is_enc = bool(blob) and (
            bypass.is_blob_encrypted(blob) or bypass.has_commercial_digest(blob))
    except Exception:
        raw_is_enc = False
    if raw_is_enc:
        report["blob"]["commercial_protected"] = True
        decrypted = _decrypt_blob_if_encrypted(
            target, blob,
            pe_data=effective_data if binfmt == "PE" else None)
        if decrypted:
            blob = decrypted
            report["blob"]["decrypted"] = True
            report["blob"]["decrypted_size"] = len(blob)
            log_ok(f"Commercial blob decrypted ({len(blob):,} bytes)")
        else:
            log_warn("Commercial/protected blob could not be decrypted "
                     "statically — the --trigger runtime mode can capture the "
                     "decoded blob from process memory instead.")
            report["notes"].append(
                "protected blob; consider --trigger to capture the decoded "
                "blob from memory without executing the payload")

    # --- python version ------------------------------------------------------
    py_ver = python_version or _NDL_TARGET_PYTHON_OVERRIDE \
        or _dv_detect_python_version(effective_data, blob=blob, binfmt=binfmt)
    if py_ver is None:
        log_err("Cannot determine the target Python version; "
                "use --target-python X.Y")
        report["notes"].append("python version unknown")
        _dv_write_devirt_manifest(out_dir, report)
        return report
    set_nuitka_target_python(py_ver)
    report["python_version"] = f"{py_ver[0]}.{py_ver[1]}"
    log_ok(f"Target Python: {py_ver[0]}.{py_ver[1]}")

    report["nuitka_edition"] = detect_nuitka_edition(effective_data, blob)

    # --- chunk table ---------------------------------------------------------
    diagnostics = {}
    modules_or_chunks = parse_blob_modules(blob, None, strict=False,
                                           diagnostics=diagnostics)
    if not modules_or_chunks:
        # Retry with the commercial bypass for protected name tables.
        modules_or_chunks = parse_blob_modules(
            blob, CommercialBypass() if raw_is_enc else None,
            strict=False, diagnostics=diagnostics)
    if not modules_or_chunks:
        log_err("Constants blob found but no chunks parsed: "
                f"{diagnostics.get('stop_reason')}")
        report["notes"].append(
            f"blob chunk parsing failed: {diagnostics.get('stop_reason')}")
        _dv_write_devirt_manifest(out_dir, report)
        return report

    chunks = {}
    for name, chunk_data in modules_or_chunks:
        chunks[name] = chunk_data
    report["chunks"] = {name: len(chunk) for name, chunk in chunks.items()}
    log_ok(f"Parsed {len(chunks)} blob chunks "
           f"(global: {'yes' if '' in chunks else 'no'}, "
           f"bytecode: {'yes' if '.bytecode' in chunks else 'no'}, "
           f"files: {'yes' if '.files' in chunks else 'no'})")

    # --- 1) rematerialize the original .pyc modules --------------------------
    if extract_pyc and ".bytecode" in chunks:
        bytecode_chunk = chunks[".bytecode"]
        count = struct.unpack_from("<H", bytecode_chunk, 0)[0] \
            if len(bytecode_chunk) >= 2 else 0
        log(f"'.bytecode' chunk: {count} marshal'd code objects — "
            f"these are the ORIGINAL compiled Python modules")
        if count:
            extracted, pyc_manifest = extract_bytecode_modules(
                bytecode_chunk, out_dir, py_ver)
            report["bytecode_modules"] = extracted
            report["pyc"] = {
                "count": extracted,
                "manifest": "BYTECODE_MANIFEST.json",
                "pyc_dir": "bytecode_pyc",
                "marshal_dir": "bytecode_marshal_raw",
            }
            if decompile and extracted:
                report["decompiled"] = _dv_decompile_extracted(
                    out_dir, py_ver, pyc_manifest)
        elif extract_constants:
            report["notes"].append(
                "no bytecode modules in this build (all modules were "
                "translated to native code)")

    # --- 2) '.files' chunk ----------------------------------------------------
    if extract_files and ".files" in chunks:
        try:
            files_records = _dv_extract_files_chunk(chunks[".files"], out_dir)
            report["files_chunk"] = {
                "count": len(files_records),
                "dir": "devirt_files",
                "files": files_records[:512],
            }
            log_ok(f"'.files' chunk: extracted {len(files_records)} embedded "
                   f"data files to devirt_files/")
        except Exception as exc:
            log_warn(f"'.files' chunk extraction failed: {exc}")

    # --- 3) per-module constants + code object maps ---------------------------
    if extract_constants:
        modules_dir = os.path.join(out_dir, "devirt_modules")
        os.makedirs(modules_dir, exist_ok=True)
        module_reports = []
        only_patterns = None
        if only:
            only_patterns = [part.strip() for part in only.split(",")
                             if part.strip()]

        for name, chunk_data in modules_or_chunks:
            if name in ("", ".bytecode", ".files", ".bytecode_data"):
                continue
            if only_patterns and not module_matches_patterns(name, only_patterns):
                continue
            entry = {"module": name, "chunk_size": len(chunk_data)}

            try:
                constants = parse_module_constants(
                    chunk_data, python_version=py_ver)
                entry["constants_count"] = len(constants)
                entry["constants_digest"] = _dv_summarize_constants(constants)

                code_objects = extract_code_object_map(
                    name, chunk_data, python_version=py_ver)
                entry["code_objects"] = [
                    {key: co.get(key) for key in
                     ("name", "qualname", "line", "argcount", "args",
                      "kind", "varnames", "freevars")}
                    for co in code_objects[:4096]]
                entry["code_object_count"] = len(code_objects)

                safe_name = re.sub(r"[^A-Za-z0-9_.-]", "_", name) or "module"
                const_path = os.path.join(
                    modules_dir, safe_name + ".constants.json")
                payload = {
                    "module": name,
                    "python_version": report["python_version"],
                    "constants": _dv_json_safe(list(constants)),
                }
                with open(const_path, "w", encoding="utf-8") as handle:
                    json.dump(payload, handle, indent=1, ensure_ascii=False,
                              default=str)
                    handle.write("\n")
                entry["constants_file"] = os.path.relpath(
                    const_path, out_dir).replace(os.sep, "/")
            except Exception as exc:
                entry["error"] = str(exc)[:256]

            try:
                constants_for_secrets = parse_module_constants(
                    chunk_data, python_version=py_ver)
                findings = scan_for_secrets(list(constants_for_secrets), name)
                if findings:
                    entry["secrets"] = findings[:64]
            except Exception:
                pass

            module_reports.append(entry)

        report["native_modules"] = module_reports
        native_count = len(module_reports)
        with_code = sum(1 for entry in module_reports
                        if entry.get("code_object_count"))
        log_ok(f"Native-compiled modules: {native_count} "
               f"({with_code} with code-object maps) -> devirt_modules/")

    if not report.get("bytecode_modules") and extract_constants:
        report["notes"].append(
            "native-compiled modules keep NO bytecode in the binary: their "
            "logic exists only as compiled C (code objects carry metadata "
            "only). Use --live-decompile/--emit-all-source for native "
            "reconstruction; devirt provides constants + code-object maps.")

    _dv_write_devirt_manifest(out_dir, report)
    return report


def _dv_write_devirt_manifest(out_dir, report):
    manifest_path = os.path.join(out_dir, "DEVIRT_MANIFEST.json")
    try:
        with open(manifest_path, "w", encoding="utf-8") as handle:
            json.dump(report, handle, indent=2, ensure_ascii=False,
                      default=str)
            handle.write("\n")
        log_ok(f"Manifest: {manifest_path}")
    except Exception as exc:
        log_warn(f"Could not write DEVIRT_MANIFEST.json: {exc}")


def _dv_decompile_extracted(out_dir, py_ver, pyc_manifest):
    """Optionally decompile every extracted .pyc to best-effort .py source."""
    print_section("DEVIRT: .pyc -> .py DECOMPILATION")
    decompilers = _detect_decompiler(py_ver)
    same_version = tuple((py_ver or ())[:2]) == sys.version_info[:2]
    if not decompilers:
        if same_version:
            log_warn("No external .pyc decompiler available — falling back "
                     "to the built-in bytecode reader (devirt_source/*.dis). "
                     "Install pycdc for full source recovery; the .pyc files "
                     "themselves are complete and version-correct.")
        else:
            log_warn("No .pyc decompiler available (install pycdc, or "
                     "decompyle3/uncompyle6). The .pyc files themselves are "
                     "complete and version-correct.")
            return 0
    source_dir = os.path.join(out_dir, "devirt_source")
    os.makedirs(source_dir, exist_ok=True)
    ok = 0
    entries = (pyc_manifest or {}).values() if isinstance(pyc_manifest, dict) else []
    for entry in entries:
        pyc_rel = (entry or {}).get("pyc_path")
        if not pyc_rel:
            continue
        pyc_path = os.path.join(out_dir, pyc_rel)
        out_py = os.path.join(source_dir, os.path.splitext(pyc_rel)[0] + ".py")
        os.makedirs(os.path.dirname(out_py) or source_dir, exist_ok=True)
        try:
            if decompilers and _decompile_pyc(pyc_path, out_py, decompilers):
                ok += 1
                continue
        except Exception:
            pass
        # Built-in fallback (same-version targets only): readable
        # pseudo-source from the bytecode, no external tool required.
        if same_version:
            try:
                dis_path = out_py + ".dis"
                if _pyc_dis(pyc_path, dis_path):
                    ok += 1
            except Exception:
                pass
    log_ok(f"Decompiled {ok} .pyc files to devirt_source/")
    return ok


def run_devirt_cli(target, out_dir, args):
    """CLI adapter for --devirt."""
    report = run_devirt_mode(
        target, out_dir,
        extract_pyc=not getattr(args, "devirt_no_pyc", False),
        extract_constants=not getattr(args, "devirt_no_constants", False),
        extract_files=not getattr(args, "devirt_no_files", False),
        decompile=bool(getattr(args, "devirt_decompile", False)),
        only=getattr(args, "only", None),
        max_file_size=getattr(args, "onefile_max_bytes", None),
    )
    ok = bool(report.get("bytecode_modules")) or bool(
        report.get("native_modules")) or bool(report.get("files_chunk"))
    return 0 if ok else 1


# ---------------------------------------------------------------------------
# TRIGGER MODE — runtime capture with the payload neutralized
# ---------------------------------------------------------------------------
#
# The trigger ("triggeratore") runs the target under gdb just long enough to
# reach a point where the constants blob is decoded in memory but NO module
# code (not even "__parents_main__") has executed:
#
#     Py_Initialize
#       -> loadConstantsBlob(".bytecode")   <- DECODE() applied here
#       -> registerMetaPathBasedLoader      <- BREAKPOINT (cross-TU call,
#                                              cannot be inlined away)
#     createGlobalConstants
#     EXECUTE_MAIN_MODULE                   <- never reached: we kill first
#
# At the breakpoint we dump the decoded constants blob straight from
# process memory, then KILL the process.  The payload never runs.  The
# captured blob feeds run_devirt_mode() like any static blob, which defeats
# in-memory/commercial blob protection that is opaque on disk.

_DV_TRIGGER_BREAKPOINTS = (
    "registerMetaPathBasedLoader",   # external symbol, called during init
    "EXECUTE_MAIN_MODULE",           # static, many call sites, never inlined
    "modulecode___main__",           # main module entry (module mode fallback)
)


def _dv_kill_pid(pid):
    """Best-effort, portable SIGKILL of a leftover inferior process."""
    if not pid or pid <= 1:
        return
    try:
        os.kill(pid, 9)
        return
    except Exception:
        pass
    try:
        subprocess.run(["taskkill", "/F", "/PID", str(pid)],
                       capture_output=True, timeout=10)
    except Exception:
        pass


def _dv_gdb_available(gdb_path="gdb"):
    """Return the gdb executable when it exists and supports Python."""
    try:
        proc = run_external_tool([gdb_path, "--version"], timeout=15)
        if proc.returncode != 0 or not proc.stdout:
            return None
        head = proc.stdout.decode("utf-8", errors="replace")[:200]
        if "GNU gdb" not in head:
            return None
    except Exception:
        return None
    try:
        proc = run_external_tool(
            [gdb_path, "-batch", "-ex", "python print(1)"], timeout=15)
        if proc.returncode == 0:
            return gdb_path
    except Exception:
        pass
    return None


def _dv_gdb_query_symbols(gdb_path, target, symbols):
    """Ask gdb which symbols exist in the target (no execution happens)."""
    existing = []
    try:
        cmd = [gdb_path, "-batch", "-ex", "file %s" % _dv_shell_quote(target)]
        for symbol in symbols:
            cmd += ["-ex", "info address %s" % symbol]
        proc = run_external_tool(cmd, timeout=60)
        out = (proc.stdout or b"") + (proc.stderr or b"")
        text = out.decode("utf-8", errors="replace")
        for symbol in symbols:
            # "Symbol \"x\" is at 0x..." / "a function descriptor" = exists;
            # "No symbol \"x\" in current context." = missing.
            for line in text.splitlines():
                if ("Symbol \"%s\"" % symbol) in line:
                    if "No symbol" not in line and "not found" not in line.lower():
                        existing.append(symbol)
                    break
    except Exception:
        pass
    return existing


def _dv_shell_quote(path):
    """Quote a path for gdb's 'file' command (double quotes, escaped)."""
    return '"%s"' % str(path).replace("\\", "\\\\").replace('"', '\\"')


def _dv_build_trigger_gdb_script(target, out_dir, breakpoints, *,
                                 dump_regions=False, py_dump=False):
    """Generate the gdb command script for the trigger run."""
    trigger_dir = os.path.join(out_dir, "trigger")
    os.makedirs(trigger_dir, exist_ok=True)
    script_path = os.path.join(trigger_dir, "trigger.gdb")
    py_script_path = os.path.join(trigger_dir, "trigger_impl.py")

    py_code = _DV_TRIGGER_GDB_PYTHON.replace("@@OUT_DIR@@", trigger_dir.replace("\\", "\\\\"))
    py_code = py_code.replace("@@DUMP_REGIONS@@", "True" if dump_regions else "False")
    py_code = py_code.replace("@@PY_DUMP@@", "True" if py_dump else "False")
    with open(py_script_path, "w", encoding="utf-8") as handle:
        handle.write(py_code)

    lines = [
        "set confirm off",
        "set pagination off",
        "set verbose off",
        "set breakpoint pending off",
        "file %s" % _dv_shell_quote(target),
    ]
    for bp in breakpoints:
        lines.append("break %s" % bp)
    lines += [
        "run",
        "source %s" % _dv_shell_quote(py_script_path),
        "kill",
        "quit",
    ]
    with open(script_path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(lines) + "\n")
    return script_path, trigger_dir


# The gdb-embedded implementation. Runs while the inferior is stopped at the
# breakpoint; writes artifacts under the trigger dir and emits "NDL_TRIG ..."
# markers on stdout for the parent process to parse.
_DV_TRIGGER_GDB_PYTHON = r'''
import gdb
import os
import struct
import zlib

OUT_DIR = r"@@OUT_DIR@@"
DUMP_REGIONS = @@DUMP_REGIONS@@
PY_DUMP = @@PY_DUMP@@
MAX_BLOB = 512 * 1024 * 1024

inf = gdb.selected_inferior()


def emit(msg):
    gdb.write("NDL_TRIG " + msg + "\n")


def read_mem(addr, size):
    try:
        return bytes(inf.read_memory(addr, size))
    except Exception:
        return None


emit("PID=%d" % inf.pid)

# Safety verification: we must be STOPPED (not exited). If the target ran to
# completion the breakpoints were inlined away and nothing here is trusted.
stopped_at = None
try:
    frame = gdb.selected_frame()
    stopped_at = frame.name() or "0x%x" % frame.pc()
except Exception:
    stopped_at = None
emit("STOPPED_AT=%s" % stopped_at)
if stopped_at is None:
    emit("RESULT=NOT_STOPPED")

blob = None
blob_source = None

# 1) Preferred: the constant_bin pointer variable (assigned and DECODE()d
#    during the first loadConstantsBlob call, before our breakpoint).
try:
    value = gdb.parse_and_eval("constant_bin")
    addr = int(value.cast(gdb.lookup_type("unsigned long")))
    emit("CONSTANT_BIN=0x%x" % addr)
    header = read_mem(addr, 8)
    if header:
        crc_stored, size_stored = struct.unpack("<II", header)
        if 0 < size_stored <= MAX_BLOB:
            data = read_mem(addr, 8 + size_stored)
            if data:
                crc_actual = zlib.crc32(data[8:]) & 0xFFFFFFFF
                if crc_actual == crc_stored:
                    blob = data
                    blob_source = "constant_bin"
                    emit("BLOB_OK size=%d crc=0x%08x" % (size_stored, crc_stored))
                else:
                    emit("BLOB_CRC_MISMATCH size=%d" % size_stored)
        else:
            emit("BLOB_BAD_SIZE=%d" % size_stored)
except Exception as exc:
    emit("CONSTANT_BIN_ERROR=%s" % exc)

# 2) Authoritative CPython version, when exported.
try:
    ver = int(gdb.parse_and_eval("Py_Version"))
    emit("PY_VERSION_HEX=%x" % ver)
except Exception:
    pass

# 3) Optional Python-level dump executed in the *target* interpreter. This
#    only touches frozen/builtin modules (sys, gc, marshal) — never app code.
if PY_DUMP:
    try:
        code = (
            "import sys, gc, types\n"
            "out = %r\n"
            "with open(out + '/trigger_py.txt', 'w') as f:\n"
            "    f.write('version=' + sys.version + '\\n')\n"
            "    f.write('implementation=' + repr(sys.implementation) + '\\n')\n"
            "    f.write('modules=' + repr(sorted(sys.modules)) + '\\n')\n"
            "    code_objects = 0\n"
            "    for o in gc.get_objects():\n"
            "        if isinstance(o, types.CodeType) and o.co_code:\n"
            "            code_objects += 1\n"
            "    f.write('code_objects_with_bytecode=%d\\n' % code_objects)\n"
        ) % (OUT_DIR,)
        escaped = code.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
        gdb.parse_and_eval('(int)PyRun_SimpleString("%s")' % escaped)
        emit("PY_DUMP=OK")
    except Exception as exc:
        emit("PY_DUMP_ERROR=%s" % exc)

# 4) Fallback: dump writable memory regions for offline CRC scanning.
region_count = 0
if blob is None and DUMP_REGIONS:
    try:
        mappings = gdb.execute("info proc mappings", to_string=True)
        for line in mappings.splitlines():
            parts = line.split()
            if len(parts) < 2:
                continue
            try:
                start = int(parts[0], 16)
                end = int(parts[1], 16)
            except ValueError:
                continue
            size = end - start
            if size <= 0 or size > 256 * 1024 * 1024:
                continue
            # Prefer writable regions; keep parsing tolerant across gdb
            # versions (perms column may be absent).
            writable = any(("w" in token and "-" in token and
                            len(token) in (4, 5)) for token in parts[2:])
            if not writable and parts[-1].startswith("["):
                writable = parts[-1] in ("[heap]", "[stack]")
            if not writable:
                continue
            region_count += 1
            if region_count > 96:
                break
            path = os.path.join(OUT_DIR, "region_%03d.bin" % region_count)
            try:
                gdb.execute("dump binary memory %s 0x%x 0x%x"
                            % (path, start, end))
            except Exception:
                pass
        emit("REGIONS_DUMPED=%d" % region_count)
    except Exception as exc:
        emit("REGIONS_ERROR=%s" % exc)

if blob is not None:
    out_path = os.path.join(OUT_DIR, "trigger_blob.bin")
    with open(out_path, "wb") as handle:
        handle.write(blob)
    emit("BLOB_WRITTEN=%s" % out_path)

emit("RESULT=%s" % ("OK" if (blob is not None or region_count) else "NO_BLOB"))
'''



# ---------------------------------------------------------------------------
# TRIGGER ENGINE 1: LD_PRELOAD interposition (Linux, no gdb required)
# ---------------------------------------------------------------------------
#
# Nuitka's MainProgram calls PySys_SetArgv(argc, argv) AFTER
# createGlobalConstants() (the constants blob is decoded by then) and BEFORE
# EXECUTE_MAIN_MODULE() (any module code). When the target imports CPython
# dynamically (libpython3.x.so — the default on Linux for accelerated and
# standalone builds), that call goes through the PLT and can be interposed.
#
# The hook dumps the decoded blob straight from the process image and then
# _exit(77)s: the payload never executes.

_DV_TRIGGER_HOOK_C = r'''/*
 * HEXPYRION v8 by dimareverse — LD_PRELOAD trigger hook
 *
 * Interposes PySys_SetArgv, which Nuitka's MainProgram calls AFTER
 * createGlobalConstants() (constants blob decoded) and BEFORE
 * EXECUTE_MAIN_MODULE() (any module code). At that point we:
 *   1. scan the process image for the constants blob (classic CRC-framed
 *      or headerless Nuitka >= 4.1 layout) and dump it,
 *   2. optionally record sys.version through PyRun_SimpleString,
 *   3. _exit(77) — the payload NEVER executes.
 *
 * When NDL_TRIGGER_OUT is not set the real PySys_SetArgv runs normally.
 */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define NDL_MAX_BLOB (512u * 1024u * 1024u)
#define NDL_MAX_CHUNKS 8192

typedef int (*ndl_setargv_fn)(int, char **);

static uint32_t ndl_crc32(const unsigned char *buf, size_t len) {
    static uint32_t table[256];
    static int table_ready = 0;
    uint32_t crc;

    if (!table_ready) {
        for (uint32_t i = 0; i < 256; i++) {
            uint32_t c = i;
            for (int k = 0; k < 8; k++)
                c = (c & 1) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
            table[i] = c;
        }
        table_ready = 1;
    }
    crc = 0xFFFFFFFFu;
    for (size_t i = 0; i < len; i++)
        crc = table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
    return crc ^ 0xFFFFFFFFu;
}

static int ndl_name_char_ok(unsigned char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '_' || c == '.';
}

/* Dotted module identifier, optional leading '.' (".bytecode"); empty is OK. */
static int ndl_chunk_name_ok(const unsigned char *name, size_t len) {
    if (len == 0)
        return 1;
    if (len > 512)
        return 0;
    if (name[0] == '.') {
        if (len == 1)
            return 0;
        name++;
        len--;
    }
    unsigned char first = name[0];
    if (!((first >= 'a' && first <= 'z') || (first >= 'A' && first <= 'Z') ||
          first == '_'))
        return 0;
    for (size_t i = 1; i < len; i++)
        if (!ndl_name_char_ok(name[i]))
            return 0;
    return 1;
}

/* Walk the headerless chunk table; return the end offset or -1.
 * Requires at least one NAMED chunk (".bytecode", module names, ...) so
 * pointer tables and zero padding cannot false-positive. */
static long ndl_walk_chunks(const unsigned char *buf, size_t n) {
    size_t pos = 0;
    size_t last_real_end = 0;
    long named = 0;
    int chunks = 0;

    while (pos + 5 <= n) {
        size_t limit = n - pos;
        if (limit > 513)
            limit = 513;
        const unsigned char *nz = (const unsigned char *)memchr(buf + pos, 0, limit);
        if (nz == NULL)
            break;
        size_t name_end = (size_t)(nz - buf);
        uint32_t csize;
        memcpy(&csize, buf + name_end + 1, 4);
        size_t chunk_end = name_end + 5 + (size_t)csize;
        if (chunk_end > n || (long)csize < 0)
            break;
        if (name_end == pos && csize == 0)
            break; /* padding terminator */
        if (!ndl_chunk_name_ok(buf + pos, name_end - pos))
            break;
        pos = chunk_end;
        chunks++;
        if (chunks > NDL_MAX_CHUNKS)
            return -1;
        if (name_end > 0) {
            named++;
            last_real_end = chunk_end;
        }
    }
    if (named < 1)
        return -1;
    return (long)last_real_end;
}

static int ndl_write_file(const char *dir, const char *name,
                          const unsigned char *data, size_t len) {
    char path[4096];
    snprintf(path, sizeof(path), "%s/%s", dir, name);
    FILE *f = fopen(path, "wb");
    if (!f)
        return 0;
    size_t wrote = fwrite(data, 1, len, f);
    fclose(f);
    return wrote == len;
}

static void ndl_dump_python_info(const char *dir) {
    /* Runs a frozen/builtin-only snippet: sys, open() — no app code. */
    int (*run_string)(const char *) = NULL;
    run_string = (int (*)(const char *))dlsym(RTLD_DEFAULT, "PyRun_SimpleString");
    if (run_string == NULL)
        return;

    char code[4096];
    snprintf(code, sizeof(code),
             "import sys\n"
             "with open(r'%s/trigger_py.txt', 'w') as _f:\n"
             "    _f.write('version=' + sys.version + '\\n')\n"
             "    _f.write('implementation=' + repr(sys.implementation) + '\\n')\n"
             "    _f.write('executable=' + sys.executable + '\\n')\n"
             "    _f.write('modules=' + repr(sorted(sys.modules)) + '\\n')\n",
             dir);
    run_string(code);
}

static void ndl_trigger(const char *dir) {
    char exe[4096];
    ssize_t n = readlink("/proc/self/exe", exe, sizeof(exe) - 1);
    if (n <= 0)
        return;
    exe[n] = 0;

    /* Enumerate our own executable's mappings and scan them for the blob. */
    FILE *maps = fopen("/proc/self/maps", "r");
    if (maps == NULL)
        return;

    char line[1024];
    unsigned char *best_blob = NULL;
    size_t best_len = 0;
    long regions = 0;

    while (fgets(line, sizeof(line), maps)) {
        unsigned long start, end;
        char perms[8];
        char path[512];
        path[0] = 0;
        /* start-end perms offset dev(##:##) inode path */
        int filled = sscanf(line, "%lx-%lx %7s %*x %*31s %*d %511s",
                            &start, &end, perms, path);
        if (filled < 3)
            continue;
        if (path[0] == 0)
            continue;
        /* Only the main executable image (file backed, readable). */
        size_t plen = strlen(path);
        if (plen >= 10 && strcmp(path + plen - 10, " (deleted)") == 0)
            plen -= 10;
        if (strncmp(path, exe, plen) != 0 || exe[plen] != 0)
            continue;
        if (perms[0] != 'r')
            continue;
        regions++;

        size_t size = end - start;
        if (size > NDL_MAX_BLOB)
            size = NDL_MAX_BLOB;
        const unsigned char *mem = (const unsigned char *)start;

        /* 1) Classic CRC-framed blob (Nuitka <= 4.0). */
        for (size_t off = 0; off + 12 <= size; off += 4) {
            uint32_t crc_stored, size_stored;
            memcpy(&crc_stored, mem + off, 4);
            memcpy(&size_stored, mem + off + 4, 4);
            if (size_stored < 64 || size_stored > size - off - 8)
                continue;
            if (ndl_crc32(mem + off + 8, size_stored) == crc_stored) {
                size_t total = 8 + (size_t)size_stored;
                if (total > best_len) {
                    unsigned char *copy = (unsigned char *)malloc(total);
                    if (copy) {
                        memcpy(copy, mem + off, total);
                        free(best_blob);
                        best_blob = copy;
                        best_len = total;
                    }
                }
                break;
            }
        }

        /* 2) Headerless blob (Nuitka >= 4.1): anchor on ".bytecode\0". */
        static const unsigned char marker[] = ".bytecode\x00";
        for (size_t off = 0; off + 16 <= size; off++) {
            if (memcmp(mem + off, marker, sizeof(marker) - 1) != 0)
                continue;
            long span = ndl_walk_chunks(mem + off, size - off);
            if (span > 128 && (size_t)span > best_len) {
                unsigned char *copy = (unsigned char *)malloc((size_t)span);
                if (copy) {
                    memcpy(copy, mem + off, (size_t)span);
                    free(best_blob);
                    best_blob = copy;
                    best_len = (size_t)span;
                }
            }
        }

        /* 3) Headerless, no .bytecode chunk (accelerated builds): aligned
         *    scan with chunk-table validation. */
        if (best_blob == NULL) {
            for (size_t off = 0; off + 16 <= size; off += 4) {
                long span = ndl_walk_chunks(mem + off, size - off);
                if (span > 128 && (size_t)span > best_len) {
                    unsigned char *copy = (unsigned char *)malloc((size_t)span);
                    if (copy) {
                        memcpy(copy, mem + off, (size_t)span);
                        free(best_blob);
                        best_blob = copy;
                        best_len = (size_t)span;
                    }
                }
            }
        }
    }
    fclose(maps);

    if (best_blob) {
        ndl_write_file(dir, "trigger_blob.bin", best_blob, best_len);
        free(best_blob);
    }

    {
        char info[256];
        snprintf(info, sizeof(info),
                 "regions=%ld blob=%zu\n", regions, best_len);
        ndl_write_file(dir, "trigger_debug.txt",
                       (const unsigned char *)info, strlen(info));
    }

    ndl_dump_python_info(dir);
}

int PySys_SetArgv(int argc, char **argv) {
    const char *dir = getenv("NDL_TRIGGER_OUT");

    if (dir == NULL || dir[0] == 0) {
        /* Pass-through: behave like the real function. */
        ndl_setargv_fn real_fn =
            (ndl_setargv_fn)dlsym(RTLD_NEXT, "PySys_SetArgv");
        if (real_fn == NULL)
            _exit(76);
        return real_fn(argc, argv);
    }

    ndl_trigger(dir);
    /* Terminate before EXECUTE_MAIN_MODULE: the payload never runs. */
    _exit(77);
}
'''


def _dv_build_trigger_hook(trigger_dir):
    """Compile (and cache) the LD_PRELOAD trigger hook. Returns .so path."""
    hook_path = os.path.join(trigger_dir, "ndl_trigger_hook.so")
    if os.path.isfile(hook_path):
        return hook_path

    source_path = os.path.join(trigger_dir, "ndl_trigger_hook.c")
    with open(source_path, "w", encoding="utf-8") as handle:
        handle.write(_DV_TRIGGER_HOOK_C)

    import shutil
    compilers = [c for c in ("cc", "gcc", "clang") if shutil.which(c)]
    if not compilers:
        log_warn("No C compiler (cc/gcc/clang) available to build the "
                 "LD_PRELOAD trigger hook.")
        return None

    for compiler in compilers:
        try:
            proc = run_external_tool(
                [compiler, "-shared", "-fPIC", "-O2", "-o", hook_path,
                 source_path, "-ldl"], timeout=60)
            if proc.returncode == 0 and os.path.isfile(hook_path):
                log_ok(f"Trigger hook built with {compiler}: {hook_path}")
                return hook_path
        except Exception:
            continue
    log_warn("Could not compile the trigger hook (see {0}).".format(
        os.path.join(trigger_dir, "hook_build.log")))
    return None


def _dv_preload_viable(data):
    """Check that PySys_SetArgv is a PLT import of this ELF target."""
    elf = _dv_elf_parse_header(data)
    if elf is None:
        return False
    try:
        symbols = _dv_elf_symbols(data, elf, section_types=(11,))  # SHT_DYNSYM
    except Exception:
        return False
    return any(name == "PySys_SetArgv" for name, _value, _size in symbols)


def _dv_trigger_preload_run(trigger_target, out_dir, args=None):
    """Run the target with the trigger hook preloaded. Zero payload exec.

    Returns ``(blob_bytes_or_None, info_dict)``.
    """
    trigger_dir = os.path.abspath(os.path.join(out_dir, "trigger"))
    os.makedirs(trigger_dir, exist_ok=True)

    hook_path = _dv_build_trigger_hook(trigger_dir)
    if hook_path is None:
        return None, {"error": "hook build failed"}

    timeout = int(getattr(args, "trigger_timeout", None) or 120)

    env = dict(os.environ)
    env["NDL_TRIGGER_OUT"] = trigger_dir
    env["LD_PRELOAD"] = hook_path
    # The child binary may need its sibling libs (libpython3.x.so) from the
    # onefile payload directory.
    payload_dir = os.path.join(out_dir, "onefile_payload")
    if os.path.isdir(payload_dir):
        env["LD_LIBRARY_PATH"] = (payload_dir + os.pathsep +
                                  env.get("LD_LIBRARY_PATH", ""))

    log(f"Running target with LD_PRELOAD trigger (timeout {timeout}s) — "
        f"the payload will NOT execute")

    info = {"engine": "ld-preload"}
    try:
        proc = subprocess.run(
            [os.path.abspath(trigger_target)], env=env,
            cwd=os.path.dirname(os.path.abspath(trigger_target)) or ".", stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            timeout=timeout)
        info["exit_code"] = proc.returncode
        info["stdout_tail"] = (proc.stdout or b"")[-2000:].decode(
            "utf-8", errors="replace")
        info["stderr_tail"] = (proc.stderr or b"")[-2000:].decode(
            "utf-8", errors="replace")
    except subprocess.TimeoutExpired:
        info["timeout"] = True
        log_warn("Trigger run timed out — the process was killed")
    except Exception as exc:
        info["error"] = str(exc)
        return None, info

    if info.get("exit_code") != 77:
        log_warn(f"Unexpected trigger exit code: {info.get('exit_code')!r} "
                 "(expected 77). If the target ran to completion its payload "
                 "may have executed — use an isolated VM for untrusted "
                 "samples.")

    blob_path = os.path.join(trigger_dir, "trigger_blob.bin")
    blob = None
    if os.path.isfile(blob_path):
        with open(blob_path, "rb") as handle:
            blob = handle.read()
    return blob, info



def run_trigger_mode(target, out_dir, args=None):
    """Runtime trigger capture: decoded blob from memory, payload never runs.

    Engines (``--trigger-engine``):
      * ``auto`` (default) — LD_PRELOAD interposition when the target imports
        CPython through the PLT (Linux default builds), gdb otherwise
      * ``preload``         — force the LD_PRELOAD engine
      * ``gdb``             — force the gdb engine
    """
    print_section("TRIGGER MODE: payload-neutralized runtime capture")

    engine = (getattr(args, "trigger_engine", None) or "auto").lower()
    gdb_path = getattr(args, "trigger_gdb", None) or "gdb"
    gdb_bin = _dv_gdb_available(gdb_path)

    with open(target, "rb") as handle:
        data = handle.read()
    binfmt = _dv_detect_binfmt(data)

    # Onefile bootstraps contain no Python: statically resolve the child
    # binary first so the trigger lands on the real compiled program.
    trigger_target = target
    try:
        found = _dv_onefile_payload_bytes(data, binfmt=binfmt)
    except Exception:
        found = []
    if found:
        log("Onefile bootstrap detected — resolving the child binary "
            "statically (no execution)")
        manifest = run_onefile_unpack(target, out_dir)
        main_binary = (manifest or {}).get("main_binary") or {}
        child_rel = main_binary.get("path")
        if not child_rel:
            log_err("Could not resolve the onefile child binary.")
            return 1
        child_path = os.path.join(out_dir, child_rel)
        trigger_target = child_path
        with open(trigger_target, "rb") as handle:
            trigger_data = handle.read()
        log_ok(f"Trigger will run against the onefile child: "
               f"{main_binary.get('name')}")
    else:
        trigger_data = data

    # --- Engine 1: LD_PRELOAD interposition ---------------------------------
    use_preload = engine in ("auto", "preload")
    if use_preload and sys.platform not in ("win32",) \
            and binfmt in ("ELF", None) \
            and _dv_preload_viable(trigger_data):
        log_ok("PySys_SetArgv is a PLT import — using the LD_PRELOAD "
               "trigger engine (no gdb needed)")
        blob, engine_info = _dv_trigger_preload_run(
            trigger_target, out_dir, args=args)

        report = {
            "mode": "trigger",
            "target": os.path.basename(target),
            "trigger_target": os.path.basename(trigger_target),
            "engine": "ld-preload",
            "engine_info": engine_info,
        }

        # Optional frozen-only Python dump recorded by the hook itself.
        py_info_path = os.path.join(out_dir, "trigger", "trigger_py.txt")
        if os.path.isfile(py_info_path):
            try:
                with open(py_info_path, "r", encoding="utf-8",
                          errors="replace") as handle:
                    py_info = handle.read()
                report["trigger_py"] = py_info[:4096]
                for line in py_info.splitlines():
                    if line.startswith("version="):
                        log_ok(f"Target interpreter: {line[8:].strip()[:60]}")
                        break
            except Exception:
                pass

        if blob:
            # Normalize: the hook may dump the headerless layout directly.
            if not _dv_blob_frame_ok(blob):
                walk = _dv_blob_walk_headerless(blob, 0, len(blob))
                if walk is not None:
                    blob = _dv_wrap_headerless(blob[:walk[0]])
                else:
                    blob = _dv_wrap_headerless(blob)
            report["blob_size"] = len(blob)
            log_ok(f"Decoded constants blob captured from process memory: "
                   f"{len(blob):,} bytes")

            _dv_write_trigger_report(out_dir, report)
            print_section("TRIGGER -> DEVIRT PIPELINE")
            devirt_report = run_devirt_mode(
                trigger_target, out_dir,
                extract_pyc=not getattr(args, "devirt_no_pyc", False),
                extract_constants=not getattr(args, "devirt_no_constants",
                                               False),
                extract_files=not getattr(args, "devirt_no_files", False),
                decompile=bool(getattr(args, "devirt_decompile", False)),
                only=getattr(args, "only", None),
                blob_override=blob,
                blob_source_label="trigger-ld-preload-memory-dump")
            report["devirt"] = devirt_report
            _dv_write_trigger_report(out_dir, report)
            return 0

        if engine == "preload":
            _dv_write_trigger_report(out_dir, report)
            log_err("The LD_PRELOAD trigger did not capture a blob" +
                    (" (timeout)" if engine_info.get("timeout") else "") +
                    ". See trigger/ for details.")
            return 1
        log_warn("LD_PRELOAD trigger did not capture a blob — falling "
                 "back to the gdb engine")
    elif engine == "preload":
        log_err("LD_PRELOAD engine requested but PySys_SetArgv is not a PLT "
                "import of this target (static CPython or non-ELF).")
        return 1
    elif engine == "auto" and sys.platform not in ("win32",) \
            and binfmt in ("ELF", None) \
            and not _dv_preload_viable(trigger_data):
        log("PySys_SetArgv is not PLT-imported (static CPython?) — the gdb "
            "engine will be used instead")

    # --- Engine 2: gdb -------------------------------------------------------
    if not gdb_bin:
        log_err("gdb (with Python support) is required for this trigger "
                "engine and was not found. Static --devirt still works.")
        log_err("Install gdb (apt install gdb / brew install gdb), or use "
                "the default LD_PRELOAD engine (dynamically linked targets).")
        return 1

    trigger_target = trigger_target  # resolved above for onefile children

    # Phase 0: symbol discovery (never launches the target).
    wanted = list(_DV_TRIGGER_BREAKPOINTS)
    custom = getattr(args, "trigger_breakpoint", None)
    if custom:
        wanted = [custom] + [bp for bp in wanted if bp != custom]
    symbols = wanted + ["constant_bin", "Py_Version"]
    existing = _dv_gdb_query_symbols(gdb_bin, trigger_target, symbols)
    breakpoints = [bp for bp in wanted if bp in existing]
    log(f"Symbols available: {', '.join(existing) or 'none'}")

    if not breakpoints:
        log_err("No trigger breakpoint symbol exists in this binary "
                "(stripped or not a Nuitka program). Refusing to run the "
                "target — that would execute the payload. Use static "
                "--devirt instead.")
        return 1
    if "constant_bin" not in existing:
        log_warn("'constant_bin' symbol missing — the memory dump will fall "
                 "back to writable-region scanning" +
                 ("" if getattr(args, "trigger_dump_regions", False)
                  else " (enable with --trigger-dump-regions)"))

    dump_regions = bool(getattr(args, "trigger_dump_regions", False)) \
        or ("constant_bin" not in existing)
    script_path, trigger_dir = _dv_build_trigger_gdb_script(
        trigger_target, out_dir, breakpoints,
        dump_regions=dump_regions,
        py_dump=bool(getattr(args, "trigger_py_dump", False)))

    timeout = int(getattr(args, "trigger_timeout", None) or 120)
    log(f"Running under gdb (breakpoint: {', '.join(breakpoints)}; "
        f"timeout {timeout}s). The payload will NOT execute.")

    cmd = [gdb_bin, "-batch", "-x", script_path]
    proc = None
    inferior_pid = None
    markers = {}
    try:
        proc = subprocess.Popen(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL)
        try:
            output, _ = proc.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            log_warn("gdb timed out — killing the inferior before anything "
                     "else can happen")
            proc.kill()
            output, _ = proc.communicate()
    finally:
        pass

    text = (output or b"").decode("utf-8", errors="replace")
    for line in text.splitlines():
        if line.startswith("NDL_TRIG "):
            key, _, value = line[len("NDL_TRIG "):].partition("=")
            markers[key] = value

    with open(os.path.join(trigger_dir, "gdb_output.log"), "w",
              encoding="utf-8") as handle:
        handle.write(text)

    inferior_pid = None
    if markers.get("PID", "").isdigit():
        inferior_pid = int(markers["PID"])
    # Defensive kill: make sure the inferior is gone even if gdb died.
    if inferior_pid:
        _dv_kill_pid(inferior_pid)

    stopped_at = markers.get("STOPPED_AT")
    if stopped_at:
        log_ok(f"Process stopped at {stopped_at} (pre-payload)")
    else:
        log_err("The breakpoint was NOT hit. The target may have run to "
                "completion — treat the environment as exposed and use an "
                "isolated VM for untrusted samples.")

    blob_path = os.path.join(trigger_dir, "trigger_blob.bin")
    result = markers.get("RESULT")
    py_version_hex = markers.get("PY_VERSION_HEX")

    report = {
        "mode": "trigger",
        "target": os.path.basename(target),
        "trigger_target": os.path.basename(trigger_target),
        "breakpoints": breakpoints,
        "stopped_at": stopped_at,
        "py_version_hex": py_version_hex,
        "result": result,
        "inferior_pid": inferior_pid,
    }

    if py_version_hex:
        try:
            version_int = int(py_version_hex, 16)
            major = (version_int >> 24) & 0xFF
            minor = (version_int >> 16) & 0xFF
            if major == 3:
                report["detected_python"] = f"{major}.{minor}"
                log_ok(f"CPython from memory: {major}.{minor} "
                       f"(Py_Version=0x{version_int:x})")
        except Exception:
            pass

    if result == "OK" and os.path.isfile(blob_path):
        with open(blob_path, "rb") as handle:
            blob = handle.read()
        log_ok(f"Decoded constants blob captured from memory: "
               f"{len(blob):,} bytes")
        report["blob_size"] = len(blob)
        python_version = None
        if report.get("detected_python"):
            major, minor = report["detected_python"].split(".")
            python_version = (int(major), int(minor))

        print_section("TRIGGER -> DEVIRT PIPELINE")
        devirt_report = run_devirt_mode(
            trigger_target, out_dir,
            extract_pyc=not getattr(args, "devirt_no_pyc", False),
            extract_constants=not getattr(args, "devirt_no_constants", False),
            extract_files=not getattr(args, "devirt_no_files", False),
            decompile=bool(getattr(args, "devirt_decompile", False)),
            only=getattr(args, "only", None),
            blob_override=blob,
            blob_source_label="trigger-memory-dump",
            python_version=python_version)
        report["devirt"] = devirt_report
        _dv_write_trigger_report(out_dir, report)
        return 0

    if result in (None, "NOT_STOPPED"):
        _dv_write_trigger_report(out_dir, report)
        log_err("Trigger failed before the dump (process not stopped).")
        return 1

    # NO_BLOB: try offline CRC scanning over the dumped regions.
    regions = [name for name in os.listdir(trigger_dir)
               if name.startswith("region_") and name.endswith(".bin")]
    if regions:
        log(f"Scanning {len(regions)} dumped memory regions for the blob...")
        best = None
        for name in sorted(regions):
            path = os.path.join(trigger_dir, name)
            try:
                with open(path, "rb") as handle:
                    region_data = handle.read()
            except Exception:
                continue
            candidate = _find_blob_in_raw_bytes(region_data)
            if candidate and (best is None or len(candidate) > len(best)):
                best = candidate
        if best:
            with open(blob_path, "wb") as handle:
                handle.write(best)
            report["blob_size"] = len(best)
            report["blob_source"] = "region-scan"
            log_ok(f"Constants blob recovered by region scan: "
                   f"{len(best):,} bytes")
            devirt_report = run_devirt_mode(
                trigger_target, out_dir,
                extract_pyc=not getattr(args, "devirt_no_pyc", False),
                extract_constants=not getattr(args, "devirt_no_constants", False),
                extract_files=not getattr(args, "devirt_no_files", False),
                decompile=bool(getattr(args, "devirt_decompile", False)),
                only=getattr(args, "only", None),
                blob_override=best,
                blob_source_label="trigger-region-scan")
            report["devirt"] = devirt_report
            _dv_write_trigger_report(out_dir, report)
            return 0

    _dv_write_trigger_report(out_dir, report)
    log_err("No constants blob could be captured. Check gdb_output.log; "
            "try --trigger-dump-regions or a custom --trigger-breakpoint.")
    return 1


def _dv_write_trigger_report(out_dir, report):
    path = os.path.join(out_dir, "TRIGGER_REPORT.json")
    try:
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(report, handle, indent=2, ensure_ascii=False,
                      default=str)
            handle.write("\n")
        log_ok(f"Trigger report: {path}")
    except Exception as exc:
        log_warn(f"Could not write TRIGGER_REPORT.json: {exc}")



def main():
    # ------------------------------------------------------------------ find default DLL/hook next to this script
    _script_dir = os.path.dirname(os.path.abspath(__file__))
    _default_dll  = os.path.join(_script_dir,
                                  "hook64.dll" if platform.machine().endswith("64") else "hook32.dll")
    _default_hook = os.path.join(_script_dir, "__hook__.py")

    parser = argparse.ArgumentParser(
        epilog="""
Examples:
  # Authorized static analysis
  python nuitka_decompiler.py --source authorized_app.exe

  # Dynamic mode: controlled lab process you are allowed to instrument
  python nuitka_decompiler.py --source authorized_app.exe --inject --pid 1234

  # Dynamic mode: launch and inject automatically
  python nuitka_decompiler.py --source authorized_app.exe --inject --launch

  # Full path overrides
  python nuitka_decompiler.py --source authorized_app.exe --inject --launch \\
      --dll hook64.dll --hook-script __hook__.py

STATIC mode  : pure PE analysis, no runtime hooks.
DYNAMIC mode : authorized lab instrumentation of a running or auto-launched
               process. Do not use on third-party software without permission.
        """,
        formatter_class=argparse.RawDescriptionHelpFormatter
    )
    # --- static / common ---
    parser.add_argument('--source', '-s', dest='source_flag', default=None,
                        metavar='FILE',
                        help='Authorized .exe or .dll compiled with Nuitka (preferred flag)')
    parser.add_argument('target', nargs='?', default=None,
                        help='Authorized .exe or .dll (positional - same as --source)')
    parser.add_argument('--output', '-o', default=None, help='Output directory (default: auto)')
    parser.add_argument('--all', '-a', action='store_true',
                        help='Also analyze library modules (not just app)')
    parser.add_argument('--only', default=None, metavar='MODS',
                        help='Comma-separated list of module names to '
                             'disassemble (PHASE 11.7 only). Exact names or '
                             'shell globs such as "pkg.*" and "**main**" are supported. Skips recursive '
                             'disasm for all other modules - much faster '
                             'when you only want one specific .nbc.')
    parser.add_argument('--list-modules', action='store_true', dest='list_modules',
                        help='List all module names in the blob and exit. No source reconstruction.')
    parser.add_argument('--filter', default=None, metavar='STR', dest='filter_str',
                        help='With --list-modules: only show modules containing STR.')
    parser.add_argument('--live-decompile', default=None, metavar='MODULE[:0xVA]',
                        dest='live_decompile',
                        help='Deterministic live native->Python for ONE module (no .nbc, no AI). '
                             'Optionally pin a function VA, e.g. pkg.module.func:0x1424E08B0')
    parser.add_argument('--emit-source', default=None, metavar='OUT.py', nargs='?', const='-',
                        dest='emit_source',
                        help='With --live-decompile MODULE: emit a parseable best-effort .py '
                             'plus an audit. Exact semantics are only claimed for surviving '
                             'source/bytecode; native-only gaps fail explicitly.')
    parser.add_argument('--emit-all-source', default=None, metavar='OUT_DIR',
                        dest='emit_all_source',
                        help='Deterministic whole-binary emit (no .nbc, no AI): run the live '
                             'decompiler over every selected module and write a .py source tree '
                             'to OUT_DIR. Use --only to restrict (default: the app\'s own code).')
    parser.add_argument('--emit-fast', action='store_true', dest='emit_fast',
                        help='With --emit-source/--emit-all-source: use the balanced profile '
                             'and conservative walkers. Source emission otherwise uses the '
                             'slower maximum-coverage profile for both one and all modules.')
    parser.add_argument('--no-resume', action='store_true', dest='no_resume',
                        help='With --emit-all-source: ignore valid per-module results in the '
                             'existing LIVE_RECOVERY_REPORT.json and rebuild everything.')
    parser.add_argument('--refine-partial', action='store_true', dest='refine_partial',
                        help='With --emit-all-source: read the existing recovery report and '
                             'run maximum-fidelity analysis only for modules still partial. '
                             'Writes LIVE_REFINEMENT_REPORT.json.')
    parser.add_argument('--require-complete', action='store_true',
                        dest='require_complete',
                        help='Fail with exit code 2 unless every selected module passes '
                             'the final on-disk executable-source contract.')
    parser.add_argument('--live-max-funcs', type=int, default=None, metavar='N',
                        dest='live_max_funcs',
                        help='Live decompile: max native functions to analyse per module '
                             '(default 120). Lower = less RAM.')
    parser.add_argument('--live-max-bytes', type=int, default=None, metavar='N',
                        dest='live_max_bytes',
                        help='Live decompile: max disasm bytes per function body '
                             '(default 32768).')
    parser.add_argument('--live-body-bytes', type=int, default=None, metavar='N',
                        dest='live_body_bytes',
                        help='Live decompile: max bytes for structured body recovery '
                             '(default 32768).')
    parser.add_argument('--live-recursion-depth', type=int, default=None, metavar='N',
                        dest='live_recursion_depth',
                        help='Maximum protected wrapper/maker recursion depth '
                             '(default 32). The traversal is cycle-safe and also '
                             'bounded by the native-function budget.')
    parser.add_argument('--live-complete', action='store_true', dest='live_complete',
                        help='Live decompile preset: higher per-function byte budgets '
                             '(targeted analysis only — low RAM).')
    parser.add_argument('--live-traces', action='store_true', dest='live_traces',
                        help='Enable heavy per-function body-trace recovery (more accurate '
                             'fallbacks, much higher RAM). Off by default.')
    parser.add_argument('--recon-executable', action='store_true', dest='recon_executable',
                        help="Emit each stripped function's tentative per-statement "
                             'reconstruction AS its body (nested, executable-looking code) '
                             'instead of a `#~` comment block. Tentative (loop→if, vN temps, '
                             'one path, branch polarity may be inverted) but clearly marked.')
    parser.add_argument('--source-line-walk', action='store_true', dest='source_line_walk',
                        default=None,
                        help='Recover stripped bodies with the SOURCE-LINE WALKER: an '
                             'address-ordered multi-pass linear walk that covers the whole '
                             'CFG-truncated body (loops+try/except+nested branches) the '
                             'default CFG walk cuts short. Flat but higher-coverage; competes '
                             'with the continuous recon and the parseable/richer one wins.')
    parser.add_argument('--no-source-line-walk', action='store_false', dest='source_line_walk',
                        help='Disable the source-line walker (see --source-line-walk).')
    parser.add_argument('--cfg-walk', action='store_true', dest='cfg_walk',
                        default=None,
                        help='CFG-AWARE SOURCE-LINE WALKER (V34, experimental): like the source-line '
                             'walker but reconstructs HOISTED receiver/argument state from the CFG '
                             'predecessors of each f_lineno marker before walking it. Fixes statement '
                             'fusion (e.g. html.parser.find(x) <- BeautifulSoup(r.text) + soup.find(x) '
                             'where the call was hoisted into a different basic block). Competes on '
                             '(parses, real_stmt_count) with the other body candidates, so it cannot '
                             'regress. Enabled by the complete source-emission profile; '
                             'balanced/programmatic analysis keeps it off unless requested.')
    parser.add_argument('--no-cfg-walk', action='store_false', dest='cfg_walk',
                        help='Disable the CFG-aware source-line walker (see --cfg-walk).')
    parser.add_argument('--target-python', default=None, metavar='X.Y',
                        help='Override the detected target Python version (e.g. 3.10, 3.11, 3.12). '
                             'Auto-detected from the PE/ELF by default. Use when auto-detection fails '
                             'or to force a specific version. Universal: applies to all Python 3.5+.')
    parser.add_argument('--clean', action='store_true', dest='clean_output',
                        help='Clean output mode: strip recovery comments (# recovered, #~ tentative) '
                             'when a real recovered body is present. Ellipsis placeholders (app = ...) '
                             'and faithful comments are kept. Default OFF (faithful output).')
    parser.add_argument('--aggressive-heuristics', action='store_true',
                        dest='aggressive_heuristics',
                        help='Opt in to legacy product-shaped semantic healers (Qt/dialog/login/'
                             'HTTP/BeautifulSoup, etc.). Default OFF in universal mode because '
                             'parseable synthesized code may be semantically wrong.')
    _partial_policy = parser.add_mutually_exclusive_group()
    _partial_policy.add_argument(
        '--allow-partial-executable', action='store_true',
        dest='allow_partial_executable', default=None,
        help='UNSAFE opt-in: keep tentative bodies containing unresolved '
             'native-recovery temporaries executable. Default OFF.')
    _partial_policy.add_argument(
        '--no-partial-executable', action='store_false',
        dest='allow_partial_executable', default=None,
        help='Quarantine tentative bodies even when the environment opted in.')
    parser.add_argument('--no-recon-executable', action='store_true', dest='no_recon_executable',
                        help='Disable executable per-statement reconstruction. With --emit-all-source '
                             'the recon is ON by default; this flag reverts to the conservative '
                             '#~ comment-block output. Useful for forensics where you want the raw '
                             'trace evidence, not the nested reconstruction.')
    parser.add_argument('--no-banner', action='store_true', help='Hide banner')
    parser.add_argument('--debug', action='store_true', dest='debug',
                        help='Write structured recovery diagnostics (blob, module table, '
                             'per-module coverage, incomplete bodies) into --debug-dir.')
    parser.add_argument('--debug-verbose', action='store_true', dest='debug_verbose',
                        help='With --debug: also dump every recovered function body '
                             '(very large on real application binaries).')
    parser.add_argument('--debug-dir', default=None, metavar='DIR', dest='debug_dir',
                        help='Directory for --debug artifacts (default: <output>/_debug).')
    parser.add_argument('--no-pyc-decompile', action='store_true',
                        help='Skip Phase 12 .pyc -> .py decompilation; useful when preparing only .nbc files.')
    parser.add_argument('--nbc-only', action='store_true',
                        help='Fast path: generate AI-ready .nbc only; skips source scans, '
                             '.pyc/.py/.c outputs, secrets reports, and .pyc decompilation.')
    parser.add_argument('--user-nbc', action='store_true', dest='user_nbc',
                        help='Restrict .nbc extraction to user/developer modules only — '
                             'excludes Python stdlib and known third-party libraries. '
                             'Useful when you want only the app\'s own code, not numpy/requests/etc.')
    parser.add_argument('--nbc-full-asm', action='store_true', dest='nbc_full_asm',
                        help='Include the per-function @ASM native-disassembly block in every '
                             '.nbc (off by default). The enriched @OPS already carries call '
                             'args, jump conditions and helper names, so @ASM is redundant; '
                             'enable it only when you want the raw x86-64 alongside @OPS.')

    # --- NEW v8: devirtualization / rematerialization modes -------------------
    devirt = parser.add_argument_group(
        'Devirtualization modes (v8) — rematerialize the ORIGINAL Python')
    devirt.add_argument('--devirt', action='store_true', dest='devirt',
                        help='[NEW] Static devirtualization with ZERO execution and NO C '
                             'reconstruction: emit every marshal\'d code object from the '
                             '".bytecode" chunk 1:1 as .pyc (the original compiled Python, '
                             'byte for byte), unpack the ".files" chunk, and dump '
                             'per-module constants + code-object maps for native modules. '
                             'Works on PE, ELF and Mach-O, standalone and onefile.')
    devirt.add_argument('--devirt-no-pyc', action='store_true', dest='devirt_no_pyc',
                        help='Skip the .pyc rematerialization phase.')
    devirt.add_argument('--devirt-no-constants', action='store_true',
                        dest='devirt_no_constants',
                        help='Skip per-module constants/code-object dumps.')
    devirt.add_argument('--devirt-no-files', action='store_true', dest='devirt_no_files',
                        help='Skip the ".files" chunk extraction.')
    devirt.add_argument('--devirt-decompile', action='store_true',
                        dest='devirt_decompile',
                        help='Also decompile the rematerialized .pyc files to best-effort '
                             '.py sources (pycdc / decompyle3 / uncompyle6 when present).')
    devirt.add_argument('--onefile-unpack', action='store_true', dest='onefile_unpack',
                        help='[NEW] Statically unpack a Nuitka onefile binary (PE, ELF, '
                             'Mach-O; zstd payloads supported) WITHOUT executing the '
                             'bootstrap. Emits onefile_payload/ + ONEFILE_MANIFEST.json.')
    devirt.add_argument('--onefile-max-bytes', type=int, default=None,
                        metavar='N', dest='onefile_max_bytes',
                        help='Safety bound for one onefile entry (default 2 GiB).')
    devirt.add_argument('--trigger', action='store_true', dest='trigger_mode',
                        help='[NEW] Runtime trigger with payload neutralization: run the '
                             'target under gdb, stop BEFORE any module code executes, dump '
                             'the DECODED constants blob from process memory, then kill the '
                             'process — the payload never runs. The captured blob feeds the '
                             'static devirt pipeline (defeats in-memory/commercial blob '
                             'protection). Requires gdb with Python support.')
    devirt.add_argument('--trigger-engine', default='auto', metavar='ENGINE',
                        dest='trigger_engine',
                        choices=['auto', 'preload', 'gdb'],
                        help='Trigger engine: auto (default) uses LD_PRELOAD '
                             'interposition when the target imports CPython '
                             'through the PLT (Linux default builds, no gdb '
                             'needed) and falls back to gdb otherwise; '
                             'preload and gdb force one engine.')
    devirt.add_argument('--trigger-breakpoint', default=None, metavar='SYM',
                        dest='trigger_breakpoint',
                        help='Override the trigger breakpoint symbol (default tries '
                             'registerMetaPathBasedLoader, EXECUTE_MAIN_MODULE, '
                             'modulecode___main__).')
    devirt.add_argument('--trigger-gdb', default='gdb', metavar='PATH',
                        dest='trigger_gdb',
                        help='Path to the gdb executable to use for --trigger.')
    devirt.add_argument('--trigger-timeout', type=int, default=120, metavar='SEC',
                        dest='trigger_timeout',
                        help='Hard timeout for the gdb trigger run (default 120s).')
    devirt.add_argument('--trigger-dump-regions', action='store_true',
                        dest='trigger_dump_regions',
                        help='Also dump writable memory regions at the trigger point and '
                             'CRC-scan them offline (needed for stripped binaries without '
                             'the constant_bin symbol).')
    devirt.add_argument('--trigger-py-dump', action='store_true', dest='trigger_py_dump',
                        help='At the trigger point also call PyRun_SimpleString in the '
                             'target to record sys.version / sys.modules (frozen modules '
                             'only — still zero app-code execution).')

    # Legacy arguments remain parseable only so old invocations receive a
    # clear policy error.  This build is deliberately static-only.
    inj = parser.add_argument_group('Disabled legacy dynamic options')
    inj.add_argument('--inject', action='store_true',
                     help=argparse.SUPPRESS)
    inj.add_argument('--launch', action='store_true',
                     help=argparse.SUPPRESS)
    inj.add_argument('--pid', type=int, default=None, metavar='PID',
                     help=argparse.SUPPRESS)
    inj.add_argument('--dll', default=_default_dll, metavar='PATH',
                     help=argparse.SUPPRESS)
    inj.add_argument('--hook-script', default=_default_hook, metavar='PATH',
                     dest='hook_script',
                     help=argparse.SUPPRESS)
    inj.add_argument('--dump-timeout', type=int, default=300, metavar='SEC',
                     dest='dump_timeout',
                     help=argparse.SUPPRESS)

    args = parser.parse_args()
    _dynamic_flags = {
        '--inject', '--launch', '--pid', '--dll', '--hook-script',
        '--dump-timeout',
    }
    if any(token.split('=', 1)[0] in _dynamic_flags
           for token in sys.argv[1:] if isinstance(token, str)):
        parser.error(
            'dynamic execution/injection is disabled: this decompiler is '
            'static-only and never launches the target')
    _ndl_set_aggressive_heuristics(
        getattr(args, 'aggressive_heuristics', False)
        or _NDL_AGGRESSIVE_HEURISTICS)
    if getattr(args, 'allow_partial_executable', None) is not None:
        _ndl_set_allow_partial_executable(args.allow_partial_executable)
    # --target-python override: universal, applies before any analysis runs.
    if getattr(args, 'target_python', None):
        try:
            _major, _minor = (int(x) for x in args.target_python.split('.')[:2])
            _ndl_set_target_python_override((_major, _minor))
            set_nuitka_target_python((_major, _minor))
            print(f'{C.BRIGHT_CYAN}[**]{C.RESET} target python overridden to {_major}.{_minor}')
        except Exception as _e:
            parser.error(
                f'invalid --target-python {args.target_python!r}: {_e}')
    if args.no_banner:
        global BANNER
        BANNER = ""
    if BANNER:
        print(BANNER, flush=True)

    # Resolve target: --source takes priority over positional
    target = args.source_flag or args.target
    if not target:
        parser.error("Specify an authorized target binary, e.g. --source authorized_app.exe")

    if getattr(args, 'debug', False) or getattr(args, 'debug_verbose', False) \
            or _RECOVER_DEBUG:
        _dbg_dir = getattr(args, 'debug_dir', None)
        if not _dbg_dir:
            if getattr(args, 'emit_all_source', None):
                _dbg_dir = os.path.join(args.emit_all_source, '_debug')
            elif getattr(args, 'output', None):
                _dbg_dir = os.path.join(args.output, '_debug')
            elif getattr(args, 'emit_source', None) and args.emit_source not in ('-', None):
                _dbg_dir = os.path.join(os.path.dirname(os.path.abspath(args.emit_source)) or '.',
                                        '_debug')
            else:
                _dbg_dir = os.path.join(
                    os.path.dirname(os.path.abspath(target)),
                    '_ndl_debug_' + Path(target).stem)
        _ndl_set_debug(True, _dbg_dir, verbose=bool(getattr(args, 'debug_verbose', False)))
        print(f'{C.BRIGHT_CYAN}[**]{C.RESET} debug diagnostics -> {_dbg_dir}')

    _ndl_configure_live_decompile(
        max_funcs=getattr(args, 'live_max_funcs', None),
        max_bytes_per_fn=getattr(args, 'live_max_bytes', None),
        structured_max_bytes=getattr(args, 'live_body_bytes', None),
        maker_max_depth=getattr(args, 'live_recursion_depth', None),
    )
    if getattr(args, 'live_complete', False):
        _ndl_apply_live_preset('complete')
        _ndl_configure_live_decompile(
            max_funcs=getattr(args, 'live_max_funcs', None),
            max_bytes_per_fn=getattr(args, 'live_max_bytes', None),
            structured_max_bytes=getattr(args, 'live_body_bytes', None),
            maker_max_depth=getattr(args, 'live_recursion_depth', None),
        )
    if getattr(args, 'live_traces', False):
        _ndl_configure_live_decompile(skip_body_traces=False)
    if getattr(args, 'recon_executable', False):
        _ndl_configure_live_decompile(recon_executable=True)
    if getattr(args, 'no_recon_executable', False):
        _ndl_configure_live_decompile(recon_executable=False)
    if getattr(args, 'source_line_walk', None) is not None:
        _ndl_configure_live_decompile(source_line_walk=args.source_line_walk)
    if getattr(args, 'cfg_walk', None) is not None:
        _ndl_configure_live_decompile(cfg_walk=args.cfg_walk)
    # Source emission is a completeness request regardless of whether it targets
    # one module or a whole binary.  Use the same maximum-coverage profile for
    # both; --emit-fast is the explicit opt-out.  Programmatic callers that do
    # not emit source retain the balanced defaults above.
    _emit_one = bool(getattr(args, 'emit_source', None))
    _emit_all = bool(getattr(args, 'emit_all_source', None))
    if _emit_one or _emit_all:
        _want_complete = bool(
            getattr(args, 'live_complete', False)
            or not getattr(args, 'emit_fast', False))
        _ndl_apply_live_preset('complete' if _want_complete else 'balanced')
        _ndl_configure_live_decompile(
            skip_body_traces=False,
            targeted_only=False,
            complete_mode=_want_complete,
            max_funcs=getattr(args, 'live_max_funcs', None),
            max_bytes_per_fn=getattr(args, 'live_max_bytes', None),
            structured_max_bytes=getattr(args, 'live_body_bytes', None),
            maker_max_depth=getattr(args, 'live_recursion_depth', None))
        if _want_complete:
            # Maximise the evidence search surface. Tentative bodies remain
            # quarantined unless --allow-partial-executable explicitly opts in.
            if not getattr(args, 'no_recon_executable', False):
                _ndl_configure_live_decompile(recon_executable=True)
            # Complete mode defaults both expensive walkers on, but their
            # documented tri-state CLI opt-outs must win over the preset.
            if getattr(args, 'source_line_walk', None) is not None:
                _ndl_configure_live_decompile(
                    source_line_walk=args.source_line_walk)
            if getattr(args, 'cfg_walk', None) is not None:
                _ndl_configure_live_decompile(cfg_walk=args.cfg_walk)
        if getattr(args, 'emit_fast', False):
            _ndl_configure_live_decompile(
                skip_body_traces=True,
                targeted_only=True,
                complete_mode=False,
                source_line_walk=False,
                cfg_walk=False,
                recon_executable=False)
        if getattr(args, 'recon_executable', False):
            _ndl_configure_live_decompile(recon_executable=True)
        if getattr(args, 'no_recon_executable', False):
            _ndl_configure_live_decompile(recon_executable=False)

    # ── --emit-all-source early exit (deterministic whole binary, no AI) ───
    if getattr(args, 'emit_all_source', None):
        _emit_report = decompile_all_to_source(
            target, args.emit_all_source,
            only=getattr(args, 'only', None),
            clean_output=getattr(args, 'clean_output', False),
            resume=not getattr(args, 'no_resume', False),
            fast=getattr(args, 'emit_fast', False),
            refine_partial=getattr(args, 'refine_partial', False),
            preserve_live_limits=True)
        if (getattr(args, 'require_complete', False)
                and (not _emit_report
                     or _emit_report.get('partial', 0)
                     or _emit_report.get('failed', 0)
                     or _emit_report.get('ok', 0) != _emit_report.get('modules', 0))):
            print('[INCOMPLETE] executable-source contract not satisfied',
                  file=sys.stderr)
            return 2
        return 0

    # ── --live-decompile early exit (deterministic, no .nbc, no AI) ────────
    if getattr(args, 'live_decompile', None):
        spec = args.live_decompile
        only_func = None
        if ':' in spec and '0x' in spec.split(':', 1)[1]:
            mod, fv = spec.rsplit(':', 1)
            only_func = int(fv, 16)
        else:
            mod = spec
        if getattr(args, 'emit_source', None):
            _emit_ctx = _live_decompile_ctx(target)
            _res = decompile_module_to_source(
                target, mod, ctx=_emit_ctx, audit=True)
            if _res is None:
                return
            src, audit = _res
            if getattr(args, 'clean_output', False):
                src = _ndl_clean_source(src)
            src = _ndl_restore_structured_module_docstring(src, mod)
            src, audit = _ndl_finalize_source_artifact(
                src, mod, audit, _emit_ctx)
            if args.emit_source in ('-', None):
                print(src)
            else:
                os.makedirs(os.path.dirname(os.path.abspath(args.emit_source)) or '.',
                            exist_ok=True)
                with open(args.emit_source, 'w', encoding='utf-8') as f:
                    f.write(src.rstrip() + "\n")
                _audit_path = args.emit_source + '.audit.json'
                with open(_audit_path, 'w', encoding='utf-8') as _af:
                    json.dump(audit, _af, indent=2, sort_keys=True, default=str)
                    _af.write("\n")
                print(f"[OK] wrote {args.emit_source}")
                print(f"[OK] wrote {_audit_path}")
            print(f"[audit] lines={audit.get('lines')} "
                  f"code_objects={audit.get('code_objects')} "
                  f"makers={audit.get('code_slot_makers')} "
                  f"impls={audit.get('code_slot_impls')} "
                  f"constant_returns={audit.get('code_slot_constant_returns')} "
                  f"bodies={audit.get('bodies_recovered')} "
                  f"ellipsis={audit.get('ellipsis_placeholders')} "
                  f"parses={audit.get('parses')} "
                  f"bfs_budget={audit.get('bfs_budget')}")
            _js = audit.get('code_slot_join') or {}
            _mc = audit.get('maker_closure') or {}
            if _js or _mc:
                print(f"[native-frontier] factory_makers={_js.get('code_slot_makers', 0)} "
                      f"exact_impls={_js.get('code_slot_impls', 0)} "
                      f"body_slot_impls={_js.get('code_slot_body_impls', 0)} "
                      f"unresolved_factories={_js.get('code_slot_unresolved_factories', 0)} "
                      f"closure_helpers={_mc.get('helpers_seen', 0)} "
                      f"closure_depth={_mc.get('max_depth', 0)} "
                      f"budget_exhausted={_mc.get('budget_exhausted', False)}")
                for _shape, _count in sorted(
                        (_js.get('code_slot_unresolved_slices') or {}).items(),
                        key=lambda kv: (-kv[1], kv[0])):
                    print(f"  [arg0-slice] x{_count} {_shape}")
            if (getattr(args, 'require_complete', False)
                    and not audit.get('executable_ready', False)):
                print('[INCOMPLETE] executable-source contract not satisfied',
                      file=sys.stderr)
                return 2
        else:
            decompile_module_live(target, mod, only_func=only_func)
        return

    if args.output:
        out_dir = args.output
    else:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        base_name = Path(target).stem
        out_dir = str(Path(target).parent / f"UNPACKED_{base_name}_{timestamp}")

    # ── v8 early exits: trigger / onefile-unpack / devirt ────────────────────
    # These modes never fall through to the PE-only pipeline below; they work
    # on PE, ELF and Mach-O containers alike.
    if getattr(args, 'trigger_mode', False):
        return run_trigger_mode(target, out_dir, args)

    if getattr(args, 'onefile_unpack', False):
        manifest = run_onefile_unpack(
            target, out_dir,
            max_file_size=getattr(args, 'onefile_max_bytes', None))
        return 0 if manifest else 1

    if getattr(args, 'devirt', False):
        return run_devirt_cli(target, out_dir, args)

    # ------------------------------------------------------------------ STATIC PHASE
    _inject_only = args.inject and (args.pid is not None or args.launch)
    # ── --list-modules early exit ──────────────────────────────────────────
    if getattr(args, 'list_modules', False):
        _filter = getattr(args, 'filter_str', None)
        try:
            import pefile as _list_pefile
            with open(target, 'rb') as _list_file:
                _outer_data = _list_file.read()
            _outer_pe = _list_pefile.PE(data=_outer_data)
            _list_onefile = _ndl_extract_nuitka_onefile_child(_outer_pe)
            _effective_data = (_list_onefile['data']
                               if _list_onefile is not None else _outer_data)
            _effective_name = (_list_onefile['name']
                               if _list_onefile is not None
                               else os.path.basename(target))
        except Exception as _list_exc:
            print(f"[ERROR] Could not resolve target PE: {_list_exc}",
                  file=sys.stderr)
            raise SystemExit(1)

        _blob = extract_pe_constants_blob(
            target, pe_data=_effective_data, _resolve_onefile=False)
        _raw_is_enc = bool(_blob) and (
            CommercialBypass().is_blob_encrypted(_blob)
            or CommercialBypass().has_commercial_digest(_blob))
        _blob = _decrypt_blob_if_encrypted(
            target, _blob, pe_data=_effective_data)
        if not _blob:
            print(f"[ERROR] Could not find Nuitka constants blob in {target}", file=sys.stderr)
            raise SystemExit(1)

        log(f"Blob: {len(_blob):,} bytes")

        _is_enc = _raw_is_enc
        _bypass_for_names = CommercialBypass() if _raw_is_enc else None
        _list_diag = {}
        _modules = parse_blob_modules(
            _blob, _bypass_for_names, strict=True,
            diagnostics=_list_diag)

        if not _modules:
            print("[ERROR] Blob found but no modules parsed — format may be unsupported.",
                  file=sys.stderr)
            raise SystemExit(1)

        if _filter:
            _f = _filter.lower()
            _modules = [(n, d) for n, d in _modules if _f in n.lower()]

        print(f"\n  Target  : {os.path.basename(target)}")
        if _list_onefile is not None:
            print(f"  Child   : {_effective_name}")
        print(f"  Edition : {'protected/commercial' if _is_enc else 'open-source'}")
        print(f"  Modules : {len(_modules)}")
        if _filter:
            print(f"  Filter  : '{_filter}'")
        print()
        print(f"  {'#':<5}  {'MODULE NAME':<55}  {'SIZE':>9}  {'NOTE'}")
        print("  " + "─" * 80)
        for _i, (_n, _d) in enumerate(_modules, 1):
            _note = ""
            if _n == "":
                _note = "← shared global constants (not a Python module)"
            elif _n == ".bytecode":
                _note = "← .pyc bytecode chunk"
            elif _n in ("__main__", "") or ("." not in _n and not _n.startswith("_")):
                _note = "← likely main module"
            print(f"  {_i:<5}  {_n:<55}  {len(_d)/1024:>7.1f} KB  {_note}")
        print()
        _sel = ",".join(n for n, _ in _modules
                        if n not in ("", ".bytecode"))
        print("  ── Ready to use with --only: ──────────────────────────────────")
        print(f"  python nuitka_decompiler.py {os.path.basename(target)} --only {_sel}")
        print()
        raise SystemExit(0)

    if _inject_only:
        # Skip all static analysis — go directly to runtime injection
        os.makedirs(out_dir, exist_ok=True)
        success = True
    else:
        only_list = None
        if args.only:
            only_list = [m.strip() for m in args.only.split(',') if m.strip()]
        engine = NuitkalizatorPro(
            target_path=target,
            output_dir=out_dir,
            main_only=not args.all,
            only_modules=only_list,
            decompile_pyc=not (args.no_pyc_decompile or args.nbc_only),
            nbc_only=args.nbc_only,
            user_nbc=args.user_nbc,
            include_native_asm=getattr(args, 'nbc_full_asm', False),
        )
        success = engine.run()

    # ------------------------------------------------------------------ DYNAMIC PHASE
    if args.inject:
        print_section("DYNAMIC PHASE: DLL INJECTION")

        if sys.platform != 'win32':
            log_err("Dynamic injection is Windows-only."); return 1 if not success else 0

        try:
            injector = DllInjector(
                dll_path=args.dll,
                hook_script_path=args.hook_script,
                out_dir=out_dir,
                log_fn=lambda m: print(f"{C.BRIGHT_CYAN}[INJ]{C.RESET} {m}"),
            )
        except RuntimeError as e:
            log_err(str(e)); return 1

        old_idx = injector.get_latest_dump_idx()

        injected = False
        if args.pid:
            # Inject into explicit PID
            log(f"Injecting into PID {args.pid} ...")
            injected = injector.inject(args.pid, f"PID-{args.pid}", target)
        elif args.launch:
            # Launch the target EXE and inject
            if not target.endswith('.exe'):
                log_err("--launch requires a .exe target"); return 1
            log(f"Launching and injecting: {target}")
            injected = injector.launch_and_inject(target, wait_timeout=60)
        else:
            # No PID, no launch: scan for a running process by EXE name
            exe_name = os.path.basename(target)
            log(f"Searching for running process: {exe_name}")
            pids = injector.find_pids_by_name(exe_name)
            if not pids:
                log_err(f"No running process named '{exe_name}'. "
                        "Use --launch to start it, or --pid to specify explicitly.")
                return 1 if not success else 0
            # Prefer the first PID that already has Python loaded
            for pid in pids:
                if injector._find_python_dll(pid):
                    log(f"Found running {exe_name} with Python loaded (PID {pid})")
                    injected = injector.inject(pid, exe_name, target)
                    break
            if not injected:
                log_err("Could not inject into any running instance")
                return 1 if not success else 0

        if not injected:
            log_err("Injection failed — see log above"); return 1

        log(f"Waiting up to {args.dump_timeout}s for hook dump ...")
        dump_dir = injector.wait_for_dump(args.dump_timeout, old_idx)
        if dump_dir:
            log_ok(f"Hook dump ready: {dump_dir}")
            src_dir = os.path.join(dump_dir, "RECONSTRUCTED_SOURCE")
            if os.path.isdir(src_dir):
                py_files = [f for f in os.listdir(src_dir) if f.endswith('.py')
                            and f != "__hook__.py"]
                log_ok(f"Dynamic sources captured: {len(py_files)} file(s) in {src_dir}")
                # Copy dynamic sources alongside the static output
                import shutil
                dyn_out = os.path.join(out_dir, "DYNAMIC_SOURCE")
                shutil.copytree(src_dir, dyn_out, dirs_exist_ok=True)
                log_ok(f"Copied to: {dyn_out}")
            else:
                log_warn("No RECONSTRUCTED_SOURCE dir in dump — hook may not have run")
        else:
            log_warn(f"No dump appeared after {args.dump_timeout}s. "
                     f"Check {injector.dump_base} and "
                     f"{os.path.join((os.getenv('LOCALAPPDATA') or os.getenv('TEMP') or '.'), 'nuitka_decompiler_dumps', 'hook_dll.log')}")

    return 0 if success else 1


if __name__ == "__main__":
    # --dev-only e' una modalità del motore NDX: se presente (anche senza
    # --ndx) attiva direttamente il CLI NDX invece di far morire argparse
    # del pipeline legacy con "unrecognized arguments".
    _NDX_RUN_ = ('--ndx' in sys.argv) or ('--dev-only' in sys.argv)
    while '--ndx' in sys.argv:
        sys.argv.remove('--ndx')
    if not _NDX_RUN_:
        try:
            sys.exit(main())
        except KeyboardInterrupt:
            print(f"\n\n{C.BRIGHT_RED}[!] Interrupted by user{C.RESET}")
        except Exception as e:
            print(f"\n{C.BRIGHT_RED}[FATAL] {e}{C.RESET}")
            import traceback
            traceback.print_exc()





# ==========================================================================
# === NDX MODULE: ndx_image.py
# ==========================================================================


import struct
import re

try:
    import pefile
except ImportError:
    pefile = None


class NdxSection:
    __slots__ = ('name', 'addr', 'offset', 'size', 'vsize', 'flags', 'type')

    def __init__(self, name, addr, offset, size, vsize=None, flags=0, typ=0):
        self.name = name
        self.addr = addr
        self.offset = offset
        self.size = size
        self.vsize = vsize if vsize is not None else size
        self.flags = flags
        self.type = typ

    def contains_va(self, va):
        return self.addr <= va < self.addr + max(self.size, self.vsize)

    def va_to_off(self, va):
        if self.contains_va(va):
            return self.offset + (va - self.addr)
        return None

    def __repr__(self):
        return f"<NdxSection {self.name} va={self.addr:#x} off={self.offset:#x} size={self.size:#x}>"


class BinaryImage:
    """Interfaccia unificata PE/ELF: data, sezioni, simboli, imports, relocs."""

    FORMAT_PE = 'pe'
    FORMAT_ELF = 'elf'
    FORMAT_MACHO = 'macho'

    def __init__(self, data: bytes, path=''):
        self.data = data
        self.path = path
        self.sections = []
        self.symbols = {}          # va -> name (symtab completo se presente)
        self.imports = {}          # va (IAT/GOT) -> nome simbolo importato
        self.imported_libraries = []  # nomi DLL/DSO per rilevamento ABI
        self.plt_map = {}          # va stub PLT -> nome
        self.exports = {}          # nome esportato -> va (PE export table / ELF dynsym)
        self.rel_relative = {}     # va -> addend (R_X86_64_RELATIVE / PE base reloc)
        self.base = 0
        self.entry = 0
        self.fmt = None
        self._parse()

    # ------------------------------------------------------------------ util
    def va_to_off(self, va):
        if va is None:
            return None
        for s in self.sections:
            o = s.va_to_off(va)
            if o is not None and o < len(self.data):
                return o
        return None

    def off_to_va(self, off):
        for s in self.sections:
            if s.offset <= off < s.offset + s.size:
                return s.addr + (off - s.offset)
        return None

    def read(self, va, n):
        o = self.va_to_off(va)
        if o is None:
            return None
        return self.data[o:o + n]

    def read_cstr(self, va, max_len=4096):
        o = self.va_to_off(va)
        if o is None:
            return None
        end = self.data.find(b'\x00', o, min(o + max_len, len(self.data)))
        if end < 0:
            return None
        try:
            return self.data[o:end].decode('utf-8', errors='replace')
        except Exception:
            return None

    def read_u64(self, va):
        b = self.read(va, 8)
        return struct.unpack('<Q', b)[0] if b and len(b) == 8 else None

    def read_u32(self, va):
        b = self.read(va, 4)
        return struct.unpack('<I', b)[0] if b and len(b) == 4 else None

    def sec_name(self, va):
        for s in self.sections:
            if s.contains_va(va):
                return s.name
        return '?'

    def is_exec(self, va):
        n = self.sec_name(va)
        return n in ('.text', '.plt', '.plt.got', '.init', 'code', '__TEXT', '.text%')

    def sym_at(self, va):
        return self.symbols.get(va)

    # ------------------------------------------------------------------ parse
    def _parse(self):
        platform = ndx_platform_evidence(self.data)
        if not platform['native_decoder_supported']:
            raise NdxABIError('; '.join(platform['issues']))
        if self.data[:2] == b'MZ':
            self._parse_pe()
        elif self.data[:4] == b'\x7fELF':
            self._parse_elf()
        elif self.data[:4] in (b'\xcf\xfa\xed\xfe', b'\xca\xfe\xba\xbe'):
            self._parse_macho()
        else:
            raise ValueError('formato binario non riconosciuto')

    # ------------------------------------------------------------------- ELF
    def _parse_elf(self):
        self.fmt = self.FORMAT_ELF
        d = self.data
        is64 = d[4] == 2
        if not is64:
            raise ValueError('solo ELF64 supportato')
        e_entry, e_phoff, e_shoff = struct.unpack_from('<QQQ', d, 0x18)
        e_phentsize, e_phnum = struct.unpack_from('<HH', d, 0x36)
        e_shentsize, e_shnum, e_shstrndx = struct.unpack_from('<HHH', d, 0x3a)
        self.entry = e_entry

        shs = []
        for i in range(e_shnum):
            off = e_shoff + i * e_shentsize
            sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size = \
                struct.unpack_from('<IIQQQQ', d, off)
            sh_link = struct.unpack_from('<I', d, off + 40)[0]
            sh_entsize = struct.unpack_from('<Q', d, off + 56)[0]
            shs.append(dict(name_off=sh_name, type=sh_type, addr=sh_addr,
                            offset=sh_offset, size=sh_size, link=sh_link,
                            entsize=sh_entsize))
        if e_shstrndx < len(shs):
            shstr = shs[e_shstrndx]
            for s in shs:
                end = d.index(b'\x00', shstr['offset'] + s['name_off'])
                s['name'] = d[shstr['offset'] + s['name_off']:end].decode(
                    errors='replace')
        else:
            for s in shs:
                s['name'] = ''
        self._elf_shs = shs

        for s in shs:
            if s['type'] != 8 and s['size'] > 0 and s['addr']:
                self.sections.append(NdxSection(s['name'], s['addr'], s['offset'],
                                              s['size']))
            elif s['type'] == 8 and s['addr']:
                # .bss: mappa con dimensione virtuale
                self.sections.append(NdxSection(s['name'], s['addr'],
                                             len(self.data), 0, vsize=s['size'],
                                             typ=8))

        self._elf_needed(shs)
        self._elf_dynsym(shs)
        self._elf_symtab(shs)
        self._elf_relocs(shs)
        self._elf_plt(shs)

    def _elf_needed(self, shs):
        """Read DT_NEEDED through the dynamic section's linked string table."""
        data = self.data
        for section in shs:
            if section['type'] != 6 or not 0 <= section['link'] < len(shs):
                continue
            strings = shs[section['link']]
            begin, end = strings['offset'], strings['offset'] + strings['size']
            if not 0 <= begin <= end <= len(data):
                raise NdxABIError('Invalid ELF dynamic string table')
            first, last = section['offset'], section['offset'] + section['size']
            if not 0 <= first <= last <= len(data) or section['size'] % 16:
                raise NdxABIError('Invalid ELF dynamic section')
            for position in range(first, last, 16):
                tag, value = struct.unpack_from('<qQ', data, position)
                if tag == 0:
                    break
                if tag != 1:
                    continue
                offset = begin + value
                stop = data.find(b'\0', offset, end) if begin <= offset < end else -1
                if stop < 0:
                    raise NdxABIError('Invalid ELF DT_NEEDED string')
                library = data[offset:stop].decode('utf8', errors='replace')
                if library not in self.imported_libraries:
                    self.imported_libraries.append(library)

    def _elf_dynsym(self, shs):
        d = self.data
        for s in shs:
            if s['name'] == '.dynsym' and s['link'] < len(shs):
                strtab = shs[s['link']]
                n = s['size'] // 24
                self._dynsyms = []
                for i in range(n):
                    st_name, st_info, st_other, st_shndx, st_value, st_size = \
                        struct.unpack_from('<IBBHQQ', d, s['offset'] + i * 24)
                    if st_value:
                        end = d.index(b'\x00', strtab['offset'] + st_name)
                        nm = d[strtab['offset'] + st_name:end].decode(
                            errors='replace')
                        self.symbols.setdefault(st_value, nm)
                    self._dynsyms.append((st_name, st_value, st_info))

    def _elf_symtab(self, shs):
        d = self.data
        for s in shs:
            if s['name'] == '.symtab' and s['link'] < len(shs):
                strtab = shs[s['link']]
                n = s['size'] // 24
                for i in range(n):
                    st_name, st_info, st_other, st_shndx, st_value, st_size = \
                        struct.unpack_from('<IBBHQQ', d, s['offset'] + i * 24)
                    if st_value and st_name:
                        end = d.index(b'\x00', strtab['offset'] + st_name)
                        nm = d[strtab['offset'] + st_name:end].decode(
                            errors='replace')
                        self.symbols.setdefault(st_value, nm)

    def _elf_relocs(self, shs):
        d = self.data
        for s in shs:
            if s['type'] == 4 and s.get('entsize') == 24:  # SHT_RELA
                n = s['size'] // 24
                is_plt = s['name'] == '.rela.plt'
                for i in range(n):
                    r_offset, r_info, r_addend = struct.unpack_from(
                        '<QQq', d, s['offset'] + i * 24)
                    rtype = r_info & 0xffffffff
                    sym_idx = r_info >> 32
                    if rtype == 8:  # R_X86_64_RELATIVE
                        self.rel_relative[r_offset] = r_addend
                    elif rtype == 7 and is_plt:  # R_X86_64_JUMP_SLOT
                        nm = self._dynsym_name(sym_idx)
                        if nm:
                            self.imports[r_offset] = nm

    def _dynsym_name(self, idx):
        syms = getattr(self, '_dynsyms', None)
        if not syms or idx >= len(syms):
            return None
        st_name = syms[idx][0]
        for s in self._elf_shs:
            if s['name'] == '.dynstr':
                end = self.data.index(b'\x00', s['offset'] + st_name)
                return self.data[s['offset'] + st_name:end].decode(
                    errors='replace')
        return None

    def _elf_plt(self, shs):
        # .plt: stubs; ogni stub jmp [rip+disp] → GOT entry → import name
        plt = next((s for s in shs if s['name'] == '.plt'), None)
        if not plt:
            return
        d = self.data
        stub_size = 16
        for i in range(plt['size'] // stub_size):
            stub_va = plt['addr'] + i * stub_size
            stub = d[plt['offset'] + i * stub_size: plt['offset'] +
                     (i + 1) * stub_size]
            m = re.search(rb'\xff\x25(....)', stub, re.DOTALL)
            if m:
                idx = m.start()
                disp = struct.unpack('<i', m.group(1))[0]
                got_va = stub_va + idx + 6 + disp
                nm = self.imports.get(got_va)
                if nm:
                    self.plt_map[stub_va] = nm

    # -------------------------------------------------------------------- PE
    def _parse_pe(self):
        self.fmt = self.FORMAT_PE
        if pefile is None:
            raise ValueError('pefile richiesto per binari PE')
        pe = pefile.PE(data=self.data)
        self._pe = pe
        self.base = pe.OPTIONAL_HEADER.ImageBase
        self.entry = self.base + pe.OPTIONAL_HEADER.AddressOfEntryPoint
        for s in pe.sections:
            name = s.Name.rstrip(b'\x00').decode(errors='replace')
            self.sections.append(NdxSection(
                name, self.base + s.VirtualAddress, s.PointerToRawData,
                s.SizeOfRawData, vsize=max(s.Misc_VirtualSize, 1)))
        if hasattr(pe, 'DIRECTORY_ENTRY_IMPORT'):
            for mod in pe.DIRECTORY_ENTRY_IMPORT:
                try:
                    library_name = mod.dll.decode(errors='replace')
                except Exception:
                    library_name = str(getattr(mod, 'dll', '') or '')
                if library_name and library_name not in self.imported_libraries:
                    self.imported_libraries.append(library_name)
                for imp in mod.imports:
                    if imp.name and imp.address:
                        self.imports[imp.address] = imp.name.decode(
                            errors='replace')
        # A Nuitka --module build (.pyd/.so) has NO meta-path loader table:
        # CPython loads it through the ordinary extension-module ABI, so the
        # only proof of the module init entry point is the exported
        # ``PyInit_<name>`` (``PyInitU_<punycode>`` for non-ASCII names).
        # Without this the module reports func_ptr=0 and is skipped entirely.
        for exp_dir in (getattr(pe, 'DIRECTORY_ENTRY_EXPORT', None),):
            if exp_dir is None:
                continue
            for symbol in getattr(exp_dir, 'symbols', ()) or ():
                if not symbol.name or not symbol.address:
                    continue
                try:
                    export_name = symbol.name.decode(errors='replace')
                except Exception:
                    continue
                self.exports[export_name] = self.base + int(symbol.address)
        # x86-64 PE unwind metadata gives exact native-function extents.  A
        # logical MSVC function can consist of multiple RUNTIME_FUNCTION
        # records linked through UNW_FLAG_CHAININFO; retain physical ranges for
        # containment and map every linked fragment to one logical extent.
        self._pe_function_ranges = []
        self._pe_function_starts = []
        self._pe_function_logical = {}
        try:
            records = []
            for runtime_function in getattr(
                    pe, 'DIRECTORY_ENTRY_EXCEPTION', ()) or ():
                begin_rva = int(runtime_function.struct.BeginAddress)
                end_rva = int(runtime_function.struct.EndAddress)
                unwind_rva = int(getattr(
                    runtime_function.struct, 'UnwindData', 0)) & ~1
                if not (0 <= begin_rva < end_rva):
                    continue
                begin = self.base + begin_rva
                end = self.base + end_rva
                if not self.is_exec(begin):
                    continue
                record = {
                    'begin': begin, 'end': end,
                    'begin_rva': begin_rva, 'end_rva': end_rva,
                    'unwind_rva': unwind_rva, 'chain': None,
                }
                # UNWIND_INFO stores an aligned RUNTIME_FUNCTION triple after
                # its unwind codes when CHAININFO is set.  Parse defensively:
                # malformed/stripped data remains a standalone physical range.
                try:
                    unwind_off = pe.get_offset_from_rva(unwind_rva)
                    raw = pe.__data__
                    if unwind_off is not None and unwind_off + 4 <= len(raw):
                        flags = int(raw[unwind_off]) >> 3
                        code_count = int(raw[unwind_off + 2])
                        chain_off = (
                            unwind_off + 4 + code_count * 2 + 3) & ~3
                        if flags & 0x4 and chain_off + 12 <= len(raw):
                            cb, ce, cu = struct.unpack_from(
                                '<III', raw, chain_off)
                            if 0 <= cb < ce:
                                record['chain'] = (cb, ce, cu & ~1)
                except Exception:
                    pass
                records.append(record)

            records.sort(key=lambda item: (item['begin'], item['end']))
            self._pe_function_ranges = [
                (item['begin'], item['end']) for item in records]
            self._pe_function_starts = [item['begin'] for item in records]

            parent = list(range(len(records)))

            def find_parent(index):
                while parent[index] != index:
                    parent[index] = parent[parent[index]]
                    index = parent[index]
                return index

            def union(left, right):
                left_root = find_parent(left)
                right_root = find_parent(right)
                if left_root != right_root:
                    parent[right_root] = left_root

            by_triple = {
                (item['begin_rva'], item['end_rva'], item['unwind_rva']): i
                for i, item in enumerate(records)
            }
            by_range = {
                (item['begin_rva'], item['end_rva']): i
                for i, item in enumerate(records)
            }
            for i, item in enumerate(records):
                chain = item.get('chain')
                if chain is None:
                    continue
                linked = by_triple.get(chain)
                if linked is None:
                    linked = by_range.get(chain[:2])
                if linked is not None:
                    union(i, linked)

            groups = {}
            for i, item in enumerate(records):
                groups.setdefault(find_parent(i), []).append(item)
            for group in groups.values():
                logical = (
                    min(item['begin'] for item in group),
                    max(item['end'] for item in group),
                )
                for item in group:
                    self._pe_function_logical[item['begin']] = logical
        except Exception:
            self._pe_function_ranges = []
            self._pe_function_starts = []
            self._pe_function_logical = {}
        # simboli COFF (raro, ma se presenti)
        try:
            if hasattr(pe, 'DIRECTORY_ENTRY_SYMBOLS'):
                for sym in pe.DIRECTORY_ENTRY_SYMBOLS:
                    pass
        except Exception:
            pass

    # ----------------------------------------------------------------- MachO
    def _parse_macho(self):
        self.fmt = self.FORMAT_MACHO
        raise NotImplementedError('Mach-O: parsing base (da completare se richiesto)')

    # ------------------------------------------------------- function bounds

    # ------------------------------------------------- eh_frame function bounds
    def elf_function_starts(self):
        """Parse .eh_frame_hdr: tabella binaria di tutte le funzioni con FDE.
        Ritorna lista ordinata di VA iniziali (function discovery universale)."""
        if self.fmt != self.FORMAT_ELF or hasattr(self, '_func_starts'):
            return getattr(self, '_func_starts', [])
        self._func_starts = []
        d = self.data
        for s in self._elf_shs:
            if s['name'] == '.eh_frame_hdr':
                off = s['offset']
                version = d[off]
                eh_frame_ptr_enc = d[off + 1]
                fde_count_enc = d[off + 2]
                table_enc = d[off + 3]
                pos = off + 4
                # eh_frame_ptr (di solito sdata4 pcrel)
                if eh_frame_ptr_enc == 0x1b:  # DW_EH_PE_pcrel | sdata4
                    disp = struct.unpack_from('<i', d, pos)[0]
                    pos += 4
                else:
                    pos += 4
                if fde_count_enc == 0x03:  # udata4
                    count = struct.unpack_from('<I', d, pos)[0]
                    pos += 4
                elif fde_count_enc == 0x1b:
                    count = struct.unpack_from('<i', d, pos)[0]
                    pos += 4
                else:
                    return self._func_starts
                # table_enc tipicamente 0x3b = datarel|sdata4
                entries = []
                for i in range(min(count, 2000000)):
                    init_loc = struct.unpack_from('<i', d, pos)[0]
                    fde_ptr = struct.unpack_from('<i', d, pos + 4)[0]
                    pos += 8
                    va = s['addr'] + init_loc
                    if va:
                        entries.append(va)
                self._func_starts = sorted(set(entries))
                break
        return self._func_starts

    def function_bounds(self, va):
        """(start, end) della funzione contenente va, via eh_frame_hdr."""
        if self.fmt == self.FORMAT_PE:
            import bisect
            starts = getattr(self, '_pe_function_starts', ())
            ranges = getattr(self, '_pe_function_ranges', ())
            index = bisect.bisect_right(starts, va) - 1
            if index >= 0:
                start, end = ranges[index]
                if start <= va < end:
                    return getattr(self, '_pe_function_logical', {}).get(
                        start, (start, end))
            return None
        starts = self.elf_function_starts()
        if not starts:
            return None
        import bisect
        i = bisect.bisect_right(starts, va) - 1
        if i < 0:
            return None
        start = starts[i]
        if start > va:
            return None
        end = starts[i + 1] if i + 1 < len(starts) else start + 0x10000
        return (start, end)

    def function_hints(self):
        """VA candidate di funzioni: simboli + entry + PLT."""
        hints = set()
        for va, nm in self.symbols.items():
            hints.add(va)
        hints.add(self.entry)
        return sorted(hints)


def load_image(path):
    with open(path, 'rb') as f:
        data = f.read()
    return BinaryImage(data, path=path)



