# Pre-compute as a frozenset of lowercased names for O(1) lookup.
_KNOWN_LIBRARY_SET = frozenset(lib.lower() for lib in KNOWN_LIBRARY_PREFIXES)


def is_main_module(name):
    if not name: return False
    base = name.split('.')[0].lower()
    # Exact match against the known library set (no startswith — avoids
    # matching 'keyboard' against 'key' or 'mss' against 'ms').
    if base in _KNOWN_LIBRARY_SET:
        return False
    # Catch private stdlib modules: _thread, _io, _collections_abc, etc.
    # But NOT dunder names like __main__, __init__ — those could be dev code.
    if base.startswith('_') and not base.startswith('__'):
        return False
    return True


def module_matches_patterns(name, patterns):
    """Match exact module names or shell-style globs used by ``--only``.

    Older releases special-cased only ``pkg.*``.  That made documented-looking
    selectors such as ``**main**`` silently behave as exact names.  Accept the
    normal ``*``, ``?`` and character-class syntax everywhere.  A backslash
    immediately before ``_`` is also discarded because PowerShell users often
    paste Markdown-escaped names such as ``parents\\_main``.
    """
    if not patterns:
        return True
    for pat in patterns:
        pat = str(pat).replace(r'\_', '_')
        if pat == name or fnmatch.fnmatchcase(name, pat):
            return True
    return False


# Module-level tracker for the 'p' (previous) constant tag. ``None`` is itself
# a valid constant, therefore absence needs a distinct sentinel.
_NO_NUITKA_PREVIOUS = object()
_last_unpacked = _NO_NUITKA_PREVIOUS


class _NuitkaDecoderAbort(Exception):
    """A bounded-decoder candidate was rejected before unsafe expansion."""

    def __init__(self, reason, pos):
        super().__init__(reason)
        self.reason = str(reason)
        self.pos = int(pos)


class _NuitkaDecodeBudget:
    """Per-stream recursion and decoded-node budget."""

    __slots__ = ('initial_nodes', 'nodes_remaining', 'max_depth', 'max_seen_depth')

    def __init__(self, node_budget, max_depth):
        self.initial_nodes = max(0, int(node_budget))
        self.nodes_remaining = self.initial_nodes
        self.max_depth = max(0, int(max_depth))
        self.max_seen_depth = 0

    def consume_node(self, pos, depth):
        if depth > self.max_depth:
            raise _NuitkaDecoderAbort(
                f"constant nesting depth {depth} exceeds limit {self.max_depth}", pos)
        self.max_seen_depth = max(self.max_seen_depth, depth)
        if self.nodes_remaining <= 0:
            raise _NuitkaDecoderAbort(
                f"constant node budget {self.initial_nodes} exhausted", pos)
        self.nodes_remaining -= 1


def _new_nuitka_decode_budget(data, start_pos=0, *, node_budget=None, max_depth=128):
    remaining = max(0, len(data) - max(0, int(start_pos)))
    if node_budget is None:
        # Every constant consumes at least its tag byte. The absolute cap protects
        # aggressive scans of adversarial multi-megabyte ranges.
        node_budget = min(remaining, 1_000_000)
    return _NuitkaDecodeBudget(node_budget, max_depth)


def _validate_constant_sequence(data, pos, count, state, *, multiplier=1):
    """Reject impossible child counts before constructing their output list."""
    try:
        count = int(count)
        required = count * int(multiplier)
    except (TypeError, ValueError, OverflowError):
        raise _NuitkaDecoderAbort("invalid constant sequence count", pos)
    if count < 0 or required < 0:
        raise _NuitkaDecoderAbort("negative constant sequence count", pos)
    remaining_bytes = max(0, len(data) - pos)
    if required > remaining_bytes:
        raise _NuitkaDecoderAbort(
            f"constant sequence needs {required} tag bytes, only {remaining_bytes} remain", pos)
    if required > state.nodes_remaining:
        raise _NuitkaDecoderAbort(
            f"constant sequence needs {required} nodes, budget has {state.nodes_remaining}", pos)
    return count


def _unpack_constant_sequence(data, pos, count, *, _decoder_state=None, _depth=0,
                              _validated_multiplier=1):
    """Decode one C ``_unpackBlobConstants`` output array.

    Nuitka's ``p`` tag means the previous element of the *current output
    array*, not the last recursively decoded object. Resetting/restoring the
    tracker at every tuple/list/dict-side/special-value sequence matches the C
    helper and prevents nested containers from leaking previous-value state.
    """
    global _last_unpacked
    state = _decoder_state or _new_nuitka_decode_budget(data, pos)
    count = _validate_constant_sequence(
        data, pos, count, state, multiplier=_validated_multiplier)
    parent_previous = _last_unpacked
    _last_unpacked = _NO_NUITKA_PREVIOUS
    out = []
    try:
        for _ in range(count):
            item, pos = unpack_single_constant(
                data, pos, _decoder_state=state, _depth=_depth)
            if item is _Nuitka_END_OF_STREAM:
                raise _NuitkaDecoderAbort(
                    "premature constant-stream terminator", max(0, pos - 1))
            out.append(item)
    finally:
        _last_unpacked = parent_previous
    return out, pos


def unpack_single_constant(data, pos, *, _decoder_state=None, _depth=0):
    """Unpack a single value from the Nuitka constants blob.

    Handles all known tags from HelpersConstantsBlob.c and DataComposer.py.
    Synchronized with Nuitka Commercial 2025 source.
    """
    global _last_unpacked
    state = _decoder_state or _new_nuitka_decode_budget(data, pos)
    state.consume_node(pos, _depth)

    if pos >= len(data):
        raise _NuitkaDecoderAbort("truncated constant tag", pos)

    marker = data[pos]
    ch = chr(marker) if 32 <= marker < 127 else None
    pos += 1

    # === 'p' - previous ref: repeat last unpacked value (NO VLQ read) ===
    if ch == 'p':
        if _last_unpacked is _NO_NUITKA_PREVIOUS:
            raise _NuitkaDecoderAbort(
                "previous-value tag has no previous constant", pos - 1)
        return _last_unpacked, pos

    if ch == '.':
        return _Nuitka_END_OF_STREAM, pos

    result = _unpack_constant_inner(
        data, pos, ch, marker, _decoder_state=state, _depth=_depth)
    if result is not None:
        val, pos = result
        if val is _Nuitka_PARSE_ERROR:
            raise _NuitkaDecoderAbort(
                "unrecognized or truncated constant", max(0, pos - 1))
        _last_unpacked = val
        return val, pos

    _last_unpacked = _NO_NUITKA_PREVIOUS
    raise _NuitkaDecoderAbort(
        "unrecognized constant tag", max(0, pos - 1))


def _unpack_constant_inner(data, pos, ch, marker, *, _decoder_state=None, _depth=0):
    """Internal dispatcher for all constant types except 'p'."""
    state = _decoder_state or _new_nuitka_decode_budget(data, pos)

    # --- Strings ---
    if ch in ('a', 'u'):  # null-terminated string (attribute or unicode)
        end = data.find(b'\x00', pos)
        if end == -1:
            raise _NuitkaDecoderAbort("unterminated unicode constant", pos)
        if ch == 'a' and _target_python_hex() < 0x300:
            return data[pos:end], end + 1
        try:
            value = data[pos:end].decode('utf-8', errors='surrogatepass')
        except UnicodeDecodeError:
            raise _NuitkaDecoderAbort("invalid UTF-8 unicode constant", pos)
        return value, end + 1

    elif ch == 'w':  # single-char unicode
        if pos < len(data):
            try:
                return data[pos:pos + 1].decode(
                    'utf-8', errors='surrogatepass'), pos + 1
            except UnicodeDecodeError:
                raise _NuitkaDecoderAbort(
                    "invalid single-byte unicode constant", pos)
        raise _NuitkaDecoderAbort("truncated unicode constant", pos)

    elif ch == 'v':  # length-prefixed unicode (contains null bytes)
        size, pos = _read_profile_payload_length(data, pos)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated unicode payload", pos)
        try:
            value = data[pos:pos + size].decode(
                'utf-8', errors='surrogatepass')
        except UnicodeDecodeError:
            raise _NuitkaDecoderAbort("invalid UTF-8 unicode payload", pos)
        return value, pos + size

    elif ch == 's':  # empty string
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "empty-string tag is absent from the selected old profile",
                pos - 1)
        return "", pos

    # --- Bytes ---
    elif ch == 'c':  # Python3: zero-terminated bytes / Python2: str
        end = data.find(b'\x00', pos)
        if end == -1:
            raise _NuitkaDecoderAbort("unterminated bytes constant", pos)
        return data[pos:end], end + 1

    elif ch == 'b':  # bytes with VLQ length (contains null bytes)
        size, pos = _read_profile_payload_length(data, pos)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated bytes payload", pos)
        return data[pos:pos + size], pos + size

    elif ch == 'B':  # bytearray
        size, pos = _read_profile_payload_length(data, pos)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated bytearray payload", pos)
        return bytearray(data[pos:pos + size]), pos + size

    elif ch == 'd':  # single byte (Python3: bytes len 1)
        if pos < len(data): return bytes([data[pos]]), pos + 1
        raise _NuitkaDecoderAbort("truncated single-byte constant", pos)

    # --- Singletons ---
    elif ch == 'n': return None, pos
    elif ch == 't': return True, pos
    elif ch == 'F': return False, pos

    # --- Integers ---
    elif ch == 'l':
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            # Historical DataComposer: C ``long`` payload, signed 32-bit on
            # Windows (negative values keep the same tag, two's complement).
            if pos + 4 > len(data):
                raise _NuitkaDecoderAbort("truncated fixed32 long", pos)
            return struct.unpack_from('<i', data, pos)[0], pos + 4
        value, pos = read_vlq(data, pos)       # current: positive magnitude
        if value >= 0x7FFFFFFF:
            raise _NuitkaDecoderAbort(
                "non-canonical modern long must use big-integer tag", pos)
        return value, pos
    elif ch == 'q':
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            # Historical ``long long`` payload (despite the mode name): fixed
            # signed 64-bit. Values such as 0x7fffffff/0xffffffff commonly use
            # this tag and are positive, so negating them was doubly wrong.
            if pos + 8 > len(data):
                raise _NuitkaDecoderAbort("truncated fixed64 long", pos)
            value = struct.unpack_from('<q', data, pos)[0]
            return value, pos + 8
        value, pos = read_vlq(data, pos)       # current: negative magnitude
        if value == 0:
            raise _NuitkaDecoderAbort(
                "non-canonical negative zero", pos)
        if value >= 0x7FFFFFFF:
            raise _NuitkaDecoderAbort(
                "non-canonical modern long must use big-integer tag", pos)
        return -value, pos

    elif ch == 'I':
        if _target_python_hex() >= 0x300:
            raise _NuitkaDecoderAbort(
                "integer-I tag is Python-2-only", pos - 1)
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "integer-I tag is absent from the selected hybrid profile",
                pos - 1)
        value, pos = read_vlq(data, pos)
        if value == 0:
            raise _NuitkaDecoderAbort(
                "non-canonical negative zero", pos)
        return -value, pos
    elif ch == 'i':
        if _target_python_hex() >= 0x300:
            raise _NuitkaDecoderAbort(
                "integer-i tag is Python-2-only", pos - 1)
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            if pos + 4 > len(data):
                raise _NuitkaDecoderAbort("truncated fixed32 integer", pos)
            return struct.unpack_from('<i', data, pos)[0], pos + 4
        value, pos = read_vlq(data, pos)
        return value, pos

    elif (ch == 'g'
          and _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31"):
        if pos >= len(data) or data[pos:pos + 1] not in (b'+', b'-'):
            raise _NuitkaDecoderAbort(
                "invalid hybrid big-integer sign", pos)
        negative = data[pos:pos + 1] == b'-'
        pos += 1
        if pos + 4 > len(data):
            raise _NuitkaDecoderAbort(
                "truncated hybrid big-integer limb count", pos)
        num_parts = struct.unpack_from('<i', data, pos)[0]
        pos += 4
        try:
            max_int_bits = max(64, int(os.environ.get(
                'NDL_MAX_INT_BITS', str(8 * 1024 * 1024))))
        except Exception:
            max_int_bits = 8 * 1024 * 1024
        max_limbs = max_int_bits // 64
        if (num_parts < 1 or num_parts > max_limbs
                or num_parts > state.nodes_remaining
                or num_parts > (len(data) - pos) // 8):
            raise _NuitkaDecoderAbort(
                f"hybrid big-integer limb count {num_parts} is invalid", pos)
        state.nodes_remaining -= num_parts
        value = 0
        first_part = None
        for _ in range(num_parts):
            part = struct.unpack_from('<Q', data, pos)[0]
            pos += 8
            if first_part is None:
                first_part = part
            value = (value << 64) | part
        if not first_part:
            raise _NuitkaDecoderAbort(
                "non-canonical hybrid big-integer leading limb", pos)
        if ((not negative and value <= 0x7FFFFFFFFFFFFFFF)
                or (negative and value <= 0x8000000000000000)):
            raise _NuitkaDecoderAbort(
                "non-canonical hybrid big integer fits signed 64-bit", pos)
        return (-value if negative else value), pos

    elif (ch in ('g', 'G')
          and _CURRENT_NUITKA_BLOB_PROFILE == "modern_vlq31"):
        # Modern Nuitka uses g/G for positive/negative base-2^31 limbs.
        is_negative = (ch == 'G')
        num_parts, pos = _read_blob_integer(data, pos)
        try:
            max_int_bits = max(62, int(os.environ.get(
                'NDL_MAX_INT_BITS', str(8 * 1024 * 1024))))
        except Exception:
            max_int_bits = 8 * 1024 * 1024
        max_limbs = max_int_bits // 31
        # Modern DataComposer uses g/G at the exact 2**31-1 boundary too.
        # Charge every limb to the stream budget before doing bigint work.
        if (num_parts < 1 or num_parts > len(data) - pos
                or num_parts > max_limbs
                or num_parts > state.nodes_remaining):
            raise _NuitkaDecoderAbort(
                f"big-integer limb count {num_parts} exceeds remaining payload", pos)
        state.nodes_remaining -= num_parts
        parts = []
        for _ in range(num_parts):
            part, pos = _read_blob_integer(data, pos)
            if part > 0x7FFFFFFF:
                raise _NuitkaDecoderAbort(
                    "big-integer limb exceeds 31 bits", pos)
            parts.append(part)
        if not parts or parts[0] == 0:
            raise _NuitkaDecoderAbort(
                "non-canonical big-integer leading limb", pos)

        def _combine_limbs(lo, hi):
            if hi - lo == 1:
                return parts[lo]
            mid = (lo + hi) // 2
            return (_combine_limbs(lo, mid) << (31 * (hi - mid))) | \
                _combine_limbs(mid, hi)

        result = _combine_limbs(0, len(parts))
        if result < 0x7FFFFFFF:
            raise _NuitkaDecoderAbort(
                "non-canonical modern big integer fits l/q tag", pos)
        return (-result if is_negative else result), pos

    # --- Floats ---
    elif ch == 'f':  # double float (8 bytes IEEE 754)
        if pos + 8 <= len(data):
            return struct.unpack('<d', data[pos:pos + 8])[0], pos + 8
        raise _NuitkaDecoderAbort("truncated float constant", pos)

    elif ch == 'Z':  # special float: +0.0, -0.0, +NaN, -NaN, +Inf, -Inf
        if pos < len(data):
            v = data[pos]
            pos += 1
            if v == 0: return 0.0, pos
            elif v == 1: return -0.0, pos
            elif v == 2: return float('nan'), pos
            elif v == 3: return copysign(float('nan'), -1.0), pos
            elif v == 4: return float('inf'), pos
            elif v == 5: return float('-inf'), pos
            else:
                raise _NuitkaDecoderAbort(
                    "unknown special-float selector", pos - 1)
        raise _NuitkaDecoderAbort("truncated special-float constant", pos)

    # --- Complex ---
    elif ch == 'j':  # complex (two 8-byte doubles)
        if pos + 16 <= len(data):
            real = struct.unpack('<d', data[pos:pos + 8])[0]
            imag = struct.unpack('<d', data[pos + 8:pos + 16])[0]
            return complex(real, imag), pos + 16
        raise _NuitkaDecoderAbort("truncated complex constant", pos)

    elif ch == 'J':  # complex via float sub-constants (for special values)
        parts, pos = _unpack_constant_sequence(
            data, pos, 2, _decoder_state=state, _depth=_depth + 1)
        try:
            return complex(parts[0], parts[1]), pos
        except (TypeError, ValueError):
            raise _NuitkaDecoderAbort("invalid complex components", pos)

    # --- Containers ---
    elif ch == 'T':  # tuple
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        return tuple(items), pos

    elif ch == 'L':  # list
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        return items, pos

    elif ch == 'D':  # dict — Nuitka writes ALL keys first, then ALL values
        count, pos = _read_constant_container_count(data, pos)
        # Validate both key and value arrays before allocating either one.
        _validate_constant_sequence(data, pos, count, state, multiplier=2)
        keys, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        values, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        d = {}
        for k, v in zip(keys, values):
            try:
                if k in d:
                    raise _NuitkaDecoderAbort(
                        "duplicate dictionary key in constants stream", pos)
                d[k] = v
            except TypeError as exc:
                raise _NuitkaDecoderAbort(
                    f"unhashable dictionary key: {exc}", pos)
        return d, pos

    elif ch == 'S':  # set
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        try:
            result = set(items)
        except TypeError as exc:
            raise _NuitkaDecoderAbort(
                f"unhashable set member: {exc}", pos)
        if len(result) != count:
            raise _NuitkaDecoderAbort(
                "duplicate set member in constants stream", pos)
        return result, pos

    elif ch == 'P':  # frozenset
        count, pos = _read_constant_container_count(data, pos)
        items, pos = _unpack_constant_sequence(
            data, pos, count, _decoder_state=state, _depth=_depth + 1)
        try:
            result = frozenset(items)
        except TypeError as exc:
            raise _NuitkaDecoderAbort(
                f"unhashable frozenset member: {exc}", pos)
        if len(result) != count:
            raise _NuitkaDecoderAbort(
                "duplicate frozenset member in constants stream", pos)
        return result, pos

    # --- Raw blob (bytecode pointer) ---
    elif ch == 'X':
        size, pos = _read_profile_payload_length(data, pos, raw_blob=True)
        if size > len(data) - pos:
            raise _NuitkaDecoderAbort("truncated raw-blob payload", pos)
        blob = data[pos:pos + size]
        return blob, pos + size

    # --- Special types ---
    elif ch == 'M':  # anon builtin / type-table value
        if pos >= len(data):
            raise _NuitkaDecoderAbort("truncated anonymous-builtin index", pos)
        py_hex = _target_python_hex()
        names = [
            'NoneType', 'ellipsis', 'NotImplementedType', 'function',
            'generator', 'builtin_function_or_method', 'code', 'module',
        ]
        if py_hex < 0x300:
            names.extend(('file', 'classobj', 'instance', 'instancemethod'))
        if py_hex >= 0x270:
            names.append('version_info')
        if py_hex >= 0x390:
            names.append('GenericAlias')
        if py_hex >= 0x3A0:
            names.append('Union' if py_hex >= 0x3E0 else 'UnionType')
        index = data[pos]
        if index >= len(names):
            raise _NuitkaDecoderAbort(
                f"invalid anonymous-builtin index {index} for target Python",
                pos)
        return ('_nuitka_builtin_anon_type', names[index]), pos + 1

    elif ch == 'Q':  # special singleton/table value
        if pos >= len(data):
            raise _NuitkaDecoderAbort("truncated special-value index", pos)
        special_values = {
            0: Ellipsis,
            1: NotImplemented,
            2: ('_nuitka_special', 'Py_SysVersionInfo'),
        }
        index = data[pos]
        if index not in special_values:
            raise _NuitkaDecoderAbort(
                f"invalid special-value index {index}", pos)
        return special_values[index], pos + 1

    elif ch in ('O', 'E'):  # builtin/exception name (null-terminated)
        end = data.find(b'\x00', pos)
        if end == -1:
            raise _NuitkaDecoderAbort(
                "unterminated builtin/exception name", pos)
        try:
            value = data[pos:end].decode('utf-8', errors='strict')
        except UnicodeDecodeError as exc:
            raise _NuitkaDecoderAbort(
                f"invalid UTF-8 builtin/exception name: {exc}", pos)
        marker_type = _NuitkaBuiltinName if ch == 'O' else _NuitkaExceptionName
        return marker_type(value), end + 1

    elif ch == ':':  # slice(start, stop, step)
        items, pos = _unpack_constant_sequence(
            data, pos, 3, _decoder_state=state, _depth=_depth + 1)
        return ('slice', items[0], items[1], items[2]), pos

    elif ch == ';':  # range/xrange(start, stop, step)
        if (_CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31"
                and _target_python_hex() < 0x300):
            if pos + 12 > len(data):
                raise _NuitkaDecoderAbort(
                    "truncated old-profile xrange payload", pos)
            items = struct.unpack_from('<iii', data, pos)
            pos += 12
        else:
            items, pos = _unpack_constant_sequence(
                data, pos, 3, _decoder_state=state, _depth=_depth + 1)
        return ('range', items[0], items[1], items[2]), pos

    elif (ch == 'G'
          and _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31"):
        if _target_python_hex() < 0x390:
            raise _NuitkaDecoderAbort(
                "old-profile GenericAlias tag requires Python 3.9+", pos - 1)
        parts, pos = _unpack_constant_sequence(
            data, pos, 2, _decoder_state=state, _depth=_depth + 1)
        return ('GenericAlias', parts[0], parts[1]), pos

    elif ch == 'A':  # GenericAlias (Python 3.9+) — 2 sub-constants
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "GenericAlias-A tag is absent from old profiles", pos - 1)
        if _target_python_hex() < 0x390:
            raise _NuitkaDecoderAbort(
                "GenericAlias tag requires Python 3.9+", pos - 1)
        parts, pos = _unpack_constant_sequence(
            data, pos, 2, _decoder_state=state, _depth=_depth + 1)
        return ('GenericAlias', parts[0], parts[1]), pos

    elif ch == 'H':  # UnionType (Python 3.10+) — 1 sub-constant
        if _target_python_hex() < 0x3A0:
            raise _NuitkaDecoderAbort(
                "UnionType tag requires Python 3.10+", pos - 1)
        parts, pos = _unpack_constant_sequence(
            data, pos, 1, _decoder_state=state, _depth=_depth + 1)
        return ('UnionType', parts[0]), pos

    elif ch == 'C':  # CodeObject metadata
        if _CURRENT_NUITKA_BLOB_PROFILE != "modern_vlq31":
            raise _NuitkaDecoderAbort(
                "code-object tag is absent from old profiles", pos - 1)
        co_info, pos = _parse_code_object_tag(
            data, pos, _decoder_state=state, _depth=_depth)
        return co_info, pos

    elif ch == '.':  # end-of-stream marker
        return _Nuitka_END_OF_STREAM, pos

    else:
        raise _NuitkaDecoderAbort(
            f"unknown constant tag 0x{marker:02x}", pos - 1)


def _parse_code_object_tag(data, pos, python_version=None, *, _decoder_state=None,
                           _depth=0):
    """Parse the 'C' tag (CodeObject skeleton) and return a dict with the info.

    Synchronized with DataComposer.py _writeConstantValueCodeObject() and
    HelpersConstantsBlob.c _unpackBlobConstant() case 'C'.

    Flag bit layout (dynamic, version-dependent):
      [qualname] [free_vars] [kw_only] [pos_only] [gen_kind:2bits]
      [CO_OPTIMIZED] [CO_NEWLOCALS] [CO_VARARGS] [CO_VARKEYWORDS]
      [future_spec bits...]
    """
    global _last_unpacked
    parent_previous = _last_unpacked
    _last_unpacked = _NO_NUITKA_PREVIOUS
    try:
        py_hex = _target_python_hex(python_version)
        flags, pos = _read_blob_integer(data, pos)
        flag_base = 1

        # Name is mandatory
        func_name, pos = unpack_single_constant(
            data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
        if not isinstance(func_name, str):
            raise _NuitkaDecoderAbort(
                "code-object name is not a string", pos)

        # Line number is mandatory (encoded as line-1)
        line_number, pos = _read_blob_integer(data, pos)
        line_number += 1

        # Arg names (tuple) is mandatory
        arg_names, pos = unpack_single_constant(
            data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
        if not isinstance(arg_names, tuple):
            raise _NuitkaDecoderAbort(
                "code-object varnames are not a tuple", pos)

        # Arg count is mandatory
        arg_count, pos = _read_blob_integer(data, pos)
        if arg_count > len(arg_names):
            raise _NuitkaDecoderAbort(
                "code-object argument count exceeds varnames", pos)

        # qualname (Python 3.11+, optional flag — o qualunque Python con
        # la variante _CURRENT_CO_QUALNAME_ALL_PY attiva)
        qualname = func_name
        if py_hex >= 0x3B0 or _CURRENT_CO_QUALNAME_ALL_PY:
            if flags & flag_base:
                qualname_parent, pos = unpack_single_constant(
                    data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
                if not isinstance(qualname_parent, str):
                    raise _NuitkaDecoderAbort(
                        "invalid code-object qualname prefix", pos)
                qualname = qualname_parent + "." + func_name
            flag_base <<= 1

        # free_vars (optional)
        free_vars = ()
        if flags & flag_base:
            free_vars, pos = unpack_single_constant(
                data, pos, _decoder_state=_decoder_state, _depth=_depth + 1)
            if not isinstance(free_vars, tuple):
                raise _NuitkaDecoderAbort(
                    "code-object freevars are not a tuple", pos)
        flag_base <<= 1

        # kw_only_count (Python 3.0+, optional)
        kw_only = 0
        if py_hex >= 0x300:
            if flags & flag_base:
                kw_only, pos = _read_blob_integer(data, pos)
                kw_only += 1
            flag_base <<= 1

        # pos_only_count (Python 3.8+, optional)
        pos_only = 0
        if py_hex >= 0x380:
            if flags & flag_base:
                pos_only, pos = _read_blob_integer(data, pos)
                pos_only += 1
            flag_base <<= 1
        if pos_only > arg_count or arg_count + kw_only > len(arg_names):
            raise _NuitkaDecoderAbort(
                "code-object parameter counts exceed varnames", pos)

        # Generator kind: 2 bits
        co_flags = 0
        gen_bits = (flags >> (flag_base.bit_length() - 1)) & 3
        if py_hex >= 0x360 and gen_bits == 3:
            co_flags |= 0x200    # CO_ASYNC_GENERATOR
        elif py_hex >= 0x350 and gen_bits == 2:
            co_flags |= 0x80     # CO_COROUTINE
        elif gen_bits == 1:
            co_flags |= 0x20     # CO_GENERATOR
        elif gen_bits:
            raise _NuitkaDecoderAbort(
                "generator-kind bits are invalid for target Python", pos)
        flag_base <<= 2

        # CO_OPTIMIZED
        if flags & flag_base:
            co_flags |= 0x01
        flag_base <<= 1

        # CO_NEWLOCALS
        if flags & flag_base:
            co_flags |= 0x02
        flag_base <<= 1

        # CO_VARARGS
        if flags & flag_base:
            co_flags |= 0x04
        flag_base <<= 1

        # CO_VARKEYWORDS
        if flags & flag_base:
            co_flags |= 0x08
        flag_base <<= 1

        # Remaining bits are future_spec flags — we consume them
        # to keep position correct but don't need them for extraction.
        # CO_FUTURE_DIVISION (Py2), CO_FUTURE_UNICODE_LITERALS,
        # CO_FUTURE_PRINT_FUNCTION (Py2), CO_FUTURE_ABSOLUTE_IMPORT (Py2),
        # CO_FUTURE_GENERATOR_STOP (3.5-3.6), CO_FUTURE_ANNOTATIONS (3.7+),
        # CO_FUTURE_BARRY_AS_BDFL (3.0+)
        # These are bit flags but no additional data is read.

        # FutureSpec.encode() stores a compact, version-dependent bitset above
        # the basic flags. Translate it back to CPython CO_FUTURE_* values.
        future_encoded = flags // flag_base
        future_bit = 1
        if py_hex < 0x300:
            if future_encoded & future_bit:
                co_flags |= 0x20000   # CO_FUTURE_DIVISION
            future_bit <<= 1
        if future_encoded & future_bit:
            co_flags |= 0x200000      # CO_FUTURE_UNICODE_LITERALS
        future_bit <<= 1
        if py_hex < 0x300:
            if future_encoded & future_bit:
                co_flags |= 0x100000  # CO_FUTURE_PRINT_FUNCTION
            future_bit <<= 1
            if future_encoded & future_bit:
                co_flags |= 0x40000   # CO_FUTURE_ABSOLUTE_IMPORT
            future_bit <<= 1
        if 0x350 <= py_hex < 0x370:
            if future_encoded & future_bit:
                co_flags |= 0x800000  # CO_FUTURE_GENERATOR_STOP
            future_bit <<= 1
        if py_hex >= 0x370:
            if future_encoded & future_bit:
                co_flags |= 0x1000000  # CO_FUTURE_ANNOTATIONS
            future_bit <<= 1
        if py_hex >= 0x300 and future_encoded & future_bit:
            co_flags |= 0x400000       # CO_FUTURE_BARRY_AS_BDFL
        if py_hex >= 0x300:
            future_bit <<= 1
        # V100: le Nuitka recenti aggiungono nuovi bit FutureSpec (nessun
        # dato extra viene letto per i future flag).  I bit sconosciuti si
        # consumano senza abortire: prima l'abort uccideva l'intero chunk
        # del modulo alla prima costante code-object (1 sola costante
        # decodificata per modulo su interi build).
        # future_encoded >= future_bit → bit future extra, ignorati.

        return {
            '_type': 'CodeObject',
            'name': func_name,
            'qualname': qualname,
            'line': line_number,
            'args': list(arg_names),
            'argcount': arg_count,
            'kwonly': kw_only,
            'posonly': pos_only,
            'freevars': list(free_vars),
            'flags': co_flags,
        }, pos
    except _NuitkaDecoderAbort:
        raise
    except Exception as exc:
        raise _NuitkaDecoderAbort(
            f"invalid code-object metadata: {type(exc).__name__}: {exc}", pos)
    finally:
        _last_unpacked = parent_previous


# =============================================================================
# BLOB PARSER - Named Chunks
# =============================================================================


def _is_plausible_blob_module_name(name: str) -> bool:
    """Validate Nuitka DataComposer chunk names without product assumptions."""
    if name == "":
        return True
    if name in (".bytecode", ".files", ".bytecode_data"):
        return True
    if len(name) > 4096:
        return False
    if any(ord(c) < 32 or ord(c) == 127 for c in name):
        return False
    # Generated preload/postload names and plugin chunks can contain dashes,
    # plus signs, paths, or a leading dot. Reject binary noise, not valid names.
    return all(c.isalnum() or c in "._-+/\\:" for c in name)


def _blob_module_name_score(name: str) -> int:
    """Rank candidate plain/mapping2 chunk-name decodings."""
    if not _is_plausible_blob_module_name(name):
        return -10_000
    if name in (".bytecode", ".files", ".bytecode_data"):
        return 10_000
    if name == "":
        return 9_000

    score = 100
    if len(name) <= 512:
        score += 20
    parts = name.lstrip('.').split('.')
    if parts and all(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*'
                                  r'(?:-(?:preLoad|postLoad))?', p or '')
                     for p in parts):
        score += 300
    if '.' in name:
        score += 80
    if name.startswith('__') and name.endswith('__'):
        score += 40
    if any(ord(c) > 127 for c in name):
        score -= 80
    return score


def _decode_blob_module_name(raw_name: bytes,
                             commercial_bypass=None) -> str:
    """Decode a DataComposer name under an explicit layout contract."""
    if commercial_bypass is not None:
        # The protected marker is authoritative. Encoded one-byte names can
        # themselves be identifiers (encoded ``e`` is raw ``i``), therefore
        # ranking the raw and mapping2 spellings cannot disambiguate them.
        decoded = commercial_bypass.decode_module_name(raw_name)
        if not _is_plausible_blob_module_name(decoded):
            raise ValueError("invalid mapping2 module name")
        return decoded

    try:
        plain = raw_name.decode('utf-8', errors='strict')
    except UnicodeDecodeError as exc:
        raise ValueError(f"invalid UTF-8 plaintext module name: {exc}")
    if not _is_plausible_blob_module_name(plain):
        raise ValueError("invalid plaintext module name")
    return plain


def parse_blob_modules(blob_data: bytes,
                       commercial_bypass=None,
                       *,
                       strict: bool = False,
                       diagnostics: dict = None):
    """Parse a framed Nuitka DataComposer blob into ``(name, data)`` chunks.

    ``strict`` rejects CRC/size/name inconsistencies.  In normal best-effort
    mode parsing stops at the first invalid trailing record but records the
    reason in ``diagnostics`` when a dictionary is supplied.
    """
    diag = diagnostics if diagnostics is not None else {}
    diag.clear()
    diag.update({
        'ok': False, 'crc_ok': False, 'declared_size': 0,
        'available_size': max(0, len(blob_data or b'') - 8),
        'parsed_chunks': 0, 'consumed_payload': 0,
        'trailing_bytes': 0, 'stop_reason': None,
    })

    if not blob_data or len(blob_data) < 8:
        diag['stop_reason'] = 'blob_too_small'
        return []

    crc_stored, size_stored = struct.unpack_from('<II', blob_data, 0)
    diag['declared_size'] = size_stored
    ndx_log(f"CRC32: 0x{crc_stored:08X}, Declared size: {size_stored:,} bytes")

    available = len(blob_data) - 8
    if size_stored > available:
        diag['stop_reason'] = 'declared_size_exceeds_available'
        ndx_log_warn(
            f"Blob is truncated: declared {size_stored:,} payload bytes, "
            f"only {available:,} available")
        if strict:
            return []
        data_end = len(blob_data)
    else:
        data_end = 8 + size_stored
        if strict and size_stored != available:
            diag['stop_reason'] = 'declared_size_does_not_match_blob'
            diag['trailing_bytes'] = available - size_stored
            return []

    actual_crc = zlib.crc32(blob_data[8:data_end]) & 0xFFFFFFFF
    diag['crc_ok'] = (size_stored <= available and actual_crc == crc_stored)
    if diag['crc_ok']:
        ndx_log_ok("CRC32 verified OK!")
    else:
        if crc_stored == 0 and _NDX_BLOB_HEADERLESS:
            ndx_log(
                "Headerless chunk-table variant: CRC frame absent in this "
                "build — table accepted on structural evidence")
        else:
            ndx_log_warn(
                f"CRC32 mismatch: expected 0x{crc_stored:08X}, "
                f"computed 0x{actual_crc:08X}")
        if strict:
            diag['stop_reason'] = 'crc_mismatch'
            return []

    data = memoryview(blob_data)[8:data_end]
    selected_name_decoder = commercial_bypass
    diag['name_encoding'] = 'plain'

    # DataHidingPlugin may encode loader lookup strings without encoding the
    # names stored inside the DataComposer blob (Commercial 4.0.6 Panel does
    # exactly that). Select one name mode for the entire table; never mix
    # per-name guesses, which is ambiguous for one-byte identifiers.
    if commercial_bypass is not None:
        raw_names = []
        probe = 0
        probe_ok = True
        while probe < len(data):
            name_rel = bytes(data[probe:min(probe + 4097, len(data))]).find(
                b'\x00')
            if name_rel < 0:
                probe_ok = False
                break
            name_end = probe + name_rel
            size_pos = name_end + 1
            if size_pos + 4 > len(data):
                probe_ok = False
                break
            chunk_size = struct.unpack_from('<I', data, size_pos)[0]
            chunk_end = size_pos + 4 + chunk_size
            if chunk_end > len(data):
                probe_ok = False
                break
            raw_names.append(bytes(data[probe:name_end]))
            probe = chunk_end
        probe_ok = probe_ok and probe == len(data) and bool(raw_names)

        def _decode_name_table(decoder):
            if not probe_ok:
                return None
            decoded_names = []
            try:
                for raw_name in raw_names:
                    value = (decoder.decode_module_name(raw_name)
                             if decoder is not None else
                             raw_name.decode('utf-8', errors='strict'))
                    if not _is_plausible_blob_module_name(value):
                        return None
                    decoded_names.append(value)
            except Exception:
                return None
            if len(set(decoded_names)) != len(decoded_names):
                return None
            score = sum(_blob_module_name_score(x) for x in decoded_names)
            score += 100000 * sum(
                x in ('', '.bytecode', '.files', '.bytecode_data')
                for x in decoded_names)
            return decoded_names, score

        plain_table = _decode_name_table(None)
        mapped_table = _decode_name_table(commercial_bypass)
        if plain_table is not None and mapped_table is None:
            selected_name_decoder = None
        elif mapped_table is not None and plain_table is None:
            selected_name_decoder = commercial_bypass
            diag['name_encoding'] = 'mapping2'
        elif plain_table is not None and mapped_table is not None:
            if plain_table[0] == mapped_table[0]:
                selected_name_decoder = None
            else:
                diag['stop_reason'] = 'ambiguous_chunk_name_encoding'
                if strict:
                    return []
                selected_name_decoder = None
                diag['name_encoding'] = 'ambiguous_plain_fallback'
        else:
            diag['stop_reason'] = 'invalid_chunk_name_encoding'
            if strict:
                return []

    offset = 0
    modules = []
    seen_names = set()

    while offset < len(data):
        # Exact carvers should leave no padding, but tolerate all-zero alignment
        # in externally supplied blobs without inventing empty chunks.
        remaining = data[offset:]
        if remaining and not any(remaining):
            diag['stop_reason'] = 'zero_padding'
            break
        if len(data) - offset < 5:
            diag['stop_reason'] = 'truncated_chunk_header'
            break

        raw_view = data[offset:min(offset + 4097, len(data))]
        name_rel = bytes(raw_view).find(b'\x00')
        if name_rel < 0:
            diag['stop_reason'] = 'unterminated_chunk_name'
            break
        name_end = offset + name_rel
        raw_name = bytes(data[offset:name_end])
        try:
            module_name = _decode_blob_module_name(
                raw_name, selected_name_decoder)
        except Exception:
            diag['stop_reason'] = 'invalid_chunk_name_encoding'
            break
        if not _is_plausible_blob_module_name(module_name):
            diag['stop_reason'] = 'invalid_chunk_name'
            break
        if module_name in seen_names:
            diag['stop_reason'] = 'duplicate_chunk_name'
            break
        seen_names.add(module_name)

        size_pos = name_end + 1
        if size_pos + 4 > len(data):
            diag['stop_reason'] = 'truncated_chunk_size'
            break
        chunk_size = struct.unpack_from('<I', data, size_pos)[0]
        chunk_pos = size_pos + 4
        chunk_end = chunk_pos + chunk_size
        if chunk_size > 100 * 1024 * 1024:
            diag['stop_reason'] = 'chunk_too_large'
            break
        if chunk_end > len(data):
            diag['stop_reason'] = 'truncated_chunk_data'
            break

        modules.append((module_name, bytes(data[chunk_pos:chunk_end])))
        offset = chunk_end

    diag['parsed_chunks'] = len(modules)
    diag['consumed_payload'] = offset
    diag['trailing_bytes'] = max(0, len(data) - offset)
    fully_consumed = (offset == len(data))
    diag['ok'] = bool(modules) and (
        (diag['crc_ok'] and fully_consumed) if strict else True)
    if diag['stop_reason'] is None:
        diag['stop_reason'] = 'eof'
    if strict and not diag['ok']:
        return []
    return modules


# =============================================================================
# SHARED BLOB DECRYPTION (extracted from --list-modules logic)
# =============================================================================

def _decrypt_blob_if_encrypted(target_path: str, blob_data: bytes,
                               pe_data: bytes = None) -> bytes:
    """
    Decrypt the Nuitka constants blob if it's encrypted (Commercial/Protected).
    Returns a CRC-verified normalized blob.  A protected blob that cannot be
    verified returns ``None``; encrypted bytes are never sent to plaintext
    parsers.  ``last_state`` records ``plaintext``, ``decrypted`` or
    ``decrypt_failed`` for reporting.
    """
    import pefile
    # V95 Fix 10 (universal): this duplicate def carried `bypass = None`,
    # an AttributeError on every call.  It was only dormant because the
    # legacy CLI exits mid-module before this half loads; imports, NDX
    # (--ndx/--dev-only) runs or driver relocation would crash on every
    # blob.  Match the authoritative first definition.
    bypass = CommercialBypass()

    _decrypt_blob_if_encrypted.last_state = 'missing'
    _decrypt_blob_if_encrypted.last_error = None
    if not blob_data:
        return blob_data

    if not bypass.is_blob_encrypted(blob_data):
        _diag = {}
        _valid_plaintext = False
        # Data-hiding can leave framing/CRC plaintext while module names still
        # use mapping2.  Try the ordinary grammar first, then name decoding;
        # both paths retain the same strict size/CRC/full-consumption checks.
        for _name_decoder in (None, bypass):
            _try_diag = {}
            if parse_blob_modules(
                    blob_data, _name_decoder, strict=True,
                    diagnostics=_try_diag):
                _diag = _try_diag
                _valid_plaintext = True
                break
            _diag = _try_diag
        if not _valid_plaintext:
            _decrypt_blob_if_encrypted.last_state = 'invalid_plaintext'
            _decrypt_blob_if_encrypted.last_error = _diag.get('stop_reason')
            return None
        _decrypt_blob_if_encrypted.last_state = 'plaintext'
        return blob_data

    log_fire("Blob is encrypted — attempting commercial metadata normalization...")

    # read PE data
    try:
        if pe_data is None:
            with open(target_path, 'rb') as f:
                pe_data = f.read()
    except Exception as e:
        log_err(f"Cannot read PE data: {e}")
        _decrypt_blob_if_encrypted.last_state = 'decrypt_failed'
        _decrypt_blob_if_encrypted.last_error = 'target_read_failed'
        return None

    try:
        pe = pefile.PE(data=pe_data)
    except Exception as e:
        log_err(f"PE parse error: {e}")
        _decrypt_blob_if_encrypted.last_state = 'decrypt_failed'
        _decrypt_blob_if_encrypted.last_error = 'target_pe_parse_failed'
        return None

    # 1) Fast path: search .rdata only for _mapping[], then derive d0-d7 from blob
    ndx_log("  Scanning .rdata for mapping table...")
    mapping_candidates = bypass._find_all_mapping_candidates(pe, rdata_only=True)
    if not mapping_candidates:
        ndx_log("  No candidates in .rdata, scanning all sections...")
        mapping_candidates = bypass._find_all_mapping_candidates(pe)

    decrypted_blob = None
    if mapping_candidates:
        ndx_log(f"  {len(mapping_candidates)} mapping candidate(s) — deriving d0-d7 from blob...")
        for idx, mapping in enumerate(mapping_candidates):
            d_vals = bypass._derive_d_from_blob(blob_data, mapping)
            if d_vals:
                try:
                    result = bypass._decrypt_raw(
                        blob_data, mapping, d_vals)
                except (ValueError, TypeError, IndexError, struct.error):
                    continue
                if bypass._check_crc(result):
                    ndx_log_ok(f"  Decrypted and verified with mapping#{idx}")
                    decrypted_blob = result
                    break

    if decrypted_blob is None:
        # 2) Slow fallback: full PE scan + brute-force
        ndx_log_warn("  Fast derivation failed — running full key scan (may be slow)...")
        mapping_candidates2, d_candidates = bypass.extract_key_material_from_pe(pe_data)
        if mapping_candidates2 is not None:
            if d_candidates is None:
                d_candidates = []
            decrypted_blob, _, _ = bypass.decrypt_blob_auto(
                blob_data, mapping_candidates2, d_candidates
            )

    _diag = {}
    _verified_chunks = []
    if decrypted_blob is not None:
        for _name_decoder in (None,):
            _try_diag = {}
            _verified_chunks = parse_blob_modules(
                decrypted_blob, _name_decoder, strict=True,
                diagnostics=_try_diag)
            _diag = _try_diag
            if _verified_chunks and _try_diag.get('ok'):
                break
    if _verified_chunks:
        ndx_log_ok("Blob decrypted successfully")
        _decrypt_blob_if_encrypted.last_state = 'decrypted'
        return decrypted_blob
    else:
        ndx_log_warn("Decryption failed CRC/structure validation; protected bytes rejected")
        _decrypt_blob_if_encrypted.last_state = 'decrypt_failed'
        _decrypt_blob_if_encrypted.last_error = (
            _diag.get('stop_reason') or 'no_crc_verified_candidate')
        return None


# =============================================================================
# NUITKA C-SOURCE REBUILDER  v7 — reconstruct Nuitka-style .c from metadata
# =============================================================================



def _decode_constants_stream_orig(stream_data: bytes, count: int, *, python_version=None,
                             start_pos: int = 0, int_mode: str = "vlq",
                             profile: str = None,
                             return_diagnostics: bool = False,
                             node_budget=None, max_depth: int = 128) -> tuple:
    """Decode *count* constants from a raw constants stream.

    This is the stateful core used by both normal chunks and aggressive scans.
    The `'p'` previous-value marker is stream-local in Nuitka, so resetting it
    here avoids cross-module contamination and keeps `None` constants intact.
    """
    global _last_unpacked, _CURRENT_NUITKA_BLOB_INT_MODE
    global _CURRENT_NUITKA_BLOB_PROFILE
    _last_unpacked = _NO_NUITKA_PREVIOUS
    old_target = _CURRENT_NUITKA_TARGET_PYTHON
    old_int_mode = _CURRENT_NUITKA_BLOB_INT_MODE
    old_profile = _CURRENT_NUITKA_BLOB_PROFILE
    if profile is None:
        profile = ("hybrid_1_9_to_2_3"
                   if int_mode == "fixed32" else "modern_vlq31")
    if profile not in _NDL_CONSTANTS_PROFILES:
        raise ValueError(f"unknown Nuitka constants profile: {profile}")
    _CURRENT_NUITKA_BLOB_PROFILE = profile
    _CURRENT_NUITKA_BLOB_INT_MODE = (
        "vlq" if profile == "modern_vlq31" else "fixed32")
    set_nuitka_target_python(python_version or old_target)

    pos = start_pos
    constants = []
    state = _new_nuitka_decode_budget(
        stream_data, start_pos, node_budget=node_budget, max_depth=max_depth)
    diagnostics = {
        'aborted': False,
        'reason': None,
        'abort_pos': None,
        'requested_count': count,
        'decoded_count': 0,
        'node_budget': state.initial_nodes,
        'nodes_used': 0,
        'max_depth': state.max_depth,
        'max_seen_depth': 0,
        'int_mode': _CURRENT_NUITKA_BLOB_INT_MODE,
        'profile': profile,
    }

    try:
        count = _validate_constant_sequence(stream_data, pos, count, state)
        for _ in range(count):
            if pos >= len(stream_data):
                break
            val, new_pos = unpack_single_constant(
                stream_data, pos, _decoder_state=state, _depth=0)
            if new_pos <= pos:
                diagnostics['reason'] = 'decoder made no forward progress'
                break
            pos = new_pos
            if val is _Nuitka_END_OF_STREAM:
                diagnostics['reason'] = 'end of stream'
                break
            if val is _Nuitka_PARSE_ERROR:
                diagnostics['reason'] = 'unrecognized or truncated constant tag'
                break
            constants.append(val)
    except _NuitkaDecoderAbort as exc:
        diagnostics['aborted'] = True
        diagnostics['reason'] = exc.reason
        diagnostics['abort_pos'] = exc.pos
        pos = max(pos, min(exc.pos, len(stream_data)))
        constants.append({
            '_type': 'unknown',
            'offset': exc.pos,
            'byte': (stream_data[exc.pos] if 0 <= exc.pos < len(stream_data)
                     else None),
            'context_hex': stream_data[
                max(0, exc.pos - 8):min(len(stream_data), exc.pos + 9)].hex(),
            'reason': exc.reason,
        })
    except Exception as exc:
        # Aggressive candidate scans operate on arbitrary bytes. A malformed
        # candidate must be rejected, not escape and terminate the whole scan.
        diagnostics['aborted'] = True
        diagnostics['reason'] = f"{type(exc).__name__}: {exc}"
        diagnostics['abort_pos'] = pos
        constants.append({
            '_type': 'unknown', 'offset': pos,
            'byte': (stream_data[pos] if 0 <= pos < len(stream_data) else None),
            'context_hex': stream_data[
                max(0, pos - 8):min(len(stream_data), pos + 9)].hex(),
            'reason': diagnostics['reason'],
        })
    finally:
        diagnostics['decoded_count'] = sum(
            not (isinstance(item, dict) and item.get('_type') == 'unknown')
            for item in constants)
        diagnostics['diagnostic_nodes'] = (
            len(constants) - diagnostics['decoded_count'])
        diagnostics['nodes_used'] = state.initial_nodes - state.nodes_remaining
        diagnostics['max_seen_depth'] = state.max_seen_depth
        _last_unpacked = _NO_NUITKA_PREVIOUS
        _CURRENT_NUITKA_BLOB_INT_MODE = old_int_mode
        _CURRENT_NUITKA_BLOB_PROFILE = old_profile
        set_nuitka_target_python(old_target)

    if return_diagnostics:
        return constants, pos, diagnostics
    return constants, pos


def _ndl_constant_values_equivalent(left, right, _depth=0):
    """Compare profile outputs, treating equal NaNs as structurally equal."""
    if _depth > 140 or type(left) is not type(right):
        return False
    if isinstance(left, float):
        return left == right or (left != left and right != right)
    if isinstance(left, complex):
        return (_ndl_constant_values_equivalent(left.real, right.real,
                                                _depth + 1)
                and _ndl_constant_values_equivalent(left.imag, right.imag,
                                                    _depth + 1))
    if isinstance(left, (list, tuple)):
        return (len(left) == len(right)
                and all(_ndl_constant_values_equivalent(a, b, _depth + 1)
                        for a, b in zip(left, right)))
    if isinstance(left, dict):
        if len(left) != len(right):
            return False
        return all(
            _ndl_constant_values_equivalent(ka, kb, _depth + 1)
            and _ndl_constant_values_equivalent(va, vb, _depth + 1)
            for (ka, va), (kb, vb) in zip(left.items(), right.items()))
    if isinstance(left, (set, frozenset)):
        return repr(left) == repr(right)
    try:
        return left == right
    except Exception:
        return repr(left) == repr(right)


def _ndl_unknown_constants_result(reason, *, count=0, offset=0,
                                  candidate_diagnostics=(), data=None):
    raw = bytes(data) if isinstance(
        data, (bytes, bytearray, memoryview)) else b''
    offset = max(0, int(offset))
    unknown = {
        '_type': 'unknown', 'offset': offset,
        'byte': (raw[offset] if offset < len(raw) else None),
        'context_hex': raw[
            max(0, offset - 8):min(len(raw), offset + 9)].hex(),
        'reason': str(reason),
    }
    diagnostics = {
        'aborted': True, 'exact': False, 'reason': str(reason),
        'abort_pos': offset, 'requested_count': int(count),
        'decoded_count': 0, 'profile': None,
    }
    return _NuitkaConstantsList(
        [unknown], declared_count=count, end_pos=offset,
        diagnostics=diagnostics,
        candidate_diagnostics=list(candidate_diagnostics))


def parse_module_constants(chunk_data: bytes, python_version=None,
                           profile: str = None) -> list:
    """Decode one DataComposer part under an exact source-backed profile.

    A successful part is precisely ``<H count> + count values + b'.'``.  No
    trailing bytes, early terminator, partial candidate, or heuristic score is
    accepted.  Unknown/malformed input is preserved as a diagnostic node.
    """
    if not isinstance(chunk_data, (bytes, bytearray, memoryview)):
        return _ndl_unknown_constants_result(
            "module constants chunk is not bytes-like")
    chunk_data = bytes(chunk_data)
    if len(chunk_data) < 3:
        return _ndl_unknown_constants_result(
            "module constants chunk is shorter than <H> plus terminator",
            offset=len(chunk_data), data=chunk_data)
    count = struct.unpack_from('<H', chunk_data, 0)[0]

    selected = profile or _NDL_SELECTED_CONSTANTS_PROFILE
    if selected is not None and selected not in _NDL_CONSTANTS_PROFILES:
        return _ndl_unknown_constants_result(
            f"unknown constants profile {selected!r}", count=count,
            offset=2, data=chunk_data)
    profiles = (selected,) if selected else _NDL_CONSTANTS_PROFILES
    exact = []
    candidate_diagnostics = []

    for candidate_profile in profiles:
        vals, pos, diagnostics = _decode_constants_stream(
            chunk_data, count, python_version=python_version,
            start_pos=2, profile=candidate_profile,
            return_diagnostics=True)
        dot_at_eof = (pos == len(chunk_data) - 1
                      and chunk_data[pos:pos + 1] == b'.')
        is_exact = (not diagnostics.get('aborted')
                    and len(vals) == count and dot_at_eof)
        diagnostics.update({
            'exact': is_exact,
            'end_pos': pos,
            'terminator_at_eof': dot_at_eof,
            'trailing_bytes': max(0, len(chunk_data) - (pos + 1)),
        })
        candidate_diagnostics.append(diagnostics)
        if is_exact:
            exact.append((candidate_profile, vals, pos, diagnostics))

    if not exact:
        furthest = max(
            candidate_diagnostics,
            key=lambda d: int(d.get('end_pos') or d.get('abort_pos') or 0),
            default={})
        reason = furthest.get('reason') or (
            "no constants profile consumed the declared values and final dot "
            "exactly")
        return _ndl_unknown_constants_result(
            reason, count=count,
            offset=int(furthest.get('end_pos') or
                       furthest.get('abort_pos') or 2),
            candidate_diagnostics=candidate_diagnostics,
            data=chunk_data)

    first_profile, first_vals, first_pos, first_diag = exact[0]
    if any(not _ndl_constant_values_equivalent(first_vals, other_vals)
           for _profile, other_vals, _pos, _diag in exact[1:]):
        return _ndl_unknown_constants_result(
            "ambiguous constants profiles produced different exact values",
            count=count, offset=first_pos,
            candidate_diagnostics=candidate_diagnostics,
            data=chunk_data)

    chosen = next(
        (item for item in exact
         if item[0] == (_NDL_SELECTED_CONSTANTS_PROFILE or
                        "modern_vlq31")),
        exact[0])
    chosen_profile, vals, pos, diagnostics = chosen
    diagnostics = dict(diagnostics)
    diagnostics['exact'] = True
    if len(exact) > 1:
        diagnostics['profile_ambiguous_equivalent'] = [
            item[0] for item in exact]
    return _NuitkaConstantsList(
        vals, declared_count=count,
        int_mode=diagnostics.get('int_mode'), profile=chosen_profile,
        end_pos=pos, diagnostics=diagnostics,
        candidate_diagnostics=candidate_diagnostics)


def _ndl_select_constants_profile(module_chunks, python_version=None):
    """Select one profile using exact evidence from every module chunk."""
    global _NDL_SELECTED_CONSTANTS_PROFILE
    _NDL_SELECTED_CONSTANTS_PROFILE = None
    survivors = list(_NDL_CONSTANTS_PROFILES)
    divergent_pairs = set()
    checked = 0
    evidence_chunks = 0
    decoded = 0
    malformed_chunks = []

    for name, chunk in module_chunks or ():
        checked += 1
        outputs = {}
        next_survivors = []
        for candidate in survivors:
            result = parse_module_constants(
                chunk, python_version=python_version, profile=candidate)
            if result.diagnostics.get('exact'):
                next_survivors.append(candidate)
                outputs[candidate] = result
        if not next_survivors:
            # Distinguish a damaged chunk from a mixed-profile blob. A chunk
            # valid only under an already-eliminated profile is positive
            # evidence that no one global DataComposer grammar can explain it.
            for candidate in _NDL_CONSTANTS_PROFILES:
                if candidate in survivors:
                    continue
                result = parse_module_constants(
                    chunk, python_version=python_version, profile=candidate)
                if result.diagnostics.get('exact'):
                    outputs[candidate] = result
            if outputs:
                _NDL_SELECTED_CONSTANTS_PROFILE = 'unresolved'
                return None, {
                    'ok': False,
                    'reason': 'no_single_profile_for_all_chunks',
                    'valid_profiles_for_conflicting_chunk': sorted(outputs),
                    'conflicting_chunk': name,
                    'checked_chunks': checked,
                    'evidence_chunks': evidence_chunks,
                    'decoded_constants': decoded,
                    'malformed_chunks': malformed_chunks,
                }
            # Invalid under all profiles: retain the framed module as an
            # unknown diagnostic and use other intact chunks as evidence.
            malformed_chunks.append(name)
            continue
        survivors = next_survivors
        evidence_chunks += 1
        decoded += len(next(iter(outputs.values()))) if outputs else 0
        for index, left_profile in enumerate(survivors):
            for right_profile in survivors[index + 1:]:
                if not _ndl_constant_values_equivalent(
                        outputs[left_profile], outputs[right_profile]):
                    divergent_pairs.add(tuple(sorted(
                        (left_profile, right_profile))))

    if not checked or not evidence_chunks:
        _NDL_SELECTED_CONSTANTS_PROFILE = 'unresolved'
        return None, {
            'ok': False, 'reason': ('no_module_constant_chunks' if not checked
                                    else 'no_valid_profile_witness'),
            'checked_chunks': checked, 'evidence_chunks': evidence_chunks,
            'decoded_constants': decoded,
            'malformed_chunks': malformed_chunks,
        }
    live_pairs = [pair for pair in divergent_pairs
                  if pair[0] in survivors and pair[1] in survivors]
    if len(survivors) > 1 and live_pairs:
        _NDL_SELECTED_CONSTANTS_PROFILE = 'unresolved'
        return None, {
            'ok': False, 'reason': 'ambiguous_constant_profile',
            'survivors': survivors, 'divergent_pairs': live_pairs,
            'checked_chunks': checked, 'evidence_chunks': evidence_chunks,
            'decoded_constants': decoded,
            'malformed_chunks': malformed_chunks,
        }
    if not survivors:
        # Fallback: prova tutti i profili in ordine di probabilità
        for fallback in ("modern_vlq31", "hybrid_1_9_to_2_3",
                         "legacy_through_1_8_6"):
            if module_chunks:
                test_result = parse_module_constants(
                    module_chunks[0][1],
                    python_version=python_version,
                    profile=fallback)
                if test_result.diagnostics.get('exact'):
                    chosen = fallback
                    break
        else:
            chosen = "modern_vlq31"
    else:
        chosen = ("modern_vlq31" if "modern_vlq31" in survivors else survivors[0])
    _NDL_SELECTED_CONSTANTS_PROFILE = chosen
    return chosen, {
        'ok': True, 'profile': chosen, 'survivors': survivors,
        'profile_ambiguous_equivalent': (
            survivors if len(survivors) > 1 else []),
        'checked_chunks': checked, 'evidence_chunks': evidence_chunks,
        'decoded_constants': decoded,
        'malformed_chunks': malformed_chunks,
    }


# =============================================================================
# STRING EXTRACTION (recursive)
# =============================================================================

def extract_all_strings(constants: list, *, max_depth: int = 25) -> list:
    """Extract ALL strings from a list of constants (recursive).

    Visits: str, tuple/list, dict (keys+values), set/frozenset, CodeObject dicts.
    Deduplicates while preserving order.
    """
    seen = set()
    out = []

    def add(s: str):
        if not s:
            return
        if s in seen:
            return
        seen.add(s)
        out.append(s)

    def walk(v, depth: int):
        if depth > max_depth:
            return

        if isinstance(v, str):
            add(v)
            return

        # Nuitka constants can contain bytes/bytearray; optionally harvest readable text.
        if isinstance(v, (bytes, bytearray)):
            b = bytes(v)
            if not b:
                return
            # Heuristic: try UTF-8, and only keep if looks mostly printable.
            try:
                s = b.decode("utf-8")
            except Exception:
                return
            printable = sum(1 for ch in s if ch.isprintable() or ch in "\r\n\t")
            if printable / max(len(s), 1) >= 0.85:
                add(s)
            return

        # Structural decoder markers are metadata, not strings from the target.
        if isinstance(v, tuple) and v and isinstance(v[0], str):
            if v[0].startswith('_nuitka_'):
                return
            if v[0] in ("slice", "range", "GenericAlias", "UnionType"):
                for item in v[1:]:
                    walk(item, depth + 1)
                return

        if isinstance(v, (tuple, list)):
            for item in v:
                walk(item, depth + 1)
            return

        if isinstance(v, dict):
            if v.get('_type') == 'unknown':
                return
            for k, val in v.items():
                walk(k, depth + 1)
                walk(val, depth + 1)
            return

        if isinstance(v, (set, frozenset)):
            for item in v:
                walk(item, depth + 1)
            return

    for c in constants:
        walk(c, 0)
    return out



# ==========================================================================
# === NDX MODULE: ndx_modtable.py
# ==========================================================================


import struct
import re
from capstone import Cs, CS_ARCH_X86, CS_MODE_64


FLAG_NAMES = {
    0x01: 'UNCOMPILING',
    0x02: 'UNINFORMED',
    0x04: 'IS_PACKAGE',
    0x08: 'IS_TOPLEVEL_PACKAGE',
    0x10: 'COMPILED',
}


# Nuitka importa i moduli "hard" (typing, sys, os, …) tramite helper dedicati
# IMPORT_HARD_* che NON ricevono il nome modulo come stringa: il modulo è
# codificato nel nome dell'helper stesso. Senza questa mappa il lifter
# produceva un nodo import anonimo e ``from typing import Any`` veniva
# degradato a ``import Any``.
_NDL_HARD_IMPORT_MODULE_NAMES = {
    'IMPORT_HARD_SYS': 'sys',
    'IMPORT_HARD_OS': 'os',
    'IMPORT_HARD_TYPING': 'typing',
    'IMPORT_HARD_TYPES': 'types',
    'IMPORT_HARD_IO': 'io',
    'IMPORT_HARD__IO': '_io',
    'IMPORT_HARD_GENERICPATH': 'genericpath',
    'IMPORT_HARD_NTPATH': 'ntpath',
    'IMPORT_HARD_POSIXPATH': 'posixpath',
    'IMPORT_HARD_FUNCTOOLS': 'functools',
    'IMPORT_HARD_BUILTINS': 'builtins',
    'IMPORT_HARD_PKGUTIL': 'pkgutil',
    'IMPORT_HARD_SITE': 'site',
    'IMPORT_HARD_SYSCONFIG': 'sysconfig',
    'IMPORT_HARD_UNITTEST': 'unittest',
    'IMPORT_HARD_UNITTEST__MOCK': 'unittest.mock',
    'IMPORT_HARD_CTYPES': 'ctypes',
    'IMPORT_HARD_CTYPES__MACHOLIB': 'ctypes.macholib',
    'IMPORT_HARD_CTYPES__UTIL': 'ctypes.util',
    'IMPORT_HARD_CTYPES___AIX': 'ctypes._aix',
    'IMPORT_HARD_CTYPES___ENDIAN': 'ctypes._endian',
    'IMPORT_HARD_IMPORTLIB': 'importlib',
    'IMPORT_HARD_IMPORTLIB_METADATA': 'importlib.metadata',
    'IMPORT_HARD_IMPORTLIB_RESOURCES': 'importlib.resources',
    'IMPORT_HARD_IMPORTLIB__METADATA': 'importlib_metadata',
    'IMPORT_HARD_IMPORTLIB__RESOURCES': 'importlib_resources',
    'IMPORT_HARD___FUTURE__': '__future__',
    'IMPORT_HARD__FROZEN_IMPORTLIB': '_frozen_importlib',
    'IMPORT_HARD__FROZEN_IMPORTLIB_EXTERNAL': '_frozen_importlib_external',
    'IMPORT_HARD_PKG_RESOURCES': 'pkg_resources',
    'IMPORT_HARD_TENSORFLOW': 'tensorflow',
}


def _ndl_hard_import_module_name(helper_name):
    """Nome modulo Python di un helper IMPORT_HARD_* (None se non risolvibile)."""
    if not isinstance(helper_name, str):
        return None
    mapped = _NDL_HARD_IMPORT_MODULE_NAMES.get(helper_name)
    if mapped is not None:
        return mapped
    if not helper_name.startswith('IMPORT_HARD_'):
        return None
    tail = helper_name[len('IMPORT_HARD_'):].lower()
    if tail.startswith('_'):
        tail = tail[1:]
    candidate = tail.replace('__', '.')
    if (candidate and not candidate.startswith('.')
            and not candidate.endswith('.') and '..' not in candidate
            and re.fullmatch(r'[A-Za-z_][\w.]*', candidate)):
        return candidate
    if tail and re.fullmatch(r'[A-Za-z_]\w*', tail):
        return tail
    return None


def _ndx_hard_import_initializers(img):
    """VA funzione → nome modulo degli initializer IMPORT_HARD_*.

    Un initializer e' una piccola funzione che chiama direttamente
    ``PyImport_ImportModule`` con una stringa costante
    (``lea reg, [rip+str]; call [rip+iat]``): la stringa È il nome modulo.
    Identificazione puramente statica (import table + stringa leggibile),
    indipendente dal signature database, quindi funziona anche quando
    l'opc-hash dell'helper non matcha la build. La scansione procede per
    confini di funzione (.pdata / eh_frame): lo sweep lineare dell'intera
    .text desincronizza e perde gli initializer oltre il primo desync."""
    cached = getattr(img, '_ndx_hard_import_map', None)
    if cached is not None:
        return cached
    mapping = {}
    img._ndx_hard_import_map = mapping
    try:
        import capstone as _cs_hard
        md = _cs_hard.Cs(_cs_hard.CS_ARCH_X86, _cs_hard.CS_MODE_64)
    except Exception:
        return mapping
    import_vas = {va for va, nm in
                  (getattr(img, 'imports', {}) or {}).items()
                  if nm == 'PyImport_ImportModule'}
    for va, nm in (getattr(img, 'plt_map', {}) or {}).items():
        if nm == 'PyImport_ImportModule':
            import_vas.add(va)
    if not import_vas:
        return mapping

    # Intervalli di funzione: PE da .pdata, ELF da eh_frame.
    spans = []
    if getattr(img, 'fmt', None) == 'pe':
        spans = [(b, e) for b, e in
                 (getattr(img, '_pe_function_ranges', None) or ())]
    if not spans:
        try:
            starts = img.elf_function_starts()
        except Exception:
            starts = []
        spans = [(s, starts[i + 1] if i + 1 < len(starts) else s + 0x20000)
                 for i, s in enumerate(starts)]

    def _read_cstr(va):
        off = img.va_to_off(va)
        if off is None:
            return None
        raw = img.data[off:off + 256]
        end = raw.find(b'\x00')
        if end < 1 or end > 200:
            return None
        try:
            return raw[:end].decode('ascii')
        except UnicodeDecodeError:
            return None

    for fstart, fend in spans:
        try:
            off = img.va_to_off(fstart)
        except Exception:
            off = None
        if off is None:
            continue
        body = img.data[off:off + max(0, fend - fstart)]
        window = deque(maxlen=12)
        for insn in md.disasm(body, fstart):
            window.append(insn)
            if insn.mnemonic != 'call':
                continue
            if 'rip' in insn.op_str:
                tgt = rip_target(insn)
            else:
                try:
                    tgt = int(insn.op_str, 16)
                except ValueError:
                    tgt = None
            if tgt is None or tgt not in import_vas:
                continue
            # Nome modulo: la lea di stringa più recente prima della call.
            for prev in reversed(window):
                if prev.mnemonic != 'lea' or 'rip' not in prev.op_str:
                    continue
                text = _read_cstr(rip_target(prev))
                if not text:
                    continue
                if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*'
                                r'(?:\.[A-Za-z_][A-Za-z0-9_]*)*', text):
                    mapping.setdefault(fstart, text)
                    break
    return mapping


class NdxModuleEntry:
    __slots__ = ('name', 'func_ptr', 'bytecode_index', 'bytecode_size',
                 'flags', 'flag_names')

    def __init__(self, name, func_ptr, bc_idx, bc_size, flags):
        self.name = name
        self.func_ptr = func_ptr
        self.bytecode_index = bc_idx
        self.bytecode_size = bc_size
        self.flags = flags
        self.flag_names = [n for b, n in FLAG_NAMES.items() if flags & b] or ['COMPILED']

    def __repr__(self):
        return f"<Module {self.name!r} fp={self.func_ptr:#x} flags={self.flag_names}>"


# ---------------------------------------------------------------------------
# Module table discovery
# ---------------------------------------------------------------------------

_MODNAME_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$')


def _candidate_module_strings(img, allowed_names=None):
    """Stringhe C candidate a nomi modulo in sezioni dati read-only.

    Commercial data-hiding builds store the loader entry names ENCODED
    with the fixed-seed mapping2 table (the runtime decodes them via
    decode_public).  When an explicit chunk-name allowlist is available,
    the encoded form of every allowed name is therefore searched as well;
    matches are recorded under the DECODED name so downstream chunk
    matching still works.
    """
    allowed = set(allowed_names) if allowed_names is not None else None
    out = {}
    bypass = CommercialBypass()
    for s in img.sections:
        if s.name not in ('.rodata', '.rdata', '.data.rel.ro', '.data'):
            continue
        body = img.data[s.offset:s.offset + s.size]
        for m in re.finditer(rb'[\x20-\x7e]{1,120}\x00', body):
            try:
                txt = m.group()[:-1].decode('ascii')
            except Exception:
                continue
            if (len(txt) >= 2 and
                    ((allowed is not None and txt in allowed) or
                     (allowed is None and _MODNAME_RE.match(txt)))):
                out[s.addr + m.start()] = txt
        if allowed:
            # mapping2-encoded loader entry names (commercial builds):
            # the stored bytes are encode(name); the terminator NUL is
            # preserved by the mapping (0 -> 0).
            for nm in list(allowed):
                if not isinstance(nm, str):
                    continue
                enc = bytes(bypass.mapping2_forward[b]
                            for b in nm.encode('utf-8'))
                if len(enc) < 2:
                    continue
                needle = enc + b'\x00'
                start = 0
                while True:
                    j = body.find(needle, start)
                    if j < 0:
                        break
                    out[s.addr + j] = nm
                    start = j + 1
    return out


def _valid_entry_at(img, cands, va, chunk_names=None):
    """Decodifica una Nuitka_MetaPathBasedLoaderEntry a *va*; None se invalida."""
    name_ptr = img.read_u64(va)
    if name_ptr is None or name_ptr not in cands:
        return None
    func_ptr = img.read_u64(va + 8)
    bc_idx = img.read_u32(va + 16)
    bc_size = img.read_u32(va + 20)
    flags = img.read_u32(va + 24)
    if func_ptr is None or bc_idx is None:
        return None
    if not (img.is_exec(func_ptr) or func_ptr == 0):
        return None
    if bc_idx > 100000 or bc_size > 100_000_000:
        return None
    if flags > 0xFF:
        return None
    name = cands[name_ptr]
    # Filtro forte: un modulo incluso ha SEMPRE un chunk blob col suo nome
    # (le costanti del modulo). Nessuna vtable CPython può soddisfarlo.
    if chunk_names is not None and name not in chunk_names:
        return None
    return NdxModuleEntry(name, func_ptr, bc_idx, bc_size, flags)


def find_module_table_elf(img, chunk_names=None):
    """ELF: Nuitka_MetaPathBasedLoaderEntry via puntatori (reloc RELATIVE o
    valori assolute) verso stringhe nome-modulo. L'array è CONTIGUO: cerchiamo
    sequenze di >=1 entry valide con entry adiacenti valide o terminatore."""
    cands = _candidate_module_strings(img)
    if not cands:
        return []
    probe_vas = set()
    for off, addend in img.rel_relative.items():
        if addend in cands:
            probe_vas.add(off)
    # aggiungi puntatori raw in .data
    for s in img.sections:
        if s.name not in ('.data', '.data.rel.ro'):
            continue
        body = img.data[s.offset:s.offset + s.size]
        for i in range(0, max(0, len(body) - 8), 8):
            if struct.unpack_from('<Q', body, i)[0] in cands:
                probe_vas.add(s.addr + i)
    # ordina e cerca run contigui di entry valide (stride della struct)
    runs = []
    cur = []          # lista di (va, entry)
    for va in sorted(probe_vas):
        e = _valid_entry_at(img, cands, va, chunk_names)
        if e is None:
            continue
        if cur and va - cur[-1][0] in (24, 28, 32):
            cur.append((va, e))
        elif not cur:
            cur = [(va, e)]
        else:
            runs.append(cur)
            cur = [(va, e)]
    if cur:
        runs.append(cur)
    if not runs:
        return []
    # il module table reale è il run più lungo
    best = max(runs, key=len)
    return [e for _va, e in best]


def find_module_table_pe(img, chunk_names=None):
    """PE module entries whose names are backed by validated blob chunks.

    On MSVC binaries many unrelated method-name tables have the same initial
    pointer/integer shape.  Requiring the pointed-to name to occur in the
    CRC-validated DataComposer chunk inventory is the format-level
    discriminator; it is independent of project or library names.
    """
    cands = _candidate_module_strings(img, allowed_names=chunk_names)
    entries = []
    seen_names = set()
    for s in img.sections:
        if s.name not in ('.data', '.rdata', '.data.rel.ro'):
            continue
        body = img.data[s.offset:s.offset + s.size]
        for i in range(0, max(0, len(body) - 28), 8):
            entry = _valid_entry_at(
                img, cands, s.addr + i, chunk_names=chunk_names)
            if entry is None:
                continue
            name = entry.name
            if name in seen_names:
                continue
            seen_names.add(name)
            entries.append(entry)
    return entries


def find_module_table(img, chunk_names=None):
    if img.fmt == 'elf':
        return find_module_table_elf(img, chunk_names)
    if img.fmt == 'pe':
        return find_module_table_pe(img, chunk_names)
    return []


# ---------------------------------------------------------------------------
# Blob + costanti
# ---------------------------------------------------------------------------

def _ndx_validate_crc_blob(blob, *, offset=0, max_blob_size=None):
    """Validate and trim one Nuitka ``CRC32 + size + payload`` frame."""
    offset = int(offset)
    if not blob or offset < 0 or offset + 8 > len(blob):
        return None
    if max_blob_size is None:
        try:
            max_blob_size = int(os.environ.get(
                'NDX_MAX_BLOB_BYTES', str(512 * 1024 * 1024)))
        except Exception:
            max_blob_size = 512 * 1024 * 1024
    max_blob_size = max(1024, int(max_blob_size))
    crc, size = struct.unpack_from('<II', blob, offset)
    frame_end = offset + 8 + size
    if size <= 0 or size > max_blob_size or frame_end > len(blob):
        return None
    payload = memoryview(blob)[offset + 8:frame_end]
    if (zlib.crc32(payload) & 0xffffffff) != crc:
        return None
    frame = bytes(memoryview(blob)[offset:frame_end])
    return frame, size


def _ndx_find_pe_resource_blob(img):
    """Find the largest CRC-valid Nuitka frame in PE ``RT_RCDATA``.

    Resource identifiers and languages are intentionally not hard-coded.  A
    candidate is accepted only when its declared size is contained in the
    resource and its CRC32 verifies, which prevents arbitrary RCDATA from
    being mistaken for a constants blob.
    """
    pe = getattr(img, '_pe', None)
    if pe is None or not hasattr(pe, 'DIRECTORY_ENTRY_RESOURCE'):
        return None
    try:
        mapped = pe.get_memory_mapped_image()
    except Exception:
        return None

    best = None
    try:
        for resource_type in pe.DIRECTORY_ENTRY_RESOURCE.entries:
            if resource_type.id != 10:  # Windows RT_RCDATA
                continue
            for resource_name in resource_type.directory.entries:
                for resource_lang in resource_name.directory.entries:
                    rva = int(resource_lang.data.struct.OffsetToData)
                    size = int(resource_lang.data.struct.Size)
                    if size < 8 or rva < 0 or rva + size > len(mapped):
                        continue
                    validated = _ndx_validate_crc_blob(
                        bytes(mapped[rva:rva + size]))
                    if validated is None:
                        continue
                    frame, declared_size = validated
                    candidate = (img.base + rva, frame, declared_size)
                    if best is None or declared_size > best[2]:
                        best = candidate
    except Exception:
        return None
    return best


def _ndx_count_plain_chunk_prefix(candidate):
    """Count a plaintext DataComposer record prefix without copying chunks."""
    pos = 0
    count = 0
    seen = set()
    total = len(candidate)
    while pos + 5 <= total:
        name_end = candidate.find(b'\x00', pos, min(pos + 4097, total))
        if name_end < 0:
            break
        raw_name = candidate[pos:name_end]
        try:
            name = raw_name.decode('utf-8', errors='strict')
        except UnicodeDecodeError:
            break
        if not _is_plausible_blob_module_name(name) or name in seen:
            break
        seen.add(name)
        size_pos = name_end + 1
        if size_pos + 4 > total:
            break
        chunk_size = struct.unpack_from('<I', candidate, size_pos)[0]
        chunk_end = size_pos + 4 + chunk_size
        if chunk_size > 100 * 1024 * 1024 or chunk_end > total:
            break
        pos = chunk_end
        count += 1
    return count, pos


def find_blob(img):
    """Trova un constants blob CRC-valido in risorse o sezioni dati."""
    global _NDX_BLOB_HEADERLESS
    d = img.data

    # Modern Windows Nuitka/MSVC stores the constants stream as RT_RCDATA.
    # Resolve resources before raw section scanning; resource bytes need not
    # be represented as an ordinary .rdata frame in the file image.
    if img.fmt == 'pe':
        resource_blob = _ndx_find_pe_resource_blob(img)
        if resource_blob is not None:
            return resource_blob

    # ELF and older/static PE layouts may embed the complete framed stream in
    # a normal data section. Scan for compatibility, but retain the existing
    # bounded window and accept only a fully CRC-verified frame.
    #
    # Every candidate pays two O(1) structural gates BEFORE any CRC work:
    #   1. the declared frame size must be 4-aligned and fully contained;
    #   2. the payload must open with a real chunk-table header — a
    #      plausible module name, NUL-terminated within a short window,
    #      followed by a sane u32 chunk size (the DataComposer frame
    #      grammar: ``name \0 size data`` repeated).
    # Random data reaches step 2 with negligible probability, so the
    # expensive full-payload CRC32 runs only on genuine frames instead of
    # on every plausible-looking length field of the section.
    best = None
    # Some builds place the composer stream inside unusual sections
    # (observed: .text).  The structural gates below keep a full-image
    # scan affordable, so no section is excluded by name.
    for s in img.sections:
        body = d[s.offset:s.offset + s.size]
        limit = max(0, len(body) - 8)
        i = 0
        while i < limit:
            i += 4          # u32-aligned frame candidates only
            crc, size = struct.unpack_from('<II', body, i)
            frame_end = i + 8 + size
            if size <= 8 or size & 3 or frame_end > len(body) or \
                    size > 512 * 1024 * 1024:
                continue
            payload = memoryview(body)[i + 8:frame_end]
            # gate 2: chunk-table header must parse
            head = bytes(payload[:min(len(payload), 300)])
            nul = head.find(b'\x00')
            if nul <= 0 or nul > 250:
                continue
            if not _is_plausible_blob_module_name(
                    head[:nul].decode('utf-8', errors='replace')):
                continue
            if nul + 5 > len(head):
                continue
            chunk_size = struct.unpack_from('<I', head, nul + 1)[0]
            if chunk_size == 0 or chunk_size > 100 * 1024 * 1024 or \
                    chunk_size > len(payload) - nul - 5:
                continue
            validated = _ndx_validate_crc_blob(body, offset=i)
            if validated is not None:
                frame, size = validated
                va = s.addr + i
                # preferisci il frame PIÙ GRANDE (blob reale vs chunk)
                if best is None or size > best[2]:
                    best = (va, frame, size)

    # Some builds (commercial/offuscated variants) store the DataComposer
    # chunk table WITHOUT the CRC32 frame.  The table itself is strong
    # structural evidence: a run of ``name \0 u32-size data`` records with
    # plausible module names, every size contained, consuming to a clean
    # end.  Locate the longest such run and present it downstream behind a
    # synthetic (crc=0) header so the rest of the pipeline is unchanged;
    # the returned VA is shifted back by the 8 header bytes so absolute
    # constant addressing still points at the real table bytes.
    if best is None:
        # Real tables conventionally open with the canonical .bytecode
        # pseudo-chunk.  Try that exact anchor first.  It avoids starting a
        # full record walk at every four-byte position inside a 10+ MB table
        # (quadratic behaviour on large commercial dumps).
        marker_best = None
        marker = b'.bytecode\x00'
        for s in img.sections:
            body = d[s.offset:s.offset + s.size]
            offset = body.find(marker)
            while offset >= 0:
                candidate = body[offset:]
                count, consumed = _ndx_count_plain_chunk_prefix(candidate)
                score = (count, consumed)
                if count >= 3 and (marker_best is None or
                                   score > marker_best[0]):
                    marker_best = (score, s.addr + offset,
                                   candidate[:consumed])
                offset = body.find(marker, offset + 1)
        if marker_best is not None:
            (_count, consumed), table_start, table_bytes = marker_best
            _NDX_BLOB_HEADERLESS = True
            blob = struct.pack('<II', 0, consumed) + table_bytes
            return table_start - 8, blob, consumed

        table_va = None
        _table_bytes = None
        _table_skip = 0
        table_candidates = {}
        for s in img.sections:
            body = d[s.offset:s.offset + s.size]
            limit = max(0, len(body) - 8)
            i = 0
            while i < limit:
                i += 4
                # skip zero alignment padding before the first chunk name
                while i < limit and body[i] == 0:
                    i += 1
                head = bytes(body[i:i + 300])
                nul = head.find(b'\x00')
                if nul < 0 or nul > 250:
                    continue
                if nul and not _is_plausible_blob_module_name(
                        head[:nul].decode('utf-8', errors='replace')):
                    continue
                if nul + 5 > len(head):
                    continue
                first_size = struct.unpack_from('<I', head, nul + 1)[0]
                if first_size == 0 or first_size > 100 * 1024 * 1024 or \
                        nul + 5 + first_size > len(body) - i:
                    continue
                # walk the chunk run from this header
                pos = i
                chunks = 0
                span = 0
                saw_marker = False
                while pos + 5 < len(body):
                    # A single 0x00 at a record boundary is the EMPTY chunk
                    # name ('' = the global constants chunk), not padding:
                    # validate the u32 that follows and consume the record.
                    if body[pos] == 0:
                        csize0 = struct.unpack_from('<I', body, pos + 1)[0] \
                            if pos + 5 <= len(body) else 0
                        if 0 < csize0 <= 100 * 1024 * 1024 and \
                                pos + 5 + csize0 <= len(body):
                            saw_marker = True      # '' is canonical
                            pos = pos + 5 + csize0
                            chunks += 1
                            span = pos - i
                            continue
                        while pos < len(body) and body[pos] == 0:
                            pos += 1
                        if pos + 5 >= len(body):
                            break
                    seg = bytes(body[pos:pos + 300])
                    nul2 = seg.find(b'\x00')
                    if nul2 <= 0 or nul2 > 250:
                        break
                    walk_name = seg[:nul2].decode('utf-8',
                                                  errors='replace')
                    if walk_name == '.bytecode':
                        saw_marker = True
                    if walk_name and not _is_plausible_blob_module_name(
                            walk_name):
                        break
                    if pos + nul2 + 5 > len(body):
                        break
                    csize = struct.unpack_from('<I', body, pos + nul2 + 1)[0]
                    if csize > 100 * 1024 * 1024 or \
                            pos + nul2 + 5 + csize > len(body):
                        break
                    pos = pos + nul2 + 5 + csize
                    chunks += 1
                    span = pos - i
                    # Some builds append a small inner header to a chunk's
                    # payload, shifting the next record boundary by a few
                    # bytes.  When the naive boundary fails, look ahead a
                    # short window for the next plausible record header
                    # instead of abandoning the whole run.
                    if pos + 6 < len(body):
                        seg2 = bytes(body[pos:pos + 300])
                        n3 = seg2.find(b'\x00')
                        bad = (n3 < 0 or n3 > 250 or
                               (n3 and not _is_plausible_blob_module_name(
                                   seg2[:n3].decode('utf-8',
                                                    errors='replace'))))
                        if bad:
                            for delta in range(1, 64):
                                p2 = pos + delta
                                if p2 + 6 > len(body):
                                    break
                                s3 = bytes(body[p2:p2 + 300])
                                m3 = s3.find(b'\x00')
                                if m3 < 0 or m3 > 250:
                                    continue
                                nm3 = s3[:m3].decode('utf-8',
                                                     errors='replace')
                                if m3 and not _is_plausible_blob_module_name(
                                        nm3):
                                    continue
                                cs3 = struct.unpack_from('<I', s3, m3 + 1)[0]
                                if cs3 == 0 or cs3 > 100 * 1024 * 1024 or \
                                        p2 + m3 + 5 + cs3 > len(body):
                                    continue
                                pos = p2
                                break
                # The canonical pseudo-chunks ('.bytecode', '.files', ...)
                # open every real constants table: a candidate whose run
                # contains one is the genuine table start; misaligned
                # walks never produce them.
                if chunks >= 2 and saw_marker:
                    _cand_va = s.addr + i
                    if _cand_va not in table_candidates or \
                            span > table_candidates[_cand_va][1]:
                        table_candidates[_cand_va] = (span, chunks)
        # Pick the candidate whose table parses into the MOST chunks:
        # near-miss starts (a few bytes off) yield far fewer records than
        # the genuine table start.  Count records without manufacturing a
        # CRC frame and calling parse_blob_modules for every candidate.  On a
        # large headerless image that old approach repeatedly CRC-hashed and
        # copied the entire remaining section, turning blob discovery into a
        # multi-minute operation.
        if table_candidates:
            best_count = -1
            best_skip = 0
            best_consumed = 0
            for cand_va, (_span, _walk_chunks) in sorted(
                    table_candidates.items()):
                _sec = next((s2 for s2 in img.sections
                             if s2.addr <= cand_va < s2.addr + s2.size), None)
                if _sec is None:
                    continue
                _rel = cand_va - _sec.addr
                _tb = d[_sec.offset:_sec.offset + _sec.size][
                    _rel:_rel + _span]
                _starts = [(_tb, 0)]
                _head = bytes(_tb[:300])
                _hn = _head.find(b'\x00')
                if 0 < _hn <= 250 and _hn + 5 <= len(_tb):
                    _starts.append((_tb[_hn + 5:], _hn + 5))
                for _cand, _skip in _starts:
                    _count, _consumed = _ndx_count_plain_chunk_prefix(_cand)
                    if (_count, _consumed) > (best_count, best_consumed):
                        best_count = _count
                        table_va = cand_va
                        _table_bytes = _cand
                        best_skip = _skip
                        best_consumed = _consumed
            if best_count >= 3:
                _table_skip = best_skip
                _table_bytes = _table_bytes[:best_consumed]
            else:
                table_va = None
                _table_bytes = None
                _table_skip = 0
        if table_va is not None and _table_bytes is not None:
            # the verified variant already carries the exact table
            # bytes; keep the VA pointing at the true table start so
            # absolute constant addressing stays correct
            blob = struct.pack('<II', 0, len(_table_bytes)) + _table_bytes
            _NDX_BLOB_HEADERLESS = True
            return (table_va + _table_skip - 8, blob,
                    len(_table_bytes))

    # Candidate C: a standalone '.bytecode' chunk carve.  Some builds ship
    # the marshalled module stream without any surrounding chunk table.
    # The chunk header is exact structural evidence: the canonical marker
    # name, a NUL, and a u32 payload size fully contained in the section.
    # Presenting it as a single-chunk blob feeds the bytecode channel,
    # which reconstructs modules from their original marshalled code
    # objects.
    for s in img.sections:
        body = d[s.offset:s.offset + s.size]
        limit = max(0, len(body) - 16)
        i = 0
        while i < limit:
            i += 1
            if body[i] != 0x2E:          # fast path: '.'
                continue
            nul = body.find(b'\x00', i, i + 32)
            if nul < 0 or body[i:nul] != b'.bytecode':
                continue
            if nul + 5 > len(body):
                continue
            payload_size = struct.unpack_from('<I', body, nul + 1)[0]
            payload_start = nul + 5
            if payload_size == 0 or payload_size > 512 * 1024 * 1024 or                     payload_start + payload_size > len(body):
                continue
            chunk = bytes(body[i:payload_start + payload_size])
            _NDX_BLOB_HEADERLESS = True
            blob = struct.pack('<II', 0, len(chunk)) + chunk
            return (s.addr + i - 8, blob, len(chunk))
    return best  # (va, bytes, declared_size)


class NdxModuleInfo:
    """Tutto ciò che sappiamo di un modulo compilato nativo."""

    def __init__(self, entry, consts, global_consts, blob_chunks):
        self.entry = entry
        self.name = entry.name if entry else '?'
        self.func_ptr = entry.func_ptr if entry else None
        self.consts = consts                    # costanti private del modulo
        self.global_consts = global_consts      # costanti globali condivise
        self.code_objects = []                  # [{name, qualname, argcount, ...}]
        self.varnames = []
        self.mod_consts_base = None             # VA array mod_consts (se trovato)

    def const_at(self, idx):
        """Slot i dell'array mod_consts: prima globali poi private."""
        if idx < len(self.global_consts):
            return self.global_consts[idx]
        j = idx - len(self.global_consts)
        if j < len(self.consts):
            return self.consts[j]
        return None


def load_modules(img, py_version=None, blob=None):
    """Pipeline: blob → chunks → moduli con costanti."""
    if blob is None:
        blob = find_blob(img)
    if blob is None:
        return [], None
    blob_va, blob_bytes, _ = blob
    chunks = parse_blob_modules(blob_bytes)
    chunk_map = {}
    for name, data in chunks:
        chunk_map.setdefault(name, data)
    # The DataComposer integer grammar belongs to the complete blob, not to
    # an individual module chunk. A chunk containing only small integers may
    # be consumed exactly by multiple historical grammars while yielding
    # different values. Select one profile from all framed constants chunks,
    # allowing unambiguous modules to disambiguate the others. This also
    # resets profile state when more than one target is analysed per process.
    profile_chunks = [
        (name, data) for name, data in chunks
        if name not in {'.bytecode', '.files', 'files'}
    ]
    _ndl_select_constants_profile(
        profile_chunks, python_version=py_version)
    global_data = chunk_map.get('', b'') or chunk_map.get('global', b'')
    global_consts = parse_module_constants(global_data, python_version=py_version) \
        if global_data else []
    meta_chunks = {'', '.bytecode', '.files', 'files'}
    chunk_names = {n for n, _ in chunks if n and n not in meta_chunks}
    entries = find_module_table(img, chunk_names)
    # Se non c'è module table (es. binario minimale), usa i chunk col nome
    if not entries:
        for name, data in chunks:
            if name and name not in meta_chunks:
                entries.append(NdxModuleEntry(name, 0, 0, 0, 0x10))
    modules = []
    for e in entries:
        cdata = chunk_map.get(e.name, b'')
        consts = parse_module_constants(cdata, python_version=py_version) if cdata else []
        modules.append(NdxModuleInfo(e, consts, global_consts, chunks))
    return modules, dict(chunk_map)



# ==========================================================================
# === NDX MODULE: ndx_helperdb.py
# ==========================================================================


import re
import struct
import bisect
from collections import deque
import capstone as _cap_ndl

_NDL_BINOP = {
    "PyNumber_Add": "+", "PyNumber_Subtract": "-", "PyNumber_Multiply": "*",
    "PyNumber_TrueDivide": "/", "PyNumber_FloorDivide": "//",
    "PyNumber_Remainder": "%", "PyNumber_Power": "**",
    "PyNumber_Lshift": "<<", "PyNumber_Rshift": ">>",
    "PyNumber_And": "&", "PyNumber_Or": "|", "PyNumber_Xor": "^",
    "PyNumber_MatrixMultiply": "@",
}


class _NativeHelperClassifier:
    """Name/classify a runtime-helper VA by the CPython APIs it reaches."""
    def __init__(self, pe, data, target_python=None, function_bounds=None):
        # ``pe`` può essere un oggetto pefile.PE (legacy) oppure un
        # ndx_image.BinaryImage (PE/ELF unificato).  L'interfaccia usata qui è
        # la stessa: base, sezioni (RVA, size, file_off), IAT/PLT imports.
        _is_ndx = hasattr(pe, 'fmt') and hasattr(pe, 'plt_map')
        self.pe = pe
        if _is_ndx:
            self.base = getattr(pe, 'base', 0)
            self.data = data if data is not None else pe.data
            self.secs = [(s.addr - self.base, max(s.size, 1), s.offset)
                         for s in pe.sections if s.type != 8]
            self.iat = dict(pe.imports)
            self._plt_map = dict(pe.plt_map)
            _dll_python = None
        else:
            self.base = pe.OPTIONAL_HEADER.ImageBase
            self.data = data
            self.secs = [(s.VirtualAddress, max(s.Misc_VirtualSize, s.SizeOfRawData),
                          s.PointerToRawData) for s in pe.sections]
            self.iat = {}
            self._plt_map = {}
            _dll_python = None
        if not _is_ndx and hasattr(pe, "DIRECTORY_ENTRY_IMPORT"):
            for mod in pe.DIRECTORY_ENTRY_IMPORT:
                try:
                    _dll = mod.dll.decode(errors="replace") if mod.dll else ""
                    _m = re.match(r"python(\d)(\d+)\.dll$", _dll.lower())
                    if _m:
                        _dll_python = (int(_m.group(1)), int(_m.group(2)))
                except Exception:
                    pass
                for imp in mod.imports:
                    if imp.name:
                        self.iat[imp.address] = imp.name.decode(errors="replace")
        elif _is_ndx and target_python:
            _dll_python = tuple(target_python[:2])
        # V74: ABI/profile selection must not depend on the PyUnstable_* spelling.
        # CPython 3.11 kept legacy PyCode_New* export names in some builds, while
        # Nuitka 4.x already used the new frame/helper ABI. Prefer the explicitly
        # detected target version, then the imported python3NN.dll, and only then
        # the historical symbol-name hint. This also fixes standalone
        # --live-decompile, which bypassed _live_decompile_ctx's old promotion.
        try:
            self.target_python = tuple(target_python[:2]) if target_python else _dll_python
        except Exception:
            self.target_python = _dll_python
        _sym_unstable = any(
            n.startswith("PyUnstable_") for n in self.iat.values())
        self._is_unstable = bool(
            (self.target_python and self.target_python >= (3, 11))
            or _sym_unstable)
        self._pycode_is_unstable = self._is_unstable   # alias for op-classifier
        self.md = _cap_ndl.Cs(_cap_ndl.CS_ARCH_X86, _cap_ndl.CS_MODE_64)
        self._apis = {}
        self._cls = {}
        self._fmt_cache = {}
        self._binop_cache = {}
        self._kwcall_cache = {}
        self._subhelper_cache = {}
        self._substore_cache = {}
        self._dict_subhelper_cache = {}
        self._deepcopy_const_cache = {}
        self._object_size_slot_cache = {}
        self._strcat_cache = {}
        self._imphard_cache = {}
        self._getattr3_cache = {}
        self._getattr3_proof = {}
        # Supplied by ``NuitkaStaticDisassembler._function_bounds`` once the
        # module disassembler exists.  That resolver is backed by PE ``.pdata``
        # (including chained unwind fragments), so helper scans stop at the
        # native function's real end instead of reading the next helper.
        self._function_bounds_resolver = None
        if callable(function_bounds):
            self.set_function_bounds(function_bounds)

    def set_function_bounds(self, resolver):
        """Attach the exact ``.pdata`` function-extent resolver.

        The classifier is created in the shared binary context before the
        per-module disassembler.  Binding is therefore deliberately late.  If
        anything was classified before that bind, discard every derived cache:
        results obtained from the old fixed-size windows are not trustworthy.
        """
        if not callable(resolver):
            return False
        old = getattr(self, "_function_bounds_resolver", None)
        if old == resolver:
            return False
        # A bound NuitkaStaticDisassembler method would otherwise keep the
        # entire per-module analysis object (Capstone handle and caches) alive
        # for the lifetime of the shared classifier.  Snapshot only the small
        # immutable pdata index and reproduce its exact lookup semantics.
        owner = getattr(resolver, "__self__", None)
        ranges = getattr(owner, "_pdata_ranges", None)
        starts = getattr(owner, "_pdata_starts", None)
        logical = getattr(owner, "_pdata_logical", None)
        if ranges is not None and starts is not None and logical is not None:
            ranges = tuple((int(a), int(b)) for a, b in ranges)
            starts = tuple(int(x) for x in starts)
            logical = {int(k): (int(v[0]), int(v[1]))
                       for k, v in logical.items()}

            def _pdata_resolver(va, _ranges=ranges, _starts=starts,
                                _logical=logical):
                try:
                    import bisect
                    index = bisect.bisect_right(_starts, int(va)) - 1
                    if index >= 0:
                        begin, end = _ranges[index]
                        if begin <= int(va) < end:
                            return _logical.get(begin, (begin, end))
                except Exception:
                    pass
                return None, None

            resolver = _pdata_resolver
        self._function_bounds_resolver = resolver
        for name in ("_apis", "_cls", "_fmt_cache", "_binop_cache",
                     "_kwcall_cache", "_subhelper_cache", "_substore_cache",
                     "_dict_subhelper_cache", "_deepcopy_const_cache",
                     "_object_size_slot_cache", "_strcat_cache",
                     "_imphard_cache", "_ctbuild_cache",
                     "_lookup_attr_tail_cache", "_method_call_slot_cache",
                     "_function_call_slot_cache", "_getattr3_cache",
                     "_getattr3_proof", "_module_var_accessor_cache",
                     "_full_extent_iat_cache"):
            cache = getattr(self, name, None)
            if hasattr(cache, "clear"):
                cache.clear()
        return True

    def _helper_extent(self, va):
        """Return a validated logical ``(start, end)`` containing *va*."""
        resolver = getattr(self, "_function_bounds_resolver", None)
        if not callable(resolver):
            return None
        try:
            bounds = resolver(int(va))
            if not bounds or len(bounds) != 2:
                return None
            start, end = bounds
            if start is None or end is None:
                return None
            start, end = int(start), int(end)
            if start <= int(va) < end:
                return start, end
        except Exception:
            pass
        return None

    def _bounded_helper_blob(self, va, off, legacy_limit):
        """Slice a helper without crossing its exact native-function end."""
        limit = max(0, int(legacy_limit))
        extent = self._helper_extent(va)
        if extent is not None:
            limit = min(limit, max(0, extent[1] - int(va)))
        return self.data[off:off + limit], extent is not None

    def va_to_off(self, va):
        rva = va - self.base
        for va0, sz, off in self.secs:
            if va0 <= rva < va0 + sz:
                return off + (rva - va0)
        return None

    def _direct(self, va):
        off = self.va_to_off(va)
        if off is None:
            return [], []
        blob, _has_exact_extent = self._bounded_helper_blob(va, off, 0x400)
        # V95 Fix 6 (universal): with an exact .pdata function extent the
        # first-`ret` stop is unnecessary and gcc/MinGW-HARMFUL: MinGW
        # interleaves early-return blocks INSIDE the function, so C-API
        # calls can sit after the first `ret` (MSVC lays them out-of-line
        # at the end, where the old stop already reached them).  Scan the
        # whole bounded blob in that case; keep the legacy stop only when
        # the extent is unknown (blob could cross into the next function).
        _max_scan_insns = 400 if _has_exact_extent else 160
        apis, internals = [], []
        _tail_seen = {va}
        # V95 Fix 4 (universal, pseudo-PLT): MinGW/gcc binds imported C-API
        # functions to registers once (`mov reg, qword ptr [rip+IAT_SLOT]`)
        # and calls them as `call reg`.  Track the latest RIP load per
        # register so register-indirect calls resolve to the IAT symbol too
        # (MSVC's direct `call qword ptr [rip+X]` path is unchanged).
        _plt_reg = {}
        _VOLATILE_REGS = {
            'rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11',
            'eax', 'ecx', 'edx', 'r8d', 'r9d', 'r10d', 'r11d',
        }
        for i, insn in enumerate(self.md.disasm(blob, va)):
            if i >= _max_scan_insns:
                break
            mn, o = insn.mnemonic, insn.op_str
            if mn in ("call", "jmp"):
                if o.startswith("0x"):
                    # ELF PLT stub: call dirette a .plt risolvono l'import
                    try:
                        _t = int(o, 16)
                        if _t in self._plt_map:
                            apis.append(self._plt_map[_t])
                    except ValueError:
                        pass
                if o.startswith("qword ptr [rip"):
                    try:
                        disp = int(o.split("+", 1)[1].split("]", 1)[0].strip(), 16)
                        t = insn.address + insn.size + disp
                        if t in self.iat:
                            apis.append(self.iat[t])
                    except Exception:
                        pass
                elif o.startswith("0x"):
                    try:
                        internals.append(int(o, 16))
                    except Exception:
                        pass
                elif o in _plt_reg:
                    # V95 Fix 4: `call reg` / `jmp reg` with a tracked
                    # pseudo-PLT binding resolves to the imported symbol.
                    _t = _plt_reg[o]
                    if _t in self.iat:
                        apis.append(self.iat[_t])
                if mn == "call":
                    # Volatile registers do not survive a call.
                    for _vr in _VOLATILE_REGS:
                        _plt_reg.pop(_vr, None)
            elif mn == "mov" and "," in o:
                _dst, _src = [x.strip() for x in o.split(",", 1)]
                if _src.startswith("qword ptr [rip"):
                    try:
                        _disp = int(_src.split("+", 1)[1].split("]", 1)[0].strip(), 16)
                        _plt_reg[_dst] = insn.address + insn.size + _disp
                    except Exception:
                        pass
                elif _dst in _plt_reg:
                    _plt_reg.pop(_dst, None)
            elif mn in ("lea", "pop"):
                _dst0 = o.split(",", 1)[0].strip() if o else ""
                if _dst0 in _plt_reg:
                    _plt_reg.pop(_dst0, None)
            elif mn == "xor" and "," in o:
                _xa, _xb = [x.strip() for x in o.split(",", 1)]
                if _xa == _xb and _xa in _plt_reg:
                    _plt_reg.pop(_xa, None)
            # Terminal edges: RET, or an unconditional tail-jump to an
            # immediate (followed one level below).  ``jmp reg/mem`` is an
            # internal virtual dispatch (tp_* slots), NOT a terminator: gcc
            # lowers C switch/dispatch that way inside one function body.
            if mn == "ret":
                # V95 Fix 6 (universal): keep scanning past early `ret`s
                # when the exact function extent is proven — gcc/MinGW
                # interleaves early-return blocks, so later C-API calls
                # still belong to THIS function.  Without the extent the
                # blob could cross into the next function: stop as before.
                if not _has_exact_extent:
                    break
                continue
            if mn == "jmp":
                if o.startswith("0x"):
                    try:
                        _tail = int(o, 16)
                    except ValueError:
                        break
                    if _tail == va or _tail in _tail_seen:
                        break
                    _tail_seen.add(_tail)
                    if self.va_to_off(_tail) is not None:
                        # follow the tail-jump target once
                        _to = self.va_to_off(_tail)
                        blob = self.data[_to:_to + 0x400]
                        va = _tail
                        continue
                    break
                # jmp reg/mem: internal dispatch — keep scanning linearly
        return apis, internals

    def collect_apis(self, va):
        if va in self._apis:
            return self._apis[va]
        found, seen, work = {}, set(), [(va, 0)]
        while work and len(seen) < 14:
            cur, d = work.pop(0)
            if cur in seen or d > 3:
                continue
            seen.add(cur)
            apis, internals = self._direct(cur)
            for a in apis:
                if a not in found or d < found[a]:
                    found[a] = d
            if d < 3:
                for t in internals:
                    if t not in seen:
                        work.append((t, d + 1))
        self._apis[va] = found
        return found

    def _global_thunk(self, va):
        off = self.va_to_off(va)
        if off is None:
            return None
        blob = self.data[off:off + 0x50]
        seq, cached = [], None
        for i, insn in enumerate(self.md.disasm(blob, va)):
            if i >= 9:
                break
            seq.append(f"{insn.mnemonic} {insn.op_str}")
            if insn.mnemonic == "mov" and insn.op_str.startswith("rax, qword ptr [rip"):
                try:
                    disp = int(insn.op_str.split("+", 1)[1].split("]", 1)[0].strip(), 16)
                    cached = insn.address + insn.size + disp
                except Exception:
                    pass
            if insn.mnemonic in ("jmp", "ret"):
                break
        t = " | ".join(seq)
        if ("mov rcx, qword ptr [rip" in t and "mov rax, qword ptr [rcx + 0x18]" in t
                and "cmp rax, qword ptr [rip" in t):
            return cached
        return None

    def _module_variable_accessor_strict(self, va):
        """Prove a generated Python 3.11+ ``module_var_accessor_*``.

        Nuitka 4.x caches a module dictionary's keys version/index instead of
        using the compact thunk above.  The native fingerprint is a dictionary
        loaded from a fixed RIP slot, followed by its ``ma_keys`` field at
        offset ``0x20`` and an indexed ``PyDictUnicodeEntry.me_value`` read at
        offset ``0x28``.  A generic dict getter receives the dict in an
        argument, so it cannot satisfy the fixed-root requirement.

        Name recovery remains independent: ``_LiveRegSim._global_name`` reads
        the exact module-constant slot used by this accessor.
        """
        cache = getattr(self, "_module_var_accessor_cache", None)
        if cache is None:
            cache = self._module_var_accessor_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False
        off = self.va_to_off(va)
        if off is None:
            return False

        gp = set(self._GP_REGS)
        fixed_regs = set()
        keys_regs = set()
        saw_fixed_keys = False
        saw_unicode_entry = False
        try:
            blob, _has_exact_extent = self._bounded_helper_blob(
                va, off, 0x300)
            for index, insn in enumerate(self.md.disasm(blob, va)):
                if index >= 220:
                    break
                m, o = insn.mnemonic.lower(), insn.op_str.lower()
                if m == "ret":
                    break
                if m not in ("mov", "lea") or "," not in o:
                    continue
                dst, src = [x.strip() for x in o.split(",", 1)]
                if dst not in gp:
                    continue
                if src in fixed_regs:
                    fixed_regs.add(dst)
                    keys_regs.discard(dst)
                    continue
                if src in keys_regs:
                    keys_regs.add(dst)
                    fixed_regs.discard(dst)
                    continue
                if "[rip + " in src and m == "mov":
                    fixed_regs.add(dst)
                    keys_regs.discard(dst)
                    continue
                mm = re.search(
                    r"\[([a-z0-9]+)(?:\s*\+\s*[a-z0-9]+\*8)?"
                    r"(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]", src)
                _base_was_fixed = False
                if mm:
                    _base_was_fixed = mm.group(1) in fixed_regs
                fixed_regs.discard(dst)
                keys_regs.discard(dst)
                if not mm:
                    continue
                disp = int(mm.group(2), 0) if mm.group(2) else 0
                if disp == 0x20 and _base_was_fixed:
                    keys_regs.add(dst)
                    saw_fixed_keys = True
                if (saw_fixed_keys and disp == 0x28
                        and re.search(r"\[[^\]]+\*8[^\]]*\]", src)):
                    saw_unicode_entry = True
            cache[va] = bool(saw_fixed_keys and saw_unicode_entry)
        except Exception:
            return False
        return cache[va]

    def _is_global_lookup(self, va):
        """The module/global value-lookup helper: given a STRING key in rdx and
        a dict in rcx, it hashes the key (`mov rax,[rdx+0x18]` = ob_shash, then
        `cmp rax,-1` to recompute if uncached) and calls the dict lookup fn.
        rdx = the global's NAME. Lets us recover globals resolved by a CALL
        (not the inline thunk handled by `_global_thunk`)."""
        off = self.va_to_off(va)
        if off is None:
            return False
        seq = []
        for i, insn in enumerate(self.md.disasm(self.data[off:off + 0x70], va)):
            if i >= 12:
                break
            seq.append(f"{insn.mnemonic} {insn.op_str}")
            if insn.mnemonic == "ret":
                break
        t = " | ".join(seq)
        # V95 Fix 5 (universal): the hash register is compiler-chosen — MSVC
        # loads ob_shash into rax, gcc/MinGW into any GP register (e.g.
        # `mov r8, [rdx+0x18]; cmp r8, -1`).  Match the loaded register
        # generically instead of the MSVC literal.
        if "[rdx + 0x18]" not in t:
            return False
        _hm = re.search(r"mov (r[a-z0-9]+), qword ptr \[rdx \+ 0x18\]", t)
        if _hm and ("cmp %s, -1" % _hm.group(1)) in t:
            return True
        return "cmp rax, -1" in t

    def global_const(self, tva):
        """Resolve a `[rip+tva]` load that targets the SHARED `global_constants`
        array (small ints 0/1/-1, '', (), {}, builtin names open/len/range/print,
        dunders __enter__/__exit__, …). Nuitka stores these in ONE blob chunk
        named "" loaded by `loadConstantsBlob(tstate, &global_constants[0], "")`;
        the values are deterministic. Returns the exact value or None."""
        self._ensure_globals()
        gb = self._gbase
        if gb and tva >= gb and (tva - gb) % 8 == 0:
            gi = (tva - gb) // 8
            if 0 <= gi < len(self._gconsts):
                return self._gconsts[gi], True
        return None, False

    def _ensure_globals(self):
        if getattr(self, "_gready", False):
            return
        self._gready = True
        self._gbase = None
        self._gconsts = []
        try:
            self._gbase = self._find_global_base()
        except Exception:
            self._gbase = None
        try:
            # The shared context owns the decrypted blob.  Prefer its exact
            # global-constants chunk; re-reading RT_RCDATA here sees encrypted
            # bytes on Commercial binaries and used to report a bogus CRC
            # mismatch after an expensive whole-resource parse.
            chunk = getattr(self, '_global_constants_chunk', None)
            if chunk:
                self._gconsts = parse_module_constants(
                    chunk,
                    python_version=(getattr(self, '_target_python', None)
                                    or (3, 10)),
                    profile=getattr(self, '_constants_profile', None))
            else:
                blob = self._extract_blob()
                if blob:
                    for n, c in parse_blob_modules(blob):
                        if n == "":
                            self._gconsts = parse_module_constants(
                                c, python_version=(getattr(
                                    self, '_target_python', None) or (3, 10)),
                                profile=getattr(
                                    self, '_constants_profile', None))
                            break
        except Exception:
            self._gconsts = []

    def _extract_blob(self):
        pe = self.pe
        if hasattr(pe, "DIRECTORY_ENTRY_RESOURCE"):
            for rt in pe.DIRECTORY_ENTRY_RESOURCE.entries:
                if rt.id == 10:                      # RT_RCDATA
                    for ri in rt.directory.entries:
                        if ri.id == 3:               # Nuitka constants
                            for rl in ri.directory.entries:
                                rva = rl.data.struct.OffsetToData
                                sz = rl.data.struct.Size
                                return bytes(pe.get_memory_mapped_image()[rva:rva + sz])
        return None

    def _find_global_base(self):
        """`&global_constants[0]` = the rdx arg of the `loadConstantsBlob(...,"")`
        call (the chunk whose name is the empty string). Find it by scanning
        .text for `lea rdx,[rip+A]; lea r8,[rip+name]; call LOADER`, taking the
        most-called target as the loader, then the entry whose name C-string is
        empty."""
        from collections import Counter

        def cstr(va):
            o = self.va_to_off(va)
            if o is None:
                return None
            b = self.data[o:o + 48]
            z = b.find(b"\x00")
            try:
                return b[:z if z >= 0 else 48].decode("ascii")
            except Exception:
                return None

        # Scan only the three machine instructions emitted by
        # loadConstantsBlob(tstate, ARRAY, NAME):
        #
        #   lea rdx, [rip + ARRAY]
        #   lea r8,  [rip + NAME]
        #   call LOADER
        #
        # The former implementation fed the complete 40-100 MiB .text section
        # through Capstone and retained every instruction.  This sparse byte
        # scanner is equivalent evidence, takes constant memory, and is also
        # resilient to stripped symbols.
        hits = []
        for s in self.pe.sections:
            if s.Name.rstrip(b'\x00') != b'.text':
                continue
            secva = self.base + s.VirtualAddress
            data = self.data[s.PointerToRawData:s.PointerToRawData + s.SizeOfRawData]
            pos = data.find(b'\x4c\x8d\x05')  # lea r8,[rip+disp32]
            while pos >= 0 and pos + 7 <= len(data):
                try:
                    name_va = secva + pos + 7 + struct.unpack_from(
                        '<i', data, pos + 3)[0]
                    cs = cstr(name_va)
                except Exception:
                    cs = None
                if cs is not None and (cs == "" or "." in cs or cs.isidentifier()):
                    # MSVC is free to schedule the independent argument LEAs in
                    # either order.  Older generated code used
                    #
                    #     lea rdx, ARRAY; lea r8, NAME; call loader
                    #
                    # while current Nuitka/MSVC output also uses
                    #
                    #     lea r8, NAME; ...; lea rdx, ARRAY; call loader.
                    #
                    # The old one-sided search therefore missed the *entire*
                    # shared global_constants table on those binaries.  Search a
                    # bounded setup window on both sides, then require the chosen
                    # rdx LEA and r8 LEA to precede the same following direct call.
                    # This remains structural evidence from loadConstantsBlob's
                    # Win64 ABI; it does not infer constants from application code.
                    lo = max(0, pos - 48)
                    hi = min(len(data), pos + 64)
                    rdx_before = data.rfind(b'\x48\x8d\x15', lo, pos)
                    rdx_after = data.find(b'\x48\x8d\x15', pos + 7, hi)
                    rdx_candidates = [p for p in (rdx_before, rdx_after)
                                      if p >= 0 and p + 7 <= len(data)]
                    # Prefer the nearest setup instruction.  A later validity
                    # gate rejects candidates that fall after the call.
                    rdx_pos = min(rdx_candidates, key=lambda p: abs(p - pos)) \
                        if rdx_candidates else -1
                    if rdx_pos >= 0:
                        arr = secva + rdx_pos + 7 + struct.unpack_from(
                            '<i', data, rdx_pos + 3)[0]
                        # Find the first direct call before another r8 setup.
                        call_start = max(pos + 7, rdx_pos + 7)
                        cp = data.find(b'\xe8', call_start, hi)
                        next_r8 = data.find(b'\x4c\x8d\x05', pos + 7, hi)
                        if (cp >= 0 and rdx_pos < cp
                                and (next_r8 < 0 or cp < next_r8)
                                and cp + 5 <= len(data)):
                            target = secva + cp + 5 + struct.unpack_from(
                                '<i', data, cp + 1)[0]
                            hits.append((target, arr, cs))
                pos = data.find(b'\x4c\x8d\x05', pos + 1)
        if not hits:
            return None
        loader = Counter(h[0] for h in hits).most_common(1)[0][0]
        for t, arr, cs in hits:
            if t == loader and cs == "":
                return arr
        return None

    # offsetof(PyTypeObject, tp_richcompare) on CPython 3.10 / Win64.
    _TP_RICHCOMPARE = 0xc8
    _RICHCMP_OPS = {0: "<", 1: "<=", 2: "==", 3: "!=", 4: ">", 5: ">="}

    # SET instructions encode comparison operators in type-specialized helpers.
    _SETOP_CMP_MAP = {
        "setne": "!=", "setnz": "!=",
        "sete":  "==", "setz":  "==",
        "setg":  ">",  "setge": ">=",
        "setl":  "<",  "setle": "<=",
        "seta":  ">",  "setae": ">=",
        "setb":  "<",  "setbe": "<=",
    }

    def _richcmp_op(self, va):
        """A type-specialized RICH_COMPARE_xx helper invokes the slow path
        `tp_richcompare(a, b, Py_XX)` via an indirect call to `[type + 0xc8]`,
        with the operator enum Py_XX loaded into r8d immediately before. Read
        that enum (NO guessing) -> exact operator string, else None.

        Also detects the fast-path-only variant used by fully type-specialized
        helpers (e.g. RICH_COMPARE_NE_OBJECT_LONG_INT): these never call
        tp_richcompare; instead they do direct integer comparison via native
        `test`/`cmp` + SET instructions (setne, sete, setg, …). The first
        SET instruction found after a `test reg,reg` or `cmp reg,0` sequence
        gives the operator."""
        # Prefer the actual Py_LT..Py_GE enum passed to tp_richcompare.  A
        # generic comparison helper often contains ``test result; setne`` to
        # convert the returned truth object to C bool; that SETcc describes
        # truth conversion, not the source comparison operator.  SETcc is a
        # valid fallback only for fully specialised helpers with no slot
        # dispatch at all.
        slot_operator = self._richcmp_slot_op(va)
        if slot_operator is not None:
            return slot_operator
        off = self.va_to_off(va)
        if off is None:
            return None
        # Resta DENTRO i confini della funzione: disassemblare oltre la
        # fine (vecchia finestra cieca 0x400/220 istruzioni) faceva
        # matchare pattern test+SETcc del codice adiacente, classificando
        # helper estranei (es. LIST_APPEND inline) come RICH_COMPARE.
        blob = self.data[off:off + 0x400]
        _extent = self._helper_extent(va)
        _end_va = (int(_extent[1]) if _extent is not None and
                   int(_extent[0]) == int(va) else None)
        last_r8 = None
        seen_slot = False
        last_test_zero = False   # True after test r,r or cmp r,0
        for i, insn in enumerate(self.md.disasm(blob, va)):
            if i >= 220:
                break
            if _end_va is not None and insn.address + insn.size > _end_va:
                break
            mn, o = insn.mnemonic, insn.op_str
            if mn == "mov" and o.split(",")[0].strip() in ("r8", "r8d"):
                rhs = o.split(",", 1)[1].strip() if "," in o else ""
                try:
                    v = int(rhs, 0)
                except Exception:
                    v = None
                last_r8 = v if (v is not None and 0 <= v <= 5) else None
            elif mn == "mov" and ("+ 0xc8]" in o):
                seen_slot = True
            elif (mn == "call" and seen_slot and last_r8 is not None
                    and o in ("rax", "r9", "r10", "r11", "rdx", "rbx", "rsi", "rdi")):
                return self._RICHCMP_OPS.get(last_r8)
            # ---- fast-path SET-instruction detector ----
            # `test reg, reg` (reg == 0?) or `cmp reg, 0` primes the flag;
            # the subsequent SET instruction encodes the comparison operator.
            elif mn in ("test", "cmp"):
                parts = [x.strip() for x in o.split(",")]
                if len(parts) == 2:
                    if mn == "test" and parts[0] == parts[1]:
                        last_test_zero = True
                    elif mn == "cmp":
                        try:
                            last_test_zero = (int(parts[1], 0) == 0)
                        except Exception:
                            last_test_zero = False
                    else:
                        last_test_zero = False
            elif mn in self._SETOP_CMP_MAP and last_test_zero:
                return self._SETOP_CMP_MAP[mn]
            elif mn == "call":
                last_test_zero = False   # reset on any intervening call
            # NOTE: do NOT break at the first `ret`. A type-specialized compare
            # has a FAST path (`cmp a,b; ret`) that returns before the SLOW path
            # (`...; mov r8d,Py_XX; call [type+0xc8]`) where the operator enum
            # lives — breaking at the fast-path ret returned None and left the
            # helper UNKNOWN (so the `if balance != -1:` decode never emitted).
            # The `seen_slot && r8d in 0..5 && call reg` pattern is specific
            # enough to scan the whole helper (capped at 220 insns) safely.
        return None

    def _richcmp_slot_op(self, va):
        """Recover a comparison enum together with its operand orientation.

        Track the actual indirect callee, argument aliases and volatile-register
        clobbers. Reflected dispatch (right, left, swapped_op) describes the
        same source operation as direct dispatch (left, right, op).
        """
        off = self.va_to_off(va)
        if off is None:
            return None
        win64 = getattr(self.pe, 'fmt', 'pe') == 'pe'
        argregs = ('rcx', 'rdx', 'r8') if win64 else ('rdi', 'rsi', 'rdx')
        volatile = ({'rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11'} if win64
                    else {'rax', 'rcx', 'rdx', 'rsi', 'rdi', 'r8', 'r9', 'r10', 'r11'})
        regs = {argregs[0]: ('operand', 0), argregs[1]: ('operand', 1)}
        observed = set()
        blob, bounded = self._bounded_helper_blob(va, off, 0x1200)
        insns = {ins.address: ins for ins in self.md.disasm(blob, va)}
        pending = [(va, regs)]
        seen = set()
        while pending:
            pc, incoming = pending.pop()
            state = (pc, tuple(sorted(incoming.items())))
            if state in seen or pc not in insns:
                continue
            seen.add(state)
            if len(seen) > 8000:
                return None
            regs = dict(incoming)
            ins = insns[pc]
            parts = split_ops(ins.op_str)
            if ins.mnemonic in ('mov', 'movabs') and len(parts) == 2:
                dst, src = subreg64(parts[0]), subreg64(parts[1])
                if dst is None:
                    pending.append((ins.address + ins.size, regs))
                    continue
                value = regs.get(src)
                imm = is_imm(parts[1])
                mem = parse_mem(parts[1])
                if imm is not None:
                    value = ('imm', imm)
                elif mem and mem[1] == 8 and regs.get(mem[0], (None,))[0] == 'operand':
                    value = ('type', regs[mem[0]][1])
                elif mem and mem[1] == 0xc8 and not mem[2]:
                    # An IAT type may describe the specialised right operand.
                    # The call's explicit operand aliases disambiguate it.
                    value = ('richslot',)
                if value is None:
                    regs.pop(dst, None)
                else:
                    regs[dst] = value
            elif ins.mnemonic in ('xor', 'sub') and len(parts) == 2:
                dst = subreg64(parts[0])
                if dst and dst == subreg64(parts[1]):
                    regs[dst] = ('imm', 0)
                elif dst:
                    regs.pop(dst, None)
            elif ins.mnemonic == 'call':
                callee = regs.get(subreg64(ins.op_str))
                mem = parse_mem(ins.op_str)
                is_slot = callee == ('richslot',) or bool(
                    mem and mem[1] == 0xc8 and not mem[2]
                    and regs.get(mem[0], (None,))[0] == 'type')
                if is_slot:
                    left, right, enum = (regs.get(r) for r in argregs)
                    if enum and enum[0] == 'imm' and 0 <= enum[1] <= 5:
                        op = enum[1]
                        if (left, right) == (('operand', 1), ('operand', 0)):
                            op = {0: 4, 1: 5, 2: 2, 3: 3, 4: 0, 5: 1}[op]
                        elif (left, right) != (('operand', 0), ('operand', 1)):
                            op = None
                        if op is not None:
                            observed.add(op)
                for reg in volatile:
                    regs.pop(reg, None)
            elif ins.mnemonic == 'ret':
                continue
            elif ins.mnemonic not in ('cmp', 'test', 'push', 'jmp') and parts:
                # Invalidate writes we do not model (lea, pop, setcc, etc.).
                if not ins.mnemonic.startswith('j'):
                    regs.pop(subreg64(parts[0]), None)
            if ins.mnemonic.startswith('j'):
                target = is_imm(ins.op_str)
                if target in insns:
                    pending.append((target, regs))
                if ins.mnemonic == 'jmp':
                    continue
            pending.append((ins.address + ins.size, regs))
        return self._RICHCMP_OPS[next(iter(observed))] if len(observed) == 1 else None

    # offsetof(PyTypeObject, tp_getattro/tp_setattro) on CPython 3.10 / Win64.
    _TP_GETATTRO = 0x90
    _TP_SETATTRO = 0x98

    def _setattr_slot(self, va):
        """`self.x = v` compiles to SET_ATTRIBUTE(tstate, target, attr, value),
        whose helper DISPATCHES the store through `type->tp_setattro` (struct
        offset 0x98): the generic fast-path COMPARES that slot against
        PyObject_GenericSetAttr, the custom path CALLs it. No read/get operation
        touches tp_setattro, so a clean 0x98 type-slot access — with NO tp_getattro
        (0x90) access, which would instead mark an attribute GET — uniquely
        fingerprints an attribute STORE helper. (Same structural style as the
        _richcmp_op tp_richcompare/0xc8 detector.)"""
        off = self.va_to_off(va)
        if off is None:
            return False
        touch_set = False
        for i, insn in enumerate(self.md.disasm(self.data[off:off + 0x140], va)):
            if i >= 90:
                break
            if insn.mnemonic == "ret":
                break
            o = insn.op_str
            for off_str, is_set in (("+ 0x98]", True), ("+ 0x90]", False)):
                if off_str in o:
                    base = o.split(off_str)[0][-7:]
                    if not any(b in base for b in ("rsp", "rbp", "rip")):
                        if is_set:
                            touch_set = True
                        else:
                            return False        # tp_getattro -> this is a GET
        return touch_set

    def _setattr_slot_strict(self, va):
        """Prove an inlined ``SET_ATTRIBUTE`` helper by dataflow shape.

        CPython 3.11+ binaries frequently do not import ``PyObject_SetAttr``:
        Nuitka expands the operation to ``Py_TYPE(target)->tp_setattro`` and
        calls that slot directly.  A plain search for offset ``0x98`` is unsafe
        on these versions because unrelated frame layouts also contain that
        offset.  This recognizer instead requires the complete, call-confirmed
        chain::

            type_reg = [argument + 8]       # Py_TYPE(argument)
            slot_reg = [type_reg + 0x98]    # tp_setattro
            call slot_reg

        It also rejects a competing ``tp_getattro`` chain.  Register copies are
        propagated, so normal compiler allocation changes do not affect it.
        """
        off = self.va_to_off(va)
        if off is None:
            return False
        gp = set(self._GP_REGS)
        type_regs = set()
        slot_regs = set()
        try:
            insns = self.md.disasm(self.data[off:off + 0x300], va)
            for index, insn in enumerate(insns):
                if index >= 180:
                    break
                m, o = insn.mnemonic, insn.op_str.lower()
                if m == 'call':
                    callee = o.strip()
                    if callee in slot_regs:
                        return True
                    continue
                if m != 'mov' or ',' not in o:
                    continue
                dst, src = [x.strip() for x in o.split(',', 1)]
                if dst not in gp:
                    continue
                if src in type_regs:
                    type_regs.add(dst)
                    slot_regs.discard(dst)
                    continue
                if src in slot_regs:
                    slot_regs.add(dst)
                    type_regs.discard(dst)
                    continue
                mm = re.search(
                    r'\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]',
                    src)
                if not mm:
                    type_regs.discard(dst)
                    slot_regs.discard(dst)
                    continue
                base = mm.group(1)
                disp = int(mm.group(2), 0) if mm.group(2) else 0
                if disp == 8 and base in ('rcx', 'rdx', 'r8', 'r9'):
                    type_regs.add(dst)
                    slot_regs.discard(dst)
                elif disp == self._TP_GETATTRO and base in type_regs:
                    return False
                elif disp == self._TP_SETATTRO and base in type_regs:
                    slot_regs.add(dst)
                    type_regs.discard(dst)
                else:
                    type_regs.discard(dst)
                    slot_regs.discard(dst)
        except Exception:
            return False
        return False

    def _pyiter_check_follows(self, va, off):
        """GetIter-specific follow-up: within a few instructions after the
        tp_iter call, the helper verifies the result is an iterator
        (CPython's PyIter_Check): `mov T,[result+8]` then `mov S,[T+K]` with
        K a tp_iternext-candidate offset (0xd8/0xe0) plus a test/compare.
        PyIter_Next never performs this check, so its presence distinguishes
        a GetIter wrapper from an iternext one on EITHER type layout.
        """
        try:
            blob, _ = self._bounded_helper_blob(va, off, 0x300)
            res_types = set()
            for index, insn in enumerate(self.md.disasm(blob, va)):
                if index >= 60:
                    break
                m, o = insn.mnemonic.lower(), insn.op_str.lower()
                if m != "mov" or "," not in o:
                    continue
                dst, src = [x.strip() for x in o.split(",", 1)]
                mm = re.search(r"\[([a-z0-9]+) \+ (0x[0-9a-f]+|\d+)\]", src)
                if not mm:
                    continue
                base, disp = mm.group(1), int(mm.group(2), 16)
                if disp == 8:
                    res_types.add(dst)
                elif base in res_types and disp in (0xd8, 0xe0):
                    return True
        except Exception:
            pass
        return False

    def _getiter_slot_strict(self, va):
        """Prove a GetIter/PyIter_New wrapper helper, API-free.

        Shape (verified on the machine code against CPython's own

        ``iter() returned non-iterator of type '%s'`` error string):
            mov T, [rcx + 8]        # ob_type of the iterable (rcx)
            mov S, [T + K]          # type->tp_iter (K = tp_iternext_off - 8)
            test S, S ; je <raise>  # NULL slot -> TypeError fallback
            call S                  # tp_iter(iterable) -> iterator
        The method-call dispatcher family shares the outer frame but invokes
        tp_call/tp_vectorcall - never the tp_iter slot, whose offset is read
        per-binary (the runtime derives tp_iternext_off from proven loop
        headers; tp_iter sits one slot before it in every PyTypeObject).
        """
        cache = getattr(self, "_getiter_slot_cache", None)
        if cache is None:
            cache = self._getiter_slot_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False
        off = self.va_to_off(va)
        if off is None:
            return False
        # tp_iter candidates: derived per-binary (iternext_off - 8) when known,
        # else the stock CPython layout 0xd0.  A shifted build never has 0xd0,
        # a stock build never legitimately CALLs through 0xd8 as tp_iter.
        derived = getattr(self, '_ndl_binary_iternext_off', None)
        if not derived and getattr(self, 'pe', None) is not None:
            derived = getattr(self.pe, '_ndl_binary_iternext_off', None)
        if derived:
            k_ok = {derived - 8}
        else:
            # Underived ABI: accept BOTH tp_iter candidates (stock 0xd0 and
            # shifted 0xd8); the phase-2 PyIter_Check verification below is
            # what distinguishes GetIter from an iternext helper, which shares
            # the outer slot-call shape but never checks the result's type.
            k_ok = {0xd0, 0xd8}
        gp = set(self._GP_REGS)
        type_regs = set()
        slot_regs = {}          # reg -> slot offset
        je_seen = False
        try:
            blob, _has_exact_extent = self._bounded_helper_blob(
                va, off, 0x300)
            for index, insn in enumerate(self.md.disasm(blob, va)):
                if index >= 120:
                    break
                m, o = insn.mnemonic.lower(), insn.op_str.lower()
                if m == "call":
                    callee = o.strip()
                    if callee in slot_regs and slot_regs[callee] in k_ok:
                        if not derived:
                            # Underived ABI: accept the call only with the
                            # GetIter-SPECIFIC follow-up - PyIter_Check on the
                            # result (`mov T,[res+8]; mov S,[T+K2]; test/cmp`),
                            # which PyIter_Next never performs.  K2 is the
                            # OTHER iterator-protocol offset, so the pair
                            # (K, K2) proves tp_iter then tp_iternext check on
                            # EITHER layout without any derived offset.
                            _chk = self._pyiter_check_follows(va, off)
                            if not _chk:
                                break
                        cache[va] = True
                        return True
                    break
                if m == "ret":
                    break
                if m in ("je", "jne", "jz", "jnz"):
                    je_seen = True
                    continue
                if m != "mov" or "," not in o:
                    continue
                dst, src = [x.strip() for x in o.split(",", 1)]
                if dst not in gp:
                    continue
                mm = re.search(r"\[([a-z0-9]+) \+ (0x[0-9a-f]+|\d+)\]", src)
                if mm:
                    base, disp = mm.group(1), int(mm.group(2), 16)
                    if disp == 8:
                        type_regs.add(dst)
                        slot_regs.pop(dst, None)
                    elif base in type_regs:
                        slot_regs[dst] = disp
                    else:
                        slot_regs.pop(dst, None)
                    continue
                if src in gp:
                    if src in type_regs:
                        type_regs.add(dst)
                    elif src in slot_regs:
                        slot_regs[dst] = slot_regs[src]
                    else:
                        type_regs.discard(dst)
                        slot_regs.pop(dst, None)
        except Exception:
            pass
        return False

    def _lookup_attr_tail_slot_strict(self, va):
        """Prove compact ``LOOKUP_ATTRIBUTE`` tp_getattro fast paths.

        Modern MSVC/Nuitka builds can inline this helper without reaching a
        public CPython API.  API collection consequently labels it UNKNOWN and
        the call-site fallback used to turn every identifier in ``r8`` into a
        *method call*.  In an async-with prologue this changed ``self._lock``
        into ``self._lock()``; the same error changed a later ``.pop`` lookup
        into a premature zero-argument call.

        The lookup-only helper has a stronger ABI fingerprint than an API name::

            type = Py_TYPE(source=rdx)          # [rdx + 8]
            slot = type->tp_getattro            # [type + 0x90]
            rcx = source; rdx = attr_name=r8
            jmp slot                             # tail return of lookup result

        Current MSVC also emits an equivalent call/return form so it can
        normalise a NULL result before returning::

            call slot
            test rax, rax; cmove rax, zero
            ret

        ``CALL_METHOD_*`` cannot use that tail jump: it must regain control and
        invoke the looked-up object.  Require the complete provenance chain,
        exact argument reshuffle, and the exact slot register as the terminal
        jump target.  Merely seeing displacement 0x90 is never sufficient.
        """
        cache = getattr(self, "_lookup_attr_tail_cache", None)
        if cache is None:
            cache = self._lookup_attr_tail_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False
        off = self.va_to_off(va)
        if off is None:
            return False

        gp = set(self._GP_REGS)
        origins = {
            "rcx": "tstate", "rdx": "source",
            "r8": "attr", "r9": "arg3",
        }
        type_regs = set()
        slot_regs = set()
        lookup_called = False
        try:
            blob, _has_exact_extent = self._bounded_helper_blob(
                va, off, 0x300)
            for index, insn in enumerate(self.md.disasm(blob, va)):
                if index >= 180:
                    break
                m, o = insn.mnemonic.lower(), insn.op_str.lower()
                if m == "call":
                    callee = o.strip()
                    if (callee in slot_regs
                            and origins.get("rcx") == "source"
                            and origins.get("rdx") == "attr"):
                        lookup_called = True
                        # The lookup result is now in RAX.  Any later call
                        # before RET would consume/transform it and therefore
                        # belongs to CALL_METHOD or another helper family.
                        continue
                    if lookup_called:
                        return False
                    continue
                if m == "jmp":
                    callee = o.strip()
                    if (callee in slot_regs
                            and origins.get("rcx") == "source"
                            and origins.get("rdx") == "attr"):
                        cache[va] = True
                        return True
                    continue
                if m == "ret":
                    if lookup_called:
                        cache[va] = True
                        return True
                    break
                if m != "mov" or "," not in o:
                    # Calls through tp_getattro followed by more work are the
                    # method-call family, never this lookup-only tail wrapper.
                    continue
                dst, src = [x.strip() for x in o.split(",", 1)]
                if dst not in gp:
                    continue
                if src in gp:
                    origin = origins.get(src)
                    if origin is None:
                        origins.pop(dst, None)
                    else:
                        origins[dst] = origin
                    if src in type_regs:
                        type_regs.add(dst)
                    else:
                        type_regs.discard(dst)
                    if src in slot_regs:
                        slot_regs.add(dst)
                    else:
                        slot_regs.discard(dst)
                    continue

                mm = re.search(
                    r"\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]",
                    src)
                origins.pop(dst, None)
                type_regs.discard(dst)
                slot_regs.discard(dst)
                if not mm:
                    continue
                base = mm.group(1)
                disp = int(mm.group(2), 0) if mm.group(2) else 0
                if disp == 8 and origins.get(base) == "source":
                    type_regs.add(dst)
                elif disp == self._TP_GETATTRO and base in type_regs:
                    slot_regs.add(dst)
        except Exception:
            return False
        return False

    def _method_call_slot_strict(self, va):
        """Prove a compact ``CALL_METHOD_*`` helper and its argument ABI.

        Nuitka 4.x/MSVC can compile ``CALL_METHOD_NO_ARGS`` and
        ``CALL_METHOD_WITH_SINGLE_ARG`` without a reachable public CPython API.
        They consequently used to be labelled ``UNKNOWN``.  Their native data
        flow is nevertheless unambiguous: look up ``source.attr`` through
        ``Py_TYPE(source)->tp_getattro``, regain control after that call, then
        consume the returned object through its call/vectorcall slot.  A plain
        ``LOOKUP_ATTRIBUTE`` ends in the first slot's tail jump and therefore
        cannot satisfy the second half of this proof.

        Return ``0`` for the no-argument helper, ``1`` when the fourth Win64
        argument (``r9``) is preserved before the lookup call, and ``None`` when
        the complete chain is absent.  The exact arity tag prevents stale
        caller registers from becoming phantom Python arguments.
        """
        cache = getattr(self, "_method_call_slot_cache", None)
        if cache is None:
            cache = self._method_call_slot_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = None
        off = self.va_to_off(va)
        if off is None:
            return None

        gp = set(self._GP_REGS)
        origins = {
            "rcx": "tstate", "rdx": "source",
            "r8": "attr", "r9": "arg0",
        }
        source_types = set()
        getattro_slots = set()
        callable_regs = set()
        callable_types = set()
        call_slots = set()
        lookup_called = False
        arg0_preserved = False

        try:
            blob, _has_exact_extent = self._bounded_helper_blob(
                va, off, 0x500)
            for index, insn in enumerate(self.md.disasm(blob, va)):
                if index >= 300:
                    break
                m, o = insn.mnemonic.lower(), insn.op_str.lower()

                if m == "call":
                    callee = o.strip()
                    if callee in getattro_slots:
                        lookup_called = True
                        # x64 return-value provenance begins in rax.  It may be
                        # copied to a callee-saved register immediately after.
                        callable_regs = {"rax"}
                        callable_types.clear()
                        call_slots.clear()
                        origins["rax"] = "callable"
                    elif lookup_called and callee in call_slots:
                        cache[va] = 1 if arg0_preserved else 0
                        return cache[va]
                    continue
                if m in ("ret", "jmp"):
                    # A tail jump through tp_getattro is lookup-only.  A method
                    # helper must return from the lookup and make a second call.
                    if m == "ret":
                        break
                    continue
                if m not in ("mov", "lea") or "," not in o:
                    continue

                dst, src = [x.strip() for x in o.split(",", 1)]
                if dst.startswith(("qword ptr [rsp", "[rsp")):
                    if origins.get(src) == "arg0" and not lookup_called:
                        arg0_preserved = True
                    continue
                if dst not in gp:
                    continue

                if src in gp:
                    origin = origins.get(src)
                    if origin is None:
                        origins.pop(dst, None)
                    else:
                        origins[dst] = origin
                    if origin == "arg0" and dst != "r9" and not lookup_called:
                        arg0_preserved = True
                    for tagged in (source_types, getattro_slots, callable_regs,
                                   callable_types, call_slots):
                        if src in tagged:
                            tagged.add(dst)
                        else:
                            tagged.discard(dst)
                    continue

                mm = re.search(
                    r"\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]",
                    src)
                _base_was_source_type = False
                _base_was_callable = False
                _base_was_callable_type = False
                if mm:
                    _pre_base = mm.group(1)
                    _base_was_source_type = _pre_base in source_types
                    _base_was_callable = _pre_base in callable_regs
                    _base_was_callable_type = _pre_base in callable_types
                origins.pop(dst, None)
                source_types.discard(dst)
                getattro_slots.discard(dst)
                callable_regs.discard(dst)
                callable_types.discard(dst)
                call_slots.discard(dst)
                if not mm:
                    continue
                base = mm.group(1)
                disp = int(mm.group(2), 0) if mm.group(2) else 0
                if disp == 8 and origins.get(base) == "source":
                    source_types.add(dst)
                elif disp == self._TP_GETATTRO and _base_was_source_type:
                    getattro_slots.add(dst)
                elif lookup_called and disp == 8 and _base_was_callable:
                    callable_types.add(dst)
                elif (lookup_called and disp == 0x110
                      and _base_was_callable_type):
                    call_slots.add(dst)
        except Exception:
            return None
        return None

    def _function_call_slot_strict(self, va):
        """Prove Nuitka's API-free generic ``CALL_FUNCTION_*`` dispatcher.

        Generated helpers recursively re-enter the same dispatcher after a
        ``__call__`` descriptor lookup.  Requiring that exact self-call, an
        argument-derived ``Py_TYPE(called)`` load, and a call-confirmed
        ``tp_call`` slot (offset ``0x110`` on the target CPython ABI) avoids the
        old broad "UNKNOWN means call" guess.  Exact ``.pdata`` bounds are
        mandatory because the recursive edge may be near the end of a large
        helper and scanning into its neighbour would manufacture this pattern.

        Returns ``"r8"`` when the third Win64 argument is preserved as the
        positional-argument payload, ``"none"`` for ``CALL_FUNCTION_NO_ARGS``,
        or ``None`` when not proven.
        """
        cache = getattr(self, "_function_call_slot_cache", None)
        if cache is None:
            cache = self._function_call_slot_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = None
        off = self.va_to_off(va)
        extent = self._helper_extent(va)
        if off is None or extent is None:
            return None

        gp = set(self._GP_REGS)
        origins = {"rdx": "called", "r8": "args"}
        called_types = set()
        any_types = set()
        call_slots = set()
        type_from_called = False
        slot_called = False
        self_called = False
        args_preserved = False
        try:
            # Exact unwind metadata makes reading the full generated dispatcher
            # safe even when it is substantially larger than the old 0x400
            # heuristic window.
            blob, has_exact_extent = self._bounded_helper_blob(
                va, off, max(0x1000, extent[1] - va))
            if not has_exact_extent:
                return None
            for index, insn in enumerate(self.md.disasm(blob, va)):
                if index >= 1800:
                    break
                m, o = insn.mnemonic.lower(), insn.op_str.lower()
                if m == "call":
                    callee = o.strip()
                    if callee in call_slots:
                        slot_called = True
                    elif callee.startswith("0x"):
                        try:
                            if int(callee, 16) == int(va):
                                self_called = True
                        except Exception:
                            pass
                    continue
                if m == "ret":
                    continue
                if m not in ("mov", "lea") or "," not in o:
                    continue
                dst, src = [x.strip() for x in o.split(",", 1)]
                if dst.startswith(("qword ptr [rsp", "[rsp")):
                    if origins.get(src) == "args":
                        args_preserved = True
                    continue
                if dst not in gp:
                    continue
                if src in gp:
                    origin = origins.get(src)
                    if origin is None:
                        origins.pop(dst, None)
                    else:
                        origins[dst] = origin
                    if origin == "args" and dst != "r8":
                        args_preserved = True
                    for tagged in (called_types, any_types, call_slots):
                        if src in tagged:
                            tagged.add(dst)
                        else:
                            tagged.discard(dst)
                    continue

                mm = re.search(
                    r"\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]",
                    src)
                # Preserve the base provenance before killing the destination:
                # MSVC commonly emits destructive walks such as
                # ``mov rdx, [rdx+8]``.  Looking up origins after the kill made
                # the whole CALL_FUNCTION_* family invisible whenever dst and
                # base were the same register.
                base_origin = None
                base_was_any_type = False
                if mm:
                    pre_base = mm.group(1)
                    base_origin = origins.get(pre_base)
                    base_was_any_type = pre_base in any_types
                origins.pop(dst, None)
                called_types.discard(dst)
                any_types.discard(dst)
                call_slots.discard(dst)
                if not mm:
                    continue
                base = mm.group(1)
                disp = int(mm.group(2), 0) if mm.group(2) else 0
                if disp == 8:
                    any_types.add(dst)
                    if base_origin == "called":
                        called_types.add(dst)
                        type_from_called = True
                elif disp == 0x110 and base_was_any_type:
                    call_slots.add(dst)
            if type_from_called and slot_called and self_called:
                cache[va] = "r8" if args_preserved else "none"
        except Exception:
            return None
        return cache[va]

    def _getattr3_helper(self, va):
        """Prove Nuitka's ``BUILTIN_GETATTR`` with an optional default.

        This helper validates the attribute as Unicode, invokes
        ``PyObject_GetAttr(object, attribute)``, and on AttributeError returns
        an INCREF'd fourth Win64 ABI argument.  All argument identities are
        followed through the helper CFG (including RSP spills), and scanning is
        admitted only with an exact ``.pdata`` extent because MSVC places the
        default/error arm after an earlier hot-path RET.

        No helper VA or application/module string participates in the proof.
        """
        cache = getattr(self, "_getattr3_cache", None)
        if cache is None:
            cache = self._getattr3_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False

        extent = self._helper_extent(va)
        off = self.va_to_off(va)
        if (extent is None or off is None or int(extent[0]) != int(va)
                or int(extent[1]) <= int(va)
                or int(extent[1]) - int(va) > 0x2000):
            return False
        blob = self.data[off:off + int(extent[1]) - int(va)]
        try:
            insns = list(self.md.disasm(blob, va))
        except Exception:
            return False
        if not insns or len(insns) > 1200:
            return False

        reg_alias = {
            "al": "rax", "ah": "rax", "ax": "rax", "eax": "rax",
            "bl": "rbx", "bh": "rbx", "bx": "rbx", "ebx": "rbx",
            "cl": "rcx", "ch": "rcx", "cx": "rcx", "ecx": "rcx",
            "dl": "rdx", "dh": "rdx", "dx": "rdx", "edx": "rdx",
            "sil": "rsi", "si": "rsi", "esi": "rsi",
            "dil": "rdi", "di": "rdi", "edi": "rdi",
            "bpl": "rbp", "bp": "rbp", "ebp": "rbp",
            "spl": "rsp", "sp": "rsp", "esp": "rsp",
        }
        for rn in range(8, 16):
            reg_alias["r%db" % rn] = "r%d" % rn
            reg_alias["r%dw" % rn] = "r%d" % rn
            reg_alias["r%dd" % rn] = "r%d" % rn
        gp = set(self._GP_REGS) | {"rsp"}

        def reg(value):
            value = str(value or "").strip().lower()
            value = reg_alias.get(value, value)
            return value if value in gp else None

        def imm(value):
            try:
                return int(str(value or "").strip(), 0)
            except (TypeError, ValueError):
                return None

        def mem(value):
            mm = re.search(
                r"\[\s*([a-z][a-z0-9]*)(?:\s*([+-])\s*"
                r"(0x[0-9a-f]+|\d+))?\s*\]",
                str(value or "").lower(),
            )
            if not mm:
                return None
            base = reg(mm.group(1))
            if base is None:
                return None
            displacement = int(mm.group(3) or "0", 0)
            if mm.group(2) == "-":
                displacement = -displacement
            return base, displacement

        def rip_target(insn):
            mm = re.search(
                r"\[\s*rip(?:\s*([+-])\s*(0x[0-9a-f]+|\d+))?\s*\]",
                str(getattr(insn, "op_str", "")).lower(),
            )
            if not mm:
                return None
            displacement = int(mm.group(2) or "0", 0)
            if mm.group(1) == "-":
                displacement = -displacement
            return int(insn.address) + int(getattr(insn, "size", 0)) + displacement

        def iat_name(insn):
            target = rip_target(insn)
            return self.iat.get(target) if target is not None else None

        # Cheap exact-symbol gate before constructing the CFG.  Most runtime
        # helpers are rejected here; the later provenance walk still proves
        # that the GetAttr call receives the correct two original arguments and
        # that the AttributeError reference is on its reachable fallback path.
        if not any(
                str(insn.mnemonic).lower() in ("call", "callq")
                and iat_name(insn) == "PyObject_GetAttr"
                for insn in insns):
            return False
        if not any(iat_name(insn) == "PyExc_AttributeError"
                   for insn in insns):
            return False

        def stack_key(state, base, displacement):
            if base == "rsp":
                sp = state.get("@sp")
                if not isinstance(sp, int):
                    return None
                return "@stack:%d" % (sp + displacement)
            if base == "rbp":
                return "@rbp:%d" % displacement
            return None

        order = [int(insn.address) for insn in insns]
        by = {int(insn.address): insn for insn in insns}
        nxt = {order[index]: order[index + 1]
               for index in range(len(order) - 1)}

        def branch_target(insn):
            text = str(getattr(insn, "op_str", "")).strip().lower()
            try:
                return int(text, 0) if text.startswith("0x") else None
            except ValueError:
                return None

        succ = {}
        for address in order:
            insn = by[address]
            mnemonic = str(insn.mnemonic).lower()
            following = nxt.get(address)
            if mnemonic in ("ret", "retn"):
                targets = []
            elif mnemonic in ("jmp", "jmpq"):
                target = branch_target(insn)
                targets = [target] if target in by else []
            elif mnemonic.startswith("j"):
                target = branch_target(insn)
                targets = []
                if target in by:
                    targets.append(target)
                if following is not None:
                    targets.append(following)
            else:
                targets = [following] if following is not None else []
            succ[address] = list(dict.fromkeys(targets))

        evidence = {
            "unicode_guard": False,
            "getattr_call": False,
            "getattr_result_guard": False,
            "default_guard": False,
            "attribute_error": False,
            "default_incref": False,
            "default_return": False,
        }
        getattr_call_va = None
        default_stage_sites = []

        def token_from_operand(state, operand):
            rr = reg(operand)
            if rr is not None:
                return state.get(rr)
            mm = mem(operand)
            if mm is None:
                return None
            base, displacement = mm
            key = stack_key(state, base, displacement)
            if key is not None and key in state:
                return state.get(key)
            base_token = state.get(base)
            if displacement == 8 and base_token == "attribute":
                return "attribute_type"
            if base_token == "attribute_type":
                return "attribute_type_flags"
            if displacement == 0 and base_token == "default":
                return "default_refcount"
            return None

        volatile = {"rax", "rcx", "rdx", "r8", "r9", "r10", "r11"}

        def clobber_volatile(state):
            for rr in volatile:
                state.pop(rr, None)

        def writes_rax(insn):
            mnemonic = str(insn.mnemonic).lower()
            if mnemonic in ("call", "callq"):
                return True
            if (mnemonic in ("cmp", "test", "push", "jmp", "jmpq", "ret", "retn")
                    or mnemonic.startswith("j")):
                return False
            operand = str(getattr(insn, "op_str", "")).split(",", 1)[0]
            return reg(operand) == "rax"

        # Must-analysis: a join retains provenance only when every reaching
        # predecessor agrees, so cold and hot paths cannot smear ABI identities.
        incoming = {
            order[0]: {
                "rcx": "tstate", "rdx": "object",
                "r8": "attribute", "r9": "default", "@sp": 0,
            }
        }
        work = [order[0]]
        updates = 0
        while work and updates < len(order) * 20:
            address = work.pop(0)
            state = dict(incoming[address])
            insn = by[address]
            mnemonic = str(insn.mnemonic).lower()
            op = str(getattr(insn, "op_str", "")).lower()
            parts = [part.strip() for part in op.split(",", 1)]

            if state.get("@getattr") and iat_name(insn) == "PyExc_AttributeError":
                evidence["attribute_error"] = True

            if mnemonic in ("test", "cmp") and len(parts) == 2:
                left_token = token_from_operand(state, parts[0])
                right_token = token_from_operand(state, parts[1])
                left_imm, right_imm = imm(parts[0]), imm(parts[1])
                if (mnemonic == "test"
                        and ((left_token in ("attribute_type", "attribute_type_flags")
                              and right_imm == 0x10000000)
                             or (right_token in ("attribute_type", "attribute_type_flags")
                                 and left_imm == 0x10000000))):
                    evidence["unicode_guard"] = True
                if state.get("@getattr"):
                    if ((left_token == "getattr_result" and
                         (right_token == "getattr_result" or right_imm == 0))
                            or (right_token == "getattr_result" and left_imm == 0)):
                        evidence["getattr_result_guard"] = True
                    if ((left_token == "default" and
                         (right_token == "default" or right_imm == 0))
                            or (right_token == "default" and left_imm == 0)):
                        evidence["default_guard"] = True
            elif mnemonic == "bt" and len(parts) == 2:
                mm = mem(parts[0])
                bit = imm(parts[1])
                if (mm is not None and state.get(mm[0]) == "attribute_type"
                        and bit == 28):
                    evidence["unicode_guard"] = True

            if mnemonic in ("ret", "retn"):
                if state.get("@getattr") and state.get("rax") == "default":
                    evidence["default_return"] = True

            if mnemonic in ("call", "callq"):
                api = iat_name(insn)
                if (api == "PyObject_GetAttr"
                        and state.get("rcx") == "object"
                        and state.get("rdx") == "attribute"):
                    evidence["getattr_call"] = True
                    getattr_call_va = int(insn.address)
                    clobber_volatile(state)
                    state["rax"] = "getattr_result"
                    state["@getattr"] = True
                else:
                    if (api in ("Py_IncRef", "_Py_IncRef")
                            and state.get("rcx") == "default"
                            and state.get("@getattr")):
                        evidence["default_incref"] = True
                    clobber_volatile(state)
            elif (mnemonic in ("mov", "movabs", "movzx", "movsx", "movsxd")
                  and len(parts) == 2):
                dst, src = parts
                dst_reg = reg(dst)
                if dst_reg is not None:
                    value = token_from_operand(state, src)
                    if value is None:
                        state.pop(dst_reg, None)
                    else:
                        state[dst_reg] = value
                    if (dst_reg == "rax" and value == "default"
                            and state.get("@getattr")):
                        default_stage_sites.append(int(insn.address))
                else:
                    dm = mem(dst)
                    value = token_from_operand(state, src)
                    if dm is not None:
                        key = stack_key(state, dm[0], dm[1])
                        if key is not None:
                            if value is None:
                                state.pop(key, None)
                            else:
                                state[key] = value
                        if (state.get(dm[0]) == "default" and dm[1] == 0
                                and value == "default_refcount_inc"
                                and state.get("@getattr")):
                            evidence["default_incref"] = True
            elif mnemonic.startswith("cmov") and len(parts) == 2:
                dst_reg, src_reg = reg(parts[0]), reg(parts[1])
                if dst_reg is not None:
                    if src_reg is None or state.get(dst_reg) != state.get(src_reg):
                        state.pop(dst_reg, None)
            elif mnemonic == "lea" and parts:
                dst_reg = reg(parts[0])
                if dst_reg is not None:
                    state.pop(dst_reg, None)
            elif mnemonic == "push":
                old_sp = state.get("@sp")
                value = token_from_operand(state, parts[0]) if parts else None
                if isinstance(old_sp, int):
                    new_sp = old_sp - 8
                    state["@sp"] = new_sp
                    if value is not None:
                        state["@stack:%d" % new_sp] = value
            elif mnemonic == "pop":
                sp = state.get("@sp")
                dst_reg = reg(parts[0]) if parts else None
                if isinstance(sp, int):
                    value = state.get("@stack:%d" % sp)
                    if dst_reg is not None:
                        if value is None:
                            state.pop(dst_reg, None)
                        else:
                            state[dst_reg] = value
                    state["@sp"] = sp + 8
            elif mnemonic in ("add", "sub") and len(parts) == 2:
                dst_reg = reg(parts[0])
                amount = imm(parts[1])
                if dst_reg == "rsp" and isinstance(amount, int):
                    sp = state.get("@sp")
                    if isinstance(sp, int):
                        state["@sp"] = sp + (amount if mnemonic == "add" else -amount)
                elif (mnemonic == "add" and dst_reg is not None
                        and state.get(dst_reg) == "default_refcount"
                        and amount == 1 and state.get("@getattr")):
                    state[dst_reg] = "default_refcount_inc"
                elif dst_reg is not None:
                    state.pop(dst_reg, None)
            elif mnemonic == "inc" and parts:
                dm = mem(parts[0])
                if (dm is not None and state.get(dm[0]) == "default"
                        and dm[1] == 0 and state.get("@getattr")):
                    evidence["default_incref"] = True
            elif (mnemonic not in ("cmp", "test", "jmp", "jmpq", "ret", "retn")
                  and not mnemonic.startswith("j") and parts):
                dst_reg = reg(parts[0])
                if dst_reg is not None and dst_reg != "rsp":
                    state.pop(dst_reg, None)

            for target in succ[address]:
                previous = incoming.get(target)
                if previous is None:
                    incoming[target] = dict(state)
                    work.append(target)
                    updates += 1
                    continue
                joined = {
                    key: value for key, value in previous.items()
                    if key in state and state[key] == value
                }
                if joined != previous:
                    incoming[target] = joined
                    work.append(target)
                    updates += 1

        # A shared epilogue can merge success/default returns and make a
        # must-join drop RAX.  Prove staged default returns path-wise too.
        for stage in default_stage_sites:
            todo = list(succ.get(stage, ()))
            seen = set()
            while todo and len(seen) <= len(order):
                address = todo.pop()
                if address in seen or address not in by:
                    continue
                seen.add(address)
                insn = by[address]
                mnemonic = str(insn.mnemonic).lower()
                if mnemonic in ("ret", "retn"):
                    evidence["default_return"] = True
                    break
                if writes_rax(insn):
                    continue
                todo.extend(succ.get(address, ()))
            if evidence["default_return"]:
                break

        result = all(evidence.values())
        cache[va] = result
        proofs = getattr(self, "_getattr3_proof", None)
        if proofs is None:
            proofs = self._getattr3_proof = {}
        proofs[va] = {
            "proof": "Nuitka_BUILTIN_GETATTR_default" if result else None,
            "extent": tuple(int(x) for x in extent),
            "getattr_call_va": getattr_call_va,
            "default_return_vas": sorted(set(default_stage_sites)),
            "evidence": dict(evidence),
        }
        return result

    def _async_await_helper(self, va):
        """True only for Nuitka's ``ASYNC_AWAIT`` runtime helper.

        Looking only at ``r8d in {0,1,2}`` near a coroutine suspension is not a
        helper identity: memcpy/preserve/decref calls in the same native region
        inherit those small integers and were falsely rendered as additional
        awaits.  ``ASYNC_AWAIT`` itself contains the two fixed protocol errors
        for await-enter and await-exit.  Requiring RIP-referenced strings that
        mention respectively ``__aenter__``/``__aexit__`` *and* ``__await__``
        is a direct fingerprint of the public Nuitka runtime template.
        """
        cache = getattr(self, "_async_await_cache", None)
        if cache is None:
            cache = self._async_await_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False
        off = self.va_to_off(va)
        if off is None:
            return False
        seen_enter = False
        seen_exit = False
        try:
            blob, _has_exact_extent = self._bounded_helper_blob(
                va, off, 0x500)
            for index, insn in enumerate(self.md.disasm(blob, va)):
                if index >= 240:
                    break
                if insn.mnemonic.lower() != "lea":
                    continue
                mrip = re.search(
                    r"\[rip\s*([+-])\s*(0x[0-9a-f]+|\d+)\]",
                    insn.op_str.lower())
                if not mrip:
                    continue
                disp = int(mrip.group(2), 0)
                if mrip.group(1) == "-":
                    disp = -disp
                text = self._read_cstr(insn.address + insn.size + disp, 320)
                if not isinstance(text, str) or "__await__" not in text:
                    continue
                seen_enter |= "__aenter__" in text
                seen_exit |= "__aexit__" in text
                if seen_enter and seen_exit:
                    cache[va] = True
                    return True
        except Exception:
            return False
        return False

    def _anyall_kind(self, va):
        """BUILTIN_ANY and BUILTIN_ALL both reach PyObject_GetIter+PyObject_IsTrue.
        Distinguish by the loop-exit polarity AFTER the IsTrue result is tested:
        `any` breaks on the first TRUE element (`jg`/`ja` -> early handler),
        `all` breaks on the first FALSE element (`je`/`jle`/`jbe`)."""
        off = self.va_to_off(va)
        if off is None:
            return "any"
        seen_istrue = False
        for i, insn in enumerate(self.md.disasm(self.data[off:off + 0x160], va)):
            if i >= 70:
                break
            mn, o = insn.mnemonic, insn.op_str
            if mn == "call" and "qword ptr [rip" in o:
                try:
                    disp = int(o.split("+", 1)[1].split("]", 1)[0].strip(), 16)
                    if self.iat.get(insn.address + insn.size + disp) == "PyObject_IsTrue":
                        seen_istrue = True
                except Exception:
                    pass
            elif seen_istrue and mn in ("jg", "ja", "jne", "jnz"):
                return "any"
            elif seen_istrue and mn in ("jle", "jbe", "je", "jz"):
                return "all"
            if mn == "ret":
                break
        return "any"

    def _read_cstr(self, va, maxlen=16):
        """Read a NUL-terminated ASCII C-string at virtual address `va`."""
        off = self.va_to_off(va)
        if off is None:
            return None
        raw = self.data[off:off + maxlen + 1]
        end = raw.find(b"\x00")
        if end < 0:
            return None
        try:
            return raw[:end].decode("ascii")
        except Exception:
            return None

    def _builtin_name(self, va):
        """A `BUILTIN_<X>` helper resolves the builtin `X` lazily via
        `PyDict_GetItemString(builtins, "X")`, referencing the literal C-string
        "X" right before that call. Read that name (e.g. "open", "format",
        "print", "len") — a specific, robust fingerprint that distinguishes such
        a helper from a register-identical user call. Returns the name or None.
        Cached per helper VA."""
        if va in self._fmt_cache:
            return self._fmt_cache[va]
        name = None
        off = self.va_to_off(va)
        if off is not None:
            last_lea = None
            for i, insn in enumerate(self.md.disasm(self.data[off:off + 0x80], va)):
                if i >= 40 or insn.mnemonic == "ret":
                    break
                m, o = insn.mnemonic, insn.op_str
                if m == "lea" and o.startswith("rdx,") and "[rip + " in o:
                    try:
                        disp = int(o.split("[rip + ", 1)[1].split("]", 1)[0], 16)
                        last_lea = self._read_cstr(insn.address + insn.size + disp, 16)
                    except Exception:
                        last_lea = None
                elif m == "call" and "qword ptr [rip" in o:
                    try:
                        disp = int(o.split("+", 1)[1].split("]", 1)[0].strip(), 16)
                        nm = self.iat.get(insn.address + insn.size + disp)
                    except Exception:
                        nm = None
                    if (nm == "PyDict_GetItemString" and last_lea
                            and re.fullmatch(r"[a-z_][a-z0-9_]*", last_lea)):
                        name = last_lea
                        break
        self._fmt_cache[va] = name
        return name

    def _is_builtin_format(self, va):
        return self._builtin_name(va) == "format"

    # PyNumberMethods slot offsets (CPython 3.10 / Win64) -> binary operator.
    # Reached via tp_as_number (PyTypeObject + 0x60). nb_rshift sits at slot 0x60
    # too, but is disambiguated by base-register membership (a slot read's base
    # must already hold a tp_as_number pointer).
    _NB_SLOT_OPS = {0x00: "+", 0x08: "-", 0x10: "*", 0x18: "%", 0x28: "**",
                    0x58: "<<", 0x60: ">>", 0x68: "&", 0x70: "^", 0x78: "|",
                    0xe8: "//", 0xf0: "/", 0x110: "@"}
    # nb_inplace_* slot offsets (PyNumberMethods, CPython 3.10): `x += y` etc.
    # dispatch through these instead of the binary nb_* slots. The inplace helper
    # takes rcx = a POINTER to the LHS storage (lea) and rdx = the addend; the
    # _apply BINOPSLOT inplace path (rcx holds \x00PTR:) renders `x = x <op> y`.
    _NB_INPLACE_SLOTS = {0x98: "+", 0xa0: "-", 0xa8: "*", 0xb0: "%", 0xb8: "**",
                         0xc0: "<<", 0xc8: ">>", 0xd0: "&", 0xd8: "^", 0xe0: "|",
                         0xf8: "//", 0x100: "/", 0x118: "@"}
    _GP_REGS = frozenset(("rax", "rbx", "rcx", "rdx", "rsi", "rdi", "rbp",
                          "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15"))

    def _binop_slot(self, va):
        """A Nuitka BINARY_OPERATION_<op> helper dispatches through the operand
        type's `tp_as_number` slot (PyTypeObject + 0x60) then an nb_* slot, and
        CALLS it: `mov R,[type+0x60]; mov R,[R+nb_off]; ...; call R`. Detect that
        strict argument->type->tp_as_number->slot->call chain and return
        `(operator, [operand_reg, ...])`. The operand registers are the first
        objects whose ob_type (`[reg+8]`) is taken — `slot(left, right)` =
        `left <op> right`. Returns None if not a binop helper. Cached."""
        if va in self._binop_cache:
            return self._binop_cache[va]
        result = None
        off = self.va_to_off(va)
        if off is not None:
            type_regs = {}           # reg -> originating ABI object argument
            number_regs = {}         # reg -> originating ABI object argument
            slot_regs = {}           # reg -> (operator, originating argument)
            operand_seen = set()
            abi_args = ("rcx", "rdx", "r8", "r9")
            blob, _has_exact_extent = self._bounded_helper_blob(
                va, off, 0x300)
            for i, insn in enumerate(self.md.disasm(blob, va)):
                if i >= 200 or insn.mnemonic == "ret":
                    break
                m, o = insn.mnemonic, insn.op_str
                if m == "call":
                    # Require the exact register loaded from nb_* to be the
                    # indirect callee; a later unrelated register call is not
                    # evidence of an arithmetic helper.
                    callee = o.strip()
                    if callee in slot_regs:
                        op, _origin = slot_regs[callee]
                        operands = [r for r in abi_args if r in operand_seen]
                        result = (op, operands)
                        break
                    continue
                if m != "mov" or "," not in o:
                    if "," in o and m not in ("cmp", "test", "jmp", "call"):
                        dst = o.split(",", 1)[0].strip()
                        if dst in self._GP_REGS:
                            type_regs.pop(dst, None)
                            number_regs.pop(dst, None)
                            slot_regs.pop(dst, None)
                    continue
                dst, srcm = [x.strip() for x in o.split(",", 1)]
                if dst not in self._GP_REGS:
                    continue
                if srcm in self._GP_REGS:
                    old_type = type_regs.get(srcm)
                    old_number = number_regs.get(srcm)
                    old_slot = slot_regs.get(srcm)
                    type_regs.pop(dst, None)
                    number_regs.pop(dst, None)
                    slot_regs.pop(dst, None)
                    if old_type is not None:
                        type_regs[dst] = old_type
                    elif old_number is not None:
                        number_regs[dst] = old_number
                    elif old_slot is not None:
                        slot_regs[dst] = old_slot
                    continue
                mt = re.search(r"\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]", srcm)
                if not mt:
                    type_regs.pop(dst, None)
                    number_regs.pop(dst, None)
                    slot_regs.pop(dst, None)
                    continue
                base = mt.group(1)
                offv = int(mt.group(2), 0) if mt.group(2) else 0
                base_type = type_regs.get(base)
                base_number = number_regs.get(base)
                type_regs.pop(dst, None)
                number_regs.pop(dst, None)
                slot_regs.pop(dst, None)
                # nb_rshift is itself at 0x60.  The proven base provenance,
                # rather than the numeric offset, disambiguates it from
                # PyTypeObject.tp_as_number.
                if (base_number is not None
                        and (offv in self._NB_SLOT_OPS
                             or offv in self._NB_INPLACE_SLOTS)):
                    op = (self._NB_SLOT_OPS.get(offv)
                          or self._NB_INPLACE_SLOTS[offv])
                    slot_regs[dst] = (op, base_number)
                elif offv == 0x60 and base_type is not None:
                    number_regs[dst] = base_type
                elif offv == 8 and base in abi_args:
                    type_regs[dst] = base
                    operand_seen.add(base)
        if result is None:
            result = self._binop_slot_cfg(va)
        self._binop_cache[va] = result
        return result

    def _binop_slot_cfg(self, va, max_states=6000):
        """Path-sensitive fallback for branched nb_* dispatch helpers.

        Modern CPython/Nuitka helpers load both the direct and reflected numeric
        slots, then clear one register on an alternate branch before a guarded
        indirect call.  A linear scan sees that mutually exclusive clear and
        loses the slot provenance.  This bounded instruction-CFG interpreter
        follows both edges and accepts only an indirect call whose register is
        still proven to originate at ``arg->ob_type->tp_as_number->nb_*``.
        """
        off = self.va_to_off(va)
        if off is None:
            return None
        blob, _exact = self._bounded_helper_blob(va, off, 0x500)
        try:
            insns = list(self.md.disasm(blob, va))[:320]
        except Exception:
            return None
        if not insns:
            return None
        by = {int(i.address): i for i in insns}
        order = [int(i.address) for i in insns]
        nxt = {order[i]: order[i + 1] for i in range(len(order) - 1)}
        abi = ("rcx", "rdx", "r8", "r9")
        cond = {
            "je", "jne", "jz", "jnz", "jg", "jge", "jl", "jle",
            "ja", "jae", "jb", "jbe", "js", "jns", "jo", "jno",
            "jp", "jnp",
        }
        work = deque([(order[0], {reg: ("arg", reg) for reg in abi}, frozenset())])
        visited = set()
        steps = 0
        while work and steps < max_states:
            pc, state, operands_seen = work.popleft()
            steps += 1
            marker = (
                pc,
                tuple(sorted(state.items())),
                tuple(sorted(operands_seen)),
            )
            if marker in visited:
                continue
            visited.add(marker)
            insn = by.get(pc)
            if insn is None:
                continue
            m, o = insn.mnemonic, insn.op_str
            out_states = [(dict(state), set(operands_seen))]

            if m == "call":
                callee = o.strip()
                provenance = state.get(callee)
                if provenance and provenance[0] == "slot":
                    passed = [state.get(reg) for reg in abi[:2]]
                    if all(value and value[0] == "arg" for value in passed) and \
                            passed[0] != passed[1]:
                        return provenance[1], [value[1] for value in passed]
                # Direct support calls can clobber volatile registers, but the
                # numeric slot is normally parked in rbx/rdi/rsi and survives.
                updated = dict(state)
                for reg in ("rax", "rcx", "rdx", "r8", "r9", "r10", "r11"):
                    updated.pop(reg, None)
                out_states = [(updated, set(operands_seen))]
            elif m == "mov" and "," in o:
                dst, src = [x.strip() for x in o.split(",", 1)]
                if dst in self._GP_REGS:
                    updated = dict(state)
                    updated.pop(dst, None)
                    seen_operands = set(operands_seen)
                    imported_type = self.iat.get(rip_target(insn)) if 'rip' in src else None
                    if imported_type and imported_type.startswith('Py') and imported_type.endswith('_Type'):
                        updated[dst] = ("type", imported_type)
                    elif src in state:
                        updated[dst] = state[src]
                    else:
                        mm = re.search(
                            r"\[([a-z0-9]+)(?:\s*\+\s*"
                            r"(0x[0-9a-f]+|\d+))?\]", src)
                        if mm:
                            base = mm.group(1)
                            disp = int(mm.group(2), 0) if mm.group(2) else 0
                            base_provenance = state.get(base)
                            if disp == 8 and base_provenance and base_provenance[0] == "arg":
                                updated[dst] = ("type", base_provenance[1])
                                seen_operands.add(base_provenance[1])
                            elif (disp == 0x60 and base_provenance
                                  and base_provenance[0] == "type"):
                                updated[dst] = (
                                    "number", base_provenance[1])
                            elif (base_provenance
                                  and base_provenance[0] == "number"
                                  and (disp in self._NB_SLOT_OPS
                                       or disp in self._NB_INPLACE_SLOTS)):
                                op = (self._NB_SLOT_OPS.get(disp)
                                      or self._NB_INPLACE_SLOTS[disp])
                                updated[dst] = (
                                    "slot", op, base_provenance[1])
                    out_states = [(updated, seen_operands)]
            elif m.startswith("cmov") and "," in o:
                # Conditional moves represent two feasible states.
                dst, src = [x.strip() for x in o.split(",", 1)]
                if dst in self._GP_REGS:
                    keep = (dict(state), set(operands_seen))
                    updated = dict(state)
                    updated.pop(dst, None)
                    if src in state:
                        updated[dst] = state[src]
                    out_states = [
                        keep, (updated, set(operands_seen))]
            elif "," in o:
                dst = o.split(",", 1)[0].strip()
                if dst in self._GP_REGS and m not in ("cmp", "test"):
                    updated = dict(state)
                    updated.pop(dst, None)
                    out_states = [(updated, set(operands_seen))]

            if m == "ret":
                successors = ()
            elif m == "jmp" and o.startswith("0x"):
                successors = (int(o, 16),)
            elif m in cond and o.startswith("0x"):
                successors = (nxt.get(pc), int(o, 16))
            else:
                successors = (nxt.get(pc),)

            for updated, seen_operands in out_states:
                for successor in successors:
                    if successor in by:
                        work.append((
                            successor, updated,
                            frozenset(seen_operands)))
        return None

    def _str_concat_helper(self, va):
        """Nuitka's str-specialized binary-add fast path
        (BINARY_OPERATION_ADD_OBJECT_OBJECT / *_UNICODE_*): instead of the
        tp_as_number->nb_add slot path (which `_binop_slot` deliberately skips as
        offset-0x00 collision-prone), it loads `PyUnicode_Type` and ob_type-checks
        an operand against it, then tail-calls the inlined unicode concat. A helper
        that proves an operand is `str` and returns a value can ONLY be `+`
        (concat): str supports no other binary operator in this shape (`%` goes
        through PyUnicode_Format, `*` carries an int operand). Operands are the
        first two integer-arg registers in CPython x64 ABI order, so the result
        flows into the following call's arg register. Returns `[left, right]` or
        None. Universal (PyUnicode_Type ob_type compare + fixed ABI). Cached."""
        if va in self._strcat_cache:
            return self._strcat_cache[va]
        result = None
        off = self.va_to_off(va)
        if off is not None:
            uni_reg = None        # reg currently holding &PyUnicode_Type
            checked = None        # operand reg whose ob_type was compared to str
            for i, insn in enumerate(self.md.disasm(self.data[off:off + 0x80], va)):
                if i >= 16 or insn.mnemonic == "ret":
                    break
                m, o = insn.mnemonic, insn.op_str
                if m == "mov" and "[rip + " in o:
                    try:
                        disp = int(o.split("[rip + ", 1)[1].split("]", 1)[0], 16)
                        tva = insn.address + insn.size + disp
                    except Exception:
                        continue
                    if self.iat.get(tva) == "PyUnicode_Type":
                        dst = o.split(",", 1)[0].strip()
                        if dst in self._GP_REGS:
                            uni_reg = dst
                    continue
                if m == "cmp" and uni_reg is not None:
                    # `cmp [operand + 8], uni_reg` OR `cmp uni_reg, [operand + 8]`
                    # ( == Py_TYPE(operand) is PyUnicode_Type ). Accept either order
                    # and decimal/hex offset 8.
                    mt = (re.match(r"^(?:qword ptr )?\[([a-z0-9]+)\s*\+\s*0?x?0*8\],\s*%s$"
                                   % re.escape(uni_reg), o)
                          or re.match(r"^%s,\s*(?:qword ptr )?\[([a-z0-9]+)\s*\+\s*0?x?0*8\]$"
                                      % re.escape(uni_reg), o))
                    if mt and mt.group(1) in ("rcx", "rdx", "r8"):
                        checked = mt.group(1)
                        break
        if checked is not None:
            _seq = ("rcx", "rdx", "r8", "r9")
            _li = _seq.index(checked)
            if _li + 1 < len(_seq):
                result = [checked, _seq[_li + 1]]
        self._strcat_cache[va] = result
        return result

    def _object_size_slot_strict(self, va):
        """Prove Nuitka's API-free ``len(object)``/``PyObject_Size`` helper.

        On Win64 the helper receives the object directly in ``rcx`` and tries
        both length protocols before raising the usual unsized-object error::

            type = Py_TYPE(rcx)                 # [rcx + 0x08]
            sq = type->tp_as_sequence           # [type + 0x68]
            if sq && sq->sq_length: tail-call sq_length
            mp = type->tp_as_mapping            # [type + 0x70]
            if mp && mp->mp_length: tail-call mp_length
            PyErr_*(); return -1

        ``sq_length`` and ``mp_length`` are both slot zero, so flat offset
        matching would be unsafe.  Track the complete register provenance for
        both independent chains, require a tested tail-dispatch for each, and
        require the error/-1 arm.  No helper VA, builtin-name literal, module,
        qualname or application string participates in the proof.
        """
        cache = self._object_size_slot_cache
        if va in cache:
            return cache[va]
        cache[va] = False

        off = self.va_to_off(va)
        if off is None:
            return False
        extent = self._helper_extent(va)
        # A direct target inside somebody else's exact pdata extent is not a
        # standalone helper entry.  Leaf helpers may legitimately lack pdata.
        if extent is not None and int(extent[0]) != int(va):
            return False
        blob, _has_exact_extent = self._bounded_helper_blob(va, off, 0x100)

        token = {}                  # register -> type/seq/map/*_length
        tested = set()              # proven non-null length-function tokens
        dispatched = set()          # length tokens reached by tail jmp
        saw_error = False
        saw_negative_one = False
        saw_ret = False
        invalid_call = False
        count = 0
        mem_re = re.compile(
            r"^(?:qword ptr )?\[([a-z0-9]+)"
            r"(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]$")

        for insn in self.md.disasm(blob, va):
            count += 1
            if count > 64:
                break
            mnemonic = insn.mnemonic.lower()
            operand = insn.op_str.lower()
            parts = [part.strip() for part in operand.split(",", 1)]

            if mnemonic in ("int3", "ud2"):
                break
            if mnemonic == "mov" and len(parts) == 2:
                dst, src = parts
                if (dst in ("rax", "eax")
                        and src in ("-1", "0xffffffff", "0xffffffffffffffff")):
                    saw_negative_one = True
                if dst in self._GP_REGS:
                    value = None
                    match = mem_re.fullmatch(src)
                    if match is not None:
                        base = match.group(1)
                        displacement = (int(match.group(2), 0)
                                        if match.group(2) else 0)
                        base_token = token.get(base)
                        if base == "rcx" and displacement == 8:
                            value = "type"
                        elif base_token == "type" and displacement == 0x68:
                            value = "seq"
                        elif base_token == "type" and displacement == 0x70:
                            value = "map"
                        elif base_token == "seq" and displacement == 0:
                            value = "seq_length"
                        elif base_token == "map" and displacement == 0:
                            value = "map_length"
                    elif src in self._GP_REGS:
                        value = token.get(src)
                    # Must-provenance: an unknown write kills the older token.
                    token.pop(dst, None)
                    if value is not None:
                        token[dst] = value
            elif (mnemonic == "test" and len(parts) == 2
                  and parts[0] == parts[1]
                  and token.get(parts[0]) in ("seq_length", "map_length")):
                tested.add(token[parts[0]])
            elif mnemonic == "jmp" and operand in self._GP_REGS:
                value = token.get(operand)
                if value in tested:
                    dispatched.add(value)
            elif mnemonic == "call":
                api = None
                match = re.search(
                    r"\[rip\s*\+\s*(0x[0-9a-f]+|\d+)\]", operand)
                if match is not None:
                    iat_va = (insn.address + insn.size
                              + int(match.group(1), 0))
                    api = self.iat.get(iat_va)
                if api in ("PyErr_Format", "PyErr_SetString"):
                    saw_error = True
                else:
                    # The two value paths are tail jumps, not calls.  Any other
                    # call before the complete proof belongs to another helper.
                    invalid_call = True
            elif (parts and parts[0] in self._GP_REGS
                  and mnemonic not in ("cmp", "test", "bt")
                  and not mnemonic.startswith("j")):
                token.pop(parts[0], None)

            if mnemonic == "ret":
                saw_ret = True
                break

        result = bool(
            16 <= count <= 64
            and dispatched == {"seq_length", "map_length"}
            and saw_error and saw_negative_one and saw_ret
            and not invalid_call)
        cache[va] = result
        return result

    def _is_subscript_helper(self, va, maxi=14):
        """The Nuitka LOOKUP_SUBSCRIPT helper (`obj[key]`, optimised: it inlines
        the protocol instead of calling PyObject_GetItem so the API-count
        heuristic misses it). Its body's FIRST action is the subscript-first
        chain on the SOURCE operand (rdx = arg1 after tstate=rcx):
            mov R,[rdx + 8]    ; Py_TYPE(source)
            mov R2,[R + 0x70]  ; type->tp_as_mapping
            mov R3,[R2 + 0x08] ; tp_as_mapping->mp_subscript
        loaded EARLY and BEFORE any call. Method/attribute helpers do
        _PyType_Lookup / tp_getattro (a CALL) first, so the no-call-before gate
        rejects them — this is what keeps it from the mass mis-fire that a deep
        scan of the shared mp_subscript fallback path causes. Renders via the
        standard SUBSCRIPT path (source=rdx, key=r8). CPython x64 ABI offsets +
        the shared Nuitka C template (subscripts.h) — universal. Cached."""
        if va in self._subhelper_cache:
            return self._subhelper_cache[va]
        result = False
        off = self.va_to_off(va)
        if off is not None:
            asmap = set()
            ob_reg = {}
            for i, insn in enumerate(self.md.disasm(self.data[off:off + 0x100], va)):
                if i >= maxi or insn.mnemonic == "ret":
                    break
                m, o = insn.mnemonic, insn.op_str
                if m == "call":
                    break                       # a call before the chain -> not subscript-first
                if m != "mov" or "," not in o:
                    continue
                dst, srcm = [x.strip() for x in o.split(",", 1)]
                if dst not in self._GP_REGS:
                    continue
                mt = re.search(r"\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]", srcm)
                if not mt:
                    asmap.discard(dst); ob_reg.pop(dst, None)
                    continue
                base = mt.group(1)
                offv = int(mt.group(2), 0) if mt.group(2) else 0
                if offv == 8 and base == "rdx":
                    ob_reg[dst] = base                       # Py_TYPE(source=rdx)
                elif offv == 0x70 and base in ob_reg:        # PyTypeObject.tp_as_mapping
                    asmap.add(dst)
                elif offv == 0x08 and base in asmap:         # PyMappingMethods.mp_subscript
                    result = True                            # mp_subscript loaded early
                    break
                else:
                    asmap.discard(dst); ob_reg.pop(dst, None)
        self._subhelper_cache[va] = result
        return result

    def _is_subscript_store_helper(self, va, maxi=14):
        """Nuitka SET_SUBSCRIPT (`obj[key] = value`) inlines the write protocol
        through ``tp_as_mapping->mp_ass_subscript`` (offset 0x10), one slot after
        the read ``mp_subscript`` (0x08) used by LOOKUP_SUBSCRIPT. Same early
        no-call-before gate and source operand (rdx after tstate=rcx) as
        ``_is_subscript_helper`` — only the mapping slot offset differs. ABI at
        the call site: rdx=target, r8=key, r9=value. Cached."""
        if va in self._substore_cache:
            return self._substore_cache[va]
        result = False
        off = self.va_to_off(va)
        if off is not None:
            asmap = set()
            ob_reg = {}
            for i, insn in enumerate(self.md.disasm(self.data[off:off + 0x100], va)):
                if i >= maxi or insn.mnemonic == "ret":
                    break
                m, o = insn.mnemonic, insn.op_str
                if m == "call":
                    break                       # a call before the chain -> not store-first
                if m != "mov" or "," not in o:
                    continue
                dst, srcm = [x.strip() for x in o.split(",", 1)]
                if dst not in self._GP_REGS:
                    continue
                mt = re.search(r"\[([a-z0-9]+)(?:\s*\+\s*(0x[0-9a-f]+|\d+))?\]", srcm)
                if not mt:
                    asmap.discard(dst); ob_reg.pop(dst, None)
                    continue
                base = mt.group(1)
                offv = int(mt.group(2), 0) if mt.group(2) else 0
                if offv == 8 and base == "rdx":
                    ob_reg[dst] = base                       # Py_TYPE(target=rdx)
                elif offv == 0x70 and base in ob_reg:        # PyTypeObject.tp_as_mapping
                    asmap.add(dst)
                elif offv == 0x10 and base in asmap:         # PyMappingMethods.mp_ass_subscript
                    result = True                            # mp_ass_subscript loaded early
                    break
                else:
                    asmap.discard(dst); ob_reg.pop(dst, None)
        self._substore_cache[va] = result
        return result

    def _is_dict_subscript_helper(self, va, maxi=60):
        """Recognise Nuitka's exact-dict item helpers as ``source[key]``.

        Nuitka 4.x emits ``DICT_GET_ITEM*`` for proven dictionaries instead of
        the generic ``LOOKUP_SUBSCRIPT`` mapping-slot chain.  The helper preserves
        ``rdx`` (dict) and ``r8`` (key), computes/caches the key hash via
        ``Py_TYPE(key)->tp_hash`` (slot 0x78), and invokes the internal dict lookup
        with an output pointer in ``r9``.  It never dereferences the dict's type
        before that lookup.  This fingerprint comes directly from
        HelpersDictionaries.c and is distinct from attribute/method helpers.
        """
        cache = getattr(self, "_dict_subhelper_cache", None)
        if cache is None:
            cache = self._dict_subhelper_cache = {}
        if va in cache:
            return cache[va]

        result = False
        off = self.va_to_off(va)
        if off is not None:
            dict_alias = {"rdx"}
            key_alias = {"r8"}
            key_type_regs = set()
            saw_key_type = False
            saw_hash = False
            saw_outptr = False
            source_deref = False
            call_count = 0
            try:
                seq = self.md.disasm(self.data[off:off + 0x180], va)
                for index, insn in enumerate(seq):
                    if index >= maxi or insn.mnemonic == "ret":
                        break
                    m, o = insn.mnemonic, insn.op_str
                    if m == "mov" and "," in o:
                        dst, src = [x.strip() for x in o.split(",", 1)]
                        if src in dict_alias and dst in self._GP_REGS:
                            dict_alias.add(dst)
                        if src in key_alias and dst in self._GP_REGS:
                            key_alias.add(dst)
                        mm = re.fullmatch(
                            r"qword ptr \[([a-z0-9]+) \+ "
                            r"(0x[0-9a-f]+|\d+)\]", src)
                        if mm:
                            base = mm.group(1)
                            disp = int(mm.group(2), 0)
                            if base in key_alias and disp == 8:
                                key_type_regs.add(dst)
                                saw_key_type = True
                            elif base in key_type_regs and disp == 0x78:
                                saw_hash = True
                            elif base in key_alias and disp in (0x18, 0x20):
                                # Cached unicode hash field (layout varies by
                                # supported CPython minor version).
                                saw_hash = True
                            if base in dict_alias:
                                source_deref = True
                    elif m == "lea" and o.startswith("r9,") and "[rsp" in o:
                        saw_outptr = True
                    elif m == "call":
                        call_count += 1
            except Exception:
                result = False
            else:
                result = bool(
                    len(dict_alias) >= 2
                    and len(key_alias) >= 2
                    and saw_key_type
                    and saw_hash
                    and saw_outptr
                    and not source_deref
                    and call_count >= 1
                )

        cache[va] = result
        return result

    def _is_module_dict_store(self, hva):
        """The module-global store UPDATE_STRING_DICT0(moduledict, name, value)
        loads moduledict_<mod> from a FIXED rip slot in its prologue, then does a
        single PyDict_SetItem. That fixed-rip-slot load distinguishes it from a
        generic `dict[k]=v` helper (which gets its dict from an argument).
        Universal: Nuitka emits this for every module-level binding, all versions,
        free & commercial (CTypeModuleDictVariables / CodeTemplatesVariables)."""
        off = self.va_to_off(hva)
        if off is None:
            return False
        try:
            seq = []
            for i, I in enumerate(self.md.disasm(self.data[off:off + 0x40], hva)):
                if i >= 8:
                    break
                seq.append(I.mnemonic + " " + I.op_str)
        except Exception:
            return False
        t = " | ".join(seq)
        return bool(re.search(r"mov r(di|cx), qword ptr \[rip \+ 0x[0-9a-f]+\]", t))

    def _is_module_dict_store_wrapper(self, va):
        """Recognise local UPDATE_STRING_DICT0 wrappers with split cold paths.

        Some MSVC/Nuitka builds wrap the module store in a native helper whose
        primary unwind fragment performs a fast dictionary-slot update and whose
        cold fragment calls ``PyDict_SetItem``.  ``collect_apis`` deliberately
        respects the primary extent and therefore cannot see that cold call.
        Prove the wrapper directly from ABI dataflow instead: RDX (name) and R8
        (value) are preserved, the module dict comes from a fixed writable RIP
        slot, and those three exact values reach PyDict_SetItem.
        """
        cache = getattr(self, '_modstore_wrapper_cache', None)
        if cache is None:
            cache = self._modstore_wrapper_cache = {}
        if va in cache:
            return cache[va]
        result = False
        off = self.va_to_off(va)
        if off is None:
            cache[va] = False
            return False

        volatile = {'rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11'}

        def _slot_is_writable(slot_va):
            try:
                rva = int(slot_va) - int(self.base)
                for sec in self.pe.sections:
                    lo = int(sec.VirtualAddress)
                    span = max(int(sec.Misc_VirtualSize or 0),
                               int(sec.SizeOfRawData or 0))
                    if lo <= rva < lo + span:
                        chars = int(sec.Characteristics or 0)
                        return bool((chars & 0x80000000)
                                    and not (chars & 0x20000000))
            except Exception:
                pass
            return False

        def _rip_target(insn):
            match = re.search(
                r'\[rip\s*([+-])\s*0x([0-9a-f]+)\]',
                str(insn.op_str), re.I)
            if not match:
                return None
            displacement = int(match.group(2), 16)
            if match.group(1) == '-':
                displacement = -displacement
            return int(insn.address) + int(insn.size) + displacement

        def _direct_target(insn):
            operand = str(insn.op_str).strip().lower()
            try:
                return int(operand, 0) if operand.startswith('0x') else None
            except ValueError:
                return None

        try:
            # This window intentionally includes split cold fragments which are
            # not always covered by the primary unwind extent.  Reachability
            # from the real entry prevents bytes from a neighbouring helper
            # from participating in the proof.
            instructions = list(self.md.disasm(
                self.data[off:off + 0x180], va))[:120]
            if not instructions:
                raise ValueError('empty helper')
            by_address = {int(insn.address): insn for insn in instructions}
            order = [int(insn.address) for insn in instructions]
            following = {
                order[index]: order[index + 1]
                for index in range(len(order) - 1)
            }

            # Path-sensitive worklist.  The former linear scan happened to
            # work only when the cold block preceded the fast-path restores;
            # when it followed them, sibling-path writes erased the preserved
            # RDX/R8 aliases before PyDict_SetItem was visited.
            work = [(order[0], frozenset(),
                     frozenset(('rdx',)), frozenset(('r8',)))]
            seen = set()
            steps = 0
            while work and steps < 4096 and not result:
                address, roots_f, names_f, values_f = work.pop()
                state_key = (address, roots_f, names_f, values_f)
                if state_key in seen:
                    continue
                seen.add(state_key)
                steps += 1
                insn = by_address.get(address)
                if insn is None:
                    continue
                roots = set(roots_f)
                names = set(names_f)
                values = set(values_f)
                mnemonic = str(insn.mnemonic).lower()
                operand = str(insn.op_str).strip().lower()

                if mnemonic in ('call', 'callq'):
                    iat_target = _rip_target(insn)
                    symbol = (self.iat.get(iat_target)
                              if iat_target is not None else None)
                    if (symbol == 'PyDict_SetItem'
                            and 'rcx' in roots
                            and 'rdx' in names
                            and 'r8' in values):
                        result = True
                        break
                    roots.difference_update(volatile)
                    names.difference_update(volatile)
                    values.difference_update(volatile)
                elif mnemonic == 'mov' and ',' in operand:
                    destination, source = [
                        part.strip() for part in operand.split(',', 1)]
                    if destination in self._GP_REGS:
                        # Read all source tags before killing destination so a
                        # self-copy cannot accidentally destroy provenance.
                        source_is_root = source in roots
                        source_is_name = source in names
                        source_is_value = source in values
                        roots.discard(destination)
                        names.discard(destination)
                        values.discard(destination)
                        if source in self._GP_REGS:
                            if source_is_root:
                                roots.add(destination)
                            if source_is_name:
                                names.add(destination)
                            if source_is_value:
                                values.add(destination)
                        elif '[rip' in source:
                            slot = _rip_target(insn)
                            if (slot is not None and slot not in self.iat
                                    and _slot_is_writable(slot)):
                                roots.add(destination)
                elif (',' in operand
                      and (mnemonic in ('lea', 'pop', 'xor', 'add', 'sub',
                                       'and', 'or', 'imul', 'movzx', 'movsxd')
                           or mnemonic.startswith('cmov'))):
                    # Conservative must-provenance: an unmodelled register
                    # write invalidates the destination on that path.
                    destination = operand.split(',', 1)[0].strip()
                    if destination in self._GP_REGS:
                        roots.discard(destination)
                        names.discard(destination)
                        values.discard(destination)

                successors = []
                next_address = following.get(address)
                if mnemonic in ('ret', 'retn'):
                    successors = []
                elif mnemonic in ('jmp', 'jmpq'):
                    target = _direct_target(insn)
                    if target in by_address:
                        successors = [target]
                elif mnemonic.startswith('j'):
                    target = _direct_target(insn)
                    if target in by_address:
                        successors.append(target)
                    if next_address is not None:
                        successors.append(next_address)
                elif next_address is not None:
                    successors = [next_address]

                new_state = (frozenset(roots), frozenset(names),
                             frozenset(values))
                for successor in dict.fromkeys(successors):
                    work.append((successor,) + new_state)
        except Exception:
            result = False
        cache[va] = result
        return result

    def _modstore_helper(self, va):
        apis = self.collect_apis(va)
        return ((apis.get("PyDict_SetItem", 9) == 0 and len(apis) <= 2
                 and apis.get("_PyDict_NewPresized", 9) > 1
                 and apis.get("PyErr_Format", 9) > 1
                 and self._is_module_dict_store(va))
                or self._is_module_dict_store_wrapper(va))

    def _import_name_helper(self, va):
        """IMPORT_NAME_FROM_MODULE(module, name) -> the bound `name`. Distinguished
        from a plain LOOKUP_ATTRIBUTE by PyModule_GetFilenameObject (its
        module-not-found error path). Universal Nuitka import codegen (>=3.5)."""
        apis = self.collect_apis(va)
        return (apis.get("PyObject_GetAttr", 9) <= 1
                and apis.get("PyModule_GetFilenameObject", 9) <= 1)

    def _import_hard_helper(self, va):
        """Nuitka IMPORT_HARD_<NAME>() getter for a stdlib `import X` compiled as a
        HARD import: X is fetched once (PyImport_ImportModule) and cached, with NO
        Python-level __import__ call — so the `__import__`-based import walk never
        sees it (`import os`/`import ctypes`/`import sys` vanish). Fingerprint
        (universal across Nuitka 3.x, ImportCodes.getImportModuleHardCode):
            mov rax,[rip cache] ; test rax,rax ; jne ret   (return cached)
            lea rcx,[rip -> cstr]                            (the dotted module name)
            call [IAT=PyImport_ImportModule]                 (the ONLY API it reaches)
            mov [rip cache], rax                             (cache the result)
        Returns the dotted module name, else None. The single-PyImport_ImportModule
        + C-string-name + cache-store triple is unique to these getters; a normal
        global assignment can never satisfy it, so emitting `import <name>` off this
        signal never fabricates. Cached."""
        if va in self._imphard_cache:
            return self._imphard_cache[va]
        name = None
        apis = self.collect_apis(va)
        if "PyImport_ImportModule" in apis and len(apis) <= 1:
            off = self.va_to_off(va)
            if off is not None:
                lea_name = None
                ncall = 0
                cache_store = False
                for i, I in enumerate(self.md.disasm(self.data[off:off + 0x40], va)):
                    if i >= 16 or I.mnemonic == "ret":
                        break
                    m, o = I.mnemonic, I.op_str
                    if m == "lea" and o.startswith("rcx,") and "[rip + " in o:
                        try:
                            d = int(o.split("[rip + ", 1)[1].split("]", 1)[0], 16)
                            lea_name = self._read_cstr(I.address + I.size + d, 64)
                        except Exception:
                            lea_name = None
                    elif m == "call" and "[rip" in o:
                        ncall += 1
                        try:
                            d = int(o.split("[rip + ", 1)[1].split("]", 1)[0], 16)
                            tgt = I.address + I.size + d
                        except Exception:
                            tgt = None
                        if tgt is None or self.iat.get(tgt) != "PyImport_ImportModule":
                            lea_name = None
                            break
                    elif (m == "mov" and o.startswith("qword ptr [rip")
                            and o.rstrip().endswith(", rax")):
                        cache_store = True
                if (ncall == 1 and cache_store and lea_name
                        and re.fullmatch(r"[A-Za-z_]\w*(\.[A-Za-z_]\w*)*", lea_name)):
                    name = lea_name
        self._imphard_cache[va] = name
        return name

    _CONTAINER_TYPE_KIND = {
        "PyList_Type": "BUILD_LIST", "PyTuple_Type": "BUILD_TUPLE",
        "PyDict_Type": "BUILD_MAP", "PySet_Type": "BUILD_SET",
        "PyFrozenSet_Type": "BUILD_FROZENSET",
    }

    def _container_builder(self, va):
        """Detect a Nuitka container-construction leaf (PyList_New / PyTuple_New /
        PySet_New ...). The leaf GC-allocates an object then stores its ob_type
        from a STATIC CPython `*_Type` IAT import (`reg <- [rip -> PyList_Type]`;
        `mov [obj+8], reg`). The type identifies the container kind. Returns the
        BUILD_* kind, or None. Universal: keyed purely on the
        GC_Malloc + ob_type-from-Type-IAT shape — no VA / name hardcoding."""
        cache = getattr(self, "_ctbuild_cache", None)
        if cache is None:
            cache = self._ctbuild_cache = {}
        if va in cache:
            return cache[va]
        res = None
        off = self.va_to_off(va)
        if off is None:
            cache[va] = None
            return None
        try:
            type_regs = {}
            gc_seen = False
            for I in self.md.disasm(self.data[off:off + 0x140], va):
                m, o = I.mnemonic, I.op_str
                if m == "mov":
                    mm = re.match(r"^(\w+),\s*qword ptr \[rip \+ (0x[0-9a-f]+)\]$", o)
                    if mm:
                        tnm = self.iat.get(I.address + I.size + int(mm.group(2), 16))
                        if isinstance(tnm, str) and tnm.endswith("_Type"):
                            type_regs[mm.group(1)] = tnm
                        else:
                            type_regs.pop(mm.group(1), None)
                        continue
                    sm = re.match(r"^(?:qword ptr )?\[(\w+)\s*\+\s*8\],\s*(\w+)$", o)
                    if sm and gc_seen and sm.group(2) in type_regs:
                        res = self._CONTAINER_TYPE_KIND.get(type_regs[sm.group(2)])
                        if res:
                            break
                    # a plain `mov reg, X` clobbers reg's type tag
                    d0 = o.split(",", 1)[0].strip()
                    if d0 in type_regs and not (sm and d0 == sm.group(1)):
                        type_regs.pop(d0, None)
                elif m == "call" and "rip" in o:
                    try:
                        d = int(o.split("[rip + ", 1)[1].split("]", 1)[0], 16)
                        if self.iat.get(I.address + I.size + d) in (
                                "_PyObject_GC_Malloc", "_PyObject_GC_New",
                                "_PyObject_GC_NewVar", "PyObject_Malloc"):
                            gc_seen = True
                    except Exception:
                        pass
        except Exception:
            res = None
        cache[va] = res
        return res

    def _deepcopy_constant_helper(self, va):
        """Recognise DEEP_COPY_DICT/DICT_COPY-style constant materialisers.

        Nuitka emits these for mutable literals whose template lives in
        ``mod_consts``.  On CPython 3.12 the optimized exact-dict copy reads
        ``ma_used``/``ma_keys``/``ma_values`` at 0x10/0x20/0x28 from the second
        Win64 argument, has a dedicated empty-dict early return, and then copies
        entries.  The proof deliberately describes the generated helper rather
        than a call-site name, so stripped/free/commercial builds behave alike.
        """
        cache = getattr(self, "_deepcopy_const_cache", None)
        if cache is None:
            cache = self._deepcopy_const_cache = {}
        if va in cache:
            return cache[va]
        result = False
        off = self.va_to_off(va)
        if off is not None:
            try:
                seq = list(self.md.disasm(self.data[off:off + 0x700], va))
            except Exception:
                seq = []
            seq = seq[:260]
            aliases = {"rdx"}
            for insn in seq[:24]:
                if insn.mnemonic == "mov" and "," in insn.op_str:
                    dst, src = [x.strip() for x in insn.op_str.split(",", 1)]
                    if src in aliases and dst in self._GP_REGS:
                        aliases.add(dst)
            fields = set()
            used_to_r8 = False
            zero_test = False
            early_ret = False
            calls = 0
            sequence_size_regs = set()
            sequence_cursor_regs = set()
            sequence_load = False
            sequence_store = False
            sequence_step = False
            sequence_countdown = False
            sequence_backedge = False
            for index, insn in enumerate(seq):
                m, o = insn.mnemonic, insn.op_str
                if m == "mov" and "," in o:
                    dst, src = [x.strip() for x in o.split(",", 1)]
                    mm = re.fullmatch(
                        r"qword ptr \[([a-z0-9]+) \+ "
                        r"(0x[0-9a-f]+|\d+)\]", src)
                    if mm and mm.group(1) in aliases:
                        disp = int(mm.group(2), 0)
                        fields.add(disp)
                        if (index < 20 and mm.group(1) == "rdx"
                                and disp == 0x10 and dst == "r8"):
                            used_to_r8 = True
                        if disp == 0x10 and dst in self._GP_REGS:
                            sequence_size_regs.add(dst)
                    seq_read = re.fullmatch(
                        r"qword ptr \[([a-z0-9]+) \+ ([a-z0-9]+)\]", src)
                    if seq_read and seq_read.group(1) in sequence_cursor_regs:
                        sequence_load = True
                    seq_write = re.fullmatch(
                        r"qword ptr \[([a-z0-9]+)\]", dst)
                    if seq_write and seq_write.group(1) in \
                            sequence_cursor_regs and src == 'rax':
                        sequence_store = True
                elif m == 'lea' and ',' in o:
                    dst, src = [x.strip() for x in o.split(',', 1)]
                    if src == '[rax + 0x18]' and dst in self._GP_REGS:
                        sequence_cursor_regs.add(dst)
                    step = re.fullmatch(
                        r'\[([a-z0-9]+) \+ 8\]', src)
                    if step and step.group(1) in sequence_cursor_regs and \
                            dst == step.group(1):
                        sequence_step = True
                elif m == "test" and o == "r8, r8" and index < 30:
                    zero_test = True
                elif m == "call":
                    calls += 1
                elif m == 'sub' and ',' in o:
                    dst, src = [x.strip() for x in o.split(',', 1)]
                    if dst in sequence_size_regs and src == '1':
                        sequence_countdown = True
                elif m in ('jne', 'jnz') and o.startswith('0x'):
                    try:
                        sequence_backedge |= int(o, 16) < insn.address
                    except ValueError:
                        pass
                elif m == "ret" and index < 40:
                    early_ret = True
                if m == "int3" and index > 30:
                    break
            dict_copy = bool(
                used_to_r8 and zero_test and early_ret
                and {0x10, 0x20, 0x28}.issubset(fields)
                and calls >= 3
            )
            sequence_copy = bool(
                sequence_size_regs and sequence_cursor_regs and
                sequence_load and sequence_store and sequence_step and
                sequence_countdown and sequence_backedge and calls >= 2)
            result = dict_copy or sequence_copy
        cache[va] = result
        return result

    def _kwcall_slot_strict(self, va):
        """Recognise CPython 3.11+ Nuitka keyword-vectorcall helpers.

        Win64 ABI: rdx=callable, r8=argument vector, r9=keyword-name tuple.
        The helper reads the tuple size at r9+0x10, checks the callable type's
        vectorcall flag at tp_flags+0xa8, obtains tp_vectorcall_offset at +0x38,
        and invokes the resolved slot.  Requiring the complete chain avoids
        confusing ordinary CALL/METHOD helpers with keyword calls.
        """
        if not getattr(self, "_is_unstable", False):
            return False
        off = self.va_to_off(va)
        if off is None:
            return False
        try:
            seq = list(self.md.disasm(self.data[off:off + 0x500], va))[:180]
        except Exception:
            return False
        saw_kwlen = saw_save_r8 = saw_save_r9 = False
        saw_type = saw_flags = saw_offset = saw_indirect = False
        vector_regs = set()
        for insn in seq:
            m, o = insn.mnemonic, insn.op_str
            if m == "mov" and "," in o:
                dst, src = [x.strip() for x in o.split(",", 1)]
                if src == "qword ptr [r9 + 0x10]":
                    saw_kwlen = True
                if src == "r8" and dst in self._GP_REGS:
                    saw_save_r8 = True
                if src == "r9" and dst in self._GP_REGS:
                    saw_save_r9 = True
                if src == "qword ptr [rdx + 8]" and dst == "r8":
                    saw_type = True
                if src == "qword ptr [r8 + 0x38]" and dst in self._GP_REGS:
                    vector_regs.add(dst)
                    saw_offset = True
                mm = re.fullmatch(
                    r"qword ptr \[rdx \+ ([a-z0-9]+)\]", src)
                if mm and mm.group(1) in vector_regs and dst in self._GP_REGS:
                    vector_regs.add(dst)
            elif m == "test" and o == "dword ptr [r8 + 0xa8], 0x800":
                saw_flags = True
            elif m == "call" and o in vector_regs:
                saw_indirect = True
            if m == "int3" and saw_kwlen:
                break
        return all((saw_kwlen, saw_save_r8, saw_save_r9, saw_type,
                    saw_flags, saw_offset, saw_indirect))

    def _kwcall_helper(self, va):
        """A keyword-bearing CALL helper (CALL_FUNCTION_WITH_*_KW_SPLIT /
        *_VECTORCALL / WITH_KW_ARGS). Nuitka generates these so the fallback
        builds `named_args = _PyDict_NewPresized(n)` then a `PyDict_SetItem` loop
        over (kw_names[i], kw_values[i]) and raises a 'not callable' complaint
        (PyErr_Format). That triple is unique to keyword-call helpers; exclude
        MAKE_FUNCTION (which also builds a dict but uses PyCode_NewWithPosOnlyArgs).
        Universal across Nuitka versions / free & commercial (shared C template)."""
        if va in self._kwcall_cache:
            return self._kwcall_cache[va]
        apis = self.collect_apis(va)
        res = ((apis.get("_PyDict_NewPresized", 9) <= 1
                and apis.get("PyDict_SetItem", 9) <= 1
                and apis.get("PyErr_Format", 9) <= 1
                and apis.get("PyCode_NewWithPosOnlyArgs", 9) > 1)
               or self._kwcall_slot_strict(va))
        self._kwcall_cache[va] = res
        return res

    def _method_call_dispatched_strict(self, va):
        """Detect a fused ``CALL_METHOD_NO_ARGS`` / ``CALL_METHOD_WITH_SINGLE_ARG``
        helper whose attribute lookup is delegated to a shared sub-stub (the
        Nuitka-4.x / MSVC inlining pattern), so ``_method_call_slot_strict``
        cannot fire (it needs the inline ``tp_getattro`` chain).

        Such a helper tail-calls a compact attribute-lookup sub-stub and then,
        having regained control, invokes the resolved attribute through the
        large ``CALL_FUNCTION`` dispatcher.  ``LOOKUP_ATTRIBUTE`` stops after the
        lookup sub-stub; ``FORMAT``/``COMPARE``/``SETATTR`` slow paths reach the
        dispatcher but never the name-keyed attribute lookup.  Requiring BOTH a
        small lookup-style sub-stub (20-90 insns) AND the big call dispatcher
        (>120 insns) inside one compact (25-160 insn) helper isolates exactly the
        fused method-call family.

        Upper bound 160 (was 135): MSVC often leaves the fused helper at ~137
        insns (LOOKUP stub + CALL_FUNCTION_NO_ARGS of the bound method). The old
        ceiling classified those as pure ATTR, so ``self.get_timer()`` emitted as
        a discarded ``self.get_timer`` and vanished from the void-call pass.

        Returns ``0`` (no-args), ``1`` (single positional arg preserved via r9),
        or ``None``.  Consulted only from the ``has_lookup`` branch of
        :meth:`classify`, where the only competing labels are ATTR (a true
        ``LOOKUP_ATTRIBUTE``) and METHOD-via-has_call; the other families are
        decided by earlier branches and never reach this test."""
        cache = getattr(self, "_mcall_dispatch_cache", None)
        if cache is None:
            cache = self._mcall_dispatch_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = None
        off = self.va_to_off(va)
        if off is None:
            return None
        gp = set(self._GP_REGS)
        try:
            blob, _has_extent = self._bounded_helper_blob(va, off, 0x900)
        except Exception:
            return None
        n = 0
        callees = set()
        arg0_preserved = False
        saw_call = False
        for insn in self.md.disasm(blob, va):
            n += 1
            if n > 300:
                break
            m = insn.mnemonic.lower()
            o = insn.op_str.lower()
            if m == "ret":
                break                       # stop at the real function end
            if m == "call":
                saw_call = True
                if o.startswith("0x"):
                    try:
                        t = int(o, 16)
                        if self.va_to_off(t) is not None:
                            callees.add(t)
                    except ValueError:
                        pass
                continue
            if (not saw_call and m == "mov" and "," in o):
                dst, src = [x.strip() for x in o.split(",", 1)]
                if src == "r9" and (dst in gp or dst.startswith(
                        ("qword ptr [rsp", "[rsp"))):
                    arg0_preserved = True
        if n < 25 or n > 160:
            return None
        if not callees or len(callees) > 6:
            return None
        small_stub = False
        big_dispatcher = False
        for c in callees:
            co = self.va_to_off(c)
            if co is None:
                continue
            try:
                cblob, _ = self._bounded_helper_blob(c, co, 0x900)
            except Exception:
                continue
            cn = 0
            for ci in self.md.disasm(cblob, c):
                cn += 1
                if cn > 500:
                    break
                if ci.mnemonic.lower() == "ret":
                    break
            if 20 <= cn <= 90:
                small_stub = True
            elif cn > 120:
                big_dispatcher = True
        if not (small_stub and big_dispatcher):
            return None
        # LOOKUP_ATTRIBUTE (AttributeCodes.py) is GetAttr only. Its error
        # path can still tail-call a large PyErr_Format wrapper, which used
        # to satisfy "small stub + big callee" and render `obj.field()`.
        # CALL_METHOD_NO_ARGS (CallCodes.py) invokes the looked-up object
        # through CALL_FUNCTION / PyObject_Call*. Require a call dispatcher
        # among the large callees; an error-only large callee is ATTR.
        _call_apis = (
            'PyObject_Call', 'PyObject_CallFunctionObjArgs',
            'PyObject_CallMethodObjArgs', 'PyObject_CallObject',
            'PyObject_Vectorcall', 'PyVectorcall_Call',
            'PyEval_GetFuncName',
        )
        _err_apis = (
            'PyErr_Format', 'PyErr_SetString', 'PyErr_SetObject',
            'PyErr_Occurred', 'PyErr_Clear', 'PyErr_ExceptionMatches',
        )
        _has_call_disp = False
        _only_error = True
        for c in callees:
            co = self.va_to_off(c)
            if co is None:
                continue
            try:
                cblob, _ = self._bounded_helper_blob(c, co, 0x900)
            except Exception:
                continue
            cn = 0
            for ci in self.md.disasm(cblob, c):
                cn += 1
                if cn > 500:
                    break
                if ci.mnemonic.lower() == "ret":
                    break
            if cn <= 120:
                continue
            apis = self.collect_apis(c) or {}
            if any(apis.get(a, 9) <= 2 for a in _call_apis):
                _has_call_disp = True
                _only_error = False
                break
            if any(apis.get(a, 9) <= 1 for a in _err_apis):
                continue
            # Inlined vectorcall / tp_call dispatcher: no public IAT, but
            # it is not an error formatter either.
            _only_error = False
            _has_call_disp = True
            break
        if _only_error or not _has_call_disp:
            cache[va] = None
            return None
        arity = 1 if arg0_preserved else 0
        cache[va] = arity
        return arity

    def _full_extent_iat_counts(self, va):
        """Scan all pdata-owned blocks of a helper for direct IAT evidence.

        Several MSVC helpers place their main loop after an early-return block.
        The ordinary fast classifier intentionally stops at that first RET;
        semantic identities such as SUM and LIST_EXTEND need the complete,
        exact unwind extent instead.
        """
        cache = getattr(self, '_full_extent_iat_cache', None)
        if cache is None:
            cache = self._full_extent_iat_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = None
        off = self.va_to_off(va)
        extent = self._helper_extent(va)
        if off is None or extent is None or int(extent[0]) != int(va):
            return None
        size = int(extent[1]) - int(va)
        if size <= 0 or size > 0x10000:
            return None
        try:
            blob, exact = self._bounded_helper_blob(va, off, size)
            if not exact or len(blob) != size:
                return None
            counts = {}
            for insn in self.md.disasm(blob, va):
                match = re.search(
                    r'\[rip\s*([+-])?\s*(0x[0-9a-f]+|\d+)?\]',
                    insn.op_str.lower())
                if not match:
                    continue
                disp = int(match.group(2) or '0', 0)
                if match.group(1) == '-':
                    disp = -disp
                name = self.iat.get(int(insn.address + insn.size + disp))
                if name:
                    counts[name] = counts.get(name, 0) + 1
        except Exception:
            return None
        cache[va] = counts
        return counts

    def _builtin_sum1_helper(self, va):
        """Prove Nuitka's optimized one-argument ``sum`` helper."""
        counts = self._full_extent_iat_counts(va)
        if not counts:
            return False
        required = {
            'PyTuple_Type', 'PyList_Type', 'PyLong_Type',
            'PyLong_AsLongAndOverflow', '_Py_FalseStruct', '_Py_TrueStruct',
        }
        return required <= set(counts) and counts.get('PyNumber_Add', 0) >= 2

    def _list_extend_iterable_helper(self, va):
        """Prove LIST_EXTEND_FROM_ITERABLE without relying on symbols."""
        counts = self._full_extent_iat_counts(va)
        if not counts:
            return False
        required = {'PyList_Type', 'PyTuple_Type', 'PyObject_LengthHint'}
        forbidden = {'PyLong_Type', 'PyLong_AsLongAndOverflow', 'PyNumber_Add'}
        return required <= set(counts) and not (forbidden & set(counts))

    def _inplace_add_pylong_helper(self, va):
        """Prova INPLACE_OPERATION_ADD su PyLong: il risultato viene
        memorizzato in-place attraverso il puntatore operand1 salvato.
        I marker: PyLong_Type in IAT, PyLong digit arithmetic, il pattern
        di salvataggio in-place attraverso il puntatore salvato."""
        counts = self._full_extent_iat_counts(va)
        if not counts or 'PyLong_Type' not in counts:
            return False
        off = self.va_to_off(va)
        extent = self._helper_extent(va)
        if off is None or extent is None or int(extent[0]) != int(va):
            return False
        size_bytes = int(extent[1]) - int(va)
        if size_bytes <= 0 or size_bytes > 0x800:
            return False
        try:
            blob, exact = self._bounded_helper_blob(va, off, size_bytes)
            if not exact or len(blob) != size_bytes:
                return False
        except Exception:
            return False
        # cerca il pattern in-place: il risultato viene memorizzato
        # attraverso il puntatore operand1 salvato (non un nuovo oggetto)
        # e c'è almeno un'operazione aritmetica (add/sub sui digit)
        has_inplace = False
        has_arith = False
        for ins in self.md.disasm(blob, va):
            mn = ins.mnemonic
            ops = ins.op_str.strip()
            if mn == 'mov' and ops.startswith('qword ptr [rdi], rbx'):
                has_inplace = True
            elif mn in ('add', 'sub', 'neg') and ('rdx' in ops or 'rbx' in ops or 'r8' in ops):
                has_arith = True
        return has_inplace and has_arith

    def _list_from_iterable_helper(self, va):
        """Prove the composite ``list(iterable)`` helper by dataflow.

        The helper must (a) call exactly one BUILD_LIST-classified creator,
        (b) call exactly one LIST_EXTEND-classified filler, (c) pass the
        creator's result as the filler's list argument and its own incoming
        iterable parameter as the filler's iterable argument, and (d) return
        the fresh list.  Copy-tracking covers registers and rsp/rbp stack
        slots for both Win64 and SysV argument registers; all slots are
        invalidated whenever the frame pointer moves, so no stale alias can
        satisfy the proof.
        """
        cache = getattr(self, '_lfi_cache', None)
        if cache is None:
            cache = self._lfi_cache = {}
        if va in cache:
            return cache[va]
        # Recursion guard: assume False while analysing callees.
        cache[va] = False
        off = self.va_to_off(va)
        extent = self._helper_extent(va)
        if off is None or extent is None or int(extent[0]) != int(va):
            return False
        size = int(extent[1]) - int(va)
        if size <= 0 or size > 0x10000:
            return False
        try:
            blob, exact = self._bounded_helper_blob(va, off, size)
            if not exact or len(blob) != size:
                return False
            events, ret_rax = self._trace_helper_calls(blob, va)
        except Exception:
            return False
        create_vals = set()
        extend_events = []
        for ev in events:
            if ev['target'] is None:
                continue          # indirect (IAT / dispatch slot) call
            try:
                cls = self.classify(ev['target'])
            except Exception:
                cls = ('UNKNOWN', None)
            if cls[0] == 'BUILD_LIST':
                create_vals.add(('call', ev['addr']))
            elif cls == ('LIST_EXTEND', None):
                extend_events.append(ev)
            elif cls[0] == 'BUILTIN_CALL' and cls[1] == 'len':
                pass              # optional preallocation length probe
            elif cls[0] in ('COMPARE', 'ERR'):
                pass              # exceptional length-conversion fallbacks
            elif cls[0] == 'UNKNOWN' and self._error_machinery_callee(
                    ev['target']):
                pass              # provato macchinario d'errore/allocazione
            else:
                return False      # any other Python-semantics call: no proof
        if len(create_vals) != 1 or len(extend_events) != 1:
            return False
        fresh = next(iter(create_vals))
        ext = extend_events[0]
        win64 = (ext['rcx'] == ('arg', 0) and ext['rdx'] == fresh
                 and ext['r8'] == ('arg', 1))
        sysv = (ext['rdi'] == ('arg', 0) and ext['rsi'] == fresh
                and ext['rdx'] == ('arg', 1))
        if not (win64 or sysv):
            return False
        if fresh not in ret_rax:
            return False
        cache[va] = True
        return True
    _REG64 = {'eax': 'rax', 'ebx': 'rbx', 'ecx': 'rcx', 'edx': 'rdx',
              'esi': 'rsi', 'edi': 'rdi', 'ebp': 'rbp', 'esp': 'rsp',
              'r8d': 'r8', 'r9d': 'r9', 'r10d': 'r10', 'r11d': 'r11',
              'r12d': 'r12', 'r13d': 'r13', 'r14d': 'r14', 'r15d': 'r15',
              'ax': 'rax', 'bx': 'rbx', 'cx': 'rcx', 'dx': 'rdx',
              'al': 'rax', 'bl': 'rbx', 'cl': 'rcx', 'dl': 'rdx',
              'sil': 'rsi', 'dil': 'rdi', 'bpl': 'rbp', 'spl': 'rsp'}

    def _trace_helper_calls(self, blob, va):
        """Linear scan recording (target, {argreg: value}) per direct call and
        the rax value live at each ``ret``.  Values are provenance tags:
        ('arg', n) for entry arguments, ('call', addr) for call results,
        ('imm', n) for constants; None marks an unknown/clobbered value."""
        events = []
        ret_rax = []
        regs = {'rcx': ('arg', 0), 'rdx': ('arg', 1),
                'rdi': ('arg', 0), 'rsi': ('arg', 1)}
        slots = {}
        clobber_regs = ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11')

        def reg64(text):
            t = text.strip().lower()
            t = re.sub(r'^(qword|dword|word|byte) ptr\s*', '', t)
            return self._REG64.get(t, t if re.fullmatch(r'r?[a-z0-9]{2,3}', t)
                                   else None)

        def parse(text):
            t = text.strip().lower()
            t = re.sub(r'^(qword|dword|word|byte) ptr\s*', '', t)
            if re.fullmatch(r'r?[a-z0-9]{2,3}', t):
                r = self._REG64.get(t, t)
                return ('reg', r)
            if t.startswith('[') and t.endswith(']'):
                inner = t[1:-1].replace(' ', '')
                m = re.fullmatch(r'(rsp|rbp)(\+0x[0-9a-f]+|\+\d+)', inner)
                if m:
                    return ('mem', m.group(1) + m.group(2))
                return None
            if re.fullmatch(r'(0x[0-9a-f]+|\d+)', t):
                return ('imm', int(t, 0))
            return None

        def value_of(opv):
            if opv is None:
                return None
            if opv[0] == 'reg':
                return regs.get(opv[1])
            if opv[0] == 'mem':
                return slots.get(opv[1])
            return opv[1] if opv[0] == 'imm' else None

        for insn in self.md.disasm(blob, va):
            mn = insn.mnemonic
            ops = insn.op_str
            if mn == 'mov' or mn == 'movabs':
                parts = ops.split(',')
                if len(parts) == 2:
                    dv = parse(parts[0])
                    val = value_of(parse(parts[1]))
                    if dv is not None:
                        if dv[0] == 'reg':
                            regs[dv[1]] = val
                        elif dv[0] == 'mem':
                            slots[dv[1]] = val
            elif mn == 'lea':
                parts = ops.split(',')
                if len(parts) == 2:
                    dv = parse(parts[0])
                    if dv is not None and dv[0] == 'reg':
                        regs[dv[1]] = None
            elif mn == 'xor':
                parts = ops.split(',')
                if len(parts) == 2 and                         reg64(parts[0]) == reg64(parts[1]) and                         reg64(parts[0]) in regs:
                    regs[reg64(parts[0])] = ('imm', 0)
            elif mn == 'pop':
                slots.clear()
                r = reg64(ops.split(',')[0])
                if r:
                    regs[r] = None
            elif mn == 'push':
                slots.clear()
            elif mn == 'call':
                tv = ops.split(',')[0].strip()
                target = None
                if re.fullmatch(r'(0x[0-9a-f]+|\d+)', tv):
                    target = int(tv, 0)
                events.append({'addr': insn.address, 'target': target,
                               'rcx': regs.get('rcx'), 'rdx': regs.get('rdx'),
                               'r8': regs.get('r8'), 'rdi': regs.get('rdi'),
                               'rsi': regs.get('rsi')})
                for r in clobber_regs:
                    regs[r] = None
                regs['rax'] = ('call', insn.address)
            elif mn == 'ret':
                ret_rax.append(regs.get('rax'))
            else:
                if mn in ('add', 'sub'):
                    r = reg64(ops.split(',')[0])
                    if r in ('rsp', 'rbp'):
                        slots.clear()
                    elif r:
                        regs[r] = None
                elif mn in ('imul', 'and', 'or', 'shl', 'shr', 'sar',
                            'inc', 'dec', 'neg', 'not', 'movzx', 'movsx'):
                    r = reg64(ops.split(',')[0])
                    if r:
                        regs[r] = None
        return events, ret_rax

    def _error_machinery_callee(self, va):
        """True se il helper tocca solo API d'errore/allocazione CPython
        (nessuna semantica Python osservabile): accettabile come callee di
        percorso eccezionale nelle prove strutturali composite."""
        counts = self._full_extent_iat_counts(va)
        if not counts:
            # Nessuna API C: dispatch indiretto via slot (es. tp_richcompare)
            # o leaf puro — non può fare lavoro Python osservabile da solo.
            return True
        return all(name.startswith(('PyErr_', 'PyMem_', 'PyExc_', '_Py'))
                   or name in ('PyObject_LengthHint',)
                   for name in counts)

    def _binop_add_object_clong_helper(self, va):
        """Prove the ADD(object, C-long) helper from source-level shape.

        Matches Nuitka's ``BINARY_OPERATION_ADD_OBJECT_LONG_CLONG`` (and the
        INT_CLONG twin): digit-size read at [arg0 + 0x10], sign split of the
        C-long argument (``shr r32, 0x1f`` or ``neg``), the ``cmp rax, 1``
        small-path check, a 32-bit ``lea reg, [reg + reg]`` medium fast path,
        no direct calls and no C-API (tails are ``jmp``).  Requires BOTH
        argument registers to participate (object pointer arg0, value arg1),
        for Win64 and SysV entry conventions."""
        cache = getattr(self, '_baoc_cache', None)
        if cache is None:
            cache = self._baoc_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False
        off = self.va_to_off(va)
        extent = self._helper_extent(va)
        if off is None or extent is None or int(extent[0]) != int(va):
            return False
        size_bytes = int(extent[1]) - int(va)
        if size_bytes <= 0 or size_bytes > 0x1000:
            return False
        if self._full_extent_iat_counts(va):
            return False           # tocca API C: non è aritmetica pura
        try:
            blob, exact = self._bounded_helper_blob(va, off, size_bytes)
            if not exact or len(blob) != size_bytes:
                return False
        except Exception:
            return False

        _reg64 = self._REG64

        def reg_of(text):
            t = text.strip().lower()
            t = re.sub(r'^(qword|dword|word|byte) ptr\s*', '', t)
            return _reg64.get(t, t if re.fullmatch(r'r?[a-z0-9]{2,3}', t)
                              else None)

        arg0_regs = {'rcx', 'rdi'}
        arg1_regs = {'rdx', 'rsi'}
        size_read = False
        sign_split = False
        small_path = False
        lea_add = False
        tail_jmp = False
        _ALLOCATION_IAT = {'PyLong_Type', 'PyObject_InitVar', '_PyRuntime',
                           'PyMem_Malloc', 'PyMem_Realloc', 'PyErr_NoMemory'}
        bad_call = False

        for insn in self.md.disasm(blob, va):
            mn = insn.mnemonic
            ops = insn.op_str
            if mn == 'mov':
                parts = ops.split(',')
                if len(parts) == 2:
                    src_l = re.sub(r'^(qword|dword|word|byte) ptr\s*', '',
                                   parts[1].strip().lower())
                    mm = re.fullmatch(r'\[(\w+) \+ 0x10\]', src_l)
                    if mm is not None and reg_of(mm.group(1)) in arg0_regs:
                        size_read = True
                    else:
                        s = reg_of(parts[1])
                        d = reg_of(parts[0])
                        if d:
                            if s in arg0_regs:
                                arg0_regs.add(d)
                            if s in arg1_regs:
                                arg1_regs.add(d)
            elif mn == 'shr':
                parts = ops.split(',')
                if len(parts) == 2 and parts[1].strip().lower() in (
                        '0x1f', '31') and reg_of(parts[0]) in arg1_regs:
                    sign_split = True
            elif mn == 'neg':
                if reg_of(ops) in arg1_regs:
                    sign_split = True
            elif mn == 'cmp':
                parts = ops.split(',')
                if len(parts) == 2 and parts[1].strip() == '1':
                    small_path = True
            elif mn == 'lea':
                mm = re.fullmatch(
                    r'([a-z0-9]+), \[([a-z0-9]+) \+ ([a-z0-9]+)\]',
                    ops.strip().lower())
                if mm is not None:
                    lea_add = True
            elif mn == 'jmp':
                if re.fullmatch(r'(0x[0-9a-f]+|\d+)', ops.strip()):
                    tail_jmp = True
            elif mn == 'call':
                tv = ops.split(',')[0].strip()
                if re.fullmatch(r'(0x[0-9a-f]+|\d+)', tv):
                    counts = self._full_extent_iat_counts(
                        int(tv, 0)) or {}
                    if not counts or not set(counts) <= _ALLOCATION_IAT:
                        bad_call = True
                else:
                    bad_call = True
        ok = (size_read and sign_split and small_path and lea_add and
              tail_jmp and not bad_call)
        cache[va] = ok
        return ok

    def _resolve_is_make_list_empty(self, va):
        """True se il target risolve (nome/sig) a MAKE_LIST_EMPTY."""
        resolver = getattr(self, 'resolver', None)
        if resolver is None:
            return False
        try:
            resolved = resolver.resolve(va)
        except Exception:
            return False
        if isinstance(resolved, tuple) and len(resolved) >= 2:
            return resolved[1] == 'MAKE_LIST_EMPTY'
        return False

    def _list_copy_const_helper(self, va):
        """Prove the specialised LIST_COPY helper (constant list displays).

        Shape (see HelpersLists.c LIST_COPY, size-specialised/unrolled by the
        compiler): one direct call to a BUILD_LIST-classified creator with an
        immediate size, then that many incref+store pairs copying items from
        the incoming collection's ob_item ([arg1 + 0x18]) into the fresh
        list's ob_item, then the fresh list is returned."""
        cache = getattr(self, '_lcc_cache', None)
        if cache is None:
            cache = self._lcc_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False
        off = self.va_to_off(va)
        extent = self._helper_extent(va)
        if off is None or extent is None or int(extent[0]) != int(va):
            return False
        size_bytes = int(extent[1]) - int(va)
        if size_bytes <= 0 or size_bytes > 0x2000:
            return False
        try:
            blob, exact = self._bounded_helper_blob(va, off, size_bytes)
            if not exact or len(blob) != size_bytes:
                return False
        except Exception:
            return False

        _reg64 = self._REG64

        def reg_of_local(text):
            t = text.strip().lower()
            t = re.sub(r'^(qword|dword|word|byte) ptr\s*', '', t)
            return _reg64.get(t, t if re.fullmatch(r'r?[a-z0-9]{2,3}', t)
                              else None)

        create_size = None
        create_calls = 0
        total_calls = 0
        increfs = 0
        item_stores = 0
        item_loads = 0
        obitem_reg = None
        returns_result = False
        bad_call = False
        copy_regs = {'rdx', 'rsi'}

        for insn in self.md.disasm(blob, va):
            mn = insn.mnemonic
            ops = insn.op_str
            if mn == 'mov':
                parts = ops.split(',')
                if len(parts) == 2:
                    dst = reg_of_local(parts[0])
                    src_l = re.sub(r'^(qword|dword|word|byte) ptr\s*', '',
                                   parts[1].strip().lower())
                    if parts[0].strip().lower() == 'edx':
                        rhs = parts[1].strip().lower()
                        if re.fullmatch(r'(0x[0-9a-f]+|\d+)', rhs):
                            create_size = int(rhs, 0)
                    mm16 = re.fullmatch(r'\[(\w+) \+ 0x18\]', src_l)
                    if mm16 is not None and dst and                             mm16.group(1) in copy_regs:
                        obitem_reg = dst          # ob_item della collezione
                    elif obitem_reg:
                        mm_item = re.fullmatch(
                            r'\[' + re.escape(obitem_reg) +
                            r'(?: \+ (?:0x[0-9a-f]+|\d+))?\]', src_l)
                        if mm_item is not None and dst:
                            item_loads += 1       # lettura di un item
                    if dst:
                        s = reg_of_local(parts[1])
                        if s in copy_regs:
                            copy_regs.add(dst)

            elif mn == 'call':
                total_calls += 1
                tv = ops.split(',')[0].strip()
                if re.fullmatch(r'(0x[0-9a-f]+|\d+)', tv):
                    target = int(tv, 0)
                    try:
                        cls = self.classify(target)
                    except Exception:
                        cls = ('UNKNOWN', None)
                    if cls[0] == 'BUILD_LIST':
                        create_calls += 1
                    elif self._resolve_is_make_list_empty(target):
                        create_calls += 1
                    elif not self._error_machinery_callee(target):
                        bad_call = True
                else:
                    bad_call = True
            elif mn == 'inc':
                if 'qword ptr [' in ops.lower():
                    increfs += 1
            elif mn == 'ret':
                ret_reg = ops.strip().lower()
                if ret_reg in ('rax', ''):
                    pass
        ok = (create_calls == 1 and create_size is not None and
              1 <= create_size <= 64 and increfs >= create_size and
              item_loads >= create_size and
              not bad_call and total_calls == 1)
        cache[va] = ok
        return ok

    def _list_append_slot_strict(self, va):
        """Prove an inlined LIST_APPEND helper (no exported API evidence).

        Shape: size = arg0->ob_size; resize(arg0, size + 1) through an
        allocation/error-only callee; arg0->ob_item[size] = arg1; return
        true.  Argument registers are tracked as sets (copies accumulate),
        so fail-path epilogue reloads cannot erase the provenance; the
        remaining gates (exact PyListObject offsets, single resize-shaped
        callee, scaled store, ``mov al, 1``) keep the proof strict."""
        cache = getattr(self, '_lap_cache', None)
        if cache is None:
            cache = self._lap_cache = {}
        if va in cache:
            return cache[va]
        cache[va] = False
        off = self.va_to_off(va)
        extent = self._helper_extent(va)
        if off is None or extent is None or int(extent[0]) != int(va):
            return False
        size_bytes = int(extent[1]) - int(va)
        if size_bytes <= 0 or size_bytes > 0x400:
            return False
        try:
            blob, exact = self._bounded_helper_blob(va, off, size_bytes)
            if not exact or len(blob) != size_bytes:
                return False
        except Exception:
            return False

        _reg64 = self._REG64

        def reg_of(text):
            t = text.strip().lower()
            t = re.sub(r'^(qword|dword|word|byte) ptr\s*', '', t)
            return _reg64.get(t, t if re.fullmatch(r'r?[a-z0-9]{2,3}', t)
                              else None)

        arg0_regs = {'rcx', 'rdi'}     # Win64 list / SysV list
        arg1_regs = {'rdx', 'rsi'}     # Win64 value / SysV value
        size_reg = None
        items_reg = None
        resize_calls = 0
        total_calls = 0
        saw_store = False
        saw_true = False
        _BENIGN_CALLEE_IAT = {'PyErr_NoMemory', 'PyMem_Realloc',
                              'PyMem_Malloc', 'PyErr_SetString'}

        for insn in self.md.disasm(blob, va):
            mn = insn.mnemonic
            ops = insn.op_str
            if mn == 'mov':
                parts = ops.split(',')
                if len(parts) != 2:
                    continue
                dst_t, src_t = parts[0].strip(), parts[1].strip()
                dst_l = dst_t.lower()
                src_l = re.sub(r'^(qword|dword|word|byte) ptr\s*', '',
                               src_t.lower())
                dst_mem = re.fullmatch(
                    r'(?:qword|dword|word|byte) ptr \[(\w+) \+ (\w+)\*8\]',
                    dst_l)
                if dst_mem is not None:
                    if (reg_of(dst_mem.group(1)) == items_reg and
                            reg_of(dst_mem.group(2)) == size_reg and
                            reg_of(src_l) in arg1_regs):
                        saw_store = True
                    continue
                d = reg_of(dst_t)
                mm = re.fullmatch(r'\[(\w+) \+ (0x[0-9a-f]+|\d+)\]', src_l)
                if mm is not None and d:
                    base = reg_of(mm.group(1))
                    disp = int(mm.group(2), 0)
                    if base in arg0_regs and disp == 0x10:
                        size_reg = d
                    elif base in arg0_regs and disp == 0x18:
                        items_reg = d
                    continue
                s = reg_of(src_l)
                if d:
                    if s in arg0_regs:
                        arg0_regs.add(d)
                    if s in arg1_regs:
                        arg1_regs.add(d)
                    if re.fullmatch(r'(0x[0-9a-f]+|\d+)', src_l):
                        if int(src_l, 0) == 1 and dst_l == 'al':
                            saw_true = True
            elif mn == 'call':
                total_calls += 1
                tv = ops.split(',')[0].strip()
                if re.fullmatch(r'(0x[0-9a-f]+|\d+)', tv):
                    counts = self._full_extent_iat_counts(
                        int(tv, 0)) or {}
                    if counts and set(counts) <= _BENIGN_CALLEE_IAT:
                        resize_calls += 1
        ok = (size_reg is not None and items_reg is not None and
              resize_calls == 1 and total_calls == 1 and saw_store and
              saw_true)
        cache[va] = ok
        return ok

    def classify(self, va):
        if va in self._cls:
            return self._cls[va]
        g = self._global_thunk(va)
        if g is not None:
            res = ("GLOBAL", g)
        elif getattr(
                self, "_module_variable_accessor_strict",
                lambda _va: False)(va):
            # Python 3.11+ keys-version-cached module global accessor.  The
            # simulator resolves the exact name from this helper's mod_consts
            # reference; classification supplies only the proven operation.
            res = ("GLOBAL", None)
        elif self._is_global_lookup(va):
            res = ("GLOBALCALL", None)            # LOOKUP module/global by name (rdx=name, rcx=dict)
        elif self._import_hard_helper(va):
            # IMPORT_HARD_<NAME>() getter used at a VALUE site (e.g. `os` in
            # `os.path.join(...)`): resolve to the bound top-level module name
            # instead of the opaque UNKNOWN that misresolves to an adjacent global.
            res = ("GLOBAL", self._import_hard_helper(va).split(".")[0])
        elif getattr(self, "_getattr3_helper", lambda _va: False)(va):
            # BUILTIN_GETATTR(tstate, object, name, default): unlike a plain
            # attribute lookup, the fourth ABI argument is returned only after
            # an AttributeError.  Its full CFG/provenance proof must precede the
            # generic ATTR/METHOD families.
            res = ("GETATTR3", None)
        elif getattr(
                self, "_lookup_attr_tail_slot_strict",
                lambda _va: False)(va):
            # API-free modern LOOKUP_ATTRIBUTE wrapper.  Its proven
            # tp_getattro tail dispatch must win over the UNKNOWN call-site
            # method fallback, which would append a spurious ``()``.
            res = ("ATTR", None)
        elif getattr(
                self, "_method_call_slot_strict",
                lambda _va: None)(va) is not None:
            # API-free CALL_METHOD_NO_ARGS / CALL_METHOD_WITH_SINGLE_ARG.
            # Carry the exact arity so stale caller registers cannot become
            # phantom Python arguments in the register simulator.
            res = ("METHOD", (
                "strict_method",
                self._method_call_slot_strict(va),
            ))
        elif getattr(self, "_getiter_slot_strict", lambda _va: False)(va):
            # API-free GetIter/PyIter_New wrapper: iter(<rcx>) with the
            # iterable as the only argument; the simulator emits `iter(src)`
            # and arms sequence-unpack exactly like a proven GetIter site.
            res = ("GETITER", None)
        elif getattr(
                self, "_function_call_slot_strict",
                lambda _va: None)(va) is not None:
            # API-free generic CALL_FUNCTION_* dispatcher.  Preserve whether
            # this form has an r8 positional payload or is the no-args form.
            res = ("CALL", (
                "strict_function",
                self._function_call_slot_strict(va),
            ))
        elif self._object_size_slot_strict(va):
            # API-free PyObject_Size/len helper.  Its exact protocol-slot proof
            # also establishes the exceptional ABI: object is rcx (no tstate).
            res = ("BUILTIN_CALL", "len")
        elif self._deepcopy_constant_helper(va):
            res = ("COPY_CONST", "rdx")
        else:
            # 3.11+/Nuitka-V4.x: promote the high-confidence tp_richcompare-slot
            # COMPARE ahead of the exported-API cascade. On V4.x these helpers
            # inline the reflected-compare/NotImplemented path whose slow branch
            # reaches PyErr_Format (or _PyType_Lookup) and is mis-claimed as
            # ('ERR',None)/METHOD before the correct _richcmp fallback runs. Only
            # the 0xc8-slot + Py_XX-enum + indirect-call shape is promoted, so it
            # can never hijack a FORMAT/SETATTR/BINOPSLOT helper.
            if getattr(self, '_pycode_is_unstable', False):
                _hc = self._richcmp_slot_op(va)
                if _hc is not None:
                    res = ("COMPARE", _hc)
                    self._cls[va] = res
                    return res
            apis = self.collect_apis(va)
            has_lookup = apis.get("_PyType_Lookup", 9) <= 1
            has_call = apis.get("PyEval_GetFuncName", 9) <= 2
            has_subscript = (apis.get("PyNumber_AsSsize_t", 9) <= 2
                             or apis.get("PyObject_GetItem", 9) <= 2)
            _bn = self._builtin_name(va)
            # ---- CPython 3.11+ / Nuitka V4.x helper C-API re-tune ----------------
            # V4.x drops the _PyType_Lookup attribute fast-path (ATTR/METHOD call
            # PyObject_GetAttr[String] directly) and never reaches PyEval_GetFuncName
            # (plain CALL dispatches through the callee tp_call slot, inlined), so the
            # 3.10 discriminators go to ~0 and ATTR/METHOD/SUBSCRIPT/SETATTR all
            # misclassify. Re-derive them from the APIs V4.x DOES call (confirmed on
            # CPython 3.12/Nuitka 4.x builds). Also the tp_setattro=0x98 heuristic
            # collides with the 3.11+ frame-object field 0x98, so use the
            # PyObject_SetAttr IAT signal instead. Gated on _is_unstable => 3.10
            # stays byte-identical.
            if getattr(self, '_is_unstable', False):
                if min(apis.get("PyObject_GetAttr", 9),
                       apis.get("PyObject_GetAttrString", 9)) <= 1:
                    has_lookup = True
                if min(apis.get("PyObject_CallFunctionObjArgs", 9),
                       apis.get("PyObject_CallMethodObjArgs", 9),
                       apis.get("PyObject_Call", 9)) <= 2:
                    has_call = True
                _setattr_ok = (
                    min(apis.get("PyObject_SetAttr", 9),
                        apis.get("PyObject_SetAttrString", 9),
                        apis.get("PyObject_GenericSetAttr", 9)) <= 1
                    or self._setattr_slot_strict(va))
            else:
                _setattr_ok = self._setattr_slot(va)
            if self._list_copy_const_helper(va):
                res = ("LIST_COPY_CONST", None)
            elif self._binop_add_object_clong_helper(va):
                # ADD(<long object>, <C long>): fonte ``x + <costante int>``
                res = ("BINOP", "+")
            elif self._list_append_slot_strict(va):
                res = ("LIST_APPEND", None)
            elif self._inplace_add_pylong_helper(va):
                # INPLACE_ADD su PyLong: ``x += <int>`` — il risultato torna
                # nell'operand1 attraverso il puntatore salvato.
                res = ("BINOP", "+")
            elif self._list_from_iterable_helper(va):
                # Composite list(iterable): a fresh MAKE_LIST_EMPTY result is
                # filled by a proven LIST_EXTEND callee and returned.  The
                # dataflow proof must win over the API cascade, whose
                # PyErr_Format/PyMem evidence comes from error paths only.
                res = ("BUILTIN_CALL", "list")
            elif self._builtin_sum1_helper(va):
                res = ("BUILTIN_CALL", "sum")
            elif self._list_extend_iterable_helper(va):
                res = ("LIST_EXTEND", None)
            elif self._kwcall_helper(va):
                res = ("KWCALL", None)                     # f(pos, kw=val) keyword call
            elif _bn == "format":
                res = ("FORMAT_VALUE", None)               # format(value) f-string piece
            elif _bn is not None:
                res = ("BUILTIN_CALL", _bn)                # open(...) / len(...) / ...
            elif (apis.get("PyObject_SetItem", 9) <= 2
                    or self._is_subscript_store_helper(va)):
                # SET_SUBSCRIPT(tstate, target, key, value) → target[key] = value.
                # Prefer over SETATTR: both are stores, but SetItem / mp_ass_subscript
                # (0x10) uniquely fingerprints item assignment. Sequence fallbacks
                # also touch PyNumber_AsSsize_t so has_subscript may be true here.
                res = ("SETSUBSCRIPT", None)
            elif (apis.get("PyObject_DelItem", 9) <= 2):
                # DEL_SUBSCRIPT(target, key) → del target[key] (no tstate in helper ABI)
                res = ("DELSUBSCRIPT", None)
            elif min(apis.get("PyObject_DelAttr", 9),
                     apis.get("PyObject_DelAttrString", 9)) <= 1:
                # getAttributeDelCode → PyObject_DelAttr(target, name)
                res = ("DELATTR", None)
            elif _setattr_ok and not has_subscript:
                # A proven tp_setattro/PyObject_SetAttr helper remains an
                # attribute store even when its slow/error path performs an
                # internal Python call.  Requiring ``not has_call`` made modern
                # Nuitka helpers fall through to METHOD/CALL and rendered
                # ``self.x = value`` as ``self.x(value)``.  PyObject_SetAttr*
                # (3.11+) and the clean tp_setattro slot fingerprint (<=3.10)
                # are both store-specific; subscript remains the only competing
                # write shape that must be excluded here.
                res = ("SETATTR", None)                    # target.attr = value
            elif apis.get("PyObject_GetIter", 9) <= 1 and apis.get("PyObject_IsTrue", 9) <= 1:
                res = ("BUILTIN", self._anyall_kind(va))   # any(x) / all(x)
            elif getattr(self, '_is_unstable', False) and has_subscript \
                    and not has_lookup and not has_call:
                res = ("SUBSCRIPT", None)            # source[key] (V4.x GetItem-only)
            elif has_lookup and has_subscript and not has_call:
                res = ("SUBSCRIPT", None)            # source[key]
            elif has_lookup and has_call:
                # Nuitka AttributeCodes.py LOOKUP_ATTRIBUTE is GetAttr only.
                # CALL_METHOD / CALL_FUNCTION_NO_ARGS is a *separate* helper.
                # On 3.11, GetAttr error paths can touch PyObject_Call* and
                # falsely set has_call, turning `obj.field` into `obj.field()`.
                # Require an invocation fingerprint before METHOD.
                if getattr(self, '_is_unstable', False):
                    _disp = self._method_call_dispatched_strict(va)
                    if _disp is not None:
                        res = ("METHOD", ("strict_method", _disp))
                    else:
                        res = ("ATTR", None)
                else:
                    res = ("METHOD", None)
            elif has_lookup and self._method_call_dispatched_strict(va) is not None:
                # Fused CALL_METHOD_NO_ARGS / CALL_METHOD_WITH_SINGLE_ARG whose
                # attribute lookup is delegated to a sub-stub.  It invokes via
                # vectorcall, so the call never reaches PyEval_GetFuncName and
                # ``has_call`` stays False -> the API cascade would drop it to
                # ATTR (rendering ``c.session`` instead of ``c.session()``).  The
                # dispatched-strict fingerprint (small lookup stub + big
                # CALL_FUNCTION dispatcher) proves it actually invokes, so render
                # it as a METHOD call with the exact arity tag.
                res = ("METHOD", (
                    "strict_method", self._method_call_dispatched_strict(va)))
            elif has_lookup:
                res = ("ATTR", None)
            elif apis.get("PySequence_Contains", 9) <= 2:
                res = ("CONTAINS", None)              # a in b
            elif apis.get("PyObject_RichCompare", 9) <= 2:
                res = ("COMPARE", self._richcmp_op(va))   # a <cmp> b (op if readable)
            elif any(apis.get(k, 9) <= 1 for k in _NDL_BINOP):
                res = ("BINOP", next(_NDL_BINOP[k] for k in _NDL_BINOP if apis.get(k, 9) <= 1))
            elif self._binop_slot(va) is not None:
                res = ("BINOPSLOT", self._binop_slot(va))   # a <op> b via nb_* slot
            elif self._str_concat_helper(va) is not None:
                # str `+` concat fast path (nb_add slot 0x00 is skipped above as
                # collision-prone; recover it via the PyUnicode_Type ob_type check)
                res = ("BINOPSLOT", ("+", self._str_concat_helper(va)))
            elif self._is_dict_subscript_helper(va):
                res = ("SUBSCRIPT", None)            # exact-dict DICT_GET_ITEM* helper
            elif self._is_subscript_helper(va):
                res = ("SUBSCRIPT", None)            # obj[key] (optimised LOOKUP_SUBSCRIPT)
            elif has_call:
                res = ("CALL", None)
            elif apis.get("PyImport_ImportModuleLevelObject", 9) <= 1:
                res = ("IMPORT", None)
            elif apis.get("PyCode_NewWithPosOnlyArgs", 9) <= 1:
                res = ("MAKE_FUNCTION", None)
            elif apis.get("PyUnicode_FromFormat", 9) <= 1:
                res = ("FORMAT", "fromformat")
            elif apis.get("PyUnicode_Format", 9) <= 1:
                res = ("FORMAT", "unicode_format")
            elif apis.get("PyErr_Format", 9) <= 1:
                res = ("ERR", None)
            elif (apis.get("PyDict_SetItem", 9) == 0 and len(apis) <= 2
                  and apis.get("_PyDict_NewPresized", 9) > 1
                  and apis.get("PyErr_Format", 9) > 1):
                # UPDATE_STRING_DICT0 loads moduledict from a fixed RIP slot
                # (CTypeModuleDictVariables). Class-body DICT_SET_ITEM
                # (LocalsDictCodes.generateLocalsDictSetCode) takes the locals
                # dict from an argument. Both are `name = value` in Python.
                if self._is_module_dict_store(va):
                    res = ("MODSTORE", None)
                else:
                    res = ("DICTSET", None)
            elif self._container_builder(va) is not None:
                res = (self._container_builder(va), None)  # BUILD_LIST/TUPLE/SET/MAP
            else:
                # Type-specialized RICH_COMPARE_xx helpers reach tp_richcompare
                # through an INDIRECT slot call, so no CPython-API fingerprint
                # matches — recognise them by the readable operator enum.
                op = self._richcmp_op(va)
                res = ("COMPARE", op) if op is not None else ("UNKNOWN", None)
        self._cls[va] = res
        return res






