import re
import struct
from collections import defaultdict

from capstone import Cs, CS_ARCH_X86, CS_MODE_64

# ---------------------------------------------------------------------------
# Disassembly utilities
# ---------------------------------------------------------------------------

GP_REGS = {'rax', 'rbx', 'rcx', 'rdx', 'rsi', 'rdi', 'rbp', 'rsp',
           'r8', 'r9', 'r10', 'r11', 'r12', 'r13', 'r14', 'r15'}

_RIP_RE = re.compile(r'rip ([+-]) (0x[0-9a-f]+)')


_REG32 = {'eax': 'rax', 'ebx': 'rbx', 'ecx': 'rcx', 'edx': 'rdx',
          'esi': 'rsi', 'edi': 'rdi', 'ebp': 'rbp', 'esp': 'rsp',
          'r8d': 'r8', 'r9d': 'r9', 'r10d': 'r10', 'r11d': 'r11',
          'r12d': 'r12', 'r13d': 'r13', 'r14d': 'r14', 'r15d': 'r15'}


def _canon_reg(r):
    """Normalizza i nomi registro a 64-bit (esi→rsi, r8d→r8, ...)."""
    r = r.strip()
    if r in GP_REGS:
        return r
    return _REG32.get(r, r)


def rip_target(insn):
    """Se l'istruzione è rip-relativa, ritorna il VA target."""
    m = _RIP_RE.search(insn.op_str)
    if not m:
        return None
    disp = int(m.group(2), 16)
    if m.group(1) == '-':
        disp = -disp
    return insn.address + insn.size + disp


def branch_target(insn):
    """Target di un jcc/jmp/call con operando immediato."""
    if insn.op_str.startswith('0x'):
        try:
            return int(insn.op_str, 16)
        except ValueError:
            return None
    return None


class FuncDisassembler:
    """Disassembla funzioni con capstone, cache per VA.

    V100 SPEED: cache ed engine capstone vivono sull'oggetto IMMAGINE e sono
    condivisi tra tutte le istanze.  Ogni chiamata di extract_code_objects
    creava una nuova istanza (230+ per run) e buttava via la cache dei VA
    gia' disassemblati.  Stesso output, un'unica disassemblatura per
    (va, max_bytes)."""

    def __init__(self, img, max_bytes=0x20000):
        self.img = img
        cache = getattr(img, '_ndx_fd_cache', None)
        if cache is None:
            from collections import OrderedDict
            cache = OrderedDict()
            img._ndx_fd_cache = cache
            img._ndx_fd_cache_size = 0
        self._cache = cache
        md = getattr(img, '_ndx_fd_md', None)
        if md is None:
            md = Cs(CS_ARCH_X86, CS_MODE_64)
            md.detail = True
            img._ndx_fd_md = md
        self.md = md
        self.max_bytes = max_bytes

    def insns(self, va, max_bytes=None, stop_at_ret=True):
        key = (va, max_bytes, stop_at_ret)
        if key in self._cache:
            self._cache.move_to_end(key)
            return self._cache[key]
        off = self.img.va_to_off(va)
        if off is None:
            return []
        limit = max_bytes or self.max_bytes
        bounds = self.img.function_bounds(va)
        if bounds is not None and bounds[0] <= va < bounds[1]:
            limit = min(limit, bounds[1] - va)
        out = []
        address = va
        finished = False
        while address < va + limit and not finished:
            relative = address - va
            code = self.img.data[off+relative:off+min(relative+4096, limit)]
            following = address
            for insn in self.md.disasm(code, address, count=512):
                out.append(insn)
                following = insn.address + insn.size
                if stop_at_ret and insn.mnemonic == 'ret':
                    finished = True
                    break
            if following == address:
                break
            address = following
        # Budget retained instructions, never the decoded function length.
        # Large module initializers otherwise accumulate in the shared cache
        # for every module during the cross-module constants prepass.
        budget = 65536
        if len(out) <= budget:
            size = getattr(self.img, '_ndx_fd_cache_size', 0)
            while self._cache and size + len(out) > budget:
                _, previous = self._cache.popitem(last=False)
                size -= len(previous)
            self._cache[key] = out
            self.img._ndx_fd_cache_size = size + len(out)

        return out


# ---------------------------------------------------------------------------
# Simboli del dataflow
# ---------------------------------------------------------------------------

class NdxSym:
    """Un valore simbolico tracciato nel dataflow."""
    __slots__ = ('kind', 'value', 'meta')

    def __init__(self, kind, value=None, meta=None):
        self.kind = kind      # const|local|temp|module|moddict|func|codeobj|iter|call|attr|...
        self.value = value
        self.meta = meta or {}

    def __repr__(self):
        return f"<{self.kind}:{self.value!r}>"


def ndxS(kind, value=None, **meta):
    return NdxSym(kind, value, meta)


