# pattern nome → semantica (per varianti con suffissi)
NUITKA_NAME_PATTERNS = [
    (re.compile(r'^RICH_COMPARE_(EQ|NE|LT|LE|GT|GE)_'), 'rich_compare'),
    (re.compile(r'^BINARY_OPERATION_'), 'binop'),
    (re.compile(r'^BINARY_OP_'), 'binop'),
    (re.compile(r'^COMPARE_(EQ|NE|LT|LE|GT|GE)_(.*)$'), 'compare'),

    (re.compile(r'^BUILTIN_(\w+)$'), 'builtin'),
    (re.compile(r'^CALL_FUNCTION_WITH_(SINGLE_ARG|ARGS(\d+)(_KW_SPLIT|_VECTORCALL)?)$'), 'call_function'),
    (re.compile(r'^CALL_FUNCTION_NO_ARGS$'), 'call_noargs'),
    (re.compile(r'^CALL_FUNCTION_KW_ARGS(\d+)$'), 'call_kw'),
    (re.compile(r'^CALL_METHOD_WITH_(SINGLE_ARG|ARGS(\d+))$'), 'call_method'),
    (re.compile(r'^CALL_METHOD_NO_ARGS$'), 'call_method_noargs'),
    (re.compile(r'^MAKE_FUNCTION_'), 'make_function'),
    (re.compile(r'^LIST_'), 'list_op'),
    (re.compile(r'^DICT_'), 'dict_op'),
    (re.compile(r'^TUPLE_'), 'tuple_op'),
    (re.compile(r'^SET_'), 'set_op'),
    (re.compile(r'^STRING_'), 'string_op'),
    (re.compile(r'^UNICODE_'), 'string_op'),
    (re.compile(r'^LOOKUP_SUBSCRIPT_'), 'subscript'),
    (re.compile(r'^SET_SUBSCRIPT'), 'set_subscript'),
    (re.compile(r'^ITERATOR_'), 'iterator_op'),
]


def helper_semantics(name):
    """Semantica (op, arity) per nome helper, None se sconosciuto."""
    if name in NUITKA_HELPER_SEMANTICS:
        return NUITKA_HELPER_SEMANTICS[name]
    for rx, op in NUITKA_NAME_PATTERNS:
        m = rx.match(name)
        if m:
            return (op, None)
    return None


# ---------------------------------------------------------------------------
# Helper resolver: nome helper per VA (PLT / API-reach / simboli / firme)
# ---------------------------------------------------------------------------

class HelperResolver:
    """Risolve VA → (nome, semantica) per call target, con cache."""

    def __init__(self, img, sig_db=None, ref_symbols=None):
        self.img = img
        self.sig_db = sig_db or {}
        self.ref_symbols = ref_symbols or {}
        self._by_api = {}      # api_reach frozenset -> [(nome, firma)]
        self._by_opc = {}      # opc_hash -> [(nome, firma)]
        self._cache = {}
        self._fd = FuncDisassembler(img)
        # Source-template classifier shared with the mature native engine.  It
        # identifies protocol slots and CPython API shapes without using names
        # or constants from the application being recovered.
        try:
            self._native_classifier = _NativeHelperClassifier(
                img, img.data,
                target_python=detect_python_version(img),
                function_bounds=img.function_bounds)
            # back-reference: le prove strutturali dei compositi risolvono i
            # callee con lo stesso nome/DB usato ai call site
            self._native_classifier.resolver = self
        except Exception:
            self._native_classifier = None
        if sig_db:
            for nm, raw in sig_db.items():
                # One helper may have multiple compiler/ABI implementations.
                # Preserve the legacy single-dict schema as well.
                variants = raw if isinstance(raw, list) else [raw]
                for s in variants:
                    if not isinstance(s, dict):
                        continue
                    api_key = frozenset(s.get('api_reach') or ())
                    opc_key = s.get('opc_hash')
                    entry = (nm, s)
                    if api_key:
                        self._by_api.setdefault(api_key, []).append(entry)
                    if opc_key:
                        self._by_opc.setdefault(opc_key, []).append(entry)

    def _cross_module_accessor(self, va):
        """Riconosce il getter di variabile-modulo di UN ALTRO modulo:
        ``mov rdx,[rip+NAME_SLOT]; mov rcx,[rip+DICT_SLOT];
        call GET_STRING_DICT_VALUE; test/…; mov rax,[rax]; ret``.
        Ritorna la tuple resolve ('api', marker, ('global_load', nome))
        con il nome letto dalla mappa globale slot→valore, o None."""
        cache = getattr(self, '_xmod_accessor_cache', None)
        if cache is None:
            cache = self._xmod_accessor_cache = {}
        elif va in cache:
            return cache[va]
        result = None
        insns = self._func_insns(va)
        if insns and len(insns) <= 40:
            has_gsdv = False
            rip_slots = []
            n_calls = 0
            for insn in insns:
                if insn.mnemonic == 'call':
                    n_calls += 1
                    if not insn.op_str.startswith('0x'):
                        continue
                    try:
                        t = int(insn.op_str, 16)
                    except ValueError:
                        continue
                    kind, nm, _s = self.resolve(t)
                    if nm == 'GET_STRING_DICT_VALUE':
                        has_gsdv = True
                elif insn.mnemonic in ('mov', 'movabs') and \
                        'rip' in insn.op_str and \
                        insn.op_str.startswith(('rdx', 'edx', 'rcx', 'ecx',
                                                'r8', 'r9')):
                    t = rip_target(insn)
                    if t is not None:
                        rip_slots.append(t)
            if has_gsdv and n_calls <= 2 and len(rip_slots) >= 2:
                vals = getattr(self, 'all_slot_values', None) or {}
                for slot in rip_slots:
                    name = vals.get(slot)
                    if isinstance(name, str) and name.isidentifier():
                        result = ('api', f'module_var_accessor:{name}',
                                  ('global_load', name))
                        break
        cache[va] = result
        return result

    def resolve(self, va):
        """→ (kind, name, semantics) dove kind ∈ {plt, api, symbol, sig, unknown}."""
        if va in self._cache:
            return self._cache[va]
        # Anti-cascata: la cache viene scritta SOLO al ritorno di _resolve, e
        # le regole shaped (trampolini alias, scan LOOKUP_BUILTIN) si
        # richiamano mutualmente — un ciclo A→B→A divergerebbe in ricorsione
        # infinita. Un VA già in analisi, o una catena di inseguimento più
        # profonda di ogni alias reale, si arresta qui come unknown; il
        # risultato vero viene comunque calcolato e cachato dal frame esterno.
        busy = getattr(self, '_resolving', None)
        if busy is None:
            busy = self._resolving = set()
        if va in busy or len(busy) >= 32:
            return ('unknown', f'sub_{va:x}', None)
        busy.add(va)
        try:
            r = self._resolve(va)
        finally:
            busy.discard(va)
        # pyfunc del binario: un'impl diretta non risolta dal sig-db È la
        # funzione Python sorgente (call intra-modulo) → nome vero
        if (_NDX_PYFUNC_BY_VA and (r[0] == 'unknown' or
                                   (isinstance(r[1], str) and
                                    r[1].startswith('sub_'))) and
                va in _NDX_PYFUNC_BY_VA):
            r = ('function', _NDX_PYFUNC_BY_VA[va], ('py_call', None))
        # V100 SPEED: cache anche gli unknown — un VA senza semantica
        # restava senza cache e veniva ri-risolto (walk _api_reach
        # depth-3) ad OGGI chiamata: sui binary grandi = ore.
        self._cache[va] = r
        profile = getattr(self.img, '_ndx_binary_abi', None)
        if profile is not None:
            profile.record_semantic(va, r)
        return r

    def _resolve(self, va):
        # 1) PLT → API CPython con semantica
        nm = self.img.plt_map.get(va)
        if nm:
            sem = PY_API_SEMANTICS.get(nm)
            return ('plt', nm, sem)
        # 2) GOT/IAT indirect già risolto
        nm = self.img.imports.get(va)
        if nm:
            sem = PY_API_SEMANTICS.get(nm)
            return ('plt', nm, sem)
        # Resolve an unconditional entry thunk before any classifier can
        # inspect the unrelated function laid out after its alignment bytes.
        offset = self.img.va_to_off(va)
        if offset is not None:
            first = next(self._fd.md.disasm(self.img.data[offset:offset + 16], va), None)
            if first is not None and first.mnemonic == 'jmp':
                target = branch_target(first)
                if target is None and 'rip' in first.op_str:
                    target = rip_target(first)
                if target is not None and target != va:
                    return self.resolve(target)
        # 3) simboli del binary (se presenti)
        nm = self.img.symbols.get(va)
        if nm and re.match(r'^[A-Za-z_][A-Za-z0-9_$]*$', nm):
            return ('symbol', nm, helper_semantics(nm.split('.')[0]))
        # ModuleCodeAnalyzer binds generated accessor VAs to the namespace key
        # they load.  This is direct module-initialisation evidence and must
        # outrank generic helper signatures, which can collide with the small
        # cached-dict lookup leaf used by every accessor.
        bound_accessor = getattr(self, 'accessor_names', {}).get(va)
        if isinstance(bound_accessor, str) and bound_accessor:
            return ('api', f'module_var_accessor:{bound_accessor}',
                    ('global_load', bound_accessor))
        # V100: accessor CROSS-MODULO via GET_STRING_DICT_VALUE — il getter
        # di una variabile globale di un ALTRO modulo (``config``, token
        # pool, …).  Forma: body piccolo, UNA call a
        # GET_STRING_DICT_VALUE, due letture ``mov reg,[rip+slot]`` (dict
        # del modulo proprietario + NOME della variabile dal suo pool).
        # Il nome si legge dalla mappa slot→valore di TUTTI i moduli
        # (pre-pass ``all_slot_values``): senza di questa il call restava
        # ``sub_XXX(...)`` opaco in ogni espressione che usa la globale.
        try:
            _acc = self._cross_module_accessor(va)
            if _acc is not None:
                return _acc
        except Exception:
            pass
        # 4) firma: api-reach + opcode-hash, with compiler/ABI variants.
        apis = self._api_reach(va)
        opc_h = self._opc_hash(va)
        if apis:
            entries = self._by_api.get(frozenset(apis), [])
            match = self._best_signature_match(va, entries, opc_h)
            if match is not None:
                native = self._resolve_native_template(va)
                # A generic CALL helper and BUILTIN_FORMAT can be code-folded
                # very similarly by MSVC.  The native classifier proves the
                # latter from its builtin/type protocol, so let that stronger
                # semantic shape override a colliding CALL signature.
                if native is not None and match.startswith(
                        ('CALL_FUNCTION_', 'CALL_METHOD_')) and \
                        native[1] in ('BUILTIN_FORMAT', 'CALL_VECTOR_WITH_KEYWORDS', 'CALL_FUNCTION_TUPLE_DICT'):
                    return native
                return ('sig', match, helper_semantics(match))
        if opc_h:
            entries = self._by_opc.get(opc_h, [])
            match = self._best_signature_match(va, entries, opc_h)
            if match is not None:
                native = self._resolve_native_template(va)
                if native is not None and match.startswith(
                        ('CALL_FUNCTION_', 'CALL_METHOD_')) and \
                        native[1] in ('BUILTIN_FORMAT', 'CALL_VECTOR_WITH_KEYWORDS', 'CALL_FUNCTION_TUPLE_DICT'):
                    return native
                return ('sig', match, helper_semantics(match))
        # 6) module var accessor (pattern Nuitka 4.x keys-version-cached):
        # leaf function che legge lo slot moduledict del modulo e accede la
        # dict entry via cache_dk_index. Il NOME è fornito dalla mappa
        # esterna (accessor_names) costruita dal ModuleCodeAnalyzer
        # (associazione ordinata accessor↔binding).
        acc_name = getattr(self, 'accessor_names', {}).get(va)
        if acc_name is not None:
            return ('api', f'module_var_accessor:{acc_name}',
                    ('global_load', acc_name))
        # anti-cascata locale: un accessor già in analisi NON re-analizza
        # (la catena circolare accessor→call→accessor nell'83MB è oltre
        # ogni recursion limit — il guard _resolving copre solo va identico)
        _acc_busy = getattr(self, '_accessor_busy', None)
        if _acc_busy is None:
            _acc_busy = self._accessor_busy = set()
        if va not in _acc_busy:
            _acc_busy.add(va)
            try:
                acc_name = self._module_accessor_name(va)
            finally:
                _acc_busy.discard(va)
        else:
            acc_name = None
        if acc_name is not None:
            return ('api', f'module_var_accessor:{acc_name}',
                    ('global_load', acc_name))
        # 7) regole API specializzate: SOLO se l'API è chiamata DIRETTAMENTE
        # (depth 1) — altrimenti funzioni che la usano internamente (come
        # loadConstantsBlob che crea code objects) verrebbero misclassificate.
        direct = self._direct_apis(va)
        if direct:
            if any(a.startswith('PyUnstable_Code_New') or a.startswith('PyCode_New')
                   for a in direct):
                return ('api', 'makeCodeObject', ('make_code_object', None))
            if 'PyFunction_New' in direct or 'PyFunction_NewWithQualname' in direct:
                return ('api', 'make_pyfunction', ('make_function', None))
            # Nuitka IMPORT_NAME_OR_MODULE(tstate, module, globals, name,
            # level): the combined ``from M import n`` helper —
            # PyObject_GetAttr with an AttributeError/level fallback that
            # re-imports the module and re-looks the name up via
            # sys.modules.  The direct-API quartet (attribute + PyLong
            # level parse + module-name read + "%s.%S" format) is exactly
            # its own template shape; IMPORT_NAME_FROM_MODULE differs by
            # its PyModule_GetFilenameObject error path and no PyLong.
            if {'PyObject_GetAttr', 'PyLong_AsLong', 'PyModule_GetName',
                'PyUnicode_FromFormat'} <= set(direct) and \
                    'PyModule_GetFilenameObject' not in direct:
                return ('api', 'IMPORT_NAME_OR_MODULE',
                        ('import_from_or_module', None))
        # Structural proof must precede the weak single-API fallback: a helper
        # can reach PyErr_Format exclusively through a cold failure branch.
        # NOTA: un verdetto 'unknown' del classifier NON è una prova — deve
        # far proseguire verso le regole shaped del runtime outlined, che
        # altrimenti non verrebbero mai raggiunte.
        native = self._resolve_native_template(va)
        if native is not None and native[0] != 'unknown':
            return native
        # Regole API-REACH universali (senza simboli/firme): famiglie di
        # helper Nuitka identificate dalle C-API che raggiungono.
        if apis:
            # CALL dispatcher generico: PyEval_GetFuncName serve SOLO al
            # messaggio "object is not callable" dei CALL_FUNCTION_*.
            if 'PyEval_GetFuncName' in apis and                     '_PyType_Lookup' not in apis:
                return ('api', 'CALL_FUNCTION_GENERIC',
                        ('call_function', -1))
            # BUILTIN_RANGE: calcola start/stop/step con aritmetica
            # PyNumber_* (incl. Negative per -step) e formatta errori.
            if {'PyNumber_Negative', 'PyNumber_Add'} <= apis and                     'PyErr_Format' in apis and                     not any(a.startswith('PyDict') or
                            a.startswith('PyList') or
                            a == 'PyEval_GetFuncName' for a in apis):
                return ('api', 'BUILTIN_RANGE', ('range', -1))
            # BUILTIN_LIST(x)/LIST_EXTEND: PyObject_LengthHint presize
            # l'iterabile e il loop fa append. LengthHint è specifico della
            # costruzione di sequenze da iterabile (list/tuple/sorted);
            # sorted porta anche PyEval_GetFuncName (classificato prima).
            if 'PyObject_LengthHint' in apis and                     'PyList_Append' in apis and                     'PyEval_GetFuncName' not in apis:
                return ('api', 'BUILTIN_LIST', ('list', 1))
        # ---- forme outlined di GCC (universal: shape del corpo) ----
        # Trampolino/alias: la PRIMA istruzione reale è un `jmp target`
        # (alias di export/ICF; il disasm lineare prosegue oltre il jmp
        # con codice di funzioni adiacenti, va ignorato).
        try:
            leaf_insns = self._func_insns(va)
        except Exception:
            leaf_insns = []
        real_insns = [i for i in leaf_insns
                      if i.mnemonic not in ('int3', 'nop', 'endbr64')]
        if real_insns and real_insns[0].mnemonic == 'jmp' and \
                real_insns[0].op_str.startswith('0x'):
            try:
                alias_target = int(real_insns[0].op_str, 16)
            except ValueError:
                alias_target = None
            if alias_target is not None and alias_target != va:
                kind_a, name_a, sem_a = self._resolve(alias_target)
                if name_a and not str(name_a).startswith('sub_'):
                    return (kind_a, name_a, sem_a)
        if real_insns and real_insns[-1].mnemonic == 'jmp' and \
                not any(item.mnemonic == 'ret' for item in real_insns):
            terminal = is_imm(real_insns[-1].op_str)
            local_addresses = {item.address for item in real_insns}
            external_jumps = {is_imm(item.op_str) for item in real_insns
                              if item.mnemonic.startswith('j') and
                              is_imm(item.op_str) not in local_addresses}
            if terminal is not None and external_jumps == {terminal}:
                _kind, target_name, _sem = self.resolve(terminal)
                if target_name == 'RUNTIME_ALLOC_compiled_frame':
                    return ('native', 'MAKE_FUNCTION_FRAME', None)
        # Thunk incref: `inc qword ptr [rX]` + ret — puro machinery.
        if 0 < len(real_insns) <= 4 and any(
                i.mnemonic == 'inc' and 'qword ptr [r' in i.op_str
                for i in real_insns):
            return ('api', 'REFCOUNT_RELEASE_SLOT', None)
        # Dispatch tp_dealloc outlined: tra le PRIME istruzioni, carica
        # [obj/type + 0x30] e tail-jmp al destructor (il disasm lineare
        # prosegue con codice adiacente) — machinery.
        head = real_insns[:4]
        if len(head) >= 3 and head[-1].mnemonic == 'jmp' and \
                head[-1].op_str.strip() in ('rdx', 'rax', 'rcx') and \
                any('+ 0x30]' in i.op_str and i.mnemonic == 'mov'
                    for i in head[:-1]):
            return ('api', 'REFCOUNT_RELEASE_SLOT', None)
        # LOOKUP_BUILTIN outlined: il corpo chiama UNA volta una funzione
        # che risolve a global_lookup/GET_STRING_DICT_VALUE (lettura del
        # dizionario builtins) e dereferenzia il valore: lookup di un
        # builtin per nome costante.
        # Una LOOKUP_BUILTIN outlined è una leaf piccola per costruzione
        # (~20-30 insn su MinGW): escludere subito i corpi lunghi evita di
        # risolvere ricorsivamente ogni call di ogni funzione grande.
        if real_insns and len(real_insns) <= 96:
            lookup_calls = []
            for i in real_insns:
                if i.mnemonic == 'call' and i.op_str.startswith('0x'):
                    try:
                        ct = int(i.op_str, 16)
                    except ValueError:
                        continue
                    _ck, cnm, cs = self.resolve(ct)
                    if cnm == 'GET_STRING_DICT_VALUE' or (
                            cs and cs[0] == 'global_lookup'):
                        lookup_calls.append(ct)
            if len(lookup_calls) == 1 and any(
                    i.mnemonic == 'mov' and
                    re.match(r'^r\w+, qword ptr \[rax\]$', i.op_str)
                    for i in real_insns):
                return ('api', 'LOOKUP_BUILTIN', ('lookup_builtin', 1))
        # PyObject_Str outlined: dispatch dello slot tp_str ([rax+0xe0])
        # con formattazione dell'errore via PyUnicode_FromFormat.
        if apis == {'PyUnicode_FromFormat'} and any(
                i.mnemonic == 'mov' and '+ 0xe0]' in i.op_str
                for i in real_insns):
            return ('plt', 'PyObject_Str', PY_API_SEMANTICS.get(
                'PyObject_Str'))
        # Thunk di rilascio refcount: leaf senza call dirette, pattern
        # decref (`sub qword [rX], 1`) + dispatch tp_dealloc (tail
        # call/jmp su registro), poche istruzioni. Puro machinery.
        if 0 < len(real_insns) <= 20:
            has_decref = any(
                i.mnemonic == 'sub' and 'qword ptr [r' in i.op_str and
                i.op_str.endswith(', 1') for i in real_insns)
            has_tail_dispatch = any(
                i.mnemonic in ('jmp', 'call') and
                i.op_str.strip() in ('rdx', 'rax', 'rcx', 'r8', 'r9')
                for i in real_insns)
            has_direct_call = any(
                i.mnemonic == 'call' and i.op_str.startswith('0x')
                for i in real_insns)
            if has_decref and has_tail_dispatch and not has_direct_call:
                return ('api', 'REFCOUNT_RELEASE_SLOT', None)
        # Concatenazione liste outlined: somma gli ob_size di DUE
        # argomenti (`mov r, [reg+0x10]; add r, [reg2+0x10]`) e alloca
        # (reach = solo GC_Malloc + PyErr_NoMemory).
        if apis == {'_PyObject_GC_Malloc', 'PyErr_NoMemory'}:
            size_loads = [i for i in real_insns
                          if i.mnemonic == 'mov' and
                          re.match(r'^r\w+, qword ptr \[r\w+ \+ 0x10\]$',
                                   i.op_str)]
            has_size_add = any(
                i.mnemonic == 'add' and
                'qword ptr [r' in i.op_str and '+ 0x10]' in i.op_str
                for i in leaf_insns)
            if size_loads and has_size_add:
                return ('api', 'LIST_CONCAT', ('binop_list', 2))
            # Factory di small-int outlined: load della struttura cache dal
            # primo arg ([rcx+0x10]), bound-check `cmp reg, imm` + jge, e
            # indexing per-valore [base + reg*8 + disp]; il cold path alloca
            # l'oggetto nuovo. È il lowering nativo di una COSTANTE intera.
            has_scaled_cache = any(
                i.mnemonic == 'mov' and
                re.search(r'\[\w+ \+ \w+\*8 \+ 0x[0-9a-f]+\]', i.op_str)
                for i in real_insns)
            has_imm_bound = any(
                i.mnemonic == 'cmp' and
                re.match(r'^r\w+, 0x[0-9a-f]+$', i.op_str)
                for i in real_insns)
            if has_scaled_cache and has_imm_bound:
                return ('api', 'SMALL_INT_FACTORY', ('const_int', 1))
        # ---- regole shape universali del runtime outlined (MinGW/GCC) ----
        # GIL wrapper: racchiude rilascio/acquisizione GIL e pending calls
        # attorno a un'operazione nativa — pura sincronizzazione, non
        # sorgente.
        if direct and direct <= {'PyEval_AcquireThread',
                                 'PyEval_SaveThread',
                                 'Py_MakePendingCalls'} and \
                len(direct) >= 2:
            return ('api', 'GIL_WRAPPER', None)
        # str() outlined con fast-path identity: exact-type PyUnicode_Type
        # + _PyUnicode_Ready + incref-self; il cold path è il tail-jmp
        # IAT a PyObject_Repr (dispatch tp_str) → ``str(x)``.
        if '_PyUnicode_Ready' in direct:
            _tail_repr = False
            for i in real_insns:
                if i.mnemonic == 'jmp' and 'rip' in i.op_str:
                    t = rip_target(i)
                    if t is not None and self.img.imports.get(t) == \
                            'PyObject_Repr':
                        _tail_repr = True
                        break
            if _tail_repr:
                return ('plt', 'PyObject_Str',
                        PY_API_SEMANTICS.get('PyObject_Str'))
        # Concatenazione unicode outlined: due _PyUnicode_Ready (uno per
        # operando) + i fast-path "operando == stringa vuota → incref
        # dell'altro e ritornalo" → ``a + b``.
        if '_PyUnicode_Ready' in direct and 'PyUnicode_New' in direct:
            return ('api', 'UNICODE_CONCAT', ('binop_str', 2))
        # Chiamata con keyword arguments: costruisce il dict kwargs
        # (_PyDict_NewPresized + PyDict_SetItem) e invoca il callable →
        # ``f(k1=v1, k2=v2, …)``; le chiavi sono l'ultima tupla const.
        if '_PyDict_NewPresized' in direct and 'PyDict_SetItem' in direct \
                and 'PyUnicode_AsUTF8' in apis:
            return ('api', 'CALL_WITH_KWARGS', ('call_kwargs', -1))
        # Append in-place su stringa (builder di Nuitka): exact-type check
        # su PyUnicode_Type + refcount==1 + Realloc dell'area dati. Il
        # valore accumulato viene letto da una lettura successiva →
        # machinery, non sorgente.
        if 'PyUnicode_New' in apis and 'PyObject_Realloc' in apis and any(
                i.mnemonic == 'cmp' and re.match(
                    r'^qword ptr \[r\w+\], 1$', i.op_str)
                for i in real_insns):
            return ('api', 'STR_INPLACE_APPEND', None)
        # Allocatore di oggetti del runtime via tp_name statico: la
        # `lea reg, [rip+X]` referenzia il PyTypeObject dell'oggetto
        # costruito e [X+0x18] è tp_name. Closure cell, frame, generatori,
        # traceback… non hanno controparte sorgente.
        rtp = self._runtime_tp_name(va, real_insns)
        if rtp is not None:
            return ('api', f'RUNTIME_ALLOC_{rtp}', None)
        # Dispatch di slot outlined (tp_iternext/tp_dealloc/tp_call…):
        # load del tipo/campo + tail-jmp su registro, NESSUNA call ad
        # indirizzo prima (le call su registro SONO dispatch dealloc).
        if real_insns and len(real_insns) <= 40 and not any(
                i.mnemonic == 'call' and i.op_str.startswith('0x')
                for i in real_insns[:6]):
            for k, i in enumerate(real_insns[:6]):
                if i.mnemonic == 'jmp' and i.op_str.strip() in (
                        'rax', 'rbx', 'rcx', 'rdx', 'rsi', 'rdi',
                        'r8', 'r9', 'r10', 'r11'):
                    if any(re.search(r'\+ 0x[0-9a-f]+\]', p.op_str)
                           for p in real_insns[:k]):
                        return ('api', 'SLOT_DISPATCH', None)
                    break
        # Swap di stato su struct (exc_info del tstate): ≥4 accessi a
        # offset alti dello stesso registro-base, zero call ad indirizzo
        # (le call su registro sono i dispatch dealloc inline) — machinery.
        if real_insns and len(real_insns) <= 40 and not any(
                i.mnemonic == 'call' and i.op_str.startswith('0x')
                for i in real_insns):
            _offs = [int(m.group(1), 16) for i in real_insns
                     for m in [re.search(r'\[rcx \+ (0x[0-9a-f]+)\]',
                                         i.op_str)] if m]
            if sum(1 for o in _offs if o >= 0x40) >= 4:
                return ('api', 'STATE_SWAP', None)
        # PyNumber_<op> outlined: legge tp_as_number ([type+0x60]) e il
        # numerico slot; l'OFFSET è l'identità dell'operatore (layout
        # PyNumberMethods stabile di CPython).
        _nb_slot = self._outlined_number_slot(va)
        if _nb_slot is not None:
            return ('api', f'PyNumber_{_nb_slot}_outlined', ('binop', _nb_slot))
        # A PyLong allocator and signed branches do not identify an operator:
        # addition, subtraction and conversions all contain those operations.
        # Rich-compare outlined: il fallback generico carica lo slot
        # tp_richcompare ([type+0xc8]) e passa l'operatore Py_LT..Py_GE
        # in r8d — l'imm NE determina il confronto (enum CPython stabile).
        if 'PyErr_Format' in direct:
            _rc_imm = None
            for i in real_insns:
                m = re.match(r'^r8d?, (0x[0-5]|[0-5])$', i.op_str)
                if i.mnemonic == 'mov' and m:
                    _rc_imm = int(m.group(1), 0)
                    break
            if _rc_imm is not None and any(
                    i.mnemonic == 'mov' and '+ 0xc8]' in i.op_str
                    for i in real_insns):
                _RC = {0: 'lt', 1: 'le', 2: 'eq', 3: 'ne', 4: 'gt',
                       5: 'ge'}
                return ('api', 'RICH_COMPARE_' + _RC[_rc_imm].upper(),
                        ('cmp', _RC[_rc_imm]))
        # GET_ITER outlined: dispatch tp_iter ([type+0xd8]) — machinery
        # del for-loop, l'iteratore non è sorgente.
        if '_PyObject_GC_Malloc' in apis and any(
                i.mnemonic == 'mov' and '+ 0xd8]' in i.op_str
                for i in real_insns[:12]) and not (
                    direct - {'_PyObject_GC_Malloc', 'PyErr_NoMemory'}):
            return ('api', 'GET_ITER_FUNC', None)
        # list.reverse() outlined: leaf senza call che scambia ob_item
        # alle due estremità (indexing [base + idx*8] + confronto tra
        # primo e ultimo puntatore) → metodo in-place sulla lista.
        if not apis and not direct and len(real_insns) <= 26 and any(
                i.mnemonic == 'lea' and re.search(
                    r'\[r\w+ \+ r\w+\*8\]', i.op_str)
                for i in real_insns) and any(
                i.mnemonic == 'mov' and
                re.match(r'^rdx, qword ptr \[rcx \+ 0x10\]$', i.op_str)
                for i in real_insns[:6]):
            return ('api', 'LIST_REVERSE', ('method_reverse', 1))
        # Inizializzazione di una struct runtime sullo stack: ≥4 store a
        # offset negativi dello stesso registro-base + chiamata al
        # costruttore. Se la struct porta una PyMethodDef leggibile in
        # .rdata (nome+impl), è la MAKE_FUNCTION outlined di MinGW: il
        # NOME del metodo è il primo qword puntato dalla lea finale.
        if len(real_insns) <= 26 and not direct and sum(
                1 for i in real_insns if i.mnemonic == 'mov' and
                re.search(r'\[r1[01] \- 0x[0-9a-f]+\]', i.op_str)) >= 4:
            _fn_name = self._methoddef_name(real_insns)
            if _fn_name:
                return ('api', f'MAKE_FUNCTION:{_fn_name}',
                        ('make_function', 1))
            return ('api', 'RUNTIME_STRUCT_INIT', None)
        # MAKE_LIST_EMPTY: the official runtime initialises one PyListObject
        # by writing ob_item (+0x18) and the same requested size to ob_size
        # (+0x10) and allocated (+0x20).  This complete layout is stronger
        # than the large-offset freelist access below, which the allocator
        # also happens to contain on Python builds with a per-interpreter
        # list freelist.
        list_fields = defaultdict(lambda: defaultdict(set))
        for item in real_insns:
            operands = split_ops(item.op_str)
            if item.mnemonic != 'mov' or len(operands) != 2:
                continue
            memory = parse_mem(operands[0])
            if memory and memory[0] and memory[2] is None and \
                    memory[1] in (0x10, 0x18, 0x20):
                list_fields[memory[0]][memory[1]].add(
                    subreg64(operands[1]) or operands[1])
        for fields in list_fields.values():
            if 'rax' in fields.get(0x18, ()) and \
                    fields.get(0x10, set()) & fields.get(0x20, set()) and \
                    ('_PyObject_GC_Malloc' in apis or any(
                        self.img.imports.get(rip_target(ins)) == 'PyList_Type'
                        for ins in real_insns if ins.mnemonic == 'mov' and
                        'rip' in ins.op_str)):
                return ('api', 'MAKE_LIST_EMPTY', ('list_empty', 1))

        # Loader dell'array delle costanti di Nuitka 2.x: indicizzato per
        # posizione dal runtime ([X+0x2xxx]) e materializza liste/tuple
        # di costanti — il valore appartiene al blob, non al codice.
        if '_PyObject_GC_Malloc' in apis and any(
                i.mnemonic == 'movsxd' and re.search(
                    r'\[r\w+ \+ 0x[1-9a-f][0-9a-f]{3,}\]', i.op_str)
                for i in real_insns[:12]):
            return ('api', 'CONST_LIST_LOAD', None)
        # Cleanup di un campo di un oggetto runtime (chiusura generatore):
        # load del campo, NULL-out, dealloc — machinery.
        if not direct and not apis and len(real_insns) <= 40 and any(
                i.mnemonic == 'mov' and re.match(
                    r'^qword ptr \[r\w+ \+ 0x[0-9a-f]+\], 0$', i.op_str)
                for i in real_insns):
            return ('api', 'RUNTIME_FIELD_CLEAR', None)
        # Exception-match outlined (except clause): legge l'eccezione
        # corrente dal tstate ([rcx+0x70]) e prova la classe con
        # PyObject_IsSubclass + normalizzazione — machinery dell'handler.
        if 'PyObject_IsSubclass' in apis and (
                '_PyErr_NormalizeException' in apis or
                'PyErr_Format' in apis) and any(
                i.mnemonic == 'mov' and
                re.match(r'^r\w+, qword ptr \[rcx \+ 0x70\]$', i.op_str)
                for i in real_insns[:10]):
            return ('api', 'EXCEPTION_MATCH', None)
        if apis == {'PyErr_NoMemory'} and len(real_insns) <= 160:
            items = self._list_constructor_shape(va)
            if items is not None:
                return ('native', 'MAKE_LIST_FROM_ARGS', ('list_from_args', items))
        # Append a un builder interno: leaf che raggiunge SOLO
        # PyErr_NoMemory e delega a un grow-buffer ([obj+0x10] size dopo
        # capacity check [obj+0x20]) — transport dell'accumulatore del
        # lowering, non sorgente.
        if apis == {'PyErr_NoMemory'} and 0 < len(real_insns) <= 32 and \
                any(i.mnemonic == 'call' and i.op_str.startswith('0x')
                    for i in real_insns):
            return ('api', 'BUILDER_APPEND', None)
        # Carichi IAT (tipi/espressioni d'errore: prove non-call).
        _iat = set()
        for i in real_insns:
            if i.mnemonic == 'mov' and 'rip' in i.op_str:
                _t2 = rip_target(i)
                _nm2 = self.img.imports.get(_t2) if _t2 is not None else None
                if _nm2:
                    _iat.add(_nm2)
        # list + list wrapper: exact-type PyList_Type e delega al concat
        # puro → ``a + b``.
        if 'PyList_Type' in _iat:
            for i in real_insns[:16]:
                if i.mnemonic == 'call' and i.op_str.startswith('0x'):
                    try:
                        _k2, _n2, _s2 = self.resolve(int(i.op_str, 16))
                    except ValueError:
                        break
                    if _n2 == 'LIST_CONCAT':
                        return ('api', 'LIST_CONCAT', ('binop_list', 2))
                    break
        # CALL dispatch outlined: load tp_call ([type+0x80]) + errore
        # "'X' object is not callable" (PyExc_TypeError) → chiamata
        # generica con argomenti espansi.
        if 'PyExc_TypeError' in _iat and any(
                i.mnemonic == 'mov' and '+ 0x80]' in i.op_str
                for i in real_insns[:12]):
            return ('api', 'CALL_FUNCTION_GENERIC', ('call_function', -1))
        # TrueDivide outlined: exact-type PyFloat_Type + confronto SSE col
        # divisore 0.0 (ucomisd) → ``a / b``.
        if 'PyFloat_Type' in _iat and any(
                i.mnemonic == 'ucomisd' for i in real_insns[:12]):
            return ('api', 'PyNumber_TrueDivide_outlined', ('binop', '/'))
        if len(apis) == 1:
            only = next(iter(apis))
            sem = PY_API_SEMANTICS.get(only)
            if sem:
                return ('api', f'via:{only}', sem)
        # Inlined/ICF-merged CPython object-protocol helpers that the
        # signature hashes and the slot provers missed.  Both rules rest on
        # the CPython API surface only: the helper's complete imported-API
        # set is the fingerprint.
        #  * ``len(x)`` — PyObject_Size inlined: length-slot dispatches are
        #    indirect calls and never appear in the IAT set, so the only
        #    Python interactions are wrapping the C ssize_t result into an
        #    int (tail PyLong_FromSsize_t) plus the unsized-object error arm
        #    (PyErr_Format/PyExc_TypeError).
        #  * ``a + b`` on str — PyUnicode_Concat inlined: readies both
        #    operands (_PyUnicode_Ready) and copies the buffers
        #    (memcpy/memmove).  Any numeric, formatting, container or call
        #    API excludes it (repeat, %, slicing, join all need those).
        _libc_only = set((
            'memcpy', 'memmove', 'memset', 'strlen', 'strcmp', 'strcpy',
            'strncmp', 'strncpy', 'wcscmp', 'wcsncmp', 'terminate'))
        _py_apis = {n for n in apis if n.startswith(('Py', '_Py'))}
        # Non-Py imports (CRT internals reachable via unwind/putil tables)
        # carry no Python semantics and are ignored on purpose; the Py*
        # subset is the fingerprint.
        if 'PyLong_FromSsize_t' in _py_apis and \
                _py_apis <= {'PyLong_FromSsize_t', 'PyErr_Format',
                             'PyErr_NoMemory', 'PyExc_TypeError'} and \
                len(real_insns) <= 120:
            return ('api', 'via:PyObject_Size',
                    PY_API_SEMANTICS.get('PyObject_Size'))
        if '_PyUnicode_Ready' in _py_apis and \
                ('memcpy' in apis or 'memmove' in apis) and \
                _py_apis <= {'_PyUnicode_Ready', 'PyUnicode_FromString',
                             'PyErr_NoMemory'}:
            # Over-followed API scans pick _PyUnicode_Ready up from
            # neighbouring blocks; the concat helper readies its operands
            # almost immediately and owns a substantial body (operand
            # readying + buffer copy + error arm).
            _dmap = {}
            if self._native_classifier is not None:
                try:
                    _dmap = self._native_classifier.collect_apis(va)
                except Exception:
                    _dmap = {}
            _fb = self.img.function_bounds(va)
            if _dmap.get('_PyUnicode_Ready', 9) <= 1 and (
                    _fb is None or (_fb[1] - _fb[0]) >= 0x140):
                return ('api', 'via:PyUnicode_Concat',
                        PY_API_SEMANTICS.get('PyUnicode_Concat'))
        return ('unknown', f'sub_{va:x}', None)

    def _best_signature_match(self, va, entries, opc_h):
        """Select a unique structural signature match, or decline safely."""
        if not entries:
            return None
        insns = self._func_insns(va)
        observed = {
            'opc_hash': opc_h,
            'opc_len': len(insns),
            'ncalls': sum(i.mnemonic == 'call' for i in insns),
            'api_direct': frozenset(self._direct_apis(va)),
        }
        # Firme cross-compilatore: una voce con opc_hash definito che NON
        # corrisponde all'osservato descrive un'altra toolchain (es. voce
        # MSVC su un binary MinGW) e i punteggi soft (ncalls/api_direct)
        # collidono per caso. La voce va scartata: restano le voci senza
        # hash (generiche) e quelle con hash confermato.
        if opc_h:
            entries = [(nm, sig) for nm, sig in entries
                       if not (sig.get('opc_hash') and
                               sig.get('opc_hash') != opc_h)]
            if not entries:
                return None
        ranked = []
        for nm, sig in entries:
            score = 0
            evidence = 0
            if sig.get('opc_hash') and sig.get('opc_hash') == observed['opc_hash']:
                score += 16
                evidence += 1
            if isinstance(sig.get('opc_len'), int):
                delta = abs(sig['opc_len'] - observed['opc_len'])
                if delta == 0:
                    score += 5
                    evidence += 1
                elif delta <= 2:
                    score += 2
            if isinstance(sig.get('ncalls'), int) and \
                    sig['ncalls'] == observed['ncalls']:
                score += 4
                evidence += 1
            if 'api_direct' in sig:
                expected = frozenset(sig.get('api_direct') or ())
                if expected == observed['api_direct']:
                    score += 6
                    evidence += 1
            ranked.append((score, evidence, nm))
        ranked.sort(reverse=True)
        best = ranked[0]
        # API closure alone is unsafe when several helpers collide.
        if best[1] == 0:
            return entries[0][0] if len(entries) == 1 else None
        ties = {x[2] for x in ranked if x[:2] == best[:2]}
        return best[2] if len(ties) == 1 else None

    @staticmethod
    def _native_binop_name(op):
        if isinstance(op, tuple):
            op = op[0] if op else None
        words = {
            '+': 'ADD', '-': 'SUBTRACT', '*': 'MULTIPLY',
            '/': 'TRUEDIV', '//': 'FLOORDIV', '%': 'REMAINDER',
            '**': 'POWER', '<<': 'LSHIFT', '>>': 'RSHIFT',
            '&': 'BITAND', '|': 'BITOR', '^': 'BITXOR',
            '@': 'MATRIX_MULTIPLY',
        }
        word = words.get(op)
        return f'BINARY_OPERATION_{word}' if word else None

    def _outlined_number_slot(self, va):
        """Require object -> ob_type -> tp_as_number -> invoked numeric slot.

        Adjacent loads at 0x60/0x68 also occur in exception-state helpers;
        offsets alone are not evidence for arithmetic.
        """
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        registers = {reg: ('object', i) for i, reg in enumerate(abi.arg_regs)}
        operators = {0: '+', 8: '-', 0x10: '*', 0x18: '%',
                     0x58: '<<', 0x60: '>>', 0x68: '&', 0x70: '^', 0x78: '|'}
        invoked = set()
        for ins in self._func_insns(va):
            operands = split_ops(ins.op_str)
            if ins.mnemonic in ('call', 'jmp') and operands:
                value = registers.get(subreg64(operands[0]))
                memory = parse_mem(operands[0])
                if memory and memory[2] is None and registers.get(memory[0], (None,))[0] == 'number':
                    value = ('slot', memory[1])
                if value and value[0] == 'slot' and value[1] in operators:
                    invoked.add(operators[value[1]])
                if ins.mnemonic == 'call':
                    for reg in abi.caller_saved:
                        registers.pop(reg, None)
            elif len(operands) == 2 and subreg64(operands[0]):
                dst = subreg64(operands[0])
                value = registers.get(subreg64(operands[1]))
                memory = parse_mem(operands[1])
                if ins.mnemonic == 'mov' and memory and memory[2] is None:
                    base = registers.get(memory[0], (None,))
                    value = None
                    if base[0] == 'object' and memory[1] == 8:
                        value = ('type', base[1])
                    elif base[0] == 'type' and memory[1] == 0x60:
                        value = ('number', base[1])
                    elif base[0] == 'number':
                        value = ('slot', memory[1])
                if ins.mnemonic == 'mov' and value:
                    registers[dst] = value
                elif ins.mnemonic not in ('cmp', 'test'):
                    registers.pop(dst, None)
        return next(iter(invoked)) if len(invoked) == 1 else None

    def _native_inplace_binop_name(self, va):
        """Identify Nuitka's ``PyObject **`` in-place binary helpers.

        Their ABI is structurally different from an ordinary binary helper:
        argument zero is dereferenced to obtain the left ``PyObject *``, that
        object is used for type/number-slot dispatch, and a result pointer is
        written back through the original argument-zero alias.  Detecting the
        pointer round-trip prevents an INPLACE_OPERATION helper from being
        misclassified as the binary operation it invokes internally.
        """
        try:
            insns = self._func_insns(va)
            abi = abi_for(self.img.fmt, detect_python_version(self.img))
        except Exception:
            return None
        if not insns or not abi.arg_regs:
            return None
        pointer_aliases = {abi.arg_regs[0]}
        object_aliases = set()
        loaded_object = False
        used_object_type = False
        wrote_pointer = False
        for item in insns[:240]:
            operands = split_ops(item.op_str)
            if len(operands) != 2:
                continue
            destination_register = subreg64(operands[0])
            source_register = subreg64(operands[1])
            source_memory = parse_mem(operands[1])
            destination_memory = parse_mem(operands[0])
            old_pointers = set(pointer_aliases)
            old_objects = set(object_aliases)
            if item.mnemonic == 'mov' and destination_register:
                pointer_aliases.discard(destination_register)
                object_aliases.discard(destination_register)
                if source_register in old_pointers:
                    pointer_aliases.add(destination_register)
                elif source_register in old_objects:
                    object_aliases.add(destination_register)
                elif source_memory and source_memory[2] is None and \
                        source_memory[0] in old_pointers and \
                        source_memory[1] == 0:
                    object_aliases.add(destination_register)
                    loaded_object = True
                elif source_memory and source_memory[2] is None and \
                        source_memory[0] in old_objects and \
                        source_memory[1] == abi.ob_type:
                    used_object_type = True
            if item.mnemonic == 'mov' and destination_memory and \
                    destination_memory[2] is None and \
                    destination_memory[0] in pointer_aliases and \
                    destination_memory[1] == 0 and \
                    source_register is not None:
                wrote_pointer = True
        if not (loaded_object and used_object_type and wrote_pointer):
            return None
        try:
            detail = self._native_classifier._binop_slot(va)
            if detail is None and \
                    self._native_classifier._str_concat_helper(va) is not None:
                detail = ('+', None)
        except Exception:
            detail = None
        operator = detail[0] if isinstance(detail, tuple) and detail else None
        words = {
            '+': 'ADD', '-': 'SUB', '*': 'MULT', '/': 'TRUEDIV',
            '//': 'FLOORDIV', '%': 'MOD', '<<': 'LSHIFT',
            '>>': 'RSHIFT', '&': 'AND', '|': 'OR', '^': 'XOR',
        }
        word = words.get(operator)
        return f'INPLACE_OPERATION_{word}' if word else None

    def _specialized_number_fallback(self, va):
        """Read a PyLong specialization's generic fallback after its type guard."""
        body = self._func_insns(va)
        if not body or len(body) > 600:
            return None
        by = {item.address: item for item in body}
        type_registers = set()
        for index, item in enumerate(body[:18]):
            operands = split_ops(item.op_str)
            if item.mnemonic == 'mov' and len(operands) == 2 and \
                    self.img.imports.get(rip_target(item)) == 'PyLong_Type':
                type_registers.add(subreg64(operands[0]))
            if item.mnemonic != 'cmp' or len(operands) != 2 or \
                    subreg64(operands[1]) not in type_registers:
                continue
            memory = parse_mem(operands[0])
            if memory is None or memory[0] not in ('rcx', 'rdx') or \
                    memory[1:] != (8, None, 1) or index + 1 >= len(body):
                continue
            branch = body[index + 1]
            if branch.mnemonic not in ('jne', 'jnz'):
                continue
            address = branch_target(branch)
            for _ in range(8):
                tail = by.get(address)
                if tail is None:
                    break
                if tail.mnemonic == 'jmp':
                    target = branch_target(tail)
                    if target is not None and target not in by and target != va:
                        result = self.resolve(target)
                        if result[2] and result[2][0] == 'binop':
                            return result
                    break
                operands = split_ops(tail.op_str)
                if tail.mnemonic != 'add' or not operands or operands[0] != 'rsp':
                    break
                address += tail.size
        return None

    def _fixed_argument_array_shape(self, va):
        """Prove the array arity of a compiled-function fast dispatcher."""
        instructions = self._func_insns(va)
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        aliases = {register: ('arg', index) for index, register in enumerate(abi.arg_regs)}
        counts = set()
        offsets = set()
        for item in instructions[:100]:
            operands = split_ops(item.op_str)
            if item.mnemonic == 'call':
                tag = aliases.get(subreg64(item.op_str))
                if tag == ('field', 1, 0x78) and len(counts) == 1:
                    count = next(iter(counts))
                    if offsets == set(range(0, count * 8, 8)):
                        return count
                return None
            if len(operands) != 2:
                continue
            destination, source = operands
            register = subreg64(destination)
            if item.mnemonic == 'cmp' and aliases.get(register) == ('field', 1, 0x40):
                count = is_imm(source)
                if count is not None and 0 <= count <= 1024:
                    counts.add(count)
            if item.mnemonic != 'mov' or not register:
                continue
            inherited = aliases.get(subreg64(source))
            memory = parse_mem(source)
            if memory and not memory[2]:
                origin = aliases.get(memory[0])
                if origin == ('arg', 1):
                    inherited = ('field', 1, memory[1])
                elif origin == ('arg', 2):
                    offsets.add(memory[1])
            aliases.pop(register, None)
            if inherited is not None:
                aliases[register] = inherited
        return None

    def _positional_tuple_call_shape(self, va):
        """Return the fixed positional arity of a proven CALL dispatcher.

        Nuitka's ``CALL_FUNCTION_WITH_POS_ARGS<n>`` consumes ``tstate``, a
        callable, and a tuple whose item array begins at the public tuple
        payload offset.  Compiled-function fast paths additionally compare
        the callable's declared positional count and dispatch through its
        code pointer.  Requiring the complete chain prevents the tuple-payload
        access from being confused with attribute helpers that happen to use
        one of the same structure offsets in a cold path.
        """
        try:
            insns = self._func_insns(va)
        except Exception:
            return None
        if not insns or len(insns) > 4000:
            return None
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        if len(abi.arg_regs) < 3:
            return None
        callable_reg = abi.arg_regs[1]
        tuple_reg = abi.arg_regs[2]
        head = [item for item in insns[:80]
                if item.mnemonic not in ('nop', 'int3', 'endbr64')]
        callable_aliases = {callable_reg}
        tuple_aliases = {tuple_reg}
        for item in head:
            operands = split_ops(item.op_str)
            if item.mnemonic != 'mov' or len(operands) != 2:
                continue
            destination = subreg64(operands[0])
            source = subreg64(operands[1])
            if destination and source in callable_aliases:
                callable_aliases.add(destination)
            if destination and source in tuple_aliases:
                tuple_aliases.add(destination)
        has_callable_type = any(
            item.mnemonic == 'mov' and len(split_ops(item.op_str)) == 2 and
            (lambda memory: memory is not None and
             memory[0] in callable_aliases and memory[1] == 8 and
             memory[2] is None)(parse_mem(split_ops(item.op_str)[1]))
            for item in head)
        has_tuple_items = False
        for item in head:
            operands = split_ops(item.op_str)
            if len(operands) != 2:
                continue
            memory = parse_mem(operands[1])
            if item.mnemonic in ('mov', 'lea') and memory and \
                    memory[0] in tuple_aliases and \
                    memory[1] in (0x18, 0x20) and memory[2] is None:
                has_tuple_items = True
                break
            if item.mnemonic == 'add' and \
                    subreg64(operands[0]) in tuple_aliases and \
                    is_imm(operands[1]) == 0x18:
                has_tuple_items = True
                break
        if not (has_callable_type and has_tuple_items):
            return None

        # Follow the register loaded from Nuitka_FunctionObject.m_args_simple
        # / parameter-count field and find the fixed count it is checked
        # against.  The field offset belongs to the generated runtime object;
        # the proof also requires its executable code-pointer dispatch below.
        count_regs = set()
        for item in head:
            operands = split_ops(item.op_str)
            if item.mnemonic != 'mov' or len(operands) != 2:
                continue
            destination = subreg64(operands[0])
            memory = parse_mem(operands[1])
            if destination and memory and memory[0] in callable_aliases and \
                    memory[1] == 0x40 and memory[2] is None:
                count_regs.add(destination)
        counts = set()
        for item in head:
            operands = split_ops(item.op_str)
            if item.mnemonic != 'cmp' or len(operands) != 2 or \
                    subreg64(operands[0]) not in count_regs:
                continue
            value = is_imm(operands[1])
            if value is not None and 0 <= value <= 1024:
                counts.add(value)
        has_code_dispatch = False
        code_regs = set()
        for item in insns:
            operands = split_ops(item.op_str)
            if item.mnemonic == 'mov' and len(operands) == 2:
                destination = subreg64(operands[0])
                memory = parse_mem(operands[1])
                if destination and memory and memory[0] in callable_aliases and \
                        memory[1] == 0x78 and memory[2] is None:
                    code_regs.add(destination)
            elif item.mnemonic == 'call' and \
                    subreg64(item.op_str.strip()) in code_regs:
                has_code_dispatch = True
                break
        if has_code_dispatch and len(counts) == 1:
            return next(iter(counts))
        return None

    def _mapping_array_call_shape(self, va):
        """Recognise the older MSVC ``**mapping`` helper family.

        These helpers receive a ``PyObject **`` in the second Win64 ABI
        register.  The first basic path reads either two array elements
        (mapping merge or callable+kwargs) or three (callable, explicit
        kwargs, expansion).  Keyword-call forms subsequently invoke the
        independently proven generic CALL dispatcher; the pure merge form
        instead obtains an iterator for the second mapping and writes the
        result with ``PyDict_SetItem``.  This is native data-flow/ABI
        evidence and does not depend on helper addresses or source names.
        """
        try:
            insns = self._func_insns(va)
        except Exception:
            return None
        if not insns or len(insns) > 1200:
            return None

        # _func_insns deliberately caps hot resolver scans at 800
        # instructions.  Keyword-merge helpers are one of the few generated
        # runtime templates that can legitimately exceed that cap because
        # their duplicate-key diagnostics are inlined.  The ABI head remains
        # in the cheap window, but the normal-path generic-call dispatcher can
        # occur later.  Extend only this structurally promising candidate,
        # within its authoritative unwind bounds and with a second hard cap.
        scan_insns = insns
        if len(insns) >= 800:
            try:
                bounds = self.img.function_bounds(va)
                if bounds and bounds[0] == va and \
                        0 < bounds[1] - bounds[0] <= 0x20000:
                    offset = self.img.va_to_off(bounds[0])
                    if offset is not None:
                        scan_insns = []
                        code = self.img.data[
                            offset:offset + (bounds[1] - bounds[0])]
                        for item in self._fd.md.disasm(code, bounds[0]):
                            scan_insns.append(item)
                            if len(scan_insns) >= 4096:
                                break
            except Exception:
                scan_insns = insns
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        if self.img.fmt != 'pe' or len(abi.arg_regs) < 2:
            return None
        array_reg = abi.arg_regs[1]
        aliases = {array_reg}
        offsets = set()
        for item in insns[:64]:
            operands = split_ops(item.op_str)
            if item.mnemonic == 'mov' and len(operands) == 2:
                destination = subreg64(operands[0])
                source = subreg64(operands[1])
                if destination and source in aliases:
                    aliases.add(destination)
                memory = parse_mem(operands[1])
                if memory and memory[0] in aliases and not memory[2] and \
                        memory[1] in (0, 8, 16):
                    offsets.add(memory[1])
        if not {0, 8} <= offsets:
            return None

        # Only compact, already-recognisable callees are consulted.  This
        # avoids folding a coincidental call in an error path into the proof.
        semantic_callees = set()
        for item in scan_insns:
            if item.mnemonic != 'call' or not item.op_str.startswith('0x'):
                continue
            try:
                target = int(item.op_str, 16)
                child = self._func_insns(target)
            except Exception:
                continue
            if not (4 <= len(child) <= 160):
                continue
            try:
                semantic_callees.add(self.resolve(target)[1])
            except Exception:
                continue
        has_generic_call = any(
            name == 'CALL_FUNCTION_GENERIC' or
            (isinstance(name, str) and
             name.startswith('CALL_FUNCTION_') and
             'KW' not in name and 'METHOD' not in name)
            for name in semantic_callees)
        if has_generic_call:
            return ('kwcall_merge', 3) if 16 in offsets else ('kwcall', 2)

        direct_apis = set(self._direct_apis(va))
        if 'PyDict_SetItem' in direct_apis and any(
                name in ('MAKE_ITERATOR', 'PyObject_GetIter')
                for name in semantic_callees):
            return ('dict_merge', 2)
        return None

    def _list_constructor_shape(self, va):
        """Prove a fixed list constructor from allocation and item stores.

        Inspect every native return path independently: the successful one
        must return the newly allocated list and write all of its item slots
        from ABI arguments.  The allocation's error return may remain NULL.
        This distinguishes construction from append/grow-buffer helpers.
        """
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 160:
            return None
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        index = {ins.address: i for i, ins in enumerate(instructions)}
        regs = {reg: ('arg', pos) for pos, reg in enumerate(abi.arg_regs)}
        work = [(0, regs, {}, None, 0, frozenset())]
        results = set()
        steps = 0
        while work and steps < 1200:
            pos, regs, items, size, calls, seen = work.pop()
            if pos in seen or pos >= len(instructions):
                return None
            seen = seen | {pos}
            steps += 1
            ins = instructions[pos]
            ops = split_ops(ins.op_str)
            if ins.mnemonic == 'ret':
                if calls != 1:
                    return None
                if regs.get(abi.ret_reg) == ('list',):
                    if set(items) != set(range(size)):
                        return None
                    results.add(tuple(items[i] for i in range(size)))
                elif regs.get(abi.ret_reg) != ('null',):
                    return None
                continue
            if ins.mnemonic.startswith('j'):
                target = is_imm(ins.op_str)
                if target not in index:
                    return None
                taken_regs = dict(regs)
                if pos and ins.mnemonic in ('je', 'jne', 'jz', 'jnz'):
                    previous = instructions[pos - 1]
                    tested = split_ops(previous.op_str)
                    if previous.mnemonic == 'test' and len(tested) == 2 and \
                            tested[0] == tested[1] and \
                            regs.get(subreg64(tested[0])) == ('list',):
                        null_regs = taken_regs if ins.mnemonic in ('je', 'jz') else regs
                        for register, value in list(null_regs.items()):
                            if value == ('list',):
                                null_regs[register] = ('null',)
                work.append((index[target], taken_regs, dict(items), size, calls, seen))
                if ins.mnemonic == 'jmp':
                    continue
            elif ins.mnemonic == 'call':
                target = is_imm(ins.op_str)
                if target is None or target == va or calls:
                    return None
                resolution = self.resolve(target)
                count = regs.get(abi.arg_regs[1])
                if resolution[1] != 'MAKE_LIST_EMPTY' or not count or \
                        count[0] != 'imm' or not 1 <= count[1] <= 128:
                    return None
                size = count[1]
                for reg in ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11'):
                    regs.pop(reg, None)
                if self.img.fmt != 'pe':
                    for reg in ('rsi', 'rdi'):
                        regs.pop(reg, None)
                regs[abi.ret_reg] = ('list',)
                calls += 1
            elif ins.mnemonic == 'mov' and len(ops) == 2:
                dst, src = subreg64(ops[0]), subreg64(ops[1])
                memsrc, memdst = parse_mem(ops[1]), parse_mem(ops[0])
                if dst:
                    value = regs.get(src)
                    literal = is_imm(ops[1])
                    if literal is not None:
                        value = ('imm', literal)
                    elif memsrc and not memsrc[2] and memsrc[1] == 0x18 and \
                            regs.get(memsrc[0]) == ('list',):
                        value = ('items',)
                    regs[dst] = value
                elif memdst and regs.get(memdst[0]) == ('items',):
                    value = regs.get(src)
                    if memdst[2] or memdst[1] % 8 or not value or value[0] != 'arg':
                        return None
                    items[memdst[1] // 8] = value[1]
            elif ins.mnemonic in ('lea', 'xor', 'add', 'sub', 'pop') and ops:
                dst = subreg64(ops[0])
                if dst and dst != 'rsp':
                    regs.pop(dst, None)
            else:
                # Any other register-producing instruction invalidates its
                # provenance.  Memory refcount updates leave the argument
                # pointer intact; arithmetic on that pointer does not.
                try:
                    _reads, writes = ins.regs_access()
                    for number in writes:
                        regs.pop(subreg64(ins.reg_name(number)), None)
                except Exception:
                    if ins.mnemonic not in ('test', 'cmp', 'nop', 'push', 'inc', 'dec'):
                        return None
            work.append((pos + 1, regs, items, size, calls, seen))
        if work or len(results) != 1:
            return None
        return next(iter(results))

    def _tuple_allocator_shape(self, va):
        """Prove Nuitka's variable-sized empty-tuple allocator.

        CPython/Nuitka tuple allocation has a distinctive combination which
        is not shared by the small-int cache: the length argument indexes a
        per-size freelist, is multiplied by pointer size, and that byte count
        zero-fills the inline item vector beginning at ``PyVarObject+0x18``.
        The slow path reaches the GC variable-object allocator.  This proof is
        based only on the public object layout and native data flow.
        """
        try:
            insns = self._func_insns(va)
            abi = abi_for(self.img.fmt, detect_python_version(self.img))
            apis = self._api_reach(va)
        except Exception:
            return False
        type_imports = {self.img.imports.get(rip_target(ins))
                        for ins in insns if ins.mnemonic == 'mov' and
                        'rip' in ins.op_str}
        if not insns or len(abi.arg_regs) < 2 or not (
                '_PyObject_GC_Malloc' in apis or 'PyTuple_Type' in type_imports):
            return False

        size_aliases = {abi.arg_regs[1]}
        scaled_freelist = False
        byte_scaled = False
        payload_pointer = False
        zero_value = False
        zero_fill_call = False
        for index, item in enumerate(insns[:220]):
            operands = split_ops(item.op_str)
            if item.mnemonic == 'mov' and len(operands) == 2:
                destination = subreg64(operands[0])
                source = subreg64(operands[1])
                old_aliases = set(size_aliases)
                if destination:
                    size_aliases.discard(destination)
                    if source in old_aliases:
                        size_aliases.add(destination)
                memory = parse_mem(operands[1])
                if memory and memory[2] is not None and memory[3] == 8 and \
                        (memory[2] in old_aliases or memory[1] != 0):
                    scaled_freelist = True
            elif item.mnemonic == 'shl' and len(operands) == 2 and \
                    subreg64(operands[0]) is not None and \
                    is_imm(operands[1]) == 3:
                byte_scaled = True
            elif item.mnemonic == 'lea' and len(operands) == 2:
                memory = parse_mem(operands[1])
                if memory and memory[1] == 0x18 and memory[2] is None:
                    payload_pointer = True
            elif item.mnemonic == 'xor' and len(operands) == 2 and \
                    subreg64(operands[0]) == subreg64(operands[1]):
                if subreg64(operands[0]) in abi.arg_regs or \
                        subreg64(operands[0]) is not None:
                    zero_value = True
            elif item.mnemonic == 'call' and index:
                # The zeroing routine may be linked as a private CRT leaf, so
                # its symbol/import name is deliberately not required.
                if byte_scaled and payload_pointer and zero_value:
                    zero_fill_call = True
        return bool(scaled_freelist and byte_scaled and payload_pointer and
                    zero_fill_call)

    def _constant_function_setter_shape(self, va):
        """Prove a setter and its installed constant-return implementation."""
        if self.img.fmt != 'pe':
            return False
        body = self._func_insns(va)
        if not body or len(body) > 16:
            return False
        regs = {'rcx': ('function',), 'rdx': ('value',)}
        fields, implementations = set(), []
        for ins in body:
            ops = split_ops(ins.op_str)
            if ins.mnemonic == 'lea' and len(ops) == 2 and 'rip' in ops[1]:
                target = rip_target(ins)
                regs[subreg64(ops[0])] = ('code', target) if target and self.img.is_exec(target) else None
            elif ins.mnemonic == 'mov' and len(ops) == 2:
                dm = parse_mem(ops[0]); value = regs.get(subreg64(ops[1]))
                if dm and not dm[2] and regs.get(dm[0]) == ('function',):
                    if value == ('value',):
                        fields.add(dm[1])
                    elif value and value[0] == 'code':
                        implementations.append(value[1])
                elif subreg64(ops[0]):
                    regs[subreg64(ops[0])] = value
            elif ins.mnemonic not in ('ret', 'nop'):
                return False
        if len(fields) != 1 or len(implementations) != 1:
            return False
        offset = next(iter(fields))
        impl = self._func_insns(implementations[0])
        aliases = {'rdx'}; result = False; incref = False
        for ins in impl:
            ops = split_ops(ins.op_str)
            if ins.mnemonic == 'mov' and len(ops) == 2:
                dst, src = subreg64(ops[0]), subreg64(ops[1])
                memory = parse_mem(ops[1])
                if dst and src in aliases:
                    aliases.add(dst)
                if dst == 'rax':
                    result = bool(memory and memory[0] in aliases and memory[1] == offset and not memory[2])
            elif ins.mnemonic == 'call':
                result = False
                aliases.difference_update(('rcx', 'rdx', 'r8', 'r9', 'r10', 'r11'))
            elif ins.mnemonic == 'inc' and ops and parse_mem(ops[0]) == ('rax', 0, None, 1):
                incref = result
            elif ins.mnemonic == 'ret':
                return result and incref
        return False

    def _exception_transfer_shape(self, va):
        """Prove the three-field exception-state ABI and traceback transfer."""
        if self.img.fmt != 'pe':
            return None
        body = self._func_insns(va)
        if not body or len(body) > 150:
            return None
        regs = {'rcx': ('context',), 'rdx': ('state',)}
        cleared, stored = set(), set()
        traceback_set = published = False
        for ins in body:
            ops = split_ops(ins.op_str)
            if ins.mnemonic == 'mov' and len(ops) == 2:
                dst, src = subreg64(ops[0]), subreg64(ops[1])
                dm, sm = parse_mem(ops[0]), parse_mem(ops[1])
                value = regs.get(src) if src else None
                if sm and not sm[2]:
                    base = regs.get(sm[0])
                    if base == ('state',) and sm[1] in (0, 8, 16):
                        value = ('field', sm[1])
                    elif base == ('context',) and sm[1] == 0x138:
                        value = ('published',)
                    elif base in (('field', 8), ('published',)):
                        value = ('attribute', base, sm[1])
                if dm and not dm[2]:
                    base = regs.get(dm[0])
                    if base == ('state',):
                        if is_imm(ops[1]) == 0:
                            cleared.add(dm[1])
                        if value:
                            stored.add((dm[1], value))
                    if base == ('field', 8) and dm[1] == 0x28 and value == ('field', 16):
                        traceback_set = True
                    if base == ('context',) and dm[1] == 0x138 and value == ('field', 8):
                        published = True
                if dst and not dm:
                    regs[dst] = value
            elif ins.mnemonic == 'call':
                for reg in ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11'):
                    regs.pop(reg, None)
        if traceback_set and published and cleared.issuperset((0, 8, 16)):
            return 'publish'
        if {(8, ('published',)), (0, ('attribute', ('field', 8), 8)),
                (16, ('attribute', ('field', 8), 0x28))}.issubset(stored):
            return 'reraise'
        return None

    def _cached_method_descriptors(self, needed_slots):
        """Resolve only cache cells used by a proven descriptor-vectorcall."""
        cached = getattr(self, '_method_descriptor_slots', None)
        if cached is None:
            self._method_descriptor_slots = cached = {}
        needed_slots = set(needed_slots) - set(cached)
        if not needed_slots or self.img.fmt != 'pe':
            return cached
        cached.update((slot, None) for slot in needed_slots)
        owners = {'PyList_Type': 'list', 'PyDict_Type': 'dict',
                  'PySet_Type': 'set', 'PyUnicode_Type': 'str',
                  'PyBytes_Type': 'bytes', 'PyByteArray_Type': 'bytearray',
                  'PyTuple_Type': 'tuple', 'PyLong_Type': 'int', 'PyFloat_Type': 'float'}
        candidates = set()
        for section in self.img.sections:
            if not self.img.is_exec(section.addr):
                continue
            data = self.img.data[section.offset:section.offset + section.size]
            for match in re.finditer(b'[\x48\x4c]\x89[\x05\x0d\x15\x1d\x25\x2d\x35\x3d]', data):
                offset = match.start()
                if offset + 7 > len(data):
                    continue
                site = section.addr + offset
                slot = site + 7 + int.from_bytes(data[offset+3:offset+7], 'little', signed=True)
                if slot in needed_slots:
                    bounds = self.img.function_bounds(site)
                    if bounds:
                        candidates.add(bounds)

        def instructions_in(bounds):
            # Bound peak decoding memory even for a very large initializer.
            address, end = bounds
            while address < end:
                offset = self.img.va_to_off(address)
                if offset is None:
                    break
                block = self.img.data[offset:offset + min(4096, end-address)]
                next_address = address
                for item in self._fd.md.disasm(block, address, count=512):
                    next_address = item.address + item.size
                    yield item
                if next_address == address:
                    break
                address = next_address

        for bounds in sorted(candidates):
            instructions = instructions_in(bounds)
            regs = {}
            for item in instructions:
                operands = split_ops(item.op_str)
                if item.mnemonic == 'call':
                    result = None
                    if self.img.imports.get(rip_target(item)) == 'PyObject_GetAttrString':
                        owner, name = regs.get('rcx'), regs.get('rdx')
                        if owner and owner[0] == 'type' and name and name[0] == 'text':
                            result = ('descriptor', owner[1], name[1])
                    for register in MSX64_ABI.caller_saved:
                        regs.pop(register, None)
                    if result:
                        regs['rax'] = result
                elif len(operands) == 2 and item.mnemonic in ('mov', 'lea'):
                    destination, source = map(subreg64, operands)
                    address = rip_target(item)
                    value = regs.get(source)
                    if address is not None and '[rip' in operands[1]:
                        imported = self.img.imports.get(address)
                        value = ('type', owners[imported]) if imported in owners else None
                        if item.mnemonic == 'lea':
                            name = self.img.read_cstr(address, 128)
                            if isinstance(name, str) and name.isidentifier():
                                value = ('text', name)
                    if destination:
                        if value:
                            regs[destination] = value
                        else:
                            regs.pop(destination, None)
                    elif address is not None and '[rip' in operands[0] and \
                            value and value[0] == 'descriptor':
                        if address in needed_slots:
                            cached[address] = value[1:]
                elif operands and item.mnemonic not in ('cmp', 'test', 'push', 'nop'):
                    regs.pop(subreg64(operands[0]), None)
        return cached

    def _cached_method_call_shape(self, va):
        if self.img.fmt != 'pe':
            return None
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 80 or not any(
                item.mnemonic == 'call' and subreg64(item.op_str) for item in instructions):
            return None
        # Cheap structural gate before scanning runtime cache initialization.
        if not any(item.mnemonic == 'mov' and rip_target(item) is not None for item in instructions):
            return None
        slots = {}
        regs = {register: ('argument', register) for register in MSX64_ABI.arg_regs}
        stack = {}
        for item in instructions:
            operands = split_ops(item.op_str)
            if item.mnemonic == 'call':
                target = regs.get(subreg64(item.op_str))
                descriptor, vector = regs.get('rcx'), regs.get('rdx')
                count, keywords = regs.get('r8'), regs.get('r9')
                if target and target[0] == 'vectorcall' and descriptor == ('descriptor', target[1]) and \
                        vector and vector[0] == 'stack' and count and count[0] == 'integer' and \
                        1 <= count[1] <= 16 and keywords == ('integer', 0):
                    args = [stack.get((vector[1], vector[2]+8*i)) for i in range(count[1])]
                    if all(arg and arg[0] == 'argument' for arg in args):
                        slots = self._cached_method_descriptors({target[1]})
                        if slots.get(target[1]):
                            owner, name = slots[target[1]]
                            return owner, name, tuple(arg[1] for arg in args)
                return None
            if len(operands) != 2:
                continue
            destination, source = map(subreg64, operands)
            memory = parse_mem(operands[1])
            store = parse_mem(operands[0])
            value = regs.get(source)
            if item.mnemonic == 'xor' and destination == source:
                value = ('integer', 0)
            elif item.mnemonic in ('mov', 'lea'):
                immediate = is_imm(operands[1])
                if immediate is not None:
                    value = ('integer', immediate)
                elif memory:
                    base, off, index, scale = memory
                    parent = regs.get(base)
                    address = rip_target(item)
                    if item.mnemonic == 'lea' and base in ('rsp', 'rbp') and not index:
                        value = ('stack', base, off)
                    elif address is not None and address not in self.img.imports and self.img.sec_name(address) in ('.data', '.bss'):
                        value = ('descriptor', address)
                    elif parent and parent[0] == 'descriptor' and off == 8 and not index:
                        value = ('descriptor_type', parent[1])
                    elif parent and parent[0] == 'descriptor_type' and off == 0x38 and not index:
                        value = ('vector_offset', parent[1])
                    elif parent and parent[0] == 'descriptor' and off == 0 and scale == 1 and \
                            regs.get(index) == ('vector_offset', parent[1]):
                        value = ('vectorcall', parent[1])
                    else:
                        value = stack.get((base, off)) if not index else None
            elif item.mnemonic in ('cmp', 'test', 'sub', 'add'):
                continue
            else:
                value = None
            if destination:
                regs[destination] = value
            elif store and not store[2]:
                stack[(store[0], store[1])] = value
        return None

    def _guided_sequence_copy_shape(self, va):
        """Prove allocation, indexed element copying and matching stores."""
        try:
            return self._guided_sequence_copy_shape_impl(va)
        except (TypeError, AttributeError, KeyError, IndexError):
            return None

    def _guided_sequence_copy_shape_impl(self, va):
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 160:
            return None
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        if abi is None or not getattr(abi, 'arg_regs', None) or                 len(abi.arg_regs) < 2:
            return None
        regs = {abi.arg_regs[1]: ('source',)}
        copied = allocated = payload_read = payload_written = False
        source_size = None
        container = None
        loop_edges = []
        for item in instructions:
            operands = split_ops(item.op_str)
            if item.mnemonic == 'call':
                target = is_imm(item.op_str)
                if target is None or target == va:
                    return None
                _kind, name, semantic = self.resolve(target)
                if semantic and semantic[0] in ('list_empty', 'tuple_empty') and \
                        regs.get(abi.arg_regs[1]) == source_size and source_size is not None:
                    container = 'list' if semantic[0] == 'list_empty' else 'tuple'
                    regs[abi.ret_reg] = ('result',)
                    allocated = True
                elif semantic and semantic[0] == 'deepcopy_element' and \
                        regs.get(abi.arg_regs[1], (None,))[0] == 'element':
                    regs[abi.ret_reg] = ('copied', regs[abi.arg_regs[1]][1])
                    copied = True
                else:
                    return None
                continue
            if item.mnemonic.startswith('j'):
                target = branch_target(item)
                if target is not None and target < item.address:
                    loop_edges.append((target, item.address))
            if len(operands) != 2 or item.mnemonic != 'mov':
                continue
            destination, source = map(subreg64, operands)
            memory, store = parse_mem(operands[1]), parse_mem(operands[0])
            value = regs.get(source)
            if memory:
                base, off, index, scale = memory
                parent = regs.get(base)
                if parent == ('source',) and off == 0x10 and not index:
                    value = source_size = ('size',)
                elif parent in (('source',), ('result',)) and off == 0x18 and not index:
                    value = (parent[0]+'_items',)
                elif parent == ('source_items',) and index and off == 0 and scale == 8:
                    value = ('element', index)
                    payload_read = True
                else:
                    value = None
            if destination:
                regs[destination] = value
            elif store and regs.get(store[0]) == ('result_items',) and store[1] == 0 and \
                    store[2] and store[3] == 8 and value == ('copied', store[2]):
                payload_written = True
        return container if allocated and copied and payload_read and payload_written and loop_edges else None

    def _deepcopy_element_shape(self, va):
        """Recognise the descriptor-driven constant element copier.

        Nuitka's constant loader passes a descriptor cursor by pointer.  The
        helper reads one tag byte, advances and writes back that cursor, then
        dispatches through a bounded jump table.  The second ABI argument is
        the Python object being copied; the cursor is runtime metadata only.
        """
        try:
            insns = self._func_insns(va)
            abi = abi_for(self.img.fmt, detect_python_version(self.img))
        except Exception:
            return False
        if not insns or len(abi.arg_regs) < 3:
            return False
        cursor_arg = abi.arg_regs[2]
        cursor_aliases = set()
        tag_read = False
        cursor_advanced = False
        cursor_written_back = False
        bounded_dispatch = False
        indirect_jump = False
        for item in insns[:100]:
            operands = split_ops(item.op_str)
            if item.mnemonic == 'mov' and len(operands) == 2:
                destination = subreg64(operands[0])
                source = subreg64(operands[1])
                source_memory = parse_mem(operands[1])
                destination_memory = parse_mem(operands[0])
                if destination and source_memory and \
                        source_memory[0] == cursor_arg and \
                        source_memory[1] == 0 and not source_memory[2]:
                    cursor_aliases.add(destination)
                elif destination and source in cursor_aliases:
                    cursor_aliases.add(destination)
                if destination_memory and \
                        destination_memory[0] == cursor_arg and \
                        destination_memory[1] == 0 and \
                        source in cursor_aliases:
                    cursor_written_back = True
            elif item.mnemonic == 'movzx' and len(operands) == 2:
                memory = parse_mem(operands[1])
                if memory and memory[0] in cursor_aliases and \
                        memory[1] == 0 and not memory[2]:
                    tag_read = True
            elif item.mnemonic in ('inc', 'add') and operands and \
                    subreg64(operands[0]) in cursor_aliases and \
                    (item.mnemonic == 'inc' or
                     (len(operands) == 2 and is_imm(operands[1]) == 1)):
                cursor_advanced = True
            elif item.mnemonic == 'cmp' and len(operands) == 2 and \
                    is_imm(operands[1]) is not None:
                bounded_dispatch = True
            elif item.mnemonic == 'jmp' and \
                    subreg64(item.op_str.strip()) is not None:
                indirect_jump = True
        return bool(tag_read and cursor_advanced and cursor_written_back and
                    bounded_dispatch and indirect_jump)

    def _module_bind_shape(self, va):
        """Prove an outlined UPDATE_STRING_DICT module binding helper.

        MSVC specialises this helper per compiled module: the dictionary is a
        rip-loaded static, while the name and owned value arrive in the second
        and third ABI registers.  Its fast path writes that third argument to
        the entry pointer returned by the dictionary lookup.  A builtin/global
        lookup has the inverse load ``rax = *rax`` and cannot satisfy this
        write-from-argument proof.
        """
        try:
            insns = self._func_insns(va)
        except Exception:
            return False
        if not insns or len(insns) > 300:
            return False
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        if len(abi.arg_regs) < 3:
            return False
        value_aliases = {abi.arg_regs[2]}
        has_static_dict = False
        has_entry_store = False
        for item in insns:
            operands = split_ops(item.op_str)
            if item.mnemonic != 'mov' or len(operands) != 2:
                continue
            destination = subreg64(operands[0])
            source = subreg64(operands[1])
            if destination and source in value_aliases:
                value_aliases.add(destination)
            if destination and 'rip' in operands[1]:
                target = rip_target(item)
                if target is not None and self.img.sec_name(target) in (
                        '.bss', '.data'):
                    has_static_dict = True
            memory = parse_mem(operands[0])
            if memory and memory[0] == 'rax' and memory[1] == 0 and \
                    memory[2] is None and source in value_aliases:
                has_entry_store = True
        return has_static_dict and has_entry_store

    def _exception_normalizer_shape(self, va):
        """Prove Nuitka's in-place exception-state normaliser.

        The second ABI argument points at the three-pointer exception state.
        The helper reads its type at +0, clears value/traceback at +8/+0x10,
        validates exception-class flags, and owns a PyUnicode_FromFormat
        diagnostic for invalid raised objects.  This combination is specific
        to exception normalisation and contains no application identifiers.
        """
        try:
            instructions = self._func_insns(va)
            abi = abi_for(self.img.fmt, detect_python_version(self.img))
            direct = set(self._direct_apis(va))
        except Exception:
            return False
        if not instructions or len(instructions) > 500 or \
                len(abi.arg_regs) < 2 or \
                'PyUnicode_FromFormat' not in direct:
            return False
        state_aliases = {abi.arg_regs[1]}
        read_type = False
        cleared = set()
        inspected_type_flags = False
        for item in instructions[:180]:
            operands = split_ops(item.op_str)
            if item.mnemonic == 'mov' and len(operands) == 2:
                destination = subreg64(operands[0])
                source = subreg64(operands[1])
                old_aliases = set(state_aliases)
                if destination:
                    state_aliases.discard(destination)
                    if source in old_aliases:
                        state_aliases.add(destination)
                source_memory = parse_mem(operands[1])
                destination_memory = parse_mem(operands[0])
                if source_memory and source_memory[0] in old_aliases and \
                        not source_memory[2] and source_memory[1] == 0:
                    read_type = True
                if destination_memory and \
                        destination_memory[0] in state_aliases and \
                        not destination_memory[2] and \
                        destination_memory[1] in (8, 0x10) and \
                        is_imm(operands[1]) == 0:
                    cleared.add(destination_memory[1])
                if source_memory and source_memory[1] == 0xa8 and \
                        source_memory[0] not in state_aliases:
                    inspected_type_flags = True
        return bool(read_type and cleared == {8, 0x10} and
                    inspected_type_flags)

    def _exception_match_shape(self, va):
        """Recognize the tuple-aware exception matcher and its diagnostic."""
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 260:
            return False
        recursive = False
        exception_flags = 0
        tuple_flag = False
        diagnostic = False
        for ins in instructions:
            ops = split_ops(ins.op_str)
            if ins.mnemonic == 'call' and is_imm(ins.op_str) == va:
                recursive = True
            if ins.mnemonic == 'test' and len(ops) == 2 and \
                    '+ 0xa8]' in ops[0] and is_imm(ops[1]) == 0x40000000:
                exception_flags += 1
            if ins.mnemonic == 'bt' and len(ops) == 2 and is_imm(ops[1]) == 26:
                tuple_flag = True
            if ins.mnemonic == 'lea' and 'rip' in ins.op_str:
                try:
                    message = self.img.read_cstr(rip_target(ins), 256)
                except Exception:
                    message = None
                if message and 'catching classes that do not inherit from BaseException' in message:
                    diagnostic = True
        return recursive and tuple_flag and exception_flags >= 3 and diagnostic

    def _tuple_dict_call_shape(self, va):
        """Prove tp_call(called, positional_tuple, keyword_dict) forwarding."""
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 500:
            return None
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        positions = {ins.address: index for index, ins in enumerate(instructions)}
        pending = [(0, {reg: ('argument', index) for index, reg in enumerate(abi.arg_regs)})]
        seen, results = set(), set()
        while pending and len(seen) < 3000:
            index, registers = pending.pop()
            if index >= len(instructions):
                continue
            state = (index, tuple(sorted(registers.items())))
            if state in seen:
                continue
            seen.add(state)
            registers = dict(registers)
            ins = instructions[index]
            ops = split_ops(ins.op_str)
            target = positions.get(is_imm(ins.op_str))
            if ins.mnemonic == 'ret':
                continue
            if ins.mnemonic.startswith('j'):
                if target is not None:
                    pending.append((target, registers))
                if ins.mnemonic != 'jmp':
                    pending.append((index + 1, registers))
                continue
            if ins.mnemonic == 'call':
                function = registers.get(subreg64(ins.op_str))
                if function and function[0] == 'tp_call':
                    args = [registers.get(reg) for reg in abi.arg_regs[:3]]
                    if args[0] == function[1] and all(value and value[0] == 'argument' for value in args):
                        indices = tuple(value[1] for value in args)
                        if len(set(indices)) == 3:
                            results.add(indices)
                    # No later cleanup call can change the proven invocation.
                    continue
                for register in abi.caller_saved:
                    registers.pop(register, None)
            elif len(ops) == 2 and ins.mnemonic not in ('cmp', 'test'):
                destination = subreg64(ops[0])
                if destination:
                    value = None
                    if ins.mnemonic == 'mov':
                        value = registers.get(subreg64(ops[1]))
                        memory = parse_mem(ops[1])
                        if memory and not memory[2]:
                            parent = registers.get(memory[0])
                            if parent and parent[0] == 'argument' and memory[1] == 8:
                                value = ('type', parent)
                            elif parent and parent[0] == 'type' and memory[1] == 0x80:
                                value = ('tp_call', parent[1])
                    if value is None:
                        registers.pop(destination, None)
                    else:
                        registers[destination] = value
            pending.append((index + 1, registers))
        return next(iter(results)) if not pending and len(results) == 1 else None

    def _dict_copy_shape(self, va):
        """Prove a shallow dict copy from copied header fields and key ownership."""
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 600:
            return None
        if not any(self.img.imports.get(rip_target(ins)) == 'PyDict_Type'
                   for ins in instructions):
            return None
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        registers = {reg: ('argument', index) for index, reg in enumerate(abi.arg_regs)}
        copied = {}
        retained_keys = set()
        for ins in instructions:
            ops = split_ops(ins.op_str)
            if ins.mnemonic == 'call':
                for register in abi.caller_saved:
                    registers.pop(register, None)
                registers['rax'] = ('allocation', ins.address)
                continue
            if not ops:
                continue
            memory = parse_mem(ops[0])
            if ins.mnemonic in ('inc', 'add') and memory and memory[1:] == (0, None, 1):
                parent = registers.get(memory[0])
                if parent and parent[0] == 'field' and parent[2] == 0x20:
                    if ins.mnemonic == 'inc' or len(ops) == 2 and is_imm(ops[1]) == 1:
                        retained_keys.add(parent[1])
            if len(ops) != 2:
                continue
            destination = subreg64(ops[0])
            value = registers.get(subreg64(ops[1]))
            source = parse_mem(ops[1])
            if ins.mnemonic == 'mov' and source and source[2] is None:
                parent = registers.get(source[0])
                value = (('field', parent[1], source[1])
                         if parent and parent[0] == 'argument' else None)
            if ins.mnemonic == 'mov' and memory and memory[2] is None:
                parent = registers.get(memory[0])
                if parent and parent[0] == 'allocation' and value and value[0] == 'field' and memory[1] == value[2]:
                    copied.setdefault((value[1], parent), set()).add(memory[1])
            if destination:
                if ins.mnemonic == 'mov' and value:
                    registers[destination] = value
                elif ins.mnemonic not in ('cmp', 'test'):
                    registers.pop(destination, None)
        sources = {arg for (arg, _), fields in copied.items()
                   if {0x10, 0x20} <= fields and arg in retained_keys}
        return next(iter(sources)) if len(sources) == 1 else None

    def _vectorcall_keyword_shape(self, va):
        """Prove kwnames provenance and positional count on vectorcall paths.

        CALL_FUNCTION_NO_ARGS_KW_SPLIT uses a zero nargsf; ARGS<n>_KW_SPLIT
        takes separate positional and keyword vectors. The latter's kwnames
        is stack argument five, including when a frame pointer aliases RSP.
        """
        if self.img.fmt != 'pe':
            return None
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 600:
            return None
        flag = any(item.mnemonic == 'test' and len(split_ops(item.op_str)) == 2 and
                   ((is_imm(split_ops(item.op_str)[1]) == 0x800 and '+ 0xa8]' in item.op_str) or
                    (is_imm(split_ops(item.op_str)[1]) == 8 and '+ 0xa9]' in item.op_str))
                   for item in instructions)
        if not flag:
            return None
        by = {item.address: item for item in instructions}
        initial = {reg: ('arg', i) for i, reg in enumerate(MSX64_ABI.arg_regs)}
        initial['rsp'] = ('stack', 0)
        work = [(instructions[0].address, initial, frozenset())]
        seen = set()
        results = set()
        while work and len(seen) < 6000:
            address, regs, sizes = work.pop()
            state = (address, tuple(sorted(regs.items())), sizes)
            if state in seen or address not in by:
                continue
            seen.add(state)
            ins = by[address]
            operands = split_ops(ins.op_str)
            regs = dict(regs)
            following = address + ins.size

            def value(text, dereference=True):
                register = subreg64(text)
                if register:
                    return regs.get(register)
                immediate = is_imm(text)
                if immediate is not None:
                    return ('imm', immediate)
                memory = parse_mem(text)
                if not memory:
                    return None
                base, offset, index, scale = memory
                parent = regs.get(base)
                if parent and parent[0] == 'stack' and index is None:
                    offset += parent[1]
                    if not dereference:
                        return ('stack', offset)
                    if offset >= 0x28 and (offset-0x28) % 8 == 0:
                        return ('arg', 4+(offset-0x28)//8)
                    return None
                if not dereference or not parent:
                    return None
                if index is not None:
                    index_value = regs.get(index)
                    if parent == ('arg', 1) and index_value == ('vector_offset',):
                        return ('vectorcall',)
                    return None
                if parent == ('arg', 1) and offset == 8:
                    return ('type',)
                if parent == ('type',) and offset == 0x38:
                    return ('vector_offset',)
                if parent in (('arg', 3), ('arg', 4)) and offset == 0x10:
                    return ('tuple_size', parent[1])
                return None

            if ins.mnemonic == 'call':
                if value(ins.op_str) == ('vectorcall',):
                    count, names, called = regs.get('r8'), regs.get('r9'), regs.get('rcx')
                    if called == ('arg', 1) and count and count[0] == 'imm' and 0 <= count[1] < (1<<20):
                        if names == ('arg', 3) and 3 in sizes and regs.get('rdx') == ('arg', 2):
                            results.add(('packed', count[1]))
                        elif names == ('arg', 4) and 4 in sizes:
                            results.add(('split', count[1]))
                for register in MSX64_ABI.caller_saved:
                    regs.pop(register, None)
            elif ins.mnemonic in ('push', 'pop'):
                stack = regs.get('rsp')
                if stack and stack[0] == 'stack':
                    regs['rsp'] = ('stack', stack[1] + (-8 if ins.mnemonic == 'push' else 8))
                if ins.mnemonic == 'pop':
                    regs.pop(subreg64(ins.op_str), None)
            elif len(operands) == 2 and subreg64(operands[0]):
                dst = subreg64(operands[0])
                result = None
                if ins.mnemonic in ('mov', 'lea'):
                    result = value(operands[1], ins.mnemonic == 'mov')
                elif ins.mnemonic == 'xor' and dst == subreg64(operands[1]):
                    result = ('imm', 0)
                elif ins.mnemonic in ('add', 'sub') and regs.get(dst, (None,))[0] == 'stack':
                    immediate = is_imm(operands[1])
                    if immediate is not None:
                        result = ('stack', regs[dst][1] + immediate * (1 if ins.mnemonic == 'add' else -1))
                if result and result[0] == 'tuple_size':
                    sizes = sizes | {result[1]}
                if result:
                    regs[dst] = result
                elif ins.mnemonic not in ('cmp', 'test'):
                    regs.pop(dst, None)
            if ins.mnemonic == 'ret':
                continue
            if ins.mnemonic.startswith('j'):
                target = branch_target(ins)
                if target in by:
                    work.append((target, regs, sizes))
                if ins.mnemonic == 'jmp':
                    continue
            if following in by:
                work.append((following, regs, sizes))
        return next(iter(results)) if not work and len(results) == 1 else None

    def _dict_unicode_index_shape(self, va):
        """Prove CPython's compact Unicode-key index lookup, independent of VA.

        The key table is an argument, has logarithmic size/index-byte fields,
        supports all four signed index widths, and uses the perturb recurrence.
        The returned index comes from that table, not from a PyObject payload.
        """
        instructions = self._func_insns(va)
        if not instructions or len(instructions) > 400:
            return False
        abi = abi_for(self.img.fmt, detect_python_version(self.img))
        aliases = {abi.arg_regs[0]}
        header = set()
        widths = set()
        indices = set()
        perturb = equality = entry_key = returned_index = False
        for ins in instructions:
            operands = split_ops(ins.op_str)
            if len(operands) == 2:
                dst, src = operands
                memory = parse_mem(src)
                if memory and memory[0] in aliases and not memory[2] and \
                        memory[1] in (8, 9) and ins.mnemonic == 'movzx':
                    header.add(memory[1])
                if memory and memory[1] == 0x20 and memory[2] and \
                        (memory[0] in aliases or memory[2] in aliases):
                    width = next((n for name, n in (
                        ('byte ptr', 1), ('word ptr', 2),
                        ('dword ptr', 4), ('qword ptr', 8))
                        if src.startswith(name)), None)
                    if width and (ins.mnemonic in ('movsx', 'movsxd') or
                                  width == 8 and ins.mnemonic == 'mov'):
                        widths.add(width)
                        indices.add(subreg64(dst))
                if memory and memory[1] == 0x20 and memory[2] and \
                        memory[3] == 8 and memory[0] not in aliases:
                    entry_key = True
                if ins.mnemonic == 'shr' and is_imm(src) == 5:
                    perturb = True
                if ins.mnemonic == 'mov' and subreg64(dst) == abi.ret_reg and \
                        subreg64(src) in indices:
                    returned_index = True
                if ins.mnemonic == 'mov' and subreg64(dst):
                    inherited = subreg64(src) in aliases
                    aliases.discard(subreg64(dst))
                    if inherited:
                        aliases.add(subreg64(dst))
            if ins.mnemonic == 'call':
                target = is_imm(ins.op_str)
                if target is not None and target != va:
                    _kind, name, _sem = self.resolve(target)
                    if name and name.startswith('RICH_COMPARE_EQ'):
                        equality = True
        return (header == {8, 9} and widths == {1, 2, 4, 8} and
                perturb and equality and entry_key and returned_index)

    def _resolve_native_template(self, va):
        """Translate a proven Nuitka/CPython native shape into NDX semantics."""
        body = self._func_insns(va)
        terminal_apis = {self.img.imports.get(rip_target(item))
                         for item in body if item.mnemonic == 'jmp' and
                         'rip' in item.op_str}
        if body and len(body) <= 16 and terminal_apis and \
                terminal_apis <= {'PyNumber_Float', 'PyFloat_FromString'} and \
                not any(item.mnemonic in ('call', 'ret') for item in body):
            return ('native', 'BUILTIN_FLOAT1', ('builtin', 1))
        specialized = self._specialized_number_fallback(va)
        if specialized is not None:
            return specialized
        tuple_dict_arguments = self._tuple_dict_call_shape(va)
        if tuple_dict_arguments is not None:
            return ('native', 'CALL_FUNCTION_TUPLE_DICT', ('tuple_dict_call', tuple_dict_arguments))
        copy_argument = self._dict_copy_shape(va)
        if copy_argument is not None:
            return ('native', 'DICT_COPY', ('dict_copy_argument', copy_argument))
        vector_count = self._vectorcall_keyword_shape(va)
        if vector_count is not None:
            return ('native', 'CALL_VECTOR_WITH_KEYWORDS',
                    ('vector_keywords', vector_count))
        if self._dict_unicode_index_shape(va):
            return ('native', 'DICT_UNICODE_INDEX', ('dict_unicode_index', 3))
        if self._exception_match_shape(va):
            return ('native', 'EXCEPTION_MATCH_BOOL', ('exception_match', 2))
        if self._tuple_allocator_shape(va):
            return ('native', 'MAKE_TUPLE_EMPTY', ('tuple_empty', 1))
        if self._constant_function_setter_shape(va):
            return ('native', 'ENABLE_CONSTANT_FUNCTION_RETURN', ('constant_function_return', 2))
        exception_transfer = self._exception_transfer_shape(va)
        if exception_transfer == 'publish':
            return ('native', 'PUBLISH_CURRENT_EXCEPTION', ('publish_exception', None))
        if exception_transfer == 'reraise':
            return ('native', 'RERAISE_EXCEPTION', ('reraise_exception', None))
        method = self._cached_method_call_shape(va)
        if method is not None:
            return ('native', 'CACHED_METHOD_DESCRIPTOR', ('cached_method', method))
        copied_sequence = self._guided_sequence_copy_shape(va)
        if copied_sequence is not None:
            return ('native', 'DEEP_COPY_SEQUENCE_GUIDED', ('guided_sequence_copy', copied_sequence))
        if self._deepcopy_element_shape(va):
            return ('native', 'DEEP_COPY_ELEMENT',
                    ('deepcopy_element', 1))
        if self._module_bind_shape(va):
            return ('native', 'UPDATE_STRING_DICT0',
                    NUITKA_HELPER_SEMANTICS['UPDATE_STRING_DICT0'])
        if self._exception_normalizer_shape(va):
            return ('native', 'NORMALIZE_EXCEPTION_STATE',
                    ('normalize_exception', 1))
        mapping_shape = self._mapping_array_call_shape(va)
        if mapping_shape == ('dict_merge', 2):
            return ('native', 'DICT_MERGE_WITH_ARGS2',
                    ('dict_merge_array', None))
        if mapping_shape == ('kwcall', 2):
            return ('native', 'CALL_FUNCTION_WITH_KW_ARGS2',
                    ('kw_call_array', None))
        if mapping_shape == ('kwcall_merge', 3):
            return ('native', 'CALL_FUNCTION_WITH_KW_ARGS3_MERGE',
                    ('kw_call_merge_array', None))
        array_count = self._fixed_argument_array_shape(va)
        if array_count is not None:
            return ('native', f'CALL_FUNCTION_WITH_ARGS{array_count}', ('call_function', None))
        positional_count = self._positional_tuple_call_shape(va)
        if positional_count is not None:
            name = f'CALL_FUNCTION_WITH_POS_ARGS{positional_count}'
            return ('native', name, ('call_function', None))
        classifier = self._native_classifier
        if classifier is None:
            return None
        # ASYNC_AWAIT is an outlined Nuitka runtime template, not an ordinary
        # CALL helper.  The classifier proves it from the paired await
        # protocol diagnostics embedded in the helper itself.  Preserve that
        # identity before the broader call-shape classifier can fold it into a
        # generic CALL category.
        try:
            if classifier._async_await_helper(va):
                return ('native', 'ASYNC_AWAIT', ('await', 1))
        except Exception:
            pass
        inplace_name = self._native_inplace_binop_name(va)
        if inplace_name is not None:
            return ('native', inplace_name, ('binop', 2))
        # In-place su PyLong con store ATTRAVERSO il puntatore del primo
        # operando (``x += <int>``): l'ABI scrive la slot e ritorna solo un
        # flag.  Identità INPLACE esplicita — il consumatore dei template
        # cosi' esegue il round-trip slot→binop→slot invece di trattare il
        # puntatore come un valore.
        try:
            if classifier._inplace_add_pylong_helper(va):
                return ('native', 'INPLACE_OPERATION_ADD_OBJECT_CLONG',
                        ('binop', 2))
        except Exception:
            pass
        try:
            cat, extra = classifier.classify(va)
        except Exception:
            return None

        if cat == 'GLOBAL' and isinstance(extra, str) and extra:
            return ('native', f'global:{extra}', ('global_load', extra))
        if cat == 'GLOBALCALL':
            return ('native', 'GET_STRING_DICT_VALUE',
                    NUITKA_HELPER_SEMANTICS['GET_STRING_DICT_VALUE'])
        if cat == 'ATTR':
            return ('native', 'LOOKUP_ATTRIBUTE', ('lookup_attribute', 2))
        if cat == 'GETATTR3':
            return ('native', 'BUILTIN_GETATTR', ('getattr', 3))
        if cat == 'SUBSCRIPT':
            return ('native', 'LOOKUP_SUBSCRIPT', ('subscript', 2))
        if cat == 'SETSUBSCRIPT':
            return ('native', 'SET_SUBSCRIPT', ('set_subscript', 3))
        if cat == 'SETATTR':
            return ('native', 'SET_ATTRIBUTE', ('set_attribute', 3))
        if cat == 'GETITER':
            return ('native', 'MAKE_ITERATOR', ('make_iterator', 1))
        if cat in ('BINOP', 'BINOPSLOT'):
            name = self._native_binop_name(extra)
            if name:
                return ('native', name, ('binop', 2))
        if cat == 'COMPARE':
            if isinstance(extra, int):
                extra = {0: '<', 1: '<=', 2: '==', 3: '!=',
                         4: '>', 5: '>='}.get(extra)
            token = {'==': 'EQ', '!=': 'NE', '<': 'LT', '<=': 'LE',
                     '>': 'GT', '>=': 'GE'}.get(extra)
            if token:
                name = f'RICH_COMPARE_{token}_OBJECT'
                return ('native', name, ('rich_compare', 2))
        if cat == 'CONTAINS':
            return ('native', 'SEQUENCE_CONTAINS', ('contains', 2))
        if cat in ('BUILTIN_CALL', 'BUILTIN') and isinstance(extra, str):
            aliases = {'sorted': 'SORT', 'str': 'STR1', 'bytes': 'BYTES1',
                       'int': 'INT1', 'float': 'FLOAT1', 'bool': 'BOOL1',
                       'list': 'LIST1', 'tuple': 'TUPLE1', 'set': 'SET1'}
            suffix = ('SUPER0' if extra == 'super' else
                      aliases.get(extra, extra.upper()))
            name = f'BUILTIN_{suffix}'
            return ('native', name,
                    helper_semantics(name) or ('builtin', None))
        if cat == 'FORMAT_VALUE':
            return ('native', 'BUILTIN_FORMAT', ('format', 2))
        if cat == 'LIST_APPEND':
            return ('native', 'BUILTIN_LIST_APPEND', ('list_append', None))
        if cat == 'LIST_COPY_CONST':
            return ('native', 'LIST_COPY_CONST', ('list_copy_const', 1))
        if cat == 'COPY_CONST':
            return ('native', 'DEEP_COPY', ('deepcopy', 1))
        if cat == 'IMPORT':
            return ('native', 'IMPORT_MODULE5', ('import_module5', 5))
        if cat == 'CALL':
            no_args = (isinstance(extra, tuple) and len(extra) == 2 and
                       extra[0] == 'strict_function' and extra[1] == 'none')
            name = ('CALL_FUNCTION_NO_ARGS' if no_args
                    else 'CALL_FUNCTION_WITH_ARGS')
            return ('native', name, ('call_function', None))
        if cat == 'METHOD':
            no_args = (isinstance(extra, tuple) and len(extra) == 2 and
                       extra[0] == 'strict_method' and extra[1] == 0)
            name = ('CALL_METHOD_NO_ARGS' if no_args
                    else 'CALL_METHOD_WITH_ARGS')
            return ('native', name, ('call_method', None))
        if cat == 'MAKE_FUNCTION':
            return ('native', 'Nuitka_Function_New', ('make_function', None))
        if cat == 'ERR':
            # Do not relabel the enclosing helper as PyErr_Format merely because
            # its exceptional branch formats an error (common for binops).
            return ('unknown', f'sub_{va:x}', None)
        # UNKNOWN does not provide source semantics.
        return None

    _RUNTIME_TP_NAMES = frozenset((
        'compiled_cell', 'compiled_frame', 'compiled_generator',
        'compiled_async_generator', 'compiled_coroutine',
        'compiled_method', 'traceback', 'coroutine',
        'async_generator', 'generator', 'frame', 'cell'))

    _IAT_TP_NAMES = {
        'PyTraceBack_Type': 'traceback', 'PyCell_Type': 'cell',
        'PyFrame_Type': 'frame', 'PyGen_Type': 'generator',
        'PyCoroutine_Type': 'coroutine',
        'PyAsyncGen_Type': 'async_generator',
    }

    def _runtime_tp_name(self, va, real_insns=None):
        """tp_name del tipo referenziato da un leaf: una ``lea reg,
        [rip+X]`` carica il PyTypeObject statico dell'oggetto allocato
        (``[X+0x18]`` = tp_name), un ``mov reg, [rip+X]`` risolve un tipo
        importato via IAT. Celle/frame/generatori/traceback sono oggetti
        del runtime Nuitka/CPython, mai sorgente utente."""
        c = getattr(self, '_rtp_cache', None)
        if c is None:
            c = self._rtp_cache = {}
        elif va in c:
            return c[va]
        r = None
        try:
            if real_insns is None:
                real_insns = [i for i in self._func_insns(va)
                              if i.mnemonic not in ('int3', 'nop',
                                                    'endbr64')]
            for i in real_insns[:40]:
                if i.mnemonic == 'mov' and 'rip' in i.op_str and \
                        'qword ptr [rip' in i.op_str:
                    t = rip_target(i)
                    mapped = self._IAT_TP_NAMES.get(
                        self.img.imports.get(t) if t is not None else None)
                    if mapped:
                        r = mapped
                        break
                    continue
                if i.mnemonic != 'lea' or 'rip' not in i.op_str:
                    continue
                t = rip_target(i)
                if t is None:
                    continue
                off = self.img.va_to_off(t)
                if off is None or self.img.is_exec(t):
                    continue
                try:
                    name_ptr = struct.unpack_from(
                        '<Q', self.img.data, off + 0x18)[0]
                except Exception:
                    continue
                o2 = self.img.va_to_off(name_ptr)
                if o2 is None:
                    continue
                raw = self.img.data[o2:o2 + 40]
                e = raw.find(b'\x00')
                if not (0 < e < 40):
                    continue
                try:
                    nm = raw[:e].decode('ascii')
                except Exception:
                    continue
                if nm in self._RUNTIME_TP_NAMES:
                    r = nm
                    break
        except Exception:
            r = None
        if len(c) < 20000:
            c[va] = r
        return r

    def _methoddef_name(self, real_insns):
        """Nome dalla PyMethodDef statica di una MAKE_FUNCTION outlined:
        l'ultima ``lea rcx, [rip ±X]`` prima della chiamata al
        costruttore punta alla struct in .rdata; ``[struct + 0]`` è il
        puntatore al nome. Deterministico su ogni build MinGW."""
        try:
            lea = None
            for i in real_insns:
                if i.mnemonic == 'lea' and re.match(
                        r'^rcx, \[rip [+\-]', i.op_str):
                    lea = rip_target(i)
            if lea is None:
                return None
            off = self.img.va_to_off(lea)
            if off is None or self.img.is_exec(lea):
                return None
            name_ptr = struct.unpack_from('<Q', self.img.data, off)[0]
            o2 = self.img.va_to_off(name_ptr)
            if o2 is None:
                return None
            raw = self.img.data[o2:o2 + 64]
            e = raw.find(b'\x00')
            if not (0 < e < 64):
                return None
            nm = raw[:e].decode('ascii', 'ignore')
            return nm if nm.isidentifier() else None
        except Exception:
            return None

    def _func_insns(self, va):
        """Istruzioni della funzione esatta via .eh_frame bounds (senza
        attraversare il confine). Memoizzata con finestra limitata:
        _resolve di ogni call-site ridomanda le stesse foglie decine di
        volte (api_reach + regole shaped) e il redisasm è il costo
        dominante; MA trattenere CsInsn vivi su tutta una run multi-modulo
        satura l'heap di capstone (CS_ERR_MEM) — la cache si svuota quando
        piena: il riuso che conta è quello a caldo, entro la stessa
        risoluzione."""
        c = getattr(self, '_fi_cache', None)
        if c is None:
            c = self._fi_cache = {}
        elif va in c:
            return c[va]
        raw = self._func_insns_uncached(va)
        instructions = {item.address: item for item in raw}
        reached = set()
        pending = [va]
        while pending:
            address = pending.pop()
            if address in reached or address not in instructions:
                continue
            reached.add(address)
            item = instructions[address]
            target = branch_target(item)
            if item.mnemonic.startswith('j'):
                if target in instructions:
                    pending.append(target)
                if item.mnemonic == 'jmp':
                    continue
            if item.mnemonic not in ('ret', 'int3', 'ud2', 'hlt'):
                pending.append(item.address + item.size)
        r = [item for item in raw if item.address in reached]
        if len(c) >= 2048:
            c.clear()
        c[va] = r
        return r

    def _func_insns_uncached(self, va):
        b = self.img.function_bounds(va)
        if b is None:
            return self._fd.insns(va, max_bytes=0x1000, stop_at_ret=False)[:600]
        start, end = b
        off = self.img.va_to_off(start)
        if off is None:
            return []
        # MAI list() integrale: su binari enormi una funzione-moduleentry
        # di MB produce milioni di CsInsn e il processo muore. Cap inline.
        code = self.img.data[off:off + min(end - start, 0x8000)]
        out = []
        for insn in self._fd.md.disasm(code, start):
            out.append(insn)
            if len(out) >= 800:
                break
        return out

    def _api_reach(self, va, depth=3, max_nodes=50):
        # V100 SPEED: memoizzazione per-VA.  La reach API di una funzione
        # e' statica, ma viene ricalcolata ~130k volte sui binary grandi
        # (regole shaped + lifter + analyzer).  Copia difensiva al ritorno:
        # alcuni caller mutano il set.
        cache = getattr(self, '_api_reach_cache', None)
        if cache is None:
            cache = self._api_reach_cache = {}
        elif va in cache:
            return set(cache[va])
        seen, apis = set(), set()
        work = [(va, 0)]
        while work and len(seen) < max_nodes:
            cur, d = work.pop(0)
            if cur in seen or d > depth:
                continue
            seen.add(cur)
            for insn in self._func_insns(cur):
                if insn.mnemonic in ('call', 'jmp'):
                    if insn.op_str.startswith('0x'):
                        try:
                            t = int(insn.op_str, 16)
                        except ValueError:
                            continue
                        if t in self.img.plt_map:
                            apis.add(self.img.plt_map[t])
                        elif t != cur:
                            work.append((t, d + 1))
                    elif 'rip' in insn.op_str:
                        tgt = rip_target(insn)
                        if tgt is not None and tgt in self.img.imports:
                            apis.add(self.img.imports[tgt])
        cache[va] = frozenset(apis)
        return apis

    def _module_accessor_name(self, va):
        """module_var_accessor_M$var Nuitka 4.x: leaf che (a) legge lo slot
        moduledict (rip→.bss usato come dict del modulo), (b) accede la dict
        entry via keys-version cache ([rbx+9]/[rbx+0xc]/shl pattern), (c)
        non chiama nulla di semantico. Il nome NON è nel corpo: ritorna
        marker '' e il nome vero arriva da accessor_names."""
        insns = self._func_insns(va)
        if not insns or len(insns) > 300:
            return None
        reads_moduledict = False
        has_keys_pattern = False
        sem_calls = 0
        mdict_slots = getattr(self, 'moduledict_slots', set())
        for insn in insns:
            if 'rip' in insn.op_str:
                t = rip_target(insn)
                if t is None:
                    continue
                nm = self.img.symbols.get(t) or ''
                if 'moduledict' in nm or 'module_' in nm or t in mdict_slots:
                    reads_moduledict = True
                # Py3.10: check del version-tag del dizionario
                # (cmp rax, [rip+&ma_version_tag]) al posto del pattern
                # keys-index (movzx/shl) di 3.11+.
                if insn.mnemonic == 'cmp' and 'rip' in insn.op_str:
                    has_keys_pattern = True
            if insn.mnemonic in ('movzx',) or ('shl' in insn.mnemonic):
                has_keys_pattern = True
            if insn.mnemonic == 'call' and insn.op_str.startswith('0x'):
                try:
                    t = int(insn.op_str, 16)
                except ValueError:
                    continue
                if t == va:
                    continue
                _k, nm2, _sem = self.resolve(t)
                if _sem is not None and _sem[0] not in (
                        'dict_unicode_index', 'global_lookup'):
                    sem_calls += 1
                # anti-cascata: un accessor è una LEAF — dopo due call
                # interne smetti di risolvere (la catena accessor→helper→
                # accessor nell'83MB supera ogni limite)
                if sem_calls >= 2:
                    break
        if reads_moduledict and sem_calls == 0 and has_keys_pattern:
            return ''
        return None

    def find_function_makers(self):
        """Scansiona .text per funzioni che chiamano Nuitka_Function_New
        (i maker specializzati MAKE_FUNCTION_*). Per ognuno estrae:
        impl VA (dal method_def nei reloc), code object slot."""
        if getattr(self, '_makers_scanned', False):
            return self._makers
        self._makers_scanned = True
        self._makers = {}
        nfn_va = None
        for sec in self.img.sections:
            if sec.name != '.text':
                continue
            code = self.img.data[sec.offset:sec.offset + sec.size]
            for ins in self._fd.md.disasm(code, sec.addr):
                if ins.mnemonic == 'call' and ins.op_str.startswith('0x'):
                    try:
                        t = int(ins.op_str, 16)
                    except ValueError:
                        continue
                    _k, nm, _s = self.resolve(t)
                    if nm == 'Nuitka_Function_New':
                        nfn_va = t
                        break
                if nfn_va:
                    break
            if nfn_va:
                break
        if nfn_va is None:
            return self._makers
        callers = self._find_callers_of(nfn_va)
        for site in callers:
            b = self.img.function_bounds(site)
            if b is None:
                continue
            info = self._analyze_maker_at(site, b[0])
            if info:
                self._makers.setdefault(b[0], info)
        return self._makers

    def _find_callers_of(self, va):
        out = []
        for sec in self.img.sections:
            if sec.name != '.text':
                continue
            code = self.img.data[sec.offset:sec.offset + sec.size]
            for ins in self._fd.md.disasm(code, sec.addr):
                if ins.mnemonic == 'call' and ins.op_str == hex(va):
                    out.append(ins.address)
        return out

    def _analyze_maker_at(self, call_site, maker_start):
        """Dal call site di Nuitka_Function_New nel maker estrae
        (impl_va, code_obj_slot)."""
        b = self.img.function_bounds(maker_start)
        if b is None:
            return None
        off = self.img.va_to_off(maker_start)
        code = self.img.data[off:off + min(b[1] - b[0], 0x800)]
        insns = list(self._fd.md.disasm(code, maker_start))
        pre = []
        for ins in insns:
            pre.append(ins)
            if ins.address == call_site:
                break
        impl_va = None
        codeobj_slot = None
        rdi_src = None
        rsi_src = None
        for ins in reversed(pre[-30:]):
            ops = split_ops(ins.op_str)
            if len(ops) == 2:
                d, s = ops
                if subreg64(d) == 'rdi' and rdi_src is None and \
                        ins.mnemonic in ('lea', 'mov'):
                    rdi_src = (ins, s)
                if subreg64(d) == 'rsi' and rsi_src is None and \
                        ins.mnemonic == 'mov':
                    rsi_src = (ins, s)
        if rdi_src:
            ins, s = rdi_src
            if 'rip' in s:
                t = rip_target(ins)
                if t is not None:
                    impl_va = self._impl_from_method_def(t)
        if rsi_src:
            ins, s = rsi_src
            if 'rip' in s:
                t = rip_target(ins)
                if t is not None and self.img.sec_name(t) in (
                        '.bss', '.data', '.data.rel.ro'):
                    codeobj_slot = t
        if impl_va is None and codeobj_slot is None:
            return None
        return {'impl_va': impl_va, 'code_obj_slot': codeobj_slot,
                'site': call_site}

    def _impl_from_method_def(self, struct_va):
        """method_def in .data.rel.ro: campo ml_meth con RELOCATION → impl."""
        relocs = getattr(self.img, 'rel_relative', {}) or {}
        for off in (8, 0x10, 0x18, 0x20, 0x28, 0x30):
            tgt = relocs.get(struct_va + off)
            if tgt is not None and self.img.is_exec(tgt):
                return tgt
        for va, tgt in relocs.items():
            if struct_va <= va < struct_va + 0x40 and self.img.is_exec(tgt):
                return tgt
        return None

    def bind_slot_consts(self, const_slots):
        """Collega la mappa VA slot→valore costante (per riconoscere i
        module var accessor)."""
        self.slot_consts = dict(const_slots)

    def _direct_apis(self, va):
        """API PLT/IAT chiamate direttamente (depth 1) dalla funzione."""
        apis = set()
        for insn in self._func_insns(va):
            if insn.mnemonic == 'call':
                if insn.op_str.startswith('0x'):
                    try:
                        t = int(insn.op_str, 16)
                    except ValueError:
                        continue
                    nm = self.img.plt_map.get(t)
                    if nm:
                        apis.add(nm)
                elif 'rip' in insn.op_str:
                    tgt = rip_target(insn)
                    if tgt is not None and tgt in self.img.imports:
                        apis.add(self.img.imports[tgt])
        return apis

    def _opc_hash(self, va):
        import hashlib
        mn = [i.mnemonic for i in self._func_insns(va)]
        if not mn:
            return None
        return hashlib.md5(','.join(mn).encode()).hexdigest()[:16]


# ---------------------------------------------------------------------------
# ModuleCode analyzer: struttura del modulo (import/def/class/globali)
# ---------------------------------------------------------------------------

class ModuleCodeAnalyzer:
    """Analizza modulecode_M per estrarre la struttura del modulo."""

    def __init__(self, img, module, resolver, verbose=False):
        self.img = img
        self.module = module
        self.res = resolver
        self.verbose = verbose
        self.fd = FuncDisassembler(img)
        # slot mod_consts: VA → indice
        self.const_slots = {}
        self.mod_consts_base = None
        self.global_base = None
        self.load_blob_va = None
        # code_objects: VA slot .bss → hash name
        self.code_objects = {}
        self.functions = []       # {name, impl_va, code_obj_slot, qualname_slot}
        self.bindings = []        # (name_const, value_sym_desc)
        self.imports_mod = []     # nomi moduli importati
        # Per-module cache for the small MAKE_FUNCTION_* wrappers reached from
        # module/class initialisation.  These wrappers are generated from
        # CodeTemplatesFunction.template_maker_function_body; recognising the
        # constructor ABI is both more precise and more portable than naming a
        # wrapper from an address/signature database.
        self._function_maker_cache = {}
        self._function_constructor_vas = set()
        # V100: helper lazy-attach (tstate, codeobj, x) → rax=codeobj:
        # appresi dallo scan module-init, riusati dalla walk nested
        self._lazy_codeobj_vas = set()

    # -- setup: trova createModuleConstants/createGlobalConstants pattern
    def find_constants_arrays(self):
        """Pattern universale (template Nuitka 4.x):

            createModuleConstants_M:
                lea rdx, [rip+"nome_M"]        ; nome chunk nel blob
                lea rsi, [rip+mod_consts_M]    ; array .bss privato del modulo
                call loadConstantsBlob
            createGlobalConstants:
                lea rdx, [rip+""]              ; chunk globale (nome vuoto)
                lea rsi, [rip+global_constants]
                call loadConstantsBlob

        La stringa del nome modulo arriva dal module table / blob, quindi il
        matching è deterministico. Risolviamo anche loadConstantsBlob (VA) e
        con essa TUTTI gli array (uno per modulo + globale)."""
        modname = self.module.name
        # stringa C col nome modulo
        str_vas = self._find_cstrings(modname)
        if not str_vas:
            return None
        # scan .text: one ABI argument references str_va, another the .bss
        # destination array, followed by loadConstantsBlob.  Register names
        # differ (Win64: r8/rdx; SysV: rdx/rsi), while the data relationship is
        # invariant.
        # MSVC può collocare questi array in .data, mentre ELF usa spesso
        # .bss: entrambe sono sezioni dati non eseguibili valide.
        found = self._constants_loader_from_module_prologue(str_vas)
        if found is not None:
            priv_base, load_blob_va = found
        else:
            # Compatibility fallback for older binaries where the constants
            # initialiser is emitted out of line.  This is intentionally after
            # the bounded module-prologue scan: scanning the complete .text
            # once per duplicate C string is very expensive on large dumps.
            load_blob_va = None
            priv_base = None
            for str_va in str_vas:
                for site, insns in self._lea_window_scan(str_va, after=6):
                    for i, (insn, target) in enumerate(insns):
                        if (insn.mnemonic == 'lea' and target is not None and
                                self.img.sec_name(target) in ('.bss', '.data')):
                            for j in range(i + 1, min(i + 4, len(insns))):
                                next_insn, _next_target = insns[j]
                                if (next_insn.mnemonic == 'call' and
                                        next_insn.op_str.startswith('0x')):
                                    try:
                                        load_blob_va = int(
                                            next_insn.op_str, 16)
                                    except ValueError:
                                        continue
                                    priv_base = target
                                    break
                            if priv_base is not None:
                                break
                    if priv_base is not None:
                        break
                if priv_base is not None:
                    break
        if priv_base is None:
            return None
        self.mod_consts_base = priv_base
        for i in range(len(self.module.consts)):
            self.const_slots[priv_base + 8 * i] = ('priv', i)
        # con loadConstantsBlob trovato: tutti i caller → global base
        if load_blob_va is not None:
            self.load_blob_va = load_blob_va
            glob_base = self._global_base_from_blob_loader(load_blob_va)
            if glob_base is not None:
                self.global_base = glob_base
                for j in range(len(self.module.global_consts)):
                    self.const_slots[glob_base + 8 * j] = ('glob', j)
        return priv_base

    def _constants_loader_from_module_prologue(self, str_vas):
        """Return ``(mod_consts, loadConstantsBlob)`` from modulecode.

        Nuitka may inline ``createModuleConstants`` into modulecode.  Its
        argument relationship is nevertheless unchanged: the private pointer
        array and the module-name C string are loaded into the two loader ABI
        registers immediately before a direct call.  Restricting the search
        to the module's own unwind bounds prevents a same-named string inside
        the constants blob (or another module) from becoming an anchor.
        """
        if not self.module.func_ptr:
            return None
        bounds = self.img.function_bounds(self.module.func_ptr)
        max_bytes = min(bounds[1] - bounds[0], 0x4000) \
            if bounds is not None else 0x4000
        try:
            insns = self.fd.insns(
                self.module.func_ptr, max_bytes=max_bytes,
                stop_at_ret=False)[:4000]
        except Exception:
            return None

        wanted_names = set(str_vas)
        registers = {}
        if self.img.fmt == 'pe':
            array_reg, name_reg = 'rdx', 'r8'
        else:
            array_reg, name_reg = 'rsi', 'rdx'

        for insn in insns:
            if (insn.mnemonic == 'lea' and 'rip' in insn.op_str and
                    ',' in insn.op_str):
                register = _canon_reg(insn.op_str.split(',', 1)[0])
                target = rip_target(insn)
                if register and target is not None:
                    registers[register] = target
                continue
            if insn.mnemonic != 'call':
                continue
            array_va = registers.get(array_reg)
            name_va = registers.get(name_reg)
            if (array_va is not None and name_va in wanted_names and
                    self.img.sec_name(array_va) in (
                        '.bss', '.data', '.data.rel.ro') and
                    insn.op_str.startswith('0x')):
                try:
                    return array_va, int(insn.op_str, 16)
                except ValueError:
                    pass
            # A call consumes the volatile argument registers.  Do not allow
            # stale LEAs to be paired with some later unrelated call.
            registers.clear()
        return None

    def _find_constants_by_reference_legacy(self):
        """Universal fallback for find_constants_arrays.

        Collects every rip-relative .data/.bss address referenced from the
        modulecode (the module's `mod_consts[N]` pointer-table slots) and
        maps them positionally to the module's parsed blob constants.  The
        table is contiguous and ordered: the minimum referenced slot is
        constant index 0, the next is index 1, and so on.  Works for
        dumped binaries (runtime pointers are irrelevant — only the slot
        ADDRESSES are needed for the mapping).
        """
        if not self.module.consts:
            return None
        slots = set()
        for x in self.res._func_insns(self.module.func_ptr):
            if 'rip' not in x.op_str:
                continue
            t = rip_target(x)
            if t is None:
                continue
            sec = self.img.sec_name(t)
            if sec in ('.data', '.bss', '.rdata'):
                slots.add(t)
        if len(slots) < len(self.module.consts):
            return None
        ordered = sorted(slots)
        # The table is the largest contiguous 8-byte-aligned run that can
        # hold all the module's constants.
        base = ordered[0]
        self.mod_consts_base = base
        for i in range(len(self.module.consts)):
            self.const_slots[base + 8 * i] = ('priv', i)
        # map the global constants too (they share the same array, just
        # at the beginning)
        glob_count = len(getattr(self.module, 'global_consts', ()) or ())
        if glob_count:
            for j in range(glob_count):
                self.const_slots[base + 8 * j] = ('glob', j)
            for i in range(len(self.module.consts)):
                self.const_slots[base + 8 * (glob_count + i)] = ('priv', i)
        if self.verbose:
            print(f'  constants-by-reference: base={hex(base)}, '
                  f'{len(ordered)} slots, {len(self.module.consts)} consts')
        return base

    def _find_constants_by_reference(self):
        """Recover ``mod_consts`` from RIP-relative slot references.

        Memory dumps may contain dead heap pointers in every slot and MSVC
        may inline ``createModuleConstants``.  The addresses referenced by
        modulecode still fall inside one ordered pointer array whose maximum
        width is known from the module's DataComposer chunk.  Select the
        densest writable-address window of that exact width and use its
        lowest referenced slot as index zero.

        Global constants live in a separate array and are not overlaid here.
        """
        const_count = len(self.module.consts)
        if not const_count or not self.module.func_ptr:
            return None

        bounds = self.img.function_bounds(self.module.func_ptr)
        max_bytes = (bounds[1] - bounds[0]) if bounds else 0x20000
        try:
            insns = self.fd.insns(self.module.func_ptr,
                                  max_bytes=max_bytes,
                                  stop_at_ret=False)[:50000]
        except Exception:
            return None

        pointer_size = 8
        slots = set()
        for insn in insns:
            if 'rip' not in insn.op_str:
                continue
            target = rip_target(insn)
            if target is None or target % pointer_size:
                continue
            if self.img.sec_name(target) in (
                    '.data', '.bss', '.data.rel.ro'):
                slots.add(target)
        aligned = sorted(slots)
        if not aligned:
            return None

        window_size = const_count * pointer_size
        best = None
        start = 0
        for stop, address in enumerate(aligned):
            while (start <= stop and
                   address - aligned[start] >= window_size):
                start += 1
            if start > stop:
                continue
            candidate_base = aligned[start]
            candidate_count = stop - start + 1
            candidate_span = address - candidate_base
            candidate = (candidate_count, candidate_span, -candidate_base,
                         start, stop)
            if best is None or candidate > best:
                best = candidate

        if best is None:
            return None
        count, _span, _negative_base, start, stop = best
        required = 2 if const_count <= 8 else 4
        if count < required:
            return None

        base = aligned[start]
        selected = aligned[start:stop + 1]
        indices = [(address - base) // pointer_size
                   for address in selected]
        if not indices or indices[-1] >= const_count:
            return None

        self.mod_consts_base = base
        for index in range(const_count):
            self.const_slots[base + pointer_size * index] = ('priv', index)
        if self.verbose:
            print(f'  constants-by-reference: base={hex(base)}, '
                  f'{count} referenced slots, span={indices[-1] + 1}/'
                  f'{const_count}')
        return base

    def _find_cstring(self, text):
        matches = self._find_cstrings(text)
        return matches[0] if matches else None

    def _find_cstrings(self, text):
        """Return every exact C-string occurrence for ``text``.

        Constants blobs contain their own copy of each module name.  Generated
        module prologues reference a later standalone copy, so returning only
        the first match makes the otherwise exact loadConstantsBlob pattern
        fail on large PE images.
        """
        if not text:
            return []
        pat = text.encode() + b'\x00'
        matches = []
        for s in self.img.sections:
            if s.name not in ('.rodata', '.rdata', '.data.rel.ro', '.data'):
                continue
            body = self.img.data[s.offset:s.offset + s.size]
            start = 0
            while True:
                offset = body.find(pat, start)
                if offset < 0:
                    break
                matches.append(s.addr + offset)
                start = offset + 1
        return matches

    _LEA_RIP_RE = re.compile(
        (b'(?:' + bytes([0x48, 0x7c, 0x4c]) + b')' +
         bytes([0x8d]) + b'[' +
         bytes([0x05, 0x0d, 0x15, 0x1d, 0x25, 0x2d, 0x35, 0x3d]) +
         b'](.{4})'), re.DOTALL)

    def _lea_window_scan(self, target_va, before=0, after=6):
        """Yield (site_va, [(insn, rip_target), ...]) per ogni lea rip→target_va.

        BYTE-PATTERN: i siti `lea REG, [rip+disp32]` (48/4C 8D modrm disp32)
        si trovano scandendo i byte — MAI disassemblando l'intera sezione
        (su binari da decine di MB il disasm integrale per modulo esaurisce
        la memoria). Solo la finestra di `after` istruzioni dopo ogni sito
        viene disassemblata (64 byte bastano)."""
        index = getattr(self.img, '_ndx_lea_reference_index', None)
        if index is None:
            index = self.img._ndx_lea_reference_index = {}
            for sec in self.img.sections:
                if not self.img.is_exec(sec.addr):
                    continue
                body = self.img.data[sec.offset:sec.offset + sec.size]
                for match in self._LEA_RIP_RE.finditer(body):
                    displacement = struct.unpack_from('<i', body, match.start(1))[0]
                    site = sec.addr + match.start()
                    index.setdefault(site + 7 + displacement, []).append(site)
        for site_va in index.get(target_va, ()):
            insns = self.fd.insns(site_va, max_bytes=96, stop_at_ret=False)[:after + 2]
            window = [(insn, rip_target(insn) if 'rip' in insn.op_str else None)
                      for insn in insns[:after]]
            if window:
                yield site_va, window

    def _global_base_from_blob_loader_legacy(self, load_blob_va):
        """createGlobalConstants = il caller di loadConstantsBlob che NON è
        un createModuleConstants_M (nessuna lea verso un nome modulo chunk).
        Fra i suoi lea verso .bss prendiamo l'array (rsi/rdi) subito prima
        della call."""
        callers = self._find_callers(load_blob_va)
        mod_str = self._find_cstring(self.module.name)
        for c in callers:
            # disassembla l'INTERA funzione (early-ret vanno superati)
            fb = self.img.function_bounds(c)
            if fb is not None:
                off = self.img.va_to_off(fb[0])
                code = self.img.data[off:off + min(fb[1] - fb[0], 0x800)]
                insns = list(self.fd.md.disasm(code, fb[0]))[:400]
            else:
                insns = self.fd.insns(c, max_bytes=0x400, stop_at_ret=False)[:150]
            arr = None
            has_module_name_lea = False
            for i, insn in enumerate(insns):
                if 'rip' in insn.op_str and insn.mnemonic == 'lea':
                    t = rip_target(insn)
                    if t is None:
                        continue
                    reg = insn.op_str.split(',')[0].strip()
                    if t == mod_str:
                        has_module_name_lea = True
                    elif (reg in ('rdx', 'edx', 'rsi', 'esi', 'rdi', 'edi')
                          and self.img.sec_name(t) in ('.bss', '.data')):
                        arr = t
                if insn.mnemonic == 'call' and insn.op_str == hex(load_blob_va):
                    if arr is not None and not has_module_name_lea:
                        return arr
                    break
        return None

    def _global_base_from_blob_loader(self, load_blob_va):
        """Resolve the global array from the loader's empty chunk name.

        ``loadConstantsBlob(tstate, array, name)`` receives ``name == ""``
        only for global constants.  This also avoids mistaking another
        module's initializer for the global one.
        """
        cache = getattr(self.img, '_ndl_global_constants_bases', None)
        if cache is None:
            cache = self.img._ndl_global_constants_bases = {}
        if load_blob_va in cache:
            return cache[load_blob_va]

        for caller in self._find_callers(load_blob_va):
            bounds = self.img.function_bounds(caller)
            if bounds is not None:
                offset = self.img.va_to_off(bounds[0])
                # V100 FIX: la funzione di inizializzazione dei constants di
                # Nuitka 4.x contiene TUTTE le loadConstantsBlob (blob,
                # bytecode, globali) e puo' superare i 10 KiB (misurato
                # 0x2bda): la vecchia finestra 0x800/400 insn non raggiungeva
                # la call ``name == ''`` dei globali.  Copri l'intera
                # funzione con un cap generoso.
                code = self.img.data[
                    offset:offset + min(bounds[1] - bounds[0], 0x10000)]
                insns = list(self.fd.md.disasm(code, bounds[0]))[:20000]
            else:
                insns = self.fd.insns(
                    caller, max_bytes=0x400, stop_at_ret=False)[:150]
            registers = {}
            for insn in insns:
                if insn.mnemonic == 'lea' and 'rip' in insn.op_str and \
                        ',' in insn.op_str:
                    register = _canon_reg(insn.op_str.split(',', 1)[0])
                    target = rip_target(insn)
                    if register and target is not None:
                        registers[register] = target
                    continue
                if insn.mnemonic != 'call' or \
                        insn.op_str != hex(load_blob_va):
                    continue
                if self.img.fmt == 'pe':
                    array_va = registers.get('rdx')
                    name_va = registers.get('r8')
                else:
                    array_va = registers.get('rsi')
                    name_va = registers.get('rdx')
                if (array_va is not None and name_va is not None and
                        self.img.sec_name(array_va) in (
                            '.bss', '.data', '.data.rel.ro') and
                        self.img.read_cstr(name_va, 1) == ''):
                    cache[load_blob_va] = array_va
                    return array_va
                # V100 FIX: NON fermarsi alla prima call.  Nuitka 4.x mette
                # PIU' loadConstantsBlob nella stessa funzione di inizial-
                # izzazione (prima ``.bytecode``, poi i globali con nome
                # vuoto): il vecchio ``break`` scartava il caller giusto e
                # global_base restava irrisolto, lasciando tutti i load
                # ``mov reg,[rip+X]`` del global-consts array (small int,
                # immortals, stringhe condivise) senza valore -> le init
                # ``x = 0`` sparivano e il naming delle locali slittava.
                continue
        cache[load_blob_va] = None
        return None

    def _find_callers(self, va):
        """Return direct near-call sites targeting ``va`` in executable data.

        The x86-64 encoding is ``E8 rel32``.  Matching that five-byte form is
        much cheaper than decoding a multi-megabyte text section for every
        constants loader; candidate callers are disassembled and validated by
        the consumer before use.
        """
        cache = getattr(self.img, '_ndl_direct_callers', None)
        if cache is None:
            cache = self.img._ndl_direct_callers = {}
        if va in cache:
            return list(cache[va])
        out = []
        for sec in self.img.sections:
            if sec.name not in ('.text', 'code'):
                continue
            code = self.img.data[sec.offset:sec.offset + sec.size]
            offset = code.find(b'\xe8')
            while offset >= 0:
                if offset + 5 <= len(code):
                    displacement = struct.unpack_from('<i', code,
                                                      offset + 1)[0]
                    site = sec.addr + offset
                    if site + 5 + displacement == va:
                        out.append(site)
                offset = code.find(b'\xe8', offset + 1)
        cache[va] = tuple(out)
        return out

    def bounded_direct_helpers(self):
        """Restituisce i helper diretti del modulecode entro limiti rigidi.

        Nuitka/MSVC può lasciare ``createModuleCodeObjects`` come funzione
        separata invece di incorporarla nel modulecode.  Seguiamo soltanto call
        dirette verso l'inizio esatto di una funzione descritta da unwind
        metadata; nessuna BFS ricorsiva e nessuna esecuzione del target.
        """
        try:
            max_roots = int(os.environ.get('NDX_MAX_DIRECT_HELPERS', '256'))
        except ValueError:
            max_roots = 256
        try:
            max_bytes = int(os.environ.get(
                'NDX_MAX_DIRECT_HELPER_BYTES', str(8 * 1024 * 1024)))
        except ValueError:
            max_bytes = 8 * 1024 * 1024
        max_roots = max(1, min(max_roots, 4096))
        max_bytes = max(0x1000, min(max_bytes, 256 * 1024 * 1024))

        roots = []
        seen = {self.module.func_ptr}
        total = 0
        for insn in self.fd.insns(self.module.func_ptr, max_bytes=0x20000,
                                  stop_at_ret=False)[:30000]:
            if insn.mnemonic != 'call' or not insn.op_str.startswith('0x'):
                continue
            try:
                target = int(insn.op_str, 16)
            except ValueError:
                continue
            if target in seen or not self.img.is_exec(target):
                continue
            bounds = self.img.function_bounds(target)
            if bounds is None or bounds[0] != target:
                continue
            extent = bounds[1] - bounds[0]
            if extent <= 0 or total + extent > max_bytes:
                continue
            seen.add(target)
            roots.append(target)
            total += extent
            if len(roots) >= max_roots:
                break
        return roots

    def _collect_rip_slots(self, va):
        """VA .bss/.data referenziati rip-relativamente nella funzione."""
        out = set()
        for insn in self.fd.insns(va, max_bytes=0x8000)[:8000]:
            if 'rip' in insn.op_str:
                t = rip_target(insn)
                if t is not None:
                    out.add(t)
        return out

    def const_for_slot(self, va):
        ent = self.const_slots.get(va)
        if ent is not None:
            which, idx = ent
            if which == 'priv' and idx < len(self.module.consts):
                return self.module.consts[idx], ('priv', idx)
            if which == 'glob' and idx < len(self.module.global_consts):
                return self.module.global_consts[idx], ('glob', idx)
        return None, None

    def _decode_function_maker(self, maker_va):
        """Decode one compiler-generated ``MAKE_FUNCTION_*`` wrapper.

        Nuitka's source template calls ``Nuitka_Function_New`` with the
        invariant leading arguments ``(impl, name, qualname, code_object)``.
        The registers are the platform ABI registers (Win64 RCX/RDX/R8/R9,
        SysV RDI/RSI/RDX/RCX).  The runtime constructor may be stripped,
        statically linked, LTCG-folded, or incorrectly classified by a broad
        helper signature, so the proof deliberately uses the complete
        four-argument data relationship rather than a symbol or an address.

        Returns metadata only for a small wrapper with a statically proven
        Python name and code-object storage slot.  Ordinary helpers cannot
        satisfy that conjunction accidentally.  Results are cached because a
        maker can be referenced by more than one control-flow path.
        """
        maker_va = int(maker_va)
        if maker_va in self._function_maker_cache:
            return self._function_maker_cache[maker_va]
        self._function_maker_cache[maker_va] = None

        bounds = self.img.function_bounds(maker_va)
        if bounds is None:
            return None
        start, end = bounds
        size = end - start
        # Generated makers are tiny.  A generous upper bound accommodates
        # debug builds and constant-return setup without accepting arbitrary
        # Python bodies as factories.
        if not (0 < size <= 0x1000):
            return None
        try:
            insns = self.fd.insns(start, max_bytes=size,
                                  stop_at_ret=False)[:1200]
        except Exception:
            return None
        if not insns:
            return None

        if self.img.fmt == 'pe':
            impl_reg, name_reg, qualname_reg, codeobj_reg = (
                'rcx', 'rdx', 'r8', 'r9')
            caller_saved = ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11')
        else:
            impl_reg, name_reg, qualname_reg, codeobj_reg = (
                'rdi', 'rsi', 'rdx', 'rcx')
            caller_saved = ('rax', 'rcx', 'rdx', 'rsi', 'rdi',
                            'r8', 'r9', 'r10', 'r11')

        # Seed wrapper parameters so their flow into the eleven constructor
        # arguments can be mapped back to values at each MAKE_FUNCTION call
        # site (defaults/kwdefaults/annotations are often runtime parameters
        # of the wrapper, not constants inside it).
        entry_arg_regs = (('rcx', 'rdx', 'r8', 'r9') if self.img.fmt == 'pe'
                          else ('rdi', 'rsi', 'rdx', 'rcx', 'r8', 'r9'))
        regs = {register: ndxS('param', index)
                for index, register in enumerate(entry_arg_regs)}
        outgoing = {}
        # Stack aliases are common in MSVC wrappers (``mov r11, rsp`` before
        # reserving the outgoing area).  Offsets are tracked relative to entry
        # RSP and normalised to RSP-at-constructor-call below.
        stack_offsets = {'rsp': 0}

        def operand_value(insn, src_text):
            src = _canon_reg(src_text)
            if src in regs:
                return regs[src]
            if re.fullmatch(r'(?:0x[0-9a-f]+|-?\d+)', src_text):
                immediate = int(src_text, 0)
                return ndxS('null' if immediate == 0 else 'imm', immediate)
            if 'rip' in src_text and insn.mnemonic in ('mov', 'lea'):
                target = rip_target(insn)
                if target is not None:
                    constant, _where = self.const_for_slot(target)
                    if constant is not None:
                        return ndxS('const', constant, va=target)
                    if insn.mnemonic == 'lea' and self.img.is_exec(target):
                        return ndxS('impl', target, va=target)
                    return ndxS('slot', target, va=target)
            return None

        def assign_register(insn):
            if ',' not in insn.op_str:
                return
            dst_text, src_text = [part.strip()
                                  for part in insn.op_str.split(',', 1)]
            dst = _canon_reg(dst_text)
            if dst is None:
                return
            value = None
            if insn.mnemonic == 'xor' and _canon_reg(src_text) == dst:
                value = ndxS('null', 0)
            else:
                value = operand_value(insn, src_text)
            if value is None:
                regs.pop(dst, None)
            else:
                regs[dst] = value

        candidates = []
        for insn in insns:
            operands = split_ops(insn.op_str)
            if insn.mnemonic in ('add', 'sub') and len(operands) == 2 and \
                    _canon_reg(operands[0]) == 'rsp':
                immediate = is_imm(operands[1])
                if immediate is not None:
                    stack_offsets['rsp'] += (
                        immediate if insn.mnemonic == 'add' else -immediate)
                continue
            if insn.mnemonic in ('mov', 'lea', 'xor'):
                if insn.mnemonic == 'mov' and len(operands) == 2:
                    destination_register = _canon_reg(operands[0])
                    source_register = _canon_reg(operands[1])
                    if destination_register is not None:
                        if source_register in stack_offsets:
                            stack_offsets[destination_register] = \
                                stack_offsets[source_register]
                        elif destination_register != 'rsp':
                            stack_offsets.pop(destination_register, None)
                    memory = parse_mem(operands[0])
                    if memory and memory[0] in stack_offsets and not memory[2]:
                        value = operand_value(insn, operands[1])
                        normalised_offset = (
                            stack_offsets[memory[0]] + memory[1] -
                            stack_offsets.get('rsp', 0))
                        if value is None:
                            outgoing.pop(normalised_offset, None)
                        else:
                            outgoing[normalised_offset] = value
                        continue
                assign_register(insn)
                continue
            if insn.mnemonic not in ('call', 'jmp') or \
                    not insn.op_str.startswith('0x'):
                continue
            try:
                constructor_va = int(insn.op_str, 16)
            except ValueError:
                continue
            impl = regs.get(impl_reg)
            name = regs.get(name_reg)
            qualname = regs.get(qualname_reg)
            codeobj = regs.get(codeobj_reg)
            impl_ok = (impl is not None and (
                (impl.kind == 'impl' and self.img.is_exec(impl.value)) or
                impl.kind == 'null'))
            name_ok = (name is not None and name.kind == 'const' and
                       isinstance(name.value, str) and bool(name.value))
            qualname_ok = (qualname is not None and (
                (qualname.kind == 'const' and
                 isinstance(qualname.value, str) and bool(qualname.value)) or
                qualname.kind == 'null'))
            codeobj_ok = (codeobj is not None and codeobj.kind == 'slot' and
                          not self.img.is_exec(codeobj.value) and
                          self.img.sec_name(codeobj.value) in (
                              '.bss', '.data', '.data.rel.ro'))
            if impl_ok and name_ok and qualname_ok and codeobj_ok:
                if self.img.fmt == 'pe':
                    constructor_tail = [outgoing.get(offset)
                                        for offset in range(0x20, 0x58, 8)]
                else:
                    constructor_tail = [regs.get('r8'), regs.get('r9')]
                    constructor_tail.extend(outgoing.get(offset)
                                            for offset in range(0, 0x28, 8))
                candidates.append({
                    'maker_va': start,
                    'constructor_va': constructor_va,
                    'impl_va': (impl.value if impl.kind == 'impl' else None),
                    'name': name.value,
                    'qualname': (qualname.value
                                 if qualname.kind == 'const' else name.value),
                    'code_obj_slot': codeobj.value,
                    'defaults_source': constructor_tail[0],
                    'kwdefaults_source': constructor_tail[1],
                    'annotations_source': constructor_tail[2],
                })
            if insn.mnemonic == 'call':
                for register in caller_saved:
                    regs.pop(register, None)

        # A generated maker has exactly one constructor-shaped call.  Multiple
        # matches indicate an arbitrary helper/body and are rejected rather
        # than guessed.
        result = candidates[0] if len(candidates) == 1 else None
        if result is not None:
            self._function_constructor_vas.add(result['constructor_va'])
        self._function_maker_cache[maker_va] = result
        return result

    # -- estrazione funzioni robusta (registri Nuitka_Function_New)
    def _extract_functions_v2(self):
        """Recupera le creazioni funzione dalla calling convention nativa.

        Oltre alle firme helper (quando disponibili), riconosce la relazione
        invariabile tra gli argomenti: implementation pointer eseguibile,
        nome Python stringa e code-object slot.  Non dipende da simboli, nomi
        C, indirizzi o moduli specifici.
        """
        fd = FuncDisassembler(self.img)
        if self.img.fmt == 'pe':
            impl_reg, name_reg, qualname_reg, codeobj_reg = (
                'rcx', 'rdx', 'r8', 'r9')
            bind_name_reg, bind_value_reg = 'rdx', 'r8'
        else:
            impl_reg, name_reg, qualname_reg, codeobj_reg = (
                'rdi', 'rsi', 'rdx', 'rcx')
            bind_name_reg, bind_value_reg = 'rsi', 'rdx'
        regs = {}
        events = []
        binds = {}
        pending = None
        for insn in fd.insns(self.module.func_ptr, max_bytes=0x20000,
                             stop_at_ret=False)[:30000]:
            m, op = insn.mnemonic, insn.op_str
            if m == 'call' and op.startswith('0x'):
                try:
                    t = int(op, 16)
                except ValueError:
                    continue
                _kind, name, sem = self.res.resolve(t)
                impl_hint = regs.get(impl_reg)
                name_hint = regs.get(name_reg)
                codeobj_hint = regs.get(codeobj_reg)
                maker_hint = self._decode_function_maker(t)
                # V100: LAZY-ATTACH MAKER — (tstate, codeobj, x) ritorna il
                # CODE OBJECT incondizionatamente (helper minuscolo che
                # fa ``return arg2``). La creazione funzione Vera segue a
                # brevissima distanza: ``r9 <- rax`` + ``lea rcx,[rip+impl]``
                # + call Nuitka_Function_New(impl, name, 0, codeobj, ...).
                # Traccia rax = codeobj cosi' la shape successiva matcha;
                # il continue preserva rax dal pop caller-saved.
                if name_hint is not None and                         name_hint.kind == 'const' and                         isinstance(name_hint.value, dict) and                         name_hint.value.get('_type') == 'CodeObject':
                    regs['rax'] = name_hint
                    self._lazy_codeobj_vas.add(t)
                    continue
                # V100: nelle Nuitka recenti il nome arriva spesso come
                # ``mov rdx,[rip+slot]`` (load dal pool mod_consts) e non
                # come lea-costante: accetta anche 'slot' — si risolve a
                # valle via const_for_slot / binding UPDATE_STRING_DICT.
                _name_ok = (
                    name_hint is not None and (
                        (name_hint.kind == 'const' and
                         isinstance(name_hint.value, str)) or
                        name_hint.kind == 'slot' or
                        # V100: ABI lazy-maker — lo slot di rdx porta il
                        # CODE OBJECT (dict del pool) invece del nome:
                        # e' il fatto d'identita' della creazione funzione
                        (name_hint.kind == 'const' and
                         isinstance(name_hint.value, dict) and
                         name_hint.value.get('_type') == 'CodeObject')))
                # V100: ABI RECENTE — r8 porta il QUALNAME come stringa
                # costante ('pkg.mod.func') invece dello slot code-object:
                # tre fatti concreti (impl + nome + qualname dotted).
                _co_or_qn = (
                    codeobj_hint is not None and (
                        codeobj_hint.kind in ('slot', 'codeobj') or
                        (codeobj_hint.kind == 'const' and
                         isinstance(codeobj_hint.value, str) and
                         '.' in codeobj_hint.value) or
                        # V100: lazy-maker — il code object arriva come
                        # dict del pool (rax del lazy-attach → r9)
                        (codeobj_hint.kind == 'const' and
                         isinstance(codeobj_hint.value, dict) and
                         codeobj_hint.value.get('_type') == 'CodeObject')) or
                    # V100: ABI lazy-maker — il code object viaggia nel
                    # registro del NOME (rdx): slot o dict del pool.
                    (name_hint is not None and (
                        name_hint.kind == 'slot' or
                        (name_hint.kind == 'const' and
                         isinstance(name_hint.value, dict) and
                         name_hint.value.get('_type') == 'CodeObject'))))
                # V100: ABI RECENTE (r8=qualname dotted, r9=altro): il
                # terzo fatto puo' essere il QUALNAME in r8 quando lo slot
                # code-object non e' in r9.
                if not _co_or_qn:
                    _qn_hint = regs.get(qualname_reg)
                    _co_or_qn = (
                        _qn_hint is not None and
                        _qn_hint.kind == 'const' and
                        isinstance(_qn_hint.value, str) and
                        '.' in _qn_hint.value)
                abi_function_shape = (
                    self.img.is_exec(t) and
                    impl_hint is not None and
                    impl_hint.kind == 'leadata' and
                    self.img.is_exec(impl_hint.value) and
                    _name_ok and
                    _co_or_qn
                )
                import os as _os
                if _os.environ.get('NDX_DBG_SHAPE'):
                    print(f"[SHAPE]@{insn.address:x} t={t:x} name={name!r} "
                          f"impl={impl_hint.kind if impl_hint else None} "
                          f"nm={name_hint.kind if name_hint else None} "
                          f"co={codeobj_hint.kind if codeobj_hint else None} "
                          f"shape={abi_function_shape} maker={maker_hint is not None}")
                if (name == 'Nuitka_Function_New' or
                        (sem and sem[0] == 'make_function') or
                        abi_function_shape or maker_hint is not None):
                    if abi_function_shape:
                        self._function_constructor_vas.add(t)
                    snapshot = dict(regs)
                    if maker_hint is not None:
                        snapshot['__function_maker__'] = maker_hint
                    events.append((insn.address, snapshot))
                    pending = len(events) - 1
                    regs['rax'] = ndxS('funcval', pending)
                    continue
                if name in ('UPDATE_STRING_DICT0', 'UPDATE_STRING_DICT1',
                            'UPDATE_STRING_DICT2') or \
                        (sem and sem[0] == 'module_bind'):
                    # binding: rsi=name, rdx=value → il nome pubblico
                    val = regs.get(bind_value_reg)
                    if val is not None and val.kind == 'funcval':
                        nm = regs.get(bind_name_reg)
                        if nm is not None and nm.kind == 'const' and \
                                isinstance(nm.value, str):
                            binds[val.value] = nm.value
                caller_saved = (
                    ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11')
                    if self.img.fmt == 'pe' else
                    ('rax', 'rcx', 'rdx', 'rsi', 'rdi',
                     'r8', 'r9', 'r10', 'r11')
                )
                for register in caller_saved:
                    regs.pop(register, None)
            elif m in ('mov', 'lea') and ',' in op:
                dst, src = [x.strip() for x in op.split(',', 1)]
                dst_c = _canon_reg(dst)
                if not dst_c:
                    continue
                if src.startswith('qword ptr [rip') or \
                        (m == 'mov' and 'rip' in src):
                    t2 = rip_target(insn)
                    if t2 is not None:
                        # costante o slot?
                        cval, _cent = self.const_for_slot(t2)
                        if cval is not None:
                            regs[dst_c] = ndxS('const', cval)
                        else:
                            regs[dst_c] = ndxS('slot', t2)
                        import os as _os2
                        if _os2.environ.get('NDX_DBG_R8') and dst_c == 'r8':
                            print(f"[R8]@{insn.address:x} {m} {src[:40]} -> "
                                  f"{regs['r8'].kind}")
                elif m == 'lea' and 'rip' in src:
                    t2 = rip_target(insn)
                    if t2 is not None:
                        regs[dst_c] = ndxS('leadata', t2)
                elif _canon_reg(src) in regs:
                    regs[dst_c] = regs[_canon_reg(src)]
                else:
                    regs.pop(dst_c, None)
        for _i, (addr, snap) in enumerate(events):
            maker = snap.get('__function_maker__')
            impl = snap.get(impl_reg)
            codeobj = snap.get(codeobj_reg)
            qualname = snap.get(qualname_reg)
            public_name = snap.get(name_reg)
            impl_va = maker.get('impl_va') if maker else (
                impl.value if impl is not None and
                impl.kind == 'leadata' else None)
            if impl_va is None or not self.img.is_exec(impl_va):
                # impl da slot: risolvi via relocs
                if impl is not None and impl.kind == 'slot':
                    impl_va = self.res._impl_from_method_def(impl.value) \
                        if hasattr(self.res, '_impl_from_method_def') else None
            if impl_va is None and maker is None:
                continue
            co_slot = (maker.get('code_obj_slot') if maker else
                       (codeobj.value if codeobj is not None and
                        codeobj.kind == 'slot' else None))
            qn = (maker.get('qualname') if maker else
                  (qualname.value if qualname is not None and
                   qualname.kind == 'const' else None))
            # nome pubblico dal binding successivo (se qualname assente)
            if not qn and _i in binds:
                qn = binds[_i]
            if (not qn and public_name is not None and
                    public_name.kind == 'const' and
                    isinstance(public_name.value, str)):
                qn = public_name.value
            # V100: public_name da slot mod_consts → risolvi a valore
            if not qn and public_name is not None and                     public_name.kind == 'slot':
                _pn, _pc = self.const_for_slot(public_name.value)
                if isinstance(_pn, str):
                    qn = _pn
            # V100: ABI lazy-maker — il registro del nome portava il CODE
            # OBJECT (dict del pool): qualname esatto dai suoi metadati.
            if not qn and public_name is not None and                     public_name.kind == 'const' and                     isinstance(public_name.value, dict) and                     public_name.value.get('_type') == 'CodeObject':
                _cv = public_name.value
                qn = _cv.get('qualname') or _cv.get('name')
            if not codeobj and co_slot is None and public_name is not None                     and public_name.kind == 'slot':
                _cvs, _ = self.const_for_slot(public_name.value)
                if isinstance(_cvs, dict) and _cvs.get('_type') == 'CodeObject':
                    co_slot = public_name.value
            if not qn and maker:
                qn = maker.get('name')
            self.functions.append({
                'impl_va': impl_va,
                'impl_name': (f'impl_{impl_va:x}' if impl_va else None),
                'qualname': qn,
                'code_obj_slot': co_slot,
                'code_obj': None,
                'maker_va': maker.get('maker_va') if maker else None,
                'event_idx': len(self.functions),
            })

        # Nested defs are created when their enclosing implementation runs, so
        # their MAKE_FUNCTION call is not present in module_code_*.  Walk only
        # the implementations already proven above and recursively add maker
        # calls found in those exact native bounds.  This is a bounded graph
        # traversal, not a whole-.text name scan, and therefore also covers
        # closures several levels deep without absorbing unrelated helpers.
        known = {(function.get('maker_va'), function.get('code_obj_slot'))
                 for function in self.functions}
        queue = [function.get('impl_va') for function in self.functions
                 if function.get('impl_va')]
        scanned = set()
        while queue:
            owner_va = queue.pop(0)
            if owner_va in scanned:
                continue
            scanned.add(owner_va)
            bounds = self.img.function_bounds(owner_va)
            if bounds is None:
                continue
            size = bounds[1] - bounds[0]
            if not (0 < size <= 0x30000):
                continue
            try:
                owner_insns = self.fd.insns(
                    bounds[0], max_bytes=size,
                    stop_at_ret=False)[:50000]
            except Exception:
                continue
            for insn in owner_insns:
                if insn.mnemonic not in ('call', 'jmp') or \
                        not insn.op_str.startswith('0x'):
                    continue
                try:
                    target = int(insn.op_str, 16)
                except ValueError:
                    continue
                maker = self._decode_function_maker(target)
                if maker is None:
                    continue
                key = (maker.get('maker_va'), maker.get('code_obj_slot'))
                if key in known:
                    continue
                known.add(key)
                nested_impl = maker.get('impl_va')
                self.functions.append({
                    'impl_va': nested_impl,
                    'impl_name': (f'impl_{nested_impl:x}'
                                  if nested_impl else None),
                    'qualname': maker.get('qualname') or maker.get('name'),
                    'code_obj_slot': maker.get('code_obj_slot'),
                    'code_obj': None,
                    'maker_va': maker.get('maker_va'),
                    'owner_impl_va': owner_va,
                    'event_idx': len(self.functions),
                })
                if nested_impl:
                    queue.append(nested_impl)
        # V100: walk ricca (track registri + shape ABI lazy) sulle impl
        # provate: recupera le funzioni annidate create con costruttori
        # non-template (varianti closure, ABI lazy) che il solo
        # _decode_function_maker non riconosce.
        try:
            self._discover_function_makers_from_impls(
                f.get('impl_va') for f in self.functions
                if f.get('impl_va'))
        except Exception:
            pass

    def _discover_function_makers_from_impls(self, roots):
        """Add MAKE_FUNCTION children referenced by proven native bodies."""
        known = {(function.get('impl_va'), function.get('maker_va'),
                  function.get('code_obj_slot'))
                 for function in self.functions}
        queue = [int(root) for root in roots if root]
        scanned = set()
        added = 0
        while queue:
            owner_va = queue.pop(0)
            if owner_va in scanned:
                continue
            scanned.add(owner_va)
            bounds = self.img.function_bounds(owner_va)
            if bounds is None:
                continue
            size = bounds[1] - bounds[0]
            if not (0 < size <= 0x30000):
                continue
            try:
                insns = self.fd.insns(bounds[0], max_bytes=size,
                                      stop_at_ret=False)[:50000]
            except Exception:
                continue
            if self.img.fmt == 'pe':
                impl_reg, name_reg, qualname_reg, codeobj_reg = (
                    'rcx', 'rdx', 'r8', 'r9')
                caller_saved = ('rax', 'rcx', 'rdx', 'r8', 'r9',
                                'r10', 'r11')
            else:
                impl_reg, name_reg, qualname_reg, codeobj_reg = (
                    'rdi', 'rsi', 'rdx', 'rcx')
                caller_saved = ('rax', 'rcx', 'rdx', 'rsi', 'rdi',
                                'r8', 'r9', 'r10', 'r11')
            regs = {}

            def track(insn):
                if ',' not in insn.op_str:
                    return
                dst_text, src_text = [piece.strip()
                                      for piece in insn.op_str.split(',', 1)]
                dst = _canon_reg(dst_text)
                if dst is None:
                    return
                src = _canon_reg(src_text)
                value = None
                if insn.mnemonic == 'xor' and src == dst:
                    value = ndxS('null', 0)
                elif insn.mnemonic == 'mov' and src in regs:
                    value = regs[src]
                elif insn.mnemonic == 'mov' and re.fullmatch(
                        r'(?:0x[0-9a-f]+|-?\d+)', src_text):
                    immediate = int(src_text, 0)
                    value = ndxS('null' if immediate == 0 else 'imm',
                                 immediate)
                elif 'rip' in src_text and insn.mnemonic in ('mov', 'lea'):
                    target = rip_target(insn)
                    if target is not None:
                        constant, _where = self.const_for_slot(target)
                        if constant is not None:
                            value = ndxS('const', constant, va=target)
                        elif insn.mnemonic == 'lea' and \
                                self.img.is_exec(target):
                            value = ndxS('impl', target, va=target)
                        else:
                            value = ndxS('slot', target, va=target)
                if value is None:
                    regs.pop(dst, None)
                else:
                    regs[dst] = value

            for insn in insns:
                if insn.mnemonic in ('mov', 'lea', 'xor'):
                    track(insn)
                    continue
                if insn.mnemonic not in ('call', 'jmp'):
                    continue
                if not insn.op_str.startswith('0x'):
                    if insn.mnemonic == 'call':
                        for register in caller_saved:
                            regs.pop(register, None)
                    continue
                try:
                    target = int(insn.op_str, 16)
                except ValueError:
                    continue
                # V100: helper lazy-attach già appreso dal module-init:
                # rax = il code object (il registro rdx/rsi corrente)
                if target in self._lazy_codeobj_vas:
                    _lz = regs.get(name_reg)
                    if _lz is not None and _lz.kind == 'const' and                             isinstance(_lz.value, dict):
                        regs['rax'] = _lz
                        continue
                maker = self._decode_function_maker(target)
                # V100: la SHAPE e' essa stessa l'evidenza (lea impl +
                # code object + nome): non limitarsi ai costruttori gia'
                # appresi dal module-init — le impl usano varianti con
                # closure diverse (es. ctor diverso per funzioni annidate).
                if maker is None:
                    impl = regs.get(impl_reg)
                    name = regs.get(name_reg)
                    qualname = regs.get(qualname_reg)
                    codeobj = regs.get(codeobj_reg)
                    # V100: ABI lazy — r9 porta il code object come dict
                    # del pool (rax dell'helper lazy) e rdx puo' portare
                    # il CodeObject invece del nome.
                    _co_dict = None
                    if codeobj is not None and codeobj.kind == 'const' and                             isinstance(codeobj.value, dict) and                             codeobj.value.get('_type') == 'CodeObject':
                        _co_dict = codeobj.value
                    if name is not None and name.kind == 'const' and                             isinstance(name.value, dict) and                             name.value.get('_type') == 'CodeObject':
                        _co_dict = _co_dict or name.value
                    _name_str = (name.value if name is not None and
                                 name.kind == 'const' and
                                 isinstance(name.value, str) else None)
                    _qn_str = (qualname.value if qualname is not None and
                               qualname.kind == 'const' and
                               isinstance(qualname.value, str) else None)
                    _shape = (
                        impl is not None and impl.kind == 'impl' and
                        self.img.is_exec(impl.value) and
                        (_name_str or _co_dict is not None) and
                        (codeobj is not None or _co_dict is not None))

                    if _shape:
                        self._function_constructor_vas.add(target)
                        if _co_dict is not None:
                            _name_str = _name_str or _co_dict.get('name')
                            _qn_str = _qn_str or _co_dict.get(
                                'qualname') or _co_dict.get('name')
                        maker = {
                            'maker_va': None,
                            'constructor_va': target,
                            'impl_va': impl.value,
                            'name': _name_str,
                            'qualname': _qn_str or _name_str,
                            'code_obj_slot': (codeobj.value
                                              if codeobj is not None and
                                              codeobj.kind == 'slot'
                                              else None),
                        }
                if maker is None:
                    if insn.mnemonic == 'call':
                        for register in caller_saved:
                            regs.pop(register, None)
                    continue
                # V100: identita' = impl (+slot): maker_va/code_obj_slot
                # possono essere entrambi None nelle shape ABI lazy e la
                # chiave (None, None) colliderebbe con TUTTE le funzioni
                # module-level facendo scartare le annidate.
                key = (maker.get('impl_va'), maker.get('maker_va'),
                       maker.get('code_obj_slot'))
                # V100: il qualname e' l'identita' univoca della funzione:
                # un generatore gia' recuperato via resumer, o la stessa
                # def trovata da un percorso diverso, non va duplicata
                # (l'impl puo' differire: creatore vs resumer).
                _mq = maker.get('qualname') or maker.get('name')
                if key not in known and not (
                        _mq and any(f.get('qualname') == _mq
                                    for f in self.functions)):
                    known.add(key)
                    nested_impl = maker.get('impl_va')
                    self.functions.append({
                        'impl_va': nested_impl,
                        'impl_name': (f'impl_{nested_impl:x}'
                                      if nested_impl else None),
                        'qualname': (maker.get('qualname') or
                                     maker.get('name')),
                        'code_obj_slot': maker.get('code_obj_slot'),
                        'code_obj': None,
                        'maker_va': maker.get('maker_va'),
                        'owner_impl_va': owner_va,
                        'event_idx': len(self.functions),
                    })
                    added += 1
                    if nested_impl:
                        queue.append(nested_impl)
                if insn.mnemonic == 'call':
                    for register in caller_saved:
                        regs.pop(register, None)
        return added

    # ---------------------------------------------- generator discovery
    def _looks_like_resumer(self, va):
        """Verifica strutturale del resumer di un generatore.

        Il contesto riceve (tstate, generator, yield_return_value) e la
        PRIMA cosa che fa è leggere m_yield_return_index dal generator e
        saltare al punto di ripresa: `cmp dword ptr [rdx+off], K` (+jcc)
        oppure `mov e??, dword ptr [rdx+off]` + cmp + jcc (Win64: generator
        in rdx; SysV: rsi). L'offset varia per tipo (generator/coroutine/
        asyncgen hanno struct diverse): qui si verifica solo la forma,
        il lifter ricava l'offset dal dispatch stesso."""
        try:
            insns = self.fd.insns(va, max_bytes=0x90)[:24]
        except Exception:
            return False
        last_load = None
        for insn in insns:
            m, op = insn.mnemonic, insn.op_str
            mm = re.fullmatch(r'\w+, dword ptr \[(\w+) \+ '
                              r'(0x[0-9a-f]+|\d+)\]', op)
            cm = re.fullmatch(r'dword ptr \[(\w+) \+ (0x[0-9a-f]+|\d+)\], '
                              r'(0x[0-9a-f]+|\d+)', op)
            if (mm and mm.group(1) in gen_regs) or                     (m == 'cmp' and cm and cm.group(1) in gen_regs):
                last_load = insn.address
                continue
            if m in COND_JCC and last_load is not None and                     insn.address - last_load <= 20:
                return True
        return False

    def generator_parameter_names(self, function):
        """Read closure-array entries from the actual coroutine constructor.

        Parameter order and closure order are independent: compiler naming and
        capture analysis may reorder them. Only the native array establishes
        which parameter occupies each cell.
        """
        if '_generator_parameters' in function:
            return function['_generator_parameters']
        result = function['_generator_parameters'] = {}
        co = function.get('code_obj')
        if self.img.fmt != 'pe' or co is None:
            return result
        registers = {'r8': ('parameters',), 'rsp': ('stack', 0)}
        stack = {}
        bounds = self.img.function_bounds(function.get('impl_va'))
        if not bounds:
            return result
        for ins in self.fd.insns(bounds[0], max_bytes=bounds[1]-bounds[0], stop_at_ret=False):
            ops = split_ops(ins.op_str)

            def operand(text, dereference=True):
                reg = subreg64(text)
                if reg:
                    return registers.get(reg)
                immediate = is_imm(text)
                if immediate is not None:
                    return ('integer', immediate)
                mem = parse_mem(text)
                if not mem or mem[2]:
                    return None
                parent = registers.get(mem[0])
                if parent and parent[0] == 'parameters' and dereference and mem[1] % 8 == 0:
                    return ('parameter', mem[1]//8)
                if parent and parent[0] == 'stack':
                    key = parent[1] + mem[1]
                    return stack.get(key) if dereference else ('stack', key)
                return None

            if ins.mnemonic == 'call':
                target = is_imm(ins.op_str)
                name = self.res.resolve(target)[1] if target else None
                returned = None
                if name == 'RUNTIME_ALLOC_compiled_cell':
                    used = effective_arg_regs(self.img, self.res._fd, target)
                    values = [registers.get(reg) for reg in used]
                    parameters = [v for v in values if v and v[0] == 'parameter']
                    if len(parameters) == 1:
                        returned = parameters[0]
                elif name in ('RUNTIME_ALLOC_compiled_coroutine',
                              'RUNTIME_ALLOC_compiled_generator',
                              'RUNTIME_ALLOC_compiled_async_generator') or (function.get('resumer_va') and registers.get('rdx') == ('code', function['resumer_va'])):
                    rsp = registers.get('rsp')
                    if rsp and rsp[0] == 'stack':
                        pointer = stack.get(rsp[1] + 0x30)
                        count = stack.get(rsp[1] + 0x38)
                        if pointer and pointer[0] == 'stack' and count and count[0] == 'integer':
                            for index in range(min(count[1], len(co.varnames) + len(co.freevars))):
                                parameter = stack.get(pointer[1] + index*8)
                                if parameter and parameter[0] == 'parameter' and 0 <= parameter[1] < len(co.varnames):
                                    result[index] = co.varnames[parameter[1]]
                    return result
                for reg in MSX64_ABI.caller_saved:
                    registers.pop(reg, None)
                if returned:
                    registers['rax'] = returned
            elif ins.mnemonic in ('push', 'pop'):
                parent = registers.get('rsp')
                if parent and parent[0] == 'stack':
                    registers['rsp'] = ('stack', parent[1] + (-8 if ins.mnemonic == 'push' else 8))
                if ins.mnemonic == 'pop':
                    registers.pop(subreg64(ins.op_str), None)
            elif len(ops) == 2:
                destination = subreg64(ops[0])
                value = operand(ops[1], ins.mnemonic != 'lea')
                if ins.mnemonic == 'lea' and 'rip' in ops[1]:
                    address = rip_target(ins)
                    if address is not None and self.img.is_exec(address):
                        value = ('code', address)
                memory = parse_mem(ops[0])
                if ins.mnemonic == 'mov' and memory and memory[2] is None:
                    base = registers.get(memory[0])
                    if base and base[0] == 'stack':
                        stack[base[1] + memory[1]] = value
                if not destination:
                    continue
                if ins.mnemonic in ('add', 'sub') and registers.get(destination, (None,))[0] == 'stack':
                    immediate = is_imm(ops[1])
                    value = (('stack', registers[destination][1] + immediate*(1 if ins.mnemonic == 'add' else -1))
                             if immediate is not None else None)
                elif ins.mnemonic not in ('mov', 'lea'):
                    if ins.mnemonic in ('cmp', 'test'):
                        continue
                    value = None
                if value:
                    registers[destination] = value
                else:
                    registers.pop(destination, None)
        return result

    def detect_generators(self, cos):
        """Maker/siti di creazione generatore + collegamento ai def.

        La creazione di un generator (maker standalone o inline-ata da
        LTCG nel chiamatore) contiene sempre, in una finestra di ~40
        istruzioni: (1) il load dello slot .bss del code object, (2) una
        costante stringa (name/qualname), (3) un `lea` verso .text — il
        CONTESTO/resumer. Il filtro autoritativo è il flag
        CO_GENERATOR/COROUTINE/ASYNCGEN del code object (metadata), con
        verifica strutturale del resumer. I siti non collegati a nessun
        def sono genexpr definiti dentro un corpo."""
        if not hasattr(self, 'generators'):
            self.generators = {}
        self.genexpr_sites = []
        co_slots = set(getattr(self, 'code_objects', {}) or ())
        if not co_slots:
            for co in cos or []:
                if getattr(co, 'slot_va', None):
                    co_slots.add(co.slot_va)
        if not co_slots:
            return {}
        co_flags = {}
        for co in cos or []:
            if getattr(co, 'slot_va', None):
                co_flags[co.slot_va] = co.flags or 0
        GEN_BITS = 0x20 | 0x80 | 0x200
        fn_events = getattr(self.img, '_ndl_fn_events', None)
        if fn_events is None:
            fn_events = self.img._ndl_fn_events = {}
        # Once MAKE_FUNCTION wrappers have supplied exact implementation/code
        # object joins, generator discovery can stay inside the module's
        # reachable native graph.  Scanning every function in a large onefile
        # executable is not only wasteful; it also retains a multi-gigabyte
        # event index unrelated to the module being reconstructed.  The list
        # is deliberately dynamic: newly found resumers and nested maker impls
        # are appended while it is being traversed.
        exact_roots = {self.module.func_ptr}
        exact_roots.update(function.get('impl_va')
                           for function in self.functions
                           if function.get('impl_va'))
        exact_roots.discard(None)
        # A function-less module can still create a top-level generator
        # expression, but its modulecode is itself the authoritative root.
        # Therefore a valid module entry never needs the process-wide fallback.
        bounded_module_scan = bool(exact_roots)
        range_keys = set()
        ranges = []

        def add_candidate_range(address):
            if not address or not self.img.is_exec(address):
                return
            bounds = self.img.function_bounds(address)
            if bounds is None:
                start, end = address, address + 0x2000
            else:
                start, end = bounds
            size = end - start
            if start in range_keys or not (0 < size <= 0x30000):
                return
            range_keys.add(start)
            ranges.append((start, end))

        if bounded_module_scan:
            for root in exact_roots:
                add_candidate_range(root)
        else:
            ranges = (getattr(self.img, '_pe_function_ranges', ())
                      if self.img.fmt == 'pe' else
                      [(s, s + 0x100000)
                       for s in self.img.elf_function_starts()])
        for st, en in ranges:
            sz = en - st
            if not (0 < sz <= (0x30000 if bounded_module_scan else 0x2000)):
                continue
            off = self.img.va_to_off(st)
            if off is None:
                continue
            ev = fn_events.get(st)
            if ev is None:
                movs, leas, calls = [], [], []
                for idx, insn in enumerate(self.fd.insns(
                        st, max_bytes=sz, stop_at_ret=False)):
                    m, op = insn.mnemonic, insn.op_str
                    if 'rip' not in op:
                        if m == 'call' and op.startswith('0x'):
                            try:
                                t = int(op, 16)
                            except ValueError:
                                t = None
                            if t is not None:
                                fb = self.img.function_bounds(t)
                                calls.append((idx, t, bool(
                                    fb and fb[1] - fb[0] > 0x200)))
                        continue
                    t = rip_target(insn)
                    if t is None:
                        continue
                    if m == 'lea':
                        if self.img.is_exec(t) and not (st <= t < en):
                            leas.append((idx, t))
                    elif m == 'mov':
                        movs.append((idx, t))
                    elif m == 'call':
                        nm = self.img.imports.get(t)
                        calls.append((idx, t, nm in ('_PyObject_GC_New',
                                                     '_PyObject_GC_Malloc')))
                ev = fn_events[st] = (movs, leas, calls)
            movs, lea_events, call_events = ev
            co_events = [(idx, t) for idx, t in movs if t in co_slots]
            if not co_events:
                continue
            name_events = []
            for idx, t in movs:
                if t in co_slots:
                    continue
                cval, _c = self.const_for_slot(t)
                if isinstance(cval, str):
                    name_events.append((idx, cval))
            for ci, slot in co_events:
                slot_flags = co_flags.get(slot, 0)
                if co_flags and not (slot_flags & GEN_BITS):
                    continue
                # With authoritative CO_GENERATOR/COROUTINE/ASYNCGEN flags,
                # the executable pointer passed beside that exact code-object
                # slot is the context body even when it has no suspension and
                # therefore no yield-index dispatch.  The structural dispatch
                # check remains mandatory when metadata flags are unavailable.
                lea_cand = [lt for li, lt in lea_events
                            if abs(li - ci) <= 40 and
                            ((slot_flags & GEN_BITS) or
                             self._looks_like_resumer(lt))]
                # A MAKE_FUNCTION site (module init, class body, parent impl)
                # pairs the code-object slot with the *impl function pointer*
                # of a registered def, and neighbouring defs' pointers fall in
                # the same +-40-instruction window because the creations are
                # sequential and tight.  A generator/coroutine resumer is
                # compiler-generated body code and is never referenced by any
                # MAKE_FUNCTION, so an impl pointer is definitionally a wrong
                # resumer: it would lift the tiny generator-object wrapper
                # (or a sibling's whole body) as this def's Python body.
                known_impls = {function.get('impl_va')
                               for function in self.functions
                               if function.get('impl_va')}
                lea_cand = [lt for lt in lea_cand
                            if lt not in known_impls]
                if not lea_cand:
                    continue
                resumer = lea_cand[0]
                if not (co_flags and (slot_flags & GEN_BITS)):
                    big_call = [1 for cidx, _t, big in call_events
                                if big and abs(cidx - ci) <= 40]
                    if big_call:
                        continue
                names = [s for ni, s in name_events if abs(ni - ci) <= 40]
                info = {
                    'resumer_va': resumer,
                    'code_obj_slot': slot,
                    'name': names[0] if names else None,
                    'qualname': next((s for s in names[1:] if '.' in s),
                                     None),
                    'site': st,
                }
                site_key = st
                previous_site = self.generators.get(site_key)
                if previous_site is not None and \
                        previous_site.get('code_obj_slot') != slot:
                    # More than one generator expression/nested coroutine may
                    # be constructed in the same native parent.  The old
                    # site-only key silently discarded every entry after the
                    # first; (function, code-slot, event-index) is stable and
                    # derived entirely from the constructor stream.
                    site_key = (st, slot, ci)
                self.generators.setdefault(site_key, info)
                if bounded_module_scan:
                    add_candidate_range(resumer)
                    # A nested async/generator def is made inside its parent's
                    # resumer.  Decode that maker immediately, then enqueue its
                    # proven implementation so its own context constructor can
                    # be found without a process-wide text scan.
                    before_impls = {
                        function.get('impl_va') for function in self.functions
                        if function.get('impl_va')}
                    self._discover_function_makers_from_impls((resumer,))
                    for function in self.functions:
                        implementation = function.get('impl_va')
                        if implementation and implementation not in before_impls:
                            add_candidate_range(implementation)
        # collegamento def ↔ generatore via slot del code object
        # Coroutine/generator implementations only allocate their resumable
        # object; nested defs live in the resumer body. Discover those makers
        # before the slot join so newly found async children participate too.
        existing_slots = {function.get('code_obj_slot')
                          for function in self.functions}
        self._discover_function_makers_from_impls(
            info.get('resumer_va')
            for info in self.generators.values()
            if info.get('code_obj_slot') in existing_slots)

        f_by_coslot = {}
        for f in self.functions:
            if f.get('code_obj_slot'):
                f_by_coslot.setdefault(f['code_obj_slot'], f)
        # The generator/coroutine object is allocated by the def's own impl,
        # so the site discovered inside that impl carries the authoritative
        # resumer.  Link those entries first; entries from wider ranges
        # (module init, parents) only fill functions the impl sites did not
        # reach.  A resumer equal to the impl itself is the wrapper that
        # merely allocates the generator object and is never the body.
        gen_items = sorted(
            self.generators.items(),
            key=lambda mk_info: 0 if (
                f_by_coslot.get(mk_info[1].get('code_obj_slot')) is not None
                and mk_info[1].get('site') ==
                f_by_coslot[mk_info[1]['code_obj_slot']].get('impl_va'))
            else 1)
        for mk, info in gen_items:
            f = f_by_coslot.get(info.get('code_obj_slot'))
            if f is not None and not f.get('resumer_va') and \
                    info.get('resumer_va') != f.get('impl_va'):
                f['resumer_va'] = info['resumer_va']
                f['gen_maker'] = mk
            else:
                self.genexpr_sites.append(info)
        # CO del def per firma/parametri del generatore
        co_by_slot = {co.slot_va: co for co in cos or []
                      if getattr(co, 'slot_va', None)}
        for f in self.functions:
            if f.get('resumer_va') and f.get('code_obj_slot') in co_by_slot:
                f['code_obj'] = co_by_slot[f['code_obj_slot']]
        # ``analyze()`` can only bind accessors reached from modulecode and
        # ordinary implementations: coroutine/generator implementations merely
        # allocate their resumable object, while the Python body (and therefore
        # its module-global loads) lives in the resumer discovered above.  Run
        # the same evidence-based binding pass again now that those exact roots
        # are known.  This is essential for globals used exclusively inside
        # async/generator bodies and does not depend on source names or order.
        self._bind_accessor_names()
        return self.generators

    # -- main analysis
    def analyze(self):
        base = self.find_constants_arrays()
        if base is None:
            base = self._find_constants_by_reference()
        if self.verbose:
            print(f"  mod_consts base: {hex(base) if base else None} "
                  f"({len(self.const_slots)} slot, "
                  f"global={hex(getattr(self, 'global_base', 0) or 0)})")
        self._walk_modulecode(self.module.func_ptr)
        self._extract_functions_v2()
        self._bind_accessor_names()
        return self

    def _bind_accessor_names(self):
        """Associa i module_var_accessor alle variabili globali utente.
        Il moduledict slot VA è noto: è il target rip degli argomenti rdi/rsi
        nei binding UPDATE_STRING_DICT del modulecode. Gli accessor sono le
        leaf keys-version che lo leggono; le variabili utente sono i binding
        non-dunder con valore non-funzione, in ordine."""
        # moduledict slots: SOLO gli slot effettivamente passati come primo
        # argomento (rdi SysV / rcx MS-ABI) alle chiamate di bind
        # UPDATE_STRING_DICT* / PyDict_SetItem del modulecode. La raccolta
        # generica dei mov rip relativi contaminava slot di costanti e
        # code-object, degradando il lifting.
        mdict_slots = set()
        mod_insns = self.fd.insns(self.module.func_ptr, max_bytes=0x10000,
                                  stop_at_ret=False)[:20000]
        candidate_slots = set()
        for insn in mod_insns:
            if 'rip' in insn.op_str and insn.mnemonic == 'mov' and (
                    insn.op_str.startswith(('rdi,', 'rsi,', 'rdx,',
                                           'rcx,', 'r8,', 'r9,'))):
                t = rip_target(insn)
                if t is not None and self.img.sec_name(t) in ('.bss', '.data'):
                    candidate_slots.add(t)
        if candidate_slots:
            window = []
            for insn in mod_insns:
                window.append(insn)
                if len(window) > 16:
                    window.pop(0)
                if insn.mnemonic != 'call':
                    continue
                try:
                    t = int(insn.op_str, 16)
                except ValueError:
                    continue
                _k, nm, _s = self.res.resolve(t)
                if not (nm and (nm.startswith('UPDATE_STRING_DICT') or
                                nm in ('PyDict_SetItem',
                                       'via:PyDict_SetItem'))):
                    continue
                for prev in reversed(window[:-1]):
                    if prev.mnemonic == 'mov' and 'rip' in prev.op_str and \
                            prev.op_str.startswith(('rcx,', 'rdi,')):
                        slot = rip_target(prev)
                        if slot in candidate_slots:
                            mdict_slots.add(slot)
                        break
        # limita agli slot effettivamente usati come dict nei bind: il più
        # frequente negli argomenti rdi
        self.res.moduledict_slots = mdict_slots
        # pulisci la cache del resolver
        self.res._cache.clear()
        # raccogli accessor tra i call target di modulecode + impl
        sites = [self.module.func_ptr]
        sites.extend(f.get('impl_va') for f in self.functions
                     if f.get('impl_va'))
        sites.extend(f.get('resumer_va') for f in self.functions
                     if f.get('resumer_va'))
        cands = []
        proven_mapping = {}
        binding_names = {name for name, _value in self.bindings
                         if isinstance(name, str) and name.isidentifier() and
                         not name.startswith('__')}
        seen = set()
        for site in sites:
            if not site:
                continue
            for insn in self.fd.insns(site, max_bytes=0x8000,
                                      stop_at_ret=False)[:8000]:
                if insn.mnemonic != 'call' or not insn.op_str.startswith('0x'):
                    continue
                try:
                    t = int(insn.op_str, 16)
                except ValueError:
                    continue
                if t in seen or not self.img.is_exec(t):
                    continue
                seen.add(t)
                target_insns = self.res._func_insns(t)
                # Use the complete cached-dictionary accessor proof.  A lone
                # comparison with a RIP-loaded object is not enough: builtin
                # helpers such as zero-argument ``super()`` also compare an
                # optional argument with a static sentinel and were therefore
                # incorrectly rebound as a module variable named ``super``.
                has_keys_shape = self.res._module_accessor_name(t) is not None
                # MSVC may outline the actual cached-dict lookup once more.
                # The per-name accessor then consists of module lookup plus
                # builtins fallback: two calls to the same lookup leaf, the
                # same rip-loaded name object in the second ABI register, and
                # a successful ``PyObject **`` dereference before returning.
                # This is the generated accessor template itself, independent
                # of the spelling of the global being loaded.
                wrapper_calls = [
                    int(item.op_str, 16) for item in target_insns
                    if item.mnemonic == 'call' and
                    item.op_str.startswith('0x')]
                wrapper_name_slots = [
                    rip_target(item) for item in target_insns
                    if item.mnemonic == 'mov' and 'rip' in item.op_str and
                    item.op_str.startswith(('rdx,', 'rsi,'))]
                wrapper_name_slots = [slot for slot in wrapper_name_slots
                                      if slot is not None]
                has_accessor_wrapper = (
                    len(wrapper_calls) == 2 and
                    len(set(wrapper_calls)) == 1 and
                    len(wrapper_name_slots) >= 2 and
                    wrapper_name_slots[0] == wrapper_name_slots[1] and
                    any(item.mnemonic == 'mov' and
                        re.fullmatch(r'rax, qword ptr \[rax\]', item.op_str)
                        for item in target_insns))
                embedded_names = set()
                if has_keys_shape or has_accessor_wrapper:
                    for item in target_insns:
                        if 'rip' not in item.op_str:
                            continue
                        slot = rip_target(item)
                        value, _which = self.const_for_slot(slot)
                        if isinstance(value, str) and value.isidentifier() \
                                and not value.startswith('__'):
                            embedded_names.add(str(value))
                # Preferisci i nomi provati dai binding-event; in loro
                # assenza (build MinGW) la forma leaf keys-version con UN
                # SOLO identificatore const nel corpo è già la prova: è la
                # chiave che l'accessor cerca nel dizionario del modulo.
                bound_hits = embedded_names & binding_names
                if len(bound_hits) == 1:
                    proven_mapping[t] = next(iter(bound_hits))
                    cands.append(t)
                    continue
                if len(embedded_names) == 1:
                    proven_mapping[t] = next(iter(embedded_names))
                    cands.append(t)
                    continue
                # Ask the dedicated accessor proof directly.  Generic helper
                # signatures can collide with this small cached-dict leaf and
                # would otherwise hide it before names are bound.
                marker = self.res._module_accessor_name(t)
                if marker is not None:
                    cands.append(t)
                    continue
                _k, nm, _s = self.res.resolve(t)
                if nm and nm.startswith('module_var_accessor'):
                    cands.append(t)
        cands = sorted(set(cands))
        # Only a key read by the accessor establishes its binding.  Native
        # address order and module assignment order need not correspond.
        mapping = dict(proven_mapping)
        if not hasattr(self.res, 'accessor_names'):
            self.res.accessor_names = {}
        self.res.accessor_names.update(mapping)
        # la cache del resolver contiene i risultati pre-mapping: invalidala
        self.res._cache.clear()


    def _walk_modulecode(self, va):
        """Percorso lineare del modulecode con tracking simbolico dei registri.
        Estrae: Nuitka_Function_New → def; UPDATE_STRING_DICT → binding;
        IMPORT_MODULE_* → import; makeCodeObject → code object slots."""
        regs = {}
        stack_args = []      # push args (per calling convention)
        events = []
        for insn in self.fd.insns(va, max_bytes=0x8000)[:8000]:
            m, op = insn.mnemonic, insn.op_str
            # --- tracking push (argomenti stack)
            if m == 'push':
                stack_args.append(('push', insn))
            elif m in ('call', 'jmp') and op.startswith('0x'):
                try:
                    t = int(op, 16)
                except ValueError:
                    continue
                kind, name, sem = self.res.resolve(t)
                events.append((insn, t, kind, name, sem,
                               dict(regs), list(stack_args)))
                if m == 'call':
                    # dopo la call i caller-saved sono sporchi
                    caller_saved = (
                        ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11')
                        if self.img.fmt == 'pe' else
                        ('rax', 'rcx', 'rdx', 'rsi', 'rdi',
                         'r8', 'r9', 'r10', 'r11')
                    )
                    for register in caller_saved:
                        regs.pop(register, None)
                    # il risultato in rax
                    regs['rax'] = ndxS('ret', name)
                    # gli argomenti push sono consumati
                    stack_args = []
            elif m == 'mov' and ',' in op:
                dst, src = [x.strip() for x in op.split(',', 1)]
                if dst in regs:
                    del regs[dst]
                if src.startswith('qword ptr [rip'):
                    t = rip_target(insn)
                    if t is not None:
                        cval, cidx = self.const_for_slot(t)
                        if cval is not None:
                            regs[dst] = ndxS('const', cval, idx=cidx)
                        else:
                            nm = self.img.symbols.get(t)
                            if nm and nm.startswith('code_objects_'):
                                regs[dst] = ndxS('codeobj', nm)
                            elif nm:
                                regs[dst] = ndxS('global', nm)
                            else:
                                regs[dst] = ndxS('slot', t)
                elif src in regs:
                    regs[dst] = regs[src]
            elif m == 'lea' and ',' in op:
                dst, src = [x.strip() for x in op.split(',', 1)]
                if dst in regs:
                    del regs[dst]
                if 'rip' in src:
                    t = rip_target(insn)
                    if t is not None:
                        if self.img.is_exec(t):
                            nm = self.img.symbols.get(t) or f'sub_{t:x}'
                            regs[dst] = ndxS('func', nm, va=t)
                        else:
                            regs[dst] = ndxS('leadata', t)
        self.events = events
        # post-processing eventi → struttura
        self._extract_structure(events)

    def _extract_structure(self, events):
        """Dagli eventi call estrae la struttura del modulo.
        (solo import/bindings: le funzioni sono estratte da
        _extract_functions_v2, più robusta)"""
        func_news = []      # eventi Nuitka_Function_New
        for idx, (insn, t, kind, name, sem, regs, pushes) in enumerate(events):
            opname = sem[0] if sem else name if kind == 'plt' else None
            if kind == 'symbol' or kind == 'sig':
                opname = sem[0] if sem else None
            # Nuitka_Function_New / MAKE_FUNCTION_*
            if name in ('Nuitka_Function_New',) or (sem and sem[0] == 'make_function'):
                func_news.append((idx, insn, regs, pushes))
            elif name in ('UPDATE_STRING_DICT0', 'UPDATE_STRING_DICT1',
                          'UPDATE_STRING_DICT2') or (sem and sem[0] == 'module_bind'):
                # UPDATE_STRING_DICT*(moduledict, name_const, value)
                if self.img.fmt == 'pe':
                    name_value = regs.get('rdx') or regs.get('edx')
                    bound_value = regs.get('r8') or regs.get('r8d')
                else:
                    name_value = regs.get('rsi') or regs.get('esi')
                    bound_value = regs.get('rdx') or regs.get('edx')
                if name_value and name_value.kind == 'const':
                    self.bindings.append((name_value.value, bound_value))
            elif sem and sem[0] and sem[0].startswith('import_module'):
                rdx = regs.get('rdx') or regs.get('edx')
                if rdx and rdx.kind == 'const' and isinstance(rdx.value, str):
                    self.imports_mod.append(rdx.value)
                else:
                    rsi = regs.get('rsi')
                    if rsi and rsi.kind == 'const' and isinstance(rsi.value, str):
                        self.imports_mod.append(rsi.value)
        # funzioni: estratte da _extract_functions_v2

        # i binding successivi a un Function_New associano il nome pubblico
        for f in self.functions:
            i = f['event_idx']
            for insn, t, kind, name, sem, regs, pushes in events[i:i + 4]:
                if sem and sem[0] == 'module_bind' or name in ('UPDATE_STRING_DICT1',):
                    rsi = regs.get('rsi')
                    rdx = regs.get('rdx')
                    if rsi and rsi.kind == 'const' and rdx and rdx.kind == 'ret':
                        f['public_name'] = rsi.value
                        break


# ---------------------------------------------------------------------------
# Code object recovery (makeCodeObject call sites)
# ---------------------------------------------------------------------------

class CodeObjectInfo:
    __slots__ = ('name', 'qualname', 'argcount', 'varnames', 'flags',
                 'kwonlyargcount', 'posonlyargcount', 'firstlineno',
                 'freevars', 'slot_va', 'nlocals')

    def __init__(self):
        self.name = None
        self.qualname = None
        self.argcount = 0
        self.kwonlyargcount = 0
        self.posonlyargcount = 0
        self.varnames = ()
        self.flags = 0
        self.firstlineno = 0
        self.freevars = ()
        self.slot_va = None      # VA dello slot .bss che contiene il code obj
        self.nlocals = 0

    def __repr__(self):
        return (f"<CodeObject {self.qualname or self.name!r} argc={self.argcount} "
                f"vars={self.varnames} line={self.firstlineno} flags={self.flags:#x}>")


def extract_code_objects(img, mca, resolver, modulecode_va):
    """Estrae i code object dalle chiamate native nel modulecode.

    Il riconoscimento usa tipi e posizioni ABI degli argomenti, non il nome del
    helper.  Supporta sia Win64 (quattro registri + shadow/stack space) sia
    SysV; una firma helper eventualmente disponibile è solo evidenza
    aggiuntiva.  Il risultato viene associato allo store RIP-relativo che
    segue la call.

    La scansione copre il modulecode E le funzioni direttamente chiamate
    (createModuleConstants → createCodeObjects), ognuna LIMITATA ai propri
    confini .pdata/.eh_frame: lo walk lineare non delimitato sconfinava nei
    createCodeObjects dei moduli adiacenti (compilati in sequenza), e i
    relativi code object — nomi/varnames/firstlineno di ALTRI moduli —
    venivano attribuiti al modulo sbagliato.
    """
    out = []
    fd = FuncDisassembler(img)
    py_version = detect_python_version(img)

    scan_sites = []
    seen_sites = set()

    def _site_limit(va):
        fb = img.function_bounds(va)
        if fb is None:
            return None          # nessun unwind data: fallback storico
        return max(0x800, min(0x20000, fb[1] - fb[0]))

    def _add_site(va, depth):
        if va in seen_sites:
            return
        try:
            executable = img.is_exec(va)
        except Exception:
            executable = False
        if not executable:
            return
        seen_sites.add(va)
        limit = _site_limit(va)
        scan_sites.append((va, limit or 0x20000))
        if limit is None or depth >= 2:
            return
        for ins in fd.insns(va, max_bytes=limit,
                            stop_at_ret=False)[:3000]:
            if ins.mnemonic == 'call' and ins.op_str.startswith('0x'):
                try:
                    t = int(ins.op_str, 16)
                except ValueError:
                    continue
                _add_site(t, depth + 1)

    _add_site(modulecode_va, 0)
    if not scan_sites:
        scan_sites = [(modulecode_va, 0x20000)]

    regs = {}
    stack_args = []
    win_stack = {}
    win_stack_src = {}
    hist = []
    last_co = None

    def operand_value(operand):
        register = _canon_reg(operand)
        if register and register in regs:
            return regs[register]
        try:
            return ndxS('const', int(operand, 0))
        except (TypeError, ValueError):
            return ndxS('unknown', operand)

    def is_const(value, value_type=None):
        if value is None or value.kind != 'const':
            return False
        return value_type is None or isinstance(value.value, value_type)

    for site_va, site_limit in scan_sites:
        regs = {}
        stack_args = []
        win_stack = {}
        win_stack_src = {}
        hist = []
        for insn in fd.insns(site_va, max_bytes=site_limit,
                             stop_at_ret=False)[:30000]:
            m, op = insn.mnemonic, insn.op_str
            hist.append(insn)
            if len(hist) > 4000:
                del hist[:2000]
            if m == 'push':
                stack_args.append(operand_value(op))
            elif m == 'xor' and ',' in op:
                left, right = [part.strip() for part in op.split(',', 1)]
                if _canon_reg(left) and _canon_reg(left) == _canon_reg(right):
                    regs[_canon_reg(left)] = ndxS('const', 0)
            elif m == 'mov':
                # Win64 arguments 5+ are written into the caller's outgoing stack
                # area.  Capstone emits e.g. "qword ptr [rsp + 0x20], rax".
                stack_store = re.match(
                    r'^(?:byte|word|dword|qword) ptr '
                    r'\[rsp(?: \+ (0x[0-9a-f]+|\d+))?\], (.+)$',
                    op, re.I)
                if stack_store:
                    displacement = int(stack_store.group(1) or '0', 0)
                    win_stack[displacement] = operand_value(
                        stack_store.group(2).strip())
                    win_stack_src[displacement] = (
                        stack_store.group(2).strip(), insn.address)
                    continue

                # Store RIP-relativo: associa il valore appena restituito allo
                # slot statico del code object.
                rip_store = re.match(
                    r'^(?:dword|qword) ptr \[rip[^\]]*\], (.+)$', op, re.I)
                if rip_store:
                    target = rip_target(insn)
                    if target is not None and img.sec_name(target) in (
                            '.bss', '.data'):
                        value = operand_value(rip_store.group(1).strip())
                        if value.kind != 'unknown':
                            mca.code_objects[target] = value
                            if (last_co is not None and last_co.slot_va is None and
                                    value.kind == 'codeobj_new'):
                                last_co.slot_va = target
                                last_co = None
                    continue

                if ',' not in op:
                    continue
                dst, src = [part.strip() for part in op.split(',', 1)]
                dst_c = _canon_reg(dst)
                if not dst_c:
                    continue
                regs.pop(dst_c, None)
                if src.startswith(('qword ptr [rip', 'dword ptr [rip')):
                    target = rip_target(insn)
                    if target is not None:
                        constant, _entry = mca.const_for_slot(target)
                        if constant is not None:
                            regs[dst_c] = ndxS('const', constant)
                        elif img.sec_name(target) in ('.bss', '.data'):
                            regs[dst_c] = ndxS('slot', target)
                else:
                    value = operand_value(src)
                    if value.kind != 'unknown':
                        regs[dst_c] = value
            elif m == 'lea' and ',' in op:
                dst, src = [part.strip() for part in op.split(',', 1)]
                dst_c = _canon_reg(dst)
                if not dst_c:
                    continue
                regs.pop(dst_c, None)
                if 'rip' in src:
                    target = rip_target(insn)
                    if target is not None:
                        regs[dst_c] = ndxS('leadata', target)
                else:
                    value = operand_value(src)
                    if value.kind != 'unknown':
                        regs[dst_c] = value
            elif m == 'call':
                helper_name = None
                semantics = None
                target = None
                if op.startswith('0x'):
                    try:
                        target = int(op, 16)
                    except ValueError:
                        target = None
                    if target is not None:
                        _kind, helper_name, semantics = resolver.resolve(target)
                elif 'rip' in op:
                    # MinGW/GCC chiama PyCode_New* DIRETTAMENTE via IAT
                    # (call qword ptr [rip+…]) senza helper locale: decodifica
                    # ABI degli argomenti stack della firma CPython 3.8+.
                    iat = rip_target(insn)
                    iat_name = (getattr(img, 'imports', None) or {}).get(iat) \
                        or (getattr(img, 'plt_map', None) or {}).get(iat)
                    if iat_name in ('PyCode_NewWithPosOnlyArgs', 'PyCode_New',
                                    'PyUnstable_Code_New',
                                    'PyUnstable_Code_NewWithPosOnlyArgs'):
                        helper_name = 'makeCodeObject'
                        semantics = ('make_code_object', None)

                        def _const_val(v, types):
                            if v is not None and v.kind == 'const' and \
                                    isinstance(v.value, types):
                                return v.value
                            return None

                        def _slot_param(offset, kinds, accept_empty=True):
                            """Valore const di un parametro stack. Il tracking
                            lineare perde il valore quando un mov dentro un
                            ramo condizionale (branch-fused default) sovrascrive
                            il registro caricato da slot: rescansione a ritroso
                            dell'ultimo caricamento rip-slot dello stesso
                            registro. Con ``accept_empty=False`` la rescansione
                            scatta anche davanti alla costante vuota condivisa
                            (tupla/lista ``()``), che è il tipico valore del
                            default branch-fuso, non del parametro reale."""
                            value = _const_val(win_stack.get(offset), kinds)
                            if value is not None:
                                if accept_empty or value:
                                    return value
                            meta = win_stack_src.get(offset)
                            if not meta:
                                return None
                            src_text, store_addr = meta
                            parts = src_text.split(',', 1)
                            want = _canon_reg(parts[0].strip())
                            if not want:
                                return None
                            for prev in reversed(hist):
                                if prev.address >= store_addr:
                                    continue
                                if prev.mnemonic not in ('mov', 'cmove',
                                                        'cmovne', 'cmovz'):
                                    continue
                                if ',' not in prev.op_str:
                                    continue
                                dst_p, src_p = [p.strip() for p in
                                                prev.op_str.split(',', 1)]
                                if _canon_reg(dst_p) != want or \
                                        'rip' not in src_p:
                                    continue
                                slot = rip_target(prev)
                                if slot is None:
                                    continue
                                constant, _entry = mca.const_for_slot(slot)
                                if isinstance(constant, kinds):
                                    return constant
                                return None
                            return None

                        co_name = _slot_param(0x68, str)
                        co_line = _const_val(win_stack.get(0x70), int)
                        co_flags = _const_val(win_stack.get(0x28), int)
                        co_argc_pre = _const_val(regs.get('rcx'), int)
                        if co_name is not None and co_line is not None:
                            co = CodeObjectInfo()
                            co.name = co_name
                            co.qualname = co_name
                            # Una funzione con argomenti non può avere varnames
                            # vuoti: se il tracking lineare ha subito il
                            # branch-fused empty-tuple default, la rescansione
                            # a ritroso recupera il caricamento slot vero.
                            co_varnames = _slot_param(
                                0x48, (tuple, list),
                                accept_empty=(co_argc_pre in (None, 0)))
                            if co_varnames is not None:
                                co.varnames = tuple(co_varnames)
                            co_freevars = _slot_param(0x50, (tuple, list))
                            if co_freevars is not None:
                                co.freevars = tuple(co_freevars)
                            co_argc = _const_val(regs.get('rcx'), int)
                            if co_argc is not None:
                                co.argcount = int(co_argc)
                            co_kw = _const_val(regs.get('r8'), int)
                            if co_kw is not None:
                                co.kwonlyargcount = int(co_kw)
                            co_po = _const_val(regs.get('rdx'), int)
                            if co_po is not None:
                                co.posonlyargcount = int(co_po)
                            co.firstlineno = int(co_line)
                            co.flags = int(co_flags or 0)
                            co.nlocals = len(co.varnames)
                            out.append(co)
                            last_co = co
                            regs['rax'] = ndxS('codeobj_new', len(out) - 1)
                            stack_args = []
                            win_stack = {}
                            win_stack_src = {}
                            win_stack_src = {}
                            continue
                    # call rip-indiretta non decodificabile: invalida i
                    # caller-saved e azzera l'area stack uscente.
                    for register in (('rax', 'rcx', 'rdx', 'r8', 'r9',
                                      'r10', 'r11')):
                        regs.pop(register, None)
                    stack_args = []
                    win_stack = {}
                    win_stack_src = {}
                    continue

                if target is None and helper_name is None:
                    # chiamata indiretta non interpretabile: invalida comunque
                    # i caller-saved per non trascinare valori obsoleti.
                    for register in (('rax', 'rcx', 'rdx', 'r8', 'r9',
                                      'r10', 'r11')):
                        regs.pop(register, None)
                    stack_args = []
                    win_stack = {}
                    win_stack_src = {}
                    continue

                # compiled_frame.h: co_qualname was added to the wrapper in
                # Python 3.11. Earlier ABIs put arg_names in that position.
                # Decode an ordered argument vector before selecting the schema,
                # so Win64 shadow space and SysV register allocation agree.
                if img.fmt == 'pe':
                    native_args = [regs.get(r) for r in ('rcx', 'rdx', 'r8', 'r9')]
                    native_args += [win_stack.get(0x20 + i * 8) for i in range(6)]
                else:
                    native_args = [regs.get(r) for r in
                                   ('rdi', 'rsi', 'rdx', 'rcx', 'r8', 'r9')]
                    native_args += list(reversed(stack_args))
                native_args += [None] * 10
                name_value, line_value, flags_value = (
                    native_args[3], native_args[1], native_args[2])
                has_qualname = py_version >= (3, 11)
                qualname_value = native_args[4] if has_qualname else name_value
                index = 5 if has_qualname else 4
                varnames_value, freevars_value, argcount_value = native_args[index:index+3]
                kwonly_value = (native_args[index+3] if py_version >= (3, 0)
                                else ndxS('const', 0))
                posonly_value = (native_args[index+4] if py_version >= (3, 8)
                                 else ndxS('const', 0))

                null_or_sequence = (
                    is_const(varnames_value, (tuple, list)) or
                    (is_const(varnames_value) and varnames_value.value in (0, None))
                )
                abi_code_shape = (
                    img.is_exec(target) and
                    is_const(name_value, str) and
                    is_const(qualname_value, str) and
                    is_const(line_value, int) and
                    is_const(flags_value, int) and
                    null_or_sequence and
                    is_const(argcount_value, int) and
                    is_const(kwonly_value, int) and
                    is_const(posonly_value, int)
                )
                semantic_code_shape = (
                    semantics and semantics[0] == 'make_code_object' and
                    is_const(name_value, str) and
                    is_const(line_value, int) and
                    is_const(flags_value, int)
                )

                return_value = ndxS('ret', helper_name)
                if abi_code_shape or semantic_code_shape:
                    if abi_code_shape:
                        profile = ndx_binary_abi(img)
                        profile.observe_layout('MAKE_CODE_OBJECT.argument_names_index', index,
                            {'kind': 'constructor_argument_types', 'function': target,
                             'call_site': insn.address, 'has_qualname': has_qualname})
                    co = CodeObjectInfo()
                    co.name = name_value.value
                    co.qualname = (qualname_value.value
                                   if is_const(qualname_value, str) else co.name)
                    if is_const(varnames_value, (tuple, list)):
                        co.varnames = tuple(varnames_value.value)
                    if is_const(freevars_value, (tuple, list)):
                        co.freevars = tuple(freevars_value.value)
                    if is_const(argcount_value, int):
                        co.argcount = int(argcount_value.value)
                    if is_const(kwonly_value, int):
                        co.kwonlyargcount = int(kwonly_value.value)
                    if is_const(posonly_value, int):
                        co.posonlyargcount = int(posonly_value.value)
                    co.firstlineno = int(line_value.value)
                    co.flags = int(flags_value.value)
                    co.nlocals = len(co.varnames)
                    out.append(co)
                    last_co = co
                    return_value = ndxS('codeobj_new', len(out) - 1)

                # Caller-saved registers are invalid after every call; preserve
                # only the symbolic return value in RAX.
                caller_saved = (
                    ('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11')
                    if img.fmt == 'pe' else
                    ('rax', 'rcx', 'rdx', 'rsi', 'rdi',
                     'r8', 'r9', 'r10', 'r11')
                )
                for register in caller_saved:
                    regs.pop(register, None)
                regs['rax'] = return_value
                stack_args = []
                win_stack = {}
                win_stack_src = {}
    return out



