import re
from collections import defaultdict

# ABI profiles
# ---------------------------------------------------------------------------

class NdxABIProfile:
    """Profilo calling convention + offset ABI CPython (per versione)."""

    def __init__(self, name, arg_regs, ret_reg='rax', caller_saved=None,
                 ob_refcnt=0, ob_type=8, tp_iternext=0xe0,
                 f_lineno=0x40, tstate_cur_exc=0x60):
        self.name = name
        self.arg_regs = arg_regs          # registri argomento (ordine)
        self.ret_reg = ret_reg
        self.caller_saved = tuple(caller_saved or ())
        # offset ABI CPython
        self.ob_refcnt = ob_refcnt
        self.ob_type = ob_type
        self.tp_iternext = tp_iternext
        self.tp_iter = tp_iternext - 8
        self.f_lineno = f_lineno
        self.tstate_cur_exc = tstate_cur_exc

    def arg_reg(self, i):
        return self.arg_regs[i] if i < len(self.arg_regs) else None


SYSV_ABI = NdxABIProfile(
    'sysv', ['rdi', 'rsi', 'rdx', 'rcx', 'r8', 'r9'],
    caller_saved=('rax', 'rcx', 'rdx', 'rsi', 'rdi',
                  'r8', 'r9', 'r10', 'r11'))
MSX64_ABI = NdxABIProfile(
    'msx64', ['rcx', 'rdx', 'r8', 'r9'],
    caller_saved=('rax', 'rcx', 'rdx', 'r8', 'r9', 'r10', 'r11'))

# offset per versione python (verificati sui sorgenti CPython)
PY_ABI_OFFSETS = {
    (3, 8):  dict(tp_iternext=0xe0, f_lineno=0x70, tstate_cur_exc=0x10),
    (3, 9):  dict(tp_iternext=0xe0, f_lineno=0x70, tstate_cur_exc=0x10),
    (3, 10): dict(tp_iternext=0xe0, f_lineno=0x70, tstate_cur_exc=0x18),
    (3, 11): dict(tp_iternext=0xe0, f_lineno=0x40, tstate_cur_exc=0x18),
    (3, 12): dict(tp_iternext=0xe0, f_lineno=0x40, tstate_cur_exc=0x60),
    (3, 13): dict(tp_iternext=0xe0, f_lineno=0x40, tstate_cur_exc=0x60),
}


def abi_for(fmt, py_version=None):
    if fmt not in ('pe', 'elf'):
        raise NdxABIError('Unsupported native calling convention: '+str(fmt))
    version = tuple(py_version[:2]) if py_version is not None else None
    if version not in PY_ABI_OFFSETS:
        raise NdxABIError('Unknown or unsupported Python ABI: '+str(version))
    abi = MSX64_ABI if fmt == 'pe' else SYSV_ABI
    off = PY_ABI_OFFSETS[version]
    return NdxABIProfile(abi.name, abi.arg_regs, 'rax', abi.caller_saved, 0, 8,
                         off['tp_iternext'], off['f_lineno'], off['tstate_cur_exc'])


# This block is integrated into the single-file decompiler by round6_integrate.py.
class NdxABIError(ValueError):
    pass


def ndx_platform_evidence(data):
    """Read architecture from file headers, without executing or disassembling."""
    result = {'format': None, 'architecture': None, 'bits': None,
              'endianness': None, 'calling_convention': None,
              'native_decoder_supported': False, 'evidence': [], 'issues': []}
    try:
        if data[:2] == b'MZ':
            pe = struct.unpack_from('<I', data, 0x3c)[0]
            if data[pe:pe+4] != b'PE\0\0':
                raise ValueError('invalid PE signature')
            machine = struct.unpack_from('<H', data, pe+4)[0]
            magic = struct.unpack_from('<H', data, pe+24)[0]
            arch = {0x8664: 'x86_64', 0x14c: 'x86', 0xaa64: 'aarch64', 0x1c4: 'arm'}.get(machine)
            result.update(format='pe', architecture=arch, bits={0x20b:64,0x10b:32}.get(magic), endianness='little')
            result['evidence'].append({'kind':'PE.COFF.Machine', 'offset':pe+4, 'value':machine})
            if arch == 'x86_64' and magic == 0x20b:
                result.update(calling_convention='msx64', native_decoder_supported=True)
        elif data[:4] == b'\x7fELF':
            bits = {1:32,2:64}.get(data[4]); endian = {1:'little',2:'big'}.get(data[5])
            if endian is None:
                raise ValueError('invalid ELF byte order')
            machine = struct.unpack_from('<H' if endian == 'little' else '>H', data, 18)[0]
            arch = {62:'x86_64',3:'x86',183:'aarch64',40:'arm',243:'riscv'}.get(machine)
            result.update(format='elf', architecture=arch, bits=bits, endianness=endian)
            result['evidence'].append({'kind':'ELF.e_machine', 'offset':18, 'value':machine})
            if arch == 'x86_64' and bits == 64 and endian == 'little':
                result.update(calling_convention='sysv', native_decoder_supported=True)
        elif data[:4] in (b'\xcf\xfa\xed\xfe', b'\xce\xfa\xed\xfe', b'\xfe\xed\xfa\xcf', b'\xfe\xed\xfa\xce'):
            little = data[:4] in (b'\xcf\xfa\xed\xfe',b'\xce\xfa\xed\xfe')
            cpu = struct.unpack_from('<I' if little else '>I', data, 4)[0]
            result.update(format='macho', architecture={0x1000007:'x86_64',7:'x86',0x100000c:'aarch64',12:'arm'}.get(cpu),
                          bits=64 if cpu & 0x1000000 else 32, endianness='little' if little else 'big')
            result['evidence'].append({'kind':'MachO.cputype', 'offset':4, 'value':cpu})
            if cpu == 0x1000007:
                result['calling_convention'] = 'sysv'
            result['issues'].append('Mach-O native loader is not implemented')
        elif data[:4] in (b'\xca\xfe\xba\xbe', b'\xbe\xba\xfe\xca', b'\xca\xfe\xba\xbf'):
            result['format'] = 'macho-fat'
            result['issues'].append('Multiple architecture slices require explicit selection')
        else:
            result['issues'].append('Unrecognized executable header')
    except (IndexError, ValueError, struct.error) as error:
        result['issues'].append('Malformed executable header: '+str(error))
    if not result['native_decoder_supported'] and not result['issues']:
        result['issues'].append('No native decoder for this architecture and format')
    return result


class NdxBinaryABI:
    """Per-image evidence, separate from layout candidates and helper inference."""
    def __init__(self, image, python_override=None):
        import hashlib
        self.image = image
        self.platform = ndx_platform_evidence(image.data)
        self.sha256 = hashlib.sha256(image.data).hexdigest()
        self.helpers = {}
        self.layouts = {}
        self.unresolved_values = {}
        self.python = self._python_evidence(python_override)
        self._signature_cache = {}
        self._signature_busy = set()
        self._layout_candidates()

    def _python_evidence(self, override):
        patterns = [re.compile(rb'python([23])(\d{1,2})((?:[dt]|_d)*)\.dll$', re.I),
                    re.compile(rb'libpython([23])\.(\d{1,2})([dt]*)(?:\.\d+)?\.(?:so(?:\.\d+)*|dylib)$',re.I)]
        evidence, hints = [], []
        for library in getattr(self.image, 'imported_libraries', ()):
            name = str(library).replace('\\','/').rsplit('/',1)[-1].encode('ascii',errors='ignore')
            for pattern in patterns:
                match = pattern.fullmatch(name)
                if match:
                    evidence.append({'kind':'imported_library','library':str(library),
                        'version':[int(match[1]),int(match[2])], 'build_flags':match[3].decode().lower()})
        # Incidental strings are hints, never a substitute for imported metadata.
        if not evidence:
            for match in re.finditer(rb'(?<![A-Za-z0-9_])(?:python[23]\d{1,2}[dt]*\.dll|libpython[23]\.\d{1,2}[dt]*\.so(?:\.\d+)*)', self.image.data, re.I):
                hint={'kind':'binary_string','offset':match.start(),'text':match[0].decode('ascii')}
                if hint['text'] not in {item['text'] for item in hints}:
                    hints.append(hint)
        versions = {tuple(item['version']) for item in evidence}
        flags = {item['build_flags'] for item in evidence}
        result={'version':None,'status':'unknown','evidence':evidence,'hints':hints,'issues':[]}
        if len(versions) == 1 and len(flags) == 1:
            result.update(version=list(next(iter(versions))),status='identified')
            if next(iter(flags)):
                result['issues'].append('Debug/free-threaded runtime layout is not validated')
        elif len(versions)>1 or len(flags)>1:
            result['status']='conflict'; result['issues'].append('Conflicting Python runtime imports')
        if override is not None:
            version = _ndl_parse_target_python_version(override)
            if versions and (len(versions)!=1 or version not in versions):
                result['status']='conflict';result['issues'].append('Explicit Python version contradicts imported runtime')
            elif not versions:
                result.update(version=list(version),status='user_override')
                result['evidence'].append({'kind':'explicit_override','version':list(version)})
        return result

    def _layout_candidates(self):
        version=tuple(self.python['version'] or ())
        if version in PY_ABI_OFFSETS and self.platform['bits']==64:
            for field,value in PY_ABI_OFFSETS[version].items():
                self.layouts[field]={'value':value,'status':'version_candidate',
                    'evidence':[{'kind':'version_table','version':list(version)}]}
        for field,value in (('PyObject.ob_type',8),('Nuitka_CellObject.ob_ref',16)):
            self.layouts[field]={'value':value if self.platform['bits']==64 else None,
                'status':'platform_candidate','evidence':[]}

    def observe_layout(self, field, value, proof):
        entry=self.layouts.setdefault(field,{'value':value,'status':'observed','evidence':[]})
        if entry['value'] != value:
            entry['status']='conflict'
            entry.setdefault('alternatives',[])
            if value not in entry['alternatives']:entry['alternatives'].append(value)
        elif entry['status'] != 'conflict':
            entry['status']='corroborated'
        if proof not in entry['evidence']:entry['evidence'].append(proof)

    def version(self):
        return tuple(self.python['version']) if self.python['version'] is not None else None

    def require_native(self):
        issues=list(self.platform['issues'])+list(self.python['issues'])
        if not self.platform['native_decoder_supported']:
            issues.append('Unsupported native ABI')
        if self.version() is None or self.python['status']=='conflict':
            issues.append('Python ABI is unknown or conflicting; no default version is assumed')
        elif self.version() not in PY_ABI_OFFSETS:
            issues.append('No validated runtime layout profile for Python '+'.'.join(map(str,self.version())))
        if issues:
            raise NdxABIError('; '.join(dict.fromkeys(issues)))

    def abi(self):
        self.require_native()
        return abi_for(self.platform['format'],self.version())

    def helper(self, va):
        return self.helpers.setdefault(va,{'address':va,'semantic':None,'semantic_evidence':'unknown','calls':{}})

    def record_semantic(self, va, resolution):
        kind,name,sem=resolution
        entry=self.helper(va)
        entry.update(name=name,semantic=sem,semantic_evidence=kind)
        if sem and sem[0] == 'tuple_dict_call':
            for field,value in (('PyObject.ob_type',8),('PyTypeObject.tp_call',0x80)):
                self.observe_layout(field,value,{'kind':'native_dispatch_chain','function':va})
        if sem and sem[0] == 'vector_keywords':
            self.observe_layout('PyTypeObject.tp_vectorcall_offset',0x38,{'kind':'native_vectorcall_protocol','function':va})

    def record_call(self, target, site, registers, values, stack):
        entry=self.helper(target)
        observed={reg:('unknown' if value is None or getattr(value,'op',None)=='unknown' else 'available')
                  for reg,value in zip(registers,values)}
        signature=entry.get('signature',{})
        for offset in signature.get('stack_offsets',()):
            key='stack+'+hex(offset)
            # Callee entry RSP includes the return address pushed by CALL.
            value=stack.get(('rsp',offset-8))
            observed[key]='unknown' if value is None else 'available'
        entry['calls'][site]={'address':site,'locations':observed,
                             'status':'incomplete' if 'unknown' in observed.values() else 'consistent'}

    def unknown(self, site, location):
        self.unresolved_values[(site,str(location))]={'address':site,'location':str(location)}

    def report(self):
        helpers=[]
        for va,stored in sorted(self.helpers.items()):
            entry={key:value for key,value in stored.items() if not key.startswith('_')}
            entry['calls']=list(stored['calls'].values());helpers.append(entry)
        issues=list(self.platform['issues'])+list(self.python['issues'])
        issues += ['Conflicting runtime layout: '+field for field,entry in self.layouts.items() if entry['status']=='conflict']
        return {'schema':'ndx-abi/1','target':str(getattr(self.image,'path','')),'sha256':self.sha256,
            'application_executed':False,'platform':self.platform,'python_runtime':self.python,
            'runtime_layouts':self.layouts,'helpers':helpers,
            'unresolved_values':list(self.unresolved_values.values()),
            'coverage':{'helpers_observed':len(helpers),'call_sites_observed':sum(len(x['calls']) for x in helpers),
                'scope':'Only functions and call sites actually analyzed; not exhaustive for the entire image'},
            'issues':issues,'source_equivalence':'unverified'}

    def write(self, directory):
        os.makedirs(directory,exist_ok=True)
        path=os.path.join(directory,'ABI_REPORT.json')
        with open(path,'w',encoding='utf8') as handle:
            json.dump(self.report(),handle,indent=2,ensure_ascii=False,default=str)
        return path


def ndx_binary_abi(image, python_override=None):
    profile=getattr(image,'_ndx_binary_abi',None)
    if profile is None or python_override is not None:
        profile=NdxBinaryABI(image,python_override)
        image._ndx_binary_abi=profile
    return profile


def ndx_function_abi(img, fd, va, instruction_budget=16384, depth=0):
    """CFG live-in analysis: joins, cold arms, zero idioms and entry stack slots.

    Budgets/unknown transfers are explicit. An observed input is not an exact
    C prototype, and a partial analysis never proves that other inputs are absent.
    """
    profile=ndx_binary_abi(img);abi=profile.abi()
    cache_key=(va,instruction_budget,depth)
    if cache_key in profile._signature_cache:return profile._signature_cache[cache_key]
    if va in profile._signature_busy or depth>4:
        return {'status':'partial','registers':[],'stack_offsets':[],'issues':['recursive or deep forwarding']}
    bounds=img.function_bounds(va)
    if bounds is None:
        result={'status':'unknown','registers':[],'stack_offsets':[],'issues':['missing function boundaries']}
        profile._signature_cache[cache_key]=result;profile.helper(va)['signature']=result
        return result
    profile._signature_busy.add(va)
    try:
        instructions=fd.insns(va,max_bytes=bounds[1]-va,stop_at_ret=False)
        issues=set()
        if len(instructions)>instruction_budget:
            instructions=instructions[:instruction_budget];issues.add('instruction budget exhausted')
        if not instructions:
            return {'status':'unknown','registers':[],'stack_offsets':[],'issues':['no decoded instructions']}
        positions={ins.address:i for i,ins in enumerate(instructions)}
        # A join keeps only registers definitely written on EVERY predecessor.
        incoming={};pending=[(0,frozenset(),{'rsp':0})]
        live=set();stack_args=set();evidence={};steps=0
        candidates=list(abi.arg_regs)+['xmm'+str(i) for i in range(4 if img.fmt=='pe' else 8)]
        volatile=list(abi.caller_saved)+['xmm'+str(i) for i in range(6 if img.fmt=='pe' else 16)]
        first_stack=0x28 if img.fmt=='pe' else 8
        def use(reg,written,address):
            if reg in candidates and reg not in written:
                live.add(reg);evidence.setdefault(reg,set()).add(address)
        while pending and steps<max(1024,len(instructions)*32):
            index,written,aliases=pending.pop()
            if index>=len(instructions):
                issues.add('control flow exceeds decoded boundary');continue
            if index in incoming:
                old_w,old_a=incoming[index]
                merged_w=old_w & written
                merged_a={r:v for r,v in old_a.items() if aliases.get(r)==v}
                if merged_w==old_w and merged_a==old_a:continue
                written,aliases=merged_w,merged_a
            incoming[index]=(written,dict(aliases));written=set(written);aliases=dict(aliases);steps+=1
            ins=instructions[index];ops=split_ops(ins.op_str);mn=ins.mnemonic
            if mn in ('ret','iret','iretq','ud2','hlt'):continue
            zero=(len(ops)==2 and mn in ('xor','sub','pxor','xorps','xorpd') and ops[0]==ops[1])
            try:reads,writes=ins.regs_access()
            except Exception:
                reads,writes=(),();issues.add('instruction register effects unavailable')
            if not zero:
                for register in reads:
                    name=ins.reg_name(register);use(subreg64(name) or name,written,ins.address)
            for operand_index,operand in enumerate(ops):
                memory=parse_mem(operand)
                memory_read=(operand_index>0 and mn!='lea') or mn in ('cmp','test','push','call','jmp')
                if memory_read and memory and memory[0] in aliases and not memory[2]:
                    offset=aliases[memory[0]]+memory[1]
                    if offset>=first_stack and offset%8==0 and ('stack',offset) not in written:
                        stack_args.add(offset);evidence.setdefault('stack+'+hex(offset),set()).add(ins.address)
            # A load of a stack word overwritten on every predecessor is a
            # local spill, not an incoming argument.
            store=parse_mem(ops[0]) if ops and mn in ('mov','movabs') and ops[0].startswith('qword ptr ') else None
            if store and store[0] in aliases and not store[2]:
                written.add(('stack',aliases[store[0]]+store[1]))
            if mn in ('call','jmp'):
                target=is_imm(ins.op_str)
                local=positions.get(target)
                if mn=='jmp' and local is not None:
                    pending.append((local,frozenset(written),aliases));continue
                import_name=img.imports.get(rip_target(ins)) if 'rip' in ins.op_str else getattr(img,'plt_map',{}).get(target)
                if import_name in ('__chkstk','__chkstk_ms','_alloca_probe'):
                    required=[]
                elif target is not None and img.is_exec(target):
                    child=ndx_function_abi(img,fd,target,instruction_budget,depth+1)
                    required=child['registers']+child.get('floating_registers',[])
                    for child_offset in child.get('stack_offsets',()):
                        if 'rsp' not in aliases:
                            issues.add('forwarded stack base is unknown');continue
                        offset=aliases['rsp']+child_offset-(8 if mn=='call' else 0)
                        if offset>=first_stack and ('stack',offset) not in written:
                            stack_args.add(offset);evidence.setdefault('stack+'+hex(offset),set()).add(ins.address)
                    if child['status']!='analyzed':issues.add('partial callee forwarding')
                else:
                    # Directly observed input reads remain useful, but unknown
                    # calls do not establish an exact register mask.
                    required=[];issues.add('external or indirect forwarding not fully typed')
                for register in required:use(register,written,ins.address)
                if mn=='jmp':continue
                if import_name not in ('__chkstk','__chkstk_ms','_alloca_probe'):
                    written.update(volatile)
                    for register in volatile:aliases.pop(register,None)
            elif mn.startswith('j') or mn in ('loop','loope','loopne','jrcxz'):
                target=positions.get(branch_target(ins))
                if target is None:issues.add('branch target outside known function')
                else:pending.append((target,frozenset(written),dict(aliases)))
            if mn=='push':
                if 'rsp' in aliases:aliases['rsp']-=8
            elif mn=='pop':
                if 'rsp' in aliases:aliases['rsp']+=8
            elif len(ops)==2:
                dst=subreg64(ops[0]);src=subreg64(ops[1]);memory=parse_mem(ops[1]);new=None
                if mn=='mov' and src in aliases:new=aliases[src]
                elif mn=='lea' and memory and memory[0] in aliases and not memory[2]:new=aliases[memory[0]]+memory[1]
                elif mn in ('add','sub') and dst in aliases and is_imm(ops[1]) is not None:new=aliases[dst]+is_imm(ops[1])*(1 if mn=='add' else -1)
                if dst and mn not in ('cmp','test'):
                    aliases.pop(dst,None)
                    if new is not None:aliases[dst]=new
            for register in writes:
                name=ins.reg_name(register)
                # A conditional move or an 8/16-bit write does not define the
                # full incoming register on every path.
                if not mn.startswith('cmov') and (name in candidates or name.startswith('e') or name.endswith('d')):
                    written.add(subreg64(name) or name)
            pending.append((index+1,frozenset(written),aliases))
        if pending:issues.add('CFG analysis budget exhausted')
        result={'status':'partial' if issues else 'analyzed','registers':[r for r in abi.arg_regs if r in live],
            'floating_registers':[r for r in candidates if r.startswith('xmm') and r in live],
            'stack_offsets':sorted(stack_args),'issues':sorted(issues),'instructions_analyzed':len(incoming),
            'evidence':{reg:sorted(sites) for reg,sites in evidence.items()},
            'meaning':'Observed input locations, not a recovered C prototype'}
        profile._signature_cache[cache_key]=result
        entry=profile.helper(va)
        if depth<=entry.get('_analysis_depth',99):
            entry['signature']=result;entry['_analysis_depth']=depth
        return result
    finally:
        profile._signature_busy.discard(va)


def ndx_abi_extract(target, out_dir, python_override=None):
    """Standalone discovery also returns explicit reports for unsupported inputs."""
    with open(target,'rb') as handle:data=handle.read()
    platform=ndx_platform_evidence(data)
    image=None
    load_error=None
    if platform['native_decoder_supported']:
        try:
            image=load_image(target)
            image,_onefile=_ndx_resolve_effective_image(target,image)
        except Exception as error:
            load_error='Executable loader: '+str(error)
    if image is None:
        from types import SimpleNamespace
        image=SimpleNamespace(data=data,path=target,imported_libraries=[])
    profile=ndx_binary_abi(image,python_override)
    if load_error:
        profile.platform['issues'].append(load_error)
    if profile.platform['native_decoder_supported'] and profile.version() is not None:
        try:
            profile.require_native()
            resolver=HelperResolver(image,sig_db=globals().get('_NDX_SIG_DB'))
            starts=[image.entry]
            starts += [address for address,name in getattr(image,'symbols',{}).items() if image.is_exec(address)]
            # Standalone mode analyzes entry/exported functions. Full recovery
            # contributes all reached helpers, without an indiscriminate scan.
            for address in dict.fromkeys(starts):
                if address:
                    resolver.resolve(address)
                    ndx_function_abi(image,resolver._fd,address)
        except NdxABIError:
            pass
    profile.write(out_dir)
    return profile


def ndx_prepare_abi_image(target, out_dir, python_override=None):
    """Persist discovery before any version-dependent constants decoding."""
    with open(target,'rb') as handle:data=handle.read()
    from types import SimpleNamespace
    raw=SimpleNamespace(data=data,path=target,imported_libraries=[])
    probe=ndx_binary_abi(raw,python_override)
    try:
        if not probe.platform['native_decoder_supported']:
            probe.require_native()
        outer=BinaryImage(data,path=target)
        image,onefile=_ndx_resolve_effective_image(target,outer)
        probe=ndx_binary_abi(image,python_override)
        probe.require_native()
        return outer,image,onefile,probe
    except Exception as error:
        probe.platform['issues'].append(str(error))
        raise
    finally:
        probe.write(out_dir)


# ---------------------------------------------------------------------------
# Valori simbolici
# ---------------------------------------------------------------------------

class NdxSV:
    """Symbolic value: nodo di espressione Python ricostruibile."""
    __slots__ = ('op', 'a', 'b', 'c', 'n')

    def __init__(self, op, a=None, b=None, c=None, n=None):
        self.op = op      # const|par|var|temp|call|getattr|binop|cmp|unary|
        self.a = a        #         bool|iter|next|sub|none|true|false|mod|
        self.b = b        #         moddict|codeobj|list|dict|set|tuple|format|
        self.c = c        #         fstring|unknown|global|exc|unpack|attribute
        self.n = n

    def __repr__(self):
        return f'<NdxSV {self.op} {self.a!r} {self.b!r}>'


def ndx_k(op, a=None, b=None, c=None, n=None):
    return NdxSV(op, a, b, c, n)


# ---------------------------------------------------------------------------
# IR ops
# ---------------------------------------------------------------------------

class NdxOp:
    __slots__ = ('kind', 'a', 'b', 'c', 'n', 'va')

    def __init__(self, kind, a=None, b=None, c=None, n=None, va=0):
        self.kind = kind
        self.a = a
        self.b = b
        self.c = c
        self.n = n
        self.va = va

    def __repr__(self):
        return f'<{self.kind} {self.a!r} {self.b!r}>'


class NdxBB:
    """Basic block con IR."""
    __slots__ = ('start', 'end', 'insns', 'succs', 'preds', 'kind',
                 'ops', 'edges', 'conds', 'loop_id', 'flags')

    def __init__(self, start):
        self.start = start
        self.end = start
        self.insns = []
        self.succs = []
        self.preds = []
        self.kind = 'normal'   # normal|error|handler|epilogue|noise
        self.ops = []
        self.edges = []        # [(target, etype)] etype: normal|error|cond
        self.conds = []        # [(target, etype, cond_sym)]
        self.loop_id = None
        self.flags = set()

    def __repr__(self):
        return (f'<NdxBB {self.start:#x}-{self.end:#x} {self.kind} '
                f'ops={len(self.ops)}>')


JCC_MAP = {
    'je': ('eq', False), 'jne': ('ne', False),
    'jl': ('lt', False), 'jg': ('gt', False),
    'jle': ('le', False), 'jge': ('ge', False),
    'jb': ('lt', False), 'ja': ('gt', False),
    'jbe': ('le', False), 'jae': ('ge', False),
    'js': ('neg', False), 'jns': ('pos', False),
}
COND_JCC = set(JCC_MAP) | {'jp', 'jnp', 'jo', 'jno'}


# ---------------------------------------------------------------------------
# helper: parse operandi capstone
# ---------------------------------------------------------------------------

_R64 = {'rax', 'rbx', 'rcx', 'rdx', 'rsi', 'rdi', 'rbp', 'rsp',
        'r8', 'r9', 'r10', 'r11', 'r12', 'r13', 'r14', 'r15'}


def split_ops(op_str):
    """Split operandi Intel al top level (fuori da parentesi)."""
    parts, depth, cur = [], 0, ''
    for ch in op_str:
        if ch == '[':
            depth += 1
        elif ch == ']':
            depth -= 1
        if ch == ',' and depth == 0:
            parts.append(cur.strip())
            cur = ''
        else:
            cur += ch
    if cur.strip():
        parts.append(cur.strip())
    return parts


_MEM_RE = re.compile(
    r'^(?:(?:qword|dword|word|byte|tbyte|xmmword|ymmword) ptr\s+)?'
    r'\[([^\]]+)\]$')


def parse_mem(op_str):
    """'[rsp + 0x20]' → ('rsp', 0x20, None, 1); con index*scale completo.
    Intel syntax. Ritorna None se non è un riferimento a memoria."""
    s = op_str.strip()
    m = _MEM_RE.match(s)
    if not m:
        return None
    inner = m.group(1).replace(' ', '')
    base = None
    index = None
    scale = 1
    disp = 0
    for p in re.split(r'(?=[+-])', inner):
        if not p:
            continue
        sign = 1
        if p.startswith('+'):
            p = p[1:]
        elif p.startswith('-'):
            sign = -1
            p = p[1:]
        if not p:
            continue
        if '*' in p:
            a, b = p.split('*', 1)
            try:
                if re.match(r'^0x[0-9a-f]+$', a) or a.isdigit():
                    # scale*index
                    scale = int(a, 16 if a.startswith('0x') else 10)
                    index = b
                else:
                    index = a
                    scale = int(b, 16 if b.startswith('0x') else 10)
            except ValueError:
                pass
        elif re.match(r'^0x[0-9a-f]+$', p):
            disp += sign * int(p, 16)
        elif re.match(r'^[0-9]+$', p):
            disp += sign * int(p)
        elif re.match(r'^[a-z0-9]+$', p):
            if sign < 0:
                return None
            if base is None:
                base = p
            elif index is None:
                index = p
            else:
                return None
    return (base, disp, index, scale)


def is_imm(op_str):
    s = op_str.strip()
    if re.match(r'^-?0x[0-9a-f]+$', s):
        return int(s, 16)
    if re.match(r'^-?[0-9]+$', s):
        return int(s)
    return None


_R64 = {'rax', 'rbx', 'rcx', 'rdx', 'rsi', 'rdi', 'rbp', 'rsp',
        'r8', 'r9', 'r10', 'r11', 'r12', 'r13', 'r14', 'r15'}


def reg_of(insn, which=0):
    ops = split_ops(insn.op_str)
    if len(ops) > which:
        return ops[which]
    return None


def is_reg(name):
    return name in _R64


def subreg64(r):
    """eax→rax, r12d→r12, al→rax ..."""
    if not r:
        return None
    r = r.strip().lstrip('%')
    m = {'eax': 'rax', 'ebx': 'rbx', 'ecx': 'rcx', 'edx': 'rdx',
         'esi': 'rsi', 'edi': 'rdi', 'ebp': 'rbp', 'esp': 'rsp',
         'ax': 'rax', 'bx': 'rbx', 'cx': 'rcx', 'dx': 'rdx',
         'al': 'rax', 'bl': 'rbx', 'cl': 'rcx', 'dl': 'rdx',
         'sil': 'rsi', 'dil': 'rdi', 'bpl': 'rbp', 'spl': 'rsp',
         'r8d': 'r8', 'r9d': 'r9', 'r10d': 'r10', 'r11d': 'r11',
         'r12d': 'r12', 'r13d': 'r13', 'r14d': 'r14', 'r15d': 'r15',
         'r8b': 'r8', 'r9b': 'r9', 'r10b': 'r10', 'r11b': 'r11',
         'r12b': 'r12', 'r13b': 'r13', 'r14b': 'r14', 'r15b': 'r15',
         'r8w': 'r8', 'r9w': 'r9', 'r10w': 'r10', 'r11w': 'r11',
         'r12w': 'r12', 'r13w': 'r13', 'r14w': 'r14', 'r15w': 'r15'}
    if r in m:
        return m[r]
    mm = re.match(r'^r(\d+)[dwb]?$', r)
    if mm:
        return 'r' + mm.group(1)
    return r if r in _R64 else None


# ---------------------------------------------------------------------------
# Effective argument registers: inferenza dal machine code del chiamato
# ---------------------------------------------------------------------------

_ARG_ORDER_SYSV = ['rdi', 'rsi', 'rdx', 'rcx', 'r8', 'r9']
_ARG_ORDER_MS = ['rcx', 'rdx', 'r8', 'r9']


def _operand_regs(op_str):
    """Registri citati in un operando AT&T."""
    regs = re.findall(r'%([a-z0-9]+)', op_str)
    out = []
    for r in regs:
        r64 = subreg64(r)
        if r64 and r64 not in out:
            out.append(r64)
    return out


VOLATILE_REGS = ('rax', 'rcx', 'rdx', 'rsi', 'rdi', 'r8', 'r9', 'r10', 'r11')


def effective_arg_regs(img, fd, va, cache=None, max_insns=16384, depth=0,
                       _in_progress=None):
    """Observed native inputs from CFG analysis, with uncertainty in ABI_REPORT.

    This compatibility interface returns observed locations; missing boundaries
    or no observed locations require the caller to retain the platform ABI.
    Structural helper protocols take precedence over this inferred mask.
    """
    signature = ndx_function_abi(img, fd, va, max_insns, depth)
    if signature['status'] == 'unknown':
        return None
    result = signature['registers']
    if signature.get('stack_offsets'):
        result = list(ndx_binary_abi(img).abi().arg_regs)
    return list(result) if result or signature['status'] == 'analyzed' else None


_IN_PROGRESS = object()


# ---------------------------------------------------------------------------
# Body lifter
# ---------------------------------------------------------------------------

_BUILTIN_EXCEPTION_NAMES = frozenset((
    'BaseException', 'Exception', 'ArithmeticError', 'AssertionError',
    'AttributeError', 'BufferError', 'EOFError', 'FloatingPointError',
    'GeneratorExit', 'ImportError', 'ModuleNotFoundError', 'IndexError',
    'KeyError', 'KeyboardInterrupt', 'LookupError', 'MemoryError',
    'NameError', 'NotImplementedError', 'OSError', 'IOError',
    'OverflowError', 'RecursionError', 'ReferenceError', 'RuntimeError',
    'StopIteration', 'StopAsyncIteration', 'SyntaxError', 'SystemError',
    'SystemExit', 'TypeError', 'UnboundLocalError', 'UnicodeError',
    'UnicodeDecodeError', 'UnicodeEncodeError', 'UnicodeTranslateError',
    'ValueError', 'ZeroDivisionError', 'EnvironmentError',
    'FileNotFoundError', 'FileExistsError', 'PermissionError',
    'NotADirectoryError', 'IsADirectoryError', 'InterruptedError',
    'ConnectionError', 'ConnectionResetError', 'ConnectionAbortedError',
    'BrokenPipeError', 'TimeoutError', 'BlockingIOError',
    'ChildProcessError', 'ProcessLookupError', 'UnicodeWarning',
    'Warning', 'UserWarning', 'DeprecationWarning', 'RuntimeWarning',
    'FutureWarning', 'PendingDeprecationWarning', 'ImportWarning',
    'ResourceWarning', 'BytesWarning', 'EncodingWarning',
    'FloatingPointError', 'IndentationError', 'TabError'))


class BodyLifter2:
    """Esecuzione simbolica di una funzione impl_Nuitka → IR ops."""

    def __init__(self, img, resolver, mca, code_obj, func_va,
                 py_version=None, verbose=False, is_module_code=False):
        self.img = img
        self.res = resolver
        self.mca = mca
        self.co = code_obj
        self.va = func_va
        # Su build GCC/MinGW il VA dell'impl estratto dai reloc può cadere
        # a METÀ funzione (cold-part / clone): il lifting partiva dal punto
        # sbagliato e perdeva l'intero fast-path iniziale. Normalizza sempre
        # all'inizio LOGICO della funzione (.pdata chained / eh_frame).
        try:
            fb = img.function_bounds(func_va)
        except Exception:
            fb = None
        if fb and fb[0] != func_va and fb[0] <= func_va < fb[1]:
            self.va = fb[0]
        self.verbose = verbose
        self.is_module_code = is_module_code
        self.abi = abi_for(img.fmt, py_version or detect_python_version(img))
        self.py_version = py_version
        self.fd = FuncDisassembler(img)
        self.varnames = list(code_obj.varnames) if code_obj else []
        if code_obj is not None:
            # python_pars contains every source parameter, not only
            # co_argcount's positional portion.  Reserve kw-only, *args and
            # **kwargs too; otherwise Structurer reuses their names for SSA
            # temporaries (notably ``kwargs`` and the ``__class__`` cell).
            self.argcount = (
                int(code_obj.argcount or 0) +
                int(getattr(code_obj, 'kwonlyargcount', 0) or 0) +
                (1 if code_obj.flags & 0x04 else 0) +
                (1 if code_obj.flags & 0x08 else 0))
            self.freevars = set(getattr(code_obj, 'freevars', ()) or ())
            # Closure ABI: a def whose code object declares freevars receives
            # the cell array as the SECOND implementation parameter
            # (tstate, closure, python_pars); cell[i] is the cell of
            # freevars[i].  Index → source name lets every closure read
            # resolve to the real outer-local name instead of None.
            self.closure_names = {
                index: name
                for index, name in enumerate(
                    getattr(code_obj, 'freevars', ()) or ())
                if isinstance(name, str)}
            self.has_closure = bool(self.closure_names)
            # Closure cells live at fixed slots of the object carried by the
            # second implementation parameter; the slot base is build
            # specific.  Offsets are self-calibrated across the repeated
            # symbolic passes: a slot is proven to be a cell when its value
            # is dereferenced at the Nuitka_CellObject.ob_ref offset (0x10).
            self._closure_offs = set()
            self._closure_cell_offs = set()
        else:
            self.argcount = 0
            self.freevars = set()
            self.closure_names = {}
            self.has_closure = False
        self.blocks = {}
        self.insns = []
        self.frame_cache_slots = set()
        self._inlined_binop_joins = {}
        self._specialized_numeric_joins = {}
        self.errors = []
        # var naming
        self._var_idx = 0
        self.tmp_count = 0
        self.var_by_slot = {}       # (slotkey) → varname
        self.slot_syms = {}         # stato corrente
        self.regs = {}
        # modalità generatore (resumer): dispatch yield → yield Python
        self.gen_mode = False
        self.gen_idx_off = None
        self.gen_yield_blocks = {}
        self.gen_resume = {}
        self.gen_entry = None
        self.gen_dispatch_end = 0
        self.gen_closure_map = {}
        self.gen_closure_names = {}
        # Per-block writes to the generator/coroutine object.  Nuitka's
        # generated return epilogue stores the semantic Python value in
        # ``context->m_returned`` and then returns C NULL.  The concrete field
        # offset is intentionally not assumed: it varies with context type,
        # target Python and Nuitka version.
        self.gen_result_stores = {}
        # Mutable container builders cross many refcount/error CFG blocks.
        # Keep their contents by the allocation instruction VA so repeated
        # symbolic visits update one canonical, target-proven object.
        self.container_values = {}
        self.container_reg_origins = {}
        # Anonymous dict builders already folded into a proven keyword call,
        # keyed by their allocation instruction VA.
        self.consumed_keyword_mappings = set()
        # Deep-copied tuple/list templates whose payload is proven to be a
        # vectorcall transport.  Keep them in dataflow but suppress their
        # native temporary assignment from emitted Python.
        self.consumed_argument_vectors = set()
        self.symbol_locations = defaultdict(set)
        self.direct_constant_loads = {}

    # ------------------------------------------------------------------ CFG
    def build_cfg(self):
        bounds = self.img.function_bounds(self.va)
        if bounds is None:
            insns = self.fd.insns(self.va, max_bytes=0x20000)
        else:
            off = self.img.va_to_off(bounds[0])
            code = self.img.data[off:off + min(bounds[1] - bounds[0], 0x20000)]
            insns = list(self.fd.md.disasm(code, bounds[0]))
        self.insns = insns
        if not insns:
            return
        leaders = {insns[0].address}
        for i, ins in enumerate(insns):
            m = ins.mnemonic
            if m in COND_JCC or m in ('jmp', 'ret', 'hlt', 'ud2'):
                if m != 'ret' and ins.op_str.startswith('0x'):
                    try:
                        t = int(ins.op_str, 16)
                    except ValueError:
                        t = None
                    if t is not None:
                        leaders.add(t)
                if i + 1 < len(insns):
                    leaders.add(insns[i + 1].address)
        blocks = {}
        cur = None
        for ins in insns:
            if ins.address in leaders:
                if cur is not None:
                    cur.end = ins.address
                    blocks[cur.start] = cur
                cur = NdxBB(ins.address)
            cur.insns.append(ins)
            m = ins.mnemonic
            if m in COND_JCC or m == 'jmp':
                try:
                    t = int(ins.op_str, 16)
                except ValueError:
                    t = None
                if t is not None:
                    cur.succs.append(t)
        if cur is not None and cur.start not in blocks:
            cur.end = insns[-1].address + insns[-1].size
            blocks[cur.start] = cur
        starts = sorted(blocks)
        for i, st in enumerate(starts):
            b = blocks[st]
            last = b.insns[-1] if b.insns else None
            if last is None:
                continue
            m = last.mnemonic
            if m in COND_JCC or m not in ('jmp', 'ret', 'hlt', 'ud2'):
                if i + 1 < len(starts):
                    b.succs.append(starts[i + 1])
            b.succs = list(dict.fromkeys(b.succs))
            for s in b.succs:
                if s in blocks:
                    blocks[s].preds.append(st)
        self.blocks = blocks
        self._prepare_generator()

    # --------------------------------------------------- modalità generatore
    def _detect_generator_mode(self):
        """(resume_map, idx_off, dispatch_end) se func_va è il resumer di
        un generatore Nuitka, altrimenti None.

        Il resumer riceve (tstate, generator, yield_return_value) e il suo
        prologo è lo switch su m_yield_return_index: catene di
        `cmp dword ptr [rdx+off], K` / `mov e,[rdx+off]; cmp e,K` + `je`.
        L'offset del campo è specifico del tipo (generator/coroutine/
        asyncgen) e della build: viene ricavato qui, mai cablato."""
        if not self.insns:
            return None
        gen_regs = ('rdx',) if self.img.fmt == 'pe' else ('rsi', 'rdx')
        # The state dispatch is not guaranteed to fit a fixed instruction
        # window: MSVC may place stack-cookie, exception-state and frame
        # initialisation before it.  First prove the state field from stores
        # performed at suspension points, then accept only comparisons of that
        # same field/value before its first suspension store.  This derives the
        # search boundary from the generated state machine itself.
        state_stores = defaultdict(list)
        for item in self.insns:
            if item.mnemonic != 'mov':
                continue
            match = re.fullmatch(
                r'dword ptr \[(\w+) \+ (0x[0-9a-f]+|\d+)\], '
                r'(0x[0-9a-f]+|\d+)', item.op_str)
            if match is None:
                continue
            state = int(match.group(3), 0)
            if state >= 1:
                state_stores[int(match.group(2), 0)].append(
                    (item.address, state))
        if not state_stores:
            return None
        resume_map = {}
        idx_off = None
        dispatch_end = 0
        candidates = []
        for candidate_off, stores in state_stores.items():
            first_store = min(address for address, _state in stores)
            states = {state for _address, state in stores}
            local_map = {}
            local_end = 0
            head = [item for item in self.insns
                    if item.address < first_store]
            for i, ins in enumerate(head):
                op = ins.op_str
                cm = re.fullmatch(
                    r'dword ptr \[(\w+) \+ (0x[0-9a-f]+|\d+)\], '
                    r'(0x[0-9a-f]+|\d+)', op) \
                    if ins.mnemonic == 'cmp' else None
                mm = re.fullmatch(
                    r'(\w+), dword ptr \[(\w+) \+ '
                    r'(0x[0-9a-f]+|\d+)\]', op) \
                    if ins.mnemonic in ('mov', 'movzx') else None
                if cm and int(cm.group(2), 0) == candidate_off:
                    state = int(cm.group(3), 0)
                    if state not in states:
                        continue
                    for j in range(i + 1, min(i + 7, len(head))):
                        branch = head[j]
                        if branch.mnemonic in COND_JCC and \
                                branch.op_str.startswith('0x') and \
                                branch.address - ins.address <= 32:
                            local_map[state] = int(branch.op_str, 16)
                            local_end = max(local_end,
                                            branch.address + branch.size)
                            break
                elif mm and int(mm.group(3), 0) == candidate_off:
                    register = mm.group(1)
                    # MSVC often normalises the state once (`sub state, 1`)
                    # and then dispatches zero with JE followed by CMPs of the
                    # normalised value.  Track that exact affine delta so the
                    # branches map back to the original stored state values.
                    delta = 0
                    zero_state_pending = None
                    for j in range(i + 1, min(i + 13, len(head))):
                        compare = head[j]
                        operands = split_ops(compare.op_str)
                        if compare.mnemonic == 'sub' and len(operands) == 2 \
                                and subreg64(operands[0]) == \
                                subreg64(register):
                            amount = is_imm(operands[1])
                            if amount is None:
                                break
                            delta += amount
                            zero_state_pending = delta
                            continue
                        if compare.mnemonic == 'dec' and operands and \
                                subreg64(operands[0]) == subreg64(register):
                            delta += 1
                            zero_state_pending = delta
                            continue
                        if compare.mnemonic in ('je', 'jz') and \
                                zero_state_pending is not None and \
                                compare.op_str.startswith('0x'):
                            state = zero_state_pending
                            if state in states:
                                local_map[state] = int(compare.op_str, 16)
                                local_end = max(
                                    local_end,
                                    compare.address + compare.size)
                            zero_state_pending = None
                            continue
                        c2 = re.fullmatch(
                            r'(?:dword ptr )?' + re.escape(register) +
                            r', (0x[0-9a-f]+|\d+)', compare.op_str) \
                            if compare.mnemonic == 'cmp' else None
                        if c2 is None:
                            if operands and subreg64(operands[0]) == \
                                    subreg64(register):
                                break
                            continue
                        zero_state_pending = None
                        state = int(c2.group(1), 0) + delta
                        if state not in states:
                            continue
                        for k in range(j + 1, min(j + 7, len(head))):
                            branch = head[k]
                            if branch.mnemonic in ('je', 'jz') and \
                                    branch.op_str.startswith('0x') and \
                                    branch.address - compare.address <= 32:
                                local_map[state] = int(branch.op_str, 16)
                                local_end = max(local_end,
                                                branch.address + branch.size)
                                break
            if local_map:
                candidates.append((len(local_map), -first_store,
                                   candidate_off, local_map, local_end))
        if candidates:
            _count, _first, idx_off, resume_map, dispatch_end = max(candidates)
            return resume_map, idx_off, dispatch_end
        return None

    def _prepare_generator(self):
        """Riscrute la CFG del resumer in un flusso Python lineare:

        - i blocchi del dispatch d'ingresso diventano irraggiungibili
          (l'entry vero è il fall-through del dispatch);
        - ogni blocco-yield (store di K≥1 su [gen+idx_off] prima di un
          ret) viene chiuso da `yield <rax>` e collegato al blocco di
          resume K estratto dal dispatch."""
        g = self._detect_generator_mode()
        if not g:
            # A coroutine/async-generator with no suspension point has no
            # m_yield_return_index switch.  It is still a resumer context and
            # uses the (tstate, coroutine, yield_return_value) ABI plus
            # m_closure storage.  Require both an authoritative code flag and
            # the exact resumer association recovered from its maker.
            flags = int(getattr(self.co, 'flags', 0) or 0)
            forced = bool(flags & (0x20 | 0x80 | 0x200)) and any(
                function.get('resumer_va') == self.va
                for function in getattr(self.mca, 'functions', ()))
            if not forced:
                return
            g = ({}, -1, 0)
        resume_map, idx_off, dispatch_end = g
        self.gen_mode = True
        self.gen_idx_off = idx_off
        self.gen_resume = resume_map
        self.gen_dispatch_end = dispatch_end
        # Register aliases established by the common prologue execute again
        # on every native resumer invocation, although the source-level CFG
        # models that invocation as yield->resume.  Derive them from MOV
        # lineage instead of assuming MSVC's current callee-saved choices.
        def prologue_aliases(source_register):
            aliases = {source_register}
            for item in self.insns:
                if dispatch_end and item.address >= dispatch_end:
                    break
                operands = split_ops(item.op_str)
                if item.mnemonic != 'mov' or len(operands) != 2:
                    continue
                destination = subreg64(operands[0])
                source = subreg64(operands[1])
                if destination is None:
                    continue
                if source in aliases:
                    aliases.add(destination)
                elif destination in aliases:
                    aliases.remove(destination)
            return aliases

        native_generator = 'rdx' if self.img.fmt == 'pe' else 'rsi'
        native_resumed = 'r8' if self.img.fmt == 'pe' else 'rdx'
        self.gen_object_regs = prologue_aliases(native_generator)
        self.gen_value_regs = prologue_aliases(native_resumed)
        yield_by_block = {}
        for b in self.blocks.values():
            for idx, ins in enumerate(b.insns):
                if ins.mnemonic != 'mov':
                    continue
                sm = re.fullmatch(
                    r'dword ptr \[(\w+) \+ (0x[0-9a-f]+|\d+)\], '
                    r'(0x[0-9a-f]+|\d+)', ins.op_str)
                if not sm or int(sm.group(2), 0) != idx_off:
                    continue
                K = int(sm.group(3), 0)
                # MSVC: dopo lo store dell'indice il valore va in rax e il
                # blocco TAIL-JUMPA all'epilogo condiviso (nessun ret
                # locale). L'appartenenza di K al dispatch è il filtro.
                if K >= 1 and (K in resume_map or not resume_map):
                    yield_by_block[b.start] = K
        self.gen_yield_blocks = yield_by_block
        # closure-cell offsets: `mov A, [B+OFF]` seguito (≤3 insn) da
        # `mov D, [A+0x10]` (cell->ob_ref). Gli OFF delle closure formano
        # un cluster a passo 8; l'indice i = (OFF - base)/8.
        closure_offs = []
        ins_list = self.insns

        def _mov_parts(ins):
            if ins.mnemonic != 'mov' or ',' not in ins.op_str:
                return None, None
            d, s = [x.strip() for x in ins.op_str.split(',', 1)]
            return d, s

        # lineage del registro-generatore: rdx (Win64) / rsi (SysV) e le
        # copie fatte nel prologo (`mov r15, rdx`). Solo i load da QUESTE
        # basi sono letture m_closure[i]; qualunque altra base è un
        # campo-oggetto qualunque (ob_type ecc.) e inquina la mappa.
        gen_src = 'rdx' if self.img.fmt == 'pe' else 'rsi'
        gen_regs = {gen_src}
        gen_regs.update(self._generator_object_alias_registers())
        for gi in range(min(30, len(ins_list))):
            dg, sg = _mov_parts(ins_list[gi])
            if dg and sg and subreg64(sg) == gen_src:
                gen_regs.add(subreg64(dg))
        for i2 in range(len(ins_list) - 3):
            a1 = ins_list[i2]
            d1, s1 = _mov_parts(a1)
            if d1 is None:
                continue
            mm1 = re.fullmatch(
                r'qword ptr \[(\w+) \+ (0x[0-9a-f]+|\d+)\]', s1)
            if not mm1 or subreg64(mm1.group(1)) not in gen_regs:
                continue
            cell_reg = d1          # registro che riceve la cella
            off1 = int(mm1.group(2), 0)
            for j2 in range(i2 + 1, min(i2 + 4, len(ins_list))):
                a2 = ins_list[j2]
                d2, s2 = _mov_parts(a2)
                if d2 is None:
                    continue
                mm2 = re.fullmatch(r'qword ptr \[' + re.escape(cell_reg) +
                                   r' \+ 0x10\]', s2)
                if mm2:
                    closure_offs.append(off1)
                    break
                # The candidate cell pointer must still be live at the
                # dereference.  MSVC frequently reuses the same register for
                # two adjacent context fields; accepting the earlier load after
                # that clobber shifts the entire closure-name map.
                if subreg64(d2) == subreg64(cell_reg):
                    break
        # Capstone formatting differs slightly across versions and compilers
        # (decimal offsets, optional size prefixes, register aliases).  Repeat
        # the same proof through the shared operand parser so valid adjacent
        # closure fields cannot be lost merely because a textual regex did not
        # match.  Provenance is still restricted to the resumer-object aliases.
        for i2 in range(len(ins_list) - 1):
            first = ins_list[i2]
            first_operands = split_ops(first.op_str)
            if first.mnemonic != 'mov' or len(first_operands) != 2:
                continue
            cell_register = subreg64(first_operands[0])
            cell_memory = parse_mem(first_operands[1])
            if cell_register is None or not cell_memory or \
                    cell_memory[0] not in gen_regs or cell_memory[2] or \
                    cell_memory[1] < 0:
                continue
            for following in ins_list[i2 + 1:i2 + 5]:
                following_operands = split_ops(following.op_str)
                if following.mnemonic != 'mov' or \
                        len(following_operands) != 2:
                    continue
                source_memory = parse_mem(following_operands[1])
                if source_memory and source_memory[0] == cell_register and \
                        not source_memory[2] and source_memory[1] == 0x10:
                    closure_offs.append(cell_memory[1])
                    break
                if subreg64(following_operands[0]) == cell_register:
                    break
        self.gen_closure_map = {}
        self.gen_closure_names = {}
        if closure_offs:
            base_off = min(closure_offs)
            # le celle m_closure[i] sono CONTIGUE a passo 8: si accettano
            # solo offset con indici consecutivi (0,1,2,...) dal minimo —
            # un salto è un accesso ad altro oggetto riusando lo stesso
            # registro (il valore-cell riassegna i callee-saved).
            offs = [base_off]
            for cand in sorted(set(closure_offs)):
                if (cand - base_off) % 8 == 0 and                         (cand - base_off) // 8 == len(offs):
                    offs.append(cand)
            for o in offs:
                self.gen_closure_map[o] = (o - base_off) // 8
            fv = list(getattr(self.co, 'freevars', ()) or
                      ()) if self.co is not None else []
            varnames = list(getattr(self.co, 'varnames', ()) or
                            ()) if self.co is not None else []
            argnames = varnames[:getattr(self.co, 'argcount', 0)
                                or len(varnames)]
            function = next((f for f in getattr(self.mca, 'functions', ())
                             if f.get('resumer_va') == self.va), None)
            parameter_names = self.mca.generator_parameter_names(function) if function else {}
            for idx3, o in enumerate(offs):
                nm = parameter_names.get(idx3)
                if nm is None:
                    nm = fv[idx3] if idx3 < len(fv) else (
                        argnames[0] if len(argnames) == 1 and idx3 == 0 else f'_cell{idx3}')
                self.gen_closure_names[self.gen_closure_map[o]] = nm
        # Snapshot della CFG PRIMA del rewire yield→resume: l'edge sintetico
        # rende il resume un join "esterno" e il loop sparisce dal grafo
        # riscritto. Lo Structurer ricostruirà i loop naturali dallo
        # snapshot, filtrando con i propri edge-typing.
        self.gen_pre_succs = {st: list(b.succs)
                              for st, b in self.blocks.items()}
        self.gen_pre_preds = {st: list(b.preds)
                              for st, b in self.blocks.items()}
        for bst, K in yield_by_block.items():
            b = self.blocks.get(bst)
            tgt = resume_map.get(K)
            if b is not None and tgt in self.blocks:
                b.succs = [tgt]
                if bst not in self.blocks[tgt].preds:
                    self.blocks[tgt].preds.append(bst)
        # Il dispatch d'ingresso (cmp+je verso i resume) va rimosso DAGLI
        # EDGES del prologo: la ripresa è già modellata dall'arco
        # yield→resume. L'entry resta il PROLOGO (il setup dei registri
        # base — heap storage, generator, tstate — deve eseguire).
        resume_set = set(resume_map.values())
        for b in self.blocks.values():
            if b.start >= dispatch_end:
                continue
            kept = []
            for s in b.succs:
                if s in resume_set:
                    rb = self.blocks.get(s)
                    if rb is not None and b.start in rb.preds:
                        rb.preds.remove(b.start)
                    continue
                kept.append(s)
            if kept != b.succs:
                b.succs = kept
        self.gen_entry = None

    def _discover_inlined_binop_joins(self):
        """Recognise Nuitka's inlined binary protocol dispatcher.

        MSVC expands generic multiplication into nb_multiply/reflected-slot
        branches plus two sequence-repeat fallbacks.  Every successful branch
        writes the same result register and jumps to one join.  Collapsing that
        compiler template restores one Python operation without depending on
        variable names, constants, source lines, or a sample-specific address.
        """
        marker_ops = {'SEQUENCE_REPEAT': '*', 'SEQUENCE_CONCAT': '+'}
        groups = {}

        def direct_name(index):
            ins = self.insns[index]
            if ins.mnemonic != 'call' or not ins.op_str.startswith('0x'):
                return None
            try:
                return self.res.resolve(int(ins.op_str, 16))[1]
            except Exception:
                return None

        def result_reg_after(index, limit=5):
            for nxt in self.insns[index + 1:index + 1 + limit]:
                if nxt.mnemonic != 'mov':
                    continue
                ops = split_ops(nxt.op_str)
                if len(ops) == 2 and subreg64(ops[1]) == self.abi.ret_reg:
                    return subreg64(ops[0])
            return None

        def jump_after(index, limit=6):
            for nxt in self.insns[index + 1:index + 1 + limit]:
                if nxt.mnemonic == 'jmp' and nxt.op_str.startswith('0x'):
                    try:
                        return int(nxt.op_str, 16)
                    except ValueError:
                        return None
            return None

        def marker_operand_regs(index, limit=12):
            """Object registers moved into a sequence-helper call.

            The helper function pointer occupies another ABI register; only
            register-to-register moves into argument registers are candidates.
            Reflected branches provide the same pair in reverse order.
            """
            setup = {}
            lower = max(0, index - limit)
            for previous in range(index - 1, lower - 1, -1):
                item = self.insns[previous]
                if item.mnemonic == 'call':
                    break
                operands = split_ops(item.op_str)
                if item.mnemonic != 'mov' or len(operands) != 2:
                    continue
                dst = subreg64(operands[0])
                src = subreg64(operands[1])
                if dst in self.abi.arg_regs and src and dst not in setup:
                    setup[dst] = src
            return tuple(setup[reg] for reg in self.abi.arg_regs
                         if reg in setup)

        for index, ins in enumerate(self.insns):
            name = direct_name(index)
            op = marker_ops.get(name)
            if op is None:
                continue
            join = jump_after(index)
            out_reg = result_reg_after(index)
            if join in self.blocks and out_reg:
                groups.setdefault((join, out_reg, op), []).append(index)

        for (join, out_reg, op), marker_indexes in groups.items():
            # Reflected and sequence branches independently reach the same join;
            # requiring both avoids treating an ordinary helper call as an
            # inlined source operation.
            if len(marker_indexes) < 2:
                continue
            before = min(marker_indexes)

            # The two sequence-repeat fallbacks are a stronger operand proof
            # than proximity to earlier producers: one branch passes (L, R),
            # the reflected branch passes (R, L).  This survives arbitrary
            # source expressions and long inlined numeric fast paths.
            pairs = [marker_operand_regs(index) for index in marker_indexes]
            pair = next((candidate for candidate in pairs
                         if len(candidate) >= 2 and any(
                             len(other) >= 2 and
                             other[:2] == tuple(reversed(candidate[:2]))
                             for other in pairs if other is not candidate)),
                        None)
            if pair is not None:
                left_reg, right_reg = pair[:2]
                definitions = {}
                for index in range(before - 1, -1, -1):
                    item = self.insns[index]
                    operands = split_ops(item.op_str)
                    if item.mnemonic == 'mov' and len(operands) == 2:
                        dst = subreg64(operands[0])
                        src = subreg64(operands[1])
                        if dst in (left_reg, right_reg) and \
                                src == self.abi.ret_reg and \
                                dst not in definitions:
                            definitions[dst] = item.address
                    if len(definitions) == 2:
                        break
                source_address = max(definitions.values()) if definitions \
                    else self.insns[before].address
                source_block = next((start for start, block in
                                     self.blocks.items()
                                     if start <= source_address < block.end),
                                    None)
                consumer_block = None
                join_index = next((i for i, item in enumerate(self.insns)
                                   if item.address == join), None)
                if join_index is not None:
                    for index in range(join_index, len(self.insns)):
                        name = direct_name(index)
                        if not name or name in marker_ops:
                            continue
                        if name.startswith(('CALL_FUNCTION_', 'CALL_METHOD_',
                                            'BUILTIN_')):
                            address = self.insns[index].address
                            consumer_block = next((
                                start for start, block in self.blocks.items()
                                if start <= address < block.end), None)
                            break
                if source_block is not None:
                    self._inlined_binop_joins[join] = (
                        out_reg, left_reg, right_reg, op,
                        source_block, consumer_block)
                    continue

            producers = []
            for index in range(before - 1, -1, -1):
                name = direct_name(index)
                if not name:
                    continue
                sem = helper_semantics(name)
                if not (name.startswith(('LOOKUP_', 'GET_STRING_DICT_VALUE',
                                         'BUILTIN_', 'CALL_FUNCTION_',
                                         'CALL_METHOD_', 'BINARY_')) or
                        (sem and sem[0] in ('lookup_attribute', 'subscript',
                                           'global_lookup', 'binop'))):
                    continue
                reg = result_reg_after(index)
                if reg and reg not in {p[0] for p in producers}:
                    producers.append((reg, index))
                if len(producers) == 2:
                    break
            if len(producers) == 2:
                producers.reverse()
                producer_address = self.insns[producers[1][1]].address
                source_block = None
                for start, block in self.blocks.items():
                    if start <= producer_address < block.end:
                        source_block = start
                        break
                consumer_block = None
                join_index = next((i for i, ins in enumerate(self.insns)
                                   if ins.address == join), None)
                if join_index is not None:
                    for index in range(join_index, len(self.insns)):
                        name = direct_name(index)
                        if not name or name in marker_ops:
                            continue
                        if name.startswith(('CALL_FUNCTION_', 'CALL_METHOD_',
                                            'BUILTIN_')):
                            address = self.insns[index].address
                            for start, block in self.blocks.items():
                                if start <= address < block.end:
                                    consumer_block = start
                                    break
                            break
                self._inlined_binop_joins[join] = (
                    out_reg, producers[0][0], producers[1][0], op,
                    source_block, consumer_block)

    def _collapse_inlined_binop_regions(self):
        """Replace proven protocol machinery with one semantic CFG edge."""
        for join, proof in self._inlined_binop_joins.items():
            _out, _left, _right, _op, source, consumer = proof
            if source not in self.blocks or join not in self.blocks:
                continue
            source_block = self.blocks[source]
            old_successors = list(source_block.succs)
            source_block.succs = [join]
            source_block.edges = [(join, 'goto')]
            for successor in old_successors:
                block = self.blocks.get(successor)
                if block is not None and source in block.preds:
                    block.preds.remove(source)
            join_block = self.blocks[join]
            join_block.preds = [source]
            join_block.kind = 'normal'
            # All native dispatch branches between the source operands and the
            # join have been represented by the synthetic binop.
            for start, block in self.blocks.items():
                if source < start < join:
                    block.kind = 'error'
            if consumer in self.blocks and consumer > join:
                old_successors = list(join_block.succs)
                join_block.succs = [consumer]
                join_block.edges = [(consumer, 'goto')]
                for successor in old_successors:
                    block = self.blocks.get(successor)
                    if block is not None and join in block.preds:
                        block.preds.remove(join)
                consumer_block = self.blocks[consumer]
                consumer_block.preds = [join]
                consumer_block.kind = 'normal'
                for start, block in self.blocks.items():
                    if join < start < consumer:
                        block.kind = 'error'
                # ``classify_blocks`` ran before the protocol region was
                # collapsed, so downstream success blocks may still carry a
                # stale cold/error mark.  Recompute reachability from the
                # proven consumer using typed non-error edges and implicit
                # fallthroughs only.
                work = [consumer]
                seen = set()
                while work:
                    current = work.pop()
                    if current in seen or current not in self.blocks:
                        continue
                    seen.add(current)
                    current_block = self.blocks[current]
                    current_block.kind = 'normal'
                    error_targets = {target for target, edge_type
                                     in current_block.edges
                                     if edge_type in ('error', 'stopiter')}
                    explicit_normal = {target for target, edge_type
                                       in current_block.edges
                                       if edge_type not in ('error',
                                                            'stopiter')}
                    for successor in current_block.succs:
                        if successor in explicit_normal or \
                                successor not in error_targets:
                            work.append(successor)

    def _collapse_native_constant_copy_loops(self):
        """Remove finite descriptor-copy loops from the source CFG.

        A mutable constant argument vector is cloned by a native counted loop:
        one proven DEEP_COPY_ELEMENT call, one result store, a decrement and a
        conditional self-edge.  The already materialised tuple node carries
        the complete Python value, so this loop has no source statement.  The
        exact self-edge/countdown proof avoids suppressing Python iteration or
        user calls to ``copy.deepcopy``.
        """
        for start, block in self.blocks.items():
            already_proven = 'native_constant_copy' in block.flags
            if not already_proven and start not in block.succs:
                continue
            exits = [successor for successor in block.succs
                     if successor != start]
            if not exits and not already_proven:
                continue
            if already_proven:
                block.succs = exits
                block.edges = [(target, edge)
                               for target, edge in block.edges
                               if target != start]
                block.conds = [(target, edge, condition)
                               for target, edge, condition in block.conds
                               if target != start]
                block.preds = [predecessor for predecessor in block.preds
                               if predecessor != start]
                block.ops = []
                continue
            has_copy = False
            has_result_store = False
            has_countdown = False
            for item in block.insns:
                operands = split_ops(item.op_str)
                if item.mnemonic == 'call' and item.op_str.startswith('0x'):
                    try:
                        target = int(item.op_str, 16)
                    except ValueError:
                        target = None
                    try:
                        helper = (self.res.resolve(target)[1]
                                  if target is not None else None)
                    except Exception:
                        helper = None
                    if helper == 'DEEP_COPY_ELEMENT' or (
                            target is not None and getattr(
                                self.res, '_deepcopy_element_shape',
                                lambda _target: False)(target)):
                        has_copy = True
                elif item.mnemonic == 'mov' and len(operands) == 2:
                    destination = parse_mem(operands[0])
                    if destination and \
                            subreg64(operands[1]) == self.abi.ret_reg:
                        has_result_store = True
                elif item.mnemonic in ('sub', 'dec') and operands:
                    if item.mnemonic == 'dec' or (
                            len(operands) == 2 and
                            is_imm(operands[1]) == 1):
                        has_countdown = True
            # The descriptor-dispatch proof plus a physical self-edge already
            # identifies the native loop.  Result-store/countdown evidence is
            # collected above as a consistency check but is allowed to be
            # hidden by compiler instruction selection (e.g. STOS/LEA forms).
            if not has_copy:
                continue
            block.succs = exits
            block.edges = [(target, edge) for target, edge in block.edges
                           if target != start]
            block.conds = [(target, edge, condition)
                           for target, edge, condition in block.conds
                           if target != start]
            block.preds = [predecessor for predecessor in block.preds
                           if predecessor != start]
            block.ops = []
            block.flags.add('native_constant_copy')

    def _discover_specialized_numeric_joins(self):
        """Canonicalise boxed-float fast/slow branches at their CFG join.

        The XMM fast path boxes through ``MAKE_FLOAT_FROM_DOUBLE``; a sibling
        generic Python binary helper proves the exact operation and operands.
        Both paths must converge at the same join before they are unified.
        """
        found = {}
        for fast_start, fast_block in self.blocks.items():
            is_boxing = any(
                op.kind == 'calc' and op.a is not None and
                op.a.op == 'nativecall' and
                str(op.a.a) == 'MAKE_FLOAT_FROM_DOUBLE'
                for op in fast_block.ops)
            if not is_boxing:
                continue
            for join in fast_block.succs:
                join_block = self.blocks.get(join)
                if join_block is None:
                    continue
                for slow_start in join_block.preds:
                    if slow_start == fast_start:
                        continue
                    slow_block = self.blocks.get(slow_start)
                    if slow_block is None:
                        continue
                    semantic = [op.a for op in slow_block.ops
                                if op.kind == 'calc' and op.a is not None and
                                op.a.op == 'binop']
                    if semantic:
                        found[join] = slow_start
                        break
        changed = found != self._specialized_numeric_joins
        self._specialized_numeric_joins = found
        return changed

    def _materialize_collapsed_returns(self):
        """Move a proven returned value ahead of shared C error epilogues."""
        returned = []
        for block in self.blocks.values():
            returned.extend(o.a for o in block.ops
                            if o.kind == 'ret' and o.a is not None)
        for join, proof in self._inlined_binop_joins.items():
            _out, _left, _right, _op, _source, consumer = proof
            candidate = self.blocks.get(consumer) or self.blocks.get(join)
            if candidate is None:
                continue
            values = [o.a for o in candidate.ops if o.kind == 'calc' and
                      o.a is not None and o.a.op in ('call', 'binop')]
            if not values:
                continue
            value = values[-1]
            if any(_sv_eq(value, ret) for ret in returned):
                candidate.ops.append(NdxOp('ret', a=value, va=candidate.end))
                candidate.succs = []
                candidate.edges = []
                candidate.kind = 'normal'

    def _repair_unresolved_returns(self):
        """Resolve shared-epilogue phi returns to their last normal producer."""
        def is_recurrence(value):
            if not isinstance(value, NdxSV) or value.op != 'loc':
                return False
            for _pred, incoming in getattr(self, '_phi_inputs', {}).get(id(value), ()):
                if isinstance(incoming, NdxSV) and incoming.op == 'binop':
                    if any(isinstance(child, NdxSV) and child.op == 'loc'
                           and child.a == value.a for child in (incoming.b, incoming.c)):
                        return True
            return False

        producers_by_loc = {}
        for start, block in self.blocks.items():
            if block.kind != 'normal':
                continue
            for op in block.ops:
                if op.kind == 'store' and op.b is not None:
                    previous = producers_by_loc.get(op.a)
                    if previous is None or (op.va or start) >= previous[0]:
                        producers_by_loc[op.a] = (op.va or start, op.b)

        # Shared cleanup epilogues often merge RAX to a phi.  A final native
        # ``mov rax, <callee-saved>`` plus the allocation store to that exact
        # register proves a returned mutable container independently of the
        # polluted epilogue state.
        for block in self.blocks.values():
            for op in block.ops:
                if op.kind != 'ret' or op.a is None or \
                        op.a.op != 'loc' or op.va is None:
                    continue
                if is_recurrence(op.a):
                    continue
                end = next((i for i, item in enumerate(self.insns)
                            if item.address >= op.va), len(self.insns))
                source_reg = None
                for item in reversed(self.insns[max(0, end - 50):end]):
                    operands = split_ops(item.op_str)
                    if item.mnemonic == 'mov' and len(operands) == 2 and \
                            subreg64(operands[0]) == self.abi.ret_reg:
                        candidate = subreg64(operands[1])
                        if candidate in GP_REGS:
                            source_reg = candidate
                        break
                producer = producers_by_loc.get(('reg', source_reg))
                if producer is not None and producer[0] <= op.va:
                    op.a = producer[1]

        candidates = []
        for start, block in self.blocks.items():
            if block.kind != 'normal':
                continue
            for op in block.ops:
                if op.kind == 'store' and op.b is not None and op.b.op in (
                        'call', 'kwcall', 'mcall', 'binop', 'getattr', 'sub'):
                    candidates.append((op.va or start, op.b))
        if not candidates:
            return
        candidates.sort(key=lambda item: item[0])
        producer = candidates[-1][1]
        for block in self.blocks.values():
            for op in block.ops:
                if op.kind == 'ret' and op.a is not None and op.a.op == 'loc':
                    if not is_recurrence(op.a):
                        op.a = producer

    def _materialize_authoritative_constants(self):
        """Emit direct constant initialisers proven by frame-local metadata.

        Optimising C compilers can load an immortal/constant PyObject straight
        into a callee-saved register, without a helper return for `_note_store`
        to observe.  Nuitka later passes that same physical location to
        ``Nuitka_Frame_AttachLocals``.  The conjunction of those two facts is
        sufficient to recover the Python local assignment without guessing a
        source name or value.
        """
        authoritative = getattr(self, 'authoritative_loc_names', {}) or {}
        local_names = set(self.varnames[self.argcount:])
        physical_aliases = {}
        for locations in self.symbol_locations.values():
            named = {location for location in locations
                     if location in authoritative}
            if len(named) != 1:
                continue
            named_location = next(iter(named))
            for location in locations:
                if location != named_location:
                    physical_aliases.setdefault(location, set()).add(
                        named_location)
        physical_aliases = {
            location: next(iter(named))
            for location, named in physical_aliases.items()
            if len(named) == 1}

        def canonicalize_locations(value, seen=None):
            """Replace proven spill aliases inside symbolic expressions.

            ``Frame_AttachLocals`` names the authoritative storage, while the
            optimiser may feed a later protocol call from an equivalent stack
            spill.  Alias evidence is collected by object identity above and
            is accepted only when it identifies exactly one named location.
            Registers are deliberately left alone here because they are much
            more aggressively reused than frame slots.
            """
            if not isinstance(value, NdxSV):
                return value
            if value.op == 'loc' and isinstance(value.a, tuple) and \
                    value.a and value.a[0] == 'mem':
                named_location = physical_aliases.get(value.a)
                if named_location is not None:
                    return ndx_k('loc', named_location)
            if seen is None:
                seen = set()
            marker = id(value)
            if marker in seen:
                return value
            seen.add(marker)
            for attribute in ('a', 'b', 'c'):
                child = getattr(value, attribute, None)
                if isinstance(child, NdxSV):
                    setattr(value, attribute,
                            canonicalize_locations(child, seen))
                elif isinstance(child, list):
                    setattr(value, attribute, [
                        canonicalize_locations(item, seen)
                        if isinstance(item, NdxSV) else item
                        for item in child])
            return value

        for block in self.blocks.values():
            for operation in block.ops:
                if operation.kind != 'store' or operation.b is None or \
                        operation.b.op != 'binop':
                    continue
                named_location = physical_aliases.get(operation.a)
                if named_location is None:
                    continue
                operation.a = named_location
                left = operation.b.b
                if left is not None and left.op == 'loc' and \
                        left.a not in authoritative:
                    operation.b.b = ndx_k('loc', named_location)
        for block in self.blocks.values():
            for operation in block.ops:
                for attribute in ('a', 'b', 'c'):
                    value = getattr(operation, attribute, None)
                    if isinstance(value, NdxSV):
                        setattr(operation, attribute,
                                canonicalize_locations(value))
        for address, (block_start, location, value) in sorted(
                self.direct_constant_loads.items()):
            name = authoritative.get(location)
            block = self.blocks.get(block_start)
            if name not in local_names or block is None or \
                    block.kind != 'normal':
                continue
            if any(op.kind == 'store' and op.a == location and
                   op.b is not None and _sv_eq(op.b, value)
                   for op in block.ops):
                continue
            block.ops.append(NdxOp('store', a=location, b=value, va=address))
            block.ops.sort(key=lambda op: op.va or block.start)
            self.symbol_locations[self._svkey_of(value)].add(location)

        # In-place numeric helpers have a specialised fast path and a generic
        # slow path.  The semantic binop is discovered in the latter, while
        # both paths converge at a shared non-NULL result check.  Place the
        # single source assignment on that proven success continuation.
        relocations = []
        persistent = set(self.CALLEE_SAVED)
        if self.img.fmt == 'pe':
            persistent.update(('rsi', 'rdi'))
        selected_slow_paths = set(self._specialized_numeric_joins.values())
        for source in self.blocks.values():
            for operation in list(source.ops):
                if operation.kind != 'store' or operation.b is None or \
                        operation.b.op != 'binop' or \
                        operation.b.n != 'inplace' or \
                        operation.a not in authoritative:
                    continue
                if source.start in selected_slow_paths:
                    continue
                destination = None
                if operation.a[0] == 'reg':
                    destination_register = operation.a[1]
                    for start, candidate in sorted(self.blocks.items()):
                        if start <= operation.va or \
                                start - operation.va > 0x400 or \
                                len(candidate.preds) < 2:
                            continue
                        writes_named_location = any(
                            item.mnemonic == 'mov' and
                            len(split_ops(item.op_str)) == 2 and
                            subreg64(split_ops(item.op_str)[0]) ==
                            destination_register
                            for item in candidate.insns)
                        if writes_named_location:
                            destination = candidate
                if destination is not None:
                    relocations.append((source, destination, operation))
                    continue
                for start, candidate in sorted(self.blocks.items()):
                    if start <= operation.va or start - operation.va > 0x400:
                        continue
                    error_targets = {target for target, edge_type
                                     in candidate.edges
                                     if edge_type == 'error'}
                    normal_targets = [target for target in candidate.succs
                                      if target not in error_targets and
                                      target in self.blocks and
                                      self.blocks[target].kind != 'error']
                    if len(normal_targets) != 1:
                        continue
                    pointer_test = False
                    for predecessor in candidate.preds:
                        previous = self.blocks.get(predecessor)
                        if previous is None or not previous.insns:
                            continue
                        last = previous.insns[-1]
                        operands = split_ops(last.op_str)
                        register = subreg64(operands[0]) if operands else None
                        if last.mnemonic == 'test' and len(operands) == 2 and \
                                register in persistent and \
                                register == subreg64(operands[1]):
                            pointer_test = True
                            break
                    if pointer_test:
                        destination = self.blocks[normal_targets[0]]
                        break
                if destination is not None and destination is not source:
                    relocations.append((source, destination, operation))
        for source, destination, operation in relocations:
            if operation in source.ops:
                source.ops.remove(operation)
            operation.va = destination.start
            if not any(item.kind == 'store' and item.a == operation.a and
                       item.b is not None and _sv_eq(item.b, operation.b)
                       for item in destination.ops):
                destination.ops.append(operation)
                destination.ops.sort(key=lambda op: op.va or destination.start)

    # ------------------------------------------------- frame cache slots
    def _find_frame_cache_slots(self):
        """Slot .bss usati come cache frame: target di `mov %rax, rip(X)`
        in blocchi che chiamano MAKE_FUNCTION_FRAME."""
        for b in self.blocks.values():
            has_mff = any(
                ins.mnemonic == 'call' and ins.op_str.startswith('0x')
                and self._call_name_safe(ins.op_str) in
                ('MAKE_FUNCTION_FRAME', 'MAKE_MODULE_FRAME')
                for ins in b.insns)
            if not has_mff:
                continue
            for ins in b.insns:
                if ins.mnemonic == 'mov' and ',0x' in ins.op_str \
                        and 'rip' in ins.op_str:
                    # forma: mov %rax,0xNN(%rip)
                    dst, src = ins.op_str.split(',', 1)
                    if src.strip().lstrip('%') in ('rax', 'eax'):
                        t = rip_target(ins)
                        if t is not None:
                            self.frame_cache_slots.add(t)

    def _call_name_safe(self, op_str):
        try:
            t = int(op_str, 16)
        except ValueError:
            return ''
        _k, nm, _s = self.res.resolve(t)
        return nm or ''

    # ------------------------------------------------- classificazione blocchi
    def classify_blocks(self):
        """error/handler/epilogue/noise. Deterministico:
        - error: blocchi percorsi solo da edge d'errore (NULL check / exc)
        - handler: catena keeper→matcher (contiene EXC_MATCH/RERAISE/traceback)
        - epilogue: pop+ret con sole operazioni di chiusura frame
        """
        # 1) blocks con semantica eccezione
        handler_marks = ('EXCEPTION_MATCH_BOOL', 'EXCEPTION_MATCH_BOOL_SINGLE',
                         'RERAISE_EXCEPTION', 'MAKE_TRACEBACK', 'ADD_TRACEBACK',
                         'PUBLISH_CURRENT_EXCEPTION', 'PyErr_NormalizeException',
                         'GET_CURRENT_EXCEPTION', 'FETCH_ERROR_OCCURRED_STATE',
                         'SET_CURRENT_EXCEPTION', 'PyErr_Format',
                         'PyErr_SetString', 'PyErr_SetObject',
                         'PyErr_SetNone')
        for b in self.blocks.values():
            for ins in b.insns:
                if ins.mnemonic != 'call':
                    continue
                nm = None
                if ins.op_str.startswith('0x'):
                    nm = self._call_name_safe(ins.op_str)
                elif 'rip' in ins.op_str:
                    slot = rip_target(ins)
                    nm = self.img.imports.get(slot) if slot is not None \
                        else None
                if nm in handler_marks:
                    b.flags.add('handler_sem')
        # 2) NULL-check edges: `test r,r; je X` dove X ⊆ percorso d'errore.
        #    Un blocco è "error" se tutti i suoi pred lo raggiungono via edge
        #    condizionale da un NULL-check oppure è marcato handler_sem.
        #    In pratica: propagate da blocchi handler_sem e da blocchi che
        #    non producono ops Python e finiscono in jump verso handler.
        changed = False
        error_like = set(a for a, b in self.blocks.items()
                         if 'handler_sem' in b.flags)
        while changed:
            changed = False
            for st, b in self.blocks.items():
                if st in error_like:
                    continue
                # blocco che non contiene call semantiche né produce ops
                # e i cui successori sono tutti error_like → error_like
                has_sem = False
                for ins in b.insns:
                    if ins.mnemonic == 'call' and ins.op_str.startswith('0x'):
                        t = int(ins.op_str, 16)
                        _k, nm, sem = self.res.resolve(t)
                        if nm in handler_marks:
                            continue
                        if sem is not None or nm in (
                                'MAKE_FUNCTION_FRAME', 'MAKE_MODULE_FRAME'):
                            has_sem = True
                    elif ins.mnemonic == 'call':
                        # dispatch di protocollo INLINE: `call [T+off]` con
                        # off = tp_iternext è il cuore del loop Python
                        # (iterazione compressa da MSVC nei resumer); non
                        # può mai essere rumore. tp_dealloc ([.. +0x30])
                        # resta rumore.
                        cm = parse_mem(ins.op_str)
                        if cm and cm[0] and not cm[2] and                                 cm[1] == self.abi.tp_iternext:
                            has_sem = True
                if has_sem:
                    continue
                succs = [s for s in b.succs if s in self.blocks]
                # Protezione: qualunque op che PRODUCE un valore Python
                # semantico (calc/expr oltre agli store) prova che il blocco
                # e' percorso normale, non macchina d'eccezione.  I bind del
                # module-init (UPDATE_STRING_DICT), le chiamate di creazione
                # classe e le mcall sono op ``calc``: senza questa protezione
                # l'intera continuazione del module-init dopo il primo
                # diamante class-creation veniva classificata error e
                # troncata.
                if succs and all(s in error_like for s in succs) and \
                        not any(o.kind in ('store', 'store_sub', 'store_attr',
                                           'append', 'setadd', 'ret', 'raise',
                                           'calc', 'expr', 'module_assign')
                                for o in b.ops):
                    error_like.add(st)
                    changed = True
        for st in error_like:
            if st in self.blocks:
                self.blocks[st].kind = 'error'
        # 3) blocchi refcount out-of-line (GCC -O2): il compilatore sposta
        # i percorsi lenti di incref/decref (overflow, dealloc) in fondo alla
        # funzione con un salto all'indietro nel flusso. Deterministico:
        # nessuna op Python + sole istruzioni refcount + terminatore jmp
        # all'indietro (o verso blocco refnoise/error).
        DEALLOC_NAMES = ('_Py_Dealloc', '_Py_NegativeRefcount', 'Py_FatalError',
                         'abort', 'NuitkaCannotGetHere')
        REF_MNEMS = {'mov', 'movl', 'movq', 'add', 'sub', 'test', 'cmp',
                     'je', 'jne', 'jmp', 'nop', 'xchg', 'not', 'neg',
                     'movzx', 'movsx', 'movslq', 'cs', 'data16'}
        changed = False
        while changed:
            changed = False
            for st, b in self.blocks.items():
                if b.kind == 'error' or b.ops:
                    continue
                last = b.insns[-1] if b.insns else None
                if last is None or last.mnemonic != 'jmp':
                    continue
                if not last.op_str.startswith('0x'):
                    continue
                try:
                    tgt = int(last.op_str, 16)
                except ValueError:
                    continue
                if tgt >= st:
                    continue          # solo salti all'indietro
                ok = True
                has_refcount_evidence = False
                saw_load = False
                saw_store_back = False
                for ins in b.insns:
                    if ins.mnemonic == 'call':
                        if not ins.op_str.startswith('0x'):
                            ok = False
                            break
                        try:
                            t = int(ins.op_str, 16)
                        except ValueError:
                            ok = False
                            break
                        _k, nm, _s = self.res.resolve(t)
                        if nm not in DEALLOC_NAMES:
                            ok = False
                            break
                        has_refcount_evidence = True
                    elif ins.mnemonic not in REF_MNEMS:
                        ok = False
                        break
                    else:
                        ops2 = split_ops(ins.op_str)
                        # load refcount: mov eRx, [reg]
                        if ins.mnemonic == 'mov' and len(ops2) == 2:
                            mm = parse_mem(ops2[1])
                            if mm and mm[0] and mm[1] == 0:
                                saw_load = True
                            mm2 = parse_mem(ops2[0])
                            if mm2 and mm2[0] and mm2[1] == 0:
                                saw_store_back = True
                        if ins.mnemonic in ('add', 'sub'):
                            has_refcount_evidence = has_refcount_evidence or \
                                (saw_load and len(ops2) == 2 and
                                 is_imm(ops2[1]) == 1)
                if ok and (has_refcount_evidence or (saw_load and
                                                     saw_store_back)):
                    b.kind = 'error'
                    changed = True
        # 4) codice cold out-of-line: blocchi raggiunti SOLO attraverso edge
        # d'errore (percorsi lenti refcount/dealloc che GCC sposta in fondo).
        # Un blocco con un predecessore raggiungibile via edge normale resta
        # nel flusso normale; gli altri sono cold → error.
        entry = min(self.blocks)
        reachable = {entry}
        changed = True
        while changed:
            changed = False
            for st, b in self.blocks.items():
                if st in reachable:
                    continue
                for p in b.preds:
                    pb = self.blocks.get(p)
                    if pb is None or p not in reachable:
                        continue
                    # I blocchi refcount/noise (error senza handler_sem) sono
                    # SEMANTICAMENTE TRASPARENTI: il flusso Python li
                    # attraversa. Bloccare la reachability su di essi isola
                    # i corpi-loop raggiungibili solo via un DECREF inline
                    # (il caso dei resumer di generatore). Solo i veri
                    # percorsi di exception-handling restano barrier.
                    noise_parent = pb.kind == 'error' and                         'handler_sem' not in pb.flags
                    if pb.kind == 'error' and not noise_parent:
                        continue
                    # In un resumer di generatore i percorsi d'eccezione
                    # avvolgono TUTTO il corpo: l'edge-typing 'error' sui
                    # null-check (celle closure, iteratori) non è affidabile
                    # come barriera — la polarità del salto decide se il
                    # target è l'errore o la continuazione. Per un genitore
                    # normale non-handler gli edge restano percorribili.
                    pass_error = noise_parent or (
                        self.gen_mode and pb.kind != 'error')
                    hit = False
                    for t, et in pb.edges:
                        if t == st and (et != 'error' or pass_error):
                            hit = True
                            break
                    if not hit and st in pb.succs:
                        # fallthrough non registrato come edge → normale
                        err_targets = {t for t, et in pb.edges if et == 'error'}
                        if st not in err_targets:
                            hit = True
                    if hit:
                        reachable.add(st)
                        changed = True
                        break
        for st, b in self.blocks.items():
            if st not in reachable and st != entry:
                # i blocchi con statement Python NON sono mai cold machinery
                # (calc/expr inclusi: bind di module-init, chiamate di
                # creazione classe, mcall — la continuazione del module-init
                # dopo i diamanti class-creation vive in blocchi raggiunti
                # attraverso edge di check NULL tipizzati error)
                if any(o.kind in ('store', 'store_sub', 'store_attr', 'append', 'setadd',
                                  'ret', 'raise', 'calc', 'expr',
                                  'module_assign') for o in b.ops):
                    continue
                b.kind = 'error'
        # 5) blocchi stop-iteration: raggiunti SOLO tramite edge 'stopiter'
        # (il check CHECK_AND_CLEAR_STOP_ITERATION dopo ITERATOR_NEXT NULL).
        # Sono la logica d'uscita del for: passthrough, senza statement.
        stopiter_only = set()
        for st, b in self.blocks.items():
            if b.kind != 'normal' or not b.preds:
                continue
            only_stopiter = True
            for p in b.preds:
                pb = self.blocks.get(p)
                if pb is None or pb.kind == 'error':
                    continue
                ets = [et for t, et in pb.edges if t == st]
                if ets and all(e in ('stopiter', 'error') for e in ets):
                    continue
                if st in pb.succs:
                    # fallthrough non tipizzato: normale
                    only_stopiter = False
                    break
            if only_stopiter and not any(
                    o.kind in ('store', 'store_sub', 'store_attr', 'append', 'setadd',
                               'ret', 'raise') for o in b.ops):
                stopiter_only.add(st)
        for st in stopiter_only:
            self.blocks[st].kind = 'stopiter'

    # ------------------------------------------------- symbolic execution
    _SVKEY_ATOMIC_OPS = frozenset((
        'const', 'imm', 'none', 'var', 'par', 'global', 'loc',
        'stackaddr', 'gslot', 'true', 'false', 'isnull'))

    def _svkey_of(self, sym):
        """sv_key con fast-path atomico e cache per-id.

        Il profilo sui binary grandi mostra milioni di store che chiedono
        la chiave strutturale dello stesso simbolo: il fast-path evita la
        chiamata ricorsiva per i nodi senza figli (chiave IDENTICA a
        sv_key: ``(op, repr(a), 'None', 'None')``), la cache (validata
        per identità, con strong-ref che mantiene valido l'id) riusa il
        risultato per i nodi composti. Svuotata a ogni pass: nessun
        nodo muta durante un singolo symbolic_pass."""
        if not isinstance(sym, NdxSV):
            return repr(sym)
        op = sym.op
        if op in self._SVKEY_ATOMIC_OPS and                 not isinstance(sym.a, NdxSV) and                 not isinstance(sym.a, (list, tuple)) and                 sym.b is None and sym.c is None:
            return (op, repr(sym.a), 'None', 'None')
        ck = getattr(self, '_sk_cache', None)
        if ck is None:
            ck = self._sk_cache = {}
        ent = ck.get(id(sym))
        if ent is not None and ent[0] is sym:
            return ent[1]
        # V100: memo PERSISTENTE condiviso tra chiamate dentro il pass:
        # ogni store ha un nodo top-level nuovo (la cache sopra non colpisce
        # mai) ma le SOTTOSTRUTTURE sono condivise — senza memo persistente
        # ogni store ripercorre l'intero grafo (quadratico sulle funzioni
        # giganti). Svuotato a ogni pass: nessun nodo muta entro un pass.
        mk = getattr(self, '_sk_memo', None)
        if mk is None:
            mk = self._sk_memo = {}
        k = sv_key(sym, _memo=mk)
        ck[id(sym)] = (sym, k)
        return k

    def symbolic_pass(self):
        self._sk_cache = {}
        self._sk_memo = {}
        """Esecuzione simbolica con worklist in priorità RPO.
        I predecessori via edge d'errore NON contribuiscono al merge:
        lo stato del flusso normale resta pulito."""
        entry = min(self.blocks) if self.blocks else None
        if entry is None:
            return
        # Every pass rebuilds block operations from scratch.  Keep the
        # context-object store evidence in lock-step with those operations so
        # a value from an earlier, less precise pass cannot leak into the
        # final IR.
        self.gen_result_stores = {}
        self.consumed_keyword_mappings = set()
        self.consumed_argument_vectors = set()
        # phi branch provenance: accumulata tra i pass (gli id dei loc
        # finali sono quelli dell'ultima passata; gli entry stale delle
        # passate precedenti non interferiscono con l'unione per pred).
        if self.gen_mode and self.gen_entry and                 self.gen_entry in self.blocks:
            entry = self.gen_entry
        order = self._rpo(entry)
        pos = {st: i for i, st in enumerate(order)}
        init_regs = {'rsp': ndx_k('stack_base', 0)}
        init_slots = {}
        if self.gen_mode:
            # resumer: (tstate, generator, yield_return_value)
            init_regs[self.abi.arg_regs[0]] = ndx_k('tstate')
            gr = 'rdx' if self.img.fmt == 'pe' else 'rsi'
            init_regs[gr] = ndx_k('genobj')
            yv = 'r8' if self.img.fmt == 'pe' else 'rdx'
            init_regs[yv] = ndx_k('var', '_sent')
            self.pars_reg = None
        elif not self.is_module_code:
            init_regs[self.abi.arg_regs[0]] = ndx_k('tstate')
            if getattr(self, 'has_closure', False):
                # def with freevars: ABI is (tstate, closure, python_pars).
                # The second parameter is the cell array of the enclosing
                # function, NOT a ``self`` value — modelling it as ``self``
                # made every closure read resolve to None.
                init_regs[self.abi.arg_regs[1]] = ndx_k('closure_array')
            else:
                init_regs[self.abi.arg_regs[1]] = ndx_k('self')
            pars_reg = self.abi.arg_regs[2]
            init_regs[pars_reg] = ndx_k('pars')
            self.pars_reg = pars_reg
        else:
            # module_code_M(tstate, module, loader_entry) follows the normal
            # platform ABI too.  Treating RCX as the module on Win64 shifted
            # every helper argument by one (notably SET_SUBSCRIPT/class-body
            # annotation writes).
            init_regs[self.abi.arg_regs[0]] = ndx_k('tstate')
            init_regs[self.abi.arg_regs[1]] = ndx_k(
                'mod', self.mca.module.name)
            if len(self.abi.arg_regs) > 2:
                init_regs[self.abi.arg_regs[2]] = ndx_k('loader_entry')
            self.pars_reg = None
        init = {'regs': init_regs, 'slots': init_slots,
                'cond': (None, None)}
        OUT = {}
        visits = {}

        def suspension_value_for_resume(resume_start):
            """Return the expression whose result re-enters this resumer.

            Nuitka implements every ``await``/``yield`` as two separate C
            invocations.  The first invocation stores a state number and
            returns; the dispatch of the next invocation jumps to
            ``gen_resume[state]`` with the suspension result in the resumer
            ABI value register.  Walk backwards from the yield block carrying
            that exact state and select the nearest already-lifted await.

            This is deliberately CFG/state based: frame offsets, helper
            addresses, source names and application constants are irrelevant.
            """
            states = {state for state, target in self.gen_resume.items()
                      if target == resume_start}
            frontier = [start for start, state in
                        self.gen_yield_blocks.items() if state in states]
            visited = set()
            resume_targets = set(self.gen_resume.values())
            while frontier and len(visited) < 256:
                candidates = []
                following = []
                for block_start in frontier:
                    if block_start in visited or block_start not in self.blocks:
                        continue
                    visited.add(block_start)
                    block = self.blocks[block_start]
                    for operation in block.ops:
                        value = operation.a if operation.kind == 'calc' else \
                            operation.b if operation.kind == 'store' else None
                        if isinstance(value, NdxSV) and value.op == 'await':
                            candidates.append((operation.va, value))
                    for predecessor in block.preds:
                        if predecessor in visited or predecessor not in self.blocks:
                            continue
                        pred_block = self.blocks[predecessor]
                        edge_type = self._edge_type(predecessor, block_start)
                        if pred_block.kind == 'error' or edge_type in (
                                'error', 'stopiter'):
                            continue
                        # Do not cross an older native re-entry boundary while
                        # looking for the suspension belonging to this state.
                        if predecessor in resume_targets and \
                                predecessor != resume_start:
                            continue
                        following.append(predecessor)
                if candidates:
                    return max(candidates, key=lambda item: item[0])[1]
                frontier = following
            return None

        import heapq
        heap = [(pos.get(entry, 0), entry)]
        in_wl = {entry}
        iters = 0
        while heap and iters < 100000:
            iters += 1
            _, st = heapq.heappop(heap)
            in_wl.discard(st)
            b = self.blocks[st]
            visits[st] = visits.get(st, 0) + 1
            if st == entry:
                in_state = init
            else:
                states = []
                err_states = []
                state_preds = []
                for p in b.preds:
                    if p not in OUT or p == st:
                        continue
                    if self.blocks[p].kind == 'error':
                        err_states.append(OUT[p])
                        continue
                    et = self._edge_type(p, st)
                    if et == 'error':
                        err_states.append(OUT[p])
                        continue
                    states.append(OUT[p])
                    state_preds.append(p)
                if states:
                    in_state = self._merge_states(states, preds=state_preds)
                elif err_states:
                    # blocco raggiunto SOLO via error-edge (handler): il suo
                    # stato d'ingresso è quello al punto dell'errore nel try
                    # (merge di tutti i punti di sollevamento)
                    in_state = self._merge_states(err_states)
                else:
                    in_state = {'regs': {}, 'slots': {},
                                'cond': (None, None)}
            if self.gen_mode and st in set(self.gen_resume.values()):
                # A synthetic yield->resume CFG edge represents a *new* C
                # invocation of the resumer.  Heap/closure state flows across
                # that edge, but its ABI registers are refreshed by Nuitka:
                # in particular yield_return_value is the result of the
                # preceding ``await``/``yield``.  Re-seeding these registers
                # prevents the calls before suspension from leaving the
                # resumed value spuriously undefined.
                resumed_regs = dict(in_state['regs'])
                resumed_regs[self.abi.arg_regs[0]] = ndx_k('tstate')
                for register in getattr(self, 'gen_object_regs', ()):
                    resumed_regs[register] = ndx_k('genobj')
                resumed_value = suspension_value_for_resume(st)
                if resumed_value is None:
                    resumed_value = ndx_k('var', '_sent')
                for register in getattr(self, 'gen_value_regs', ()):
                    resumed_regs[register] = resumed_value
                in_state = {
                    'regs': resumed_regs,
                    'slots': dict(in_state['slots']),
                    'cond': in_state.get('cond', (None, None)),
                }
            self.regs = dict(in_state['regs'])
            self.slot_syms = dict(in_state['slots'])
            self._incoming_cond = in_state.get('cond', (None, None))
            self._exec_block(b)
            new_out = {'regs': dict(self.regs), 'slots': dict(self.slot_syms),
                       'cond': (self._cond_val, self._cond_kind)}
            old = OUT.get(st)
            OUT[st] = new_out
            self._final_out = OUT
            if old is None or not self._same_state(old, new_out) or \
                    visits[st] <= 1:
                for s in b.succs:
                    if s in self.blocks and s not in in_wl and \
                            visits.get(s, 0) < 12:
                        heapq.heappush(heap, (pos.get(s, 9999), s))
                        in_wl.add(s)
            if visits[st] >= 6:
                continue

        snapshots = getattr(self, 'native_return_phis', None)
        if snapshots is None:
            snapshots = self.native_return_phis = {}
        for block in self.blocks.values():
            for operation in block.ops:
                value = operation.a
                if operation.kind == 'ret' and isinstance(value, NdxSV) and \
                        id(value) in getattr(self, '_phi_inputs', {}):
                    snapshots[block.start] = value

    def _edge_type(self, src, tgt):
        for t, et in self.blocks[src].edges:
            if t == tgt:
                return et
        if tgt in self.blocks[src].succs:
            return 'fallthrough'
        return 'unknown'

    def _merge_states(self, states, preds=None):
        regs = {}
        slots = {}
        # Per-branch provenance of value merges: when two branch values
        # disagree and a loc phi is created, the (predecessor, value) pairs
        # are recorded so the renderer can materialise the phi back into
        # the empty branch arms (``if c1: x = a elif c2: x = b``).  Purely
        # additive: the merge decisions are untouched.
        preds = preds or [None] * len(states)
        if not hasattr(self, '_phi_inputs'):
            self._phi_inputs = {}
            self._phi_symbols = {}
        _phi_first = {}

        def _record_phi(loc_sym, slot_key, first_pair, pair):
            inputs = []
            if first_pair is not None:
                inputs.append(first_pair)
            inputs.append(pair)
            # flatten chained phis (branch merges absorbed a previous phi)
            flat = []
            for p, v in inputs:
                nested = None
                if isinstance(v, NdxSV) and v.op == 'loc':
                    nested = self._phi_inputs.get(id(v))
                if nested is not None:
                    flat.extend(nested)
                else:
                    flat.append((p, v))
            # Keep the node alive: id-only provenance otherwise aliases a later
            # allocation after Python reuses the old object's address.
            self._phi_symbols[id(loc_sym)] = loc_sym
            self._phi_inputs[id(loc_sym)] = flat

        def container_origin(value):
            if isinstance(value, NdxSV) and value.op in (
                    'tuple_build', 'list_build', 'dict_build', 'loc'):
                return value.n
            return None

        def nullable_protocol(left, right):
            """Merge a protocol pointer with its explicit NULL alternative.

            CPython dispatch templates load a type slot or zero, merge those
            branches, and immediately guard the call with ``test slot,slot``.
            Retaining the non-NULL semantic identity is safe and lets the
            guarded success branch recover the source operation.
            """
            protocol_ops = {'binary_slot', 'len_slot', 'tpiternext',
                            'tp_slot'}
            for protocol, null_value in ((left, right), (right, left)):
                if isinstance(protocol, NdxSV) and \
                        protocol.op in protocol_ops and \
                        isinstance(null_value, NdxSV) and \
                        null_value.op == 'imm' and null_value.a == 0:
                    return protocol
            return None

        for si, ps in enumerate(states):
            pred = preds[si] if si < len(preds) else None
            for r, v in ps['regs'].items():
                if r not in regs:
                    regs[r] = v
                    _phi_first[r] = (pred, v)
                    continue
                prev_pair = ((None, regs[r]) if id(regs[r]) in self._phi_inputs
                             else _phi_first.get(r) or (pred, regs[r]))
                if regs[r] is not v and not _sv_eq(regs[r], v):
                    protocol = nullable_protocol(regs[r], v)
                    if protocol is not None:
                        regs[r] = protocol
                        continue
                    # conflitto: None-ENGINE (registro senza sym: percorso
                    # d'errore che azzera, cold path) NON è un valore
                    # Python e non può vincere — mantiene il valore noto.
                    # Solo valore-vs-valore produce un phi loc.
                    if regs[r] is None:
                        regs[r] = v
                        continue
                    if v is None:
                        continue
                    # Un immediato `imm` è un valore di MACCHINA (C NULL,
                    # numeri di riga per il traceback, size C): non è mai
                    # un oggetto Python — gli interi Python arrivano come
                    # `const` dal blob costanti. In un merge normale il
                    # lato imm perde contro un vero simbolo Python.
                    def _machine_value(s):
                        return isinstance(s, NdxSV) and s.op == 'imm'
                    if _machine_value(regs[r]) != _machine_value(v):
                        if _machine_value(v):
                            continue        # il simbolo Python resta
                        regs[r] = v
                        continue
                    # Due interpretazioni PRECISE di valori Python diversi
                    # devono sopravvivere entrambe: il phi è l'unica
                    # rappresentazione fedele (il valore dipende dal ramo
                    # percorso a runtime). Una merge può mantenere un solo
                    # valore soltanto quando il lato perdente è una chiamata
                    # nativa GENERICA non risolta (`nativecall`/`apicall`):
                    # il diamante fast/slow del dispatch su slot CPython,
                    # dove entrambi i rami calcolano lo STESSO valore di
                    # macchina ma un solo ramo ha recuperato semantica
                    # Python. Nelle vecchie versioni un rank di "semanticità"
                    # faceva vincere un producer contro una costante precisa
                    # (una costante intera dal blob vs una chiamata),
                    # distruggendo silenziosamente i valori condizionali
                    # reali che convergono in un epilogo C condiviso.
                    def _generic_native(s):
                        return isinstance(s, NdxSV) and \
                            s.op in ('nativecall', 'apicall')
                    if _generic_native(regs[r]) != _generic_native(v):
                        if _generic_native(v):
                            # PHI-COLLAPSE FIX: quando il registro e'
                            # gia' legato a un valore semantico e il
                            # nuovo lato e' una call nativa, crea il
                            # loc-phi con provenienza invece di
                            # collassare al primo lato (i valori
                            # condizionali reali convergono in un
                            # epilogo C condiviso).
                            left_origin_p = container_origin(regs[r])
                            right_origin_p = container_origin(v)
                            origin_p = left_origin_p \
                                if left_origin_p is not None and \
                                left_origin_p == right_origin_p \
                                else None
                            regs[r] = ndx_k('loc', ('reg', r), 
                                            n=origin_p)
                            _record_phi(regs[r], ('reg', r), 
                                        prev_pair, (pred, v))
                            continue
                        regs[r] = v
                        continue
                    left_origin = container_origin(regs[r])
                    right_origin = container_origin(v)
                    origin = left_origin if left_origin is not None and \
                        left_origin == right_origin else None
                    regs[r] = ndx_k('loc', ('reg', r), n=origin)
                    _record_phi(regs[r], ('reg', r), prev_pair, (pred, v))
            for s, v in ps['slots'].items():
                if s not in slots:
                    slots[s] = v
                    _phi_first[('mem',) + tuple(s)] = (pred, v)
                    continue
                skey = ('mem',) + tuple(s)
                prev_pair = ((None, slots[s]) if id(slots[s]) in self._phi_inputs
                             else _phi_first.get(skey) or (pred, slots[s]))
                if slots[s] is not v and not _sv_eq(slots[s], v):
                    if slots[s] is None:
                        slots[s] = v
                        _phi_first[skey] = (pred, v)
                    elif v is None:
                        pass
                    else:
                        protocol = nullable_protocol(slots[s], v)
                        if protocol is not None:
                            slots[s] = protocol
                        else:
                            slots[s] = ndx_k('loc', ('mem',) + tuple(s))
                            _record_phi(slots[s], skey, prev_pair,
                                        (pred, v))
        conditions = [state.get('cond', (None, None)) for state in states]
        condition = (None, None)
        if conditions:
            first_value, first_kind = conditions[0]
            if all(kind == first_kind and
                   ((value is first_value) or _sv_eq(value, first_value))
                   for value, kind in conditions[1:]):
                condition = (first_value, first_kind)
        return {'regs': regs, 'slots': slots, 'cond': condition}

    def _same_state(self, a, b):
        if len(a['regs']) != len(b['regs']) or \
                len(a['slots']) != len(b['slots']):
            return False
        for r, v in a['regs'].items():
            if not _sv_eq(b['regs'].get(r), v):
                return False
        for s, v in a['slots'].items():
            if not _sv_eq(b['slots'].get(s), v):
                return False
        av, ak = a.get('cond', (None, None))
        bv, bk = b.get('cond', (None, None))
        if ak != bk or not ((av is bv) or _sv_eq(av, bv)):
            return False
        return True


    def _rpo(self, entry):
        visited = set()
        order = []

        if entry in self.blocks:
            visited.add(entry)
            stack = [(entry, iter(self.blocks[entry].succs))]
            while stack:
                node, successors = stack[-1]
                successor = next(successors, None)
                if successor is None:
                    order.append(node)
                    stack.pop()
                elif successor not in visited and successor in self.blocks:
                    visited.add(successor)
                    stack.append((successor, iter(self.blocks[successor].succs)))
        order.reverse()
        # blocchi irraggiungibili (error paths isolati): in coda
        for st in sorted(self.blocks):
            if st not in visited:
                order.append(st)
        return order

    # ------------------------------------------------------------------ exec
    def _exec_block(self, b):
        b.ops = []
        b.edges = []
        b.conds = []
        self._cur_block = b
        self._last_call = None       # (insn, sym, helper_name, sem)
        self._cond_val, self._cond_kind = getattr(
            self, '_incoming_cond', (None, None))
        self._pending_ternext = None
        is_yield_blk = self.gen_mode and b.start in self.gen_yield_blocks
        inline_binop = self._inlined_binop_joins.get(b.start)
        if inline_binop is not None:
            out_reg, left_reg, right_reg, operator, _source, _consumer = inline_binop
            left = self._reg(left_reg)
            right = self._reg(right_reg)
            if left is not None and right is not None:
                value = ndx_k('binop', operator, left, right)
                self._setreg(out_reg, value)
                b.ops.append(NdxOp('calc', a=value, va=b.start))
        numeric_slow = self._specialized_numeric_joins.get(b.start)
        if numeric_slow in self.blocks:
            values = [op.a for op in self.blocks[numeric_slow].ops
                      if op.kind == 'calc' and op.a is not None and
                      op.a.op == 'binop']
            if values:
                value = values[-1]
                self._setreg(self.abi.ret_reg, value)
                b.ops.append(NdxOp('calc', a=value, va=b.start))
        n = len(b.insns)
        i = 0
        while i < n:
            ins = b.insns[i]
            if is_yield_blk and ins.mnemonic in ('ret', 'jmp'):
                # fine del blocco-yield: rax contiene il valore prodotto
                # (`mov rax, r14` dopo lo store dell'indice); il flusso
                # Python continua nel resume block (succs già rewired).
                val = self._reg('rax')
                # A plain coroutine's suspension is already represented by
                # the preceding ASYNC_AWAIT node; only generators and async
                # generators expose a source-level ``yield`` expression.
                flags = int(getattr(self.co, 'flags', 0) or 0)
                if not (flags & 0x80 and not flags & (0x20 | 0x200)):
                    b.ops.append(NdxOp('yield', a=val, va=ins.address))
                resume = self.gen_resume.get(self.gen_yield_blocks[b.start])
                if resume in self.blocks:
                    b.edges.append((resume, 'goto'))
                break
            consumed = self._try_patterns(b, i)
            if consumed:
                i += consumed
                continue
            self._exec_insn(ins)
            i += 1
        self._finish_block(b)

    # ---- pattern multi-istruzione (rumore deterministico) ----
    def _try_patterns(self, b, i):
        """Pattern multi-istruzione (rumore deterministico). Intel syntax."""
        insns = b.insns
        n = len(insns)
        ins = insns[i]
        m = ins.mnemonic
        ops = split_ops(ins.op_str)

        # --- INCREF inline: mov r2, [r]; add r2, 1; [je ovf]; mov [r], r2
        if m == 'mov' and len(ops) == 2:
            mem = parse_mem(ops[1])
            if mem and mem[0] and mem[1] == self.abi.ob_refcnt and \
                    not mem[2]:
                base = mem[0]
                if i + 2 < n:
                    i1, i2 = insns[i + 1], insns[i + 2]
                    o1 = split_ops(i1.op_str)
                    o2 = split_ops(i2.op_str)
                    # add r2, 1
                    if i1.mnemonic == 'add' and len(o1) == 2 and \
                            is_imm(o1[1]) == 1:
                        # mov [base], r2  (con possibile je in mezzo)
                        if i2.mnemonic == 'mov' and len(o2) == 2 and \
                                parse_mem(o2[0]) and \
                                parse_mem(o2[0])[0] == base and \
                                parse_mem(o2[0])[1] == 0:
                            return 3
                        if i2.mnemonic == 'je' and i + 3 < n and \
                                insns[i + 3].mnemonic == 'mov':
                            o3 = split_ops(insns[i + 3].op_str)
                            if len(o3) == 2 and parse_mem(o3[0]) and \
                                    parse_mem(o3[0])[0] == base and \
                                    parse_mem(o3[0])[1] == 0:
                                return 4
                    # DECREF: mov r2,[r]; sub r2,1; [je dealloc]; mov [r],r2
                    if i1.mnemonic == 'sub' and len(o1) == 2 and \
                            is_imm(o1[1]) == 1:
                        j = i + 2
                        if j < n and insns[j].mnemonic == 'mov':
                            o2 = split_ops(insns[j].op_str)
                            if len(o2) == 2 and parse_mem(o2[0]) and \
                                    parse_mem(o2[0])[0] == base and \
                                    parse_mem(o2[0])[1] == 0:
                                return 3
                        if j < n and insns[j].mnemonic == 'je' and \
                                j + 1 < n and insns[j + 1].mnemonic == 'mov':
                            o3 = split_ops(insns[j + 1].op_str)
                            if len(o3) == 2 and parse_mem(o3[0]) and \
                                    parse_mem(o3[0])[0] == base and \
                                    parse_mem(o3[0])[1] == 0:
                                return 4
                        # decref con salto a dealloc: consuma fino al mov
                        # (mov [base],r2 può seguire un je dealloc)
                        if j + 1 < n and insns[j].mnemonic == 'je':
                            k = j + 1
                            while k < n and k < j + 3:
                                if insns[k].mnemonic == 'mov':
                                    ok = split_ops(insns[k].op_str)
                                    if len(ok) == 2 and parse_mem(ok[0]) \
                                            and parse_mem(ok[0])[0] == base \
                                            and parse_mem(ok[0])[1] == 0:
                                        return k - i + 1
                                k += 1
            # lea r2, [r + 1]; mov [r], r2 (incref lea-form)
            if len(ops) == 2 and i + 1 < n:
                mem = parse_mem(ops[1])
                if mem and mem[0] and mem[1] == 1 and not mem[2]:
                    i1 = insns[i + 1]
                    o1 = split_ops(i1.op_str)
                    if i1.mnemonic == 'mov' and len(o1) == 2:
                        tm = parse_mem(o1[0])
                        if tm and tm[0] == mem[0] and tm[1] == 0:
                            return 2

        # --- tp_iternext inline:
        #   mov rT, [it + 8]        ; ob_type
        #   mov rF, [rT + 0xe0]     ; tp_iternext
        #   mov rArg, it
        #   call rF
        if m == 'mov' and len(ops) == 2 and i + 3 < n:
            mem = parse_mem(ops[1])
            if mem and mem[0] and mem[1] == self.abi.ob_type and not mem[2]:
                it_reg = mem[0]
                i1, i2, i3 = insns[i + 1], insns[i + 2], insns[i + 3]
                o1 = split_ops(i1.op_str)
                m1 = parse_mem(o1[1]) if i1.mnemonic == 'mov' and \
                    len(o1) == 2 else None
                if m1 and m1[0] and m1[1] == self.abi.tp_iternext and \
                        not m1[2] and i2.mnemonic == 'mov' and \
                        i3.mnemonic == 'call':
                    it_sym = self._reg(it_reg)
                    if it_sym is not None and it_sym.op == 'iter':
                        o2 = split_ops(i2.op_str)
                        if len(o2) == 2:
                            self._setreg(o2[0], it_sym.a if it_sym.a
                                         is not None else it_sym)
                        self._setreg(self.abi.ret_reg, ndx_k('next', it_sym))
                        self._cur_block.ops.append(
                            NdxOp('calc', a=ndx_k('next', it_sym),
                               va=ins.address))
                        return 4
        # --- f_lineno: mov dword ptr [frame + 0x40], imm
        if m == 'mov' and len(ops) == 2:
            mem = parse_mem(ops[0])
            if mem and mem[0] and mem[1] == self.abi.f_lineno and not mem[2]:
                base_sym = self._reg(mem[0])
                if base_sym is not None and base_sym.op == 'frame':
                    ln = is_imm(ops[1])
                    if ln:
                        b.ops.append(NdxOp('line', n=ln, va=ins.address))
                    return 1
        # --- refcount check: sub/add rX,1; [mov [rB],rX]; jcc → error edge
        # NB: il jcc NON viene consumato: processato con cond 'refcount'
        if m in ('sub', 'add') and len(ops) == 2 and is_imm(ops[1]) == 1:
            rX = subreg64(ops[0])
            refmem = parse_mem(ops[0])
            ref_target = bool(
                (rX and rX not in ('rsp', 'rbp')) or
                (refmem and refmem[0] not in ('rsp', 'rbp', 'rip') and
                 refmem[1] == 0 and not refmem[2]))
            if ref_target:
                nxt_jcc = (i + 1 < n and insns[i + 1].mnemonic in COND_JCC)
                nxt2 = (i + 2 < n and insns[i + 1].mnemonic == 'mov' and
                        insns[i + 2].mnemonic in COND_JCC)
                if nxt_jcc or nxt2:
                    self._cond_val = None
                    self._cond_kind = 'refcount'
                    return 1
        # --- salto immortale check: cmp byte ptr [r + 0x46], 1 → noise
        if m == 'cmp' and len(ops) == 2:
            mem = parse_mem(ops[0])
            if mem and mem[0] and 0x40 <= mem[1] <= 0x48:
                base_sym = self._reg(mem[0])
                if base_sym is not None and base_sym.op in ('const',
                                                            'par', 'var'):
                    return 1
        return 0

    # ---- singola istruzione ----
    def _inlined_long_inplace_store(self, ins, base, off, source_register):
        """Recover an inlined PyLong ``local <op>= small_literal`` region.

        MSVC can inline all compact/non-compact PyLong branches into the
        caller.  The source operation is nevertheless proven by four facts in
        one bounded region: the same local is loaded and written back, both
        PyLong header and digit payload are inspected, and a generic
        ``PyNumber_*`` fallback carrying the exact binary operator is present.
        The literal is the small displacement used by the compact fast path.
        """
        index = next((position for position, item in enumerate(self.insns)
                      if item.address == ins.address), None)
        if index is None or source_register is None:
            return None
        lower = max(0, index - 180)
        load_index = None
        value_register = None
        for position in range(index - 1, lower - 1, -1):
            item = self.insns[position]
            operands = split_ops(item.op_str)
            if item.mnemonic != 'mov' or len(operands) != 2:
                continue
            memory = parse_mem(operands[1])
            if memory and memory[0] == base and memory[1] == off and \
                    memory[2] is None:
                load_index = position
                value_register = subreg64(operands[0])
                break
            destination = parse_mem(operands[0])
            if destination and destination[0] == base and \
                    destination[1] == off and destination[2] is None:
                return None
        if load_index is None or value_register != source_register:
            return None
        region = self.insns[load_index:index]
        has_header = any(
            (lambda operands: len(operands) == 2 and
             (lambda memory: memory is not None and
              memory[0] == value_register and memory[1] == 0x10 and
              memory[2] is None)(parse_mem(operands[1])))(
                split_ops(item.op_str))
            for item in region if item.mnemonic == 'mov')
        has_digit = any(
            (lambda operands: len(operands) == 2 and
             (lambda memory: memory is not None and
              memory[0] == value_register and memory[1] >= 0x18 and
              memory[2] is None)(parse_mem(operands[1])))(
                split_ops(item.op_str))
            for item in region if item.mnemonic == 'mov')
        if not (has_header and has_digit):
            return None
        operator = None
        for item in region:
            if item.mnemonic != 'call' or not item.op_str.startswith('0x'):
                continue
            try:
                _kind, name, semantic = self.res.resolve(
                    int(item.op_str, 16))
            except Exception:
                continue
            if semantic and semantic[0] == 'binop' and \
                    isinstance(name, str) and name.startswith('PyNumber_'):
                operator = semantic[1]
                break
        if operator not in ('+', '-', '*', '/', '//', '%', '<<', '>>',
                            '&', '|', '^'):
            return None
        displacement = None
        for item in region:
            operands = split_ops(item.op_str)
            if item.mnemonic != 'lea' or len(operands) != 2 or \
                    subreg64(operands[0]) is None:
                continue
            memory = parse_mem(operands[1])
            if not memory or memory[0] in ('rsp', 'rbp', value_register) or \
                    memory[2] is not None or memory[1] == 0 or \
                    abs(memory[1]) > 16:
                continue
            displacement = memory[1]
        if displacement is None:
            return None
        literal = abs(displacement) if operator == '-' else displacement
        left = ndx_k('loc', ('mem', base, off))
        return ndx_k('binop', operator, left,
                     ndx_k('const', literal), n='inplace')

    def _exec_insn(self, ins):
        self._cur_insn_addr = ins.address
        m = ins.mnemonic
        ops = split_ops(ins.op_str)
        nops = len(ops)

        if m in ('push', 'pop'):
            stack = self._reg('rsp')
            if isinstance(stack, NdxSV) and stack.op == 'stack_base':
                self._setreg('rsp', ndx_k('stack_base', stack.a + (8 if m == 'pop' else -8)))
            if m == 'pop' and ops and subreg64(ops[0]):
                self._setreg(ops[0], None)
            return
        if m in ('add', 'sub') and nops == 2 and subreg64(ops[0]) == 'rsp':
            stack = self._reg('rsp')
            amount = is_imm(ops[1])
            if amount is None:
                value = self._reg(subreg64(ops[1]))
                if isinstance(value, NdxSV) and value.op == 'imm':
                    amount = value.a
            self._setreg('rsp', ndx_k('stack_base', stack.a + (amount if m == 'add' else -amount))
                         if isinstance(stack, NdxSV) and stack.op == 'stack_base' and
                         isinstance(amount, int) else None)
            return
        if m == 'lea' and nops == 2 and subreg64(ops[0]) in ('rsp', 'rbp'):
            memory = parse_mem(ops[1])
            origin = self._reg(memory[0]) if memory else None
            if memory and not memory[2] and isinstance(origin, NdxSV) and origin.op == 'stack_base':
                self._setreg(ops[0], ndx_k('stack_base', origin.a + memory[1]))
                return

        if m == 'mov' or m == 'movabs':
            if nops != 2:
                return
            dst, src = ops
            # store in memoria: mov [base+off], reg/imm
            dmem = parse_mem(dst)
            if dmem:
                base, off = dmem[0], dmem[1]
                if base is None:
                    return
                imm = is_imm(src)
                if imm is not None:
                    self._store_slot(base, off, None)
                    return
                sr = subreg64(src)
                if sr:
                    src_sym = self._reg(sr)
                    inlined_inplace = self._inlined_long_inplace_store(
                        ins, base, off, sr)
                    if inlined_inplace is not None:
                        src_sym = inlined_inplace
                        self._setreg(sr, src_sym)
                        self._store_slot(base, off, src_sym)
                        self._cur_block.ops.append(NdxOp(
                            'store', a=('mem', base, off), b=src_sym,
                            va=ins.address))
                        return
                    if base == 'rip' and isinstance(src_sym, NdxSV) and \
                            src_sym.op == 'dict_index':
                        cache = getattr(self, 'dict_index_slots', None)
                        if cache is None:
                            cache = self.dict_index_slots = {}
                        slot = rip_target(ins)
                        if slot is not None:
                            previous = cache.get(slot, src_sym)
                            cache[slot] = src_sym if _sv_eq(previous, src_sym) else None
                    self._store_slot(base, off, src_sym)
                    self._note_slot_store(base, off, src_sym, ins, src_reg=sr)
                else:
                    self._store_slot(base, off, None)
                return
            # immediato
            imm = is_imm(src)
            if imm is not None:
                self._setreg(dst, ndx_k('imm', imm))
                return
            # registro
            sr = subreg64(src)
            if sr:
                src_sym = self._reg(sr)
                self._setreg(dst, src_sym)
                self._note_store(dst, src_sym, ins, src_reg=sr)
                return
            # memoria
            mem = parse_mem(src)
            if mem:
                base, off = mem[0], mem[1]
                if base is not None:
                    self._load_mem(dst, base, off, ins, mem)
                else:
                    self._setreg(dst, None)
                return
            self._setreg(dst, None)
            return

        if m in ('movl', 'movq', 'movb', 'movw', 'movslq', 'movzx', 'movsx'):
            if nops != 2:
                return
            dst, src = ops
            dmem = parse_mem(dst)
            if dmem:
                # store parziale su slot: non assegnamento Python
                base, off = dmem[0], dmem[1]
                if base is not None:
                    self._store_slot(base, off, None)
                return
            mem = parse_mem(src)
            if mem and mem[0] is not None:
                self._load_mem(dst, mem[0], mem[1], ins, mem)
            elif 'rip' in src:
                t = rip_target(ins)
                self._load_rip(dst, t, ins)
            else:
                imm = is_imm(src)
                if imm is not None and m in ('movl', 'movq', 'mov'):
                    self._setreg(dst, ndx_k('imm', imm))
                else:
                    sr = subreg64(src) if src else None
                    self._setreg(dst, self._reg(sr) if sr else None)
            return

        if m in ('cmove', 'cmovz', 'cmovne', 'cmovnz') and nops == 2:
            # Conditional moves are the branchless form used for compact
            # Python conditional expressions.  Accept them only while the
            # flags still describe a recovered Python boolean comparison;
            # arbitrary native flag arithmetic remains machinery.
            condition = self._cond_val
            if condition is None or self._cond_kind not in (
                    'nbool', 'cbool', 'auto', 'int_nonzero', 'is_none',
                    'is_single'):
                return
            dst, src = ops
            destination = subreg64(dst)
            if destination is None:
                return
            previous = self._reg(destination)
            source = None
            source_register = subreg64(src)
            if source_register is not None:
                source = self._reg(source_register)
            else:
                memory = parse_mem(src)
                if memory and memory[0] is not None:
                    # Reuse the ordinary exact constant/global load path, then
                    # restore the old destination before installing the select.
                    self._load_mem(destination, memory[0], memory[1], ins,
                                   memory)
                    source = self._reg(destination)
                    self._setreg(destination, previous)
            if previous is None or source is None:
                return
            if m in ('cmove', 'cmovz'):
                value = ndx_k('ifexp', condition, source, previous)
            else:
                value = ndx_k('ifexp', condition, previous, source)
            self._setreg(destination, value)
            return

        if m == 'lea':
            if nops != 2:
                return
            dst, src = ops
            if 'rip' in src:
                t = rip_target(ins)
                self._load_rip(dst, t, ins, addr=True)
            else:
                mem = parse_mem(src)
                # MSVC uses either the live stack pointer or a frame pointer as
                # the base of temporary PyObject* argument arrays.  Keep the
                # actual base register: KW_SPLIT and ARGS<n> expansion is the
                # same ABI operation in both cases.
                if mem and mem[0] in ('rsp', 'rbp') and not mem[2]:
                    self._setreg(dst, ndx_k('stackaddr', mem[0], mem[1]))
                elif mem and mem[0] and not mem[2]:
                    base_value = self._reg(mem[0])
                    if base_value is not None and \
                            base_value.op == 'const' and \
                            isinstance(base_value.a, (tuple, list)) and \
                            mem[1] >= 0x18 and (mem[1] - 0x18) % 8 == 0:
                        # PyTupleObject stores its item vector inline after the
                        # PyVarObject header.  A LEA of that proven constant
                        # object's payload is an argument-vector pointer, not
                        # a source-level address expression.
                        self._setreg(dst, ndx_k(
                            'const_array', base_value.a,
                            (mem[1] - 0x18) // 8, n=base_value))
                    elif base_value is not None and base_value.op in (
                            'list_empty', 'list_build', 'dict_empty', 'set_empty',
                            'tuple_build') and -0x40 <= mem[1] <= 0x40:
                        self._setreg(dst, base_value)
                    elif base_value is not None and mem[1] == 0x18 and \
                            base_value.op in (
                            'par', 'var', 'getattr', 'global', 'const',
                            'call', 'binop', 'next', 'mcall', 'sub',
                            'ifexp', 'len'):
                        # PyLongObject.ob_digit sits at +0x18 (after the
                        # PyVarObject header + compact tag).  The inlined
                        # long arithmetic takes DIGIT pointers derived from
                        # the real operand objects; keeping the object
                        # provenance lets the Long helper mapping recover
                        # the actual Python operands (``k - 1``).
                        self._setreg(dst, ndx_k('digit_ptr', base_value))
                    else:
                        self._setreg(dst, None)
                else:
                    self._setreg(dst, None)
            return

        if m == 'xor' and len(ops) == 2 and \
                subreg64(ops[0]) is not None and \
                subreg64(ops[0]) == subreg64(ops[1]):
            self._setreg(ops[0], ndx_k('imm', 0))
            return

        if m in ('add', 'sub', 'or', 'and', 'xor', 'shl', 'shr', 'sar',
                 'imul', 'neg', 'not', 'inc', 'dec'):
            if len(ops) == 2 and subreg64(ops[0]):
                dst_reg = subreg64(ops[0])
                left = self._reg(dst_reg)
                immediate = is_imm(ops[1])
                right = ndx_k('imm', immediate) if immediate is not None else \
                    self._reg(subreg64(ops[1]))
                if isinstance(left, NdxSV) and isinstance(right, NdxSV):
                    if m == 'add' and left.op == right.op == 'dict_index' and \
                            _sv_eq(left.a, right.a) and left.b == right.b:
                        self._setreg(dst_reg, ndx_k(
                            'dict_index', left.a, left.b, left.c + right.c))
                        return
                    if m == 'shl' and left.op == 'imm' and left.a == 1 and \
                            right.op == 'dict_index_log':
                        self._setreg(dst_reg, ndx_k('dict_index_bytes', right.a))
                        return
                    if m == 'add':
                        size, keys = (left, right) if left.op == 'dict_index_bytes' \
                            else (right, left)
                        if size.op == 'dict_index_bytes' and keys.op == 'dict_keys' and \
                                _sv_eq(size.a, keys):
                            self._setreg(dst_reg, ndx_k('dict_entries', keys))
                            return
            if m == 'add' and len(ops) == 2:
                dst_reg = subreg64(ops[0])
                value = self._reg(dst_reg) if dst_reg else None
                displacement = is_imm(ops[1])
                if value is not None and value.op == 'const' and \
                        isinstance(value.a, (tuple, list)) and \
                        displacement is not None and displacement >= 0x18 \
                        and (displacement - 0x18) % 8 == 0:
                    self._setreg(dst_reg, ndx_k(
                        'const_array', value.a, (displacement - 0x18) // 8))
                    return
                if value is not None and value.op == 'tuple_build' and \
                        displacement == 0x18:
                    # A tuple's item vector is inline.  Keeping the allocation
                    # node attached to the payload pointer lets vectorcall
                    # consume the completed tuple while native element stores
                    # remain implementation detail.
                    self._setreg(dst_reg, value)
                    return
                if value is not None and displacement == 0x18 and \
                        value.op in ('par', 'var', 'getattr', 'global',
                                     'const', 'call', 'binop', 'next',
                                     'mcall', 'sub', 'ifexp', 'len',
                                     'digit_ptr'):
                    # PyLong inline magic: `add ptr, 0x18` derives the
                    # ob_digit pointer from the operand object.  Keeping
                    # the object provenance lets the Long helper mapping
                    # restore the actual Python operands (``k - 1``).
                    inner = value.a if value.op == 'digit_ptr' else value
                    self._setreg(dst_reg, ndx_k('digit_ptr', inner))
                    return
            # aritmetica C: neutra per il dataflow Python (i valori Python
            # vivono in PyObject*; l'aritmetica qui è su interi/indici C)
            for r in ops:
                r64 = subreg64(r) if r else None
                if r64 and r64 not in ('rsp', 'rbp'):
                    # il dst può essere sovrascritto: invalida
                    pass
            # invalida il registro destinazione
            if ops:
                d64 = subreg64(ops[0])
                if d64 and d64 not in ('rsp', 'rbp') and m in (
                        'add', 'sub', 'or', 'and', 'xor', 'shl', 'shr',
                        'sar', 'imul', 'neg', 'not', 'inc', 'dec'):
                    self._setreg(d64, None)
                elif m in ('add', 'sub') and parse_mem(ops[0]) is not None \
                        and len(ops) == 2 and is_imm(ops[1]) == 1:
                    self._cond_val = None
                    self._cond_kind = 'refcount'
            return

        if m in ('sete', 'setne', 'setz', 'setnz') and nops == 1:
            value = self._cond_val
            if value is not None and m in ('sete', 'setz'):
                value = ndx_k('not', value)
            self._setreg(ops[0], value)
            return

        if m == 'call':
            self._exec_call(ins)
            return

        if m in ('test', 'cmp'):
            self._exec_test(ins)
            return

        if m in COND_JCC or m == 'jmp':
            self._exec_jcc(ins)
            return

        if m == 'ret':
            return
        # push/pop/xchg/nop/altro: neutro
        return

    # ---- helpers di stato ----
    def _reg(self, r):
        if r is None:
            return None
        r64 = subreg64(r)
        return self.regs.get(r64)

    def _setreg(self, dst, val):
        r64 = subreg64(dst)
        if r64:
            self.regs[r64] = val
            # registro delle definizioni semantiche per-VA (per il
            # recovery cross-block degli argomenti): simboli Python-levelli
            # che entrano in un registro, con l'indirizzo della def
            if isinstance(val, NdxSV) and val.op not in (
                    'tstate', 'frame', 'excstate', 'pars', 'imm'):
                if not hasattr(self, 'reg_sem_defs'):
                    self.reg_sem_defs = {}
                self.reg_sem_defs[(r64, self._cur_insn_addr)] = val
            if isinstance(val, NdxSV) and val.n is not None and val.op in (
                    'tuple_build', 'list_build', 'dict_build', 'loc'):
                self.container_reg_origins[r64] = val.n
            elif not (isinstance(val, NdxSV) and val.op == 'loc'):
                self.container_reg_origins.pop(r64, None)

    def _imm(self, s):
        try:
            return int(s.strip().lstrip('$'), 16)
        except ValueError:
            return None

    # ------------------------------------------------- store tracking
    CALLEE_SAVED = ('rbx', 'r12', 'r13', 'r14', 'r15', 'rbp')

    def _is_argument_array_slot(self, address, base, off, max_back=0x90):
        """Prove that a stack slot is part of a CALL_* PyObject** array."""
        index = next((i for i, item in enumerate(self.insns)
                      if item.address == address), None)
        if index is None:
            return False
        lower = max(0, index - 28)
        for setup_index in range(index - 1, lower - 1, -1):
            setup = self.insns[setup_index]
            operands = split_ops(setup.op_str)
            if setup.mnemonic != 'lea' or len(operands) != 2 or \
                    subreg64(operands[0]) not in self.abi.arg_regs:
                continue
            memory = parse_mem(operands[1])
            if not memory or memory[0] != base or memory[2]:
                continue
            array_start = memory[1]
            for call in self.insns[index:index + 18]:
                if call.mnemonic != 'call':
                    continue
                helper = None
                if call.op_str.startswith('0x'):
                    try:
                        helper = self.res.resolve(
                            int(call.op_str, 16))[1]
                    except Exception:
                        helper = None
                match = re.search(r'ARGS(\d+)', str(helper or ''))
                if match:
                    count = int(match.group(1))
                    return array_start <= off < array_start + 8 * count
                break
        return False

    def _is_refhold_store(self, dst, address):
        """A callee-saved copy used only to decref a call-array argument."""
        index = next((i for i, item in enumerate(self.insns)
                      if item.address == address), None)
        if index is None:
            return False
        copied_to_args = False
        call_index = None
        for pos in range(index + 1, min(len(self.insns), index + 32)):
            item = self.insns[pos]
            operands = split_ops(item.op_str)
            if item.mnemonic == 'mov' and len(operands) == 2 and \
                    subreg64(operands[1]) == self.abi.ret_reg:
                memory = parse_mem(operands[0])
                if memory and memory[0] and self._is_argument_array_slot(
                        item.address, memory[0], memory[1]):
                    copied_to_args = True
            if item.mnemonic == 'call':
                call_index = pos
                break
        if not copied_to_args or call_index is None:
            return False
        for item in self.insns[call_index + 1:call_index + 10]:
            operands = split_ops(item.op_str)
            memory = parse_mem(operands[0]) if operands else None
            if item.mnemonic == 'sub' and memory and memory[0] == dst and \
                    memory[1] == 0 and len(operands) == 2 and \
                    is_imm(operands[1]) == 1:
                return True
        return False

    def _note_store(self, dst, src_sym, ins, src_reg=None):
        """Store di un producer in locazione persistente (regs callee-saved).
        Assegnamento Python SOLO se la sorgente è il registro di ritorno
        (valore fresco da call); gli store da altri registri sono spill
        del compilatore (tracciati nello stato, senza statement)."""
        if src_sym is None or src_sym.op in (
                'imm', 'tstate', 'pars', 'frame', 'self', 'excstate',
                'gslot', 'gaddr', 'modconsts', 'par', 'loc', 'global',
                'none', 'stackaddr'):
            return
        d64 = subreg64(dst)
        if d64 in self.CALLEE_SAVED or \
                (self.img.fmt == 'pe' and d64 in ('rsi', 'rdi')):
            loc = ('reg', d64)
            self.symbol_locations[self._svkey_of(src_sym)].add(loc)
            sr64 = subreg64(src_reg) if src_reg else None
            if sr64 == self.abi.ret_reg:
                if self._is_refhold_store(d64, ins.address):
                    return
                if not hasattr(self, 'var_of_sym'):
                    self.var_of_sym = {}
                self.var_of_sym[id(src_sym)] = loc
                self._cur_block.ops.append(NdxOp('store', a=loc, b=src_sym,
                                              va=ins.address))
                if not hasattr(self, 'store_sites'):
                    self.store_sites = []
                self.store_sites.append((self._cur_block.start, loc, src_sym))

    def _note_slot_store(self, base, off, src_sym, ins, src_reg=None):
        # costruzione MANUALE di un seq-iteratore (Nuitka inline
        # ``for v in SEQ:`` senza chiamare PySeqIter_New):
        # ``mov [obj+8], PySeqIter_Type`` poi ``mov [obj+24], SEQ``.
        # Il simbolo base DIVENTA iter(SEQ): il dispatch tp_iternext
        # e la for-detection vedono l'iterabile vero.
        if isinstance(src_sym, NdxSV) and src_sym.op == 'api_symbol' and \
                str(getattr(src_sym, 'a', '')) in ('PySeqIter_Type',
                                                   'PyCallIter_Type') and \
                off == getattr(self.abi, 'ob_type', 8):
            base_sym = self._reg(base)
            if base_sym is not None:
                if not hasattr(self, '_pending_seqiter'):
                    self._pending_seqiter = {}
                self._pending_seqiter[id(base_sym)] = base_sym
            return
        if off == 24 and isinstance(src_sym, NdxSV) and \
                src_sym.op in ('const', 'tuple_build', 'list_build',
                               'list_empty', 'call', 'var', 'loc',
                               'par', 'dict_build') and \
                getattr(self, '_pending_seqiter', {}):
            base_sym = self._reg(base)
            if base_sym is not None and \
                    id(base_sym) in self._pending_seqiter:
                del self._pending_seqiter[id(base_sym)]
                self._setreg(base, ndx_k('iter', src_sym))
                return
        if src_sym is None or src_sym.op in (
                'imm', 'tstate', 'pars', 'frame', 'self', 'excstate',
                'gslot', 'gaddr', 'modconsts', 'par', 'loc', 'global',
                'none', 'stackaddr'):
            return
        # Win64 vectorcall/kw-split passes the immutable tuple of keyword
        # names in shadow-space +0x20.  Keep it in ``slot_syms`` for call
        # reconstruction, but never materialise that ABI transport slot as a
        # Python local assignment.
        if self.img.fmt == 'pe' and base == 'rsp' and off == 0x20 and \
                src_sym.op == 'const' and isinstance(src_sym.a, tuple) and \
                all(isinstance(name, str) for name in src_sym.a):
            return
        if self._is_argument_array_slot(ins.address, base, off):
            return
        sr64 = subreg64(src_reg) if src_reg else None
        # V100 FIX: MSVC spilla i valori Python VERI nei callee-saved
        # (``mov rbx, rax`` … ``mov [rbp-0x18], rbx``) prima di scriverli
        # nello slot della variabile.  La vecchia regola accettava SOLO il
        # registro di ritorno ABI, quindi ogni assegnamento spillato da un
        # callee-saved (le inizializzazioni ``x = 0``/``x = costante`` su
        # small-int immortals) spariva: il naming lazy delle locali slittava
        # di conseguenza (la variabile del for rubava il nome della prima
        # locale non assegnata).  Gli spill PRIMITIVI trasportano simboli
        # None/imm/machinery, gia' filtrati sopra: un simbolo Python ricco
        # in un callee-saved e' un assegnamento reale.
        _persistent = set(self.CALLEE_SAVED)
        if self.img.fmt == 'pe':
            _persistent.update(('rsi', 'rdi'))
        if sr64 != self.abi.ret_reg and sr64 not in _persistent:
            return      # registro volatile non-result: spill del compilatore
        loc = ('mem', base, off)
        if not hasattr(self, 'var_of_sym'):
            self.var_of_sym = {}
        if id(src_sym) in self.var_of_sym:
            return
        self.var_of_sym[id(src_sym)] = loc
        self._cur_block.ops.append(NdxOp('store', a=loc, b=src_sym,
                                      va=ins.address))
        if not hasattr(self, 'store_sites'):
            self.store_sites = []
        self.store_sites.append((self._cur_block.start, loc, src_sym))

    def _load_mem(self, dst, base, off, ins, mem=None):
        # rip-relativo → slot costanti / globali
        if base == 'rip':
            t = rip_target(ins)
            self._load_rip(dst, t, ins)
            return
        base_sym = self._reg(base)
        # A proven stack address is not a PyObject, even when its displacement
        # happens to equal ob_type or ob_size. Resolve frame memory first.
        if isinstance(base_sym, NdxSV) and base_sym.op == 'stack_base' and not (mem and mem[2]):
            transport = self.slot_syms.get(('entry_argspill', base_sym.a + off))
            self._setreg(dst, transport if transport is not None else self.slot_syms.get((base, off)))
            return
        if isinstance(base_sym, NdxSV):
            if base_sym.op == 'moddict' and off == 0x20 and \
                    not (mem and mem[2]) and self.img.fmt == 'pe' and \
                    self.py_version == (3, 11):
                self._setreg(dst, ndx_k('dict_keys', base_sym))
                return
            if base_sym.op == 'dict_keys' and off == 9 and not (mem and mem[2]):
                self._setreg(dst, ndx_k('dict_index_log', base_sym))
                return
            if base_sym.op == 'dict_entries' and mem and mem[2]:
                index = self._reg(mem[2])
                if isinstance(index, NdxSV) and index.op == 'dict_index' and \
                        _sv_eq(base_sym.a, index.a) and \
                        index.c * mem[3] == 16 and off == 0x28:
                    self._setreg(dst, ndx_k('global', index.b))
                    return
        # PE imports for exception classes are pointer-valued data symbols:
        # ``mov slot, [rip+IAT]; mov exc, [slot]``.  The second dereference is
        # the Python exception class itself, not an opaque object field.
        if base_sym is not None and base_sym.op == 'api_symbol' and \
                isinstance(base_sym.a, str) and \
                base_sym.a.startswith('PyExc_') and off == 0:
            self._setreg(dst, ndx_k('global', base_sym.a[6:]))
            return
        # --- generatore: letture delle closure-cell ---
        # m_closure[i] via [gen+OFFi] → cellref(i); il valore della cella
        # è ob_ref (offset 0x10 di Nuitka_CellObject, layout verificato su
        # compiled_cell.h). I nomi arrivano dai freevars del code object
        # (o _cell{i} come fallback semantico).
        if self.gen_mode:
            proven_generator_base = (
                base_sym is not None and base_sym.op == 'genobj') or (
                base in self._generator_object_alias_registers())
            if proven_generator_base:
                ci = self.gen_closure_map.get(off)
                if ci is not None:
                    self._setreg(dst, ndx_k('cellref', ci))
                    return
            if base_sym is not None and base_sym.op == 'cellref' and                     off == 0x10:
                name = self.gen_closure_names.get(base_sym.a,
                                                  f'_cell{base_sym.a}')
                self._setreg(dst, ndx_k('var', name))
                return
        # --- closure cells of a plain def with freevars ---
        # The second implementation parameter carries the enclosing
        # function's closure state as fixed cell slots (build-specific
        # base offset, one slot per co_freevars entry).  A slot is proven
        # to be a cell when its loaded pointer is dereferenced at the
        # Nuitka_CellObject.ob_ref offset (0x10); the slot's rank among the
        # proven slots selects the co_freevars name.  Calibration
        # accumulates over the repeated symbolic passes; unresolved paths
        # keep the historical None verdict instead of leaking internals.
        if not self.gen_mode and base_sym is not None:
            if base_sym.op == 'closure_array' and off >= 0 and \
                    off % 8 == 0:
                if len(getattr(self, 'closure_names', {})) == 1:
                    # Single freevar: the one slot is THE cell; resolve
                    # immediately (no calibration pass needed).
                    name = next(iter(self.closure_names.values()))
                    self._setreg(dst, ndx_k('cellref', 0))
                    self._closure_cell_offs.add(off)
                    return
                self._closure_offs.add(off)
                if off in self._closure_cell_offs:
                    ci = sorted(self._closure_cell_offs).index(off)
                    name = getattr(self, 'closure_names', {}).get(ci)
                    self._setreg(dst, ndx_k('var', name) if name else None)
                else:
                    self._setreg(dst, ndx_k('closure_cell', off))
                return
            if base_sym.op == 'closure_cell':
                if off == 0x10:
                    self._closure_cell_offs.add(base_sym.a)
                    ci = sorted(self._closure_cell_offs).index(base_sym.a)
                    name = getattr(self, 'closure_names', {}).get(ci)
                    self._setreg(dst, ndx_k('var', name) if name else None)
                else:
                    self._setreg(dst, None)
                return
            if base_sym.op == 'cellref' and off == 0x10:
                profile = ndx_binary_abi(self.img)
                profile.observe_layout('Nuitka_CellObject.ob_ref', off,
                    {'kind': 'closure_argument_dereference', 'function': self.va,
                     'call_site': ins.address})
                if len(self.closure_names) == 1 and len(self._closure_cell_offs) == 1:
                    profile.observe_layout('Nuitka_FunctionObject.m_closure',
                        next(iter(self._closure_cell_offs)),
                        {'kind': 'single_freevar_function_slot', 'function': self.va,
                         'call_site': ins.address})
                name = getattr(self, 'closure_names', {}).get(base_sym.a)
                self._setreg(dst, ndx_k('var', name) if name else None)
                return
        # pars[i].  MSVC commonly preserves ``python_pars`` in a callee-saved
        # register, so retain its symbolic provenance across that move.
        if base_sym is not None and base_sym.op == 'pars':
            idx = off // 8
            self._setreg(dst, ndx_k('par', idx))
            return
        # Direct element load from an exact tuple/list constant.  CPython's
        # 64-bit PyVarObject header is 0x18 bytes and tuple payload slots are
        # consecutive PyObject pointers.  Nuitka uses this form for small
        # positional call vectors (e.g. ``tuple_const->ob_item[0]``).
        if base_sym is not None and base_sym.op == 'const' and \
                isinstance(base_sym.a, (tuple, list)) and off >= 0x18 and \
                (off - 0x18) % 8 == 0:
            index = (off - 0x18) // 8
            if 0 <= index < len(base_sym.a):
                self._setreg(dst, ndx_k('const', base_sym.a[index]))
                return
        # V100: UNPACK_SEQUENCE inline su tupla RUNTIME — Nuitka, dopo
        # ``PySequence_Check``/``PyTuple_Check`` sul valore, carica gli
        # item direttamente: ``mov reg, [val + 0x18 + 8*i]`` (payload
        # inline del PyTupleObject, layout identico al caso costante).
        # La base qui è un valore qualunque: la variabile di loop di
        # ``for row in X: t, o, c = row`` (op ``next``), il risultato di
        # una call decomposta, ecc. L'elemento è ``base[i]``.
        if base_sym is not None and base_sym.op in (
                'next', 'unpack', 'stopiter_value', 'call', 'kwcall',
                'mcall', 'sub') and off >= 0x18 and (off - 0x18) % 8 == 0:
            index = (off - 0x18) // 8
            if 0 <= index < 32:
                self._setreg(dst, ndx_k('sub', base_sym,
                                        ndx_k('imm', index)))
                return
        # Exact tuple/list templates expose their element count through
        # PyVarObject.ob_size.  Preserve the originating sequence so an
        # outlined MAKE_TUPLE_EMPTY followed by Nuitka's descriptor-driven
        # deep-copy loop can be represented as the same literal vector.
        if base_sym is not None and base_sym.op == 'const' and \
                isinstance(base_sym.a, (tuple, list)) and off == 0x10:
            self._setreg(dst, ndx_k('const_size', base_sym))
            return
        # PE data imports are loaded through the IAT and may then be
        # dereferenced once (e.g. ``PyExc_ValueError``).  Preserve the proven
        # Python/API object across that compiler-level indirection.
        if off == 0 and base_sym is not None and base_sym.op in (
                'global', 'api_symbol'):
            self._setreg(dst, base_sym)
            return
        # PyListObject.ob_item is a separately allocated PyObject** array.
        # Preserve the allocation identity across ``items = list->ob_item``
        # so the following direct stores can populate a literal list.  Tuple
        # payloads are inline and continue through the existing +0x18 path.
        if off == 0x18 and base_sym is not None and \
                base_sym.op in ('list_build', 'list_empty'):
            self._setreg(dst, ndx_k(
                'container_items', base_sym, n=base_sym.n))
            return
        # PyLong's public variable-size header stores its signed digit count
        # (or the equivalent compact tag on newer CPython) at +0x10.  Keep the
        # originating Python object attached to this native field; it becomes
        # semantic only when _exec_test proves the complete size+digit compare
        # template for a small integer literal.
        if off == 0x10 and base_sym is not None and base_sym.op not in (
                'tstate', 'frame', 'excstate', 'mod', 'pars', 'genobj'):
            self._setreg(dst, ndx_k('long_tag', base_sym))
            return
        # ob_type di un oggetto Python → type_of (per dispatch tp_*)
        if off == self.abi.ob_type and base_sym is not None and \
                base_sym.op not in ('tstate', 'frame', 'excstate', 'mod',
                                    'pars'):
            self._setreg(dst, ndx_k('type_of', base_sym))
            return
        # PyTypeObject has separate adjacent slots for creating an
        # iterator and advancing it. Treating tp_iter as an alternative
        # tp_iternext offset consumes a value when Python only calls iter().
        if base_sym is not None and base_sym.op == 'type_of':
            if off == self.abi.tp_iter:
                self._setreg(dst, ndx_k('tpiter', base_sym.a))
                return
            if off == self.abi.tp_iternext:
                self._setreg(dst, ndx_k('tpiternext', base_sym.a))
                return
        # sq_length and mp_length are the first entry in their respective
        # protocol tables.  Carry the originating object to the indirect
        # call; the native ssize result is boxed later by CPython.
        if off == 0 and base_sym is not None and \
                base_sym.op == 'tp_slot' and base_sym.a in (0x68, 0x70):
            self._setreg(dst, ndx_k('len_slot', base_sym.b))
            return
        # Binary entries of CPython's public PyNumberMethods ABI reached via
        # ``PyTypeObject.tp_as_number`` (offset 0x60 on the supported 64-bit
        # layouts).  This covers both the ordinary and in-place dispatchers;
        # unary/conversion entries are intentionally absent.
        number_binary_slots = {
            0x00: ('+', False), 0x08: ('-', False),
            0x10: ('*', False), 0x18: ('%', False),
            0x28: ('**', False),
            0x58: ('<<', False), 0x60: ('>>', False),
            0x68: ('&', False), 0x70: ('^', False),
            0x78: ('|', False),
            0x98: ('+', True), 0xa0: ('-', True),
            0xa8: ('*', True), 0xb0: ('%', True),
            0xb8: ('**', True),
            0xc0: ('<<', True), 0xc8: ('>>', True),
            0xd0: ('&', True), 0xd8: ('^', True),
            0xe0: ('|', True),
            0xe8: ('//', False), 0xf0: ('/', False),
            0xf8: ('//', True), 0x100: ('/', True),
            0x110: ('@', False), 0x118: ('@', True),
        }
        if off in number_binary_slots and base_sym is not None and \
                base_sym.op == 'tp_slot' and base_sym.a == 0x60:
            operator, inplace = number_binary_slots[off]
            self._setreg(dst, ndx_k(
                'binary_slot', operator, base_sym.b,
                n='inplace' if inplace else None))
            return
        if off == 0x48 and base_sym is not None and \
                base_sym.op == 'tp_slot' and base_sym.a == 0x60:
            # nb_bool: tp_as_number->nb_bool — la chiamata produce la
            # verita' Python dell'oggetto (``bool(T)``), testata subito
            # dopo come condizione (lowering di ``if X`` / ``if not X``).
            self._setreg(dst, ndx_k('bool_slot', base_sym.b))
            return
        # fast-path numerico: `[PyLong_Type + 0x60]` — tp_as_number di un
        # TIPO COSTANTE (dal check `ob_type == PyLong_Type` del ramo
        # veloce). Il tipo-noto vale quanto type_of per il dispatch slot.
        if off == 0x60 and base_sym is not None and \
                base_sym.op in ('api_symbol', 'global', 'gslot') and \
                isinstance(base_sym.a, str) and \
                base_sym.a.endswith('_Type'):
            self._setreg(dst, ndx_k('tp_slot', 0x60, base_sym))
            return
        # altro slot di tipo (tp_call/tp_hash/tp_dealloc...) → marker
        if 0x10 <= off <= 0x400 and base_sym is not None and \
                base_sym.op == 'type_of':
            self._setreg(dst, ndx_k('tp_slot', off, base_sym.a))
            return
        # frame internals / tstate internals / exception state → noise
        if base_sym is not None and base_sym.op in ('tstate', 'frame',
                                                    'excstate', 'mod'):
            self._setreg(dst, None)
            return
        # slot stack
        key = (base, off)
        if key in self.slot_syms:
            self._setreg(dst, self.slot_syms[key])
            return
        # caricamento campo oggetto Python (ob_refcnt/...) → noise
        self._setreg(dst, None)

    def _store_slot(self, base, off, src_sym):
        origin = self._reg(base)
        if isinstance(origin, NdxSV) and origin.op == 'stack_base':
            # Entry arguments can be homed before PUSH/SUB establish RBP.
            # Preserve their absolute stack byte, and invalidate it on reuse.
            transport = src_sym if isinstance(src_sym, NdxSV) and src_sym.op in (
                'tstate', 'closure_array', 'pars', 'self', 'genobj', 'loader_entry') else None
            self.slot_syms[('entry_argspill', origin.a + off)] = transport
        if base in ('rsp', 'rbp'):
            other = 'rbp' if base == 'rsp' else 'rsp'
            left, right = self._reg(base), self._reg(other)
            if isinstance(left, NdxSV) and isinstance(right, NdxSV) and \
                    left.op == right.op == 'stack_base':
                # Two addressing forms of the very same stack byte.  This
                # matters for large frames where adjacent vector elements
                # straddle the compiler's rsp/rbp displacement boundary.
                self.slot_syms[(other, left.a + off - right.a)] = src_sym
        self.slot_syms[(base, off)] = src_sym
        if isinstance(src_sym, NdxSV):
            self.symbol_locations[self._svkey_of(src_sym)].add(('mem', base, off))
        base_sym = self._reg(base)
        if isinstance(base_sym, NdxSV) and base_sym.op == 'iter' and \
                base_sym.a is None and off == 0x18 and isinstance(src_sym, NdxSV):
            # A proven PySeqIter allocation stores its input sequence at
            # it_seq; preserve that source through the sequence fallback.
            base_sym.a = src_sym
        proven_generator_base = (
            isinstance(base_sym, NdxSV) and base_sym.op == 'genobj') or (
            self.gen_mode and
            base in self._generator_object_alias_registers())
        if self.gen_mode and proven_generator_base and \
                isinstance(src_sym, NdxSV) and off != self.gen_idx_off:
            # Official Nuitka generator/coroutine templates materialise a
            # Python ``return value`` as ``context->m_returned = value`` and
            # then return C NULL.  Record all semantic context stores here;
            # _finish_block accepts one only when it occurs in that exact RET
            # epilogue.  This avoids hard-coding m_returned's ABI offset while
            # excluding the separately discovered yield-index field.
            non_values = {
                'tstate', 'frame', 'excstate', 'pars', 'self', 'modconsts',
                'genobj', 'codeobj', 'gaddr', 'api_symbol', 'loader_entry',
            }
            if src_sym.op not in non_values:
                self.gen_result_stores[self._cur_block.start] = (
                    getattr(self, '_cur_insn_addr', self._cur_block.end),
                    off, src_sym)
        origin = (base_sym.n if base_sym is not None and
                  base_sym.n is not None else
                  self.container_reg_origins.get(base))
        if base_sym is not None and base_sym.op == 'container_items' and \
                off >= 0 and off % 8 == 0:
            container = base_sym.a
            origin = base_sym.n
            values = self.container_values.get(
                origin, getattr(container, 'b', None))
            index = off // 8
            if isinstance(values, list) and 0 <= index < len(values):
                values[index] = src_sym
                if origin is not None:
                    self.container_values[origin] = values
                if isinstance(container, NdxSV):
                    container.b = values
            return
        if base_sym is not None and base_sym.op in (
                'tuple_build', 'list_build', 'loc') and \
                off >= 0x18 and (off - 0x18) % 8 == 0 and \
                (isinstance(base_sym.b, list) or
                 origin in self.container_values):
            values = self.container_values.get(origin, base_sym.b)
            index = (off - 0x18) // 8
            if 0 <= index < len(values):
                values[index] = src_sym
                if origin is not None:
                    self.container_values[origin] = values
                if base_sym.op in ('tuple_build', 'list_build'):
                    base_sym.b = values

    def _generator_object_alias_registers(self):
        """Return stable prologue aliases of the resumer object argument.

        Optimised resumers preserve their generator/coroutine object in a
        callee-saved register.  Long exception-cleanup joins may turn that
        register into an unresolved symbolic phi even though its machine
        provenance is invariant.  Prove aliases only in the straight-line
        entry prologue, before the first call, and retain only registers whose
        calling convention guarantees stability for the whole function.
        """
        cached = getattr(self, '_generator_alias_register_cache', None)
        if cached is not None:
            return cached
        if not self.gen_mode:
            self._generator_alias_register_cache = frozenset()
            return self._generator_alias_register_cache
        argument = 'rdx' if self.img.fmt == 'pe' else 'rsi'
        aliases = {argument}
        for item in self.insns[:96]:
            if item.mnemonic == 'call':
                break
            operands = split_ops(item.op_str)
            if not operands:
                continue
            destination = subreg64(operands[0])
            if destination is None:
                continue
            if item.mnemonic in ('mov', 'movabs') and len(operands) == 2:
                source = subreg64(operands[1])
                if source in aliases:
                    aliases.add(destination)
                    continue
            if item.mnemonic not in ('cmp', 'test', 'push'):
                aliases.discard(destination)
        persistent = set(self.CALLEE_SAVED)
        if self.img.fmt == 'pe':
            persistent.update(('rsi', 'rdi'))
        self._generator_alias_register_cache = frozenset(
            aliases.intersection(persistent))
        return self._generator_alias_register_cache

    def _load_rip(self, dst, t, ins, addr=False):
        if t is None:
            self._setreg(dst, None)
            return
        imported = self.img.imports.get(t)
        if imported:
            if imported.startswith('PyExc_'):
                self._setreg(dst, ndx_k('global', imported[6:]))
            elif imported in ('Py_None', '_Py_NoneStruct', 'Py_NoneStruct'):
                self._setreg(dst, ndx_k('none'))
            elif imported in ('Py_True', '_Py_TrueStruct'):
                self._setreg(dst, ndx_k('const', True))
            elif imported in ('Py_False', '_Py_FalseStruct'):
                self._setreg(dst, ndx_k('const', False))
            else:
                self._setreg(dst, ndx_k('api_symbol', imported))
            return
        # Slot del dizionario modulo su build SENZA simboli (MinGW/ELF
        # stripped): mca.analyze() lo ha mappato in moduledict_slots dai
        # mov rip relativi negli argomenti dei binding del modulecode.
        # DEVE precedere const_for_slot: lo slot può finire anche nella
        # mappa delle costanti (il dict è un PyObject), ma l'evidenza del
        # bind è più forte e abilita il recovery degli import/assegnazioni.
        _mds = getattr(self.res, 'moduledict_slots', None)
        if _mds and t in _mds:
            self._setreg(dst, ndx_k('moddict', t))
            return
        if not addr and t in getattr(self, 'dict_index_slots', {}):
            self._setreg(dst, self.dict_index_slots[t])
            return
        # Cached VALUE slot di un accessor inline di variabile di modulo
        # (template ufficiale Nuitka: fast-path ``result = cache_value``
        # guidato dal confronto di dk_version).  La mappa slot→nome è
        # provata dallo store del slow path dello stesso accessor.
        _gsv = self._global_value_slots()
        if t in _gsv:
            value = ndx_k('global', _gsv[t])
            self._setreg(dst, value)
            self.symbol_locations.setdefault(self._svkey_of(value), set()).add(
                ('reg', subreg64(dst)))
            return
        # costante mod_consts
        if self.mca is not None:
            val, which = self.mca.const_for_slot(t)
            if val is not None:
                value = ndx_k('const', val)
                self._setreg(dst, value)
                register = subreg64(dst)
                persistent = set(self.CALLEE_SAVED)
                if self.img.fmt == 'pe':
                    persistent.update(('rsi', 'rdi'))
                if not addr and register in persistent:
                    self.direct_constant_loads[ins.address] = (
                        self._cur_block.start, ('reg', register), value)
                    self.symbol_locations[self._svkey_of(value)].add(
                        ('reg', register))
                return
        # modulo
        if self.mca is not None and t == getattr(self.mca, 'mod_consts_base', None):
            self._setreg(dst, ndx_k('modconsts'))
            return
        # cache frame slot
        if t in self.frame_cache_slots:
            self._setreg(dst, ndx_k('frame'))
            return
        # simbolo noto?
        nm = self.img.symbols.get(t)
        if nm in ('Py_None', '_Py_NoneStruct', 'Py_NoneStruct'):
            self._setreg(dst, ndx_k('none'))
            return
        if nm in ('Py_True', '_Py_TrueStruct', 'Py_False',
                  '_Py_FalseStruct'):
            self._setreg(dst, ndx_k('const', nm.startswith(('Py_True',
                                                         '_Py_True'))))
            return
        if nm:
            if nm.startswith('module_') and self.mca and \
                    nm == 'module_' + self.mca.module.name:
                self._setreg(dst, ndx_k('mod', self.mca.module.name))
                return
            if nm.startswith('moduledict_'):
                self._setreg(dst, ndx_k('moddict'))
                return
            if nm.startswith('code_objects_'):
                self._setreg(dst, ndx_k('codeobj', nm))
                return
        self._setreg(dst, ndx_k('gslot', t) if not addr else ndx_k('gaddr', t))

    # ---- call ----
    def _parameter_arg_before(self, address, register):
        """Recover a call argument from a prologue ``python_pars[i]`` load.

        Callee-saved aliases survive intervening helper calls.  The terminal
        load is accepted only before the function's first call, while the ABI
        parameter-array register is still the entry value.
        """
        index = next((i for i, item in enumerate(self.insns)
                      if item.address == address), None)
        if index is None or not getattr(self, 'pars_reg', None):
            return None
        first_call = next((item.address for item in self.insns
                           if item.mnemonic == 'call'), address)
        if not hasattr(self, '_entry_parameter_locations'):
            parameter_registers = {
                getattr(self, 'pars_reg', None): ('pars', None)}
            parameter_locations = {}
            for item in self.insns:
                if item.address >= first_call:
                    break
                operands = split_ops(item.op_str)
                if item.mnemonic != 'mov' or len(operands) != 2:
                    continue
                destination_register = subreg64(operands[0])
                source_register = subreg64(operands[1])
                source_memory = parse_mem(operands[1])
                if destination_register:
                    value = parameter_registers.get(source_register)
                    if source_memory and not source_memory[2]:
                        base_value = parameter_registers.get(source_memory[0])
                        if base_value and base_value[0] == 'pars' and \
                                source_memory[1] >= 0 and \
                                source_memory[1] % 8 == 0:
                            value = ('par', source_memory[1] // 8)
                        else:
                            value = parameter_locations.get(
                                ('mem', source_memory[0], source_memory[1]))
                    if value is None:
                        parameter_registers.pop(destination_register, None)
                    else:
                        parameter_registers[destination_register] = value
                    continue
                destination_memory = parse_mem(operands[0])
                if destination_memory and not destination_memory[2] and \
                        source_register in parameter_registers:
                    value = parameter_registers[source_register]
                    if value and value[0] == 'par':
                        parameter_locations[
                            ('mem', destination_memory[0],
                             destination_memory[1])] = value
            self._entry_parameter_locations = parameter_locations
        tracked = subreg64(register)
        for item in reversed(self.insns[:index]):
            operands = split_ops(item.op_str)
            if len(operands) != 2 or subreg64(operands[0]) != tracked:
                continue
            if item.mnemonic == 'mov':
                source_reg = subreg64(operands[1])
                if source_reg:
                    tracked = source_reg
                    continue
                memory = parse_mem(operands[1])
                if memory and item.address < first_call and \
                        memory[0] == self.pars_reg and not memory[2] and \
                        memory[1] >= 0 and memory[1] % 8 == 0:
                    parameter_index = memory[1] // 8
                    if parameter_index < self.argcount:
                        return ndx_k('par', parameter_index)
            return None
        return None

    def _consume_pending_method(self, ins):
        """Se una _PyType_Lookup è pendente e il suo valore è vivo in un
        registro, la prossima chiamata dispatch (diretta/indiretta) è la
        method call ``obj.name(args)``: emetti il mcall, rimuovi le ops
        della lookup (calc + store) e ritorna True."""
        pending = getattr(self, '_pending_method', None)
        if pending is None:
            return False
        fn_sv = pending[2]
        creg = next((r for r, s in self.regs.items() if s is fn_sv), None)
        if creg is None:
            return False
        obj = pending[0]
        cargs = []
        for r in self.abi.arg_regs:
            s = self._reg(r)
            if s is None or s is fn_sv or s.op in ('tstate', 'imm',
                                                   'stackaddr', 'gslot',
                                                   'frame', 'tp_slot'):
                continue
            # il receiver (e il suo tipo) viaggia sempre col metodo
            # cercato: non è un argomento sorgente
            if obj is not None and (s is obj or (
                    s.op == 'type_of' and s.a is obj)):
                continue
            cargs.append(s)
        try:
            self._cur_block.ops[:] = [
                o for o in self._cur_block.ops
                if not ((o.kind == 'calc' and o.a is fn_sv) or
                        (o.kind == 'store' and o.b is fn_sv))]
        except Exception:
            pass
        self._pending_method = None
        ret = ndx_k('mcall', pending[0], ndx_k('const', pending[1]), cargs)
        self._setreg(self.abi.ret_reg, ret)
        self._cur_block.ops.append(NdxOp('calc', a=ret, va=ins.address))
        self._last_call = (ins, ret, 'lookup_dispatch', None)
        return True

    def _exec_call(self, ins):
        op = ins.op_str
        if not op.startswith('0x'):
            # PE imports are normally invoked as
            # ``call qword ptr [rip + IAT_SLOT]``.  They are semantically
            # direct CPython C-API calls even though the machine instruction
            # is indirect; resolve the IAT slot before considering tp_* calls.
            if 'rip' in op:
                slot = rip_target(ins)
                name = self.img.imports.get(slot) if slot is not None else None
                if name:
                    sem = PY_API_SEMANTICS.get(name)
                    args = [self._reg(r) for r in self.abi.arg_regs]
                    ret = self._semantic_call(name, sem, args, ins)
                    if isinstance(ret, NdxSV) and \
                            ret.n is None and ret.op in ('call', 'kwcall', 'mcall', 'apicall'):
                        ret.n = ins.address
                    self._setreg(self.abi.ret_reg, ret)
                    self._last_call = (ins, ret, name, sem)
                    if ret is not None and ret.op not in (
                            'frame', 'excstate', 'codeobj_new',
                            'gslot', 'gaddr', 'dict_merge'):
                        self._cur_block.ops.append(NdxOp(
                            'calc', a=ret, va=ins.address))
                    for reg in self.abi.caller_saved:
                        if reg != self.abi.ret_reg:
                            self.regs[reg] = None
                    return
            # ``call [spill]`` is the same protocol dispatch after MSVC has
            # saved the selected slot pointer in a frame/stack location.
            call_memory = parse_mem(op)
            # dispatch tp_* inline COMPRESSO: ``call qword ptr [T+off]``
            # dove T è il registro-ob_type (nessun caricamento del campo in
            # un registro intermedio). É la forma dei loop generatori.
            if call_memory and call_memory[0] and not call_memory[2]:
                t_sym = self._reg(call_memory[0])
                # ``call [reg]`` su un valore Python vivo nel registro
                # (vectorcall del callable senza displacement): stessa
                # semantica del reg_dispatch qui sotto — il callable è
                # il valore del registro, inclusa la consumazione della
                # _PyType_Lookup pendente (protocollo with / metodi).
                if t_sym is not None and isinstance(t_sym, NdxSV) and \
                        t_sym.op in ('getattr', 'mcall', 'call', 'global',
                                     'var', 'par', 'super', 'loc',
                                     'cellref', 'sub'):
                    if self._consume_pending_method(ins):
                        return
                    cargs = []
                    for r in self.abi.arg_regs[1:]:
                        s = self._reg(r)
                        if s is not None:
                            cargs.append(s)
                    ret = ndx_k('call', t_sym, cargs)
                    self._setreg(self.abi.ret_reg, ret)
                    self._cur_block.ops.append(NdxOp('calc', a=ret,
                                                     va=ins.address))
                    self._last_call = (ins, ret, 'reg_dispatch', None)
                    return
                if t_sym is not None and t_sym.op == 'tp_slot' and                         t_sym.a == 0x60:
                    # call diretto `[tp_as_number+SLOT]`: il dispatcher
                    # binario inline (nb_add/nb_remainder/...). L'operatore
                    # dalla tabella PyNumberMethods; gli operandi sono gli
                    # argomenti ABI della chiamata.
                    NBS = {0x00: '+', 0x08: '-', 0x10: '*', 0x18: '%',
                           0x28: '**', 0x58: '<<', 0x60: '>>', 0x68: '&',
                           0x70: '^', 0x78: '|', 0x98: '+', 0xa0: '-',
                           0xa8: '*', 0xb0: '%', 0xb8: '**', 0xc0: '<<',
                           0xc8: '>>', 0xd0: '&', 0xd8: '^', 0xe0: '|',
                           0xe8: '//', 0xf0: '/', 0xf8: '//', 0x100: '/',
                           0x110: '@', 0x118: '@'}
                    if call_memory[1] in NBS:
                        left = self._reg(self.abi.arg_regs[0])
                        right = self._reg(self.abi.arg_regs[1])
                        if left is None:
                            left = self._symbol_for_register_before(
                                ins.address, self.abi.arg_regs[0])
                        if right is None:
                            right = self._symbol_for_register_before(
                                ins.address, self.abi.arg_regs[1])
                        value = ndx_k('binop', NBS[call_memory[1]],
                                      t_sym.b, right)
                        if left is not None and right is not None and                                 left is not t_sym.b:
                            value = ndx_k('binop', NBS[call_memory[1]],
                                          left, right)
                        self._setreg(self.abi.ret_reg, value)
                        self._cur_block.ops.append(NdxOp(
                            'calc', a=value, va=ins.address))
                        self._last_call = (ins, value, 'NUMBER_SLOT', None)
                        return
                if t_sym is not None and t_sym.op == 'type_of':
                    if call_memory[1] == self.abi.tp_iter:
                        iterator = ndx_k('iter', t_sym.a)
                        self._setreg(self.abi.ret_reg, iterator)
                        self._cur_block.ops.append(NdxOp('calc', a=iterator, va=ins.address))
                        self._last_call = (ins, iterator, 'MAKE_ITERATOR', ('make_iterator', 1))
                        return
                    if call_memory[1] == self.abi.tp_iternext:
                        nxt = ndx_k('next', t_sym.a, n=ins.address)
                        self._setreg(self.abi.ret_reg, nxt)
                        self._cur_block.ops.append(NdxOp(
                            'calc', a=nxt, va=ins.address))
                        self._last_call = (ins, nxt, 'ITERATOR_NEXT', None)
                        return
                    if call_memory[1] == 0xc8:
                        # tp_richcompare inline compresso: l'operatore è
                        # il 3° argomento (r8d) con l'enum CPython
                        # Py_LT..Py_GE (0..5)
                        left = self._reg(self.abi.arg_regs[0])
                        right = self._reg(self.abi.arg_regs[1])
                        opid_sym = self._reg(self.abi.arg_regs[2])
                        opid = getattr(opid_sym, 'a', None)                             if opid_sym is not None and                             getattr(opid_sym, 'op', None) == 'imm' else None
                        OPS = {0: 'lt', 1: 'le', 2: 'eq', 3: 'ne',
                               4: 'gt', 5: 'ge'}
                        if opid in OPS and left is not None and                                 right is not None:
                            csym = ndx_k('cmp', OPS[opid], left, right)
                            self._setreg(self.abi.ret_reg, csym)
                            self._cur_block.ops.append(NdxOp(
                                'calc', a=csym, va=ins.address))
                            self._last_call = (ins, csym,
                                               'RICH_COMPARE', None)
                            return
                    # gli altri slot tp_* proseguono nel path generico
            spilled_call = None
            if call_memory and call_memory[0] and not call_memory[2]:
                spilled_call = self.slot_syms.get(
                    (call_memory[0], call_memory[1]))
            # call reg: dispatch inline di un campo tipo CPython
            cr = subreg64(op.strip())
            cs = self._reg(cr) if cr else spilled_call
            if cs is not None and cs.op == 'tpiter':
                iterator = ndx_k('iter', cs.a)
                self._setreg(self.abi.ret_reg, iterator)
                self._cur_block.ops.append(NdxOp('calc', a=iterator, va=ins.address))
                self._last_call = (ins, iterator, 'MAKE_ITERATOR', ('make_iterator', 1))
                return
            if cs is not None and cs.op == 'tpiternext':
                nxt = ndx_k('next', cs.a, n=ins.address)
                self._setreg(self.abi.ret_reg, nxt)
                self._cur_block.ops.append(NdxOp('calc', a=nxt,
                                              va=ins.address))
                self._last_call = (ins, nxt, 'ITERATOR_NEXT', None)
                return
            if cs is not None and cs.op == 'len_slot':
                length = ndx_k('native_ssize', ndx_k('len', cs.a))
                self._setreg(self.abi.ret_reg, length)
                self._last_call = (ins, length, 'PROTOCOL_LENGTH', None)
                return
            if cs is not None and cs.op == 'bool_slot':
                # nb_bool(T) — il risultato in al/eax e' la verita' Python:
                # il branch che lo testa diventa ``if T:`` / ``if not T:``.
                truth_arg = self._reg(self.abi.arg_regs[0])
                if truth_arg is None:
                    truth_arg = cs.a
                truth = ndx_k('bool', truth_arg)
                self._setreg(self.abi.ret_reg, truth)
                self._cur_block.ops.append(NdxOp('calc', a=truth,
                                                 va=ins.address))
                self._last_call = (ins, truth, 'NB_BOOL', None)
                return
            if cs is not None and cs.op == 'binary_slot':
                left = self._reg(self.abi.arg_regs[0])
                right = self._reg(self.abi.arg_regs[1])
                if left is None or left.op == 'loc':
                    reached = self._latest_semantic_store_before(
                        left.a if left is not None else None, ins.address)
                    if reached is None:
                        reached = self._symbol_for_register_before(
                            ins.address, self.abi.arg_regs[0])
                    if reached is not None:
                        left = reached
                if right is None or right.op == 'loc':
                    reached = self._latest_semantic_store_before(
                        right.a if right is not None else None, ins.address)
                    if reached is None:
                        reached = self._symbol_for_register_before(
                            ins.address, self.abi.arg_regs[1])
                    if reached is not None:
                        right = reached
                value = ndx_k('binop', cs.a, left, right, n=cs.n)
                self._setreg(self.abi.ret_reg, value)
                self._cur_block.ops.append(NdxOp('calc', a=value,
                                                 va=ins.address))
                self._last_call = (ins, value, 'NUMBER_BINARY_SLOT', None)
                return
            # dispatch per slot di tipo:
            #  - tp_call (0x78): invocazione inline di un callable
            #    (GCC inline-a CALL_METHOD_*): il callable è in rdi/rcx
            #  - altri slot (tp_hash, tp_richcompare, ...): machinery
            #    interno CPython → opaco
            TP_CALL = 0x78
            if cs is not None and cs.op == 'tp_slot' and cs.a != TP_CALL:
                self._setreg(self.abi.ret_reg, None)
                self._last_call = None
                return
            fn = self._reg(self.abi.arg_regs[0])
            if cs is not None and cs.op == 'tp_slot' and \
                    cs.a == TP_CALL and fn is not None and \
                    fn.op in ('mcall', 'call', 'getattr', 'global',
                              'sub', 'binop'):
                cargs = []
                for r in self.abi.arg_regs[1:]:
                    s = self._reg(r)
                    if s is not None:
                        cargs.append(s)
                ret = ndx_k('call', fn, cargs)
                self._setreg(self.abi.ret_reg, ret)
                self._cur_block.ops.append(NdxOp('calc', a=ret,
                                              va=ins.address))
                self._last_call = (ins, ret, 'inline_invoke', None)
                return
            # dispatch tp_call/vectorcall inline: ``call rax|rdi|rcx|…`` —
            # il callable viaggia nel registro indicato (metodi legati,
            # callable locali, risultati di _PyType_Lookup).  Il callee è
            # il valore semantico corrente del registro; quando quel
            # valore è l'attributo appena cercato (_PyType_Lookup) la
            # coppia lookup+call È una method call sorgente:
            # ``obj.name(args)``.
            _creg = reg_of(ins, 0)
            if _creg and is_reg(_creg):
                _fn = self._reg(subreg64(_creg))
                if isinstance(_fn, NdxSV) and _fn.op in (
                        'getattr', 'mcall', 'call', 'global', 'var', 'par',
                        'super', 'loc', 'cellref', 'sub'):
                    if self._consume_pending_method(ins):
                        return
                    cargs = []
                    for r in self.abi.arg_regs[1:]:
                        s = self._reg(r)
                        if s is not None:
                            cargs.append(s)
                    ret = ndx_k('call', _fn, cargs)
                    self._setreg(self.abi.ret_reg, ret)
                    self._cur_block.ops.append(NdxOp('calc', a=ret,
                                                     va=ins.address))
                    self._last_call = (ins, ret, 'reg_dispatch', None)
                    return
            self._setreg(self.abi.ret_reg, None)
            self._last_call = None
            return
        t = None
        if op.startswith('0x'):
            try:
                t = int(op, 16)
            except ValueError:
                t = None
        if t is not None:
            kind, name, sem = self.res.resolve(t)
            # un metodo appena cercato (_PyType_Lookup) consumato da una
            # call diretta/indiretta: la coppia È la method call sorgente
            # ``obj.name(args)`` — prova il dispatch prima di ogni altra
            # classificazione
            if self._consume_pending_method(ins):
                return
        elif 'rip' in op:
            # MinGW/GCC: chiamate CPython API DIRETTE via IAT
            # (call qword ptr [rip+…]) senza stub locale risolvibile.
            iat = rip_target(ins)
            iat_name = (getattr(self.img, 'imports', None) or {}).get(iat) \
                or (getattr(self.img, 'plt_map', None) or {}).get(iat)
            if iat_name is None:
                # Slot NON-import (tabelle di helper Nuitka a
                # static-link in .rdata): lo slot contiene il VA del
                # callee locale.  Leggi il puntatore e riclassifica il
                # callee con il resolver strutturale (fingerprint).
                try:
                    _off = self.img.va_to_off(iat)
                    _tgt = int.from_bytes(
                        self.img.data[_off:_off + 8], 'little')
                except Exception:
                    return
                if not _tgt or not self.img.is_exec(_tgt):
                    return
                t = _tgt
                kind, name, sem = self.res.resolve(t)
                if name is None or kind == 'unknown':
                    return
            else:
                kind, name, sem = 'plt', iat_name, \
                    PY_API_SEMANTICS.get(iat_name)
        else:
            return
        if name == '__security_check_cookie':
            # MSVC /GS epilogue intrinsic.  It has no Python result and the
            # compiler deliberately keeps the function's semantic return in
            # RAX across this check, so do not replace that value with a
            # synthetic native call.
            self._last_call = (ins, self._reg(self.abi.ret_reg), name, sem)
            return
        if t is not None and self.mca is not None and t in getattr(
                self.mca, '_function_constructor_vas', ()):
            kind, name, sem = 'plt', 'Nuitka_Function_New', ('make_function', None)
        exact_maker = None
        if t is not None and self.mca is not None:
            try:
                exact_maker = self.mca._decode_function_maker(t)
            except Exception:
                exact_maker = None
        if exact_maker is not None:
            # The exact wrapper ABI is stronger than a broad native signature
            # collision such as RUNTIME_STRUCT_INIT.  Preserve its identity so
            # runtime defaults and annotations can be joined to the matching
            # function by code-object slot.
            kind = 'function_maker'
            name = f'MAKE_FUNCTION_EXACT@{t:x}'
            sem = ('make_function_exact', None)
        # Initializer IMPORT_HARD_* non classificato dal sig db (opc-hash
        # di una build diversa): identificato dallo scan statico — la
        # funzione chiama PyImport_ImportModule con la stringa del modulo.
        if name is None or kind == 'unknown':
            # dispatch di un metodo appena cercato (_PyType_Lookup):
            # ``call trampoline_sconosciuto`` con l'attributo vivo in un
            # registro È la method call sorgente ``obj.name(args)``.
            if self._consume_pending_method(ins):
                return
            hard_module = _ndx_hard_import_initializers(self.img).get(t)
            if hard_module is not None:
                # Marker reversibile: il nome modulo vero viaggia nel nome
                # helper (niente tabelle, nessuna ambiguità dotted).
                name = 'IMPORT_HARD@' + hard_module
                sem = ('import', 0)
                kind = 'hard'
        if name in ('__chkstk', '__chkstk_ms', '_alloca_probe'):
            # Win64 stack probes preserve the function's argument registers.
            # Treating this prologue helper as a Python call erased python_pars
            # precisely when a long function needed more than one stack page.
            self._last_call = None
            for register in ('r10', 'r11'):
                self._setreg(register, None)
            return
        # registri argomento EFFETTIVI del chiamato (IPA-SRA / MSVC):
        # inferiti dal machine code della funzione destinazione.
        # Le funzioni PLT/IAT seguono l'ABI standard (lo stub è pass-through).
        if not hasattr(self, '_argreg_cache'):
            self._argreg_cache = {}
        if kind == 'function_maker':
            eff = list(self.abi.arg_regs)
        elif kind == 'plt':
            eff = list(self.abi.arg_regs)
        else:
            eff = effective_arg_regs(self.img, self.fd, t,
                                     cache=self._argreg_cache)
            if eff is None or (not eff and sem and sem[1]):
                eff = list(self.abi.arg_regs)
        if sem and sem[0] == 'binop' and name and name.startswith('BINARY_OPERATION_'):
            # Some specialized helpers inspect only the right operand's type,
            # yet pass both original operands to nb_*.  Live-in scans miss the
            # implicit left argument of that indirect dispatch.
            canonical = t
            seen_thunks = set()
            while canonical is not None and canonical not in seen_thunks:
                seen_thunks.add(canonical)
                body = self.res._func_insns(canonical)
                if body and body[0].mnemonic == 'jmp':
                    canonical = branch_target(body[0])
                else:
                    break
            classifier = getattr(self.res, '_native_classifier', None)
            detail = classifier._binop_slot(canonical) if classifier and canonical else None
            if isinstance(detail, tuple) and len(detail) == 2 and len(detail[1]) == 2:
                eff = list(detail[1])
        args = [self._reg(r) for r in eff]
        for index, register in enumerate(eff):
            if args[index] is None or args[index].op == 'loc':
                recovered = self._parameter_arg_before(
                    ins.address, register)
                if recovered is not None:
                    args[index] = recovered
        # Complete fixed-arity Win64 calls with their fifth and later
        # arguments from the outgoing stack area.  ``arity`` describes Python
        # operands; Nuitka helpers commonly prepend ``tstate``.
        if self.img.fmt == 'pe' and sem and isinstance(sem[1], int) and \
                sem[1] > 0:
            has_tstate = bool(args and args[0] is not None and
                              args[0].op == 'tstate')
            expected = sem[1] + (1 if has_tstate else 0)
            while len(args) < expected:
                offset = 0x20 + 8 * (len(args) - 4)
                args.append(self.slot_syms.get(('rsp', offset)))
        # ``Nuitka_Function_New`` has eleven arguments.  On Win64 the first
        # four are registers and the remaining seven occupy the standard
        # outgoing argument area.  In particular, offsets 0x20/0x28/0x30 are
        # exactly positional defaults, keyword defaults and annotations.
        # Preserve these ABI fields in the symbolic node; nearby constants are
        # deliberately not considered evidence for function metadata.
        if self.img.fmt == 'pe' and name == 'Nuitka_Function_New':
            args = list(args[:4])
            args.extend(self.slot_syms.get(('rsp', offset))
                        for offset in range(0x20, 0x58, 8))
        if self.img.fmt == 'pe' and name == 'Nuitka_Frame_AttachLocals' and \
                self.varnames:
            required = 2 + len(self.varnames)
            args = list(args[:4])
            while len(args) < required:
                offset = 0x20 + 8 * (len(args) - 4)
                args.append(self.slot_syms.get(('rsp', offset)))
        # __import__(name, globals, locals, fromlist, level): fromlist e
        # level vivono nell'area stack uscente (0x20/0x28) su Win64.
        if self.img.fmt == 'pe' and name == 'BUILTIN___IMPORT__' and \
                len(args) < 6:
            args = list(args[:4])
            while len(args) < 6:
                offset = 0x20 + 8 * (len(args) - 4)
                args.append(self.slot_syms.get(('rsp', offset)))
        # Native iterator wrappers are frequently IPA/SRA-specialised.  A
        # generic live-in analysis then sees the registers prepared for calls
        # made *inside* the wrapper and can mistake them for Python operands.
        # The wrapper itself supplies an exact, ABI-neutral proof: the input
        # PyObject (or one of its register aliases) is dereferenced at the
        # public ``ob_type`` offset before dispatching ``tp_iter``.  Use that
        # single origin register when it can be proven from the callee body.
        if name == 'MAKE_ITERATOR' and t is not None and kind != 'plt':
            operand_register = self._native_object_operand_register(t)
            if operand_register is not None:
                operand = self._reg(operand_register)
                if operand is None or operand.op == 'loc':
                    reached = self._latest_semantic_store_before(
                        operand.a if operand is not None else None,
                        ins.address)
                    if reached is None:
                        reached = self._symbol_for_register_before(
                            ins.address, operand_register)
                    if reached is None:
                        reached = self._parameter_arg_before(
                            ins.address, operand_register)
                    if reached is not None:
                        operand = reached
                if operand is not None:
                    args = [operand]
        profile = ndx_binary_abi(self.img)
        profile.record_semantic(t, (kind, name, sem))
        profile.record_call(t, ins.address, eff, args, self.slot_syms)
        # per gli argomenti usati: sem = (op, arity)
        ret = self._semantic_call(name, sem, args, ins)
        if isinstance(ret, NdxSV) and ret.n is None and ret.op in (
                'call', 'kwcall', 'mcall', 'nativecall', 'apicall',
                'tuple_build', 'list_build'):
            ret.n = ins.address
        self._setreg(self.abi.ret_reg, ret)
        self._last_call = (ins, ret, name, sem)
        # op calc: ogni produttore semantico è un nodo d'espressione
        if ret is not None and ret.op not in (
                'frame', 'excstate', 'codeobj_new', 'gslot', 'gaddr',
                'dict_merge', 'dict_index'):
            self._cur_block.ops.append(NdxOp('calc', a=ret, va=ins.address))
        # azzera i volatili
        for r in self.abi.caller_saved:
            if r != self.abi.ret_reg:
                self.regs[r] = None

    def _native_object_operand_register(self, target_va):
        """Prove the incoming PyObject register used by a native wrapper.

        Nuitka helper signatures can be specialised by the C compiler, so
        their effective Python operand is not necessarily the first platform
        ABI register.  Track straight-line register aliases in the helper's
        entry and return the original argument whose ``PyObject.ob_type`` is
        read.  No helper address, source identifier or application constant
        participates in the decision.
        """
        if not hasattr(self, '_native_object_operand_cache'):
            self._native_object_operand_cache = {}
        cache = self._native_object_operand_cache
        if target_va in cache:
            return cache[target_va]
        cache[target_va] = None
        try:
            bounds = self.img.function_bounds(target_va)
            if bounds is None:
                return None
            start, end = bounds
            offset = self.img.va_to_off(start)
            if offset is None:
                return None
            code = self.img.data[
                offset:offset + min(max(0, end - start), 0x400)]
            instructions = list(self.fd.md.disasm(code, start))[:64]
        except Exception:
            return None
        aliases = {register: register for register in self.abi.arg_regs}
        for item in instructions:
            if item.mnemonic in ('ret', 'hlt', 'ud2', 'jmp'):
                break
            operands = split_ops(item.op_str)
            for operand in operands:
                memory = parse_mem(operand)
                if memory and not memory[2] and \
                        memory[1] == self.abi.ob_type and \
                        memory[0] in aliases:
                    result = aliases[memory[0]]
                    cache[target_va] = result
                    return result
            if not operands:
                continue
            destination = subreg64(operands[0])
            if destination is None:
                continue
            if item.mnemonic in ('mov', 'movabs') and len(operands) == 2:
                source = subreg64(operands[1])
                if source in aliases:
                    aliases[destination] = aliases[source]
                    continue
            # A write which is not a pure alias transfer destroys the prior
            # argument provenance for that register.
            if item.mnemonic not in ('cmp', 'test', 'push'):
                aliases.pop(destination, None)
        return None

    # machinery di runtime Nuitka/CPython: mai semantica Python. Il loro
    # contributo a livello statement è rumore (spill, conversioni interne,
    # formattazione messaggi d'errore inline).
    MACHINERY_CALL_NAMES = frozenset((
        'PyUnicode_FromFormat', 'PyLong_FromSsize_t',
        'PyLong_AsLongAndOverflow', 'QUICK_ITERATOR_NEXT',
        '_PyObject_GC_Resize', 'Nuitka_LongFromCLong',
        'Nuitka_Number_Index', '_PyLong_Copy', 'PyTraceBack_Here',
        'PyErr_NormalizeException', 'Nuitka_Type_IsSubtype',
        'PyUnicode_FromString', 'PyErr_NoMemory', 'PyMem_Malloc',
        'CONSIDER_THREADING', 'Py_MakePendingCalls'))

    def _expand_stack_args(self, rel, ins):
        """Espande gli argomenti passati come PUNTATORI ad array di stack.

        MSVC materializza l'array degli argomenti Python con `lea rX,
        [rsp+OFF]` e passa il puntatore: gli argomenti veri sono gli
        slot consecutivi [rsp+OFF], [rsp+OFF+8], ... tracciati in
        slot_syms dai mov-store. Sostituisce ogni stackaddr con i
        valori dell'array (fino al primo slot vuoto)."""
        out = []
        for a in rel:
            if a is not None and getattr(a, 'op', None) == 'stackaddr':
                base, off = a.a, a.b
                vals = []
                for k in range(8):
                    v = self.slot_syms.get((base, off + 8 * k))
                    if v is None:
                        break
                    vals.append(v)
                if vals:
                    out.extend(vals)
                else:
                    out.append(a)
            else:
                out.append(a)
        return out

    def _dict_keyword_parts(self, mapping, before_va, _depth=0):
        """Materialise keyword syntax from a proven mapping value.

        Literal dictionaries are populated by separate ``PyDict_SetItem``
        calls, so their key/value pairs live in preceding IR operations rather
        than inside the allocation node.  Join them by allocation identity;
        arbitrary mappings remain an explicit ``**mapping`` expansion.
        """
        if not isinstance(mapping, NdxSV) or _depth > 64:
            return []
        if mapping.op == 'dict_merge':
            parts = []
            for child in mapping.b or []:
                parts.extend(self._dict_keyword_parts(
                    child, before_va, _depth + 1))
            return parts
        if mapping.op == 'dict_empty':
            pairs = []
            for block in self.blocks.values():
                for operation in block.ops:
                    if operation.kind != 'store_sub' or \
                            operation.va >= before_va:
                        continue
                    same_mapping = operation.a is mapping or (
                        isinstance(operation.a, NdxSV) and
                        operation.a.op == 'dict_empty' and
                        operation.a.n is not None and
                        operation.a.n == mapping.n)
                    if not same_mapping:
                        continue
                    key = operation.b
                    if not (isinstance(key, NdxSV) and key.op == 'const' and
                            isinstance(key.a, str) and key.a.isidentifier()):
                        return [ndx_k('kwspread', mapping)]
                    pairs.append((operation.va,
                                  ndx_k('kwarg', key.a, operation.c)))
            if pairs:
                if mapping.n is not None:
                    self.consumed_keyword_mappings.add(mapping.n)
                return [value for _address, value in sorted(pairs)]
        return [ndx_k('kwspread', mapping)]

    def _gc_inline_pyobject_vector(self, ins):
        """Recover a directly allocated inline ``PyObject *`` vector.

        Older MSVC Nuitka builds construct the temporary tuple used by a
        ``**mapping`` merge with ``_PyObject_GC_Malloc`` instead of a named
        tuple helper.  Prove that object from the public ``PyVarObject``
        layout: the call result is copied to an alias, ``ob_size`` is written
        at +0x10, and every small inline element slot starts at +0x18.  No
        source names, helper addresses or application constants participate.
        """
        try:
            index = next(i for i, item in enumerate(self.insns)
                         if item.address == ins.address)
        except (StopIteration, AttributeError):
            return None
        aliases = {self.abi.ret_reg}
        count = None
        payload_offsets = set()
        # Initialisation is straight-line and precedes the next semantic call.
        for item in self.insns[index + 1:index + 40]:
            if item.mnemonic == 'call':
                break
            operands = split_ops(item.op_str)
            if item.mnemonic != 'mov' or len(operands) != 2:
                continue
            destination_register = subreg64(operands[0])
            source_register = subreg64(operands[1])
            if destination_register:
                if source_register in aliases:
                    aliases.add(destination_register)
                continue
            memory = parse_mem(operands[0])
            if not memory or memory[0] not in aliases or memory[2]:
                continue
            offset = memory[1]
            immediate = is_imm(operands[1])
            if offset == 0x10 and immediate is not None and \
                    0 < immediate <= 256:
                count = immediate
            elif offset >= 0x18 and (offset - 0x18) % 8 == 0:
                payload_offsets.add(offset)
        if count is None:
            return None
        # Small compiler-generated transports are explicitly zeroed before
        # being populated.  Requiring all slots prevents a random GC-managed
        # variable-size object from being mistaken for a Python tuple.
        expected = {0x18 + 8 * position for position in range(count)}
        if count > 32 or not expected <= payload_offsets:
            return None
        values = self.container_values.get(ins.address)
        if not isinstance(values, list) or len(values) != count:
            values = [None] * count
            self.container_values[ins.address] = values
        return ndx_k('tuple_build', None, values, n=ins.address)

    def _double_literal_before(self, ins, limit=16):
        """C double letterale caricato in XMM da .rdata poco prima di ``ins``.

        ``MAKE_FLOAT_FROM_DOUBLE(tstate, value)`` riceve il double in XMM:
        per i letterali sorgente MSVC lo carica con ``movsd xmm, [rip+c]``.
        La lettura degli 8 byte ripristina la costante float esatta.
        """
        import struct as _struct
        insns = self.insns
        idx = None
        target = getattr(ins, 'address', None)
        for i, item in enumerate(insns):
            if item.address == target:
                idx = i
                break
        if idx is None:
            return None
        for item in reversed(insns[max(0, idx - limit):idx]):
            if item.mnemonic not in ('movsd', 'mov') or \
                    'xmm' not in item.op_str or 'rip' not in item.op_str:
                continue
            t = rip_target(item)
            if t is None:
                continue
            try:
                off = self.img.va_to_off(t)
                raw = self.img.data[off:off + 8]
                if len(raw) != 8:
                    continue
                value = _struct.unpack('<d', raw)[0]
            except Exception:
                continue
            if value != value or abs(value) > 1e18:
                continue
            return value
        return None

    def _scan_range_fields(self, ins):
        """Range-iteratore a REGISTRI (range inline di Nuitka, es.
        ``for i in range(1, n + 1):``): il costruttore non ha operando
        PyObject, ma il codice subito dopo scrive start/stop nei campi
        dell'oggetto appena allocato ([rax+0x10]/[rax+0x18]).  I
        sorgenti dei registri si risolvono con una reaching-definition
        locale (_symbol_for_register_before), NON con lo stato del
        walk (ordine di visita dei blocchi != ordine di programma).
        Ritorna range(start, stop), o None se i campi non si
        risolvono."""
        start = stop = None
        start_addr = stop_addr = None
        try:
            idx = next(i for i, item in enumerate(self.insns)
                       if item.address == ins.address)
        except (StopIteration, AttributeError):
            return None
        for item in self.insns[idx + 1: idx + 16]:
            if item.mnemonic == 'call':
                break
            if item.mnemonic != 'mov':
                continue
            parts = split_ops(item.op_str)
            if len(parts) != 2 or not parts[1].isidentifier():
                continue
            mem = parse_mem(parts[0])
            if not mem or mem[0] != self.abi.ret_reg or mem[2]:
                continue
            sreg = subreg64(parts[1])
            if mem[1] == 0x10 and start is None:
                start = sreg
                start_addr = item.address
            elif mem[1] == 0x18 and stop is None:
                stop = sreg
                stop_addr = item.address
        if start is None or stop is None:
            return None
        start_sym = self._symbol_for_register_before(
            start_addr or ins.address, start)
        stop_sym = self._symbol_for_register_before(
            stop_addr or ins.address, stop)
        if start_sym is None or stop_sym is None:
            return None
        if start_sym.op in ('tstate', 'frame', 'excstate', 'stackaddr',
                            'none') or stop_sym.op in (
                'tstate', 'frame', 'excstate', 'stackaddr', 'none'):
            return None
        return ndx_k('call', 'range', [start_sym, stop_sym])

    def _semantic_call(self, name, sem, args, ins):
        """Converte una call risolta in un simbolo semantico o op."""
        b = self._cur_block
        # dispatch di un metodo appena cercato (_PyType_Lookup): il
        # trampoline (spesso un sub_* senza firma) che riceve l'attributo
        # vivo in un registro È la method call sorgente ``obj.name(args)``
        if (name is None or str(name).startswith('sub_')) and \
                self._consume_pending_method(ins):
            return None
        # call diretta a una pyfunc del binario (impl intra-modulo)
        if sem and sem[0] == 'py_call' and isinstance(name, str):
            rel = [a for a in args if isinstance(a, NdxSV) and
                   a.op not in ('tstate', 'frame', 'stackaddr', 'gslot')]
            return ndx_k('call', ndx_k('global', name), rel)
        if name is None:
            return ndx_k('call', args=args)
        # A few CPython APIs take raw ``const char *`` arguments.  LEA of
        # their literal is represented as gaddr by the machine lifter; the C
        # prototype proves that it is text and permits lossless
        # materialisation without treating arbitrary global addresses as
        # strings.
        cstring_arguments = {
            'PyImport_ImportModule': (0,),
            'PyObject_GetAttrString': (1,),
            'PyObject_SetAttrString': (1,),
            'PyObject_HasAttrString': (1,),
        }
        if name in cstring_arguments:
            args = list(args)
            for position in cstring_arguments[name]:
                if position >= len(args):
                    continue
                argument = args[position]
                if argument is None or argument.op != 'gaddr' or \
                        not isinstance(argument.a, int):
                    continue
                try:
                    literal = self.img.read_cstr(argument.a, 4096)
                except Exception:
                    literal = None
                if isinstance(literal, str) and literal and \
                        all(character.isprintable() for character in literal):
                    args[position] = ndx_k('const', literal)
        sop, arity = (sem or (None, None))
        if sop == 'tuple_dict_call':
            raw = [self._reg(register) for register in self.abi.arg_regs]
            function, positional, keyword = [raw[index] for index in arity]
            if isinstance(positional, NdxSV) and positional.op in ('tuple_build', 'list_build'):
                args = list(positional.b or [])
                self.consumed_argument_vectors.add(id(positional))
            elif isinstance(positional, NdxSV) and positional.op == 'const' and isinstance(positional.a, tuple):
                args = [ndx_k('const', value) for value in positional.a]
            else:
                args = [ndx_k('star', positional)]
            if keyword is None or keyword.op == 'none' or (keyword.op == 'imm' and keyword.a == 0):
                return ndx_k('call', function, args)
            if keyword.op == 'const' and isinstance(keyword.a, dict):
                parts = [ndx_k('kwarg', key, ndx_k('const', value)) for key, value in keyword.a.items()] if all(isinstance(key, str) and key.isidentifier() and not __import__('keyword').iskeyword(key) for key in keyword.a) else [ndx_k('kwspread', keyword)]
            else:
                parts = self._dict_keyword_parts(keyword, ins.address)
                if not parts:
                    parts = [ndx_k('kwspread', keyword)]
            return ndx_k('kwcall', function, args, parts)
        if sop == 'dict_copy_argument':
            raw = [self._reg(register) for register in self.abi.arg_regs]
            source = raw[arity]
            if isinstance(source, NdxSV) and source.op == 'const' and isinstance(source.a, dict):
                return ndx_k('const', dict(source.a))
            return ndx_k('dict_copy', source)
        if sop == 'vector_keywords':
            raw = [self._reg(register) for register in self.abi.arg_regs]
            function, vector, names = raw[1:4]
            layout, count = arity if isinstance(arity, tuple) else ('packed', arity)
            if layout == 'split':
                keyword_vector = raw[3]
                names = self.slot_syms.get(('rsp', 0x20))
            if isinstance(names, NdxSV) and names.op == 'const' and \
                    isinstance(names.a, tuple) and all(
                        isinstance(key, str) and key.isidentifier() for key in names.a):
                if layout == 'split':
                    positional = self._expand_argument_array(vector, count)
                    keywords = self._expand_argument_array(keyword_vector, len(names.a))
                else:
                    values = self._expand_argument_array(vector, count + len(names.a))
                    positional, keywords = values[:count], values[count:]
                if len(positional) == count and len(keywords) == len(names.a):
                    return ndx_k('kwcall', function, positional, [
                        ndx_k('kwarg', key, value)
                        for key, value in zip(names.a, keywords)])
            return ndx_k('nativecall', name, args)
        if sop == 'dict_unicode_index':
            keys = args[0] if args else None
            key = args[1] if len(args) > 1 else None
            if isinstance(keys, NdxSV) and keys.op == 'dict_keys' and \
                    isinstance(key, NdxSV) and key.op == 'const' and \
                    isinstance(key.a, str):
                return ndx_k('dict_index', keys, key.a, 1)
            return None
        if sop == 'list_from_args':
            return ndx_k('list_build', None, [
                args[index] if index < len(args) else None for index in arity])
        # Inline module-variable accessor: the cached-dictionary lookup
        # (template GET_STRING_DICT_VALUE(moduledict, key)) IS the read of
        # the global.  Its key register setup carries the exact namespace
        # name; returning a `global` symbol makes the accessor diamond's
        # fast and slow arms converge on one identical Python value.
        if sop == 'global_lookup' and self.mca is not None:
            key = args[1] if len(args) > 1 else None
            if key is not None and key.op == 'const' and \
                    isinstance(key.a, str) and key.a.isidentifier():
                value = ndx_k('global', key.a)
                self.symbol_locations.setdefault(
                    self._svkey_of(value), set()).add(('reg', subreg64(
                        self.abi.ret_reg)))
                return value
        if sop == 'make_function_exact' and self.mca is not None:
            try:
                maker_va = int(str(name).rsplit('@', 1)[1], 16)
                maker = self.mca._decode_function_maker(maker_va)
            except Exception:
                maker = None
            if maker is not None:
                def materialise(source):
                    if source is None or source.kind == 'null':
                        return None
                    if source.kind == 'param':
                        index = int(source.value)
                        return args[index] if index < len(args) else None
                    if source.kind == 'const':
                        return ndx_k('const', source.value)
                    if source.kind == 'slot':
                        return ndx_k('gslot', source.value)
                    if source.kind == 'impl':
                        return ndx_k('gaddr', source.value)
                    if source.kind == 'imm':
                        return ndx_k('imm', source.value)
                    return None

                constructor_args = [
                    ndx_k('gaddr', maker.get('impl_va')),
                    ndx_k('const', maker.get('name')),
                    ndx_k('const', maker.get('qualname')),
                    ndx_k('gslot', maker.get('code_obj_slot')),
                    materialise(maker.get('defaults_source')),
                    materialise(maker.get('kwdefaults_source')),
                    materialise(maker.get('annotations_source')),
                ]
                return ndx_k('func_new', maker_va, constructor_args)
        # machinery: il valore restituito può ancora fluire (es. int
        # interno), ma NON genera statement né condizioni.
        if name in self.MACHINERY_CALL_NAMES:
            rel = [a for a in args if a is not None and a.op != 'tstate']
            return rel[-1] if rel else None
        # regole API-reach universali
        if name in ('CALL_FUNCTION_GENERIC', 'BUILTIN_RANGE',
                    'BUILTIN_LIST'):            # le posizioni None si conservano fino al recovery (il drop
            # anticipato fa perdere le posizioni ABI degli argomenti)
            rel = [a for a in args if not (a is not None and
                                           a.op == 'tstate')]
            rel = self._expand_stack_args(rel, ins)
            if name == 'BUILTIN_RANGE':
                # range(start, stop, step): recovery degli argomenti None
                # tramite le load ABI adiacenti (`mov r8/r9, SRC; call`) e
                # gli store semantici (es. il len calcolato prima).
                if ins is not None:
                    idx3 = next((i4 for i4, it in enumerate(self.insns)
                                 if it.address == ins.address), None)
                    if idx3 is not None:
                        for apos in range(min(3, len(rel))):
                            cur = rel[apos]
                            if cur is not None and not (
                                    isinstance(cur, NdxSV) and
                                    cur.op == 'loc'):
                                continue
                            # rel ha il tstate già filtrato: rel[i] vive
                            # in arg_regs[i+1] (il primo slot ABI è tstate)
                            areg = self.abi.arg_regs[apos + 1]                                 if apos + 1 < len(self.abi.arg_regs)                                 else None
                            if areg is None:
                                continue
                            for it in reversed(self.insns[
                                    max(0, idx3 - 160):idx3]):
                                ops2 = split_ops(it.op_str)
                                if it.mnemonic == 'mov' and                                         len(ops2) == 2 and                                         subreg64(ops2[0]) == areg:
                                    # sorgente MEMORIA: slot heap/stack
                                    # tracciato (es. locals del generatore)
                                    mem2 = parse_mem(ops2[1])
                                    if mem2 and mem2[0] and not mem2[2]:
                                        slot_val = self.slot_syms.get(
                                            (mem2[0], mem2[1]))
                                        if slot_val is not None:
                                            if rel and apos < len(rel):
                                                rel[apos] = slot_val
                                            break
                                        # deref di cella closure: [REG+0x10]
                                        # con REG=cellref(i) → il valore
                                        # della closure (nome dal gen mode)
                                        if mem2[1] == 0x10 and                                                 getattr(self, 'gen_mode',
                                                        False):
                                            cdef = None
                                            cva = (0, None)
                                            for (rr2, va2), sym3 in                                                     getattr(self,
                                                            'reg_sem_defs',
                                                            {}).items():
                                                if rr2 == mem2[0] and                                                         va2 < it.address:
                                                    if getattr(sym3, 'op',
                                                               '') ==                                                             'cellref' and                                                             va2 > cva[0]:
                                                        cdef = sym3
                                                        cva = (va2, sym3)
                                            if cdef is not None:
                                                nm2 = self.gen_closure_names.get(
                                                    cdef.a, f'_cell{cdef.a}')
                                                if rel and apos < len(rel):
                                                    rel[apos] = ndx_k(
                                                        'var', nm2)
                                                break
                                    s2 = subreg64(ops2[1])
                                    if s2 is not None:
                                        best = (0, None)
                                        for blk in self.blocks.values():
                                            for op2 in blk.ops:
                                                if op2.kind == 'store' and                                                         op2.a == ('reg', s2) and                                                         op2.b is not None and                                                         op2.va is not None and                                                         op2.va < it.address:
                                                    if op2.va > best[0]:
                                                        best = (op2.va, op2.b)
                                        # anche le definizioni simulate
                                        # (reg_sem_defs) — coprono i valori
                                        # senza store-op (closure deref,
                                        # copie intermedie)
                                        for (rr, va), sym2 in getattr(
                                                self, 'reg_sem_defs',
                                                {}).items():
                                            if rr == s2 and va < it.address:
                                                if va > best[0]:
                                                    best = (va, sym2)
                                        if best[1] is not None:
                                            rel[apos] = best[1]
                                    break
                while rel and rel[-1] is None:
                    rel.pop()
                return ndx_k('call', 'range', rel)
            if name == 'BUILTIN_LIST':
                rel = [a for a in rel if a is not None]
                return ndx_k('call', 'list', rel)
            fn = rel[0] if rel else None
            cargs = [a for a in rel[1:] if a is not None]
            # Nuitka's keyword-call ABI appends the keyword NAMES as a
            # trailing constant tuple of identifiers after the argument
            # values (CPython's CALL_FUNCTION_KW convention). Splitting it
            # back out is what makes ``field(default_factory=list)`` render
            # as a keyword call instead of the invalid
            # ``field(list, ('default_factory',))`` — and class-decorator
            # recovery requires a ``kwcall``, so without this split
            # ``@dataclass(slots=True)`` is dropped from every class.
            if name == 'CALL_FUNCTION_GENERIC' and cargs:
                last = cargs[-1]
                if isinstance(last, NdxSV) and last.op == 'const' and \
                        isinstance(last.a, tuple) and last.a and \
                        all(isinstance(k, str) and k.isidentifier()
                            for k in last.a) and \
                        len(cargs) - 1 >= len(last.a):
                    kw_names = list(last.a)
                    split = (len(cargs) - 1) - len(kw_names)
                    keywords = [ndx_k('kwarg', key, value)
                                for key, value in zip(kw_names,
                                                      cargs[split:-1])]
                    return ndx_k('kwcall', fn, cargs[:split], keywords)
            return ndx_k('call', fn, cargs)
        positional_tuple_call = re.match(
            r'^CALL_FUNCTION_WITH_POS_ARGS(\d+)$', str(name))
        if positional_tuple_call and len(args) >= 3:
            # ABI invariant: tstate, callable, constant/runtime args tuple.
            # The tstate register can look like an unrelated Python value
            # after register merging, so select the two physical operands by
            # position instead of semantic-value heuristics.
            args = [args[1], args[2]]
        # Arity nota: conserva i primi N operandi Python materializzati.
        # MSVC può eliminare completamente l'uso di ``tstate`` lasciando il
        # primo registro ABI simbolicamente vuoto (es. [None, value, ...]); un
        # semplice slice posizionale perderebbe quindi ``value``.
        # Module-dict bind key recovery: UPDATE_STRING_DICT*(moddict, key,
        # value).  The key register is frequently dead by the call (MSVC
        # loads it early into a volatile register), so the symbolic state
        # holds None there.  The key is a module-dict C string: recover it
        # from the last definition of the ABI key register before the call.
        if sop == 'module_bind' and self.mca is not None:
            raw = list(args) + [None] * (4 - len(args))
            key_sym = raw[1]
            if key_sym is None:
                key_reg = self.abi.arg_regs[1]
                index = next((i for i, item in enumerate(self.insns)
                              if item.address == ins.address), None)
                if index is not None:
                    hops = 0
                    for back in range(index - 1, max(0, index - 24), -1):
                        prior = self.insns[back]
                        p_ops = split_ops(prior.op_str)
                        if not p_ops or prior.mnemonic not in ('mov', 'lea') \
                                or subreg64(p_ops[0]) != key_reg:
                            continue
                        if 'rip' in p_ops[1] and parse_mem(p_ops[1]):
                            slot = rip_target(prior)
                            if slot is None or self.mca is None:
                                break
                            value, _which = self.mca.const_for_slot(slot)
                            if not (isinstance(value, str) and
                                    value.isidentifier()):
                                # `mov rdx,[rip+X]` loads a POINTER cell
                                # whose target is the C-string key;
                                # `lea rdx,[rip+X]` addresses the string
                                # directly.
                                try:
                                    str_va = self.img.read_u64(slot) \
                                        if prior.mnemonic == 'mov' else slot
                                except Exception:
                                    str_va = None
                                value = None
                                if str_va:
                                    try:
                                        value = self.img.read_cstr(
                                            str_va, 256)
                                    except Exception:
                                        value = None
                                if not value and slot:
                                    try:
                                        value = self.img.read_cstr(slot, 256)
                                    except Exception:
                                        value = None
                            if isinstance(value, str) and \
                                    re.fullmatch(r'[A-Za-z_]\w*', value):
                                key_sym = ndx_k('const', value)
                            break
                        src = subreg64(p_ops[1])
                        if src is None:
                            break
                        key_reg = src
                        hops += 1
                        if hops > 3:
                            break
            if key_sym is not None:
                value_sym = next((a for a in raw[2:]
                                  if a is not None and a.op != 'tstate'),
                                 None)
                mod_dict = raw[0]
                if mod_dict is not None and mod_dict.op == 'tstate':
                    mod_dict = next((a for a in raw[1:] if a is not None and
                                     a.op not in ('tstate',)), None)
                if mod_dict is not None:
                    return ndx_k('apicall', name,
                                 [mod_dict, key_sym, value_sym])

        if isinstance(arity, int) and arity > 0:
            state = next((arg for arg in args if arg is not None and
                          arg.op == 'tstate'), None)
            operands = [arg for arg in args if arg is not None and
                        arg.op != 'tstate']
            if len(operands) > arity:
                strong = [arg for arg in operands if arg.op not in (
                    'loc', 'gslot', 'gaddr', 'frame', 'excstate',
                    'type_of', 'tp_slot', 'imm')]
                if len(strong) >= arity:
                    operands = strong
            operands = operands[:arity]
            if sop in ('binop', 'cmp', 'unary', 'subscript', 'await'):
                while len(operands) < arity:
                    location = str(name) + ':operand:' + str(len(operands))
                    profile = getattr(getattr(self, 'img', None), '_ndx_binary_abi', None)
                    if profile is not None:
                        profile.unknown(ins.address, location)
                    operands.append(ndx_k('unknown', location, n=ins.address))
            args = ([state] if state is not None else []) + operands

        if sop == 'await':
            awaited = next((arg for arg in args if arg is not None and
                            arg.op != 'tstate'), None)
            return ndx_k('await', awaited)

        if name == 'LIST_RESIZE':
            # Native list append template:
            #   LIST_RESIZE(list, old_size + 1)
            #   ...; items = list->ob_item; items[old_size] = value
            # The final indexed store proves both the append operation and
            # its value; this is independent of source identifiers.
            relevant = [arg for arg in args if arg is not None and
                        arg.op != 'tstate']
            lst = relevant[0] if relevant else None
            position = next((index for index, item in enumerate(self.insns)
                             if item.address == ins.address), None)
            if position is not None and lst is not None:
                future = self.insns[position + 1:position + 14]
                for index, item in enumerate(future):
                    operands = split_ops(item.op_str)
                    if item.mnemonic != 'mov' or len(operands) != 2:
                        continue
                    destination = parse_mem(operands[0])
                    value_register = subreg64(operands[1])
                    if not destination or destination[2] is None or \
                            destination[3] != 8 or value_register is None:
                        continue
                    item_pointer = destination[0]
                    pointer_load = None
                    for previous in reversed(future[:index]):
                        previous_operands = split_ops(previous.op_str)
                        if previous.mnemonic != 'mov' or \
                                len(previous_operands) != 2 or \
                                subreg64(previous_operands[0]) != item_pointer:
                            continue
                        memory = parse_mem(previous_operands[1])
                        if memory and memory[0] and memory[1] == 0x18 and \
                                not memory[2]:
                            pointer_load = memory[0]
                        break
                    if pointer_load is None:
                        continue
                    container = self._reg(pointer_load)
                    value = self._reg(value_register)
                    if container is not None and value is not None and \
                            _sv_eq(container, lst):
                        b.ops.append(NdxOp('append', a=lst, b=value,
                                           va=ins.address))
                        break
            # variante SENZA store indicizzato: dopo il resize il
            # valore viene increfato (``inc [reg]``) e il registro e'
            # riusato dal compilatore.  Backward-scan della definizione
            # del registro increfato fino alla load rip dell'immortale
            # (const_for_slot): se e' una costante stringa, quella e'
            # l'append.  Il fold non puo' piu' fabbricare comprehension
            # su questi loop (guardie adiacenza/auto-iterazione).
            _inc_addr = _inc_reg = None
            for item in self.insns[position + 1: position + 8]:
                inc_ops = split_ops(item.op_str)
                if item.mnemonic == 'inc' and len(inc_ops) == 1:
                    vmem = parse_mem(inc_ops[0])
                    if vmem and vmem[0] and not vmem[2] and vmem[1] == 0:
                        _inc_addr = item.address
                        _inc_reg = vmem[0]
                    break
            if _inc_reg is not None and self.mca is not None:
                _end = next((i2 for i2, it2 in enumerate(self.insns)
                             if it2.address >= _inc_addr), len(self.insns))
                _seen_defs = 0
                for item in reversed(self.insns[:_end]):
                    _ops2 = split_ops(item.op_str)
                    if len(_ops2) != 2 or item.mnemonic != 'mov':
                        continue
                    if subreg64(_ops2[0]) != _inc_reg:
                        continue
                    _seen_defs += 1
                    if _seen_defs > 4 or 'rip' not in _ops2[1]:
                        break
                    _t = rip_target(item)
                    if _t is None:
                        break
                    try:
                        _cval, _which = self.mca.const_for_slot(_t)
                    except Exception:
                        break
                    if isinstance(_cval, str):
                        b.ops.append(NdxOp(
                            'append', a=lst, b=ndx_k('const', _cval),
                            va=ins.address))
                    break
            return None

        # ---- funzioni con effetto statement ----
        if name in ('pushFrameStackCompiledFrame', 'popFrameStack'):
            return None
        if name in ('MAKE_FUNCTION_FRAME', 'MAKE_MODULE_FRAME'):
            return ndx_k('frame')
        # Frame maker SENZA nome (build MinGW/strip senza firme): la prova
        # deterministica è a livello di SITO — l'unica helper Nuitka
        # chiamata con lo SLOT del code object come argomento è la creazione
        # del frame: (tstate, codeobj_slot, module, lineno).
        if self.mca is not None and str(name).startswith('sub_'):
            rel = [a for a in (args or [])
                   if a is not None and a.op != 'tstate']
            if len(rel) >= 3 and rel[0].op == 'gslot':
                code_objects = getattr(self.mca, 'code_objects', None) or {}
                if rel[0].a in code_objects and \
                        rel[2].op in ('const', 'imm') and \
                        isinstance(rel[2].a, int) and \
                        0 < rel[2].a < 1000000:
                    return ndx_k('frame')
        if name == 'makeCodeObject':
            return ndx_k('codeobj_new')
        if name in ('Nuitka_Function_New', 'make_pyfunction'):
            return ndx_k('func_new', None, list(args or []))
        if name in ('FETCH_ERROR_OCCURRED_STATE',):
            return ndx_k('excstate')
        if name in ('EXCEPTION_MATCH_BOOL', 'EXCEPTION_MATCH_BOOL_SINGLE',
                    'PyErr_ExceptionMatches', 'PyErr_GivenExceptionMatches'):
            # argomento rilevante: il tipo/tuple costante
            targs = [a for a in args if a is not None]
            types = next((a.a for a in targs if isinstance(a, NdxSV) and a.op == 'global' and isinstance(a.a, str) and a.a.isidentifier()), None)
            for a in targs:
                if a is not None and a.op == 'const' and a.n == 'const' \
                        and isinstance(a.a, (tuple, type, str)):
                    types = a.a
                    break
            # PyErr_ExceptionMatches(path): cerca const tra gli argomenti
            if types is None:
                for a in targs:
                    if a is not None and a.op == 'const' and \
                            isinstance(a.a, (tuple, type)):
                        types = a.a
                        break
            # il tipo eccezione puo' viaggiare SPILLATO su stack
            # (``mov [rsp+N], type`` prima del test): risolvi lo slot.
            if types is None:
                for a in targs:
                    if a is not None and a.op == 'stackaddr':
                        spilled = self.slot_syms.get(
                            (a.a, getattr(a, 'b', None)))
                        if (isinstance(spilled, NdxSV) and
                                spilled.op in ('global', 'gslot') and
                                isinstance(spilled.a, str) and
                                spilled.a in _BUILTIN_EXCEPTION_NAMES):
                            types = spilled.a
                            break
            sym = ndx_k('exc_match', types)
            self._cond_val = sym
            self._cond_kind = 'int_nonzero'  # res != 0 → match
            return sym
        if name == 'ENABLE_CONSTANT_FUNCTION_RETURN':
            function, value = self._reg('rcx'), self._reg('rdx')
            if isinstance(function, NdxSV) and function.op == 'func_new':
                b.ops.append(NdxOp('function_const_return', a=function, b=value, va=ins.address))
            return None
        if name == 'PUBLISH_CURRENT_EXCEPTION':
            b.ops.append(NdxOp('exc_publish', va=ins.address))
            return None
        if name in ('RERAISE_EXCEPTION',):
            b.ops.append(NdxOp('reraise', va=ins.address))
            return None
        if name == 'NORMALIZE_EXCEPTION_STATE':
            state_pointer = next((argument for argument in args
                                  if isinstance(argument, NdxSV) and
                                  argument.op == 'stackaddr'), None)
            if state_pointer is not None:
                base, offset = state_pointer.a, state_pointer.b
                exception_type = self.slot_syms.get((base, offset))
                exception_value = self.slot_syms.get((base, offset + 8))
                raised = exception_value or exception_type
                if isinstance(raised, NdxSV) and raised.op not in (
                        'tstate', 'frame', 'excstate', 'stackaddr'):
                    b.ops.append(NdxOp('raise', a=raised,
                                       va=ins.address))
            return None
        if name in ('RAISE_EXCEPTION_WITH_TYPE',
                    'RAISE_EXCEPTION_WITH_VALUE',
                    'RAISE_EXCEPTION_WITH_CAUSE'):
            exc = None
            previous = getattr(self, '_last_call', None)
            if previous is not None and previous[1] is not None and \
                    previous[2] and previous[2].startswith(
                        ('CALL_FUNCTION_', 'CALL_METHOD_')):
                exc = previous[1]
            b.ops.append(NdxOp('raise', a=exc, va=ins.address))
            return None
        if name in ('FORMAT_UNBOUND_LOCAL_ERROR', 'FORMAT_UNBOUND_CLOSURE_ERROR'):
            return None
        if name == 'Nuitka_Frame_AttachLocals':
            # ABI: frame, type_description, then one value per co_varname.
            # This is authoritative debug/traceback metadata emitted by
            # Nuitka itself and survives optimisation of source assignments.
            mapping = getattr(self, 'authoritative_loc_names', {})
            for varname, value in zip(self.varnames, args[2:]):
                if value is not None and value.op == 'loc':
                    mapping[value.a] = varname
            self.authoritative_loc_names = mapping
            return None
        if name in ('MAKE_TRACEBACK', 'ADD_TRACEBACK', 'PUBLISH_CURRENT_EXCEPTION',
                    'SET_CURRENT_EXCEPTION', 'GET_CURRENT_EXCEPTION',
                    'PyErr_NormalizeException', 'CHAIN_EXCEPTION',
                    'INIT_ERROR_OCCURRED_STATE'):
            return None
        if name in ('_Py_Dealloc', '_Py_NegativeRefcount', 'Py_FatalError',
                    'abort', 'NuitkaCannotGetHere'):
            return None
        if name in ('_PyObject_GC_Malloc', 'PyObject_GC_Malloc'):
            # A small inline PyObject-vector has source-level tuple semantics
            # (and is also the transport used by the older **mapping ABI).
            # Other direct GC allocations remain runtime machinery.
            return self._gc_inline_pyobject_vector(ins)
        if name in ('Nuitka_Frame_AttachLocals', 'RAISE_CURRENT_EXCEPTION_NAME_ERROR',
                    'RAISE_CURRENT_EXCEPTION_STATE', 'PyErr_CheckSignals',
                    'PyErr_SetString', 'PyErr_Format', 'PyErr_SetObject',
                    'PyErr_SetNone', 'PyErr_Clear', 'PyErr_Restore',
                    'PyTraceBack_Here', 'PyErr_Display', 'PyErr_Print',
                    'PyErr_WriteUnraisable', 'PyErr_CheckSignals',
                    'PyOS_InterruptOccurred', 'CONSIDER_THREADING',
                    'Nuitka_Py_unicodekeys_lookup_unicode',
                    'Nuitka_Py_unicodekeys_lookup',
                    'Nuitka_PyDictLookupStr', 'Nuitka_PyDictLookupNext',
                    'Py_GenericAlias',
                    'SET_CURRENT_EXCEPTION_TYPE_COMPLAINT',
                    'NORMALIZE_EXCEPTION_VALUE_FOR_RAISE',
                    'Nuitka_Err_NormalizeException', 'Nuitka_Type_IsSubtype',
                    'MAKE_STOP_ITERATION_EMPTY', 'Py_MakePendingCalls',
                    'PyEval_SaveThread', 'PyEval_AcquireThread',
                    'PyEval_RestoreThread', 'PyEval_SaveThread',
                     'SET_EXCEPTION_PRESERVATION_STATE_STOP_ITERATION_EMPTY',
                     'Nuitka_PyErr_NormalizeException', 'PyErr_ExceptionMatches',
                     'pushFrameStack', 'popFrameStack'):
            return None
        if name in ('BUILTIN_PRINT',):
            # print(...) — argomenti variabili (calc op lo registra)
            return ndx_k('call', a='print', b=args)
        if name.startswith('BUILTIN_PRINT') and name[12:].isdigit():
            return ndx_k('call', a='print', b=args)

        # ---- costruttori specializzati Nuitka (semantica dal runtime) ----
        # DICT_COPY/Nuitka_PyDict_Copy: materializza una costante dict
        # mutabile → è il dizionale letterale stesso.
        if name in ('DICT_COPY', 'Nuitka_PyDict_Copy', 'DEEP_COPY_DICT'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            for a in rel:
                if a.op == 'const' and isinstance(a.a, dict):
                    return a
            return rel[-1] if rel else None
        # slice: PySlice_New/SLICE_NEW(start, stop, step) → slice(a, b, c)
        if name in ('PySlice_New', 'SLICE_NEW3', 'SLICE_NEW'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            rel = rel[-3:] if len(rel) >= 3 else rel
            return ndx_k('slice', *rel)
        # viste dict: DICT_ITEMS/KEYS/VALUES(tstate, dict) → dict.items()
        if name in ('DICT_ITEMS', 'DICT_KEYS', 'DICT_VALUES'):
            meth = {'DICT_ITEMS': 'items', 'DICT_KEYS': 'keys',
                    'DICT_VALUES': 'values'}[name]
            d = self._pick1(args)
            return ndx_k('mcall', d, meth, [])
        # Inlined PyUnicode_Concat / PyObject_Size (api-via structural
        # verdicts from the resolver): the Python source was ``a + b`` on
        # str and ``len(x)`` — operators/builtins, not calls.
        if sem and sem[0] == 'cached_method':
            owner, method, registers = sem[1]
            operands = [self._reg(register) for register in registers]
            return ndx_k('call', ndx_k('getattr', ndx_k('global', owner), method), operands)
        if sem and sem[0] == 'guided_sequence_copy':
            value = self._reg(self.abi.arg_regs[1])
            if isinstance(value, NdxSV) and value.op == 'const' and \
                    isinstance(value.a, (list, tuple)):
                return ndx_k('const', copy.deepcopy(value.a), n=ins.address)
            return ndx_k('nativecall', name, args)
        if name == 'via:PyUnicode_Concat':
            rel = [a for a in args if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', '+', x, y)
        if name == 'via:PyObject_Size':
            rel = [a for a in args if a is not None and a.op != 'tstate']
            return ndx_k('len', rel[-1] if rel else None)
        # Match di eccezione inlineato (handler ``except Tipo:``): il
        # resolver strutturale classifica l'helper come
        # ``via:PyUnicode_FromString`` (unica API importata), ma da C
        # PyUnicode_FromString prende un ``const char*`` — un sito
        # (tstate, global <EccezioneBuiltin>) puo' essere solo il match di
        # tipo dell'handler.  Reinterpreta come ``exc_match``: e' la forma
        # che ``_find_handlers`` attende per ricostruire try/except.
        if name == 'via:PyUnicode_FromString':
            rel = [a for a in (args or [])
                   if a is not None and a.op != 'tstate']
            if len(rel) == 1 and rel[0].op in ('global', 'gslot') and                     isinstance(rel[0].a, str) and                     rel[0].a in _BUILTIN_EXCEPTION_NAMES:
                sym = ndx_k('exc_match', rel[0].a)
                self._cond_val = sym
                self._cond_kind = 'int_nonzero'
                return sym
        # fast-path long inplace: l'helper digitale interno di Nuitka per
        # int += int ha la semantica del binop '+', non una chiamata.
        # (le firme note sono tre per operazione: inplace con/senza
        # underscore e la variante out-of-place, a seconda della build)
        # Gli operandi viaggiano come DIGIT POINTER (lea rX, [obj + 0x18]):
        # si riporta il simbolo dell'oggetto Python di origine.
        def _unwrap_digit(sp):
            if isinstance(sp, NdxSV) and sp.op == 'digit_ptr':
                return sp.a
            return sp

        if name in ('_Nuitka_LongAddInplaceDigits', 'Nuitka_LongAddDigits',
                    '_Nuitka_LongAddDigits', '_Nuitka_LongAdd',
                    'Nuitka_LongAdd'):
            rel = [_unwrap_digit(a) for a in args
                   if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', '+', x, y)
        if name in ('_Nuitka_LongSubInplaceDigits', 'Nuitka_LongSubDigits',
                    '_Nuitka_LongSubDigits', '_Nuitka_LongSub',
                    'Nuitka_LongSub'):
            rel = [_unwrap_digit(a) for a in args
                   if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', '-', x, y)
        if name in ('_Nuitka_LongMulInplaceDigits', 'Nuitka_LongMulDigits',
                    '_Nuitka_LongMulDigits', 'Nuitka_LongMul'):
            rel = [_unwrap_digit(a) for a in args
                   if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', '*', x, y)
        if name == 'MAKE_FLOAT_FROM_DOUBLE':
            # Letterale double da .rdata caricato in XMM poco prima della
            # call: il sorgente era una costante float esplicita.
            value = self._double_literal_before(ins)
            if value is not None:
                return ndx_k('const', value)
        # SET_SUBSCRIPT equivalente di sequence: target[key] = value
        if name in ('SEQUENCE_SET_ITEM', 'SEQUENCE_SET_ITEM_CONST'):
            d, k, v = self._pick3(args)
            b.ops.append(NdxOp('store_sub', a=d, b=k, c=v, va=ins.address))
            return None
        # creazione generatore con nome noto: è un genexpr/def-generator;
        # il corpo vive nel resumer (discovery separata). Il nome è un
        # qualname: va reso identificatore Python valido.
        if name in ('Nuitka_Generator_New', 'Nuitka_Coroutine_New',
                    'Nuitka_Asyncgen_New'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            nm = next((a.a for a in rel if a.op == 'const' and
                       isinstance(a.a, str) and a.a != '<genexpr>'), None)
            qn = next((a.a for a in rel if a.op == 'const' and
                       isinstance(a.a, str) and '<locals>' in a.a), None)
            import re as _re_gen
            raw = (qn or nm or 'generator')
            ident = _re_gen.sub(r'\W', '_', raw).strip('_') or 'generator'
            return ndx_k('call', a=ident, b=[])

        # isinstance/issubclass C-API dirette
        if name == 'PySequence_Tuple':
            rel = [a for a in args if a is not None and a.op != 'tstate']
            return ndx_k('call', 'tuple', rel)
        if name in ('PyObject_IsInstance', 'PyObject_IsSubclass'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            if len(rel) >= 2:
                sym = ndx_k('call', 'isinstance' if 'IsInstance' in name
                            else 'issubclass', rel[:2])
                self._cond_val = sym
                self._cond_kind = 'int_nonzero'
                return sym
        # membership: PySequence_Contains(a, b) → b in a (rovesciato)
        if name in ('PySequence_Contains', 'SEQUENCE_CONTAINS'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            if len(rel) >= 2:
                sym = ndx_k('contains', rel[0], rel[1])
                self._cond_val = sym
                self._cond_kind = 'int_nonzero'
                return sym

        # ---- iteratori / loop ----
        if name in ('MAKE_ITERATOR', 'PyObject_GetIter'):
            return ndx_k('iter', self._pick1(args))

        if name == 'ITERATOR_NEXT':
            return ndx_k('next', self._pick1(args))
        if name == 'MAKE_UNPACK_ITERATOR':
            return ndx_k('iter2', self._pick1(args))
        if name == 'UNPACK_NEXT':
            # UNPACK_NEXT(tstate,&exc,iter,idx,total)
            it = None
            idx = None
            for a in args:
                if a is not None and a.op in ('iter2', 'iter'):
                    it = a
            # idx è un immediato nel registro corrispondente
            return ndx_k('unpack', it)
        if name == 'UNPACK_ITERATOR_CHECK':
            return None
        if name in ('CHECK_AND_CLEAR_STOP_ITERATION_OCCURRED',):
            return None
        if name == 'ERROR_GET_STOP_ITERATION_VALUE':
            return ndx_k('stopiter_value')

        # ---- contenitori ----
        if name in ('MAKE_DICT_EMPTY', 'PyDict_New',
                    '_PyDict_NewPresized'):
            return ndx_k('dict_empty', n=ins.address)
        if name == 'MAKE_LIST_EMPTY':
            count = next((a.a for a in args if a is not None and
                          a.op == 'imm' and isinstance(a.a, int)), 0)
            count = max(0, min(count, 100000))
            if count:
                values = self.container_values.setdefault(
                    ins.address, [None] * count)
                return ndx_k('list_build', None, values, n=ins.address)
            return ndx_k('list_empty', n=ins.address)
        if name == 'MAKE_TUPLE_EMPTY':
            template = next((a.a for a in args if a is not None and
                             a.op == 'const_size' and
                             isinstance(a.a, NdxSV) and
                             a.a.op == 'const' and
                             isinstance(a.a.a, (tuple, list))), None)
            if template is not None:
                exact_values = [ndx_k('const', value)
                                for value in template.a]
                count = len(exact_values)
            else:
                count = next((a.a for a in args if a is not None and
                              a.op == 'imm' and isinstance(a.a, int)), 0)
                count = max(0, min(count, 100000))
                exact_values = [None] * count
            values = self.container_values.get(ins.address)
            if not isinstance(values, list) or len(values) != count or \
                    template is not None:
                values = exact_values
                self.container_values[ins.address] = values
            return ndx_k('tuple_build', None, values, n=ins.address)
        if name == 'MAKE_SET_EMPTY':
            return ndx_k('set_empty', n=ins.address)
        if name == 'PySet_New':
            # CPython's public API defines PySet_New(NULL) as construction of
            # a new empty set.  Treat the native NULL pointer as absence of a
            # Python iterable; a non-NULL symbolic object is ``set(iterable)``.
            # This is an ABI/API fact and works independently of application
            # constants or the compiler-selected container helper.
            source = self._pick1(args)
            if source is None or (source.op == 'imm' and source.a == 0):
                return ndx_k('set_empty', n=ins.address)
            return ndx_k('call', 'set', [source])
        if name == 'Nuitka_GC_NewVar':
            rel = [a for a in args if a is not None]
            kind = next((a.a for a in rel if a.op == 'api_symbol'), None)
            count = next((a.a for a in rel if a.op == 'imm' and
                          isinstance(a.a, int)), 0)
            if kind == 'PyTuple_Type':
                count = max(0, min(count, 100000))
                values = self.container_values.setdefault(
                    ins.address, [None] * count)
                return ndx_k('tuple_build', None, values, n=ins.address)
        if name in ('_PyObject_New', 'PyObject_New', 'PyObject_Malloc',
                    '_PyObject_Malloc'):
            # costruzione dell'oggetto range: il tipo-costante identifica
            # l'operazione, gli altri argomenti sono i bound
            has_range = any(a is not None and a.op == 'api_symbol' and
                            str(a.a) == 'PyRange_Type' for a in args)
            if has_range:
                rel = [a for a in args if a is not None and
                       a.op not in ('tstate', 'api_symbol')]
                return ndx_k('call', 'range', rel)
        if name == 'Nuitka_GC_New':
            kind = next((a.a for a in args if a is not None and
                         a.op == 'api_symbol'), None)
            if kind == 'PySlice_Type':
                # slice inline: GC_New(PySlice_Type, start, stop, step) —
                # gli argomenti dopo il tipo SONO i bound dello slice.
                rel = [a for a in args if a is not None and
                       a.op not in ('tstate', 'api_symbol')]
                parts = (rel + [None, None, None])[:3]
                return ndx_k('slice', *parts)
            if kind in ('PySeqIter_Type', 'PyCallIter_Type'):
                # iteratore su sequenza: iter(SEQ) — SEQ e' il
                # primo argomento non-tstate non-tipo
                rel = [a for a in args if a is not None and
                       a.op not in ('tstate', 'api_symbol')]
                if not rel:
                    rng = self._scan_range_fields(ins)
                    if rng is not None:
                        return rng
                return ndx_k('iter', rel[0] if rel else None)
            if kind == 'PyList_Type':
                value = ndx_k('list_empty', n=ins.address)
                self.native_allocations = getattr(
                    self, 'native_allocations', [])
                self.native_allocations.append((ins.address, value))
                return value
            if kind in ('PySet_Type', 'PyFrozenSet_Type'):
                value = ndx_k('set_empty', n=ins.address)
                self.native_allocations = getattr(
                    self, 'native_allocations', [])
                self.native_allocations.append((ins.address, value))
                return value
            if kind == 'PyDict_Type':
                value = ndx_k('dict_empty', n=ins.address)
                self.native_allocations = getattr(
                    self, 'native_allocations', [])
                self.native_allocations.append((ins.address, value))
                return value
        if name in ('PyDict_SetItem', 'PyObject_SetItem',
                    'SET_SUBSCRIPT', 'SET_SUBSCRIPT_CONST'):
            d, k, v = self._pick3(args)
            b.ops.append(NdxOp('store_sub', a=d, b=k, c=v, va=ins.address))
            return None
        if name in ('SET_ATTRIBUTE', 'PyObject_SetAttr'):
            o, nm2, v = self._pick3(args)
            if v is not None and v.op == 'loc':
                allocations = [entry for entry in getattr(
                    self, 'native_allocations', [])
                    if 0 <= ins.address - entry[0] <= 0x100]
                if allocations:
                    v = max(allocations, key=lambda entry: entry[0])[1]
            attr = nm2.a if nm2 is not None and nm2.op == 'const' else None
            if isinstance(attr, str):
                b.ops.append(NdxOp('store_attr', a=o, b=attr, c=v,
                                   va=ins.address))
            return None
        if name == 'LIST_COPY_CONST':
            # lista costante specializzata: LIST_COPY(tstate, <const>) —
            # il valore e' la sequenza costante stessa come list display
            src_sym = self._pick1(args)
            if isinstance(src_sym, NdxSV) and src_sym.op == 'const' and \
                    isinstance(src_sym.a, (tuple, list)):
                values = [ndx_k('const', item) for item in src_sym.a]
                return ndx_k('list_build', None, values, n=ins.address)
            return ndx_k('call', 'list', [src_sym] if src_sym else [])
        if name in ('PyList_Append', 'LIST_APPEND', 'LIST_APPEND0',
                    'LIST_APPEND1', 'BUILTIN_LIST_APPEND'):
            lst, val = self._pick2(args)
            b.ops.append(NdxOp('append', a=lst, b=val, va=ins.address))
            return None
        if name in ('PySet_Add', 'SET_ADD'):
            st, val = self._pick2(args)
            b.ops.append(NdxOp('setadd', a=st, b=val, va=ins.address))
            return None

        # ---- subscript ----
        if name in ('LOOKUP_SUBSCRIPT', 'LOOKUP_SUBSCRIPT_CONST',
                    'PyObject_GetItem', 'PyDict_GetItem'):
            o, k = self._pick2(args)
            if isinstance(k, NdxSV) and k.op == 'imm' and \
                    isinstance(k.a, int) and k.a > 0x7fffffffffffffff:
                # Capstone reports a sign-extended x86-64 immediate as its
                # unsigned bit pattern.  At the Python subscript boundary the
                # ABI value is Py_ssize_t, so restore its signed meaning.
                k = ndx_k('imm', k.a - (1 << 64))
            return ndx_k('sub', o, k)
        if name.startswith('DICT_GET_ITEM'):
            o, k = self._pick2(args)
            return ndx_k('sub', o, k)

        # ---- attributi ----
        if name in ('LOOKUP_ATTRIBUTE', 'LOOKUP_ATTRIBUTE_OBJECT',
                    'PyObject_GetAttr'):
            o, nm2 = self._pick2(args)
            if o is None or o.op in ('loc', 'gslot', 'gaddr', 'nativecall'):
                global_name = self._global_name_before(ins.address)
                if global_name:
                    o = ndx_k('global', global_name)
            # il nome è tipicamente una const string
            attr = nm2.a if nm2 is not None and nm2.op == 'const' else None
            if attr is None and nm2 is not None:
                attr = self._const_str_of(nm2)
            return ndx_k('getattr', o, attr)

        if name == 'LOOKUP_BUILTIN':
            key = self._pick1(args)
            if key is not None and key.op == 'const' and \
                    isinstance(key.a, str):
                return ndx_k('global', key.a)
            return ndx_k('sub', ndx_k('global', '__builtins__'), key)

        if name == 'GET_STRING_DICT_VALUE':
            d, k = self._pick2(args)
            key = k.a if k is not None and k.op == 'const' else None
            if isinstance(key, str):
                if d is not None and d.op in ('moddict', 'gslot'):
                    return ndx_k('global', key)
                if d is not None and d.op == 'global':
                    return ndx_k('getattr', d, key)
            return ndx_k('sub', d, k)

        # ---- confronti ----
        if name.startswith('RICH_COMPARE_'):
            mm = re.match(r'^RICH_COMPARE_(EQ|NE|LT|LE|GT|GE)_(NBOOL|CBOOL|OBJECT)?', name)
            o, x, y = None, None, None
            # gli argomenti con semantica: (a, b) — tstate è primo su NBOOL
            rel = [a for a in args if a is not None]
            if len(rel) >= 2:
                x, y = rel[-2], rel[-1]
            opcd = mm.group(1).lower() if mm else 'eq'
            if x is None or y is None:
                repaired = self._repair_name_main_compare(
                    around_va=getattr(ins, 'address', None))
                if repaired is not None:
                    x, y = repaired
            if 'NBOOL' in name:
                self._cond_val = ndx_k('cmp', opcd, x, y)
                self._cond_kind = 'nbool'
                return ndx_k('cmp', opcd, x, y)
            return ndx_k('cmp', opcd, x, y)
        if name in ('TO_BOOL', 'TO_BOOL_IN_BOOL', 'CHECK_IF_TRUE',
                    'PyObject_IsTrue'):
            v = self._pick1(args)
            if name == 'CHECK_IF_TRUE':
                inlined = self._inline_richcompare_before(ins.address)
                if inlined is not None:
                    v = inlined
            sym = ndx_k('bool', v)
            self._cond_val = sym
            self._cond_kind = 'cbool'
            return sym
        if name == 'TO_BOOL_BOOL':
            v = self._pick1(args)
            return ndx_k('bool', v)
        if name == 'SEQUENCE_CONTAINS':
            x, y = self._pick2(args)
            return ndx_k('cmp', 'in', x, y)

        # ---- binop ----
        normalized_name = name.lstrip('_')
        inplace_match = re.match(
            r'^INPLACE_OPERATION_(ADD|SUB|MULT|MUL|TRUEDIV|FLOORDIV|MOD|'
            r'LSHIFT|RSHIFT|AND|OR|XOR)(?:_|$)', normalized_name)
        if inplace_match:
            operator = {
                'ADD': '+', 'SUB': '-', 'MULT': '*', 'MUL': '*',
                'TRUEDIV': '/', 'FLOORDIV': '//', 'MOD': '%',
                'LSHIFT': '<<', 'RSHIFT': '>>', 'AND': '&',
                'OR': '|', 'XOR': '^',
            }[inplace_match.group(1)]
            relevant = [arg for arg in args if arg is not None and
                        arg.op != 'tstate']
            pointer = next((arg for arg in relevant
                            if arg.op == 'stackaddr'), None)
            right = next((arg for arg in reversed(relevant)
                          if arg is not pointer), None)
            left = None
            location = None
            authoritative_location = None
            if pointer is not None:
                location = (pointer.a, pointer.b)
                left = self.slot_syms.get(location)
                physical_location = ('mem',) + tuple(location)
                authoritative = getattr(
                    self, 'authoritative_loc_names', {}) or {}
                aliases = set()
                for locations in self.symbol_locations.values():
                    if physical_location in locations:
                        aliases.update(loc for loc in locations
                                       if loc in authoritative)
                if len(aliases) == 1:
                    authoritative_location = next(iter(aliases))
                    left = ndx_k('loc', authoritative_location)
            if left is None and len(relevant) >= 2:
                left = relevant[-2]
            value = ndx_k('binop', operator, left, right, n='inplace')
            if location is not None:
                self._store_slot(location[0], location[1], value)
                b.ops.append(NdxOp('store',
                                   a=(authoritative_location or
                                      ('mem',) + tuple(location)), b=value,
                                   va=ins.address))
            return value
        if normalized_name.startswith(('BINARY_OPERATION_', 'BINARY_OP_')):
            rel = [a for a in args if a is not None]
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            # backward-recovery diretto: le load ABI degli argomenti
            # (`mov rcx, SRC; mov rdx, SRC; call`) sono ADIACENTI alla
            # call. SRC risolto tramite gli store semantici del lifter
            # (i risultati delle call precedenti in callee-saved) —
            # niente finestre ricorsive.
            def _adjacent_arg(reg32):
                if ins is None:
                    return None
                idx = next((i3 for i3, it in enumerate(self.insns)
                            if it.address == ins.address), None)
                if idx is None:
                    return None
                for it in reversed(self.insns[max(0, idx - 6):idx]):
                    ops2 = split_ops(it.op_str)
                    if it.mnemonic == 'mov' and len(ops2) == 2 and                             subreg64(ops2[0]) == reg32:
                        s2 = subreg64(ops2[1])
                        if s2 is None:
                            return None
                        # store semantico più recente per SRC
                        best = (0, None)
                        for blk in self.blocks.values():
                            for op2 in blk.ops:
                                if op2.kind == 'store' and                                         op2.a == ('reg', s2) and                                         op2.b is not None and                                         op2.va is not None and                                         op2.va < it.address:
                                    if op2.va > best[0]:
                                        best = (op2.va, op2.b)
                        if best[1] is not None:
                            return best[1]
                        # catena di copia: `mov SRC, SRC2`
                        for it2 in reversed(self.insns[
                                max(0, next(
                                    (i4 for i4, x2 in enumerate(self.insns)
                                     if x2.address == it.address), 0) - 12):]):
                            ops3 = split_ops(it2.op_str)
                            if it2.mnemonic == 'mov' and len(ops3) == 2                                     and subreg64(ops3[0]) == s2:
                                s3 = subreg64(ops3[1])
                                if s3 is None:
                                    return None
                                best3 = (0, None)
                                for blk in self.blocks.values():
                                    for op3 in blk.ops:
                                        if op3.kind == 'store' and                                                 op3.a == ('reg', s3) and                                                 op3.b is not None and                                                 op3.va is not None and                                                 op3.va < it2.address:
                                            if op3.va > best3[0]:
                                                best3 = (op3.va, op3.b)
                                if best3[1] is not None:
                                    return best3[1]
                                return None
                        return None
                return None

            if x is None:
                got = _adjacent_arg(self.abi.arg_regs[0])
                if got is not None:
                    x = got
            if y is None:
                got = _adjacent_arg(self.abi.arg_regs[1])
                if got is not None:
                    y = got
            opc = self._binop_code(normalized_name)
            return ndx_k('binop', opc, x, y)
        if name == 'PyLong_FromSsize_t':
            value = self._pick1(args)
            if value is not None and value.op == 'native_ssize':
                return value.a
            return ndx_k('nativecall', name,
                         [value] if value is not None else [])
        if name == 'PyFloat_FromString':
            value = self._pick1(args)
            return ndx_k('call', 'float', [value] if value else [])
        if name.startswith('PyNumber_'):
            base = name.split('PyNumber_')[-1]
            # Le forme outlined MinGW portano l'operatore come simbolo
            # (es. PyNumber_*_outlined): stesso trattamento delle API.
            if base.endswith('_outlined'):
                base = base[:-len('_outlined')]
            unary_map = {'Negative': ('-', 'neg'), 'Invert': ('~', 'inv'),
                         'Absolute': (None, 'abs'), 'Index': (None, 'index'),
                         'Int': (None, 'int'), 'Long': (None, 'int'),
                         'Float': (None, 'float'), 'Positive': ('+', 'pos')}
            if base in unary_map:
                opc, fn = unary_map[base]
                v = self._pick1(args)
                if opc:
                    return ndx_k('unary', opc, v)
                return ndx_k('call', fn, [v] if v else [])
            opc = {'Add': '+', 'Subtract': '-', 'Multiply': '*',
                   'TrueDivide': '/', 'FloorDivide': '//', 'Remainder': '%',
                   'Power': '**', 'Lshift': '<<', 'Rshift': '>>',
                   'And': '&', 'Or': '|', 'Xor': '^',
                   '+': '+', '-': '-', '*': '*', '%': '%',
                   '<<': '<<', '>>': '>>', '&': '&', '^': '^',
                   '|': '|'}.get(base, '?')
            rel = [a for a in args if a is not None]
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', opc, x, y)
        if name in ('PyObject_Str', 'PyObject_Bytes'):
            return ndx_k('call', 'str', [self._pick1(args)])
        if name == 'PyObject_Repr':
            return ndx_k('call', 'repr', [self._pick1(args)])
        if name in ('PyObject_ASCII',):
            return ndx_k('call', 'ascii', [self._pick1(args)])
        # _PyType_Lookup(type, name): lookup outlined dell'attributo sul
        # tipo (LOOKUP_ATTRIBUTE / protocollo with).  Da sola non è
        # sorgente: quando la call indiretta successiva la consuma come
        # callee (reg_dispatch in _exec_call) la coppia diventa la method
        # call ``obj.name(...)``; altrimenti resta una lettura di
        # attributo legittima.
        if name == '_PyType_Lookup':
            rel = [a for a in args if isinstance(a, NdxSV) and
                   a.op not in ('tstate', 'imm', 'none')]
            obj = None
            for a in rel:
                if a.op == 'type_of':
                    obj = a.a
                    break
            if obj is None and rel:
                obj = rel[0]
            nm = next((a.a for a in args if isinstance(a, NdxSV) and
                       a.op == 'const' and isinstance(a.a, str)), None)
            sv = ndx_k('getattr', obj, nm)
            self._pending_method = (obj, nm, sv) if (
                obj is not None and nm) else None
            return sv

        # ---- builtin note ----
        if name in ('BUILTIN_FORMAT', 'FORMAT_VALUE'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            value = rel[0] if rel else None
            spec = rel[1] if len(rel) > 1 else ndx_k('const', '')
            return ndx_k('format', value, spec)
        if name.startswith('BUILTIN_') and \
                name not in ('BUILTIN___IMPORT__',):
            base = name[8:]
            base = re.sub(r'\d+$', '', base)
            pyname = base.lower()
            if pyname in ('len', 'range', 'iter', 'next', 'type', 'abs',
                          'sum', 'min', 'max', 'sorted', 'repr', 'str',
                          'int', 'float', 'bool', 'list', 'dict', 'tuple',
                          'set', 'bytes', 'any', 'all', 'enumerate', 'zip',
                          'map', 'filter', 'hash', 'hex', 'oct', 'bin',
                          'chr', 'ord', 'round', 'format', 'input', 'open',
                          'isinstance', 'issubclass', 'getattr', 'setattr',
                          'hasattr', 'print', 'super'):
                rel = [a for a in args if a is not None]
                # drop tstate
                rel = [a for a in rel if not (a.op == 'tstate')]
                if pyname == 'len':
                    return ndx_k('len', rel[-1] if rel else None)
                if name == 'BUILTIN_SUPER0':
                    return ndx_k('super', [])
                if pyname == 'super':
                    return ndx_k('super', rel)
                return ndx_k('call', a=pyname, b=rel)
            return ndx_k('call', a=base.lower(), b=args)

        # ---- error-path outlined (GCC cold-path) ----
        # GCC separa la formattazione degli errori in funclet: la call porta
        # (frame, <costante stringa in .rdata>, args...). La costante è il
        # MESSAGGIO d'eccezione: è il percorso d'errore di una chiamata già
        # emessa, non codice utente → soppresso.
        if str(name).startswith('sub_'):
            rel = [a for a in (args or [])
                   if a is not None and a.op != 'tstate']
            if len(rel) >= 2 and rel[0].op == 'frame' and \
                    rel[1].op == 'gaddr':
                try:
                    target_exec = self.img.is_exec(rel[1].a)
                except Exception:
                    target_exec = True
                if not target_exec:
                    return None
        # ---- thunk di rilascio refcount ( outlined ) ----
        # Piccolo leaf che decrementa lo slot del frame e fa il tail-jmp al
        # tp_dealloc: puro machinery, nessuna semantica Python.
        if name == 'REFCOUNT_RELEASE_SLOT':
            return None
        # ---- lookup di un builtin per nome ( outlined ) ----
        # Il nome arriva come costante stringa: è un caricamento dal
        # dizionario builtins → variabile globale Python.
        if name == 'LOOKUP_BUILTIN':
            for a in (args or []):
                if a is not None and a.op == 'const' and \
                        isinstance(a.a, str) and a.a.isidentifier():
                    return ndx_k('global', a.a)
            return None
        # ---- concatenazione liste outlined ----
        # Legge ob_size di due argomenti, li somma e alloca la lista: è il
        # lowering nativo di ``list1 + list2``.
        if name == 'LIST_CONCAT':
            rel = [a for a in args if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', '+', x, y)
        # ---- factory di interi piccoli outlined ----
        # Leaf con cache per-valore e cold-path di allocazione: è il
        # lowering nativo di una costante intera; il valore è l'ultimo
        # argomento intero della chiamata (sub_…(_tstate(), 2) → 2).
        if name == 'SMALL_INT_FACTORY':
            rel = [a for a in args if a is not None and a.op != 'tstate']
            for a in reversed(rel):
                if a.op == 'const' and isinstance(a.a, int) and \
                        not isinstance(a.a, bool):
                    return ndx_k('const', a.a)
            return None
        # ---- machinery del runtime outlined (universale MinGW) ----
        # GIL wrapper, builder di stringa in-place, allocatori di oggetti
        # runtime (closure cell / frame / generator / traceback via
        # tp_name statico), dispatch di slot (tp_iternext outlined) e
        # swap dello stato eccezione: nessuna controparte sorgente.
        if name == 'GIL_WRAPPER' or name == 'STR_INPLACE_APPEND' or \
                str(name).startswith('RUNTIME_ALLOC_') or \
                name in ('SLOT_DISPATCH', 'STATE_SWAP', 'GET_ITER_FUNC',
                         'CONST_LIST_LOAD', 'RUNTIME_FIELD_CLEAR',
                         'EXCEPTION_MATCH', 'BUILDER_APPEND'):
            return None
        # ---- struct-init runtime senza nome leggibile ----
        # È comunque la MAKE_FUNCTION outlined (costruttore del
        # compiled_function): conserva il bind nome←funzione invece di
        # far sparire la riga dal sorgente.
        if name == 'RUNTIME_STRUCT_INIT':
            return ndx_k('call', a='make_function', b=[])
        # ---- MAKE_FUNCTION outlined (MinGW) ----
        # Il costruttore riceve la PyMethodDef statica: il nome del
        # metodo/funzione è recuperato dal .rdata. Il def vero viene
        # ricostruito dal class-detection; qui si conserva il bind
        # nome←funzione in forma esplicita e valida.
        if str(name).startswith('MAKE_FUNCTION:'):
            _fnm = str(name).split(':', 1)[1]
            return ndx_k('call', a='make_function',
                         b=[ndx_k('const', _fnm)])
        # ---- list.reverse() outlined ----
        if name == 'LIST_REVERSE':
            rel = [a for a in args if a is not None and a.op != 'tstate']
            lst = rel[0] if rel else None
            return ndx_k('call', a=ndx_k('getattr', lst, 'reverse'), b=[])
        # ---- operatori numerici / confronti outlined (MinGW) ----
        # PyNumber_<op> specializzati: l'operatore è determinato dallo
        # slot tp_as_number letto nel corpo (o dai branch di borrow).
        if str(name).startswith('PyNumber_') and name.endswith('_outlined'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', arity if isinstance(arity, str) else '+',
                         x, y)
        if str(name).startswith('RICH_COMPARE_'):
            _RK = {'LT': 'lt', 'LE': 'le', 'EQ': 'eq', 'NE': 'ne',
                   'GT': 'gt', 'GE': 'ge'}
            key = _RK.get(str(name)[len('RICH_COMPARE_'):])
            rel = [a for a in args if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            if key:
                return ndx_k('cmp', key, x, y)
        # ---- concatenazione unicode outlined → ``a + b`` ----
        if name == 'UNICODE_CONCAT':
            rel = [a for a in args if a is not None and a.op != 'tstate']
            x, y = (rel[-2], rel[-1]) if len(rel) >= 2 else (None, None)
            return ndx_k('binop', '+', x, y)
        # ---- chiamata con keyword arguments ----
        if name == 'IMPORT_NAME_OR_MODULE':
            # (tstate, module, globals, name, level): getattr with an
            # import fallback — the value producer of ``from M import n``.
            rel = [a for a in args if not (a is not None and a.op == 'tstate')]
            module = rel[0] if rel else None
            nm = next((a for a in rel[1:] if a is not None and
                       a.op == 'const' and isinstance(a.a, str)), None)
            if module is not None and nm is not None:
                return ndx_k('getattr', module, nm.a)
        if name == 'DICT_MERGE_WITH_ARGS2':
            rel = [a for a in args if not (
                a is not None and a.op == 'tstate')]
            rel = self._expand_stack_args(rel, ins)
            # ABI array: [callable-for-error-reporting, tuple-of-mappings].
            # The callable is diagnostic context, not a mapping operand.
            transport = rel[1] if len(rel) > 1 else None
            if isinstance(transport, NdxSV) and transport.op in (
                    'tuple_build', 'list_build'):
                mappings = [value for value in (transport.b or [])
                            if value is not None and not (
                                value.op == 'imm' and value.a == 0)]
            else:
                mappings = [transport] if transport is not None else []
            return ndx_k('dict_merge', None, mappings)
        if name in ('CALL_FUNCTION_WITH_KW_ARGS2',
                    'CALL_FUNCTION_WITH_KW_ARGS3_MERGE'):
            rel = [a for a in args if not (
                a is not None and a.op == 'tstate')]
            rel = self._expand_stack_args(rel, ins)
            if not rel:
                return ndx_k('call', None, [])
            callable_value = rel[0]
            # C signature: CALL_FUNCTION(tstate, called, pos_args, kw_dict).
            # In the array ABI the operands after the callable keep that
            # exact order, each being NULL when absent.  The FIRST operand
            # is therefore the positional vector and the SECOND the keyword
            # mapping — a dynamic sequence there is a source ``*args``
            # spread, never ``**``.  Only a dict-typed operand is keywords.
            def _is_mapping(value):
                return isinstance(value, NdxSV) and value.op in (
                    'dict_empty', 'dict_merge')

            def _is_null(value):
                return value is None or (
                    isinstance(value, NdxSV) and value.op == 'imm' and
                    value.a == 0)

            operands = [value for value in rel[1:]
                        if not _is_null(value)]
            positional_node = None
            keyword_node = None
            if operands:
                if _is_mapping(operands[0]):
                    keyword_node = operands[0]     # only-kwargs form
                else:
                    positional_node = operands[0]  # *args form
                    if len(operands) > 1 and _is_mapping(operands[1]):
                        keyword_node = operands[1]
            if positional_node is not None or keyword_node is not None:
                positional = []
                if positional_node is not None:
                    if positional_node.op == 'const' and \
                            isinstance(positional_node.a, (tuple, list)):
                        # constant positional arguments: plain arguments
                        positional = [ndx_k('const', item)
                                      for item in positional_node.a]
                    else:
                        # dynamic sequence: the source used ``*expr``
                        positional = [ndx_k('star', positional_node)]
                keyword_parts = (
                    self._dict_keyword_parts(keyword_node, ins.address)
                    if keyword_node is not None else [])
                return ndx_k('kwcall', a=callable_value, b=positional,
                             c=keyword_parts)
            mappings = rel[1:]
            mapping = (mappings[0] if len(mappings) == 1 else
                       ndx_k('dict_merge', None, mappings))
            keyword_parts = self._dict_keyword_parts(mapping, ins.address)
            return ndx_k('kwcall', callable_value, [], keyword_parts)
        # Costruisce il dict kwargs da chiavi-tupla + valori su array di
        # stack. Se le chiavi coincidono coi PARAMETRI della funzione
        # corrente è il dict locals del frame (machinery), non una
        # chiamata: la tupla può comparire sia in testa sia in coda
        # (convenzione MinGW), il callable è il primo argomento non
        # chiavi/non stack.
        if name == 'CALL_WITH_KWARGS':
            rel = [a for a in args if not (a is not None and a.op == 'tstate')]
            # Vectorcall KW_SPLIT ABI: (tstate, callable, pos_args,
            # kw_values*, kw_names).  The keyword VALUES arrive through a
            # stack-address array pointer while the NAMES tuple rides in
            # the Win64 fifth-argument stack slot (SysV: the register
            # following the pointer).  Pair names with values BEFORE any
            # generic stack expansion: expanding the pointer first would
            # flatten the value array into ordinary arguments and disguise
            # this form as a register-carried mapping, silently dropping
            # the ``name=`` pairing (e.g. a single ``params=<dict>``
            # keyword degenerating into the dict's own keys).
            values_pointer = next((value for value in rel
                                   if value is not None and
                                   value.op == 'stackaddr'), None)
            if values_pointer is not None:
                pointer_index = rel.index(values_pointer)

                def _identifier_tuple(value):
                    return value is not None and value.op == 'const' and \
                        isinstance(value.a, tuple) and value.a and \
                        all(isinstance(key, str) and key.isidentifier()
                            for key in value.a)

                names_candidate = next(
                    (value for value in rel[pointer_index + 1:]
                     if _identifier_tuple(value)), None)
                if names_candidate is None and self.img.fmt == 'pe':
                    _slot_names = self.slot_syms.get(('rsp', 0x20))
                    if _identifier_tuple(_slot_names):
                        names_candidate = _slot_names
                if names_candidate is not None:
                    # Il dict locals del frame (machinery di traceback)
                    # usa come nomi esattamente i parametri della funzione
                    # corrente e non ha argomenti posizionali: non è una
                    # chiamata Python.
                    _frame_locals = set(self.varnames or ())
                    positional_node = next(
                        (value for value in rel[:pointer_index]
                         if value is not None and value.op == 'const' and
                         isinstance(value.a, (tuple, list))), None)
                    if _frame_locals and positional_node is None and \
                            set(names_candidate.a) <= _frame_locals:
                        names_candidate = None
                if names_candidate is not None:
                    kw_values = self._expand_argument_array(
                        values_pointer, len(names_candidate.a))
                    if len(kw_values) == len(names_candidate.a) and \
                            all(value is not None
                                for value in kw_values):
                        callee = next(
                            (value for value in rel
                             if value is not None and
                             value is not values_pointer and
                             value is not names_candidate and
                             value is not positional_node), None)
                        if callee is not None:
                            positional = (
                                [ndx_k('const', item)
                                 for item in positional_node.a]
                                if positional_node is not None else [])
                            kw_nodes = [
                                ndx_k('kwarg', key, value)
                                for key, value in zip(names_candidate.a,
                                                      kw_values)]
                            return ndx_k('kwcall', a=callee, b=positional,
                                         c=kw_nodes)
            rel = self._expand_stack_args(rel, ins)
            # MinGW's mapping form carries a tuple of positional values and a
            # separately built kwargs dict.  A tuple of strings is therefore
            # not necessarily ``kwnames`` (a URL or any other positional
            # string is a common counterexample).  Prefer the concrete dict
            # construction when its preceding SetItem operations prove the
            # keyword names and values.
            mapping_node = next((value for value in rel
                                 if isinstance(value, NdxSV) and
                                 value.op in ('dict_empty', 'dict_merge')),
                                None)
            positional_node = next((value for value in rel
                                    if isinstance(value, NdxSV) and
                                    value.op == 'const' and
                                    isinstance(value.a, (tuple, list))),
                                   None)
            if mapping_node is not None:
                keyword_parts = self._dict_keyword_parts(
                    mapping_node, ins.address)
                if any(isinstance(part, NdxSV) and
                       part.op == 'kwarg' for part in keyword_parts):
                    callee = next((value for value in rel
                                   if isinstance(value, NdxSV) and
                                   value is not mapping_node and
                                   value is not positional_node and
                                   value.op != 'stackaddr'), None)
                    positional = ([ndx_k('const', value)
                                   for value in positional_node.a]
                                  if positional_node is not None else [])
                    if callee is not None:
                        return ndx_k('kwcall', a=callee, b=positional,
                                     c=keyword_parts)
            kw_keys = None
            kw_names_node = None
            for a in reversed(rel):
                if getattr(a, 'op', None) == 'const' and \
                        isinstance(getattr(a, 'a', None), tuple):
                    kw_keys = [k for k in a.a if isinstance(k, str)]
                    kw_names_node = a
                    break
            if kw_keys:
                _params = set(self.varnames or ())
                if _params and set(kw_keys) <= _params:
                    return None
                # Vectorcall ABI: one pointer denotes all positional values
                # followed by the values named by ``kwnames``.  Preserve the
                # complete constant/inline vector and split it by the exact
                # keyword-name tuple length.  This covers both immutable tuple
                # templates and stack/heap vectors without knowing any source
                # identifier or call-site arity in advance.
                vector_node = next((a for a in rel if a is not None and
                                    a is not kw_names_node and a.op in (
                                        'const_array', 'tuple_build',
                                        'list_build') or
                                    (a is not None and a is not kw_names_node
                                     and a.op == 'const' and
                                     isinstance(a.a, (tuple, list)))), None)
                vector_values = None
                if vector_node is not None:
                    if vector_node.op == 'const_array':
                        start = int(vector_node.b or 0)
                        vector_values = [ndx_k('const', value)
                                         for value in vector_node.a[start:]]
                    elif vector_node.op in ('tuple_build', 'list_build'):
                        vector_values = list(vector_node.b or [])
                    elif vector_node.op == 'const':
                        vector_values = [ndx_k('const', value)
                                         for value in vector_node.a]
                callee = next((a for a in rel if a is not None and
                               a is not kw_names_node and a is not vector_node
                               and a.op != 'stackaddr'), None)
                if callee is not None and vector_values is not None and \
                        len(vector_values) >= len(kw_keys):
                    if isinstance(getattr(vector_node, 'n', None), NdxSV):
                        self.consumed_argument_vectors.add(id(vector_node.n))
                    elif vector_node.op in ('tuple_build', 'list_build'):
                        self.consumed_argument_vectors.add(id(vector_node))
                    positional_count = len(vector_values) - len(kw_keys)
                    positional = vector_values[:positional_count]
                    keyword_values = vector_values[positional_count:]
                    keywords = [ndx_k('kwarg', key, value)
                                for key, value in zip(kw_keys,
                                                      keyword_values)]
                    return ndx_k('kwcall', a=callee, b=positional,
                                 c=keywords)
                callee = None
                vals = []
                for a in rel:
                    if a is None:
                        continue
                    if getattr(a, 'op', None) == 'const' and \
                            isinstance(getattr(a, 'a', None), tuple):
                        continue
                    if getattr(a, 'op', None) == 'stackaddr':
                        continue
                    if callee is None:
                        callee = a
                    else:
                        vals.append(a)
                if callee is not None:
                    kwn = [ndx_k('kwarg', k, v) for k, v in
                           zip(kw_keys, vals) if v is not None]
                    extra = vals[len(kw_keys):]
                    return ndx_k('kwcall', a=callee, b=extra, c=kwn)
                return None
            return ndx_k('call', a=None, b=rel)

        # ---- chiamate ----
        # CALL_METHOD_*: (tstate, instance, method_name, args...) → obj.m(a)
        # CALL_FUNCTION_*: (tstate, callable, args...) → f(a)
        if name.startswith('CALL_FUNCTION_WITH_') or \
                name.startswith('CALL_METHOD_WITH_'):
            rel = (list(args) if positional_tuple_call else
                   [a for a in args if a is not None and a.op != 'tstate'])
            # callable recovery: se rel[0] è assente/primitivo ma la load
            # ABI adiacente (`mov rcx, SRC`) risolve a uno store semantico,
            # quello è il callable (il machinery d'errore intermedio può
            # aver inquinato il registro nel tracking).
            if ins is not None and (
                    not rel or rel[0] is None or
                    (rel[0].op == 'imm')):
                idx3 = next((i4 for i4, it in enumerate(self.insns)
                             if it.address == ins.address), None)
                if idx3 is not None:
                    for it in reversed(self.insns[max(0, idx3 - 6):idx3]):
                        ops2 = split_ops(it.op_str)
                        if it.mnemonic == 'mov' and len(ops2) == 2 and \
                                subreg64(ops2[0]) == self.abi.arg_regs[0]:
                            s2 = subreg64(ops2[1])
                            if s2 is not None:
                                best = (0, None)
                                for blk in self.blocks.values():
                                    for op2 in blk.ops:
                                        if op2.kind == 'store' and \
                                                op2.a == ('reg', s2) and \
                                                op2.b is not None and \
                                                op2.va is not None and \
                                                op2.va < it.address:
                                            if op2.va > best[0]:
                                                best = (op2.va, op2.b)
                                if best[1] is not None:
                                    if rel:
                                        rel[0] = best[1]
                                    else:
                                        rel = [best[1]]
                            break
            is_method = 'METHOD' in name
            # correzione deterministica dall'arity osservata: se l'argomento
            # di posizione 1 è una costante stringa, è il nome del metodo
            if is_method and len(rel) >= 2:
                obj, mname = rel[0], rel[1]
                cargs = rel[2:]
                # V100: un nome-metodo è SEMPRE una stringa del pool
                # costanti.  Una tupla/lista costante in quella posizione
                # è il vettore argomenti della vectorcall (la tuple const
                # il cui item-vector passa nel name-slot dell'helper):
                # la chiamata è ``obj(elem, ...)`` (pattern costruttore
                # ``QLabel('...')``), mai un metodo con nome-tupla.
                if mname is not None and \
                        getattr(mname, 'op', None) == 'const' and \
                        isinstance(mname.a, (tuple, list)) and \
                        obj is not None:
                    _spread = [ndx_k('const', _v)
                               for _v in mname.a if _v is not None]
                    return ndx_k('call', obj, _spread + list(cargs))
                if len(cargs) == 1 and cargs[0] is not None and \
                        cargs[0].op == 'stackaddr':
                    cargs = self._expand_stack_args(cargs, ins)
                # Generic-subscript template tail (subscripts.h): the
                # PyType_Check arm looks up ``__class_getitem__`` and calls
                # it with the subscript.  The template as a whole IS the
                # Python operation ``source[key]``; never a user-level
                # method call on a dunder.
                if mname is not None and getattr(mname, 'op', None) == \
                        'const' and mname.a == '__class_getitem__':
                    return ndx_k('sub', obj,
                                 cargs[0] if cargs else None)
                # An unresolved OBJECT register (spill/reload or a self
                # phi) may still carry a proven module global: the same
                # data-flow proof used for plain attribute lookups — the
                # ABI object register must be fed by the global's own
                # lookup — makes this exact, never a proximity guess.
                # Bound-method chains surface the original object one
                # level down (``global.m(...)`` as the callee of ``.m2``),
                # so probe through a single call wrapper as well.
                def _probe_global(node):
                    if not isinstance(node, NdxSV):
                        return None
                    if node.op in ('loc', 'gslot', 'gaddr', 'nativecall'):
                        return self._global_name_before(ins.address)
                    if node.op == 'call' and \
                            isinstance(node.a, NdxSV):
                        return _probe_global(node.a)
                    return None

                if obj is not None:
                    proven_global = _probe_global(obj)
                    if proven_global:
                        obj = ndx_k('global', proven_global)
                # obj non tracciato (spill/ricarico non visibile): il nome
                # del metodo è noto → chiamata qualificata dal nome
                if obj is None and mname is not None and \
                        mname.op == 'const' and isinstance(mname.a, str):
                    return ndx_k('call', mname.a, cargs)
                return ndx_k('mcall', obj, mname, cargs)
            fn = rel[0] if rel else None
            # Generic-subscript template tail (subscripts.h): the
            # PyType_Check arm lowers ``source[key]`` to
            # ``LOOKUP_ATTRIBUTE(source, '__class_getitem__')`` followed by
            # this call.  Rebuild the subscript; the dunder lookup is
            # machine machinery, not source.
            if fn is not None and fn.op == 'getattr' and \
                    fn.b == '__class_getitem__':
                return ndx_k('sub', fn.a, rel[1] if len(rel) > 1 else None)
            global_name = self._global_name_before(ins.address)
            if global_name is None:
                global_name = self._cached_builtin_name_before(ins.address)
            if global_name and (fn is None or fn.op in ('loc', 'gslot',
                                                        'gaddr', 'nativecall')):
                fn = ndx_k('global', global_name)
            cargs = rel[1:]
            if '_POS_ARGS' in name and len(cargs) == 1 and \
                    cargs[0] is not None and cargs[0].op == 'const' and \
                    isinstance(cargs[0].a, tuple):
                cargs = [ndx_k('const', value, n='const')
                         for value in cargs[0].a]
            # The generic MSVC dispatcher carries an unencoded-length vector
            # in r8.  At a proven stack-address argument, the contiguous stores
            # immediately preceding the call are the vector's authoritative
            # contents; expansion stops at the first unwritten slot.  Named
            # ARGS<n> variants below retain their stricter exact-count path.
            if not re.search(r'ARGS\d+', name) and len(cargs) == 1 and cargs[0] is not None and \
                    cargs[0].op == 'stackaddr':
                cargs = self._expand_stack_args(cargs, ins)
            if '_KW_SPLIT' in name and len(rel) >= 3:
                count_match = re.search(r'ARGS(\d+)', name)
                pos_count = int(count_match.group(1)) if count_match else 0
                no_positional = 'NO_ARGS_KW_SPLIT' in name
                pos_args = ([] if no_positional else
                            self._expand_argument_array(rel[1], pos_count))
                # Win64: ARGS<n> has a fifth kwnames argument on the
                # stack; NO_ARGS uses r9 for kwnames and r8 for values.
                names_sym = (rel[2] if no_positional else
                             self.slot_syms.get(('rsp', 0x20)))
                kw_names = (names_sym.a if names_sym is not None and
                            names_sym.op == 'const' and
                            isinstance(names_sym.a, tuple) else ())
                values_pointer = rel[1] if no_positional else rel[2]
                kw_values = self._expand_argument_array(
                    values_pointer, len(kw_names))
                if kw_names and len(kw_values) == len(kw_names):
                    kw_nodes = [ndx_k('kwarg', key, value)
                                for key, value in zip(kw_names, kw_values)]
                    return ndx_k('kwcall', fn, pos_args, kw_nodes)
                if kw_names:
                    # The keyword VALUES are not always behind a stack/const
                    # array pointer: MSVC also passes them inline in registers,
                    # in which case _expand_argument_array finds nothing and
                    # the call would degrade to a positional one carrying the
                    # kwnames tuple as a bogus argument. Take the nodes that
                    # sit in the keyword-value region (after the positional
                    # args, excluding the kwnames constant) instead.
                    region = rel[1:] if no_positional else rel[2:]
                    inline = [a for a in region
                              if a is not None and a is not names_sym
                              and a.op not in ('tstate', 'stackaddr')]
                    if len(inline) == len(kw_names):
                        kw_nodes = [ndx_k('kwarg', key, value)
                                    for key, value in zip(kw_names, inline)]
                        return ndx_k('kwcall', fn, pos_args, kw_nodes)
                    if names_sym is not None and names_sym in cargs:
                        # Never emit the kwnames tuple as a positional
                        # argument; it is call ABI metadata, not a value.
                        cargs = [a for a in cargs if a is not names_sym]
            # MSVC CALL_FUNCTION_WITH_ARGSn receives a pointer to a contiguous
            # PyObject* array.  Preserve stack LEA provenance and materialise
            # those arguments from the symbolic stack slots.
            count_match = re.search(r'ARGS(\d+)', name)
            if count_match and len(rel) >= 2 and rel[1].op == 'stackaddr':
                count = int(count_match.group(1))
                base = rel[1].a
                offset = rel[1].b
                expanded = [self.slot_syms.get((base, offset + 8 * i))
                            for i in range(count)]
                if expanded and (expanded[0] is None or
                                 expanded[0].op == 'loc'):
                    producers = [
                        operation for block in self.blocks.values()
                        for operation in block.ops
                        if operation.kind == 'calc' and
                        operation.a is not None and
                        operation.a.op == 'binop' and
                        operation.va is not None and
                        0 < ins.address - operation.va <= 0x300]
                    if producers:
                        expanded[0] = max(
                            producers, key=lambda operation: operation.va).a
                if any(a is not None for a in expanded):
                    cargs = expanded
            return ndx_k('call', fn, cargs)
        if name in ('CALL_FUNCTION_NO_ARGS', 'CALL_METHOD_NO_ARGS'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            if 'METHOD' in name and len(rel) >= 2:
                return ndx_k('mcall', rel[0], rel[1], [])
            fn = rel[-1] if rel else None
            if fn is None or (isinstance(fn, NdxSV) and fn.op in (
                    'none', 'imm')):
                # il callable non viaggia nei registri ABI (il compilatore
                # lo tiene in un volatile non-ABI dopo la lookup del
                # metodo): cerca il valore Python vivo più recente fra
                # TUTTI i registri, con preferenza per l'attributo appena
                # cercato (una method lookup è il callee naturale)
                cands = [s for s in self.regs.values()
                         if isinstance(s, NdxSV) and s.op == 'getattr']
                if not cands:
                    cands = [s for s in self.regs.values()
                             if isinstance(s, NdxSV) and s.op in (
                                 'global', 'var', 'par', 'cellref',
                                 'mcall', 'call', 'super', 'sub')]
                fn = cands[-1] if cands else fn
            pending = getattr(self, '_pending_method', None)
            if pending is not None and fn is not None and \
                    (pending[2] is fn or (
                        isinstance(fn, NdxSV) and fn is pending[0])):
                # dispatch bound-method: il callee candidato è il
                # RECEIVER della lookup pendente → il callee vero è
                # l'attributo cercato (``obj.name()``), e la lettura
                # attributo da sola perde il senso: rimuovi le sue ops
                # (calc + store) da qualunque blocco
                fn = pending[2]
                self._pending_method = None
                removed = False
                try:
                    for blk in self.blocks.values():
                        keep = [
                            o for o in blk.ops
                            if not ((o.kind == 'calc' and o.a is fn) or
                                    (o.kind == 'store' and o.b is fn))]
                        if len(keep) != len(blk.ops):
                            blk.ops[:] = keep
                            removed = True
                except Exception:
                    pass
            elif pending is not None and fn is not None and \
                    pending[2] is fn:
                self._pending_method = None
            return ndx_k('call', fn, [])
        if name.startswith('CALL_FUNCTION_KW'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            fn = rel[0] if rel else None
            return ndx_k('call', fn, rel[1:])
        if name in ('PyObject_Call', 'PyObject_Vectorcall',
                    'PyVectorcall_Function', 'PyObject_CallNoArgs',
                    'PyObject_CallOneArg'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            fn = rel[0] if rel else None
            return ndx_k('call', fn, rel[1:])

        # ---- formattazione ----
        if name in ('PyUnicode_Format', 'UNICODE_FORMAT'):
            fmt = None
            vals = None
            single = None
            rel = [a for a in args if a is not None]
            for a in rel:
                if a.op == 'const' and isinstance(a.a, str) and fmt is None:
                    fmt = a.a
                elif a.op == 'const' and isinstance(a.a, tuple):
                    vals = a.a
                elif single is None:
                    # valore singolo da registro: ``fmt % x``
                    single = a
            if vals is None and single is not None:
                vals = single
            return ndx_k('pyformat', fmt, vals)
        if name == 'PyUnicode_Join':
            sep, values = self._pick2(args)
            if values is not None and values.op == 'loc':
                recovered = self._tuple_build_before(ins.address)
                if recovered is not None:
                    values = recovered
            if sep is not None and sep.op == 'const' and sep.a == '' and \
                    values is not None and values.op == 'tuple_build':
                parts = []
                for part in values.b or []:
                    if part is not None and part.op == 'call' and \
                            part.a is not None and part.a.op == 'global' and \
                            part.a.a == 'format' and part.b:
                        spec = part.b[1] if len(part.b) > 1 else ndx_k(
                            'const', '')
                        part = ndx_k('format', part.b[0], spec)
                    parts.append(part)
                return ndx_k('fstring', parts)
            return ndx_k('str_join', sep, values)
        if name == 'TO_DICT':
            value = self._pick1(args)
            return ndx_k('call', 'dict', [value] if value is not None else [])

        # ---- import ----
        if name.startswith('IMPORT_'):
            rel = [a for a in args if a is not None]
            modname = None
            if name.startswith('IMPORT_HARD@'):
                # Initializer identificato dallo scan statico: il nome modulo
                # è incorporato nel marker e ha la precedenza.
                modname = name[len('IMPORT_HARD@'):]
                # The initializer proves a constant module and has no Python
                # operands. Stale argument registers must not consume an
                # earlier call's result and erase that call from the source.
                return ndx_k('import', modname, [])
            if modname is None:
                for a in rel:
                    if a.op == 'const' and isinstance(a.a, str):
                        modname = a.a
                        break
            if modname is None:
                # IMPORT_HARD_* non riceve il nome modulo: è codificato nel
                # nome dell'helper (es. IMPORT_HARD_TYPING -> 'typing').
                modname = _ndl_hard_import_module_name(name)
            return ndx_k('import', modname, rel)
        # ---- import via builtin __import__ (Nuitka 2.x+/MinGW) ----
        if name in ('BUILTIN___IMPORT__', 'PyImport_Import',
                    'PyImport_ImportModule'):
            rel = [a for a in args if a is not None]
            modname = None
            for a in rel:
                if a.op == 'const' and isinstance(a.a, str):
                    modname = a.a
                    break
            if modname is not None:
                # Forma ABI (tstate, name, globals, locals, fromlist, level)
                # con fromlist/level nell'area stack uscente: args è già
                # completato dal dispatch; garantisci solo lunghezza 6.
                node_args = list(args)
                while len(node_args) < 6:
                    node_args.insert(0, None)
                return ndx_k('import', modname, node_args[:6])

        # The descriptor cursor used by Nuitka's per-element constant copier
        # is native metadata.  Its Python result is exactly the source object,
        # which is the ABI operand immediately after tstate.
        if name == 'DEEP_COPY_ELEMENT':
            if args and args[0] is not None and args[0].op == 'tstate':
                return args[1] if len(args) > 1 else None
            return args[0] if args else None
        # ---- DEEP_COPY delle costanti mutabili: identity ----
        if name.startswith('DEEP_COPY'):
            return self._pick1(args)
        # ---- load di variabile globale del modulo ----
        if sop == 'global_load':
            return ndx_k('global', arity if isinstance(arity, str) else name)
        # ---- dict lookup interno (subscript veloce / globali) ----
        if name in ('Nuitka_PyDictLookup', 'Nuitka_PyDictLookupNext',
                    'Nuitka_PyDictLookupStr'):
            rel = [a for a in args if a is not None and a.op != 'tstate']
            if len(rel) >= 2:
                d, k = rel[0], rel[1]
                # lookup sul dizionario del modulo → nome globale
                if d is not None and d.op == 'moddict' and \
                        k is not None and k.op == 'const' and \
                        isinstance(k.a, str):
                    return ndx_k('global', k.a)
                # lookup sul dizionario di un modulo noto → getattr
                if d is not None and d.op == 'global' and \
                        k is not None and k.op == 'const' and \
                        isinstance(k.a, str):
                    return ndx_k('getattr', d, k.a)
                if d is not None and d.op == 'gslot':
                    # slot dict del modulo (accessor inlined)
                    mds = getattr(self.res, 'moduledict_slots', set())
                    if d.a in mds and k is not None and k.op == 'const' \
                            and isinstance(k.a, str):
                        return ndx_k('global', k.a)
                return ndx_k('sub', d, k)
            return ndx_k('sub', self._pick1(args))
        # ---- generico API con semantica nota ----
        if sop:
            return ndx_k('apicall', name, args)

        return ndx_k('nativecall', name, args)

    def _expand_stack_array(self, pointer, count):
        if pointer is None or pointer.op != 'stackaddr' or count < 0:
            return []
        base, offset = pointer.a, pointer.b
        return [self.slot_syms.get((base, offset + 8 * index))
                for index in range(count)]

    def _expand_argument_array(self, pointer, count):
        if pointer is not None and pointer.op == 'const' and \
                isinstance(pointer.a, (tuple, list)):
            return [ndx_k('const', value) for value in pointer.a[:count]]
        if pointer is not None and pointer.op == 'const_array' and \
                isinstance(pointer.a, (tuple, list)):
            start = pointer.b or 0
            return [ndx_k('const', value)
                    for value in pointer.a[start:start + count]]
        return self._expand_stack_array(pointer, count)

    def _global_value_slots(self):
        """(value_slot → global name) map of this function's INLINE accessors.

        MSVC inlines Nuitka's per-global cached-dictionary lookup: a
        version-cache test guards ``GET_STRING_DICT_VALUE`` on the miss
        path, and the hit path simply re-loads the cached PyObject* from a
        dedicated .data slot.  Every lookup site therefore exhibits the
        structural triple ``name-const → GET_STRING_DICT_VALUE → store to
        value slot``; collecting it once maps each value slot to the global
        it caches — including the pointer-cell indirection
        ``mov R, [rip+PTR]; mov arg, [R]`` used for the callable register.
        """
        cached = getattr(self, '_gsv_value_slots', None)
        if cached is not None:
            return cached
        mapping = {}
        limit = len(self.insns)
        for index, ins in enumerate(self.insns):
            if ins.mnemonic != 'call' or not ins.op_str.startswith('0x'):
                continue
            try:
                helper = self.res.resolve(int(ins.op_str, 16))[1]
            except Exception:
                continue
            if helper != 'GET_STRING_DICT_VALUE':
                continue
            name = None
            for setup in reversed(self.insns[max(0, index - 10):index]):
                if setup.mnemonic not in ('mov', 'lea'):
                    continue
                ops2 = split_ops(setup.op_str)
                if len(ops2) != 2 or \
                        subreg64(ops2[0]) != self.abi.arg_regs[1] or \
                        'rip' not in ops2[1]:
                    continue
                target = rip_target(setup)
                if target is None or self.mca is None:
                    continue
                value, _which = self.mca.const_for_slot(target)
                if isinstance(value, str) and value.isidentifier():
                    name = value
                    break
            if name is None:
                continue
            for store in self.insns[index + 1:min(limit, index + 14)]:
                if store.mnemonic == 'call':
                    break
                if store.mnemonic != 'mov':
                    continue
                ops3 = split_ops(store.op_str)
                if len(ops3) != 2 or \
                        not ops3[0].startswith('qword ptr [rip'):
                    continue
                # the cached value is a PyObject* register spill; reject
                # immediate stores (those are the version cache, not the
                # value cell)
                if subreg64(ops3[1]) is None:
                    continue
                slot = rip_target(store)
                if slot is not None:
                    mapping.setdefault(slot, name)
                break
        self._gsv_value_slots = mapping
        return mapping

    def _global_name_before(self, call_address, max_back=0x280):
        """Name of the module global whose lookup VALUE feeds this call.

        Proves the data-flow instead of trusting address order.  Starting
        from the ABI value register (the second argument after tstate —
        rdx on Win64, rsi on SysV) a single backward walk classifies every
        definition it meets:

          * ``mov R, [rip+SLOT]``  — a fast-path load of an inline
            accessor's cached value slot (slot→name map proven from the
            accessor's own slow-path store);
          * ``mov R, [RET]`` right after ``call GET_STRING_DICT_VALUE`` —
            the slow arm; the name is proven by that call's key register
            setup;
          * ``mov R, [rbp-X]``     — a spill reload; jump to the matching
            store and continue with its source register;
          * ``mov R, S``           — register alias; continue with S;
          * ``call`` writing the tracked register — the accessor result;
            resolve via its key setup like the slow arm.

        A nearby but unrelated lookup — e.g. the ARGUMENT of
        ``global_fn(global_arg)``, which sits closer to the call than the
        callable's own lookup — can never satisfy the chain.
        """
        indexes = {ins.address: index for index, ins in enumerate(self.insns)}
        end = indexes.get(call_address)
        if end is None:
            return None
        value_slots = self._global_value_slots()

        def _slot_name(slot):
            return value_slots.get(slot) if slot is not None else None

        def _name_of_lookup_call(producer_index):
            producer = self.insns[producer_index]
            if not producer.op_str.startswith('0x'):
                return None
            try:
                helper = self.res.resolve(int(producer.op_str, 16))[1]
            except Exception:
                return None
            if helper != 'GET_STRING_DICT_VALUE':
                return None
            for setup in reversed(self.insns[
                    max(0, producer_index - 10):producer_index]):
                if setup.mnemonic not in ('mov', 'lea'):
                    continue
                setup_ops = split_ops(setup.op_str)
                if len(setup_ops) != 2 or                         subreg64(setup_ops[0]) != self.abi.arg_regs[1] or                         'rip' not in setup_ops[1]:
                    continue
                target = rip_target(setup)
                if target is None or self.mca is None:
                    continue
                value, _which = self.mca.const_for_slot(target)
                if isinstance(value, str) and value.isidentifier():
                    return value
            return None

        tracked = self.abi.arg_regs[1]
        origin_index = end
        for _hop in range(24):
            definition = None
            for index in range(origin_index - 1, -1, -1):
                ins = self.insns[index]
                if call_address - ins.address > max_back:
                    return None
                operands = split_ops(ins.op_str)
                if not operands:
                    continue
                if subreg64(operands[0]) != tracked:
                    continue
                if ins.mnemonic not in ('mov', 'movzx', 'movsxd', 'lea'):
                    return None   # redefined by arithmetic/store: not a move
                definition = (index, operands)
                break
            if definition is None:
                return None
            index, operands = definition
            destination = operands[0]
            source_text = operands[1]
            # 1) fast-path load of a cached value slot
            if ins.mnemonic == 'mov' and 'rip' in source_text and                     parse_mem(source_text) is not None:
                name = _slot_name(rip_target(ins))
                return name          # None when the slot is not a global
            memory = parse_mem(source_text)
            if ins.mnemonic == 'mov' and memory is not None:
                base = memory[0]
                # 2) deref of the accessor's dict-entry result
                if base is not None and base not in ('rbp', 'rsp'):
                    producer_index = None
                    for back in range(index - 1,
                                      max(0, index - 12) - 1, -1):
                        prior = self.insns[back]
                        if prior.mnemonic == 'call' and                                 prior.op_str.startswith('0x'):
                            producer_index = back
                            break
                    if producer_index is not None:
                        name = _name_of_lookup_call(producer_index)
                        if name is not None:
                            return name
                    return None
                # 3) spill reload: jump to the matching store
                if base in ('rbp', 'rsp') and not memory[2]:
                    for back in range(index - 1,
                                      max(0, index - 200) - 1, -1):
                        prior = self.insns[back]
                        prior_ops = split_ops(prior.op_str)
                        if len(prior_ops) != 2 or                                 prior.mnemonic not in ('mov', 'lea'):
                            continue
                        prior_mem = parse_mem(prior_ops[0])
                        if prior_mem is None or prior_mem[2] or                                 prior_mem[0] != base or                                 prior_mem[1] != memory[1] or                                 'rip' in prior_ops[0]:
                            continue
                        if prior_mem[0] is None:
                            continue
                        if 'rip' in prior_ops[1]:
                            name = _slot_name(rip_target(prior))
                            if name is not None:
                                return name
                            return None
                        tracked = subreg64(prior_ops[1])
                        origin_index = back
                        if tracked is None:
                            return None
                        break
                    else:
                        return None
                    continue
                return None
            # 4) producer call result
            if ins.mnemonic == 'mov' and subreg64(source_text) is None:
                return None          # immediate
            # 5) register alias (or the value loaded by an earlier call)
            tracked = subreg64(source_text)
            if tracked is None:
                return None
            origin_index = index
        return None

    def _cached_builtin_name_before(self, call_address, max_back=0x100):
        """Resolve MSVC's lazily cached ``PyObject_GetAttrString`` builtin."""
        end = next((i for i, item in enumerate(self.insns)
                    if item.address == call_address), None)
        if end is None:
            return None
        lower = max(0, end - 80)
        for index in range(end - 1, lower - 1, -1):
            call = self.insns[index]
            if call_address - call.address > max_back:
                break
            if call.mnemonic != 'call' or 'rip' not in call.op_str:
                continue
            slot = rip_target(call)
            if self.img.imports.get(slot) not in (
                    'PyObject_GetAttrString', 'PyObject_GetAttr',
                    'PyDict_GetItemString'):
                continue
            for setup in reversed(self.insns[max(lower, index - 8):index]):
                if setup.mnemonic != 'lea' or 'rip' not in setup.op_str:
                    continue
                operands = split_ops(setup.op_str)
                if len(operands) != 2 or subreg64(operands[0]) != 'rdx':
                    continue
                address = rip_target(setup)
                if address is None:
                    continue
                try:
                    name = self.img.read_cstr(address, 128)
                except Exception:
                    name = None
                if isinstance(name, bytes):
                    name = name.decode('ascii', errors='ignore')
                if isinstance(name, str) and name.isidentifier():
                    return name
        return None

    def _tuple_build_before(self, call_address, max_back=0x300):
        """Reassociate a tuple builder across refcount/error CFG joins."""
        end = next((i for i, item in enumerate(self.insns)
                    if item.address == call_address), None)
        if end is None:
            return None
        base = None
        for setup in reversed(self.insns[max(0, end - 10):end]):
            if setup.mnemonic != 'mov':
                continue
            operands = split_ops(setup.op_str)
            if len(operands) == 2 and subreg64(operands[0]) == 'rdx':
                base = subreg64(operands[1])
                if base:
                    break
        if base is None:
            return None
        builders = []
        for block in self.blocks.values():
            for op in block.ops:
                if op.kind == 'calc' and op.a is not None and \
                        op.a.op == 'tuple_build' and \
                        0 < call_address - op.va <= max_back:
                    builders.append((op.va, op.a))
        if not builders:
            return None
        builder = max(builders, key=lambda pair: pair[0])[1]
        count = len(builder.b or [])
        elements = [self.slot_syms.get((base, 0x18 + index * 8))
                    for index in range(count)]
        if count and all(element is not None for element in elements):
            return ndx_k('tuple_build', None, elements)
        return builder

    def _symbol_for_register_before(self, address, register, max_depth=12):
        """Resolve a symbolic value through MOV aliases and stack spills.

        This is a local reaching-definition query for recognisers that inspect
        an earlier native protocol call after registers have been reused.  It
        accepts only exact register copies, exact non-indexed memory slots and
        entry ``python_pars[i]`` loads.
        """
        first_call = next((item.address for item in self.insns
                           if item.mnemonic == 'call'), address)

        def operation_store_entry(location, before):
            candidates = []
            for block in self.blocks.values():
                for operation in block.ops:
                    if operation.kind == 'store' and \
                            operation.a == location and \
                            operation.b is not None and \
                            operation.va is not None and \
                            operation.va < before:
                        candidates.append((operation.va, operation.b))
            return max(candidates, default=(0, None),
                       key=lambda pair: pair[0])

        def operation_store(location, before):
            return operation_store_entry(location, before)[1]

        def memory_value(base, offset, before, depth, seen):
            location = ('mem', base, offset)
            parameter = getattr(self, '_entry_parameter_locations',
                                {}).get(location)
            if parameter is not None and parameter[0] == 'par' and \
                    parameter[1] < self.argcount:
                return ndx_k('par', parameter[1])
            semantic = operation_store(location, before)
            if semantic is not None:
                return semantic
            end = next((index for index, item in enumerate(self.insns)
                        if item.address >= before), len(self.insns))
            for item in reversed(self.insns[:end]):
                operands = split_ops(item.op_str)
                if item.mnemonic != 'mov' or len(operands) != 2:
                    continue
                destination = parse_mem(operands[0])
                if not destination or destination[0] != base or \
                        destination[1] != offset or destination[2]:
                    continue
                source = subreg64(operands[1])
                if source:
                    value = register_value(source, item.address,
                                           depth + 1, seen)
                    if value is None:
                        value = self._parameter_arg_before(
                            item.address, source)
                    return value
                return None
            return None

        def register_value(current, before, depth, seen):
            current = subreg64(current)
            marker = ('reg', current, before)
            if current is None or depth > max_depth or marker in seen:
                return None
            seen = set(seen)
            seen.add(marker)
            semantic_address, semantic = operation_store_entry(
                ('reg', current), before)
            end = next((index for index, item in enumerate(self.insns)
                        if item.address >= before), len(self.insns))
            for item in reversed(self.insns[:end]):
                operands = split_ops(item.op_str)
                if len(operands) != 2 or \
                        subreg64(operands[0]) != current:
                    continue
                if item.mnemonic != 'mov':
                    if item.mnemonic in ('add', 'sub', 'xor', 'or', 'and',
                                         'imul', 'shl', 'shr', 'sar'):
                        return None
                    # CMP/TEST and other read-only instructions mention the
                    # register first but are not reaching definitions.
                    continue
                if semantic is not None and semantic_address >= item.address:
                    return semantic
                source = subreg64(operands[1])
                if source is not None:
                    return register_value(source, item.address, depth + 1,
                                          seen)
                memory = parse_mem(operands[1])
                if memory and memory[0] and not memory[2]:
                    if item.address < first_call and \
                            memory[0] == getattr(self, 'pars_reg', None) and \
                            memory[1] >= 0 and memory[1] % 8 == 0:
                        index = memory[1] // 8
                        if index < self.argcount:
                            return ndx_k('par', index)
                    return memory_value(memory[0], memory[1], item.address,
                                        depth + 1, seen)
                return None
            return semantic

        return register_value(register, address, 0, set())

    def _latest_semantic_store_before(self, location, address):
        """Return the latest same-location producer on a normal CFG path."""
        if not isinstance(location, tuple):
            return None
        target = next((start for start, block in self.blocks.items()
                       if start <= address < block.end), None)
        if target is None:
            return None

        # V100: reachability calcolata UNA volta con BFS all'indietro dal
        # target (preds derivati dai succs) invece che per-blocco in
        # avanti (O(B*400) per query — ore sulle funzioni giganti).
        # Stessa semantica: nodi 'error' non attraversano.
        preds_of = {}
        for start, block in self.blocks.items():
            if block.kind == 'error':
                continue
            for successor in block.succs:
                if successor in self.blocks and                         self.blocks[successor].kind != 'error':
                    preds_of.setdefault(successor, []).append(start)
        can_reach = {target}
        pending = [target]
        while pending and len(can_reach) < 100000:
            current = pending.pop()
            for pred in preds_of.get(current, ()):
                if pred not in can_reach:
                    can_reach.add(pred)
                    pending.append(pred)

        def reaches(source):
            return source in can_reach

        candidates = []
        for start, block in self.blocks.items():
            if block.kind == 'error' or not reaches(start):
                continue
            for operation in block.ops:
                if operation.kind == 'store' and operation.a == location and \
                        operation.b is not None and operation.va is not None and \
                        operation.va < address:
                    candidates.append((operation.va, operation.b))
        return max(candidates, default=(0, None),
                   key=lambda pair: pair[0])[1]

    def _inline_richcompare_before(self, call_address, max_back=0x220):
        """Recover an MSVC-inlined ``tp_richcompare`` dispatcher.

        Nuitka emits reflected and direct slot calls through ``tp+0xc8``.
        Each call carries the CPython comparison opcode in r8d.  Canonicalise
        reflected GT/GE forms by swapping operands, and require two matching
        protocol branches before claiming a Python comparison.
        """
        end = next((i for i, item in enumerate(self.insns)
                    if item.address == call_address), None)
        if end is None:
            return None
        candidates = []
        lower = max(0, end - 180)
        for index in range(end - 1, lower - 1, -1):
            call = self.insns[index]
            if call_address - call.address > max_back:
                break
            if call.mnemonic != 'call':
                continue
            target_reg = subreg64(call.op_str.strip())
            if target_reg is None:
                continue
            slot_index = None
            for probe in range(index - 1, max(lower - 1, index - 18), -1):
                setup = self.insns[probe]
                if setup.mnemonic != 'mov':
                    continue
                operands = split_ops(setup.op_str)
                if len(operands) != 2 or \
                        subreg64(operands[0]) != target_reg:
                    continue
                mem = parse_mem(operands[1])
                if mem is not None and mem[1] == 0xc8:
                    slot_index = probe
                    break
            if slot_index is None:
                continue
            opcode = None
            sources = {}
            for setup in self.insns[slot_index + 1:index]:
                operands = split_ops(setup.op_str)
                if setup.mnemonic == 'xor' and len(operands) == 2 and \
                        subreg64(operands[0]) == 'r8' and \
                        subreg64(operands[1]) == 'r8':
                    opcode = 0
                    continue
                if setup.mnemonic != 'mov':
                    continue
                if len(operands) != 2:
                    continue
                dst = subreg64(operands[0])
                if dst == 'r8':
                    opcode = is_imm(operands[1])
                elif dst in ('rcx', 'rdx'):
                    src = subreg64(operands[1])
                    if src:
                        sources[dst] = src
            if opcode not in range(6) or not {'rcx', 'rdx'} <= sources.keys():
                continue
            left = self._symbol_for_register_before(
                call.address, sources['rcx']) or self._reg(sources['rcx'])
            right = self._symbol_for_register_before(
                call.address, sources['rdx']) or self._reg(sources['rdx'])
            if left is None or right is None:
                continue
            token = {0: 'lt', 1: 'le', 2: 'eq', 3: 'ne',
                     4: 'gt', 5: 'ge'}[opcode]
            if token == 'gt':
                left, right, token = right, left, 'lt'
            elif token == 'ge':
                left, right, token = right, left, 'le'
            candidates.append(ndx_k('cmp', token, left, right))
        for candidate in candidates:
            if sum(1 for other in candidates if _sv_eq(candidate, other)) >= 2:
                return candidate
        return None

    def _const_str_of(self, sym):
        return None

    def _pick1(self, args):
        rel = [a for a in args if a is not None and a.op != 'tstate']
        return rel[-1] if rel else None

    def _repair_name_main_compare(self, around_va=None):
        """V100: ripara gli operandi di una ``RICH_COMPARE_*`` caduta nel
        cold-path outline (args NULL) quando il flusso vicino contiene la
        fast-path del template universale Nuitka per ``__name__ ==
        '__main__'``: ``PyUnicode_Find(global __name__, const '__main__')``
        / ``PyUnicode_GetLength(global __name__)`` con la costante
        ``'__main__'``.  Cerca nel blocco corrente E nei blocchi gia'
        processati entro 0x2000 byte di VA (il cold-path e' out-of-line).
        Ritorna (x, y) o None."""
        candidates = []
        block = getattr(self, '_cur_block', None)
        if block is not None:
            candidates.append(block)
        if around_va is not None:
            blocks = getattr(self, 'blocks', None) or {}
            for start, blk in blocks.items():
                if blk is block:
                    continue
                if around_va - 0x2000 <= start <= around_va + 0x40:
                    candidates.append(blk)
        has_main_const = False
        find_pair = None
        name_glob = None
        for blk in candidates:
            for op in list(blk.ops)[-60:]:
                node = op.a
                if not isinstance(node, NdxSV):
                    if isinstance(node, str) and node == '__main__':
                        has_main_const = True
                    continue
                if node.op == 'const' and node.a == '__main__':
                    has_main_const = True
                    continue
                if node.op == 'global' and node.a == '__name__':
                    name_glob = node
                    continue
                if node.op == 'nativecall' and isinstance(node.a, str) and \
                        node.a in ('PyUnicode_Find', 'PyUnicode_FindChar',
                                   'PyUnicode_IndexOf'):
                    a0 = node.b[0] if isinstance(node.b, list) and len(node.b) > 0 else None
                    a1 = node.b[1] if isinstance(node.b, list) and len(node.b) > 1 else None
                    if getattr(a0, 'op', None) == 'global' and a0.a == '__name__':
                        find_pair = (a0, a1)
        if find_pair is not None and getattr(find_pair[1], 'op', None) == 'const':
            return find_pair
        if name_glob is not None and has_main_const:
            return (name_glob, ndx_k('const', '__main__'))
        # Template-prova residua: ``PyUnicode_Find(global __name__, X)`` in
        # un MODULE-INIT esiste solo come fast-path del main-guard di
        # Nuitka (nessun altro costrutto cerca dentro __name__): X e' per
        # definizione del template la costante confrontata.
        if find_pair is not None and getattr(self, 'is_module_code', False):
            return (name_glob or find_pair[0],
                    ndx_k('const', '__main__'))
        return None

    def _pick2(self, args):
        rel = [a for a in args if a is not None and a.op != 'tstate']
        if len(rel) >= 2:
            return rel[-2], rel[-1]
        if len(rel) == 1:
            return None, rel[0]
        return None, None

    def _pick3(self, args):
        rel = [a for a in args if a is not None and a.op != 'tstate']
        if len(rel) >= 3:
            return rel[-3], rel[-2], rel[-1]
        while len(rel) < 3:
            rel.insert(0, None)
        return tuple(rel)

    def _binop_code(self, name):
        n = name
        if 'MULT' in n:
            return '*'
        if 'ADD' in n:
            return '+'
        if 'SUB' in n:
            return '-'
        if 'FLOORDIV' in n:
            return '//'
        if 'DIV' in n or 'TRUEDIV' in n:
            return '/'
        if 'MOD' in n or 'REMAINDER' in n:
            return '%'
        if 'POW' in n or 'POWER' in n:
            return '**'
        if 'LSHIFT' in n:
            return '<<'
        if 'RSHIFT' in n:
            return '>>'
        if 'BITAND' in n or '_AND_' in n:
            return '&'
        if 'BITOR' in n or '_OR_' in n:
            return '|'
        if 'BITXOR' in n or '_XOR_' in n:
            return '^'
        return '?'

    # ---- test/cmp → valore condizione ----
    def _exec_test(self, ins):
        m = ins.mnemonic
        ops = split_ops(ins.op_str)
        if len(ops) != 2:
            self._cond_val = None
            self._cond_kind = None
            return
        o1, o2 = ops
        # immediati Intel: senza prefisso
        if m == 'test':
            r1 = subreg64(o1)
            r2 = subreg64(o2)
            if r1 and r1 == r2:
                sym = self._reg(r1)
                if sym is not None and sym.op == 'cmp' and o1 in _R64:
                    # Pointer-width TEST of the comparison's PyObject* result
                    # checks allocation/dispatch failure. False is a non-NULL
                    # object too. NBOOL/CBOOL consumers test eax/al instead.
                    self._cond_val = sym
                    self._cond_kind = 'null_or_bool'
                elif sym is not None and sym.op in ('cmp', 'bool',
                                                    'exc_match'):
                    self._cond_val = sym
                    self._cond_kind = 'auto'
                elif sym is not None and sym.op == 'next':
                    # NULL check su ITERATOR_NEXT: uscita loop (stop
                    # iteration) SOLO se il registro testato è il registro
                    # di ritorno fresco della chiamata; altrimenti è il
                    # Py_XDECREF(old) del valore precedente (refcount).
                    if r1 == self.abi.ret_reg and self._last_call and \
                            self._last_call[1] is sym:
                        self._cond_val = sym
                        self._cond_kind = 'iter_null'
                    else:
                        self._cond_val = sym
                        self._cond_kind = 'null_or_bool'
                elif sym is not None and sym.op == 'tpiternext':
                    # test sul campo tp_iternext: jne = dispatch inline ok
                    # (flusso normale, es. back edge di loop ruotato);
                    # je = slow path (gestione via eccezione) → error
                    self._cond_val = None
                    self._cond_kind = 'tpnull'
                elif sym is not None and sym.op in ('nativecall',
                                                    'apicall'):
                    # Un flag C-int è provato SOLO dal nome della chiamata
                    # (CONSIDER_THREADING e simili). Un helper nativo
                    # SCONOSCIUTO (join/string-builder locali del modulo,
                    # comuni su MinGW senza firme) restituisce un
                    # PyObject*: il test è il solito NULL-check.
                    last = getattr(self, '_last_call', None)
                    last_name = last[2] if last else None
                    if isinstance(last_name, str) and last_name in (
                            'CONSIDER_THREADING', 'Py_MakePendingCalls',
                            'PyErr_CheckSignals', 'PyErr_CheckSignalsEx'):
                        self._cond_val = sym
                        self._cond_kind = 'c_int'
                    else:
                        self._cond_val = sym
                        self._cond_kind = 'null_or_bool'
                elif sym is None:
                    # An untracked C/runtime flag (threading, eval breaker,
                    # frame state) is not proof of a Python NULL result.
                    last = getattr(self, '_last_call', None)
                    if last and last[2] == 'GIL_WRAPPER':
                        self._cond_val = None
                        self._cond_kind = 'runtime_success'
                    else:
                        self._cond_val = None
                        self._cond_kind = None
                else:
                    self._cond_val = sym
                    self._cond_kind = 'null_or_bool'
                return
            self._cond_val = None
            self._cond_kind = None
            return
        if m == 'cmp':
            # Intel: cmp dst, src (dst - src)
            # confronto su SLOT di stack: check di stato C (exception_state,
            # flag) — mai una condizione Python → edge d'errore
            if parse_mem(o1) is not None:
                self._cond_val = None
                self._cond_kind = 'error_flag'
                return
            imm = is_imm(o2)
            if imm is None and o1 not in _R64 and o2 not in _R64:
                right = self._reg(subreg64(o2))
                if isinstance(right, NdxSV) and right.op == 'imm':
                    imm = right.a
            if imm is not None:
                r1 = subreg64(o1)
                sym = self._reg(r1) if r1 else None
                if isinstance(sym, NdxSV) and sym.op == 'long_tag':
                    literal = self._small_long_literal_after(ins.address, imm)
                    if literal is not None:
                        self._cond_val = ndx_k(
                            'cmp', 'eq', sym.a, ndx_k('const', literal))
                        self._cond_kind = 'nbool'
                        return
                bool_ops = ('cmp', 'bool', 'contains')
                if imm == 1 and (sym is None or sym.op not in bool_ops):
                    sym = self._materialized_bool_before(ins.address, r1)
                if sym is not None and sym.op in bool_ops:
                    if imm == 1:
                        self._cond_val = sym
                        self._cond_kind = 'nbool'
                    elif imm == 0:
                        self._cond_val = sym
                        self._cond_kind = 'auto'
                    elif imm in (-1, 0xffffffff):
                        self._cond_val = None
                        self._cond_kind = 'nbool_exc'
                    else:
                        self._cond_val = None
                        self._cond_kind = None
                elif imm in (-1, 0xffffffff) and r1 is not None:
                    inlined = self._inline_richcompare_before(ins.address)
                    if inlined is not None:
                        # The -1 branch is only the C error sentinel.  Carry
                        # the proven Python comparison into the fallthrough,
                        # where Nuitka immediately tests its boolean result.
                        self._setreg(r1, inlined)
                        self._cond_val = None
                        self._cond_kind = 'nbool_exc'
                    else:
                        self._cond_val = None
                        self._cond_kind = None
                elif sym is not None and sym.op == 'exc_match':
                    self._cond_val = sym
                    self._cond_kind = 'int_nonzero'
                elif sym is not None and sym.op == 'next':
                    self._cond_val = sym
                    self._cond_kind = 'iter_null'
                elif r1 == 'eax' or r1 == 'rax':
                    # confronto C su intero: condizione non-Python
                    self._cond_val = None
                    self._cond_kind = None
                else:
                    self._cond_val = None
                    self._cond_kind = None
                return
            # cmp reg, [rip+IAT]: identita' di singleton (``x is True`` /
            # ``x is False`` / ``x is None``).  Il campo IAT di
            # _Py_TrueStruct/_Py_FalseStruct/_Py_NoneStruct e' l'indirizzo
            # dell'oggetto singleton: il confronto e' un `is` Python, non un
            # confronto C.  Nuitka lo usa per il lowering di ``not X``.
            r1s = subreg64(o1)
            if r1s is not None and o2 not in _R64:
                mem2 = parse_mem(o2)
                if mem2 is not None and mem2[0] == 'rip' and \
                        mem2[2] is None:
                    try:
                        _tgt = rip_target(ins)
                        _iat = getattr(getattr(self.res, '_native_classifier',
                                               None), 'iat', None) or {}
                        _sing = _iat.get(_tgt)
                    except Exception:
                        _sing = None
                    _sv = {'_Py_TrueStruct': True, '_Py_FalseStruct': False,
                           '_Py_NoneStruct': None}.get(_sing, _SINGLETON_MISS)
                    if _sv is not _SINGLETON_MISS:
                        _obj = self._reg(r1s)
                        # solo un OGGETTO puo' identificare un singleton:
                        # un risultato gia' booleano/confronto (richcompare,
                        # bool, binop % ...) testato contro True/False e'
                        # il test del flag C, non un ``is`` Python.
                        if _obj is not None and _obj.op not in (
                                'cmp', 'bool', 'binop', 'not', 'unary',
                                'native_ssize'):
                            self._cond_val = ndx_k('cmp', 'is', _obj,
                                                   ndx_k('const', _sv))
                            self._cond_kind = 'is_single'
                            return
            # cmp reg,reg con simboli: is-None inline? (PyObject* == Py_None)
            r1 = subreg64(o1)
            r2 = subreg64(o2)
            s1 = self._reg(r1) if r1 else None
            s2 = self._reg(r2) if r2 else None
            if s1 is not None and s1.op == 'const' and s1.a is None:
                self._cond_val = ndx_k('isnull', s2)
                self._cond_kind = 'is_none'
                return
            if s2 is not None and s2.op == 'const' and s2.a is None:
                self._cond_val = ndx_k('isnull', s1)
                self._cond_kind = 'is_none'
                return
            self._cond_val = None
            self._cond_kind = None
            return
        self._cond_val = None
        self._cond_kind = None

    def _small_long_literal_after(self, compare_address, size_value):
        """Decode a one-digit PyLong equality guard following ``ob_size``.

        Nuitka emits ``cmp Py_SIZE(value), +/-1; jcc miss`` followed on the
        success path by ``cmp value->ob_digit[0], DIGIT; jcc miss``.  Requiring
        both guards to share the same miss target proves that the native tests
        form one Python comparison rather than two unrelated C conditions.
        """
        if abs(int(size_value)) != 1:
            return None
        index = next((position for position, item in enumerate(self.insns)
                      if item.address == compare_address), None)
        if index is None:
            return None
        conditional = {'je', 'jne', 'jz', 'jnz'}
        first_branch = None
        first_target = None
        for position in range(index + 1, min(len(self.insns), index + 4)):
            item = self.insns[position]
            if item.mnemonic in conditional and item.op_str.startswith('0x'):
                first_branch = position
                try:
                    first_target = int(item.op_str, 16)
                except ValueError:
                    return None
                break
        if first_branch is None:
            return None
        for position in range(first_branch + 1,
                              min(len(self.insns), first_branch + 18)):
            item = self.insns[position]
            operands = split_ops(item.op_str)
            if item.mnemonic != 'cmp' or len(operands) != 2 or \
                    parse_mem(operands[0]) is None:
                continue
            digit = is_imm(operands[1])
            if digit is None:
                continue
            for following in self.insns[position + 1:position + 3]:
                if following.mnemonic not in conditional or \
                        not following.op_str.startswith('0x'):
                    continue
                try:
                    target = int(following.op_str, 16)
                except ValueError:
                    continue
                if target == first_target:
                    guards = getattr(self, '_compound_guard_jcc', None)
                    if guards is None:
                        guards = self._compound_guard_jcc = set()
                    guards.add(following.address)
                    # Multi-digit equality templates advance backwards over
                    # the digit array with a native signed-count loop.  Its
                    # back edge is another sub-guard of the same comparison,
                    # not a Python loop.  Ignore bounded backward Jcc edges
                    # before the next semantic call, leaving their physical
                    # fallthrough as the successful comparison path.
                    following_index = next(
                        (idx for idx, candidate in enumerate(self.insns)
                         if candidate.address == following.address), None)
                    if following_index is not None:
                        for tail in self.insns[
                                following_index + 1:following_index + 10]:
                            if tail.mnemonic == 'call':
                                break
                            if not tail.mnemonic.startswith('j') or \
                                    tail.mnemonic == 'jmp' or \
                                    not tail.op_str.startswith('0x'):
                                continue
                            try:
                                tail_target = int(tail.op_str, 16)
                            except ValueError:
                                continue
                            if compare_address < tail_target <= tail.address:
                                guards.add(tail.address)
                    return -digit if int(size_value) < 0 else digit
        return None

    def _materialized_bool_before(self, address, target_reg, max_back=0x80):
        """Follow MOV aliases back to a SETcc fed by a semantic bool value.

        GCC/MinGW materializza il risultato di RICH_COMPARE come intero
        -1/0/1 e lo SPILLA su uno slot di stack per attraversare i decref
        intercalati (``mov [rbp+X], eax … mov eax, [rbp+X]; cmp eax, 1``):
        il round-trip dello slot è seguito come alias oltre ai registri.
        Senza SETcc, la ricerca candidati usa la finestra stessa (la prova
        resta il collegamento alias/spill fino all'operazione bool/cmp)."""
        index = next((i for i, item in enumerate(self.insns)
                      if item.address == address), None)
        if index is None or target_reg is None:
            return None
        aliases = {target_reg}
        alias_slots = set()
        setcc_address = None
        window_items = list(reversed(self.insns[max(0, index - 50):index]))
        # Due passate: a ritroso il RELOAD dello slot precede lo SPILL
        # (lo spill è più vecchio); il secondo passaggio collega i registri
        # ricaricati dagli slot scoperti nel primo.
        for _pass in range(2):
            for item in window_items:
                if address - item.address > max_back * 2:
                    continue
                operands = split_ops(item.op_str)
                if item.mnemonic == 'mov' and len(operands) == 2:
                    dst = subreg64(operands[0])
                    src = subreg64(operands[1])
                    src_mem = parse_mem(operands[1])
                    dst_mem = parse_mem(operands[0])
                    if dst in aliases and src and not src_mem:
                        aliases.add(src)
                    elif src in aliases and dst_mem and not dst_mem[2]:
                        alias_slots.add((dst_mem[0], dst_mem[1]))
                    elif dst and src_mem and not src_mem[2] and \
                            (src_mem[0], src_mem[1]) in alias_slots:
                        aliases.add(dst)
                elif item.mnemonic in ('sete', 'setne', 'setz',
                                       'setnz') and \
                        operands and subreg64(operands[0]) in aliases:
                    setcc_address = item.address
                    break
            if setcc_address is not None:
                break
        candidates = []
        window = (max_back if setcc_address is not None else max_back * 2)
        for block in self.blocks.values():
            for op in block.ops:
                if op.kind == 'calc' and op.a is not None and \
                        op.a.op in ('bool', 'cmp', 'contains') and \
                        0 < address - op.va <= window:
                    candidates.append((op.va, op.a))
        if not candidates:
            return None
        if setcc_address is not None:
            candidates = [(va, sym) for va, sym in candidates
                          if 0 < setcc_address - va <= max_back]
            if not candidates:
                return None
        return max(candidates, default=(0, None),
                   key=lambda pair: pair[0])[1]

    # ---- salti ----
    def _exec_jcc(self, ins):
        m = ins.mnemonic
        try:
            tgt = int(ins.op_str.strip(), 16)
        except ValueError:
            tgt = None
        b = self._cur_block
        if ins.address in getattr(self, '_compound_guard_jcc', ()):
            # Continuation of a previously materialised compound comparison
            # (for example PyLong size+digit equality).  Its miss edge is
            # already represented by the source condition's first guard; keep
            # only the fallthrough here so native sub-guards cannot become a
            # nested Python ``if`` or an apparent coroutine error path.
            if tgt is not None:
                b.edges.append((tgt, 'guard_fail'))
            return
        if self.gen_mode and tgt is not None:
            resume_targets = set(self.gen_resume.values())
            # Entry dispatch edges select a native re-entry state, not a
            # source-level branch.  _prepare_generator already removed those
            # targets from structural successors; keep the symbolic edge set
            # consistent so Structurer follows the first-invocation fallthrough.
            if b.start < self.gen_dispatch_end and tgt in resume_targets:
                return
            # A suspension block jumps to the shared C epilogue after storing
            # its state.  Its source-level continuation is the corresponding
            # resume target discovered from that same state value.
            if m == 'jmp' and b.start in self.gen_yield_blocks:
                resume = self.gen_resume.get(self.gen_yield_blocks[b.start])
                if resume in self.blocks:
                    b.edges.append((resume, 'goto'))
                return
        if m == 'jmp':
            if tgt is not None:
                b.edges.append((tgt, 'goto'))
            return
        jcc = m
        ck = self._cond_kind
        cv = self._cond_val
        if tgt is None:
            return
        # registra il sym della condizione con l'edge (attraversa i blocchi)
        if cv is not None and ck not in ('null_or_bool', 'refcount',
                                         'nbool_exc', 'tpnull'):
            b.conds.append((tgt, 'cond_sym', cv))
        if ck == 'nbool_exc':
            if jcc in ('jne', 'jnz'):
                b.edges.append((tgt, 'goto'))
                for successor in b.succs:
                    if successor != tgt:
                        b.edges.append((successor, 'error'))
            else:
                # je verso il sentinel d'errore (-1 di RICH_COMPARE): il
                # FALLTHROUGH è il flusso Python vero (il confronto
                # booleano segue subito dopo, es. ``cmp eax,1; jne``).
                b.edges.append((tgt, 'error'))
                for successor in b.succs:
                    if successor != tgt:
                        b.edges.append((successor, 'goto'))
            return
        if ck == 'error_flag':
            b.edges.append((tgt, 'error'))
            return
        if ck == 'refcount':
            # Both arms are ordinary runtime flow: one skips deallocation,
            # the other performs it and rejoins.  Refcount zero is not a
            # Python exception and must not sever a loop latch.
            b.edges.append((tgt, 'goto'))
            return
        if ck == 'c_int':
            # check C su intero (threading/pending calls): il salto verso
            # un target precedente (back edge del loop Nuitka) è NORMALE
            if tgt < ins.address:
                b.edges.append((tgt, 'goto'))
            else:
                b.edges.append((tgt, 'error'))
            return
        if ck == 'runtime_success':
            # Runtime/GIL housekeeping returns a native success flag.  The
            # non-zero arm resumes Python execution; the other arm enters
            # pending-call/exception machinery and is never a source branch.
            if jcc in ('jne', 'jnz'):
                b.edges.append((tgt, 'goto'))
                for successor in b.succs:
                    if successor != tgt:
                        b.edges.append((successor, 'error'))
            else:
                b.edges.append((tgt, 'error'))
            return
        if ck == 'iter_null':
            # NULL check su ITERATOR_NEXT: target = blocco check stop-iter.
            b.edges.append((tgt, 'stopiter'))
            return
        if ck == 'is_none':
            # cmp ptr, Py_None: (s == None) — je → yes=is_none
            if jcc == 'je':
                b.edges.append((tgt, 'cond_yes'))
                b.ops.append(NdxOp('condmark', a=cv, b='is', va=ins.address))
            elif jcc == 'jne':
                b.edges.append((tgt, 'cond_no'))
                b.ops.append(NdxOp('condmark', a=cv, b='is', va=ins.address))
            else:
                b.edges.append((tgt, 'cond_unknown'))
            self._cond_polarity = jcc
            return
        if ck == 'is_single':
            # cmp reg, [rip+IAT singleton] (True/False/None): l'arm del
            # salto e' l'esito dell'identita' Python ``x is <singleton>``.
            if jcc == 'je':
                b.edges.append((tgt, 'cond_yes'))
                b.ops.append(NdxOp('condmark', a=cv, b='is', va=ins.address))
            elif jcc == 'jne':
                b.edges.append((tgt, 'cond_no'))
                b.ops.append(NdxOp('condmark', a=cv, b='is', va=ins.address))
            else:
                b.edges.append((tgt, 'cond_unknown'))
            self._cond_polarity = jcc
            return
        if ck == 'tpnull':
            if jcc == 'jne':
                b.edges.append((tgt, 'cond_unknown'))
            elif jcc == 'je':
                b.edges.append((tgt, 'error'))
            else:
                b.edges.append((tgt, 'cond_unknown'))
            return
        if ck == 'null_or_bool':
            # A PyObject* producer is checked as ``test value,value``.  For a
            # JE/JZ always selects the NULL/error path; JNE/JNZ always selects
            # the non-NULL success continuation.  Nuitka reuses backward cold
            # cleanup labels, so target direction is not semantic evidence.
            if jcc in ('jne', 'jnz'):
                b.edges.append((tgt, 'goto'))
                for successor in b.succs:
                    if successor != tgt:
                        b.edges.append((successor, 'error'))
            else:
                b.edges.append((tgt, 'error'))
            return
        if ck == 'nbool':
            _truth_test = isinstance(self._cond_val, NdxSV) and \
                self._cond_val.op == 'bool'
            if jcc == 'je':
                b.edges.append((tgt, 'cond_yes'))
            elif jcc == 'jne':
                b.edges.append((tgt, 'cond_no'))
            elif _truth_test and jcc in ('jg', 'jge', 'ja'):
                # risultato > 0: arm vero del test di verita' (0/1)
                b.edges.append((tgt, 'cond_yes'))
            elif _truth_test and jcc in ('jle', 'jl', 'jbe'):
                b.edges.append((tgt, 'cond_no'))
            else:
                b.edges.append((tgt, 'error'))
            return
        if ck in ('cbool', 'auto', 'int_nonzero'):
            _truth_test = isinstance(self._cond_val, NdxSV) and \
                self._cond_val.op == 'bool'
            if jcc == 'jne':
                b.edges.append((tgt, 'cond_yes'))
            elif jcc == 'je':
                b.edges.append((tgt, 'cond_no'))
            elif _truth_test and jcc in ('jg', 'jge', 'ja'):
                b.edges.append((tgt, 'cond_yes'))
            elif _truth_test and jcc in ('jle', 'jl', 'jbe'):
                b.edges.append((tgt, 'cond_no'))
            else:
                b.edges.append((tgt, 'error'))
            return
        incoming_null_test = False
        if ck is None and jcc in ('je', 'jz'):
            for predecessor in b.preds:
                previous = self.blocks.get(predecessor)
                if previous is None or not previous.insns:
                    continue
                last = previous.insns[-1]
                operands = split_ops(last.op_str)
                if last.mnemonic == 'test' and len(operands) == 2 and \
                        subreg64(operands[0]) is not None and \
                        subreg64(operands[0]) == subreg64(operands[1]):
                    incoming_null_test = True
                    break
        if incoming_null_test and self._target_starts_exception_path(tgt):
            b.edges.append((tgt, 'error'))
            return
        b.edges.append((tgt, 'cond_unknown'))

    def _target_starts_exception_path(self, target, max_blocks=200,
                                      max_span=0x400):
        """Prove that a branch target enters Nuitka exception machinery."""
        strong = {
            'Nuitka_Err_NormalizeException', 'PyErr_NormalizeException',
            'CHAIN_EXCEPTION', 'RERAISE_EXCEPTION', 'MAKE_TRACEBACK',
            'ADD_TRACEBACK', 'RAISE_CURRENT_EXCEPTION_NAME_ERROR',
            'FORMAT_UNBOUND_LOCAL_ERROR', 'FORMAT_UNBOUND_CLOSURE_ERROR',
        }
        work = [target]
        seen = set()
        while work and len(seen) < max_blocks:
            start = work.pop(0)
            if start in seen or start not in self.blocks or \
                    start - target > max_span:
                continue
            seen.add(start)
            block = self.blocks[start]
            for item in block.insns:
                if item.mnemonic != 'call':
                    continue
                name = None
                if item.op_str.startswith('0x'):
                    name = self._call_name_safe(item.op_str)
                elif 'rip' in item.op_str:
                    slot = rip_target(item)
                    name = self.img.imports.get(slot) if slot is not None \
                        else None
                if name in strong:
                    return True
            for successor in block.succs:
                if successor >= target and successor - target <= max_span:
                    work.append(successor)
        return False

    # ---- fine blocco: op di controllo ----
    def _finish_block(self, b):
        if not b.insns:
            return
        last = b.insns[-1]
        # A suspension block's machine RET/JMP only hands control back to the
        # coroutine/generator driver.  _exec_block has already emitted the
        # source-level yield where applicable and the synthetic state edge
        # points at the real continuation; never materialise this native
        # epilogue as a Python ``return``.
        if self.gen_mode and b.start in self.gen_yield_blocks:
            return
        # ret diretto
        if last.mnemonic == 'ret':
            rax = self._reg('rax')
            # `imm` 0 in rax = C NULL (function_error_exit di Nuitka),
            # NON lo zero Python (che arriva come `const` da mod_consts):
            # è l'uscita d'erroce condivisa, non un return Python.
            if rax is not None and rax.op == 'imm' and rax.a == 0:
                rax = None
            # Generator/coroutine resumers return C NULL even for a Python
            # ``return value``.  The value is instead written to the context
            # object's m_returned field in the same official template
            # epilogue.  A same-block genobj store is the structural proof;
            # yield blocks are handled independently above.
            context_store = self.gen_result_stores.get(b.start) \
                if self.gen_mode and \
                b.start not in self.gen_yield_blocks else None
            if rax is None and context_store is not None:
                b.ops.append(NdxOp('ret', a=context_store[2],
                                   va=last.address))
                return
            if rax is None or rax.op in ('tstate', 'frame', 'excstate',
                                         'pars', 'self', 'modconsts'):
                b.ops.append(NdxOp('ret', a=None, va=last.address))
            else:
                b.ops.append(NdxOp('ret', a=rax, va=last.address))
            return
        # jmp verso blocco ret (epilogo condiviso) con rax = valore → return
        if last.mnemonic == 'jmp':
            try:
                tgt = int(last.op_str.strip(), 16)
            except ValueError:
                tgt = None
            if tgt is not None and tgt not in self.blocks and self.img.is_exec(tgt):
                # A jump outside this function to a proven Python-value helper
                # is a tail call. Its result is the implementation's result.
                resolved = self.res.resolve(tgt)
                if resolved and len(resolved) > 2 and resolved[2] is not None:
                    self._exec_call(last)
                    result = self._reg('rax')
                    if isinstance(result, NdxSV) and result.op not in (
                            'tstate', 'frame', 'excstate', 'imm'):
                        b.ops.append(NdxOp('ret', a=result, va=last.address))
                        return
            if tgt is not None and tgt in self.blocks:
                tb = self.blocks[tgt]
                if tb.insns and tb.insns[-1].mnemonic == 'ret':
                    context_store = self.gen_result_stores.get(b.start) \
                        if self.gen_mode and \
                        b.start not in self.gen_yield_blocks else None
                    if context_store is not None:
                        b.ops.append(NdxOp('ret', a=context_store[2],
                                           va=last.address))
                        b.ops.append(NdxOp('retmark', va=last.address))
                        return
                    rax = self._reg('rax')
                    if rax is not None and rax.op not in (
                            'tstate', 'frame', 'excstate', 'pars', 'self',
                            'modconsts', 'imm'):
                        b.ops.append(NdxOp('ret', a=rax, va=last.address))
                        b.ops.append(NdxOp('retmark', va=last.address))
                        return
        # store del valore di ritorno in rax poi jmp generico: se il blocco
        # contiene `mov rax, X` come ultima scrittura di rax e termina in jmp
        # a blocco non-ret, lascia perdere (goto normale)
        # MSVC can place the m_returned store immediately before a shared
        # epilogue as fallthrough rather than JMP.  The same context-store
        # proof applies when the block has one successor ending in RET.
        context_store = self.gen_result_stores.get(b.start) \
            if self.gen_mode and b.start not in self.gen_yield_blocks \
            else None
        if context_store is not None and len(b.succs) == 1:
            successor = self.blocks.get(b.succs[0])
            if successor is not None and successor.insns and \
                    successor.insns[-1].mnemonic == 'ret':
                b.ops.append(NdxOp('ret', a=context_store[2],
                                   va=last.address))
                b.ops.append(NdxOp('retmark', va=last.address))

    # ------------------------------------------------------------------ API
    def _resolve_phi_locations(self):
        """Copy-propagation dei phi sui risultati del pass simbolico.

        Per ogni blocco, un sym `loc ('reg', r)` (phi creato al merge) i
        cui predecessori NORMALI portano tutti lo stesso valore non-None
        nel registro r è in realtà una copia: si sostituisce ovunque quel
        valore. I phi veri (accumulatori: predecessori in disaccordo)
        restano. Basato sugli stati OUT finali del worklist."""
        snapshots = getattr(self, 'native_return_phis', None)
        if snapshots is None:
            snapshots = self.native_return_phis = {}
        for block in self.blocks.values():
            for operation in block.ops:
                value = operation.a
                if operation.kind == 'ret' and isinstance(value, NdxSV) and \
                        id(value) in getattr(self, '_phi_inputs', {}):
                    snapshots[block.start] = value
        OUT = getattr(self, '_final_out', None)
        if not OUT:
            return 0
        _phi_resolved = 0
        pending_conditional_stores = dict(getattr(
            self, '_conditional_phi_definitions', {}) or {})
        # corpi dei loop naturali (back-edge u→h, h<=u): i phi usati DENTRO
        # un loop possono essere accumulatori (miscompile se sostituiti col
        # valore pre-loop); fuori dal loop un producer-concordante è una
        # copia e si sostituisce.
        # corpi dei loop naturali: un back-edge è u→h dove h DOMINA u
        # (definizione esatta dei loop naturali sul CFG). Il confronto
        # fra indirizzi (target <= sorgente) è un'euristica del layout:
        # un ramo che salta al proprio join posto a un indirizzo minore
        # verrebbe scambiato per back-edge, marcando quasi tutta la
        # funzione come "loop" e disattivando il recupero dei phi
        # condizionali proprio sui join dei branch.
        loop_blocks = set()
        succs_all = {st3: [s3 for s3 in b3.succs if s3 in self.blocks]
                     for st3, b3 in self.blocks.items()}
        preds_all = {st3: [] for st3 in self.blocks}
        for u3, ss3 in succs_all.items():
            for s3 in ss3:
                if s3 in preds_all:
                    preds_all[s3].append(u3)
        flow_entry = getattr(self, 'gen_entry', None)
        if flow_entry not in self.blocks:
            flow_entry = min(self.blocks) if self.blocks else None
        if flow_entry is not None:
            idom_all, _rpo_all = dominators(
                succs_all, flow_entry,
                lambda node: preds_all.get(node, ()))

            def _dominates_all(header, node):
                cursor = node
                guard = 0
                while cursor is not None and guard < 10000:
                    guard += 1
                    if cursor == header:
                        return True
                    if cursor == flow_entry:
                        return False
                    cursor = idom_all.get(cursor)
                return False

            for u3, ss3 in succs_all.items():
                for h3 in ss3:
                    if not _dominates_all(h3, u3):
                        continue
                    body3 = {h3, u3}
                    work3 = [u3]
                    while work3:
                        cur3 = work3.pop()
                        for p3 in preds_all.get(cur3, ()):
                            if p3 not in body3:
                                body3.add(p3)
                                work3.append(p3)
                    loop_blocks |= body3

        def conditional_phi(block_start, incoming):
            """Build an if-expression from a proven two-arm CFG join."""
            if block_start in loop_blocks or len(incoming) < 2:
                return None
            incoming_by_pred = {pred: value for pred, value in incoming}
            # A conditional phi models ONE Python value chosen between two
            # live branches.  Machine markers can never be its arms: `imm`
            # immediates are C-level data (traceback line numbers, NULL,
            # sizes), and raw `loc`/frame symbols carry no Python object.
            machine_ops = ('imm', 'loc', 'tstate', 'frame', 'excstate',
                           'pars', 'modconsts', 'stackaddr', 'gaddr')

            def _python_value(value):
                return isinstance(value, NdxSV) and \
                    value.op not in machine_ops

            def arm_value(start, join, limit=300):
                queue = [(start, 0)]
                seen = set()
                reached = []
                while queue and len(seen) < limit:
                    node, distance = queue.pop(0)
                    if node in seen or node == join:
                        continue
                    seen.add(node)
                    if node in incoming_by_pred:
                        value = incoming_by_pred[node]
                        if _python_value(value):
                            reached.append((distance, value))
                        continue
                    block = self.blocks.get(node)
                    if block is None or block.kind in ('error', 'stopiter'):
                        continue
                    # Control never flows through a raise: its arm is
                    # terminated Python execution, not a value producer.
                    if any(operation.kind == 'raise'
                           for operation in block.ops):
                        continue
                    for successor in succs_all.get(node, ()):
                        queue.append((successor, distance + 1))
                if not reached:
                    return None
                first = reached[0][1]
                if any(value is not first and not _sv_eq(value, first)
                       for _distance, value in reached[1:]):
                    return None
                return min(distance for distance, _value in reached), first

            candidates = []
            for controller in self.blocks.values():
                condition = next((symbol for _target, _edge, symbol
                                  in reversed(controller.conds or [])
                                  if isinstance(symbol, NdxSV)), None)
                if condition is None:
                    continue
                yes = next((target for target, edge_type
                            in controller.edges
                            if edge_type == 'cond_yes'), None)
                no = next((target for target, edge_type
                           in controller.edges
                           if edge_type == 'cond_no'), None)
                normal_successors = [successor
                                     for successor in succs_all.get(
                                         controller.start, ())
                                     if successor in self.blocks]
                if yes is None and no is not None:
                    yes = next((successor for successor in normal_successors
                                if successor != no), None)
                if no is None and yes is not None:
                    no = next((successor for successor in normal_successors
                               if successor != yes), None)
                if yes is None or no is None or yes == no:
                    continue
                yes_reached = arm_value(yes, block_start)
                no_reached = arm_value(no, block_start)
                if yes_reached is None or no_reached is None:
                    continue
                yes_distance, yes_value = yes_reached
                no_distance, no_value = no_reached
                if yes_value is no_value or _sv_eq(yes_value, no_value):
                    continue
                # The controller must DOMINATE the join.  A branch that a
                # path can bypass (e.g. an outer ``if`` whose arm already
                # returned) must never be folded into an if-expression at
                # this join: doing so would pull a guarded value out of
                # its guard and change the program's semantics.
                if not _dominates_all(controller.start, block_start):
                    continue
                candidates.append((yes_distance + no_distance,
                                   max(yes_distance, no_distance),
                                   controller.start,
                                   ndx_k('ifexp', condition,
                                         yes_value, no_value)))
            if not candidates:
                return None
            selected = min(candidates, key=lambda item: item[:3])
            joins = getattr(self, '_ifexp_controller_joins', None)
            if joins is None:
                joins = self._ifexp_controller_joins = {}
            joins[selected[2]] = block_start
            return selected[3]

        def resolve_at(block_start, loc):
            b = self.blocks.get(block_start)
            if b is None:
                return None
            vals = []
            for p in b.preds:
                if p not in OUT or p == block_start:
                    continue
                pb = self.blocks.get(p)
                if pb is not None and pb.kind == 'error' and                         'handler_sem' in pb.flags:
                    continue
                et = self._edge_type(p, block_start)                     if hasattr(self, '_edge_type') else None
                if et == 'error':
                    continue
                st = OUT[p]
                if loc[0] == 'reg':
                    v = st['regs'].get(loc[1])
                else:
                    v = st['slots'].get((loc[1], loc[2]))
                if v is None:
                    continue
                if getattr(v, 'op', None) == 'loc' and v.a == loc:
                    continue      # self-phi
                vals.append((p, v))
            if not vals:
                return None
            first = vals[0][1]
            for _predecessor, v in vals[1:]:
                if v is not first and not _sv_eq(v, first):
                    selected = conditional_phi(block_start, vals)
                    if selected is not None:
                        pending_conditional_stores.setdefault(
                            (block_start, loc), selected)
                        self._conditional_phi_definitions = dict(
                            pending_conditional_stores)
                    return selected
            return first

        # A common Nuitka return template assigns the result in two branch
        # arms, funnels both through decref-only blocks, then executes one
        # ``mov return_reg, callee_saved`` epilogue.  Worklist order may leave
        # that RET holding one arm's value directly instead of a ``loc`` phi,
        # so the ordinary substitution pass below has nothing to resolve.
        # Recover the physical return source and walk backwards to the first
        # normal merge whose incoming values prove a conditional phi.
        for return_block in self.blocks.values():
            # Only an unresolved phi return needs recovery: a concrete
            # Python producer already in the op is authoritative, and a
            # NULL return is the shared error exit (no Python value).
            return_ops = [operation for operation in return_block.ops
                          if operation.kind == 'ret' and
                          isinstance(operation.a, NdxSV) and
                          operation.a.op == 'loc']
            if not return_ops or not return_block.insns:
                continue
            return_address = max((operation.va or return_block.end)
                                 for operation in return_ops)
            instruction_index = next((index for index, item in
                                      enumerate(self.insns)
                                      if item.address >= return_address),
                                     len(self.insns))
            source_register = None
            for item in reversed(self.insns[
                    max(0, instruction_index - 64):instruction_index + 1]):
                operands = split_ops(item.op_str)
                if item.mnemonic == 'mov' and len(operands) == 2 and \
                        subreg64(operands[0]) == self.abi.ret_reg:
                    candidate = subreg64(operands[1])
                    if candidate in GP_REGS and \
                            candidate != self.abi.ret_reg:
                        source_register = candidate
                    break
            if source_register is None:
                continue
            location = ('reg', source_register)
            queue = [(return_block.start, 0)]
            seen = set()
            recovered = None
            while queue and len(seen) < 500:
                node, distance = queue.pop(0)
                if node in seen:
                    continue
                seen.add(node)
                normal_predecessors = [
                    predecessor for predecessor in preds_all.get(node, ())
                    if predecessor in self.blocks and
                    self.blocks[predecessor].kind == 'normal' and
                    self._edge_type(predecessor, node) != 'error']
                if len(normal_predecessors) >= 2:
                    selected = resolve_at(node, location)
                    if isinstance(selected, NdxSV) and \
                            selected.op == 'ifexp':
                        recovered = selected
                        break
                for predecessor in normal_predecessors:
                    queue.append((predecessor, distance + 1))
            if recovered is not None:
                for operation in return_ops:
                    operation.a = recovered

        def substitute(sym, mapping, depth=0):
            if not isinstance(sym, NdxSV) or depth > 12:
                return sym
            loc = sym.a if sym.op == 'loc' else None
            if loc is not None and loc in mapping:
                return mapping[loc]
            changed = False
            parts = {}
            for f in ('a', 'b', 'c'):
                v = getattr(sym, f)
                if isinstance(v, NdxSV):
                    nv = substitute(v, mapping, depth + 1)
                    if nv is not v:
                        changed = True
                    parts[f] = nv
                elif isinstance(v, list):
                    nl = []
                    lc = False
                    for x in v:
                        if isinstance(x, NdxSV):
                            nx = substitute(x, mapping, depth + 1)
                            if nx is not x:
                                lc = True
                            nl.append(nx)
                        else:
                            nl.append(x)
                    if lc:
                        changed = True
                    parts[f] = nl
                else:
                    parts[f] = v
            if changed:
                return ndx_k(sym.op, parts['a'], parts['b'], parts['c'],
                             n=sym.n)
            return sym

        for b in self.blocks.values():
            mapping = {}

            def collect(sym, depth=0):
                if not isinstance(sym, NdxSV) or depth > 12:
                    return
                if sym.op == 'loc' and isinstance(sym.a, tuple) and                         sym.a not in mapping:
                    r = resolve_at(b.start, sym.a)
                    # SOLO valori foglia (nomi/costanti/parametri): un
                    # phi d'accumulo (lista/dict in append) che tutti i
                    # preds riportano come init NON è una copia — è il
                    # valore pre-loop visto dal primo visit. Sostituirlo
                    # muta `acc.append(x)` in `[].append(x)` e corrompe
                    # il ritorno. I producer restano phi.
                    if r is not None:
                        rop = getattr(r, 'op', None)
                        in_loop = b.start in loop_blocks
                        if rop in ('var', 'const', 'global', 'imm',
                                   'cellref'):
                            mapping[sym.a] = r
                        elif rop in ('call', 'mcall', 'binop', 'cmp',
                                     'getattr', 'sub', 'len', 'ifexp') and \
                                not in_loop:
                            mapping[sym.a] = r
                for f in ('a', 'b', 'c'):
                    v = getattr(sym, f)
                    if isinstance(v, NdxSV):
                        collect(v, depth + 1)
                    elif isinstance(v, list):
                        for x in v:
                            if isinstance(x, NdxSV):
                                collect(x, depth + 1)

            for o in b.ops:
                for f in ('a', 'b', 'c'):
                    v = getattr(o, f)
                    if isinstance(v, NdxSV):
                        collect(v)
                    elif isinstance(v, list):
                        for x in v:
                            if isinstance(x, NdxSV):
                                collect(x)
            for t, et, cs in (b.conds or []):
                if isinstance(cs, NdxSV):
                    collect(cs)
            if not mapping:
                continue
            for o in b.ops:
                for f in ('a', 'b', 'c'):
                    v = getattr(o, f)
                    if isinstance(v, NdxSV):
                        setattr(o, f, substitute(v, mapping))
                    elif isinstance(v, list):
                        setattr(o, f, [substitute(x, mapping)
                                       if isinstance(x, NdxSV) else x
                                       for x in v])
            b.conds = [(t, et, substitute(cs, mapping)
                        if isinstance(cs, NdxSV) else cs)
                       for t, et, cs in (b.conds or [])]

        # A conditional phi represents one Python value evaluated once.  Put
        # that definition at its exact CFG join and propagate it only through
        # dominated straight-line regions until the physical location is
        # overwritten.  This both preserves side-effect count and lets code
        # object varnames name the source local (when one exists).
        for (origin, location), value in pending_conditional_stores.items():
            block = self.blocks.get(origin)
            if block is None or any(operation.kind == 'store' and
                                    operation.a == location and
                                    _sv_eq(operation.b, value)
                                    for operation in block.ops):
                continue
            materialized_store = NdxOp('store', a=location, b=value,
                                       va=origin)
            block.ops.append(materialized_store)
            block.ops.sort(key=lambda operation: operation.va or origin)
            queue = list(succs_all.get(origin, ()))
            seen = set()
            while queue and len(seen) < 1000:
                node = queue.pop(0)
                if node in seen or node not in self.blocks:
                    continue
                seen.add(node)
                candidate = self.blocks[node]
                replacement = {location: value}
                for operation in candidate.ops:
                    for field in ('a', 'b', 'c'):
                        child = getattr(operation, field)
                        if isinstance(child, NdxSV):
                            setattr(operation, field,
                                    substitute(child, replacement))
                        elif isinstance(child, list):
                            setattr(operation, field, [
                                substitute(item, replacement)
                                if isinstance(item, NdxSV) else item
                                for item in child])
                candidate.conds = [
                    (target, edge_type,
                     substitute(symbol, replacement)
                     if isinstance(symbol, NdxSV) else symbol)
                    for target, edge_type, symbol in candidate.conds]
                overwritten = False
                if location[0] == 'reg':
                    register = location[1]
                    for item in candidate.insns:
                        operands = split_ops(item.op_str)
                        if not operands or \
                                subreg64(operands[0]) != register:
                            continue
                        if item.mnemonic not in ('cmp', 'test', 'push'):
                            overwritten = True
                            break
                else:
                    overwritten = any(
                        operation.kind == 'store' and
                        operation.a == location
                        for operation in candidate.ops)
                if not overwritten:
                    queue.extend(succs_all.get(node, ()))

            # La propagazione sopra ha sostituito il valore al posto della
            # locazione in ogni uso raggiungibile. Se nessuna operazione o
            # condizione referenzia ancora la locazione, la definizione
            # materializzata è morta: il suo valore Python è già reso
            # inline in ogni uso. Tenerla duplicherebbe l'intera espressione
            # condizionale come assegnazione orfana (e impedirebbe l'inline
            # dei temporanei usati sia lì che negli usi reali).
            def _location_referenced(node, depth=0):
                if not isinstance(node, NdxSV) or depth > 12:
                    return False
                if node.op == 'loc' and node.a == location:
                    return True
                for field in ('a', 'b', 'c'):
                    child = getattr(node, field)
                    if isinstance(child, NdxSV):
                        if _location_referenced(child, depth + 1):
                            return True
                    elif isinstance(child, list):
                        if any(_location_referenced(item, depth + 1)
                               for item in child
                               if isinstance(item, NdxSV)):
                            return True
                return False

            still_referenced = False
            for other in self.blocks.values():
                for operation in other.ops:
                    if any(_location_referenced(
                            getattr(operation, field))
                           for field in ('a', 'b', 'c')):
                        still_referenced = True
                        break
                if not still_referenced:
                    for _target, _edge, symbol in (other.conds or []):
                        if _location_referenced(symbol):
                            still_referenced = True
                            break
                if still_referenced:
                    break
            if not still_referenced:
                block.ops = [operation for operation in block.ops
                             if operation is not materialized_store]
        return _phi_resolved

    def lift(self):
        self.build_cfg()
        if not self.blocks:
            return self
        self._discover_inlined_binop_joins()
        self._find_frame_cache_slots()
        # il pass simbolico genera i TIPI di edge (error/cond/goto):
        # la classificazione dei blocchi li usa → prima simbolico, poi classify
        self.symbolic_pass()
        if self._discover_specialized_numeric_joins():
            # RPO propagates a whole chain in one pass; the second pass also
            # stabilises nested MSVC fast paths without a source-specific cap.
            self.symbolic_pass()
            self.symbolic_pass()
        self.classify_blocks()
        # Classification identifies C-API exception construction paths.  A
        # second value-flow pass excludes those predecessors from phi merges,
        # preserving values produced by the successful protocol path.
        self.symbolic_pass()
        self.classify_blocks()
        self._collapse_native_constant_copy_loops()
        # Copy-propagation dei phi LEAF-ONLY con convergenza: cap visite
        # alzato (12) + pass di stabilizzazione extra; la sostituzione è
        # ristretta a foglie NON-parametro (var/const/imm/global/cellref)
        # — i phi d'accumulo (containers/producers) e i binding dei
        # parametri restano phi, eliminando le miscompilation osservate.
        try:
            self.symbolic_pass()   # stabilizzazione: stati OUT definitivi
            if self._resolve_phi_locations():
                self.symbolic_pass()   # propaga i valori sostituiti
        except Exception:
            pass
        if self._inlined_binop_joins:
            self._collapse_inlined_binop_regions()
            # Re-run value flow on the collapsed graph.  This separates normal
            # return values from NULL/error epilogues that share the final RET.
            self.symbolic_pass()
            self.classify_blocks()
            self._collapse_inlined_binop_regions()
            self._materialize_collapsed_returns()
        # Later value-flow stabilisation replays physical Jcc instructions;
        # re-apply the proven native-loop collapse to remove those regenerated
        # self edges and descriptor-cursor expressions from the final CFG.
        self._collapse_native_constant_copy_loops()
        # Inlined-operation recovery above may run one final symbolic pass,
        # which necessarily rebuilds block operations.  Re-materialise proven
        # conditional phis afterwards so their source assignment and
        # downstream value propagation survive into the final IR.
        try:
            self._resolve_phi_locations()
        except Exception:
            pass
        self._repair_unresolved_returns()
        self._materialize_authoritative_constants()
        # The keyword Call node now owns these exact key/value expressions.
        # Do not emit the native anonymous dict allocation and its population
        # a second time as source statements.
        if self.consumed_keyword_mappings or self.consumed_argument_vectors:
            consumed = self.consumed_keyword_mappings
            consumed_vectors = self.consumed_argument_vectors
            for block in self.blocks.values():
                filtered = []
                for operation in block.ops:
                    value = operation.a
                    if operation.kind == 'calc' and \
                            isinstance(value, NdxSV) and \
                            id(value) in consumed_vectors:
                        continue
                    if operation.kind == 'store' and \
                            isinstance(operation.b, NdxSV) and \
                            id(operation.b) in consumed_vectors:
                        continue
                    if operation.kind == 'calc' and \
                            isinstance(value, NdxSV) and \
                            value.op == 'dict_empty' and value.n in consumed:
                        continue
                    if operation.kind == 'store_sub' and \
                            isinstance(value, NdxSV) and \
                            value.op == 'dict_empty' and value.n in consumed:
                        continue
                    filtered.append(operation)
                block.ops = filtered
        # Rich-compare helpers return a raw C int which Nuitka commonly spills
        # to a volatile register solely so a later ``cmp result, 1`` can
        # branch.  That spill is not a Python local assignment.  A genuine
        # source boolean local has an authoritative frame/context location;
        # remove only unauthoritative register stores whose exact comparison
        # is consumed as a CFG condition.
        condition_value_keys = set()
        for block in self.blocks.values():
            for _target, _edge, condition in block.conds or ():
                if isinstance(condition, NdxSV):
                    condition_value_keys.add(sv_key(condition))
        if condition_value_keys:
            authoritative = getattr(self, 'authoritative_loc_names', {}) or {}
            for block in self.blocks.values():
                block.ops = [
                    operation for operation in block.ops
                    if not (operation.kind == 'store' and
                            isinstance(operation.a, tuple) and
                            operation.a[:1] == ('reg',) and
                            operation.a not in authoritative and
                            isinstance(operation.b, NdxSV) and
                            operation.b.op in ('cmp', 'bool', 'contains') and
                            sv_key(operation.b) in condition_value_keys)]
        # Register-only one-use transports are compiler SSA plumbing, not
        # Python assignments.  Two especially common forms are a bound/getattr
        # value immediately consumed as a call target and a call result
        # immediately consumed by MAKE_ITERATOR.  Match by NdxSV object
        # identity in the final pass; source locals that are reloaded through a
        # location node, or values used more than once, do not satisfy this.
        transport_uses = defaultdict(set)
        transport_values = set()
        stack_transport_values = set()

        def note_transports(value, seen=None):
            if not isinstance(value, NdxSV):
                return
            if seen is None:
                seen = set()
            marker = id(value)
            if marker in seen:
                return
            seen.add(marker)
            if value.op == 'getattr' and \
                    isinstance(value.a, NdxSV) and \
                    value.a.op == 'getattr':
                # In a native ``obj.attr.method(...)`` chain the first
                # attribute is only the receiver of the following lookup.
                # Object identity proves this is one uninterrupted compiler
                # expression; a real Python temporary is reloaded through a
                # location node and therefore does not match this transport.
                transport_values.add(id(value.a))
                stack_transport_values.add(id(value.a))
                transport_uses[id(value.a)].add(id(value))
            if value.op in ('contains', 'cmp', 'binop', 'sub'):
                for operand in (value.a, value.b, value.c):
                    if isinstance(operand, NdxSV) and \
                            operand.op == 'getattr':
                        # A getter embedded directly in the semantic
                        # expression is an SSA operand.  A source-level local
                        # would appear here as a location reload instead.
                        transport_values.add(id(operand))
                        stack_transport_values.add(id(operand))
                        transport_uses[id(operand)].add(id(value))
            if value.op in ('call', 'kwcall') and \
                    isinstance(value.a, NdxSV) and \
                    value.a.op == 'getattr':
                transport_values.add(id(value.a))
                stack_transport_values.add(id(value.a))
                transport_uses[id(value.a)].add(id(value))
            if value.op in ('call', 'kwcall', 'mcall'):
                argument_groups = ((value.b,) if value.op == 'call' else
                                   (value.b, value.c) if value.op == 'kwcall'
                                   else (value.c,))
                for group in argument_groups:
                    items = group if isinstance(group, (list, tuple)) \
                        else (group,)
                    for argument in items:
                        candidate = (argument.c if isinstance(argument, NdxSV)
                                     and argument.op == 'kwarg' else argument)
                        if isinstance(candidate, NdxSV) and \
                                candidate.op == 'getattr':
                            transport_values.add(id(candidate))
                            stack_transport_values.add(id(candidate))
                            transport_uses[id(candidate)].add(id(value))
            if value.op == 'iter' and isinstance(value.a, NdxSV) and \
                    value.a.op in ('call', 'kwcall', 'mcall'):
                transport_values.add(id(value.a))
                transport_uses[id(value.a)].add(id(value))
            if value.op == 'await' and isinstance(value.a, NdxSV) and \
                    value.a.op in ('call', 'kwcall', 'mcall'):
                # The awaited object is commonly spilled in the native stack
                # frame between CALL_* and ASYNC_AWAIT.  That spill is not a
                # Python assignment; a genuine coroutine local instead lives
                # in the persistent generator context across suspension.
                transport_values.add(id(value.a))
                stack_transport_values.add(id(value.a))
                transport_uses[id(value.a)].add(id(value))
            for child in (value.a, value.b, value.c):
                if isinstance(child, NdxSV):
                    note_transports(child, seen)
                elif isinstance(child, (list, tuple)):
                    for item in child:
                        if isinstance(item, NdxSV):
                            note_transports(item, seen)

        for block in self.blocks.values():
            for operation in block.ops:
                note_transports(operation.a)
                note_transports(operation.b)
                note_transports(operation.c)
            for _target, _edge, condition in block.conds or ():
                note_transports(condition)
        if transport_values:
            for block in self.blocks.values():
                block.ops = [
                    operation for operation in block.ops
                    if not (operation.kind == 'store' and
                            isinstance(operation.b, NdxSV) and
                            id(operation.b) in transport_values and
                            len(transport_uses[id(operation.b)]) == 1 and
                            isinstance(operation.a, tuple) and
                            (operation.a[:1] == ('reg',) or
                             (id(operation.b) in stack_transport_values and
                              operation.a[:1] == ('mem',) and
                              len(operation.a) > 1 and
                              operation.a[1] in ('rsp', 'rbp'))))]
        # value numbering: ricostruisci sym→locazione dalle op FINALI
        # (gli id degli NdxSV delle passate intermedie non sono affidabili)
        var_of_sym = {}
        for b in self.blocks.values():
            for o in b.ops:
                if o.kind == 'store' and o.b is not None:
                    var_of_sym[id(o.b)] = o.a
        self.var_of_sym = var_of_sym
        # marca epiloghi: blocchi che terminano in ret
        for b in self.blocks.values():
            if b.insns and b.insns[-1].mnemonic == 'ret':
                b.flags.add('ret_block')
        self._fold_truthiness_chains()
        # Anchor dei bind di module-init: i blocchi che contengono un
        # UPDATE_STRING_DICT.  Il module-init e' la sequenza dei bind in
        # ordine nativo (uno statement sorgente ciascuno); i percorsi di
        # check del protocollo class-creation sono intrecciati con edge
        # tipizzati error e possono uccidere il walk lineare — la
        # strutturazione riprende dal primo anchor non visitato.
        if getattr(self, 'is_module_code', False):
            anchors = set()
            for st, b in self.blocks.items():
                for o in b.ops:
                    value = o.a if o.kind in ('calc', 'expr') else None
                    if isinstance(value, NdxSV) and value.op == 'apicall' \
                            and isinstance(value.a, str) \
                            and str(value.a).startswith('UPDATE_STRING_DICT'):
                        anchors.add(st)
                        break
                    # side-effect call statements (module-level ``print``,
                    # ``sys.exit`` drivers): anchor del codice eseguibile
                    # oltre l'ultimo bind.  Le mcall del protocollo classe
                    # riprese qui finiscono nelle regioni machinery dello
                    # stream e non raggiungono il sorgente.
                    if isinstance(value, NdxSV) and \
                            value.op in ('mcall', 'call'):
                        anchors.add(st)
                        break
            self.module_bind_anchor_blocks = sorted(anchors)
        return self

    # ------------------------------------------------- catene di verita'
    def _fold_truthiness_chains(self):
        """Fold del lowering ``if not X:`` / ``if X:`` di Nuitka.

        La catena e': ``X is True`` (je→join), ``X is False`` (je→uscita
        falsy), ``X is None`` (je→uscita falsy), nb_bool(X) (jle→uscita
        falsy, caduta→join).  Tutti i test portano lo STESSO simbolo T e
        la catena converge sul join.  Il fold riscrive il blocco-entry con
        la condizione ``not T`` (cond_yes→uscita falsy, cond_no→join) ed
        elimina i blocchi interni: lo structurer vede UN if semplice con
        bracci corretti, senza sintesi di break/continue.
        """
        def cond_of(blk):
            for _t, _kind, csym in (blk.conds or ()):
                if isinstance(csym, NdxSV):
                    return csym
            return None

        def yes_target(blk):
            for t, et in blk.edges:
                if et == 'cond_yes':
                    return t
            return None

        def no_target(blk, yes):
            for t, et in blk.edges:
                if et == 'cond_no':
                    return t
            for s in blk.succs:
                if s != yes:
                    return s
            return None

        for e_addr in sorted(self.blocks):
            e = self.blocks.get(e_addr)
            if e is None or not e.conds:
                continue
            sym0 = cond_of(e)
            if sym0 is None or sym0.op != 'cmp' or sym0.a != 'is':
                continue
            tc = sym0.c
            if not (isinstance(tc, NdxSV) and tc.op == 'const' and
                    tc.a is True):
                continue
            T = sym0.b
            j = yes_target(e)
            if j is None or j not in self.blocks:
                continue
            # gli ALTRI successori dell'entry = inizio catena
            others = [s for s in e.succs if s != j]
            if len(others) != 1:
                continue
            cur = others[0]
            chain = []
            glue = []
            falsy = set()
            ok = False
            for _depth in range(14):
                cb = self.blocks.get(cur)
                if cb is None or cur == j or cur == e_addr:
                    break
                cs = cond_of(cb)
                if cs is None:
                    # blocco colla del dispatch (null-check tp_as_number /
                    # nb_bool): attraversa il solo proseguimento non-error
                    fwd = [s for s in cb.succs if s in self.blocks and
                           not any(t2 == s and et in ('error', 'stopiter')
                                   for t2, et in cb.edges)]
                    if len(fwd) == 1:
                        glue.append(cur)
                        cur = fwd[0]
                        continue
                    break
                cy = yes_target(cb)
                cn = no_target(cb, cy) if cy is not None else None
                if cs.op == 'cmp' and cs.a == 'is' and \
                        _sv_eq(cs.b, T) and \
                        isinstance(cs.c, NdxSV) and cs.c.op == 'const' and \
                        cs.c.a in (False, None) and cy is not None:
                    # test singleton falso → uscita falsy; prosegui
                    chain.append(cur)
                    falsy.add(cy)
                    cur = cn
                    if cur is None or cur not in self.blocks:
                        break
                    continue
                if cs.op == 'bool' and _sv_eq(cs.a, T):
                    # test di verita' finale: il braccio falso (edge
                    # cond_no o, in mancanza, l'altro successore) esce;
                    # quello vero converge sul join
                    chain.append(cur)
                    cn2 = next((t for t, et in cb.edges if et == 'cond_no'),
                               None)
                    cy2 = next((t for t, et in cb.edges if et == 'cond_yes'),
                               None)
                    if cy2 is None and cn2 is not None:
                        cy2 = next((s for s in cb.succs if s != cn2), None)
                    elif cn2 is None and cy2 is not None:
                        cn2 = next((s for s in cb.succs if s != cy2), None)
                    if cn2 is not None:
                        falsy.add(cn2)
                    if cy2 == j:
                        ok = True
                    break
                break
            if not ok or not chain or not falsy:
                if os.environ.get('NDX_FOLD_DEBUG'):
                    print('FOLD abort', hex(e_addr), 'ok', ok,
                          'chain', [hex(c) for c in chain],
                          'falsy', [hex(f) for f in falsy])
                continue
            core = set(chain) | set(glue)
            escape_ok = set(falsy) | {j}
            b_target = min(falsy)
            # Chiusura dei blocchi-colla ORFANI (fallback IsTrue, cleanup
            # del dispatch): candidati = blocchi i cui predecessori stanno
            # tutti nel core/nei candidati.  Un candidato con operazioni
            # Python o con un successore reale fuori dal gruppo viene
            # CONSERVATO (e i suoi fratelli a valle restano raggiungibili
            # come orfani innocui).
            cand = set()
            changed = True
            while changed:
                changed = False
                for cand_addr in sorted(self.blocks):
                    if cand_addr in core or cand_addr in cand or \
                            cand_addr in escape_ok or cand_addr == e_addr:
                        continue
                    preds_in = [p for p in self.blocks[cand_addr].preds
                                if p in self.blocks]
                    if preds_in and \
                            all(p in core or p in cand for p in preds_in):
                        cand.add(cand_addr)
                        changed = True
            for c_addr in sorted(cand):
                cb2 = self.blocks[c_addr]
                if any(o.kind in ('store', 'store_sub', 'store_attr',
                                  'append', 'ret', 'raise', 'yield')
                       or (o.kind == 'calc' and o.a is not None and
                           o.a.op not in ('loc', 'reg', 'global',
                                          'gaddr', 'type_of', 'bool'))
                       for o in cb2.ops):
                    cand.discard(c_addr)
                    continue
                if any(s not in cand and s not in escape_ok
                       for s in cb2.succs if s in self.blocks):
                    cand.discard(c_addr)
            region = core | cand
            extern = False
            # il CORE non deve avere operazioni Python (solo cond) ne'
            # successori fuori dalla regione/escape
            for c_addr in core:
                cb2 = self.blocks[c_addr]
                if any(o.kind in ('store', 'store_sub', 'store_attr',
                                  'append', 'ret', 'raise', 'yield')
                       or (o.kind == 'calc' and o.a is not None and
                           o.a.op not in ('loc', 'reg', 'global',
                                          'gaddr', 'type_of', 'bool'))
                       for o in cb2.ops):
                    extern = True
                    break
                if any(s not in region and s not in escape_ok
                       for s in cb2.succs if s in self.blocks):
                    extern = True
                    break
            if extern:
                if os.environ.get('NDX_FOLD_DEBUG'):
                    print('FOLD extern-abort', hex(e_addr))
                continue
            # riscrivi l'entry: ``not T`` → cond_yes=falsy, cond_no=join
            e.conds = [(b_target, 'cond_sym', ndx_k('not', T))]
            e.edges = [(b_target, 'cond_yes'), (j, 'cond_no')]
            e.succs = [b_target, j]
            for c_addr in region:
                self.blocks.pop(c_addr, None)
            if os.environ.get('NDX_FOLD_DEBUG'):
                print('FOLD ok', hex(e_addr), 'cond not(T) yes',
                      hex(b_target), 'no', hex(j), 'deleted',
                      len(region))


    # ------------------------------------------------- utilità per struttura
    def normal_preds(self, st):
        out = []
        for p in self.blocks[st].preds:
            pb = self.blocks[p]
            # un pred è "normale" se il suo edge verso st non è error
            has_normal = False
            for t, et in pb.edges:
                if t == st and et in ('goto', 'cond_yes', 'cond_no',
                                      'cond_unknown', 'fallthrough'):
                    has_normal = True
            if not pb.edges and st in pb.succs:
                has_normal = True
            if has_normal:
                out.append(p)
        return out

    def edge_type(self, src, tgt):
        for t, et in self.blocks[src].edges:
            if t == tgt:
                return et
        if tgt in self.blocks[src].succs:
            return 'fallthrough'
        return None


def _sv_eq(a, b, *, ignore_call_sites=False):
    """Compare symbolic graphs without recursion, including shared/cyclic nodes."""
    pending = [(a, b)]
    seen = set()
    identities = {'tuple_build', 'list_build', 'dict_build',
                  'list_empty', 'dict_empty', 'set_empty',
                  'call', 'kwcall', 'mcall', 'nativecall', 'apicall', 'next'}
    while pending:
        left, right = pending.pop()
        if left is right:
            continue
        marker = (id(left), id(right))
        if marker in seen:
            continue
        seen.add(marker)
        if isinstance(left, NdxSV) or isinstance(right, NdxSV):
            if not isinstance(left, NdxSV) or not isinstance(right, NdxSV):
                return False
            if left.op != right.op:
                return False
            if left.n != right.n and (left.op == 'binop' or
                    (left.op in identities and not ignore_call_sites)):
                return False
            if left.op in ('const', 'imm') and type(left.a) is not type(right.a):
                return False
            pending.extend(((left.a, right.a), (left.b, right.b), (left.c, right.c)))
        elif isinstance(left, (list, tuple)) and isinstance(right, type(left)):
            if len(left) != len(right):
                return False
            pending.extend(zip(left, right))
        elif left != right:
            return False
    return True



