class NdxSt:
    """Statement ricostruito."""
    __slots__ = ('kind', 'a', 'b', 'c', 'd', 'e', 'f', 'line', 'blocks')

    def __init__(self, kind, a=None, b=None, c=None, d=None, e=None,
                 f=None, line=None, blocks=None):
        self.kind = kind
        self.a = a
        self.b = b
        self.c = c
        self.d = d
        self.e = e
        self.f = f
        self.line = line
        self.blocks = blocks or set()


# ---------------------------------------------------------------------------
# Dominatori
# ---------------------------------------------------------------------------

def dominators(blocks, entry, preds_of):
    """Dominatori immediati — algoritmo Cooper-Harvey-Kennedy con
    numerazione in Reverse Post-Order."""
    # RPO via DFS iterativo
    visited = {entry}
    post = []
    stack = [(entry, 0)]
    children = {}
    while stack:
        node, i = stack.pop()
        if i == 0:
            children[node] = 0
        succs = blocks.get(node, [])
        if i < len(succs):
            stack.append((node, i + 1))
            s = succs[i]
            if s not in visited and s in blocks:
                visited.add(s)
                stack.append((s, 0))
        else:
            post.append(node)
    rpo = list(reversed(post))
    rpo_num = {b: i for i, b in enumerate(rpo)}

    def intersect(a, b):
        f1, f2 = a, b
        while f1 != f2:
            while rpo_num.get(f1, 1 << 30) > rpo_num.get(f2, 1 << 30):
                f1 = idom[f1]
            while rpo_num.get(f2, 1 << 30) > rpo_num.get(f1, 1 << 30):
                f2 = idom[f2]
        return f1

    idom = {entry: entry}
    changed = True
    guard = 0
    while changed and guard < 1000:
        guard += 1
        changed = False
        for b in rpo:
            if b == entry:
                continue
            ps = [p for p in preds_of(b)
                  if p in idom and p in rpo_num]
            if not ps:
                continue
            new = ps[0]
            for p in ps[1:]:
                new = intersect(new, p)
            if idom.get(b) != new:
                idom[b] = new
                changed = True
    return idom, rpo


def postdominators(nsucc, succs_of, exits):
    """Postdominatori immediati = dominatori sul grafo INVERSO con uscita
    virtuale (riusa l'algoritmo CHK esatto)."""
    from collections import defaultdict
    rsucc = defaultdict(list)
    for n in list(nsucc.keys()):
        rsucc.setdefault(n, [])
        for s in nsucc[n]:
            rsucc[s].append(n)
    V = '__EXIT__'
    rsucc[V] = list(exits)
    rpred = defaultdict(list)
    for n, ss in rsucc.items():
        for s in ss:
            rpred[s].append(n)
    idom, _order = dominators(dict(rsucc), V, lambda n: rpred[n])
    return idom


# ---------------------------------------------------------------------------
# Structurer
# ---------------------------------------------------------------------------

CmpInvert = {'eq': 'ne', 'ne': 'eq', 'lt': 'ge', 'ge': 'lt',
             'le': 'gt', 'gt': 'le'}


def sv_key(sym, _seen=None, _depth=0, _memo=None):
    """Chiave strutturale ricorsiva di un NdxSV (per value numbering).

    I grafi SV possono condividere nodi o contenere cicli (phi, loop
    carried dep, nodi riusati dal lifter). Senza marcatura dei nodi in
    corso la ricorsione non termina; senza memoizzazione un DAG con
    sottoespressioni condivise (diamond sharing) viene ricalcolato un
    numero esponenziale di volte e la tupla risultato cresce altrettanto
    (CPU infinita + decine di GB). La visita tronca i cicli con un
    marker, memoizza ogni nodo una sola volta e limita la profondità
    dei DAG patologici."""
    if not isinstance(sym, NdxSV):
        return repr(sym)
    if _seen is None:
        _seen = set()
        _memo = {}
    marker = id(sym)
    if marker in _seen:
        return ('<cycle>',)
    hit = _memo.get(marker)
    if hit is not None:
        return hit
    if _depth > 256:
        return ('<deep>',)
    _seen.add(marker)
    try:
        parts = [sym.op]
        if sym.op in ('tuple_build', 'list_build', 'dict_build',
                      'list_empty', 'dict_empty', 'set_empty',
                      'call', 'kwcall', 'mcall', 'nativecall', 'apicall', 'next') and \
                sym.n is not None:
            parts.append(('allocation', sym.n))
        for attr in ('a', 'b', 'c'):
            v = getattr(sym, attr, None)
            if isinstance(v, NdxSV):
                parts.append(sv_key(v, _seen, _depth + 1, _memo))
            elif isinstance(v, list):
                parts.append(tuple(
                    sv_key(x, _seen, _depth + 1, _memo)
                    if isinstance(x, NdxSV) else repr(x)
                    for x in v))
            else:
                parts.append(repr(v))
        key = tuple(parts)
    finally:
        _seen.discard(marker)
    _memo[marker] = key
    return key


_NDX_REG64_MAP = {'eax': 'rax', 'ebx': 'rbx', 'ecx': 'rcx', 'edx': 'rdx',
                  'esi': 'rsi', 'edi': 'rdi', 'ebp': 'rbp', 'esp': 'rsp',
                  'r8d': 'r8', 'r9d': 'r9', 'r10d': 'r10', 'r11d': 'r11',
                  'r12d': 'r12', 'r13d': 'r13', 'r14d': 'r14', 'r15d': 'r15',
                  'ax': 'rax', 'bx': 'rbx', 'cx': 'rcx', 'dx': 'rdx',
                  'al': 'rax', 'bl': 'rbx', 'cl': 'rcx', 'dl': 'rdx',
                  'sil': 'rsi', 'dil': 'rdi', 'bpl': 'rbp', 'spl': 'rsp'}


class Structurer:
    def __init__(self, lifter: BodyLifter2, name_ctx=None):
        self.L = lifter
        self.img = lifter.img
        self.blocks = lifter.blocks
        self.entry = min(self.blocks) if self.blocks else None
        self.name_ctx = name_ctx or {}
        # flusso normale
        self.nsucc = {}
        self.npred = {}
        self._build_normal_flow()
        if self.entry is not None:
            self.idom, self.order = dominators(
                self.nsucc, self.entry, lambda n: self.npred[n])
            self.loops = self._find_loops()
            # gen_mode: la dominanza dell'header è rotta dai re-entry
            # delle exception (l'handler rientra dopo lo yield point).
            # Fallback sui RETREATING EDGE del grafo corrente: un edge
            # all'indietro verso un blocco con ops Python è il back-edge
            # del loop. Il corpo = backward(latch, stop=header) ∩
            # forward(header) — l'intersezione isola la regione del loop
            # dai re-entry esterni. Filtro di semanticità come sopra.
            if not self.loops and getattr(lifter, 'gen_mode', False):
                pre = {}
                for u, ss in self.nsucc.items():
                    for h in ss:
                        if h <= u and h in self.blocks:
                            body = {h, u}
                            work = [u]
                            while work:
                                cur = work.pop()
                                for p2 in self.npred.get(cur, ()):
                                    if p2 in self.blocks and p2 not in body:
                                        body.add(p2)
                                        work.append(p2)
                            fwd = {h}
                            fw = [h]
                            while fw:
                                cur = fw.pop()
                                for s2 in self.nsucc.get(cur, ()):
                                    if s2 in self.blocks and s2 not in fwd:
                                        fwd.add(s2)
                                        fw.append(s2)
                            body &= fwd
                            if not body:
                                body = {h, u}
                            if h in pre:
                                pre[h]['body'] |= body
                                pre[h]['latches'].append(u)
                            else:
                                pre[h] = {'header': h, 'body': body,
                                          'latches': [u]}
                self.loops = {
                    h: lp for h, lp in pre.items()
                    if h in self.blocks and
                    all(latch in lp['body'] for latch in lp['latches']) and
                    any(self.blocks[n].ops or self.blocks[n].conds
                        for n in lp['body'] if n in self.blocks)
                }
            # postdominatori per i join dei branch
            self._exits = [st for st, succs in self.nsucc.items()
                           if not succs]
            self.pdom = postdominators(
                self.nsucc, lambda n: self.nsucc[n], self._exits)
        else:
            self.idom, self.order, self.loops = {}, [], {}
            self.pdom = {}
        # nomi variabili
        self.var_names = {}
        self.tmp_n = 0
        self._materialize_loop_carried_values()
        self._assign_var_names()

    def _materialize_loop_carried_values(self):
        """Make register recurrences explicit before assigning local names.

        A single-entry natural loop with one back edge has two sources for
        its header phi: the initial value and the previous iteration.  Emit
        those assignments only when the back-edge expression uses that same
        location and its store dominates the latch.  No operator, source
        name, constant, address or number of iterations is guessed.
        """
        self.loop_carried_locations = set()
        states = getattr(self.L, '_final_out', {})

        def dominates(ancestor, node):
            seen = set()
            while node is not None and node not in seen:
                if node == ancestor:
                    return True
                seen.add(node)
                node = self.idom.get(node)
            return False

        for header, loop in self.loops.items():
            latches = loop['latches']
            outside = [p for p in self.npred.get(header, ())
                       if p not in loop['body']]
            if len(latches) != 1 or len(outside) != 1:
                continue
            pre, latch = outside[0], latches[0]
            initial_regs = states.get(pre, {}).get('regs', {})
            final_regs = states.get(latch, {}).get('regs', {})
            for register, update in final_regs.items():
                initial = initial_regs.get(register)
                location = ('reg', register)
                if not isinstance(initial, NdxSV) or initial.op not in ('const', 'par'):
                    continue
                if not isinstance(update, NdxSV) or update.op != 'binop':
                    continue
                if not any(isinstance(child, NdxSV) and child.op == 'loc'
                           and child.a == location for child in (update.b, update.c)):
                    continue
                stores = [(start, op) for start in loop['body']
                          for op in self.blocks[start].ops
                          if op.kind == 'store' and isinstance(op.b, NdxSV)
                          and _sv_eq(op.b, update)]
                sources = {start for start, _op in stores}
                if len(sources) != 1 or not dominates(next(iter(sources)), latch):
                    continue
                if location in self.loop_carried_locations:
                    continue
                self.loop_carried_locations.add(location)
                block = self.blocks[pre]
                if not any(op.kind == 'store' and op.a == location
                           and _sv_eq(op.b, initial) for op in block.ops):
                    block.ops.insert(0, NdxOp('store', a=location, b=initial,
                                             va=block.start))
                # Spilling the update and moving it back into the recurrence
                # register is one source assignment, regardless of its ABI slot.
                first = stores[0][1]
                first.a = location
                for start, duplicate in stores[1:]:
                    self.blocks[start].ops.remove(duplicate)

        # Conditional updates need not dominate the latch: an unchanged
        # incoming value is a valid recurrence arm. Prove the actual register
        # write and its computed Python value, then preserve the assignment
        # in its original branch. Start with the enclosing loop so a shared
        # recurrence is initialized once before all nested iterations.
        for header, loop in sorted(self.loops.items(),
                                   key=lambda item: -len(item[1]['body'])):
            outside = [p for p in self.npred.get(header, ())
                       if p not in loop['body']]
            if len(outside) != 1:
                continue
            pre = outside[0]
            initial_regs = states.get(pre, {}).get('regs', {})
            calculations = [(start, op.a) for start in loop['body']
                            for op in self.blocks[start].ops
                            if op.kind == 'calc' and isinstance(op.a, NdxSV)
                            and op.a.op == 'binop']
            for start, update in calculations:
                for child in (update.b, update.c):
                    if not isinstance(child, NdxSV) or child.op != 'loc' or \
                            not isinstance(child.a, tuple) or child.a[0] != 'reg':
                        continue
                    location = child.a
                    if location in self.loop_carried_locations:
                        continue
                    register = location[1]
                    initial = initial_regs.get(register)
                    if not isinstance(initial, NdxSV) or initial.op not in ('const', 'par'):
                        continue
                    writes = []
                    for target in loop['body']:
                        if not dominates(start, target):
                            continue
                        stored = states.get(target, {}).get('regs', {}).get(register)
                        if not _sv_eq(stored, update):
                            continue
                        for ins in self.blocks[target].insns:
                            operands = split_ops(ins.op_str)
                            if ins.mnemonic == 'mov' and len(operands) == 2 and \
                                    subreg64(operands[0]) == register:
                                writes.append((target, ins.address))
                    if len(writes) != 1:
                        continue
                    target, address = writes[0]
                    self.loop_carried_locations.add(location)
                    self.blocks[pre].ops.insert(0, NdxOp(
                        'store', a=location, b=initial, va=self.blocks[pre].start))
                    if not any(op.kind == 'store' and op.a == location and
                               _sv_eq(op.b, update) for op in self.blocks[target].ops):
                        self.blocks[target].ops.append(NdxOp(
                            'store', a=location, b=update, va=address))

    # ------------------------------------------------------------ normal flow
    def _build_normal_flow(self):
        # An async/generator *resumer* only needs the relaxed error-edge model
        # when it actually has native re-entry states.  Async functions with
        # no suspension still use a context object, but their exception and
        # StopIteration regions are ordinary cold paths and must not pollute
        # the source CFG.
        gen_reentry = bool(
            getattr(getattr(self, 'L', None), 'gen_mode', False) and
            getattr(getattr(self, 'L', None), 'gen_resume', None))
        for st, b in self.blocks.items():
            succs = []
            # i blocchi della catena eccezioni non contribuiscono al flusso
            # normale: il loro reingresso (goto try_end) è un re-entry di
            # regione, non sequenza. I body delle clausole except sono
            # raggiunti esplicitamente dallo structurer degli handler.
            if b.kind == 'error':
                # gen_mode: nel resumer gran parte dei blocchi 'error' sono
                # null-check/noise trasparenti, non handler. Solo i blocchi
                # con semantica di exception-handling restano dead-end.
                if not (gen_reentry and
                        'handler_sem' not in b.flags):
                    self.nsucc[st] = []
                    self.npred[st] = []
                    continue
            # gen_mode: nel resumer gli edge 'error' dei null-check (celle
            # closure, iteratori) non sono barriere affidabili — la polarità
            # del salto decide se il target è l'errore o la continuazione;
            # e i blocchi 'stopiter' sono spesso closure-read interni al
            # loop. Entrambi restano percorribili SOLO in gen_mode.
            gen_mode = gen_reentry
            # Exhaustion continues after a Python for-loop. Keeping these
            # edges in the analysis graph is essential for enclosing loops:
            # the inner loop's exhaustion is the outer loop's back path.
            bad_kinds = ('error',)
            if b.kind == 'stopiter':
                # uscita del for: tutti i successori strutturali non-error
                # sono normali (loop_end / handler)
                succs = [s for s in b.succs
                         if s in self.blocks and
                         self.blocks[s].kind not in bad_kinds]
                self.nsucc[st] = list(dict.fromkeys(succs))
                self.npred[st] = []
                continue
            edge_tgts = set()
            for t, et in b.edges:
                edge_tgts.add(t)      # TUTTI i target (anche error)
                if et == 'guard_fail':
                    continue
                if et == 'error':
                    continue
                if t in self.blocks and self.blocks[t].kind not in bad_kinds:
                    succs.append(t)
            # fallthrough: successori strutturali non coperti da edges
            # (es. il ramo cadente di un jcc)
            for s in b.succs:
                if s in self.blocks and s not in edge_tgts and \
                        self.blocks[s].kind not in bad_kinds:
                    succs.append(s)
                    edge_tgts.add(s)
            # dedup
            self.nsucc[st] = list(dict.fromkeys(succs))
            self.npred[st] = []
        # Ripara i blocchi 'isola': nessuna edge non-errore registrata, ma
        # il fallthrough adiacente (block.end) e' un blocco noto e il
        # blocco non termina con ret/jmp.  Senza questa edge l'analisi dei
        # cicli perde la continuita' corpo<->latch sui test di condizione
        # ridotti a test+flag.
        starts = sorted(self.blocks)
        import bisect as _bisect
        for st, b in self.blocks.items():
            if self.nsucc.get(st):
                continue
            if b.kind == 'error' or any(o.kind == 'ret' for o in b.ops):
                continue
            if any(et == 'jmp' for _t, et in b.edges):
                continue
            end = getattr(b, 'end', None)
            nxt = None
            if end is not None:
                i = _bisect.bisect_right(starts, end - 1)
                if i < len(starts) and starts[i] == end:
                    nxt = end
            if nxt is None or nxt not in self.blocks:
                continue
            if self.blocks[nxt].kind in ('error', 'stopiter'):
                continue
            self.nsucc[st] = [nxt]
        for st, succs in self.nsucc.items():
            for s in succs:
                if st not in self.npred[s]:
                    self.npred[s].append(st)

    # ------------------------------------------------------------ loops
    def _find_loops(self):
        """Back edges u→h (h domina u) → loop naturali."""
        back = []
        for u, succs in self.nsucc.items():
            for h in succs:
                if self._dominates(h, u):
                    back.append((u, h))
        loops = {}
        for u, h in back:
            # corpo: reachability all'indietro da u, fermandosi a h
            body = {h, u}
            work = [u]
            while work:
                cur = work.pop()
                for p in self.npred[cur]:
                    if p not in body:
                        body.add(p)
                        work.append(p)
            # il corpo non deve includere blocchi che dominano h
            # (rimuovi i nodi fuori dal ciclo: quelli da cui h è raggiungibile
            # senza passare da u — approssimazione standard)
            if h in loops:
                loops[h]['body'] |= body
            else:
                loops[h] = {'header': h, 'body': body, 'latches': [u]}
        # Machine-level refcount/deallocation diamonds can contain tiny back
        # edges, but they are not Python loops.  A language-level loop must
        # carry at least one recovered Python operation or condition in its
        # natural-loop region.  Removing operation-free cycles prevents them
        # from truncating the surrounding real loop during structuring.
        return {
            header: loop for header, loop in loops.items()
            if any(self.blocks[node].ops or self.blocks[node].conds
                   for node in loop['body'] if node in self.blocks)
        }

    def _dominates(self, a, b):
        """a domina b?"""
        cur = b
        guard = 0
        while cur is not None and guard < 10000:
            guard += 1
            if cur == a:
                return True
            if cur == self.entry:
                return False
            cur = self.idom.get(cur)
        return False

    def loop_header_of(self, st):
        # Natural loops are nested sets.  A block in an inner loop therefore
        # also belongs to every enclosing loop; dictionary insertion order is
        # not a semantic nesting rule and commonly lists the outer header
        # first.  The smallest containing body is the innermost loop and is
        # the correct target for source ``break``/``continue`` recovery.
        containing = [loop for loop in self.loops.values()
                      if st in loop['body']]
        if not containing:
            return None
        return min(containing, key=lambda loop: len(loop['body']))

    # ------------------------------------------------------------ var naming
    def _assign_var_names(self):
        """Naming lazy: i varnames (post-argomenti) vengono assegnati al
        PRIMO USO durante la strutturazione (≈ ordine sorgente). Il naming
        è per-VALORE (sym), non per registro: GCC riusa i registri per
        variabili diverse in regioni diverse."""
        varnames = self.L.varnames
        freevars = set(getattr(self.L, 'freevars', ()) or ())
        semantic_names = set()
        has_zero_arg_super = False

        def inspect(value, seen=None):
            nonlocal has_zero_arg_super
            if not isinstance(value, NdxSV):
                return
            if seen is None:
                seen = set()
            marker = id(value)
            if marker in seen:
                return
            seen.add(marker)
            if value.op == 'var' and isinstance(value.a, str):
                semantic_names.add(value.a)
            elif value.op == 'super' and not (value.a or value.b or value.c):
                has_zero_arg_super = True
            for child in (value.a, value.b, value.c):
                if isinstance(child, NdxSV):
                    inspect(child, seen)
                elif isinstance(child, (list, tuple)):
                    for item in child:
                        inspect(item, seen)

        # V100: seen UNICO per tutta la funzione — la raccolta nomi è
        # monotona (solo set-add idempotenti): ricreare il seen per op
        # ripercorre i DAG condivisi di ogni operazione (quadratico sulle
        # funzioni giganti).
        _seen_all = set()
        for block in self.blocks.values():
            for operation in block.ops:
                inspect(operation.a, _seen_all)
                inspect(operation.b, _seen_all)
                inspect(operation.c, _seen_all)
        semantic_names.update(
            name for name in getattr(
                self.L, 'gen_closure_names', {}).values()
            if isinstance(name, str))
        if has_zero_arg_super:
            # Nuitka's synthetic code-object varname vector can include the
            # implicit class closure beside true locals.  A proven SUPER0 is
            # the language-level evidence that ``__class__`` is that closure,
            # never an SSA destination to invent in source.
            semantic_names.add('__class__')
        self.semantic_names = set(semantic_names)
        # Every entry of co_varnames is BY DEFINITION a local slot of this
        # code object, so it stays available for the lazy naming pool even
        # when an embedded ``var`` use made it "semantic": reserving it
        # would shift every later local by one.
        self._free_names = [v for v in varnames[self.L.argcount:]
                            if v not in freevars]
        self._named_locs = set()
        self.sym_names = {}
        self.sym_keys = {}
        self.loc_cur_sym = {}
        self.authoritative_loc_names = dict(
            getattr(self.L, 'authoritative_loc_names', {}) or {})
        if semantic_names:
            self.authoritative_loc_names = {
                location: name
                for location, name in self.authoritative_loc_names.items()
                if name not in semantic_names}
        self.authoritative_sym_names = dict(getattr(self.L, 'module_iterator_names', {}))
        self.authoritative_sym_locations = {}
        self.semantic_store_locations = defaultdict(set)
        for block in self.blocks.values():
            for operation in block.ops:
                if operation.kind == 'store' and operation.b is not None:
                    self.semantic_store_locations[sv_key(operation.b)].add(
                        operation.a)
        for key, locations in getattr(
                self.L, 'symbol_locations', {}).items():
            authoritative_locations = {
                location for location in locations
                if location in self.authoritative_loc_names}
            if authoritative_locations:
                self.authoritative_sym_locations[key] = \
                    authoritative_locations
            names = {self.authoritative_loc_names[location]
                     for location in authoritative_locations}
            if len(names) == 1:
                self.authoritative_sym_names[key] = next(iter(names))

    def _take_varname(self):
        if self._free_names:
            return self._free_names.pop(0)
        self.tmp_n += 1
        return f'_v{self.tmp_n}' 

    def name_of_loc(self, loc):
        if loc in self.var_names:
            return self.var_names[loc]
        nm = self.authoritative_loc_names.get(loc) or self._take_varname()
        if nm in self._free_names:
            self._free_names.remove(nm)
        self.var_names[loc] = nm
        return nm

    def name_of_sym(self, sym):
        """NdxSym → nome/expr-string gestita dal renderer."""
        return None

    # ------------------------------------------------------------ entry
    def _discover_starred_unpack(self):
        """Recover iterator/remaining-list/pop lowering with its length guard.

        The native minimum-length diagnostic and the actual extraction counts
        must agree. Every skipped semantic operation must belong to that
        extraction or its ValueError construction. No application names or
        constants determine the reconstructed assignment.
        """
        self._unpack_regions = {}
        self._unpack_transport_keys = set()
        # Length-guard helpers may still have an unknown native-bool ABI.
        # Analyze the raw CFG here; the extraction and exception proof below
        # establishes which branches belong to the unpack protocol.
        graph = {start: [n for n in block.succs if n in self.blocks]
                 for start, block in self.blocks.items()}
        parents = {start: [] for start in graph}
        for start, successors in graph.items():
            for successor in successors:
                parents[successor].append(start)
        idom, order = dominators(graph, self.entry, lambda n: parents[n])
        def dominates(first, last):
            seen = set()
            while last is not None and last not in seen:
                if last == first:
                    return True
                seen.add(last); last = idom.get(last)
            return False
        operations = [(start, op) for start in order for op in self.blocks[start].ops]
        rank = {start: i for i, start in enumerate(order)}
        def nodes(value):
            pending, seen = [value], set()
            while pending:
                v = pending.pop()
                if isinstance(v, NdxSV) and id(v) not in seen:
                    seen.add(id(v)); yield v
                    pending.extend((v.a, v.b, v.c))
                elif isinstance(v, (list, tuple)):
                    pending.extend(v)
        def pop_of(value, remaining):
            return isinstance(value, NdxSV) and value.op == 'call' and \
                isinstance(value.a, NdxSV) and value.a.op == 'getattr' and \
                isinstance(value.a.a, NdxSV) and value.a.a.op == 'global' and \
                value.a.a.a == 'list' and value.a.b == 'pop' and \
                isinstance(value.b, list) and len(value.b) == 1 and _sv_eq(value.b[0], remaining)
        def contains(value, target):
            return any(_sv_eq(v, target) for v in nodes(value))
        def diagnostic(value):
            for v in nodes(value):
                if v.op == 'const' and isinstance(v.a, str):
                    match = re.fullmatch(r'not enough values to unpack \(expected at least (\d+), got %d\)', v.a)
                    if match:
                        return int(match.group(1))
            return None
        for list_block, operation in operations:
            remaining = operation.a
            if operation.kind != 'calc' or not isinstance(remaining, NdxSV) or \
                    remaining.op != 'call' or remaining.a != 'list' or \
                    not isinstance(remaining.b, list) or len(remaining.b) != 1:
                continue
            iterator = remaining.b[0]
            if not isinstance(iterator, NdxSV) or iterator.op != 'iter' or iterator.a is None:
                continue
            prefix = [(start, op) for start, op in operations if op.kind == 'calc' and
                      isinstance(op.a, NdxSV) and op.a.op == 'next' and
                      _sv_eq(op.a.a, iterator) and dominates(start, list_block)]
            # Separate repeated unpack assignments of the same input.
            prior_lists = [start for start, op in operations if op.kind == 'calc' and
                           op.a is not remaining and isinstance(op.a, NdxSV) and
                           op.a.op == 'call' and op.a.a == 'list' and
                           dominates(start, list_block) and rank[start] < rank[list_block]]
            if prior_lists:
                previous = max(prior_lists, key=rank.get)
                prefix = [(start, op) for start, op in prefix if rank[start] > rank[previous]]
            prefix.sort(key=lambda pair: (rank[pair[0]], pair[1].va))
            suffix = [(start, op) for start, op in operations if op.kind == 'calc' and pop_of(op.a, remaining)]
            suffix.sort(key=lambda pair: (rank[pair[0]], pair[1].va))
            values = [op.a for _, op in prefix] + [remaining] + [op.a for _, op in reversed(suffix)]
            if len({sv_key(value) for value in values}) != len(values):
                continue
            expected = len(prefix) + len(suffix)
            guards = [(start, op) for start, op in operations if diagnostic(op.b if op.kind == 'store' else op.a) == expected and
                      dominates(list_block, start)]
            if not guards:
                continue
            last = suffix[-1][0] if suffix else list_block
            def machinery(value):
                if not isinstance(value, NdxSV):
                    return True
                if value.op in ('frame', 'excstate', 'imm', 'type_of', 'global', 'getattr'):
                    return True
                if any(_sv_eq(value, v) for v in values) or _sv_eq(value, iterator):
                    return True
                if diagnostic(value) is not None:
                    return True
                if value.op in ('len', 'cmp', 'nativecall') and contains(value, remaining):
                    return True
                # L'aritmetica della diagnostica (es. len(remaining) + 1
                # riconosciuto come BINARY_OPERATION_ADD_OBJECT_LONG_CLONG)
                # e la formattazione del messaggio sono machinery del
                # protocollo d'unpacking, non lavoro sorgente.
                if value.op in ('binop', 'call', 'format') and (
                        contains(value, remaining) or
                        any(diagnostic(v) is not None for v in nodes(value))):
                    return True
                if value.op == 'nativecall' and all(x is None or x.op in (
                        'imm', 'tstate', 'stackaddr', 'type_of', 'global') for x in (value.b or [])):
                    return True
                return False
            candidates = [(start, op) for start, op in operations if rank[start] >= rank[last] and
                          (dominates(list_block, start) or op.kind == 'ret') and
                          op.kind in ('calc', 'ret') and (op.kind == 'ret' or not machinery(op.a)) and
                          any(contains(op.a, value) for value in values)]
            if not candidates:
                continue
            after, _ = min(candidates, key=lambda pair: (rank[pair[0]], pair[1].va))
            # Prove that no unrelated source work is bypassed.
            begin = prefix[0][0] if prefix else list_block
            if any(op.kind in ('calc', 'append', 'store_sub', 'store_attr', 'yield') and
                   not machinery(op.a) for start, op in operations
                   if rank[begin] <= rank[start] < rank[after] and dominates(begin, start)):
                continue
            self._unpack_regions[begin] = (iterator.a, values, len(prefix), after)
            self._unpack_transport_keys.update(sv_key(value) for value in values + [iterator])

    def _starred_unpack_statement(self, region):
        source, values, starred, after = region
        names = [self._take_varname() for _ in values]
        for value, name in zip(values, names):
            self.sym_names[id(value)] = name
            self.sym_keys[sv_key(value)] = name
        return NdxSt('unpack_ex', a=names, b=source, c=starred), after

    def structure(self):
        if self.entry is None:
            return []
        # handler chains (try/except): le regioni handler non sono
        # raggiungibili dal flusso normale (blocchi error) — nessuno stop
        self.handlers = self._find_handlers()
        self._discover_starred_unpack()
        stmts = self._seq(self.entry, {None})
        # inserisci i try/except attorno alle regioni
        stmts = self._wrap_try(stmts)
        stmts = self._wrap_finally(stmts)
        # catene di incrementi multi-iterazione sui valori loop-carried
        # provati: il return/uso post-loop legge la variabile, non la catena
        if getattr(self, 'loop_carried_locations', None):
            self._collapse_loop_carried_chains(stmts, depth=0)
        # inline dei temporanei: disattivato (richiede conteggio per-sym
        # esatto; i statement con _vN sono semanticamente corretti)
        return stmts

    def _loop_carried_chain_base(self, sym, depth=0):
        """Se sym e' una catena di binop (profondita' >= 2) radicata in una
        location loop-carried provata, restituisce il simbolo loc della
        location; None altrimenti."""
        if depth > 8 or not isinstance(sym, NdxSV) or sym.op != 'binop':
            return None
        base = None
        for child in (sym.b, sym.c):
            if isinstance(child, NdxSV) and child.op == 'loc' and \
                    isinstance(child.a, tuple) and \
                    tuple(child.a) in self.loop_carried_locations:
                base = child          # radice loop-carried a profondita' 1
        for child in (sym.b, sym.c):
            inner = self._loop_carried_chain_base(child, depth + 1)
            if inner is not None:
                # radice raggiunta a profondita' >= 2: catena multi-iterazione
                return inner
        return base if base is not None else None

    def _collapse_loop_carried_chains(self, stmts, depth=0):
        """Sostituisce le catene di incrementi post-loop con la variabile
        loop-carried (il valore finale del registro, non la catena)."""
        if depth > 12:
            return
        for s in stmts:
            if s is None or not hasattr(s, 'kind'):
                continue
            if s.kind == 'return' and isinstance(s.a, NdxSV):
                base = self._loop_carried_chain_base(s.a)
                if base is not None:
                    s.a = base
            for f in ('b', 'c', 'd'):
                v = getattr(s, f, None)
                if isinstance(v, list) and v and \
                        all(hasattr(x, 'kind') for x in v):
                    self._collapse_loop_carried_chains(v, depth + 1)

    def _fallback_linear_stmts(self):
        """Emissione lineare di sicurezza: tutti gli statement Python dei
        blocchi normali in ordine di blocco, senza strutturazione."""
        out = []
        seen_ops = set()
        for st in sorted(self.blocks):
            b = self.blocks[st]
            if b.kind in ('error', 'stopiter'):
                continue
            for s in self._block_stmts(b):
                key = (s.kind, id(s.a), id(s.b), id(s.c))
                if key in seen_ops:
                    continue
                seen_ops.add(key)
                s.blocks = {st}
                out.append(s)
        return out

    # ------------------------------------------------------------- inline temps
    def _inline_temps(self, stmts, round_n=0):
        """`_vN = expr` con _vN usato esattamente una volta → sostituisci."""
        if round_n > 4:
            return stmts
        # conta usi di ogni nome temporaneo
        from collections import defaultdict
        uses = defaultdict(int)

        def count_syms(sym, acc):
            if sym is None:
                return
            for attr in ('a', 'b', 'c'):
                v = getattr(sym, attr, None)
                if isinstance(v, NdxSV):
                    if v.op == 'loc':
                        acc.append(v)
                    count_syms(v, acc)
                elif isinstance(v, list):
                    for x in v:
                        if isinstance(x, NdxSV):
                            if x.op == 'loc':
                                acc.append(x)
                            count_syms(x, acc)
            if sym.op == 'loc':
                pass

        temp_defs = {}
        for i, st in enumerate(stmts):
            if st.kind == 'assign' and isinstance(st.a, str) and \
                    st.a.startswith('_v'):
                temp_defs.setdefault(st.a, []).append(i)
        # nomi usati (approssimazione: conta occorrenze nei rendering)
        def stmt_refs(st):
            refs = []
            for f in ('a', 'b', 'c', 'd', 'e'):
                v = getattr(st, f, None)
                if isinstance(v, NdxSV):
                    count_syms(v, refs)
                elif isinstance(v, str) and v.startswith('_v'):
                    refs.append(v)
                elif isinstance(v, list):
                    for x in v:
                        if isinstance(x, NdxSV):
                            count_syms(x, refs)
                        elif isinstance(x, NdxSt):
                            refs.extend(stmt_refs(x))
                        elif isinstance(x, tuple):
                            for y in x:
                                if isinstance(y, list):
                                    for z in y:
                                        if isinstance(z, NdxSt):
                                            refs.extend(stmt_refs(z))
            return refs

        all_refs = []
        for st in stmts:
            all_refs.extend(stmt_refs(st))
        from collections import Counter
        use_count = Counter(r for r in all_refs if isinstance(r, str))
        # candidati: definiti una volta, usati una volta, NON self-reference
        subs = {}
        for name, idxs in temp_defs.items():
            if len(idxs) == 1 and use_count.get(name, 0) == 1:
                subs[name] = idxs[0]
        if not subs:
            return stmts
        # sostituisci
        out = []
        removed = set()
        for i, st in enumerate(stmts):
            if i in subs.values():
                removed.add(i)
                continue
            out.append(st)
        # nel rendering le loc-ref di quel nome puntano alla loc — la
        # sostituzione avviene a livello di nome: il renderer userà il nome
        # della variabile; per semplicità sostituiamo il NOME della var
        # con l'espressione in una seconda fase del renderer.
        # Qui: rinominiamo la loc → il valore resta inline se la loc non è
        # più nominata. Approccio pratico: elimina l'assegnamento e registra
        # la sostituzione simbolo→espressione per il renderer.
        self.temp_inline = getattr(self, 'temp_inline', {})
        for name, idx in subs.items():
            self.temp_inline[name] = stmts[idx].b
        return out

    # ------------------------------------------------------------ sequences
    def _seq(self, cur, stop_set, depth=0, enter_stop=False):
        stmts = []
        visited = set()
        guard = 0
        while True:
            while cur is not None and (enter_stop or cur not in stop_set) \
                        and cur not in visited:
                # enter_stop: il blocco iniziale (header del while True) viene
                # camminato anche se e' stop/loop-header, senza ristrutturarlo
                first = enter_stop
                enter_stop = False
                visited.add(cur)
                guard += 1
                b = self.blocks[cur]
                if cur in getattr(self, '_unpack_regions', {}):
                    statement, cur = self._starred_unpack_statement(self._unpack_regions[cur])
                    stmts.append(statement)
                    continue
                # A branch whose two arms were proven to construct one
                # conditional-phi value is expression lowering, not a source
                # ``if`` statement.  The lifter materialised that value at the
                # exact join; jump there and let ordinary statement sequencing
                # emit its single assignment.
                ifexp_join = getattr(self.L, '_ifexp_controller_joins', {}).get(
                    cur)
                if ifexp_join in self.blocks and ifexp_join not in stop_set:
                    cur = ifexp_join
                    continue
                # --- loop header?
                if cur in self.loops and not first:
                    lp_result = self._structure_loop(cur, stop_set, depth)
                    if lp_result is None:
                        # loop non strutturabile: prosegui in sequenza
                        # invece di far fallire l'intera funzione
                        stmts.extend(self._block_stmts(self.blocks[cur]))
                        cur = self._next_normal(cur)
                        continue
                    lp_stmts, after = lp_result
                    stmts.extend(lp_stmts)
                    cur = after
                    continue
                # --- guard di ``for``: blocco con next(iter(...)) e un edge
                # stopiter — è l'ingresso (o il latch) di un ciclo for, anche
                # quando GCC lo ha fuso/ruotato dentro un ciclo esterno e il
                # natural-loop non si chiude: struttura ``for`` e prosegui
                # dall'uscita StopIteration
                if b.conds and any(et == 'stopiter' for _t, et in b.edges):
                    fr = self._structure_for_guard(cur, stop_set, depth,
                                                   visited)
                    if fr is not None:
                        st, after = fr
                        stmts.append(st)
                        cur = after
                        continue
                # --- branch condizionale?
                br = self._cond_info(b)
                if br is not None:
                    # A source assignment can share the machine block with the
                    # comparison that immediately consumes it (notably a
                    # conditional-expression phi materialised at its join).
                    # _structure_if owns only the branch arms, so preserve linear
                    # statements from the controller block before emitting it.
                    stmts.extend(self._block_stmts(b))
                    st, after = self._structure_if(cur, br, stop_set, depth)
                    if st is not None:
                        stmts.append(st)
                    cur = after
                    continue
                # --- return?
                ret_op = None
                for o in b.ops:
                    if o.kind == 'ret':
                        ret_op = o
                if ret_op is not None and self._is_terminal(b):
                    stmts.extend(self._block_stmts(b))
                    cur = None
                    break
                # --- raise? il flusso NORMAL termina: tutto ciò che segue nel
                # nativo è la propagazione dell'eccezione (decref chain,
                # traceback attach, unwind).  Senza questo stop il walk entra
                # nella catena d'errore e muore al primo dead-end, perdendo
                # tutto il codice successivo alla raise (nei diamanti del
                # protocollo class-creation tronca l'intero module-init).
                if any(o.kind == 'raise' for o in b.ops):
                    stmts.extend(self._block_stmts(b))
                    cur = None
                    break
                # --- blocco stop-iteration: passthrough (logica uscita for).
                # Un blocco stopiter che PRODUCE statement Python (bind di
                # module-init raggiunti via edge di check tipizzati stopiter)
                # non e' passthrough: i suoi ops sono codice sorgente.
                if b.kind == 'stopiter':
                    stmts.extend(self._block_stmts(b))
                    cur = self._next_normal(cur)
                    continue
                # --- reraise / blocco noise
                if b.kind == 'error':
                    cur = self._next_after_errorish(cur)
                    if cur is None:
                        break
                    continue
                # --- statement lineari del blocco
                stmts.extend(self._block_stmts(b))
                cur = self._next_normal(cur)
            # V101 MODULE RESUME: il walk del module-init puo' morire nei
            # percorsi di check del protocollo class-creation (edge
            # tipizzati error intrecciati alla continuazione normale).
            # I bind UPDATE_STRING_DICT sono gli anchor degli statement
            # module-level: riprendi dal primo anchor non visitato.
            if depth == 0 and (cur is None or cur in visited) and \
                    getattr(self.L, 'is_module_code', False):

                anchors = getattr(self.L, 'module_bind_anchor_blocks',
                                  ()) or ()
                candidates = [a for a in anchors
                              if a in self.blocks and a not in visited]
                if candidates:
                    cur = min(candidates)
                    continue
            break
        return stmts

    def _next_normal(self, cur):
        succs = self.nsucc.get(cur, [])
        # The analysis graph includes iterator exhaustion so enclosing loops
        # remain connected. Linear body sequencing follows the value arm;
        # the for structurer visits exhaustion separately after the body.
        block = self.blocks.get(cur)
        protocol_exits = {target for target, kind in block.edges
                          if kind == 'stopiter'} if block is not None else set()
        if protocol_exits:
            succs = [target for target in succs if target not in protocol_exits]
        if len(succs) == 1:
            return succs[0]
        if len(succs) == 0:
            # l'unico proseguimento passa per blocchi 'error'
            # rappresentati (slow-path di dispatch): risolvi la
            # continuazione reale oltre la regione rappresentata
            _cont = self._raw_continuation(cur)
            if _cont is not None:
                return _cont
            return None
        # più successori senza condizione Python: segui il goto (se unico)
        b = self.blocks[cur]
        gotos = [t for t, et in b.edges if et == 'goto']
        if len(gotos) == 1:
            return gotos[0]

        def continuation_score(start, limit=500):
            work = [(start, 0)]
            seen = set()
            best = 0
            best_distance = limit
            while work and len(seen) < limit:
                node, distance = work.pop(0)
                if node in seen or node not in self.blocks:
                    continue
                seen.add(node)
                block = self.blocks[node]
                if any(edge_type in ('cond_yes', 'cond_no')
                       for _target, edge_type in block.edges):
                    return (3, -distance)
                if any(operation.kind == 'yield'
                       for operation in block.ops):
                    # A suspension point is the strongest language-level
                    # continuation proof in a generator/coroutine resumer.
                    # Native error/refcount diamonds can contain stores and
                    # returns, but never a proven yield transport.
                    return (5, -distance)
                if any(operation.kind == 'calc' and
                       operation.a is not None and operation.a.op in (
                           'await', 'call', 'mcall', 'kwcall', 'import')
                       for operation in block.ops):
                    if best < 4:
                        best = 4
                        best_distance = distance
                    elif distance < best_distance:
                        best_distance = distance
                if any(operation.kind in (
                        'store', 'store_sub', 'store_attr', 'append',
                        'setadd', 'ret', 'raise') for operation in block.ops):
                    if best < 2:
                        best = 2
                        best_distance = distance
                    elif best < 4 and distance < best_distance:
                        best_distance = distance
                if node in self.loops:
                    if best < 1:
                        best = 1
                        best_distance = distance
                for successor in self.nsucc.get(node, ()):
                    work.append((successor, distance + 1))
            # il tie-break sulla DISTANZA del best è decisivo: due rami
            # che raggiungono lo stesso reward (il secondo convergendo
            # subito nel primo) devono premiare quello più VICINO,
            # altrimenti max() sceglie il primo in ordine e la camminata
            # può finire intrappolata in un ciclo vuoto di cleanup
            return (best, -best_distance)

        return max(succs, key=continuation_score)

    def _raw_continuation(self, cur):
        seen, frontier = {cur}, set()
        work = list(self.blocks[cur].succs)
        while work:
            target = work.pop()
            if target in seen or target not in self.blocks:
                continue
            seen.add(target)
            block = self.blocks[target]
            if block.kind != 'error':
                frontier.add(target)
                continue
            if block.ops or 'handler_sem' in block.flags:
                return None
            work.extend(block.succs)
        return next(iter(frontier)) if len(frontier) == 1 else None

    def _next_after_errorish(self, cur):
        return self._next_normal(cur)

    def _is_terminal(self, b):
        last = b.insns[-1] if b.insns else None
        if last is not None and last.mnemonic == 'ret':
            return True
        # jmp verso blocco ret
        succs = self.nsucc.get(b.start, [])
        if len(succs) == 1:
            nb = self.blocks.get(succs[0])
            if nb is not None and nb.insns and \
                    nb.insns[-1].mnemonic == 'ret':
                return True
        return False

    # ------------------------------------------------------------ cond info
    def _cond_info(self, b):
        """Se il blocco termina con un branch Python (cond_yes/cond_no),
        ritorna (sym, yes, no, yes_edge_type)."""
        yes = no = None
        sym = None
        for t, et in b.edges:
            if et == 'cond_yes':
                yes, no = t, None
            elif et == 'cond_no':
                no = t
        if yes is None and no is None:
            # nessun branch Python
            return None
        # sym: threading cross-blocco — l'ultimo calc del predecessore
        # unico e' l'espressione piu' recente testata dal branch
        # (MSVC: call/operazione nel pred, test+branch in questo blocco)
        preds = [pp for pp in self.npred.get(b.start, ())
                 if pp in self.blocks and
                 self.blocks[pp].kind != 'error']
        if len(preds) == 1:
            for o in reversed(self.blocks[preds[0]].ops):
                if o.kind == 'calc' and o.a is not None:
                    sym = o.a
                    break
        # fallback: dal campo conds (confronto cross-blocco registrato
        # dal lifter)
        if sym is None:
            for t, et, csym in getattr(b, 'conds', []):
                if csym is not None:
                    sym = csym
        for o in b.ops:
            if o.kind == 'condmark' and o.a is not None and \
                    o.a.op in ('isnull',):
                sym = o.a
            elif o.kind == 'calc' and o.a is not None and \
                    o.a.op in ('cmp', 'bool', 'exc_match', 'isnull'):
                sym = o.a
        if yes is None:
            # cond_no presente: yes = fallthrough implicito
            # (gcc: test;je no_target → fallthrough = yes)
            succs = self.nsucc.get(b.start, []) or list(b.succs)
            for s in succs:
                if s in self.blocks and s != no:
                    yes = s
                    break
        if no is None:
            succs = self.nsucc.get(b.start, []) or list(b.succs)
            for s in succs:
                if s in self.blocks and s != yes:
                    no = s
                    break

        if yes is None:
            return None
        return (sym, yes, no)

    # ------------------------------------------------------------ if
    def _negate_cond(self, sym):
        """Nega una condizione Python recuperata (per l'inversione del
        braccio pass-through di un ``if``).  Ritorna None se la condizione
        non e' negabile con certezza."""
        if not isinstance(sym, NdxSV):
            return None
        if sym.op == 'cmp' and isinstance(sym.a, str) and \
                sym.a in _CMP_NEGATE:
            return ndx_k('cmp', _CMP_NEGATE[sym.a], sym.b, sym.c)
        if sym.op == 'bool':
            return ndx_k('not', sym.a)
        if sym.op == 'not':
            return sym.a
        if sym.op == 'isnull':
            return ndx_k('cmp', 'ne', sym.a, ndx_k('const', None))
        return None

    def _arm_local_merge(self, start, loop, limit=64):
        """Merge IN-LOOP del braccio che non esce: primo blocco raggiunto
        dal braccio che ha anche un predecessore esterno al braccio (una
        convergenza reale del diamante), restando dentro il corpo del
        ciclo.  Questo e' il punto in cui la camminata deve riprendere
        quando l'ALTRO braccio esce dal ciclo (break/continue/return)."""
        if start is None or loop is None:
            return None
        header = loop.get('header')
        body = getattr(self.loops.get(header), 'get', lambda _k: None)('body')
        body = set(body or ())
        if not body:
            return None
        visited = set()
        work = [start]
        while work and len(visited) < limit:
            node = work.pop(0)
            if node in visited or node not in self.blocks or \
                    node not in body or node == header:
                continue
            visited.add(node)
            for succ in self.nsucc.get(node, ()):
                if succ in visited or succ not in body or \
                        succ == header or succ not in self.blocks:
                    continue
                preds = [p for p in self.npred.get(succ, ())
                         if p in body and p in self.blocks]
                foreign = [p for p in preds if p not in visited]
                if foreign and any(
                        self.blocks[p].kind != 'error' for p in foreign):
                    return succ
                work.append(succ)
        return None

    def _arm_flows_to_join(self, start, join, loop, limit=64):
        """True se il braccio raggiunge il join restando nel corpo del
        ciclo: e' un braccio di caduta (fall-through), non un'uscita —
        mai sintetizzare break/continue per esso."""
        if start is None or join is None or loop is None:
            return False
        if start == join:
            return True
        header = loop.get('header')
        body = set(getattr(self.loops.get(header), 'get',
                           lambda _k: None)('body') or ())
        if not body or join not in body:
            return False
        visited = set()
        work = [start]
        while work and len(visited) < limit:
            node = work.pop(0)
            if node == join:
                return True
            if node in visited or node not in self.blocks or \
                    node not in body or node == header:
                continue
            visited.add(node)
            work.extend(self.nsucc.get(node, ()))
        return False

    def _structure_if(self, cur, br, stop_set, depth):
        b = self.blocks[cur]
        sym, yes, no = br
        # Conds di verita'/identita' (lowering ``not X`` / ``x is Y``):
        # solo per queste vale il macchinario nuovo (inversione del
        # braccio pass-through, merge locale, guardie di caduta).  Gli if
        # regolari mantengono il comportamento storico.
        new_style = isinstance(sym, NdxSV) and (
            sym.op in ('bool', 'not') or
            (sym.op == 'cmp' and sym.a in ('is', 'is_not')))
        # join: primo blocco comune (postdominatore immediato di cur)
        join = self._join_of(cur, yes, no)
        inner_stop = (stop_set | {join}) if join is not None else stop_set
        loop = self.loop_header_of(cur)
        yes_exits = no_exits = False
        yes_frontier = no_frontier = set()
        if loop is not None:
            yes_exits = self._arm_exits_loop_before_latch(yes, loop,
                                                          truth=new_style)
            no_exits = (no is not None and
                        self._arm_exits_loop_before_latch(no, loop,
                                                          truth=new_style))
            if yes_exits:
                yes_frontier = self._arm_post_loop_frontier(yes, loop)
            if no_exits:
                no_frontier = self._arm_post_loop_frontier(no, loop)
        # Un solo braccio esce dal ciclo (break/continue/return): la
        # continuazione e' il merge LOCALE del braccio che resta, non il
        # postdominatore globale (che sarebbe oltre l'uscita del ciclo).
        if new_style and loop is not None and (yes_exits != no_exits):
            non_exit = no if yes_exits else yes
            local = self._arm_local_merge(non_exit, loop)
            if local is not None and local != cur:
                join = local
                inner_stop = stop_set | {join}
        yes_stop = inner_stop | yes_frontier if yes_exits else inner_stop
        no_stop = inner_stop | no_frontier if no_exits else inner_stop
        yes_latch = self._arm_reaches_latch(yes, loop) if loop is not None else False
        no_latch = (self._arm_reaches_latch(no, loop)
                    if loop is not None and no is not None else False)
        yes_stmts = self._seq(yes, yes_stop, depth + 1)
        no_stmts = self._seq(no, no_stop, depth + 1) if no is not None else []
        # Braccio-yes pass-through (vuoto: coincide col join) con braccio-no
        # popolato → inverti: ``if C: pass else: N`` diventa
        # ``if not C: N``.  La forma non invertita inghiottirebbe la
        # continuazione del ciclo nel corpo dell'if.
        if new_style and not yes_stmts and no_stmts and yes != join:
            neg = self._negate_cond(sym)
            if neg is not None:
                sym = neg
                yes, no = no, yes
                yes_stmts, no_stmts = no_stmts, yes_stmts
                yes_exits, no_exits = no_exits, yes_exits
                yes_latch, no_latch = no_latch, yes_latch
                yes_stop, no_stop = no_stop, yes_stop
        if loop is not None:
            terminal_kinds = {'break', 'continue', 'return', 'raise'}
            if new_style:
                yes_falls = self._arm_flows_to_join(yes, join, loop)
                no_falls = (no is not None and
                            self._arm_flows_to_join(no, join, loop))
            else:
                yes_falls = no_falls = False
            if new_style:
                if yes_exits and not yes_falls and \
                        (not yes_stmts or yes_stmts[-1].kind not in
                         terminal_kinds):
                    yes_stmts.append(NdxSt('break', blocks={cur}))
                if no is not None and no_exits and not no_falls and \
                        (not no_stmts or no_stmts[-1].kind not in
                         terminal_kinds):
                    no_stmts.append(NdxSt('break', blocks={cur}))
                # sintesi del continue: braccio che torna al latch senza
                # uscire dal ciclo (il proseguimento lineare e' il percorso
                # di caduta, non il braccio).  Un braccio che COINCIDE col
                # join e' il pass-through: non e' mai un ``continue``.
                if yes_latch and not yes_exits and not yes_falls and (
                        not yes_stmts or yes_stmts[-1].kind not in
                        terminal_kinds | {'continue'}):
                    yes_stmts.append(NdxSt('continue', blocks={cur}))
                if no is not None and no_latch and not no_exits and \
                        not no_falls and (
                        not no_stmts or no_stmts[-1].kind not in
                        terminal_kinds | {'continue'}):
                    no_stmts.append(NdxSt('continue', blocks={cur}))
            else:
                if yes_exits and \
                        (not yes_stmts or yes_stmts[-1].kind not in
                         terminal_kinds):
                    yes_stmts.append(NdxSt('break', blocks={cur}))
                if no_exits and \
                        (not no_stmts or no_stmts[-1].kind not in
                         terminal_kinds):
                    no_stmts.append(NdxSt('break', blocks={cur}))
                # sintesi del continue: braccio che torna al latch senza
                # uscire dal ciclo (il proseguimento lineare e' il percorso
                # di caduta, non il braccio)
                if yes_latch and not yes_exits and (
                        not yes_stmts or yes_stmts[-1].kind not in
                        terminal_kinds | {'continue'}):
                    yes_stmts.append(NdxSt('continue', blocks={cur}))
                if no is not None and no_latch and not no_exits and (
                        not no_stmts or no_stmts[-1].kind not in
                        terminal_kinds | {'continue'}):
                    no_stmts.append(NdxSt('continue', blocks={cur}))
        # boolean expression pattern: yes-region e no-region entrambe
        # single-block senza statement ma con calcolo di valore → and/or
        bo = self._try_bool_expr(b, sym, yes, no, yes_stmts, no_stmts)
        if bo is not None:
            # restituisce come "statement" virtuale d'espressione
            return bo, join if join is not None else self._next_normal(cur)
        line = self._line_of(b)
        blocks = {cur}
        for sub in (yes_stmts or []) + (no_stmts or []):
            blocks |= (sub.blocks or set())
        st = NdxSt('if', a=sym, b=yes_stmts, c=no_stmts, d=(yes, no),
                line=line, blocks=blocks)
        return st, join

    def _arm_post_loop_frontier(self, start, loop, limit=800):
        """Find where a break arm rejoins the iterator's normal exit.

        Blocks containing source statements that execute only before a
        ``break`` need not belong to the natural-loop set (they do not reach
        its latch), so the first edge outside that set is not a valid source
        boundary.  A ``for`` supplies stronger evidence: its typed
        StopIteration path and an explicit break converge at the first real
        post-loop continuation.  Return that convergence as a stop frontier.
        """
        body = set(loop.get('body', ()))
        # Un braccio che PARTE fuori dal corpo (uscita gia' avvenuta:
        # clone di finally/break-path) ha il frontier nel suo stesso
        # inizio: la camminata non deve risalire l'epilogo.
        if start is not None and start not in body and \
                start in self.blocks and \
                not (loop.get('header') == start):
            return {start}
        stopiter_targets = {
            target
            for node in body if node in self.blocks
            for target, edge_type in self.blocks[node].edges
            if edge_type == 'stopiter' and target in self.blocks
        }

        def distances(starts):
            queue = [(value, 0) for value in starts
                     if value is not None and value in self.blocks]
            result = {}
            while queue and len(result) < limit:
                node, distance = queue.pop(0)
                if node in result:
                    continue
                result[node] = distance
                for successor in self.nsucc.get(node, ()):
                    if successor not in result:
                        queue.append((successor, distance + 1))
            return result

        if stopiter_targets:
            arm_distances = distances((start,))
            exit_distances = distances(stopiter_targets)
            common = set(arm_distances).intersection(exit_distances)
            # Re-entering the same loop header is the next iteration, not a
            # post-loop convergence.  Prefer a normal semantic continuation
            # when cleanup paths offer more than one common node.
            common.discard(loop.get('header'))
            normal = [node for node in common
                      if self.blocks[node].kind not in ('error', 'stopiter')]
            if normal:
                best = min(normal, key=lambda node: (
                    arm_distances[node] + exit_distances[node],
                    max(arm_distances[node], exit_distances[node]), node))
                return {best}
        # While-loops and unusual iterator templates may lack a typed
        # StopIteration edge.  Retain the conservative natural-loop frontier
        # as a fallback rather than traversing into arbitrary following code.
        return {
            successor
            for node in body
            for successor in self.nsucc.get(node, ())
            if successor not in body
        }

    def _outside_chain_has_ops(self, start, body, limit=10):
        """True se la catena fuori-body da start contiene blocchi con
        operazioni Python lifted (il percorso di un break sorgente) —
        le catene vuote sono machinery (propagazione d'eccezione)."""
        seen = set()
        work = [start]
        while work and len(seen) <= limit:
            n = work.pop(0)
            if n in seen or n not in self.blocks or n in body:
                continue
            seen.add(n)
            b = self.blocks[n]
            if b.ops:
                return True
            work.extend(s for s in self.nsucc.get(n, [])
                        if s not in body and s not in seen)
        return False

    def _outside_chain_has_ops(self, start, body, limit=10):
        """True se la catena fuori-body da start contiene blocchi con
        operazioni Python lifted (il percorso di un break sorgente) —
        le catene vuote sono machinery (propagazione d'eccezione)."""
        seen = set()
        work = [start]
        while work and len(seen) <= limit:
            n = work.pop(0)
            if n in seen or n not in self.blocks or n in body:
                continue
            seen.add(n)
            b = self.blocks[n]
            if b.ops:
                return True
            work.extend(s for s in self.nsucc.get(n, [])
                        if s not in body and s not in seen)
        return False

    def _arm_reaches_latch(self, start, loop, limit=400):
        """True se il braccio torna al latch/header del loop (prosegue
        l'iterazione = semantica di ``continue``) restando nel corpo."""
        body = set(loop.get('body', ()))
        header = loop.get('header')
        latches = set(loop.get('latches', ()))
        seen = set()
        work = [start]
        while work and len(seen) < 300:
            n = work.pop()
            if n in seen:
                continue
            if n in latches or (n == header and n != start):
                return True
            seen.add(n)
            if n not in self.blocks:
                continue
            for s in self.nsucc.get(n, ()):
                if s in body:
                    work.append(s)
        return False

    def _arm_exits_loop_before_latch(self, start, loop, limit=600,
                                     truth=False):
        """Whether one branch leaves a natural loop before reaching its latch.

        This is the machine-CFG shape of a source ``break``.  Reaching the
        header is normal iteration; typed StopIteration/error/compound-guard
        edges are protocol exits and do not count as an explicit break.
        ``truth`` abilita le regole per le catene di verita' (``not X``):
        il braccio che PARTE fuori dal corpo (clone di finally post-loop)
        e' un'uscita certain, e gli edge stopiter con target in-body sono
        la continuazione normale di un for annidato, non uscite.
        """
        if start is None or start not in self.blocks:
            return False
        body = set(loop.get('body', ()))
        header = loop.get('header')
        latches = set(loop.get('latches', ()))
        # Il braccio PARTE gia' fuori dal corpo (cloni di finally/exit
        # post-loop raggiunti dal break): l'uscita dal ciclo e' un fatto,
        # non una proiezione.
        if truth and body and start not in body and start != header:
            return True
        work = [start]
        seen = set()
        reached_latch = False
        reached_outside = False
        while work and len(seen) < limit:
            node = work.pop()
            if node in seen:
                continue
            if node in latches:
                reached_latch = True
                continue
            if node == header and node != start:
                reached_latch = True
                continue
            seen.add(node)
            block = self.blocks.get(node)
            if block is None:
                continue
            edge_types = defaultdict(set)
            for target, edge_type in block.edges:
                edge_types[target].add(edge_type)
            for successor in self.nsucc.get(node, ()):
                types = edge_types.get(successor, set())
                if types.intersection(('error', 'stopiter', 'guard_fail')) \
                        and (successor not in body or not truth):
                    # Uscita di protocollo/machinery: conta solo se lascia
                    # il ciclo.  Con truth, l'edge stopiter di un for
                    # ANNIDATO verso un target in-body e' la continuazione
                    # normale del corpo while esterno: la camminata deve
                    # seguirlo, altrimenti ogni braccio con un break
                    # condizionato dentro un for risulta un'uscita.
                    continue
                if successor == header:
                    reached_latch = True
                    continue
                if successor not in body:
                    target = self.blocks.get(successor)
                    if target is not None and target.kind not in (
                            'error', 'stopiter'):
                        # solo le catene fuori-body con operazioni reali
                        # contano come break; le catene vuote sono
                        # propagazione d'eccezione/machinery
                        if self._outside_chain_has_ops(successor, body):
                            reached_outside = True
                    continue
                work.append(successor)
        # Un braccio che raggiunge il latch prosegue il ciclo normalmente:
        # le uscite laterali sul suo percorso sono machinery, non break.
        return reached_outside and not reached_latch

    def _join_of(self, cur, yes, no):
        """Join = postdominatore immediato di cur (convergenza dei rami).
        Non attraversa i loop: il postdominatore è calcolato sul grafo del
        flusso normale."""
        # Inside a loop the global postdominator is often the loop header,
        # even for a source ``if`` whose false arm is the local continuation.
        # If one branch reaches the other without crossing the loop header,
        # that branch target is the exact local join.
        loop = self.loop_header_of(cur)
        barrier = loop['header'] if loop is not None else None

        def reaches(start, target):
            if start is None or target is None:
                return False
            work = [start]
            seen = set()
            while work:
                node = work.pop()
                if node == target:
                    return True
                if node in seen or (node == barrier and node != start):
                    continue
                seen.add(node)
                work.extend(self.nsucc.get(node, ()))
            return False

        if no is not None and reaches(yes, no):
            return no
        if yes is not None and reaches(no, yes):
            return yes
        pd = getattr(self, 'pdom', {}).get(cur)
        if pd is not None and pd != cur and pd in self.blocks:
            return pd
        # fallback: primo blocco comune per BFS con limite
        if yes is None:
            return no
        if no is None:
            return None
        def reach(a):
            seen = set()
            work = [a]
            while work:
                x = work.pop()
                if x in seen:
                    continue
                seen.add(x)
                for s in self.nsucc.get(x, []):
                    work.append(s)
            return seen
        ry = reach(yes)
        rn = reach(no)
        common = ry & rn
        if common:
            return min(common)
        return None

    def _try_bool_expr(self, b, sym, yes, no, yes_stmts, no_stmts):
        """Riconosci `a and b` / `a or b`: branch i cui corpi sono puri
        calcoli assegnati alla stessa locazione."""
        # TODO attivato dopo test base; per ora disattivo
        return None

    # ------------------------------------------------------------ loops
    def _structure_loop(self, header, stop_set, depth):
        lp = self.loops[header]
        body = set(lp['body'])
        # uscite del loop: successori normali fuori dal body
        exits = {}
        stopiter_exits = set()
        for st in body:
            for s in self.nsucc.get(st, []):
                if s not in body:
                    exits.setdefault(s, []).append(st)
            # ``tp_iternext == NULL`` reaches Nuitka's StopIteration cleanup
            # region through a typed edge.  That edge is deliberately absent
            # from ``nsucc`` (it is not part of the loop body), but its target
            # is precisely the structural continuation of a Python ``for``.
            # Keep it as an exit so sequencing can pass through the cleanup
            # region and reach statements/return after the loop.
            for target, edge_type in self.blocks[st].edges:
                if edge_type == 'stopiter' and target not in body:
                    exits.setdefault(target, []).append(st)
                    stopiter_exits.add(target)
        # Detect the iterator protocol before ranking exits.  Refcount
        # deallocation diamonds may also leave the natural-loop set, but for
        # a proven Python ``for`` only the typed StopIteration edge is its
        # language-level continuation.
        for_info = self._detect_for(header, lp, exits)
        # uscita "dopo il loop": preferisci blocchi non-error con più
        # predecessori interni (l'uscita strutturale del costrutto)
        after = None
        if exits:
            if for_info is not None and stopiter_exits:
                pool = list(stopiter_exits)
            else:
                good = [e for e in exits
                        if self.blocks.get(e) is not None and
                        self.blocks[e].kind not in ('error', 'stopiter')]
                pool = good if good else list(exits)

            def exit_rank(e):
                srcs = exits[e]
                # uscita strutturale: da un blocco con condizione Python
                cond_src = any(self.blocks[s].conds for s in srcs
                               if s in self.blocks)
                return (1 if cond_src else 0, len(srcs))
            after = max(pool, key=exit_rank)
        # header: contiene next(iter)? → for
        line = self._line_of(self.blocks[header])
        if for_info is not None:
            itvar, iterable, itersym = for_info
            _ = itersym
            body_stop = stop_set | {after} if after is not None else stop_set
            body_stop = body_stop | {header}
            # il latch (avanzamento iternext) e' meccanismo del for:
            # fermare il body walk ai latch evita il sotto-loop while
            # True con lo next di avanzamento reso come statement
            pass  # BISECT5: body_stop = body_stop | set(lp.get('latches') or ())

            # il body inizia dopo l'assegnazione della variabile
            body_stmts = self._seq_body(header, body_stop, depth + 1, body,
                                        skip_for_assign=for_info)
            blocks = {header}
            for sub in (body_stmts or []):
                blocks |= (sub.blocks or set())
            # gen_mode: i blocchi-yield nella regione del loop sono la
            # semantica del generatore. Il walker può saltarli quando il
            # valore attraversa un diamante di calcolo (l'espressione è già
            # simbolizzata): si iniettano in ordine di indirizzo se il
            # corpo non li contiene già.
            if getattr(getattr(self, 'L', None), 'gen_mode', False):
                yblocks = sorted(
                    st2 for st2 in lp['body']
                    if st2 in self.blocks and
                    any(o.kind == 'yield' for o in self.blocks[st2].ops))
                if yblocks and not any(
                        s3.kind == 'yield' for s3 in body_stmts):
                    for yb2 in yblocks:
                        body_stmts.extend(
                            self._block_stmts(self.blocks[yb2]))
                blocks2 = {header}
                for sub in (body_stmts or []):
                    blocks2 |= (sub.blocks or set())
                blocks = blocks2
            body_stmts = self._clean_for_body(body_stmts)
            # for-else: gli statement del corpo i cui blocchi sono TUTTI
            # fuori dal body set sono la clausola else (percorso di
            # esaurimento), non il corpo
            body_set = set(body)
            else_stmts = []
            inner_body = []
            for sub in (body_stmts or []):
                s_blocks = getattr(sub, 'blocks', None) or set()
                if s_blocks and s_blocks & body_set:
                    inner_body.append(sub)
                else:
                    else_stmts.append(sub)
            if else_stmts and inner_body:
                body_stmts = inner_body
                blocks = {header}
                for sub in (body_stmts or []):
                    blocks |= (sub.blocks or set())
            # il return dopo il for-else e' post-loop, non else
            post_ret = [s for s in else_stmts if s.kind == 'return']
            else_only = [s for s in else_stmts if s.kind != 'return']
            st = NdxSt('for', a=itvar, b=iterable, c=body_stmts,
                    d=after, e=itersym, f=else_only or None,
                    line=line, blocks=blocks)
            return [st] + post_ret, after

        # while: condizione dal branch del header
        wh = self._detect_while(header, lp, after)
        if wh is not None:
            cond, body_entry, else_blk = wh
            else_stop = stop_set | ({after} if after is not None else set())
            else_stmts = []
            if else_blk is not None and else_blk in self.blocks:
                entry = self._skip_error_to_normal(else_blk)
                if entry is not None:
                    else_stmts = self._seq(entry, else_stop, depth + 1,
                                           enter_stop=True)
            body_stop = stop_set | ({after} if after is not None else set())
            body_stop.add(header)
            body_stmts = self._seq(body_entry if body_entry else header,
                                   body_stop, depth + 1)
            if not body_stmts and len(lp['body']) > 2:
                # il body_entry scelto è un ramo non classificato
                # (cond_unknown, nessuna op, doppio successore): il corpo
                # vero parte dal primo blocco del loop — su funzioni lunghe
                # questo recupera centinaia di blocchi altrimenti persi
                body_stmts = self._seq(
                    self._first_body_block(header, body),
                    body_stop, depth + 1)
            blocks = {header}
            for sub in (body_stmts or []):
                blocks |= (sub.blocks or set())
            st = NdxSt('while', a=cond, b=body_stmts, c=after,
                    d=else_stmts or None, line=line, blocks=blocks)
            return [st], after
        # while True (o condizione non isolabile): il corpo parte dal
        # blocco header stesso — i suoi statement girano ad ogni iterazione
        body_stop = stop_set | ({after} if after is not None else set())
        body_stop.add(header)
        body_stmts = self._seq(header, body_stop, depth + 1,
                               enter_stop=True)
        blocks = {header}
        for sub in (body_stmts or []):
            blocks |= (sub.blocks or set())
        st = NdxSt('while', a=None, b=body_stmts, c=after,
                line=line, blocks=blocks)
        return [st], after
    @staticmethod
    def _temp_used(stmts_after, name):
        for s2 in stmts_after or []:
            stack = [s2]
            while stack:
                x = stack.pop()
                if x is None:
                    continue
                if isinstance(x, NdxSV):
                    if x.op in ('var', 'loc') and x.a == name:
                        return True
                    stack.extend((x.a, x.b, x.c))
                elif hasattr(x, 'kind'):
                    if x.a == name:
                        return True
                    stack.extend([getattr(x, f, None)
                                  for f in ('a', 'b', 'c', 'd', 'e')])
                    for f in ('b', 'c'):
                        v = getattr(x, f, None)
                        if isinstance(v, list):
                            stack.extend(v)
                elif isinstance(x, (list, tuple)):
                    stack.extend(x)
        return False

    def _clean_for_body(self, stmts, depth=0, tail_strip=True):
        """Pulizia del corpo for: (1) un ``while True`` SENZA uscite
        (break/continue/return/raise) dentro un for e' un artefatto
        della cycle-detection (il rejoin dell'handler/latch letto come
        sotto-loop): si srotola nel corpo; (2) le statement di
        macchinario (expr su api_symbol, assign a temp morti) si
        eliminano: non sono sorgente."""
        if depth > 6:
            return stmts
        out = []
        for idx, s in enumerate(stmts or []):
            if s is None or not hasattr(s, 'kind'):
                continue
            if s.kind == 'while' and s.a is None:
                body = s.b or []
                if not self._loop_has_exit(body, 0) and not any(
                        bl_ in self.blocks and
                        (self.blocks[bl_].ops or self.blocks[bl_].conds)
                        for bl_ in (s.blocks or set())):
                    # ciclo privo di operazioni: artefatto di cycle-detection
                    out.extend(self._clean_for_body(body, depth + 1))
                    continue
            if s.kind == 'for' and depth > 0 and \
                    isinstance(getattr(s, 'b', None), NdxSV) and \
                    s.b.op in ('next', 'var', 'loc', 'par'):
                # latch del for strutturato come sotto-loop
                # auto-referenziale (``for X in X``/``for X in next(X)``):
                # artefatto — srotola il corpo scartando i break del
                # latch e i next di avanzamento
                self_ref = s.b.op == 'next'
                if not self_ref and s.b.op == 'loc' and \
                        isinstance(s.b.a, tuple) and s.b.a and \
                        s.b.a[0] == 'reg':
                    # iterabile su REGISTRO dentro un for annidato:
                    # e' l'oggetto iteratore del latch, mai sorgente
                    # (gli iterabili sorgente vivono in var/par/slot)
                    self_ref = True
                if not self_ref:
                    try:
                        nm = (self.name_of_loc(s.b.a)
                              if s.b.op == 'loc' else s.b.a)
                    except Exception:
                        nm = None
                    self_ref = (nm == s.a)
                if self_ref:
                    inner = self._clean_for_body(s.c or [], depth + 1)
                    inner = self._strip_breaks(inner)
                    out.extend(inner)
                    continue
            if s.kind == 'expr' and isinstance(s.a, NdxSV) and \
                    s.a.op == 'next':
                # next() di avanzamento come statement: macchinario
                continue
            if s.kind == 'expr' and isinstance(s.a, NdxSV) and \
                    s.a.op == 'next':
                # next() di avanzamento come statement: macchinario
                continue
            if s.kind == 'expr' and isinstance(s.a, NdxSV) and \
                    s.a.op in ('api_symbol', 'gaddr'):
                continue
            if s.kind == 'assign' and isinstance(s.a, str) and \
                    s.a.startswith('_'):
                rest = stmts[idx + 1:]
                if not self._temp_used(rest, s.a):
                    # temp mai letto: eliminabile SOLO se il valore e'
                    # puro.  Un RHS con chiamata/append e' un statement di
                    # effetto sorgente (``TOTAL.append(x)``): degrada a
                    # expr invece di scartarlo.
                    if _ndx_sv_has_effect(s.b):
                        out.append(NdxSt('expr', a=s.b,
                                         line=getattr(s, 'line', None),
                                         blocks=getattr(s, 'blocks', None)))
                    continue
            if s.kind in ('assign', 'expr') and \
                    isinstance(getattr(s, 'b', None), NdxSV) and \
                    s.b.op == 'next':
                # avanzamento iternext del for: non e' sorgente,
                # a meno che il target non sia riusato dopo
                if not (s.kind == 'assign' and \
                        isinstance(s.a, str) and \
                        self._temp_used(stmts[idx + 1:], s.a)):
                    continue
            for f in ('b', 'c'):
                v = getattr(s, f, None)
                if isinstance(v, list) and v and \
                        all(hasattr(g, 'kind') for g in v):
                    # le braccia di un if NON sono corpi di loop: lì un
                    # continue di coda resta (un else lo rende vivo)
                    setattr(s, f, self._clean_for_body(
                        v, depth + 1, tail_strip=(s.kind != 'if')))
            out.append(s)
        if not tail_strip:
            return out
        # ``continue`` in coda a un corpo di loop (o alla fine di un braccio
        # if SENZA else che chiude il corpo): il latch esiste sempre nel
        # flusso nativo e la struttura lo emette come statement esplicito,
        # il sorgente no → drop.  Il salto risultante raggiunge comunque il
        # latch, quindi la semantica non cambia.
        while out:
            last = out[-1]
            if getattr(last, 'kind', None) == 'continue':
                out.pop()
                continue
            if getattr(last, 'kind', None) == 'if' and not getattr(
                    last, 'c', None) and isinstance(getattr(last, 'b', None),
                                                    list) and last.b and \
                    getattr(last.b[-1], 'kind', None) == 'continue':
                last.b.pop()
                if not last.b:
                    out.pop()
                continue
            break
        # store consecutivi della STESSA variabile con lo STESSO valore
        # (alias di slot spill: rbp-9 / rbp-49 → 'fetched'): un solo
        # assegnamento. Due ``x += k`` consecutivi NON sono duplicati qui
        # perche' il secondo binop annida il primo.
        if len(out) > 1:
            dedup = [out[0]]
            for s in out[1:]:
                p = dedup[-1]
                if (s.kind == 'assign' and p.kind == 'assign' and
                        isinstance(s.a, str) and s.a == p.a and
                        isinstance(s.b, NdxSV) and isinstance(p.b, NdxSV)
                        and _sv_eq(s.b, p.b)):
                    continue
                dedup.append(s)
            out = dedup
        return out

    @staticmethod
    def _strip_breaks(stmts, depth=0):
        if depth > 8:
            return stmts or []
        out = []
        for s in stmts or []:
            if s is None or not hasattr(s, 'kind'):
                continue
            if s.kind == 'break':
                continue
            for f in ('b', 'c'):
                v = getattr(s, f, None)
                if isinstance(v, list) and v and \
                        all(hasattr(g, 'kind') for g in v):
                    setattr(s, f, Structurer._strip_breaks(v, depth + 1))
            out.append(s)
        return out

    def _loop_has_exit(self, stmts, depth=0):
        if depth > 8:
            return True        # non provabile: non srotolare
        for s in stmts or []:
            if s is None or not hasattr(s, 'kind'):
                continue
            if s.kind in ('break', 'continue', 'return', 'raise'):
                return True
            if s.kind == 'try':
                # corpo e clausole (tuple (types, body, line)):
                # una raise ovunque e' un'uscita dal while
                if self._loop_has_exit(s.a or [], depth + 1):
                    return True
                for clause in (s.b or []):
                    if isinstance(clause, tuple) and len(clause) >= 2 \
                            and self._loop_has_exit(clause[1] or [], depth + 1):
                        return True
                continue
            for f in ('b', 'c'):
                v = getattr(s, f, None)
                if isinstance(v, list) and self._loop_has_exit(v, depth + 1):
                    return True
        return False

        return [st], after

    def _structure_for_guard(self, cur, stop_set, depth, visited=None):
        """Guard di ``for`` con ciclo ruotato/fuso (GCC): il blocco esegue
        ``next(iter(X))`` con due esiti — valore (continua nel corpo) e
        StopIteration (edge tipizzato verso la continuazione). Costruisce
        ``for var in X:`` col corpo dal successore del valore, e ritorna
        la continuazione dopo il loop."""
        b = self.blocks[cur]
        next_sym = None
        for o in b.ops:
            if o.kind == 'calc' and o.a is not None and o.a.op == 'next':
                next_sym = o.a
                break
        if next_sym is None or next_sym.a is None:
            return None
        iter_sym = next_sym.a
        # identità dell'iteratore: un secondo guard sullo STESSO iter
        # è il latch dello stesso for (ciclo ruotato) — mai strutturare
        # due for per un solo iteratore (ricorsione infinita)
        try:
            _ik = sv_key(iter_sym)
        except Exception:
            _ik = id(iter_sym)
        done = getattr(self, '_for_iter_done', None)
        if done is None:
            done = self._for_iter_done = set()
        if _ik in done:
            return None
        done.add(_ik)
        iterable = iter_sym.a if iter_sym.op == 'iter' else iter_sym
        _rng = self._synthesize_range_from_advance(iterable, cur)
        if _rng is not None:
            iterable = _rng
        exit_t = next((t for t, et in b.edges if et == 'stopiter'), None)
        val_succs = [s for s in self.nsucc.get(cur, []) if s != exit_t]
        if exit_t is None or not val_succs or exit_t not in self.blocks:
            return None
        body_entry = val_succs[0]
        # il successore-valore È il latch del ciclo corrente se è già
        # stato visitato: il corpo è già stato emesso, questo blocco
        # chiude il for — mai strutturare un secondo for (ricorsione)
        if visited is not None and body_entry in visited:
            return None
        # nome della variabile di loop: lo store del valore next
        itvar = None
        for st2, bb in self.blocks.items():
            for o in bb.ops:
                if o.kind == 'store' and o.b is next_sym:
                    nm = self.authoritative_sym_names.get(sv_key(next_sym)) or self.authoritative_loc_names.get(o.a) or self.var_names.get(o.a)
                    if isinstance(nm, str):
                        itvar = nm
                    break
            if itvar is not None:
                break
        if itvar is None:
            itvar = self._take_varname()
        self.sym_names[id(next_sym)] = itvar
        if not hasattr(self, 'sym_keys'):
            self.sym_keys = {}
        try:
            self.sym_keys[sv_key(next_sym)] = itvar
        except Exception:
            pass
        body_stop = set(stop_set) | {cur, exit_t}
        body_stmts = self._seq(body_entry, body_stop, depth + 1)
        body_stmts = self._clean_for_body(body_stmts, 1)
        blocks = {cur}
        for sub in (body_stmts or []):
            blocks |= (sub.blocks or set())
        st = NdxSt('for', a=itvar, b=iterable, c=body_stmts,
                   d=exit_t, e=None, line=self._line_of(b), blocks=blocks)
        return st, exit_t

    def _first_body_block(self, header, body):
        succs = [s for s in self.nsucc.get(header, []) if s in body]
        return succs[0] if succs else header

    def _seq_body(self, header, stop_set, depth, body, skip_for_assign=None):
        """Sequenza del corpo di un for: salta l'assegnazione della var."""
        # il corpo parte dal blocco dopo il check stop-iteration:
        # l'header produce next(iter) → var; il body reale segue.
        # Il braccio stop-iteration (esaurimento) NON è corpo: escludilo
        # esplicitamente, altrimenti un header con succs=[stopiter, value]
        # in quest'ordine consuma il braccio di macchinario e il corpo
        # del for esce vuoto.
        stopiter_t = {t for t, et in self.blocks[header].edges
                      if et == 'stopiter'} if header in self.blocks else set()
        succs = [s for s in self.nsucc.get(header, [])
                 if s in body and s not in stopiter_t]
        if not succs:
            succs = [s for s in self.nsucc.get(header, []) if s in body]
        stmts = []
        if skip_for_assign:
            itvar, _, _ = skip_for_assign
            # il corpo reale inizia dopo l'assegnazione itvar = next(...)
            for s in succs:
                b = self.blocks[s]
                bstmts = self._block_stmts(b, skip_assign_to=[itvar])
                stmts.extend(bstmts)
                nxt = self._next_normal(s)
                if nxt is not None and nxt not in stop_set:
                    stmts.extend(self._seq(nxt, stop_set, depth))
                break
            return stmts
        return self._seq(succs[0] if succs else header, stop_set, depth)

    def _detect_for(self, header, lp, exits=None):
        """For Nuitka: next(iter) con iteratore LOOP-INVARIANTE (creato
        FUORI dal corpo) e assegnazione a variabile. Un next() inline
        (es. next(iter(x)) come argomento) crea l'iteratore DENTRO il loop
        ad ogni iterazione → non è un for."""
        body_order = [header] + sorted(
            st for st in lp['body'] if st != header)
        # mappa sym-id → blocco creatore (per op calc)
        creator_of = {}
        for st2, bb in self.blocks.items():
            for o in bb.ops:
                if o.kind == 'calc' and o.a is not None:
                    creator_of.setdefault(id(o.a), st2)
        next_sym = None
        hdr_addr = header if isinstance(header, int) else None
        for st in body_order[:12]:
            b = self.blocks[st]
            for o in b.ops:
                if o.kind == 'calc' and o.a is not None and \
                        o.a.op == 'next' and o.a.a is not None:
                    it = o.a.a
                    creator = creator_of.get(id(it))
                    if creator is None or creator not in lp['body']:
                        next_sym = o.a
                        break
            if next_sym is not None:
                break
        if next_sym is None:
            return None
        itvar = None
        for st in body_order[:12]:
            bb = self.blocks[st]
            for o in bb.ops:
                if o.kind == 'store' and o.b is next_sym:
                    itvar = (self.authoritative_loc_names.get(o.a) or
                             self.authoritative_sym_names.get(
                                 sv_key(next_sym)) or
                             self._take_varname())
                    if itvar in self._free_names:
                        self._free_names.remove(itvar)
                    self.sym_names[id(next_sym)] = itvar
                    if not hasattr(self, 'sym_keys'):
                        self.sym_keys = {}
                    self.sym_keys[sv_key(next_sym)] = itvar
                    if o.a is not None:
                        self.var_names[o.a] = itvar
                        self.loc_cur_sym[o.a] = id(next_sym)
                    break
            if itvar is not None:
                break
        if itvar is None:
            itvar = self._take_varname()
            self.sym_names[id(next_sym)] = itvar
            if not hasattr(self, 'sym_keys'):
                self.sym_keys = {}
            self.sym_keys[sv_key(next_sym)] = itvar
        # iterabile: iter(X) → X
        iterable = next_sym.a.a if next_sym.a is not None else None
        _rng = self._synthesize_range_from_advance(
            iterable, hdr_addr)
        if _rng is not None:
            iterable = _rng
        return (itvar, iterable, next_sym.a)

    def _synthesize_range_from_advance(self, iterable, before_addr):
        """RANGE SPECIALIZZATO a registri: l'iteratore e' collassato e
        l'avanzamento compare come binop tra COSTANTI (l'indice iniziale
        immortalato = start, la costante = step).  Lo stop e' il binop
        '+' con operando PAR (il bound calcolato dal sorgente, es.
        n + 1) nel blocco piu' vicino SOPRA il loop."""
        if (iterable is None or not hasattr(iterable, 'op') or
                iterable.op != 'binop' or iterable.a != '+' or
                not isinstance(getattr(iterable, 'b', None), NdxSV) or
                iterable.b.op != 'const' or
                not isinstance(iterable.b.a, int) or
                not isinstance(getattr(iterable, 'c', None), NdxSV) or
                iterable.c.op != 'const' or
                not isinstance(iterable.c.a, int)):
            return None
        _start = iterable.b.a
        _stop_sym = None
        _best_addr = None
        for st, bb in self.blocks.items():
            if before_addr is not None and st >= before_addr:
                continue
            for o in bb.ops:
                sv = getattr(o, 'a', None)
                if (o.kind == 'calc' and isinstance(sv, NdxSV) and
                        sv.op == 'binop' and sv.a == '+' and
                        isinstance(getattr(sv, 'b', None), NdxSV) and
                        sv.b.op == 'par'):
                    if _best_addr is None or st > _best_addr:
                        _best_addr = st
                        _stop_sym = sv
        if _stop_sym is None:
            return None
        return ndx_k('call', 'range',
                     [ndx_k('const', _start), _stop_sym])

    def _skip_error_to_normal(self, blk):
        """Segue la catena raw dei blocchi classificati 'error' fino al
        primo blocco normale."""
        seen = set()
        node = blk
        for _ in range(16):
            if node not in self.blocks:
                return None
            b = self.blocks[node]
            if b.kind != 'error':
                return node
            if node in seen:
                return None
            seen.add(node)
            succs = [s for s in b.succs if s in self.blocks]
            normal = [s for s in succs
                      if self.blocks[s].kind != 'error']
            if normal:
                node = normal[0]
            elif succs:
                node = succs[0]
            else:
                return None
        return None

    def _singleton_exit_polarity(self, b, succs, body):
        """Test d'identita' bool: cmp reg, [rip+slot] con slot che risolve a
        _Py_TrueStruct/_Py_FalseStruct, seguito da jcc verso uno dei due
        successori.  Se uno dei bracci esce dal ciclo (non raggiunge il
        latch) e l'altro lo raggiunge, restituisce (positive, stay_block).
        positive=True quando il braccio d'uscita e' quello del confronto
        con _Py_FalseStruct (o jne con _Py_TrueStruct)."""
        pairs = []
        insns = list(getattr(b, 'insns', ()) or [])
        for idx, ins in enumerate(insns):
            if ins.mnemonic in ('cmp', 'test') and 'rip' in ins.op_str:
                t = rip_target(ins)
                nm = self.img.imports.get(t)
                if nm in ('_Py_TrueStruct', '_Py_FalseStruct'):
                    for j in range(idx + 1, min(idx + 4, len(insns))):
                        j2 = insns[j]
                        if j2.mnemonic in ('je', 'jne', 'jmp'):
                            pairs.append((nm, j2.mnemonic, j2.op_str.strip()))
                            break
        if not pairs:
            return None

        def leaves_body(start, limit=24):
            seen = set()
            work = [start]
            while work and len(seen) < limit:
                n = work.pop(0)
                if n in seen or n not in self.blocks:
                    continue
                seen.add(n)
                for s in self.nsucc.get(n, ()):
                    if s not in body:
                        return True
                work.extend(s for s in self.nsucc.get(n, ())
                            if s in body)
            return False

        for nm, jmn, jtgt in pairs:
            try:
                tgt = int(jtgt, 0)
            except Exception:
                continue
            if tgt not in succs:
                continue
            fall = next((s for s in succs if s != tgt), None)
            if fall is None or jmn == 'jmp':
                continue
            jcc_exits = leaves_body(tgt)
            fall_exits = leaves_body(fall)
            if jcc_exits and not fall_exits:
                # esce quando result == S
                return (nm == '_Py_FalseStruct', tgt)
            if fall_exits and not jcc_exits:
                # esce quando result != S
                return (nm == '_Py_TrueStruct', fall)
        return None

    def _arm_flag_stores(self, start, body, rejoin):
        """BFS nel sottografo del braccio (fermo al rejoin): restituisce
        l'insieme dei caricamenti immediati su registro a 32 bit
        (mov r32, imm / xor r32, r32) come {(registro, valore)}.  I blocchi
        'error' contengono comunque flag-store e vengono scansionati."""
        node = start
        seen = set()
        work = [start]
        stores = []
        while work and len(seen) <= 12:
            n = work.pop(0)
            if n in seen or n not in self.blocks or n == rejoin:
                continue
            seen.add(n)
            b = self.blocks[n]
            # i blocchi 'error' contengono comunque i flag-store (il loro
            # nsucc vuoto ferma l'espansione in modo naturale)
            for ins in getattr(b, 'insns', ()) or ():
                mn = ins.mnemonic
                ops = ins.op_str.strip()
                if mn == 'mov' and ',' in ops:
                    dst, rhs = (x.strip().lower()
                                for x in ops.split(',', 1))
                    if re.fullmatch(r'(0x[0-9a-f]+|\d+)', rhs):
                        r = _NDX_REG64_MAP.get(dst, dst)
                        try:
                            stores.append((r, int(rhs, 0)))
                        except Exception:
                            pass
                elif mn == 'xor' and ',' in ops:
                    a1, a2 = (x.strip().lower() for x in ops.split(','))
                    if a1 == a2:
                        r = _NDX_REG64_MAP.get(a1, a1)
                        stores.append((r, 0))
            work.extend(s for s in self.nsucc.get(n, [])
                        if s in body and s != rejoin)
        return {(r, v) for r, v in stores}

    def _flag_exit_test(self, start, body, flag_reg, latch):
        """BFS limitata dal rejoin: raccoglie i valori del flag la cui
        selezione abbandona il corpo (je con target fuori body).  I percorsi
        "prosegui nel corpo" e i test su altri registri sono ignorati."""
        _reg64 = _NDX_REG64_MAP
        exit_vals = set()
        seen = set()
        work = [start]
        while work and len(seen) <= 14:
            n = work.pop(0)
            if n in seen or n not in self.blocks:
                continue
            seen.add(n)
            b = self.blocks[n]
            if b.kind in ('error', 'stopiter'):
                continue
            tested = None
            for ins in getattr(b, 'insns', ()) or ():
                mn = ins.mnemonic
                ops = ins.op_str.strip()
                if mn in ('cmp', 'test') and ',' in ops:
                    parts = [x.strip().lower() for x in ops.split(',', 1)]
                    r = _reg64.get(parts[0], parts[0])
                    if r == flag_reg:
                        if mn == 'test':
                            tested = 0
                        else:
                            try:
                                tested = int(parts[1], 0)
                            except Exception:
                                tested = None
                    else:
                        tested = None
                elif mn in ('je', 'jz') and tested is not None:
                    try:
                        tgt = int(ops, 0)
                    except Exception:
                        continue
                    if tgt not in body:
                        exit_vals.add(tested)
                        if tested == 0:
                            self._last_else_entry = tgt
                    tested = None
                elif mn in ('jne', 'jnz') and tested is not None:
                    tested = None
            work.extend(s for s in self.nsucc.get(n, [])
                        if s in body and s not in seen)
        return exit_vals

    def _detect_while(self, header, lp, after):
        """Nuitka lowers ``while cond:`` as ``while(1) { tmp = cond;
        if (!tmp) break; body }``: the source condition is the FIRST
        Python-level branch reachable from the loop header without executing
        a source statement, and its exit arm must leave the loop.  MSVC
        materialises the boolean through singleton-identity tests and a
        FLAG DIAMOND (both arms load distinct immediates into one register,
        tested after the rejoin) -- handled via ``_singleton_exit_polarity``
        + ``_arm_flag_stores`` + ``_flag_exit_test``."""
        body = lp['body']
        cur = header
        seen = set()
        last_cmp = None
        while cur is not None and cur in body and cur not in seen:
            seen.add(cur)
            b = self.blocks.get(cur)
            if b is None or b.kind in ('error', 'stopiter'):
                return None
            br = self._cond_info(b)
            if br is not None:
                sym, yes, no = br
                if yes is None or no is None:
                    return None
                yes_in = yes in body
                no_in = no in body
                if yes_in and not no_in:
                    # cond vera -> body (yes); cond falsa -> uscita
                    return (self._polarity(sym, positive=True), yes)
                if no_in and not yes_in:
                    # cond vera -> uscita; cond falsa -> body (no)
                    return (self._polarity(sym, positive=False), no)
                return None            # entrambi i rami dentro il ciclo: if
            if self._while_prefix_statements(b):
                return None            # statement prima di un test d'uscita
            for o in b.ops:
                if o.kind == 'calc' and isinstance(o.a, NdxSV) and \
                        o.a.op in ('cmp', 'bool'):
                    last_cmp = o.a
            succs = [s for s in self.nsucc.get(cur, []) if s in body]
            if len(succs) == 2:
                pol = self._singleton_exit_polarity(b, succs, body)
                if pol is not None:
                    positive, stay = pol
                    if last_cmp is not None:
                        return (self._polarity(last_cmp, positive=positive),
                                stay)
                    return None
                # diamante a flag: i bracci caricano immediati nello stesso
                # registro; quello con un valore d'uscita ESCLUSIVO e' il
                # braccio d'uscita (l'altro condivide il valore di
                # proseguimento del percorso truthy generico)
                mid = None
                for cand in succs:
                    nxt = [s for s in self.nsucc.get(cand, [])
                           if s in body]
                    if len(nxt) == 1 and nxt[0] in body:
                        mid = nxt[0]
                        break
                if mid is not None:
                    fa = self._arm_flag_stores(succs[0], body, mid)
                    fb = self._arm_flag_stores(succs[1], body, mid)
                    if fa and fb:
                        regs = {r for r, v in fa} & {r for r, v in fb}
                        if regs:
                            r0 = next(iter(regs))
                            va_ = {v for (rr, v) in fa if rr == r0}
                            vb_ = {v for (rr, v) in fb if rr == r0}
                            if va_ != vb_:
                                latch = next(iter(lp['latches']), None)
                                exit_vals = self._flag_exit_test(
                                    mid, body, r0, latch)
                                if exit_vals:
                                    a0 = bool(va_ & exit_vals)
                                    a1 = bool(vb_ & exit_vals)
                                    if a0 != a1:
                                        stay = succs[1] if a0 else succs[0]
                                        if last_cmp is not None:
                                            return (
                                                self._polarity(
                                                    last_cmp,
                                                    positive=True), stay,
                                                getattr(
                                                    self,
                                                    '_last_else_entry',
                                                    None))
                                        return None
                return None
            if len(succs) != 1:
                return None
            cur = succs[0]
        return None

    def _while_prefix_statements(self, b):
        """True se il blocco esegue source statement prima del test
        d'uscita.  La materializzazione della condizione (cmp/bool/isnull
        anche via call helper consumata dalla branch), il macchinario degli
        iteratori (iter/next) e il bookkeeping dei registri non contano."""
        for o in b.ops:
            if o.kind in ('store_sub', 'store_attr', 'append', 'setadd',
                          'module_assign', 'raise', 'ret'):
                return True
            if o.kind == 'store':
                tgt = o.a
                if isinstance(tgt, tuple) and tgt and tgt[0] == 'reg':
                    continue            # bookkeeping registri
                if isinstance(tgt, NdxSV) and tgt.op == 'reg':
                    continue            # bookkeeping registri
                v = o.b
                if isinstance(v, NdxSV) and v.op in ('cmp', 'bool', 'isnull'):
                    continue            # condizione materializzata
                return True
            if o.kind == 'calc':
                v = o.a
                if isinstance(v, NdxSV) and (v.op in (
                        'cmp', 'bool', 'isnull', 'iter', 'next') or
                        id(v) in getattr(self, '_cond_syms_cache', set())):
                    continue
                return True
        return False

    def _polarity(self, sym, positive=True):
        if sym is None:
            return None
        if positive:
            return sym
        if sym.op == 'cmp':
            inv = CmpInvert.get(sym.a)
            if inv:
                return NdxSV('cmp', inv, sym.b, sym.c)
        if sym.op == 'bool':
            return NdxSV('not', sym.a)
        return NdxSV('not', sym)

    def _line_of(self, b):
        for o in b.ops:
            if o.kind == 'line':
                return o.n
        return None

    # ------------------------------------------------------------ block stmts
    def _block_stmts(self, b, skip_assign_to=None):
        """Converte le ops del blocco in statement."""
        out = []
        line = self._line_of(b)
        # consumi GLOBALI: un calc è statement solo se non è consumato da
        # NESSUNA op/cond in nessun blocco (le espressioni attraversano i
        # confini di blocco: call in un blocco, branch nel successivo)
        if not hasattr(self, '_global_consumed'):
            consumed = set()
            consumed_keys = set()
            intermediate_keys = set()
            last_calc_va = {}

            def use(sym):
                if sym is None:
                    return
                # V100: il grafo SV può contenere cicli (phi, nodi riusati
                # dal lifter): senza early-return la ricorsione esplode
                # (RecursionError) e l'intero corpo funzione va perso.
                # ``consumed`` è per-id: il controllo è anche dedup.
                if id(sym) in consumed:
                    return
                consumed.add(id(sym))
                consumed_keys.add(sv_key(sym))
                for attr in ('a', 'b', 'c'):
                    v = getattr(sym, attr, None)
                    if isinstance(v, NdxSV):
                        use(v)
                    elif isinstance(v, list):
                        for x in v:
                            if isinstance(x, NdxSV):
                                use(x)

            def use_intermediate(sym, _seen=None, _kmemo=None):
                if sym is None:
                    return
                if not isinstance(sym, NdxSV):
                    return
                if _seen is None:
                    _seen = set()
                if _kmemo is None:
                    _kmemo = {}
                if id(sym) in _seen:
                    return
                _seen.add(id(sym))
                # V100: memo per-nodo condivisa (formato sv_key: id→key) —
                # senza questa ogni nodo ripercorre il proprio sottoalbero
                # in sv_key (quadratico sui corpi giganti).
                if id(sym) not in _kmemo:
                    _kmemo[id(sym)] = sv_key(sym, _memo=_kmemo)
                intermediate_keys.add(_kmemo[id(sym)])
                for value in (sym.a, sym.b, sym.c):
                    if isinstance(value, NdxSV):
                        use_intermediate(value, _seen, _kmemo)
                    elif isinstance(value, list):
                        for item in value:
                            if isinstance(item, NdxSV):
                                use_intermediate(item, _seen, _kmemo)

            for bb in self.blocks.values():
                for t, et, csym in getattr(bb, 'conds', []):
                    use(csym)
                for o in bb.ops:
                    if o.kind == 'store':
                        use(o.b)
                    elif o.kind == 'calc' and o.a is not None:
                        # The calc root may be a genuine expression statement;
                        # only its descendants are compiler intermediates.
                        for value in (o.a.a, o.a.b, o.a.c):
                            if isinstance(value, NdxSV):
                                use_intermediate(value)
                            elif isinstance(value, list):
                                for item in value:
                                    if isinstance(item, NdxSV):
                                        use_intermediate(item)
                        last_calc_va[sv_key(o.a)] = max(
                            o.va, last_calc_va.get(sv_key(o.a), 0))
                    elif o.kind in ('store_sub', 'store_attr'):
                        use(o.a); use(o.b); use(o.c)
                    elif o.kind in ('append', 'setadd'):
                        use(o.a); use(o.b)
                    elif o.kind == 'ret':
                        use(o.a)
                    elif o.kind == 'raise':
                        use(o.a)
            container_calls = set()
            for block in self.blocks.values():
                for operation in block.ops:
                    value = operation.a
                    if operation.kind != 'calc' or not isinstance(value, NdxSV) or value.op not in ('tuple_build', 'list_build'):
                        continue
                    pending, seen = [value.b], set()
                    while pending:
                        child = pending.pop()
                        if isinstance(child, NdxSV) and id(child) not in seen:
                            seen.add(id(child))
                            if child.op in ('call', 'kwcall', 'mcall') and isinstance(child.n, int):
                                container_calls.add((child.op, child.n))
                            pending.extend((child.a, child.b, child.c))
                        elif isinstance(child, (list, tuple)):
                            pending.extend(child)
            self._container_call_sites = container_calls
            self._global_consumed = consumed
            self._global_consumed_keys = consumed_keys
            self._intermediate_keys = intermediate_keys
            self._last_calc_va = last_calc_va
        consumed = self._global_consumed
        consumed_keys = self._global_consumed_keys
        intermediate_keys = self._intermediate_keys
        last_calc_va = self._last_calc_va
        ops = b.ops

        # iteratori del for: store di 'iter' consumati da un 'next'
        # (raccolti GLOBALMENTE su tutti i blocchi)
        if not hasattr(self, '_iter_syms'):
            self._iter_syms = set()
            for bb in self.blocks.values():
                for o in bb.ops:
                    if o.kind == 'calc' and o.a is not None and \
                            o.a.op == 'next' and o.a.a is not None:
                        self._iter_syms.add(id(o.a.a))
        iters_used = self._iter_syms
        raised_values = {id(o.a) for o in ops
                         if o.kind == 'raise' and o.a is not None}

        for o in ops:
            transport = o.b if o.kind == 'store' else o.a if o.kind == 'calc' else None
            if isinstance(transport, NdxSV) and sv_key(transport) in getattr(self, '_unpack_transport_keys', set()):
                continue
            if o.kind == 'store':
                if o.b is not None and id(o.b) in raised_values:
                    continue
                if o.b is not None and id(o.b) in iters_used:
                    continue          # setup iteratore del for
                authoritative_locations = \
                    self.authoritative_sym_locations.get(sv_key(o.b), set())
                if authoritative_locations and \
                        o.a not in authoritative_locations and \
                        authoritative_locations.intersection(
                            self.semantic_store_locations.get(
                                sv_key(o.b), set())):
                    # The same value commonly passes through a spill before
                    # reaching the location named by Frame_AttachLocals.
                    # Chained assignments remain intact because every
                    # authoritative destination is retained.
                    continue
                # nome per-VALORE: il registro può essere riusato
                if id(o.b) not in self.sym_names:
                    nm = (self.authoritative_loc_names.get(o.a) or
                          self.authoritative_sym_names.get(sv_key(o.b)))
                    # INPLACE_OPERATION_* receives a pointer to compiler
                    # storage and may write its result through a transient
                    # stack slot before the persistent local is updated.  The
                    # source assignment belongs to the proven left-hand loc,
                    # carried by the binop node, not to that ABI destination.
                    if isinstance(o.b, NdxSV) and o.b.op == 'binop' and \
                            o.b.n == 'inplace' and \
                            isinstance(o.b.b, NdxSV) and \
                            o.b.b.op == 'loc' and \
                            isinstance(o.b.b.a, tuple):
                        left_location = o.b.b.a
                        nm = (self.authoritative_loc_names.get(left_location)
                              or self.var_names.get(left_location) or nm)
                    if nm in self._free_names:
                        self._free_names.remove(nm)
                    # riusa il nome della locazione se è già la variabile
                    # corrente di quella locazione
                    if nm is None and o.a in self.var_names and \
                            (self.loc_cur_sym.get(o.a) == id(o.b) or
                             o.a in self.loop_carried_locations):
                        nm = self.var_names[o.a]
                    elif nm is None:
                        nm = self._take_varname()
                    self.var_names[o.a] = nm
                    self.loc_cur_sym[o.a] = id(o.b)
                    self.sym_names[id(o.b)] = nm
                name = self.sym_names[id(o.b)]
                if skip_assign_to and name in skip_assign_to:
                    continue
                # se il valore è una costante semplice o producer → assign
                out.append(NdxSt('assign', a=name, b=o.b, c=o.a, line=line,
                              blocks={b.start}))
            elif o.kind == 'module_assign':
                out.append(NdxSt('assign', a=o.a, b=o.b, line=line, blocks={b.start}))
            elif o.kind == 'store_sub':
                out.append(NdxSt('store_sub', a=o.a, b=o.b, c=o.c, line=line,
                              blocks={b.start}))
            elif o.kind == 'store_attr':
                out.append(NdxSt('store_attr', a=o.a, b=o.b, c=o.c, line=line,
                              blocks={b.start}))
            elif o.kind == 'append':
                out.append(NdxSt('append', a=o.a, b=o.b, line=line,
                              blocks={b.start}))
            elif o.kind == 'setadd':
                out.append(NdxSt('setadd', a=o.a, b=o.b, line=line,
                              blocks={b.start}))
            elif o.kind == 'calc':
                if o.a is None:
                    continue
                if o.a.op == 'nativecall' and \
                        str(o.a.a) == 'MAKE_FLOAT_FROM_DOUBLE':
                    continue
                key = sv_key(o.a)
                if isinstance(o.a.n, int) and (o.a.op, o.a.n) in self._container_call_sites and (id(o.a) in consumed or key in consumed_keys):
                    out.append(NdxSt('eval_hint', a=o.a, line=line, blocks={b.start}))
                if id(o.a) in consumed or key in consumed_keys or \
                        (key in intermediate_keys and o.a.op in (
                            'getattr', 'sub', 'type_of', 'len', 'bool',
                            'cmp', 'unary', 'iter', 'next')) or \
                        (key in intermediate_keys and
                         o.va < last_calc_va.get(key, o.va)):
                    continue
                if o.a.op in ('call', 'print', 'apicall', 'nativecall',
                              'raise', 'import', 'func_new'):
                    out.append(NdxSt('expr', a=o.a, line=line,
                                  blocks={b.start}))
                elif o.a.op in ('next', 'iter', 'unpack', 'stopiter_value'):
                    # usati solo come parte di loop; se non consumati: skip
                    continue
                else:
                    out.append(NdxSt('expr', a=o.a, line=line,
                                  blocks={b.start}))
            elif o.kind == 'ret':
                out.append(NdxSt('return', a=o.a, line=line, blocks={b.start}))
            elif o.kind == 'yield':
                out.append(NdxSt('yield', a=o.a, line=line, blocks={b.start}))
                # il blocco-yield termina con `mov rax,val; ret/jmp epilogo`:
                # il ret è il TRASPORTO del valore yieldato, non un return
                # Python — soppresso per evitare `return` dopo `yield`.
                for o2 in ops:
                    if o2.kind == 'ret':
                        o2.kind = '_yield_ret'
            elif o.kind == 'raise':
                out.append(NdxSt('raise', a=o.a, line=line,
                                 blocks={b.start}))
            elif o.kind == 'reraise':
                out.append(NdxSt('raise', a=None, line=line,
                                 blocks={b.start}))
        # dedup: stesso statement ripetuto (multi-passata simbolica)
        seen = set()
        ded = []
        for s in out:
            key = (s.kind, id(s.a) if isinstance(s.a, NdxSV) else s.a,
                   id(s.b) if isinstance(s.b, NdxSV) else s.b,
                   id(s.c) if isinstance(s.c, NdxSV) else s.c)
            if key in seen:
                continue
            seen.add(key)
            ded.append(s)
        return ded

    # ------------------------------------------------------------ try/except
    def _find_handlers(self):
        """Catene handler: matcher (EXCEPTION_MATCH_BOOL) → clausole."""
        handlers = []
        for st, b in self.blocks.items():
            match_ops = [o for o in b.ops if o.kind == 'calc' and
                         o.a is not None and o.a.op == 'exc_match']
            branch_matches = [sym for _target, _kind, sym in b.conds
                              if isinstance(sym, NdxSV) and sym.op == 'exc_match']
            if not match_ops and not branch_matches:
                continue
            # clause: branch sul matcher
            br = self._cond_info(b)
            if br is None:
                continue
            sym, yes, no = br
            # tipo della clausola
            types = sym.a if sym is not None else None
            if types is None:
                types = self._exc_types_from_context(st)
            clause = {'block': st, 'types': types, 'body': yes,
                      'next': no, 'line': self._line_of(b)}
            handlers.append({'matcher': st, 'clauses': [clause],
                             'try_end': None})
        # raggruppa: clausole in catena (next di una clausola è il matcher
        # della successiva)
        merged = []
        used = set()
        for h in handlers:
            if id(h) in used:
                continue
            chain = list(h['clauses'])
            cur = h
            while True:
                nxt = chain[-1]['next']
                found = None
                for h2 in handlers:
                    if h2['matcher'] == nxt:
                        found = h2
                        break
                if found is not None:
                    used.add(id(found))
                    chain.extend(found['clauses'])
                    continue
                break
            # try_end: dal target del salto di fine body della prima clausola
            # (branch_end) — approssimato: il blocco dove converge il flusso
            # normale dopo l'handler
            merged.append({'matcher': h['matcher'], 'clauses': chain,
                           'try_end': self._handler_try_end(chain)})
        for h in merged:
            if all(c['types'] is None for c in h['clauses']):
                self._recover_exc_types(h)
        return merged

    def _recover_exc_types(self, h):
        """Clausa senza tipo: il test e' avvenuto su un valore spillato
        (o su un helper senza argomento costante).  Il nome dell'eccezione
        compare comunque come GLOBAL nei blocchi ERROR della regione
        handler (il publishing carica il tipo): un solo nome distinto
        nella regione e' l'identita' della clausola."""
        seen = set()
        work = [h['matcher']]
        region = []
        while work and len(seen) < 120:
            st = work.pop(0)
            if st in seen or st not in self.blocks:
                continue
            seen.add(st)
            b = self.blocks[st]
            if b.kind == 'error':
                region.append(b)
            for p in (getattr(b, 'preds', None) or []):
                if p not in seen:
                    work.append(p)
        # secondo test della catena: il tipo puo' essere caricato anche
        # nel flusso in avanti che parte DALLA CATENA backward (i rami
        # di test secondari si innestano sui blocchi error della catena)
        seen2 = set()
        work2 = list(seen)
        while work2 and len(seen2) < 200:
            st = work2.pop(0)
            if st in seen2 or st not in self.blocks:
                continue
            seen2.add(st)
            b = self.blocks[st]
            if b.kind == 'error' and st not in seen:
                region.append(b)
            for s in (getattr(b, 'succs', None) or []):
                if s not in seen2:
                    work2.append(s)
        names = set()

        def scan_sym(sym, d=0):
            if d > 6 or not isinstance(sym, NdxSV):
                return
            if sym.op == 'global' and isinstance(sym.a, str) and                     sym.a in _BUILTIN_EXCEPTION_NAMES:
                names.add(sym.a)
                return
            for f in ('a', 'b', 'c'):
                scan_sym(getattr(sym, f, None), d + 1)

        for b in region:
            for o in b.ops:
                scan_sym(getattr(o, 'a', None))
        if len(names) >= 1:
            # il primo nome per indirizzo di blocco: l'ordine del region
            # layout segue l'ordine delle clausole nel sorgente
            name = sorted(names)[0] if len(names) == 1 else                 sorted(names)[0]
            for c in h['clauses']:
                if c['types'] is None:
                    c['types'] = name

    def _region_stmts(self, start, chain, normal_reach, try_end,
                      max_blocks=80):
        """Raccogli gli statement Python dalla regione handler raggiungibile
        da start: blocchi normali con op Python, non nella catena, non nel
        flusso normale, fermati al try_end."""
        stmts = []
        seen = {start}
        work = [(0, start)]
        stop = {try_end} if try_end is not None else set()
        collected = set()
        while work:
            dist, x = work.pop(0)
            if x not in self.blocks:
                continue
            b = self.blocks[x]
            if x in stop or x in normal_reach:
                continue
            has_py = any(o.kind in ('store', 'store_sub', 'append', 'setadd', 'ret', 'raise') or (o.kind == 'calc' and isinstance(o.a, NdxSV) and o.a.op in ('call', 'kwcall', 'mcall')) for o in b.ops)
            # il blocco di PARTENZA e' il primo blocco handler: le
            # sue statement sono il corpo della clausola (handler a
            # blocco singolo altrimenti escono vuoti)
            if has_py and x not in chain and x not in collected:
                sub = self._block_stmts(b)
                if sub:
                    stmts.extend(sub)
                    collected.add(x)
            errors = {target for target, kind in b.edges if kind == 'error'}
            for s in b.succs:
                if s not in errors and s in self.blocks and s not in seen:
                    seen.add(s)
                    sb = self.blocks[s]
                    p = 0 if (sb.kind != 'error' and any(
                        o.kind in ('store', 'store_sub', 'append',
                                   'setadd', 'ret', 'raise') for o in sb.ops)) else 1
                    work.append((dist + 1, s))
            work.sort()
        return stmts

    def _exc_types_from_context(self, matcher_st, depth=14):
        """GCC inline-a l'iterazione della tuple di eccezioni: la tuple è
        caricata vicino al matcher. Cerca mov rip-relativi che risolvono a
        costanti tuple/type nel matcher e nei suoi predecessori (fino a
        depth livelli, escludendo i back-edge)."""
        seen_blocks = set()
        work = [matcher_st]
        for _d in range(depth + 1):
            nxt = []
            for st in work:
                if st in seen_blocks or st not in self.blocks:
                    continue
                seen_blocks.add(st)
                b = self.blocks[st]
                for ins in b.insns:
                    if ins.mnemonic in ('mov', 'movq') and 'rip' in ins.op_str:
                        t = rip_target(ins)
                        if t is not None and self.L.mca is not None:
                            val, _which = self.L.mca.const_for_slot(t)
                            if (isinstance(val, type) and issubclass(val, BaseException)) or (isinstance(val, tuple) and val and all(isinstance(item, type) and issubclass(item, BaseException) for item in val)):
                                return val
                for p in b.preds:
                    if p not in seen_blocks:
                        nxt.append(p)
            work = nxt
        return None

    def _handler_try_end(self, chain):
        """try_end = il primo blocco del FLUSSO NORMALE raggiunto dai body
        delle clausole attraverso la catena handler (il punto di rejoin)."""
        if not hasattr(self, '_normal_reach'):
            nr = {self.entry}
            q = [self.entry]
            while q:
                x = q.pop()
                for s2 in self.nsucc.get(x, []):
                    if s2 not in nr:
                        nr.add(s2)
                        q.append(s2)
            self._normal_reach = nr
        bodies = [c['body'] for c in chain if c['body'] is not None]
        if not bodies:
            return None
        best = None
        best_dist = None
        for bd in bodies:
            seen = {bd}
            work = [(0, bd)]
            while work and len(seen) < 200:
                dist, x = work.pop(0)
                if x not in self.blocks:
                    continue
                if x != bd and x in self._normal_reach:
                    if best_dist is None or dist < best_dist:
                        best = x
                        best_dist = dist
                    break
                for s in self.blocks[x].succs:
                    if s in self.blocks and s not in seen:
                        seen.add(s)
                        work.append((dist + 1, s))
        return best

    def _exc_types_from_context(self, matcher_st, depth=14):
        """GCC inline-a l'iterazione della tuple di eccezioni: la tuple è
        caricata vicino al matcher. Cerca mov rip-relativi che risolvono a
        costanti tuple/type nel matcher e nei suoi predecessori (fino a
        depth livelli, escludendo i back-edge)."""
        seen_blocks = set()
        work = [matcher_st]
        for _d in range(depth + 1):
            nxt = []
            for st in work:
                if st in seen_blocks or st not in self.blocks:
                    continue
                seen_blocks.add(st)
                b = self.blocks[st]
                for ins in b.insns:
                    if ins.mnemonic in ('mov', 'movq') and 'rip' in ins.op_str:
                        t = rip_target(ins)
                        if t is not None and self.L.mca is not None:
                            val, _which = self.L.mca.const_for_slot(t)
                            if (isinstance(val, type) and issubclass(val, BaseException)) or (isinstance(val, tuple) and val and all(isinstance(item, type) and issubclass(item, BaseException) for item in val)):
                                return val
                for p in b.preds:
                    if p not in seen_blocks:
                        nxt.append(p)
            work = nxt
        return None

    def _wrap_finally(self, stmts):
        """Join cloned normal/error cleanup only with publish + reraise proof.

        Call-site identity is ignored solely while matching the compiler's two
        cleanup copies. It remains intact in the emitted value graph.
        """
        def nodes(value):
            stack, seen = [value], set()
            while stack:
                v = stack.pop()
                if isinstance(v, NdxSV) and id(v) not in seen:
                    seen.add(id(v)); yield v
                    stack.extend((v.a, v.b, v.c))
                elif isinstance(v, (list, tuple)):
                    stack.extend(v)
        def expression(statement):
            return statement.b if statement.kind == 'assign' else statement.a
        publications = [(start, op) for start, block in self.blocks.items()
                        for op in block.ops if op.kind == 'exc_publish']
        for published, publication in publications:
            # The error cleanup's successful paths must all reach a rethrow.
            work, seen, graph, cold = [published], set(), {}, []
            valid, rethrows = True, set()
            while work:
                start = work.pop()
                if start in seen:
                    continue
                seen.add(start)
                block = self.blocks[start]
                relevant = [o for o in block.ops if start != published or o.va > publication.va]
                if any(o.kind == 'reraise' for o in relevant):
                    rethrows.add(start); graph[start] = []; continue
                if any(o.kind in ('raise', 'ret', 'yield', 'exc_publish') or
                       (o.kind == 'calc' and isinstance(o.a, NdxSV) and
                        o.a.op in ('exc_match', 'nativecall', 'apicall')) for o in relevant):
                    valid = False; break
                if any(k in ('cond_yes', 'cond_no') for _, k in block.edges):
                    valid = False; break
                cold.extend((start, o.a) for o in relevant if o.kind == 'calc')
                errors = {n for n, k in block.edges if k == 'error'}
                following = [n for n in block.succs if n in self.blocks and n not in errors]
                if not following:
                    valid = False; break
                graph[start] = following; work.extend(following)
            if not valid or not rethrows:
                continue
            # Fixed-point proves termination at the rethrow; cycles are rejected.
            good = set(rethrows)
            while True:
                added = {n for n, ss in graph.items() if ss and all(k in good for k in ss)} - good
                if not added:
                    break
                good.update(added)
            if published not in good:
                continue
            # The source-level roots consume attribute lookup / argument producers.
            nested = {id(n) for _, v in cold for child in (v.a, v.b, v.c)
                      for n in nodes(child)}
            roots = [v for _, v in sorted(cold, key=lambda pair: pair[1].n or pair[0])
                     if id(v) not in nested and v.op not in ('frame', 'excstate', 'imm')]
            if not roots:
                continue
            # Source operations whose failure reaches publication through runtime
            # bookkeeping define the protected interval.
            parents = {n: [] for n in self.blocks}
            for n, block in self.blocks.items():
                for target in block.succs:
                    if target in parents:
                        parents[target].append(n)
            pending, back, sources = list(parents[published]), {published}, set()
            while pending:
                n = pending.pop()
                if n in back:
                    continue
                back.add(n); block = self.blocks[n]
                if n in self.order:
                    if any(t in back and k == 'error' for t, k in block.edges):
                        sources.add(n)
                    continue
                if any(o.kind not in ('store',) for o in block.ops):
                    continue
                pending.extend(parents[n])
            indices = [i for i, st in enumerate(stmts) if st.blocks & sources]
            if not indices:
                continue
            begin = min(indices)
            matches = []
            for i in range(max(indices) + 1, len(stmts) - len(roots) + 1):
                chosen = stmts[i:i + len(roots)]
                if all(st.kind in ('assign', 'expr') and
                       _sv_eq(expression(st), root, ignore_call_sites=True) for st, root in zip(chosen, roots)):
                    matches.append(i)
            if len(matches) != 1:
                continue
            first = matches[0]; last = first + len(roots)
            protected = stmts[begin:first]
            cleanup = stmts[first:last]
            if not protected or any(st.kind not in ('assign', 'expr') for st in protected):
                continue
            # A return already evaluated before cleanup stays inside the try.
            if last < len(stmts) and stmts[last].kind == 'return' and any(
                    st.kind == 'assign' and _sv_eq(st.b, stmts[last].a) for st in protected):
                protected = protected + [stmts[last]]; last += 1
            wrapper = NdxSt('try', a=protected, b=[], c=cleanup,
                            blocks=set().union(*(st.blocks for st in protected + cleanup)))
            stmts[begin:last] = [wrapper]
        return stmts

    def _wrap_try(self, stmts):
        """Avvolgi le regioni con error-edge verso handler in try/except,
        al livello di annidamento PIÙ PROFONDO che contiene i blocchi
        sorgente (il try del sorgente può stare dentro un for/if)."""
        for h in self.handlers:
            src_blocks = self._handler_src_blocks(h)
            h['src_blocks'] = src_blocks
            if not src_blocks:
                continue
            cur = stmts
            guard = 0
            while guard < 16:
                guard += 1
                idxs = [i for i, s in enumerate(cur)
                        if s.blocks and (s.blocks & src_blocks)]
                if len(idxs) != 1:
                    break
                s = cur[idxs[0]]
                descended = False
                for attr in ('b', 'c'):
                    sub = getattr(s, attr, None)
                    if isinstance(sub, list) and sub and \
                            all(isinstance(x, NdxSt) for x in sub) and \
                            any(x.blocks and (x.blocks & src_blocks)
                                for x in sub):
                        cur = sub
                        descended = True
                        break
                if not descended:
                    break
            self._wrap_try_level(cur, h)
        return stmts

    def _handler_src_blocks(self, h):
        """Blocchi del flusso normale che commutano errori verso la catena
        dell'handler (i candidati corpo del try)."""
        def is_chain_block(b):
            for o in b.ops:
                if o.kind in ('store_sub', 'append', 'setadd', 'ret',
                              'raise', 'reraise'):
                    return False
                if o.kind == 'calc' and o.a is not None and \
                        o.a.op not in ('excstate', 'frame', 'none',
                                       'nativecall', 'apicall',
                                       'stopiter_value'):
                    return False
                if o.kind == 'store' and o.b is not None and \
                        o.b.op not in ('none', 'excstate', 'frame',
                                       'stopiter_value', 'nativecall',
                                       'apicall'):
                    return False
            return True

        # catena: BFS all'indietro dal matcher
        chain = {h['matcher']}
        work = [h['matcher']]
        while work:
            st = work.pop()
            b = self.blocks.get(st)
            if b is None:
                continue
            for p in b.preds:
                if p in chain or p not in self.blocks:
                    continue
                pb = self.blocks[p]
                if pb.kind == 'error' or is_chain_block(pb):
                    chain.add(p)
                    work.append(p)
        # body delle clausole: escludi dalla catena
        for c in h['clauses']:
            if c['body'] is None:
                continue
            bodyset = set()
            work2 = [c['body']]
            while work2 and len(bodyset) < 400:
                x = work2.pop()
                if x in bodyset or x not in self.blocks:
                    continue
                # non attraversare la catena handler: con il try dentro un
                # loop il rejoin rientra nel matcher e il walk ciclico
                # risucchia l'intera catena (chain = 0, mai un try)
                if x in chain and x != c['body']:
                    continue
                bodyset.add(x)
                for s in self.blocks[x].succs:
                    work2.append(s)
            chain -= bodyset
        h['chain'] = chain
        # sorgenti: blocchi normali che saltano nella catena
        src_blocks = set()
        for st, b in self.blocks.items():
            if st in chain or b.kind != 'normal':
                continue
            tgts = {t for t, _et in b.edges} | set(b.succs)
            if tgts & chain:
                src_blocks.add(st)
        return src_blocks

    def _restore_terminal_handler_returns(self, try_body, clauses, handler, suffix):
        """Restore returns whose normal/except arms share a native epilogue.

        A region is eligible only when each arm contributes one proven value,
        every phi predecessor belongs to an arm, and no source continuation
        lies between the try and the terminal return.  This keeps a finally or
        post-try computation outside this transformation.
        """
        if len(suffix) != 1 or suffix[0].kind != 'return':
            return False
        snapshots = getattr(self.L, 'native_return_phis', {})
        phis = [snapshots[block] for block in suffix[0].blocks if block in snapshots]
        if len(phis) != 1 or not clauses or len(clauses) != len(handler['clauses']):
            return False
        pairs = getattr(self.L, '_phi_inputs', {}).get(id(phis[0]), ())
        if not pairs or any(pred is None or not isinstance(value, NdxSV)
                            or value.op in ('imm', 'loc', 'nativecall', 'apicall',
                                            'frame', 'excstate', 'tstate')
                            for pred, value in pairs):
            return False
        arm_regions = [set(handler.get('src_blocks', ()))]
        for clause in handler['clauses']:
            region, pending = set(), [clause['body']]
            while pending:
                block = pending.pop()
                if block in region or block == handler.get('try_end') or block not in self.blocks:
                    continue
                region.add(block)
                pending.extend(self.blocks[block].succs)
            arm_regions.append(region)
        bodies = [try_body] + [clause[1] for clause in clauses]
        covered = set()
        proposals = []
        for body, region in zip(bodies, arm_regions):
            incoming = [(pred, value) for pred, value in pairs if pred in region]
            if not incoming or any(pred in covered for pred, _value in incoming):
                return False
            value = incoming[0][1]
            if any(not _sv_eq(value, other) for _pred, other in incoming):
                return False
            represented = set()
            for statement in body:
                NdxRenderer._stmt_walk(statement, lambda node: represented.add(sv_key(node))
                                      if isinstance(node, NdxSV) else None)
            for block in region:
                for operation in self.blocks[block].ops:
                    if operation.kind == 'calc' and isinstance(operation.a, NdxSV) and \
                            operation.a.op in ('call', 'kwcall', 'mcall', 'nativecall', 'apicall') and \
                            sv_key(operation.a) not in represented:
                        return False
            replacement = list(body)
            if replacement and replacement[-1].kind == 'assign' and \
                    _sv_eq(replacement[-1].b, value):
                replacement[-1] = NdxSt('return', a=value)
            elif replacement and replacement[-1].kind == 'expr' and \
                    _sv_eq(replacement[-1].a, value):
                replacement[-1] = NdxSt('return', a=value)
            elif value.op in ('const', 'par', 'var', 'none'):
                replacement.append(NdxSt('return', a=value))
            else:
                return False
            proposals.append(replacement)
            covered.update(pred for pred, _value in incoming)
        if covered != {pred for pred, _value in pairs}:
            return False
        for body, replacement in zip(bodies, proposals):
            body[:] = replacement
        return True

    def _wrap_try_level(self, stmts, h):
        src_blocks = h.get('src_blocks') or set()
        source_values = [operation.a for address in src_blocks
                         for operation in self.blocks[address].ops
                         if operation.kind == 'calc' and isinstance(operation.a, NdxSV)]
        idxs = [i for i, s in enumerate(stmts)
                if (s.blocks and (s.blocks & src_blocks)) or
                (s.kind == 'assign' and isinstance(s.b, NdxSV) and
                 any(_sv_eq(s.b, value) for value in source_values))]
        if not idxs:
            return stmts
        lo, hi = min(idxs), max(idxs)
        try_body = stmts[lo:hi + 1]
        # nomi gia' vincolati nell'albero: un ``as`` non puo' riusarli
        bound_names = set()

        def _collect_bound(st, d=0):
            if d > 12 or st is None or not hasattr(st, 'kind'):
                return
            if st.kind in ('assign', 'for') and isinstance(st.a, str):
                bound_names.add(st.a)
            for f in ('a', 'b', 'c', 'd', 'e'):
                v = getattr(st, f, None)
                if isinstance(v, list):
                    for g in v:
                        _collect_bound(g, d + 1)
                elif v is not None:
                    _collect_bound(v, d + 1)

        # i binding DENTRO la regione try non contano: i temporanei della
        # regione sono candidati legittimi per il nome ``as``
        for st0 in list(stmts[:lo]) + list(stmts[hi + 1:]):
            _collect_bound(st0)
        # il fetch dell'eccezione corrente e' nel matcher della PRIMA
        # clausola e serve a tutta la catena dei test
        chain_fetch = None
        for c in h['clauses']:
            mb = self.blocks.get(c.get('block'))
            if mb is None:
                continue
            for o in getattr(mb, 'ops', []):
                sv = getattr(o, 'a', None)
                if (getattr(o, 'kind', None) == 'calc' and
                        isinstance(sv, NdxSV) and
                        sv.op == 'nativecall' and
                        str(sv.a).startswith('sub_') and
                        isinstance(sv.b, list) and
                        len([x for x in sv.b if isinstance(x, NdxSV) and
                             x.op != 'tstate']) == 1 and
                        any(isinstance(x, NdxSV) and x.op == 'stackaddr'
                            for x in sv.b)):
                    chain_fetch = sv
                    break
            if chain_fetch is not None:
                break
        clauses = []
        for c in h['clauses']:
            if c['body'] is None:
                continue
            bstop = {h['try_end']} if h['try_end'] else set()
            # salta i blocchi di pubblicazione/traceback (error-kind, nessuna
            # op Python) fino al primo blocco statement
            # BFS attraverso i blocchi di pubblicazione/traceback
            # (error-kind) fino al primo blocco statement del body
            # corpo della clausola: raccogli gli statement Python dai
            # blocchi della regione handler raggiungibili dal body entry,
            # escludendo la catena (keeper/traceback/publish) e i blocchi
            # del flusso normale (punti di rejoin)
            if not hasattr(self, '_normal_reach'):
                nr = {self.entry}
                q = [self.entry]
                while q:
                    x = q.pop()
                    for s2 in self.nsucc.get(x, []):
                        if s2 not in nr:
                            nr.add(s2)
                            q.append(s2)
                self._normal_reach = nr
            chain = h.get('chain') or set()
            body = self._region_stmts(c['body'], chain,
                                      self._normal_reach, h.get('try_end'))
            body, asname = self._bind_exc_value(
                body, self.blocks.get(c['block']), chain_fetch,
                bound_names)
            # dedup: gli statement che ricompaiono IDENTICI (stessa
            # struttura completa) nel flusso post-try (il finally e i
            # rejoin condivisi di Nuitka) sono gia' resi fuori dal try.
            post_keys = {self._stmt_sv_key(s2) for s2 in stmts[hi + 1:]}
            body = [s2 for s2 in body
                    if self._stmt_sv_key(s2) not in post_keys]
            clauses.append((c['types'], body, c['line'], asname))
        # An assignment may be performed in the native rejoin block although
        # its producer belongs to the try.  Recover the handler's value at the
        # very same machine location, using only its incoming CFG states.
        join = self.blocks.get(h.get('try_end'))
        if join is not None:
            for normal in try_body:
                if normal.kind != 'assign' or not isinstance(normal.a, str) or \
                        not isinstance(normal.c, tuple) or normal.c[0] != 'reg':
                    continue
                register = normal.c[1]
                normal_states = [getattr(self.L, '_final_out', {}).get(pred, {}).get('regs', {}).get(register)
                                 for pred in join.preds if self.blocks[pred].kind != 'error']
                if not normal_states or not all(_sv_eq(value, normal.b) for value in normal_states):
                    continue
                for clause, native in zip(clauses, h['clauses']):
                    if clause[1]:
                        continue
                    pending = [native['body']]
                    region = set()
                    while pending:
                        address = pending.pop()
                        if address == join.start or address in region or address not in self.blocks:
                            continue
                        region.add(address)
                        pending.extend(self.blocks[address].succs)
                    incoming = [getattr(self.L, '_final_out', {}).get(pred, {}).get('regs', {}).get(register)
                                for pred in join.preds if pred in region]
                    if incoming and all(isinstance(value, NdxSV) and
                                        value.op in ('const', 'none', 'par', 'var') and
                                        _sv_eq(value, incoming[0]) for value in incoming):
                        clause[1].append(NdxSt('assign', normal.a, incoming[0], normal.c,
                                               blocks=region))
                        # The post-try expression consumes the merged local,
                        # never a second execution of its successful producer.
                        def bind(value, memo):
                            if isinstance(value, NdxSV):
                                if _sv_eq(value, normal.b):
                                    return ndx_k('var', normal.a)
                                if id(value) in memo:
                                    return memo[id(value)]
                                clone = ndx_k(value.op, n=value.n)
                                memo[id(value)] = clone
                                clone.a = bind(value.a, memo)
                                clone.b = bind(value.b, memo)
                                clone.c = bind(value.c, memo)
                                return clone
                            if isinstance(value, list):
                                return [bind(item, memo) for item in value]
                            return value
                        memo = {}
                        for following in stmts[hi + 1:]:
                            if following.kind == 'assign':
                                original_rhs = following.b
                                following.b = bind(original_rhs, memo)
                                if following.a == normal.a:
                                    break
                            elif following.kind in ('return', 'expr'):
                                following.a = bind(following.a, memo)
                            else:
                                break
        terminal_return = self._restore_terminal_handler_returns(
            try_body, clauses, h, stmts[hi + 1:])
        tr = NdxSt('try', a=try_body, b=clauses,
                line=try_body[0].line if try_body else None, blocks=set())
        stmts[lo:hi + 1 + int(terminal_return)] = [tr]
        return stmts

    def _stmt_sv_key(self, st):
        """Chiave strutturale COMPLETA di uno statement (kind + chiavi dei
        simboli nei campi): identifica lo statement stesso, non i suoi
        operandi singoli."""
        if st is None or not hasattr(st, 'kind'):
            return None

        def kof(v):
            if isinstance(v, NdxSV):
                try:
                    return sv_key(v)
                except Exception:
                    return id(v)
            if isinstance(v, list):
                return tuple(kof(g) for g in v[:4])
            if v is None or isinstance(v, (str, int, float)):
                return v
            return str(type(v))

        return (st.kind, kof(getattr(st, 'a', None)),
                kof(getattr(st, 'b', None)), kof(getattr(st, 'c', None)))

    def _bind_exc_value(self, body, matcher_block=None,
                        chain_fetch=None, bound_names=frozenset()):
        """``except Tipo as exc:`` — l'handler recupera l'eccezione con un
        helper (tstate, stackaddr) e la conserva in una locazione.  Collega
        il valore recuperato ai ``getattr`` rimasti orfani (``exc.__name__``
        arriva nel lifting con oggetto None) e restituisce il nome del
        binding (se e' un varname reale) per il rendering ``as NAME``."""
        fetch = None
        asname = None
        L = getattr(self, 'L', None)
        _vn = (getattr(L, 'varnames', None) or
               getattr(self, 'varnames', None) or ())
        _ac = (getattr(L, 'argcount', None) if L is not None else None)
        if _ac is None:
            _ac = getattr(self, 'argcount', 0) or 0
        varnames = set(v for v in _vn if isinstance(v, str))

        def _is_exc_fetch(sv):
            return (isinstance(sv, NdxSV) and sv.op == 'nativecall' and
                    str(sv.a).startswith('sub_') and
                    isinstance(sv.b, list) and
                    len([x for x in sv.b if isinstance(x, NdxSV) and
                         x.op != 'tstate']) == 1 and
                    any(isinstance(x, NdxSV) and x.op == 'stackaddr'
                        for x in sv.b))

        # il fetch vive spesso nel blocco MATCHER (prima del test): lo
        # store di quel valore e' il binding ``as NAME`` della clausola
        mb_stmts = []
        if matcher_block is not None:
            try:
                mb_stmts = self._block_stmts(matcher_block) or []
            except Exception:
                mb_stmts = []
        for s in list(mb_stmts) + list(body):
            if getattr(s, 'kind', None) == 'store' and                     _is_exc_fetch(getattr(s, 'b', None)):
                fetch = s.b
                if isinstance(getattr(s, 'a', None), str) and                         s.a in varnames:
                    asname = s.a
        if fetch is None and chain_fetch is not None:
            fetch = chain_fetch
        if fetch is None and matcher_block is not None:
            # il fetch e' un CALC nel matcher (nessuno store): il valore
            # viaggia in registro.  Il nome ``as`` e' il primo varname
            # libero del pool (co_varnames ordina come il sorgente).
            for o in getattr(matcher_block, 'ops', []):
                sv = getattr(o, 'a', None)
                if o.kind == 'calc' and _is_exc_fetch(sv):
                    fetch = sv
                    break
        _uses_exc = False

        def _scan_orphan(st, d=0):
            nonlocal _uses_exc
            if d > 8 or st is None or not hasattr(st, 'kind'):
                return
            for f in ('b', 'c'):
                _scan_sym(getattr(st, f), d)

        def _scan_sym(sym, d):
            nonlocal _uses_exc
            if d > 8 or not isinstance(sym, NdxSV):
                return
            if sym.op == 'getattr' and sym.a is None:
                _uses_exc = True
            for f in ('a', 'b', 'c'):
                _scan_sym(getattr(sym, f, None), d + 1)

        for s in body:
            _scan_orphan(s)
        if fetch is not None and not asname and _uses_exc:
            used = set()
            for s in body:
                if isinstance(getattr(s, 'a', None), str):
                    used.add(s.a)
            taken = getattr(self, '_used_exc_names', None)
            if taken is None:
                taken = self._used_exc_names = set()
            for cand in list(_vn)[_ac:]:
                if (isinstance(cand, str) and cand.isidentifier() and
                        cand not in used and cand not in taken and
                        cand not in bound_names):
                    asname = cand
                    break
        if fetch is not None and asname and _uses_exc:
            taken = getattr(self, '_used_exc_names', None)
            if taken is None:
                taken = self._used_exc_names = set()
            taken.add(asname)
        for s in body:
            if getattr(s, 'kind', None) != 'assign' or                     not isinstance(getattr(s, 'b', None), NdxSV):
                continue
            sv = s.b
            if sv.op == 'nativecall' and str(sv.a).startswith('sub_') and                     isinstance(sv.b, list):
                rel = [x for x in sv.b
                       if isinstance(x, NdxSV) and x.op != 'tstate']
                if len(rel) == 1 and rel[0].op == 'stackaddr':
                    fetch = sv
                    if isinstance(s.a, str) and s.a in varnames:
                        asname = s.a
                    s.kind = 'dead'
        if fetch is None:
            return body, None
        exc_map = getattr(self, '_exc_fetch_names', None)
        if exc_map is None:
            exc_map = self._exc_fetch_names = {}
        if asname:
            exc_map[id(fetch)] = asname

        def link(st, depth=0):
            if depth > 8 or st is None or not hasattr(st, 'kind'):
                return
            for f in ('a', 'b', 'c'):
                v = getattr(st, f, None)
                if isinstance(v, NdxSV):
                    _link_sym(v, depth)
                elif isinstance(v, list):
                    for g in v:
                        if isinstance(g, NdxSV):
                            _link_sym(g, depth)

        def _link_sym(sym, depth):
            seen = getattr(link, '_seen', None)
            if seen is None:
                seen = link._seen = set()
            if id(sym) in seen:
                return
            seen.add(id(sym))
            if sym.op == 'getattr' and sym.a is None:
                sym.a = fetch
                return
            for f in ('a', 'b', 'c'):
                v = getattr(sym, f, None)
                if isinstance(v, NdxSV):
                    _link_sym(v, depth + 1)
                elif isinstance(v, list):
                    for g in v:
                        if isinstance(g, NdxSV):
                            _link_sym(g, depth + 1)

        for s in body:
            link(s)
        return body, asname


def use_args_only(sym, consumed):
    """Marca gli argomenti di sym come consumati (non sym stesso)."""
    for attr in ('a', 'b', 'c'):
        v = getattr(sym, attr, None)
        if isinstance(v, NdxSV):
            consumed.add(id(v))
            use_args_only(v, consumed)
        elif isinstance(v, list):
            for x in v:
                if isinstance(x, NdxSV):
                    consumed.add(id(x))
                    use_args_only(x, consumed)



# ==========================================================================
# === NDX MODULE: ndx_render.py
# ==========================================================================


import re



OP_TEXT = {
    '+': '+', '-': '-', '*': '*', '/': '/', '//': '//', '%': '%',
    '**': '**', '<<': '<<', '>>': '>>', '&': '&', '|': '|', '^': '^',
}

CMP_TEXT = {'eq': '==', 'ne': '!=', 'lt': '<', 'le': '<=',
            'gt': '>', 'ge': '>=', 'is': 'is', 'is_not': 'is not'}

# negazione logica degli operatori di confronto Python
_CMP_NEGATE = {'eq': 'ne', 'ne': 'eq', 'lt': 'ge', 'ge': 'lt',
               'le': 'gt', 'gt': 'le', 'is': 'is_not', 'is_not': 'is'}

_SINGLETON_MISS = object()   # sentinel: campo IAT non singleton

_CLASS_BASE_MACHINERY_MARKERS = ('via_PyUnicode_FromString', '<metaclass>',
                                 '_tstate(', '_stackaddr(', '_type_of(',
                                 'CALL_FUNCTION(', '__prepare__',
                                 '_PyObject_GC_Malloc(', '_gslot(')


def _heal_class_bases(bases, class_name=None):
    """Riduce le basi machinery di Nuitka alle classi reali del sorgente.

    La create-class porta il metaclass plumbing (lookup del nome,
    ``__prepare__``, ``_type_of``) come basi spurie; la tupla delle basi
    VERE vive dentro una di esse come ``(Base,)``. Una base con marker
    machinery viene scartata, a meno che contenga una tupla di soli
    identifier classe-like: quei nomi SONO le basi del sorgente."""
    out = []
    for b in bases:
        if not any(m in b for m in _CLASS_BASE_MACHINERY_MARKERS):
            out.append(b)
            continue
        for m in re.finditer(
                r'\(\s*([A-Z]\w*(?:\s*,\s*[A-Z]\w*)*)\s*,?\s*\)', b):
            for nm in m.group(1).split(','):
                nm = nm.strip()
                if nm and nm != class_name and nm not in out:
                    out.append(nm)
    return out

BUILTIN_RENAME = {
    'str1': 'str', 'int1': 'int', 'int2': 'int', 'float1': 'float',
    'bool1': 'bool', 'list1': 'list', 'tuple1': 'tuple', 'set1': 'set',
    'dict': 'dict', 'range1': 'range', 'range2': 'range', 'range3': 'range',
    'iter2': 'iter', 'next1': 'next', 'next2': 'next', 'type1': 'type',
    'type3': 'type', 'repr': 'repr', 'len': 'len', 'sum1': 'sum', 'sum2': 'sum',
}


def _const_repr(v, quote_str=True):
    if isinstance(v, (_NuitkaBuiltinName, _NuitkaExceptionName)):
        return _ident(str(v))
    if isinstance(v, str):
        if quote_str:
            return repr(v)
        return v
    if isinstance(v, tuple):
        # V100: marker strutturali del blob — mai tuple utente.
        # ('range', a, b, c) → range(a, b, c); ('slice', a, b, c) →
        # slice(a, b, c) in posizione valore (nel subscript la sintassi
        # x[a:b] e' gestita dal renderer 'sub').
        if len(v) == 4 and v[0] in ('range', 'slice') and \
                isinstance(v[0], str):
            args = ', '.join('None' if x is None else _const_repr(x)
                             for x in v[1:])
            if v[0] == 'range':
                return f'range({args})'
            return f'slice({args})'
        items = ', '.join(_const_repr(x) for x in v)
        if len(v) == 1:
            items += ','
        return '(' + items + ')'
    if isinstance(v, list):
        return '[' + ', '.join(_const_repr(x) for x in v) + ']'
    if isinstance(v, dict):
        # V100: code-object del pool (payload MAKE_FUNCTION di genexpr/
        # lambda non sollevate): mai un dict utente — marker leggibile.
        if v.get('_type') == 'CodeObject':
            _nm = v.get('name') or 'code'
            return f'<code {_const_repr(str(_nm), quote_str=False)}>'
        return '{' + ', '.join(
            f'{_const_repr(k)}: {_const_repr(val)}'
            for k, val in v.items()) + '}'
    if isinstance(v, set):
        return '{' + ', '.join(_const_repr(x) for x in v) + '}'
    if isinstance(v, bool):
        return 'True' if v else 'False'
    if v is None:
        return 'None'
    if isinstance(v, float):
        return repr(v)
    return repr(v)


def _ident(nm):
    """Nome → identificatore Python valido."""
    s = re.sub(r'[^0-9a-zA-Z_]', '_', str(nm))
    if not s or s[0].isdigit():
        s = '_' + s
    return s[:80]


def _exc_types_repr(types):
    if types is None:
        return 'Exception'
    if isinstance(types, tuple):
        return '(' + ', '.join(t.__name__ if isinstance(t, type) else
                               _const_repr(t, False) for t in types) + ')'
    if isinstance(types, type):
        return types.__name__
    if isinstance(types, str):
        return types
    return repr(types)


class NdxRenderer:
    def __init__(self, structurer, varnames=None, argcount=0):
        self.S = structurer
        self.varnames = varnames or []
        self.argcount = argcount
        # comprehension fold: container allocation key -> source name
        self.comp_names = {}
        self._comp_seq = 0
        # phi branch provenance -> injected arm name
        self._phi_names = {}

    _ATOM_RX = re.compile(
        r"[A-Za-z_]\w*(?:\.\w+|\([^()]*\)|\[[^\[\]]*\])*"
        r"(?:\.\w+|\([^()]*\)|\[[^\[\]]*\])*")

    def _atomize(self, text):
        """Parenthesise a rendered expression used in owner/callable position.

        Call/attribute chains must be syntactic atoms: a callable that
        renders to a comparison or arithmetic expression would otherwise
        emit invalid Python (``a == 200(x)``).  Simple names, attribute
        chains and balanced call/subscript tails are already atoms.
        """
        if not text:
            return text
        if self._ATOM_RX.fullmatch(text):
            return text
        return f'({text})'

    def _args_str(self, args, depth=0):
        parts = []
        if isinstance(args, list):
            for a in args:
                if isinstance(a, list):
                    # lista annidata (campo lista di un SV): rendi gli
                    # elementi, MAI il repr dell'oggetto
                    parts.append(self._args_str(a, depth))
                elif isinstance(a, NdxSV):
                    # V100: transport ABI (tstate/stackaddr) mai visibili
                    # come argomenti sorgente; il LEA del payload di una
                    # tupla costante è un vettore argomenti vectorcall.
                    if a.op in ('tstate', 'stackaddr', 'gslot'):
                        continue
                    _sp = self._spread_const_vector(a)
                    if _sp:
                        parts.extend(
                            self.expr(v, depth + 1) for v in _sp)
                        continue
                    parts.append(self.expr(a, depth + 1) or 'None')
                elif a is not None:
                    parts.append(_const_repr(a))
        elif args is not None:
            e = self.expr(args, depth + 1) if isinstance(args, NdxSV) else str(args)
            parts.append(e or 'None')
        return ', '.join(parts)

    def _spread_const_vector(self, node):
        """V100: un nodo ``const_array`` (LEA/add del payload di una tupla
        costante provata) in posizione argomento è il vettore argomenti
        di una vectorcall: ``f(_const_array((a, b), 0))`` è ``f(a, b)``.
        Il caso tupla-singolo-argomento del sorgente passerebbe invece il
        puntatore PyObject (nodo ``const``), non l'indirizzo del payload.
        Ritorna la lista dei valori costanti o None."""
        if not isinstance(node, NdxSV) or node.op != 'const_array':
            return None
        vals = getattr(node, 'a', None)
        if not isinstance(vals, (tuple, list)):
            return None
        start = getattr(node, 'b', 0)
        try:
            start = int(start or 0)
        except (TypeError, ValueError):
            start = 0
        out = [ndx_k('const', v) for v in vals[start:]
               if v is not None]
        return out or None

    # ------------------------------------------------------------ expr
    def _name_or_inline(self, name):
        ti = getattr(self.S, 'temp_inline', {})
        if name in ti:
            # guard anti-ricorsione: un inline che si auto-referenza
            # (`a = f(a)`) o una catena ciclica ritorna il nome.
            # L'inline è anche limitato in profondità: espressioni
            # combinate attraverso più phi possono altrimenti crescere
            # esponenzialmente annidando la stessa chiamata.
            busy = getattr(self, '_inlining_names', None)
            if busy is None:
                busy = self._inlining_names = set()
            if name in busy or len(busy) >= 64:
                return name
            busy.add(name)
            try:
                e = self.expr(ti[name], depth=1)
            finally:
                busy.discard(name)
            if e is not None:
                return e
        return name

    def _render_fstring(self, parts, depth):
        chunks = []

        def _field(text):
            # An f-string delimited with single quotes cannot contain a
            # single quote inside a replacement field.  Re-represent plain
            # string constants with the other quote; every other
            # expression keeps its exact spelling.
            if "'" in text and '"' not in text:
                return text.replace("'", '"')
            return text

        for part in parts or []:
            if part is None:
                return None
            if part.op == 'const' and isinstance(part.a, str):
                literal = part.a.replace('\\', '\\\\')
                literal = literal.replace('{', '{{').replace('}', '}}')
                # the f-string is a single source line: raw newlines and
                # tabs in the literal part must be escaped
                literal = literal.replace('\n', '\\n').replace('\r', '\\r')
                literal = literal.replace('\t', '\\t')
                literal = literal.replace("'", "\\'")
                chunks.append(literal)
                continue
            if part.op == 'format':
                value = self.expr(part.a, depth + 1)
                if not value:
                    return None
                spec = ''
                if part.b is not None:
                    if part.b.op != 'const' or not isinstance(part.b.a, str):
                        return None
                    spec = part.b.a
                chunks.append('{' + _field(value) +
                              (':' + spec if spec else '') + '}')
                continue
            value = self.expr(part, depth + 1)
            if not value:
                return None
            chunks.append('{' + _field(value) + '}')
        text = "f'" + ''.join(chunks) + "'"
        try:
            # Deeply nested recoveries can produce fields that do not
            # re-parse (quote conflicts with nested f-strings, unbalanced
            # delimiters).  Verify the literal and fall back to the plain
            # join form, which renders the same parts as ordinary
            # expressions and is always valid syntax.
            compile(text, '<fstring>', 'eval')
        except SyntaxError:
            return None
        return text

    def expr(self, sym, depth=0, assign_rhs=None, top_assign=False):
        """V100: guard anti-ciclo/anti-profondità del rendering.

        Il value-numbering e i phi possono rendere ciclico il grafo SV
        (un nodo che contiene, attraverso loc/phi, un proprio antenato):
        senza guard la ricorsione di rendering esplode e il RecursionError
        — ingoiato da lift_body — costa l'intero corpo funzione (``pass``).
        Un nodo già in corso di rendering rende il suo nome noto (o None);
        la profondità è comunque limitata per i DAG patologici."""
        if sym is None:
            return None
        if not isinstance(sym, NdxSV):
            return self._expr_body(sym, depth, assign_rhs, top_assign)
        if depth > 64:
            return self._unresolved_expr(sym, 'expression_depth')
        _ep = getattr(self, '_expr_path', None)
        if _ep is None:
            _ep = self._expr_path = set()
        marker = id(sym)
        if marker in _ep:
            _nm = getattr(self.S, 'sym_names', {}).get(marker)
            return _nm if isinstance(_nm, str) else self._unresolved_expr(sym, 'cyclic_expression')
        _ep.add(marker)
        try:
            return self._expr_body(sym, depth, assign_rhs, top_assign)
        finally:
            _ep.discard(marker)

    def _unresolved_expr(self, sym, reason):
        site = getattr(sym, 'n', None)
        lifter = getattr(self.S, 'L', None)
        profile = getattr(getattr(lifter, 'img', None), '_ndx_binary_abi', None)
        if profile is not None:
            profile.unknown(site, reason)
        return '_ndx_unresolved_value(' + repr(reason) + ', ' + repr(site) + ')'

    def _render_lambda_inline(self, qualname, values, depth):
        """Lift e render del corpo di una lambda inline dal func_new."""
        if depth > 3:
            return None
        L = getattr(getattr(self, 'S', None), 'L', None)
        if L is None:
            return None
        mca = getattr(L, 'mca', None)
        img = getattr(L, 'img', None)
        res = getattr(L, 'res', None)
        py_ver = getattr(L, 'py_version', None)
        if mca is None or img is None or res is None:
            return None
        code_slot = None
        for v in (values or []):
            if isinstance(v, NdxSV) and v.op == 'gslot':
                code_slot = v.a
                break
        if code_slot is None:
            return None
        fn_entry = None
        for fn in mca.functions:
            if fn.get('code_obj_slot') == code_slot:
                fn_entry = fn
                break
        lam_co = None
        emitter_cos = getattr(type(L), '_emitter_cos', [])
        for c in emitter_cos:
            co_name = getattr(c, 'name', None)
            if co_name and '<lambda>' in str(co_name):
                lam_co = c
                break
        if fn_entry is None:
            # fallback: usa la prima lambda entry disponibile
            for fn in mca.functions:
                if '<lambda>' in str(fn.get('qualname', '')):
                    fn_entry = fn
                    break
        if fn_entry is None or lam_co is None:
            return None
        params = []
        co_vn = getattr(lam_co, 'varnames', None)
        if co_vn:
            params = list(co_vn[:1])
        if not params:
            params = ['_arg']
        try:
            lam_bl = BodyLifter2(img, res, mca, lam_co,
                                 fn_entry['impl_va'],
                                 py_version=py_ver).lift()
            lam_st = Structurer(lam_bl)
            lam_stmts = lam_st.structure()
            lam_r = NdxRenderer(lam_st, lam_bl.varnames,
                                lam_bl.argcount)
            lam_rend = lam_r.render(lam_stmts, depth + 1)
            import sys as _sys
            print('LAMBDA RENDER LINES:', lam_rend, file=_sys.stderr)
            # raccogli gli assegnamenti dal corpo lambda per
            # sostituire i riferimenti ai temp nel return
            assigns = {}
            ret_expr = None
            for line in lam_rend:
                stripped = line.strip()
                if stripped.startswith('return '):
                    ret_expr = stripped[7:]
                    break
                if ' = ' in stripped and not stripped.startswith('#'):
                    var, _, val = stripped.partition(' = ')
                    assigns[var.strip()] = val.strip()
            if ret_expr is None:
                return None
            # sostituisci i temp con le espressioni assegnate
            for temp, val in assigns.items():
                ret_expr = ret_expr.replace(temp, val)
            param_str = ', '.join(params)
            return f'lambda {param_str}: {ret_expr}'
        except Exception:
            return None


    def _expr_body(self, sym, depth=0, assign_rhs=None, top_assign=False):
        if isinstance(sym, NdxSV) and sym.op == 'unknown':
            return self._unresolved_expr(sym, str(sym.a or 'unrecovered_operand'))
        if sym is None:
            return None
        if assign_rhs is None:
            assign_rhs = getattr(self, '_active_assign_rhs', None)
        active_assign_name = getattr(self, '_active_assign_name', None)
        # Il tag PyLong (+0x10, contatore cifre compact) è internals C:
        # il sorgente usa l'OGGETTO che lo porta, mai il tag.
        if sym.op == 'long_tag':
            return self.expr(sym.a, depth + 1)
        # phi di merge con provenienza per-ramo iniettata nei rami: il nome
        # della variabile è quello dell'assegnazione che il phi materializza.
        if sym.op == 'loc':
            nm = self._phi_names.get(id(sym))
            if nm:
                return nm
            # Cluster numerico inlineato: il merge riunisce i path di
            # variante del calcolo (segno/digit) che producono TUTTI lo
            # stesso valore Python — stessi operandi, operatore variante.
            # Un phi i cui input sono tutti binop con lo stesso operando
            # sinistro rappresenta quel UNO valore: si renderizza la
            # variante di sottrazione (k - 1), non un temporaneo aliasato.
            L = getattr(self.S, 'L', None)
            prov = getattr(L, '_phi_inputs', None) if L is not None else None
            inputs = (prov or {}).get(id(sym))
            if inputs:
                binops = [v for p, v in inputs
                          if isinstance(v, NdxSV) and v.op == 'binop' and
                          isinstance(v.b, NdxSV)]
                if binops and len(binops) == len(inputs) and all(
                        _sv_eq(v.b, binops[0].b) for v in binops):
                    subs = [v for v in binops if v.a == '-']
                    pick = subs[0] if subs else binops[0]
                    return self.expr(pick, depth + 1)
                # super() diviso in più bracci dal compilatore (guard su
                # self / fast-path): tutti i phi-input sono call del
                # globale ``super`` → il valore merge è ``super()``.
                supers = [v for p, v in inputs
                          if isinstance(v, NdxSV) and v.op == 'call' and
                          isinstance(v.a, NdxSV) and v.a.op == 'global' and
                          v.a.a == 'super']
                if supers and len(supers) == len(inputs):
                    return 'super()'
        # phi di merge con provenienza per-ramo iniettata nei rami: il nome
        # della variabile è quello dell'assegnazione che il phi materializza.
        if sym.op == 'loc':
            nm = self._phi_names.get(id(sym))
            if nm:
                return nm
        # globali del modulo e none: nome diretto (prima del value numbering)
        if sym.op == 'global':
            return str(sym.a)
        if sym.op == 'imm':
            return str(sym.a)
        # value numbering: rendi il nome della variabile — MAI per il RHS
        # top-level di un assegnamento (lì va resa l'espressione), tranne
        # quando è una copia variabile→variabile (loc-ref). Un nome NON
        # vivo (la sua assegnazione non è tra gli statement correnti,
        # es. embedded dal lowering) è un FANTASMA: rendere il nome
        # spezzerebbe l'espressione già fusa → si espande il simbolo.
        # Durante il fold delle comprehension i simboli COMPUTATI si
        # inlineano: la SSA aliasa i risultati intermedi (es. il binop di
        # guardia ``next(iter) % 2``) allo slot del loop var per riuso di
        # registro — risolverli al nome perderebbe l'operazione.
        _fold_inline = getattr(self, '_fold_inline', False) and sym.op in (
            'binop', 'cmp', 'bool', 'not', 'unary', 'ifexp')
        if (not top_assign or sym.op == 'loc') and not _fold_inline:
            _ln = getattr(self, '_live_names', None)
            _dn = getattr(self, '_defined_names', None)
            sn = getattr(self.S, 'sym_names', {})
            _nm = sn.get(id(sym))
            if _nm is not None and _nm != active_assign_name and \
                    (_ln is None or _nm in _ln) and \
                    (_dn is None or _nm in _dn):
                return self._name_or_inline(_nm)
            # value numbering strutturale (stessa espressione = stessa var)
            sk = getattr(self.S, 'sym_keys', {})
            if sk:
                _nm2 = sk.get(sv_key(sym))
                if _nm2 is not None and _nm2 != active_assign_name and \
                        (_ln is None or _nm2 in _ln) and \
                        (_dn is None or _nm2 in _dn):
                    return self._name_or_inline(_nm2)
            if not top_assign:
                vos = getattr(self.S.L, 'var_of_sym', {})
                loc = vos.get(id(sym))
                if loc is not None and loc != assign_rhs and \
                        loc in self.S.var_names and \
                        self.S.loc_cur_sym.get(loc) == id(sym):
                    _nm3 = self.S.var_names[loc]
                    if _nm3 != active_assign_name and \
                            (_ln is None or _nm3 in _ln) and \
                            (_dn is None or _nm3 in _dn):
                        return self._name_or_inline(_nm3)
        op = sym.op
        if op == 'const':
            return _const_repr(sym.a)
        if op == 'api_symbol':
            aliases = {'PyProperty_Type': 'property', 'PyType_Type': 'type',
                       'PyList_Type': 'list', 'PyTuple_Type': 'tuple',
                       'PyDict_Type': 'dict', 'PySet_Type': 'set',
                       'PyUnicode_Type': 'str', 'PyLong_Type': 'int',
                       'PyFloat_Type': 'float', 'PyBool_Type': 'bool',
                       'PyBytes_Type': 'bytes'}
            return aliases.get(sym.a, _ident(sym.a))
        if op == 'par':
            i = sym.a
            if i is not None and i < len(self.varnames):
                return self.varnames[i]
            return f'_p{sym.a}'
        if op == 'var':
            nm = sym.a
            _ti_v = getattr(self.S, 'temp_inline', None) or {}
            if isinstance(nm, str) and nm in _ti_v:
                return self._name_or_inline(nm)
            return str(nm)
        if op == 'cellref':
            nm = getattr(self.S, 'bl', None)
            names = getattr(self, '_gen_names', None)
            if names and sym.a in names:
                return names[sym.a]
            return f'_cell{sym.a}'
        if op == 'loc':
            # riferimento a variabile (phi): risolvi il nome
            try:
                nm = self.S.name_of_loc(sym.a)
                return self._name_or_inline(nm)
            except Exception:
                return '_tmp'
        if op == 'isnull':
            return f'{self.expr(sym.a, depth + 1)} is None'
        if op == 'none':
            return 'None'
        if op == 'mcall':
            obj = self.expr(sym.a, depth + 1) if sym.a is not None else None
            if isinstance(sym.b, NdxSV) and sym.b.op == 'const':
                mname = sym.b.a
            elif isinstance(sym.b, NdxSV):
                mname = self.expr(sym.b, depth + 1)
            else:
                mname = str(sym.b)
            # V100: nome-metodo tupla/lista costante — un nome-metodo è
            # SEMPRE una stringa del pool; una tupla lì è il vettore
            # argomenti di una vectorcall (pattern costruttore):
            # ``getattr(QLabel, ('text',))`` → ``QLabel('text')``.
            # Fallback al rendering: copre ogni percorso di costruzione.
            if isinstance(mname, (tuple, list)) and mname and obj:
                _sp_txt = [_const_repr(v) for v in mname if v is not None]
                _extra = []
                for a in (sym.c or []):
                    if isinstance(a, NdxSV):
                        if a.op in ('tstate', 'stackaddr', 'gslot'):
                            continue
                        _e2 = self.expr(a, depth + 1)
                        if _e2:
                            _extra.append(_e2)
                    elif a is not None:
                        _extra.append(_const_repr(a))
                return f'{self._atomize(obj)}({", ".join(_sp_txt + _extra)})'
            args = []
            for a in (sym.c or []):
                if isinstance(a, NdxSV):
                    # V100: vettore costante → spread; transport ABI → skip
                    if a.op in ('tstate', 'stackaddr', 'gslot'):
                        continue
                    _sp = self._spread_const_vector(a)
                    if _sp:
                        args.extend(
                            self.expr(v, depth + 1) for v in _sp)
                        continue
                    args.append(self.expr(a, depth + 1))
                elif a is not None:
                    args.append(_const_repr(a))
            arg_s = ', '.join(args)
            if obj is None:
                return f'{_ident(mname)}({arg_s})'
            if isinstance(sym.b, NdxSV) and sym.b.op == 'const':
                return f'{obj}.{_ident(mname)}({arg_s})'
            # V100: nome-metodo non risolto (mname == 'None').  Il vecchio
            # ``getattr(obj, None)(args)`` e' Python invalido garantito.  La
            # forma nativa che produce un mcall senza nome e' quasi sempre
            # ``dict.get(key, default)`` (call METH_FASTCALL su tp_getattro
            # con nome mancante dal pool): rende ``obj.get(...)`` — valido e
            # semanticamente la ricostruzione piu' probabile.
            if str(mname) == 'None' and args:
                return f'{obj}.get({arg_s})'
            return f'getattr({obj}, {mname})({arg_s})'
        if op == 'call':
            # zero-arg super(): Nuitka compila ``super()`` in un metodo
            # come call del globale ``super`` con ``__class__`` e la guard
            # ``self if self is not None else None`` come argomenti di
            # protocollo — il sorgente e' sempre ``super()``.  Un super
            # esplicito a due argomenti porta la classe base reale, mai
            # la cella ``__class__``, quindi resta intatto.
            if isinstance(sym.a, NdxSV) and sym.a.op == 'global' and \
                    sym.a.a == 'super':
                _sup_args = sym.b or []
                if not _sup_args or (
                        isinstance(_sup_args[0], NdxSV) and
                        _sup_args[0].op == 'var' and
                        _sup_args[0].a == '__class__'):
                    return 'super()'
            fn = self.expr(sym.a, depth + 1) if isinstance(sym.a, NdxSV) else sym.a
            args = []
            for a in (sym.b or []):
                if isinstance(a, NdxSV):
                    # V100: vettore costante → spread; transport ABI → skip
                    if a.op in ('tstate', 'stackaddr', 'gslot'):
                        continue
                    _sp = self._spread_const_vector(a)
                    if _sp:
                        args.extend(
                            self.expr(v, depth + 1) for v in _sp)
                        continue
                    args.append(self.expr(a, depth + 1))
                elif a is not None:
                    args.append(_const_repr(a))
            # V100: chiamata su un TYPE-OBJECT C-API: ``PyZip_Type(a, b)``
            # e' la call del costruttore builtin → ``zip(a, b)``.  Il
            # vecchio rendering lasciava il nome C-API invalido come callee.
            if (isinstance(sym.a, NdxSV) and sym.a.op == 'api_symbol'
                    and isinstance(sym.a.a, str)):
                _ctor = {
                    'PyZip_Type': 'zip', 'PyList_Type': 'list',
                    'PyDict_Type': 'dict', 'PySet_Type': 'set',
                    'PyTuple_Type': 'tuple', 'PyFrozenSet_Type': 'frozenset',
                    'PyComplex_Type': 'complex', 'PyRange_Type': 'range',
                    'PySuper_Type': 'super',
                }.get(sym.a.a)
                if _ctor:
                    return f'{_ctor}({", ".join(args)})'
            # V100: call(getattr(obj, <nome mancante>), args) — il vecchio
            # rendering componeva ``getattr(obj, None)(args)``, Python
            # invalido garantito.  La forma nativa e' quasi sempre un
            # ``dict.get(key, default)`` (METH_FASTCALL con nome mancante dal
            # pool costanti): rende ``obj.get(...)``.
            if (isinstance(sym.a, NdxSV) and sym.a.op == 'getattr'
                    and getattr(sym.a, 'b', None) is None
                    and args):
                _recv = self._atomize(self.expr(sym.a.a, depth + 1))
                if _recv:
                    return f'{_recv}.get({", ".join(args)})'
            return f'{fn}({", ".join(args)})'
        if op == 'await':
            value = self.expr(sym.a, depth + 1)
            return f'await {value}' if value else 'await _unknown_awaitable'
        if op == 'kwcall':
            fn = self.expr(sym.a, depth + 1) if isinstance(sym.a, NdxSV) else sym.a
            fn = self._atomize(fn) if isinstance(fn, str) else fn
            if not fn or fn == 'None':
                # a NULL callable is machine transport (e.g. a context
                # object), never source syntax; keep the arguments visible
                fn = '_unknown_callable'
            parts = []
            for value in (sym.b or []):
                if isinstance(value, NdxSV):
                    # V100: vettore costante → spread; transport ABI → skip
                    if value.op in ('tstate', 'stackaddr', 'gslot'):
                        continue
                    _sp = self._spread_const_vector(value)
                    if _sp:
                        parts.extend(
                            self.expr(v, depth + 1) for v in _sp)
                        continue
                    parts.append(self.expr(value, depth + 1) or 'None')
            for item in (sym.c or []):
                if not isinstance(item, NdxSV):
                    continue
                if item.op == 'kwarg':
                    value = self.expr(item.b, depth + 1) if isinstance(
                        item.b, NdxSV) else _const_repr(item.b)
                    if isinstance(item.a, str) and item.a.isidentifier() and not __import__('keyword').iskeyword(item.a):
                        parts.append(f'{item.a}={value or "None"}')
                    else:
                        parts.append('**{' + repr(item.a) + ': ' + (value or 'None') + '}')
                elif item.op == 'kwspread':
                    value = self.expr(item.a, depth + 1) if isinstance(
                        item.a, NdxSV) else _const_repr(item.a)
                    parts.append(f'**{value or "{}"}')
            return f'{fn}({", ".join(parts)})'
        if op == 'kwarg':
            value = self.expr(sym.b, depth + 1) if isinstance(
                sym.b, NdxSV) else _const_repr(sym.b)
            return f'{sym.a}={value}'
        if op == 'star':
            # positional star-spread of one sequence at a call site
            inner = self.expr(sym.a, depth + 1)
            return f'*{inner}' if inner else '*_unknown_iterable_'
        if op == 'getattr':
            obj = self._atomize(self.expr(sym.a, depth + 1))
            attr = sym.b
            if isinstance(attr, str) and attr.isidentifier():
                return f'{obj}.{attr}'
            # V100: nome attributo MANCANTE (sym.b None): ``getattr(x, None)``
            # e' Python invalido.  Il valore trasportato e' comunque l'oggetto
            # stesso: rendi il receiver nudo (forma valida, nessuna invenzione
            # di nome).
            if attr is None:
                return obj
            attr_s = self.expr(attr, depth + 1) if isinstance(attr, NdxSV) \
                else _const_repr(attr)
            return f'getattr({obj}, {attr_s})'
        if op == 'sub':
            o = self.expr(sym.a, depth + 1)
            if sym.b is not None and getattr(sym.b, 'op', None) == 'slice':
                parts = [self.expr(x, depth + 1)
                         for x in (sym.b.a, sym.b.b, sym.b.c)]
                while len(parts) > 1 and parts[-1] in (None, 'None'):
                    parts.pop()
                txt = ':'.join(p if p is not None else ''
                               for p in parts)
                if not txt:
                    txt = ':'
                return f'{o}[{txt}]'
            # V100: chiave const con marker strutturale slice del blob —
            # ('slice', start, stop, step) — e' ``x[start:stop:step]``,
            # mai ``x['slice', ...]``.  None → estremo vuoto.
            if (sym.b is not None and getattr(sym.b, 'op', None) == 'const'
                    and isinstance(sym.b.a, tuple) and len(sym.b.a) == 4
                    and sym.b.a[0] == 'slice'):
                _parts = [_const_repr(x) if x is not None else ''
                          for x in sym.b.a[1:]]
                while len(_parts) > 1 and _parts[-1] == 'None':
                    _parts.pop()
                _txt = ':'.join('' if p == 'None' else p for p in _parts)
                if not _txt:
                    _txt = ':'
                return f'{o}[{_txt}]'
            k = self.expr(sym.b, depth + 1)
            return f'{o}[{k}]'
        if op == 'slice':
            parts = [self.expr(x, depth + 1) for x in (sym.a, sym.b, sym.c)]
            while len(parts) > 1 and parts[-1] in (None, 'None'):
                parts.pop()
            txt = ':'.join(p if p is not None else '' for p in parts)
            # in un subscript contesto: base[slice]; standalone: slice(...)
            return ndx_k('slicelit', txt) if False else f'slice({", ".join(p for p in parts if p is not None)})'
        if op == 'contains':
            hay = self.expr(sym.a, depth + 1)
            needle = self.expr(sym.b, depth + 1)
            return f'{needle} in {hay}'
        if op == 'binop':
            x = self.expr(sym.b, depth + 1)
            y = self.expr(sym.c, depth + 1)
            opc = OP_TEXT.get(sym.a, sym.a)
            if opc not in ('+', '-', '*', '/', '//', '%', '**', '<<',
                           '>>', '&', '|', '^', '@'):
                # Never turn an unresolved native helper into invalid Python
                # such as ``left ? right``.  Keep both recovered operands in
                # an explicit, parseable evidence marker instead.
                return f'_HEXPYRION_UNKNOWN_BINOP({x}, {y})'
            return f'{x} {opc} {y}'
        if op == 'unary':
            if sym.a == '-':
                return f'-{self.expr(sym.b, depth + 1)}'
            if sym.a == '~':
                return f'~{self.expr(sym.b, depth + 1)}'
            return f'{sym.a}({self.expr(sym.b, depth + 1)})'
        if op == 'cmp':
            x = self.expr(sym.b, depth + 1)
            y = self.expr(sym.c, depth + 1)
            cop = CMP_TEXT.get(sym.a, sym.a)
            return f'{x} {cop} {y}'
        if op == 'ifexp':
            condition = self.expr(sym.a, depth + 1)
            when_true = self.expr(sym.b, depth + 1)
            when_false = self.expr(sym.c, depth + 1)
            if None in (condition, when_true, when_false):
                return None
            return f'({when_true} if {condition} else {when_false})'
        if op == 'bool':
            return self.expr(sym.a, depth + 1)
        if op == 'not':
            inner = self.expr(sym.a, depth + 1)
            if inner is None:
                return None
            return f'not {inner}'
        if op == 'len_slot':
            return f'len({self.expr(sym.a, depth + 1)})'
        if op == 'native_ssize':
            return self.expr(sym.a, depth + 1)
        if op == 'len':
            return f'len({self.expr(sym.a, depth + 1)})'
        if op == 'iter':
            return f'iter({self.expr(sym.a, depth + 1)})'
        if op == 'next':
            return f'next({self.expr(sym.a, depth + 1)})'
        if op == 'unpack':
            return self.expr(sym.a, depth + 1)
        if op == 'dict_empty':
            key = getattr(sym, 'n', None)
            if key is not None and key in self.comp_names:
                return self.comp_names[key]
            return '{}'
        if op == 'list_empty':
            key = getattr(sym, 'n', None)
            if key is not None and key in self.comp_names:
                return self.comp_names[key]
            _vn = None if top_assign else self._container_var_name(sym)
            if _vn:
                return _vn
            return '[]'
        if op == 'list_build':
            key = getattr(sym, 'n', None)
            if key is not None and key in self.comp_names:
                return self.comp_names[key]
            values = [self.expr(value, depth + 1)
                      if isinstance(value, NdxSV) else 'None'
                      for value in (sym.b or [])]
            return '[' + ', '.join(value or 'None' for value in values) + ']'
        if op == 'set_empty':
            key = getattr(sym, 'n', None)
            if key is not None and key in self.comp_names:
                return self.comp_names[key]
            return 'set()'
        if op == 'tuple_empty':
            return '()'
        if op == 'tuple_build':
            values = [self.expr(value, depth + 1) if isinstance(value, NdxSV)
                      else 'None' for value in (sym.b or [])]
            if len(values) == 1:
                return f'({values[0]},)'
            return '(' + ', '.join(value or 'None' for value in values) + ')'
        if op == 'format':
            value = self.expr(sym.a, depth + 1)
            spec = self.expr(sym.b, depth + 1) if sym.b is not None else "''"
            return f'format({value}, {spec})'
        if op == 'fstring':
            rendered = self._render_fstring(sym.a, depth)
            if rendered is not None:
                return rendered
            return "''.join(" + self._args_str(sym.a, depth) + ')'
        if op == 'str_join':
            sep = self.expr(sym.a, depth + 1)
            values = self.expr(sym.b, depth + 1)
            return f'{sep}.join({values})'
        if op == 'exc_match':
            return _exc_types_repr(sym.a)
        if op == 'import':
            # import inline in un'espressione → __import__ (sempre valido)
            if isinstance(sym.a, str) and sym.a.isidentifier():
                return f'__import__(\'{sym.a}\')'
            return '__import__(\'_unknown_\')'
        if op == 'super':
            return 'super()'
        if op == 'mod':
            return str(sym.a)
        if op == 'global':
            return str(sym.a)
        if op == 'pyformat':
            if sym.b is None:
                return repr(sym.a)
            if isinstance(sym.b, NdxSV):
                # valore singolo da registro: rendilo come espressione
                v = self.expr(sym.b, depth + 1)
                return f'{sym.a!r} % {v}'
            return f'{sym.a!r} % {sym.b!r}'
        # fallback: espressioni Python valide (MAI commenti/placeholder):
        # le chiamate native non mappate diventano funzioni nominate
        if op == 'apicall':
            nm = str(sym.a)
            return f'{_ident(nm)}({self._args_str(sym.b, depth)})'
        if op == 'nativecall':
            nm = str(sym.a)
            # il fetch dell'eccezione corrente di un handler legato con
            # ``as NAME`` si rende col nome del binding
            _exc_map = getattr(self, '_exc_fetch_names', None) or                 getattr(getattr(self, 'S', None), '_exc_fetch_names', None)
            _exc_nm = (_exc_map or {}).get(id(sym))
            if _exc_nm:
                return _exc_nm
            # V100: helper C-API con semantica Python diretta.  Il vecchio
            # rendering lasciava ``PySet_Contains(s, k)`` come call C
            # invalida; il sorgente originale e' l'operatore ``in``.
            _live_args = [x for x in (sym.b or []) if x is not None]
            if nm in ('PySet_Contains', 'PyDict_Contains',
                      'PySequence_Contains', 'PyUnicode_Contains',
                      'PyBytes_Contains') and len(_live_args) >= 2:
                _key = self.expr(_live_args[1], depth + 1)
                _cont = self._atomize(self.expr(_live_args[0], depth + 1))
                if _key and _cont:
                    return f'{_key} in {_cont}'
            if nm == 'Nuitka_LongUpdateFromCLong' and len(_live_args) >= 2 \
                    and getattr(_live_args[0], 'op', None) == 'stackaddr':
                # aggiorna una locale int col NUOVO valore: assegnamento
                _var = self._slot_var_of_stackaddr(_live_args[0])
                _val = self.expr(_live_args[1], depth + 1)
                if _var and _val and 'stackaddr' not in _val \
                        and '_gslot' not in _val:
                    return f'{_var} = {_val}'
            return f'{_ident(nm)}({self._args_str(sym.b, depth)})'
        if op == 'dict_copy':
            return 'dict.copy(' + self.expr(sym.a, depth + 1) + ')'
        if op == 'func_new':
            owner = getattr(getattr(getattr(self, 'S', None), 'L', None), 'co', None)
            parent = getattr(owner, 'qualname', None) or getattr(owner, 'name', None)
            values = sym.b if isinstance(sym.b, list) else []
            qualname = values[2].a if len(values) > 2 and isinstance(values[2], NdxSV) and values[2].op == 'const' else None
            prefix = str(parent) + '.<locals>.'
            if isinstance(qualname, str) and qualname.startswith(prefix):
                name = qualname[len(prefix):]
                if name.isidentifier():
                    return name
                if '<lambda>' in name:
                    lam = self._render_lambda_inline(qualname, values, depth)
                    if lam is not None:
                        return lam
                    return 'lambda *_args: None'
            return '_make_function()'
        if op in ('unpack', 'stopiter_value', 'iter2'):
            return self.expr(sym.a, depth + 1)
        if op == 'tp_slot':
            return '_tp_slot'
        if op == 'imm':
            return str(sym.a)
        # V100: const_array fuori da una call — il vettore-item di una
        # tupla costante provata.  Come valore Python è la tupla stessa.
        if op == 'const_array' and isinstance(sym.a, (tuple, list)):
            try:
                _start = int(sym.b or 0)
            except (TypeError, ValueError):
                _start = 0
            _vals = list(sym.a[_start:])
            if len(_vals) == 1:
                return _const_repr(_vals[0])
            return '(' + ', '.join(_const_repr(v) for v in _vals) + ')'
        # dict_merge: ``{**m1, **m2}`` (merge di mapping del lowering)
        if op == 'dict_merge':
            ms = [self.expr(x, depth + 1) for x in (sym.b or [])
                  if isinstance(x, NdxSV)]
            ms = [m for m in ms if m and m != '{}']
            return '{' + ', '.join('**' + m for m in ms) + '}' if ms                 else '{}'
        # generico
        return f'_{_ident(op)}({self._args_str([sym.a, sym.b, sym.c], depth)})'

    # ------------------------------------------------------------ stmts
    # nomi di eccezione builtin CPython: una call bare a uno di questi è
    # la costruzione dell'eccezione nel percorso RAISE di Nuitka.
    EXC_CLASS_NAMES = frozenset((
        'ValueError', 'TypeError', 'RuntimeError', 'KeyError', 'IndexError',
        'AttributeError', 'NameError', 'UnboundLocalError', 'ZeroDivisionError',
        'StopIteration', 'StopAsyncIteration', 'ArithmeticError',
        'OverflowError', 'AssertionError', 'NotImplementedError',
        'ImportError', 'ModuleNotFoundError', 'LookupError', 'MemoryError',
        'BufferError', 'OSError', 'IOError', 'FileNotFoundError',
        'FileExistsError', 'PermissionError', 'ReferenceError',
        'SystemError', 'RecursionError', 'SyntaxError', 'IndentationError',
        'TabError', 'UnicodeError', 'UnicodeDecodeError',
        'UnicodeEncodeError', 'UnicodeTranslateError', 'Exception',
        'BaseException', 'KeyboardInterrupt', 'SystemExit',
        'GeneratorExit', 'FloatingPointError', 'TimeoutError',
        'ConnectionError', 'ConnectionResetError', 'ConnectionAbortedError',
        'ConnectionRefusedError', 'BrokenPipeError', 'InterruptedError'))

    # marker di machinery ai livelli statement: non sono semantica Python
    MACHINERY_STMT_MARKERS = ('_stackaddr(', '_gaddr(', '_gslot(',
                              '_tstate(', '_tp_slot', '_type_of(',
                              '_make_function()', ' PyLong_FromSsize_t(',
                              '_frame(')

    def _slot_var_of_stackaddr(self, sa):
        """Nome della variabile locale che vive nello slot indicato da uno
        stackaddr SV ('rbp', off) — tramite la tabella nomi dello Structurer."""
        base = getattr(sa, 'a', None)
        off = getattr(sa, 'b', None)
        if base is None or off is None:
            return None
        try:
            nm = self.S.name_of_loc(('mem', base, off))
        except Exception:
            return None
        return nm if isinstance(nm, str) and nm.isidentifier() else None

    def _clean_lines(self, lines):
        """Filtro universale post-render: statement machinery, duplicati
        consecutivi e raise di classi-eccezione."""
        import re as _re_r
        out = []
        i = 0
        # while spurio del guard-retry Nuitka: stesso identico header
        # `while COND:` di un `if COND:` già emesso alla stessa
        # indentazione, col corpo che ne duplica il raise → elimina
        # l'intero blocco while (header + corpo più indentato).
        seen_if_conds = set()
        cleaned_retry = []
        i2 = 0
        while i2 < len(lines):
            ln2 = lines[i2]
            st2 = ln2.strip()
            ind2 = len(ln2) - len(ln2.lstrip())
            if st2.startswith('if ') and st2.endswith(':'):
                seen_if_conds.add((ind2, st2[3:]))
                cleaned_retry.append(ln2)
            elif st2.startswith('while ') and st2.endswith(':') and                     (ind2, st2[6:]) in seen_if_conds:
                j2 = i2 + 1
                while j2 < len(lines):
                    nxt = lines[j2]
                    if nxt.strip() and (len(nxt) - len(nxt.lstrip())) <= ind2:
                        break
                    j2 += 1
                i2 = j2
                continue
            else:
                cleaned_retry.append(ln2)
            i2 += 1
        lines = cleaned_retry
        yielded_exprs = set()
        yielded_seen = [False]
        while i < len(lines):
            ln = lines[i]
            stripped = ln.strip()
            # machinery standalone → drop (statement interi, mai
            # sotto-espressioni)
            if any(stripped.startswith(m)
                   for m in self.MACHINERY_STMT_MARKERS):
                i += 1
                continue
            # V100: statement rumore residuali del lowering — mai codice
            # sorgente utente:
            #   * letterale numerico bare (trasporto di un intero non
            #     consumato, es. il conteggio argomenti di una kwcall)
            #   * temporanea bare `_vN` (value-numbering orfano)
            #   * allocazione runtime bare: Nuitka_GC_New / MAKE_FLOAT /
            #     MAKE_TUPLE non consumate dal rendering
            if _re_r.fullmatch(r'[-+]?\d+', stripped) or \
                    _re_r.fullmatch(r'_v\d+', stripped) or \
                    _re_r.fullmatch(r'\w+\s*=\s*None\(\)\s*', stripped) or \
                    stripped.startswith(('Nuitka_GC_New(',
                                         'MAKE_FLOAT_FROM_DOUBLE(',
                                         'MAKE_TUPLE(',
                                         'Nuitka_LongUpdateFromCLong(',
                                         'Nuitka_Coroutine_await(',
                                         'Nuitka_CoroutineSwitcher(')):
                i += 1
                continue
            # V100: lazy-check del code object all'ingresso dell'impl
            # (coppia maker ``sub_A(sub_B(<code f>), N)``) e binding di
            # creazione funzione annidata (``X.Y = sub(<code f>)``,
            # ``sub(<code f>)`` nudo): puro machinery di registrazione,
            # mai sorgente — il marker ``<code ...>`` esiste SOLO lì.
            if _re_r.search(
                    r'= sub_[0-9a-f]+\(.*<code .*\)?\)?'
                    r'(, \d+\))?$', stripped) or                     _re_r.match(
                        r'sub_[0-9a-f]+\(.*<code .*\)?\)?'
                        r'(, \d+\))?$', stripped):
                i += 1
                continue
            # V100: statement nudo nome/letterale — un'espressione Name o
            # un display di soli atomi scartati non ha MAI effetti in
            # Python: è rumore del lowering (binding di modulo emessi come
            # nomi nudi, costanti non consumate). Droppato solo se senza
            # chiamate/attributi/subscript (parentesi interne, punti).
            if stripped and '(' not in stripped and '.' not in stripped \
                    and '=' not in stripped and ' for ' not in stripped \
                    and ' if ' not in stripped \
                    and not stripped.endswith(':') \
                    and not stripped.startswith(('return', 'raise', 'yield',
                                                 'assert', 'del ', 'global ',
                                                 'nonlocal ', 'import',
                                                 'from', 'pass', 'break',
                                                 'continue', '#', '@')) and \
                    (_re_r.fullmatch(r'[A-Za-z_]\w*', stripped) or
                     _re_r.fullmatch(r'(?s)[\'"].*[\'"]', stripped) or
                     stripped in ('None', 'True', 'False', '...', '[]',
                                  '{}', '()') or
                     (_re_r.fullmatch(
                         r'[\[{(][\w\s,.:\'\"{}\[\]()-]*[\]})]',
                         stripped) and
                      '(' not in stripped[1:-1] and
                      '[' not in stripped[1:-1] and
                      '{' not in stripped[1:-1])):
                i += 1
                continue
            # helper nativo NON risolto come statement bare: quando la
            # semantica è nota il rendering usa nomi Python. Un sub_*
            # residuo con SOLO argomenti machinery (tstate/frame/slot) è
            # transport già consumato → drop. Se invece trasporta valori
            # del sorgente (variabili, costanti, f-string) viene CONSERVATO:
            # è codice recuperato che non deve sparire dall'output.
            m_bare_sub = _re_r.match(r'sub_[0-9a-f]+\((.*)\)$', stripped)
            if m_bare_sub:
                inner = m_bare_sub.group(1)
                parts = [p.strip() for p in inner.split(',')] \
                    if inner.strip() else []
                mach_prefixes = ('_tstate', '_gslot', '_gaddr',
                                 '_stackaddr', '_frame', '_tp_slot')
                all_mach = not parts or all(
                    (not p) or p.startswith(mach_prefixes) or
                    _re_r.fullmatch(r'[-+]?\d+\)?', p)
                    for p in parts)
                if all_mach:
                    i += 1
                    continue
            # generatore: dopo un `yield`, i `return VALORE` sono il
            # percorso StopIteration-value di Nuitka (il valore di ritorno
            # del generatore) — nel sorgente originale non compaiono come
            # statement visibili. Bare return (fine generazione) resta.
            if yielded_seen[0] and stripped != 'return' and                     stripped.startswith('return'):
                i += 1
                continue
            if stripped.startswith('yield'):
                yielded_exprs.add(stripped[6:])
                yielded_seen[0] = True
            # uscita del for-loop: check StopIteration inline di Nuitka e
            # next(iter(x)) residuo del setup iteratore
            if (stripped.startswith('issubclass(_type_of(') and
                    'StopIteration' in stripped) or                     (stripped.startswith('next(iter(') and
                     stripped.endswith(')')):
                i += 1
                continue
            # assign con RHS machinery puro → drop
            if ' = ' in stripped:
                rhs = stripped.split(' = ', 1)[1].strip()
                if any(rhs.startswith(m) for m in
                       self.MACHINERY_STMT_MARKERS) or \
                        any(m in rhs for m in ('_frame(', '_tstate(',
                                               '_gslot(', '_stackaddr(',
                                               '_gaddr(',
                                               'Nuitka_GC_New(',
                                               'Nuitka_LongUpdateFromCLong(',
                                               'MAKE_FLOAT_FROM_DOUBLE(')) or \
                        (rhs.startswith('next(iter(') and
                         rhs.endswith(')')):
                    i += 1
                    continue
            # return del check StopIteration (uscita loop Nuitka) → drop
            if stripped.startswith('return ') and                     '_type_of(' in stripped and                     'StopIteration' in stripped:
                i += 1
                continue
            # Repeated source text is not evidence of repeated native work.
            # Calls, yields, and mutations must retain their multiplicity.
            # `X = ExcClass(...)` o `ExcClass(...)` bare → raise
            import re as _re_r
            m_asgn = _re_r.fullmatch(
                r'(\s*)(\w+) = ((?:\w+\.)?(?:%s)\(.*)' %
                '|'.join(self.EXC_CLASS_NAMES), ln)
            m_bare = _re_r.fullmatch(
                r'(\s*)((?:\w+\.)?(?:%s)\(.*)' %
                '|'.join(self.EXC_CLASS_NAMES), ln)
            if m_asgn and ' = ' not in m_asgn.group(3):
                # Cold-path NULL-check delle globali (semantica reload di
                # Nuitka): la costruzione ``NameError(<nome>)`` ASSEGNATA alla
                # variabile del risultato è il percorso d'errore del check
                # ``if global == NULL``, non un raise utente. Non promuoverla
                # a raise: scarta.
                if m_asgn.group(3).startswith('NameError('):
                    i += 1
                    continue
                out.append(f'{m_asgn.group(1)}raise {m_asgn.group(3)}')
                i += 1
                continue
            if m_bare:
                if m_bare.group(2).startswith('NameError('):
                    i += 1
                    continue
                out.append(f'{m_bare.group(1)}raise {m_bare.group(2)}')
                i += 1
                continue
            out.append(ln)
            i += 1
        # V100: pota i FRAMMENTI del lowering di una f-string quando la
        # f-string completa e' gia' emessa nelle righe successive.  Il
        # lowering nativo calcola la stringa due volte: una come tuple di
        # pezzi (``T = (lit, format(E, ''), ...)`` con temporanee singole
        # ``X = format(E2, '')`` spillate subito prima) e una come formato
        # nativo ``Y = f'...{E}...'``.  Se ogni sotto-espressione E dei
        # pezzi compare nella f-string vicina, i frammenti sono duplicati
        # e la tuple non e' sorgente: si droppa.  Universale: nessun nome
        # applicativo, solo la forma (literal|format(E,'')).
        # Il frammento STANDALONE ``X = format(E, '')`` seguito dalla
        # f-string ``Y = f'...{E}...'`` e' il PRIMO uso del valore nel
        # flusso: il suo nome X e' quello giusto per la variabile —
        # trasferisce X alla f-string e rinomina tutti gli usi di Y.
        try:
            _tuple_asgn = _re_r.compile(
                r'^(\w+) = \((.+)\)$')
            _fmt = _re_r.compile(r"^format\((.+), ''\)$")
            _lit = _re_r.compile(r'^(?:\'[^\']*\'|"[^"]*")$')
            _fstr = _re_r.compile(r"^(\w+) = f['\"]")
            _drop2 = set()
            for _k2, _ln2 in enumerate(out):
                _st2 = _ln2.strip()
                m2 = _tuple_asgn.match(_st2)
                if not m2:
                    continue
                # split top-level delle virgole
                parts, depth, cur = [], 0, ''
                for ch in m2.group(2):
                    if ch in '([{':
                        depth += 1
                    elif ch in ')]}':
                        depth -= 1
                    if ch == ',' and depth == 0:
                        parts.append(cur.strip())
                        cur = ''
                    else:
                        cur += ch
                if cur.strip():
                    parts.append(cur.strip())
                if not parts or len(parts) < 2:
                    continue
                # risolvi ogni pezzo a una sotto-espressione
                exprs, ok_all = [], True
                for p in parts:
                    if _lit.match(p):
                        continue
                    fm = _fmt.match(p)
                    if fm:
                        exprs.append(fm.group(1))
                        continue
                    # identifier: cerca indietro `id = format(E, '')`
                    resolved = None
                    for back in range(_k2 - 1, max(-1, _k2 - 6), -1):
                        bm = _re_r.fullmatch(
                            _re_r.escape(p) + r" = format\((.+), ''\)",
                            out[back].strip())
                        if bm:
                            resolved = bm.group(1)
                            _drop2.add(back)
                            break
                    if resolved:
                        exprs.append(resolved)
                    else:
                        ok_all = False
                        break
                if not ok_all or not exprs:
                    _drop2.discard(_k2)
                    continue
                # f-string completa nelle prossime 8 righe che contiene
                # TUTTE le sotto-espressioni
                fused = False
                for fwd in range(_k2 + 1, min(len(out), _k2 + 9)):
                    if _fstr.match(out[fwd].strip()) and \
                            all(e in out[fwd] for e in exprs):
                        fused = True
                        break
                if fused:
                    _drop2.add(_k2)
            if _drop2:
                out = [l for k, l in enumerate(out) if k not in _drop2]
            # V100: trasferimento del NOME dal frammento standalone alla
            # f-string.  ``X = format(E, '')`` + ``Y = f'...{E}...'``:
            # il frammento era il primo uso del valore e ha consumato il
            # varname corretto (X); la f-string deve portare quel nome e
            # ogni uso successivo di Y va rinominato X.
            try:
                _frag = _re_r.compile(r"^(\w+) = format\((.+), ''\)$")
                _fasgn = _re_r.compile(r"^(\w+) = (f['\"].*)$")
                for _k4, _ln4 in enumerate(out):
                    m4 = _frag.match(_ln4.strip())
                    if not m4:
                        continue
                    frag_name, frag_expr = m4.group(1), m4.group(2)
                    for _j4 in range(_k4 + 1, min(len(out), _k4 + 7)):
                        m5 = _fasgn.match(out[_j4].strip())
                        if m5 and frag_expr in out[_j4]:
                            old_name = m5.group(1)
                            if old_name == frag_name:
                                break
                            pad4 = out[_j4][:len(out[_j4]) -
                                            len(out[_j4].lstrip())]
                            out[_j4] = f'{pad4}{frag_name} = {m5.group(2)}'
                            out[_k4] = None
                            for _r4 in range(len(out)):
                                if out[_r4] is not None:
                                    out[_r4] = _re_r.sub(
                                        r'\b' + _re_r.escape(old_name) +
                                        r'\b', frag_name, out[_r4])
                            break
                out = [l for l in out if l is not None]
            except Exception:
                pass
            # Literal propagation is performed by the AST cleanup with
            # lexical scopes and synthetic names. Text substitution here
            # loses closure bindings and can replace a name inside a string.
            # V100: inline single-use di una f-string assegnata e subito
            # stampata: ``T = f'...'\nprint(T)`` → ``print(f'...')`` (il
            # nome compare esattamente due volte nel blocco).
            try:
                _fa = _re_r.compile(r"^(\w+) = (f['\"].*)$")
                _pr = _re_r.compile(r'^print\((\w+)\)$')
                for _k3, _ln3 in enumerate(out):
                    m3 = _fa.match(_ln3.strip())
                    if not m3:
                        continue
                    name3, fval = m3.group(1), m3.group(2)
                    uses = [j for j, l in enumerate(out)
                            if _re_r.search(r'\b' + name3 + r'\b', l)]
                    if len(uses) != 2 or uses[1] != uses[0] + 1:
                        continue
                    if _pr.match(out[uses[1]].strip()) and \
                            _pr.match(out[uses[1]].strip()).group(1) == name3:
                        pad = out[uses[1]][:len(out[uses[1]]) -
                                           len(out[uses[1]].lstrip())]
                        out[uses[0]] = None
                        out[uses[1]] = f'{pad}print({fval})'
                out = [l for l in out if l is not None]
            except Exception:
                pass
        except Exception:
            pass
        # A trailing break is legal Python. Only native control-flow
        # evidence may eliminate one; indentation alone proves nothing.
        # V100: riparazione universale — se un filtro ha rimosso TUTTI gli
        # statement di un blocco (header if/for/while/def/try/else/...
        # senza alcuna riga più indentata che segue), reinserisci ``pass``:
        # un corpo vuoto è Python invalido, ``pass`` è la semantica che
        # quei filtri intendevano (statement interamente machinery).
        try:
            header_rx = _re_r.compile(
                r'\s*(if.*|elif.*|for.*|while.*|def.*|'
                r'class.*|with.*|async.*|try:|else:|finally:|'
                r'except[^:]*):\s*$')
            repaired = []
            for k, ln in enumerate(out):
                repaired.append(ln)
                if header_rx.match(ln):
                    ind = len(ln) - len(ln.lstrip())
                    nxt_ind = None
                    for ln2 in out[k + 1:]:
                        if ln2.strip():
                            nxt_ind = len(ln2) - len(ln2.lstrip())
                            break
                    if nxt_ind is None or nxt_ind <= ind:
                        repaired.append(' ' * (ind + 4) + 'pass')
            out = repaired
        except Exception:
            pass
        return out

    def render(self, stmts, indent=0, loop_tail=False):
        stmts = self._restore_constant_returns(stmts)
        # NOTA: il two-pass di inline dei temp single-use è DISABILITATO
        # (il rendering dell'espressione inline può divergere dal pass 1
        # e lasciare usi orfani). L'inline rimane per gli iterable del
        # for (mutazione statement, sicura).
        _ = getattr(self, '_inline_pass', False)
        if False and not getattr(self, '_inline_pass', False) and stmts:
            import re as _re_i
            self._inline_pass = True
            try:
                lines1 = self._render_once(list(stmts), indent)
                cands = {}
                for idx, st in enumerate(stmts):
                    if st.kind == 'assign' and isinstance(st.a, str) and                             isinstance(st.b, NdxSV) and st.b.op not in (
                                'loc', 'var', 'par', 'const', 'imm'):
                        cands.setdefault(st.a, []).append(idx)
                inline = {}
                drop = set()
                for name, idxs in cands.items():
                    if len(idxs) != 1:
                        continue
                    pat = '\\b' + _re_i.escape(name) + '\\b'
                    cnt = len(_re_i.findall(pat, chr(10).join(lines1)))
                    if cnt == 2:
                        inline[name] = stmts[idxs[0]].b
                        drop.add(idxs[0])
                # valida: l'espressione inline deve rendersi pulita (niente
                # token invalidi/marker) altrimenti l'inline corrompe
                # l'identificatore
                ok_inline = {}
                for name2, rhs in inline.items():
                    try:
                        e2 = self.expr(rhs, depth=1)
                    except Exception:
                        e2 = None
                    # solo espressioni CONCRETE: se l'espressione
                    # contiene a sua volta nomi temp (catena), l'inline
                    # spezzerebbe la definizione lasciando usi orfani
                    if e2 and '?' not in e2 and                             '__HEXPYRION' not in e2 and not _re_i.search(
                                r'_v\d+|_tmp', e2):
                        ok_inline[name2] = rhs
                inline = ok_inline
                if not inline:
                    return lines1
                S = getattr(self, 'S', None)
                saved_ti = getattr(S, 'temp_inline', {}) if S else {}
                if S is not None:
                    ti = dict(saved_ti)
                    ti.update(inline)
                    S.temp_inline = ti
                stmts2 = [st for i, st in enumerate(stmts)
                          if i not in drop]
                try:
                    return self._render_once(stmts2, indent)
                finally:
                    self._inline_pass = False
                    if S is not None:
                        S.temp_inline = saved_ti
            finally:
                self._inline_pass = False
        # ``continue`` finale di un corpo for/while: no-op sorgente (il
        # latch esiste sempre nel flusso nativo e la struttura lo emette
        # come statement esplicito) → drop, ma solo se il corpo resta
        # non vuoto.  Nello stesso giro cadono gli ``super()`` nudi:
        # l'espressione è protocollo puro (nessun effetto sorgente), il
        # valore vero arriva dal phi/mcall collegato.
        def _strip_trailing_continue(lst, depth=0):
            if depth > 24 or not lst:
                return
            keep = []
            for s in lst:
                if s is None or not hasattr(s, 'kind'):
                    keep.append(s)
                    continue
                if s.kind == 'expr' and isinstance(s.a, NdxSV) and \
                        s.a.op == 'call' and isinstance(s.a.a, NdxSV) and \
                        s.a.a.op == 'global' and s.a.a.a == 'super':
                    continue
                # residui di protocollo: lettura __enter__/__exit__ mai
                # consumata e chiamata di un callee-costante non chiamabile
                # (la tupla (None, None, None) del dispatch di with) —
                # trasporto di macchina, mai sorgente
                if s.kind == 'expr' and isinstance(s.a, NdxSV) and \
                        s.a.op == 'getattr' and \
                        isinstance(s.a.b, str) and \
                        s.a.b in ('__enter__', '__exit__'):
                    continue
                if s.kind == 'expr' and isinstance(s.a, NdxSV) and \
                        s.a.op == 'call' and isinstance(s.a.a, NdxSV) and \
                        s.a.a.op == 'const' and not isinstance(
                            s.a.a.a, (str, int, float, bool)):
                    continue
                keep.append(s)
            lst[:] = keep
            for s in lst:
                for f in ('c', 'b'):
                    v = getattr(s, f, None)
                    if isinstance(v, list) and len(v) > 1 and \
                            s.kind in ('for', 'while'):
                        while v and getattr(v[-1], 'kind', None) == 'continue':
                            v.pop()
                        # if senza else in coda al corpo: il continue a fine
                        # braccio raggiunge comunque il latch → droppabile
                        while v and getattr(v[-1], 'kind', None) == 'if' and \
                                not getattr(v[-1], 'c', None) and \
                                isinstance(getattr(v[-1], 'b', None), list) \
                                and v[-1].b and getattr(
                                    v[-1].b[-1], 'kind', None) == 'continue':
                            v[-1].b.pop()
                            if not v[-1].b:
                                v.pop()
                    if isinstance(v, list) and v and all(
                            hasattr(g, 'kind') for g in v):
                        _strip_trailing_continue(v, depth + 1)
        _strip_trailing_continue(stmts)
        if loop_tail:
            # questa lista È un corpo di loop (chiamata ricorsiva da
            # render_stmt per for/while): la regola di coda vale anche
            # per la lista radice
            while stmts and getattr(stmts[-1], 'kind', None) == 'continue':
                stmts.pop()
            while stmts and getattr(stmts[-1], 'kind', None) == 'if' and \
                    not getattr(stmts[-1], 'c', None) and \
                    isinstance(getattr(stmts[-1], 'b', None), list) and \
                    stmts[-1].b and getattr(stmts[-1].b[-1], 'kind',
                                            None) == 'continue':
                stmts[-1].b.pop()
                if not stmts[-1].b:
                    stmts.pop()
        return self._render_once(stmts, indent)

    @staticmethod
    def _sv_walk(sym, fn, _path=None, _depth=0):
        """Visita ricorsivamente un NdxSV: fn viene chiamato su OGNI nodo
        (strutturale incluso) e, per i riferimenti var/loc, anche sul
        nome stringa.

        V100: il grafo SV può contenere cicli (phi, nodi riusati dal
        lifter): senza marcatura dei nodi sul cammino corrente la
        ricorsione non termina e il RecursionError ingoia l'intero
        corpo. La guard è per-cammino (discard in uscita) così i DAG
        con nodi condivisi contano ancora più usi dello stesso nome."""
        if not isinstance(sym, NdxSV):
            return
        if _depth > 400:
            return
        if _path is None:
            _path = set()
        marker = id(sym)
        if marker in _path:
            return
        _path.add(marker)
        try:
            fn(sym)
            if sym.op in ('var', 'loc'):
                if isinstance(sym.a, str):
                    fn(sym.a)
                return
            for f in (sym.a, sym.b, sym.c, sym.n):
                if isinstance(f, NdxSV):
                    NdxRenderer._sv_walk(f, fn, _path, _depth + 1)
                elif isinstance(f, (list, tuple)):
                    for g in f:
                        if isinstance(g, NdxSV):
                            NdxRenderer._sv_walk(g, fn, _path, _depth + 1)
        finally:
            _path.discard(marker)

    @classmethod
    def _stmt_walk(cls, st, fn):
        """Visita tutti gli NdxSV di uno statement, inclusi i body annidati."""
        if st is None:
            return
        stack = [st]
        while stack:
            cur = stack.pop()
            if cur is None:
                continue
            for f in (getattr(cur, 'a', None), getattr(cur, 'b', None),
                      getattr(cur, 'c', None), getattr(cur, 'd', None),
                      getattr(cur, 'e', None)):
                if isinstance(f, NdxSV):
                    cls._sv_walk(f, fn)
                elif isinstance(f, (list, tuple)):
                    for g in f:
                        if isinstance(g, NdxSV):
                            cls._sv_walk(g, fn)
                        elif hasattr(g, 'kind'):
                            stack.append(g)

    @staticmethod
    def _sv_key_eq(s, k):
        try:
            return sv_key(s) == k
        except Exception:
            return False

    @classmethod
    def _count_uses(cls, stmts, name):
        cnt = 0
        box = []
        for st in stmts:
            cls._stmt_walk(st, box.append)
        return sum(1 for n in box if n == name)

    def _harvest_nested_decorators(self, stmts):
        """``W = D(…)`` + ``_vN = W(func_new(Q))`` + ``return <stessa call>``
        → decorator ``@D(…)`` sul nested def Q + ``return Q``: è lo zucchero
        ``@D def Q…`` del sorgente, che il lowering nativo spezza in una
        applicazione esplicita.  L'argomento della factory è la cellref
        assegnata poco prima (il callable chiuso)."""
        factory_by_name = {}
        for idx, s in enumerate(stmts):
            if s is None or getattr(s, 'kind', None) != 'assign' or \
                    not isinstance(s.b, NdxSV) or s.b.op != 'call':
                continue
            if isinstance(s.b.a, NdxSV) and s.b.a.op == 'global' and \
                    not (s.b.b or []) and isinstance(s.a, str):
                factory_by_name[s.a] = (idx, s)
        if not factory_by_name:
            return stmts
        drops = set()
        rewrites = {}
        for idx, s in enumerate(stmts):
            if s is None or getattr(s, 'kind', None) != 'assign' or \
                    not isinstance(s.b, NdxSV) or s.b.op != 'call':
                continue
            # callee: var(W) (value numbering) oppure call(global(D)) identity
            wname = None
            if isinstance(s.b.a, NdxSV) and s.b.a.op == 'var' and \
                    isinstance(s.b.a.a, str) and s.b.a.a in factory_by_name:
                wname = s.b.a.a
            elif isinstance(s.b.a, NdxSV) and s.b.a.op == 'call' and \
                    isinstance(s.b.a.a, NdxSV) and s.b.a.a.op == 'global':
                for _nm, (_fi, _fs) in factory_by_name.items():
                    if _fs.b is s.b.a:
                        wname = _nm
                        break
            if wname is None:
                continue
            fn = next((a for a in (s.b.b or []) if isinstance(a, NdxSV)
                       and a.op == 'func_new'), None)
            if fn is None or not (isinstance(fn.b, list) and
                                  len(fn.b) > 2 and
                                  isinstance(fn.b[1], NdxSV) and
                                  isinstance(fn.b[1].a, str) and
                                  isinstance(fn.b[2], NdxSV) and
                                  isinstance(fn.b[2].a, str)):
                continue
            fname, qn = fn.b[1].a, fn.b[2].a
            ridx = next((j for j, s2 in enumerate(stmts)
                         if s2 is not None and getattr(s2, 'kind', None) ==
                         'return' and (s2.a is s.b or _sv_eq(s2.a, s.b))),
                        None)
            if ridx is None:
                continue
            fidx, fs = factory_by_name[wname]
            arg_txt = None
            # la cellref (argomento perso della factory 0-arg): prima
            # cellref del corpo.  Si rende come _cellN LETTERALE: la
            # sostituzione freevars in _emit_nested_defs/_emit_def lo
            # traduce nel nome reale (co.freevars[N]).
            for s3 in stmts:
                if s3 is not None and getattr(s3, 'kind', None) == 'assign' \
                        and isinstance(s3.b, NdxSV) and \
                        s3.b.op == 'cellref':
                    arg_txt = f'_cell{s3.b.a}'
                    break
            dec = f'@{fs.b.a.a}({arg_txt})' if arg_txt else f'@{fs.b.a.a}'
            _NDX_NESTED_DECORATORS.setdefault(qn, dec)
            # NOTA: la riscrittura stmt dell'apply/return (var(fname))
            # viene poi sostituita da _schedule_native_values — si tiene
            # SOLO lo stash del decoratore (basta per la firma esatta).
            if True:
                continue
            _var_sv = ndx_k('var', fname)
            s.b = _var_sv
            _rs = stmts[ridx]
            if getattr(_rs, 'a', None) is not None and \
                    hasattr(getattr(_rs, 'a', None), 'op'):
                _rs.a = _var_sv
            drops.add(fidx)
        if not drops and not rewrites:
            return stmts
        out = []
        for j, s in enumerate(stmts):
            if j in rewrites:
                out.append(rewrites[j])
            elif j in drops or id(s) in drops:
                continue
            else:
                out.append(s)
        return out

    def _fuse_call_chains(self, stmts):
        """Fonde le catene di chiamate spezzate dal lowering nativo:
        ``A = f()``; ``B = A.attr``; ``C = B(x)`` → ``C = f().attr(x)``.
        Ogni destinazione intermedia deve essere single-use (consumata
        solo dal passo successivo della catena). Universale: opera sui
        nodi statement, prima del rendering."""
        for _round in range(8):
            changed = False
            i = 0
            while i < len(stmts):
                st = stmts[i]
                if st is None or st.kind != 'assign' or \
                        not isinstance(st.b, NdxSV) or \
                        not isinstance(st.a, str):
                    i += 1
                    continue
                name = st.a
                tail = stmts[i + 1:]
                if self._count_uses(tail, name) != 1:
                    i += 1
                    continue
                fused = False
                for j, nx in enumerate(tail):
                    if nx is None or nx.kind != 'assign' or \
                            not isinstance(nx.b, NdxSV):
                        continue
                    nb = nx.b
                    # receiver di una mcall: C = X.name(...) con X single-use
                    if nb.op == 'mcall' and isinstance(nb.a, NdxSV) and \
                            nb.a.op in ('var', 'loc') and \
                            nb.a.a == name and \
                            st.b.op in ('call', 'mcall', 'getattr'):
                        nb.a = st.b
                        stmts[i] = None
                        fused = True
                        break
                    # callee bound: C = X(...) con X = Y.attr
                    if nb.op == 'call' and isinstance(nb.a, NdxSV) and \
                            nb.a.op in ('var', 'loc') and \
                            nb.a.a == name and st.b.op == 'getattr':
                        nb.a = st.b
                        stmts[i] = None
                        fused = True
                        break
                    # receiver dentro un getattr-callee: C = X.attr(...)
                    # con X = f(...) — chain completa .session().get()
                    if nb.op == 'call' and isinstance(nb.a, NdxSV) and \
                            nb.a.op == 'getattr' and \
                            isinstance(nb.a.a, NdxSV) and \
                            nb.a.a.op in ('var', 'loc') and \
                            nb.a.a.a == name and \
                            st.b.op in ('call', 'mcall'):
                        nb.a.a = st.b
                        stmts[i] = None
                        fused = True
                        break
                    # chiamata diretta: C = X(...) con X = f(...)
                    if nb.op == 'call' and isinstance(nb.a, NdxSV) and \
                            nb.a.op in ('var', 'loc') and \
                            nb.a.a == name and \
                            st.b.op in ('call', 'mcall'):
                        nb.a = st.b
                        stmts[i] = None
                        fused = True
                        break
                if fused:
                    changed = True
                i += 1
            stmts = [s for s in stmts if s is not None]
            if not changed:
                break
        return stmts

    def _fuse_fstring_stmts(self, stmts):
        """Fonde i pezzi del lowering f-string quando il value numbering
        li ha separati: ``A = format(X, '')`` + ``B = ''.join(<LIT>)`` →
        ``A = f'LIT{X}'``, e ogni uso EMBEDDED del valore di B (il join)
        negli statement successivi diventa un riferimento ad A — il nome
        che il sorgente originale usa (``get(B)`` → ``get(A)``)."""
        def join_lit(jval):
            if isinstance(jval, NdxSV) and jval.op == 'nativecall' and \
                    isinstance(jval.b, list):
                for a in jval.b:
                    if isinstance(a, NdxSV) and a.op == 'const' and \
                            isinstance(a.a, str):
                        return a.a
            if isinstance(jval, NdxSV) and jval.op == 'const' and \
                    isinstance(jval.a, str):
                return jval.a
            if isinstance(jval, NdxSV) and jval.op == 'tuple_build' and \
                    isinstance(jval.b, list) and len(jval.b) == 1 and \
                    isinstance(jval.b[0], NdxSV) and \
                    jval.b[0].op == 'const' and isinstance(jval.b[0].a, str):
                return jval.b[0].a
            return None

        def _walk_sv(sym, name, target, cnt):
            if not isinstance(sym, NdxSV):
                return
            if target is not None and sym is target:
                cnt[0] += 1
            if sym.op == 'var' and sym.a == name:
                cnt[0] += 1
            for f in ('a', 'b', 'c'):
                v = getattr(sym, f, None)
                if isinstance(v, NdxSV):
                    _walk_sv(v, name, target, cnt)
                elif isinstance(v, list):
                    for g in v:
                        if isinstance(g, NdxSV):
                            _walk_sv(g, name, target, cnt)

        # Un temp con valore PURO i cui usi cadono TUTTI dentro
        # espressioni f-string successive è l'espressione inline del
        # sorgente (``f"...{x * K}..."``): droppa l'assign e inlinea il
        # valore (per identità o via temp_inline per i riferimenti nome).
        try:
            inlined = set()
            ti = getattr(self.S, 'temp_inline', None)
            if ti is None:
                ti = self.S.temp_inline = {}
            for idx, st in enumerate(stmts):
                if st is None or st.kind != 'assign' or \
                        not isinstance(st.a, str) or \
                        not isinstance(st.b, NdxSV) or \
                        st.b.op not in ('binop', 'unary', 'cmp', 'len',
                                        'sub', 'getattr', 'attr', 'iter'):
                    continue
                ident_hits = [0]
                name_hits = [0]
                for later in stmts[idx + 1:]:
                    if later is None:
                        continue
                    for f in ('a', 'b', 'c', 'd', 'e'):
                        v = getattr(later, f, None)
                        if isinstance(v, NdxSV) and v.op == 'fstring':
                            _walk_sv(v, st.a, st.b, ident_hits)
                        elif isinstance(v, list):
                            for g in v:
                                if isinstance(g, NdxSV) and \
                                        g.op == 'fstring':
                                    _walk_sv(g, st.a, st.b, ident_hits)
                # due conteggi: usi per NOME dentro fstring vs usi per
                # IDENTITÀ dell'RHS (il binop embeddato direttamente)
                name_only = [0]
                ident_hits = [0]
                for later in stmts[idx + 1:]:
                    if later is None:
                        continue
                    for f in ('a', 'b', 'c', 'd', 'e'):
                        v = getattr(later, f, None)
                        if isinstance(v, NdxSV) and v.op == 'fstring':
                            _walk_sv(v, st.a, None, name_only)
                            _walk_sv(v, st.a, st.b, ident_hits)
                        elif isinstance(v, list):
                            for g in v:
                                if isinstance(g, NdxSV) and \
                                        g.op == 'fstring':
                                    _walk_sv(g, st.a, None, name_only)
                                    _walk_sv(g, st.a, st.b, ident_hits)
                ident = ident_hits[0] - name_only[0]
                total = self._count_uses(stmts[idx + 1:], st.a)
                if ident > 0 and total == 0:
                    inlined.add(id(st))
                elif name_only[0] > 0 and name_only[0] >= total:
                    ti[st.a] = st.b
                    inlined.add(id(st))
            if inlined:
                dropped_names = {st.a for st in stmts
                                 if st is not None and id(st) in inlined}
                stmts = [st for st in stmts if id(st) not in inlined]
                for attr in ('_live_names', '_defined_names'):
                    nm_set = getattr(self, attr, None)
                    if isinstance(nm_set, set):
                        nm_set -= dropped_names
        except Exception:
            pass

        out = []
        i = 0
        while i < len(stmts):
            st = stmts[i]
            nxt = stmts[i + 1] if i + 1 < len(stmts) else None
            if st is not None and st.kind == 'assign' and \
                    isinstance(st.b, NdxSV) and st.b.op == 'format' and \
                    nxt is not None and nxt.kind == 'assign' and \
                    isinstance(nxt.b, NdxSV) and nxt.b.op == 'str_join' and \
                    isinstance(nxt.b.a, NdxSV) and nxt.b.a.op == 'const' and \
                    nxt.b.a.a == '' and \
                    self._count_uses(stmts[i + 2:], nxt.a) == 0:
                lit = join_lit(nxt.b.b)
                if isinstance(lit, str):
                    jk_key = None
                    try:
                        jk_key = sv_key(nxt.b)
                    except Exception:
                        jk_key = None
                    st.b = ndx_k('fstring', [ndx_k('const', lit), st.b])
                    if jk_key is not None:
                        def rewrite(sym, _k=jk_key, _nm=st.a):
                            if not isinstance(sym, NdxSV):
                                return sym
                            if sym.op not in ('var', 'loc') and \
                                    self._sv_key_eq(sym, _k):
                                return NdxSV('var', _nm)
                            for f in ('a', 'b', 'c', 'n'):
                                v = getattr(sym, f, None)
                                if isinstance(v, NdxSV):
                                    setattr(sym, f, rewrite(v))
                                elif isinstance(v, list):
                                    setattr(sym, f, [
                                        rewrite(g) if isinstance(g, NdxSV)
                                        else g for g in v])
                            return sym
                        for later in stmts[i + 2:]:
                            if later is None:
                                continue
                            for f in ('a', 'b', 'c', 'd', 'e'):
                                v = getattr(later, f, None)
                                if isinstance(v, NdxSV):
                                    setattr(later, f, rewrite(v))
                                elif isinstance(v, list):
                                    setattr(later, f, [
                                        rewrite(g) if isinstance(g, NdxSV)
                                        else g for g in v])
                    out.append(st)
                    i += 2
                    continue
            out.append(st)
            i += 1
        return out

    def _rename_to_varnames(self, stmts):
        """Dopo le fusioni, le variabili locali superstiti vengono
        rinominate coi varnames originali in ordine di prima apparizione:
        è il naming lazy del sorgente, rifatto SENZA i simboli
        intermedi del lowering (pezzi f-string, gradini di catena) che
        ne slittavano l'ordine — ``balance_btc`` → ``response``,
        ``_v3`` → ``data``."""
        if getattr(self, '_rename_done', False):
            return stmts
        self._rename_done = True
        # The pipeline runs once per BLOCK (nested blocks get their own
        # renderer instance).  The positional rename is a whole-FUNCTION
        # operation — its `collect` already walks nested statements — so
        # re-running it per block would rename already-renamed targets
        # starting from free[0] again and shift every local.  Gate it on
        # the shared Structurer (one per function).
        if getattr(self.S, '_rename_done', False):
            return stmts
        self.S._rename_done = True
        # I for comprehension-shaped NON consumano varname: il loro
        # target vive nello scope della comprehension (fold successivo),
        # consumarli slitta ogni locale successivo di una posizione.
        self._mark_comp_targets(stmts)
        ac = getattr(self, 'argcount', 0) or 0
        # co_varnames entries are this function's own locals: keep them all
        # in the naming pool (embedded ``var`` uses are reads of these same
        # locals, not outer bindings).  Only genuine freevars are reserved.
        reserved = set(getattr(self.S.L, 'freevars', ()) or ())
        free = [v for v in (self.varnames or [])[ac:] if v not in reserved]
        if not free:
            return stmts
        order = []
        order_late = []     # (temp, for_stmt) dei for comprehension-shaped

        def collect(st):
            if st is None:
                return
            # V100: il target di un ``for`` è un binding del sorgente e
            # occupa il suo posto in co_varnames (ordine di prima
            # assegnazione).  Saltarlo slittava ogni locale successivo
            # di una posizione (``key`` → ``row``, ``_v1`` → ``key``).
            # I for comprehension-shaped fanno eccezione: il loro target
            # vive nello scope della comprehension — riceve un nome solo
            # DOPO tutti i binding normali, così non li sfalsa.
            if st.kind in ('assign', 'for') and isinstance(st.a, str) \
                    and st.a not in order \
                    and not (st.kind == 'for' and
                             id(st) in self._comp_targets):
                order.append(st.a)
            elif st.kind == 'for' and isinstance(st.a, str) and \
                    id(st) in self._comp_targets and \
                    all(st is not g for _n, g in order_late):
                order_late.append((st.a, st))
            if st.kind == 'unpack_ex':
                order.extend(n for n in st.a if n not in order)
            for f in ('a', 'b', 'c', 'd', 'e'):
                v = getattr(st, f, None)
                if isinstance(v, list):
                    for g in v:
                        if hasattr(g, 'kind'):
                            collect(g)

        for st in stmts:
            collect(st)
        mapping = {}
        for i, nm in enumerate(order):
            if i < len(free) and nm != free[i] and \
                    not nm.startswith('__'):
                mapping[nm] = free[i]
        # Nomi per i target delle comprehension: pool residuo, ma se una
        # comprehension precedente itera lo STESSO iterable riusa il suo
        # nome di loop (il sorgente riusa la variabile; scope della comp
        # rende il riuso sicuro) — rimette ``for value in`` al posto di
        # ``for index in`` nel secondo comprehension sulla stessa lista.
        used_names = {free[i] for i in range(len(order)) if i < len(free)}
        used_names |= set(mapping.values())
        it_names = {}
        pos = len(order)
        for nm, fst in order_late:
            ik = None
            if fst.b is not None:
                try:
                    ik = sv_key(fst.b)
                except Exception:
                    ik = ('id', id(fst.b))
            if ik is not None and ik in it_names:
                target = it_names[ik]
            else:
                target = self._match_comp_loop_name(fst)
                if target is not None:
                    used_names.add(target)
            if target is None:
                while pos < len(free):
                    cand = free[pos]
                    pos += 1
                    if cand not in used_names and \
                            not cand.startswith('__'):
                        target = cand
                        break
                if target is None:
                    continue
                used_names.add(target)
            if ik is not None:
                it_names.setdefault(ik, target)
            if nm != target:
                mapping[nm] = target
        if not mapping:
            return stmts
        # i dizionari nome→valore del Structurer guidano la sostituzione
        # dei simboli embedded al rendering: vanno rinominati COERENTEMENTE
        # con gli statement, altrimenti LHS nuovo e RHS vecchio
        for d in (getattr(self.S, 'sym_names', None),
                  getattr(self.S, 'sym_keys', None)):
            if isinstance(d, dict):
                for k in list(d):
                    if d[k] in mapping:
                        d[k] = mapping[d[k]]
        vn = getattr(self.S, 'var_names', None)
        if isinstance(vn, dict):
            for k in list(vn):
                if vn[k] in mapping:
                    vn[k] = mapping[vn[k]]

        def ren_sym(s, _seen=None):
            if not isinstance(s, NdxSV):
                return
            # V100: il grafo SV può essere ciclico (phi/loc riusati):
            # senza visited-set la rinomina esplode in RecursionError e
            # l'intero corpo va perso. Il rename per-id è idempotente.
            if _seen is None:
                _seen = set()
            if id(s) in _seen:
                return
            _seen.add(id(s))
            if s.op in ('var', 'loc') and isinstance(s.a, str) and \
                    s.a in mapping:
                s.a = mapping[s.a]
                return
            for f in ('a', 'b', 'c', 'n'):
                v = getattr(s, f, None)
                if isinstance(v, NdxSV):
                    ren_sym(v, _seen)
                elif isinstance(v, list):
                    for g in v:
                        if isinstance(g, NdxSV):
                            ren_sym(g, _seen)

        def ren_st(st):
            if st is None:
                return
            # V100: anche il target di un ``for`` è rinominabile (è un
            # binding sorgente come gli assign — vedi collect()).
            if st.kind in ('assign', 'for') and isinstance(st.a, str) \
                    and st.a in mapping:
                st.a = mapping[st.a]
            for f in ('a', 'b', 'c', 'd', 'e'):
                v = getattr(st, f, None)
                if isinstance(v, NdxSV):
                    ren_sym(v)
                elif isinstance(v, list):
                    for g in v:
                        if isinstance(g, NdxSV):
                            ren_sym(g)
                        elif hasattr(g, 'kind'):
                            ren_st(g)

        for st in stmts:
            ren_st(st)
        return stmts

    def _fuse_iterable_temps(self, stmts):
        """V100: ``X = expr; for v in X:`` — la temporanea dell'iterabile
        non è sorgente. Fonde quando l'iterabile del for è la variabile
        assegnata (per ``loc`` vale il nome corrente della locazione,
        non lo slot fisico) oppure è strutturalmente identico (stesso
        sv_key) all'RHS dell'assegnamento che precede — il caso
        assegnamento ridondante prodotto dal value-numbering. Corre
        PRIMA della rinomina posizionale così il target del for riceve
        il varname giusto dal pool."""
        for i2, st in enumerate(stmts):
            if st is None or st.kind != 'assign' or \
                    not isinstance(st.b, NdxSV) or \
                    i2 + 1 >= len(stmts) or \
                    stmts[i2 + 1] is None or \
                    stmts[i2 + 1].kind != 'for':
                continue
            nxt = stmts[i2 + 1]
            if not isinstance(nxt.b, NdxSV):
                continue
            if nxt.b.op not in ('var', 'loc'):
                # assegnamento ridondante da value-numbering: l'iterabile
                # del for è strutturalmente identico (stesso sv_key)
                # all'RHS dell'assegnamento che precede. Solo per RHS
                # PURI (letterali/attributi/nomi): una call con lo stesso
                # sv_key può essere una vera doppia valutazione del
                # sorgente — fondere cambierebbe la semantica.
                _PURE_RHS_OPS = frozenset((
                    'const', 'imm', 'none', 'var', 'loc', 'par', 'global',
                    'getattr', 'list_empty', 'dict_empty', 'set_empty',
                    'list_build', 'dict_build', 'set_build', 'tuple_build',
                    'fstring'))
                if st.b.op in _PURE_RHS_OPS:
                    try:
                        if self._sv_key_eq(nxt.b, sv_key(st.b)):
                            stmts[i2] = None
                    except Exception:
                        pass
                continue
            _nxt_a = getattr(nxt.b, 'a', None)
            _iter_is_tmp = _nxt_a == st.a or (
                nxt.b.op == 'loc' and isinstance(_nxt_a, tuple) and
                (getattr(self.S, 'var_names', None) or {}).get(_nxt_a)
                == st.a)
            if _iter_is_tmp:
                nxt.b = st.b
                stmts[i2] = None
        return [s for s in stmts if s is not None]

    def _promote_tail_returns(self, stmts):
        """Keep the return at its proven control-flow position.

        Equal expression keys (or equal callees) do not prove that a value
        should be returned from a nested suite.  In particular a loop may
        run zero or many times, and the other branch of an if may carry a
        different result.  Constant join returns are reconstructed by
        _restore_constant_returns using their actual incoming CFG edges.
        """
        return stmts

    def _fix_dispatch_polarity(self, stmts):
        """Catena match/case (``match network: case 'k':``): Nuitka la
        compila come dispatch di confronti e il lifter struttura il corpo
        del case-k nel ramo ``!= case-k``. Se in tutto il body la STESSA
        variabile (parametro o locale) è confrontata con ≥2 costanti
        stringa distanti e TUTTI i confronti sono ``!=``, è un dispatch
        match: la polarità si inverte (``!=`` → ``==``) e i corpi tornano
        ai case del sorgente. I confronti con costanti non-stringa
        (``balance != -1``) restano al loro posto."""
        CMP_INV = {'ne': 'eq'}

        def cond_parts(sym):
            if isinstance(sym, NdxSV) and sym.op == 'cmp' and \
                    sym.a in CMP_INV:
                left, right = sym.b, sym.c
                for x, y in ((left, right), (right, left)):
                    if isinstance(x, NdxSV) and x.op != 'const' and \
                            isinstance(y, NdxSV) and y.op == 'const' and \
                            isinstance(y.a, str):
                        if x.op in ('var', 'loc', 'par'):
                            return (x.op, x.a), y.a
                        # soggetto strutturale (es. next(iter(X)) nel
                        # corpo di un for): l'identità è la sua chiave
                        try:
                            return ('sv', sv_key(x)), y.a
                        except Exception:
                            return None, None
            return None, None

        per_var = {}

        def collect(st):
            if st is None or not hasattr(st, 'kind'):
                return
            if st.kind == 'if' and isinstance(st.a, NdxSV):
                var, const = cond_parts(st.a)
                if var is not None:
                    per_var.setdefault(var, []).append((st.a, const))
            for f in ('a', 'b', 'c', 'd', 'e'):
                v = getattr(st, f, None)
                if isinstance(v, list):
                    for g in v:
                        collect(g)
                elif isinstance(v, NdxSV):
                    pass

        def walk_syms(st):
            """Raccogli anche le cond annidate dentro espressioni."""
            pass

        for st in stmts:
            collect(st)

        for var, entries in per_var.items():
            consts = {c for _s, c in entries}
            if len(entries) >= 2 and len(consts) >= 2:
                for sym, _c in entries:
                    sym.a = CMP_INV.get(sym.a, sym.a)
        return stmts

    def _promote_expr_conditions(self, stmts, _seen_bodies=None):
        """Promuove a CONDIZIONE dell'if il test che il lowering nativo
        valuta come statement separato: (a) l'espressione booleana seguita
        da ``if <var>`` non riassegnata (``address in data`` → ``if
        address in data:``); (b) l'assegnazione single-use di un confronto
        consumata dall'if (``t = x == 200; if t:`` → ``if x == 200:``).
        Agisce ricorsivamente nei body annidati.

        V100 SPEED FIX: il vecchio codice processava OGNI body annidato due
        volte (una nel pre-pass e una nel loop principale dopo la
        promozione) e la ricorsione raddoppiava a ogni livello di
        annidamento: sui body profondi dello structurer il costo diventava
        esponenziale (misurato: ~90% del runtime NDX totale, 2.3s per
        chiamata).  Il seen-set garantisce che ogni body venga promosso
        ESATTAMENTE UNA volta per invocazione top-level: stesso risultato
        (il pre-pass aveva gia' fissato i body prima del loop), costo
        lineare."""
        if _seen_bodies is None:
            _seen_bodies = set()

        def fix_body(body):
            if isinstance(body, list) and \
                    not any(isinstance(x, tuple) for x in body):
                key = id(body)
                if key in _seen_bodies:
                    return
                _seen_bodies.add(key)
                fixed = self._promote_expr_conditions(
                    body, _seen_bodies=_seen_bodies)
                body[:] = fixed
        # pre-pass ricorsivo: le promozioni annidate eliminano usi di var
        # che il livello esterno conta per la propria single-use check.
        # (i body del try contengono tuple-handler `(types, body, line)`,
        # non statement: mai toccarli qui)
        for st in stmts:
            if st is not None and hasattr(st, 'kind'):
                for attr in ('b', 'c', 'd', 'e'):
                    fix_body(getattr(st, attr, None))
        out = []
        i = 0
        while i < len(stmts):
            st = stmts[i]
            if st is None or not hasattr(st, 'kind'):
                out.append(st)
                i += 1
                continue
            nxt = stmts[i + 1] if i + 1 < len(stmts) else None
            # (a) statement-expr booleano + if con condizione stantia
            if st is not None and st.kind == 'expr' and \
                    isinstance(st.a, NdxSV) and \
                    st.a.op in ('contains', 'cmp', 'bool', 'not') and \
                    nxt is not None and nxt.kind == 'if' and \
                    isinstance(nxt.a, NdxSV):
                _promote = False
                if nxt.a.op in ('var', 'loc') and \
                        isinstance(nxt.a.a, str):
                    cond_var = nxt.a.a
                    _promote = not any(
                        later is not None and later.kind == 'assign' and
                        later.a == cond_var for later in stmts[i:])
                else:
                    # cond embedded: se NON contiene questo test, è la
                    # condizione spillata di un if ESTERNO riusata dal
                    # ramo freddo — il test vero è l'espressione
                    try:
                        _ek = sv_key(st.a)
                    except Exception:
                        _ek = None
                    if _ek is not None:
                        _box = [False]
                        self._sv_walk(
                            nxt.a,
                            lambda s, _b=_box, _k=_ek: _b.__setitem__(
                                0, _b[0] or self._sv_key_eq(s, _k)))
                        _promote = not _box[0]
                if _promote:
                    nxt.a = st.a
                    fix_body(nxt.b)
                    fix_body(nxt.c)
                    out.append(nxt)
                    i += 2
                    continue
            # (b) assegnazione single-use di un test immediatamente prima
            # di un if: il test È la condizione (var-ref da sostituire,
            # oppure cond embedded che la contiene già in altra forma) —
            # la riga dell'assign è sempre un doppione del lowering
            if st is not None and st.kind == 'assign' and \
                    isinstance(st.a, str) and \
                    isinstance(st.b, NdxSV) and \
                    st.b.op in ('contains', 'cmp', 'bool', 'not') and \
                    nxt is not None and nxt.kind == 'if' and \
                    isinstance(nxt.a, NdxSV) and \
                    self._count_uses(stmts[i + 1:], st.a) <= 1:
                if nxt.a.op in ('var', 'loc') and nxt.a.a == st.a:
                    nxt.a = st.b
                fix_body(nxt.b)
                fix_body(nxt.c)
                out.append(nxt)
                i += 2
                continue
            if st is not None:
                for attr in ('b', 'c', 'd', 'e'):
                    fix_body(getattr(st, attr, None))
            out.append(st)
            i += 1
        return out

    def _drop_embedded_temps(self, stmts):
        """Rimuove le assegnazioni il cui VALORE è già embedded
        strutturalmente in un ASSEGNAMENTO consumer successivo (inline
        del lowering Nuitka) e il cui nome non è MAI referenziato: la
        riga resterebbe fantasma e il suo nome spezzerebbe la catena già
        fusa (``A = f()``; ``B = A.attr``; ``C = B(x)`` → ``C = f().attr(x)``).
        Selettivo per non svuotare i corpi: solo nodi mcall/getattr (i
        gradini intermedi di una chain), MAI call (il risultato finale
        appartiene al sorgente), e SOLO consumer assegnamento (if/return
        mantengono il nome, come nell'originale). I pezzi di f-string
        (format/str_join) restano righe per la fusione del cleaner."""
        def assign_keys_after(i):
            ks = set()
            for j in range(i + 1, len(stmts)):
                st2 = stmts[j]
                if st2 is None or st2.kind not in ('assign', 'store_sub')\
                        or not isinstance(st2.b, NdxSV):
                    continue
                def visit(sym):
                    if isinstance(sym, NdxSV) and sym.op not in (
                            'var', 'loc'):
                        try:
                            ks.add(sv_key(sym))
                        except Exception:
                            pass
                self._stmt_walk(st2, visit)
            return ks

        out = []
        for i, st in enumerate(stmts):
            if st is not None and st.kind == 'assign' and \
                    isinstance(st.a, str) and isinstance(st.b, NdxSV) and \
                    st.b.op in ('mcall', 'getattr', 'pyformat'):
                try:
                    vk = sv_key(st.b)
                except Exception:
                    vk = None
                if vk is not None and vk in assign_keys_after(i):
                    rest = stmts[i + 1:]
                    if self._count_uses(rest, st.a) == 0:
                        continue
            out.append(st)
        return out

    _CONTAINER_OPS = ('list_empty', 'list_build', 'dict_empty', 'dict_build',
                      'set_empty')

    def _fold_comprehensions(self, stmts):
        """Desugared comprehension → comprehension literal (tree level).

        Nuitka lowers ``[e for v in it if c]`` to: build the receiver
        container, for-loop over the iterator, optional condition, one
        append/setadd/dict-store onto the container, loop exits as
        ``break``.  A ``for`` whose body matches exactly that shape (plus
        loop-local temps, inlined into condition/element) folds back to
        ``NAME = [e for v in it if c]`` — NAME taken from the container's
        own assignment when one exists (the receiver's source name), so
        every later reference to the container stays bound to it."""
        cont_assigns = {}
        for i, s in enumerate(stmts):
            if s is not None and s.kind == 'assign' and \
                    isinstance(s.a, str) and isinstance(s.b, NdxSV) and \
                    s.b.op in self._CONTAINER_OPS:
                key = s.b.n if getattr(s.b, 'n', None) is not None \
                    else id(s.b)
                cont_assigns.setdefault(key, (i, s.a, s))
        self._mark_comp_targets(stmts)
        self._fold_root = stmts
        out = []
        for fi, st in enumerate(stmts):
            if st is None or st.kind == 'dead':
                continue
            if st.kind == 'for':
                folded = self._try_fold_comprehension(st, cont_assigns,
                                                      for_index=fi)
                if folded is not None:
                    out.append(folded)
                    continue
                # for marcato comprehension-shaped ma non ripiegabile
                # (corpo complesso): il target resta un for sorgente
                # vero — ripristina un nome sorgente non consumato,
                # altrimenti rende ``for _vN in ...`` senza binding.
                self._rename_comp_for_target(st)
            # campi corpo per kind: if→b/c, for→c (b=iterabile),
            # while→b (c=id blocco join, NON una lista: recursarci
            # distrugge l'intero corpo con un TypeError silenzioso).
            if st.kind == 'if':
                if isinstance(st.b, list):
                    st.b = self._fold_comprehensions(st.b)
                if isinstance(st.c, list):
                    st.c = self._fold_comprehensions(st.c)
            elif st.kind == 'for':
                if isinstance(st.c, list):
                    st.c = self._fold_comprehensions(st.c)
            elif st.kind == 'while':
                if isinstance(st.b, list):
                    st.b = self._fold_comprehensions(st.b)
            out.append(st)
        out = [s for s in out if s is not None and s.kind != 'dead']
        _consumed = getattr(self, '_consumed_assign_ids', None)
        if _consumed:
            out = [s for s in out if id(s) not in _consumed]
        return out

    def _mark_comp_targets(self, stmts):
        """Marca i for riaggomigliati a comprehension desugurate.

        Il target di quel for NON è un binding del sorgente (la
        comprehension dichiara la sua variabile nel proprio scope): non
        deve consumare un posto in co_varnames in ``_rename_to_varnames``,
        altrimenti ogni locale successivo slitta di una posizione.
        Riconoscimento: corpo = append/setadd/store_sub unici (eventuale
        guard ``if`` con braccio-else di soli break, temp e probe di
        protocollo) che scrive in un container allocato dall'assign
        IMMEDIATAMENTE precedente (il ricevitore del comprehension)."""
        found = getattr(self, '_comp_targets', None)
        if found is None:
            found = self._comp_targets = set()
        cops = self._CONTAINER_OPS

        def cont_key(sv):
            n = getattr(sv, 'n', None)
            return n if n is not None else id(sv)

        def is_comp_for(fst, prev):
            acts = []
            for s in (fst.c or []):
                if s is None:
                    continue
                k = getattr(s, 'kind', None)
                if k in ('break', 'assign', 'expr', 'raw'):
                    continue
                if k in ('append', 'setadd', 'store_sub'):
                    acts.append(s)
                    continue
                if k == 'if':
                    inner = [x for x in (s.b or [])
                             if getattr(x, 'kind', None) in
                             ('append', 'setadd', 'store_sub')]
                    acts.extend(inner)
                    if len(inner) > 1:
                        return False
                    if s.c and any(getattr(x, 'kind', None) != 'break'
                                   for x in s.c if x is not None):
                        return False
                    continue
                return False
            if len(acts) != 1:
                return False
            cont = getattr(acts[0], 'a', None)
            if not (hasattr(cont, 'op') and cont.op in cops):
                return False
            # ricevitore = assign container adiacente prima del for
            return (prev is not None and prev.kind == 'assign' and
                    isinstance(prev.b, NdxSV) and prev.b.op in cops and
                    cont_key(prev.b) == cont_key(cont))

        def walk(lst):
            for j, s in enumerate(lst):
                if s is None:
                    continue
                # clausole try: (types, body, line) — attraversa
                # anche il body della clausola
                if isinstance(s, tuple):
                    if len(s) == 3 and isinstance(s[1], list):
                        walk(s[1])
                    continue
                if not hasattr(s, 'kind'):
                    continue
                if s.kind == 'for' and \
                        is_comp_for(s, lst[j - 1] if j else None):
                    found.add(id(s))
                for f in ('b', 'c'):
                    v = getattr(s, f, None)
                    if isinstance(v, list):
                        walk(v)

        walk(stmts)

    def _match_comp_loop_name(self, fst):
        """Nome della variabile di loop di una comprehension desugurata.

        Il nome vive SOLO nel code object della comprehension
        (``co_varnames = ['.0', name]``) — il parent non lo ha.  L'aggancio
        al sito inline usa la linea: il for desugurato eredita la linea del
        blocco nativo, il code object ha la firstlineno del sorgente.
        Senza linea nota il matching sequenziale si usa solo se esiste un
        solo candidato (nessuna inventa: il nome esce dal blob)."""
        pool = getattr(self, '_comp_cos', None)
        if not pool:
            return None
        used = getattr(self, '_comp_cos_used', None)
        if used is None:
            used = self._comp_cos_used = set()

        def loop_name(c):
            names = [v for v in (getattr(c, 'varnames', None) or [])[1:]
                     if isinstance(v, str) and v.isidentifier()]
            return names[0] if len(names) == 1 else None

        cand = [c for c in pool if id(c) not in used and
                loop_name(c) is not None]
        if not cand:
            return None
        pick = None
        line = getattr(fst, 'line', None)
        if line:
            near = [c for c in cand
                    if abs((getattr(c, 'firstlineno', 0) or 0) - line) <= 3]
            if len(near) == 1:
                pick = near[0]
            elif near:
                pick = min(near, key=lambda c: abs(
                    (getattr(c, 'firstlineno', 0) or 0) - line))
        if pick is None and len(cand) == 1:
            pick = cand[0]
        if pick is None:
            return None
        used.add(id(pick))
        return loop_name(pick)

    def _fresh_comp_name(self, avoid=()):
        """Primo varname sorgente non consumato da alcun binding
        dell'albero (co_varnames è ordinato come il sorgente: il nome
        scelto è quello con migliori probabilità di essere l'originale),
        o None se non c'è nulla di sicuro."""
        ac = getattr(self, 'argcount', 0) or 0
        reserved = set(getattr(getattr(self, 'S', None), 'L', None)
                       and self.S.L.freevars or ())
        bound = set(avoid)

        def walk(st):
            if st is None or not hasattr(st, 'kind'):
                return
            if st.kind in ('assign', 'for') and isinstance(st.a, str):
                bound.add(st.a)
            for f in ('b', 'c', 'd', 'e'):
                v = getattr(st, f, None)
                if isinstance(v, list):
                    for g in v:
                        walk(g)
                elif v is not None:
                    walk(v)

        for root in (getattr(self, '_fold_root', None) or ()):
            walk(root)
        cand = [v for v in (getattr(self, 'varnames', None) or [])[ac:]
                if v not in bound and v not in reserved and
                not v.startswith('_')]
        return cand[0] if cand else None

    def _rename_comp_for_target(self, st):
        """For marcato comprehension-shaped ma NON ripiegabile: ripristina
        un nome sorgente per il suo target, rinominando COERENTEMENTE i
        riferimenti embedded (stessa disciplina di ``_rename_to_varnames``:
        dizionari nome→valore del Structurer + grafo SV con visited-set)."""
        old = st.a
        if not (isinstance(old, str) and old.startswith('_')):
            return
        new = self._fresh_comp_name(avoid=(old,))
        if not new or new == old:
            return
        mapping = {old: new}
        for d in (getattr(self.S, 'sym_names', None),
                  getattr(self.S, 'sym_keys', None)):
            if isinstance(d, dict):
                for k in list(d):
                    if d[k] in mapping:
                        d[k] = mapping[d[k]]
        vn = getattr(self.S, 'var_names', None)
        if isinstance(vn, dict):
            for k in list(vn):
                if vn[k] in mapping:
                    vn[k] = mapping[vn[k]]

        def ren_sym(s, _seen=None):
            if not isinstance(s, NdxSV):
                return
            if _seen is None:
                _seen = set()
            if id(s) in _seen:
                return
            _seen.add(id(s))
            if s.op in ('var', 'loc') and isinstance(s.a, str) and \
                    s.a in mapping:
                s.a = mapping[s.a]
                return
            for f in ('a', 'b', 'c', 'n'):
                v = getattr(s, f, None)
                if isinstance(v, NdxSV):
                    ren_sym(v, _seen)
                elif isinstance(v, list):
                    for g in v:
                        if isinstance(g, NdxSV):
                            ren_sym(g, _seen)

        def ren_st(x):
            if x is None or not hasattr(x, 'kind'):
                return
            if x.kind in ('assign', 'for') and isinstance(x.a, str) and \
                    x.a in mapping:
                x.a = mapping[x.a]
            for f in ('a', 'b', 'c', 'd', 'e'):
                v = getattr(x, f, None)
                if isinstance(v, list):
                    for g in v:
                        ren_st(g)
                elif v is not None:
                    if isinstance(v, NdxSV):
                        ren_sym(v)
                    elif hasattr(v, 'kind'):
                        ren_st(v)

        ren_st(st)

    def _container_var_name(self, sym, depth=0):
        """Nome della variabile a cui un container letterale e' legato
        (``rows = []`` assegnato a monte): risolve via symbol_locations
        del lifter e var_names/authoritative_loc_names dello structurer.
        Senza questo, le append recuperate rendono ``[].append(x)``
        invece di ``rows.append(x)``."""
        if depth > 3 or not isinstance(sym, NdxSV):
            return None
        S = getattr(self, 'S', None)
        L = getattr(S, 'L', None)
        symlocs = getattr(L, 'symbol_locations', None)
        if not symlocs:
            return None
        try:
            key = sv_key(sym)
        except Exception:
            return None
        locs = symlocs.get(key)
        if not locs:
            # Module-init containers without a proven variable location are
            # source literals (``f([])`` whose native lowering copied the
            # argument vector): the positional fallback would invent a name
            # with no definition.  Function bodies keep the fallback.
            if getattr(L, 'is_module_code', False):
                return None
        vn = getattr(S, 'var_names', None) or {}
        aln = getattr(S, 'authoritative_loc_names', None) or {}
        aln2 = getattr(L, 'authoritative_loc_names', None) or {}
        for loc in locs:
            nm = vn.get(loc) or aln.get(loc) or aln2.get(loc)
            if isinstance(nm, str) and nm.isidentifier():
                return nm
        # fallback posizionale: co_varnames ordina le locali come il
        # sorgente; i container letterali (in ordine di blocco) prendono
        # i nomi residui nello stesso ordine.  Stessa classe di evidenza
        # del rename posizionale: nessun nome inventato.
        ac = 0
        try:
            ac = int(L.argcount)
        except Exception:
            pass
        pool = [v for v in (getattr(self, 'varnames', None) or [])[ac:]
                if isinstance(v, str) and v.isidentifier() and
                not v.startswith('_')]
        seq = getattr(self, '_container_name_seq', None)
        if seq is None:
            seq = []
            _blocks = getattr(L, 'blocks', {}) or {}
            for st in sorted(_blocks):
                for o in _blocks[st].ops:
                    sv = getattr(o, 'a', None)
                    if o.kind == 'calc' and isinstance(sv, NdxSV) and \
                            sv.op in ('list_empty', 'dict_empty', \
                                      'set_empty'):
                        seq.append(id(sv))
            self._container_name_seq = seq
        used = getattr(self, '_container_name_used', None)
        if used is None:
            used = self._container_name_used = set()
        pos = seq.index(id(sym)) if id(sym) in seq else None
        if pos is not None and pos < len(pool):
            used.add(pool[pos])
            return pool[pos]
        return None

    def _try_fold_comprehension(self, st, cont_assigns=None,
                                for_index=None):
        # auto-iterazione: il for itera il proprio ricevitore
        # (``for rows in rows``) — artefatto del latch strutturato,
        # mai una comprehension del sorgente
        _its = getattr(st, 'b', None)
        if _its is not None and hasattr(_its, 'op'):
            try:
                if _its.op == 'var' and _its.a == st.a:
                    return None
                if _its.op in ('list_empty', 'dict_empty', 'set_empty',
                               'list_build', 'dict_build', 'tuple_build'):
                    # iterare un container appena allocato e scriverci
                    # dentro e' il mangle del latch, non una comprehension
                    return None
                if _its.op == 'loc' and isinstance(_its.a, tuple) and \
                        _its.a and _its.a[0] == 'reg':
                    # iterabile tenuto in un REGISTRO: e' l'oggetto
                    # iteratore del lowering (range/seq specializzato),
                    # mai un iterabile di sorgente
                    return None
                if _its.op == 'loc' and \
                        self.S.name_of_loc(_its.a) == st.a:
                    return None
            except Exception:
                pass
        body = st.c or []
        recv = None
        inner_if = None
        temps = []
        probes = []

        def _arm_is_breaks(lst):
            return all(s.kind == 'break' for s in lst)

        for s in body:
            k = s.kind
            if k == 'break':
                continue
            if k in ('append', 'setadd', 'store_sub'):
                if recv is not None:
                    return None
                recv = s
            elif k == 'if':
                if inner_if is not None:
                    return None
                if s.b and not all(
                        s2.kind in ('append', 'setadd', 'store_sub',
                                    'break') for s2 in s.b):
                    return None
                if s.c and not _arm_is_breaks(s.c):
                    return None
                inner_if = s
            elif k == 'assign' and isinstance(s.a, str):
                temps.append(s)
            elif k == 'for':
                # comp annidata: il for interno deve essere ripiegabile
                # a sua volta — il suo raw-testo diventa un temp del comp
                # esterno ([[e for c in row] for row in matrix])
                inner = self._try_fold_comprehension(s, cont_assigns)
                if inner is None or getattr(inner, 'kind', None) != 'raw':
                    return None
                temps.append(inner)
            elif k == 'raw' and isinstance(getattr(s, 'a', None), str) and \
                    re.match(r'\w+\s*=\s*.+', s.a):
                # comp già ripiegata (raw): è un temp testuale il cui
                # valore si inlinea nell'elemento del comp esterno
                temps.append(s)
            elif k == 'expr' and isinstance(s.a, NdxSV) and \
                    s.a.op in ('type_of', 'nativecall', 'binop', 'cmp',
                               'bool', 'not', 'unary', 'len', 'iter',
                               'next'):
                # CPython protocol probes (type/tag checks) the lowering
                # runs around the loop; they carry no source semantics.
                # Le expr PURE (binop/cmp/…) sono i calcoli dell'elemento
                # aliasati a registri SSA: servono come valore di soccorso
                # quando append/setadd perde il collegamento del registro.
                probes.append(s)
            else:
                return None
        if inner_if is not None:
            core = [s for s in (inner_if.b or [])
                    if s.kind not in ('break',)]
            if len(core) != 1:
                return None
            if recv is not None and recv is not core[0]:
                return None
            recv = core[0]
        if recv is None:
            return None
        # SSA-merge: il valore dell'elemento è rimasto vivo solo in un
        # registro aliasato (``loc(('reg', …))``): l'expr pura calcolata
        # SUBITO prima nel corpo è lo stesso valore (stesso registro) —
        # usala come elemento del comprehension invece del loc perduto.
        if isinstance(recv.b, NdxSV) and recv.b.op == 'loc' and \
                isinstance(recv.b.a, tuple) and recv.b.a and \
                recv.b.a[0] == 'reg':
            for _p in reversed(probes):
                _psv = getattr(_p, 'a', None)
                if isinstance(_psv, NdxSV) and _psv.op in (
                        'binop', 'cmp', 'bool', 'not', 'unary', 'next'):
                    recv = NdxSt(recv.kind, a=recv.a, b=_psv,
                                 line=getattr(recv, 'line', None),
                                 blocks=getattr(recv, 'blocks', None))
                    break
        cont = recv.a
        if not (isinstance(cont, NdxSV) and cont.op in (
                'list_empty', 'list_build', 'dict_empty', 'dict_build',
                'set_empty')):
            return None
        # nome del target del comp scelto PRIMA del rendering degli
        # elementi e registrato fra i nomi definiti/vivi: il value
        # numbering del renderer risolve così i ``next(iter(iterabile))``
        # dell'elemento al target del comp (fondamentale per le comp
        # annidate, dove l'elemento annida due next(iter(...)))
        _lv = st.a if isinstance(st.a, str) and str(st.a).startswith('_') \
            else None
        _nv = self._fresh_comp_name(avoid=()) if _lv else None
        _loop_name = _nv or _lv
        if _loop_name:
            for _attr in ('_defined_names', '_live_names'):
                _nmset = getattr(self, _attr, None)
                if isinstance(_nmset, set):
                    _nmset.add(_loop_name)
        self._fold_inline = True
        try:
            if recv.kind == 'store_sub':
                key_t = self.expr(recv.b, 2)
                elem_t = self.expr(recv.c, 2)
            else:
                key_t = None
                elem_t = self.expr(recv.b, 2)
            if not elem_t or (recv.kind == 'store_sub' and not key_t):
                return None
            cond_t = self.expr(inner_if.a, 2) if inner_if is not None                 else None
        finally:
            self._fold_inline = False
        for t in temps:
            if t.kind == 'raw':
                _m = re.match(r'(\w+)\s*=\s*(.+)$', t.a or '')
                if not _m:
                    continue
                _nm2, _rhs2 = _m.group(1), _m.group(2)
                _pat2 = re.compile(r'\b' + re.escape(_nm2) + r'\b')
                if cond_t:
                    cond_t = _pat2.sub('(' + _rhs2 + ')', cond_t)
                elem_t = _pat2.sub('(' + _rhs2 + ')', elem_t)
                if key_t:
                    key_t = _pat2.sub('(' + _rhs2 + ')', key_t)
                continue
            rhs = self.expr(t.b, 2) or ''
            nm = t.a
            if isinstance(nm, str) and nm and rhs:
                pat = re.compile(r'\b' + re.escape(nm) + r'\b')
                if cond_t:
                    cond_t = pat.sub('(' + rhs + ')', cond_t)
                elem_t = pat.sub('(' + rhs + ')', elem_t)
                if key_t:
                    key_t = pat.sub('(' + rhs + ')', key_t)
        free = getattr(self.S, '_free_names', None)
        key = getattr(cont, 'n', None)
        if key is None:
            key = id(cont)
        name = None
        if cont_assigns and key in cont_assigns:
            assign_index, name, assign_stmt = cont_assigns[key]
            # ADIACENZA: il ricevitore di una comprehension desugurata
            # e' allocato IMMEDIATAMENTE prima del loop.  Un container
            # allocato lontano (es. la lista di una funzione il cui for
            # e' stato mal strutturato) non e' una comprehension:
            # rifiuta il fold invece di fabbricarne uno sbagliato.
            if for_index is not None and \
                    abs(assign_index - for_index) > 3:
                return None
            # consume the receiver's own assignment in modo REVERSIBILE:
            # niente mutazione a 'dead' (persisterebbe nei passaggi
            # successivi anche quando il fold viene rifiutato, 
            # privando il container del suo nome); il filtro della
            # stessa passata rimuove la riga tramite il consumed-set.
            if name:
                consumed = getattr(self, '_consumed_assign_ids', None)
                if consumed is None:
                    consumed = self._consumed_assign_ids = set()
                consumed.add(id(assign_stmt))
        if not name:
            name = free.pop(0) if free else None
        if not name:
            self._comp_seq += 1
            name = f'_comp{self._comp_seq}'
        self.comp_names[key] = name
        # Il target del for desugurato è la variabile della comprehension:
        # se è ancora una temp, sostituiscigli un varname sorgente non
        # consumato (scope della comp: riusare un nome non binding è
        # legittimo e riporta il testo al sorgente).  Solo nelle stringhe
        # renderizzate — ``st.a`` resta intatto per coerenza con i
        # riferimenti embedded già risolti.
        lv = st.a if isinstance(st.a, str) else None
        if lv and lv.startswith('_'):
            nv = _nv if _nv else self._fresh_comp_name(avoid=(name,))
            if nv and nv != lv:
                pat_lv = re.compile(r'\b' + re.escape(lv) + r'\b')
                if cond_t:
                    cond_t = pat_lv.sub(nv, cond_t)
                elem_t = pat_lv.sub(nv, elem_t)
                if key_t:
                    key_t = pat_lv.sub(nv, key_t)
                lv = nv
        it_part = f'for {lv if lv is not None else st.a} in {self.expr(st.b, 2) or "None"}'
        tail = f' if {cond_t}' if cond_t else ''
        if recv.kind == 'store_sub':
            comp = f'{{{key_t}: {elem_t} {it_part}{tail}}}'
        elif recv.kind == 'setadd':
            comp = f'{{{elem_t} {it_part}{tail}}}'
        else:
            comp = f'[{elem_t} {it_part}{tail}]'
        return NdxSt('raw', a=f'{name} = {comp}', line=st.line,
                     blocks=st.blocks)

    def _restore_constant_returns(self, stmts):
        """Rebuild constant-return branches sharing one native epilogue."""
        prov = getattr(self.S.L, '_phi_inputs', {})
        out = list(stmts)
        for index in range(len(out) - 2, -1, -1):
            branch, following = out[index:index + 2]
            if branch.kind != 'if' or following.kind != 'return':
                continue
            phi = following.a
            if not isinstance(phi, NdxSV) or phi.op != 'loc':
                continue
            pairs = prov.get(id(phi), ())
            values = {}
            valid = bool(pairs)
            for pred, value in pairs:
                if pred is None or not isinstance(value, NdxSV) or value.op not in ('const', 'none'):
                    valid = False
                    break
                if pred in values and not _sv_eq(values[pred], value):
                    valid = False
                    break
                values[pred] = value
            if not valid:
                continue
            used = set()

            def leaf(entry):
                pending, visited, found = [entry], set(), []
                while pending:
                    cur = pending.pop()
                    if cur in visited:
                        continue
                    visited.add(cur)
                    if len(visited) > 1000:
                        return None
                    if cur in values:
                        found.append(cur)
                        continue
                    successors = self.S.nsucc.get(cur, ())
                    if not successors:
                        return None
                    pending.extend(successors)
                if not found or any(not _sv_eq(values[found[0]], values[p]) for p in found):
                    return None
                used.update(found)
                return [NdxSt('return', a=values[found[0]], blocks=set(found))]

            def rebuild(node):
                if node.kind != 'if' or not isinstance(node.d, tuple) or len(node.d) != 2:
                    return None
                arms = []
                for body, entry in zip((node.b, node.c), node.d):
                    if not body:
                        result = leaf(entry)
                    elif len(body) == 1 and body[0].kind == 'if':
                        nested = rebuild(body[0])
                        result = [nested] if nested is not None else None
                    else:
                        return None
                    if result is None:
                        return None
                    arms.append(result)
                return NdxSt('if', a=node.a, b=arms[0], c=arms[1], d=node.d,
                             line=node.line, blocks=node.blocks)

            restored = rebuild(branch)
            if restored is not None and used == set(values):
                out[index:index + 2] = [restored]
        return out

    def _inject_phi_arms(self, stmts):
        """Empty match/if arms + following phi assign → per-arm assigns.

        ``match tier: case 'gold': factor = 1.5 ...`` lowers to compare
        chains whose arm bodies are frame-slot stores the renderer sees
        only as a merged loc phi at the join (``factor = amount * _v1``).
        When the lifter recorded the phi's per-predecessor values and they
        are all constants, the constants are materialised back into the
        empty arms (chain order = predecessor address order, leftovers go
        to the implicit else) and the phi is named after the variable."""
        L = getattr(self.S, 'L', None)
        prov = getattr(L, '_phi_inputs', {}) or {} if L is not None else {}
        if not prov:
            return stmts

        def collect_phis(node, acc):
            for f in ('a', 'b', 'c'):
                v = getattr(node, f, None)
                if isinstance(v, NdxSV):
                    if v.op == 'loc' and id(v) in prov:
                        acc.setdefault(id(v), v)
                    for g in ('a', 'b', 'c'):
                        gv = getattr(v, g, None)
                        if isinstance(gv, NdxSV):
                            collect_phis_sym(gv, acc)
                elif isinstance(v, list):
                    for item in v:
                        collect_phis(item, acc)

        def collect_phis_sym(v, acc):
            if not isinstance(v, NdxSV):
                return
            if v.op == 'loc' and id(v) in prov:
                acc.setdefault(id(v), v)
            for g in ('a', 'b', 'c'):
                child = getattr(v, g, None)
                if isinstance(child, NdxSV):
                    collect_phis_sym(child, acc)

        out = self._restore_constant_returns(stmts)
        for idx, st in enumerate(out):
            if st is None or st.kind != 'if':
                continue
            chain = []
            node = st
            while True:
                chain.append(node)
                c = node.c
                if isinstance(c, list) and len(c) == 1 and \
                        c[0].kind == 'if':
                    node = c[0]
                else:
                    break
            if idx + 1 >= len(out):
                continue
            following = out[idx + 1]
            if following is None or following.kind != 'assign' or                     not isinstance(following.a, str) or                     not following.a.isidentifier():
                continue
            phis = {}
            collect_phis_sym(following.b, phis)
            if not phis:
                continue
            # I merge parzialmente ordinati spezzano il dispatch in più phi
            # (gold+silver, gold+default, ...): i rami consumati da merge
            # intermedi non compaiono più nello statement finale.  La
            # chiusura transitiva sceglie dall'INTERA tabella provenienza i
            # phi tutti-const il cui intervallo di pred interseca quello
            # raccolto, ricostruendo l'insieme completo caso-per-caso.
            const_only_entries = []
            for pid, psym in phis.items():
                pairs = [(p, v) for p, v in (prov.get(pid) or [])
                         if p is not None and isinstance(v, NdxSV) and
                         v.op == 'const']
                if pairs:
                    const_only_entries.append(pairs)
            merged = {}
            for pairs in const_only_entries:
                for p, v in pairs:
                    merged.setdefault(p, v)
            changed = True
            while changed and merged:
                changed = False
                lo = min(merged)
                hi = max(merged)
                for cand_pairs in [
                        [(p, v) for p, v in (prov.get(pid) or [])
                         if p is not None and isinstance(v, NdxSV) and
                         v.op == 'const']
                        for pid in prov]:
                    if not cand_pairs or len(cand_pairs) > len(chain) + 2:
                        continue
                    preds_c = [p for p, _v in cand_pairs]
                    if not (min(preds_c) <= hi and max(preds_c) >= lo):
                        continue
                    for p, v in cand_pairs:
                        if p not in merged:
                            merged[p] = v
                            changed = True
            inputs = sorted(merged.items(), key=lambda pv: pv[0])
            if not inputs or len(inputs) < len(chain):
                continue
            if len(inputs) > len(chain) + 1:
                continue        # troppi candidati: dispatch non riconosciuto
            if any(n.b for n in chain):
                continue        # arms already carry statements
            for n, (pred, value) in zip(chain, inputs[:len(chain)]):
                # raw: verbatim, immune ai pass di value-prop downstream
                n.b = [NdxSt('raw', a=f'{following.a} = ' + repr(value.a),
                             line=n.line, blocks=n.blocks)]
            leftovers = inputs[len(chain):]
            if leftovers:
                last = chain[-1]
                last.c = [NdxSt('raw', a=f'{following.a} = ' +
                                repr(leftovers[-1][1].a) if
                                isinstance(leftovers[-1][1], NdxSV) and
                                leftovers[-1][1].op == 'const' else
                                f'{following.a} = {leftovers[-1][1].a}',
                                line=last.line, blocks=last.blocks)]
            # il phi merge rappresenta la variabile stessa
            for phi_id in phis:
                self._phi_names[phi_id] = following.a
        return out

    def _schedule_native_values(self, stmts):
        """Materialise each native call once, in statement evaluation order.

        Tuple allocation precedes its element stores in C.  A populated tuple
        literal can only be emitted after those producers, without pulling
        future calls backwards or repeating calls already executed.
        """
        stmts = list(stmts)
        identity_ops = {'call', 'kwcall', 'mcall', 'nativecall', 'apicall',
                        'tuple_build', 'list_build'}
        def token(value):
            if isinstance(value, NdxSV) and value.op in identity_ops and \
                    isinstance(value.n, int):
                return value.op, value.n
            # The exact shared IR object also proves a single evaluation.
            # Structural equality alone does not: overloaded operators can
            # have effects even when their operands have identical text.
            if isinstance(value, NdxSV) and value.op in (
                    'binop', 'unary', 'cmp', 'getattr', 'sub', 'await'):
                return value.op, ('object', id(value))
            return None

        assignments = {}
        producers = {}
        for index, stmt in enumerate(stmts):
            if stmt is not None and stmt.kind in ('expr', 'eval_hint'):
                key = token(stmt.a)
                if key is not None:
                    producers.setdefault(key, index)
            if stmt is not None and stmt.kind == 'assign' and isinstance(stmt.a, str):
                key = token(stmt.b)
                if key is not None:
                    assignments.setdefault(key, (index, stmt))
                    producers.setdefault(key, index)

        def descendants(value):
            pending, seen = [value], set()
            while pending:
                item = pending.pop()
                if isinstance(item, NdxSV):
                    if id(item) in seen:
                        continue
                    seen.add(id(item))
                    yield item
                    pending.extend((item.a, item.b, item.c))
                elif isinstance(item, (list, tuple)):
                    pending.extend(item)

        nested_uses = set()
        for item in stmts:
            if item is None or item.kind not in ('assign', 'expr', 'return'):
                continue
            root = item.b if item.kind == 'assign' else item.a
            for child in descendants(root):
                if child is not root and token(child) is not None:
                    nested_uses.add(token(child))
        delayed = {}
        removed = set()
        for key, (index, stmt) in assignments.items():
            if stmt.b.op not in ('tuple_build', 'list_build'):
                continue
            dependencies = [producers[token(child)]
                            for child in descendants(stmt.b.b)
                            if token(child) in producers and token(child) != key]
            end = max(dependencies, default=index)
            if end <= index or any(item is None or item.kind not in ('assign', 'expr', 'eval_hint')
                                   for item in stmts[index + 1:end + 1]):
                continue
            # No statement may observe the tuple before all element values
            # exist.  A partial/escaping construction needs explicit stores.
            if any(any(token(child) == key for child in descendants(
                    item.b if item.kind == 'assign' else item.a))
                   for item in stmts[index + 1:end + 1]):
                continue
            removed.add(index)
            delayed.setdefault(end, []).append(stmt)
        ordered = []
        for index, stmt in enumerate(stmts):
            if index not in removed:
                ordered.append(stmt)
            ordered.extend(delayed.get(index, ()))

        available = {}
        def rewrite(value, root=False, memo=None):
            if memo is None:
                memo = {}
            if isinstance(value, NdxSV):
                key = token(value)
                if not root and key in available:
                    return ndx_k('var', available[key])
                if id(value) in memo:
                    return memo[id(value)]
                clone = ndx_k(value.op, n=value.n)
                memo[id(value)] = clone
                clone.a = rewrite(value.a, memo=memo)
                clone.b = rewrite(value.b, memo=memo)
                clone.c = rewrite(value.c, memo=memo)
                if clone.a is value.a and clone.b is value.b and clone.c is value.c:
                    memo[id(value)] = value
                    return value
                return clone
            if isinstance(value, (list, tuple)):
                children = [rewrite(child, memo=memo) for child in value]
                if all(before is after for before, after in zip(value, children)):
                    return value
                return tuple(children) if isinstance(value, tuple) else children
            return value

        scheduled = []
        used_names = {item.a for item in stmts if item is not None and item.kind == 'assign' and isinstance(item.a, str)}
        used_names.update(getattr(self.S, 'semantic_names', ()))
        temporary_index = 0
        for stmt in ordered:
            if stmt is None:
                continue
            if stmt.kind == 'assign' and isinstance(stmt.a, str):
                key = token(stmt.b)
                # Reusing the same source variable is not an SSA identity;
                # invalidate old associations before its next assignment.
                if key in available:
                    previous = available[key]
                    if previous == stmt.a:
                        continue
                    stmt.b = ndx_k('var', previous)
                else:
                    stmt.b = rewrite(stmt.b, root=True)
                available = {k: name for k, name in available.items() if name != stmt.a}
                if key is not None:
                    available[key] = stmt.a
            elif stmt.kind in ('return', 'expr', 'eval_hint'):
                key = token(stmt.a)
                if stmt.kind == 'eval_hint' and (key not in nested_uses or key in available):
                    continue
                if stmt.kind in ('expr', 'eval_hint') and (key in assignments or key in nested_uses) and key not in available:
                    while '_ndx_value_%d' % temporary_index in used_names:
                        temporary_index += 1
                    name = '_ndx_value_%d' % temporary_index
                    used_names.add(name)
                    temporary_index += 1
                    value = rewrite(stmt.a, root=True)
                    stmt = NdxSt('assign', a=name, b=value, blocks=stmt.blocks, line=stmt.line)
                    available[key] = name
                else:
                    stmt.a = rewrite(stmt.a)
            else:
                # Branches and loops require dominance-sensitive name scopes.
                # They are scheduled separately when their bodies are rendered.
                available.clear()
            scheduled.append(stmt)
        return scheduled

    # ------------------------------------------------------------------
    # V101 — SSA transport folding (statement-IR level, no text matching)
    _TRANSPORT_NAME_RE = None

    @classmethod
    def _is_transport_name(cls, name):
        if cls._TRANSPORT_NAME_RE is None:
            import re as _re_tr
            cls._TRANSPORT_NAME_RE = _re_tr.compile(
                r'_v\d+\Z|_ndx_value_\d+\Z|_tmp\w*\Z')
        return isinstance(name, str) and \
            cls._TRANSPORT_NAME_RE.match(name) is not None

    @staticmethod
    def _top_expr_symbols(st):
        """Expression SV fields of one statement, without descending into
        nested statement bodies (a use there is conditionally executed)."""
        fields = []
        if st is None:
            return fields
        if st.kind in ('assign', 'unpack_ex'):
            fields.append(st.b)
        elif st.kind in ('expr', 'eval_hint', 'return', 'raise'):
            fields.append(st.a)
        elif st.kind in ('if', 'while'):
            fields.append(st.a)
        elif st.kind == 'for':
            fields.extend([st.b, st.e])
        elif st.kind == 'store_sub':
            fields.extend([st.a, st.b, st.c])
        elif st.kind == 'store_attr':
            fields.extend([st.a, st.c])
        elif st.kind in ('append', 'setadd'):
            fields.extend([st.a, st.b])
        return [f for f in fields if isinstance(f, NdxSV)]

    @staticmethod
    def _nested_stmt_lists(st):
        if st is None:
            return []
        if st.kind in ('if', 'while'):
            lists = [st.b or [], st.c or []]
            if st.kind == 'while' and getattr(st, 'd', None):
                lists.append(st.d)
            return lists
        if st.kind == 'for':
            return [st.c or []]
        if st.kind == 'try':
            lists = [st.a or [], st.c or []]
            for handler in (st.b or []):
                if isinstance(handler, (tuple, list)) and len(handler) >= 2:
                    lists.append(handler[1] or [])
            return lists
        return []

    def _fold_transport_temps(self, stmts, _round=0):
        """Fold single-use SSA transport temps into their use site and drop
        dead ones (duplicate materializations of the same value).

        Runs after ``_rename_to_varnames``: every surviving ``_vN`` /
        ``_ndx_value_N`` name has no source variable behind it, so folding
        cannot hide an original local.  Decisions are made on the statement
        IR (definition/def counts, use positions, control-flow boundaries),
        never on rendered text.
        """
        try:
            import re as _re_t
            ti = getattr(self.S, 'temp_inline', None)
            if ti is None:
                ti = self.S.temp_inline = {}

            def name_of(node):
                """Source name of a var/loc reference, resolved exactly as
                the renderer does (loc names via name_of_loc)."""
                if not isinstance(node, NdxSV):
                    return None
                if node.op == 'var':
                    return node.a if isinstance(node.a, str) else None
                if node.op == 'loc':
                    try:
                        return self.S.name_of_loc(node.a)
                    except Exception:
                        return None
                return None

            def _sv_depth(sv):
                if not isinstance(sv, NdxSV):
                    return 0
                children = []
                for field in (sv.a, sv.b, sv.c, sv.n):
                    if isinstance(field, NdxSV):
                        children.append(field)
                    elif isinstance(field, (list, tuple)):
                        children.extend(x for x in field
                                        if isinstance(x, NdxSV))
                return 1 + max([_sv_depth(c) for c in children] or [0])

            eff_memo = {}

            def _eff_depth(sv):
                """Effective depth of a value: references to already-folded
                temps count at their expanded depth.  Long SSA reassignment
                chains (``value = adjust(value, ...)`` compiled to one temp
                per link) stop folding at this bound and keep their natural
                sequential-assignment form instead of one giant nested
                expression."""
                if not isinstance(sv, NdxSV):
                    return 0
                if sv.op == 'var':
                    nm = sv.a if isinstance(sv.a, str) else None
                    if nm is not None and nm in ti:
                        return 1 + _eff_depth(ti[nm])
                    return 1
                if sv.op == 'loc':
                    nm = name_of(sv)
                    if nm is not None and nm in ti:
                        return 1 + _eff_depth(ti[nm])
                    return 1
                key = id(sv)
                if key in eff_memo:
                    return eff_memo[key]
                eff_memo[key] = 1     # cycle guard
                depth = 1
                for field in (sv.a, sv.b, sv.c, sv.n):
                    if isinstance(field, NdxSV):
                        d = _eff_depth(field)
                    elif isinstance(field, (list, tuple)):
                        d = max([_eff_depth(x) for x in field
                                 if isinstance(x, NdxSV)] or [0])
                    else:
                        d = 0
                    depth = max(depth, 1 + d)
                eff_memo[key] = depth
                return depth

            def count_uses(name, list_stmts):
                """(uses_top, uses_any) with top = own-expression fields."""
                top = any_use = 0
                stack = list(list_stmts)
                while stack:
                    st = stack.pop()
                    if st is None:
                        continue
                    for sym in self._top_expr_symbols(st):
                        def visit(node):
                            nonlocal top, any_use
                            if name_of(node) == name:
                                top += 1
                                any_use += 1
                        self._sv_walk(sym, visit)
                    for nested in self._nested_stmt_lists(st):
                        for inner in nested:
                            if inner is None:
                                continue
                            def visit2(node):
                                nonlocal any_use
                                if name_of(node) == name:
                                    any_use += 1
                            for sym2 in self._top_expr_symbols(inner):
                                self._sv_walk(sym2, visit2)
                            stack.append(inner)
                # virtual uses: references inside already-registered
                # expansions (temp_inline values).  When a consumer folded,
                # its expression lives in ti — the temps it references still
                # have exactly that one use and must fold into the expansion
                # too (otherwise the hoisted definition evaluates out of
                # source order).  Counted as top-level uses: the expansion
                # renders at its consumer position, after this definition.
                for folded_value in ti.values():
                    def visit3(node):
                        nonlocal top, any_use
                        if name_of(node) == name:
                            top += 1
                            any_use += 1
                    if isinstance(folded_value, NdxSV):
                        self._sv_walk(folded_value, visit3)
                return top, any_use

            # definition counts (single list level; transport temps are
            # defined once per straight-line region)
            defs = {}
            for st in stmts:
                if st is not None and st.kind == 'assign' and \
                        isinstance(st.a, str):
                    defs[st.a] = defs.get(st.a, 0) + 1
            # names used as MUTATION targets keep their variable: the
            # container object is written through them (append/store_sub),
            # so folding the definition into a use site would rebuild a
            # fresh literal for every mutation.
            mutated = set()
            for st in stmts:
                if st is None:
                    continue
                if st.kind in ('append', 'setadd', 'store_sub', 'store_attr') \
                        and isinstance(st.a, NdxSV):
                    target_name = (st.a.a if st.a.op == 'var'
                                   and isinstance(st.a.a, str) else
                                   name_of(st.a))
                    if target_name:
                        mutated.add(target_name)
            control_kinds = ('if', 'while', 'for', 'try')

            def pure_subtree(sv, _depth=0):
                """No observable-effect operation in the value subtree."""
                ok = [True]
                def visit(node):
                    if isinstance(node, NdxSV) and node.op in (
                            'call', 'mcall', 'nativecall', 'apicall',
                            'await', 'awaited', 'raise'):
                        ok[0] = False
                self._sv_walk(sv, visit)
                return ok[0]

            changed = False
            drop_indices = set()
            # duplicate materialization: an expr statement whose value node
            # is (by identity) embedded in another statement is the same
            # native computation structured twice — rendering both would
            # evaluate it twice.  Node identity is the proof.
            try:
                per_stmt_ids = []
                for st in stmts:
                    ids = set()
                    if st is not None:
                        for sym in self._top_expr_symbols(st):
                            def visit(node, _ids=ids):
                                if isinstance(node, NdxSV):
                                    _ids.add(id(node))
                            self._sv_walk(sym, visit)
                    per_stmt_ids.append(ids)
                for index, st in enumerate(stmts):
                    if st is None or st.kind != 'expr' or \
                            not isinstance(st.a, NdxSV):
                        continue
                    root_id = id(st.a)
                    if any(root_id in per_stmt_ids[j]
                           for j in range(len(stmts)) if j != index):
                        drop_indices.add(index)
                        changed = True
            except Exception:
                pass
            for index, st in enumerate(stmts):
                if st is None or st.kind != 'assign' or \
                        not isinstance(st.a, str) or \
                        not isinstance(st.b, NdxSV):
                    continue
                name = st.a
                if not self._is_transport_name(name) or name in ti:
                    continue
                if defs.get(name, 0) != 1 or name in mutated:
                    continue
                uses_top, uses_any = count_uses(name, stmts)
                if uses_any == 0:
                    # Dead transport.  Pure values (lifter duplicate
                    # materializations: the tuple/form parts of an f-string,
                    # alias copies) drop safely — the surviving copy renders
                    # the value.  A dead temp holding a call keeps its
                    # statement: native code computed it for a reason and
                    # dropping an unrendered call changes behavior.
                    if pure_subtree(st.b):
                        drop_indices.add(index)
                        changed = True
                    continue
                if uses_top == 1 and uses_any == 1 and \
                        _eff_depth(st.b) <= 16:
                    # single use on an unconditional path: fold when the
                    # use follows the definition with no control boundary
                    # between (evaluation order preserved)
                    use_index = None
                    for j in range(index + 1, len(stmts)):
                        other = stmts[j]
                        if other is None:
                            continue
                        hit = False
                        for sym in self._top_expr_symbols(other):
                            def visit4(node):
                                nonlocal hit
                                if name_of(node) == name:
                                    hit = True
                            self._sv_walk(sym, visit4)
                        if hit:
                            use_index = j
                            break
                    if use_index is not None and not any(
                            stmts[k] is not None and
                            stmts[k].kind in control_kinds
                            for k in range(index + 1, use_index)):
                        ti[name] = st.b
                        drop_indices.add(index)
                        changed = True
                    elif use_index is None and _sv_depth(st.b) <= 2:
                        # the single use is virtual: it lives inside an
                        # already-registered expansion (temp_inline).  The
                        # consumer's own folding already proved its position
                        # after this definition — folding keeps evaluation
                        # at the consumer site instead of leaving a hoisted
                        # definition that would run out of source order.
                        # Leaf values only (aliases, single calls): a value
                        # whose subtree embeds other foldable expressions
                        # can be referenced by several expansions and would
                        # duplicate its computation at each of them.
                        ti[name] = st.b
                        drop_indices.add(index)
                        changed = True
            if drop_indices:
                stmts = [st for i, st in enumerate(stmts)
                         if i not in drop_indices]
            if changed and _round < 6:
                return self._fold_transport_temps(stmts, _round + 1)
            return stmts
        except Exception:
            return stmts

    def _render_once(self, stmts, indent=0):
        # inline delle temporanee single-use: `t = EXPR` subito seguito da
        # `for v in t:` → `for v in EXPR:` (mutazione dello statement, così
        # il renderer del for vede direttamente l'espressione)
        # il harvest del decoratore annidato deve girare PRIMA di ogni
        # altra pass: qui i SV hanno ancora i nomi reali (global('wraps'))
        # e le identity tra apply-call e return sono intatte
        try:
            stmts = self._harvest_nested_decorators(stmts)
        except Exception:
            pass
        stmts = self._schedule_native_values(stmts)
        # V100: seeding dell'inline per le temporanee LETTERALI — il
        # lowering spilla gli argomenti costanti in temp (``_v6 = {}`` poi
        # ``.get('k', _v6)``): il renderer sostituisce il letterale al
        # nome in ogni uso.  Le collezioni vuote e i const brevi non hanno
        # side-effect: l'inline e' sempre fedele.
        # V100.2: INLINE DELLE TEMPORANEE ``_vN`` SINGLE-USE — la massa
        # del lowering: ogni intermedio spillato in una temp usata una
        # sola volta e' puro trasporto.  Si registra in temp_inline (il
        # renderer espande l'espressione al punto d'uso) e si DROPPA la
        # definizione.  Ordine di valutazione preservato (uso segue la
        # def nel flusso); multi-use restano variabili nominate.
        try:
            import re as _re_su
            _ti = getattr(self.S, 'temp_inline', None)
            if _ti is None:
                _ti = self.S.temp_inline = {}
            _drop_inline = set()
            for _i0, _st0 in enumerate(stmts):
                if _st0 is None or _st0.kind != 'assign' or \
                        not isinstance(_st0.a, str) or \
                        not isinstance(_st0.b, NdxSV):
                    continue
                if _re_su.fullmatch(r'_v\d+', _st0.a) and \
                        _st0.b.op in ('const', 'none', 'par'):
                    _uses0 = 0
                    for _j0, _stx in enumerate(stmts):
                        if _stx is None or _j0 == _i0:
                            continue

                        def _cnt(sym, _n=_st0.a):
                            nonlocal _uses0
                            if isinstance(sym, NdxSV) and \
                                    sym.op in ('var', 'loc') and \
                                    isinstance(sym.a, str) and \
                                    sym.a == _n:
                                _uses0 += 1
                        self._stmt_walk(_stx, _cnt)
                    if _uses0 == 1 and _st0.a not in _ti:
                        _ti[_st0.a] = _st0.b
                        _drop_inline.add(_st0.a)
                        continue
                _op0 = _st0.b.op
                _lit0 = ((_op0 in ('dict_empty', 'list_empty',
                                   'set_empty')) or
                         (_op0 == 'const' and (
                             isinstance(_st0.b.a, (int, float, str, bool))
                             or _st0.b.a is None)))
                # User locals can change across branches and loop iterations.
                # Only genuine synthetic temporaries may be literal aliases.
                if _lit0 and _re_su.fullmatch(r'_v\d+', _st0.a) and \
                        _st0.a not in _ti:
                    _ti[_st0.a] = _st0.b
            if _drop_inline:
                stmts = [s for s in stmts
                         if not (s is not None and s.kind == 'assign'
                                 and isinstance(s.a, str)
                                 and s.a in _drop_inline)]
        except Exception:
            pass
        # nomi vivi: assegnazioni presenti + parametri + livelli esterni.
        # Un nome non vivo è fantasma e il renderer espande il simbolo.
        def finally_bindings(statements):
            names = set()
            for statement in statements:
                if statement.kind == 'assign' and isinstance(statement.a, str):
                    names.add(statement.a)
                elif statement.kind == 'try' and not statement.b and statement.c:
                    names.update(finally_bindings(statement.a + statement.c))
            return names
        _finally_names = set().union(*(finally_bindings(st.a + st.c)
            for st in stmts if st.kind == 'try' and not st.b and st.c))
        _prev = getattr(self, '_live_names', None)
        _prev_defined = getattr(self, '_defined_names', None)
        _base = _prev if _prev is not None else \
            set(self.varnames[:getattr(self, 'argcount', 0) or 0])
        self._live_names = _base | _finally_names | {
            st.a for st in stmts
            if st is not None and st.kind == 'assign' and
            isinstance(st.a, str)} | {
            st.a for st in stmts
            if st is not None and st.kind == 'for' and
            isinstance(st.a, str)} | {name for st in stmts if st is not None and
                                     st.kind == 'unpack_ex' for name in st.a}
        try:
            stmts = self._drop_embedded_temps(stmts)
            stmts = self._harvest_nested_decorators(stmts)
            stmts = self._fuse_call_chains(stmts)
            stmts = self._promote_expr_conditions(stmts)
            stmts = self._fuse_fstring_stmts(stmts)
            stmts = self._fix_dispatch_polarity(stmts)
            stmts = self._promote_tail_returns(stmts)
            stmts = self._fuse_iterable_temps(stmts)
            stmts = self._rename_to_varnames(stmts)
            # V101 ROOT FIX — trasporto SSA: dopo la rinomatura, ogni temp
            # rimasta (_vN/_ndx_value_N senza nome sorgente) e' puro
            # trasporto del lowering. Le single-use si piegono nel punto
            # d'uso (ordine di valutazione preservato: uso dopo la def,
            # nessuno statement di controllo in mezzo, uso non annidato in
            # un body condizionale); le dead (zero usi superstiti) si
            # eliminano quando il valore e' puro o la sua rappresentazione
            # sopravvive altrove (doppia materializzazione del lifter).
            stmts = self._fold_transport_temps(stmts)
            # dopo il naming: le comprehension desugurate si piegano sui
            # nomi sorgente FINALI (ricevitore incluso).
            stmts = self._fold_comprehensions(stmts)
            # ricalcolo: i nomi degli assegnamenti rimossi sono FANTASMI,
            # il renderer deve espandere i loro simboli embedded
            self._live_names = _base | _finally_names | {
                st.a for st in stmts
                if st is not None and st.kind == 'assign' and
                isinstance(st.a, str)} | {
                st.a for st in stmts
                if st is not None and st.kind == 'for' and
                isinstance(st.a, str)} | {name for st in stmts if st is not None and
                                         st.kind == 'unpack_ex' for name in st.a}
            stmts = [s for s in stmts if s is not None]
            lines = []
            defined = set(_prev_defined) if _prev_defined is not None \
                else set(self.varnames[:getattr(self, 'argcount', 0) or 0])
            for st in stmts:
                self._defined_names = defined
                lines.extend(self.render_stmt(st, indent))
                if st.kind in ('assign', 'for') and isinstance(st.a, str):
                    defined.add(st.a)
                elif st.kind == 'unpack_ex':
                    defined.update(st.a)
                elif st.kind == 'try' and not st.b and st.c:
                    defined.update(finally_bindings(st.a + st.c))
            # V100.3: RINOMINA delle temp multi-use con i VARNAMES residui
            # del pool.  CPython ordina co_varnames per prima assegnazione
            # nel sorgente: una temp ``_vN`` multi-uso con definizione,
            # in ordine di prima definizione, corrisponde al prossimo
            # varname non consumato.  E' la stessa informazione che il
            # compilatore aveva — nessuna invenzione.
            try:
                free = [n for n in (getattr(self.S, '_free_names', None)
                                    or []) if n not in defined]
                if free:
                    import re as _re_rn
                    seen_order = []
                    for ln in lines:
                        m = _re_rn.match(r'\s*(_v\d+) =', ln)
                        if m and m.group(1) not in seen_order:
                            seen_order.append(m.group(1))
                    for tmp in seen_order:
                        if not free:
                            break
                        new = free.pop(0)
                        lines = [_re_rn.sub(r'\b' + tmp + r'\b', new, l)
                                 for l in lines]
            except Exception:
                pass
            return self._clean_lines(lines)
        finally:
            self._live_names = _prev
            self._defined_names = _prev_defined
        stmts = self._fuse_call_chains(stmts)
        stmts = self._promote_expr_conditions(stmts)
        for i2, st in enumerate(stmts):
            if st.kind == 'assign' and isinstance(st.b, NdxSV) and                     i2 + 1 < len(stmts) and stmts[i2 + 1].kind == 'for':
                nxt = stmts[i2 + 1]
                if nxt.b is not None and isinstance(nxt.b, NdxSV) and                         nxt.b.op in ('var', 'loc') and                         getattr(nxt.b, 'a', None) == st.a:
                    nxt.b = st.b
                    stmts[i2] = None
        stmts = [s for s in stmts if s is not None]
        lines = []
        for st in stmts:
            lines.extend(self.render_stmt(st, indent))
        return self._clean_lines(lines)

    def render_stmt(self, st, indent):
        pad = '    ' * indent
        k = st.kind
        value = st.b if k == 'assign' else st.a if k == 'expr' else None
        if getattr(getattr(self.S, 'L', None), 'gen_mode', False) and \
                isinstance(value, NdxSV) and value.op == 'call' and \
                value.a == 'issubclass' and isinstance(value.b, list) and \
                len(value.b) == 2:
            subject, expected = value.b
            if isinstance(subject, NdxSV) and subject.op == 'type_of' and \
                    isinstance(subject.a, NdxSV) and subject.a.op == 'imm' and \
                    subject.a.a == 0 and isinstance(expected, NdxSV) and \
                    expected.op == 'global' and expected.a in (
                        'GeneratorExit', 'StopIteration', 'StopAsyncIteration'):
                # Internal exception-state type probes have no Python object
                # as their subject. They are suspension protocol machinery,
                # not calls on a source expression such as type(value).
                return []
        if k == 'module_definition':
            return [pad + st.a + '()']
        if k == 'unpack_ex':
            targets = [('*' if index == st.c else '') + name for index, name in enumerate(st.a)]
            target = ', '.join(targets) + (',' if len(targets) == 1 else '')
            return [f'{pad}{target} = {self.expr(st.b)}']
        if k == 'assign':
            if not isinstance(st.a, str):
                # target non-nome (slot costante del lowering, es.
                # ``'Circle' = ...``): non e' sorgente, si elimina.
                tgt = self.expr(st.a) if isinstance(st.a, NdxSV) else None
                if not tgt or not str(tgt).isidentifier():
                    return []
                st.a = tgt
            if isinstance(st.b, NdxSV) and st.b.op == 'binop':
                left = self.expr(st.b.b)
                right = self.expr(st.b.c)
                operator = OP_TEXT.get(st.b.a, st.b.a)
                # AugAssign anche senza marker 'inplace': nel sorgente
                # ``x = x + k`` è ``x += k`` a tutti gli effetti (il
                # compilatore non distingue); il read-back del target
                # come operando sinistro è la prova strutturale.
                if left == st.a and operator in (
                        '+', '-', '*', '/', '//', '%', '**', '<<', '>>',
                        '&', '|', '^', '@'):
                    return [f'{pad}{st.a} {operator}= {right}']
            previous_rhs = getattr(self, '_active_assign_rhs', None)
            previous_name = getattr(self, '_active_assign_name', None)
            self._active_assign_rhs = st.c
            self._active_assign_name = st.a
            try:
                val = self.expr(st.b, assign_rhs=st.c, top_assign=True)
            finally:
                self._active_assign_rhs = previous_rhs
                self._active_assign_name = previous_name
            return [f'{pad}{st.a} = {val}']
        if k == 'store_sub':
            o = self.expr(st.a)
            key = self.expr(st.b)
            v = self.expr(st.c)
            return [f'{pad}{o}[{key}] = {v}']
        if k == 'store_attr':
            o = self.expr(st.a)
            v = self.expr(st.c)
            # AugAssign su attributo: ``o.a = o.a + k`` è ``o.a += k`` nel
            # sorgente (il compilatore non distingue; il read-back del
            # receiver.attr come operando sinistro è la prova)
            if isinstance(st.c, NdxSV) and st.c.op == 'binop':
                _op_txt = OP_TEXT.get(st.c.a, st.c.a)
                if isinstance(st.b, str) and _op_txt in (
                        '+', '-', '*', '/', '//', '%', '**', '<<', '>>',
                        '&', '|', '^', '@'):
                    _recv = self.expr(st.c.b)
                    if _recv == f'{o}.{st.b}':
                        return [f'{pad}{o}.{st.b} {_op_txt}= '
                                f'{self.expr(st.c.c)}']
            return [f'{pad}{o}.{st.b} = {v}']
        if k == 'raw':
            return [f'{pad}{st.a}']
        if k == 'append':
            lst = self.expr(st.a)
            v = self.expr(st.b)
            return [f'{pad}{lst}.append({v})']
        if k == 'setadd':
            s = self.expr(st.a)
            v = self.expr(st.b)
            return [f'{pad}{s}.add({v})']
        if k == 'expr':
            e = self.expr(st.a)
            if e is None:
                return []
            return [f'{pad}{e}']
        if k == 'if':
            cond = self.expr(st.a)
            yes = self.render(st.b or [], indent + 1)
            no = self.render(st.c or [], indent + 1)
            out = [f'{pad}if {cond}:']
            out.extend(yes or [f'{pad}    pass'])
            if no:
                # elif-chain: se no è un solo statement if alla stessa profondità
                if len(no) == 1 and no[0].startswith(pad + 'if '):
                    out.append(f'{pad}else:')
                    out.extend(no)
                else:
                    out.append(f'{pad}else:')
                    out.extend(no)
            return out
        if k == 'while':
            cond = self.expr(st.a) if st.a is not None else 'True'
            self._loop_depth = getattr(self, '_loop_depth', 0) + 1
            try:
                body = self.render(st.b or [], indent + 1, loop_tail=True)
            finally:
                self._loop_depth -= 1
            out = [f'{pad}while {cond}:']
            out.extend(body or [f'{pad}    pass'])
            if getattr(st, 'd', None):
                out.append(f'{pad}else:')
                out.extend(self.render(st.d, indent + 1) or
                           [f'{pad}    pass'])
            return out
        if k == 'for':
            # iterabile desugurato: next(iter(X))/iter(X) MSCIAMO X
            iterable = st.b
            # unwrap solo delle forme complete next(iter(X))/iter(X)
            if st.e is not None:
                # The structurer already separated this loop's iterator
                # from its source iterable. A next() here may be the value
                # of an enclosing loop, and must keep that binding.
                pass
            elif hasattr(iterable, 'op') and iterable.op == 'next' and \
                    hasattr(iterable.a, 'op') and iterable.a.op == 'iter':
                iterable = iterable.a.a
            elif hasattr(iterable, 'op') and iterable.op == 'next':
                # next nudo su una sequenza: l'iternext e' stato
                # risolto direttamente sull'iterabile; mai quando
                # coincide col target del for (auto-riferimento)
                _inner = iterable.a
                _itxt = self.expr(_inner) if _inner is not None else None
                if _itxt and _itxt != str(st.a):
                    iterable = _inner
            elif hasattr(iterable, 'op') and iterable.op == 'iter':
                iterable = iterable.a
            iterable = self.expr(iterable)
            # V100: il target del for è definito DENTRO il suo corpo.
            # Senza registrarne la definizione prima di renderizzare il
            # body, ogni uso del valore di loop fallisce il gate
            # ``_defined_names`` del value-numbering e viene espeso come
            # ``next(iter(X))`` invece del nome della variabile.
            if isinstance(st.a, str):
                _dn = getattr(self, '_defined_names', None)
                if _dn is None:
                    _dn = set()
                    self._defined_names = _dn
                _dn.add(st.a)
            self._loop_depth = getattr(self, '_loop_depth', 0) + 1
            try:
                body = self.render(st.c or [], indent + 1, loop_tail=True)
            finally:
                self._loop_depth -= 1
            out = [f'{pad}for {st.a} in {iterable}:']
            out.extend(body or [f'{pad}    pass'])
            if getattr(st, 'f', None):
                # Il clone del finally sul percorso di esaurimento che
                # referenzia la variabile di loop e' Python INVALIDO (la
                # variabile non esiste se il corpo non gira mai) e doppio
                # conteggio quando gira: il sorgente non puo' mai
                # referenziarla in un else.  Droppalo.
                import re as _re
                _keep = []
                for _sub in st.f:
                    if _sub.kind == 'expr':
                        try:
                            _txt = self.expr(_sub.a) or ''
                        except Exception:
                            _txt = ''
                        if _txt and _re.search(
                                r'\b%s\b' % _re.escape(str(st.a)), _txt):
                            continue
                    _keep.append(_sub)
                if _keep:
                    out.append(f'{pad}else:')
                    out.extend(self.render(_keep, indent + 1) or
                               [f'{pad}    pass'])
            return out
        if k == 'return':
            if st.a is None:
                return [f'{pad}return']
            return [f'{pad}return {self.expr(st.a)}']
        if k == 'raise':
            if st.a is None:
                return [f'{pad}raise']
            # Nuitka emette per ogni globale importata il cold-path di
            # NULL-check ``raise NameError('<nome>')`` (semantica reload):
            # è machinery, non codice utente. Il nome è un identificatore
            # puro (o la variabile che lo contiene); un raise utente reale
            # porta un messaggio calcolato (call/format/binop).
            a = st.a
            if isinstance(a, NdxSV) and a.op == 'call' and \
                    getattr(a.a, 'op', None) == 'global' and \
                    a.a.a == 'NameError':
                cargs = a.b or []
                if len(cargs) == 1 and cargs[0] is not None:
                    arg0 = cargs[0]
                    if arg0.op in ('loc', 'gslot', 'global', 'var'):
                        return []
                    if arg0.op == 'const' and isinstance(arg0.a, str) and \
                            arg0.a.isidentifier():
                        return []
            return [f'{pad}raise {self.expr(st.a)}']
        if k == 'yield':
            e = self.expr(st.a) if st.a is not None else None
            # Coroutine suspension transports the ASYNC_AWAIT result through
            # the same native yield machinery used by generators.  Once the
            # value is authoritatively tagged as an await expression, emitting
            # an additional Python ``yield`` would be both wrong and invalid
            # for a normal coroutine.
            if isinstance(st.a, NdxSV) and st.a.op == 'await':
                return [f'{pad}{e}'] if e else []
            return [f'{pad}yield {e}' if e else f'{pad}yield']
        if k == 'try':
            out = [f'{pad}try:']
            out.extend(self.render(st.a or [], indent + 1) or
                       [f'{pad}    pass'])
            for clause in (st.b or []):
                types, body, line = clause[0], clause[1], clause[2]
                asname = clause[3] if len(clause) > 3 else None
                t = _exc_types_repr(types)
                suffix = f' as {asname}' if asname else ''
                out.append(f'{pad}except {t}{suffix}:')
                live = [s for s in (body or [])
                        if getattr(s, 'kind', None) != 'dead']
                out.extend(self.render(live, indent + 1) or
                           [f'{pad}    pass'])
            if st.c:
                out.append(f'{pad}finally:')
                out.extend(self.render(st.c, indent + 1) or [f'{pad}    pass'])
            return out
        if k == 'pass':
            return [f'{pad}pass']
        if k in ('break', 'continue'):
            if getattr(self, '_loop_depth', 0) <= 0:
                # Uscita di ciclo non riconducibile ad alcun ciclo
                # ricostruito (loop perso nel lift): gap ESPPLICITO al
                # posto di un modulo non compilabile.
                return [f'{pad}# ndx-gap: {k} outside reconstructed loop']
            return [f'{pad}{k}']
        return [f'{pad}/* stmt {k} */']


def ndx_render_function(lifter, structurer, name, args, returns=False):
    """Render di una funzione completa."""
    r = NdxRenderer(structurer, lifter.varnames, lifter.argcount)
    stmts = structurer.structure()
    lines = r.render(stmts, 1)
    arg_s = ', '.join(args)
    out = [f'def {name}({arg_s}):']
    if not lines:
        out.append('    pass')
    else:
        out.extend(lines)
    return '\n'.join(out)



