def discover_impls(img, res, code_objects):
    """Mappa code object slot VA → impl VA: ogni funzione impl_Nuitka crea
    il proprio frame con MAKE_FUNCTION_FRAME(tstate, code_objects_X, ...)
    → un rip-load dello slot X dentro la funzione la identifica come impl.
    Scansione deterministica di tutte le funzioni (.eh_frame bounds)."""
    slot_to_co = {}
    for co in code_objects:
        if co.slot_va:
            slot_to_co[co.slot_va] = co
    impl_of_co = {}
    fd = None
    fd = FuncDisassembler(img)
    starts = img.elf_function_starts() if img.fmt == 'elf' else \
        img.function_hints()
    for fs in starts:
        try:
            b = img.function_bounds(fs)
        except Exception:
            b = None
        start = b[0] if b else fs
        span = (b[1] - b[0]) if b else 0x400
        if span <= 0 or span > 0x30000:
            continue
        if _time.time() - _t0 > _budget:
            break
        off = img.va_to_off(start)
        if off is None:
            continue
        code = img.data[off:off + min(span, 0x400)]
        # prime ~120 istruzioni: il frame creation è all'inizio
        n_ins = 0
        for ins in fd.md.disasm(code, start):
            n_ins += 1
            if n_ins > 120:
                break
            if 'rip' in ins.op_str:
                t = rip_target(ins)
                if t in slot_to_co:
                    co = slot_to_co[t]
                    if co.slot_va not in impl_of_co:
                        impl_of_co[co.slot_va] = start
                    break
    return impl_of_co


_NDX_API_TYPE_DECORATORS = {
    'PyStaticMethod_Type': 'staticmethod',
    'PyClassMethod_Type': 'classmethod',
}
_NDX_BUILTIN_METHOD_DECORATORS = frozenset(('staticmethod', 'classmethod'))


def _ndx_method_decorator_name(callee):
    """Decorator name proven by a class-body method store's callee node.

    Nuitka emits ``classmethod``/``staticmethod`` in two shapes: as the CPython
    type object directly (``api_symbol('PyClassMethod_Type')``) and, when the
    name is resolved as a module global, as ``global('classmethod')``.  Only
    the first shape was recognised, so ``@classmethod``/``@staticmethod`` were
    silently dropped from every recovered class while ``@property`` — detected
    through a separate ``PyProperty_Type`` path — survived.

    ``property`` is deliberately NOT returned here: it has its own evidence
    path and returning it as well would emit the decorator twice.
    """
    if isinstance(callee, str):
        return callee if callee in _NDX_BUILTIN_METHOD_DECORATORS else None
    if not isinstance(callee, NdxSV):
        return None
    if callee.op == 'api_symbol' and isinstance(callee.a, str):
        return _NDX_API_TYPE_DECORATORS.get(callee.a)
    if callee.op in ('global', 'var', 'loc') and \
            isinstance(callee.a, str):
        return (callee.a if callee.a in _NDX_BUILTIN_METHOD_DECORATORS
                else None)
    if callee.op == 'getattr' and isinstance(callee.b, str):
        return (callee.b if callee.b in _NDX_BUILTIN_METHOD_DECORATORS
                else None)
    return None


class ModuleEmitter:
    def __init__(self, img, res, mca, mod, py_version=(3, 12),
                 verbose=False, code_objects=None):
        self.img = img
        self.res = res
        self.mca = mca
        self.mod = mod
        self.py_version = py_version
        self.verbose = verbose
        self.code_objects = code_objects or []
        self.func_by_impl = {}
        self.class_meta = {}
        self.function_meta = {}
        self.module_lifter = None
        self.import_lines = []
        self.future_annotations = any(
            bool(getattr(co, 'flags', 0) & 0x1000000)
            for co in self.code_objects)
        self._prepare()

    def _prepare(self):
        for va, co in getattr(self.mca, 'code_objects', {}).items():
            if isinstance(co, CodeObjectInfo) and co not in self.code_objects:
                self.code_objects.append(co)
        self.code_objects = [c for c in self.code_objects
                             if isinstance(c, CodeObjectInfo)]
        # The code-object storage slot is the compiler's authoritative join
        # key between a MAKE_FUNCTION wrapper and PyCode metadata.  Joining by
        # leaf name loses sibling methods such as seven different ``get_url``
        # implementations; joining by slot remains unambiguous even when every
        # name and signature is identical.
        code_by_slot = {co.slot_va: co for co in self.code_objects
                        if co.slot_va is not None}
        for function in self.mca.functions:
            code = code_by_slot.get(function.get('code_obj_slot'))
            if code is not None:
                function['code_obj'] = code
        for f in self.mca.functions:
            iv = f.get('impl_va')
            if iv:
                self.func_by_impl[iv] = f
            _co = f.get('code_obj')
            _nm = getattr(_co, 'name', None)
            if iv and isinstance(_nm, str) and _nm.isidentifier() and \
                    not _nm.startswith('<'):
                _NDX_PYFUNC_BY_VA.setdefault(iv, _nm)
        self.future_annotations = self.future_annotations or any(
            bool(getattr(co, 'flags', 0) & 0x1000000)
            for co in self.code_objects)
        try:
            self.module_lifter = BodyLifter2(
                self.img, self.res, self.mca, None, self.mod.func_ptr,
                py_version=self.py_version, is_module_code=True).lift()
            self.import_lines = self._recover_import_lines(self.module_lifter)
            # V100: fallback a evidenza costanti per i from-import del
            # package-init che il lifter nativo non ha sollevato (moduli
            # il cui init non produce funzioni).  Layout classico Nuitka:
            # 'modulo' + ('nome', ...) + nomi ripetuti come stringhe.
            try:
                self.import_lines = self._merge_const_from_imports(
                    self.import_lines)
            except Exception:
                pass
            self._recover_constant_functions(self.module_lifter)
            self.function_meta = self._recover_function_metadata(
                self.module_lifter)
            self.class_meta = self._recover_class_metadata(self.module_lifter)
        except Exception:
            self.class_meta = {}

        BodyLifter2._emitter_cos = list(self.code_objects)
    def _recover_constant_functions(self, lifter):
        code_by_slot = {co.slot_va: co for co in self.code_objects if co.slot_va is not None}
        existing = {f.get('code_obj_slot'): f for f in self.mca.functions}
        for block in lifter.blocks.values():
            for op in block.ops:
                if op.kind != 'function_const_return' or not isinstance(op.a, NdxSV):
                    continue
                args = op.a.b
                if not isinstance(args, list) or len(args) < 4:
                    continue
                implementation, name, _, code = args[:4]
                if not (isinstance(implementation, NdxSV) and implementation.op == 'imm' and
                        implementation.a == 0 and isinstance(name, NdxSV) and name.op == 'const' and
                        isinstance(name.a, str) and isinstance(code, NdxSV) and code.op == 'gslot' and
                        code.a in code_by_slot and isinstance(op.b, NdxSV) and op.b.op in ('const', 'none')):
                    continue
                f = existing.get(code.a)
                if f is None:
                    f = {'impl_va': None, 'impl_name': None, 'qualname': name.a,
                         'code_obj_slot': code.a, 'code_obj': code_by_slot[code.a],
                         'maker_va': None, 'event_idx': len(self.mca.functions)}
                    self.mca.functions.append(f); existing[code.a] = f
                f['_constant_return'] = op.b

    def _merge_const_from_imports(self, import_lines):
        """V100: from-import dal pool costanti quando il lifter nativo ha
        prodotto solo ``import X`` (o niente) per un modulo-init.

        Layout di Nuitka per ``from X import a, b``: la stringa del modulo,
        la tuple dei nomi e i singoli nomi ripetuti compaiono adiacenti nel
        pool.  Un modulo-init di package contiene inoltre il marker
        ``('NUITKA_PACKAGE_<pkg>', ...)``.  La regola:
          * ``m`` stringa identificatore seguita da una tuple T di
            identificatori, con OGNI nome di T presente come stringa
            standalone nelle vicinanze (±8) → ``from m import T``
          * se il modulo corrente e' un package e ``m`` e' un sibling
            senza punti → livello relativo ``from .m import ...``
        Sostituisce l'eventuale ``import m`` plain della stessa m.
        """
        import re as _re
        consts = list(getattr(self.mod, 'consts', ()) or ())
        if not consts:
            return import_lines
        lines = list(import_lines or [])
        is_package = any(
            (isinstance(c, str) and c.startswith('NUITKA_PACKAGE_'))
            or (isinstance(c, tuple) and c
                and isinstance(c[0], str)
                and c[0].startswith('NUITKA_PACKAGE_'))
            for c in consts)
        mod_name = str(getattr(self.mod, 'name', '') or '')
        pkg_prefix = mod_name + '.' if mod_name else ''

        def _ident(s):
            return isinstance(s, str) and _re.fullmatch(
                r'[A-Za-z_]\w*', s) is not None

        # nomi gia' coperti da from-import esistenti
        covered_mods = set()
        for ln in lines:
            m2 = _re.match(r'^from\s+\.?([\w.]+)\s+import', ln.strip())
            if m2:
                covered_mods.add(m2.group(1).split('.')[-1])

        found = []   # (module, names)
        n = len(consts)
        for i in range(n - 1):
            m = consts[i]
            if not _ident(m) or m.startswith('_') or len(m) < 2:
                continue
            t = consts[i + 1]
            if (not isinstance(t, tuple) or not t or len(t) > 40
                    or not all(_ident(x) for x in t)):
                continue
            # V100: NON skippare i moduli gia' coperti: la riga nativa puo'
            # avere il ALIAS come nome diretto (``from .x import Alias``
            # invece di ``from .x import Nome as Alias``) — la sostituzione
            # ad evidenza qui sotto la corregge.
            # conferma: i nomi della tuple riappaiono come stringhe
            # standalone poco dopo (layout Nuitka del from-import)
            window = consts[i + 2:i + 2 + 2 * len(t) + 4]
            window_strs = {x for x in window if isinstance(x, str)}
            hits = sum(1 for x in t if x in window_strs)
            if hits < len(t):
                continue
            # il modulo deve essere plausibile: noto come import del
            # module-init O sibling del package corrente
            # V100 GATE STRETTO: il modulo deve essere nell'evidenza
            # IMPORT del module-init (IMPORT_MODULE/IMPORT_NAME sollevati
            # nativamente).  Il vecchio fallback ``is_package`` accettava
            # QUALSIASI stringa-ident adiacente a una tuple in un package
            # — incluse stringhe di CLASSI (``'StealthConnection'`` seguito
            # dalla tuple di un ALTRO import) → ``from .StealthConnection
            # import config`` fantasma.  imports_mod copre i casi reali
            # (sibling relativi inclusi, come 'ethereum' in bnb_bsc_eth).
            plausible = (m in set(getattr(self.mca, 'imports_mod', ()) or ()))
            if not plausible:
                continue
            if any(m == fm and set(names) == set(t) for fm, names in found):
                continue
            # V100: ALIAS.  Layout Nuitka di ``from X import A as B``:
            # X, (A,), A, B — il nome ripetuto seguito da un identificatore
            # DIVERSO.  Vincolo ANTI-FALSO-POSITIVO: dopo l'alias NON puo'
            # iniziare un altro layout from-import (tuple di idents o
            # stringa-modulo con tuple subito dopo), perche' in quel caso
            # il presunto alias e' il MODULO dell'import successivo.
            rendered_names = list(t)
            if len(t) == 1 and i + 4 < n:
                # layout: [i]=modulo, [i+1]=(A,), [i+2]=A, [i+3]=alias
                after = consts[i + 2:i + 5]
                cand = after[1] if len(after) >= 2 else None
                nxt = after[2] if len(after) >= 3 else None
                starts_import = (
                    (isinstance(nxt, tuple) and nxt
                     and all(isinstance(x, str) and _ident(x) for x in nxt))
                    or (isinstance(cand, str) and _ident(cand)
                        and isinstance(nxt, tuple)))
                if (len(after) >= 2 and after[0] == t[0]
                        and isinstance(cand, str)
                        and _ident(cand) and cand != t[0]
                        and cand not in t
                        and not cand.startswith('_')
                        and not starts_import):
                    rendered_names = [f'{t[0]} as {cand}']
            # V100: se esiste GIA' un from-import della stessa m con gli
            # stessi nomi base, NON aggiungere ne' sostituire nulla (il
            # nativo era corretto).  Il replace avviene solo per il caso
            # alias-provato o plain import.
            has_alias = any(' as ' in x for x in rendered_names)
            existing_for_m = []
            for ln in lines:
                fm = _re.match(
                    r'\s*from\s+(?:\.+)?' + _re.escape(m) +
                    r'\s+import\s+(.+?)\s*$', ln)
                if fm:
                    existing_for_m.append(
                        {x.strip() for x in fm.group(1).split(',')})
            base_set = {x.split(' as ')[0].strip() for x in rendered_names}
            if any(existing == base_set for existing in existing_for_m):
                continue    # gia' corretto: non duplicare
            if existing_for_m and not has_alias:
                continue    # nativo presente e nessuna prova di alias: lascia
            found.append((m, rendered_names))

        if not found:
            return lines
        # stile relativo del modulo: se una riga from-import esistente usa
        # i dots (livello >0), le nuove righe per sibling coerenti usano lo
        # stesso livello (l'evidenza nativa IMPORT_MODULE level).
        _rel_style = 0
        for ln in lines:
            fm0 = _re.match(r'\s*from\s+(\.+)', ln)
            if fm0:
                _rel_style = len(fm0.group(1))
                break
        imported_names = set()
        for m, names in found:
            rel = (is_package and '.' not in m and pkg_prefix)
            mod_ref = ('.' * _rel_style + m) if _rel_style else (
                ('.' + m) if rel else m)
            new_line = f'from {mod_ref} import {", ".join(names)}'
            imported_names.update(
                n.split(' as ')[0].strip() for n in names)
            # sostituisci l'eventuale plain import dello stesso modulo, o
            # un from-import NATIVO della stessa m con i nomi SBAGLIATI
            # (l'alias emesso come nome diretto): l'evidenza del pool
            # (modulo + tuple + nome + alias) e' piu' forte del nativo.
            base_names = {x.split(' as ')[0].strip() for x in names}
            alias_only = {
                x.split(' as ')[1].strip() for x in names if ' as ' in x}
            replaced = False
            for idx, ln in enumerate(lines):
                if _re.fullmatch(
                        r'\s*import\s+' + _re.escape(m) + r'\s*',
                        ln):
                    lines[idx] = new_line
                    replaced = True
                    break
                fm = _re.match(
                    r'\s*from\s+(\.*)' + _re.escape(m) +
                    r'\s+import\s+(.+?)\s*$', ln)
                if fm:
                    existing = {x.strip() for x in fm.group(2).split(',')}
                    if existing != base_names and (
                            existing == alias_only
                            or existing <= base_names | alias_only):
                        lines[idx] = new_line
                        replaced = True
                        break
            if not replaced:
                lines.append(new_line)
        # V100: PLAIN IMPORT per i moduli referenziati non coperti da
        # from-import: ``imports_mod`` e' evidenza (tabella moduli del
        # binary / stdlib / pypi noti).  Senza questi, i nomi usati nei
        # corpi restano non-definiti e il sorgente non gira.
        try:
            _covered = set()
            for ln in lines:
                m0 = _re.match(r'\s*(?:from|import)\s+([.\w]+)', ln)
                if m0:
                    _covered.add(m0.group(1).lstrip('.').split('.')[0])
            for m in getattr(self.mca, 'imports_mod', ()) or ():
                if m not in _covered and m not in covered_mods:
                    lines.append(f'import {m}')
                    _covered.add(m)
        except Exception:
            pass
        # ``__all__``: lista costante di stringhe identica all'insieme dei
        # nomi appena importati — l'idioma standard del package __init__.
        if imported_names and not any(
                _re.match(r'\s*__all__\s*=', ln) for ln in lines):
            for c in consts:
                if (isinstance(c, list) and c
                        and all(isinstance(x, str) and _ident(x) for x in c)
                        and set(c) == imported_names):
                    lines.append('__all__ = [' +
                                 ', '.join(repr(x) for x in c) + ']')
                    break
        return lines

    @staticmethod
    def _symbol_children(sym, _path=None):
        if not isinstance(sym, NdxSV):
            return
        if _path is None:
            _path = set()
        marker = id(sym)
        if marker in _path:
            return
        _path.add(marker)
        try:
            for value in (sym.a, sym.b, sym.c):
                if isinstance(value, NdxSV):
                    yield value
                    yield from ModuleEmitter._symbol_children(value, _path)
                elif isinstance(value, (list, tuple)):
                    for item in value:
                        if isinstance(item, NdxSV):
                            yield item
                            yield from ModuleEmitter._symbol_children(
                                item, _path)
        finally:
            _path.discard(marker)

    @staticmethod
    def _static_metadata_value(node, expected_type):
        """Return a statically proven metadata object from a symbolic node."""
        if node is None:
            return None
        candidates = ([node] + list(ModuleEmitter._symbol_children(node))) \
            if isinstance(node, NdxSV) else []
        for candidate in candidates:
            if candidate.op == 'const' and isinstance(
                    candidate.a, expected_type):
                return candidate.a
        return None

    def _function_abi_metadata(self, node):
        """Decode the invariant ``Nuitka_Function_New`` metadata ABI.

        The function-maker decoder normalises each supported native ABI to
        this seven-field intermediate shape.  Metadata consumers therefore
        validate the shape itself instead of coupling semantic recovery to a
        particular executable container or host ABI.  Constants adjacent to
        the call are deliberately ignored: they may instead be annotations,
        import-name tuples or keyword-name transport arrays.
        """
        if not (isinstance(node, NdxSV) and node.op == 'func_new' and
                isinstance(node.b, list) and
                len(node.b) >= 6):
            return {}
        args = node.b + [None]
        if not (isinstance(args[0], NdxSV) and args[0].op == 'gaddr' and
                isinstance(args[1], NdxSV) and args[1].op == 'const' and
                isinstance(args[1].a, str) and
                isinstance(args[3], NdxSV) and
                args[3].op in ('gslot', 'codeobj')):
            return {}
        return {
            'positional': self._static_metadata_value(args[4], tuple),
            'keyword': self._static_metadata_value(args[5], dict),
            'annotations': self._static_metadata_value(args[6], dict),
        }

    @staticmethod
    def _is_module_bind_call(root):
        """True per le call che legano un nome nel namespace del modulo.

        Riconosce sia gli helper ``UPDATE_STRING_DICT*`` nominati (build con
        firma/simboli) sia, sulle build senza simboli (MinGW/ELF stripped),
        la chiamata generica ``via:PyDict_SetItem``. L'analisi IPA-SRA può
        omettere dal tracking l'argomento dict (rcx), lasciando gli argomenti
        shiftati: in module code le PyDict_SetItem sono ESATTAMENTE i
        binding del namespace, quindi il nome const identificatore tra gli
        argomenti è la prova del bind."""
        if not (isinstance(root, NdxSV) and root.op == 'apicall'):
            return False
        name = str(root.a)
        if name.startswith('UPDATE_STRING_DICT'):
            return True
        if name in ('via:PyDict_SetItem', 'PyDict_SetItem'):
            args = root.b or []
            if bool(args) and getattr(args[0], 'op', None) == 'moddict':
                return True
            return any(a is not None and a.op == 'const' and
                       isinstance(a.a, str) and a.a.isidentifier()
                       for a in args)
        return False

    def _hard_import_getter_name(self, va):
        """Module name of a Nuitka IMPORT_HARD_<NAME>() getter.

        Fingerprint (ImportCodes.getImportModuleHardCode): a cached-null
        test, one ``lea rcx, [rip+cstr]`` with the dotted module name, a
        single call to the PyImport_ImportModule IAT slot, and the result
        cached into a rip slot.  A plain global assignment can never match
        this triple, so emitting ``import <name>`` from it never
        fabricates.
        """
        bounds = self.img.function_bounds(va)
        if bounds is None:
            return None
        lea_name = None
        ncall = 0
        iat_import = False
        cache_store = False
        first_arg = 'rcx' if self.img.fmt == 'pe' else 'rdi'
        for ins in self.mca.fd.insns(
                va, max_bytes=min(0x60, bounds[1] - va), stop_at_ret=False):
            if ins.mnemonic == 'ret':
                break
            ops = split_ops(ins.op_str)
            if ins.mnemonic == 'lea' and len(ops) == 2 and \
                    subreg64(ops[0]) == first_arg and 'rip' in ops[1]:
                target = rip_target(ins)
                try:
                    lea_name = self.img.read_cstr(target, 256) \
                        if target else None
                except Exception:
                    lea_name = None
            elif ins.mnemonic == 'call':
                ncall += 1
                if ins.op_str.startswith('0x'):
                    continue
                slot = rip_target(ins)
                name = self.img.imports.get(slot) if slot else None
                if name == 'PyImport_ImportModule':
                    iat_import = True
            elif ins.mnemonic == 'mov' and len(ops) == 2 and \
                    ops[0].startswith('qword ptr [rip') and \
                    subreg64(ops[1]) == 'rax':
                cache_store = True
        if ncall == 1 and iat_import and cache_store and lea_name and \
                re.fullmatch(r'[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*', lea_name):
            return lea_name
        return None

    def _recover_import_lines(self, lifter):
        """Recover Python import bindings from native module initialisation.

        ``IMPORT_MODULE`` produces the parent module temporarily; only an
        ``UPDATE_STRING_DICT*`` proves which names are actually bound in the
        module namespace.  This distinguishes ``from a import b`` from
        ``import a`` without consulting source names or sample patterns.
        """
        operations = sorted(
            (op for block in lifter.blocks.values() for op in block.ops),
            key=lambda op: op.va)
        bound = set()
        imported = []
        seen_import_nodes = set()

        def import_level(node):
            if not isinstance(node, NdxSV) or node.op != 'import':
                return 0
            args = node.b if isinstance(node.b, list) else []
            # IMPORT_MODULE5: tstate, name, globals, locals, fromlist, level.
            if len(args) >= 6:
                level_node = args[5]
                if isinstance(level_node, NdxSV) and \
                        level_node.op == 'const' and \
                        isinstance(level_node.a, int):
                    return max(0, level_node.a)
            # BUILTIN___IMPORT__ senza tstate in testa: il level è l'ULTIMO
            # argomento (area stack uscente).
            if args:
                level_node = args[-1]
                if isinstance(level_node, NdxSV) and \
                        level_node.op == 'const' and \
                        isinstance(level_node.a, int):
                    return max(0, level_node.a)
            for child in self._symbol_children(node):
                if child.op == 'import':
                    level = import_level(child)
                    if level:
                        return level
            return 0

        for op in operations:
            root = op.a if isinstance(op.a, NdxSV) else None
            nodes = ([root] + list(self._symbol_children(root))) if root \
                is not None else []
            for node in nodes:
                if node.op == 'import' and id(node) not in seen_import_nodes:
                    seen_import_nodes.add(id(node))
                    parent = next((child.a for child in
                                   self._symbol_children(node)
                                   if child.op == 'import' and
                                   isinstance(child.a, str)), None)
                    imported.append((op.va, node.a, parent,
                                     import_level(node)))
            if self._is_module_bind_call(root):
                for arg in (root.b or []):
                    if arg is not None and arg.op == 'const' and \
                            isinstance(arg.a, str) and arg.a.isidentifier():
                        bound.add(arg.a)

        # Binding ordinati per VA con il loro VALORE: il valore di un bind
        # è la prova diretta della natura dell'import (modello valido sia
        # per IMPORT_MODULE5/IMPORT_NAME_FROM_MODULE sia per il
        # BUILTIN___IMPORT__ di Nuitka 2.x / MinGW):
        #   value == import(M)                     → ``import M``
        #   value == getattr(import(M), nome)      → ``from M import nome``
        #   value == import(nome) con figlio M     → ``from M import nome``
        binds = []
        for op in operations:
            root = op.a if isinstance(op.a, NdxSV) else None
            if not self._is_module_bind_call(root):
                continue
            args = [a for a in (root.b or []) if a is not None]
            name = next((a.a for a in args
                         if a.op == 'const' and isinstance(a.a, str)
                         and a.a.isidentifier()), None)
            if name is not None and args:
                binds.append((op.va, name, args[-1]))

        from_names = {}
        plain = []
        plain_set = set()
        classified = set()
        for va, name, value in binds:
            v = value
            if not isinstance(v, NdxSV):
                continue
            # A hard-import getter result (``IMPORT_HARD_<name>()``) is the
            # compiled form of a plain ``import <name>`` bound into the
            # module namespace; its fingerprint proves the module name.
            if v.op == 'nativecall' and isinstance(v.a, str) and \
                    v.a.startswith('sub_'):
                try:
                    getter_va = int(v.a[4:], 16)
                except ValueError:
                    getter_va = None
                if getter_va is not None:
                    hard_name = self._hard_import_getter_name(getter_va)
                    if hard_name:
                        v = ndx_k('import', hard_name)
            # Hard-import self-binding: the getter caches the freshly
            # imported module under its own name, so the bind reads back
            # ``bind(name, global name)`` — the compiled form of a plain
            # ``import <name>``.
            if v.op == 'global' and v.a == name:
                if name not in plain_set:
                    plain.append(name)
                    plain_set.add(name)
                classified.add(name)
                continue
            if v.op == 'import' and v.a is None and isinstance(v.b, list):
                # IMPORT_MODULE5 / BUILTIN___IMPORT__ with the module name
                # passed as a separate argument (not inline in `a`):
                # extract the first const-str identifier from the args.
                mod_name = next(
                    (a.a for a in v.b
                     if isinstance(a, NdxSV) and a.op == 'const' and
                     isinstance(a.a, str) and
                     re.fullmatch(r'[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*', a.a)),
                    None)
                if mod_name:
                    v = ndx_k('import', mod_name, v.b)
            if v.op == 'import' and isinstance(v.a, str):
                child = next((c for c in self._symbol_children(v)
                              if c.op == 'import' and
                              isinstance(c.a, str)), None)
                if child is not None and child.a != v.a:
                    # from-name MSVC: il nodo import del from-name porta il
                    # modulo padre come figlio.
                    source = '.' * import_level(v) + child.a
                    bucket = from_names.setdefault(source, [])
                    if name not in bucket:
                        bucket.append(name)
                else:
                    key = '.' * import_level(v) + v.a
                    if key not in plain_set:
                        plain.append(key)
                        plain_set.add(key)
                classified.add(name)
            elif v.op == 'getattr' and isinstance(v.a, NdxSV) and \
                    v.a.op == 'import' and isinstance(v.a.a, str):
                source = '.' * import_level(v.a) + v.a.a
                bucket = from_names.setdefault(source, [])
                if name not in bucket:
                    bucket.append(name)
                classified.add(name)

        # Eventi import in ordine di VA (inclusi gli IMPORT_HARD_* e i moduli
        # "" dei from-import puri ``from .. import x``): servono per
        # attribuire il modulo padre ai from-import tramite slot condiviso.
        import_events = [(va, nm, lv) for va, nm, _p, lv in imported
                         if isinstance(nm, str)]
        known_modules = set(self.mca.imports_mod or ())
        for va, name, parent, level in imported:
            if not isinstance(name, str) or not name:
                continue
            if name in classified:
                continue
            if parent and parent != name and name in bound:
                source = '.' * level + parent
                bucket = from_names.setdefault(source, [])
                if name not in bucket:
                    bucket.append(name)
                classified.add(name)
            elif name in bound and name not in plain_set:
                if name not in known_modules and '.' not in name:
                    # Nome bound senza modulo padre: e' un from-import il cui
                    # riferimento modulo passa da uno slot statico condiviso
                    # (es. ``from typing import Any`` via IMPORT_HARD_TYPING).
                    # Nuitka inizializza lo slot nel blocco IMMEDIATAMENTE
                    # precedente. La sorgente di un from-import non e' mai
                    # essa stessa un nome bound (l'oggetto modulo resta un
                    # temporaneo): questo esclude i from-name precedenti
                    # ('sha256', 'IntEnum', …) e lascia solo le init di
                    # modulo vere (IMPORT_MODULE5 / IMPORT_HARD_*).
                    source = None
                    for other_va, other_name, other_level in import_events:
                        if (other_va < va and other_name != name
                                and other_name not in bound
                                and va - other_va < 0x800):
                            source = '.' * other_level + other_name
                    if source and source != name:
                        bucket = from_names.setdefault(source, [])
                        if name not in bucket:
                            bucket.append(name)
                        classified.add(name)
                        continue
                plain.append('.' * level + name)
                plain_set.add('.' * level + name)

        # Keep deterministic target order.  The fallback is needed for older
        # Nuitka builds whose UPDATE helper is inlined beyond recognition.
        from_names = {src: names for src, names in from_names.items()
                      if src.lstrip('.') != '__future__'}
        lines = [f'import {name}' for name in plain if not name.startswith('.')]
        lines.extend(f'from {name} import *' for name in plain
                     if name.startswith('.'))
        for parent, names in from_names.items():
            lines.append(f'from {parent} import {", ".join(names)}')
        if not lines:
            # Older MSVC builds may inline the builtin-dict lookup of
            # ``__import__`` so aggressively that the callable reaches
            # CALL_FUNCTION_WITH_ARGS as an unclassified comparison value.
            # Its argument transport remains exact: a module-name literal is
            # stored in an outgoing stack slot, that same stack address is
            # consumed by the call, and the returned module/name is then read
            # from the module namespace.  Recover that data-flow pattern; no
            # module-name catalogue or source-specific spelling is involved.
            module_name_rx = re.compile(
                r'^[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*$')
            namespace_starts = [
                op.va for op in operations
                if op.kind == 'store_sub' and
                isinstance(op.b, NdxSV) and op.b.op == 'const' and
                op.b.a == '__qualname__']
            namespace_end = min(namespace_starts, default=float('inf'))
            argument_stores = [
                op for op in operations
                if op.va < namespace_end and op.kind == 'store' and
                isinstance(op.a, tuple) and len(op.a) == 3 and
                op.a[0] == 'mem' and isinstance(op.b, NdxSV) and
                op.b.op == 'const' and isinstance(op.b.a, str) and
                module_name_rx.fullmatch(op.b.a)]

            def operation_nodes(operation):
                nodes = []
                for root in (operation.a, operation.b, operation.c):
                    if isinstance(root, NdxSV):
                        nodes.append(root)
                        nodes.extend(self._symbol_children(root))
                return nodes

            recovered_lines = []
            for store_index, store in enumerate(argument_stores):
                same_slot_next = next((
                    later.va for later in argument_stores[store_index + 1:]
                    if later.a == store.a), namespace_end)
                region = [op for op in operations
                          if store.va < op.va < same_slot_next]
                base, offset = store.a[1], store.a[2]
                call_operation = None
                for candidate in region:
                    if candidate.kind != 'calc' or \
                            not isinstance(candidate.a, NdxSV) or \
                            candidate.a.op != 'call':
                        continue
                    candidate_nodes = operation_nodes(candidate)
                    transported_pointer = any(
                        node.op == 'stackaddr' and node.a == base and
                        node.b == offset for node in candidate_nodes)
                    # Once a CALL_FUNCTION_WITH_POS_ARGS<n> helper has been
                    # identified, its constant tuple is expanded and the
                    # stack-pointer transport intentionally disappears from
                    # the semantic node.  The exact same module-name object in
                    # the call arguments is the equivalent, stronger fact.
                    transported_value = any(
                        node.op == 'const' and node.a == store.b.a
                        for node in candidate_nodes)
                    if transported_pointer or transported_value:
                        call_operation = candidate
                        break
                if call_operation is None:
                    continue
                tail = [op for op in region if op.va > call_operation.va]
                # The import result is not required to retain an ``import``
                # semantic tag.  In stripped MSVC builds the cached
                # ``__import__`` callable can look like a comparison, but the
                # five Python import arguments and the following module-dict
                # bind are still exact.  Join those two independently proven
                # events.  A non-empty fromlist distinguishes ``from M import
                # x`` from ``import M as x`` without a package/name catalogue.
                binding_record = next((
                    record for record in binds
                    if call_operation.va < record[0] < same_slot_next and
                    not record[1].startswith('__')), None)
                if binding_record is not None:
                    _bind_va, binding, _bind_value = binding_record
                    call_nodes = operation_nodes(call_operation)
                    fromlist = []
                    for node in call_nodes:
                        if node.op != 'const' or not isinstance(
                                node.a, (tuple, list)):
                            continue
                        for item in node.a:
                            if isinstance(item, str) and item.isidentifier() \
                                    and item not in fromlist:
                                fromlist.append(item)
                    module_name = store.b.a
                    if binding in fromlist:
                        recovered_lines.append(
                            f'from {module_name} import {binding}')
                    else:
                        natural_binding = module_name.split('.', 1)[0]
                        # V100: un alias che e' esso stesso un NOME MODULO
                        # noto (stdlib/pypi/binary) diverso dalla radice
                        # importata e' quasi sempre un misjoin di binding
                        # (``import math as json`` non e' sorgente reale):
                        # emetti l'import plain.
                        _b_top = binding.split('.', 1)[0]
                        _km_set = getattr(self, 'known_modules', None)                             or set(getattr(self.mca, 'all_module_names', ())
                                   or ())
                        _known_root = (_b_top in _NDX_STDLIB_TOP or
                                       _b_top in _NDX_KNOWN_PYPI_TOP or
                                       any(km == _b_top or
                                           km.startswith(_b_top + '.')
                                           for km in _km_set))
                        import os as _os3
                        if _os3.environ.get('NDX_DBG_IMP'):
                            print(f"[IMP] mod={module_name} binding={binding} "
                                  f"known_root={_known_root} b_top={_b_top}")
                        if binding != natural_binding and not _known_root:
                            recovered_lines.append(
                                f'import {module_name} as {binding}')
                        else:
                            recovered_lines.append(f'import {module_name}')
                    continue
                global_names = []
                attributes = []
                for candidate in tail:
                    nodes = operation_nodes(candidate)
                    for node in nodes:
                        if node.op == 'global' and isinstance(node.a, str) and \
                                node.a.isidentifier() and \
                                node.a not in global_names:
                            global_names.append(node.a)
                        if node.op == 'getattr' and isinstance(node.b, str) and \
                                node.b.isidentifier() and \
                                node.b not in attributes:
                            attributes.append(node.b)
                module_name = store.b.a
                imported_attributes = [name for name in attributes
                                       if name in global_names]
                if imported_attributes:
                    recovered_lines.append(
                        f'from {module_name} import '
                        f'{", ".join(imported_attributes)}')
                    continue
                natural_binding = module_name.split('.', 1)[0]
                binding = natural_binding if natural_binding in global_names \
                    else next((name for name in global_names
                               if name not in ('__name__', '__package__',
                                               '__builtins__', '__loader__',
                                               '__spec__', '__doc__',
                                               '__file__', '__cached__')),
                              None)
                if binding is not None:
                    # V100: stessa guardia anti-misjoin — un binding che e'
                    # un nome-modulo noto diverso dalla radice importata
                    # appartiene a un ALTRO import: emetti plain.
                    _b2 = binding.split('.', 1)[0]
                    _kr2 = (_b2 in _NDX_STDLIB_TOP or
                            _b2 in _NDX_KNOWN_PYPI_TOP or
                            _b2 in set(getattr(self.mca, 'imports_mod', ())
                                       or ()))
                    line = f'import {module_name}'
                    if binding != natural_binding and not _kr2:
                        line += f' as {binding}'
                    recovered_lines.append(line)
            lines = list(dict.fromkeys(recovered_lines))
        if not lines:
            lines = [f'import {name}' for name in self.mca.imports_mod
                     if isinstance(name, str) and name
                     and not name.startswith('_virtualenv')
                     and name != 'sys']
        return lines

    def _recover_function_metadata(self, lifter):
        """Recover annotations/defaults/decorators for module-level functions."""
        operations = sorted(
            (op for block in lifter.blocks.values() for op in block.ops),
            key=lambda op: op.va)
        functions = {
            str(info.get('qualname')): info for info in self.mca.functions
            if isinstance(info.get('qualname'), str) and
            '.' not in info.get('qualname') and
            '<locals>' not in info.get('qualname')}
        code_by_name = {str(co.qualname or co.name): co
                        for co in self.code_objects}
        bindings = []
        for op in operations:
            root = op.a
            if not (op.kind == 'calc' and root is not None and
                    self._is_module_bind_call(root)):
                continue
            names = [arg.a for arg in (root.b or [])
                     if arg is not None and arg.op == 'const' and
                     isinstance(arg.a, str) and arg.a in functions]
            if names:
                bindings.append((op.va, names[-1], op))

        def _decorator_label(sym):
            """Source text of a callable symbol used as a decorator."""
            if not isinstance(sym, NdxSV):
                return None
            if sym.op == 'global' and isinstance(sym.a, str) and \
                    sym.a.isidentifier():
                return sym.a
            if sym.op == 'mcall' and isinstance(sym.a, NdxSV) and \
                    sym.a.op == 'global' and isinstance(sym.a.a, str) and \
                    sym.a.a.isidentifier():
                args = sym.b if isinstance(sym.b, list) else (
                    [sym.b] if isinstance(sym.b, NdxSV) else [])
                if args and isinstance(args[0], NdxSV) and \
                        args[0].op == 'const' and \
                        isinstance(args[0].a, str) and \
                        args[0].a.isidentifier():
                    return f'{sym.a.a}.{args[0].a}'
            if sym.op in ('call', 'kwcall'):
                # A parameterised decorator — ``@traced("sum")``,
                # ``@wraps(function)``, ``@dataclass(slots=True)`` — is a call
                # whose callee is the decorator factory. Without this the
                # label is None and every decorated function loses its
                # decorator, because the chain terminates at the func_new
                # with no label recorded.
                base = _decorator_label(sym.a)
                if base is None:
                    return None
                rendered = []
                for arg in (sym.b if isinstance(sym.b, list) else []):
                    if not isinstance(arg, NdxSV):
                        continue
                    if arg.op == 'const':
                        rendered.append(_const_repr(arg.a))
                    elif arg.op in ('global', 'var', 'loc') and \
                            isinstance(arg.a, str) and arg.a.isidentifier():
                        rendered.append(arg.a)
                    else:
                        return None
                for kw in (sym.c if isinstance(sym.c, list) else []):
                    if not (isinstance(kw, NdxSV) and kw.op == 'kwarg' and
                            isinstance(kw.a, str) and kw.a.isidentifier() and
                            isinstance(kw.b, NdxSV) and kw.b.op == 'const'):
                        return None
                    rendered.append('%s=%s' % (kw.a, _const_repr(kw.b.a)))
                if not rendered:
                    return None
                return '%s(%s)' % (base, ', '.join(rendered))
            return None

        def _unwrap_decorators(value, fname):
            """Decorator chain around the exact MAKE_FUNCTION of ``fname``.

            ``name = deco2(deco1(MAKE_FUNCTION(name)))`` is how Nuitka lowers
            decorated module functions; every wrapper call in that chain
            carries either the function creation itself or the next wrapper
            call as its argument.  Callees are proven decorators only when
            the chain terminates at the creation of the bound name."""
            labels = []
            sym = value
            for _ in range(8):
                if not (isinstance(sym, NdxSV) and
                        sym.op in ('call', 'kwcall')):
                    return None
                label = _decorator_label(sym.a)
                inner = None
                for arg in (sym.b or []):
                    if not isinstance(arg, NdxSV):
                        continue
                    if arg.op == 'func_new':
                        created = next(
                            (x.a for x in (arg.b or [])
                             if isinstance(x, NdxSV) and x.op == 'const' and
                             isinstance(x.a, str)), None)
                        if created == fname:
                            if label:
                                labels.append(label)
                            return labels
                        return labels or None
                    if arg.op in ('call', 'kwcall'):
                        inner = arg
                        break
                if label:
                    labels.append(label)
                if inner is None:
                    return labels or None
                sym = inner
            return labels or None

        result = {}
        previous = 0
        for binding_va, name, bind_op in bindings:
            region = [op for op in operations if previous < op.va < binding_va]
            copies = []
            for op in region:
                if not (op.kind == 'calc' and op.a is not None and
                        op.a.op == 'apicall' and op.a.a == 'DICT_COPY'):
                    continue
                for argument in (op.a.b or []):
                    if argument is not None and argument.op == 'const' and \
                            isinstance(argument.a, dict):
                        copies.append((op.va, argument.a))
            annotations = {}
            keyword_defaults = {}
            if copies:
                annotation_va, annotations = max(copies)
                for copy_va, copied in copies:
                    if copy_va < annotation_va:
                        keyword_defaults.update(copied)

            positional_defaults = ()
            maker_calls = [op for op in region if op.kind == 'calc' and
                           op.a is not None and op.a.op == 'func_new']
            if maker_calls:
                creation = max(maker_calls, key=lambda op: op.va).a
                abi_metadata = self._function_abi_metadata(creation)
                if abi_metadata.get('positional') is not None:
                    positional_defaults = abi_metadata['positional']
                if abi_metadata.get('keyword') is not None:
                    keyword_defaults = abi_metadata['keyword']
                if abi_metadata.get('annotations') is not None:
                    annotations = abi_metadata['annotations']

            # Decorators: (1) proven call chain around MAKE_FUNCTION in the
            # bind value; (2) otherwise a bound-module callable materialised
            # in the same region (``contextlib.contextmanager``: the wrapper
            # call itself is a register call the lifter does not op-encode).
            decorators = []
            for arg in (bind_op.a.b or []):
                if isinstance(arg, NdxSV) and arg.op == 'call':
                    chain = _unwrap_decorators(arg, name)
                    if chain:
                        decorators = chain
                        break
            if not decorators:
                made_here = any(
                    op.kind == 'calc' and op.a is not None and
                    op.a.op == 'func_new' and
                    any(isinstance(x, NdxSV) and x.op == 'const' and
                        x.a == name
                        for x in (op.a.b or []) if isinstance(x, NdxSV))
                    for op in region)
                if made_here:
                    for op in region:
                        if not (op.kind == 'calc' and op.a is not None and
                                op.a.op == 'mcall'):
                            continue
                        label = _decorator_label(op.a)
                        if label and label not in decorators and \
                                '.' in label and \
                                label.split('.', 1)[0] in (
                                    getattr(self.mca, 'imports_mod', ()) or ()):
                            decorators.append(label)

            result[name] = {
                'annotations': annotations,
                'defaults': {
                    'positional': positional_defaults,
                    'keyword': keyword_defaults,
                },
                'decorators': decorators,
                'code': code_by_name.get(name),
            }
            previous = binding_va
        if not result:
            # Bind helpers carry no resolvable names in this build: anchor on
            # the MAKE_FUNCTION sites themselves.  Evidence per module-level
            # function:
            #  * a ``call`` op whose argument list contains exactly this
            #    function creation — the decorator wrapper chain;
            #  * otherwise a bound-module callable (``module.name``) built in
            #    a short window right after the creation (``@
            #    contextlib.contextmanager``: the wrapper call is a register
            #    call the lifter does not op-encode).
            def _func_new_name(sym):
                return next((x.a for x in (sym.b or [])
                             if isinstance(x, NdxSV) and x.op == 'const' and
                             isinstance(x.a, str)), None)

            func_news = []
            for op in operations:
                if op.kind == 'calc' and op.a is not None and \
                        op.a.op == 'func_new' and isinstance(
                            _func_new_name(op.a), str) and \
                        _func_new_name(op.a) in functions:
                    func_news.append((op, _func_new_name(op.a)))
            call_ops = [op for op in operations
                        if op.kind == 'calc' and op.a is not None and
                        op.a.op == 'call']
            known_imports = set(getattr(self.mca, 'imports_mod', ()) or ())
            for created_op, name in func_news:
                created_key = _nbc_sv(created_op.a)
                decorators = []
                for call_op in call_ops:
                    wraps_creation = any(
                        isinstance(arg, NdxSV) and arg.op == 'func_new' and
                        _nbc_sv(arg) == created_key
                        for arg in (call_op.a.b or []))
                    if not wraps_creation:
                        continue
                    label = _decorator_label(call_op.a.a)
                    if label and label not in decorators:
                        decorators.append(label)
                if not decorators:
                    for op in operations:
                        if not (created_op.va < op.va <
                                created_op.va + 0x400):
                            continue
                        if not (op.kind == 'calc' and op.a is not None and
                                op.a.op == 'mcall'):
                            continue
                        label = _decorator_label(op.a)
                        if label and '.' in label and \
                                label.split('.', 1)[0] in known_imports and \
                                label not in decorators:
                            decorators.append(label)
                if decorators:
                    result[name] = {
                        'annotations': {},
                        'defaults': {'positional': (), 'keyword': {}},
                        'decorators': decorators,
                        'code': code_by_name.get(name),
                    }
        return result

    def _recover_class_metadata(self, lifter=None):
        """Materialise class namespace writes from the native module body."""
        if lifter is None:
            lifter = BodyLifter2(
                self.img, self.res, self.mca, None, self.mod.func_ptr,
                py_version=self.py_version, is_module_code=True).lift()
        structurer = Structurer(lifter)
        renderer = NdxRenderer(structurer, lifter.varnames, 0)
        operations = sorted(
            (op for block in lifter.blocks.values() for op in block.ops),
            key=lambda op: op.va)

        names = {
            str(op.c.a) for op in operations
            if op.kind == 'store_sub' and op.b is not None and
            op.c is not None and op.b.op == 'const' and
            op.b.a == '__qualname__' and op.c.op == 'const' and
            isinstance(op.c.a, str) and op.c.a.isidentifier()}
        if not names:
            return {}

        qualifiers = []
        for op in operations:
            if op.kind != 'store_sub' or op.b is None or op.c is None:
                continue
            if op.b.op == 'const' and op.b.a == '__qualname__' and \
                    op.c.op == 'const' and op.c.a in names:
                qualifiers.append((op.va, op.c.a, op.a))
        if not qualifiers:
            return {}

        method_names = {}
        for name in names:
            method_names[name] = {
                str((co.qualname or co.name)).split('.', 1)[1]
                for co in self.code_objects
                if str(co.qualname or co.name).startswith(name + '.') and
                '<locals>' not in str(co.qualname or co.name)
            }
            # Older Nuitka code-object builders store only the leaf co_name;
            # MAKE_FUNCTION still carries the exact qualname.  Merge that
            # authoritative source so method namespace writes are not emitted
            # as ``method = make_function()`` class attributes.
            method_names[name].update(
                str(function.get('qualname')).split('.', 1)[1]
                for function in self.mca.functions
                if isinstance(function.get('qualname'), str) and
                function.get('qualname').startswith(name + '.') and
                '<locals>' not in function.get('qualname'))

        def annotation_text(sym):
            if sym is None:
                return None
            if sym.op == 'const' and isinstance(sym.a, str):
                return sym.a
            try:
                return renderer.expr(sym)
            except Exception:
                return None

        def expression_text(sym):
            try:
                return renderer.expr(sym, top_assign=True)
            except Exception:
                return None

        result = {}
        for index, (start, name, namespace) in enumerate(qualifiers):
            end = qualifiers[index + 1][0] if index + 1 < len(qualifiers) \
                else max((op.va for op in operations), default=start) + 1
            region = [op for op in operations if start <= op.va < end]
            annotations = []
            defaults = {}
            assignments = []
            methods = method_names.get(name, set())
            method_store = {}
            properties = set()
            method_decorators = {}
            declared_bases = []

            for op in region:
                if op.kind != 'store_sub' or op.b is None or \
                        op.b.op != 'const' or not isinstance(op.b.a, str):
                    continue
                key = op.b.a
                target = op.a
                if key == '__orig_bases__' and op.c is not None and \
                        op.c.op == 'const' and isinstance(
                            op.c.a, (tuple, list)):
                    rendered_bases = [
                        str(item) if isinstance(item, str) and
                        str(item).isidentifier() else _const_repr(item)
                        for item in op.c.a]
                    if all(rendered_bases):
                        declared_bases = rendered_bases
                    continue
                is_annotation = (target is not None and target.op == 'sub' and
                                 target.b is not None and
                                 target.b.op == 'const' and
                                 target.b.a == '__annotations__')
                if is_annotation:
                    annotations.append((key, annotation_text(op.c)))
                    continue
                if key in methods:
                    method_store[key] = op
                    value = op.c
                    if value is not None and value.op == 'call' and \
                            isinstance(value.a, NdxSV) and \
                            value.a.op == 'api_symbol' \
                            and value.a.a == 'PyProperty_Type':
                        properties.add(key)
                    if value is not None and value.op == 'call':
                        decorator = _ndx_method_decorator_name(value.a)
                        if decorator and any(
                                isinstance(arg, NdxSV) and arg.op == 'func_new'
                                for arg in (value.b or [])):
                            method_decorators[key] = [decorator]
                    continue
                if key.startswith('__'):
                    continue
                # Attribute writes must target this class's prepared mapping.
                # Accept semantic equality across CFG copies, but never any
                # arbitrary dict/loc in the region: function annotation and
                # kw-default dictionaries are created beside the namespace
                # and otherwise leak argument names as fake class fields.
                if target is namespace or (target is not None and
                                           _sv_eq(target, namespace)):
                    defaults[key] = op.c
                    assignments.append((key, op.c))

            fields = []
            seen_fields = set()
            for field_name, ann in annotations:
                if field_name in seen_fields:
                    continue
                seen_fields.add(field_name)
                default = defaults.get(field_name)
                fields.append({
                    'name': field_name,
                    'annotation': ann,
                    'default': expression_text(default) if default else None,
                })

            enum_assignments = []
            if not fields:
                for key, value in assignments:
                    if key not in methods:
                        rendered = expression_text(value)
                        if rendered is not None:
                            enum_assignments.append((key, rendered))

            method_annotations = {}
            method_defaults = {}
            ordered_method_stores = sorted(
                method_store.items(), key=lambda pair: pair[1].va)
            previous_store_va = start
            for method, store in ordered_method_stores:
                copies = []
                for op in region:
                    if not (previous_store_va < op.va < store.va and
                            op.kind == 'calc' and op.a is not None and
                            op.a.op == 'apicall' and op.a.a == 'DICT_COPY'):
                        continue
                    for arg in (op.a.b or []):
                        if arg is not None and arg.op == 'const' and \
                                isinstance(arg.a, dict):
                            copies.append((op.va, arg.a))
                if copies:
                    annotation_va, annotation_dict = max(copies)
                    method_annotations[method] = annotation_dict
                    keyword_defaults = {}
                    for copy_va, copied in copies:
                        if copy_va < annotation_va:
                            keyword_defaults.update(copied)
                    if keyword_defaults:
                        method_defaults.setdefault(method, {})[
                            'keyword'] = keyword_defaults
                function_value = store.c
                function_nodes = ([function_value] + list(
                    self._symbol_children(function_value))) if isinstance(
                        function_value, NdxSV) else []
                creation = next((node for node in function_nodes
                                 if node.op == 'func_new'), None)
                abi_metadata = self._function_abi_metadata(creation)
                if abi_metadata.get('annotations') is not None:
                    method_annotations[method] = abi_metadata['annotations']
                if abi_metadata.get('keyword') is not None:
                    method_defaults.setdefault(method, {})['keyword'] = \
                        abi_metadata['keyword']
                if abi_metadata.get('positional') is not None:
                    method_defaults.setdefault(method, {})['positional'] = \
                        abi_metadata['positional']
                previous_store_va = store.va

            decorators = []
            preceding = [op for op in operations
                         if start - 0x1000 <= op.va < start and
                         op.kind == 'calc' and op.a is not None and
                         op.a.op == 'kwcall' and
                         op.a.a is not None and op.a.a.op == 'global']
            if preceding:
                best_op = max(preceding, key=lambda op: op.va)
                best = best_op.a
                # V100: un decoratore di classe VERO viene APPLICATO —
                # dopo la creazione della classe una call usa il risultato
                # della kwcall come callable.  Senza quella call la kwcall
                # e' uno statement module-level libero (es. ``init(...)``
                # colorama seguito da altri binding): NON inventare un
                # decoratore.  Il confronto e' strutturale (sv_key) perche'
                # il value numbering duplica i nodi.
                best_key = sv_key(best)
                applied = False
                for op in operations:
                    if op.va <= start or op.kind != 'calc':
                        continue
                    node = op.a
                    if not isinstance(node, NdxSV) or node.op != 'call':
                        continue
                    cands = []
                    if isinstance(node.a, NdxSV):
                        cands.append(node.a)
                    cands.extend(c for c in self._symbol_children(node)
                                 if isinstance(c, NdxSV))
                    for cand in cands:
                        try:
                            if sv_key(cand) == best_key:
                                applied = True
                                break
                        except Exception:
                            continue
                    if applied:
                        break
                if applied:
                    text = expression_text(best)
                    if text:
                        decorators.append(text)

            # Explicit bases are materialised as a PyTuple immediately before
            # the class namespace starts.  Require every element to be a
            # statically renderable type expression, excluding ordinary data
            # tuples used by annotations/defaults.
            base_candidates = []
            for op in operations:
                value = op.a
                if not (op.va < start and op.kind == 'calc' and
                        value is not None):
                    continue
                # A bases tuple belongs to the first class namespace opened
                # after it.  Class bodies may be large, so an address window
                # would be compiler/size dependent.
                if any(op.va < qualifier_va < start
                       for qualifier_va, _qualifier_name, _namespace
                       in qualifiers):
                    continue
                if value.op == 'tuple_build' and value.b and all(
                        item is not None and item.op in (
                            'api_symbol', 'global', 'getattr', 'sub', 'call',
                            'loc', 'var')
                        for item in value.b):
                    rendered = [expression_text(item) for item in value.b]
                    # Optimised builds commonly spill a loaded base class to a
                    # callee-saved location before constructing the tuple.  A
                    # proven tuple in the class-creation region may therefore
                    # contain ``loc`` nodes; accept them only when value
                    # numbering renders every element as a type-like Python
                    # expression, never as a recovery temporary.
                    type_expression = re.compile(
                        r'^[A-Za-z][A-Za-z0-9_.]*(?:\[[^\n]+\])?$')
                    if all(rendered) and all(
                            type_expression.fullmatch(text) and
                            not text.startswith(('_v', '_tmp'))
                            for text in rendered):
                        base_candidates.append((op.va, rendered))
                roots = []
                for root in (op.a, op.b, op.c):
                    if isinstance(root, NdxSV):
                        roots.append(root)
                        roots.extend(self._symbol_children(root))
                for candidate in roots:
                    if candidate.op != 'const' or \
                            not isinstance(candidate.a, tuple) or \
                            not candidate.a:
                        continue
                    if all(isinstance(item, (
                            _NuitkaBuiltinName, _NuitkaExceptionName, type))
                           for item in candidate.a):
                        base_candidates.append((
                            op.va, [_const_repr(item)
                                    for item in candidate.a]))
            bases = max(base_candidates, default=(0, []),
                        key=lambda pair: pair[0])[1]
            if declared_bases:
                bases = declared_bases
            if not bases and index:
                # On older MSVC Nuitka builds the explicit bases tuple is
                # consumed by mro_entries_conversion before symbolic tuple
                # materialisation completes.  Its elements still have a
                # precise lifetime: after the preceding class's final
                # MAKE_FUNCTION and before this class namespace receives
                # __qualname__.  A module-defined base is therefore the last
                # already-defined class loaded in that interval (the previous
                # class binding itself, when present, occurs earlier).  Class
                # attributes/annotations are before the final maker or after
                # __qualname__, so they cannot satisfy this region proof.
                previous_start = qualifiers[index - 1][0]
                between = [op for op in operations
                           if previous_start < op.va < start]
                maker_vas = []
                for candidate_op in between:
                    root = candidate_op.a
                    if candidate_op.kind != 'calc' or \
                            not isinstance(root, NdxSV):
                        continue
                    if root.op == 'func_new' or \
                            (root.op == 'call' and
                             root.a == 'make_function'):
                        maker_vas.append(candidate_op.va)
                maker_boundary = max(maker_vas, default=previous_start)
                earlier_classes = {
                    qualifier_name for qualifier_va, qualifier_name, _space
                    in qualifiers if qualifier_va < start}
                class_loads = []
                for candidate_op in between:
                    if candidate_op.va <= maker_boundary:
                        continue
                    roots = []
                    for root in (candidate_op.a, candidate_op.b,
                                 candidate_op.c):
                        if isinstance(root, NdxSV):
                            roots.append(root)
                            roots.extend(self._symbol_children(root))
                    for node in roots:
                        if node.op == 'global' and \
                                node.a in earlier_classes:
                            class_loads.append((candidate_op.va, node.a))
                if class_loads:
                    bases = [max(class_loads, key=lambda pair: pair[0])[1]]

            result[name] = {
                'fields': fields,
                'assignments': enum_assignments,
                'decorators': decorators,
                'properties': properties,
                'method_decorators': method_decorators,
                'method_annotations': method_annotations,
                'method_defaults': method_defaults,
                'bases': bases,
                'line': next((op.n for op in reversed(operations)
                              if op.va <= start and op.kind == 'line' and
                              isinstance(op.n, int)), None),
                'order': index,
            }
        return result

    # ------------------------------------------------------------------
    def emit(self):
        """→ righe sorgente del modulo."""
        lines = [f'"""HEXPYRION native semantic reconstruction — module '
                 f'{self.mod.name!r}.\nOriginal .py bytes were not embedded.\n'
                 f'by dimareverse"""', '']
        if self.future_annotations:
            lines.extend(['from __future__ import annotations', ''])
        # funzioni dedup per impl
        funcs = {}
        _seen_pubnames = set()
        for f in self.mca.functions:
            iv = f.get('impl_va')
            identity = (('impl', iv) if iv else
                        ('maker', f.get('maker_va')) if f.get('maker_va') else
                        ('slot', f.get('code_obj_slot')))
            if identity[1] is not None and identity not in funcs:
                # V100: la stessa funzione puo' arrivare sia con impl_va
                # che con maker_va (identita' diverse, stesso public_name)
                # → definizione duplicata nell'output.  Prima definizione
                # vince.
                pub = f.get('public_name') or f.get('qualname')
                if pub is not None and pub in _seen_pubnames:
                    continue
                if pub is not None:
                    _seen_pubnames.add(pub)
                funcs[identity] = f
        # code objects per qualname
        cos = self.code_objects or []
        # V100: MATERIALIZE FALLBACK — nessuna funzione nativa recuperata
        # (ABI di creazione funzione non riconosciuta in questa build:
        # maker/impl non trovati) ma code object COMPLETI nel pool
        # costanti. Registra funzioni pseudo dai metadati: firme ESATTE
        # (varnames/argcount/flags/firstlineno dal blob), nested
        # ``<locals>`` dentro il parent, classi dai qualname puntati.
        # I corpi non sollevabili escono marcati [reconstructed-gap]:
        # sorgente reale al posto del solo inventario-costanti.
        if not funcs and cos:
            for co in cos:
                qn = co.qualname or co.name
                if not isinstance(qn, str) or not qn or qn == '<module>':
                    continue
                leaf = qn.rsplit('.', 1)[-1].rsplit('<locals>', 1)[-1]
                if '.<locals>.' in qn:
                    leaf = qn.rsplit('.<locals>.', 1)[-1]
                if not leaf.isidentifier():
                    continue
                if leaf.startswith('<') or qn in (
                        '<genexpr>', '<lambda>', '<listcomp>',
                        '<dictcomp>', '<setcomp>'):
                    continue
                pf = {'qualname': qn, 'public_name': leaf,
                      'impl_va': None, 'maker_va': None,
                      'code_obj_slot': None, 'code_obj': co,
                      '_pseudo': True}
                self.mca.functions.append(pf)
                funcs[('co', id(co))] = pf
        co_by_qn = {}
        for co in cos:
            qn = co.qualname or co.name
            if isinstance(qn, str) and qn and qn not in co_by_qn:
                co_by_qn[qn] = co
        # associa funzioni ↔ code objects per qualname
        for _identity, f in funcs.items():
            if f.get('code_obj') is not None:
                continue
            qn = f.get('qualname')
            if qn and qn in co_by_qn:
                f['code_obj'] = co_by_qn[qn]
        # fallback: QUALNAME assente o non corrispondente (tipico delle
        # build MinGW senza firme) — abbina per NOME semplice il code
        # object non ancora usato. Recupera firma (varnames/argcount) e i
        # nomi delle variabili locali per il lifting dei corpi.
        used_cos = {id(f.get('code_obj')) for f in funcs.values()
                    if f.get('code_obj') is not None}
        for _identity, f in funcs.items():
            if f.get('code_obj') is not None:
                continue
            qn = f.get('qualname') or f.get('public_name') or ''
            simple = str(qn).rsplit('.', 1)[-1]
            if not simple or '<' in simple:
                continue
            for co in cos:
                if id(co) in used_cos:
                    continue
                if co.name == simple:
                    f['code_obj'] = co
                    used_cos.add(id(co))
                    break
        # strutture: classi (qualname con punto), funzioni semplici
        classes = {}     # nome classe → {'line':, 'methods': {nome: (f, co)}}
        plain_funcs = []
        for _identity, f in funcs.items():
            qn = f.get('qualname') or ''
            if not isinstance(qn, str):
                qn = ''
            co = f.get('code_obj')
            if '.' in qn and '<locals>' not in qn and qn not in (
                    '<module>',):
                cls_name, mname = qn.split('.', 1)
                c = classes.setdefault(cls_name, {'methods': {},
                                                  'line': None})
                if co:
                    c['line'] = min(c['line'] or 99999, co.firstlineno or 99999)
                c['methods'][mname] = (f, co)
            else:
                plain_funcs.append((f, co))
        # i code objects di classe danno nome e linea anche senza metodi
        for co in cos:
            qn = co.qualname or co.name
            if isinstance(qn, str) and qn and '.' not in qn and qn != '<module>' and \
                    qn not in ('<genexpr>', '<lambda>', '<listcomp>',
                               '<dictcomp>', '<setcomp>') and \
                    qn in self.class_meta:
                if qn not in classes:
                    classes[qn] = {'methods': {},
                                   'line': co.firstlineno}
                else:
                    classes[qn]['line'] = min(
                        classes[qn]['line'] or 99999,
                        co.firstlineno or 99999)
        for class_name, metadata in self.class_meta.items():
            if class_name not in classes:
                classes[class_name] = {
                    'methods': {},
                    'line': metadata.get('line') or 99999,
                }
            elif metadata.get('line'):
                classes[class_name]['line'] = min(
                    classes[class_name]['line'] or 99999,
                    metadata['line'])
        ordered_classes = sorted(
            self.class_meta, key=lambda class_name:
            self.class_meta[class_name].get('order', 99999))
        for index, class_name in enumerate(ordered_classes):
            if classes[class_name]['line'] not in (None, 99999):
                continue
            following = [classes[name]['line'] for name in
                         ordered_classes[index + 1:]
                         if classes[name]['line'] not in (None, 99999)]
            if following:
                classes[class_name]['line'] = max(
                    1, min(following) - len(following))
        # emissione ordinata per linea
        entries = []
        for cls_name, c in classes.items():
            entries.append(('class', c['line'] or 99999, cls_name, c))
        for f, co in plain_funcs:
            qn = f.get('qualname') or 'func'
            if qn in ('<module>',) or '<locals>' in qn:
                continue
            # ``def`` requires an identifier: lambdas/genexprs/comprehension
            # code objects are expressions, not module-level statements.
            if not str(qn).isidentifier():
                continue
            entries.append(('def', (co.firstlineno if co else None) or
                            99999, qn, (f, co)))
        if self.module_lifter is None:
            for assignment_line, assignment_name, assignment_value in self._recover_module_assignments():
                entries.append(('assign', assignment_line, assignment_name, assignment_value))
        entries.sort(key=lambda e: e[1])
        # Binding provati da IMPORT_* + UPDATE_STRING_DICT*.
        for import_line in self.import_lines:
            lines.append(import_line)
        if self.import_lines:
            lines.append('')
        self._module_definitions = {}
        self._module_definition_markers = {}
        for kind, line, name, payload in entries:
            if kind == 'class':
                self._module_definitions[name] = self._emit_class(name, payload)
            elif kind == 'def':
                f, co = payload
                self._module_definitions[name] = self._emit_def(name, f, co)
            else:
                renderer = NdxRenderer(
                    Structurer(self.module_lifter),
                    self.module_lifter.varnames, 0)
                if name == '__all__' and isinstance(payload, NdxSV) and \
                        payload.op == 'const' and \
                        isinstance(payload.a, (tuple, list)) and \
                        all(isinstance(item, str) for item in payload.a):
                    # the export list is source-level a list literal
                    rendered = '[' + ', '.join(repr(item)
                                               for item in payload.a) + ']'
                else:
                    rendered = renderer.expr(payload)
                lines.append(f'{name} = {rendered}')
            lines.append('')
        # statement eseguibili del modulo (main driver)
        tail = self._emit_module_statements()
        for name, definition in self._module_definitions.items():
            if name not in self._module_definition_markers:
                lines.extend(definition + [''])
        lines.extend(tail)
        # Universal fallback: when no code statement could be recovered for
        # a module whose constants were parsed, emit the constant
        # inventory.  Constants are hard evidence recovered from the blob
        # (strings, URLs, keys, table data) and are what analysts need most
        # when a build resists full structural recovery.
        body_has_code = any(
            ln.strip() and not ln.strip().startswith(('"""', "'''", '#',
                'import ', 'from '))
            # V100: un from-import CON ALIAS e' un binding esplicito
            # provato dal pool costanti (``from .x import A as B``): e'
            # codice recuperato a tutti gli effetti, non solo preamble.
            or ' as ' in ln.split(' import ')[-1]
            for ln in lines[2:] if ln.strip())
        if not body_has_code:
            consts = list(getattr(self.mod, 'consts', ()) or ())
            if consts:
                lines.append('')
                lines.append('# ' + '-' * 66)
                lines.append('# Constants inventory '
                             f'({len(consts)} values recovered from the '
                             'blob - module code was not statically '
                             'recoverable in this build)')
                lines.append('# ' + '-' * 66)

                def _fmt(value, depth=0):
                    if depth > 3:
                        return '...'
                    try:
                        if isinstance(value, str):
                            return repr(value if len(value) <= 160
                                        else value[:160] + '...')
                        if isinstance(value, (int, float, bool)) or \
                                value is None:
                            return repr(value)
                        if isinstance(value, bytes):
                            return repr(value if len(value) <= 96 else
                                        value[:96] + b'...')
                        if isinstance(value, (tuple, list)):
                            inner = ', '.join(_fmt(v, depth + 1)
                                              for v in value[:24])
                            more = ', ...' if len(value) > 24 else ''
                            return ('(' if isinstance(value, tuple)
                                    else '[') + inner + more + (
                                        ')' if isinstance(value, tuple)
                                        else ']')
                        if isinstance(value, dict):
                            items = list(value.items())[:12]
                            inner = ', '.join(
                                f'{_fmt(k, depth + 1)}: {_fmt(v, depth + 1)}'
                                for k, v in items)
                            more = ', ...' if len(value) > 12 else ''
                            return '{' + inner + more + '}'
                    except Exception:
                        pass
                    return repr(value)[:80]

                for value in consts:
                    lines.append(f'# {_fmt(value)}')
        return _ndx_drop_runtime_stmt_lines('\n'.join(lines))

    def _recover_module_assignments(self):
        """Recover ordinary ``name = value`` module bindings.

        UPDATE_STRING_DICT is also used for imports, definitions and runtime
        metadata, so only bindings whose name is not claimed by those
        structures and whose value is a source-level symbolic expression are
        emitted.  Ordering is derived from native call VAs and the first line
        of the next exact function maker; no application identifier is known
        to this routine.
        """
        lifter = self.module_lifter
        if lifter is None:
            return []
        operations = sorted(
            (operation for block in lifter.blocks.values()
             for operation in block.ops), key=lambda operation: operation.va)
        excluded = set(self.class_meta)
        for function in self.mca.functions:
            for key in ('public_name', 'qualname'):
                name = function.get(key)
                if isinstance(name, str) and '.' not in name and \
                        '<locals>' not in name:
                    excluded.add(name)
        try:
            import ast as _ast
            for line in self.import_lines:
                for statement in _ast.parse(line).body:
                    if isinstance(statement, _ast.Import):
                        excluded.update(alias.asname or
                                        alias.name.split('.', 1)[0]
                                        for alias in statement.names)
                    elif isinstance(statement, _ast.ImportFrom):
                        excluded.update(alias.asname or alias.name
                                        for alias in statement.names)
        except Exception:
            pass

        code_lines = {str(code.qualname or code.name): code.firstlineno
                      for code in self.code_objects
                      if isinstance(code, CodeObjectInfo)}
        maker_lines = []
        for operation in operations:
            node = operation.a
            if operation.kind != 'calc' or not isinstance(node, NdxSV) or \
                    node.op != 'func_new' or not isinstance(node.b, list):
                continue
            qualname = next((argument.a for argument in node.b[2:3]
                             if isinstance(argument, NdxSV) and
                             argument.op == 'const' and
                             isinstance(argument.a, str)), None)
            if qualname and '<locals>' not in qualname:
                # V100: includi ANCHE i maker dei METODI (qualname puntato).
                # Un modulo fatto solo di classi non ha maker top-level e
                # ogni suo assignment module-level finiva in coda (linea
                # 99998) invece che nella posizione sorgente: un metodo non
                # puo' iniziare prima della sua classe, quindi la prima
                # linea di metodo resta un bound superiore valido per
                # ordinare gli statement che la precedono.
                maker_lines.append((operation.va,
                                    code_lines.get(qualname, 99999)))

        recovered = []
        for operation in operations:
            root = operation.a
            if operation.kind != 'calc' or \
                    not self._is_module_bind_call(root):
                continue
            arguments = [argument for argument in (root.b or [])
                         if isinstance(argument, NdxSV)]
            name_node = next((argument for argument in arguments
                              if argument.op == 'const' and
                              isinstance(argument.a, str) and
                              argument.a.isidentifier()), None)
            # Commercial data-hiding builds decode module-dict keys at
            # runtime (decode_public into heap buffers); the key argument
            # is then an untracked/dead cell.  The BOUND NAME for a plain
            # ``import X`` is recoverable from the import itself: the top
            # package of the imported module.
            name = name_node.a if name_node is not None else None
            value = arguments[-1] if arguments else None
            if name is None and isinstance(value, NdxSV) and                     value.op == 'import' and isinstance(value.a, str) and                     value.a:
                name = value.a.split('.', 1)[0]
            if name_node is None and name is None:
                continue
            # Mutable constants are stored as templates and materialised
            # at runtime by a single-argument copy helper
            # (``helper(tstate, const_sequence)``): the constant IS the
            # source-level value.
            if isinstance(value, NdxSV) and value.op in (
                    'nativecall', 'apicall', 'call') and \
                    isinstance(value.b, list):
                real_args = [a for a in value.b
                             if a is not None and a.op != 'tstate']
                consts = [a for a in real_args if a.op == 'const' and
                          isinstance(a.a, (tuple, list))]
                if len(real_args) == 1 and len(consts) == 1:
                    value = consts[0]
            if name.startswith('__') and name != '__name__':
                # ``__all__`` is a language protocol: the module export
                # list.  It is source when bound to a constant sequence of
                # strings (its only defined shape); other dunder bindings
                # are runtime metadata.
                if not (name == '__all__' and isinstance(value, NdxSV) and
                        value.op == 'const' and
                        isinstance(value.a, (tuple, list)) and
                        value.a and
                        all(isinstance(item, str) for item in value.a)):
                    continue
            elif name in excluded:
                continue
            elif name == 'annotations' and self.future_annotations:
                # lowering di ``from __future__ import annotations``: la
                # copia dell'attributo del modulo future non è sorgente.
                continue
            if value is name_node or value is None or value.op in (
                    'func_new', 'import', 'frame', 'codeobj_new',
                    'make_code_object', 'module_bind', 'moddict', 'none'):
                continue
            following_lines = [line for address, line in maker_lines
                               if address > operation.va and
                               isinstance(line, int) and line > 0]
            source_line = (min(following_lines) - 1
                           if following_lines else None)
            if source_line is None:
                # V100: nessuna ancora (module-init senza func_new nel
                # flusso sollevato).  Un binding module-level da CALL di un
                # nome importato e' un'inizializzazione: la posizione
                # canonica del linguaggio e' DOPO gli import, PRIMA delle
                # definizioni (linea 0).  Gli altri binding non ancorati
                # restano in coda (potrebbero essere trailing setup).
                if isinstance(value, NdxSV) and value.op in (
                        'call', 'kwcall'):
                    source_line = 0
                else:
                    source_line = 99998
            recovered.append((source_line, name, value))
        return recovered

    def _emit_def(self, name, f, co):
        metadata = self.function_meta.get(name, {})
        annotations = metadata.get('annotations', {})
        defaults = metadata.get('defaults', {})
        signature = self._annotated_signature(co, annotations, defaults)
        if not signature:
            signature = list(co.varnames[:co.argcount]) if co else []
        # decoratore raccolto dall'apply nel corpo del parent (``@wraps``…)
        stashed = []
        if co is not None:
            _qn = getattr(co, 'qualname', None) or getattr(co, 'name', None)
            if _qn and _qn in _NDX_NESTED_DECORATORS:
                _dec = _NDX_NESTED_DECORATORS.pop(_qn)
                # il parametro della factory arriva come cellref: nel
                # nested def è una freevar con nome reale (co.freevars)
                if getattr(co, 'freevars', None):
                    def _cell_name(m):
                        _i = int(m.group(1))
                        return co.freevars[_i] if _i < len(co.freevars) \
                            else m.group(0)
                    _dec = re.sub(r'_cell(\d+)', _cell_name, _dec)
                stashed = [_dec]
        # generatore: il corpo Python reale vive nel resumer, non nell'impl
        # (l'impl costruisce solo l'oggetto generatore).
        if '_constant_return' in f:
            body = ['    return ' + NdxRenderer(None).expr(f['_constant_return'], top_assign=True)]
        else:
            body = self._lift_body(f.get('resumer_va') or f.get('impl_va'), co)
        nested = self._emit_nested_defs(name)
        if nested:
            body, nested = _ndx_reclaim_annotation_dicts(body, nested)
            body = nested + body
        async_prefix = ('async ' if co is not None and
                        bool(co.flags & (0x80 | 0x200)) else '')
        header = f'{async_prefix}def {name}({", ".join(signature)})'
        return_annotation = annotations.get('return')
        if return_annotation:
            header += f' -> {return_annotation}'
        out = [f'@{decorator}'
               for decorator in list(stashed) +
               list(metadata.get('decorators') or ())]
        out.append(header + ':')
        if body:
            out.extend(body)
        elif f.get('_pseudo'):
            out.append('    # [reconstructed-gap] firma esatta dal code '
                       'object del blob;')
            out.append('    # corpo non sollevabile: impl VA non trovata '
                       'in questa build')
            out.append('    ...')
        else:
            out.append('    pass')
        return out

    def _resumer_from_coroutine_ctor(self, impl_va):
        """Resumer address hidden in a coroutine *constructor*.

        A nested coroutine's impl only allocates the coroutine object
        (template ``Nuitka_Coroutine_New(tstate, coro_body, …)``); the
        lifted body is the ``coro_body`` code pointer, materialised by the
        constructor as the sole ``lea reg, [rip+…]`` whose target is
        executable text.  Works for any nesting depth and every layout.
        """
        bounds = self.img.function_bounds(impl_va)
        if bounds is None:
            return None
        candidate = None
        for ins in self.mca.fd.insns(
                impl_va, max_bytes=min(0x180, bounds[1] - impl_va),
                stop_at_ret=False):
            if ins.mnemonic == 'call' and candidate is not None:
                return candidate
            if ins.mnemonic != 'lea' or 'rip' not in ins.op_str:
                continue
            target = rip_target(ins)
            if target is None or not self.img.is_exec(target):
                continue
            candidate = target
        return None

    def _emit_nested_defs(self, parent_qualname, active=None):
        """Render direct ``<locals>`` children inside their owning def.

        Parentage comes from the exact qualname passed by MAKE_FUNCTION, not
        from a source-name heuristic.  Lines follow ``lift_body``'s relative
        convention: four spaces means one level inside the current function.
        """
        marker = str(parent_qualname) + '.<locals>.'
        active = set(active or ())
        if parent_qualname in active:
            return []
        active.add(parent_qualname)
        children = []
        for function in self.mca.functions:
            qualname = function.get('qualname')
            if not isinstance(qualname, str) or \
                    not qualname.startswith(marker):
                continue
            remainder = qualname[len(marker):]
            if '.<locals>.' in remainder:
                continue
            # A ``def`` statement requires an identifier name: lambdas and
            # comprehension code objects (``<lambda>``, ``<listcomp>``, …)
            # are expressions at their use site, not nested statements.
            if not remainder.isidentifier():
                continue
            code = function.get('code_obj')
            children.append(((code.firstlineno if code else 0) or 99999,
                             remainder, qualname, function, code))
        children.sort(key=lambda item: (item[0], item[1]))
        lines = []
        for _line, name, qualname, function, code in children:
            metadata = getattr(self.mca, '_nested_function_metadata', {}).get(qualname, {})
            signature = self._annotated_signature(code, metadata.get('annotations') or {}, metadata)
            async_prefix = ('async ' if code is not None and
                            bool(code.flags & (0x80 | 0x200)) else '')
            # decoratore raccolto dall'apply nel corpo del parent
            if qualname in _NDX_NESTED_DECORATORS:
                _dec = _NDX_NESTED_DECORATORS.pop(qualname)
                _fv = getattr(code, 'freevars', None)
                if _fv:
                    def _cell_name(m, _fv=_fv):
                        _i = int(m.group(1))
                        return _fv[_i] if _i < len(_fv) else m.group(0)
                    _dec = re.sub(r'_cell(\d+)', _cell_name, _dec)
                lines.append(f'    {_dec}')
            lines.append(
                f'    {async_prefix}def {name}({", ".join(signature)}):')
            entry_va = function.get('resumer_va') or function.get('impl_va')
            if code is not None and bool(code.flags & (0x80 | 0x200)) and \
                    function.get('resumer_va') in (None,
                                                   function.get('impl_va')):
                # The impl is the coroutine *constructor*: the lifted body
                # lives in the coro_body pointer it passes to
                # Nuitka_Coroutine_New.
                hidden = self._resumer_from_coroutine_ctor(entry_va)
                if hidden:
                    entry_va = hidden
            # i nipoti DOPO il lift del corpo: il harvest del decoratore
            # annidato gira dentro _lift_body del parent e popola lo stash
            child_body = self._lift_body(entry_va, code)
            grandchildren = self._emit_nested_defs(qualname, active)
            child_body = grandchildren + child_body
            if child_body:
                lines.extend('    ' + line if line.strip() else ''
                             for line in child_body)
            else:
                lines.append('        pass')
            lines.append('')
        while lines and not lines[-1].strip():
            lines.pop()
        return lines

    @staticmethod
    def _annotated_signature(co, annotations, defaults=None):
        if co is None:
            return []
        defaults = defaults or {}
        positional_defaults = tuple(defaults.get('positional') or ())
        keyword_defaults = dict(defaults.get('keyword') or {})
        varnames = list(co.varnames)
        positional = varnames[:co.argcount]
        # V100: co_varnames puo' contenere lo stesso nome due volte (slot
        # sintetici del lowering); una firma Python non ammette duplicati
        # (SyntaxError garantita): il secondo occorrente rinominato.
        _seen_names = set()
        for _i7, _nm7 in enumerate(positional):
            if _nm7 in _seen_names:
                _k7 = 2
                while f'{_nm7}_{_k7}' in _seen_names:
                    _k7 += 1
                positional[_i7] = f'{_nm7}_{_k7}'
            _seen_names.add(positional[_i7])
        kwonly_count = int(getattr(co, 'kwonlyargcount', 0) or 0)
        kw_start = co.argcount
        kwonly = varnames[kw_start:kw_start + kwonly_count]
        kwonly = [n if n not in _seen_names and not _seen_names.add(n)
                  else (n + '_2') for n in kwonly]
        cursor = kw_start + kwonly_count
        vararg = None
        varkw = None
        if co.flags & 0x04:
            vararg = (varnames[cursor] if cursor < len(varnames) else 'args')
            cursor += 1
        if co.flags & 0x08:
            varkw = (varnames[cursor] if cursor < len(varnames) else 'kwargs')

        positional_values = {
            name: value for name, value in zip(
                positional[-len(positional_defaults):], positional_defaults)
        } if positional_defaults else {}

        def annotated(name, prefix=''):
            annotation = annotations.get(name)
            result = (f'{prefix}{name}: {annotation}' if annotation else
                      f'{prefix}{name}')
            if not prefix and name in positional_values:
                result += ' = ' + _const_repr(positional_values[name])
            elif not prefix and name in keyword_defaults:
                result += ' = ' + _const_repr(keyword_defaults[name])
            return result

        result = [annotated(name) for name in positional]
        posonly_count = min(
            len(positional),
            int(getattr(co, 'posonlyargcount', 0) or 0))
        if posonly_count:
            result.insert(posonly_count, '/')
        if vararg:
            result.append(annotated(vararg, '*'))
        elif kwonly:
            result.append('*')
        result.extend(annotated(name) for name in kwonly)
        if varkw:
            result.append(annotated(varkw, '**'))
        return result

    def _emit_class(self, name, c):
        meta = self.class_meta.get(name, {})
        out = [f'@{decorator}' for decorator in meta.get('decorators', [])]
        bases = _heal_class_bases(meta.get('bases') or [], name)
        base_text = '(' + ', '.join(bases) + ')' if bases else ''
        out.append(f'class {name}{base_text}:')
        for field in meta.get('fields', []):
            annotation = field.get('annotation') or 'object'
            line = f"    {field['name']}: {annotation}"
            if field.get('default') is not None:
                line += ' = ' + field['default']
            out.append(line)
        for assignment, value in meta.get('assignments', []):
            out.append(f'    {assignment} = {value}')
        methods = c['methods']
        if not methods:
            if len(out) == 1 + len(meta.get('decorators', [])):
                out.append('    pass')
            return out
        for mname in sorted(methods, key=lambda mn: (
                methods[mn][1].firstlineno if methods[mn][1] else 99999)):
            f, co = methods[mname]
            argnames = list(co.varnames[:co.argcount]) if co else []
            annotations = meta.get('method_annotations', {}).get(mname, {})
            defaults = meta.get('method_defaults', {}).get(mname, {})
            signature = self._annotated_signature(co, annotations, defaults)
            if not signature:
                signature = argnames
            return_annotation = annotations.get('return')
            # For generators/coroutines the impl only allocates the resumable
            # object; the Python body lives in the resumer.  Free functions
            # already followed this rule, but class methods accidentally kept
            # lifting the constructor stub and consequently collapsed every
            # async method to a synthetic temporary return.
            body = self._lift_body(
                f.get('resumer_va') or f.get('impl_va'), co)
            nested = self._emit_nested_defs(f'{name}.{mname}')
            if nested:
                body = nested + body
            out.append('')
            if mname in meta.get('properties', set()):
                out.append('    @property')
            out.extend('    @' + decorator for decorator in meta.get('method_decorators', {}).get(mname, ()))
            async_prefix = ('async ' if co is not None and
                            bool(co.flags & (0x80 | 0x200)) else '')
            header = f'    {async_prefix}def {mname}({", ".join(signature)})'
            if return_annotation:
                header += f' -> {return_annotation}'
            out.append(header + ':')
            if body:
                out.extend('    ' + l if l.strip() else '' for l in body)
            else:
                out.append('        pass')
        return out

    def _lift_body(self, impl_va, co):
        if not impl_va:
            return []
        try:
            body = lift_body(self.mod, self.mca, co, impl_va, self.img,
                             self.res, verbose=self.verbose,
                             py_version=self.py_version)
        except Exception:
            body = []
        # V100: MAKER-STUB FALLBACK.  Se il corpo sollevato e' il solo
        # stub di registrazione della funzione (``pass``/``...`` o poche
        # righe vuote), l'impl_va puntava al maker.  La funzione reale
        # vive altrove e ``discover_impls`` la trova dallo SLOT del code
        # object: ri-solleva da li'.
        def _is_stub(lines):
            real = [l for l in (lines or [])
                    if l.strip() and l.strip() not in
                    ('pass', '...', 'return', 'return None')]
            return not real
        if _is_stub(body) and co is not None and not any(
                f.get('resumer_va') == impl_va for f in self.mca.functions):
            try:
                # V100 SPEED: la mappa impl e' una proprieta' dell'IMMAGINE
                # (slot→impl e' statico): cache condivisa tra tutti gli
                # emitter.  Prima era per-ModuleEmitter e ogni modulo con
                # stub ri-scansioneva TUTTE le funzioni del binary (su un
                # 146MB = minuti per modulo → run bloccate).
                cache = getattr(self.img, '_ndx_impl_map_cache', None)
                if cache is None:
                    cache = self.img._ndx_impl_map_cache = discover_impls(
                        self.img, self.res, self.code_objects or [])
                    # estendila con i code objects degli altri moduli gia'
                    # analizzati non serve: la mappa slot→impl copre tutto
                    # per costruzione (scansione function_bounds completa).
                real_va = None
                slot = getattr(co, 'slot_va', None)
                if slot is not None:
                    real_va = cache.get(slot)
                if not real_va:
                    # per code object senza slot: match per identita'
                    for s_va, c in cache.items():
                        if c is co:
                            real_va = s_va
                            break
                if not real_va or real_va == impl_va:
                    # V100: CLOSURE-MAKER FALLBACK.  L'impl puo' essere un
                    # factory: alloca una compiled_cell e chiama il maker
                    # passando il puntatore alla FUNZIONE REALE via
                    # ``lea r64, [rip+X]``.  Scansiona il factory, prendi
                    # i lea-target eseguibili (sono address-of, mai load
                    # di dati) e prova il lift dal primo che produce un
                    # corpo non-stub.
                    fd = FuncDisassembler(self.img)
                    try:
                        exec_ok = self.img.is_exec
                    except Exception:
                        exec_ok = lambda _v: False
                    cands = []
                    for ins in fd.insns(impl_va, max_bytes=0x200,
                                        stop_at_ret=False)[:80]:
                        if ins.mnemonic == 'lea' and 'rip' in ins.op_str \
                                and ins.op_str.split(',')[0].strip() in \
                                ('rdx', 'rdi', 'rsi', 'rcx', 'r9'):
                            t = rip_target(ins)
                            if t is not None and t != impl_va:
                                try:
                                    if exec_ok(t):
                                        cands.append(t)
                                except Exception:
                                    pass
                    for cand in cands[:6]:
                        try:
                            body2 = lift_body(self.mod, self.mca, co, cand,
                                              self.img, self.res,
                                              verbose=self.verbose,
                                              py_version=self.py_version)
                        except Exception:
                            continue
                        if not _is_stub(body2):
                            return body2
                if real_va and real_va != impl_va:
                    body2 = lift_body(self.mod, self.mca, co, real_va,
                                      self.img, self.res,
                                      verbose=self.verbose,
                                      py_version=self.py_version)
                    if not _is_stub(body2):
                        return body2
            except Exception:
                pass
        return body

    # ops di machinery da NON emettere a livello modulo
    MACHINERY_OPS = ('func_new', 'codeobj_new', 'frame', 'excstate',
                     'modconsts', 'module_bind', 'import', 'make_code_object',
                     'stopiter_value', 'none')
    MACHINERY_NAMES = ('UPDATE_STRING_DICT', 'Nuitka_LoaderNew',
                       'Nuitka_Loader_New', 'MAKE_CODE_OBJECT',
                       'sub_41830', 'sub_a650', 'sub_b500',
                       'Nuitka_Class_', 'SELECT_METACLASS',
                       'Nuitka_Coroutine_await', 'Nuitka_Generator_New')

    def _prepare_module_updates(self, bl):
        """Name updates whose dictionary fallback proves the destination.

        In-place updates keep the binding even when the result is the same
        object, so their native identity fast path must not discard the Python
        operation. Iterator target names come from the exact stored location.
        """
        bindings = [op for block in bl.blocks.values() for op in block.ops
                    if op.kind == 'store_sub' and isinstance(op.a, NdxSV)
                    and op.a.op == 'moddict' and isinstance(op.b, NdxSV)
                    and op.b.op == 'const' and isinstance(op.b.a, str)
                    and op.b.a.isidentifier() and isinstance(op.c, NdxSV)]
        for block in bl.blocks.values():
            for op in block.ops:
                if op.kind == 'calc' and self._is_module_bind_call(op.a) and len(op.a.b or []) >= 3:
                    args = op.a.b
                    if isinstance(args[1], NdxSV) and args[1].op == 'const' and isinstance(args[-1], NdxSV):
                        bindings.append(NdxOp('store_sub', a=args[0], b=args[1], c=args[-1], va=op.va))
        for binding in bindings:
            name, value = binding.b.a, binding.c
            if value.op == 'binop' and value.n == 'inplace' and isinstance(value.b, NdxSV) and value.b.op == 'global' and value.b.a == name:
                for block in bl.blocks.values():
                    rewritten = []
                    for op in block.ops:
                        if op.kind == 'store' and _sv_eq(op.b, value):
                            continue
                        if op.kind == 'calc' and _sv_eq(op.a, value):
                            rewritten.append(NdxOp('module_assign', a=name, b=op.a, va=op.va))
                        else:
                            rewritten.append(op)
                    block.ops = rewritten
            elif value.op == 'loc':
                owner = next(block for block in bl.blocks.values() if any(op.va == binding.va for op in block.ops))
                pending, seen, candidates = [(owner.start, binding.va)], set(), []
                while pending:
                    address, before = pending.pop()
                    if (address, before) in seen:
                        continue
                    seen.add((address, before))
                    block = bl.blocks[address]
                    writes = [op for op in block.ops if op.va < before and op.kind == 'store' and op.a == value.a]
                    if writes:
                        candidates.append(writes[-1].b)
                    else:
                        pending.extend((pred, float('inf')) for pred in block.preds)
                if candidates and all(isinstance(v, NdxSV) and v.op == 'next' for v in candidates):
                    mapping = getattr(bl, 'module_iterator_names', {})
                    for candidate in candidates:
                        mapping[sv_key(candidate)] = name
                    bl.module_iterator_names = mapping
                    sites = getattr(bl, 'module_iterator_binding_sites', set())
                    sites.add(binding.va)
                    bl.module_iterator_binding_sites = sites

    def _emit_module_statements(self):
        """Render module bindings and statements in native control-flow order.

        Root algorithm (IR level, no rendered-text filtering): the module
        init is, in native order, the sequence of module-dict binds — one
        bind per module-level source statement, in source order.  The
        statements between two consecutive binds are the *construction
        region* of the later bind:

        * ``setup``/``import``/``def``/``class`` binds compile single source
          statements, so their whole region is compiler machinery (class
          creation protocol — metaclass select, ``__prepare__``, mapping
          check, namespace transport —, MAKE_FUNCTION transport, import
          bookkeeping);
        * ``assign`` binds keep the dataflow that constructs or mutates the
          bound value (SSA temp chains, comprehension append loops).

        Statements after the last bind are the executable module tail (the
        entry driver): side-effect statements survive, machinery does not.
        """
        out = []
        try:
            bl = self.module_lifter
            if bl is None:
                bl = BodyLifter2(self.img, self.res, self.mca, None,
                                 self.mod.func_ptr,
                                 py_version=self.py_version,
                                 is_module_code=True).lift()
            self._prepare_module_updates(bl)
            S = Structurer(bl)
            r = NdxRenderer(S, bl.varnames, 0)
            stmts = S.structure()
            final = self._module_statement_stream(bl, S, stmts)
            self._module_has_name_write = any(
                st.kind == 'assign' and st.a == '__name__' for st in final
                if st is not None)
            # Same value/temporary rendering as function bodies.
            out.extend(r.render(final, 0))
            out = [t for t in out if t is not None and t.strip()]
            # Orphaned container names: the renderer materialises an empty
            # container under a variable name (native argument-vector copy)
            # when no source assignment backs it.  Such a name is the
            # literal itself — materialise it instead of leaving an
            # undefined reference.
            try:
                import re as _re_o
                assigned_here = {
                    m.group(1)
                    for line in out
                    for m in _re_o.finditer(r'^\s*([A-Za-z_]\w*)\s*=',
                                            line)}
                orphans = set()
                for line in out:
                    for m in _re_o.finditer(r'\b(_v\d+)\b', line):
                        if m.group(1) not in assigned_here:
                            orphans.add(m.group(1))
                if orphans:
                    def _sub_orphan(text):
                        for name in orphans:
                            text = _re_o.sub(
                                r'\b' + _re_o.escape(name) + r'\b', '[]',
                                text)
                        return text
                    out = [_sub_orphan(line) for line in out]
            except Exception:
                pass
        except Exception as exc:
            _NDX_NATIVE_EVIDENCE.setdefault(str(self.mod.name), {}).setdefault('<module>', {})['structure_error'] = type(exc).__name__ + ': ' + str(exc)
            getattr(self, '_module_definition_markers', {}).clear()
            return []
        # Module-tail postprocessing kept to the minimum that is a faithful
        # inverse of a Nuitka lowering, not a content filter:
        #   * bare ``raise`` lines are the tp_slot re-raise of machinery;
        #   * a leading ``SystemExit(expr)`` statement is the lowering of
        #     ``sys.exit(expr)`` (constructor + raise dispatch).
        try:
            import ast as _ast_t
            out = [l for l in out if l.strip() != 'raise']
            out = [l.replace('SystemExit(', 'sys.exit(')
                   if l.strip().startswith('SystemExit(') else l
                   for l in out]
            # The compiler may have folded the source guard away.  In that
            # case the conventional script boundary is a declared policy,
            # never evidence about the original import behavior.
            parsed_body = _ast_t.parse('\n'.join(out) if out else 'pass')
            has_guard = any(isinstance(node, _ast_t.If) and any(isinstance(child, _ast_t.Name) and child.id == '__name__' for child in _ast_t.walk(node.test)) for node in _ast_t.walk(parsed_body))
            guard_evidence = {'entry_guard': 'preserved' if has_guard else 'absent_or_optimized_away', 'policy': globals().get('_NDX_MAIN_GUARD_MODE', 'auto')}
            _NDX_NATIVE_EVIDENCE.setdefault(str(self.mod.name), {})['<module>'] = guard_evidence
            if str(getattr(self.mod, 'name', '')) == '__main__' and out and not has_guard and not getattr(self, '_module_has_name_write', False):
                mode = globals().get('_NDX_MAIN_GUARD_MODE', 'auto')
                if mode != 'never':
                    markers = getattr(self, '_module_definition_markers', {})
                    definition_lines = [i for i, line in enumerate(out)
                                        if line.strip() in
                                        {m + '()' for m in markers.values()}]
                    start = max(definition_lines, default=-1) + 1
                    if start < len(out) and (definition_lines or self.mca.functions):
                        guard_evidence['entry_guard'] = 'inferred'
                        out = out[:start] + ['# Entry boundary inferred: the native code no longer proves the original __name__ guard.', 'if __name__ == "__main__":'] + ['    ' + line for line in out[start:]]

        except Exception as exc:
            _NDX_NATIVE_EVIDENCE.setdefault(str(self.mod.name), {}).setdefault('<module>', {})['structure_error'] = type(exc).__name__ + ': ' + str(exc)

        expanded = []
        definitions = getattr(self, '_module_definitions', {})
        markers = getattr(self, '_module_definition_markers', {})
        by_marker = {marker + '()': definitions[name] for name, marker in markers.items()}
        for line in out:
            if line.strip() in by_marker:
                pad = line[:len(line) - len(line.lstrip())]
                expanded.extend(pad + item for item in by_marker[line.strip()])
                expanded.append('')
            else:
                expanded.append(line)
        out = expanded
        return out

    # Dunder names the import machinery writes into the module dict before
    # and around user statements.  None of them is ever the target of a
    # module-level source statement (the module docstring and annotations
    # are recovered through their own evidence channels).
    _MODULE_SETUP_NAMES = frozenset((
        '__compiled__', '__package__', '__builtins__', '__spec__', '__doc__',
        '__file__', '__cached__', '__annotations__', '__loader__',
        '__initializing__', '__module__',))

    def _module_base_names(self, sv):
        """Source-level base-name of a class-bases SV element."""
        if not isinstance(sv, NdxSV):
            return None
        if sv.op == 'global' and isinstance(sv.a, str) and sv.a.isidentifier():
            return sv.a
        if sv.op == 'getattr' and isinstance(sv.b, str):
            owner = self._module_base_names(sv.a)
            if owner:
                return owner + '.' + sv.b
        return None

    def _import_bound_names(self):
        """Names bound by the emitted import lines (already recovered)."""
        names = set()
        for line in (self.import_lines or []):
            text = line.strip()
            if text.startswith('import '):
                rest = text[7:].split('#')[0]
                for piece in rest.split(','):
                    piece = piece.strip()
                    if ' as ' in piece:
                        bound = piece.split(' as ')[-1].strip()
                    else:
                        bound = piece.split('.')[0]
                    if bound and bound.isidentifier():
                        names.add(bound)
            elif text.startswith('from ') and ' import ' in text:
                rest = text.split(' import ', 1)[-1].split('#')[0].strip()
                if rest.startswith('(') and rest.endswith(')'):
                    rest = rest[1:-1].strip()
                for piece in rest.split(','):
                    piece = piece.strip()
                    if ' as ' in piece:
                        piece = piece.split(' as ')[-1].strip()
                    elif piece:
                        piece = piece.split('.')[0]
                    if piece and piece.isidentifier():
                        names.add(piece)
        return names

    @staticmethod
    def _module_temp_name(name):
        import re as _re_m
        return isinstance(name, str) and bool(_re_m.fullmatch(
            r'_v\d+|_ndx_value_\d+|_tmp\w*', name))

    def _module_stmt_expr_symbols(self, st):
        """Expression SV fields of a statement (not descending into nested
        statement bodies — those belong to the nested statements)."""
        fields = []
        if st.kind in ('assign', 'unpack_ex'):
            fields.append(st.b)
        elif st.kind in ('expr', 'eval_hint', 'return', 'raise'):
            fields.append(st.a)
        elif st.kind in ('if', 'while'):
            fields.append(st.a)
        elif st.kind == 'for':
            fields.extend([st.b, st.e])
        elif st.kind == 'store_sub':
            fields.extend([st.a, st.b, st.c])
        elif st.kind == 'store_attr':
            fields.extend([st.a, st.c])
        elif st.kind in ('append', 'setadd'):
            fields.extend([st.a, st.b])
        return [f for f in fields if isinstance(f, NdxSV)]

    def _module_nested_stmts(self, st):
        """Nested statement lists of a control statement."""
        if st.kind in ('if', 'while'):
            nested = list(st.b or []) + list(st.c or [])
            if st.kind == 'while' and getattr(st, 'd', None):
                nested.extend(st.d)
            return nested
        if st.kind == 'for':
            return list(st.c or [])
        if st.kind == 'try':
            bodies = list(st.a or []) + list(st.c or [])
            for handler in (st.b or []):
                if isinstance(handler, (tuple, list)) and len(handler) >= 2:
                    bodies.extend(handler[1] or [])
            return bodies
        return []

    def _module_is_bind_statement(self, st):
        return st is not None and st.kind in ('expr', 'eval_hint') and             isinstance(st.a, NdxSV) and self._is_module_bind_call(st.a)

    def _module_bind_name_and_value(self, st):
        """(name, value) of a bind statement, or (None, None)."""
        root = st.a
        args = [a for a in (root.b or []) if a is not None]
        name = next((a.a for a in args
                     if isinstance(a, NdxSV) and a.op == 'const' and
                     isinstance(a.a, str) and a.a.isidentifier()), None)
        if name is None:
            return None, None
        return name, (args[-1] if args else None)

    def _module_deep_stmts(self, stmts):
        """Statements of a sequence at any nesting depth."""
        stack = list(stmts)
        while stack:
            st = stack.pop()
            if st is None:
                continue
            yield st
            stack.extend(self._module_nested_stmts(st))

    def _module_deep_bind_names(self, stmts):
        names = set()
        for st in self._module_deep_stmts(stmts):
            if self._module_is_bind_statement(st):
                name, _value = self._module_bind_name_and_value(st)
                if name is not None:
                    names.add(name)
        return names

    @classmethod
    def _module_is_const_condition(cls, sv, depth=0):
        """True when a branch condition is a compile-time constant.

        Nuitka folds the class-creation protocol (ReformulationClasses3) into
        constant-condition diamonds: the metaclass mapping check renders as
        ``{}`` (a ``dict_empty`` node) and the ``__prepare__`` fast/slow path
        selector as ``False`` (a ``bool`` node wrapping a const).  Neither has
        op ``const``/``none``, so a filter keyed only on those two ops keeps
        the diamond and leaks the metaclass plumbing — including Nuitka's own
        ``raise TypeError('%s.__prepare__() must return a mapping, not %s')``
        — into the recovered module.
        """
        if not isinstance(sv, NdxSV) or depth > 8:
            return False
        op = sv.op
        if op in ('const', 'none'):
            return True
        if op in ('dict_empty', 'list_empty', 'set_empty'):
            return True
        if op == 'bool':
            return cls._module_is_const_condition(sv.a, depth + 1)
        if op in ('tuple_build', 'list_build', 'set_build'):
            items = cls._sv_items(sv) or []
            return bool(items) is False or all(
                cls._module_is_const_condition(item, depth + 1)
                for item in items)
        return False

    def _module_harvest_protocol_binds(self, node, bind_record_for, emit_bind):
        """Bind statements nested inside a dropped protocol diamond.

        The class/def bind of a compiled ``class`` or decorated ``def`` lives
        inside the metaclass diamond, so dropping the diamond without
        harvesting would lose the definition entirely.  ``bind_record_for``
        pops from the pending queue, so a bind consumed here is never emitted
        a second time elsewhere.
        """
        emitted = []
        for deep in self._module_deep_stmts([node]):
            if deep is None or not self._module_is_bind_statement(deep):
                continue
            rec = bind_record_for(deep)
            if rec is not None:
                emitted.extend(emit_bind(rec, deep))
        return emitted

    def _flatten_duplication(self, stmts):
        """Undo the structurer's branch duplication in module init.

        When a branch diamond carries the SAME module binds in both arms,
        the continuation was structured twice: one arm is a full copy.  The
        arm with the richer bind set continues the walk inlined; the other
        copy is dropped.  Diamonds without binds (protocol checks) pass
        through and die with their construction region.
        """
        out = []
        for st in stmts:
            if st is None:
                continue
            if st.kind == 'if':
                yes, no = st.b or [], st.c or []
                yes_binds = self._module_deep_bind_names(yes)
                no_binds = self._module_deep_bind_names(no)
                if yes_binds and no_binds and (yes_binds & no_binds):
                    chosen = yes if len(yes_binds) >= len(no_binds) else no
                    out.extend(self._flatten_duplication(chosen))
                    continue
                # GCC folds the class-creation protocol's statically-known
                # checks into constant conditions: the diamond survives as
                # ``if False: <fills/construction> else: <raise machinery>``
                # (or the mirrored form).  The arm carrying the Python
                # statements is the executed one — inline it; the constant
                # branch itself is never source.
                cond = st.a
                if isinstance(cond, NdxSV) and cond.op in ('const', 'none'):

                    def arm_weight(arm):
                        count = 0
                        for inner in self._module_deep_stmts(arm):
                            if inner is None:
                                continue
                            if inner.kind == 'raise':
                                continue
                            if inner.kind == 'expr' and \
                                    isinstance(inner.a, NdxSV) and \
                                    inner.a.op in ('calc',):
                                continue
                            if inner.kind in ('assign', 'append', 'setadd',
                                              'store_sub', 'store_attr',
                                              'expr', 'for', 'while', 'if',
                                              'try'):
                                count += 1
                        return count
                    wy, wn = arm_weight(yes), arm_weight(no)
                    if wy or wn:
                        chosen = yes if wy >= wn else no
                        out.extend(self._flatten_duplication(chosen))
                        continue
            if st.kind in ('if', 'while', 'for', 'try'):
                self._module_rewrite_nested_flatten(st)
            out.append(st)
        return out

    def _module_rewrite_nested_flatten(self, st):
        """Flatten duplication inside the nested bodies in place."""
        if st.kind in ('if', 'while'):
            st.b = self._flatten_duplication(st.b or [])
            st.c = self._flatten_duplication(st.c or [])
            if st.kind == 'while' and getattr(st, 'd', None):
                st.d = self._flatten_duplication(st.d)
        elif st.kind == 'for':
            st.c = self._flatten_duplication(st.c or [])
        elif st.kind == 'try':
            st.a = self._flatten_duplication(st.a or [])
            st.c = self._flatten_duplication(st.c or [])
            if st.b:
                st.b = [(types, self._flatten_duplication(body), line, name)
                        for types, body, line, name in st.b]

    @staticmethod
    def _sv_items(sv):
        """Element list of a multi-element SV (tuple_build / call args).

        Different builders store the elements in ``.a`` or ``.b``; accept
        either so callers never have to know which one produced the node.
        """
        if not isinstance(sv, NdxSV):
            return None
        for field in ('a', 'b'):
            value = getattr(sv, field, None)
            if isinstance(value, (list, tuple)):
                return list(value)
        return None

    @classmethod
    def _class_creation_args(cls, value, name):
        """Positional arguments of a class-creation call, in either shape.

        Lowered shape — ``metaclass(NAME, bases, ns, **kw)``: NAME is the
        first argument of the call itself.

        Raw helper shape — an unlowered ``nativecall`` into a Nuitka
        ``CALL_FUNCTION*`` helper::

            CALL_FUNCTION(tstate, <metaclass>, (NAME, bases, ns), kw)

        Here ``value.b`` is the *helper's* argument vector, so NAME is the
        first element of the positional-args tuple rather than ``value.b[0]``
        (the thread state). Recognising both shapes is what lets the class
        bind be classified as a class at all; when it is missed, the class
        definition is flushed out of source order and the metaclass/
        ``__prepare__`` plumbing leaks into the emitted module.
        """
        if not isinstance(value, NdxSV):
            return None
        args = value.b
        if not isinstance(args, (list, tuple)) or not args:
            return None

        def is_name(node):
            if node == name:
                return True
            return (isinstance(node, NdxSV) and node.op == 'const'
                    and node.a == name)

        if is_name(args[0]):
            return list(args)
        for arg in args:
            if not isinstance(arg, NdxSV):
                continue
            items = cls._sv_items(arg)
            if items and is_name(items[0]):
                return items
        return None

    @classmethod
    def _bind_value_is_class_creation(cls, value, name):
        """``metaclass(NAME, bases, ns, **kw)`` — the compiled class
        statement, in lowered or raw-helper form."""
        return cls._class_creation_args(value, name) is not None

    def _bind_class_bases(self, value, name=None):
        """Base names from the class-creation call's bases argument.

        Returns None when the bases are not provable from this value, so the
        caller keeps what ``_recover_class_metadata`` already established
        rather than overwriting it with an empty list.
        """
        args = None
        if name is not None:
            args = self._class_creation_args(value, name)
        if args is None and isinstance(value, NdxSV) and \
                value.op in ('call', 'kwcall'):
            args = list(value.b or [])
        if not args or len(args) < 2:
            return None
        items = self._sv_items(args[1])
        if not items:
            return None
        names = [self._module_base_names(item) for item in items]
        return names if all(names) else None

    def _module_rewrite_nested_bodies(self, st, rewrite):
        if st.kind in ('if', 'while'):
            st.b = rewrite(st.b)
            st.c = rewrite(st.c)
            if st.kind == 'while' and getattr(st, 'd', None):
                st.d = rewrite(st.d)
        elif st.kind == 'for':
            st.c = rewrite(st.c)
        elif st.kind == 'try':
            st.a = rewrite(st.a)
            st.c = rewrite(st.c)
            if st.b:
                st.b = [(types, rewrite(body), line, name)
                        for types, body, line, name in st.b]

    def _module_statement_stream(self, bl, S, stmts):
        """Keep/drop walk over the structured module init.

        The module init is, in native order, the sequence of module-dict
        binds — one bind per module-level source statement, in source
        order.  Statements between two consecutive binds are the
        construction region of the later bind:

        * ``setup``/``import``/``def``/``class`` binds compile single
          source statements, so their whole region is compiler machinery
          (class creation protocol — metaclass select, ``__prepare__``,
          mapping check, namespace transport —, MAKE_FUNCTION transport,
          import bookkeeping);
        * ``assign`` binds keep the dataflow that constructs or mutates the
          bound value (SSA temp chains, comprehension append loops).

        Statements after the last bind are the executable module tail (the
        entry driver): side-effect statements survive, machinery does not.
        """
        iterator_sites = getattr(bl, 'module_iterator_binding_sites',
                                 set()) or set()
        definitions = getattr(self, '_module_definitions', None)
        if definitions is None:
            definitions = self._module_definitions = {}
        markers = getattr(self, '_module_definition_markers', None)
        if markers is None:
            markers = self._module_definition_markers = {}
        semantic_names = getattr(S, 'semantic_names', ()) or ()
        imported_names = self._import_bound_names()
        class_meta = self.class_meta or {}

        flat = self._flatten_duplication(
            [st for st in stmts if st is not None])

        def is_temp(name):
            return self._module_temp_name(name)

        # ---- bind classification from positional regions -----------------
        bind_positions = [(i, st) for i, st in enumerate(flat)
                          if self._module_is_bind_statement(st)]
        decisions = []
        for k, (i, st) in enumerate(bind_positions):
            name, value = self._module_bind_name_and_value(st)
            low = bind_positions[k - 1][0] if k else -1
            span = flat[low + 1:i]
            site = getattr(st.a, 'n', None)
            if site is not None and site in iterator_sites:
                kind = 'iterator'
            elif name in self._MODULE_SETUP_NAMES:
                kind = 'setup'
            elif isinstance(value, NdxSV) and value.op == 'import':
                kind = 'import'
            elif isinstance(value, NdxSV) and value.op == 'func_new':
                kind = 'def'
            elif isinstance(value, NdxSV) and \
                    value.op in ('call', 'kwcall') and \
                    any(isinstance(a, NdxSV) and a.op == 'func_new'
                        for a in (value.b or [])
                        if isinstance(a, NdxSV)):
                kind = 'def'                     # decorator at binding time
            elif self._bind_value_is_class_creation(value, name) or (
                    name in class_meta and
                    # proof 1: the class namespace ran in the region
                    # (``__qualname__`` store with this class name)
                    any(inner is not None and inner.kind == 'store_sub' and
                        isinstance(inner.b, NdxSV) and
                        inner.b.op == 'const' and inner.b.a == '__qualname__' and
                        isinstance(inner.c, NdxSV) and inner.c.op == 'const' and
                        inner.c.a == name
                        for inner in self._module_deep_stmts(span))):
                # The metaclass call itself — ``metaclass(NAME, bases, ns,
                # **kwds)`` with the class name as first positional argument
                # — is the compiled form of the class statement
                # (ReformulationClasses3) and is sufficient proof on its own,
                # including for classes the native metadata scan missed.
                kind = 'class'
                bases = self._bind_class_bases(value, name)
                if not bases:
                    # _recover_class_metadata may already have proven the
                    # bases (it heals Nuitka's metaclass plumbing out of the
                    # rendered create-class). Never overwrite real evidence
                    # with an empty list.
                    bases = list((self.class_meta.get(name) or {}).get('bases')
                                 or [])
                if not bases:
                    for inner in self._module_deep_stmts(span):
                        if inner is not None and inner.kind == 'assign' and \
                                isinstance(inner.b, NdxSV) and \
                                inner.b.op == 'tuple_build':
                            items = self._sv_items(inner.b)
                            if not items:
                                continue
                            names = [self._module_base_names(item)
                                     for item in items]
                            if all(names):
                                bases = names
                if bases:
                    self.class_meta.setdefault(name, {})['bases'] = bases
            elif name in imported_names:
                kind = 'import'
            else:
                kind = 'assign'
            decisions.append({'name': name, 'value': value, 'kind': kind})
        pending = {}
        for rec in decisions:
            pending.setdefault(rec['name'], []).append(rec)

        # ---- construction analysis for assignment regions ----------------
        def value_refs(sv, names, ids, depth=0):
            if not isinstance(sv, NdxSV) or depth > 200:
                return
            if sv.op in ('var', 'loc'):
                if isinstance(sv.a, str):
                    names.add(sv.a)
                return
            try:
                ids.add(sv_key(sv))
            except Exception:
                pass
            for field in (sv.a, sv.b, sv.c, sv.n):
                if isinstance(field, NdxSV):
                    value_refs(field, names, ids, depth + 1)
                elif isinstance(field, (list, tuple)):
                    for item in field:
                        if isinstance(item, NdxSV):
                            value_refs(item, names, ids, depth + 1)

        def add_stmt_refs(st, names, ids):
            for sym in self._module_stmt_expr_symbols(st):
                value_refs(sym, names, ids)

        def candidate_hits(st, names, ids):
            if st.kind == 'assign' and isinstance(st.a, str) and st.a in names:
                return True
            if st.kind in ('append', 'setadd') and isinstance(st.a, NdxSV):
                target = st.a
                if target.op in ('var', 'loc'):
                    return isinstance(target.a, str) and target.a in names
                try:
                    return sv_key(target) in ids
                except Exception:
                    return False
            if st.kind == 'store_sub' and isinstance(st.a, NdxSV) and \
                    st.a.op in ('var', 'loc') and isinstance(st.a.a, str):
                return st.a.a in names
            return False

        def construction_fixpoint(region_stmts, bind_value):
            names, ids = set(), set()
            if isinstance(bind_value, NdxSV):
                value_refs(bind_value, names, ids)
            kept = set()
            changed = True
            while changed:
                changed = False
                stack = [(st, (id(st),)) for st in region_stmts
                         if st is not None]
                while stack:
                    st, path = stack.pop()
                    if st is None:
                        continue
                    if candidate_hits(st, names, ids):
                        if not all(pid in kept for pid in path):
                            for pid in path:
                                kept.add(pid)
                            add_stmt_refs(st, names, ids)
                            changed = True
                    for inner in self._module_nested_stmts(st):
                        if inner is not None:
                            stack.append((inner, path + (id(inner),)))
            return [st for st in region_stmts
                    if st is not None and id(st) in kept]

        # ---- executable-tail keep rule -----------------------------------
        def tail_keep(st):
            if st is None:
                return False
            if st.kind == 'raise':
                return True
            if st.kind == 'expr':
                return isinstance(st.a, NdxSV) and st.a.op in (
                    'call', 'mcall', 'await', 'awaited')
            if st.kind == 'assign':
                if isinstance(st.a, str) and not is_temp(st.a):
                    return True
                # a side-effect call spilled to a temp: the temp name is
                # transport, the call is the module statement
                return isinstance(st.b, NdxSV) and st.b.op in (
                    'call', 'mcall', 'await', 'awaited')
            if st.kind == 'store_attr':
                return True
            if st.kind == 'store_sub':
                dest = st.a
                return isinstance(dest, NdxSV) and dest.op not in (
                    'gslot', 'moddict', 'dict_empty', 'none', 'loc')
            if st.kind in ('if', 'while', 'for', 'try'):
                return any(tail_keep(inner)
                           for inner in self._module_nested_stmts(st))
            return False

        def emit_bind(rec, st):
            kind = rec.get('kind')
            name = rec.get('name')
            if kind in ('def', 'class'):
                if name not in definitions:
                    return []
                marker = markers.get(name)
                if marker is None:
                    index = len(markers)
                    while ('__ndx_source_definition_%d__' % index
                           in semantic_names or
                           '__ndx_source_definition_%d__' % index
                           in definitions):
                        index += 1
                    marker = '__ndx_source_definition_%d__' % index
                    markers[name] = marker
                return [NdxSt('module_definition', a=marker,
                              blocks=st.blocks, line=st.line)]
            if kind == 'assign':
                return [NdxSt('assign', a=name, b=rec.get('value'),
                              blocks=st.blocks, line=st.line)]
            return []            # setup/import/iterator machinery

        def bind_record_for(st):
            name, _value = self._module_bind_name_and_value(st)
            if name is None:
                return None
            queue = pending.get(name)
            return queue.pop(0) if queue else None

        def clean_body_list(body):
            """Recursive cleanup for genuine module control bodies: bind
            decisions, const-condition protocol diamonds dropped, side
            effects kept, empty controls pruned bottom-up."""
            kept = []
            for inner in body or []:
                if inner is None:
                    continue
                if self._module_is_bind_statement(inner):
                    rec = bind_record_for(inner)
                    if rec is not None:
                        kept.extend(emit_bind(rec, inner))
                    continue
                if inner.kind == 'if' and \
                        self._module_is_const_condition(inner.a):
                    # compile-time-constant branch: protocol fast/slow
                    # path folded by the optimizer, never source. Harvest
                    # any class/def bind nested inside before dropping it.
                    kept.extend(self._module_harvest_protocol_binds(
                        inner, bind_record_for, emit_bind))
                    continue
                if inner.kind in ('if', 'while', 'for', 'try'):
                    self._module_rewrite_nested_bodies(inner, clean_body_list)
                    has_content = any(
                        self._module_nested_stmts(inner))
                    has_bind = bool(self._module_deep_bind_names([inner]))
                    if has_content or has_bind:
                        kept.append(inner)
                    continue
                if tail_keep(inner):
                    if inner.kind in ('if', 'while', 'for', 'try'):
                        self._module_rewrite_nested_bodies(inner,
                                                           clean_body_list)
                    kept.append(inner)
            return kept

        def process_genuine_control(st):
            """Module-level control flow with binds inside (conditional
            import/assignment): its bodies keep bind decisions and
            side-effect statements."""
            self._module_rewrite_nested_bodies(st, clean_body_list)

        out = []
        region_buf = []
        for st in flat:
            if self._module_is_bind_statement(st):
                rec = bind_record_for(st)
                region = region_buf
                region_buf = []
                if rec is None:
                    continue                     # duplicated bind statement
                if rec.get('kind') == 'assign':
                    out.extend(construction_fixpoint(region,
                                                     rec.get('value')))
                out.extend(emit_bind(rec, st))
                continue
            if st.kind in ('if', 'while', 'for', 'try') and \
                    self._module_deep_bind_names([st]):
                if st.kind == 'if' and self._module_is_const_condition(st.a):
                    # A constant-condition diamond is the folded metaclass /
                    # ``__prepare__`` protocol, not genuine module control
                    # flow: the class bind lives inside it, but the branch
                    # structure itself is compiler machinery. Harvest the
                    # bind, drop the diamond.
                    out.extend(self._module_harvest_protocol_binds(
                        st, bind_record_for, emit_bind))
                    continue
                process_genuine_control(st)
                out.append(st)
                continue
            region_buf.append(st)
        kept_ids = set()
        referenced = set()

        def visit(node):
            if isinstance(node, NdxSV):
                nm = None
                if node.op == 'var' and isinstance(node.a, str):
                    nm = node.a
                elif node.op == 'loc':
                    # pure lookup (no name allocation: the renderer owns it)
                    nm = (S.var_names.get(node.a)
                          if isinstance(getattr(S, 'var_names', None), dict)
                          else None)
                if isinstance(nm, str) and nm not in referenced:
                    referenced.add(nm)
                for field in (node.a, node.b, node.c, node.n):
                    if isinstance(field, NdxSV):
                        visit(field)
                    elif isinstance(field, (list, tuple)):
                        for item in field:
                            if isinstance(item, NdxSV):
                                visit(item)

        # first pass: what survives (same rules as the genuine-control
        # bodies — bind decisions excluded here, they were consumed above)
        surviving = []
        for st in region_buf:
            if st is None:
                continue
            if st.kind == 'if' and self._module_is_const_condition(st.a):
                # compile-time protocol branch; keep any bind it encloses
                surviving.extend(self._module_harvest_protocol_binds(
                    st, bind_record_for, emit_bind))
                continue
            if st.kind in ('if', 'while', 'for', 'try'):
                self._module_rewrite_nested_bodies(st, clean_body_list)
                if any(self._module_nested_stmts(st)):
                    surviving.append(st)
                continue
            if tail_keep(st):
                surviving.append(st)
        # fixpoint: temp definitions referenced by surviving statements
        # (the renderer folding would inline them later — dropping the
        # definition here would orphan the name)
        while True:
            added = False
            for st in region_buf:
                if st is None or id(st) in kept_ids:
                    continue
                if st in surviving:
                    kept_ids.add(id(st))
                    added = True
                    continue
                if st.kind == 'assign' and isinstance(st.a, str) and \
                        is_temp(st.a) and st.a in referenced:
                    surviving.append(st)
                    kept_ids.add(id(st))
                    added = True
            if not added:
                break
            referenced.clear()
            for st in surviving:
                for sym in self._module_stmt_expr_symbols(st):
                    visit(sym)
        order = {id(st): i for i, st in enumerate(region_buf)}
        surviving.sort(key=lambda s: order.get(id(s), 1 << 30))
        for st in surviving:
            if st.kind == 'assign' and is_temp(st.a) and \
                    isinstance(st.b, NdxSV):
                # bare call statement: the temp is transport only
                out.append(NdxSt('expr', a=st.b, blocks=st.blocks,
                                 line=st.line))
            else:
                out.append(st)
        return out

    def _find_classes(self, bl, ops):
        """Regioni classe: MAKE_CLASS_FRAME(code_obj) … binding."""
        classes = []
        n = len(ops)
        for i, (st, line, o) in enumerate(ops):
            if o.kind != 'calc' or o.a is None or o.a.op != 'frame':
                continue
            # il MAKE_CLASS_FRAME: verificato dal call nel blocco
            b = bl.blocks[st]
            is_class_frame = False
            co_slot = None
            for ins in b.insns:
                if ins.mnemonic == 'call' and ins.op_str.startswith('0x'):
                    t = int(ins.op_str, 16)
                    _k, nm, _s = self.res.resolve(t)
                    if nm == 'MAKE_CLASS_FRAME':
                        is_class_frame = True
                        # code object: dal registro rsi/rdx (slot)
                        for insn2 in b.insns:
                            if 'rip' in insn2.op_str and \
                                    insn2.mnemonic == 'mov':
                                rt = rip_target(insn2)
                                if rt in self.cos:
                                    co_slot = rt
                        break
            if not is_class_frame:
                continue
            co = self.cos.get(co_slot) if co_slot else None
            cname = co.name if co else 'Class'
            # raccogli il nome della classe anche dai setitem __qualname__
            qualname = None
            # regione: fino al binding successivo (UPDATE_STRING_DICT) o
            # al prossimo MAKE_CLASS_FRAME
            blocks = set()
            j = i
            while j < n:
                st2, line2, o2 = ops[j]
                blocks.add(st2)
                if o2.kind == 'calc' and o2.a is not None and \
                        o2.a.op == 'class_bind':
                    break
                j += 1
                if len(blocks) > 300:
                    break
            # metodi: SetItem(class_locals, name, func) nella regione
            methods = []
            for st2, line2, o2 in ops[i:j + 1]:
                if o2.kind == 'store_sub':
                    key = o2.b
                    val = o2.c
                    if key is not None and key.op == 'const' and \
                            isinstance(key.a, str) and val is not None:
                        methods.append((key.a, line2))
            classes.append({'name': cname, 'methods': methods,
                            'blocks': blocks, 'line': line,
                            'co': co})
        return classes

    # ------------------------------------------------------------------
    def _op_to_item(self, st, line, o, bl, S, classes):
        if o.kind == 'calc' and o.a is not None:
            sym = o.a
            if sym.op == 'func_new':
                return None       # le def sono gestite da MCA
            if sym.op == 'import':
                nm = sym.a
                if nm and not nm.startswith('_virtualenv') and nm != 'sys':
                    return {'kind': 'import', 'name': nm, 'line': line}
                return None
            if sym.op == 'frame':
                return None
            if sym.op == 'module_bind':
                return None
            if sym.op in ('excstate', 'codeobj_new', 'modconsts',
                          'stopiter_value'):
                return None
            if sym.op == 'make_code_object':
                return None
            return {'kind': 'expr', 'sym': sym, 'line': line,
                    'block': st}
        if o.kind == 'store':
            return {'kind': 'assign', 'sym': o.b, 'line': line,
                    'block': st}
        if o.kind == 'store_sub':
            return {'kind': 'store_sub', 'a': o.a, 'b': o.b, 'c': o.c,
                    'line': line, 'block': st}
        if o.kind == 'store_attr':
            return {'kind': 'store_attr', 'a': o.a, 'b': o.b, 'c': o.c,
                    'line': line, 'block': st}
        if o.kind == 'expr':
            return {'kind': 'expr', 'sym': o.a, 'line': line, 'block': st}
        return None

    # ------------------------------------------------------------------
    def _render_item(self, it, r, bl, S):
        out = []
        try:
            if it['kind'] == 'expr':
                e = r.expr(it['sym'])
                if e and not e.startswith('_tstate') and \
                        'nativecall' not in e:
                    out.append(e)
            elif it['kind'] == 'assign':
                val = r.expr(it['sym'], top_assign=True)
                name = S.name_of_loc(('reg', 'r12')) if False else None
                out.append(f'{val}' if val else '')
            elif it['kind'] == 'store_sub':
                d = r.expr(it['a'])
                k = r.expr(it['b'])
                v = r.expr(it['c'])
                if d and k and v and 'nativecall' not in str(d):
                    out.append(f'{d}[{k}] = {v}')
            elif it['kind'] == 'store_attr':
                d = r.expr(it['a'])
                v = r.expr(it['c'])
                if d and v and isinstance(it['b'], str):
                    out.append(f"{d}.{it['b']} = {v}")
        except Exception:
            pass
        return [o for o in out if o]

    def _render_class(self, c, r, bl, S):
        out = [f"class {c['name']}:"]
        # trova le funzioni/metodi dal MCA per impl
        method_names = [m[0] for m in c['methods']]
        # i metodi: cerca in mca.functions per qualname `Class.method`
        # oppure per nome semplice in ordine di apparizione
        used = set()
        found = []
        for f in self.mca.functions:
            qn = f.get('public_name') or f.get('qualname') or ''
            if qn in method_names and qn not in used:
                found.append(f)
                used.add(qn)
        if not found:
            # per qualname Class.method
            for f in self.mca.functions:
                qn = f.get('public_name') or f.get('qualname') or ''
                for mn in method_names:
                    if qn.endswith('.' + mn) or qn == mn:
                        if f not in found:
                            found.append(f)
        if not found:
            out.append('    pass')
            return out
        # ordina per linea
        found.sort(key=lambda f: f.get('lineno') or 99999)
        for f in found:
            qn = f.get('public_name') or 'method'
            simple = qn.split('.')[-1]
            impl = f.get('impl_va')
            co = f.get('code_obj')
            argnames = list(co.varnames[:co.argcount]) if co else []
            body = self._lift_method_body(impl, co, bl, S)
            out.append('')
            out.append(f'    def {simple}({", ".join(argnames)}):')
            if body:
                out.extend('    ' + l if l.strip() else '' for l in body)
            else:
                out.append('        pass')
        return out

    def _lift_method_body(self, impl_va, co, bl, S):
        if not impl_va:
            return []
        try:
            return lift_body(self.mod, self.mca, co, impl_va, self.img,
                             self.res, verbose=self.verbose,
                             py_version=self.py_version)
        except Exception:
            return []



# ==========================================================================
