import argparse
import json
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))



_PROGRESS_T0 = 0.0
_PROGRESS_ACTIVE = False
_NDX_BLOB_HEADERLESS = False


def _ndx_bar_break():
    """Clear the live progress-bar line so a message can take over."""
    if _PROGRESS_ACTIVE:
        ndx_progress_break()


def ndx_log(msg):
    _ndx_bar_break()
    print(f"{_C['info']}[**]{_C['r']} {msg}")


def ndx_log_ok(msg):
    _ndx_bar_break()
    print(f"{_C['ok']}[OK]{_C['r']} {msg}")


def ndx_log_warn(msg):
    _ndx_bar_break()
    print(f"{_C['warn']}[!!]{_C['r']} {msg}")


def ndx_log_err(msg):
    _ndx_bar_break()
    print(f"{_C['err']}[XX]{_C['r']} {msg}")


# ---------------------------------------------------------------- console
# Colored output with a real per-module progress bar.  ANSI escape codes
# are used directly; on modern Windows terminals virtual-terminal
# processing is enabled once via the console API.  Piped/non-TTY output
# and NO_COLOR fall back to plain text automatically.

def _ndx_console_supports_ansi():
    global _ANSI_READY
    if _ANSI_READY is not None:
        return _ANSI_READY
    _ANSI_READY = False
    if os.environ.get('NO_COLOR'):
        return _ANSI_READY
    if not sys.stdout.isatty():
        return _ANSI_READY
    if os.name == 'nt':
        try:
            import ctypes
            kernel32 = ctypes.windll.kernel32
            handle = kernel32.GetStdHandle(-11)      # STD_OUTPUT_HANDLE
            mode = ctypes.c_uint32()
            if not kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                return _ANSI_READY
            ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
            kernel32.SetConsoleMode(
                handle, mode.value | ENABLE_VIRTUAL_TERMINAL_PROCESSING)
            _ANSI_READY = True
        except Exception:
            _ANSI_READY = False
    else:
        _ANSI_READY = True
    return _ANSI_READY


_ANSI_READY = None
_C = {
    'info': '\x1b[38;5;75m' if _ndx_console_supports_ansi() else '',
    'ok': '\x1b[38;5;114m' if _ANSI_READY else '',
    'warn': '\x1b[38;5;215m' if _ANSI_READY else '',
    'err': '\x1b[38;5;203m' if _ANSI_READY else '',
    'dim': '\x1b[38;5;245m' if _ANSI_READY else '',
    'bar': '\x1b[38;5;75m' if _ANSI_READY else '',
    'done': '\x1b[38;5;114m' if _ANSI_READY else '',
    'fail': '\x1b[38;5;203m' if _ANSI_READY else '',
    'r': '\x1b[0m' if _ANSI_READY else '',
    'clr': '\x1b[2K' if _ANSI_READY else '',
}


def ndx_progress(done, total, label='', width=26):
    """Draw a real single-line progress bar: ▰▰▰▱▱ 42% (20/47) label eta."""
    if total <= 0 or not sys.stdout.isatty():
        return
    frac = min(1.0, max(0.0, done / total))
    filled = int(round(frac * width))
    bar = ('▰' * filled) + ('▱' * (width - filled))
    elapsed = time.time() - _PROGRESS_T0
    eta = ''
    if done > 0 and done < total:
        remaining = elapsed / done * (total - done)
        eta = f' eta {int(round(remaining))}s'
    line = (f"\r{_C['clr']}{_C['bar']}{bar}{_C['r']} "
            f"{frac * 100:5.1f}% {_C['dim']}({done}/{total})"
            f" elapsed {int(round(elapsed))}s{eta}{_C['r']} {label}")
    sys.stdout.write(line[:2048])
    sys.stdout.flush()


def ndx_progress_break():
    """Clear the progress-bar line before printing a message over it."""
    if sys.stdout.isatty():
        sys.stdout.write(f"\r{_C['clr']}\r")
        sys.stdout.flush()


def ndx_progress_start():
    global _PROGRESS_T0
    _PROGRESS_T0 = time.time()


_PROGRESS_T0 = 0.0


def detect_python_version(img):
    """Imported runtime metadata or explicit per-image selection; no default."""
    return ndx_binary_abi(img).version()


def _ndx_resolve_effective_image(target, image):
    """Resolve a validated Nuitka onefile child without executing it."""
    if image.fmt != 'pe':
        return image, None
    pe = getattr(image, '_pe', None)
    if pe is None:
        return image, None
    child = _ndl_extract_nuitka_onefile_child(pe, collect_sources=True)
    if child is None:
        return image, None

    child_data = child.get('data', b'')
    if not child_data or child_data[:2] != b'MZ':
        raise ValueError('validated onefile archive has no PE child')
    effective_path = f"{target}!{child.get('name', '<child>')}"
    child_image = BinaryImage(child_data, path=effective_path)
    embedded_sources = dict(child.get('embedded_sources', {}) or {})
    child_image.embedded_sources = embedded_sources
    metadata = {
        key: value for key, value in child.items()
        if key not in ('data', 'embedded_sources')
    }
    metadata['embedded_source_entries'] = tuple(embedded_sources)
    metadata['embedded_source_count'] = len(embedded_sources)
    return child_image, metadata


def _ndx_normalize_embedded_source_name(name):
    normalized = str(name or '').replace('\\', '/')
    while normalized.startswith('./'):
        normalized = normalized[2:]
    if (not normalized or normalized.startswith('/') or
            re.match(r'^[A-Za-z]:', normalized)):
        return None
    parts = [part for part in normalized.split('/') if part not in ('', '.')]
    if (not parts or any(part == '..' for part in parts) or
            not parts[-1].lower().endswith(('.py', '.pyw'))):
        return None
    return '/'.join(parts)


def _ndx_match_exact_embedded_sources(modules, embedded_sources):
    """Map module names to uniquely matching archive source members.

    Matches use import paths and decoded module filename constants.  A source
    is accepted only when the best suffix match is unique (or all tied bytes
    are identical), avoiding basename guesses across unrelated packages.
    """
    normalized = []
    for archive_name, data in (embedded_sources or {}).items():
        safe_name = _ndx_normalize_embedded_source_name(archive_name)
        if safe_name is not None and isinstance(data, (bytes, bytearray)):
            normalized.append((archive_name, safe_name, bytes(data)))

    result = {}
    for module in modules:
        dotted = str(module.name or '')
        module_path = dotted.replace('.', '/')
        variants = {module_path + '.py', module_path + '.pyw'}
        variants.update({module_path + '/__init__.py',
                         module_path + '/__init__.pyw'})
        # Nuitka preserves co_filename/module filename as a constant even when
        # the archive member is not named from the import path (notably main).
        for value in list(getattr(module, 'consts', ()) or ()):
            if isinstance(value, str) and value.lower().endswith(('.py', '.pyw')):
                filename = value.replace('\\', '/').lstrip('./')
                variants.add(filename)
                variants.add(filename.rsplit('/', 1)[-1])

        matches = []
        for archive_name, safe_name, data in normalized:
            matching = [variant for variant in variants
                        if safe_name == variant or safe_name.endswith('/' + variant)]
            if not matching:
                continue
            # Prefer the most specific suffix and then the least prefixed path.
            specificity = max(len(item.split('/')) for item in matching)
            prefix_parts = len(safe_name.split('/')) - specificity
            matches.append((prefix_parts, -specificity,
                            archive_name, safe_name, data))
        if not matches:
            continue
        matches.sort(key=lambda item: (item[0], item[1], item[3]))
        best_rank = matches[0][:2]
        best = [item for item in matches if item[:2] == best_rank]
        if len(best) > 1 and any(item[4] != best[0][4] for item in best[1:]):
            continue
        result[module.name] = (best[0][2], best[0][3], best[0][4])
    return result


def _ndx_write_exact_source_archive(out_dir, embedded_sources):
    """Write validated embedded sources byte-for-byte below EXACT_SOURCE."""
    written = {}
    if not embedded_sources:
        return written
    root = os.path.abspath(os.path.join(out_dir, 'EXACT_SOURCE'))
    for archive_name, data in embedded_sources.items():
        safe_name = _ndx_normalize_embedded_source_name(archive_name)
        if safe_name is None or not isinstance(data, (bytes, bytearray)):
            continue
        destination = os.path.abspath(os.path.join(root, *safe_name.split('/')))
        try:
            if os.path.commonpath((root, destination)) != root:
                continue
        except ValueError:
            continue
        os.makedirs(os.path.dirname(destination), exist_ok=True)
        with open(destination, 'wb') as handle:
            handle.write(bytes(data))
        written[archive_name] = os.path.relpath(destination, out_dir).replace(
            os.sep, '/')
    return written


def _ndx_decode_exact_source(data):
    """Decode Python source for the in-memory API without changing its bytes."""
    try:
        import io
        import tokenize
        encoding, _ = tokenize.detect_encoding(io.BytesIO(data).readline)
        return data.decode(encoding)
    except Exception:
        return data.decode('utf-8', errors='replace')


def _ndx_runtime_map_symbol(name):
    """Whether an MSVC map name is compiler/runtime infrastructure.

    Application function implementations emitted by Nuitka contain ``$`` and
    are rejected by the identifier grammar.  The explicit prefixes below also
    exclude module-specific entry points which happen to remain valid C names.
    """
    if not isinstance(name, str) or not re.fullmatch(
            r'[A-Za-z_][A-Za-z0-9_]*', name):
        return False
    if name.startswith(('impl_', 'module_code_', 'module_var_accessor_')):
        return False
    if name.startswith(('createModuleConstants_', 'createMainModuleConstants')):
        return False
    return True


def _ndx_parse_msvc_map(map_path, image):
    """Return generic runtime helper names keyed by VA from an MSVC map."""
    by_va = {}
    line_rx = re.compile(
        r'^\s*[0-9A-Fa-f]{4}:[0-9A-Fa-f]+\s+(\S+)\s+'
        r'([0-9A-Fa-f]{8,16})\s+f(?:\s+i)?(?:\s+|$)')
    with open(map_path, 'r', encoding='utf-8', errors='replace') as handle:
        for line in handle:
            match = line_rx.match(line)
            if not match:
                continue
            name, va_text = match.groups()
            if not _ndx_runtime_map_symbol(name):
                continue
            va = int(va_text, 16)
            if not image.is_exec(va):
                continue
            by_va.setdefault(va, set()).add(name)

    def name_rank(name):
        known = helper_semantics(name) is not None or name in {
            'Nuitka_Frame_AttachLocals', 'pushFrameStack', 'popFrameStack',
            'MAKE_TRACEBACK', 'ADD_TRACEBACK', 'GET_STRING_DICT_VALUE',
        }
        return (int(known), int(name.isupper()), -len(name), name)

    return {va: max(names, key=name_rank) for va, names in by_va.items()}


def _ndx_build_sig_db_from_msvc_map(reference_image_path, map_path):
    """Build reusable helper signatures without executing the reference."""
    outer = load_image(reference_image_path)
    image, _onefile = _ndx_resolve_effective_image(reference_image_path, outer)
    symbols = _ndx_parse_msvc_map(map_path, image)
    probe = HelperResolver(image, sig_db={})
    result = {}
    for va, name in sorted(symbols.items()):
        insns = probe._func_insns(va)
        if not insns:
            continue
        signature = {
            'api_direct': sorted(probe._direct_apis(va)),
            'api_reach': sorted(probe._api_reach(va)),
            'opc_hash': probe._opc_hash(va),
            'opc_len': len(insns),
            'ncalls': sum(i.mnemonic == 'call' for i in insns),
        }
        old = result.get(name)
        if old is None:
            result[name] = signature
        elif isinstance(old, list):
            if signature not in old:
                old.append(signature)
        elif signature != old:
            result[name] = [old, signature]
    return result


def _ndx_merge_sig_dbs(*databases):
    """Merge signature databases while preserving compiler variants."""
    merged = {}
    for database in databases:
        if not isinstance(database, dict):
            continue
        for name, raw in database.items():
            variants = raw if isinstance(raw, list) else [raw]
            for signature in variants:
                if not isinstance(signature, dict):
                    continue
                current = merged.get(name)
                if current is None:
                    merged[name] = signature
                elif isinstance(current, list):
                    if signature not in current:
                        current.append(signature)
                elif signature != current:
                    merged[name] = [current, signature]
    return merged


