def _ndx_module_kind(name, imports_by_mod, all_names):
    """'dev' | 'lib' per modulo, con classificazione del top-level."""
    if name in ('__main__', '__parents_main__'):
        return 'dev'
    top = name.split('.')[0]
    if top in _NDX_STDLIB_TOP or top in _NDX_KNOWN_PYPI_TOP:
        return 'lib'
    # segnali libreria: sottomoduli versione/about/test nel pacchetto top
    pkg_prefix = top + '.'
    for other in all_names:
        if other.startswith(pkg_prefix):
            tail = other[len(pkg_prefix):]
            if tail in ('__version__', '_version', 'version', '__about__',
                        'version_info') or                     tail in ('SelfTest', 'tests', 'test') or                     tail.startswith(('SelfTest.', 'tests.', 'test_')):
                return 'lib'
    return 'dev'


def ndx_classify_dev_libs(modules, imports_by_mod):
    """Partiziona i moduli in dev/lib e organizza l'output.

    Ritorna ({nome: 'dev'|'lib'}, stats). Un top-level unknown raggiunto
    SOLO da __main__/altri unknown è first-party; se una libreria nota lo
    importa, è un wrapper dell'ecosistema (lib).

    V100: regola aggiuntiva per i grandi bundle — un top-level UNKNOWN
    con MOLTI sottomoduli compilati (>= 8) è quasi sempre una libreria
    piena (l'app utente raramente supera una manciata di file per
    pacchetto), e i moduli *-preLoad/postLoad e pywin32_system32 sono
    runtime Nuitka, non codice cliente."""
    all_names = [m.name for m in modules]
    name_set = set(all_names)
    _top_count = {}
    for n in all_names:
        t = n.split('.')[0]
        _top_count[t] = _top_count.get(t, 0) + 1
    kinds = {}
    for n in all_names:
        t = n.split('.')[0]
        base = _ndx_module_kind(n, imports_by_mod, name_set)
        if base == 'dev' and t not in ('__main__', '__parents_main__'):
            # V100: solo regole SICURE — runtime Nuitka.  La vecchia regola
            # numerica (>=8 sottomodoli -> lib) riclassificava i PACCHETTI
            # DELL'APP (es. modules.balance con 11 sub) come librerie: le
            # librerie note sono gia' coperte dalla lista PYPI estesa.
            if t.endswith(('-preLoad', '-postLoad')) or \
                    t == 'pywin32_system32':
                base = 'lib'
        kinds[n] = base
    # chi importa cosa (invertito): importer → imported
    imported_by = {n: set() for n in all_names}
    for importer, imports in imports_by_mod.items():
        for imp in imports:
            top = imp.split('.')[0]
            if top in imported_by and top != importer.split('.')[0]:
                imported_by[top].add(importer.split('.')[0])
    # raffina: unknown importato da una LIB nota → lib
    changed = True
    while changed:
        changed = False
        for n, k in kinds.items():
            if k != 'dev' or n in ('__main__', '__parents_main__'):
                continue
            top = n.split('.')[0]
            for importer in imported_by.get(top, ()):
                if importer != top and kinds.get(importer) == 'lib':
                    kinds[n] = 'lib'
                    changed = True
                    break
    stats = {'dev': sum(1 for k in kinds.values() if k == 'dev'),
             'lib': sum(1 for k in kinds.values() if k == 'lib')}
    return kinds, stats


def _ndx_write_manifest(out_dir, kinds, stats):
    import json as _json
    dev = sorted(n for n, k in kinds.items() if k == 'dev')
    libs = sorted(n for n, k in kinds.items() if k == 'lib')
    with open(os.path.join(out_dir, 'MODULE_MANIFEST.json'), 'w',
              encoding='utf-8') as fh:
        _json.dump({'dev_modules': dev, 'library_modules': libs,
                    'stats': stats}, fh, indent=1, ensure_ascii=False)
    return dev, libs


def _ndx_safe_module_filename(name):
    """Filename sicuro (Windows incluso) per un nome modulo arbitrario."""
    safe = re.sub(r'[^A-Za-z0-9_.\-]', '_', str(name or 'module'))
    safe = safe.strip('.') or 'module'
    return safe


def _ndx_module_output_relpath(mod, package_names=None):
    """Percorso relativo di output di un modulo come ALBERO di package.

    ``modules.balance.bitcoin`` → ``modules/balance/bitcoin.py``; i moduli
    con flag IS_PACKAGE (0x04) dalla module table — o con sottomoduli
    effettivi nel binary — diventano ``<pkg>/__init__.py``. Gli shims
    runtime di Nuitka (``*-preLoad``, ``*-postLoad``, ``__parents_main__``)
    finiscono sotto ``_nuitka_runtime/`` invece di inquinare il sorgente
    first-party. ``__main__`` usa il nome file originale quando
    recuperabile dai const del modulo (co_filename), altrimenti resta
    ``__main__.py``."""
    name = str(getattr(mod, 'name', '') or 'module')
    if name == '__parents_main__' or name.endswith(('-preLoad',
                                                    '-postLoad')):
        return '_nuitka_runtime/' + _ndx_safe_module_filename(name) + '.py'
    if name == '__main__':
        for value in list(getattr(mod, 'consts', ()) or ()):
            if isinstance(value, str) and value.lower().endswith(
                    ('.py', '.pyw')):
                base = value.replace('\\', '/').rsplit('/', 1)[-1]
                if base.lower() not in ('__init__.py', '__init__.pyw') and \
                        re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*\.pyw?', base):
                    stem = base[:-4] if base.lower().endswith('.pyw') \
                        else base[:-3]
                    return _ndx_safe_module_filename(stem) + '.py'
        return '__main__.py'
    entry = getattr(mod, 'entry', None)
    flags = getattr(entry, 'flags', 0) or 0
    is_package = bool(flags & 0x04) or (
        name in (package_names or ()))
    parts = [_ndx_safe_module_filename(p) or '_' for p in name.split('.')]
    if is_package:
        return '/'.join(parts) + '/__init__.py'
    return '/'.join(parts) + '.py'


_NDX_PYC_DECOMPILERS = None


def _ndx_pyc_decompilers(py_version):
    """Risolve UNA volta per processo i decompilatori .pyc disponibili."""
    global _NDX_PYC_DECOMPILERS
    if _NDX_PYC_DECOMPILERS is None:
        try:
            _NDX_PYC_DECOMPILERS = _detect_decompiler(
                tuple((py_version or (3, 12))[:2])) or []
        except Exception:
            _NDX_PYC_DECOMPILERS = []
    return _NDX_PYC_DECOMPILERS


def _ndx_emit_bytecode_module_source(mod_name, marshal_data, out_dir,
                                     py_version):
    """Ricostruzione near-originale da un code object marshal del blob.

    Priorità: (1) .pyc byte-esatto sempre scritto in ``bytecode_pyc/``;
    (2) sorgente via decompilatori .pyc (pycdc/decompyle3/uncompyle6/…);
    (3) se l'interprete host matcha la versione target, listing ``dis``
    leggibile del modulo (docstring inclusa) come ultima risorsa.

    Ritorna ``(source_text_or_None, info_dict)``.
    """
    info = {'source_origin': 'bytecode', 'pyc': None,
            'decompiler': None, 'fallback': None}
    safe = _ndx_safe_module_filename(mod_name)
    pyc_dir = os.path.join(out_dir, 'bytecode_pyc')
    pyc_path = os.path.join(pyc_dir, safe + '.pyc')
    try:
        write_pyc_from_marshal(marshal_data, pyc_path, py_version)
        info['pyc'] = os.path.relpath(pyc_path, out_dir).replace(os.sep, '/')
    except Exception:
        return None, info

    py_path = os.path.join(pyc_dir, safe + '.py')
    for candidate in _ndx_pyc_decompilers(py_version):
        try:
            if _decompile_pyc(pyc_path, py_path, candidate):
                if os.path.getsize(py_path) > 20:
                    with open(py_path, 'r', encoding='utf-8',
                              errors='replace') as handle:
                        text = handle.read()
                    if text.strip():
                        info['decompiler'] = candidate.get('kind')
                        return text, info
        except Exception:
            continue

    # Fallback stesso-interprete: listing dis + docstring, mai vuoto.
    try:
        code = marshal.loads(marshal_data)
    except Exception:
        code = None
    if isinstance(code, types.CodeType):
        import io as _io
        import dis as _dis
        buf = _io.StringIO()
        try:
            _dis.dis(code, file=buf, depth=None)
        except TypeError:
            try:
                _dis.dis(code, file=buf)
            except Exception:
                pass
        except Exception:
            pass
        lines = [
            '"""HEXPYRION bytecode recovery — modulo %r.' % str(mod_name),
            'Il .pyc originale (byte per byte) e in bytecode_pyc/.',
            'Nessun decompilatore .pyc disponibile: listing dis.',
            'by dimareverse"""',
            '']
        doc = code.co_consts[0] if code.co_consts else None
        if isinstance(doc, str) and doc.strip():
            lines.append('# module docstring (da co_consts[0]):')
            lines.extend('# ' + ln for ln in doc.splitlines())
            lines.append('')
        text = '\n'.join(lines) + buf.getvalue()
        info['fallback'] = 'dis-listing'
        return text, info
    return None, info


def _ndx_audit_source(source, code_objects=(), native_evidence=None):
    """Report detectable recovery gaps without claiming semantic equivalence.

    This is static validation only. The recovered application is never run.
    Missing globals can be intentional dynamic bindings; stubs can be real
    empty functions. Strict mode therefore uses a conservative threshold.
    """
    import builtins
    import symtable
    audit = {'parses': False, 'compiles': False, 'semantic_equivalence': 'unverified',
             'status': 'partial', 'issues': [], 'functions_expected': 0,
             'functions_emitted': 0, 'missing_functions': []}
    try:
        tree = ast.parse(source)
        audit['parses'] = True
        compile(tree, '<recovered>', 'exec')
        audit['compiles'] = True
    except (SyntaxError, ValueError, TypeError) as exc:
        audit['issues'].append({'kind': 'invalid_python', 'detail': str(exc)})
        return audit
    module_evidence = (native_evidence or {}).get('<module>', {})
    if module_evidence:
        audit['module_entry'] = dict(module_evidence)
        if module_evidence.get('entry_guard') == 'inferred':
            audit['assumptions'] = [{'kind': 'inferred_main_guard', 'detail': 'The original entry boundary may have been optimized away. Use --main-guard never for flat module execution.'}]
        if module_evidence.get('structure_error'):
            audit['issues'].append({'kind': 'module_structure_error', 'detail': module_evidence['structure_error']})
    definitions = set()
    function_nodes = {}

    def walk_definitions(body, prefix=''):
        for node in body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                name = prefix + node.name
                definitions.add(name)
                walk_definitions(node.body, name + '.')
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    function_nodes[name] = node
                    executable = [n for n in node.body if not (
                        isinstance(n, ast.Expr) and isinstance(n.value, ast.Constant)
                        and isinstance(n.value.value, str))]
                    if executable and all(isinstance(n, ast.Pass) for n in executable):
                        audit['issues'].append({'kind': 'possible_stub', 'name': name,
                                                'line': node.lineno})
            else:
                for field in ('body', 'orelse', 'finalbody'):
                    children = getattr(node, field, ())
                    if isinstance(children, list):
                        walk_definitions(children, prefix)
    walk_definitions(tree.body)
    expected = set()
    for co in code_objects:
        name = co.get('qualname') or co.get('name') or ''
        if name and not name.startswith('<') and '.<' not in name.replace('.<locals>.', '.'):
            expected.add(name.replace('.<locals>.', '.'))
    audit['functions_expected'] = len(expected)
    audit['functions_emitted'] = len(definitions)
    audit['missing_functions'] = sorted(expected - definitions)
    for name in audit['missing_functions']:
        audit['issues'].append({'kind': 'missing_definition', 'name': name})
    table = symtable.symtable(source, '<recovered>', 'exec')
    bound = {sym.get_name() for sym in table.get_symbols()
             if sym.is_assigned() or sym.is_imported() or sym.is_namespace()}
    bound.update(vars(builtins))
    bound.update(('__name__', '__file__', '__package__', '__doc__', '__spec__',
                  '__loader__', '__builtins__', '__cached__', '__path__'))
    unresolved = set()
    pending = [table]
    while pending:
        scope = pending.pop()
        for sym in scope.get_symbols():
            if sym.is_referenced() and sym.is_global() and sym.get_name() not in bound:
                unresolved.add(sym.get_name())
        pending.extend(scope.get_children())
    for name in sorted(unresolved):
        audit['issues'].append({'kind': 'unresolved_global', 'name': name})
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == '_ndx_unresolved_value':
            audit['issues'].append({'kind': 'unresolved_value', 'line': node.lineno})
        if isinstance(node, ast.Call) and isinstance(node.func, (ast.Constant, ast.Tuple, ast.List, ast.Dict, ast.Set)):
            audit['issues'].append({'kind': 'noncallable_literal', 'line': node.lineno})
        elif isinstance(node, ast.If) and node.body and all(isinstance(n, ast.Pass) for n in node.body):
            audit['issues'].append({'kind': 'empty_branch', 'line': node.lineno})
        elif isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name) and isinstance(node.value, ast.Name) and node.targets[0].id == node.value.id:
            audit['issues'].append({'kind': 'self_assignment', 'name': node.value.id,
                                    'line': node.lineno})
    for qualname, evidence in (native_evidence or {}).items():
        node = function_nodes.get(qualname.replace('.<locals>.', '.'))
        if node is None or not evidence.get('exception_matchers'):
            continue
        pending_nodes = list(node.body)
        has_handler = False
        while pending_nodes:
            child = pending_nodes.pop()
            if isinstance(child, ast.ExceptHandler):
                has_handler = True
                break
            if not isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                pending_nodes.extend(ast.iter_child_nodes(child))
        if not has_handler:
            audit['issues'].append({'kind': 'missing_exception_handler',
                                    'name': qualname, 'line': node.lineno,
                                    'native_matchers': evidence['exception_matchers']})
    if not audit['issues']:
        audit['status'] = 'no_detected_gaps'
    return audit


def _ndx_resolve_module_entry(img, mod):
    """Entry-point VA for a module whose loader-table func_ptr is absent.

    Nuitka's ``--module`` builds (.pyd/.so) are loaded by CPython through the
    ordinary extension-module ABI, so they carry NO ``Nuitka_MetaPathBasedLoader
    Entry`` table: the only proof of the module init function is the exported
    ``PyInit_<name>`` (``PyInitU_<punycode>`` for non-ASCII module names, per
    code_generation/ModuleCodes.py).  Standalone/onefile builds keep the loader
    table and are unaffected because their func_ptr is already non-zero.
    """
    name = str(getattr(mod, 'name', '') or '')
    if not name:
        return None
    table = {}
    for source in (getattr(img, 'exports', None), getattr(img, 'symbols', None)):
        if not source:
            continue
        if source is getattr(img, 'symbols', None):
            # symbols maps va -> name; invert it
            for va, sym in source.items():
                if isinstance(sym, str) and sym not in table:
                    table[sym] = va
        else:
            for key, va in source.items():
                if isinstance(key, str) and key not in table:
                    table[key] = va
    if not table:
        return None

    candidates = ['PyInit_' + name, 'PyInit_' + name.rsplit('.', 1)[-1]]
    try:
        candidates.append('PyInitU_' + name.encode('punycode').decode('ascii'))
    except Exception:
        pass
    for candidate in candidates:
        va = table.get(candidate)
        if va and img.is_exec(va):
            return va
    return None


def _ndx_follow_module_entry(img, entry_va, max_depth=4, max_funcs=48):
    """Follow ``PyInit_<name>`` to the real ``module_code_<name>`` function.

    Nuitka's module-mode entry chain (code_generation/templates/
    CodeTemplatesModules.py) is::

        NUITKA_MODULE_INIT_FUNCTION(PyInit_X)
            mdef.m_slots = _module_slots;  return PyModuleDef_Init(&mdef);
        X_slot(module)  ->  X_phase2(module)
        X_phase2(module) -> module_code_X(tstate, module, getLoaderEntry(name))

    ``PyInit_X`` therefore does NOT call the module body: for Python >= 3.5 it
    hands CPython a ``Py_mod_exec`` slot table, so the next hop is a function
    pointer stored in DATA, not a call target.  The walk follows both.
    ``module_code_X`` contains the entire module body and is by far the
    largest function reachable this way, which is what identifies it.
    """
    if not entry_va:
        return None
    try:
        import capstone as _cs
    except Exception:
        return None
    try:
        md = _cs.Cs(_cs.CS_ARCH_X86, _cs.CS_MODE_64)
        md.detail = True
    except Exception:
        return None

    sizes = {}
    visited = set()
    queue = [(entry_va, 0)]
    while queue and len(sizes) < max_funcs:
        va, depth = queue.pop(0)
        if va in visited or depth > max_depth:
            continue
        visited.add(va)
        bounds = img.function_bounds(va)
        if not bounds:
            continue
        start, end = bounds
        if start not in sizes:
            sizes[start] = end - start
        off = img.va_to_off(start)
        if off is None:
            continue
        code = img.data[off:off + min(end - start, 0x2000)]
        try:
            insns = list(md.disasm(code, start))
        except Exception:
            continue
        for ins in insns:
            if ins.mnemonic in ('call', 'jmp'):
                for operand in ins.operands:
                    if operand.type != _cs.x86.X86_OP_IMM:
                        continue
                    target = int(operand.imm)
                    if img.is_exec(target):
                        queue.append((target, depth + 1))
            elif ins.mnemonic == 'lea':
                # rip-relative address of a data object (slot table / mdef);
                # any function pointers inside it are the next hops.
                for operand in ins.operands:
                    if operand.type != _cs.x86.X86_OP_MEM:
                        continue
                    if getattr(operand.mem, 'base', 0) != \
                            _cs.x86.X86_REG_RIP:
                        continue
                    data_va = ins.address + ins.size + int(operand.mem.disp)
                    data_off = img.va_to_off(data_va)
                    if data_off is None:
                        continue
                    window = img.data[data_off:data_off + 256]
                    for i in range(0, max(0, len(window) - 8), 8):
                        ptr = struct.unpack_from('<Q', window, i)[0]
                        if ptr and img.is_exec(ptr):
                            queue.append((ptr, depth + 1))
    if not sizes:
        return None
    # The module body dominates every wrapper in the chain.
    best = max(sizes.items(), key=lambda kv: kv[1])
    return best[0] if best[0] != entry_va or len(sizes) == 1 else None


def decompile_binary(target, out_dir, verbose=False, sig_db_path=None, only=None,
                     dev_only=False,
                     reference_image_path=None, reference_map_path=None,
                     target_python=None):
    t0 = time.time()
    _NDX_NATIVE_EVIDENCE.clear()
    # V100: tuning GC per i binary grandi — decine di GB di costanti/
    # indici helper vivono per tutta la run: le soglie di default fanno
    # girare la gen0 continuamente e la gen2 (full, secondi alla volta)
    # diverse volte al minuto. Soglie ampie = meno pause, stesso
    # comportamento funzionale (nessun riferimento ciclico atteso tra i
    # record del blob).
    try:
        import gc as _gc
        _gc.set_threshold(100000, 100, 100)
    except Exception:
        pass
    outer_img, img, onefile, abi_profile = ndx_prepare_abi_image(
        target, out_dir, target_python)
    try:
        ndx_log(f"Binary: {target} ({outer_img.fmt.upper()}, "
                f"{len(outer_img.data):,} bytes)")
        if onefile is not None:
            ndx_log_ok(
                f"Onefile child: {onefile.get('name')} "
                f"({len(img.data):,} bytes; "
                f"{len(onefile.get('entries', ()))} entries)")

        # blob
        blob = find_blob(img)
        if blob is None:
            ndx_log_warn("No constants blob found — not a Nuitka binary?")
            return None
        blob_va, blob_bytes, blob_size = blob
        ndx_log(f"Constants blob: {hex(blob_va)} ({blob_size:,} declared bytes)")
        chunks = parse_blob_modules(blob_bytes)
        chunk_map = {}
        for name, data in chunks:
            chunk_map.setdefault(name, data)
        ndx_log(f"Blob chunks: {[n or '<global>' for n, _ in chunks]}")

        py_version = detect_python_version(img)
        modules, _ = load_modules(img, py_version=py_version, blob=blob)
        ndx_log(f"Compiled native modules: {len(modules)}")


        if not modules and _NDX_BLOB_HEADERLESS:
            ndx_log_warn(
                "This build stores an obfuscated/commercial constants stream "
                "(no plain chunk table, encrypted payload). Static recovery "
                "needs the matching commercial bypass; nothing to decompile "
                "as-is.")

        # helper resolver con firme embedded
        sig_db = None
        if sig_db_path and os.path.exists(sig_db_path):
            with open(sig_db_path, 'r', encoding='utf-8') as handle:
                sig_db = json.load(handle)
        else:
            default = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                   'helper_sigs.json')
            if os.path.exists(default):
                with open(default, 'r', encoding='utf-8') as handle:
                    sig_db = json.load(handle)
            elif globals().get('_NDX_SIG_DB'):
                sig_db = _NDX_SIG_DB
        if bool(reference_image_path) != bool(reference_map_path):
            ndx_log_warn('La calibrazione richiede sia reference image sia MSVC map.')
            return None
        if reference_image_path and reference_map_path:
            try:
                reference_db = _ndx_build_sig_db_from_msvc_map(
                    reference_image_path, reference_map_path)
            except Exception as exc:
                ndx_log_warn(f'Calibrazione MSVC non valida: {exc}')
                return None
            sig_db = _ndx_merge_sig_dbs(sig_db, reference_db)
            ndx_log_ok(f'Firme MSVC calibrate staticamente: {len(reference_db)}')
        res = HelperResolver(img, sig_db=sig_db)

        # V100 PRE-PASS: mappa slot→VALORE di TUTTI i moduli (priv + global
        # arrays).  Gli accessor di variabile-modulo CROSS-MODULO (getter di
        # ``config``/token di un altro modulo) leggono il NOME dal pool del
        # modulo PROPRIETARIO: senza questa mappa restano ``sub_*`` opachi in
        # ogni espressione che usa la globale.  Leggero: solo basi array +
        # slot fill (niente analisi funzioni).
        try:
            _all_slots = {}
            for _pm in modules:
                try:
                    _pmca = ModuleCodeAnalyzer(img, _pm, res)
                    _pmca.find_constants_arrays()
                    for _sva, (_w, _idx) in _pmca.const_slots.items():
                        _pool = (_pm.consts if _w == 'priv'
                                 else _pm.global_consts)
                        if _idx < len(_pool):
                            _val = _pool[_idx]
                            if isinstance(_val, (str, int, float, bool)) or \
                                    _val is None:
                                _all_slots[_sva] = _val
                except Exception:
                    continue
            res.all_slot_values = _all_slots
            ndx_log(f"Cross-module slot map: {len(_all_slots)} valori")
        except Exception:
            pass


        os.makedirs(out_dir, exist_ok=True)
        embedded_sources = dict(getattr(img, 'embedded_sources', {}) or {})
        exact_sources = _ndx_match_exact_embedded_sources(modules, embedded_sources)
        exact_archive_paths = _ndx_write_exact_source_archive(
            out_dir, embedded_sources)
        report = {
            'product': APP_NAME,
            'watermark': APP_WATERMARK,
            'target': os.path.basename(target),
            'effective_target': os.path.basename(getattr(img, 'path', '') or target),
            'format': img.fmt,
            'python_version': '.'.join(map(str, py_version)),
            'blob': {'va': blob_va, 'size': blob_size},
            'onefile': onefile,
            'source_recovery': {
                'contract': ('embedded-exact when original .py bytes are present; '
                             'otherwise native semantic reconstruction'),
                'embedded_source_entries': exact_archive_paths,
                'exact_module_matches': {
                    name: match[0] for name, match in exact_sources.items()
                },
            },
            'modules': [],
        }

        sources = {}
        # Prefissi package impliciti: ogni modulo dotted prova che i suoi
        # antenati sono package (evidenza strutturale, utile quando il flag
        # IS_PACKAGE manca nella module table).
        package_names = set()
        for m in modules:
            _nm = str(getattr(m, 'name', '') or '')
            while '.' in _nm:
                _nm = _nm.rsplit('.', 1)[0]
                package_names.add(_nm)
        # classificazione dev/lib universale (top-level + grafo import)
        imports_by_mod = {m.name: list(getattr(m, 'imports_mod', []) or [])
                          for m in modules}
        module_kinds, kind_stats = ndx_classify_dev_libs(modules, imports_by_mod)
        ndx_log(f"Module classification: {kind_stats['dev']} first-party, "
                f"{kind_stats['lib']} libraries")
        if dev_only:
            before = len(modules)
            modules = [m for m in modules
                       if module_kinds.get(m.name) == 'dev']
            ndx_log_ok(f"--dev-only: {len(modules)}/{before} first-party modules "
                       f"(libraries skipped)")
        if only:
            import fnmatch as _fnm
            _pats = [s.strip() for s in only.split(',') if s.strip()]
            _before = len(modules)
            def _matches(name):
                _ln = name.lower()
                return any(_fnm.fnmatch(_ln, p.lower()) or _ln == p.lower()
                           or _ln.endswith('.' + p.lower())
                           for p in _pats)
            modules = [m for m in modules if _matches(m.name)]
            ndx_log_ok(f"--only: {len(modules)}/{_before} modules matched "
                       f"patterns {_pats}")
        dev_dir = os.path.join(out_dir, 'dev')
        libs_dir = os.path.join(out_dir, 'libs')
        os.makedirs(dev_dir, exist_ok=True)
        os.makedirs(libs_dir, exist_ok=True)

        # PRE-ANALISI: popola il registry pyfunc (call intra/inter-modulo →
        # nome sorgente) PRIMA dell'emissione, con cache sull'entry del
        # modulo cosi' il loop principale non rianalizza.
        for _mod in modules:
            if getattr(_mod, 'func_ptr', None) and \
                    getattr(_mod, '_ndx_mca', None) is None:
                try:
                    _mod._ndx_mca = ModuleCodeAnalyzer(img, _mod, res)
                    _mod._ndx_mca.analyze()
                except Exception:
                    _mod._ndx_mca = False
            _m = getattr(_mod, '_ndx_mca', None)
            if not _m:
                continue
            for _f in _m.functions:
                _iv = _f.get('impl_va')
                _nm = getattr(_f.get('code_obj'), 'name', None)
                if _iv and isinstance(_nm, str) and _nm.isidentifier() and \
                        not _nm.startswith('<'):
                    _NDX_PYFUNC_BY_VA.setdefault(_iv, _nm)


        # Sorgente originale universale — canale bytecode: il chunk ".bytecode"
        # del blob contiene i code object marshal ORIGINALI dei moduli inclusi
        # come bytecode. Emettendo il .pyc byte-esatto e decompilandolo si
        # ottiene una ricostruzione quasi identica all'originale, superiore
        # alla ricostruzione nativa. L'indice arriva dalla module table
        # (bytecode_index) o, in fallback, dal co_filename del marshal.
        bytecode_chunk = chunk_map.get('.bytecode') or b''
        bc_by_name = {}
        if bytecode_chunk:
            try:
                for _idx, _name in _bytecode_index_name_map(
                        bytecode_chunk, py_version).items():
                    bc_by_name.setdefault(_name, _idx)
            except Exception:
                bc_by_name = {}
            if bc_by_name:
                ndx_log(f"Bytecode blob: {len(bc_by_name)} modules "
                        f"mappabili via co_filename")

        total_mods = len(modules)
        failed_mods = 0
        global _PROGRESS_ACTIVE
        _PROGRESS_ACTIVE = True
        ndx_progress_start()
        for mod_index, mod in enumerate(modules, 1):
            progress = f"[{mod_index}/{total_mods}] " if total_mods > 1 else ""
            ndx_progress(mod_index - 1, total_mods, label=mod.name)
            try:
                exact_match = exact_sources.get(mod.name)
                if exact_match is not None:
                    import hashlib
                    archive_name, safe_name, source_bytes = exact_match
                    _kd = (dev_dir if module_kinds.get(mod.name) == 'dev'
                           else libs_dir)
                    _rel = _ndx_module_output_relpath(mod, package_names)
                    output_path = os.path.join(_kd, *_rel.split('/'))
                    os.makedirs(os.path.dirname(output_path), exist_ok=True)
                    with open(output_path, 'wb') as handle:
                        handle.write(source_bytes)
                    source_text = _ndx_decode_exact_source(source_bytes)
                    sources[mod.name] = source_text
                    report['modules'].append({
                        'name': mod.name,
                        'func_ptr': mod.func_ptr,
                        'source_origin': 'embedded-exact',
                        'embedded_path': archive_name,
                        'archive_copy': exact_archive_paths.get(archive_name),
                        'output_path': _rel,
                        'sha256': hashlib.sha256(source_bytes).hexdigest(),
                        'source_lines': len(source_bytes.splitlines()),
                        'code_objects': [],
                    })
                    ndx_log_ok(
                        f"{progress}Module {mod.name}: byte-exact original "
                        f"source from {safe_name}")
                    continue

                # --- canale bytecode: marshal originale del modulo ---
                entry = getattr(mod, 'entry', None)
                bc_idx = getattr(entry, 'bytecode_index', -1)
                bc_size = getattr(entry, 'bytecode_size', 0) or 0
                marshal_data = None
                if bytecode_chunk:
                    if bc_idx is not None and bc_idx >= 0 and bc_size > 0:
                        cand = _bytecode_marshal_at_index(
                            bytecode_chunk, bc_idx)
                        if cand is not None and len(cand) == bc_size:
                            marshal_data = cand
                    if marshal_data is None and mod.name in bc_by_name:
                        marshal_data = _bytecode_marshal_at_index(
                            bytecode_chunk, bc_by_name[mod.name])
                if marshal_data:
                    import hashlib
                    bc_src, bc_info = _ndx_emit_bytecode_module_source(
                        mod.name, marshal_data, out_dir, py_version)
                    if bc_src is not None:
                        # Parse-guarantee: vale anche per il path bytecode.
                        # Il listing dis (o un testo decompilato non valido)
                        # viene commentato riga per riga: evidenza preservata,
                        # modulo emesso sempre parsebile.
                        try:
                            import ast as _a_bc
                            _a_bc.parse(bc_src)
                        except Exception:
                            _bc_lines = []
                            for _ln in bc_src.split('\n'):
                                if _ln.strip() and not _ln.lstrip().\
                                        startswith('#'):
                                    _bc_lines.append('# [dis-listing] ' + _ln)
                                else:
                                    _bc_lines.append(_ln)
                            bc_src = '\n'.join(_bc_lines)
                        _kd = (dev_dir if module_kinds.get(mod.name) == 'dev'
                               else libs_dir)
                        _rel = _ndx_module_output_relpath(mod, package_names)
                        _out = os.path.join(_kd, *_rel.split('/'))
                        os.makedirs(os.path.dirname(_out), exist_ok=True)
                        with open(_out, 'w', encoding='utf-8') as f:
                            f.write(bc_src)
                        sources[mod.name] = bc_src
                        report['modules'].append({
                            'name': mod.name,
                            'func_ptr': mod.func_ptr,
                            'source_origin': ('bytecode-evidence' if bc_info.get('fallback')
                                              else 'bytecode-decompiled'),
                            'bytecode_index': int(bc_idx) if (
                                bc_idx is not None and bc_idx >= 0) else
                                bc_by_name.get(mod.name),
                            'bytecode_size': len(marshal_data),
                            'pyc': bc_info.get('pyc'),
                            'decompiler': bc_info.get('decompiler'),
                            'fallback': bc_info.get('fallback'),
                            'output_path': _rel,
                            'sha256_marshal': hashlib.sha256(
                                marshal_data).hexdigest(),
                            'source_lines': len(bc_src.split('\n')),
                            'code_objects': [],
                        })
                        ndx_log_ok(
                            f"{progress}Module {mod.name}: source from original "
                            f"bytecode "
                            f"({bc_info.get('decompiler') or bc_info.get('fallback')})")
                        continue
                if not mod.func_ptr:
                    # Module-mode builds have no loader table; recover the
                    # init entry point from the exported PyInit_<name>, then
                    # follow the PyInit -> slot -> phase2 -> module_code chain
                    # to the function that actually holds the module body.
                    resolved = _ndx_resolve_module_entry(img, mod)
                    if resolved:
                        followed = _ndx_follow_module_entry(img, resolved)
                        mod.func_ptr = followed or resolved
                        ndx_log(f"{progress}{mod.name}: entry point resolved "
                                f"from export table at {resolved:#x}"
                                + (f" -> module code at {followed:#x}"
                                   if followed else ""))
                if not mod.func_ptr:
                    ndx_log_warn(f"{progress}{mod.name}: no entry point and no "
                                 f"recoverable bytecode — skipped")
                    failed_mods += 1
                    report['modules'].append({
                        'name': mod.name, 'source_origin': 'unrecovered',
                        'error': 'No native entry point or usable bytecode'})
                    continue
                mlog = {'name': mod.name, 'func_ptr': mod.func_ptr,
                        'source_origin': 'native-semantic-reconstruction'}
                mca = getattr(mod, '_ndx_mca', None)
                if not mca:
                    mca = ModuleCodeAnalyzer(img, mod, res)
                    mca.analyze()
                # V100: IMPORT FALLBACK UNIVERSALE.  Sulle generazioni Nuitka
                # con ABI nuova la detection nativa degli import puo' restare
                # a zero (nessun UPDATE/IMPORT risolto) — ma il pool costanti
                # contiene i nomi dei moduli importati e la tabella moduli del
                # binary dice cosa esiste davvero: l'intersezione e' evidenza
                # solida.  Senza questo, il sorgente esce senza import e ogni
                # nome e' non-definito.
                if not mca.imports_mod:
                    _all_tops = {m2.name.split('.')[0] for m2 in modules}
                    _cand_mods = set()
                    for _c in list(mod.consts)[:400]:
                        if (isinstance(_c, str) and _c and
                                '.' not in _c and _c.isidentifier()
                                and not _c.startswith('_')
                                and (_c in _all_tops or
                                     _c in _NDX_STDLIB_TOP or
                                     _c in _NDX_KNOWN_PYPI_TOP)):
                            _cand_mods.add(_c)
                    mca.imports_mod = sorted(_cand_mods)
                # collega la mappa slot→costante al resolver (module var accessor)
                if hasattr(res, 'bind_slot_consts'):
                    res.bind_slot_consts(mca.const_slots)
                mlog['mod_consts_base'] = mca.mod_consts_base
                mlog['global_base'] = mca.global_base
                mlog['consts_private'] = len(mod.consts)
                mlog['consts_global'] = len(mod.global_consts)

                code_roots = [mod.func_ptr] + mca.bounded_direct_helpers()
                cos = []
                for code_root in code_roots:
                    cos.extend(extract_code_objects(img, mca, res, code_root))
                # A physical helper can be reachable from more than one call site, but
                # is scanned once above.  Keep a final slot/metadata deduplication for
                # malformed or overlapping unwind tables.
                unique_cos = []
                seen_cos = set()
                for co in cos:
                    key = (('slot', co.slot_va) if co.slot_va is not None else
                           ('meta', co.name, co.qualname, co.firstlineno,
                            co.flags, co.argcount, tuple(co.varnames)))
                    if key in seen_cos:
                        continue
                    seen_cos.add(key)
                    unique_cos.append(co)
                cos = unique_cos
                # V100: FALLBACK CODE OBJECT DALLE COSTANTI.  Se lo scan nativo
                # degli slot non ha prodotto nulla (ABI nuova), i code object
                # sono comunque decodificati nel pool costanti del modulo con
                # tutti i metadati (name/qualname/args/argcount/flags/line).
                # Convertili in CodeObjectInfo: firme ESATTE per l'emit e per
                # l'abbinamento per-qualname con le funzioni native trovate.
                if not cos:
                    def _co_from_const(c):
                        if not isinstance(c, dict) or                             c.get('_type') != 'CodeObject':
                            return None
                        ci = CodeObjectInfo()
                        ci.name = c.get('name')
                        ci.qualname = c.get('qualname') or ci.name
                        ci.argcount = c.get('argcount', 0)
                        ci.varnames = tuple(c.get('args', ()))
                        ci.flags = c.get('flags', 0)
                        ci.firstlineno = c.get('line', 0)
                        ci.freevars = tuple(c.get('freevars', ()))
                        return ci
                    _seen_cos2 = set()
                    for _c in list(mod.consts) + list(mod.global_consts or ()):
                        _ci = _co_from_const(_c)
                        if _ci is None:
                            continue
                        _k2 = (_ci.qualname, _ci.name, _ci.firstlineno,
                               _ci.argcount, tuple(_ci.varnames))
                        if _k2 in _seen_cos2:
                            continue
                        _seen_cos2.add(_k2)
                        cos.append(_ci)
                # generatori: siti di creazione + collegamento ai def (il corpo
                # Python reale di un generatore vive nel resumer, non nell'impl)
                try:
                    mca.detect_generators(cos)
                    mlog['generators'] = len(getattr(mca, 'generators', {}))
                    mlog['genexpr_sites'] = len(getattr(mca, 'genexpr_sites', []))
                except Exception:
                    if verbose:
                        import traceback
                        traceback.print_exc()
                mlog['direct_helpers_scanned'] = len(code_roots) - 1
                mlog['code_objects'] = [
                    {'name': c.name, 'qualname': c.qualname, 'argcount': c.argcount,
                     'varnames': list(c.varnames), 'firstlineno': c.firstlineno,
                     'flags': c.flags}
                    for c in cos
                ]
                ndx_log(f"{progress}Module {mod.name}: {len(cos)} code objects, "
                        f"{len(mca.functions)} functions, "
                        f"{len(mca.imports_mod)} imports")

                # genera il sorgente del modulo
                src = emit_module_source(mod, mca, cos, img, res, verbose,
                                         py_version=py_version)
                # V100: healing universale degli import mancanti — nomi usati
                # e mai definiti instradati a import veri (radici modulo del
                # binary/stdlib/pypi; classi Qt col binding provato dal pool).
                try:
                    _mod_roots = {m2.name.split('.')[0] for m2 in modules}
                    src = _ndx_heal_undefined_imports(
                        src, list(mod.consts) + list(mod.global_consts or ()),
                        _mod_roots)
                    src = _ndx_drop_builtin_alias_imports(src)
                except Exception:
                    if verbose:
                        import traceback
                        traceback.print_exc()
                sources[mod.name] = src
                # V100 NBC/3: modulo record self-contained — oltre al sorgente
                # contiene i FATTI esatti del binary (firme con varnames in
                # ordine sorgente, costanti, import, entry VA) e la TRACCIA
                # OPS del lifter per funzione (semantica nativa grezza: con
                # questa un LLM ricostruisce i corpi anche dove il renderer
                # degrada).  Emissione a costo zero: le tracce sono state
                # catturate durante lift_body.
                try:
                    if os.environ.get('NDX_EMIT_NBC', '1').strip().lower() \
                            not in ('0', 'false', 'no', 'off'):
                        _nbc_dir = os.path.join(out_dir, 'nbc')
                        os.makedirs(_nbc_dir, exist_ok=True)
                        _nbc = [
                            '# NBC/3 — Nuitka module record (self-contained)',
                            '# Sezioni: @MOD/@VER/@ENTRY @IMPORTS @CONSTS '
                            '@FUNCS(facts) @SRC(corpo recuperato) '
                            '@TRACE(ops native per funzione)',
                            '# Il @TRACE e la semantica nativa in ordine di '
                            'indirizzo: va kind sym — la fonte di verita\' '
                            'quando @SRC ha residui (_vN, sub_*).',
                            '',
                            f'@MOD {mod.name}',
                            f'@VER {py_version[0]}.{py_version[1]}',
                            f'@ENTRY 0x{mod.func_ptr:X}',
                            '',
                            '@IMPORTS ' + ', '.join(mca.imports_mod or ()),
                            '',
                            '@CONSTS']
                        _seen_c = set()
                        for _c in list(mod.consts)[:120]:
                            if isinstance(_c, (str, int, float, bool)) or \
                                    _c is None:
                                _r = repr(_c)
                                if len(_r) <= 90 and _r not in _seen_c:
                                    _seen_c.add(_r)
                                    _nbc.append(f'  {_r}')
                        _nbc += ['', '@FUNCS']
                        for _co in cos:
                            _nbc.append(
                                f'  {_co.qualname or _co.name}('
                                f'argcount={_co.argcount}, '
                                f'firstlineno={_co.firstlineno}, '
                                f'flags={_co.flags}) '
                                f'varnames=[{", ".join(_co.varnames)}]')
                        _nbc += ['', '@SRC', src, '']
                        _tr = _NBC_TRACES.get(mod.name) or {}
                        for _qn, _rows in _tr.items():
                            _nbc.append(f'@TRACE {_qn}  ({len(_rows)} ops)')
                            _nbc += _rows
                            _nbc.append('')
                        _nbc_name = mod.name.replace('.', '_') + \
                            ('.nbc' if '.' not in mod.name else '.nbc')
                        _nbc_path = os.path.join(
                            _nbc_dir, *mod.name.split('.')[:-1]) \
                            if '.' in mod.name else _nbc_dir
                        os.makedirs(_nbc_path or _nbc_dir, exist_ok=True)
                        open(os.path.join(_nbc_path or _nbc_dir,
                                          mod.name.split('.')[-1] + '.nbc'),
                             'w', encoding='utf-8').write('\n'.join(_nbc))
                except Exception:
                    if verbose:
                        import traceback
                        traceback.print_exc()
                mlog['source_lines'] = len(src.split('\n'))
                _kd = (dev_dir if module_kinds.get(mod.name) == 'dev'
                       else libs_dir)
                _rel = _ndx_module_output_relpath(mod, package_names)
                mlog['output_path'] = _rel
                _out = os.path.join(_kd, *_rel.split('/'))
                os.makedirs(os.path.dirname(_out), exist_ok=True)
                with open(_out, 'w', encoding='utf-8') as f:
                    f.write(src)
                report['modules'].append(mlog)
                ndx_progress(mod_index, total_mods,
                             label=f"{_C['done']}✔{_C['r']} {mod.name}")
            except Exception as exc:
                # Un modulo malformato NON deve piu' abortire l'intera run:
                # su binari con centinaia di moduli, un solo modulo fallito
                # si limitava a distruggere tutto l'output.
                failed_mods += 1
                ndx_log_warn(f"{progress}Module {mod.name}: analysis failed "
                             f"({exc}) — skipped, continuing")
                ndx_progress(mod_index, total_mods,
                             label=f"{_C['fail']}{mod.name}{_C['r']} FAILED")
                if verbose:
                    import traceback
                    traceback.print_exc()
                report['modules'].append({
                    'name': mod.name,
                    'func_ptr': getattr(mod, 'func_ptr', None),
                    'source_origin': 'failed',
                    'error': str(exc),
                })
                continue

        _PROGRESS_ACTIVE = False
        if total_mods:
            ndx_progress(total_mods, total_mods,
                         label=f"{_C['done']}done{_C['r']}")
            if sys.stdout.isatty():
                sys.stdout.write('\n')
                sys.stdout.flush()

        partial = 0
        for record in report['modules']:
            source = sources.get(record['name'])
            if source is None:
                record['quality'] = {'status': 'unrecovered', 'semantic_equivalence': 'unverified'}
                partial += 1
                continue
            audit = _ndx_audit_source(
                source, record.get('code_objects', ()),
                _NDX_NATIVE_EVIDENCE.get(record['name'], {}))
            if record.get('source_origin') == 'embedded-exact':
                # Exact archived bytes are the evidence; dynamic globals are valid
                # Python and are not a loss introduced by this decompiler.
                audit['status'] = 'embedded_exact'
            elif record.get('fallback') or record.get('source_origin') == 'bytecode-evidence':
                audit['status'] = 'evidence_only'
            if audit['status'] in ('partial', 'evidence_only', 'unrecovered'):
                partial += 1
            record['quality'] = audit
        report['source_recovery']['partial_modules'] = partial
        report['source_recovery']['semantic_equivalence'] = 'unverified'
        report['source_recovery']['validation'] = 'Static checks; no application execution'
        if partial:
            ndx_log_warn(f"Recovery gaps detected in {partial} module(s); see HEXPYRION_REPORT.json")
        report['failed_modules'] = failed_mods
        report['elapsed_sec'] = round(time.time() - t0, 2)
        abi_profile.write(out_dir)
        report['abi'] = {'report': 'ABI_REPORT.json',
                         'runtime_status': abi_profile.python['status'],
                         'python_version': abi_profile.python['version'],
                         'unresolved_values': len(abi_profile.unresolved_values),
                         'semantic_equivalence': 'unverified'}
        report_text = json.dumps(report, indent=2, default=str)
        with open(os.path.join(out_dir, 'HEXPYRION_REPORT.json'),
                  'w', encoding='utf-8') as f:
            f.write(report_text)
        # Compatibility alias for existing NDX integrations.
        try:
            dev_list, lib_list = _ndx_write_manifest(out_dir, module_kinds,
                                                     kind_stats)
            ndx_log_ok(f"Dev modules ({len(dev_list)}): "
                       f"{', '.join(dev_list[:12])}"
                       + (' ...' if len(dev_list) > 12 else ''))
        except Exception:
            pass
        with open(os.path.join(out_dir, 'NDX_REPORT.json'),
                  'w', encoding='utf-8') as f:
            f.write(report_text)
        ndx_log_ok(f"Finished in {report['elapsed_sec']}s → {out_dir} "
                   f"({len(sources)} sources, {failed_mods} failed modules)")
        return sources, report
    finally:
        abi_profile.write(out_dir)


def _ndx_render_pythonic_artifacts(text):
    """Translate residual compiler artifacts into their Python source forms.

    Universal, purely textual, and only touches shapes that cannot occur in
    real user source:
      * ``X = _genobj()`` / bare ``_genobj()`` — the generator/coroutine
        object allocation emitted by the lowering; allocation is implicit in
        Python and the line carries no source semantics.
      * calls through imported CPython *type objects* (``PyEnum_Type(...)``
        etc.) — the compiled form of the corresponding builtin call.
      * ``getLengthOfRange(start, stop, step)`` immediately followed by
        ``for VAR in range():`` — the lowered ``for VAR in range(...)`` loop
        (the helper computes the iterate count for the range protocol).
    """
    import re as _re
    lines = text.split('\n')
    out = []
    i = 0
    type_call_map = {
        'PyEnum_Type': 'enumerate', 'PyMap_Type': 'map',
        'PyFilter_Type': 'filter', 'PyZip_Type': 'zip',
        'PyRange_Type': 'range', 'PyReversed_Type': 'reversed',
    }
    lenrange_re = _re.compile(
        r'^(\s*)getLengthOfRange\(([^,()]+(?:\([^()]*\))?[^,()]*),'
        r'\s*([^,()]+(?:\([^()]*\))?[^,()]*),\s*([^,()]+)\)\s*$')
    emptyfor_re = _re.compile(r'^(\s*)for ([A-Za-z_]\w*) in range\(\):\s*$')
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if stripped.endswith('_genobj()') and (
                _re.fullmatch(r'[A-Za-z_]\w* = _genobj\(\)', stripped) or
                stripped == '_genobj()'):
            i += 1
            continue
        changed = False
        for type_name, builtin in type_call_map.items():
            if type_name + '(' in line:
                line = _re.sub(
                    r'\b' + type_name + r'\(', builtin + '(', line)
                changed = True
        if changed:
            out.append(line)
            i += 1
            continue
        m = lenrange_re.match(stripped)
        if m:
            indent, start, stop, step = m.groups()
            start_s, step_s = start.strip(), step.strip()
            j = i + 1
            while j < len(lines) and not lines[j].strip():
                j += 1
            if j < len(lines):
                fm = emptyfor_re.match(lines[j])
                if fm:
                    findent, var = fm.groups()
                    if start_s in ('0',) and step_s in ('1',):
                        rng = f'range({stop.strip()})'
                    elif step_s in ('1',):
                        rng = f'range({start_s}, {stop.strip()})'
                    else:
                        rng = (f'range({start_s}, {stop.strip()}, '
                               f'{step_s})')
                    out.append(f'{findent}for {var} in {rng}:')
                    i = j + 1
                    continue
        out.append(line)
        i += 1
    return '\n'.join(out)


def _ndx_split_params(text):
    """Split a parameter string on top-level commas (quote/bracket aware)."""
    parts, depth, cur, quote = [], 0, '', None
    for ch in text:
        if quote:
            cur += ch
            if ch == quote:
                quote = None
            continue
        if ch in '\'"':
            quote = ch
            cur += ch
            continue
        if ch in '([{':
            depth += 1
        elif ch in ')]}':
            depth -= 1
        if ch == ',' and depth == 0:
            parts.append(cur)
            cur = ''
        else:
            cur += ch
    if cur.strip():
        parts.append(cur)
    return parts


def _ndx_annotated_header(header, annotations):
    """Rewrite a ``def`` header line adding ``name: ann`` / ``-> ann``."""
    if not annotations:
        return header
    open_idx = header.find('(')
    if open_idx < 0:
        return header
    close_idx = header.rfind(')')
    if close_idx < open_idx:
        return header
    prefix = header[:open_idx + 1]
    params_text = header[open_idx + 1:close_idx]
    suffix = header[close_idx + 1:]
    if not params_text.strip():
        params = []
    else:
        params = _ndx_split_params(params_text)
    out_params = []
    for part in params:
        p = part.strip()
        stars = ''
        while p and p[0] in '*':
            stars += p[0]
            p = p[1:]
        if '=' in p and ':' not in p.split('=', 1)[0]:
            pname, default = p.split('=', 1)
            pname = pname.strip()
            if pname in annotations and pname.isidentifier():
                p = f'{pname}: {annotations[pname]} = {default.strip()}'
                out_params.append(f'{stars}{p}')
                continue
            p = f'{stars}{p}'
            out_params.append(p)
            continue
        pname = p.split(':', 1)[0].strip()
        if pname in annotations and pname.isidentifier() and ':' not in p:
            out_params.append(f'{stars}{pname}: {annotations[pname]}')
        else:
            out_params.append(f'{stars}{p}')
    if 'return' in annotations and '->' not in suffix:
        suffix = f' -> {annotations["return"]}' + suffix
    return f'{prefix}{", ".join(out_params)}){suffix}'


def _ndx_reclaim_annotation_dicts(body, nested):
    """Turn ``NAME = {'param': 'ann', 'return': 'ann'}`` body artifacts back
    into the nested def's annotations.

    Nuitka materialises a nested def's annotation dict as a constant store
    feeding MAKE_FUNCTION; the render spills it as a plain assignment.  When
    the assigned name matches a nested ``def`` emitted in the same body and
    the mapping is annotation-shaped (identifier keys, string values), apply
    it to that def's header and drop the spurious assignment — under
    ``from __future__ import annotations`` string values are exact source
    annotations, not a heuristic guess.
    """
    import ast as _ast
    artifact_re = re.compile(
        r'^(\s*)([A-Za-z_]\w*)\s*=\s*(\{[^\n]*\})\s*$')
    headers = {}
    params_by_name = {}
    for idx, line in enumerate(nested):
        m = re.match(
            r'^(\s*)(async )?def\s+([A-Za-z_]\w*)\s*\((.*)\)', line)
        if m:
            headers[m.group(3)] = idx
            params_by_name[m.group(3)] = {
                p.split(':', 1)[0].split('=', 1)[0].strip().lstrip('*')
                for p in _ndx_split_params(m.group(4)) if p.strip()}
    if not headers:
        return body, nested
    drop = set()
    for idx, line in enumerate(body):
        m = artifact_re.match(line)
        if not m:
            continue
        try:
            value = _ast.literal_eval(m.group(3))
        except Exception:
            continue
        if not isinstance(value, dict) or not value:
            continue
        if not all(isinstance(k, str) and k.isidentifier() and
                   isinstance(v, str)
                   for k, v in value.items()):
            continue
        target_name = m.group(2)
        if target_name not in headers:
            # The store spilled under a different local's name: match the
            # nested def whose parameter set covers the dict's keys.
            keys = set(value) - {'return'}
            hits = [nm for nm, ps in params_by_name.items()
                    if keys and keys == ps]
            if len(hits) == 1:
                target_name = hits[0]
            else:
                continue
        target = headers[target_name]
        nested[target] = _ndx_annotated_header(nested[target], value)
        drop.add(idx)
    if drop:
        body = [line for i, line in enumerate(body) if i not in drop]
    return body, nested


def emit_module_source(mod, mca, cos, img, res, verbose=False,
                       py_version=(3, 12)):
    try:
        me = ModuleEmitter(img, res, mca, mod, py_version=py_version,
                           verbose=verbose, code_objects=cos)
        return _ndl_ensure_module_parseable(
            _ndx_render_pythonic_artifacts(me.emit()))
    except Exception as e:
        if verbose:
            import traceback
            traceback.print_exc()
        return _ndl_ensure_module_parseable(
            _emit_module_source_legacy(mod, mca, cos, img, res, verbose))


def _emit_module_source_legacy(mod, mca, cos, img, res, verbose=False):
    """Modulo → sorgente Python: docstring, import, def con corpi."""
    lines = []
    # header provenance
    lines.append(f'"""HEXPYRION native semantic reconstruction — module '
                 f'{mod.name!r}.')
    lines.append('Original .py bytes were not embedded.')
    lines.append('by dimareverse"""')
    lines.append('')

    # import (dal modulecode)
    imports = [i for i in mca.imports_mod if not i.startswith('_virtualenv')
               and i != 'sys']
    seen = set()
    for imp in imports:
        if imp not in seen:
            lines.append(f'import {imp}')
            seen.add(imp)
    if imports:
        lines.append('')

    # funzioni in ordine di riga
    funcs = []
    for f_info in mca.functions:
        qn = f_info.get('public_name') or f_info.get('qualname') or 'func'
        # trova il code object per nome
        co = next((c for c in cos if c.name == qn or c.qualname == qn), None)
        impl_va = f_info.get('impl_va')
        if not impl_va:
            continue
        funcs.append((qn, impl_va, co))
    funcs.sort(key=lambda x: (x[2].firstlineno if x[2] else 0))

    for qn, impl_va, co in funcs:
        argnames = []
        if co:
            argnames = list(co.varnames[:co.argcount])
        sig = ', '.join(argnames) if argnames else ''
        lines.append(f'def {qn}({sig}):')
        body = lift_body(mod, mca, co, impl_va, img, res, verbose)
        if body:
            lines.extend(body)
        else:
            lines.append('    pass')
        lines.append('')

    # __main__ driver: if __name__ == '__main__': main()
    has_main = any(q == 'main' for q, _, _ in funcs)
    if mod.name == '__main__' and has_main:
        lines.append('if __name__ == "__main__":')
        lines.append('    main()')
        lines.append('')
    return _ndx_drop_runtime_stmt_lines('\n'.join(lines))


_NDX_RUNTIME_STMT_PREFIXES = (
    'Nuitka_GC_New(', 'Nuitka_LongUpdateFromCLong(',
    'Nuitka_Coroutine_await(', 'Nuitka_CoroutineSwitcher(',
    'MAKE_FLOAT_FROM_DOUBLE(', 'MAKE_TUPLE(', 'MAKE_TRACEBACK(',
    'Nuitka_Frame_AttachLocals(', 'Nuitka_Function_New(',
    'CONSIDER_THREADING(', 'Py_MakePendingCalls(', 'PyErr_PrintEx(',
    'Nuitka_CheckMemoryIntegrity(', 'Py_ReprLeave(', 'Py_ReprEnter(',
    'Py_EnterRecursiveCall(', 'Py_LeaveRecursiveCall(',
)


