def _ndx_drop_builtin_alias_imports(src):
    """``import X as TypeError`` con asname = builtin Python non è mai
    sorgente: quel binding viene dal machinery errori (SET_CURRENT_EXCEPTION),
    non da un import.  Droppa l'alias (o la riga se resta vuota)."""
    import builtins as _b
    if not src:
        return src
    _bi = set(dir(_b))
    out = []
    for ln in src.split('\n'):
        s = ln.strip()
        m = re.match(r'import\s+(.+)$', s)
        if m and not ln[:1] in (' ', '\t'):
            parts = [p.strip() for p in m.group(1).split(',')]
            keep = []
            for p in parts:
                am = re.match(r'(\S+)\s+as\s+(\w+)$', p)
                if am and am.group(2) in _bi:
                    continue
                keep.append(p)
            if keep != parts:
                if not keep:
                    continue
                ln = ln.replace(m.group(1), ', '.join(keep))
        out.append(ln)
    return '\n'.join(out)


def _ndx_heal_undefined_imports(src, consts, module_roots):
    """V100 UNIVERSALE: post-emit healing degli import mancanti.

    Raccoglie i NOMI usati e mai definiti nel sorgente emesso e li
    instrada: (a) nome che e' una radice modulo del binary/stdlib/pypi →
    ``import nome``; (b) nome Q* con binding Qt provato dal pool costanti
    → ``from <binding>.<sub> import nome`` con la tabella standard Qt.
    Mai nomi inventati: solo instradamento di nomi gia' presenti nel
    sorgente.  Ritorna il sorgente con gli import aggiunti in coda agli
    altri.
    """
    import ast as _ast
    import builtins as _b
    if not src or 'import ' not in src and '=' not in src:
        return src
    try:
        tree = _ast.parse(src)
    except SyntaxError:
        return src

    defined = set()
    used = set()
    for node in _ast.walk(tree):
        if isinstance(node, (_ast.Import, _ast.ImportFrom)):
            for alias in node.names:
                defined.add((alias.asname or alias.name).split('.')[0])
        elif isinstance(node, _ast.Name):
            if isinstance(node.ctx, _ast.Store):
                defined.add(node.id)
            else:
                used.add(node.id)
        elif isinstance(node, _ast.arg):
            defined.add(node.arg)
        elif isinstance(node, (_ast.FunctionDef, _ast.AsyncFunctionDef,
                               _ast.ClassDef)):
            defined.add(node.name)
        elif isinstance(node, _ast.ExceptHandler) and node.name:
            defined.add(node.name)
        elif isinstance(node, _ast.Global):
            defined.update(node.names)
    undefined = sorted(n for n in used - defined
                       if n not in dir(_b) and not n.startswith('_'))
    if not undefined:
        return src

    lines = src.split('\n')
    # inserisci dopo l'ultimo import top-level
    insert_at = 0
    for i, ln in enumerate(lines[:120]):
        s = ln.strip()
        if s.startswith(('import ', 'from ')) and not ln.startswith((' ', '\t')):
            insert_at = i + 1

    qt_binding = _ndl_qt_binding_from_consts_v58(consts)
    pool_strings = {c for c in (consts or []) if isinstance(c, str)}

    plain, qt_by_sub = [], {}
    qt_subs_names = set(_NDX_QT_SUBMODULES)
    for name in undefined:
        # nome che E' un sottomodulo Qt (uso namespace: ``QtGui.QPicture()``)
        if qt_binding and name in qt_subs_names:
            qt_by_sub.setdefault('__ns__', []).append(name)
            continue
        if qt_binding and name.startswith('Q') and len(name) > 1 and \
                name[1].isupper():
            for sub, classes in _NDX_QT_SUBMODULES.items():
                if name in classes:
                    qt_by_sub.setdefault(sub, []).append(name)
                    break
            else:
                # classe Qt non in tabella: se nel pool come stringa,
                # assegnala al sottomodulo piu' probabile dai vicini
                if name in pool_strings:
                    qt_by_sub.setdefault('QtWidgets', []).append(name)
            continue
        if name in module_roots or name in _NDX_STDLIB_TOP or \
                name in _NDX_KNOWN_PYPI_TOP:
            plain.append(name)

    new_lines = [f'import {n}' for n in plain]
    ns = sorted(set(qt_by_sub.pop('__ns__', ())))
    if ns:
        new_lines.append(f'from {qt_binding} import {", ".join(ns)}')
    for sub in sorted(qt_by_sub):
        names = sorted(set(qt_by_sub[sub]))
        new_lines.append(f'from {qt_binding}.{sub} import '
                         f'{", ".join(names)}')
    if not new_lines:
        return src
    out = lines[:insert_at] + new_lines + [''] + lines[insert_at:]
    return '\n'.join(out)


def _ndx_drop_runtime_stmt_lines(text):
    """V100 UNIVERSALE: sanity pass finale sul sorgente di un modulo.

    1. rimuove gli statement singoli di helper runtime Nuitka/CPython
       (chokepoint: qualunque percorso di emissione li abbia prodotti, uno
       statement BARE di machinery runtime non e' mai sorgente utente);
    2. ripulisce dai ``from X import ...`` i nomi che sono MARKER DI
       COSTANTE leaked dal pool (es. ``_c__HHNNCCS_1``): pattern
       ``...__...._<cifre>`` o prefisso ``_c__``.  Se non restano nomi,
       l'intera riga viene droppata.
    """
    if not text:
        return text
    import re as _re
    _prefixes = '|'.join(
        _re.escape(p[:-1]) for p in _NDX_RUNTIME_STMT_PREFIXES)
    pat = _re.compile(
        r'^(?P<indent>[ \t]*)(?:' + _prefixes + r')[A-Za-z0-9_]*\(.*\)[ \t]*$')
    marker_name = _re.compile(r'^(_c__.*|_?[A-Za-z0-9]+__.*_\d+)$')
    from_imp = _re.compile(r'^(\s*)from\s+([.\w]+)\s+import\s+(.+)$')
    out = []
    for ln in text.split('\n'):
        if pat.match(ln):
            continue
        m = from_imp.match(ln)
        if m and ',' not in m.group(2):
            names = [n.strip() for n in m.group(3).split(',')]
            keep = [n for n in names
                    if n and not marker_name.match(n)]
            if not keep:
                continue
            if len(keep) != len(names):
                ln = f'{m.group(1)}from {m.group(2)} import {", ".join(keep)}'
        out.append(ln)
    text = '\n'.join(out)
    # V100 ROBUSTEZZA: contratto universale — il modulo emesso DEVE essere
    # Python valido.  Se una riga contiene residui non renderizzabili
    # (es. ``<NdxSV ...>`` leaked) o altra sintassi rotta, commentala
    # (contenuto preservato, stile [parse-error]) finché il modulo non
    # parsce.  Mai scrivere un sorgente non eseguibile dal parser.
    try:
        import ast as _ast
        _ast.parse(text)
    except SyntaxError:
        lines = text.split('\n')
        for _ in range(200):
            try:
                _ast.parse('\n'.join(lines))
                break
            except SyntaxError as _se:
                _li = (_se.lineno or 1) - 1
                if not 0 <= _li < len(lines):
                    break
                _ln5 = lines[_li]
                _st5 = _ln5.strip()
                if _st5.endswith(':') and not _st5.startswith('#') and                         'expected an indented block' in str(_se.msg):
                    # header di blocco senza corpo: inserisci ``pass``
                    # alla profondita' corretta invece di commentare.
                    _pad5 = _ln5[:len(_ln5) - len(_ln5.lstrip())] + '    '
                    lines.insert(_li + 1, _pad5 + 'pass')
                    continue
                if _st5.startswith('#'):
                    lines[_li] = ''
                    continue
                lines[_li] = (_ln5[:len(_ln5) - len(_ln5.lstrip())] +
                              '# [parse-error] ' + _st5)
        text = '\n'.join(lines)
    return text


def _ndx_guard_block_indentation(lines):
    """Insert ``pass`` under any block header left without a body.

    Structuring edge cases (empty else arms after statement motion, native
    clean-up tails) can emit ``else:``/``if ...:`` immediately followed by a
    line at the same or lower indentation, which is a syntax error.  A
    keyword-opened block followed by a non-indented line provably lacks a
    body: an explicit ``pass`` preserves validity without altering any
    recovered statement.
    """
    header_rx = re.compile(
        r'^(\s*)(?:if\b.*|elif\b.*|else\b.*|for\b.*|while\b.*|try\b.*|'
        r'except\b.*|finally\b.*|with\b.*|def\b.*|async def\b.*|'
        r'class\b.*|match\b.*|case\b.*):\s*(#.*)?$')
    out = []
    for index, line in enumerate(lines):
        out.append(line)
        if not line.rstrip().endswith(':'):
            continue
        match = header_rx.match(line)
        if match is None:
            continue
        base_indent = len(match.group(1))
        following = lines[index + 1] if index + 1 < len(lines) else ''
        if not following.strip() or \
                len(following) - len(following.lstrip()) <= base_indent:
            out.append(' ' * (base_indent + 4) + 'pass')
    return out


def _ndx_cleanup_body_lines(lines, function_name=None):
    """Conservative source-level cleanup of native SSA temporaries.

    Only synthetic ``_vN`` values are considered.  A value is moved across
    statements solely when the intervening statements are themselves pure
    temporary definitions; calls are inlined only into the immediately next
    statement.  The transform therefore preserves Python evaluation order
    while removing register/stack names introduced by the lifter.
    """
    if not lines:
        return lines
    try:
        tree = ast.parse('def __hexpyrion_body__():\n' + '\n'.join(lines))
    except (SyntaxError, ValueError):
        return lines
    function = tree.body[0]
    temp_rx = re.compile(r'^_v\d+$')

    def node_key(node):
        return ast.dump(node, annotate_fields=True,
                        include_attributes=False)

    def pure(node):
        # Operators, descriptors and subscripts can invoke arbitrary Python.
        # Their apparent syntax does not make them safe to reorder.
        if isinstance(node, (ast.Constant, ast.Name)):
            return True
        if isinstance(node, (ast.Tuple, ast.List, ast.Set)):
            return all(pure(item) for item in node.elts)
        if isinstance(node, ast.Dict):
            return all(key is not None and pure(key) and pure(value)
                       for key, value in zip(node.keys, node.values))
        return False

    def expression_depth(node):
        maximum = 0
        pending = [(node, 0)]
        while pending:
            item, depth = pending.pop()
            maximum = max(maximum, depth)
            pending.extend((child, depth + 1) for child in ast.iter_child_nodes(item))
        return maximum

    class ReplaceLoad(ast.NodeTransformer):
        def __init__(self, name, replacement):
            self.name = name
            self.replacement = replacement

        def visit_Name(self, node):
            if isinstance(node.ctx, ast.Load) and node.id == self.name:
                return ast.copy_location(copy.deepcopy(self.replacement), node)
            return node

    def load_count(node, name):
        return sum(isinstance(item, ast.Name) and
                   isinstance(item.ctx, ast.Load) and item.id == name
                   for item in ast.walk(node))

    def cleanup_list(body, require_nonempty=False):
        # First clean nested statement lists.
        for statement in body:
            for field in ('body', 'orelse', 'finalbody'):
                nested = getattr(statement, field, None)
                if isinstance(nested, list):
                    cleaned = cleanup_list(nested, field == 'body')
                    setattr(statement, field, cleaned)
            handlers = getattr(statement, 'handlers', None)
            if handlers:
                for handler in handlers:
                    handler.body = cleanup_list(handler.body, True)

        # Native post-dominator structuring often leaves the continuation in
        # an ``else`` even when the true arm cannot continue.  Flatten only
        # when Python control flow proves that the complete arm terminates.
        flattened = []
        for statement in body:
            flattened.append(statement)
            if isinstance(statement, ast.If) and statement.orelse and \
                    statement.body and isinstance(
                        statement.body[-1],
                        (ast.Return, ast.Raise, ast.Break, ast.Continue)):
                continuation = statement.orelse
                statement.orelse = []
                flattened.extend(continuation)
        body = flattened

        # Source text alone cannot distinguish two independent identical
        # calls from one duplicated native producer.  Deduplication belongs
        # to the provenance-aware IR pass, before call-site identity is lost.

        # Reassemble a freshly allocated mapping followed by constant-key
        # SET_SUBSCRIPT operations.  This is the native lowering of a dict
        # display and preserves evaluation order exactly.
        rebuilt = []
        index = 0
        while index < len(body):
            statement = body[index]
            if not (isinstance(statement, ast.Assign) and
                    len(statement.targets) == 1 and
                    isinstance(statement.targets[0], ast.Name) and
                    temp_rx.fullmatch(statement.targets[0].id) and
                    isinstance(statement.value, ast.Dict) and
                    not statement.value.keys):
                rebuilt.append(statement)
                index += 1
                continue
            name = statement.targets[0].id
            keys, values = [], []
            cursor = index + 1
            while cursor < len(body):
                candidate = body[cursor]
                if not (isinstance(candidate, ast.Assign) and
                        len(candidate.targets) == 1 and
                        isinstance(candidate.targets[0], ast.Subscript) and
                        isinstance(candidate.targets[0].value, ast.Name) and
                        candidate.targets[0].value.id == name):
                    break
                keys.append(candidate.targets[0].slice)
                values.append(candidate.value)
                cursor += 1
            if keys:
                statement.value = ast.Dict(keys=keys, values=values)
                rebuilt.append(statement)
                index = cursor
            else:
                rebuilt.append(statement)
                index += 1
        body = rebuilt

        # FORMAT_VALUE + PyUnicode_Join lowering can leave already-consumed
        # ``format(value, spec)`` temporaries beside a reconstructed f-string.
        # Remove only calls whose value is visibly present in that f-string.
        # The lowering also assigns the field fragments to REAL source names
        # (the lazy naming consumes varnames in order, so the fragments grab
        # the names of the variables the f-string later represents).  A
        # fragment assignment whose name is never read again and whose
        # rendered value is visibly part of a following f-string in the same
        # block is machine lowering, not source: drop it so the name is free
        # for the statement that actually defines the variable.
        formatted_values = set()
        fstring_literals = set()
        for statement in body:
            candidate = None
            if isinstance(statement, ast.Return) and \
                    isinstance(statement.value, ast.JoinedStr):
                candidate = statement.value
            elif isinstance(statement, ast.Assign) and \
                    isinstance(statement.value, ast.JoinedStr):
                candidate = statement.value
            if candidate is None:
                continue
            for part in candidate.values:
                if isinstance(part, ast.FormattedValue):
                    formatted_values.add(node_key(part.value))
                elif isinstance(part, ast.Constant) and \
                        isinstance(part.value, str) and part.value:
                    fstring_literals.add(part.value)
        if formatted_values or fstring_literals:
            filtered = []
            for statement in body:
                drop = False
                if isinstance(statement, ast.Assign) and \
                        len(statement.targets) == 1 and \
                        isinstance(statement.targets[0], ast.Name) and \
                        isinstance(statement.value, ast.Call) and \
                        isinstance(statement.value.func, ast.Name) and \
                        statement.value.func.id == 'format' and \
                        statement.value.args:
                    fragment_name = statement.targets[0].id
                    drop = node_key(statement.value.args[0]) in formatted_values
                    if drop and not temp_rx.fullmatch(fragment_name):
                        # real names additionally require zero later reads
                        position = body.index(statement)
                        drop = all(
                            load_count(later, fragment_name) == 0
                            for later in body[position + 1:])
                elif isinstance(statement, ast.Assign) and \
                        len(statement.targets) == 1 and \
                        isinstance(statement.targets[0], ast.Name) and \
                        isinstance(statement.value, ast.Constant) and \
                        isinstance(statement.value.value, str) and \
                        statement.value.value in fstring_literals:
                    fragment_name = statement.targets[0].id
                    position = body.index(statement)
                    drop = all(load_count(later, fragment_name) == 0
                               for later in body[position + 1:])
                if not drop:
                    filtered.append(statement)
            body = filtered

        # A common post-dominator can be emitted both as the if-else body and
        # immediately after the if.  Structural equality proves duplication.
        for index, statement in enumerate(body):
            if not isinstance(statement, ast.If) or not statement.orelse:
                continue
            count = len(statement.orelse)
            if index + 1 + count <= len(body) and all(
                    node_key(left) == node_key(right)
                    for left, right in zip(
                        statement.orelse, body[index + 1:index + 1 + count])):
                statement.orelse = []

        changed = True
        while changed:
            changed = False
            for index, statement in enumerate(body):
                if not (isinstance(statement, ast.Assign) and
                        len(statement.targets) == 1 and
                        isinstance(statement.targets[0], ast.Name)):
                    continue
                name = statement.targets[0].id
                if not temp_rx.fullmatch(name):
                    continue
                uses = [(later, load_count(candidate, name))
                        for later, candidate in enumerate(body[index + 1:],
                                                          index + 1)]
                uses = [(later, count) for later, count in uses if count]
                total = sum(count for _later, count in uses)
                if total == 0 and pure(statement.value):
                    del body[index]
                    changed = True
                    break
                if total == 0 and isinstance(statement.value, ast.Call):
                    # The result register is dead, but the Python call itself
                    # is observable (e.g. ``items.append(value)``).  Retain
                    # the side effect while dropping only the synthetic SSA
                    # destination introduced by the native lifter.
                    body[index] = ast.copy_location(
                        ast.Expr(value=statement.value), statement)
                    changed = True
                    break
                if total != 1:
                    continue
                use_index = uses[0][0]
                intervening = body[index + 1:use_index]
                safe_gap = all(
                    isinstance(item, ast.Assign) and
                    len(item.targets) == 1 and
                    isinstance(item.targets[0], ast.Name) and
                    temp_rx.fullmatch(item.targets[0].id) and pure(item.value)
                    for item in intervening)
                if not (use_index == index + 1 or
                        (pure(statement.value) and safe_gap)):
                    continue
                consumer = body[use_index]
                if not pure(statement.value):
                    # Moving an effectful value inside another expression
                    # changes ordering, short-circuiting or loop frequency.
                    value = getattr(consumer, 'value', None)
                    if not isinstance(consumer, (ast.Return, ast.Assign, ast.Expr)) or \
                            not isinstance(value, ast.Name) or value.id != name:
                        continue
                if expression_depth(statement.value) + expression_depth(consumer) > 48:
                    # Keep a named intermediate instead of constructing a
                    # deeply nested expression that Python cannot compile.
                    continue
                replacer = ReplaceLoad(name, statement.value)
                body[use_index] = replacer.visit(body[use_index])
                ast.fix_missing_locations(body[use_index])
                del body[index]
                changed = True
                break
        # Temporary inlining can make later SET_SUBSCRIPT operations adjacent
        # to a partially rebuilt dict display; fold that newly exposed tail.
        index = 0
        while index < len(body):
            statement = body[index]
            if not (isinstance(statement, ast.Assign) and
                    len(statement.targets) == 1 and
                    isinstance(statement.targets[0], ast.Name) and
                    isinstance(statement.value, ast.Dict)):
                index += 1
                continue
            name = statement.targets[0].id
            cursor = index + 1
            while cursor < len(body):
                candidate = body[cursor]
                if not (isinstance(candidate, ast.Assign) and
                        len(candidate.targets) == 1 and
                        isinstance(candidate.targets[0], ast.Subscript) and
                        isinstance(candidate.targets[0].value, ast.Name) and
                        candidate.targets[0].value.id == name):
                    break
                statement.value.keys.append(candidate.targets[0].slice)
                statement.value.values.append(candidate.value)
                del body[cursor]
            index += 1
        for index in range(len(body) - 1):
            statement = body[index]
            following = body[index + 1]
            if isinstance(statement, ast.Assign) and \
                    len(statement.targets) == 1 and \
                    isinstance(statement.targets[0], ast.Name) and \
                    isinstance(following, ast.Return) and \
                    isinstance(following.value, ast.Name) and \
                    following.value.id == statement.targets[0].id:
                following.value = statement.value
                del body[index]
                break
        # The coroutine resumer receives the value produced by a suspension
        # in its synthetic ``_sent`` ABI operand.  When that exact value is
        # immediately stored as m_returned, the source construct is
        # ``return await expr``.  Fuse only this adjacent, provenance-bearing
        # pair; an awaited result assigned or otherwise consumed remains a
        # separate statement.
        for index in range(len(body) - 1):
            statement = body[index]
            following = body[index + 1]
            if isinstance(statement, ast.Expr) and \
                    isinstance(statement.value, ast.Await) and \
                    isinstance(following, ast.Return) and \
                    isinstance(following.value, ast.Name) and \
                    following.value.id == '_sent':
                following.value = statement.value
                del body[index]
                break
        # Nothing in the same Python suite can execute after an unconditional
        # control-transfer statement.  Nuitka's shared native cleanup graph
        # can nevertheless make exception/refcount continuations appear
        # linearly after a recovered return or raise.  Trim that unreachable
        # suffix at every recursively cleaned suite.
        for index, statement in enumerate(body):
            if isinstance(statement, (ast.Return, ast.Raise,
                                      ast.Break, ast.Continue)):
                body = body[:index + 1]
                break
        if require_nonempty and not body:
            return [ast.Pass()]
        return body

    def fuse_fstrings(body):
        """Fonde il lowering nativo delle f-string: la sequenza
        ``A = <costante>; B = format(X, spec); C = ''.join(A)`` prodotta
        da FORMAT_VALUE + PyUnicode_Join torna ``A = f"costante{X:spec}"``.
        Il nome utente originale è A (la parte costante): il join finisce
        in un temporaneo del lifter, non nella variabile del sorgente."""
        out = []
        i = 0
        n = len(body)

        def const_str(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                return node.value
            # wrapper nativi del valore costante (_PyObject_GC_Malloc('LIT'))
            if isinstance(node, ast.Call) and len(node.args) == 1 and \
                    not node.keywords and \
                    isinstance(node.args[0], ast.Constant) and \
                    isinstance(node.args[0].value, str):
                return node.args[0].value
            return None

        def is_empty_join_on(node, name):
            return (isinstance(node, ast.Call) and
                    isinstance(node.func, ast.Attribute) and
                    node.func.attr == 'join' and
                    isinstance(node.func.value, ast.Constant) and
                    node.func.value.value == '' and
                    len(node.args) == 1 and
                    isinstance(node.args[0], ast.Name) and
                    node.args[0].id == name)

        while i < n:
            st = body[i]
            fused = False
            if isinstance(st, ast.Assign) and len(st.targets) == 1 and \
                    isinstance(st.targets[0], ast.Name):
                # Variante A: A = <const>; B = format(X,spec); C = ''.join(A)
                if i + 2 < n:
                    lit = const_str(st.value)
                    if lit is not None:
                        b, c = body[i + 1], body[i + 2]
                        if (isinstance(b, ast.Assign) and len(b.targets) == 1 and
                                isinstance(b.value, ast.Call) and
                                isinstance(b.value.func, ast.Name) and
                                b.value.func.id == 'format' and
                                len(b.value.args) == 2 and
                                isinstance(b.value.args[1], ast.Constant) and
                                isinstance(b.value.args[1].value, str) and
                                isinstance(c, ast.Assign) and
                                len(c.targets) == 1 and
                                is_empty_join_on(c.value, st.targets[0].id)):
                            spec = b.value.args[1].value
                            fv = ast.FormattedValue(
                                value=b.value.args[0], conversion=-1,
                                format_spec=(ast.Constant(value=spec)
                                             if spec else None))
                            st.value = ast.JoinedStr(
                                values=[ast.Constant(value=lit), fv])
                            i += 3
                            fused = True
                # Variante B (inline del renderer): A = format(X,spec);
                # B = ''.join(<wrapper('LIT')>) — la costante è dentro il
                # join. Il nome utente originale è A (il format).
                if not fused and i + 1 < n:
                    b = body[i + 1]
                    if (isinstance(st.value, ast.Call) and
                            isinstance(st.value.func, ast.Name) and
                            st.value.func.id == 'format' and
                            len(st.value.args) == 2 and
                            isinstance(st.value.args[1], ast.Constant) and
                            isinstance(st.value.args[1].value, str) and
                            isinstance(b, ast.Assign) and
                            len(b.targets) == 1 and
                            isinstance(b.value, ast.Call) and
                            isinstance(b.value.func, ast.Attribute) and
                            b.value.func.attr == 'join' and
                            isinstance(b.value.func.value, ast.Constant) and
                            b.value.func.value.value == '' and
                            len(b.value.args) == 1):
                        lit = const_str(b.value.args[0])
                        if lit is not None:
                            spec = st.value.args[1].value
                            fv = ast.FormattedValue(
                                value=st.value.args[0], conversion=-1,
                                format_spec=(ast.Constant(value=spec)
                                             if spec else None))
                            st.value = ast.JoinedStr(
                                values=[ast.Constant(value=lit), fv])
                            i += 2
                            fused = True
            if fused:
                out.append(st)
                continue
            # ricorri nei corpi annidati
            for field in ('body', 'orelse', 'finalbody'):
                nested = getattr(st, field, None)
                if isinstance(nested, list) and nested and \
                        isinstance(nested[0], ast.stmt):
                    setattr(st, field, fuse_fstrings(nested))
            handlers = getattr(st, 'handlers', None)
            if handlers:
                for handler in handlers:
                    handler.body = fuse_fstrings(handler.body)
            out.append(st)
            i += 1
        return out

    function.body = fuse_fstrings(function.body)
    import os as _osf
    if _osf.environ.get('NDL_DBG_FSTR'):
        print('POST-FUSE:', ast.unparse(function))
    function.body = cleanup_list(function.body, True)
    if function_name == '__init__' and function.body:
        trailing = function.body[-1]
        if isinstance(trailing, ast.Return):
            value = trailing.value
            # The C implementation returns a success pointer even when the
            # Python constructor falls through.  An unresolved synthetic SSA
            # register is therefore not a user return value.  Likewise a
            # proven super().__init__ result represents the source expression
            # call followed by implicit None.
            if isinstance(value, ast.Name) and temp_rx.fullmatch(value.id):
                function.body.pop()
            elif isinstance(value, ast.Call) and \
                    isinstance(value.func, ast.Attribute) and \
                    value.func.attr == '__init__' and \
                    isinstance(value.func.value, ast.Call) and \
                    isinstance(value.func.value.func, ast.Name) and \
                    value.func.value.func.id == 'super' and \
                    not value.func.value.args and \
                    not value.func.value.keywords:
                function.body[-1] = ast.copy_location(
                    ast.Expr(value=value), trailing)
        if not function.body:
            function.body = [ast.Pass()]
    ast.fix_missing_locations(tree)
    try:
        rendered = ast.unparse(function).splitlines()[1:]
    except Exception:
        return lines
    return rendered or lines


# V100 NBC/3: registro delle tracce lifter per funzione (qualname → righe
# ops compatte).  Popolato da lift_body quando l'emissione NBC e' attiva;
# consumato da decompile_binary per scrivere i .nbc arricchiti.
_NBC_TRACES = {}
# Decoratori di funzioni annidati raccolti dal pattern di applicazione
# ``NAME = D(...)`` + ``APPLY = D(...)(func_new(Q))`` + ``return APPLY``
# (lo zucchero ``@D(...)`` del sorgente).  Chiave: qualname del nested def.
_NDX_NESTED_DECORATORS = {}
# Registry VA→nome sorgente delle funzioni Python del binario (impl dirette
# di Nuitka): una call intra-modulo a un altro pyfunc si risolve al NOME
# invece di degradare a sub_VA.  Popolato da ModuleEmitter._prepare.
_NDX_PYFUNC_BY_VA = {}
_NDX_NATIVE_EVIDENCE = {}


def _nbc_sv(sym, depth=0):
    """Dump compatto di un NdxSV per il trace NBC/3."""
    if not isinstance(sym, NdxSV):
        return repr(sym)[:40]
    if depth > 3:
        return '…'
    head = str(sym.a) if not isinstance(sym.a, NdxSV) else _nbc_sv(
        sym.a, depth + 1)
    head = head[:32]
    parts = []
    b = sym.b
    if isinstance(b, list):
        parts.append('[' + ','.join(
            (_nbc_sv(x, depth + 1) if isinstance(x, NdxSV)
             else repr(x)[:16]) for x in b[:6]) + ']')
    elif isinstance(b, NdxSV):
        parts.append(_nbc_sv(b, depth + 1))
    c = sym.c
    if isinstance(c, NdxSV):
        parts.append(_nbc_sv(c, depth + 1))
    return sym.op + '(' + head + ('; ' + ' '.join(parts) if parts else '') \
        + ')'


_NDX_EFFECT_OPS = frozenset((
    # valori la cui valutazione esegue codice sorgente: chiamate, appended /
    # aggiunti a collezioni, sospensioni, raise.  'next' e' volutamente
    # escluso: l'avanzamento iternext ha le sue regole di scarto dedicate.
    'call', 'mcall', 'kwcall', 'nativecall', 'apicall', 'append', 'setadd',
    'store_sub', 'store_attr', 'del_sub', 'del_attr', 'raise', 'yield',
    'await', 'print', 'import',
))


def _ndx_sv_has_effect(sym, depth=0):
    """True se la valutazione del simbolo esegue codice sorgente.

    Un ``assign _vN = <expr>`` con temp mai letto non e' eliminabile quando
    <expr> contiene una chiamata (o append/await/...): il risultato e'
    scartato ma l'EFFETTO e' sorgente Python reale (``TOTAL.append(x)``,
    ``print(x)``, ...).  Ricorre negli argomenti e nei costrutti
    contenitori: una tuple/costrutto che contiene una chiamata ha essa
    stessa un effetto.
    """
    if depth > 12 or not isinstance(sym, NdxSV):
        return False
    if sym.op in _NDX_EFFECT_OPS:
        return True
    if isinstance(sym.a, NdxSV) and _ndx_sv_has_effect(sym.a, depth + 1):
        return True
    if isinstance(sym.b, NdxSV) and _ndx_sv_has_effect(sym.b, depth + 1):
        return True
    if isinstance(sym.b, list):
        for item in sym.b:
            if isinstance(item, NdxSV) and \
                    _ndx_sv_has_effect(item, depth + 1):
                return True
    if isinstance(sym.c, NdxSV) and _ndx_sv_has_effect(sym.c, depth + 1):
        return True
    return False


def _nbc_capture(modname, qualname, bl):
    """Cattura le ops del lifter in forma NBC/3 (una riga per op)."""
    try:
        rows = []
        ops = []
        for block in bl.blocks.values():
            for op in block.ops:
                ops.append(op)
        ops.sort(key=lambda o: o.va)
        for op in ops[:600]:
            a = op.a
            desc = _nbc_sv(a) if isinstance(a, NdxSV) else repr(a)[:48]
            rows.append(f"  {op.va:x} {op.kind:<9} {desc[:150]}")
        _NBC_TRACES.setdefault(modname, {})[qualname or '<anon>'] = rows
    except Exception:
        pass


def lift_body(mod, mca, co, impl_va, img, res, verbose=False,
              py_version=(3, 12)):
    """Corpo di una funzione → righe Python indentate (motore v2)."""
    try:
        bl = BodyLifter2(img, res, mca, co, impl_va,
                         py_version=py_version, verbose=verbose).lift()
        if os.environ.get('NDX_EMIT_NBC', '1').strip().lower() not in (
                '0', 'false', 'no', 'off'):
            _nbc_capture(getattr(mod, 'name', '?'),
                         getattr(co, 'qualname', None) or
                         getattr(co, 'name', None), bl)
        qualname = getattr(co, 'qualname', None) or getattr(co, 'name', None)
        _NDX_NATIVE_EVIDENCE.setdefault(getattr(mod, 'name', '?'), {})[qualname or '<anon>'] = {
            'exception_matchers': len({op.va for block in bl.blocks.values()
                                      for op in block.ops if op.kind == 'calc'
                                      and isinstance(op.a, NdxSV) and op.a.op == 'exc_match'})}
        nested_metadata = getattr(mca, '_nested_function_metadata', None)
        if nested_metadata is None:
            nested_metadata = mca._nested_function_metadata = {}
        metadata_values = set()
        for block in bl.blocks.values():
            for operation in block.ops:
                node = operation.a
                if operation.kind != 'calc' or not isinstance(node, NdxSV) or node.op != 'func_new':
                    continue
                values = node.b or []
                if len(values) > 2 and isinstance(values[2], NdxSV) and values[2].op == 'const':
                    nested_metadata[values[2].a] = ModuleEmitter._function_abi_metadata(ModuleEmitter.__new__(ModuleEmitter), node)
                metadata_values.update(id(value) for value in values[4:7] if isinstance(value, NdxSV) and value.op == 'const' and isinstance(value.a, (tuple, dict)))
        for block in bl.blocks.values():
            block.ops = [operation for operation in block.ops if not (operation.kind == 'store' and id(operation.b) in metadata_values)]
        S = Structurer(bl)
        stmts = S.structure()
        if not stmts:
            # rete di sicurezza: la strutturazione non ha prodotto nulla
            # (es. corpo interamente comprehension) → emissione lineare
            # delle op Python in ordine di blocco (MAI corpo vuoto)
            stmts = S._fallback_linear_stmts()
        r = NdxRenderer(S, bl.varnames, bl.argcount)
        # Pool dei code object comprehension del modulo: i nomi delle
        # variabili di loop delle comprehension desugurate vivono SOLO
        # qui (co_varnames ['.0', name]) — il parent non li ha.
        try:
            _cline = getattr(co, 'firstlineno', None) or 0
            _end = [getattr(c, 'firstlineno')
                    for c in getattr(mca, 'code_objects', {}).values()
                    if isinstance(c, CodeObjectInfo) and
                    not str(getattr(c, 'qualname', None) or
                            getattr(c, 'name', '')).startswith('<') and
                    getattr(c, 'firstlineno', None) and
                    c.firstlineno > _cline]
            r._comp_line_hi = min(_end) if _end else None
            r._comp_cos = [
                c for c in getattr(mca, 'code_objects', {}).values()
                if isinstance(c, CodeObjectInfo) and
                str(getattr(c, 'qualname', None) or
                    getattr(c, 'name', '')).rsplit('.', 1)[-1] in
                ('<listcomp>', '<dictcomp>', '<setcomp>', '<genexpr>') and
                getattr(c, 'firstlineno', None) and
                c.firstlineno >= _cline and
                (r._comp_line_hi is None or c.firstlineno < r._comp_line_hi)]
            r._comp_cos.sort(key=lambda c: c.firstlineno)
            r._comp_cos_used = set()
        except Exception:
            r._comp_cos = []
        lines = r.render(stmts)
    except Exception as e:
        if verbose:
            import traceback
            traceback.print_exc()
        return ['    pass']
    out = ['    ' + l if l.strip() else '' for l in lines]
    out = _ndx_cleanup_body_lines(
        out, getattr(co, 'name', None) if co is not None else None)
    # Ricomponi i blocchi ``with``: il lowering nativo espone __enter__/
    # __exit__ come chiamate separate sullo stesso context manager.  La
    # regola è strutturale (bracketing enter/exit dello stesso oggetto),
    # non un healer euristico: usa la funzione non decorata, che il gate
    # ``--aggressive-heuristics`` riserva invece ai healer del motore
    # legacy.
    try:
        fold_with = getattr(_ndl_fold_with_statements, '__wrapped__',
                            _ndl_fold_with_statements)
        out = fold_with(out)
    except Exception:
        pass
    try:
        out = _ndx_drop_trailing_continues(out)
    except Exception:
        pass
    try:
        out = _ndx_inline_fstring_temps(out)
    except Exception:
        pass
    out = _ndx_guard_block_indentation(out)
    # Branch phi values are materialized in the IR from their incoming
    # edges.  Textual address-order substitution cannot preserve that proof,
    # and unrelated synthetic temporaries must keep distinct identities.
    # Every compiled void function ends with an implicit ``return NULL``
    # lowering; a trailing ``return None`` with no other return statement in
    # the body is that artifact, not source (a genuine ``return None`` body
    # keeps its statement because it is the only return and would be the
    # body's content).
    live = [i for i, l in enumerate(out) if l.strip()]
    if live and out[live[-1]].strip() == 'return None':
        if not any(re.match(r'\s*return\b', out[i]) for i in live[:-1]) and \
                len(live) > 1:
            out = out[:live[-1]] + out[live[-1] + 1:]
            while out and not out[-1].strip():
                out.pop()
    return out


def _ndx_materialize_const_phi_arms(lines, bl):
    """Catene if/elif con corbi pass + phi merge a costanti: materializza
    NAME = costante in ogni ramo (ordine predecessori = ordine rami) e
    rinomina il temporaneo del phi nella lettura post-dispatch."""
    import re as _re
    prov = getattr(bl, '_phi_inputs', None)
    if not prov:
        return lines
    # nome della variabile: primo co_varname non-argomento (lo slot del
    # match dispatch corrisponde alla variabile locale assegnata nei rami)
    name = None
    argcount = getattr(bl, 'argcount', 0) or 0
    for cand in (getattr(bl, 'varnames', ()) or ())[argcount:]:
        if isinstance(cand, str):
            name = cand
            break
    if name is None:
        return lines
    merged = {}
    for pairs in prov.values():
        for p, v in pairs:
            if p is None:
                continue
            if not (isinstance(v, NdxSV) and v.op == 'const' and
                    isinstance(v.a, (int, float)) and not isinstance(v.a, bool)):
                continue
            merged.setdefault(p, v.a)
    if len(merged) < 2:
        return lines
    vals = [merged[k] for k in sorted(merged)]
    IND = '    '
    # forma annidata
    for i, ln in enumerate(lines):
        m1 = _re.match(r'^(\s*)if\s+.+:\s*$', ln)
        if not m1 or i + 4 >= len(lines):
            continue
        ind = m1.group(1)
        bind = ind + IND
        if lines[i + 1].strip() != 'pass' or lines[i + 2].strip() != 'else:':
            continue
        m3 = _re.match(r'^' + _re.escape(bind) + r'if\s+(.+):\s*$', lines[i + 3])
        if not m3 or i + 4 >= len(lines) or lines[i + 4].strip() != 'pass':
            continue
        cond2 = lines[i + 3].strip()[3:].rstrip(':').strip()
        out = list(lines)
        out[i + 1] = bind + name + ' = ' + repr(vals[0])
        out[i + 2] = ind + 'elif ' + cond2 + ':'
        out[i + 3] = bind + name + ' = ' + repr(vals[1])
        if len(vals) > 2:
            out[i + 4] = ind + 'else:'
            out.insert(i + 5, bind + name + ' = ' + repr(vals[2]))
        return [l for l in out if l.strip() != 'pass']
    # forma piatta
    for i, ln in enumerate(lines):
        m = _re.match(r'^(\s*)if\s+.+:\s*$', ln)
        if not m:
            continue
        ind = m.group(1)
        bind = ind + IND
        j = i + 1
        arms = []
        while j < len(lines):
            if lines[j] == bind + 'pass':
                arms.append(j)
                j += 1
                continue
            m2 = _re.match(r'^' + _re.escape(ind) + r'elif\s+(.+):\s*$', lines[j])
            if m2 and j + 1 < len(lines) and lines[j + 1] == bind + 'pass':
                arms.append(j + 1)
                j += 2
                continue
            break
        if len(arms) < 1:
            continue
        if len(vals) not in (len(arms), len(arms) + 1):
            continue
        out = list(lines)
        for k, al in enumerate(arms):
            out[al] = bind + name + ' = ' + repr(vals[k])
        if len(vals) == len(arms) + 1:
            out.insert(arms[-1] + 1, ind + 'else:')
            out.insert(arms[-1] + 2, bind + name + ' = ' + repr(vals[-1]))
        return out
    return lines


def main():
    ap = argparse.ArgumentParser(
        prog='hexpyrion',
        description='HEXPYRION by dimareverse — static Nuitka recovery (PE/ELF)')
    ap.add_argument('target', help='binary Nuitka (.exe/.dll/.bin/.so)')
    ap.add_argument('--output-dir', '-o', default='hexpyrion_out',
                    help='output directory')
    ap.add_argument('--dev-only', action='store_true',
                    help='process first-party modules only (dev), '
                         'skipping libraries: useful for binaries with '
                         'hundreds of compiled modules')
    ap.add_argument('--sigs', default=None,
                    help='path al database firme helper (helper_sigs.json)')
    ap.add_argument('--reference-image', default=None,
                    help='DLL/EXE Nuitka di riferimento per calibrazione MSVC')
    ap.add_argument('--reference-map', default=None,
                    help='file .map MSVC corrispondente alla reference image')
    ap.add_argument('--verbose', '-v', action='store_true')
    args = ap.parse_args()

    result = decompile_binary(args.target, args.output_dir,
                              verbose=args.verbose, sig_db_path=args.sigs,
                         dev_only=getattr(args, 'dev_only', False),
                              reference_image_path=args.reference_image,
                              reference_map_path=args.reference_map)
    if result is None:
        sys.exit(1)





def _ndx_load_sig_db():
    """Database firme helper Nuitka incorporato (zlib+base64)."""
    import base64 as _b64
    import zlib as _zlib
    try:
        raw = _zlib.decompress(_b64.b64decode(_NDX_SIG_B64))
        return json.loads(raw)
    except Exception:
        return None


