def _ndx_load_msvc_sig_db():
    """Generic Nuitka/CPython MSVC runtime signatures (no application data)."""
    import base64 as _b64
    import zlib as _zlib
    try:
        raw = _zlib.decompress(_b64.b64decode(_NDX_MSVC_SIG_B64))
        return json.loads(raw)
    except Exception:
        return None


_NDX_SIG_DB = _ndx_merge_sig_dbs(
    _ndx_load_sig_db(), _ndx_load_msvc_sig_db())




# =============================================================================
# === NDX UNIVERSAL STATIC ENGINE v2 — integrated into the user decompiler ===
# Static source recovery: ELF/PE x86-64, GCC/MSVC/MinGW codegen, GCC IPA-SRA
# (.isra.N), cold-path outlining, rotated loops, inlined tp_* dispatch.
# Deterministic machine-code analysis only: no content heuristics.
# =============================================================================

def ndx_bridge_decompile(target, out_dir, verbose=False, sig_db_path=None,
                         reference_image_path=None, reference_map_path=None,
                         dev_only=False, target_python=None, only=None):
    """Source recovery universale via motore NDX v2 (statico)."""
    try:
        return decompile_binary(
            target, out_dir, verbose=verbose, sig_db_path=sig_db_path,
            reference_image_path=reference_image_path,
            reference_map_path=reference_map_path,
            dev_only=dev_only, target_python=target_python, only=only)
    except Exception as e:
        if verbose:
            import traceback
            traceback.print_exc()
        ndx_log_warn(f"NDX decompilation failed: {e}")
        return None


def _ndx_run_cli():
    """NDX command line with explicit argument and recovery validation."""
    parser = argparse.ArgumentParser(description='Static Nuitka source recovery')
    parser.add_argument('target', nargs='?', help='Nuitka binary')
    parser.add_argument('-s', '--source', dest='source_target')
    parser.add_argument('-o', '--output', '--output-dir', default='HEXPYRION_OUT')
    parser.add_argument('--dev-only', action='store_true')
    parser.add_argument('--sigs')
    parser.add_argument('--abi-only', action='store_true',
                        help='write static ABI discovery without source recovery')
    parser.add_argument('--target-python', metavar='X.Y',
                        help='explicit runtime version when imported metadata is unavailable')
    parser.add_argument('--reference-image')
    parser.add_argument('--reference-map')
    parser.add_argument('-v', '--verbose', action='store_true')
    parser.add_argument('--main-guard', choices=('auto', 'never'), default='auto',
                        help='auto: infer a conventional entry guard if optimized away; never: preserve flat execution when no native guard survives')
    parser.add_argument('--strict', action='store_true',
                        help='exit 2 on detectable recovery gaps; this does not prove equivalence')
    parser.add_argument('--only', default=None, metavar='MODS',
                        help='comma-separated glob patterns to filter modules (e.g. "twokmate.*,__main__")')
    args = parser.parse_args()
    global _NDX_MAIN_GUARD_MODE
    _NDX_MAIN_GUARD_MODE = args.main_guard
    target = args.source_target or args.target
    if not target:
        parser.error('a target binary is required')
    if args.source_target and args.target and args.source_target != args.target:
        parser.error('specify the target once, either positional or with --source')
    if bool(args.reference_image) != bool(args.reference_map):
        parser.error('--reference-image and --reference-map must be provided together')
    if args.target_python:
        try:
            _ndl_parse_target_python_version(args.target_python)
        except ValueError as error:
            parser.error(str(error))
    if args.abi_only:
        try:
            profile = ndx_abi_extract(target, args.output, args.target_python)
            ndx_log_ok('ABI report: '+os.path.join(args.output, 'ABI_REPORT.json'))
            profile.require_native()
        except NdxABIError as error:
            ndx_log_warn(str(error))
            sys.exit(2)
        except (OSError, ValueError) as error:
            ndx_log_warn(str(error))
            sys.exit(1)
        sys.exit(0)
    if BANNER:
        print(BANNER, flush=True)
    if args.dev_only:
        ndx_log_ok('--dev-only: first-party modules only (libraries skipped)')
    try:
        result = ndx_bridge_decompile(
            target, args.output, verbose=args.verbose, sig_db_path=args.sigs,
            reference_image_path=args.reference_image,
            reference_map_path=args.reference_map, dev_only=args.dev_only,
            target_python=args.target_python, only=args.only)
    except KeyboardInterrupt:
        sys.exit(130)
    if result is None:
        sys.exit(1)
    sources, report = result
    gaps = report.get('source_recovery', {}).get('partial_modules', 0)
    sys.exit(2 if args.strict and (not sources or gaps or report.get('failed_modules')) else 0)


if __name__ == "__main__" and globals().get('_NDX_RUN_'):
    _ndx_run_cli()
